-- Daily push notifications (pregnancy_day_notifications, mommy_day_notifications) translated into
-- es, fr, hi, id, ja, ko, nl, pl, pt, sv, vi, zh (owner request 2026-11-12; human-quality translation, not machine/Gemini). Batch 20261112270000_push_notifications_i18n_wave5.
-- Only empty cells are filled; existing text is never overwritten. Tables already CDC enrolled and writer guarded.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '300s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public'
      AND table_name IN ('pregnancy_day_notifications', 'mommy_day_notifications')) <> 2 THEN
    RAISE EXCEPTION 'PUSH_I18N_GUARD_MISSING'; END IF;
END $$;
UPDATE public.mommy_day_notifications SET title_es = 'Café helado ☕', body_es = 'Servirse un café y bebérselo 3 horas después es la ley no escrita de la maternidad. Hoy haz algo diferente: déjale solo con sus juguetes ¡y tómate ese café caliente en 10 minutos!', title_fr = 'Un café glacé ☕', body_fr = 'Se servir un café et le boire 3 heures plus tard, c''est la loi non écrite de la maternité. Aujourd''hui, changez la règle. Laissez-le seul avec ses jouets et buvez ce café encore chaud en 10 minutes !', title_hi = 'बर्फ़ जैसी ठंडी कॉफ़ी ☕', body_hi = 'कॉफ़ी बनाकर 3 घंटे बाद पीना माँ होने का अनलिखा नियम है। आज कुछ अलग कीजिए। उसे खिलौनों के साथ अकेला छोड़िए और वह कॉफ़ी 10 मिनट के अंदर गर्म-गर्म पीजिए!', title_id = 'Kopi sedingin es ☕', body_id = 'Menuang kopi lalu baru meminumnya 3 jam kemudian adalah hukum tak tertulis menjadi ibu. Hari ini coba berbeda. Biarkan ia bermain sendiri dengan mainannya dan minum kopi itu selagi hangat dalam 10 menit!', title_ja = '氷のように冷めたコーヒー ☕', body_ja = 'コーヒーをいれて3時間後に飲むのは、子育ての暗黙のルール。今日はひと工夫を。お子さんをおもちゃとひとりで遊ばせて、そのコーヒーを10分以内に温かいうちに飲みましょう！', title_ko = '얼음처럼 식은 커피 ☕', body_ko = '커피를 따르고 3시간 뒤에 마시는 건 엄마들의 공식 불문율이죠. 오늘은 달라져 보세요. 아이가 장난감과 노는 동안 그 커피를 10분 안에 따뜻할 때 드세요!', title_nl = 'IJskoude koffie ☕', body_nl = 'Koffie inschenken en die 3 uur later drinken is de ongeschreven wet van het moederschap. Doe vandaag eens anders. Laat hem even alleen met zijn speelgoed en drink die koffie binnen 10 minuten, nog warm!', title_pl = 'Kawa zimna jak lód ☕', body_pl = 'Nalać kawę i wypić ją 3 godziny później to nieoficjalne prawo macierzyństwa. Dziś zrób inaczej. Zostaw go z zabawkami i wypij tę kawę w 10 minut, póki jest gorąca!', title_pt = 'Café gelado ☕', body_pt = 'Servir o café e bebê-lo 3 horas depois é a lei não escrita da maternidade. Hoje faça diferente. Deixe-o com os brinquedos e beba esse café quente, em 10 minutos!', title_sv = 'Iskallt kaffe ☕', body_sv = 'Att hälla upp kaffet och dricka det 3 timmar senare är moderskapets officiella oskrivna lag. Gör något annorlunda i dag. Lämna barnet ensamt med leksakerna och drick kaffet medan det är varmt, inom 10 minuter!', title_vi = 'Ly cà phê nguội lạnh ☕', body_vi = 'Rót cà phê rồi 3 tiếng sau mới uống là luật bất thành văn của các mẹ. Hôm nay hãy khác đi. Để bé chơi một mình với đồ chơi và uống ly cà phê khi còn nóng trong vòng 10 phút!', title_zh = '冰凉的咖啡 ☕', body_zh = '倒好咖啡，3小时后才喝上，是当妈妈不成文的规定。今天来点不一样的吧。让宝宝和玩具自己玩，你在10分钟内趁热把那杯咖啡喝掉！' WHERE id = '7a36ad44-2dba-4854-82a6-8b3c27a56c6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las frases se alargan 🗣️', body_es = 'Ya junta palabras y construye frases curiosas con su propia lógica. No te pierdas estos momentos: graba en vídeo sus dulces diálogos con la Sesión de fotos del bebé.', title_fr = 'Les phrases s''allongent 🗣️', body_fr = 'Il relie déjà les mots entre eux pour former des phrases intéressantes, avec sa propre logique. Ne manquez pas ces moments : filmez ses adorables dialogues avec la Séance photo bébé.', title_hi = 'वाक्य लंबे हो रहे हैं 🗣️', body_hi = 'अब शब्दों को जोड़कर दिलचस्प, पूरी तरह अपने तर्क वाले वाक्य बनाता है। ये पल मत चूकिए, बेबी फ़ोटोशूट से उसकी इन प्यारी बातों का वीडियो बनाइए।', title_id = 'Kalimatnya makin panjang 🗣️', body_id = 'Ia kini merangkai kata menjadi kalimat menarik dengan logikanya sendiri. Jangan lewatkan momen ini, rekam percakapan manisnya dalam video lewat Pemotretan Bayi.', title_ja = '文が長くなってきた 🗣️', body_ja = '言葉をつなげて、おもしろくて、まったく自分なりの理屈で文を作るようになりました。この瞬間を見逃さず、「ベビーフォトセッション」でかわいいおしゃべりを動画に残しましょう。', title_ko = '문장이 길어져요 🗣️', body_ko = '이제 단어를 이어 자기만의 논리로 재미있는 문장을 만들어요. 이 순간을 놓치지 말고 아기 사진 촬영으로 사랑스러운 대화를 영상에 담아 두세요.', title_nl = 'Zinnen worden langer 🗣️', body_nl = 'Hij rijgt woorden aan elkaar en maakt interessante zinnen, helemaal volgens zijn eigen logica. Mis deze momenten niet en film zijn schattige gesprekjes met Babyfotoshoot.', title_pl = 'Zdania się wydłużają 🗣️', body_pl = 'Łączy już słowa i buduje ciekawe zdania, całkowicie według własnej logiki. Nie przegap tych chwil, nagraj te słodkie dialogi w Sesji zdjęciowej dziecka.', title_pt = 'As frases crescem 🗣️', body_pt = 'Já junta palavras e constrói frases curiosas, com uma lógica só dele. Não perca estes momentos: filme estes diálogos ternurentos com a Sessão Fotográfica.', title_sv = 'Meningarna blir längre 🗣️', body_sv = 'Barnet sätter redan ihop ord till intressanta meningar som följer hens helt egen logik. Missa inte de här stunderna, filma de söta dialogerna med Babyfotografering.', title_vi = 'Câu nói dài ra 🗣️', body_vi = 'Bé đã biết nối các từ lại, tạo nên những câu thú vị theo logic của riêng mình. Đừng bỏ lỡ những khoảnh khắc này, hãy quay video những cuộc đối thoại đáng yêu của bé bằng Chụp ảnh cho bé.', title_zh = '句子越来越长 🗣️', body_zh = '已经能把词连起来，说出有趣又完全符合自己逻辑的句子了。别错过这些时刻，用宝宝写真把这些可爱的对话录下来吧。' WHERE id = 'e2414d34-11c4-4990-9c63-38d30534a147' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Le da miedo cuando se apagan las luces? Oscurece del todo la habitación y haced juegos de sombras en la pared con una linterna. Convierte el miedo en diversión y ayúdale a hacer las paces con la oscuridad.', body_fr = 'Il a peur quand la lumière s''éteint ? Faites le noir complet dans la chambre et créez des ombres chinoises au mur avec une lampe torche. En transformant la peur en jeu, aidez-le à faire la paix avec le noir.', body_hi = 'लाइट बंद होने पर डरता है? कमरे में पूरा अंधेरा कीजिए और टॉर्च से दीवार पर परछाइयों का खेल बनाइए। डर को मज़े में बदलकर अंधेरे से उसकी दोस्ती कराइए।', body_id = 'Takut saat lampu padam? Gelapkan kamar sepenuhnya dan buat permainan bayangan di dinding dengan senter. Bantu ia berdamai dengan gelap dengan mengubah rasa takut menjadi keseruan.', body_ja = '明かりが消えるとこわがりますか？部屋を真っ暗にして、懐中電灯で壁に影絵を映して遊びましょう。こわさを楽しさに変えて、暗やみと仲よくなる手助けをしてあげて。', body_ko = '불을 끄면 무서워하나요? 방을 완전히 어둡게 하고 손전등으로 벽에 그림자 놀이를 해 보세요. 두려움을 놀이로 바꿔 어둠과 친해지도록 도와주세요.', body_nl = 'Is hij bang als de lichten uitgaan? Maak de kamer helemaal donker en maak met een zaklamp schaduwfiguren op de muur. Maak van angst een spel en help hem zo vrede te sluiten met het donker.', body_pl = 'Boi się, gdy gaśnie światło? Zaciemnij całkowicie pokój i twórz latarką teatr cieni na ścianie. Zamieniając strach w zabawę, pomożesz mu oswoić ciemność.', body_pt = 'Tem medo quando as luzes se apagam? Escureça o quarto por completo e faça sombras chinesas na parede com uma lanterna. Transforme o medo em diversão e ajude-o a fazer as pazes com o escuro.', body_sv = 'Blir barnet rädd när lamporna släcks? Gör rummet helt mörkt och skapa skuggfigurer på väggen med en ficklampa. Gör rädslan till lek och hjälp barnet att försonas med mörkret.', body_vi = 'Bé sợ khi tắt đèn? Hãy làm tối phòng hoàn toàn và dùng đèn pin tạo trò chơi bóng hình trên tường. Biến nỗi sợ thành niềm vui để giúp bé làm quen với bóng tối.', body_zh = '一关灯就害怕？把房间完全调暗，用手电筒在墙上玩影子游戏。把害怕变成乐趣，帮宝宝和黑暗和解。' WHERE id = 'ef8a1fe8-6bb2-49b8-bcbe-cb005f42d12f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Estirón de talla y peso 📏', body_es = '¿Los pantalones vuelven a quedarle cortos? ¡Está creciendo a toda velocidad! Introduce sus medidas actuales en el Seguimiento del desarrollo y mira con orgullo esa curva que sube, fruto de tus noches sin dormir.', title_fr = 'Poussée de taille et de poids 📏', body_fr = 'Les pantalons sont encore trop courts ? Il grandit vite ! Entrez ses mesures actuelles dans le Suivi de développement et regardez fièrement cette courbe qui monte, fruit de vos nuits blanches.', title_hi = 'लंबाई और वज़न में उछाल 📏', body_hi = 'पैंट फिर छोटी हो गई? वह तेज़ी से बड़ा हो रहा है! ग्रोथ ट्रैकर में मौजूदा माप दर्ज कीजिए और आपकी जागी हुई रातों का फल, ऊपर जाता विकास का ग्राफ़ गर्व से देखिए।', title_id = 'Lonjakan tinggi dan berat badan 📏', body_id = 'Celananya kependekan lagi? Ia tumbuh dengan cepat! Masukkan ukuran terbarunya ke Pelacak Perkembangan dan lihat dengan bangga kurva pertumbuhan yang naik, buah dari malam-malam tanpa tidur Anda.', title_ja = '身長と体重の伸び 📏', body_ja = 'ズボンの丈がまた短くなった？ぐんぐん成長しています！「発達トラッカー」に今のサイズを入力して、眠れない夜の成果である右肩上がりの成長曲線を誇らしく見てみましょう。', title_ko = '키와 몸무게가 쑥 📏', body_ko = '바지가 또 짧아졌나요? 쑥쑥 크고 있어요! 성장 기록에 현재 수치를 입력하고, 잠 못 든 밤들의 결실인 올라가는 성장 곡선을 뿌듯하게 바라보세요.', title_nl = 'Sprong in lengte en gewicht 📏', body_nl = 'Is zijn broek weer te kort? Hij groeit snel! Vul de huidige maten in de Groeitracker in en kijk trots naar die stijgende groeicurve, de vrucht van al je slapeloze nachten.', title_pl = 'Skok wzrostu i wagi 📏', body_pl = 'Spodnie znów za krótkie? Szybko rośnie! Wpisz aktualne wymiary do Śledzenia rozwoju i z dumą spójrz na rosnącą krzywą rozwoju, owoc twoich nieprzespanych nocy.', title_pt = 'Salto na altura e no peso 📏', body_pt = 'As calças voltaram a ficar curtas? Está a crescer depressa! Introduza as medidas atuais no Registo de Desenvolvimento e veja com orgulho a curva a subir, fruto das suas noites sem dormir.', title_sv = 'Spurt i längd och vikt 📏', body_sv = 'Har byxorna blivit korta igen? Barnet växer snabbt! För in de aktuella måtten i Tillväxtspåraren och se stolt på den stigande tillväxtkurvan, frukten av dina sömnlösa nätter.', title_vi = 'Tăng vọt chiều cao và cân nặng 📏', body_vi = 'Ống quần lại ngắn nữa rồi? Bé đang lớn rất nhanh! Hãy nhập số đo hiện tại vào Theo dõi phát triển và tự hào ngắm đường cong phát triển đi lên, thành quả của những đêm mất ngủ.', title_zh = '身高体重突增 📏', body_zh = '裤子又短了？长得真快！在发育追踪里输入当前尺寸，骄傲地看看那条往上走的成长曲线，那是你无数个不眠之夜的成果。' WHERE id = '005f91e2-a696-4de0-bf24-bb840b614746' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares sin motivo 😭', body_es = 'Se ha despertado gritando en mitad de la noche. No te alarmes. Comprueba con el Análisis del llanto si es dolor de crecimiento o un terror nocturno y abrázale con paciencia.', title_fr = 'Réveils sans raison 😭', body_fr = 'Il s''est réveillé en hurlant en pleine nuit. Pas de panique. Vérifiez avec l''Analyse des pleurs s''il s''agit de douleurs de croissance ou d''une terreur nocturne, et prenez-le patiemment dans vos bras.', title_hi = 'बिना वजह जागना 😭', body_hi = 'आधी रात को चीखते हुए जाग गया। घबराइए मत। क्राइंग एनालिसिस टूल से जाँचिए कि यह ग्रोथ पेन है या नाइट टेरर, और धैर्य से उसे गले लगाइए।', title_id = 'Terbangun tanpa sebab 😭', body_id = 'Ia terbangun tengah malam sambil berteriak. Jangan panik. Periksa dengan Analisis Tangisan apakah ini nyeri pertumbuhan atau teror malam, lalu peluk ia dengan sabar.', title_ja = '理由のわからない夜泣き 😭', body_ja = '夜中に叫んで目を覚ましましたか？あわてないで。「泣き声分析」で成長痛か夜驚症かを確かめて、やさしく抱きしめてあげましょう。', title_ko = '이유 없이 깨요 😭', body_ko = '한밤중에 비명을 지르며 깼나요? 당황하지 마세요. 울음 분석 도구로 성장통인지 야경증인지 확인하고 인내심 있게 안아 주세요.', title_nl = 'Zomaar wakker worden 😭', body_nl = 'Midden in de nacht schreeuwend wakker geworden? Raak niet in paniek. Check met Huilanalyse of het groeipijn of nachtangst is en knuffel hem geduldig.', title_pl = 'Pobudki bez powodu 😭', body_pl = 'Obudził się w nocy z krzykiem? Nie panikuj. Sprawdź w Analizie płaczu, czy to bóle wzrostowe, czy lęk nocny, i cierpliwie go przytul.', title_pt = 'Despertares sem razão 😭', body_pt = 'Acordou a meio da noite aos gritos. Não entre em pânico. Use a Análise do Choro para ver se é dor de crescimento ou terror noturno e abrace-o com paciência.', title_sv = 'Uppvaknanden utan orsak 😭', body_sv = 'Barnet vaknade skrikande mitt i natten. Få inte panik. Kolla med verktyget Gråtanalys om det är växtvärk eller nattskräck och krama barnet med tålamod.', title_vi = 'Thức giấc không rõ lý do 😭', body_vi = 'Bé hét lên thức giấc giữa đêm. Đừng hoảng. Hãy dùng công cụ Phân tích tiếng khóc để xem đó là đau do tăng trưởng hay hoảng sợ ban đêm, rồi kiên nhẫn ôm bé vào lòng.', title_zh = '无缘无故醒来 😭', body_zh = '半夜尖叫着醒来。别慌。用哭声分析工具看看是生长痛还是夜惊，再耐心地抱抱宝宝。' WHERE id = '4d0ac53a-0a7d-40d8-a958-4dd99382d977' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rebeldía con la siesta 🥱', body_es = '¿No quiere ir a la cama de ninguna manera? A los 2,5 años algunos niños empiezan a dejar la siesta. No le obligues a dormir: sustitúyela por 30 minutos de lectura tranquila.', title_fr = 'Les caprices de la sieste 🥱', body_fr = 'Il refuse catégoriquement d''aller au lit ? Vers 2,5 ans, certains enfants commencent à abandonner la sieste. Ne forcez pas le sommeil, remplacez-le par 30 minutes de « lecture calme ».', title_hi = 'दिन की नींद की ज़िद 🥱', body_hi = 'बिस्तर पर बिल्कुल नहीं जाना चाहता? 2.5 साल में कुछ बच्चे दिन की नींद छोड़ने लगते हैं। नींद ज़बरदस्ती मत कराइए, उसकी जगह 30 मिनट का ''शांत किताब समय'' रखिए।', title_id = 'Drama tidur siang 🥱', body_id = 'Sama sekali tidak mau tidur? Di usia 2,5 tahun sebagian anak mulai berhenti tidur siang. Jangan memaksanya tidur, ganti dengan 30 menit ''Waktu Membaca Tenang''.', title_ja = 'お昼寝のあまのじゃく 🥱', body_ja = 'どうしてもベッドに行きたがらない？2歳半になると、お昼寝をしなくなる子もいます。無理に寝かせず、30分の「静かな絵本の時間」に置きかえましょう。', title_ko = '낮잠 거부 🥱', body_ko = '절대 자러 가지 않으려 하나요? 두 돌 반 무렵 낮잠을 거부하기 시작하는 아이도 있어요. 억지로 재우지 말고 30분의 ''조용한 책 시간''으로 바꿔 보세요.', title_nl = 'Gedoe met het middagslaapje 🥱', body_nl = 'Wil hij absoluut niet naar bed? Rond 2,5 jaar stoppen sommige kinderen met hun middagslaapje. Dwing de slaap niet af, maar vervang hem door een stil leesuurtje van 30 minuten.', title_pl = 'Kłopoty z drzemką 🥱', body_pl = 'Za nic nie chce iść do łóżka? Około 2,5 roku niektóre dzieci zaczynają rezygnować z drzemki w dzień. Nie zmuszaj do snu, zastąp go 30-minutową cichą godziną z książką.', title_pt = 'Teimosias com a sesta 🥱', body_pt = 'Não quer de maneira nenhuma ir para a cama? Por volta dos 2,5 anos, algumas crianças começam a deixar a sesta. Não force o sono: substitua-o por 30 minutos de livros em silêncio.', title_sv = 'Bråk om dagsömnen 🥱', body_sv = 'Vill barnet absolut inte gå och lägga sig? Vid 2,5 år börjar vissa barn sluta sova på dagen. Ersätt sömnen med en 30 minuters tyst bokstund i stället för att tvinga.', title_vi = 'Bướng bỉnh với giấc ngủ ngày 🥱', body_vi = 'Bé nhất quyết không chịu lên giường? Ở tuổi 2,5, một số trẻ bắt đầu bỏ giấc ngủ ngày. Đừng ép ngủ, hãy thay bằng 30 phút "Giờ đọc sách yên tĩnh".', title_zh = '午睡闹别扭 🥱', body_zh = '怎么都不肯上床？2.5岁时有些孩子开始不再午睡。别强迫睡觉，用30分钟的“安静看书时间”来代替。' WHERE id = 'b24ba903-09d2-4243-a80b-995524b45caf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mira abajo, ¿qué hay? 👣', body_es = 'Le encanta andar descalzo y tocar superficies distintas (arena, alfombra, piedra). Estimular los nervios de la planta del pie es insustituible para su desarrollo neurológico.', title_fr = 'Regarde par terre, qu''est-ce qu''il y a ? 👣', body_fr = 'Il adore marcher pieds nus et toucher différentes surfaces (sable, tapis, cailloux). L''éveil des nerfs de la plante des pieds est précieux pour son développement neurologique.', title_hi = 'नीचे देखो, क्या है? 👣', body_hi = 'नंगे पैर चलने और अलग-अलग सतहों (रेत, कालीन, पत्थर) को छूने में उसे खास मज़ा आता है। तलवों की नसों का जागना उसके न्यूरोलॉजिकल विकास के लिए बेहद अहम है।', title_id = 'Lihat ke bawah, ada apa? 👣', body_id = 'Ia sangat senang berjalan tanpa alas kaki dan menyentuh berbagai permukaan (pasir, karpet, batu)? Rangsangan saraf di telapak kakinya sangat berharga bagi perkembangan sarafnya.', title_ja = '下を見て、何がある？👣', body_ja = 'はだしで歩いたり、いろいろな表面（砂、カーペット、石）にふれたりするのが大好き。足の裏の神経が目覚めることは、神経の発達にとってかけがえのないことです。', title_ko = '발밑에 뭐가 있을까? 👣', body_ko = '맨발로 걸으며 모래, 카펫, 돌 같은 여러 표면을 만지는 걸 특히 좋아하나요? 발바닥 신경의 자극은 신경 발달에 정말 소중해요.', title_nl = 'Kijk naar beneden, wat is daar? 👣', body_nl = 'Hij geniet extra van blootsvoets lopen en verschillende ondergronden voelen (zand, tapijt, steen). Het prikkelen van de zenuwen onder zijn voetzolen is onmisbaar voor zijn neurologische ontwikkeling.', title_pl = 'Spójrz w dół, co tam jest? 👣', body_pl = 'Z wyjątkową przyjemnością chodzi boso i dotyka różnych powierzchni (piasek, dywan, kamienie). Pobudzanie nerwów na podeszwach stóp jest bezcenne dla jego rozwoju neurologicznego.', title_pt = 'Olha para baixo, o que é? 👣', body_pt = 'Adora andar descalço e tocar em superfícies diferentes (areia, tapete, pedra). Estimular os nervos da planta do pé é insubstituível para o desenvolvimento neurológico.', title_sv = 'Titta ner, vad finns där? 👣', body_sv = 'Barnet njuter särskilt av att gå barfota och känna på olika ytor (sand, matta, sten). Att nerverna under fötterna väcks är ovärderligt för den neurologiska utvecklingen.', title_vi = 'Nhìn xuống xem, có gì nào? 👣', body_vi = 'Bé đặc biệt thích đi chân trần và chạm vào các bề mặt khác nhau (cát, thảm, đá). Việc kích thích các dây thần kinh dưới lòng bàn chân là vô giá cho sự phát triển thần kinh của bé.', title_zh = '往下看，有什么？👣', body_zh = '特别喜欢光着脚走路，摸摸不同的地面（沙子、地毯、石头）。唤醒脚底的神经，对宝宝的神经发育无可替代。' WHERE id = '54501d8f-f370-4895-a96c-448bca275b4e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '1 hora antes de dormir, apaga en casa las luces intensas y las pantallas azules. Crea en casa un ambiente tranquilo de noche para que se active la hormona melatonina.', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans bleus de la maison. Créez une ambiance tamisée de soirée pour que l''hormone mélatonine se mette en route.', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ लाइटें और नीली स्क्रीन बंद कर दीजिए। मेलाटोनिन हार्मोन के काम शुरू करने के लिए घर में शाम जैसा धीमा माहौल बनाइए।', body_id = 'Satu jam sebelum tidur, matikan semua lampu terang dan layar biru di rumah. Ciptakan suasana malam yang redup agar hormon melatonin mulai bekerja.', body_ja = '寝る1時間前には、家の明るい照明や画面の青い光をすべて消しましょう。メラトニンが働きだすように、家に夕暮れのような落ち着いた環境をつくって。', body_ko = '잠들기 1시간 전에는 집 안의 밝은 조명과 블루라이트 화면을 모두 꺼 주세요. 멜라토닌이 잘 분비되도록 저녁다운 차분한 분위기를 만들어 주세요.', body_nl = 'Doe 1 uur voor het slapengaan alle felle lampen en blauwe schermen in huis uit. Zorg voor een rustige avondsfeer in huis, zodat het hormoon melatonine op gang komt.', body_pl = '1 godzinę przed snem wyłącz w domu wszystkie mocne światła i niebieskie ekrany. Stwórz w domu wieczorny półmrok, by mógł zadziałać hormon melatonina.', body_pt = '1 hora antes de dormir, apague todas as luzes fortes da casa e os ecrãs azuis. Crie em casa um ambiente de fim de tarde, calmo, para que a hormona melatonina comece a atuar.', body_sv = 'En timme före läggdags, släck alla starka lampor och blå skärmar hemma. Skapa en skymningslik miljö hemma så att melatoninet kommer igång.', body_vi = 'Trước giờ ngủ 1 tiếng, hãy tắt mọi đèn sáng và màn hình ánh sáng xanh trong nhà. Tạo không gian buổi tối dịu nhẹ để hormone melatonin bắt đầu hoạt động.', body_zh = '睡前1小时，关掉家里所有昏暗的灯光和发蓝光的屏幕。在家里营造傍晚般的氛围，让褪黑素开始发挥作用。' WHERE id = '7212233e-c5da-4c83-bd8d-a74e469e3fcc' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preocupaciones de médico 🤖', body_es = '¿Tienes dudas sobre las vacunas o vitaminas necesarias a los 2,5 años? No te pierdas en foros de internet que asustan: pide ya a Anacan AI una respuesta precisa.', title_fr = 'Inquiétudes de santé 🤖', body_fr = 'Vous avez des doutes sur les vaccins ou les vitamines nécessaires à 2,5 ans ? Ne vous perdez pas sur des forums effrayants, obtenez tout de suite une réponse précise d''Anacan AI.', title_hi = 'डॉक्टर वाली चिंताएँ 🤖', body_hi = '2.5 साल के लिए ज़रूरी टीकों या विटामिन को लेकर शक है? इंटरनेट के डरावने फ़ोरम में मत खोइए, तुरंत Anacan AI से सटीक जवाब पाइए।', title_id = 'Cemas soal dokter 🤖', body_id = 'Ragu soal vaksin atau vitamin yang diperlukan untuk usia 2,5 tahun? Jangan tersesat di forum internet yang menakutkan, segera dapatkan jawaban tepat dari Anacan AI.', title_ja = '病院の心配ごと 🤖', body_ja = '2歳半に必要な予防接種やビタミンについて不安がありますか？ネットのこわい掲示板で迷わずに、すぐにAnacan AIから正確な答えをもらいましょう。', title_ko = '병원 걱정 🤖', body_ko = '두 돌 반에 필요한 예방접종이나 비타민이 헷갈리나요? 인터넷의 무서운 게시판에서 헤매지 말고 Anacan AI에게 바로 정확한 답을 받으세요.', title_nl = 'Zorgen over de dokter 🤖', body_nl = 'Twijfel je over de nodige vaccinaties of vitamines voor 2,5 jaar? Verdwaal niet op enge internetfora, maar krijg meteen een nauwkeurig antwoord van Anacan AI.', title_pl = 'Niepokoje przed lekarzem 🤖', body_pl = 'Masz wątpliwości co do szczepień lub witamin potrzebnych 2,5-latkowi? Nie gub się na przerażających forach internetowych, od razu uzyskaj dokładną odpowiedź od Anacan AI.', title_pt = 'Preocupações com o médico 🤖', body_pt = 'Tem dúvidas sobre as vacinas ou vitaminas necessárias aos 2,5 anos? Não se perca em fóruns assustadores na internet: obtenha já uma resposta precisa do Anacan AI.', title_sv = 'Oro inför läkarbesök 🤖', body_sv = 'Är du osäker på vilka vacciner eller vitaminer som behövs vid 2,5 år? Gå inte vilse i skrämmande forum på nätet, få ett exakt svar direkt från Anacan AI.', title_vi = 'Lo lắng chuyện khám bác sĩ 🤖', body_vi = 'Mẹ băn khoăn về các mũi tiêm hay vitamin cần thiết cho bé 2,5 tuổi? Đừng lạc vào những diễn đàn đáng sợ trên mạng, hãy hỏi ngay Anacan AI để có câu trả lời chính xác.', title_zh = '看病的担心 🤖', body_zh = '对2.5岁需要的疫苗或维生素有疑问？别在网上那些吓人的论坛里迷失，马上从Anacan AI那里得到准确的回答。' WHERE id = 'efc5b454-d92c-49c6-a2a5-9e995c6d9a84' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Microdiscusiones 🗣️', body_es = '«¡No, soy mayor, yo sé!». Ya intenta llevarte la contraria con argumentos. Respóndele sin levantar la voz, a su altura pero con firmeza.', title_fr = 'Mini-disputes 🗣️', body_fr = '« Non, je suis grand, je sais ! » Il essaie déjà de vous contredire avec des arguments. Répondez sans hausser le ton, au même niveau, mais fermement.', title_hi = 'छोटी-छोटी बहसें 🗣️', body_hi = '''नहीं, मैं बड़ा हूँ, मुझे पता है!'' अब वह तर्क देकर आपसे असहमत होने की कोशिश करता है। आवाज़ ऊँची किए बिना, उसी स्तर पर, लेकिन दृढ़ता से जवाब दीजिए।', title_id = 'Debat mini 🗣️', body_id = '''Tidak, aku sudah besar, aku tahu sendiri!'' Ia kini mencoba membantah Anda dengan argumen. Jawablah tanpa meninggikan suara, dengan nada setara namun tegas.', title_ja = '小さな言い合い 🗣️', body_ja = '「ちがう、ぼくは大きいの、自分でわかる！」理由を言ってあなたに反対しようとしています。声を荒げず、同じ目線で、でもきっぱりと答えましょう。', title_ko = '작은 말다툼 🗣️', body_ko = '''아니야, 나 다 컸어, 내가 알아!'' 이제 논리를 대며 엄마 말에 반대하려 하나요? 목소리를 높이지 말고 같은 높이에서 차분하지만 단호하게 대답해 주세요.', title_nl = 'Mini-discussies 🗣️', body_nl = '''Nee, ik ben groot, ik weet het zelf!'' Hij probeert het nu met argumenten oneens met je te zijn. Antwoord zonder je stem te verheffen, op dezelfde toon maar duidelijk.', title_pl = 'Mikrokłótnie 🗣️', body_pl = '„Nie, jestem duży, sam wiem!”. Już próbuje się z tobą nie zgadzać, podając argumenty. Odpowiadaj bez podnoszenia głosu, na tym samym poziomie, ale stanowczo.', title_pt = 'Microdiscussões 🗣️', body_pt = '"Não, eu sou grande, eu é que sei!" Já tenta discordar de si com argumentos. Responda sem levantar a voz, no mesmo tom, mas com firmeza.', title_sv = 'Mikrodiskussioner 🗣️', body_sv = '”Nej, jag är stor, jag vet själv!” Barnet försöker redan säga emot dig med argument. Svara utan att höja rösten, på samma nivå men bestämt.', title_vi = 'Những cuộc tranh luận nhỏ 🗣️', body_vi = '"Không, con lớn rồi, con tự biết!" Bé đã biết đưa ra lý lẽ để không đồng ý với mẹ. Hãy trả lời không cao giọng, ngang hàng với bé nhưng thật dứt khoát.', title_zh = '小小争论 🗣️', body_zh = '“不，我长大了，我自己知道！”宝宝已经会摆出理由和你唱反调了。别提高音调，用同样平和但坚定的语气回应。' WHERE id = '235bf352-67d4-4056-94d7-5429271d340f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedicarte tiempo no es pecado 💆‍♀️', body_es = 'El síndrome de «paso poco tiempo con mi hijo» le llega a toda madre. Pero olvidas que una madre agotada no tiene nada que dar. A mediodía regálate una pausa de 20 minutos para respirar.', title_fr = 'Prendre du temps pour soi n''est pas une faute 💆‍♀️', body_fr = 'Le syndrome « je ne passe pas assez de temps avec mon enfant » touche toutes les mamans. Mais vous oubliez qu''une maman épuisée n''a plus rien à donner. Accordez-vous 20 minutes de pause pour respirer en début d''après-midi.', title_hi = 'अपने लिए समय निकालना गुनाह नहीं 💆‍♀️', body_hi = '''मैं बच्चे के साथ कम समय बिताती हूँ'' वाला एहसास हर माँ को होता है। लेकिन आप भूल जाती हैं कि थकी हुई माँ के पास बच्चे को देने के लिए कुछ नहीं बचता। दोपहर में अपने लिए 20 मिनट का साँस लेने वाला ब्रेक निकालिए।', title_id = 'Meluangkan waktu untuk diri bukan dosa 💆‍♀️', body_id = 'Sindrom ''aku kurang waktu bersama anak'' menghantui setiap ibu. Tetapi ingat, ibu yang kehabisan tenaga tidak punya apa-apa lagi untuk diberikan kepada anak. Di siang hari, sisihkan 20 menit jeda bernapas untuk diri Anda.', title_ja = '自分の時間を持つのは悪いことじゃない 💆‍♀️', body_ja = '「子どもと過ごす時間が少ない」という悩みは、どのママにも訪れます。でも、疲れきったママには子どもにあげられるものが何もありません。お昼に自分のための20分の息抜きをつくりましょう。', title_ko = '나를 위한 시간은 죄가 아니에요 💆‍♀️', body_ko = '''아이와 보내는 시간이 부족해'' 증후군은 모든 엄마를 찾아와요. 하지만 지친 엄마는 아이에게 줄 것이 없다는 걸 잊지 마세요. 오후에 나를 위한 20분의 숨 고르기 시간을 만드세요.', title_nl = 'Tijd voor jezelf is geen zonde 💆‍♀️', body_nl = 'Het ''ik besteed te weinig tijd aan mijn kind''-gevoel treft elke moeder. Maar vergeet niet: een uitgeputte moeder heeft haar kind niets meer te geven. Neem ''s middags 20 minuten ademruimte voor jezelf.', title_pl = 'Czas dla siebie to nie grzech 💆‍♀️', body_pl = 'Syndrom „spędzam z dzieckiem za mało czasu” dopada każdą mamę. Ale zapominasz, że wyczerpana mama nie ma dziecku nic do dania. Zrób sobie po południu 20-minutową przerwę na oddech.', title_pt = 'Tempo para si não é pecado 💆‍♀️', body_pt = 'A síndrome do "passo pouco tempo com o meu filho" atinge todas as mães. Mas esquece-se de que uma mãe esgotada não tem nada para dar. À tarde, crie para si uma pausa de 20 minutos para respirar.', title_sv = 'Att ta tid för sig själv är ingen synd 💆‍♀️', body_sv = 'Syndromet ”jag spenderar för lite tid med barnet” drabbar varje mamma. Men du glömmer att en utmattad mamma inte har något att ge barnet. Skapa en 20 minuters andningspaus åt dig själv mitt på dagen.', title_vi = 'Dành thời gian cho mình không có lỗi 💆‍♀️', body_vi = 'Hội chứng "Mình dành quá ít thời gian cho con" ai làm mẹ cũng gặp. Nhưng đừng quên một người mẹ kiệt sức không còn gì để trao cho con. Buổi trưa hãy dành cho mình 20 phút hít thở.', title_zh = '给自己留点时间不是罪过 💆‍♀️', body_zh = '“我陪孩子的时间太少”的想法每个妈妈都有过。可别忘了，被掏空的妈妈什么也给不了孩子。中午给自己留20分钟喘口气吧。' WHERE id = 'ae99921f-bf29-40ac-a251-a633a4741d07' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La carga más bonita 🫂', body_es = 'Te ha vuelto loca todo el día y ha llorado por todo. Pero por la noche, al dormirse, el olor de ese cuerpecito cálido acurrucado en tu pecho... Eso es el sentimiento más bonito del mundo.', title_fr = 'Le plus doux des fardeaux 🫂', body_fr = 'Toute la journée, il vous a rendue folle et a pleuré pour tout. Mais le soir, l''odeur de ce petit corps chaud blotti contre vous au moment de s''endormir... Voilà le plus beau sentiment du monde.', title_hi = 'सबसे प्यारा बोझ 🫂', body_hi = 'दिनभर उसने आपको परेशान किया, हर बात पर रोया। लेकिन शाम को सोते समय आपके सीने से लिपटे उस गर्म, नन्हे शरीर की खुशबू... यही दुनिया का सबसे खूबसूरत एहसास है।', title_id = 'Beban paling indah 🫂', body_id = 'Seharian ia membuat Anda pusing dan menangis karena segala hal. Tetapi di malam hari, saat ia tertidur meringkuk di dada Anda, aroma tubuh kecil yang hangat itu... Itulah perasaan terindah di dunia.', title_ja = 'いちばんすてきな重み 🫂', body_ja = '一日じゅう振り回されて、何にでも泣いていました。でも夜、眠りにつくときに胸に寄りそう、あたたかく小さな体のにおい…これこそ世界でいちばんすてきな気持ちです。', title_ko = '가장 사랑스러운 무게 🫂', body_ko = '하루 종일 정신없게 하고 모든 것에 울었죠. 하지만 저녁에 잠들며 엄마 품에 파고드는 그 따뜻하고 작은 몸의 냄새... 이게 바로 세상에서 가장 아름다운 감정이에요.', title_nl = 'De mooiste last 🫂', body_nl = 'Hij maakte je de hele dag gek en huilde om alles. Maar de geur van dat warme lijfje dat ''s avonds bij het inslapen tegen je borst kruipt... Dat is het mooiste gevoel ter wereld.', title_pl = 'Najpiękniejszy ciężar 🫂', body_pl = 'Przez cały dzień doprowadzał cię do szału i płakał o wszystko. Ale wieczorem, gdy zasypia, zapach tego ciepłego, małego ciałka przytulonego do ciebie... To najpiękniejsze uczucie na świecie.', title_pt = 'O peso mais bonito 🫂', body_pt = 'Durante o dia deu-lhe a volta à cabeça e chorou por tudo. Mas à noite, ao adormecer, o cheiro daquele corpinho quente aninhado no seu peito... Isso é o sentimento mais bonito do mundo.', title_sv = 'Den finaste bördan 🫂', body_sv = 'Barnet gjorde dig galen hela dagen och grät för allt. Men på kvällen, när den varma lilla kroppen kryper intill dig och somnar, doften... Det är världens finaste känsla.', title_vi = 'Gánh nặng ngọt ngào nhất 🫂', body_vi = 'Cả ngày bé khiến mẹ phát điên, khóc vì mọi thứ. Nhưng buổi tối khi chìm vào giấc ngủ, mùi hương của thân hình nhỏ bé ấm áp nép vào lòng mẹ... Đó chính là cảm giác đẹp nhất trên đời.', title_zh = '最美的负担 🫂', body_zh = '一整天把你折腾得快疯了，什么都哭。可晚上入睡时，那个依偎在你怀里、温暖小小的身体的气味……这就是世界上最美好的感觉。' WHERE id = 'ead40251-f5fc-4b01-b344-4b041fbbf0eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Harta de ir cada día al mismo parque? Descubre en Lugares para mamás una cafetería tranquila y distinta donde tu peque pueda jugar a gusto, y date hoy un capricho.', body_fr = 'Lassée d''aller tous les jours au même parc ? Découvrez dans les Lieux adaptés aux mamans un café calme et différent où les enfants jouent tranquillement, et faites-vous plaisir aujourd''hui.', body_hi = 'रोज़ एक ही पार्क जाते-जाते ऊब गईं? माँ के लिए अनुकूल जगहें में ऐसा शांत और अलग कैफ़े खोजिए जहाँ बच्चे भी आराम से खेल सकें, और आज खुद को थोड़ा लाड़ दीजिए।', body_id = 'Bosan pergi ke taman yang sama setiap hari? Temukan kafe yang tenang dan berbeda di Tempat Ramah Ibu, tempat anak juga bisa bermain dengan nyaman, dan manjakan diri Anda hari ini.', body_ja = '毎日同じ公園に行くのにあきましたか？「ママにやさしいスポット」で、お子さんものびのび遊べる静かでいつもと違うカフェを見つけて、今日は自分を甘やかしましょう。', body_ko = '매일 같은 공원에 가는 게 지겨워졌나요? 엄마 친화 장소에서 아이도 편히 놀 수 있는 조용하고 색다른 카페를 찾아 오늘은 나를 아껴 주세요.', body_nl = 'Ben je het zat om elke dag naar hetzelfde park te gaan? Ontdek in Mamavriendelijke plekken een rustig, ander café waar kinderen ook fijn kunnen spelen, en verwen jezelf vandaag.', body_pl = 'Masz dość chodzenia codziennie do tego samego parku? Odkryj w Miejscach przyjaznych mamom cichą, inną kawiarnię, gdzie dzieci też mogą swobodnie się bawić, i rozpieść się dziś.', body_pt = 'Cansada de ir sempre ao mesmo parque? Descubra nos Locais Amigos das Mães um café diferente e sossegado, onde as crianças também brincam à vontade, e mime-se hoje.', body_sv = 'Är du trött på att gå till samma park varje dag? Upptäck ett lugnt och annorlunda kafé i Mammavänliga platser där barnen också kan leka bekvämt, och skäm bort dig själv i dag.', body_vi = 'Mẹ chán ngày nào cũng ra một công viên? Hãy tìm trong Địa điểm thân thiện với mẹ một quán cà phê yên tĩnh, mới lạ, nơi bé cũng có thể thoải mái vui chơi, và hôm nay hãy tự chiều chuộng mình.', body_zh = '每天去同一个公园，腻了吧？在妈妈友好场所里找一家安静、与众不同、孩子也能自在玩耍的咖啡馆，今天宠一宠自己吧。' WHERE id = '41765791-323c-438b-b416-30b7105b9c01' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Formas y espacio 🧩', body_es = 'Insiste en meter puzles y formas en sus agujeros. Aunque se equivoque, no intervengas. Aprende a resolver problemas justamente a base de prueba y error.', title_fr = 'Formes et espace 🧩', body_fr = 'Il s''obstine à glisser les puzzles et les formes dans les bons trous. Même s''il se trompe, n''intervenez pas. C''est justement par essais et erreurs qu''il apprend à résoudre les problèmes.', title_hi = 'आकार और जगह की समझ 🧩', body_hi = 'पज़ल और अलग-अलग आकारों को सही छेद में डालने की ज़िद करता है? गलती करे तब भी दखल मत दीजिए। वह आज़माने और गलती करने से ही समस्या सुलझाना सीखता है।', title_id = 'Mengenal bentuk dan ruang 🧩', body_id = 'Ia bersikeras memasukkan puzzle dan berbagai bentuk ke lubang yang pas? Jangan ikut campur meski ia salah. Ia justru belajar memecahkan masalah lewat coba-coba.', title_ja = '形と空間の理解 🧩', body_ja = 'パズルやいろいろな形を合う穴に入れようと、ねばり強くがんばっていますか？まちがえても手を出さないで。問題解決の力は、まさに試行錯誤で身につきます。', title_ko = '모양과 공간 개념 🧩', body_ko = '퍼즐과 여러 모양을 맞는 구멍에 넣으려고 끈질기게 노력하나요? 틀려도 끼어들지 마세요. 시행착오를 통해 문제 해결 능력을 배우는 중이에요.', title_nl = 'Begrip van vorm en ruimte 🧩', body_nl = 'Wil hij per se puzzels en vormen in de juiste gaatjes stoppen? Grijp niet in, ook als het fout gaat. Juist door vallen en opstaan leert hij problemen oplossen.', title_pl = 'Pojęcie kształtu i przestrzeni 🧩', body_pl = 'Uparcie wkłada układanki i różne kształty do pasujących otworów. Nie wtrącaj się, nawet gdy się myli. Właśnie metodą prób i błędów uczy się rozwiązywać problemy.', title_pt = 'Noção de forma e espaço 🧩', body_pt = 'Insiste em encaixar puzzles e formas diferentes nos buracos certos. Mesmo que erre, não intervenha. É precisamente por tentativa e erro que aprende a resolver problemas.', title_sv = 'Form och rum 🧩', body_sv = 'Barnet envisas med att få ner pusselbitar och olika former i rätt hål. Ingrip inte även om hen gör fel. Barnet lär sig problemlösning just genom att pröva och misslyckas.', title_vi = 'Khái niệm hình dạng và không gian 🧩', body_vi = 'Bé kiên trì đặt các mảnh ghép, các hình khối vào đúng lỗ. Dù bé có sai cũng đừng can thiệp. Bé học kỹ năng giải quyết vấn đề chính qua thử và sai.', title_zh = '形状和空间的概念 🧩', body_zh = '坚持要把拼图、各种形状塞进对应的洞里。就算放错了也别插手。宝宝正是在反复尝试和犯错中学会解决问题的。' WHERE id = 'dc90d262-2720-4f19-9f2a-dcf90cd5da80' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ruido blanco natural 🤫', body_es = 'La primera media hora después de dormirse es cuando el cerebro está más activo. Ajusta la habitación con el Medidor de sonido. A veces basta con el sonido de una lluvia suave para llevarle a un sueño profundo.', title_fr = 'Un bruit blanc naturel 🤫', body_fr = 'La première demi-heure de sommeil est le moment où le cerveau est le plus actif. Ajustez la chambre avec le Sonomètre. Parfois, le simple bruit d''une pluie légère suffit à l''emmener dans un sommeil profond.', title_hi = 'प्राकृतिक व्हाइट नॉइज़ 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा वह समय है जब दिमाग सबसे सक्रिय होता है। साउंड मीटर से कमरे का माहौल ठीक कीजिए। कभी-कभी हल्की बारिश की आवाज़ ही उसे गहरी नींद में ले जा सकती है।', title_id = 'Suara putih alami 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah saat otak paling aktif. Atur kamar dengan Pengukur Suara. Kadang suara gerimis saja bisa membawanya ke tidur yang lelap.', title_ja = '自然のホワイトノイズ 🤫', body_ja = '寝ついてから最初の30分は、脳がいちばん活発な時間です。「サウンドメーター」で部屋を整えましょう。やさしく降る雨の音だけで、深い眠りに入れることもあります。', title_ko = '자연의 백색소음 🤫', body_ko = '잠든 후 첫 30분은 뇌가 가장 활발한 시간이에요. 소음 측정기로 방을 조절하세요. 때로는 잔잔한 빗소리만으로도 깊은 잠에 빠질 수 있어요.', title_nl = 'Natuurlijke witte ruis 🤫', body_nl = 'Het eerste halfuur na het inslapen zijn de hersenen het actiefst. Stem de kamer af met de Geluidsmeter. Soms brengt alleen al het geluid van zachte regen hem in een diepe slaap.', title_pl = 'Naturalny biały szum 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to czas największej aktywności mózgu. Dostosuj pokój Miernikiem dźwięku. Czasem sam odgłos delikatnego deszczu wystarczy, by zapadł w głęboki sen.', title_pt = 'Ruído branco natural 🤫', body_pt = 'A primeira meia hora depois de adormecer é quando o cérebro está mais ativo. Ajuste o quarto com o Medidor de Som. Às vezes basta o som de uma chuva leve para o levar a um sono profundo.', title_sv = 'Naturligt vitt brus 🤫', body_sv = 'Den första halvtimmen efter insomnandet är då hjärnan är som mest aktiv. Justera rummet med Ljudmätaren. Ibland räcker ljudet av lätt regn för att barnet ska falla i djup sömn.', title_vi = 'Tiếng ồn trắng tự nhiên 🤫', body_vi = 'Nửa giờ đầu sau khi bé ngủ là lúc não hoạt động mạnh nhất. Hãy điều chỉnh phòng bằng Đo âm thanh. Đôi khi chỉ tiếng mưa rơi nhẹ cũng có thể đưa bé vào giấc ngủ sâu.', title_zh = '天然白噪音 🤫', body_zh = '入睡后的头半小时是大脑最活跃的时候。用分贝仪调节房间环境。有时只是轻轻的雨声，就能把宝宝带入深睡。' WHERE id = 'e0925ec9-2283-4167-888a-ee7948c21d0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Date las gracias 🎈', body_es = 'Noches sin dormir, días a la carrera... Pero lo has conseguido. ¡Hoy dite «Bien hecho» por criarle sin levantar la voz!', title_fr = 'Remerciez-vous 🎈', body_fr = 'Des nuits sans sommeil, des journées à courir... Mais vous y êtes arrivée. Aujourd''hui, dites-vous « Bravo ! » pour l''avoir élevé sans hausser la voix.', title_hi = 'खुद को धन्यवाद दीजिए 🎈', body_hi = 'रातों को नींद नहीं, दिन में भागदौड़... लेकिन आपने कर दिखाया। आज आवाज़ ऊँची किए बिना उसकी परवरिश करने के लिए खुद से कहिए ''शाबाश!''', title_id = 'Berterima kasihlah pada diri sendiri 🎈', body_id = 'Malam tanpa tidur, siang penuh kesibukan... Tetapi Anda berhasil. Hari ini katakan ''Hebat!'' pada diri sendiri karena telah membesarkannya tanpa meninggikan suara!', title_ja = '自分にありがとう 🎈', body_ja = '夜は寝不足、昼はバタバタ…でもあなたはやりとげました。今日、声を荒げずにお子さんを育てた自分に「よくがんばったね」と言ってあげましょう！', title_ko = '스스로에게 고마워하세요 🎈', body_ko = '잠 못 드는 밤, 정신없는 낮... 그래도 해냈어요. 오늘 목소리 한 번 높이지 않고 아이를 돌본 나에게 ''잘했어!''라고 말해 주세요.', title_nl = 'Bedank jezelf 🎈', body_nl = '''s Nachts slapeloos, overdag gerace... Maar je hebt het geflikt. Zeg vandaag ''Goed gedaan!'' tegen jezelf, omdat je hem grootbracht zonder je stem te verheffen.', title_pl = 'Podziękuj sobie 🎈', body_pl = 'Nieprzespane noce, dzienna bieganina... Ale dałaś radę. Powiedz dziś sobie „Brawo!” za to, że wychowujesz go bez podnoszenia głosu.', title_pt = 'Agradeça a si mesma 🎈', body_pt = 'Noites sem dormir, dias a correr... Mas conseguiu. Hoje, dê-se os parabéns por o ter criado sem levantar a voz!', title_sv = 'Tacka dig själv 🎈', body_sv = 'Sömnlösa nätter, hektiska dagar... Men du klarade det. Säg ”Bra jobbat!” till dig själv i dag för att du tog hand om barnet utan att höja rösten.', title_vi = 'Hãy cảm ơn chính mình 🎈', body_vi = 'Đêm thì mất ngủ, ngày thì tất bật... Nhưng mẹ đã làm được. Hôm nay hãy tự nói "Giỏi lắm!" vì đã nuôi dạy bé mà không cần to tiếng!', title_zh = '谢谢自己 🎈', body_zh = '晚上睡不好，白天忙不停……可你做到了。今天没提高嗓门把宝宝带好了，对自己说一声“真棒！”吧。' WHERE id = '28ff0d8a-2265-4669-8253-5aac2bfb80da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Ir al súper sin lista? ¡Jamás! 🛒', body_es = 'Vas al súper fiándote de tu memoria y vuelves sin lo más necesario. Deja de hacerlo. Acostúmbrate a apuntar al momento en la Lista de la compra cada cosa que falte en casa.', title_fr = 'Faire les courses sans liste ? Jamais ! 🛒', body_fr = 'Vous faites confiance à votre mémoire au supermarché et rentrez sans l''essentiel. Fini tout ça. Prenez l''habitude de noter immédiatement chaque manque dans la Liste de courses.', title_hi = 'बिना लिस्ट के बाज़ार? कभी नहीं! 🛒', body_hi = 'याददाश्त के भरोसे बाज़ार जाती हैं और सबसे ज़रूरी चीज़ के बिना लौट आती हैं? यह आदत छोड़िए। घर में किसी भी चीज़ की कमी को तुरंत शॉपिंग लिस्ट में लिखने की आदत बनाइए।', title_id = 'Belanja tanpa daftar? Jangan! 🛒', body_id = 'Anda pergi belanja mengandalkan ingatan dan pulang tanpa barang yang paling penting. Tinggalkan kebiasaan ini. Biasakan langsung mencatat setiap kekurangan di rumah ke Daftar Belanja.', title_ja = 'リストなしで買い物？絶対ダメ！🛒', body_ja = '記憶にたよって買い物に行き、いちばん必要なものを買い忘れて帰ってくる。もうやめましょう。家で切れたものはすぐに「買い物リスト」に書くことを習慣にして。', title_ko = '목록 없이 장보기? 절대 안 돼요! 🛒', body_ko = '기억만 믿고 마트에 갔다가 가장 필요한 걸 빼고 돌아오나요? 이제 그만하세요. 집에 떨어진 게 생기면 바로 쇼핑 목록에 적는 습관을 들이세요.', title_nl = 'Zonder lijstje boodschappen doen? Nooit! 🛒', body_nl = 'Je vertrouwt op je geheugen in de supermarkt en komt thuis zonder het belangrijkste. Stop daarmee. Maak er een gewoonte van om alles wat thuis op is meteen op je Boodschappenlijstje te zetten.', title_pl = 'Zakupy bez listy? Nigdy! 🛒', body_pl = 'Ufasz pamięci, idziesz do sklepu i wracasz bez najpotrzebniejszej rzeczy. Skończ z tym. Wyrób sobie nawyk, by od razu wpisywać każdy brak na Listę zakupów.', title_pt = 'Ir ao supermercado sem lista? Nunca! 🛒', body_pt = 'Confia na memória, vai ao supermercado e volta para casa sem o mais importante. Deixe isso. Crie o hábito de apontar logo na Lista de Compras tudo o que falta em casa.', title_sv = 'Handla utan lista? Aldrig! 🛒', body_sv = 'Du litar på ditt minne när du går och handlar och kommer hem utan det viktigaste. Sluta med det. Gör det till en vana att genast skriva in allt som saknas hemma i Inköpslistan.', title_vi = 'Đi chợ không có danh sách? Không bao giờ! 🛒', body_vi = 'Mẹ tin vào trí nhớ để đi siêu thị rồi về nhà thiếu đúng món cần nhất. Hãy bỏ thói quen đó. Tập ghi ngay mọi thứ còn thiếu trong nhà vào Danh sách mua sắm.', title_zh = '不带清单去超市？绝不！🛒', body_zh = '相信自己的记性去超市，结果最需要的东西没买回来。别这样了。养成习惯，家里缺什么就马上写进购物清单。' WHERE id = '95ffd69a-c8c2-4b14-b98e-76c322f02229' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Nadie te entiende? ¿Nadie ve tu cansancio? El Diario de ánimo es tu mejor confidente. Escribe ahí todo el estrés, el dolor y la soledad, y verás cómo te alivias por dentro.', body_fr = 'Personne ne vous comprend ? Personne ne voit votre fatigue ? Le Journal d''humeur est le meilleur confident. Écrivez-y tout votre stress, votre douleur et votre solitude, vous verrez comme vous vous sentirez soulagée.', body_hi = 'कोई आपको नहीं समझता? आपकी थकान नहीं देखता? मूड डायरी सबसे अच्छी राज़दार है। वहाँ सारा तनाव, दर्द और अकेलापन लिखिए, आप देखेंगी कि मन कितना हल्का हो जाता है।', body_id = 'Merasa tidak ada yang memahami Anda? Tidak ada yang melihat lelah Anda? Buku Harian Suasana Hati adalah teman curhat terbaik. Tuliskan semua stres, rasa sakit, dan kesepian di sana, Anda akan merasakan hati jadi lega.', body_ja = 'だれもわかってくれない？疲れに気づいてもらえない？「気分日記」はいちばんの打ち明け相手です。ストレスも痛みもさみしさも全部書いてみて、心がどれほど軽くなるかわかります。', body_ko = '아무도 나를 이해하지 못하나요? 피곤함을 몰라주나요? 기분 일기는 최고의 비밀 친구예요. 스트레스, 아픔, 외로움을 모두 적어 보세요. 마음이 얼마나 가벼워지는지 느낄 거예요.', body_nl = 'Begrijpt niemand je? Ziet niemand je vermoeidheid? Je Stemmingsdagboek is je beste vertrouweling. Schrijf er al je stress, pijn en eenzaamheid in en je zult merken hoe opgelucht je je voelt.', body_pl = 'Nikt cię nie rozumie? Nie widzi twojego zmęczenia? Dziennik nastroju to najlepszy powiernik. Wpisz tam cały stres, ból i samotność, a zobaczysz, jak ci ulży.', body_pt = 'Ninguém a compreende? Ninguém vê o seu cansaço? O Diário de Humor é o melhor confidente. Escreva lá todo o stress, a dor e a solidão e vai ver como fica aliviada.', body_sv = 'Känns det som att ingen förstår dig? Att ingen ser din trötthet? Humördagboken är den bästa förtrogna. Skriv av dig all stress, smärta och ensamhet där, så märker du hur det lättar.', body_vi = 'Không ai hiểu mẹ? Không ai thấy mẹ mệt mỏi? Nhật ký tâm trạng là người bạn tâm giao tốt nhất. Hãy viết hết căng thẳng, nỗi đau và cô đơn vào đó, mẹ sẽ thấy lòng nhẹ nhõm biết bao.', body_zh = '没人理解你？没人看见你的疲惫？心情日记是最好的知己。把所有的压力、痛苦和孤独都写进去，你会发现心里轻松多了。' WHERE id = 'ec24c154-30dc-40d8-8aed-20579933d8fb' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue la guerra contra las verduras 🥦', body_es = '¿Otra vez ha rechazado la comida al ver ese trocito de zanahoria en la sopa? Reduce las raciones y cambia las formas. La creatividad es la mejor arma de una madre.', title_fr = 'La guerre des légumes continue 🥦', body_fr = 'Il a encore refusé de manger parce qu''il a vu ce petit morceau de carotte dans la soupe ? Réduisez les portions, changez les formes. La créativité est la plus grande arme d''une maman.', title_hi = 'सब्ज़ियों से दुश्मनी जारी है 🥦', body_hi = 'फिर से सूप में गाजर का छोटा सा टुकड़ा देखकर खाने से मना कर दिया? हिस्से छोटे कीजिए, आकार बदलिए। रचनात्मकता माँ का सबसे बड़ा हथियार है।', title_id = 'Perang melawan sayuran berlanjut 🥦', body_id = 'Lagi-lagi ia menolak makan karena melihat potongan kecil wortel di supnya? Kecilkan porsinya, ubah bentuknya. Kreativitas adalah senjata terbesar seorang ibu.', title_ja = '野菜との戦いは続く 🥦', body_ja = 'またスープの小さなにんじんを見つけて、食べるのをやめましたか？量を少なくして、形を変えてみましょう。創意工夫はママのいちばんの武器です。', title_ko = '채소와의 전쟁은 계속돼요 🥦', body_ko = '수프 속 작은 당근 조각을 보고 또 안 먹겠다고 했나요? 양은 줄이고 모양을 바꿔 보세요. 창의력은 엄마의 가장 큰 무기예요.', title_nl = 'De oorlog met groenten gaat door 🥦', body_nl = 'Weigerde hij weer te eten omdat hij dat kleine stukje wortel in de soep zag? Maak kleinere porties en verander de vormen. Creativiteit is het grootste wapen van een moeder.', title_pl = 'Wojna z warzywami trwa 🥦', body_pl = 'Znowu zobaczył w zupie mały kawałek marchewki i odmówił jedzenia? Zmniejsz porcje, zmień kształty. Kreatywność to największa broń mamy.', title_pt = 'A guerra aos legumes continua 🥦', body_pt = 'Voltou a recusar a comida por ver aquele pedacinho de cenoura na sopa? Diminua as porções e mude as formas. A criatividade é a maior arma de uma mãe.', title_sv = 'Grönsaksfiendskapen fortsätter 🥦', body_sv = 'Vägrade barnet äta igen när hen såg den lilla morotsbiten i soppan? Gör portionerna mindre och ändra formerna. Kreativitet är mammans största vapen.', title_vi = 'Cuộc chiến với rau củ vẫn tiếp diễn 🥦', body_vi = 'Bé lại không chịu ăn vì thấy miếng cà rốt nhỏ trong bát canh? Hãy giảm khẩu phần, đổi hình dạng. Sự sáng tạo là vũ khí lớn nhất của người mẹ.', title_zh = '和蔬菜的战争还在继续 🥦', body_zh = '又因为看到汤里那一小块胡萝卜就不肯吃了？把份量变小，换换形状。创意是妈妈最大的武器。' WHERE id = '093d545f-b52d-4160-be2f-88e5e1b53427' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La sorpresa del «¡Te encontré!» 🙈', body_es = 'Las reglas del escondite han cambiado. Ahora se esconde él y sale gritando «¡Estoy aquí!». Deja que invente las reglas del juego y reíd a carcajadas.', title_fr = 'La surprise « Coucou, je t''ai trouvé ! » 🙈', body_fr = 'Les règles du cache-cache ont changé. Maintenant, c''est lui qui se cache et qui surgit en criant « Je suis là ! ». Laissez-le inventer les règles et riez aux éclats.', title_hi = '''मिल गया!'' वाला सरप्राइज़ 🙈', body_hi = 'छुपन-छुपाई के नियम बदल गए हैं। अब वह छिपता है और खुद ही ''मैं यहाँ हूँ!'' चिल्लाकर बाहर आ जाता है। खेल के नियम उसे बनाने दीजिए और खूब हँसिए।', title_id = 'Kejutan ''Ketemu!'' 🙈', body_id = 'Aturan petak umpet sudah berubah. Kini ia yang bersembunyi lalu keluar sambil berteriak ''Aku di sini!''. Biarkan ia mengarang aturan mainnya dan tertawalah bersama.', title_ja = '「みーつけた！」のサプライズ 🙈', body_ja = 'かくれんぼのルールが変わりました。今度はお子さんが隠れて、自分から「ここだよ！」と叫んで出てきます。ルールはお子さんに考えさせて、一緒に大笑いしましょう。', title_ko = '''찾았다!'' 깜짝 놀이 🙈', body_ko = '숨바꼭질 규칙이 바뀌었어요. 이제 아이가 숨었다가 ''나 여기 있어!'' 하고 소리치며 나와요. 놀이 규칙을 아이가 만들게 하고 함께 깔깔 웃어 보세요.', title_nl = 'Verrassing: ''Gevonden!'' 🙈', body_nl = 'De regels van verstoppertje zijn veranderd. Nu verstopt hij zich en springt hij zelf tevoorschijn met ''Hier ben ik!''. Laat hem de spelregels verzinnen en lach lekker mee.', title_pl = 'Niespodzianka „Mam cię!” 🙈', body_pl = 'Zasady zabawy w chowanego się zmieniły. Teraz to on się chowa i sam wyskakuje z okrzykiem „Tu jestem!”. Pozwól mu wymyślać zasady i śmiejcie się razem.', title_pt = 'A surpresa do "Encontrei-te!" 🙈', body_pt = 'As regras das escondidas mudaram. Agora é ele que se esconde e sai a gritar "Estou aqui!". Deixe-o inventar as regras do jogo e riam às gargalhadas.', title_sv = 'Överraskningen i ”Där är du!” 🙈', body_sv = 'Reglerna för kurragömma har ändrats. Nu gömmer sig barnet och kommer själv fram och ropar ”Här är jag!”. Låt barnet hitta på reglerna och skratta gott.', title_vi = 'Bất ngờ "Tìm thấy con rồi!" 🙈', body_vi = 'Luật chơi trốn tìm đã thay đổi. Giờ bé tự trốn rồi tự nhảy ra hét "Con ở đây!". Hãy để bé tự nghĩ ra luật chơi và cùng cười thật giòn tan.', title_zh = '“找到你啦！”的惊喜 🙈', body_zh = '躲猫猫的规则变了。现在宝宝自己躲起来，然后大喊“我在这儿！”跑出来。让宝宝自己编游戏规则，一起哈哈大笑吧。' WHERE id = '0e43d226-9cd6-4c62-b9a7-e0206f0830ca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si es una tarde de mucha tozudez y nervios, mételo en agua templada. Simplemente jugar con el agua en la bañera, con su poder terapéutico, se llevará toda su energía negativa.', body_fr = 'Si la soirée est particulièrement têtue et nerveuse, mettez-le dans l''eau tiède. Le simple fait de jouer avec l''eau du bain et son pouvoir apaisant emportera toute son énergie négative.', body_hi = 'अगर शाम बहुत ज़िद और चिड़चिड़ाहट भरी है, तो उसे गुनगुने पानी में बिठाइए। टब में बस पानी से खेलना और पानी की चिकित्सीय ताकत उसकी सारी नकारात्मक ऊर्जा धो देगी।', body_id = 'Jika malam ini ia sangat rewel dan keras kepala, ajak ia berendam air hangat. Sekadar bermain air di bak mandi, kekuatan terapi air akan menghanyutkan semua energi negatifnya.', body_ja = 'とてもがんこでイライラした夜なら、ぬるめのお湯に入れてあげましょう。お風呂でただお水と遊ぶだけで、お水の癒やしの力が嫌な気分をすっかり洗い流してくれます。', body_ko = '유난히 고집 세고 예민한 저녁이라면 따뜻한 물에 들어가게 해 주세요. 욕조에서 물장난만 쳐도 물의 치유력이 나쁜 기운을 모두 씻어 낼 거예요.', body_nl = 'Is het een koppige, prikkelbare avond? Zet hem in lauw water. Gewoon met water spelen in bad: de helende kracht van water spoelt al zijn negatieve energie weg.', body_pl = 'Jeśli wieczór jest bardzo uparty i nerwowy, włóż go do ciepłej wody. Zwykła zabawa wodą w wannie i terapeutyczna moc wody zmyją całą negatywną energię.', body_pt = 'Se a noite estiver muito teimosa e nervosa, ponha-o em água morna. Só de brincar com a água na banheira, o poder terapêutico da água vai levar toda a energia negativa.', body_sv = 'Om det är en väldigt envis och irriterad kväll, sätt barnet i ljummet vatten. Att bara leka med vattnet i badet och vattnets terapeutiska kraft sköljer bort all negativ energi.', body_vi = 'Nếu đó là một buổi tối bé thật bướng và cáu kỉnh, hãy cho bé vào bồn nước ấm. Chỉ cần được nghịch nước, sức mạnh trị liệu của nước sẽ cuốn trôi mọi năng lượng tiêu cực.', body_zh = '如果这是个特别倔、特别烦躁的晚上，就把宝宝放进温水里。在浴缸里单纯玩水，水的疗愈力量会把所有负面情绪都冲走。' WHERE id = '39e6032f-d2bf-40b5-98db-1f2ab3a5a379' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Canturreos 🎶', body_es = 'Mientras juega canta canciones con palabras que no se entienden. Es señal del desarrollo del habla y del oído. Añade sin falta esta nueva etapa al Seguimiento del desarrollo.', title_fr = 'Petites chansons fredonnées 🎶', body_fr = 'En jouant, il chante tout seul des chansons aux mots incompréhensibles. C''est un signe de développement du langage et de l''audition. Ajoutez absolument cette nouvelle étape au Suivi de développement.', title_hi = 'गुनगुनाते गाने 🎶', body_hi = 'खेलते समय खुद ही अनजाने शब्दों में गाने गाता है। यह बोलने और सुनने, दोनों के विकास का संकेत है। इस नए पड़ाव को ग्रोथ ट्रैकर में ज़रूर दर्ज कीजिए।', title_id = 'Senandung lagu 🎶', body_id = 'Saat bermain, ia bernyanyi sendiri dengan kata-kata yang tidak jelas. Ini tanda perkembangan bicara sekaligus pendengaran. Pastikan mencatat tahap baru ini di Pelacak Perkembangan.', title_ja = '鼻歌 🎶', body_ja = '遊びながら、ひとりでよくわからない言葉で歌っていますか？言葉と聴覚の発達のしるしです。この新しい段階をぜひ「発達トラッカー」に記録しましょう。', title_ko = '흥얼흥얼 노래 🎶', body_ko = '놀면서 알 수 없는 말로 혼자 노래를 부르나요? 말하기와 청각이 함께 자라고 있다는 신호예요. 성장 기록에 이 새로운 단계를 꼭 남겨 두세요.', title_nl = 'Liedjes neuriën 🎶', body_nl = 'Zingt hij tijdens het spelen in zichzelf liedjes met onverstaanbare woordjes? Dat is een teken van zowel spraak- als gehoorontwikkeling. Zet deze nieuwe fase zeker in de Groeitracker.', title_pl = 'Nucenie piosenek 🎶', body_pl = 'Podczas zabawy śpiewa sobie piosenki z niezrozumiałymi słowami. To znak rozwoju i mowy, i słuchu. Koniecznie zapisz ten nowy etap w Śledzeniu rozwoju.', title_pt = 'Cantarolar canções 🎶', body_pt = 'Enquanto brinca, canta sozinho canções com palavras incompreensíveis. É sinal de desenvolvimento da fala e da audição. Registe sem falta esta nova etapa no Registo de Desenvolvimento.', title_sv = 'Nynnade sånger 🎶', body_sv = 'Barnet sjunger sånger med obegripliga ord för sig själv medan hen leker. Det är ett tecken på både tal- och hörselutveckling. Lägg absolut till det nya steget i Utvecklingsspåraren.', title_vi = 'Ngân nga giai điệu 🎶', body_vi = 'Khi chơi, bé tự hát những bài hát với những từ khó hiểu. Đây là dấu hiệu phát triển của cả khả năng nói và thính giác. Nhất định hãy ghi giai đoạn mới này vào Theo dõi phát triển.', title_zh = '哼歌时间 🎶', body_zh = '玩的时候，自己用听不懂的词唱着歌。这是语言和听觉发展的标志。一定要把这个新阶段记进发育追踪里。' WHERE id = '2c4fbb59-42cd-4340-ba93-aee620d9df26' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche creemos un ambiente distinto en la habitación. Deja la lectura del cuento a la voz grave y tranquilizadora de papá y disfruta tú a un lado del silencio absoluto.', body_fr = 'Ce soir, créons une ambiance différente dans la chambre. Confiez la lecture à la voix grave et rassurante de papa et, de votre côté, savourez un silence absolu.', body_hi = 'आज शाम कमरे में कुछ अलग माहौल बनाइए। किताब पढ़ने का काम पापा की भारी, भरोसा देने वाली आवाज़ को सौंपिए और आप एक तरफ़ पूरी खामोशी का आनंद लीजिए।', body_id = 'Malam ini mari ciptakan suasana berbeda di kamar. Serahkan tugas membacakan buku pada suara Ayah yang berat dan menenangkan, sementara Anda menikmati keheningan total di sudut lain.', body_ja = '今夜は部屋に違う雰囲気をつくりましょう。絵本を読む役目はパパの低くて安心できる声にお任せして、あなたは少し離れて完全な静けさを味わって。', body_ko = '오늘 밤엔 방에 색다른 분위기를 만들어 봐요. 책 읽어 주기는 아빠의 굵고 든든한 목소리에 맡기고, 엄마는 한쪽에서 완벽한 고요를 즐기세요.', body_nl = 'Laten we vanavond een andere sfeer in de kamer maken. Geef het voorlezen aan de diepe, geruststellende stem van papa en geniet jij aan de zijkant van de totale stilte.', body_pl = 'Stwórzmy dziś wieczorem w pokoju inny klimat. Powierz czytanie książki głębokiemu, dającemu poczucie bezpieczeństwa głosowi taty, a ty z boku delektuj się absolutną ciszą.', body_pt = 'Esta noite, vamos criar um ambiente diferente no quarto. Entregue a leitura à voz grave e tranquilizadora do pai e saboreie, à parte, o silêncio absoluto.', body_sv = 'Låt oss skapa en annan stämning i rummet i kväll. Lämna över bokläsningen till pappas djupa, trygga röst och njut av total tystnad en bit bort.', body_vi = 'Tối nay hãy tạo một bầu không khí khác trong phòng. Giao việc đọc sách cho giọng trầm ấm, đáng tin cậy của bố, còn mẹ ngồi một góc tận hưởng sự yên lặng tuyệt đối.', body_zh = '今晚给房间换一种氛围吧。把读书的任务交给爸爸那低沉、让人安心的声音，你在一旁享受绝对的安静。' WHERE id = '491d12b8-51d5-4984-8dda-d40fbb4e95c8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Grupo de apoyo de madres 💬', body_es = '¿Tienes que tomar una decisión difícil? (guardería, orinal, sueño). Los consejos de las madres con experiencia de la Comunidad Anacan son las soluciones más reales, que no vienen en ningún libro.', title_fr = 'Le groupe de soutien des mamans 💬', body_fr = 'Vous devez prendre une décision difficile (crèche, pot, sommeil) ? Les conseils des mamans expérimentées de la Communauté Anacan sont les solutions les plus concrètes, introuvables dans les livres.', title_hi = 'माँओं का सपोर्ट ग्रुप 💬', body_hi = 'कोई मुश्किल फ़ैसला लेना है? (प्लेस्कूल, पॉटी, नींद)। Anacan कम्युनिटी में अनुभवी माँओं की सलाह वे असली समाधान हैं जो किसी किताब में नहीं लिखे।', title_id = 'Grup dukungan para ibu 💬', body_id = 'Harus mengambil keputusan sulit? (TK, pispot, tidur). Saran ibu-ibu berpengalaman di Komunitas Anacan adalah solusi paling nyata yang tidak tertulis di buku mana pun.', title_ja = 'ママたちのサポートグループ 💬', body_ja = 'むずかしい決断をしなければなりませんか？（保育園、おまる、睡眠）。Anacanコミュニティの経験豊富なママたちのアドバイスは、どの本にも書かれていないいちばん現実的な解決策です。', title_ko = '엄마들의 응원 모임 💬', body_ko = '어린이집, 배변 훈련, 수면처럼 어려운 결정을 해야 하나요? Anacan 커뮤니티의 경험 많은 엄마들의 조언은 어떤 책에도 없는 가장 현실적인 해결책이에요.', title_nl = 'Steungroep voor moeders 💬', body_nl = 'Moet je een moeilijke beslissing nemen? (Opvang, potje, slaap). Het advies van ervaren moeders in de Anacan Community zijn de meest realistische oplossingen, die in geen enkel boek staan.', title_pl = 'Grupa wsparcia mam 💬', body_pl = 'Musisz podjąć trudną decyzję? (Żłobek, nocnik, sen). Rady doświadczonych mam ze Społeczności Anacan to najbardziej realne rozwiązania, których nie znajdziesz w żadnej książce.', title_pt = 'Grupo de apoio das mães 💬', body_pt = 'Tem de tomar uma decisão difícil? (Creche, bacio, sono.) Os conselhos das mães experientes da Comunidade Anacan são as soluções mais reais, que não vêm em nenhum livro.', title_sv = 'Mammornas stödgrupp 💬', body_sv = 'Behöver du fatta ett svårt beslut? (Förskola, potta, sömn.) Råden från erfarna mammor i Anacan Community är de mest verklighetsnära lösningarna som inte står i någon bok.', title_vi = 'Nhóm hỗ trợ của các mẹ 💬', body_vi = 'Mẹ cần đưa ra một quyết định khó? (Nhà trẻ, ngồi bô, giấc ngủ). Lời khuyên từ các mẹ giàu kinh nghiệm trong Cộng đồng Anacan là những giải pháp thực tế nhất mà không cuốn sách nào viết.', title_zh = '妈妈互助小组 💬', body_zh = '要做一个艰难的决定？（幼儿园、便盆、睡觉）Anacan社区里有经验的妈妈们的建议，是任何书里都没写过的最实在的办法。' WHERE id = 'c32299af-eeac-42f3-ab67-01688b0d4551' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que la casa siga desordenada 🌪️', body_es = '¿Cansada de guardar cada noche los mismos juguetes en la caja? ¡Hoy no recojas! Tu casa no es un museo, es un lugar lleno de vida donde crece un pequeño explorador.', title_fr = 'Laissez le désordre 🌪️', body_fr = 'Fatiguée de ranger chaque soir les mêmes jouets dans le coffre ? Aujourd''hui, ne rangez pas ! Une maison n''est pas un musée, c''est un lieu plein de vie où grandit un petit explorateur.', title_hi = 'घर बिखरा रहने दीजिए 🌪️', body_hi = 'हर शाम वही खिलौने डिब्बे में भरते-भरते थक गईं? आज मत समेटिए! घर कोई म्यूज़ियम नहीं, बल्कि ज़िंदगी से भरी वह जगह है जहाँ एक नन्हा खोजी बड़ा हो रहा है।', title_id = 'Biarkan rumah berantakan 🌪️', body_id = 'Lelah memasukkan mainan yang sama ke kotak setiap malam? Hari ini jangan dibereskan! Rumah bukan museum, tetapi tempat penuh kehidupan di mana seorang penjelajah kecil tumbuh.', title_ja = '家は散らかったままでいい 🌪️', body_ja = '毎晩同じおもちゃを箱にしまうのに疲れましたか？今日は片づけなくていい！家は博物館ではなく、命があふれ、小さな探検家が育つ場所です。', title_ko = '집은 어질러져도 괜찮아요 🌪️', body_ko = '매일 저녁 같은 장난감을 상자에 담느라 지쳤나요? 오늘은 치우지 마세요! 집은 박물관이 아니라 꼬마 탐험가가 자라는 생기 넘치는 공간이에요.', title_nl = 'Laat het huis maar rommelig 🌪️', body_nl = 'Ben je het zat om elke avond hetzelfde speelgoed in de bak te doen? Ruim vandaag niet op! Je huis is geen museum, maar een plek vol leven waar een kleine ontdekkingsreiziger opgroeit.', title_pl = 'Niech w domu będzie bałagan 🌪️', body_pl = 'Masz dość wkładania co wieczór tych samych zabawek do pudła? Dziś ich nie sprzątaj! Dom to nie muzeum, tylko miejsce pełne życia, w którym rośnie mały odkrywca.', title_pt = 'Deixe a casa desarrumada 🌪️', body_pt = 'Cansada de arrumar todas as noites os mesmos brinquedos na caixa? Hoje não arrume! A casa não é um museu, é um lugar cheio de vida onde cresce um pequeno explorador.', title_sv = 'Låt hemmet vara stökigt 🌪️', body_sv = 'Är du trött på att plocka in samma leksaker i lådan varje kväll? Låt bli i dag! Hemmet är inget museum, det är en plats full av liv där en liten upptäcktsresande växer upp.', title_vi = 'Cứ để nhà bừa 🌪️', body_vi = 'Mẹ mệt vì tối nào cũng xếp lại những món đồ chơi giống nhau vào thùng? Hôm nay đừng dọn! Nhà không phải là bảo tàng, mà là nơi tràn đầy sức sống, nơi một nhà thám hiểm nhỏ đang lớn lên.', title_zh = '家里乱就乱吧 🌪️', body_zh = '每晚把同样的玩具收进箱子，收累了？今天就别收了！家不是博物馆，而是充满生活气息、一个小探险家在其中长大的地方。' WHERE id = '1c02ca47-65ab-4daa-8468-3f801795414a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lanzar y atrapar ⚾', body_es = 'Ya no solo deja escapar la pelota grande que le lanzas: intenta atraparla. Su coordinación ojo-mano avanza a pasos agigantados. Organizad pequeños juegos de pelota en el pasillo.', title_fr = 'Lancer et attraper ⚾', body_fr = 'Il ne laisse plus simplement passer le gros ballon que vous lui lancez, il essaie de l''attraper. Sa coordination œil-main progresse vite. Organisez de petits jeux de balle à deux dans le couloir.', title_hi = 'निशाना लगाकर फेंकना और पकड़ना ⚾', body_hi = 'आप जो बड़ी बॉल उसकी ओर फेंकती हैं, अब वह उसे सिर्फ़ जाने नहीं देता, पकड़ने की कोशिश करता है। आँख और हाथ का तालमेल तेज़ी से बढ़ रहा है। गलियारे में साथ मिलकर छोटे-छोटे खेल खेलिए।', title_id = 'Melempar dan menangkap ⚾', body_id = 'Bola besar yang Anda lempar kini tidak hanya ia lewatkan, ia mencoba menangkapnya. Koordinasi mata dan tangannya berkembang pesat. Buat permainan olahraga kecil bersama di lorong rumah.', title_ja = 'ねらって投げる、キャッチする ⚾', body_ja = '投げた大きなボールを、ただ見送るのではなく、キャッチしようとします。目と手の協調がぐんと育っています。廊下で一緒に小さなスポーツ遊びをしましょう。', title_ko = '겨냥해서 던지고 받기 ⚾', body_ko = '던져 준 큰 공을 이제 그냥 놓치지 않고 잡으려 하나요? 눈과 손의 협응력이 빠르게 자라고 있어요. 복도에서 주고받는 작은 운동 놀이를 해 보세요.', title_nl = 'Gericht gooien en vangen ⚾', body_nl = 'Hij laat de grote bal die je gooit niet meer zomaar voorbijgaan, hij probeert hem te vangen. Zijn oog-handcoördinatie ontwikkelt zich snel. Doe in de gang kleine balspelletjes samen.', title_pl = 'Celne rzuty i łapanie ⚾', body_pl = 'Już nie tylko przepuszcza dużą piłkę, którą mu rzucasz, ale próbuje ją złapać. Koordynacja oko-ręka gwałtownie się rozwija. Urządźcie w korytarzu małe wspólne zabawy sportowe.', title_pt = 'Lançar e apanhar ⚾', body_pt = 'Já não deixa só fugir a bola grande que lhe atira, tenta apanhá-la. A coordenação olho-mão está a desenvolver-se muito. Organize pequenos jogos desportivos a dois no corredor.', title_sv = 'Kast med sikte och fångst ⚾', body_sv = 'Barnet låter inte längre bara den stora bollen du kastar rulla förbi, hen försöker fånga den. Öga-hand-koordinationen utvecklas snabbt. Ordna små bollekar tillsammans i hallen.', title_vi = 'Ném có chủ đích và bắt bóng ⚾', body_vi = 'Bé không còn để tuột quả bóng lớn mẹ ném mà đã cố bắt lấy. Khả năng phối hợp tay và mắt đang phát triển mạnh. Hãy cùng bé chơi những trò thể thao nho nhỏ ở hành lang.', title_zh = '有目标地投和接 ⚾', body_zh = '你扔过去的大球，宝宝已经不只是追，而是想接住了。手眼协调正在飞速发展。在走廊里一起玩些互相传接的小运动游戏吧。' WHERE id = '890c1216-15b7-4852-b1cb-42e4a141e897' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Apaga del todo las luces de la habitación. En Cuentos inteligentes crea un fondo relajante sin palabras, solo con sonidos de la naturaleza (viento, bosque), y acelera el paso al sueño.', body_fr = 'Éteignez toutes les lumières de la chambre. Dans les Contes intelligents, créez un fond apaisant, sans paroles, avec seulement des sons de la nature (vent, forêt) pour l''aider à s''endormir plus vite.', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। स्मार्ट कहानियों में पीछे सिर्फ़ प्रकृति की आवाज़ों (हवा, जंगल) वाला, बिना शब्दों का शांत माहौल बनाइए और जल्दी नींद लाइए।', body_id = 'Matikan semua lampu kamar. Di Dongeng Pintar, ciptakan latar tanpa kata yang menenangkan dengan hanya suara alam (angin, hutan) untuk mempercepat ia tertidur.', body_ja = '部屋の明かりをすべて消しましょう。「スマートおはなし」で、自然の音（風、森）だけが流れる言葉のない落ち着いた音をつくって、眠りへの切りかえを早めましょう。', body_ko = '방의 불을 모두 꺼 주세요. 스마트 동화에서 바람, 숲 같은 자연의 소리만 흐르는 말 없는 차분한 배경을 만들어 더 빨리 잠들도록 도와주세요.', body_nl = 'Doe alle lichten in de kamer uit. Maak in Slimme sprookjes een rustgevende achtergrond zonder woorden, met alleen natuurgeluiden (wind, bos), zodat hij sneller in slaap valt.', body_pl = 'Zgaś całkowicie światła w pokoju. W Mądrych bajkach stwórz bezsłowne, kojące tło z samymi odgłosami natury (wiatr, las) i przyspiesz zasypianie.', body_pt = 'Apague por completo as luzes do quarto. Nas Histórias Inteligentes, crie um fundo calmante e sem palavras, só com sons da natureza (vento, floresta), e acelere a passagem para o sono.', body_sv = 'Släck alla lampor i rummet. Skapa en ordlös, lugnande bakgrund med bara naturljud (vind, skog) i Smarta sagor och gör övergången till sömn snabbare.', body_vi = 'Hãy tắt hết đèn trong phòng. Trong Truyện cổ tích thông minh, hãy tạo nền âm thanh êm dịu không lời chỉ có tiếng thiên nhiên (gió, rừng) để bé vào giấc nhanh hơn.', body_zh = '把房间的灯全部关掉。在智能故事里营造一个只有大自然声音（风声、森林）的无声舒缓背景，让宝宝更快进入梦乡。' WHERE id = 'a764d770-048d-4a17-b477-fc4f761c3c2d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Come dos cucharadas, dice que está lleno y se va corriendo? No le obligues. Crear una relación sana con la comida es más importante que dejar el plato vacío.', body_fr = 'Deux cuillères, il dit qu''il n''a plus faim et s''en va ? Ne le forcez pas. Construire une relation saine avec la nourriture compte plus que finir son assiette.', body_hi = 'दो चम्मच खाकर ''पेट भर गया'' कहकर भाग जाता है? ज़बरदस्ती मत कीजिए। खाने के साथ स्वस्थ रिश्ता बनाना थाली खत्म करने से ज़्यादा ज़रूरी है।', body_id = 'Baru dua sendok sudah bilang kenyang lalu kabur? Jangan memaksanya. Membangun hubungan sehat dengan makanan lebih penting daripada menghabiskan isi piring.', body_ja = 'ふた口食べて「おなかいっぱい」と言って逃げていきますか？無理に食べさせないで。食べ物とよい関係を築くことは、お皿を空にすることより大切です。', body_ko = '두 숟가락 먹고 배부르다며 도망가나요? 억지로 먹이지 마세요. 음식과 건강한 관계를 만드는 게 접시를 비우는 것보다 더 중요해요.', body_nl = 'Zegt hij na twee hapjes al dat hij vol zit en rent hij weg? Dwing hem niet. Een gezonde relatie met eten is belangrijker dan een leeg bord.', body_pl = 'Po dwóch łyżkach mówi, że jest najedzony, i ucieka? Nie zmuszaj go. Zdrowa relacja z jedzeniem jest ważniejsza niż pusty talerz.', body_pt = 'Come duas colheres, diz que está cheio e foge? Não o force. Criar uma relação saudável com a comida é mais importante do que limpar o prato.', body_sv = 'Äter barnet två skedar, säger att det är mätt och springer iväg? Tvinga inte. Att bygga en sund relation till mat är viktigare än att äta upp allt på tallriken.', body_vi = 'Bé ăn hai thìa đã bảo no rồi chạy đi? Đừng ép bé. Xây dựng mối quan hệ lành mạnh với thức ăn quan trọng hơn việc ăn hết đĩa.', body_zh = '吃了两勺就说“饱了”，然后跑开？别勉强。和食物建立健康的关系，比吃光盘子重要得多。' WHERE id = '0f2d9f90-69e8-4777-adab-24eab59b69a5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mientras juega tan a gusto en la habitación, abre ya la Sesión de fotos del bebé y graba para el futuro, sin ningún filtro, esa carita nueva y más mayor y esos ojos brillantes.', body_fr = 'Pendant qu''il joue tranquillement dans la chambre, ouvrez vite la Séance photo bébé et gravez pour l''avenir, sans aucun filtre, ce visage qui a changé et grandi, et ces yeux brillants.', body_hi = 'जब वह कमरे में मज़े से खेल रहा हो, तुरंत बेबी फ़ोटोशूट खोलिए और उसके इस बदले हुए, बड़े होते चेहरे और चमकती आँखों को बिना किसी फ़िल्टर के आगे के लिए यादों में सहेज लीजिए।', body_id = 'Saat ia asyik bermain di kamar, segera buka Pemotretan Bayi dan abadikan wajahnya yang kian besar dan berbeda serta mata berbinarnya tanpa filter untuk masa depan.', body_ja = '部屋でかわいく遊んでいるときに、すぐに「ベビーフォトセッション」を開いて、この大きくなった表情とキラキラした目を、フィルターなしで未来のために残しましょう。', body_ko = '방에서 사랑스럽게 놀고 있을 때 바로 아기 사진 촬영을 열어 보세요. 달라지고 훌쩍 자란 얼굴과 반짝이는 눈을 필터 없이 그대로 담아 두세요.', body_nl = 'Speelt hij lief in de kamer? Open meteen Babyfotoshoot en leg dit andere, grotere gezichtje en die stralende oogjes zonder filter vast voor later.', body_pl = 'Gdy słodko bawi się w pokoju, od razu otwórz Sesję zdjęciową dziecka i uwiecznij na przyszłość tę inną, dojrzalszą buzię i błyszczące oczy, bez żadnego filtra.', body_pt = 'Enquanto brinca docemente no quarto, abra já a Sessão Fotográfica e guarde para o futuro, sem filtros, este rosto diferente e crescido e aqueles olhos brilhantes.', body_sv = 'När barnet leker gott i rummet, öppna genast Babyfotografering och föreviga det nya, större ansiktet och de lysande ögonen utan filter för framtiden.', body_vi = 'Khi bé đang chơi ngoan trong phòng, hãy mở ngay Chụp ảnh cho bé và lưu giữ gương mặt đã lớn khác hẳn, đôi mắt sáng ngời ấy mà không cần bộ lọc nào để làm kỷ niệm.', body_zh = '宝宝在房间里玩得正开心时，马上打开宝宝写真，不加任何滤镜，把这张不一样的、长大了的小脸和那双明亮的眼睛留作永远的回忆吧。' WHERE id = '1b92930f-874b-4bdc-b9d4-44b2ec744469' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Otra vez ansiedad por separación? 🥺', body_es = '¿Hasta cuando vas al baño te espera llorando detrás de la puerta? La ansiedad por separación a veces vuelve. Háblale cada vez, incluso desde otra habitación, para que sepa que estás ahí y que vas a volver.', title_fr = 'Encore l''angoisse de séparation ? 🥺', body_fr = 'Même quand vous allez aux toilettes, il pleure derrière la porte en vous attendant. L''angoisse de séparation revient parfois. À chaque fois, même depuis une autre pièce, dites-lui que vous êtes là et que vous revenez.', title_hi = 'फिर से बिछड़ने की चिंता? 🥺', body_hi = 'आप टॉयलेट भी जाएँ तो दरवाज़े के पीछे इंतज़ार करते हुए रोता है? अलगाव की चिंता कभी-कभी लौट आती है। हर बार दूसरे कमरे से भी आवाज़ देकर बताइए कि आप यहीं हैं और लौट आएँगी।', title_id = 'Cemas berpisah lagi? 🥺', body_id = 'Bahkan saat Anda ke toilet, ia menunggu di balik pintu sambil menangis. Kecemasan berpisah kadang kembali. Setiap kali, bersuaralah bahkan dari ruangan lain dan katakan bahwa Anda ada di sini dan akan kembali.', title_ja = 'また分離不安？🥺', body_ja = 'トイレに行くときでさえ、ドアの向こうで待って泣いていますか？分離不安はときどきぶり返します。そのたびに、別の部屋からでも声をかけて、ここにいること、戻ってくることを伝えましょう。', title_ko = '분리 불안이 다시? 🥺', body_ko = '화장실에 갈 때도 문 앞에서 기다리며 우나요? 분리 불안은 가끔 다시 찾아와요. 다른 방에서라도 그때마다 목소리로 여기 있고 꼭 돌아온다고 말해 주세요.', title_nl = 'Weer verlatingsangst? 🥺', body_nl = 'Zelfs als je naar de wc gaat, wacht hij huilend achter de deur. Verlatingsangst komt soms terug. Laat steeds je stem horen, zelfs vanuit een andere kamer, en zeg dat je er bent en terugkomt.', title_pl = 'Znowu lęk separacyjny? 🥺', body_pl = 'Nawet gdy idziesz do toalety, czeka pod drzwiami i płacze? Lęk separacyjny czasem wraca. Za każdym razem odezwij się, nawet z innego pokoju, i powiedz, że jesteś tu i wrócisz.', title_pt = 'Ansiedade de separação outra vez? 🥺', body_pt = 'Até quando vai à casa de banho, espera por si atrás da porta a chorar? A ansiedade de separação às vezes volta. Fale sempre com ele, mesmo de outra divisão, e diga-lhe que está ali e que vai voltar.', title_sv = 'Separationsångest igen? 🥺', body_sv = 'Barnet väntar bakom dörren och gråter till och med när du går på toaletten. Separationsångesten kommer ibland tillbaka. Ropa varje gång, även från ett annat rum, och säg att du är här och att du kommer tillbaka.', title_vi = 'Lại lo âu chia ly? 🥺', body_vi = 'Ngay cả khi mẹ vào nhà vệ sinh, bé cũng đứng sau cửa chờ và khóc. Lo âu chia ly đôi khi quay trở lại. Mỗi lần như vậy, kể cả từ phòng khác, hãy lên tiếng để bé biết mẹ ở đây và sẽ quay lại.', title_zh = '分离焦虑又来了？🥺', body_zh = '连你去洗手间，宝宝都在门外等着哭？分离焦虑有时会卷土重来。每次都出声告诉宝宝你就在这里，你会回来的，就算在别的房间也说出来。' WHERE id = '1beec453-866b-4504-9a19-59d21f2305e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hay que soltar energía 🌳', body_es = 'Las cuatro paredes le ponen agresivo. Siéntale en el carrito o cógele de la mano y salid a tomar aire fresco. La paz de la naturaleza os sentará genial a tu peque y a tu ánimo.', title_fr = 'Il faut se défouler 🌳', body_fr = 'Les quatre murs le rendent agressif. Installez-le dans sa poussette ou prenez-le par la main et sortez prendre l''air. Le calme de la nature fera du bien à votre enfant comme à votre moral.', title_hi = 'ऊर्जा निकालना ज़रूरी है 🌳', body_hi = 'चार दीवारें उसे चिड़चिड़ा बना रही हैं। उसे स्ट्रोलर में बिठाइए या हाथ पकड़िए और ताज़ी हवा में निकलिए। प्रकृति का सुकून बच्चे पर भी और आपके मन पर भी अच्छा असर डालेगा।', title_id = 'Energi harus disalurkan 🌳', body_id = 'Empat dinding rumah membuatnya agresif. Dudukkan ia di kereta dorong atau gandeng tangannya dan keluarlah menghirup udara segar. Ketenangan alam akan berdampak baik bagi si kecil dan juga bagi batin Anda.', title_ja = 'エネルギーの発散が必要 🌳', body_ja = '家にこもっているとイライラが強くなりますか？ベビーカーに乗せるか手をつないで、新鮮な空気の中へ出かけましょう。自然の安らぎは、お子さんにもあなたの心にもとてもよい効果があります。', title_ko = '에너지 발산은 필수예요 🌳', body_ko = '네 벽 안에서 아이가 예민해지나요? 유모차에 태우거나 손을 잡고 맑은 공기를 마시러 나가세요. 자연의 평온함은 아이에게도 엄마의 마음에도 좋은 영향을 줄 거예요.', title_nl = 'Energie kwijt is een must 🌳', body_nl = 'De vier muren maken hem agressief. Zet hem in de buggy of neem hem bij de hand en ga naar buiten. De rust van de natuur doet je kindje en jouw gemoed heel goed.', title_pl = 'Trzeba spalić energię 🌳', body_pl = 'Cztery ściany sprawiają, że staje się agresywny. Posadź go w wózku albo weź za rękę i wyjdźcie na świeże powietrze. Spokój natury świetnie wpłynie i na malucha, i na twoją psychikę.', title_pt = 'Gastar energia é obrigatório 🌳', body_pt = 'As quatro paredes deixam-no agressivo. Ponha-o no carrinho ou dê-lhe a mão e saiam para o ar livre. A paz da natureza vai fazer muito bem ao bebé e ao seu estado de espírito.', title_sv = 'Energin måste ut 🌳', body_sv = 'De fyra väggarna gör barnet aggressivt. Sätt hen i vagnen eller ta hen i handen och gå ut i friska luften. Naturens lugn gör gott både för barnet och för ditt psyke.', title_vi = 'Cần xả năng lượng 🌳', body_vi = 'Bốn bức tường khiến bé trở nên hung hăng. Hãy cho bé vào xe đẩy hoặc nắm tay bé ra ngoài hít thở không khí trong lành. Sự bình yên của thiên nhiên sẽ tốt cho cả bé và tâm lý của mẹ.', title_zh = '一定要释放精力 🌳', body_zh = '四面墙让宝宝变得烦躁。把宝宝放进推车或牵着小手，出门呼吸新鲜空气。大自然的宁静，对宝宝和你的心情都有很好的作用。' WHERE id = '01e5d997-771c-4149-81ec-cf5e1b89ede9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las luces extra de la habitación y las pantallas de las tablets. La melatonina solo se produce rápido en un ambiente tranquilo y oscuro.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles de la chambre et les écrans de tablette. La mélatonine n''est sécrétée rapidement que dans le calme et le noir.', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ शांत और अंधेरे माहौल में तेज़ी से बनता है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar. Melatonin diproduksi dengan cepat hanya dalam suasana tenang dan gelap.', body_ja = '早く寝つけるように、部屋の余分な明かりとタブレットの画面をすべて消しましょう。メラトニンは静かで暗い環境でこそすばやく分泌されます。', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명과 태블릿 화면을 모두 꺼 주세요. 멜라토닌은 조용하고 어두운 환경에서만 빠르게 분비돼요.', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en tabletschermen in de kamer uit. Melatonine wordt alleen in een rustige, donkere omgeving snel aangemaakt.', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina wydziela się szybko tylko w spokojnym i ciemnym otoczeniu.', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets. A melatonina só é produzida rapidamente num ambiente calmo e escuro.', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplattornas skärmar i rummet. Melatonin utsöndras snabbt bara i en lugn och mörk miljö.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng. Melatonin chỉ được tiết ra nhanh trong môi trường yên tĩnh và tối.', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光和平板屏幕。褪黑素只有在安静、黑暗的环境里才会快速分泌。' WHERE id = '149c401f-2cba-4bc8-b3fb-54e3507ca6f5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lluvia de «¿Qué es esto?» ☝️', body_es = '¿Lo señala todo con el dedo y pregunta cómo se llama? Quiere que le pongas nombre al mundo. ¡Es un gran salto en la comunicación! Repite con paciencia el nombre de cada cosa que señale.', title_fr = 'L''avalanche de « C''est quoi ? » ☝️', body_fr = 'Il montre tout du doigt en demandant le nom ? Il veut que vous lui nommiez le monde. C''est un grand bond dans la communication ! Répétez patiemment le nom de chaque objet qu''il montre.', title_hi = '''यह क्या है?'' की झड़ी ☝️', body_hi = 'हर चीज़ की ओर उँगली दिखाकर उसका नाम पूछता है? वह चाहता है कि आप उसे दुनिया के नाम बताएँ। बातचीत में यह बड़ी छलांग है! वह जो भी चीज़ दिखाए, उसका नाम धैर्य से दोहराइए।', title_id = 'Banjir pertanyaan ''Ini apa?'' ☝️', body_id = 'Ia menunjuk segala hal dengan jarinya dan menanyakan namanya? Ia ingin Anda menamai dunia untuknya. Lompatan besar dalam komunikasi! Ulangi dengan sabar nama setiap benda yang ia tunjuk.', title_ja = '「これなあに？」のあらし ☝️', body_ja = 'なんでも指さして名前を聞きますか？世界に名前をつけてほしいのです。コミュニケーションの大きな飛躍です！指さしたものの名前を、根気よくくり返してあげましょう。', title_ko = '''이게 뭐야?'' 질문 폭탄 ☝️', body_ko = '손가락으로 모든 걸 가리키며 이름을 묻나요? 엄마가 세상에 이름을 붙여 주길 바라는 거예요. 소통의 큰 도약이에요! 가리키는 물건의 이름을 인내심 있게 반복해 주세요.', title_nl = 'Een stroom van ''Wat is dat?'' ☝️', body_nl = 'Wijst hij alles aan en vraagt hij hoe het heet? Hij wil dat jij de wereld voor hem benoemt. Een grote sprong in communicatie! Herhaal geduldig de naam van alles wat hij aanwijst.', title_pl = 'Lawina pytań „Co to?” ☝️', body_pl = 'Pokazuje wszystko paluszkiem i pyta o nazwę? Chce, żebyś nazywała mu świat. To wielki skok w komunikacji! Cierpliwie powtarzaj nazwę każdej rzeczy, którą pokazuje.', title_pt = 'A avalanche de "O que é isto?" ☝️', body_pt = 'Aponta tudo com o dedo e pergunta o nome? Quer que dê nome ao mundo por ele. É um grande salto na comunicação! Repita com paciência o nome de cada objeto que aponta.', title_sv = 'En flod av ”Vad är det?” ☝️', body_sv = 'Pekar barnet på allt och frågar vad det heter? Hen vill att du ska sätta namn på världen. Ett stort kommunikativt språng! Upprepa tålmodigt namnet på varje sak hen pekar på.', title_vi = 'Cơn mưa "Cái gì đây?" ☝️', body_vi = 'Bé chỉ tay vào mọi thứ và hỏi tên? Bé muốn mẹ gọi tên thế giới cho bé. Đây là bước nhảy vọt lớn trong giao tiếp! Hãy kiên nhẫn nhắc lại tên của mọi đồ vật bé chỉ.', title_zh = '“这是什么？”问个不停 ☝️', body_zh = '什么东西都用手指着问名字？宝宝想让你给世界命名。这是交流上的一大飞跃！耐心地重复宝宝指着的每样东西的名字。' WHERE id = '1d84618d-c436-422f-bb3e-95d3ae0487d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Orgullo de equipo 🥂', body_es = 'Habéis superado un día difícil. Cuando tu peque se duerma, tomaos un té con tu pareja y motivaos diciendo: «De verdad lo estamos haciendo genial».', title_fr = 'Fierté d''équipe 🥂', body_fr = 'Vous avez laissé derrière vous une journée difficile. Une fois l''enfant couché, servez-vous un thé avec votre partenaire et motivez-vous : « On s''en sort vraiment très bien. »', title_hi = 'टीम का गर्व 🥂', body_hi = 'एक मुश्किल दिन पीछे छोड़ दिया। बच्चे के सोने के बाद अपने पार्टनर के साथ चाय पीजिए और ''हम सच में यह काम बहुत अच्छे से संभाल रहे हैं'' कहकर एक-दूसरे का हौसला बढ़ाइए।', title_id = 'Bangga sebagai tim 🥂', body_id = 'Satu hari berat sudah terlewati. Setelah anak tidur, seduh teh bersama pasangan dan saling menyemangati dengan berkata ''Kita benar-benar hebat menjalani ini''.', title_ja = 'チームの誇り 🥂', body_ja = '大変な一日を乗りこえました。お子さんが眠ったら、パートナーとお茶をいれて「わたしたち、本当によくやってるね」とお互いを励まし合いましょう。', title_ko = '팀의 자부심 🥂', body_ko = '힘든 하루를 또 이겨 냈어요. 아이가 잠들면 배우자와 차 한잔 따르며 ''우리 정말 잘하고 있어'' 하고 서로를 북돋아 주세요.', title_nl = 'Trots op jullie team 🥂', body_nl = 'Jullie hebben weer een zware dag achter de rug. Schenk als hij slaapt samen met je partner thee in en motiveer elkaar met ''We doen dit echt geweldig''.', title_pl = 'Duma drużyny 🥂', body_pl = 'Kolejny trudny dzień za wami. Gdy dziecko zaśnie, nalejcie sobie z partnerem herbaty i zmotywujcie się nawzajem słowami: „Naprawdę świetnie sobie z tym radzimy”.', title_pt = 'Orgulho de equipa 🥂', body_pt = 'Deixaram para trás um dia difícil. Depois de a criança adormecer, sirvam-se de um chá e motivem-se um ao outro: "Estamos mesmo a sair-nos lindamente nisto."', title_sv = 'Stolthet som team 🥂', body_sv = 'Ni har en tuff dag bakom er. När barnet har somnat, häll upp te med din partner och peppa varandra med ”vi klarar verkligen det här jättebra”.', title_vi = 'Niềm tự hào của đội 🥂', body_vi = 'Hai người đã vượt qua một ngày khó khăn. Khi bé ngủ, hãy cùng chồng pha một tách trà và động viên nhau: "Chúng mình thật sự làm rất tốt".', title_zh = '团队的骄傲 🥂', body_zh = '你们又熬过了艰难的一天。孩子睡着后，和另一半倒杯茶，说一句“我们真的把这件事做得很好”，互相打打气吧。' WHERE id = '1c8d40ed-ce45-4ab5-a646-af121febdc6b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El tiempo cambia ⛅', body_es = 'Al salir de paseo, no te fíes del tiempo y evita que se enfríe. No decidas solo mirando por la ventana: elige con Tiempo y ropa el conjunto más adecuado para el tiempo que hace fuera.', title_fr = 'Le temps est changeant ⛅', body_fr = 'Ne vous laissez pas tromper par le temps et ne le laissez pas prendre froid en promenade. Ne décidez pas en regardant par la fenêtre : avec Météo et tenue, choisissez la tenue la mieux adaptée au temps dehors.', title_hi = 'मौसम बदलता रहता है ⛅', body_hi = 'सैर पर जाते समय मौसम के धोखे में आकर उसे ठंड मत लगने दीजिए। सिर्फ़ खिड़की से देखकर फ़ैसला मत कीजिए, मौसम और कपड़े असिस्टेंट से बाहर के माहौल के लिए सबसे सही कपड़े चुनिए।', title_id = 'Cuaca tak menentu ⛅', body_id = 'Saat jalan-jalan, jangan tertipu cuaca hingga ia kedinginan. Jangan memutuskan hanya dengan melihat dari jendela, tentukan setelan yang paling pas untuk kondisi di luar dengan alat Cuaca dan Pakaian.', title_ja = '天気は変わりやすい ⛅', body_ja = 'お散歩のとき、見た目の天気にだまされて体を冷やさないように。窓から見て決めずに、「天気と服装」で外の様子にいちばん合うコーディネートを決めましょう。', title_ko = '날씨가 변덕스러워요 ⛅', body_ko = '산책할 때 날씨에 속아 아이를 춥게 하지 마세요. 창밖만 보고 정하지 말고 날씨와 옷차림 도우미로 바깥 날씨에 가장 알맞은 옷차림을 정하세요.', title_nl = 'Het weer is wisselvallig ⛅', body_nl = 'Laat je niet misleiden door het weer als je gaat wandelen, zodat hij het niet koud krijgt. Beslis niet door uit het raam te kijken, maar kies met Weer en kleding de outfit die het best past bij het weer buiten.', title_pl = 'Pogoda jest zmienna ⛅', body_pl = 'Wychodząc na spacer, nie daj się zwieść pogodzie, żeby go nie przeziębić. Nie decyduj, patrząc przez okno, tylko dobierz w narzędziu Pogoda i ubiór zestaw najlepiej pasujący do warunków na zewnątrz.', title_pt = 'O tempo está instável ⛅', body_pt = 'Quando saírem para passear, não se deixe enganar pelo tempo e evite que ele apanhe frio. Não decida só pela janela: escolha no Tempo e Roupa a combinação mais adequada ao tempo lá fora.', title_sv = 'Vädret är ombytligt ⛅', body_sv = 'Låt dig inte luras av vädret så att barnet fryser på promenaden. Bestäm inte genom att titta ut genom fönstret, välj den klädsel som passar bäst för vädret ute med assistenten Väder och kläder.', title_vi = 'Thời tiết thất thường ⛅', body_vi = 'Khi ra ngoài đi dạo, đừng để thời tiết đánh lừa khiến bé bị lạnh. Đừng quyết định chỉ bằng cách nhìn qua cửa sổ, hãy dùng trợ lý Thời tiết và trang phục để chọn cách phối đồ phù hợp nhất với bên ngoài.', title_zh = '天气多变 ⛅', body_zh = '出门散步时，别被天气骗了，让宝宝着凉。别只看窗外做决定，用天气穿衣助手找到最适合外面环境的搭配。' WHERE id = 'b19556d6-123c-4633-b806-8552c2789139' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Saltos valientes 🧗‍♂️', body_es = 'Se lanza desde el sofá sobre los cojines. Está probando la gravedad y su valentía. En lugar de prohibírselo, crea en la habitación una zona segura para saltar.', title_fr = 'Sauts audacieux 🧗‍♂️', body_fr = 'Il se jette du canapé sur les coussins. Il teste la gravité et son courage. Au lieu d''interdire, créez dans la pièce une zone de saut sécurisée.', title_hi = 'हिम्मत भरी छलाँगें 🧗‍♂️', body_hi = 'सोफ़े से तकियों पर कूद जाता है? वह गुरुत्वाकर्षण और अपनी हिम्मत, दोनों को परख रहा है। मना करने के बजाय कमरे में कूदने के लिए एक सुरक्षित जगह बनाइए।', title_id = 'Lompatan pemberani 🧗‍♂️', body_id = 'Ia melompat dari sofa ke tumpukan bantal. Ia sedang menguji gravitasi dan keberaniannya. Daripada melarang, buat zona lompat yang aman di kamar.', title_ja = '勇気あるジャンプ 🧗‍♂️', body_ja = 'ソファからクッションの上へ飛びこみますか？重力と自分の勇気を試しています。禁止するかわりに、部屋に安全なジャンプゾーンをつくりましょう。', title_ko = '용감한 점프 🧗‍♂️', body_ko = '소파에서 쿠션 위로 몸을 던지나요? 중력과 자신의 용기를 시험하는 중이에요. 막는 대신 방에 안전한 점프 구역을 만들어 주세요.', title_nl = 'Dappere sprongen 🧗‍♂️', body_nl = 'Springt hij van de bank op de kussens? Hij test de zwaartekracht en zijn eigen moed. Verbied het niet, maar maak een veilige springzone in de kamer.', title_pl = 'Odważne skoki 🧗‍♂️', body_pl = 'Skacze z kanapy na poduszki? Sprawdza grawitację i swoją odwagę. Zamiast zabraniać, stwórz w pokoju bezpieczną strefę do skakania.', title_pt = 'Saltos corajosos 🧗‍♂️', body_pt = 'Atira-se do sofá para cima das almofadas. Está a testar a gravidade e a coragem. Em vez de proibir, crie no quarto uma zona segura para saltar.', title_sv = 'Modiga hopp 🧗‍♂️', body_sv = 'Kastar sig barnet från soffan ner på kuddarna? Hen testar tyngdkraften och sitt mod. I stället för att förbjuda, skapa en säker hoppzon i rummet.', title_vi = 'Những cú nhảy dũng cảm 🧗‍♂️', body_vi = 'Bé lao mình từ sofa xuống đống gối. Bé đang thử trọng lực và lòng can đảm. Thay vì cấm đoán, hãy tạo một khu nhảy an toàn trong phòng.', title_zh = '勇敢的跳跃 🧗‍♂️', body_zh = '从沙发上扑到靠垫上？宝宝在测试重力和自己的勇气。与其禁止，不如在房间里布置一个安全的跳跃区。' WHERE id = 'd7f16071-fb32-41c6-bf73-3b61867ff844' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con el insomnio 😭', body_es = 'Se ha despertado en mitad de la noche y no quiere dormir. No te enfades. Averigua la causa y acaríciale haciéndole sentir que estás a su lado.', title_fr = 'Faire la paix avec les nuits blanches 😭', body_fr = 'Il s''est réveillé en pleine nuit et ne veut pas se rendormir. Ne vous énervez pas. Cherchez la cause et caressez-le simplement en lui faisant sentir que vous êtes là.', title_hi = 'नींद न आने से समझौता 😭', body_hi = 'आधी रात को जाग गया और सोना नहीं चाहता? उस पर गुस्सा मत कीजिए। वजह पता कीजिए और बस यह महसूस कराते हुए सहलाइए कि आप उसके पास हैं।', title_id = 'Berdamai dengan kurang tidur 😭', body_id = 'Ia terbangun tengah malam dan tidak mau tidur lagi. Jangan kesal padanya. Pastikan penyebabnya dan usap ia sambil menunjukkan bahwa Anda ada di sisinya.', title_ja = '眠れない夜と仲直り 😭', body_ja = '真夜中に目を覚まして、眠ろうとしない？イライラしないで。原因を確かめて、そばにいることを感じさせながらやさしくなでてあげましょう。', title_ko = '잠 못 드는 밤과 화해하기 😭', body_ko = '한밤중에 깨서 다시 자려 하지 않나요? 화내지 마세요. 이유를 살펴보고 곁에 있다는 걸 느끼게 하며 부드럽게 쓰다듬어 주세요.', title_nl = 'Vrede sluiten met slapeloosheid 😭', body_nl = 'Hij is midden in de nacht wakker en wil niet slapen. Word niet boos op hem. Zoek uit wat de oorzaak is en aai hem, zodat hij voelt dat je bij hem bent.', title_pl = 'Pogodzić się z nieprzespanymi nocami 😭', body_pl = 'Obudził się w środku nocy i nie chce spać? Nie złość się na niego. Ustal przyczynę i po prostu go pogłaszcz, dając mu poczuć, że jesteś obok.', title_pt = 'Fazer as pazes com as noites sem dormir 😭', body_pt = 'Acordou a meio da noite e não quer dormir? Não se irrite com ele. Descubra a causa e faça-lhe festinhas, mostrando que está ali ao lado dele.', title_sv = 'Försonas med sömnlösheten 😭', body_sv = 'Barnet har vaknat mitt i natten och vill inte sova. Bli inte arg. Ta reda på orsaken och smek barnet så att hen känner att du är där.', title_vi = 'Làm hòa với những đêm mất ngủ 😭', body_vi = 'Bé thức dậy giữa đêm và không chịu ngủ lại. Đừng bực bé. Hãy xác định nguyên nhân và nhẹ nhàng vuốt ve để bé cảm nhận mẹ đang ở bên.', title_zh = '和失眠和解 😭', body_zh = '半夜醒来，就是不肯睡？别对宝宝发火。弄清原因，轻轻抚摸宝宝，让宝宝感觉到你就在身边。' WHERE id = '3c7fed9f-b2da-420c-b7cb-afa7c5dc9f37' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paciencia en plena crisis 🛒', body_es = 'Grita porque no le compraste el juguete que quería en el súper. No hagas caso de las miradas de los padres perfectos de alrededor. Míralo a los ojos con calma, explícaselo y mantente firme.', title_fr = 'La patience en pleine crise 🛒', body_fr = 'Il hurle parce que vous ne lui avez pas acheté le jouet qu''il voulait au supermarché. Ignorez les regards des parents « parfaits » autour. Regardez-le calmement dans les yeux, expliquez et ne cédez pas.', title_hi = 'नखरों के बीच धैर्य 🛒', body_hi = 'बाज़ार में मनचाहा खिलौना नहीं मिला तो चिल्ला रहा है? आसपास के ''परफ़ेक्ट'' माता-पिता की नज़रों की परवाह मत कीजिए। शांति से आँखों में आँखें डालकर समझाइए और अपनी बात पर टिकी रहिए।', title_id = 'Sabar saat krisis 🛒', body_id = 'Ia menjerit karena Anda tidak membelikan mainan yang ia mau di supermarket. Abaikan tatapan para orang tua ''sempurna'' di sekitar. Tatap matanya dengan tenang, jelaskan, dan tetaplah teguh.', title_ja = 'かんしゃくのときの忍耐 🛒', body_ja = 'スーパーでほしいおもちゃを買ってもらえず、大声で泣いていますか？周りの「完璧な親」たちの視線は気にしないで。落ち着いて目を合わせて説明し、態度を変えないでいましょう。', title_ko = '위기의 순간에 필요한 인내 🛒', body_ko = '마트에서 원하는 장난감을 안 사 줬다고 소리를 지르나요? 주변 ''완벽한'' 부모들의 시선은 신경 쓰지 마세요. 차분히 눈을 맞추고 설명하되 입장은 흔들리지 마세요.', title_nl = 'Geduld tijdens een driftbui 🛒', body_nl = 'Hij schreeuwt omdat je het speelgoed dat hij wilde niet hebt gekocht. Trek je niets aan van de blikken van ''perfecte'' ouders. Maak rustig oogcontact, leg het uit en houd voet bij stuk.', title_pl = 'Cierpliwość w chwili kryzysu 🛒', body_pl = 'Krzyczy, bo nie kupiłaś mu w sklepie zabawki, którą chciał? Nie przejmuj się spojrzeniami „idealnych” rodziców wokół. Spokojnie nawiąż kontakt wzrokowy, wytłumacz i nie zmieniaj zdania.', title_pt = 'Paciência na hora da crise 🛒', body_pt = 'Grita no supermercado porque não lhe comprou o brinquedo que queria? Não ligue aos olhares dos pais "perfeitos" à volta. Estabeleça contacto visual com calma, explique e mantenha a sua posição.', title_sv = 'Tålamod i krisen 🛒', body_sv = 'Barnet skriker för att det inte fick leksaken det ville ha i affären. Bry dig inte om blickarna från de perfekta föräldrarna runt omkring. Skapa lugnt ögonkontakt, förklara och stå fast.', title_vi = 'Kiên nhẫn lúc khủng hoảng 🛒', body_vi = 'Bé la hét vì mẹ không mua món đồ chơi bé muốn ở siêu thị. Đừng bận tâm đến ánh nhìn của những phụ huynh "hoàn hảo" xung quanh. Hãy bình tĩnh nhìn vào mắt bé, giải thích và giữ vững lập trường.', title_zh = '崩溃时刻的耐心 🛒', body_zh = '在超市没给买想要的玩具，就大喊大叫？别在意旁边那些“完美父母”的目光。平静地和宝宝对视，耐心解释，保持你的立场。' WHERE id = '904ee771-1822-4dbc-a79d-be6697d8f129' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Llega el mes 31! 🎉', body_es = 'Ya está en la etapa más intelectual y a la vez más revuelta de la infancia. Cada frase y cada pregunta suya es un gran descubrimiento para ti.', title_fr = 'Bienvenue au 31e mois !  🎉', body_fr = 'Il est désormais dans l''étape la plus intellectuelle, mais aussi la plus mouvementée de l''enfance. Chacune de ses phrases, chacune de ses questions est une grande découverte pour vous.', title_hi = '31वें महीने में कदम!  🎉', body_hi = 'वह अब बचपन के सबसे समझदार और साथ ही सबसे उथल-पुथल वाले दौर में है। उसका हर वाक्य, हर सवाल आपके लिए एक बड़ी खोज है।', title_id = 'Memasuki bulan ke-31!  🎉', body_id = 'Kini ia berada di tahap masa kanak-kanak yang paling intelektual sekaligus paling penuh gejolak. Setiap kalimat dan setiap pertanyaannya adalah penemuan besar bagi Anda.', title_ja = '生後31か月へ！ 🎉', body_ja = 'いま、子ども時代でいちばん知的で、同時にいちばん波乱に満ちた時期にいます。ひとつひとつの言葉、ひとつひとつの質問が、あなたにとって大きな発見です。', title_ko = '31개월이 되었어요!  🎉', body_ko = '아이는 이제 어린 시절 중 가장 지적이면서도 가장 혼란스러운 시기에 들어섰어요. 아이의 문장 하나, 질문 하나가 엄마에게는 큰 발견이에요.', title_nl = 'Op naar maand 31!  🎉', body_nl = 'Hij zit nu in de meest intellectuele, maar ook de meest woelige fase van de kindertijd. Elke zin, elke vraag is voor jou een grote ontdekking.', title_pl = 'Witaj, 31. miesiącu!  🎉', body_pl = 'Jest już na najbardziej intelektualnym, a zarazem najbardziej burzliwym etapie dzieciństwa. Każde jego zdanie i każde pytanie to dla ciebie wielkie odkrycie.', title_pt = 'Chegou o 31.º mês!  🎉', body_pt = 'Ele está agora na fase mais intelectual e, ao mesmo tempo, mais agitada da infância. Cada frase e cada pergunta são uma grande descoberta para si.', title_sv = 'Nu börjar 31:a månaden!  🎉', body_sv = 'Barnet är nu i barndomens mest intellektuella och samtidigt mest kaotiska fas. Varje mening och varje fråga är en stor upptäckt för dig.', title_vi = 'Chào tháng thứ 31!  🎉', body_vi = 'Bé đang ở giai đoạn trí tuệ nhất nhưng cũng nhiều biến động nhất của tuổi thơ. Mỗi câu nói, mỗi câu hỏi của bé đều là một khám phá lớn với mẹ.', title_zh = '迈入第31个月！ 🎉', body_zh = '宝宝正处在童年最有智慧、同时也最折腾的阶段。宝宝的每一句话、每一个问题，对你来说都是一个大发现。' WHERE id = 'c5b71abf-d92a-46da-8996-4282a02052e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La alegría de aplaudir 👏', body_es = '¿Cuando consigue algo se aplaude solo, todo orgulloso? ¡Quiere que se lo reconozcan! Celebra tú también su pequeño logro con mucha alegría y motívale.', title_fr = 'La joie d''applaudir 👏', body_fr = 'Quand il réussit quelque chose, il s''applaudit tout seul, tout fier ? Il a besoin d''être encouragé ! Applaudissez, vous aussi, sa petite réussite avec une grande joie et motivez-le.', title_hi = 'ताली बजाने की खुशी 👏', body_hi = 'कुछ कर लेने पर खुद ही ताली बजाकर गर्व करता है? वह चाहता है कि उसे सराहा जाए! उसकी इस छोटी सी कामयाबी पर आप भी बड़ी खुशी से ताली बजाइए और उसका हौसला बढ़ाइए।', title_id = 'Senangnya bertepuk tangan 👏', body_id = 'Saat berhasil melakukan sesuatu, ia bertepuk tangan sendiri dengan bangga? Ia ingin diakui! Sambut keberhasilan kecilnya dengan kegembiraan besar dan beri ia semangat.', title_ja = '拍手のよろこび 👏', body_ja = '何かができたとき、自分で拍手して得意げにしていますか？認めてほしいのです！この小さな成功を、あなたも大きなよろこびで拍手して、やる気を引き出しましょう。', title_ko = '박수의 기쁨 👏', body_ko = '무언가를 해냈을 때 스스로 박수 치며 뿌듯해하나요? 인정받고 싶은 거예요! 이 작은 성공을 엄마도 크게 기뻐하며 박수로 응원해 주세요.', title_nl = 'Klappen van blijdschap 👏', body_nl = 'Klapt hij voor zichzelf en is hij trots als iets lukt? Hij wil bevestiging! Juich zijn kleine succes ook met grote blijdschap toe en motiveer hem.', title_pl = 'Radość klaskania 👏', body_pl = 'Gdy coś mu się uda, sam sobie klaszcze i jest dumny? Chce uznania! Ty też oklaskuj jego mały sukces z wielką radością i go motywuj.', title_pt = 'A alegria de bater palmas 👏', body_pt = 'Quando consegue fazer algo, bate palmas a si próprio cheio de orgulho? Quer reconhecimento! Aplauda também esta pequena conquista com muita alegria e motive-o.', title_sv = 'Glädjen i att klappa händerna 👏', body_sv = 'Klappar barnet händerna för sig själv och är stolt när något lyckas? Barnet vill bli bekräftat! Applådera den lilla framgången med stor glädje du också och motivera hen.', title_vi = 'Niềm vui vỗ tay 👏', body_vi = 'Khi làm được điều gì đó, bé tự vỗ tay và đầy tự hào? Bé muốn được công nhận! Hãy cùng reo mừng thành công nhỏ này của bé thật vui vẻ và tiếp thêm động lực cho bé.', title_zh = '拍手的喜悦 👏', body_zh = '做成一件事就自己拍手，很骄傲？宝宝想得到认可！你也用大大的喜悦为这个小成就鼓掌，给宝宝打打气吧。' WHERE id = '0d2ab4f6-8a9d-4fb2-978b-635299c5c2d2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te preocupa su curva de talla y peso a partir de los 2,5 años? En lugar de leer artículos que asustan en internet, pide a Anacan AI información precisa y con base científica.', body_fr = 'Ses courbes de taille et de poids après 2,5 ans vous inquiètent ? Plutôt que de lire des articles effrayants sur Internet, obtenez auprès d''Anacan AI une information précise et fondée sur la science.', body_hi = '2.5 साल के बाद बच्चे की लंबाई और वज़न का चार्ट आपको चिंता में डाल रहा है? इंटरनेट पर डरावने लेख पढ़ने के बजाय Anacan AI से सटीक और वैज्ञानिक आधार वाली जानकारी लीजिए।', body_id = 'Grafik tinggi dan berat badannya setelah usia 2,5 tahun membuat Anda cemas? Daripada membaca artikel menyeramkan di internet, dapatkan informasi yang tepat dan berdasar ilmiah dari Anacan AI.', body_ja = '2歳半を過ぎて、身長や体重のグラフが気になりますか？ネットでこわい記事を読むより、Anacan AIから正確で科学的な根拠のある情報をもらいましょう。', body_ko = '두 돌 반 이후 키와 몸무게 그래프가 걱정되나요? 인터넷의 무서운 글을 읽기보다 Anacan AI에게 정확하고 과학적인 정보를 받아 보세요.', body_nl = 'Maak je je na 2,5 jaar zorgen over zijn lengte- en gewichtscurve? Lees geen enge artikelen op internet, maar krijg nauwkeurige, wetenschappelijk onderbouwde informatie van Anacan AI.', body_pl = 'Niepokoją cię siatki wzrostu i wagi dziecka po 2,5 roku? Zamiast czytać przerażające artykuły w internecie, uzyskaj dokładne, oparte na nauce informacje od Anacan AI.', body_pt = 'Depois dos 2,5 anos, as curvas de altura e peso preocupam-na? Em vez de ler artigos assustadores na internet, obtenha informação precisa e com base científica no Anacan AI.', body_sv = 'Oroar barnets längd- och viktkurva dig efter 2,5 år? I stället för att läsa skrämmande artiklar på nätet, få exakt och vetenskapligt grundad information från Anacan AI.', body_vi = 'Mẹ lo lắng về biểu đồ chiều cao và cân nặng của bé sau 2,5 tuổi? Thay vì đọc những bài báo đáng sợ trên mạng, hãy hỏi Anacan AI để có thông tin chính xác, có cơ sở khoa học.', body_zh = '2.5岁以后孩子的身高体重曲线让你担心？与其看网上那些吓人的文章，不如从Anacan AI那里获取准确、有科学依据的信息。' WHERE id = '25c7776c-5416-4926-9ebf-f1fff97f3809' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los sonidos raros de papá 🤡', body_es = 'Cuando tus trucos no funcionan, los sonidos raros de papá salvan la situación. En las crisis de la noche, pásale la pelota enseguida y sonríe desde fuera.', title_fr = 'Les drôles de bruits de papa 🤡', body_fr = 'Quand vos astuces ne marchent plus, les bruits bizarres de papa sauvent la situation. Pendant les crises du soir, passez-lui vite la balle et souriez en coulisses.', title_hi = 'पापा की अजीब आवाज़ें 🤡', body_hi = 'जब आपकी तरकीबें काम नहीं करतीं, तो पापा की अजीब आवाज़ें हालात संभाल लेती हैं। शाम के नखरों में तुरंत बॉल उनके पाले में डालिए और दूर से मुस्कुराइए।', title_id = 'Suara lucu Ayah 🤡', body_id = 'Saat cara Anda tidak berhasil, suara aneh Ayah bisa menyelamatkan keadaan. Saat krisis malam hari, langsung oper bolanya kepada Ayah dan tersenyumlah dari jauh.', title_ja = 'パパのおもしろい声 🤡', body_ja = 'あなたの手が効かないとき、パパのおもしろい声が状況を救ってくれます。夕方のかんしゃくでは、すぐにパパにバトンを渡して、そばでほほえみましょう。', title_ko = '아빠의 웃긴 소리 🤡', body_ko = '엄마의 방법이 통하지 않을 때 아빠의 웃긴 소리가 상황을 구해 줘요. 저녁 떼쓰기 때는 바로 아빠에게 공을 넘기고 옆에서 웃어 주세요.', title_nl = 'Papa''s gekke geluidjes 🤡', body_nl = 'Als jouw trucjes niet werken, redden papa''s gekke geluiden de situatie. Speel de bal bij avondbuien direct naar hem door en glimlach vanaf de zijlijn.', title_pl = 'Śmieszne odgłosy taty 🤡', body_pl = 'Gdy twoje sposoby nie działają, dziwne odgłosy taty ratują sytuację. Podczas wieczornych kryzysów od razu podaj mu piłeczkę i uśmiechaj się z boku.', title_pt = 'Os sons engraçados do pai 🤡', body_pt = 'Quando os seus truques não funcionam, os sons estranhos do pai salvam a situação. Nas crises da noite, passe-lhe logo a bola e sorria de longe.', title_sv = 'Pappas konstiga ljud 🤡', body_sv = 'När dina knep inte fungerar räddar pappas konstiga ljud situationen. Vid kvällskriser, passa bollen till honom direkt och le från sidan.', title_vi = 'Những âm thanh ngộ nghĩnh của bố 🤡', body_vi = 'Khi những chiêu của mẹ không hiệu quả, những âm thanh lạ của bố sẽ cứu nguy. Khi bé quấy buổi tối, hãy "chuyền bóng" ngay cho bố và mỉm cười đứng xem.', title_zh = '爸爸的怪声音 🤡', body_zh = '你的办法都不管用时，爸爸的怪声音能挽救局面。晚上宝宝崩溃时，马上把球传给他，在一旁笑着看就好。' WHERE id = '8ca38ffe-27aa-42ae-a1e8-03b42c6c25c2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La melodía de la noche 🛀', body_es = 'Después de correr todo el día, estáis agotados los dos. Un baño templado y una melodía suave y tranquila de fondo calmarán por completo su sistema nervioso.', title_fr = 'La mélodie du soir 🛀', body_fr = 'Après avoir couru toute la journée, vous êtes épuisés tous les deux. Un bain tiède et une mélodie douce en fond sonore apaiseront complètement son système nerveux.', title_hi = 'रात की धुन 🛀', body_hi = 'दिनभर भागदौड़ से वह भी थक गया और आप भी। गुनगुना स्नान और पीछे बजती हल्की, धीमी धुन उसके नर्वस सिस्टम को पूरी तरह शांत कर देगी।', title_id = 'Melodi malam 🛀', body_id = 'Seharian berlarian, ia dan Anda sama-sama kelelahan. Mandi air hangat dengan alunan melodi lembut di latar belakang akan menenangkan sistem sarafnya sepenuhnya.', title_ja = '夜のメロディー 🛀', body_ja = '一日じゅう走り回って、ふたりともへとへと。ぬるめのお風呂と、後ろで流れるやさしく穏やかなメロディーが、神経をすっかり落ち着かせてくれます。', title_ko = '밤의 멜로디 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤죠. 따뜻한 목욕과 잔잔하게 흐르는 부드러운 멜로디가 아이의 신경을 편안하게 진정시켜 줄 거예요.', title_nl = 'Avondmelodie 🛀', body_nl = 'Jullie zijn allebei op van een hele dag rennen. Een lauw bad met een zacht, rustig melodietje op de achtergrond kalmeert zijn zenuwstelsel helemaal.', title_pl = 'Melodia nocy 🛀', body_pl = 'Po całym dniu biegania oboje jesteście wykończeni. Ciepła kąpiel i lekka, łagodna melodia w tle całkowicie uspokoją jego układ nerwowy.', title_pt = 'Melodia da noite 🛀', body_pt = 'Depois de correrem o dia todo, estão os dois esgotados. Um banho morno e uma melodia suave a tocar em fundo vão acalmar completamente o sistema nervoso dele.', title_sv = 'Nattens melodi 🛀', body_sv = 'Både du och barnet är helt slut efter en hel dag i farten. Ett ljummet bad och en lätt, lugn melodi i bakgrunden lugnar barnets nervsystem helt.', title_vi = 'Giai điệu của đêm 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều kiệt sức. Một bồn nước ấm cùng giai điệu nhẹ nhàng, êm dịu vang lên phía sau sẽ giúp hệ thần kinh của bé hoàn toàn dịu lại.', title_zh = '夜晚的旋律 🛀', body_zh = '跑了一整天，宝宝和你都累坏了。一次温水澡，加上背景里轻柔舒缓的旋律，会让宝宝的神经系统彻底放松下来。' WHERE id = '186e8c82-10c6-4dcc-8ae8-517e2888e663' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Da sentido a los dibujos 📖', body_es = '¿Toca los animales o niños que ve en el libro y pregunta «¿Qué hace este?»? Su percepción visual es asombrosa. Cuéntale historias detalladas sobre los personajes.', title_fr = 'Il donne du sens aux images 📖', body_fr = 'Il touche les animaux ou les enfants des livres et demande « Qu''est-ce qu''il fait ? » Sa perception visuelle est étonnante. Racontez-lui des histoires riches sur les personnages.', title_hi = 'तस्वीरों को मतलब देता है 📖', body_hi = 'किताब में जानवरों या बच्चों को देखकर उन्हें छूता है और पूछता है ''यह क्या कर रहा है?'' उसकी देखकर समझने की क्षमता कमाल की है। उसके साथ किरदारों के बारे में गहरी कहानियाँ बनाइए।', title_id = 'Memberi makna pada gambar 📖', body_id = 'Saat melihat hewan atau anak-anak di buku, ia menyentuhnya dan bertanya ''Dia sedang apa?'' Persepsi visualnya luar biasa. Ceritakan kisah yang mendalam tentang tokoh-tokohnya.', title_ja = '絵の意味がわかる 📖', body_ja = '絵本の動物や子どもを見て、さわりながら「これ、なにしてるの？」と聞きますか？視覚的な理解力がすばらしいですね。キャラクターについて一緒にじっくりお話をしましょう。', title_ko = '그림의 의미를 알아요 📖', body_ko = '책 속 동물이나 아이들을 만지며 ''이건 뭐 해?'' 하고 묻나요? 시각 인지가 놀라워요. 등장인물에 대해 깊이 있는 이야기를 함께 나눠 보세요.', title_nl = 'Hij geeft betekenis aan plaatjes 📖', body_nl = 'Raakt hij dieren of kinderen in een boek aan en vraagt hij ''Wat doet die?'' Zijn visuele waarneming is geweldig. Vertel hem uitgebreide verhalen over de figuren.', title_pl = 'Nadaje sens obrazkom 📖', body_pl = 'Dotyka zwierzątek i dzieci w książeczce i pyta: „Co to robi?”. Jego percepcja wzrokowa jest niesamowita. Opowiadaj mu rozbudowane historie o postaciach.', title_pt = 'Dá significado às imagens 📖', body_pt = 'Toca nos animais ou nas crianças que vê nos livros e pergunta "O que está a fazer?" A perceção visual é espantosa. Conte-lhe histórias mais ricas sobre as personagens.', title_sv = 'Barnet ger bilderna mening 📖', body_sv = 'Rör barnet vid djuren eller barnen i boken och frågar ”vad gör den?”. Synuppfattningen är fantastisk. Berätta djupa historier om figurerna tillsammans.', title_vi = 'Bé hiểu ý nghĩa tranh ảnh 📖', body_vi = 'Thấy con vật hay em bé trong sách, bé chạm vào và hỏi "Bạn này đang làm gì?". Khả năng nhận thức thị giác của bé thật đáng kinh ngạc. Hãy kể cho bé những câu chuyện sâu sắc về các nhân vật.', title_zh = '给图片赋予意义 📖', body_zh = '看到书里的动物或小朋友，就去摸，还问“这是在干什么？”视觉感知真是惊人。和宝宝一起围绕书里的角色讲讲有深度的故事吧。' WHERE id = '34a5aff2-1b83-44f1-acd3-59c942a78f84' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tiempo para mamá 🥑', body_es = 'Con el ajetreo diario, no comas de pie. Elige un tentempié energético en Recetas saludables y, aunque sea 10 minutos, túmbate en el sofá y pon tu alimentación en primer plano.', title_fr = 'Du temps pour maman 🥑', body_fr = 'Dans la course du quotidien, ne déjeunez pas debout. Choisissez une collation énergisante dans les Recettes saines et pensez à votre propre alimentation en vous allongeant au moins 10 minutes sur le canapé.', title_hi = 'माँ के लिए समय 🥑', body_hi = 'रोज़ की भागदौड़ में खड़े-खड़े लंच मत कीजिए। सेहतमंद रेसिपी से ऊर्जा देने वाला स्नैक चुनिए और कम से कम 10 मिनट सोफ़े पर आराम करते हुए अपने खाने को प्राथमिकता दीजिए।', title_id = 'Waktu untuk Ibu 🥑', body_id = 'Di tengah kesibukan, jangan makan siang sambil berdiri. Pilih camilan berenergi dari Resep Sehat, dan setidaknya berbaringlah 10 menit di sofa dengan mengutamakan asupan Anda sendiri.', title_ja = 'ママの時間 🥑', body_ja = '毎日のバタバタで、ランチを立ったまま済ませないで。「ヘルシーレシピ」から元気の出るおやつを選び、せめて10分はソファに横になって、自分の栄養を大切にしましょう。', title_ko = '엄마를 위한 시간 🥑', body_ko = '바쁜 하루 속에서 점심을 서서 때우지 마세요. 건강한 레시피에서 힘이 나는 간식을 고르고, 단 10분이라도 소파에 누워 나의 식사를 먼저 챙기세요.', title_nl = 'Tijd voor mama 🥑', body_nl = 'Eet in de dagelijkse drukte je lunch niet staand. Kies een energierijk tussendoortje uit Gezonde recepten en zet je eigen voeding op de eerste plaats, al is het maar 10 minuten liggend op de bank.', title_pl = 'Czas dla mamy 🥑', body_pl = 'W codziennej bieganinie nie jedz obiadu na stojąco. Wybierz ze Zdrowych przepisów energetyczną przekąskę i choć przez 10 minut leżąc na kanapie, postaw swoje odżywianie na pierwszym miejscu.', title_pt = 'Tempo para a mãe 🥑', body_pt = 'Na correria do dia, não almoce de pé. Escolha nas Receitas Saudáveis um snack energético e deite-se pelo menos 10 minutos no sofá, pondo a sua alimentação em primeiro lugar.', title_sv = 'Tid för mamma 🥑', body_sv = 'Ät inte lunchen stående i vardagsstressen. Välj ett energirikt mellanmål från Hälsosamma recept och sätt din egen kost i första rummet, ligg åtminstone 10 minuter på soffan.', title_vi = 'Thời gian của mẹ 🥑', body_vi = 'Đừng ăn trưa vội vàng giữa nhịp sống tất bật. Hãy chọn một món ăn nhẹ giàu năng lượng từ Công thức lành mạnh và ưu tiên dinh dưỡng của mình, ít nhất nằm nghỉ trên sofa 10 phút.', title_zh = '妈妈的时间 🥑', body_zh = '每天忙忙碌碌，别站着解决午饭。从健康食谱里选一份充满能量的小零食，至少在沙发上躺10分钟，把自己的饮食放在首位。' WHERE id = '638fb01b-1266-441c-a6a2-ad8bcb0172d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charlas en susurros 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y cuéntale en voz muy bajita, susurrando, lo que ha pasado durante el día. Susurrar es el mejor método para preparar el cerebro para dormir.', title_fr = 'Conversations chuchotées 🌙', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et racontez-lui sa journée tout bas, en chuchotant. Le chuchotement est la meilleure façon de préparer le cerveau au sommeil.', title_hi = 'फुसफुसाती बातें 🌙', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें बहुत धीमी आवाज़ में, फुसफुसाकर उसे सुनाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे अच्छा तरीका है।', title_id = 'Obrolan berbisik 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan ceritakan kejadian hari ini dengan suara sangat pelan, berbisik. Berbisik adalah cara terbaik menyiapkan otak untuk tidur.', title_ja = 'ささやき声のおしゃべり 🌙', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、今日あったことをとても小さな声でささやくように話してあげて。ささやき声は、脳を眠りへ導くいちばんの方法です。', title_ko = '속삭이는 대화 🌙', body_ko = '방의 불을 모두 꺼 주세요. 옆에 누워 오늘 있었던 일을 아주 작은 목소리로 속삭이듯 들려주세요. 속삭임은 뇌가 잠들 준비를 하게 돕는 가장 좋은 방법이에요.', title_nl = 'Fluistergesprekjes 🌙', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en vertel heel zachtjes, fluisterend, wat er vandaag is gebeurd. Fluisteren is de beste manier om de hersenen klaar te maken voor de slaap.', title_pl = 'Rozmowy szeptem 🌙', body_pl = 'Zgaś wszystkie światła w pokoju. Połóż się obok i bardzo cicho, szeptem opowiedz mu, co wydarzyło się w ciągu dnia. Szept to najlepszy sposób, by przygotować mózg do snu.', title_pt = 'Conversas em sussurro 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e conte-lhe, em voz muito baixa e a sussurrar, o que aconteceu durante o dia. Sussurrar é o melhor método para preparar o cérebro para o sono.', title_sv = 'Viskande samtal 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och berätta mycket tyst, viskande, om det som hänt under dagen. Viskningar är det bästa sättet att förbereda hjärnan för sömn.', title_vi = 'Những cuộc trò chuyện thì thầm 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ kể về những gì đã xảy ra trong ngày. Thì thầm là cách tốt nhất giúp não bộ chuẩn bị cho giấc ngủ.', title_zh = '悄悄话时间 🌙', body_zh = '把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音，悄悄讲讲今天发生的事。悄悄话是帮大脑准备入睡的最好方法。' WHERE id = '543664cd-6c89-4ffd-ac7b-d08edd1101b7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hierro y fuerza 🥩', body_es = '¿Está pálido o se cansa enseguida? Mejora la absorción de vitaminas dándole ensalada con limón o tomate junto con la carne.', title_fr = 'Fer et énergie 🥩', body_fr = 'Il a le teint pâle ou se fatigue vite ? Servez avec la viande une salade au citron ou à la tomate pour mieux absorber les vitamines.', title_hi = 'आयरन और ताकत 🥩', body_hi = 'चेहरा पीला है या जल्दी थक जाता है? मांस के साथ नींबू या टमाटर वाला सलाद देकर विटामिन का अवशोषण बढ़ाइए।', title_id = 'Zat besi dan tenaga 🥩', body_id = 'Ia tampak pucat atau cepat lelah? Sajikan salad dengan lemon atau tomat bersama daging untuk meningkatkan penyerapan vitamin.', title_ja = '鉄分と元気 🥩', body_ja = '顔色が悪かったり、すぐに疲れたりしますか？お肉と一緒にレモンやトマトのサラダを出して、ビタミンの吸収を高めましょう。', title_ko = '철분과 힘 🥩', body_ko = '얼굴이 창백하거나 쉽게 지치나요? 고기와 함께 레몬이나 토마토 샐러드를 곁들여 비타민 흡수를 높여 주세요.', title_nl = 'IJzer en kracht 🥩', body_nl = 'Ziet hij bleek of is hij snel moe? Geef bij vlees een salade met citroen of tomaat om de opname van vitamines te verbeteren.', title_pl = 'Żelazo i siła 🥩', body_pl = 'Jest blady albo szybko się męczy? Do mięsa podawaj sałatkę z cytryną lub pomidorami, by poprawić wchłanianie witamin.', title_pt = 'Ferro e força 🥩', body_pt = 'Está pálido ou cansa-se depressa? Sirva a carne com uma salada com limão ou tomate para melhorar a absorção.', title_sv = 'Järn och styrka 🥩', body_sv = 'Är barnet blekt eller blir snabbt trött? Servera en sallad med citron eller tomat till köttet för att öka vitaminupptaget.', title_vi = 'Sắt và sức mạnh 🥩', body_vi = 'Bé xanh xao hoặc nhanh mệt? Hãy cho bé ăn thịt kèm salad có nước cốt chanh hoặc cà chua để tăng hấp thu vitamin.', title_zh = '铁与力量 🥩', body_zh = '脸色苍白，或者很容易累？搭配肉类时配上柠檬或番茄沙拉，提高维生素的吸收。' WHERE id = '93186474-3eab-43ed-a284-f876b4f1b709' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de las listas 🛒', body_es = '¿Siempre se te olvida algo al ir al súper? La Lista de la compra te espera en la app. Apunta ahí lo que falta y que tu pareja lo compre sin fallo al volver del trabajo.', title_fr = 'Le pouvoir des listes 🛒', body_fr = 'Vous oubliez toujours quelque chose au supermarché ? La Liste de courses vous attend dans l''application. Notez-y vos besoins, votre partenaire fera les courses avec précision en rentrant du travail.', title_hi = 'लिस्ट की ताकत 🛒', body_hi = 'बाज़ार जाते समय कुछ न कुछ ज़रूर भूल जाती हैं? ऐप में शॉपिंग लिस्ट आपका इंतज़ार कर रही है। ज़रूरतें वहाँ लिखिए, ताकि आपके पार्टनर काम से लौटते समय सब कुछ ठीक-ठीक ले आएँ।', title_id = 'Kekuatan sebuah daftar 🛒', body_id = 'Selalu ada yang terlupa saat belanja? Daftar Belanja menunggu Anda di aplikasi. Catat kebutuhan di sana, biar pasangan membelinya dengan tepat saat pulang kerja.', title_ja = 'リストの力 🛒', body_ja = '買い物に行くと、必ず何かを忘れてしまう？アプリの「買い物リスト」が待っています。必要なものをそこに書いて、パートナーに仕事帰りにきちんと買ってきてもらいましょう。', title_ko = '목록의 힘 🛒', body_ko = '마트에 가면 꼭 하나씩 잊어버리나요? 앱의 쇼핑 목록이 기다리고 있어요. 필요한 걸 적어 두면 배우자가 퇴근길에 정확히 사 올 수 있어요.', title_nl = 'De kracht van lijstjes 🛒', body_nl = 'Vergeet je altijd iets als je naar de supermarkt gaat? Het Boodschappenlijstje wacht op je in de app. Zet erop wat je nodig hebt, dan haalt je partner het precies op weg terug van zijn werk.', title_pl = 'Moc list 🛒', body_pl = 'Idąc do sklepu, zawsze o czymś zapominasz? Lista zakupów czeka na ciebie w aplikacji. Zapisz tam potrzeby, a partner wracając z pracy, kupi wszystko co do joty.', title_pt = 'O poder das listas 🛒', body_pt = 'Esquece-se sempre de alguma coisa no supermercado? A Lista de Compras espera por si na app. Aponte lá o que falta e o seu companheiro compra tudo certinho ao voltar do trabalho.', title_sv = 'Listornas kraft 🛒', body_sv = 'Glömmer du alltid något när du går och handlar? Inköpslistan väntar på dig i appen. Skriv in behoven där så kan din partner handla exakt det som behövs på vägen hem från jobbet.', title_vi = 'Sức mạnh của danh sách 🛒', body_vi = 'Đi siêu thị lần nào mẹ cũng quên một thứ gì đó? Danh sách mua sắm đang chờ mẹ trong ứng dụng. Hãy ghi những thứ cần mua vào đó để chồng mua đủ trên đường đi làm về.', title_zh = '清单的力量 🛒', body_zh = '去超市总会忘点什么？购物清单就在应用里等着你。把需要的东西记进去，让另一半下班回家时准确采购。' WHERE id = 'fd977b6d-8463-4d3e-998c-e4dea887a555' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escribe tus emociones 📝', body_es = '¿Nadie te entiende? ¿Nadie ve tu cansancio? El Diario de ánimo es tu mejor confidente. Escribe ahí todo el estrés, el dolor y la soledad, y verás qué rápido te alivias por dentro.', title_fr = 'Écrivez vos émotions 📝', body_fr = 'Personne ne vous comprend ? Personne ne voit votre fatigue ? Le Journal d''humeur est le meilleur confident. Écrivez-y tout votre stress, votre douleur et votre solitude, vous verrez à quelle vitesse vous vous sentirez soulagée.', title_hi = 'भावनाएँ लिखिए 📝', body_hi = 'कोई आपको नहीं समझता? आपकी थकान नहीं देखता? मूड डायरी सबसे अच्छी राज़दार है। वहाँ सारा तनाव, दर्द और अकेलापन लिखिए, आप देखेंगी कि मन कितनी जल्दी हल्का हो जाता है।', title_id = 'Tuliskan perasaan Anda 📝', body_id = 'Merasa tidak ada yang memahami Anda? Tidak ada yang melihat lelah Anda? Buku Harian Suasana Hati adalah teman curhat terbaik. Tuliskan semua stres, rasa sakit, dan kesepian di sana, Anda akan merasakan hati cepat lega.', title_ja = '気持ちを書こう 📝', body_ja = 'だれもわかってくれない？疲れに気づいてもらえない？「気分日記」はいちばんの打ち明け相手です。ストレスも痛みもさみしさも全部書いてみて、心がどれほど早く軽くなるかわかります。', title_ko = '감정을 적어 보세요 📝', body_ko = '아무도 나를 이해하지 못하나요? 피곤함을 몰라주나요? 기분 일기는 최고의 비밀 친구예요. 스트레스, 아픔, 외로움을 모두 적어 보세요. 마음이 금세 가벼워지는 걸 느낄 거예요.', title_nl = 'Schrijf je gevoelens op 📝', body_nl = 'Begrijpt niemand je? Ziet niemand je vermoeidheid? Je Stemmingsdagboek is je beste vertrouweling. Schrijf er al je stress, pijn en eenzaamheid in en je zult merken hoe snel je je opgelucht voelt.', title_pl = 'Zapisz uczucia 📝', body_pl = 'Nikt cię nie rozumie? Nie widzi twojego zmęczenia? Dziennik nastroju to najlepszy powiernik. Wpisz tam cały stres, ból i samotność, a zobaczysz, jak szybko ci ulży.', title_pt = 'Escreva o que sente 📝', body_pt = 'Ninguém a compreende? Ninguém vê o seu cansaço? O Diário de Humor é o melhor confidente. Escreva lá todo o stress, a dor e a solidão e vai ver como fica aliviada muito depressa.', title_sv = 'Skriv ner känslorna 📝', body_sv = 'Känns det som att ingen förstår dig? Att ingen ser din trötthet? Humördagboken är den bästa förtrogna. Skriv av dig all stress, smärta och ensamhet där, så märker du hur snabbt det lättar.', title_vi = 'Viết ra cảm xúc 📝', body_vi = 'Không ai hiểu mẹ? Không ai thấy mẹ mệt mỏi? Nhật ký tâm trạng là người bạn tâm giao tốt nhất. Hãy viết hết căng thẳng, nỗi đau và cô đơn vào đó, mẹ sẽ thấy lòng nhẹ nhõm thật nhanh.', title_zh = '写下感受 📝', body_zh = '没人理解你？没人看见你的疲惫？心情日记是最好的知己。把所有的压力、痛苦和孤独都写进去，你会发现心里很快就轻松了。' WHERE id = '7c36b46e-089a-4d1a-adf7-c6f69476bd88' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Es mío! 🧸', body_es = '¿No le deja sus juguetes al niño que viene de visita? No es egoísmo, es proteger sus límites personales. Enséñale a compartir con el ejemplo, no obligándole.', title_fr = 'C''est à moi 🧸', body_fr = 'Il ne prête pas son jouet à l''enfant venu en visite ? Ce n''est pas de l''égoïsme, il protège ses limites personnelles. Apprenez-lui le partage par l''exemple, pas par la contrainte.', title_hi = 'यह मेरा है 🧸', body_hi = 'घर आए मेहमान बच्चे को अपना खिलौना नहीं देता? यह स्वार्थ नहीं, अपनी निजी सीमाओं की रक्षा है। बाँटना ज़बरदस्ती से नहीं, बस खुद उदाहरण बनकर सिखाइए।', title_id = 'Punyaku 🧸', body_id = 'Ia tidak mau meminjamkan mainannya kepada anak tamu? Ini bukan egois, ia sedang menjaga batas pribadinya. Ajarkan berbagi bukan dengan paksaan, tetapi cukup dengan memberi contoh.', title_ja = 'ぼくの、わたしの 🧸', body_ja = '遊びに来たお友だちに、自分のおもちゃを渡さない？これはわがままではなく、自分の境界線を守っているのです。分け合うことは無理強いではなく、お手本を見せて教えましょう。', title_ko = '내 거야 🧸', body_ko = '놀러 온 친구에게 장난감을 안 빌려주나요? 이기심이 아니라 자기 경계를 지키는 거예요. 나눔은 억지로가 아니라 엄마가 본보기를 보여 주며 가르쳐 주세요.', title_nl = 'Van mij 🧸', body_nl = 'Geeft hij zijn speelgoed niet aan een kindje dat op bezoek komt? Dat is geen egoïsme, maar zijn persoonlijke grenzen bewaken. Leer delen niet door te dwingen, maar door zelf het voorbeeld te geven.', title_pl = 'To moje 🧸', body_pl = 'Nie daje swojej zabawki dziecku, które przyszło w gości? To nie egoizm, tylko ochrona osobistych granic. Ucz dzielenia się nie przymusem, ale własnym przykładem.', title_pt = 'É meu 🧸', body_pt = 'Não empresta o brinquedo à criança que vem de visita? Não é egoísmo, é proteger os seus limites pessoais. Ensine a partilhar não à força, mas pelo seu exemplo.', title_sv = 'Den är min 🧸', body_sv = 'Vill barnet inte låna ut sin leksak till ett gästande barn? Det är inte egoism, det är att skydda sina personliga gränser. Lär ut att dela genom att vara ett exempel, inte genom tvång.', title_vi = 'Của con 🧸', body_vi = 'Bé không cho bạn nhỏ đến chơi mượn đồ chơi? Đây không phải ích kỷ mà là bé đang bảo vệ ranh giới cá nhân. Hãy dạy chia sẻ bằng cách làm gương, đừng ép buộc.', title_zh = '是我的 🧸', body_zh = '不肯把自己的玩具给来家里做客的小朋友？这不是自私，而是在守护自己的界限。别强迫分享，用自己的榜样去教就好。' WHERE id = 'b5b01983-be53-446e-a05f-8de98770b472' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No tienes por qué entretenerle cada minuto ni inventarle juegos. Aburrirse es el principio de la creatividad para los niños. Deja que descubra algo él solo en la habitación.', body_fr = 'Vous n''êtes pas obligée de l''amuser et de lui inventer des jeux à chaque minute. Chez l''enfant, l''ennui est le début de la créativité. Laissez-le découvrir quelque chose tout seul dans la chambre.', body_hi = 'आपको हर मिनट उसका मनोरंजन करने, उसके लिए खेल गढ़ने की ज़रूरत नहीं है। बच्चों के लिए ऊब रचनात्मकता की शुरुआत है। उसे कमरे में अकेले कुछ खोजने दीजिए।', body_id = 'Anda tidak wajib menghiburnya atau mengarang permainan setiap menit. Bagi anak, rasa bosan adalah awal kreativitas. Biarkan ia menemukan sesuatu sendiri di kamar.', body_ja = 'いつもお子さんを楽しませたり、遊びを考えたりしなくてもいいんです。退屈は、子どもにとって創造性のはじまり。部屋でひとりで何かを発見させてあげましょう。', body_ko = '매 순간 아이를 즐겁게 해 주고 놀이를 만들어 줄 필요는 없어요. 심심함은 아이 창의력의 시작이에요. 방에서 혼자 무언가를 발견하게 두세요.', body_nl = 'Je hoeft hem niet elke minuut te vermaken of spelletjes te verzinnen. Verveling is voor kinderen het begin van creativiteit. Laat hem in zijn eentje in de kamer iets ontdekken.', body_pl = 'Nie musisz zabawiać go co minutę i wymyślać mu zabaw. Nuda to dla dzieci początek kreatywności. Pozwól mu samemu coś odkryć w pokoju.', body_pt = 'Não tem de o entreter nem de inventar jogos a cada minuto. O aborrecimento é, para as crianças, o início da criatividade. Deixe-o descobrir algo sozinho no quarto.', body_sv = 'Du måste inte underhålla barnet varje minut eller hitta på lekar hela tiden. Tristess är början på kreativitet för barn. Låt barnet upptäcka något på egen hand i rummet.', body_vi = 'Mẹ không cần phải lúc nào cũng giải trí cho bé hay nghĩ ra trò chơi. Buồn chán là khởi đầu của sự sáng tạo ở trẻ. Hãy để bé tự khám phá điều gì đó trong phòng.', body_zh = '你不必每分每秒都逗宝宝玩、给宝宝编游戏。无聊是孩子创造力的起点。让宝宝在房间里自己去探索点什么吧。' WHERE id = 'b791e063-932d-483a-b56e-e710cf0815c9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Permiso total para ensuciarse 🏖️', body_es = '¿Quiere jugar con barro o con agua? ¡Deja que se ensucie! Encuentra en Productos recomendados materiales fáciles de limpiar para estas actividades que apoyan su desarrollo sensorial.', title_fr = 'Feu vert pour se salir 🏖️', body_fr = 'Il veut jouer avec la boue ou l''eau ? Laissez-le se salir ! Trouvez dans les Produits recommandés du matériel facile à nettoyer pour ces activités qui soutiennent son développement sensoriel.', title_hi = 'गंदा होने की पूरी इजाज़त 🏖️', body_hi = 'कीचड़ या पानी से खेलना चाहता है? गंदा होने दीजिए! सेंसरी विकास में मदद करने वाले इन खेलों के लिए आसानी से साफ़ होने वाली चीज़ें सुझाए गए प्रोडक्ट में ढूँढिए।', title_id = 'Bebas kotor-kotoran 🏖️', body_id = 'Ia ingin bermain lumpur atau air? Biarkan ia kotor! Temukan perlengkapan yang mudah dibersihkan untuk kegiatan yang mendukung perkembangan sensorik ini di Produk Rekomendasi.', title_ja = '思いきり汚れてOK 🏖️', body_ja = 'どろんこ遊びや水遊びがしたい？汚れても大丈夫！感覚の発達をサポートするこうした遊びのために、お手入れが簡単な道具を「おすすめ商品」で見つけましょう。', title_ko = '마음껏 더러워져도 돼요 🏖️', body_ko = '진흙이나 물로 놀고 싶어 하나요? 더러워지게 두세요! 감각 발달을 돕는 이런 놀이를 위한 세척이 쉬운 도구를 추천 제품에서 찾아보세요.', title_nl = 'Helemaal vies worden mag 🏖️', body_nl = 'Wil hij met modder of water spelen? Laat hem lekker vies worden! Vind in Aanbevolen producten makkelijk schoon te maken spullen voor deze activiteiten die zijn zintuiglijke ontwikkeling steunen.', title_pl = 'Pełna zgoda na brudzenie się 🏖️', body_pl = 'Chce bawić się w błocie albo wodą? Niech się ubrudzi! Znajdź w Polecanych produktach łatwe do czyszczenia akcesoria do tych zabaw wspierających rozwój sensoryczny.', title_pt = 'Licença total para se sujar 🏖️', body_pt = 'Quer brincar com lama ou com água? Deixe-o sujar-se! Encontre nos Produtos Recomendados materiais fáceis de limpar para estas atividades que apoiam o desenvolvimento sensorial.', title_sv = 'Fritt fram att bli smutsig 🏖️', body_sv = 'Vill barnet leka med lera eller vatten? Låt hen bli smutsig! Hitta lättstädade saker för de här aktiviteterna som stöder sensorisk utveckling i Rekommenderade produkter.', title_vi = 'Thoải mái lấm bẩn 🏖️', body_vi = 'Bé muốn nghịch bùn hay nghịch nước? Cứ để bé bẩn! Hãy tìm trong Sản phẩm gợi ý những món đồ dễ vệ sinh cho các hoạt động hỗ trợ phát triển giác quan này.', title_zh = '完全允许弄脏 🏖️', body_zh = '想玩泥巴或玩水？就让宝宝弄脏吧！这些活动支持感官发展，去推荐商品找找容易清洗的用品。' WHERE id = '78cdd6a4-a9f3-4cd8-8b42-3de0066371e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al quedarse dormido está más sensible. Para neutralizar los ruidos que llegan por la ventana, enciende en la habitación un aparato de ruido blanco suave (white noise) o música de la naturaleza.', body_fr = 'Au moment de l''endormissement, il est plus sensible aux bruits. Pour neutraliser les sons venant de la fenêtre, allumez dans la chambre un appareil à bruit blanc doux ou une musique de la nature.', body_hi = 'सोते समय संवेदनशीलता बढ़ जाती है। खिड़की से आने वाली आवाज़ों को दबाने के लिए कमरे में हल्का व्हाइट नॉइज़ (white noise) डिवाइस या प्रकृति का संगीत चलाइए।', body_id = 'Saat ia mulai terlelap, kepekaannya meningkat. Untuk meredam suara dari jendela, nyalakan perangkat suara putih (white noise) yang lembut atau musik alam di kamar.', body_ja = '寝入りばなは音に敏感になります。窓の外から聞こえる音をやわらげるために、部屋でやさしいホワイトノイズの機械や自然の音楽をつけましょう。', body_ko = '잠드는 순간에는 예민함이 커져요. 창밖에서 들어오는 소리를 줄이려면 방에 은은한 백색소음 기기나 자연의 소리를 틀어 주세요.', body_nl = 'Bij het inslapen is hij extra gevoelig. Zet een zacht witteruisapparaat of natuurmuziek aan in de kamer om geluiden van buiten te neutraliseren.', body_pl = 'Gdy zasypia, jest bardziej wrażliwy. Aby zneutralizować odgłosy zza okna, włącz w pokoju urządzenie z delikatnym białym szumem (white noise) albo dźwięki natury.', body_pt = 'Ao adormecer, a sensibilidade aumenta. Para neutralizar os sons que vêm da janela, ligue no quarto um aparelho de ruído branco (white noise) suave ou música da natureza.', body_sv = 'Känsligheten ökar när barnet håller på att somna. För att neutralisera ljud från fönstret, sätt på en lätt vit brus-apparat (white noise) eller naturmusik i rummet.', body_vi = 'Lúc bé đang chìm vào giấc ngủ là lúc nhạy cảm nhất. Để trung hòa tiếng ồn từ cửa sổ, hãy bật máy tiếng ồn trắng (white noise) nhẹ nhàng hoặc nhạc thiên nhiên trong phòng.', body_zh = '入睡的时候最敏感。为了屏蔽窗外的声音，在房间里打开轻柔的白噪音机或大自然音乐。' WHERE id = 'a54926e2-dcf2-4ae7-b48f-de76a56a8b5a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mira abajo, ¿qué descubre? 👣', body_es = 'Ya disfruta andando descalzo y tocando la alfombra o las piedras de la habitación. Estimular los nervios de la planta del pie es muy importante para su equilibrio y su motricidad.', title_fr = 'Regardez par terre, que découvre-t-il ? 👣', body_fr = 'Il adore désormais marcher pieds nus, toucher le tapis ou les cailloux de la pièce. L''éveil des nerfs de la plante des pieds est très important pour son équilibre et sa motricité.', title_hi = 'नीचे देखिए, वह क्या खोज रहा है? 👣', body_hi = 'उसे अब नंगे पैर चलने, कालीन या कमरे के पत्थरों को छूने में मज़ा आता है। तलवों की नसों का जागना उसके संतुलन और मोटर स्किल्स के लिए बहुत ज़रूरी है।', title_id = 'Lihat ke bawah, apa yang ia temukan? 👣', body_id = 'Kini ia senang berjalan tanpa alas kaki dan menyentuh karpet atau batu-batu di kamar. Rangsangan saraf di telapak kaki sangat penting untuk keseimbangan dan motoriknya.', title_ja = '下を見て、何を発見中？👣', body_ja = 'はだしで歩いたり、カーペットや部屋の石にふれたりするのを楽しんでいます。足の裏の神経が目覚めることは、バランス感覚と運動能力にとってとても大切です。', title_ko = '발밑을 보세요, 무엇을 발견했을까요? 👣', body_ko = '이제 맨발로 걸으며 카펫이나 방 안의 돌멩이를 만지는 걸 즐겨요. 발바닥 신경의 자극은 균형 감각과 운동 발달에 아주 중요해요.', title_nl = 'Kijk naar beneden, wat ontdekt hij? 👣', body_nl = 'Hij geniet er nu van om op blote voeten te lopen en het tapijt of steentjes in de kamer te voelen. Het prikkelen van de zenuwen onder zijn voetzolen is heel belangrijk voor zijn evenwicht en motoriek.', title_pl = 'Spójrz w dół, co odkrywa? 👣', body_pl = 'Z przyjemnością chodzi już boso i dotyka dywanu albo kamyków w pokoju. Pobudzanie nerwów na podeszwach stóp jest bardzo ważne dla jego równowagi i motoryki.', title_pt = 'Olhe para baixo: o que está a descobrir? 👣', body_pt = 'Já gosta de andar descalço e de tocar no tapete ou nas pedrinhas do quarto. Estimular os nervos da planta do pé é muito importante para o equilíbrio e a motricidade dele.', title_sv = 'Titta ner, vad upptäcker barnet? 👣', body_sv = 'Barnet tycker redan om att gå barfota och känna på mattan eller stenarna i rummet. Att nerverna under fötterna väcks är väldigt viktigt för balansen och motoriken.', title_vi = 'Nhìn xuống xem, bé khám phá gì nào? 👣', body_vi = 'Bé đã thích đi chân trần, chạm vào thảm hay những viên sỏi trong phòng. Việc kích thích các dây thần kinh dưới lòng bàn chân rất quan trọng cho khả năng giữ thăng bằng và vận động của bé.', title_zh = '往下看，宝宝在发现什么？👣', body_zh = '已经喜欢光着脚走路，摸摸地毯或房间里的石头。唤醒脚底的神经，对宝宝的平衡和动作发展非常重要。' WHERE id = 'b1b0d666-c61e-4108-b645-d26f43bbe56c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo abrázale 🫂', body_es = 'No hace falta ningún juego, libro ni cuento. Esta noche simplemente abrázale contra tu pecho, respira su olor y susúrrale en la oscuridad lo valioso que es para ti.', title_fr = 'Serrez-le simplement 🫂', body_fr = 'Pas besoin de jeu, de livre ni de conte. Ce soir, serrez-le simplement contre vous, respirez son odeur et chuchotez-lui dans le noir combien il est précieux.', title_hi = 'बस गले लगाइए 🫂', body_hi = 'किसी खेल, किताब या कहानी की ज़रूरत नहीं। आज शाम बस उसे सीने से लगाइए, उसकी खुशबू महसूस कीजिए और अंधेरे में फुसफुसाकर बताइए कि वह आपके लिए कितना कीमती है।', title_id = 'Cukup peluk 🫂', body_id = 'Tidak perlu permainan, buku, atau dongeng. Malam ini cukup dekap ia di dada, hirup aromanya, dan bisikkan dalam gelap betapa berharganya ia bagi Anda.', title_ja = 'ただ抱きしめて 🫂', body_ja = '遊びも絵本もお話もいりません。今夜はただ胸に抱きしめて、においを深く吸いこみ、暗やみの中でどれほど大切な存在かをささやいてあげましょう。', title_ko = '그냥 안아 주세요 🫂', body_ko = '오늘 밤엔 놀이도, 책도, 동화도 필요 없어요. 그냥 꼭 끌어안고 아이 냄새를 깊이 들이마신 뒤, 어둠 속에서 얼마나 소중한 존재인지 속삭여 주세요.', title_nl = 'Gewoon knuffelen 🫂', body_nl = 'Je hebt geen spelletje, boek of sprookje nodig. Druk hem vanavond gewoon tegen je borst, snuif zijn geurtje op en fluister in het donker hoe dierbaar hij voor je is.', title_pl = 'Po prostu przytul 🫂', body_pl = 'Nie potrzeba żadnej zabawy, książki ani bajki. Dziś wieczorem po prostu przytul go mocno do piersi, wdychaj jego zapach i szepnij w ciemności, jak bardzo jest dla ciebie cenny.', title_pt = 'Só um abraço 🫂', body_pt = 'Não precisa de jogos, livros nem histórias. Esta noite, simplesmente aperte-o contra o peito, respire o cheiro dele e sussurre-lhe no escuro o quanto é precioso.', title_sv = 'Bara en kram 🫂', body_sv = 'Inga lekar, böcker eller sagor behövs. I kväll, håll bara barnet tätt intill dig, andas in doften och viska i mörkret hur värdefull hen är.', title_vi = 'Chỉ cần ôm thôi 🫂', body_vi = 'Không cần trò chơi, sách vở hay truyện cổ tích. Tối nay chỉ cần ôm bé vào lòng, hít hà mùi hương của bé và thì thầm trong bóng tối rằng bé quý giá với mẹ biết bao.', title_zh = '抱一抱就好 🫂', body_zh = '不需要任何游戏、书或故事。今晚就把宝宝紧紧抱在怀里，深深闻一闻宝宝的味道，在黑暗中轻声告诉宝宝，宝宝对你有多珍贵。' WHERE id = '07396f85-0dfe-4998-a9ea-d36af8bc97dd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te ha asustado que se oponga a todo? No busques artículos que dan miedo en internet. Aprovecha las experiencias reales de las madres veteranas de la Comunidad Anacan.', body_fr = 'Son entêtement face à tout vous a fait peur ? Ne cherchez pas d''articles effrayants sur Internet. Profitez du vécu des mamans expérimentées de la Communauté Anacan.', body_hi = 'बच्चे की हर बात पर ज़िद ने आपको डरा दिया? इंटरनेट पर डरावने लेख मत ढूँढिए। Anacan कम्युनिटी में अनुभवी माँओं के असली अनुभवों का फ़ायदा उठाइए।', body_id = 'Sifat keras kepalanya untuk segala hal membuat Anda takut? Jangan mencari artikel menyeramkan di internet. Manfaatkan pengalaman nyata ibu-ibu berpengalaman di Komunitas Anacan.', body_ja = '何にでも反抗するお子さんにドキッとしましたか？ネットでこわい記事を探さないで。Anacanコミュニティの経験豊富なママたちのリアルな体験を活用しましょう。', body_ko = '모든 것에 고집을 부리는 아이 때문에 걱정되나요? 인터넷에서 무서운 글을 찾지 마세요. Anacan 커뮤니티의 경험 많은 엄마들의 현실 이야기를 참고하세요.', body_nl = 'Schrok je van zijn koppigheid over alles? Zoek niet naar enge artikelen op internet. Leer van de echte ervaringen van ervaren moeders in de Anacan Community.', body_pl = 'Przestraszył cię jego upór we wszystkim? Nie szukaj w internecie przerażających artykułów. Skorzystaj z prawdziwych doświadczeń mam w Społeczności Anacan.', body_pt = 'A teimosia dele em tudo assustou-a? Não procure artigos assustadores na internet. Aproveite as experiências reais das mães experientes da Comunidade Anacan.', body_sv = 'Skrämde barnets envishet med allt dig? Sök inte efter skrämmande artiklar på nätet. Ta del av erfarna mammors verklighet i Anacan Community.', body_vi = 'Sự bướng bỉnh với mọi thứ của bé khiến mẹ lo sợ? Đừng tìm đọc những bài báo đáng sợ trên mạng. Hãy tham khảo trải nghiệm thực tế của các mẹ giàu kinh nghiệm trong Cộng đồng Anacan.', body_zh = '孩子什么都要对着干，吓到你了？别在网上搜那些吓人的文章。听听Anacan社区里有经验的妈妈们的真实经历吧。' WHERE id = '0c781594-9b76-4258-9f91-7171c6608a1a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Carreras con objetivo 🐢', body_es = 'Ya no le basta con caminar: corre rápido y se esconde de ti. Quita los obstáculos peligrosos de la habitación y únete con mucha energía al juego del pilla-pilla.', title_fr = 'Courses déterminées 🐢', body_fr = 'Marcher ne lui suffit plus : il court vite pour se cacher de vous. Retirez les obstacles dangereux de la pièce et jouez, vous aussi, au chat et à la souris avec plein d''énergie.', title_hi = 'मकसद वाली दौड़ 🐢', body_hi = 'अब सिर्फ़ चलने से उसका मन नहीं भरता, तेज़ी से दौड़कर आपसे छिप जाता है। कमरे से खतरनाक रुकावटें हटाइए और इस पकड़म-पकड़ाई में आप भी पूरे जोश से शामिल हो जाइए।', title_id = 'Lari penuh tujuan 🐢', body_id = 'Ia tidak lagi puas hanya berjalan, kini ia berlari cepat dan bersembunyi dari Anda. Singkirkan rintangan berbahaya di kamar dan ikutlah bermain kejar-kejaran dengan penuh semangat.', title_ja = '目的のある走り 🐢', body_ja = 'もう歩くだけでは満足せず、さっと走ってあなたから隠れます。部屋の危ないものを片づけて、あなたも元気いっぱいにこの追いかけっこに加わりましょう。', title_ko = '목적 있는 달리기 🐢', body_ko = '이제 걷는 걸로는 부족해서 빠르게 달려 엄마에게서 숨나요? 방의 위험한 장애물을 치우고 엄마도 신나게 이 술래잡기에 함께해 보세요.', title_nl = 'Rennen met een doel 🐢', body_nl = 'Lopen is niet meer genoeg: hij rent razendsnel weg en verstopt zich voor je. Ruim gevaarlijke obstakels in de kamer op en doe vol energie mee met dit tikkertje.', title_pl = 'Celowe ucieczki 🐢', body_pl = 'Nie wystarcza mu już chodzenie, szybko biega i chowa się przed tobą. Usuń z pokoju niebezpieczne przeszkody i z wielką energią dołącz do tej zabawy w berka.', title_pt = 'Corridas com destino 🐢', body_pt = 'Já não se contenta em andar: corre depressa e esconde-se de si. Retire os obstáculos perigosos do quarto e entre também, cheia de energia, nesta brincadeira da apanhada.', title_sv = 'Målmedvetet springande 🐢', body_sv = 'Barnet nöjer sig inte längre med att gå, hen springer snabbt iväg och gömmer sig för dig. Plocka bort farliga hinder i rummet och var med i tafattleken du också, med full energi.', title_vi = 'Những cuộc chạy có mục đích 🐢', body_vi = 'Không chỉ đi bộ, bé còn chạy thật nhanh để trốn mẹ. Hãy dọn những vật cản nguy hiểm trong phòng và hào hứng tham gia trò đuổi bắt này cùng bé.', title_zh = '有目标地奔跑 🐢', body_zh = '已经不满足于走路，飞快地跑开躲着你。收起房间里危险的障碍物，你也充满活力地加入这场“你追我跑”的游戏吧。' WHERE id = '598525b6-1a5f-4877-944f-c79292ee0167' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empiezan los «no» en serio 🛑', body_es = '¿Se aparta y dice «no» con firmeza cuando alguien quiere darle un beso? Respeta los límites de su cuerpo. Que proteste ante el contacto sin permiso es clave para su autoestima futura.', title_fr = 'Les « non » sérieux commencent 🛑', body_fr = 'Quand quelqu''un veut l''embrasser, il recule et dit « non » fermement ? Respectez les limites de son corps. Pouvoir refuser les contacts non désirés est essentiel pour sa future confiance en lui.', title_hi = 'पक्की ''नहीं'' शुरू 🛑', body_hi = 'कोई उसे चूमना चाहे तो दूर हट जाता है और सख्ती से ''नहीं'' कहता है? उसके शरीर की सीमाओं का सम्मान कीजिए। बिना इजाज़त छूने का विरोध करना उसके आगे के आत्मविश्वास के लिए ज़रूरी है।', title_id = '''Tidak'' yang serius dimulai 🛑', body_id = 'Saat seseorang ingin menciumnya, ia menjauh dan tegas berkata tidak? Hormati batas tubuhnya. Keberaniannya menolak sentuhan tanpa izin penting untuk rasa percaya dirinya kelak.', title_ja = '本気の「いや」が始まる 🛑', body_ja = 'だれかにキスされそうになると離れて、きっぱり「いや」と言いますか？体の境界線を尊重しましょう。許可のないふれあいを拒めることは、将来の自信のために欠かせません。', title_ko = '단호한 ''싫어''가 시작돼요 🛑', body_ko = '누가 뽀뽀하려고 하면 피하며 단호하게 ''싫어''라고 하나요? 아이의 몸의 경계를 존중해 주세요. 허락 없는 접촉에 거부할 줄 아는 건 앞으로의 자존감에 꼭 필요해요.', title_nl = 'Het serieuze ''nee'' begint 🛑', body_nl = 'Trekt hij zich terug en zegt hij stellig ''nee'' als iemand hem wil zoenen? Respecteer zijn lichamelijke grenzen. Protesteren tegen aanrakingen zonder toestemming is de basis voor zijn zelfvertrouwen later.', title_pl = 'Zaczynają się poważne „nie” 🛑', body_pl = 'Gdy ktoś chce go pocałować, odsuwa się i stanowczo mówi „nie”? Szanuj granice jego ciała. Sprzeciw wobec dotyku bez zgody jest niezbędny dla jego przyszłej pewności siebie.', title_pt = 'Começam os "nãos" a sério 🛑', body_pt = 'Quando alguém o quer beijar, afasta-se e diz "não" com firmeza? Respeite os limites do corpo dele. Protestar contra toques sem autorização é essencial para a sua autoconfiança futura.', title_sv = 'Bestämda nej börjar 🛑', body_sv = 'Drar sig barnet undan och säger bestämt nej när någon vill pussa hen? Respektera barnets kroppsliga gränser. Att hen säger ifrån mot beröring utan lov är avgörande för självkänslan i framtiden.', title_vi = 'Những tiếng "Không" nghiêm túc bắt đầu 🛑', body_vi = 'Khi có ai muốn hôn, bé né ra và dứt khoát nói "không"? Hãy tôn trọng ranh giới cơ thể của bé. Việc bé phản đối những đụng chạm không được cho phép là nền tảng cho sự tự tin sau này.', title_zh = '认真的“不”开始了 🛑', body_zh = '有人想亲宝宝时，宝宝躲开还坚决说“不”？要尊重宝宝的身体界限。宝宝会拒绝未经允许的触碰，这对未来的自信心至关重要。' WHERE id = '687bbb3b-79db-41d1-81e9-02d82200fd25' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No eres de hierro. Si hoy no tienes fuerzas para cocinar, hierve pasta o pide comida a domicilio. Ser una madre perfecta no es hacerlo todo sola.', body_fr = 'Vous n''êtes pas en fer. Si vous n''avez pas la force de cuisiner aujourd''hui, faites cuire des pâtes ou commandez à manger. Être une mère parfaite, ce n''est pas tout faire seule.', body_hi = 'आप लोहे की नहीं बनी हैं। अगर आज खाना बनाने की ताकत नहीं है, तो पास्ता उबाल लीजिए या बाहर से मँगा लीजिए। परफ़ेक्ट माँ होने का मतलब सब कुछ अकेले करना नहीं है।', body_id = 'Anda bukan robot. Jika hari ini tidak punya tenaga untuk memasak, rebus makaroni atau pesan makanan dari luar. Menjadi ibu sempurna bukan berarti melakukan semuanya sendiri.', body_ja = 'あなたは鉄でできているわけではありません。今日料理する元気がないなら、パスタをゆでるか出前を頼みましょう。完璧なママとは、なんでもひとりでこなすことではありません。', body_ko = '엄마는 철인이 아니에요. 오늘 요리할 힘이 없다면 파스타를 삶거나 배달을 시키세요. 완벽한 엄마란 모든 걸 혼자 해내는 사람이 아니에요.', body_nl = 'Je bent niet van ijzer. Heb je vandaag geen energie om te koken? Kook wat pasta of bestel eten. Een perfecte moeder zijn betekent niet alles alleen doen.', body_pl = 'Nie jesteś z żelaza. Jeśli dziś nie masz siły gotować, ugotuj makaron albo zamów jedzenie. Być idealną mamą nie znaczy robić wszystkiego samej.', body_pt = 'Não é de ferro. Se hoje não tem forças para cozinhar, coza uma massa ou encomende comida. Ser uma mãe perfeita não é fazer tudo sozinha.', body_sv = 'Du är inte av järn. Om du inte orkar laga mat i dag, koka pasta eller beställ mat. Att vara en perfekt mamma betyder inte att göra allt själv.', body_vi = 'Mẹ không phải người sắt. Nếu hôm nay mẹ không còn sức nấu ăn, hãy luộc mì ống hoặc gọi đồ ăn ngoài. Làm mẹ hoàn hảo không có nghĩa là tự mình làm tất cả.', body_zh = '你不是铁打的。如果今天没力气做饭，就煮点意面，或者点个外卖。做一个完美妈妈，不等于什么都要自己扛。' WHERE id = 'cb9d6b16-c52e-4770-b96a-4ab41dd866dc' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Señal de estreñimiento 💩', body_es = '¿Corre mucho pero se olvida de beber agua? Fíjate en las deposiciones en el orinal. Añade sin falta a su menú avena y ciruelas, ricas en fibra.', title_fr = 'Signal de constipation 💩', body_fr = 'Il court beaucoup mais oublie de boire ? Surveillez ses selles dans le pot. Ajoutez absolument à son menu de l''avoine riche en fibres et des pruneaux.', title_hi = 'कब्ज़ का संकेत 💩', body_hi = 'खूब दौड़ता है, लेकिन पानी पीना भूल जाता है? पॉटी में मल पर नज़र रखिए। मेन्यू में फ़ाइबर वाले ओट्स और आलूबुखारा ज़रूर जोड़िए।', title_id = 'Tanda sembelit 💩', body_id = 'Banyak berlari, tetapi lupa minum? Perhatikan kotorannya di pispot. Pastikan menambahkan oat dan plum yang kaya serat ke menunya.', title_ja = '便秘のサイン 💩', body_ja = 'よく走るのに、お水を飲むのを忘れていますか？おまるで便の様子をチェックしましょう。メニューに食物繊維の多いオートミールやプルーンを必ず加えて。', title_ko = '변비 신호 💩', body_ko = '많이 뛰는데 물 마시는 걸 잊나요? 아기 변기에서 배변을 살펴보세요. 식단에 섬유질이 풍부한 귀리와 자두를 꼭 추가하세요.', title_nl = 'Signaal van verstopping 💩', body_nl = 'Rent hij veel en vergeet hij te drinken? Let op zijn ontlasting in het potje. Voeg zeker vezelrijke havermout en pruimen toe aan zijn menu.', title_pl = 'Sygnał zaparcia 💩', body_pl = 'Dużo biega, ale zapomina pić wodę? Obserwuj wypróżnienia w nocniku. Koniecznie dodaj do menu bogate w błonnik płatki owsiane i suszone śliwki.', title_pt = 'Sinais de prisão de ventre 💩', body_pt = 'Corre muito mas esquece-se de beber água? Repare nas fezes no bacio. Junte sem falta à ementa aveia e ameixas, ricas em fibra.', title_sv = 'Tecken på förstoppning 💩', body_sv = 'Springer barnet mycket men glömmer att dricka vatten? Håll koll på avföringen i pottan. Lägg absolut till fiberrik havre och plommon i menyn.', title_vi = 'Tín hiệu táo bón 💩', body_vi = 'Bé chạy nhiều nhưng quên uống nước? Hãy để ý chất thải trong bô. Nhất định thêm yến mạch và mận giàu chất xơ vào thực đơn.', title_zh = '便秘信号 💩', body_zh = '跑得很多，却忘了喝水？留意便盆里的排便情况。菜单里一定要加上富含纤维的燕麦和李子。' WHERE id = '438805fb-6787-4d0d-b1d5-b2a1a747c30c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿En lugar de dormir salta y corre en la cama? Pon el temporizador de sueño y mantén los límites con cariño. Convierte la habitación en una zona de sueño tranquila con el susurro del bosque de Ruido blanco.', body_fr = 'Au lieu de dormir, il saute et court sur le lit ? Lancez le Minuteur de sommeil et tenez vos limites avec amour. Avec le murmure de la forêt des Bruits blancs, transformez la chambre en zone de sommeil apaisante.', body_hi = 'सोने के बजाय बिस्तर पर कूदता और भागता है? स्लीप टाइमर चालू कीजिए, प्यार से अपनी सीमाओं पर टिके रहिए। व्हाइट नॉइज़ में जंगल की सरसराहट से कमरे को शांत नींद वाली जगह बनाइए।', body_id = 'Bukannya tidur, ia malah melompat-lompat di kasur? Nyalakan Timer Tidur dan jaga batasan dengan penuh kasih. Ubah kamar menjadi zona tidur yang tenang dengan suara desir hutan dari Suara Putih.', body_ja = '寝るかわりにベッドの上で跳ねたり走ったり？睡眠タイマーをオンにして、愛情をもってルールを守りましょう。「ホワイトノイズ」の森のざわめきで、部屋を静かな眠りのゾーンに変えて。', body_ko = '자는 대신 침대에서 뛰고 도망가나요? 수면 타이머를 켜고 경계를 사랑으로 지켜 주세요. 백색소음의 숲 바스락 소리로 방을 차분한 수면 공간으로 바꿔 주세요.', body_nl = 'Springt en rent hij op bed in plaats van te slapen? Zet de Slaaptimer aan en bewaak je grenzen liefdevol. Maak van de kamer een rustige slaapzone met bosgeruis uit Witte ruis.', body_pl = 'Zamiast spać, skacze i biega po łóżku? Włącz timer snu i z miłością pilnuj granic. Zamień pokój w spokojną strefę snu szumem lasu z Białego szumu.', body_pt = 'Em vez de dormir, salta e corre na cama? Ligue o temporizador de sono e mantenha os limites com amor. Com o murmúrio da floresta do Ruído Branco, transforme o quarto numa zona de sono tranquila.', body_sv = 'Hoppar och springer barnet i sängen i stället för att sova? Starta sömntimern och håll gränserna med kärlek. Gör rummet till en lugn sömnzon med skogens sus i Vitt brus.', body_vi = 'Bé nhảy nhót, chạy trên giường thay vì ngủ? Hãy bật Bộ hẹn giờ ngủ, giữ vững giới hạn bằng tình yêu thương. Dùng tiếng rì rào của rừng trong Tiếng ồn trắng để biến căn phòng thành vùng ngủ yên tĩnh.', body_zh = '不睡觉，反而在床上又蹦又跑？打开睡眠计时器，用爱守住界限。用白噪音里的森林风声，把房间变成安静的睡眠区。' WHERE id = '6e0e2948-0156-4f7e-a4e9-342d621f5670' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No bebe leche? El calcio es imprescindible para los huesos. Calcula con el Seguimiento de tomas cuánto queso, yogur o brócoli ha tomado hoy y completa lo que falte.', body_fr = 'Il ne boit pas de lait ? Le calcium est indispensable pour les os. Calculez aujourd''hui ses apports en fromage, yaourt ou brocoli avec le Suivi des repas et comblez les manques.', body_hi = 'दूध नहीं पीता? हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से आज पनीर, दही या ब्रोकली की मात्रा गिनिए और कमी पूरी कीजिए।', body_id = 'Tidak mau minum susu? Kalsium wajib untuk tulang. Hitung asupan keju, yoghurt, atau brokoli hari ini di Pemantau Nutrisi dan lengkapi kekurangannya.', body_ja = '牛乳を飲まない？骨のためにカルシウムは欠かせません。「栄養管理ツール」で今日のチーズ、ヨーグルト、ブロッコリーの摂取量を計算して、足りない分を補いましょう。', body_ko = '우유를 안 마시나요? 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 치즈, 요거트, 브로콜리 섭취량을 계산해 부족한 만큼 채워 주세요.', body_nl = 'Drinkt hij geen melk? Calcium is nodig voor de botten. Bereken met de Voedingstracker hoeveel kaas, yoghurt of broccoli hij vandaag binnenkreeg en vul aan wat ontbreekt.', body_pl = 'Nie pije mleka? Wapń jest niezbędny dla kości. Policz w narzędziu do śledzenia karmienia dzisiejsze spożycie sera, jogurtu lub brokułów i uzupełnij braki.', body_pt = 'Não bebe leite? O cálcio é essencial para os ossos. Calcule no Registo de Alimentação o consumo de queijo, iogurte ou brócolos de hoje e compense o que falta.', body_sv = 'Dricker barnet inte mjölk? Kalcium är ett måste för skelettet. Räkna ut dagens intag av ost, yoghurt eller broccoli med Matningskoll och fyll på det som saknas.', body_vi = 'Bé không uống sữa? Canxi rất cần cho xương. Hãy tính lượng phô mai, sữa chua hoặc bông cải xanh hôm nay bằng Theo dõi cữ bú và bổ sung phần còn thiếu.', body_zh = '不肯喝奶？骨骼离不开钙。用喂养记录工具算一算今天奶酪、酸奶或西兰花的摄入量，把不足的补上。' WHERE id = 'c7ebe08f-c601-4b91-b115-456e094665de' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al salir de paseo, no te fíes del tiempo y evita que se enfríe. No decidas solo mirando por la ventana: elige con Tiempo y ropa el conjunto más adecuado para el tiempo de fuera y sal de casa.', body_fr = 'Ne vous laissez pas tromper par le temps et ne le laissez pas prendre froid en promenade. Ne décidez pas en regardant par la fenêtre : avec Météo et tenue, choisissez la tenue la mieux adaptée au temps dehors avant de sortir.', body_hi = 'सैर पर जाते समय मौसम के धोखे में आकर उसे ठंड मत लगने दीजिए। सिर्फ़ खिड़की से देखकर फ़ैसला मत कीजिए, मौसम और कपड़े असिस्टेंट से बाहर के माहौल के लिए सबसे सही कपड़े चुनकर निकलिए।', body_id = 'Saat jalan-jalan, jangan tertipu cuaca hingga ia kedinginan. Jangan memutuskan hanya dengan melihat dari jendela, tentukan setelan yang paling pas dengan alat Cuaca dan Pakaian sebelum keluar rumah.', body_ja = 'お散歩のとき、見た目の天気にだまされて体を冷やさないように。窓から見て決めずに、「天気と服装」で外の様子にいちばん合うコーディネートを決めてから出かけましょう。', body_ko = '산책할 때 날씨에 속아 아이를 춥게 하지 마세요. 창밖만 보고 정하지 말고 날씨와 옷차림 도우미로 바깥 날씨에 가장 알맞은 옷차림을 정한 뒤 나가세요.', body_nl = 'Laat je niet misleiden door het weer als je gaat wandelen, zodat hij het niet koud krijgt. Beslis niet door uit het raam te kijken, maar kies met Weer en kleding de outfit die het best past bij het weer buiten en ga dan pas de deur uit.', body_pl = 'Wychodząc na spacer, nie daj się zwieść pogodzie, żeby go nie przeziębić. Nie decyduj, patrząc przez okno, tylko dobierz w narzędziu Pogoda i ubiór zestaw najlepiej pasujący do warunków i dopiero wtedy wyjdźcie.', body_pt = 'Quando saírem para passear, não se deixe enganar pelo tempo e evite que ele apanhe frio. Não decida só pela janela: escolha no Tempo e Roupa a combinação mais adequada ao tempo lá fora e saiam.', body_sv = 'Låt dig inte luras av vädret så att barnet fryser på promenaden. Bestäm inte genom att titta ut genom fönstret, välj den klädsel som passar bäst för vädret ute med assistenten Väder och kläder innan ni går.', body_vi = 'Khi ra ngoài đi dạo, đừng để thời tiết đánh lừa khiến bé bị lạnh. Đừng quyết định chỉ bằng cách nhìn qua cửa sổ, hãy dùng trợ lý Thời tiết và trang phục để chọn cách phối đồ phù hợp nhất rồi mới ra khỏi nhà.', body_zh = '出门散步时，别被天气骗了，让宝宝着凉。别只看窗外做决定，用天气穿衣助手找到最适合外面环境的搭配再出门。' WHERE id = 'b0e5435a-23a4-401e-a5a2-1b672694e080' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se ha despertado llorando en mitad de la noche sin motivo? ¿Son gases o un terror nocturno? Abrázale con calma y, sin levantar la voz, dale paz y ayúdale a volver a dormirse.', body_fr = 'Il s''est réveillé en pleurant en pleine nuit, sans raison apparente ? Des gaz, ou juste une terreur nocturne ? Prenez-le calmement dans vos bras, apaisez-le sans hausser la voix et aidez-le à se rendormir.', body_hi = 'बिना वजह आधी रात को रोते हुए जाग गया? गैस है या बस नाइट टेरर? शांति से गले लगाइए, आवाज़ ऊँची किए बिना सुकून दीजिए और उसे फिर से सुला दीजिए।', body_id = 'Ia terbangun tengah malam sambil menangis tanpa sebab? Kembung, atau hanya teror malam? Peluk ia dengan tenang dan beri ketenangan tanpa meninggikan suara hingga ia tidur lagi.', body_ja = '理由もなく夜中に泣いて目を覚ましましたか？ガス？それとも夜驚症？静かに抱きしめて、声を荒げずに安心させ、もう一度眠りへ導いてあげましょう。', body_ko = '이유 없이 한밤중에 울며 깼나요? 가스 때문일까요, 아니면 야경증일까요? 조용히 안아 주고 목소리를 높이지 말고 편안하게 해 주며 다시 재워 주세요.', body_nl = 'Zomaar midden in de nacht huilend wakker? Zijn het krampjes of gewoon nachtangst? Knuffel hem rustig, geef hem rust zonder je stem te verheffen en help hem weer in slaap.', body_pl = 'Obudził się w nocy z płaczem bez powodu? To gazy czy lęk nocny? Spokojnie go przytul i nie podnosząc głosu, daj mu spokój, by znów zasnął.', body_pt = 'Acordou a meio da noite a chorar sem razão? São gases ou apenas terror noturno? Abrace-o com calma, tranquilize-o sem levantar a voz e ajude-o a voltar a adormecer.', body_sv = 'Har barnet vaknat gråtande mitt i natten utan anledning? Är det gaser, eller bara nattskräck? Krama barnet lugnt, ge hen ro utan att höja rösten och hjälp hen att somna om.', body_vi = 'Bé bỗng khóc thức giấc giữa đêm không rõ lý do? Đầy hơi hay hoảng sợ ban đêm? Hãy nhẹ nhàng ôm bé, vỗ về mà không cao giọng và đưa bé vào giấc ngủ lại.', body_zh = '半夜无缘无故哭醒？是胀气，还是只是夜惊？平静地抱住宝宝，不提高嗓门，给宝宝安宁，再哄宝宝睡着。' WHERE id = 'c7c50614-edd2-448c-a9f6-e76579ba2f11' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Miedo a la separación 🥺', body_es = '¿Hasta cuando vas al baño te espera llorando detrás de la puerta? La ansiedad por separación a veces se intensifica. Háblale cada vez para que sepa que estás ahí y que vuelves enseguida.', title_fr = 'Peur de la séparation 🥺', body_fr = 'Même quand vous allez aux toilettes, il pleure derrière la porte en vous attendant. L''angoisse de séparation devient parfois plus forte. Parlez-lui à chaque fois pour lui dire que vous êtes là et que vous revenez tout de suite.', title_hi = 'बिछड़ने का डर 🥺', body_hi = 'आप टॉयलेट भी जाएँ तो दरवाज़े के पीछे इंतज़ार करते हुए रोता है? अलगाव की चिंता कभी-कभी बढ़ जाती है। हर बार आवाज़ देकर बताइए कि आप यहीं हैं और तुरंत लौट आएँगी।', title_id = 'Takut berpisah 🥺', body_id = 'Bahkan saat Anda ke toilet, ia menunggu di balik pintu sambil menangis. Kecemasan berpisah kadang memuncak. Setiap kali, bersuaralah dan katakan bahwa Anda ada di sini dan akan segera kembali.', title_ja = '離れるのがこわい 🥺', body_ja = 'トイレに行くときでさえ、ドアの向こうで待って泣いていますか？分離不安が強くなる時期もあります。そのたびに声をかけて、ここにいること、すぐに戻ってくることを伝えましょう。', title_ko = '분리 불안 🥺', body_ko = '화장실에 갈 때도 문 앞에서 기다리며 우나요? 분리 불안이 가끔 심해질 수 있어요. 그때마다 목소리를 들려주며 여기 있고 금방 돌아온다고 말해 주세요.', title_nl = 'Verlatingsangst 🥺', body_nl = 'Zelfs als je naar de wc gaat, wacht hij huilend achter de deur. Verlatingsangst kan soms heftig worden. Laat steeds je stem horen en zeg dat je er bent en zo terugkomt.', title_pl = 'Lęk separacyjny 🥺', body_pl = 'Nawet gdy idziesz do toalety, czeka pod drzwiami i płacze? Lęk separacyjny czasem się nasila. Za każdym razem odezwij się i powiedz, że jesteś obok i zaraz wrócisz.', title_pt = 'Medo da separação 🥺', body_pt = 'Até quando vai à casa de banho, espera por si atrás da porta a chorar? A ansiedade de separação por vezes intensifica-se. Fale com ele sempre, diga-lhe que está ali e que volta já.', title_sv = 'Separationsrädsla 🥺', body_sv = 'Barnet väntar bakom dörren och gråter till och med när du går på toaletten. Separationsångesten kan ibland bli starkare. Ropa varje gång och säg att du är här och att du kommer tillbaka direkt.', title_vi = 'Nỗi sợ xa mẹ 🥺', body_vi = 'Ngay cả khi mẹ vào nhà vệ sinh, bé cũng đứng sau cửa chờ và khóc. Lo âu chia ly đôi khi trở nên dữ dội. Mỗi lần như vậy, hãy lên tiếng để bé biết mẹ ở ngay đây và sẽ quay lại ngay.', title_zh = '分离焦虑 🥺', body_zh = '连你去洗手间，宝宝都在门外等着哭？分离焦虑有时会变得强烈。每次都出声告诉宝宝你就在这里，马上就回来。' WHERE id = 'ccc01a90-d6a0-43fa-b96b-7ed5976f5309' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Buscando nuevos amigos 👫', body_es = '¿En el parque intenta correr con otros niños de su edad y acercarse a ellos? ¡La socialización ya está en marcha! Vigílale de lejos y observa con orgullo estos primeros intentos.', title_fr = 'À la recherche de nouveaux amis 👫', body_fr = 'Au parc, il essaie de courir avec les enfants de son âge et de s''approcher d''eux ? La socialisation est officiellement lancée ! Surveillez de loin ces premières tentatives avec fierté.', title_hi = 'नए दोस्त की तलाश 👫', body_hi = 'पार्क में अपने हमउम्र बच्चों के साथ दौड़ने और उनके पास जाने की कोशिश करता है? सामाजिकता अब शुरू हो चुकी है! दूर से नज़र रखते हुए इन पहली कोशिशों को गर्व से देखिए।', title_id = 'Mencari teman baru 👫', body_id = 'Ia mencoba berlari bersama teman sebayanya di taman dan mendekati mereka? Sosialisasi resmi dimulai! Awasi dari jauh dan saksikan usaha pertamanya ini dengan bangga.', title_ja = '新しいお友だち探し 👫', body_ja = '公園で同じ年ごろの子と一緒に走ったり、近づこうとしたりしていますか？社会性がいよいよ動き出しました！少し離れて見守りながら、このはじめての挑戦を誇らしく眺めましょう。', title_ko = '새 친구 찾기 👫', body_ko = '공원에서 또래와 함께 뛰고 다가가려고 하나요? 사회성이 본격적으로 자라고 있어요! 멀리서 안전을 지키며 이 첫 시도를 뿌듯하게 지켜보세요.', title_nl = 'Op zoek naar nieuwe vriendjes 👫', body_nl = 'Probeert hij in het park met leeftijdsgenootjes mee te rennen en toenadering te zoeken? De socialisatie is officieel begonnen! Houd hem op afstand in de gaten en kijk trots naar deze eerste pogingen.', title_pl = 'W poszukiwaniu nowych przyjaciół 👫', body_pl = 'W parku próbuje biegać z rówieśnikami i do nich podchodzić? Socjalizacja oficjalnie ruszyła! Asekuruj go z daleka i z dumą obserwuj te pierwsze próby.', title_pt = 'À procura de novos amigos 👫', body_pt = 'No parque, tenta correr com crianças da idade dele e aproximar-se delas? A socialização está oficialmente em marcha! Vigie de longe e acompanhe com orgulho estas primeiras tentativas.', title_sv = 'På jakt efter nya vänner 👫', body_sv = 'Försöker barnet springa med jämnåriga i parken och närma sig dem? Socialiseringen är officiellt igång! Håll ett öga på avstånd och se stolt på de här första försöken.', title_vi = 'Đi tìm bạn mới 👫', body_vi = 'Bé cố chạy theo các bạn cùng tuổi ở công viên và lại gần các bạn? Bé chính thức bắt đầu hòa nhập xã hội! Hãy trông chừng từ xa và tự hào ngắm những nỗ lực đầu tiên này.', title_zh = '寻找新朋友 👫', body_zh = '在公园里想跟同龄小朋友一起跑，主动靠近他们？社交正式开始啦！在远处护着宝宝，骄傲地看着这些最初的尝试。' WHERE id = '1f77c97d-063c-457e-9c51-eaecc473dae1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ponerse el pijama por la noche se ha convertido en una gran guerra? Deja que elija: «¿Quieres el pijama rojo o el azul?». Este pequeño truco le hará sentir que decide él.', body_fr = 'S''habiller le soir tourne à la guerre ? Laissez-lui le choix : « Tu veux le pyjama rouge ou le bleu ? » Cette petite astuce lui donnera le sentiment de décider.', body_hi = 'शाम को कपड़े पहनाना बड़ी जंग बन जाता है? चुनाव उस पर छोड़िए: ''लाल पजामा चाहिए या नीला?'' यह छोटी सी तरकीब उसे महसूस कराएगी कि फ़ैसला उसने लिया।', body_id = 'Berganti baju di malam hari berubah jadi perang besar? Serahkan pilihan padanya: ''Mau piyama merah atau biru?'' Trik kecil ini membuatnya merasa ia yang memutuskan.', body_ja = '夜の着がえが大きな戦いになっていますか？選ばせてあげましょう：「赤いパジャマがいい？それとも青？」この小さな工夫で、自分で決めたと感じられます。', body_ko = '저녁마다 옷 입히기가 큰 전쟁이 되나요? 선택을 맡겨 보세요: ''빨간 잠옷 입을래, 파란 잠옷 입을래?'' 이 작은 요령으로 아이는 스스로 결정했다고 느낄 거예요.', body_nl = 'Wordt ''s avonds aankleden een grote strijd? Laat hem kiezen: ''Wil je de rode pyjama of de blauwe?'' Door dit kleine trucje voelt hij dat hij zelf beslist.', body_pl = 'Wieczorne przebieranie zamienia się w wielką wojnę? Zostaw mu wybór: „Chcesz czerwoną piżamę czy niebieską?”. Ta mała sztuczka da mu poczucie, że to on decyduje.', body_pt = 'À noite, vestir o pijama vira uma guerra? Deixe-o escolher: "Queres o pijama vermelho ou o azul?" Este pequeno truque faz com que sinta que é ele quem decide.', body_sv = 'Blir påklädningen på kvällen ett stort krig? Låt barnet välja: ”Vill du ha den röda pyjamasen eller den blå?” Det lilla knepet får barnet att känna att hen bestämmer.', body_vi = 'Mặc đồ buổi tối trở thành cuộc chiến lớn? Hãy để bé chọn: "Con muốn bộ đồ ngủ màu đỏ hay màu xanh?". Mẹo nhỏ này sẽ giúp bé cảm thấy mình được quyết định.', body_zh = '晚上穿衣服变成一场大战？把选择权交给宝宝：“你想穿红色睡衣，还是蓝色的？”这个小妙招会让宝宝觉得是自己做的决定。' WHERE id = '3eccfd90-7490-4750-87b2-6db63c387fc8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de calma ☕', body_es = 'Si no hay siesta, establece al menos 1 hora de calma (quiet time). Que hojee un libro en su cama mientras tú te tomas el té y pones la mente a cero.', title_fr = 'L''heure calme ☕', body_fr = 'Pas de sieste ? Instaurez au moins 1 heure de « temps calme ». Il feuillette un livre dans son lit pendant que vous buvez votre thé et remettez votre cerveau à zéro.', title_hi = 'शांत समय ☕', body_hi = 'अगर दिन की नींद नहीं होती, तो कम से कम 1 घंटे का ''शांत समय'' (quiet time) तय कीजिए। वह अपने बिस्तर पर किताब पलटे और आप अपनी चाय पीकर दिमाग को रीसेट कीजिए।', title_id = 'Jam tenang ☕', body_id = 'Kalau tidak ada tidur siang, tetapkan setidaknya 1 jam ''waktu tenang'' (quiet time). Biarkan ia membolak-balik buku di tempat tidurnya, sementara Anda minum teh dan menyegarkan pikiran.', title_ja = '静かな時間 ☕', body_ja = 'お昼寝をしないなら、少なくとも1時間の「静かな時間」を決めましょう。お子さんは自分のベッドで絵本をめくり、あなたはお茶を飲んで頭をリセットして。', title_ko = '조용한 시간 ☕', body_ko = '낮잠을 안 잔다면 최소 1시간의 ''조용한 시간''을 정해 보세요. 아이는 침대에서 책을 넘겨 보고, 엄마는 차를 마시며 머리를 비우세요.', title_nl = 'Rustuurtje ☕', body_nl = 'Geen middagslaapje? Plan dan minstens een uur rusttijd. Laat hem in zijn bed in een boekje bladeren, terwijl jij je thee drinkt en je hoofd leegmaakt.', title_pl = 'Godzina wyciszenia ☕', body_pl = 'Jeśli nie ma drzemki, wyznacz przynajmniej 1 godzinę wyciszenia (quiet time). Niech przegląda książeczkę w swoim łóżku, a ty wypij herbatę i zresetuj głowę.', title_pt = 'Hora do sossego ☕', body_pt = 'Se não houver sesta, defina pelo menos 1 hora de sossego (quiet time). Ele folheia um livro na cama dele e a mãe bebe o seu chá e repõe as energias.', title_sv = 'Lugn stund ☕', body_sv = 'Om barnet inte sover på dagen, inför minst 1 timmes Lugn stund (quiet time). Låt barnet bläddra i böcker i sin säng medan du dricker ditt te och nollställer hjärnan.', title_vi = 'Giờ yên tĩnh ☕', body_vi = 'Nếu bé không ngủ ngày, hãy đặt ít nhất 1 tiếng "Giờ yên tĩnh" (quiet time). Bé lật sách trên giường của mình, còn mẹ uống trà và để đầu óc được nghỉ ngơi.', title_zh = '安静时间 ☕', body_zh = '如果不睡午觉，至少定一个1小时的“安静时间”。让宝宝在自己床上翻翻书，你喝杯茶，让大脑重启一下。' WHERE id = 'a9a77950-254b-44a6-a42a-1aaac4de986d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El monstruo de la oscuridad 🌌', body_es = '¿Le dan miedo las sombras cuando apagas la luz? Cuanto más crece su imaginación, más reales parecen los miedos. Pon el sonido del vientre materno de Ruido blanco y dale esa seguridad tan antigua que necesita.', title_fr = 'Le monstre dans le noir 🌌', body_fr = 'Il a peur des ombres quand on éteint la lumière ? Plus l''imagination grandit, plus les peurs semblent réelles. Mettez le son du ventre maternel dans les Bruits blancs pour lui offrir cette sécurité ancienne dont il a besoin.', title_hi = 'अंधेरे का राक्षस 🌌', body_hi = 'लाइट बंद करते ही परछाइयों से डरता है? कल्पना बढ़ने के साथ डर भी असली लगने लगते हैं। व्हाइट नॉइज़ में गर्भ की आवाज़ चलाकर उसे वह पुराना भरोसा दीजिए जिसकी उसे ज़रूरत है।', title_id = 'Monster dalam gelap 🌌', body_id = 'Ia takut bayangan saat lampu dimatikan? Seiring imajinasinya tumbuh, rasa takut terasa makin nyata. Putar suara rahim dari Suara Putih untuk memberinya rasa aman purba yang ia butuhkan.', title_ja = '暗やみのモンスター 🌌', body_ja = '明かりを消すと影をこわがりますか？想像力が育つにつれて、こわさも本物のように感じられます。「ホワイトノイズ」の胎内音を流して、必要としているなつかしい安心感を届けてあげましょう。', title_ko = '어둠 속 괴물 🌌', body_ko = '불을 끄면 그림자를 무서워하나요? 상상력이 자라면서 두려움도 진짜처럼 느껴져요. 백색소음에서 엄마 배 속 소리를 틀어 아이에게 필요한 근원적인 안정감을 선물하세요.', title_nl = 'Het monster in het donker 🌌', body_nl = 'Is hij bang voor schaduwen als het licht uitgaat? Hoe groter zijn fantasie, hoe echter de angsten. Zet in Witte ruis het baarmoedergeluid aan en geef hem dat oeroude gevoel van veiligheid dat hij nodig heeft.', title_pl = 'Potwór w ciemności 🌌', body_pl = 'Boi się cieni, gdy gasisz światło? Wraz z wyobraźnią rosną i lęki. Włącz z Białego szumu odgłosy z brzucha mamy i daj mu to pradawne poczucie bezpieczeństwa, którego potrzebuje.', title_pt = 'O monstro no escuro 🌌', body_pt = 'Tem medo das sombras quando as luzes se apagam? À medida que a imaginação cresce, os medos parecem reais. Ponha o som do útero no Ruído Branco e dê-lhe aquela segurança antiga de que precisa.', title_sv = 'Monstret i mörkret 🌌', body_sv = 'Är barnet rädd för skuggorna när lamporna släcks? När fantasin växer blir rädslorna verkliga. Sätt på livmoderljudet i Vitt brus och ge barnet den urgamla trygghet hen behöver.', title_vi = 'Quái vật trong bóng tối 🌌', body_vi = 'Tắt đèn là bé sợ những cái bóng? Trí tưởng tượng càng lớn thì nỗi sợ càng như thật. Hãy bật âm thanh trong bụng mẹ trong Tiếng ồn trắng để mang lại cho bé cảm giác an toàn nguyên thủy bé cần.', title_zh = '黑暗里的怪兽 🌌', body_zh = '一关灯就害怕影子？想象力越丰富，恐惧也变得越真实。打开白噪音里的子宫声，给宝宝那份需要的、熟悉的安全感。' WHERE id = '193d109c-1b4e-4ffc-b28d-b0ef379e189f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lágrimas repentinas 😭', body_es = '¿Nada más abrir los ojos llora sin motivo? Descubre hablando con nuestro experto Anacan AI cómo calmar con serenidad a un peque con sobrecarga emocional.', title_fr = 'Larmes soudaines 😭', body_fr = 'Il pleure sans raison dès le réveil ? Découvrez en discutant avec notre expert Anacan AI comment apaiser avec calme un petit en surcharge émotionnelle.', title_hi = 'अचानक आँसू 😭', body_hi = 'आँख खुलते ही बिना वजह रोता है? हमारे Anacan AI एक्सपर्ट से बात करके जानिए कि भावनाओं के बोझ से जूझ रहे नन्हे को शांत रहकर कैसे सँभालें।', title_id = 'Air mata tiba-tiba 😭', body_id = 'Begitu membuka mata ia menangis tanpa sebab? Temukan cara menenangkan si kecil yang kewalahan secara emosi dengan kepala dingin dengan mengobrol bersama ahli Anacan AI.', title_ja = '突然の涙 😭', body_ja = '目を開けたとたん理由もなく泣きますか？感情があふれているお子さんを冷静に落ち着かせる方法を、Anacan AIのエキスパートに相談して見つけましょう。', title_ko = '갑작스러운 눈물 😭', body_ko = '눈 뜨자마자 이유 없이 우나요? 감정 과부하를 겪는 아이를 침착하게 달래는 방법을 Anacan AI 전문가와 이야기하며 알아보세요.', title_nl = 'Plotselinge tranen 😭', body_nl = 'Huilt hij zomaar zodra hij wakker is? Ontdek in een gesprek met onze expert Anacan AI hoe je een overprikkeld kindje kalm tot rust brengt.', title_pl = 'Nagłe łzy 😭', body_pl = 'Gdy tylko otworzy oczy, płacze bez powodu? Porozmawiaj z naszym ekspertem Anacan AI i odkryj, jak spokojnie ukoić malucha przeciążonego emocjami.', title_pt = 'Lágrimas repentinas 😭', body_pt = 'Mal abre os olhos, chora sem razão? Descubra, a conversar com o especialista Anacan AI, como acalmar com serenidade um pequeno em sobrecarga emocional.', title_sv = 'Plötsliga tårar 😭', body_sv = 'Gråter barnet utan anledning så fort hen öppnar ögonen? Prata med vår expert Anacan AI och upptäck hur du lugnt kan trösta ett litet barn med känslomässig överbelastning.', title_vi = 'Những giọt nước mắt bất chợt 😭', body_vi = 'Vừa mở mắt bé đã khóc không rõ lý do? Hãy trò chuyện với chuyên gia Anacan AI để khám phá cách bình tĩnh xoa dịu bé khi bé bị quá tải cảm xúc.', title_zh = '突然的眼泪 😭', body_zh = '一睁眼就无缘无故地哭？和我们的Anacan AI专家聊一聊，学学怎样冷静地安抚情绪过载的小家伙。' WHERE id = '52e4f8ee-826b-476b-b87c-2f51c60ddd09' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Las cuatro paredes de casa os agobian a los dos? Antes de que todo se desmadre, busca en Lugares para mamás un parque cercano. El aire fresco es la mejor medicina para los dos.', body_fr = 'Les quatre murs de la maison vous oppressent tous les deux ? Avant que tout ne parte en vrille, trouvez un parc tout proche dans les Lieux adaptés aux mamans. L''air frais est le meilleur remède pour vous deux.', body_hi = 'घर की चार दीवारें उसे भी और आपको भी घुटन दे रही हैं? सब कुछ बिखरने से पहले माँ के लिए अनुकूल जगहें में पास का पार्क ढूँढिए। ताज़ी हवा आप दोनों के लिए सबसे अच्छी दवा है।', body_id = 'Empat dinding rumah terasa sempit untuknya dan untuk Anda? Sebelum semuanya berantakan, temukan taman terdekat di Tempat Ramah Ibu. Udara segar adalah obat terbaik untuk kalian berdua.', body_ja = '家にこもって、お子さんもあなたも息がつまりそう？すべてが崩れる前に、「ママにやさしいスポット」で近くの公園を見つけましょう。新鮮な空気はふたりにとっていちばんの薬です。', body_ko = '집의 네 벽이 아이도 엄마도 답답하게 하나요? 더 정신없어지기 전에 엄마 친화 장소에서 가까운 공원을 찾아보세요. 맑은 공기는 두 사람 모두에게 최고의 약이에요.', body_nl = 'Worden jullie allebei gek tussen vier muren? Zoek voordat alles uit de hand loopt in Mamavriendelijke plekken een park in de buurt. Frisse lucht is voor jullie allebei het beste medicijn.', body_pl = 'Cztery ściany przytłaczają i jego, i ciebie? Zanim wszystko się rozsypie, znajdź w Miejscach przyjaznych mamom pobliski park. Świeże powietrze to dla was obojga najlepsze lekarstwo.', body_pt = 'As quatro paredes apertam-no a ele e a si? Antes que tudo descambe, encontre um parque perto nos Locais Amigos das Mães. O ar puro é o melhor remédio para os dois.', body_sv = 'Kväver hemmets fyra väggar både barnet och dig? Innan allt rasar, hitta en park i närheten i Mammavänliga platser. Frisk luft är den bästa medicinen för er båda.', body_vi = 'Bốn bức tường khiến cả bé và mẹ ngột ngạt? Trước khi mọi thứ rối tung, hãy tìm công viên gần nhà trong Địa điểm thân thiện với mẹ. Không khí trong lành là liều thuốc tốt nhất cho cả hai.', body_zh = '家里的四面墙让宝宝和你都喘不过气？趁一切还没乱套，在妈妈友好场所里找一个附近的公园。新鲜空气对你们俩都是最好的良药。' WHERE id = '9a65afbd-9f9f-42c0-ae08-4e58e8bf0c14' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te ayudo! 🧹', body_es = '¿Cuando friegas el suelo o quitas el polvo intenta quitarte el trapo? Ya se siente mayor. Dale un trapito, deja que se una a tu equipo y que siga desarrollándose.', title_fr = 'Je t''aide ! 🧹', body_fr = 'Quand vous passez la serpillière ou la poussière, il essaie de vous prendre le chiffon ? Il se sent déjà grand. Donnez-lui un petit chiffon et laissez-le rejoindre l''équipe pour qu''il progresse.', title_hi = 'मैं मदद करूँ! 🧹', body_hi = 'आप पोंछा लगाती हैं या धूल झाड़ती हैं तो आपके हाथ से लेने की कोशिश करता है? वह खुद को बड़ा महसूस करता है। उसे एक छोटा कपड़ा दीजिए और अपनी टीम में शामिल होने दीजिए, ताकि वह आगे बढ़े।', title_id = 'Aku bantu ya! 🧹', body_id = 'Saat Anda mengepel atau membersihkan debu, ia mencoba merebut lapnya? Ia merasa sudah besar. Beri ia lap kecil dan biarkan ia bergabung dengan tim Anda agar ia berkembang.', title_ja = 'お手伝いするね！🧹', body_ja = '床をふいたり、ほこりを払ったりしていると、手から取ろうとしますか？もう自分は大きいと感じています。小さなぞうきんを渡してチームに加わらせ、成長させてあげましょう。', title_ko = '내가 도와줄게! 🧹', body_ko = '엄마가 바닥을 닦거나 먼지를 털 때 손에서 걸레를 가져가려 하나요? 벌써 다 컸다고 느끼는 거예요. 작은 걸레를 쥐여 주고 팀에 합류하게 해 주세요. 성장에 큰 도움이 돼요.', title_nl = 'Ik help je wel! 🧹', body_nl = 'Probeert hij de doek uit je hand te pakken als je dweilt of afstoft? Hij voelt zich al groot. Geef hem een klein doekje en laat hem bij je team komen, zo groeit hij.', title_pl = 'Pomogę ci! 🧹', body_pl = 'Gdy myjesz podłogę albo ścierasz kurze, próbuje zabrać ci szmatkę z ręki? Czuje się już duży. Daj mu małą ściereczkę i pozwól dołączyć do twojej drużyny, niech się rozwija.', title_pt = 'Deixa-me ajudar! 🧹', body_pt = 'Quando limpa o chão ou tira o pó, tenta tirar-lhe o pano da mão? Já se sente crescido. Dê-lhe um paninho e deixe-o juntar-se à equipa: é bom para o desenvolvimento dele.', title_sv = 'Jag hjälper dig! 🧹', body_sv = 'Försöker barnet ta moppen eller dammtrasan ur din hand när du städar? Hen känner sig redan stor. Ge barnet en liten trasa och låt hen gå med i laget och utvecklas.', title_vi = 'Để con giúp mẹ! 🧹', body_vi = 'Khi mẹ lau nhà hay phủi bụi, bé cố giành lấy khăn trong tay mẹ? Bé đã thấy mình lớn rồi. Hãy đưa bé một chiếc khăn nhỏ và cho bé tham gia "đội" của mẹ để bé phát triển.', title_zh = '我来帮你！🧹', body_zh = '你拖地或擦灰时，宝宝想从你手里抢过去？宝宝已经觉得自己长大了。给宝宝一块小抹布，让宝宝加入你的团队，在其中成长吧。' WHERE id = '51ad8bab-02f3-44e2-b4ec-e672c59c18fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hay que soltar energía 🌳', body_es = 'Las cuatro paredes le ponen agresivo. Siéntale en el carrito o cógele de la mano y salid a tomar aire fresco. La paz de la naturaleza os sentará genial a tu peque y a tu ánimo.', title_fr = 'Il faut se défouler 🌳', body_fr = 'Les quatre murs le rendent agressif. Installez-le dans sa poussette ou prenez-le par la main et sortez prendre l''air. Le calme de la nature fera du bien à votre enfant comme à votre moral.', title_hi = 'ऊर्जा निकालना ज़रूरी है 🌳', body_hi = 'चार दीवारें उसे चिड़चिड़ा बना रही हैं। उसे स्ट्रोलर में बिठाइए या हाथ पकड़िए और ताज़ी हवा में निकलिए। प्रकृति का सुकून बच्चे पर भी और आपके मन पर भी अच्छा असर डालेगा।', title_id = 'Energi harus disalurkan 🌳', body_id = 'Empat dinding rumah membuatnya agresif. Dudukkan ia di kereta dorong atau gandeng tangannya dan keluarlah menghirup udara segar. Ketenangan alam akan berdampak baik bagi si kecil dan juga bagi batin Anda.', title_ja = 'エネルギーの発散が必要 🌳', body_ja = '家にこもっているとイライラが強くなりますか？ベビーカーに乗せるか手をつないで、新鮮な空気の中へ出かけましょう。自然の安らぎは、お子さんにもあなたの心にもとてもよい効果があります。', title_ko = '에너지 발산은 필수예요 🌳', body_ko = '네 벽 안에서 아이가 예민해지나요? 유모차에 태우거나 손을 잡고 맑은 공기를 마시러 나가세요. 자연의 평온함은 아이에게도 엄마의 마음에도 좋은 영향을 줄 거예요.', title_nl = 'Energie kwijt is een must 🌳', body_nl = 'De vier muren maken hem agressief. Zet hem in de buggy of neem hem bij de hand en ga naar buiten. De rust van de natuur doet je kindje en jouw gemoed heel goed.', title_pl = 'Trzeba spalić energię 🌳', body_pl = 'Cztery ściany sprawiają, że staje się agresywny. Posadź go w wózku albo weź za rękę i wyjdźcie na świeże powietrze. Spokój natury świetnie wpłynie i na malucha, i na twoją psychikę.', title_pt = 'Gastar energia é obrigatório 🌳', body_pt = 'As quatro paredes deixam-no agressivo. Ponha-o no carrinho ou dê-lhe a mão e saiam para o ar livre. A paz da natureza vai fazer muito bem ao bebé e ao seu estado de espírito.', title_sv = 'Energin måste ut 🌳', body_sv = 'De fyra väggarna gör barnet aggressivt. Sätt hen i vagnen eller ta hen i handen och gå ut i friska luften. Naturens lugn gör gott både för barnet och för ditt psyke.', title_vi = 'Cần xả năng lượng 🌳', body_vi = 'Bốn bức tường khiến bé trở nên hung hăng. Hãy cho bé vào xe đẩy hoặc nắm tay bé ra ngoài hít thở không khí trong lành. Sự bình yên của thiên nhiên sẽ tốt cho cả bé và tâm lý của mẹ.', title_zh = '一定要释放精力 🌳', body_zh = '四面墙让宝宝变得烦躁。把宝宝放进推车或牵着小手，出门呼吸新鲜空气。大自然的宁静，对宝宝和你的心情都有很好的作用。' WHERE id = 'aa639fbc-fe83-44f4-b9ac-8b3bd199a951' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las luces extra de la habitación y, sobre todo, las pantallas de las tablets. La melatonina solo se produce a oscuras.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles de la chambre, et surtout les écrans de tablette. La mélatonine n''est sécrétée que dans le noir.', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और खासकर टैबलेट की स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ अंधेरे माहौल में बनता है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan di kamar, terutama layar tablet. Melatonin hanya diproduksi dalam suasana gelap.', body_ja = '早く寝つけるように、部屋の余分な明かり、特にタブレットの画面はすべて消しましょう。メラトニンは暗い環境でしか分泌されません。', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명, 특히 태블릿 화면을 모두 꺼 주세요. 멜라토닌은 어두운 환경에서만 분비돼요.', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en vooral tabletschermen in de kamer uit. Melatonine wordt alleen in het donker aangemaakt.', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła, a zwłaszcza ekrany tabletów. Melatonina wydziela się tylko w ciemności.', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e sobretudo os ecrãs de tablets. A melatonina só é produzida no escuro.', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor i rummet och särskilt surfplattans skärm. Melatonin utsöndras bara i mörker.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ trong phòng, đặc biệt là màn hình máy tính bảng. Melatonin chỉ được tiết ra trong môi trường tối.', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光，尤其是平板屏幕。褪黑素只有在黑暗环境中才会分泌。' WHERE id = 'd88a96c2-0998-4bcd-a181-952127acf518' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche convierte la habitación en un parque de juegos. Construid un pequeño castillo con los cojines del sofá y meteos dentro. Habrá algo de desorden, pero esas risas lo valen sin duda.', body_fr = 'Ce soir, transformez la chambre en terrain de jeu. Construisez un petit fort avec les coussins du canapé et glissez-vous dedans. Il y aura un peu de désordre, mais ces éclats de rire en valent vraiment la peine.', body_hi = 'आज शाम कमरे को खेल का मैदान बना दीजिए। सोफ़े के कुशन से एक छोटा सा किला बनाइए और अंदर घुस जाइए। थोड़ा बिखराव होगा, लेकिन ये खिलखिलाहटें इसके लायक हैं।', body_id = 'Malam ini ubah kamar menjadi taman bermain. Buat benteng kecil dari bantal sofa dan masuklah ke dalamnya. Akan sedikit berantakan, tetapi tawa riang ini pasti sepadan.', body_ja = '今夜は部屋を遊び場に変えましょう。ソファのクッションで小さなお城を作って、中にもぐりこんで。少し散らかりますが、楽しい笑い声のためなら絶対にその価値があります。', body_ko = '오늘 저녁엔 방을 놀이터로 바꿔 보세요. 소파 쿠션으로 작은 성을 쌓고 그 안에 들어가 보세요. 조금 어질러지겠지만 즐거운 웃음소리는 그럴 가치가 충분해요.', body_nl = 'Maak van de kamer vanavond een speeltuin. Bouw een klein fort van bankkussens en kruip erin. Het wordt een beetje een rommeltje, maar dat vrolijke gelach is het zeker waard.', body_pl = 'Dziś wieczorem zamień pokój w plac zabaw. Zbudujcie małą fortecę z poduszek z kanapy i schowajcie się w środku. Będzie trochę bałaganu, ale te radosne śmiechy są tego warte.', body_pt = 'Esta noite, transforme o quarto num parque infantil. Construam um pequeno forte com as almofadas do sofá e entrem lá para dentro. Vai haver alguma desarrumação, mas estas gargalhadas valem bem a pena.', body_sv = 'Gör rummet till en lekplats i kväll. Bygg en liten borg av soffkuddar och kryp in. Det blir lite stök, men de glada skratten är absolut värda det.', body_vi = 'Tối nay hãy biến căn phòng thành sân chơi. Dùng gối sofa dựng một tòa lâu đài nhỏ rồi cùng chui vào. Sẽ hơi bừa một chút, nhưng những tràng cười vui vẻ chắc chắn rất xứng đáng.', body_zh = '今晚把房间变成游乐场吧。用沙发靠垫搭一座小城堡，一起钻进去。会有点乱，但这些欢笑绝对值得。' WHERE id = '54448f6d-1a3b-4d93-a54d-a52f199ed706' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Coge la cuchara y lo pringa todo? Pon el temporizador de tomas. No mires la comida derramada, sino la independencia y la seguridad que está ganando, y siéntete orgullosa.', body_fr = 'Il prend la cuillère et en met partout ? Lancez le minuteur des repas. Ne regardez pas la nourriture renversée, mais l''autonomie et la confiance en lui qu''il gagne, et soyez fière.', body_hi = 'चम्मच ले लेता है और सब जगह खाना फैला देता है? फ़ीडिंग टाइमर चालू कीजिए। बिखरे खाने को नहीं, उसकी मिली आज़ादी और आत्मविश्वास को देखकर गर्व कीजिए।', body_id = 'Ia merebut sendok dan membuat semuanya belepotan? Nyalakan Timer Makan. Jangan lihat makanan yang tumpah, lihatlah kemandirian dan rasa percaya diri yang ia raih, dan berbanggalah.', body_ja = 'スプーンを持って、あちこち汚しますか？食事タイマーをオンにしましょう。こぼれた食べ物ではなく、お子さんが手に入れた自立心と自信に目を向けて、誇りに思いましょう。', body_ko = '숟가락을 들고 사방을 엉망으로 만드나요? 수유 타이머를 켜세요. 흘린 음식 말고 아이가 얻은 자립심과 자신감을 보며 뿌듯해하세요.', body_nl = 'Pakt hij de lepel en maakt hij overal een knoeiboel van? Zet de Voedingstimer aan. Kijk niet naar het gemorste eten, maar wees trots op de zelfstandigheid en het zelfvertrouwen dat hij wint.', body_pl = 'Bierze łyżkę i wszystko brudzi? Włącz timer karmienia. Nie patrz na rozsypane jedzenie, tylko na samodzielność i pewność siebie, które zdobywa, i bądź dumna.', body_pt = 'Pega na colher e suja tudo? Ligue o temporizador de alimentação. Não olhe para a comida espalhada, mas para a autonomia e a confiança que está a ganhar, e sinta orgulho.', body_sv = 'Tar barnet skeden och kladdar ner överallt? Starta matningstimern. Titta inte på maten som spills, var stolt över friheten och självförtroendet barnet vinner.', body_vi = 'Bé cầm thìa và làm bẩn khắp nơi? Hãy bật Hẹn giờ cho bú. Đừng nhìn vào thức ăn vương vãi, hãy tự hào về sự tự lập và tự tin mà bé đạt được.', body_zh = '抢过勺子弄得到处都是？打开喂养计时器。别盯着撒了一地的饭，看看宝宝获得的独立和自信，骄傲一下吧。' WHERE id = '71cd2e71-d81c-477a-9842-72269b236716' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Nada más abrir los ojos llora por todo y nada le parece bien? Quizá esté en pleno estirón. Salva el día dándole muchos abrazos y seguridad.', body_fr = 'Il pleure pour tout dès le réveil et rien ne lui convient ? Il est peut-être en plein pic de croissance. Sauvez la journée en le câlinant beaucoup et en le rassurant.', body_hi = 'आँख खुलते ही हर बात पर रोता है और किसी चीज़ से खुश नहीं? शायद वह ग्रोथ स्पर्ट के बीच में है। बस उसे खूब गले लगाइए, भरोसा दीजिए और दिन बचा लीजिए।', body_id = 'Begitu membuka mata ia menangis karena segala hal dan tidak puas dengan apa pun? Mungkin ia sedang di tengah lonjakan pertumbuhan. Selamatkan hari ini dengan banyak memeluknya dan memberinya rasa aman.', body_ja = '目を開けたとたん何にでも泣いて、何をしても気に入らない？ちょうど成長の伸びのまっただ中なのかもしれません。たくさん抱きしめて安心させ、一日を救いましょう。', body_ko = '눈 뜨자마자 모든 것에 울고 아무것도 마음에 안 들어 하나요? 성장 급등기 한가운데일지도 몰라요. 많이 안아 주고 안심시켜 주며 하루를 지켜 내세요.', body_nl = 'Huilt hij om alles zodra hij wakker is en is niets goed? Misschien zit hij midden in een groeisprong. Red de dag door hem veel te knuffelen en vertrouwen te geven.', body_pl = 'Gdy tylko otworzy oczy, płacze o wszystko i nic go nie zadowala? Może jest w samym środku skoku rozwojowego. Uratuj dzień, po prostu często go przytulając i dając poczucie bezpieczeństwa.', body_pt = 'Mal abre os olhos, chora por tudo e nada lhe agrada? Talvez esteja em pleno salto de crescimento. Salve o dia com muitos abraços e segurança.', body_sv = 'Gråter barnet för allt så fort hen öppnar ögonen och är inte nöjd med något? Kanske är hen mitt i en tillväxtspurt. Rädda dagen genom att krama barnet mycket och ge trygghet.', body_vi = 'Vừa mở mắt bé đã khóc vì mọi thứ và không hài lòng với gì cả? Có thể bé đang ở giữa giai đoạn tăng trưởng vọt. Hãy ôm bé thật nhiều và trấn an để cứu vãn cả ngày.', body_zh = '一睁眼就什么都哭，什么都不满意？也许正处在生长突增的高峰。多多抱抱宝宝，给宝宝安全感，就能挽救这一天。' WHERE id = 'a40edf39-5245-44c1-a544-58bd483fee61' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Repetir palabras 🗣️', body_es = '¿Repite como un loro cada palabra nueva que sale de tu boca? Su vocabulario se enriquece. Presta especial atención a las palabras y emociones que usas delante de tu peque, porque lo copia todo.', title_fr = 'Il répète les mots 🗣️', body_fr = 'Il répète comme un perroquet chaque nouveau mot qui sort de votre bouche ? Son vocabulaire s''enrichit. Faites bien attention aux mots et aux émotions que vous exprimez près de lui, il copie tout.', title_hi = 'शब्दों को दोहराना 🗣️', body_hi = 'आपके मुँह से निकला हर नया शब्द तोते की तरह तुरंत दोहराता है? उसकी शब्दावली बढ़ रही है। उसके सामने बोले जाने वाले शब्दों और भावनाओं पर खास ध्यान दीजिए, वह सब कुछ नकल करता है।', title_id = 'Mengulang kata 🗣️', body_id = 'Setiap kata baru dari mulut Anda langsung ia ulangi seperti burung beo? Kosakatanya makin kaya. Perhatikan baik-baik kata dan emosi yang Anda ucapkan di dekatnya, ia meniru segalanya.', title_ja = '言葉のまね 🗣️', body_ja = 'あなたが口にする新しい言葉を、すぐにオウムのようにまねしますか？語彙が豊かになっています。そばで話す言葉や感情表現に特に気をつけて、お子さんはなんでもまねします。', title_ko = '말 따라 하기 🗣️', body_ko = '엄마가 하는 새로운 말을 앵무새처럼 바로 따라 하나요? 어휘가 풍부해지고 있어요. 아이 앞에서 쓰는 말과 감정에 특히 신경 써 주세요. 모든 걸 따라 하니까요.', title_nl = 'Woordjes herhalen 🗣️', body_nl = 'Herhaalt hij elk nieuw woord dat jij zegt meteen als een papegaai? Zijn woordenschat groeit. Let extra op de woorden en emoties die je in zijn bijzijn gebruikt, hij kopieert alles.', title_pl = 'Powtarzanie słów 🗣️', body_pl = 'Każde nowe słowo, które powiesz, od razu powtarza jak papużka? Jego słownictwo się wzbogaca. Zwracaj szczególną uwagę na słowa i emocje, które przy nim wyrażasz, bo on wszystko kopiuje.', title_pt = 'Repetir palavras 🗣️', body_pt = 'Repete logo, como um papagaio, cada palavra nova que sai da sua boca? O vocabulário está a crescer. Tenha especial atenção às palavras e emoções que usa perto dele: ele copia tudo.', title_sv = 'Ordupprepning 🗣️', body_sv = 'Upprepar barnet genast varje nytt ord du säger, som en papegoja? Ordförrådet växer. Tänk extra på vilka ord och känslor du uttrycker när barnet är nära, hen kopierar allt.', title_vi = 'Lặp lại từ ngữ 🗣️', body_vi = 'Bé lặp lại ngay như vẹt mọi từ mới mẹ vừa nói? Vốn từ của bé đang phong phú dần. Hãy đặc biệt chú ý đến lời nói và cảm xúc của mẹ khi ở cạnh bé, vì bé bắt chước mọi thứ.', title_zh = '重复说话 🗣️', body_zh = '你说出的每个新词，宝宝都像小鹦鹉一样马上跟着说？词汇量正在丰富起来。在宝宝身边说话和表达情绪时要格外注意，宝宝什么都会模仿。' WHERE id = '352c5750-18d9-48a8-a40c-2d51006fd988' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Esconde las verduras 🥦', body_es = '¿Otra vez ha rechazado la comida al ver ese trocito de zanahoria en la sopa? Hacer puré las verduras y esconderlas en albóndigas con ayuda del Plan de alimentación es el truco de madre más antiguo y útil.', title_fr = 'Cachez les légumes 🥦', body_fr = 'Il a encore refusé de manger parce qu''il a vu ce petit morceau de carotte dans la soupe ? Avec le Plan de nutrition, réduire les légumes en purée et les cacher dans les boulettes, c''est la plus vieille et la plus utile des astuces de maman.', title_hi = 'सब्ज़ियाँ छिपाइए 🥦', body_hi = 'फिर से सूप में गाजर का छोटा सा टुकड़ा देखकर खाने से मना कर दिया? फ़ीडिंग प्लान की मदद से सब्ज़ियों को प्यूरी बनाकर कटलेट में छिपाना माँओं की सबसे पुरानी और काम की तरकीब है।', title_id = 'Sembunyikan sayurannya 🥦', body_id = 'Lagi-lagi ia menolak makan karena melihat potongan kecil wortel di supnya? Menghaluskan sayuran dengan bantuan Rencana Nutrisi lalu menyembunyikannya di perkedel adalah trik ibu paling kuno dan ampuh.', title_ja = '野菜をかくそう 🥦', body_ja = 'またスープの小さなにんじんを見つけて、食べるのをやめましたか？「栄養管理ツール」を使って野菜をピューレにし、ハンバーグにかくすのは、昔ながらの役立つママの知恵です。', title_ko = '채소 숨기기 🥦', body_ko = '수프 속 작은 당근 조각을 보고 또 안 먹겠다고 했나요? 식단 계획을 참고해 채소를 퓌레로 만들어 커틀릿에 숨기는 건 가장 오래되고 유용한 엄마의 비법이에요.', title_nl = 'Verstop de groenten 🥦', body_nl = 'Weigerde hij weer te eten omdat hij dat kleine stukje wortel in de soep zag? Groenten pureren en in gehaktballetjes verstoppen met hulp van het Voedingsplan is de oudste en handigste moedertruc.', title_pl = 'Ukryj warzywa 🥦', body_pl = 'Znowu zobaczył w zupie mały kawałek marchewki i odmówił jedzenia? Zmiksowanie warzyw z pomocą planu karmienia i ukrycie ich w kotlecikach to najstarsza i najskuteczniejsza sztuczka mam.', title_pt = 'Esconder os legumes 🥦', body_pt = 'Voltou a recusar a comida por ver aquele pedacinho de cenoura na sopa? Com o Plano Alimentar, fazer puré dos legumes e escondê-los nos hambúrgueres é o truque de mãe mais antigo e útil.', title_sv = 'Göm grönsakerna 🥦', body_sv = 'Vägrade barnet äta igen när hen såg den lilla morotsbiten i soppan? Att mosa grönsakerna och gömma dem i biffar med hjälp av matplanen är det äldsta och mest användbara mammaknepet.', title_vi = 'Giấu rau đi 🥦', body_vi = 'Bé lại không chịu ăn vì thấy miếng cà rốt nhỏ trong bát canh? Xay nhuyễn rau để giấu vào chả viên với Kế hoạch dinh dưỡng là mẹo lâu đời và hữu ích nhất của các mẹ.', title_zh = '把蔬菜藏起来 🥦', body_zh = '又因为看到汤里那一小块胡萝卜就不肯吃了？借助喂养计划，把蔬菜做成泥藏进肉饼里，是妈妈们最古老也最有用的妙招。' WHERE id = '3f0547e8-7e6b-4c78-bdaf-b78aab3ce2fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con el insomnio 😭', body_es = 'Se ha despertado en mitad de la noche y no quiere dormir. No te enfades. Averigua la causa (dolor, gases, miedo), abrázale con paciencia y espera a que vuelva a dormirse.', title_fr = 'Faire la paix avec les nuits blanches 😭', body_fr = 'Il s''est réveillé en pleine nuit et ne veut pas se rendormir. Ne vous énervez pas. Cherchez la cause (douleur, gaz, peur), câlinez-le avec patience et attendez qu''il replonge dans le sommeil.', title_hi = 'नींद न आने से समझौता 😭', body_hi = 'आधी रात को जाग गया और सोना नहीं चाहता? उस पर गुस्सा मत कीजिए। वजह (दर्द, गैस, डर) पक्की कीजिए और धैर्य से गले लगाकर उसके फिर से सो जाने का इंतज़ार कीजिए।', title_id = 'Berdamai dengan kurang tidur 😭', body_id = 'Ia terbangun tengah malam dan tidak mau tidur lagi. Jangan kesal padanya. Pastikan penyebabnya (sakit, kembung, takut), lalu peluk ia dengan sabar sampai ia terlelap lagi.', title_ja = '眠れない夜と仲直り 😭', body_ja = '真夜中に目を覚まして、眠ろうとしない？イライラしないで。原因（痛み、ガス、こわさ）を確かめ、やさしく抱きしめて、また眠りに落ちるのを待ちましょう。', title_ko = '잠 못 드는 밤과 화해하기 😭', body_ko = '한밤중에 깨서 다시 자려 하지 않나요? 화내지 마세요. 이유(통증, 가스, 무서움)를 살펴보고 인내심 있게 안아 주며 다시 잠들 때까지 기다려 주세요.', title_nl = 'Vrede sluiten met slapeloosheid 😭', body_nl = 'Hij is midden in de nacht wakker en wil niet slapen. Word niet boos op hem. Zoek uit wat de oorzaak is (pijn, krampjes, angst), knuffel hem geduldig en wacht tot hij weer in slaap valt.', title_pl = 'Pogodzić się z nieprzespanymi nocami 😭', body_pl = 'Obudził się w środku nocy i nie chce spać? Nie złość się na niego. Ustal przyczynę (ból, gazy, strach), cierpliwie go przytul i poczekaj, aż znów zaśnie.', title_pt = 'Fazer as pazes com as noites sem dormir 😭', body_pt = 'Acordou a meio da noite e não quer dormir? Não se irrite com ele. Descubra a causa (dor, gases, medo), abrace-o com paciência e espere que volte a adormecer.', title_sv = 'Försonas med sömnlösheten 😭', body_sv = 'Barnet har vaknat mitt i natten och vill inte sova. Bli inte arg. Ta reda på orsaken (smärta, gaser, rädsla), krama barnet med tålamod och vänta tills hen somnar om.', title_vi = 'Làm hòa với những đêm mất ngủ 😭', body_vi = 'Bé thức dậy giữa đêm và không chịu ngủ lại. Đừng bực bé. Hãy xác định nguyên nhân (đau, đầy hơi, sợ hãi), kiên nhẫn ôm bé và chờ bé chìm vào giấc ngủ lại.', title_zh = '和失眠和解 😭', body_zh = '半夜醒来，就是不肯睡？别对宝宝发火。弄清原因（疼痛、胀气、害怕），耐心地抱着宝宝，等宝宝重新入睡。' WHERE id = '5d05da29-b0e2-435e-9e14-f523b38e966b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te agota que la ropa siempre acabe manchada? No te enfades. Está descubriendo los alimentos. Usa baberos de silicona y simplemente disfruta de estos momentos llenos de color y pringue.', body_fr = 'Les vêtements toujours tachés vous fatiguent ? Ne vous énervez pas. Il découvre les aliments. Utilisez des bavoirs en silicone et savourez simplement ces moments colorés et salissants.', body_hi = 'कपड़ों पर बार-बार दाग लगना थका रहा है? इस पर गुस्सा मत कीजिए। वह खाने की चीज़ों को खोज रहा है। सिलिकॉन बिब इस्तेमाल कीजिए और इन रंग-बिरंगे, सने हुए पलों का बस आनंद लीजिए।', body_id = 'Lelah karena bajunya terus kotor? Jangan kesal. Ia sedang mengenal makanan. Gunakan celemek silikon dan nikmati saja momen penuh warna dan belepotan ini.', body_ja = '服がいつも汚れて疲れますか？イライラしないで。食べ物を探検しているのです。シリコンのスタイを使って、このカラフルでべちゃべちゃな時間をただ楽しみましょう。', body_ko = '옷에 늘 얼룩이 져서 지쳤나요? 화내지 마세요. 음식을 탐색하는 중이에요. 실리콘 턱받이를 쓰고 이 알록달록하고 엉망진창인 순간을 그냥 즐겨 보세요.', body_nl = 'Word je moe van de steeds vieze kleren? Erger je er niet aan. Hij ontdekt eten. Gebruik siliconen slabben en geniet gewoon van deze kleurrijke, kliederige momenten.', body_pl = 'Męczą cię ciągle poplamione ubrania? Nie denerwuj się. On odkrywa jedzenie. Używaj silikonowych śliniaków i po prostu ciesz się tymi kolorowymi, umorusanymi chwilami.', body_pt = 'Cansada da roupa sempre manchada? Não se irrite. Ele está a descobrir os alimentos. Use babetes de silicone e simplesmente aproveite estes momentos coloridos e lambuzados.', body_sv = 'Är du trött på att kläderna ständigt blir fläckiga? Bli inte arg. Barnet upptäcker maten. Använd silikonhaklappar och njut helt enkelt av de här färgglada, kladdiga stunderna.', body_vi = 'Quần áo lúc nào cũng dính bẩn khiến mẹ mệt mỏi? Đừng bực mình. Bé đang khám phá thức ăn. Hãy dùng yếm silicon và cứ tận hưởng những khoảnh khắc nhiều màu sắc, lấm lem này.', body_zh = '衣服总是弄脏，让你心累？别为这个生气。宝宝正在探索食物。用硅胶围兜，尽情享受这些五颜六色、脏兮兮的时刻吧。' WHERE id = '7d1bf85e-e587-4da1-8ee8-b719514d8f71' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Llévale delante del espejo. Mira cómo observa asombrado su reflejo y hace muecas distintas. Es una actividad estupenda para que tome conciencia de sí mismo.', body_fr = 'Emmenez-le devant le miroir. Regardez-le contempler son reflet avec étonnement et faire des grimaces. C''est une superbe activité pour sa conscience de soi.', body_hi = 'उसे आईने के सामने ले जाइए। देखिए वह अपनी परछाईं को कितनी हैरानी से देखता है और तरह-तरह के चेहरे बनाता है। यह खुद को पहचानने के लिए एक शानदार गतिविधि है।', body_id = 'Bawa ia ke depan cermin. Lihat betapa takjubnya ia memandangi bayangannya dan membuat berbagai ekspresi. Ini kegiatan luar biasa untuk mengenal dirinya.', body_ja = '鏡の前に連れていきましょう。自分の姿に驚いて見入ったり、いろいろな表情をしたりする様子を見守って。自己認識を育てるすばらしい遊びです。', body_ko = '아이를 거울 앞에 데려가 보세요. 자기 모습을 신기하게 바라보며 여러 표정을 짓는 걸 지켜보세요. 자기 인식에 아주 멋진 활동이에요.', body_nl = 'Neem hem mee naar de spiegel. Kijk hoe verbaasd hij naar zijn spiegelbeeld kijkt en gekke gezichten trekt. Een prachtige activiteit voor zijn zelfbewustzijn.', body_pl = 'Zanieś go przed lustro. Zobacz, z jakim zdumieniem patrzy na swoje odbicie i robi różne miny. To wspaniałe zajęcie dla jego samoświadomości.', body_pt = 'Leve-o até ao espelho. Veja como olha espantado para o seu reflexo e faz caretas diferentes. É uma atividade fantástica para a consciência de si próprio.', body_sv = 'Ta barnet till spegeln. Se hur förundrat hen tittar på sin spegelbild och gör olika miner. Det är en fantastisk aktivitet för barnets självmedvetenhet.', body_vi = 'Hãy đưa bé đến trước gương. Ngắm bé ngạc nhiên nhìn hình ảnh của mình và làm đủ kiểu mặt. Đây là hoạt động tuyệt vời giúp bé nhận thức về bản thân.', body_zh = '把宝宝带到镜子前。看看宝宝怎样惊奇地盯着自己的倒影，做出各种表情。这是帮助宝宝认识自我的绝佳活动。' WHERE id = 'f3bd302c-47f2-4428-b12d-4062c2445dfe' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tozudez con la comida 🥣', body_es = '¿Come dos cucharadas, dice que está lleno y se va corriendo? No le obligues. Crear una relación sana con la comida es más importante que hacerle comer a la fuerza. Ofrece más tomas con raciones más pequeñas.', title_fr = 'Bras de fer à table 🥣', body_fr = 'Deux cuillères, il dit qu''il n''a plus faim et s''en va ? Ne le forcez pas. Construire une relation saine avec la nourriture compte plus que le faire manger de force. Proposez des repas plus fréquents, en plus petites quantités.', title_hi = 'खाने की ज़िद 🥣', body_hi = 'दो चम्मच खाकर ''पेट भर गया'' कहकर भाग जाता है? ज़बरदस्ती मत कीजिए। ज़बरदस्ती खिलाने से ज़्यादा ज़रूरी है खाने के साथ स्वस्थ रिश्ता बनाना। खाने के मौके बढ़ाइए, मात्रा घटाइए।', title_id = 'Keras kepala saat makan 🥣', body_id = 'Baru dua sendok sudah bilang kenyang lalu kabur? Jangan memaksanya. Membangun hubungan sehat dengan makanan lebih penting daripada menyuapi secara paksa. Perbanyak waktu makan, kecilkan porsinya.', title_ja = '食事でのがんこさ 🥣', body_ja = 'ふた口食べて「おなかいっぱい」と言って逃げていきますか？無理に食べさせないで。食べ物とよい関係を築くことは、無理やり食べさせるより大切です。回数を増やして、1回の量を減らしましょう。', title_ko = '밥상 위의 고집 🥣', body_ko = '두 숟가락 먹고 배부르다며 도망가나요? 억지로 먹이지 마세요. 억지로 먹이는 것보다 음식과 건강한 관계를 만드는 게 더 중요해요. 양은 줄이고 횟수를 늘려 주세요.', title_nl = 'Koppig aan tafel 🥣', body_nl = 'Zegt hij na twee hapjes al dat hij vol zit en rent hij weg? Dwing hem niet. Een gezonde relatie met eten is belangrijker dan dwangvoeren. Geef vaker kleinere porties.', title_pl = 'Upór przy jedzeniu 🥣', body_pl = 'Po dwóch łyżkach mówi, że jest najedzony, i ucieka? Nie zmuszaj go. Zdrowa relacja z jedzeniem jest ważniejsza niż karmienie na siłę. Podawaj częściej, ale mniejsze porcje.', title_pt = 'Teimosia à mesa 🥣', body_pt = 'Come duas colheres, diz que está cheio e foge? Não o force. Criar uma relação saudável com a comida é mais importante do que obrigá-lo a comer. Ofereça mais refeições, em porções mais pequenas.', title_sv = 'Envis med maten 🥣', body_sv = 'Äter barnet två skedar, säger att det är mätt och springer iväg? Tvinga inte. Att bygga en sund relation till mat är viktigare än att tvångsmata. Fler portioner, mindre mängd.', title_vi = 'Bướng bỉnh trong bữa ăn 🥣', body_vi = 'Bé ăn hai thìa đã bảo no rồi chạy đi? Đừng ép bé. Xây dựng mối quan hệ lành mạnh với thức ăn quan trọng hơn ép ăn. Hãy cho ăn nhiều bữa hơn, mỗi bữa ít hơn.', title_zh = '吃饭较劲 🥣', body_zh = '吃了两勺就说“饱了”，然后跑开？别勉强。和食物建立健康的关系，比强迫进食重要得多。多分几次吃，每次少一点。' WHERE id = 'c0129df7-df96-4659-882d-c3fd4d3c25e7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tormenta hormonal 🩸', body_es = '¿Antojos repentinos de dulce e irritabilidad? Mira el Calendario menstrual. Quizá sea el SPM. No te culpes y apoya tu cuerpo con un tentempié de dátiles con magnesio de Recetas saludables.', title_fr = 'La tempête hormonale 🩸', body_fr = 'Envies soudaines de sucré et irritabilité ? Regardez le Suivi des règles. C''est peut-être le SPM. Ne vous blâmez pas, soutenez votre corps avec une collation aux dattes riche en magnésium des Recettes saines.', title_hi = 'हार्मोन का तूफ़ान 🩸', body_hi = 'अचानक मीठे की तलब और चिड़चिड़ापन? पीरियड ट्रैकर देखिए। शायद PMS है। खुद को दोष मत दीजिए, सेहतमंद रेसिपी से मैग्नीशियम वाले खजूर के स्नैक से अपने शरीर को सहारा दीजिए।', title_id = 'Badai hormon 🩸', body_id = 'Tiba-tiba ingin makan manis dan mudah kesal? Lihat Pelacak Menstruasi. Mungkin ini PMS. Jangan salahkan diri, dukung tubuh Anda dengan camilan kurma bermagnesium dari Resep Sehat.', title_ja = 'ホルモンの嵐 🩸', body_ja = '急に甘いものが欲しくなったり、イライラしたりしますか？「生理トラッカー」を見てみましょう。PMSかもしれません。自分を責めずに、「ヘルシーレシピ」からマグネシウムたっぷりのデーツのおやつで体をサポートして。', title_ko = '호르몬 폭풍 🩸', body_ko = '갑자기 단 게 당기고 예민해졌나요? 생리 주기 기록을 확인해 보세요. PMS일 수도 있어요. 자책하지 말고 건강한 레시피의 마그네슘이 든 대추야자 간식으로 몸을 돌봐 주세요.', title_nl = 'Hormonenstorm 🩸', body_nl = 'Plotselinge zoetbuien en prikkelbaarheid? Kijk in de Cyclustracker. Misschien is het PMS. Veroordeel jezelf niet en steun je lichaam met een tussendoortje met dadels en magnesium uit Gezonde recepten.', title_pl = 'Burza hormonów 🩸', body_pl = 'Nagła ochota na słodycze i rozdrażnienie? Zajrzyj do Kalendarza miesiączkowego. Może to PMS. Nie obwiniaj się, wesprzyj organizm przekąską z daktylami i magnezem ze Zdrowych przepisów.', title_pt = 'Tempestade hormonal 🩸', body_pt = 'Desejos repentinos de doces e irritabilidade? Veja o Registo do Período. Talvez seja TPM. Não se culpe e apoie o corpo com um snack de tâmaras com magnésio das Receitas Saudáveis.', title_sv = 'Hormonstorm 🩸', body_sv = 'Plötsligt sötsug och irritation? Titta i Mensspåraren. Kanske är det PMS. Klandra inte dig själv, stöd kroppen med ett magnesiumrikt mellanmål med dadlar från Hälsosamma recept.', title_vi = 'Cơn bão hormone 🩸', body_vi = 'Bỗng thèm đồ ngọt và dễ cáu? Hãy xem Theo dõi kỳ kinh. Có thể đó là hội chứng tiền kinh nguyệt. Đừng tự trách, hãy hỗ trợ cơ thể bằng món ăn vặt chà là giàu magie từ Công thức lành mạnh.', title_zh = '荷尔蒙风暴 🩸', body_zh = '突然想吃甜食，还心烦气躁？看看经期记录。也许是经前综合征。别责怪自己，从健康食谱里做一份含镁的椰枣小零食，给身体一点支持。' WHERE id = '2f4c11d8-739d-4bb0-9942-69a623d77f66' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis matutinas sin motivo 🛑', body_es = '¿Nada más abrir los ojos grita y llora por todo? Aprende ya, hablando con nuestro experto Anacan AI, cómo calmar con serenidad a un peque con sobrecarga emocional.', title_fr = 'Crises du matin sans raison 🛑', body_fr = 'Il crie et pleure pour tout dès le réveil ? Découvrez vite en discutant avec notre expert Anacan AI comment apaiser avec calme un petit en surcharge émotionnelle.', title_hi = 'बिना वजह सुबह के नखरे 🛑', body_hi = 'आँख खुलते ही हर बात पर चिल्लाता और रोता है? हमारे Anacan AI एक्सपर्ट से तुरंत बात करके जानिए कि भावनाओं के बोझ से जूझ रहे नन्हे को शांत रहकर कैसे सँभालें।', title_id = 'Tantrum pagi tanpa sebab 🛑', body_id = 'Begitu membuka mata ia berteriak dan menangis karena segala hal? Segera pelajari cara menenangkan si kecil yang kewalahan secara emosi dengan kepala dingin dengan mengobrol bersama ahli Anacan AI.', title_ja = '理由のない朝のかんしゃく 🛑', body_ja = '目を開けたとたん何にでも叫んで泣きますか？感情があふれているお子さんを冷静に落ち着かせる方法を、すぐにAnacan AIのエキスパートに相談して学びましょう。', title_ko = '이유 없는 아침 떼쓰기 🛑', body_ko = '눈 뜨자마자 모든 것에 소리 지르고 우나요? 감정 과부하를 겪는 아이를 침착하게 달래는 방법을 지금 바로 Anacan AI 전문가와 이야기하며 배워 보세요.', title_nl = 'Ochtendbuien zonder reden 🛑', body_nl = 'Schreeuwt en huilt hij om alles zodra hij wakker is? Leer meteen in een gesprek met onze expert Anacan AI hoe je een overprikkeld kindje kalm tot rust brengt.', title_pl = 'Poranne kryzysy bez powodu 🛑', body_pl = 'Gdy tylko otworzy oczy, krzyczy i płacze o wszystko? Od razu porozmawiaj z naszym ekspertem Anacan AI i dowiedz się, jak spokojnie ukoić malucha przeciążonego emocjami.', title_pt = 'Crises matinais sem razão 🛑', body_pt = 'Mal abre os olhos, grita e chora por tudo? Aprenda já, a conversar com o especialista Anacan AI, como acalmar com serenidade um pequeno em sobrecarga emocional.', title_sv = 'Morgonkriser utan orsak 🛑', body_sv = 'Skriker och gråter barnet åt allt så fort hen öppnar ögonen? Prata direkt med vår expert Anacan AI och lär dig hur du lugnt tröstar ett litet barn med känslomässig överbelastning.', title_vi = 'Khủng hoảng buổi sáng không lý do 🛑', body_vi = 'Vừa mở mắt bé đã la hét và khóc vì mọi thứ? Hãy trò chuyện ngay với chuyên gia Anacan AI để học cách bình tĩnh xoa dịu bé khi bé bị quá tải cảm xúc.', title_zh = '莫名的早晨崩溃 🛑', body_zh = '一睁眼就对什么都尖叫、哭闹？马上和我们的Anacan AI专家聊一聊，学学怎样冷静地安抚情绪过载的小家伙。' WHERE id = 'b69b6089-ef94-4c8e-8537-ca4464897520' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que termine él el cuento 📖', body_es = 'Esta noche, al leer el cuento, deja las frases a medias ¡y que las termine tu peque! Pregunta a Anacan AI formas de dialogar que apoyen este asombroso desarrollo del lenguaje.', title_fr = 'C''est lui qui finit l''histoire 📖', body_fr = 'Ce soir, en lisant l''histoire, laissez vos phrases en suspens et laissez-le les compléter ! Demandez à Anacan AI d''autres façons de dialoguer pour soutenir ce développement du langage étonnant.', title_hi = 'कहानी का अंत वह बताए 📖', body_hi = 'आज शाम कहानी पढ़ते समय वाक्य अधूरे छोड़िए और उसे पूरा करने दीजिए! भाषा के इस कमाल के विकास को बढ़ावा देने वाले बातचीत के तरीके Anacan AI से पूछिए।', title_id = 'Biar ia yang menutup cerita 📖', body_id = 'Malam ini saat membacakan dongeng, hentikan kalimat di tengah jalan dan biarkan ia melanjutkannya! Tanyakan pada Anacan AI cara berdialog yang mendukung perkembangan bahasa yang luar biasa ini.', title_ja = 'お話の結末はお子さんに 📖', body_ja = '今夜お話を読むとき、文を途中で止めて、お子さんに続きを言ってもらいましょう！このすばらしい言葉の発達を支える対話のコツを、Anacan AIに聞いてみて。', title_ko = '동화의 끝은 아이가 말해요 📖', body_ko = '오늘 저녁 동화를 읽을 때 문장을 중간에 멈추고 아이가 마무리하게 해 보세요! 이 놀라운 언어 발달을 돕는 대화 요령을 Anacan AI에게 물어보세요.', title_nl = 'Laat hem het einde vertellen 📖', body_nl = 'Stop vanavond tijdens het voorlezen halverwege een zin en laat hem die afmaken! Vraag Anacan AI naar manieren om met gesprekjes deze geweldige taalontwikkeling te steunen.', title_pl = 'Niech on dokończy bajkę 📖', body_pl = 'Dziś wieczorem, czytając bajkę, przerywaj zdania w połowie i pozwól mu je dokończyć! Zapytaj Anacan AI o sposoby prowadzenia dialogu, które wspierają ten niesamowity rozwój mowy.', title_pt = 'Ele que diga o fim da história 📖', body_pt = 'Esta noite, ao ler a história, deixe as frases a meio e deixe-o completá-las! Pergunte ao Anacan AI que diálogos apoiam este desenvolvimento da linguagem fantástico.', title_sv = 'Låt barnet avsluta sagan 📖', body_sv = 'När du läser saga i kväll, stanna mitt i meningarna och låt barnet fylla i! Fråga Anacan AI om samtalssätt som stöder den här fantastiska språkutvecklingen.', title_vi = 'Để bé kể đoạn kết 📖', body_vi = 'Tối nay khi đọc truyện, hãy dừng giữa câu và để bé nói tiếp! Hãy hỏi Anacan AI những cách đối thoại giúp hỗ trợ sự phát triển ngôn ngữ đáng kinh ngạc này.', title_zh = '让宝宝来说故事结局 📖', body_zh = '今晚读故事时，把句子留一半，让宝宝来补完！问问Anacan AI，有哪些对话方式能支持这种惊人的语言发展。' WHERE id = 'c01d73b8-c3b9-41a9-ae94-2f63ced9cfc4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Permiso total para ensuciarse 🏖️', body_es = '¿Quiere jugar con barro o con agua? ¡Deja que se ensucie! Encuentra en Productos recomendados materiales fáciles de limpiar para estas actividades que apoyan su desarrollo sensorial.', title_fr = 'Feu vert pour se salir 🏖️', body_fr = 'Il veut jouer avec la boue ou l''eau ? Laissez-le se salir ! Trouvez dans les Produits recommandés du matériel facile à nettoyer pour ces activités qui soutiennent son développement sensoriel.', title_hi = 'गंदा होने की पूरी इजाज़त 🏖️', body_hi = 'कीचड़ या पानी से खेलना चाहता है? गंदा होने दीजिए! सेंसरी विकास में मदद करने वाले इन खेलों के लिए आसानी से साफ़ होने वाली चीज़ें सुझाए गए प्रोडक्ट में ढूँढिए।', title_id = 'Bebas kotor-kotoran 🏖️', body_id = 'Ia ingin bermain lumpur atau air? Biarkan ia kotor! Temukan perlengkapan yang mudah dibersihkan untuk kegiatan yang mendukung perkembangan sensorik ini di Produk Rekomendasi.', title_ja = '思いきり汚れてOK 🏖️', body_ja = 'どろんこ遊びや水遊びがしたい？汚れても大丈夫！感覚の発達をサポートするこうした遊びのために、お手入れが簡単な道具を「おすすめ商品」で見つけましょう。', title_ko = '마음껏 더러워져도 돼요 🏖️', body_ko = '진흙이나 물로 놀고 싶어 하나요? 더러워지게 두세요! 감각 발달을 돕는 이런 놀이를 위한 세척이 쉬운 도구를 추천 제품에서 찾아보세요.', title_nl = 'Helemaal vies worden mag 🏖️', body_nl = 'Wil hij met modder of water spelen? Laat hem lekker vies worden! Vind in Aanbevolen producten makkelijk schoon te maken spullen voor deze activiteiten die zijn zintuiglijke ontwikkeling steunen.', title_pl = 'Pełna zgoda na brudzenie się 🏖️', body_pl = 'Chce bawić się w błocie albo wodą? Niech się ubrudzi! Znajdź w Polecanych produktach łatwe do czyszczenia akcesoria do tych zabaw wspierających rozwój sensoryczny.', title_pt = 'Licença total para se sujar 🏖️', body_pt = 'Quer brincar com lama ou com água? Deixe-o sujar-se! Encontre nos Produtos Recomendados materiais fáceis de limpar para estas atividades que apoiam o desenvolvimento sensorial.', title_sv = 'Fritt fram att bli smutsig 🏖️', body_sv = 'Vill barnet leka med lera eller vatten? Låt hen bli smutsig! Hitta lättstädade saker för de här aktiviteterna som stöder sensorisk utveckling i Rekommenderade produkter.', title_vi = 'Thoải mái lấm bẩn 🏖️', body_vi = 'Bé muốn nghịch bùn hay nghịch nước? Cứ để bé bẩn! Hãy tìm trong Sản phẩm gợi ý những món đồ dễ vệ sinh cho các hoạt động hỗ trợ phát triển giác quan này.', title_zh = '完全允许弄脏 🏖️', body_zh = '想玩泥巴或玩水？就让宝宝弄脏吧！这些活动支持感官发展，去推荐商品找找容易清洗的用品。' WHERE id = '0b9c3636-088f-48ec-88e8-94ea05f16477' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Análisis de la rutina ⏱️', body_es = '¿Tarda 1 hora en dormirse por la noche? Mira el gráfico del temporizador de sueño. Quizá hace tiempo que toca acortar del todo la siesta y adelantar la hora de dormir.', title_fr = 'Analyse du rythme ⏱️', body_fr = 'L''endormissement du soir prend 1 heure ? Regardez le graphique du Minuteur de sommeil. Il est peut-être grand temps de raccourcir nettement la sieste et d''avancer l''heure du coucher.', title_hi = 'रूटीन का विश्लेषण ⏱️', body_hi = 'शाम को सोने में 1 घंटा लग जाता है? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद को और छोटा करने और शाम का रूटीन जल्दी करने का समय कब का आ चुका है।', title_id = 'Analisis rutinitas ⏱️', body_id = 'Tidur malam butuh 1 jam? Lihat grafik Timer Tidur. Mungkin sudah lama tiba waktunya memangkas tidur siang dan memajukan jam tidur malam.', title_ja = '生活リズムの分析 ⏱️', body_ja = '夜の寝かしつけに1時間かかりますか？睡眠タイマーのグラフを見てみましょう。お昼寝を短くして、夜の寝る時間を早める時期がとっくに来ているのかもしれません。', title_ko = '일과 분석 ⏱️', body_ko = '저녁에 잠드는 데 1시간이나 걸리나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 확 줄이고 잠자리 시간을 앞당길 때가 진작 되었을지도 몰라요.', title_nl = 'Het ritme analyseren ⏱️', body_nl = 'Duurt inslapen ''s avonds een uur? Bekijk het schema in de Slaaptimer. Misschien is het allang tijd om het middagslaapje flink in te korten en de avond te vervroegen.', title_pl = 'Analiza rytmu dnia ⏱️', body_pl = 'Wieczorne zasypianie trwa 1 godzinę? Spójrz na wykres w timerze snu. Może już dawno czas skrócić drzemkę w ciągu dnia i przesunąć wieczorne zasypianie na wcześniej.', title_pt = 'Análise da rotina ⏱️', body_pt = 'Adormecer à noite demora 1 hora? Veja o gráfico do temporizador de sono. Talvez já tenha passado a altura de encurtar de vez a sesta e antecipar a hora de deitar.', title_sv = 'Analys av rutinen ⏱️', body_sv = 'Tar det 1 timme för barnet att somna på kvällen? Titta på sömntimerns diagram. Kanske är det sedan länge dags att korta dagsömnen ordentligt och tidigarelägga kvällen.', title_vi = 'Phân tích nếp sinh hoạt ⏱️', body_vi = 'Buổi tối bé mất 1 tiếng mới ngủ được? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đã đến lúc rút ngắn hẳn giấc ngủ ngày và cho bé đi ngủ tối sớm hơn.', title_zh = '作息分析 ⏱️', body_zh = '晚上入睡要花1个小时？看看睡眠计时器的图表。也许早就该把白天的午睡大大缩短，把晚上的入睡时间提前了。' WHERE id = '28f1c509-c643-44be-b37c-9bbbdb368b42' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Limpieza en equipo 🧹', body_es = '¿Toca recoger la casa? Mientras barres, deja que te ayude pasando un trapo. Lee en el Blog cómo convertir juntos la limpieza en un juego divertido.', title_fr = 'Le ménage ensemble 🧹', body_fr = 'Il faut ranger la maison ? Quand vous balayez, laissez-le vous aider avec un chiffon. Lisez dans les Blogs comment transformer le ménage en jeu amusant à faire ensemble.', title_hi = 'साथ मिलकर सफ़ाई 🧹', body_hi = 'घर समेटना है? जब आप झाड़ू लगाएँ, तो उसे भी कपड़े से पोंछकर मदद करने दीजिए। सफ़ाई को साथ मिलकर मज़ेदार खेल कैसे बनाएँ, ब्लॉग में पढ़िए।', title_id = 'Bersih-bersih bersama 🧹', body_id = 'Rumah perlu dirapikan? Saat Anda menyapu kamar, biarkan ia membantu mengelap dengan kain. Baca di bagian Blog cara mengubah bersih-bersih bersama menjadi permainan yang seru.', title_ja = '一緒にお掃除 🧹', body_ja = '家の片づけをしなきゃ？部屋をはいているとき、お子さんにもぞうきんでふいて手伝ってもらいましょう。お掃除を一緒に楽しい遊びにする方法を、ブログで読んでみて。', title_ko = '함께하는 청소 🧹', body_ko = '집을 정리해야 하나요? 엄마가 방을 쓸 때 아이도 걸레로 닦으며 돕게 해 주세요. 청소를 함께 즐거운 놀이로 바꾸는 방법을 블로그에서 읽어 보세요.', title_nl = 'Samen schoonmaken 🧹', body_nl = 'Moet het huis opgeruimd? Laat hem met een doekje meehelpen als jij de kamer veegt. Lees in Blogs hoe je van schoonmaken samen een leuk spel maakt.', title_pl = 'Wspólne sprzątanie 🧹', body_pl = 'Trzeba posprzątać dom? Gdy zamiatasz pokój, pozwól mu pomóc, przecierając ściereczką. Przeczytaj na Blogu, jak razem zamienić sprzątanie w wesołą zabawę.', title_pt = 'Limpezas a dois 🧹', body_pt = 'É preciso arrumar a casa? Enquanto varre o quarto, deixe-o ajudar a limpar com um pano. Leia no Blogue como transformar as limpezas num jogo divertido para os dois.', title_sv = 'Städning tillsammans 🧹', body_sv = 'Behöver hemmet städas? Låt barnet hjälpa till att torka med en trasa när du sopar. Läs i Bloggar hur ni kan göra städningen till en rolig lek tillsammans.', title_vi = 'Cùng nhau dọn dẹp 🧹', body_vi = 'Cần dọn nhà? Khi mẹ quét phòng, hãy để bé lấy khăn lau giúp mẹ. Đọc trong mục Blog cách biến việc dọn dẹp thành trò chơi vui nhộn cùng nhau.', title_zh = '一起打扫 🧹', body_zh = '家里该收拾了？你扫地时，让宝宝拿抹布擦擦，帮你的忙。去博客里读读怎样一起把打扫变成有趣的游戏。' WHERE id = 'e4b4940d-8946-4ebd-8a09-0e41f12848e2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gritos a medianoche 🤖', body_es = '¿Se despierta gritando en mitad de la noche y no te reconoce? Puede ser un terror nocturno. Pregunta ya a Anacan AI cómo actuar bien y los secretos para no despertarle.', title_fr = 'Le cri de minuit 🤖', body_fr = 'Il se réveille en hurlant en pleine nuit et ne vous reconnaît pas ? C''est peut-être une terreur nocturne. Demandez vite à Anacan AI comment bien réagir et les secrets pour ne pas le réveiller.', title_hi = 'आधी रात की चीख 🤖', body_hi = 'आधी रात को चीखते हुए जागता है और आपको पहचानता नहीं? यह नाइट टेरर हो सकता है। उसे सही तरीके से कैसे सँभालें और न जगाने के राज़ तुरंत Anacan AI से पूछिए।', title_id = 'Jeritan tengah malam 🤖', body_id = 'Ia terbangun tengah malam sambil berteriak dan tidak mengenali Anda? Ini bisa jadi teror malam. Segera tanyakan pada Anacan AI cara menghadapinya dengan benar dan rahasia agar tidak membangunkannya.', title_ja = '真夜中の叫び声 🤖', body_ja = '夜中に叫んで目を覚まし、あなたのことがわからない？夜驚症かもしれません。正しい接し方と、起こさないほうがいい理由を、すぐにAnacan AIに聞いてみましょう。', title_ko = '한밤중의 비명 🤖', body_ko = '한밤중에 비명을 지르며 깨서 엄마를 못 알아보나요? 야경증일 수 있어요. 올바르게 대처하는 법과 깨우지 않는 요령을 Anacan AI에게 바로 물어보세요.', title_nl = 'Gegil midden in de nacht 🤖', body_nl = 'Wordt hij midden in de nacht schreeuwend wakker en herkent hij je niet? Dat kan nachtangst zijn. Vraag Anacan AI meteen hoe je er goed mee omgaat en waarom je hem beter niet wakker maakt.', title_pl = 'Nocny krzyk 🤖', body_pl = 'Budzi się w nocy z krzykiem i cię nie poznaje? To może być lęk nocny. Od razu zapytaj Anacan AI, jak właściwie się wtedy zachować i dlaczego lepiej go nie budzić.', title_pt = 'O grito da meia-noite 🤖', body_pt = 'Acordou a meio da noite aos gritos e não a reconhece? Pode ser um terror noturno. Pergunte já ao Anacan AI como lidar com ele da forma certa e porque não o deve acordar.', title_sv = 'Skrik mitt i natten 🤖', body_sv = 'Vaknar barnet skrikande mitt i natten och känner inte igen dig? Det kan vara nattskräck. Fråga Anacan AI direkt hur du bemöter det rätt och varför du inte ska väcka barnet.', title_vi = 'Tiếng thét giữa đêm 🤖', body_vi = 'Bé hét lên thức giấc giữa đêm và không nhận ra mẹ? Đó có thể là hoảng sợ ban đêm. Hãy hỏi ngay Anacan AI cách xử lý đúng và bí quyết để không làm bé tỉnh giấc.', title_zh = '半夜的哭喊 🤖', body_zh = '半夜尖叫着醒来，还认不出你？这可能是夜惊。马上问问Anacan AI，怎样正确应对，以及为什么不要叫醒宝宝。' WHERE id = '08a08f0f-d89f-412b-a0e0-06835ec16be6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los «¿Por qué?» no se acaban 🤔', body_es = 'Quiere entender el mundo y darle lógica a todo. Aprende con Anacan AI a responder a sus preguntas sin fin con paciencia y sin aburrirte. Tu paciencia es su futuro.', title_fr = 'Les « Pourquoi ? » sans fin 🤔', body_fr = 'Il veut comprendre le monde et donner une logique à tout. Découvrez avec Anacan AI comment répondre à ses questions sans fin avec patience et sans vous lasser. Votre patience, c''est son avenir.', title_hi = '''क्यों?'' खत्म ही नहीं होता 🤔', body_hi = 'वह दुनिया को समझना और हर चीज़ को तर्क से जोड़ना चाहता है। Anacan AI से जानिए कि उसके कभी न खत्म होने वाले सवालों का बिना ऊबे, सब्र से जवाब कैसे दें। आपका सब्र ही उसका भविष्य है।', title_id = '''Kenapa?'' tak ada habisnya 🤔', body_id = 'Ia ingin memahami dunia dan mencari logika di balik segalanya. Pelajari dari Anacan AI cara menjawab pertanyaannya yang tak ada habisnya dengan sabar tanpa bosan. Kesabaran Anda adalah masa depannya.', title_ja = '終わらない「なんで？」🤔', body_ja = '世界を理解して、なんでも筋道立てて考えたいのです。終わらない質問に、うんざりせず気長に答える方法をAnacan AIから学びましょう。あなたの忍耐が、お子さんの未来になります。', title_ko = '끝나지 않는 ''왜?'' 🤔', body_ko = '세상을 이해하고 모든 걸 논리적으로 정리하고 싶어 해요. 끝없는 질문에 지치지 않고 인내심 있게 대답하는 방법을 Anacan AI에게 배워 보세요. 엄마의 인내가 곧 아이의 미래예요.', title_nl = 'Het ''Waarom?'' stopt niet 🤔', body_nl = 'Hij wil de wereld begrijpen en alles logisch kunnen plaatsen. Leer van Anacan AI hoe je zijn eindeloze vragen geduldig beantwoordt zonder je te vervelen. Jouw geduld is zijn toekomst.', title_pl = '„Dlaczego?” bez końca 🤔', body_pl = 'Chce zrozumieć świat i wszystko logicznie poukładać. Dowiedz się od Anacan AI, jak cierpliwie i bez znużenia odpowiadać na jego niekończące się pytania. Twoja cierpliwość to jego przyszłość.', title_pt = 'Os "Porquê?" não acabam 🤔', body_pt = 'Quer compreender o mundo e dar lógica a tudo. Aprenda com o Anacan AI a responder às perguntas sem fim dele com paciência e sem se aborrecer. A sua paciência é o futuro dele.', title_sv = '”Varför?” tar aldrig slut 🤔', body_sv = 'Barnet vill förstå världen och få logik i allt. Lär dig av Anacan AI hur du svarar på de ändlösa frågorna med tålamod och utan att tröttna. Ditt tålamod är barnets framtid.', title_vi = '"Tại sao?" mãi không dứt 🤔', body_vi = 'Bé muốn hiểu thế giới, muốn mọi thứ đều có lý lẽ. Hãy học từ Anacan AI cách kiên nhẫn trả lời những câu hỏi bất tận của bé mà không thấy chán. Sự kiên nhẫn của mẹ là tương lai của bé.', title_zh = '“为什么？”没完没了 🤔', body_zh = '宝宝想了解世界，想把一切都理出逻辑。向Anacan AI学学怎样不厌烦、耐心地回答那些问不完的问题。你的耐心，就是宝宝的未来。' WHERE id = '0b568eaa-4297-4b84-983b-14d42c18fb06' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Derecho a un café caliente ☕', body_es = '¿La habitación está desordenada? Que se quede así. Dedícate 10 minutos y tómate por fin ese café caliente. No tienes por qué ser perfecta.', title_fr = 'Le droit de boire son café chaud ☕', body_fr = 'La pièce est en désordre ? Laissez faire. Accordez-vous 10 minutes et buvez enfin ce café chaud. Vous n''êtes pas obligée d''être parfaite.', title_hi = 'गर्म कॉफ़ी पीने का हक ☕', body_hi = 'कमरा बिखरा है? रहने दीजिए। खुद को 10 मिनट दीजिए और आखिरकार वह कॉफ़ी गर्म-गर्म पीजिए। आपको परफ़ेक्ट होने की कोई मजबूरी नहीं है।', title_id = 'Hak minum kopi selagi panas ☕', body_id = 'Kamar berantakan? Biarkan saja. Luangkan 10 menit untuk diri Anda dan akhirnya minum kopi itu selagi panas. Anda tidak harus sempurna.', title_ja = '温かいコーヒーを飲む権利 ☕', body_ja = '部屋が散らかっている？そのままでいいんです。自分のために10分とって、そのコーヒーをやっと温かいうちに飲みましょう。完璧でいる必要はありません。', title_ko = '커피를 따뜻하게 마실 권리 ☕', body_ko = '방이 어질러졌나요? 그냥 두세요. 나를 위해 10분만 내서 그 커피를 드디어 따뜻할 때 드세요. 완벽하지 않아도 괜찮아요.', title_nl = 'Het recht op warme koffie ☕', body_nl = 'Is de kamer een rommeltje? Laat maar zo. Neem 10 minuten voor jezelf en drink die koffie eindelijk eens warm. Je hoeft niet perfect te zijn.', title_pl = 'Prawo do gorącej kawy ☕', body_pl = 'W pokoju bałagan? Niech tak zostanie. Daj sobie 10 minut i w końcu wypij tę kawę gorącą. Nie musisz być bez skazy.', title_pt = 'O direito ao café quente ☕', body_pt = 'O quarto está desarrumado? Deixe ficar. Reserve 10 minutos para si e beba finalmente esse café quente. Não tem de ser perfeita.', title_sv = 'Rätten till varmt kaffe ☕', body_sv = 'Är rummet stökigt? Låt det vara. Ta 10 minuter för dig själv och drick äntligen kaffet medan det är varmt. Du måste inte vara felfri.', title_vi = 'Quyền được uống cà phê nóng ☕', body_vi = 'Phòng bừa bộn? Cứ để đó. Hãy dành cho mình 10 phút và cuối cùng cũng được uống ly cà phê khi còn nóng. Mẹ không cần phải hoàn hảo.', title_zh = '喝杯热咖啡的权利 ☕', body_zh = '房间乱？就让它乱着吧。给自己留10分钟，终于能趁热喝那杯咖啡了。你不必做到完美。' WHERE id = 'e029b1ab-4432-4819-9a9e-c44e5506a20c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Chocolate a escondidas 🍫', body_es = '¿Te has escapado a la cocina para picar algo dulce de pie a escondidas? No te culpes. Una madre tiene todo el derecho a subir su azúcar para aguantar el jaleo del día.', title_fr = 'Le chocolat en cachette 🍫', body_fr = 'Vous avez filé à la cuisine pour grignoter un petit truc sucré en cachette, debout ? Ne vous blâmez pas. Pour supporter le bruit de la journée, une maman a parfaitement le droit de faire remonter sa glycémie.', title_hi = 'छिपकर खाई चॉकलेट 🍫', body_hi = 'रसोई में जाकर उससे छिपकर खड़े-खड़े कुछ मीठा खा लिया? खुद को दोष मत दीजिए। दिनभर का शोर सहने के लिए माँ का ब्लड शुगर बढ़ाना पूरी तरह जायज़ है।', title_id = 'Cokelat yang dimakan diam-diam 🍫', body_id = 'Diam-diam ke dapur dan ngemil sesuatu yang manis sambil berdiri tanpa sepengetahuannya? Jangan salahkan diri. Untuk bertahan di tengah hiruk-pikuk hari ini, ibu berhak menaikkan gula darahnya.', title_ja = 'こっそり食べるチョコレート 🍫', body_ja = 'キッチンでこっそり、立ったまま甘いものをつまみましたか？自分を責めないで。一日のにぎやかさに耐えるために、ママが血糖値を上げるのは当然の権利です。', title_ko = '몰래 먹는 초콜릿 🍫', body_ko = '주방에 가서 아이 몰래 서서 단것을 먹었나요? 자책하지 마세요. 하루의 소란을 견디려면 엄마도 혈당을 올릴 권리가 충분히 있어요.', title_nl = 'Stiekem chocola eten 🍫', body_nl = 'Glipte je de keuken in om stiekem staand iets zoets te eten? Veroordeel jezelf niet. Een moeder heeft alle recht op wat extra bloedsuiker om de drukte van de dag te doorstaan.', title_pl = 'Czekolada zjedzona po kryjomu 🍫', body_pl = 'Wymknęłaś się do kuchni i po kryjomu zjadłaś na stojąco coś słodkiego? Nie obwiniaj się. Żeby znieść hałas całego dnia, mama ma pełne prawo podnieść sobie cukier we krwi.', title_pt = 'O chocolate às escondidas 🍫', body_pt = 'Foi à cozinha e comeu um doce às escondidas, de pé? Não se culpe. Para aguentar o barulho do dia, a mãe tem todo o direito a um pouco de açúcar no sangue.', title_sv = 'Chokladen som äts i smyg 🍫', body_sv = 'Smet du in i köket och åt något sött stående i smyg? Klandra inte dig själv. En mamma har all rätt att höja blodsockret för att stå ut med dagens oväsen.', title_vi = 'Thanh sô-cô-la ăn lén 🍫', body_vi = 'Mẹ lén vào bếp ăn vội chút đồ ngọt mà không để bé thấy? Đừng tự trách. Để chịu đựng sự ồn ào cả ngày, mẹ hoàn toàn có quyền nạp thêm chút đường.', title_zh = '偷偷吃的巧克力 🍫', body_zh = '躲进厨房，背着宝宝站着偷吃了点甜的？别责怪自己。为了扛住一天的吵闹，妈妈完全有权利让血糖升一升。' WHERE id = '7d7930a8-9ab0-45ba-bbf4-3a10238d3d72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El escenario es de papá 🎭', body_es = 'Tu «Acábate la comida» ya no funciona. Pásale la pelota a papá. Cuando convierte la cuchara en un avión, la tozudez desaparece como por arte de magia. Descansa y mira.', title_fr = 'La scène est à papa 🎭', body_fr = 'Votre « Finis ton assiette » ne marche plus. Passez la balle à papa. Quand il transforme la cuillère en avion, l''entêtement disparaît comme par miracle. Reposez-vous et regardez.', title_hi = 'मंच पापा का है 🎭', body_hi = 'आपका ''खाना खत्म करो'' अब असर नहीं करता? बॉल पापा के पाले में डालिए। जब वे चम्मच को उड़ता हवाई जहाज़ बनाते हैं, तो ज़िद न जाने कैसे गायब हो जाती है। आराम कीजिए और देखिए।', title_id = 'Panggung milik Ayah 🎭', body_id = 'Kalimat ''Habiskan makananmu'' dari Anda sudah tidak mempan. Oper bolanya kepada Ayah. Saat ia menjadikan sendok pesawat terbang, sifat keras kepala entah bagaimana lenyap secara ajaib. Beristirahatlah dan saksikan.', title_ja = '主役はパパ 🎭', body_ja = 'あなたの「ごはん食べちゃって」はもう効かない？パパにバトンを渡しましょう。パパがスプーンを飛行機にすると、がんこさがなぜか魔法のように消えます。休みながら見守って。', title_ko = '무대의 주인공은 아빠 🎭', body_ko = '''밥 다 먹어야지''가 더는 통하지 않나요? 아빠에게 공을 넘기세요. 아빠가 숟가락을 비행기로 만들면 고집이 신기하게 사라져요. 쉬면서 구경하세요.', title_nl = 'Het podium is voor papa 🎭', body_nl = 'Jouw ''Eet je bord leeg'' werkt niet meer. Speel de bal naar papa. Zodra hij van de lepel een vliegtuigje maakt, verdwijnt de koppigheid als bij toverslag. Rust uit en kijk toe.', title_pl = 'Scena należy do taty 🎭', body_pl = 'Twoje „Dokończ jedzenie” już nie działa. Podaj piłeczkę tacie. Gdy zamienia łyżkę w latający samolot, upór w cudowny sposób znika. Odpocznij i patrz.', title_pt = 'O palco é do pai 🎭', body_pt = 'O seu "Acaba a comida" já não resulta. Passe a bola ao pai. Quando ele transforma a colher num avião, a teimosia desaparece como por milagre. Descanse e assista.', title_sv = 'Scenen tillhör pappa 🎭', body_sv = 'Ditt ”Ät upp maten” biter inte längre. Passa bollen till pappa. När han låter skeden bli ett flygplan försvinner envisheten på något mirakulöst sätt. Vila och titta på.', title_vi = 'Sân khấu thuộc về bố 🎭', body_vi = 'Câu "Ăn hết đi con" của mẹ không còn tác dụng. Hãy "chuyền bóng" cho bố. Khi bố biến chiếc thìa thành máy bay, sự bướng bỉnh bỗng biến mất thần kỳ. Mẹ cứ nghỉ ngơi và xem nhé.', title_zh = '舞台交给爸爸 🎭', body_zh = '你那句“把饭吃完”已经不管用了？把球传给爸爸。他把勺子变成飞机时，倔强不知怎么就神奇地消失了。休息一下，在旁边看着吧。' WHERE id = '946cf6ed-b93e-4326-a1b8-4af737be38ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis de la cuchara del color equivocado 🥄', body_es = '¿Se ha montado un drama porque le diste la comida con la cuchara amarilla y no con la verde? Respira hondo. No busques lógica: solo comprueba si puede controlar el mundo. Cambia la cuchara y sonríe.', title_fr = 'La crise de la cuillère de la mauvaise couleur 🥄', body_fr = 'C''est le drame parce que vous avez servi le repas avec la cuillère jaune et non la verte ? Respirez profondément. Ne cherchez pas de logique, il vérifie simplement qu''il peut contrôler son monde. Changez la cuillère et souriez.', title_hi = 'गलत रंग के चम्मच का संकट 🥄', body_hi = 'खाना हरे की जगह पीले चम्मच से दिया तो हंगामा मच गया? गहरी साँस लीजिए। तर्क मत ढूँढिए, वह बस परख रहा है कि वह दुनिया को नियंत्रित कर सकता है या नहीं। बस चम्मच बदल दीजिए और मुस्कुराइए।', title_id = 'Krisis sendok salah warna 🥄', body_id = 'Dunia serasa runtuh karena Anda memberinya makan dengan sendok kuning, bukan hijau? Tarik napas dalam. Jangan mencari logika, ia hanya menguji apakah ia bisa mengendalikan dunianya. Ganti saja sendoknya dan tersenyumlah.', title_ja = 'スプーンの色ちがいで大騒ぎ 🥄', body_ja = '緑ではなく黄色のスプーンでごはんを出したから大騒ぎ？深呼吸しましょう。理屈を探さないで、世界を動かせるかを試しているだけです。スプーンを替えて、ほほえみましょう。', title_ko = '숟가락 색깔 대참사 🥄', body_ko = '초록 숟가락이 아니라 노란 숟가락으로 줬다고 난리가 났나요? 깊게 숨 쉬세요. 논리를 찾지 마세요. 세상을 움직일 수 있는지 시험하는 거예요. 숟가락을 바꿔 주고 웃어 주세요.', title_nl = 'Drama om de verkeerde lepel 🥄', body_nl = 'Brak de hel los omdat je het eten met een gele in plaats van een groene lepel gaf? Haal diep adem. Zoek geen logica, hij test gewoon of hij de wereld kan sturen. Pak een andere lepel en glimlach.', title_pl = 'Kryzys łyżki w złym kolorze 🥄', body_pl = 'Rozpętała się burza, bo podałaś jedzenie żółtą, a nie zieloną łyżką? Weź głęboki oddech. Nie szukaj logiki, on po prostu sprawdza, czy potrafi rządzić światem. Po prostu zmień łyżkę i się uśmiechnij.', title_pt = 'A crise da colher da cor errada 🥄', body_pt = 'Foi o fim do mundo porque lhe deu a comida com a colher amarela e não com a verde? Respire fundo. Não procure lógica: está só a testar se consegue controlar o mundo. Troque a colher e sorria.', title_sv = 'Krisen med skeden i fel färg 🥄', body_sv = 'Blev det kaos för att du gav maten med en gul sked i stället för en grön? Andas djupt. Leta inte efter logik, barnet testar bara om hen kan styra världen. Byt bara sked och le.', title_vi = 'Khủng hoảng vì chiếc thìa sai màu 🥄', body_vi = 'Cả thế giới như sụp đổ chỉ vì mẹ dùng thìa vàng thay vì thìa xanh lá? Hãy hít thở sâu. Đừng tìm logic, bé chỉ đang thử xem mình có điều khiển được thế giới không. Cứ đổi thìa và mỉm cười.', title_zh = '勺子颜色不对引发的崩溃 🥄', body_zh = '因为用黄勺子而不是绿勺子喂饭，就闹翻了天？深呼吸。别在这时找道理，宝宝只是在测试自己能不能掌控世界。换个勺子，笑一笑就好。' WHERE id = 'c17a59df-f595-4941-acce-8426080226bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te ayudo! 🧽', body_es = '¿Mientras quitas el polvo te tira del paño? Quiere sentirse mayor. Dale un trapito húmedo. Ensuciará más de lo que limpie, pero su ego quedará encantado.', title_fr = 'Je t''aide 🧽', body_fr = 'Quand vous faites la poussière, il vous arrache le chiffon des mains ? Il veut se sentir grand. Donnez-lui un petit chiffon humide. Il salira plus qu''il ne nettoiera, mais il sera tellement fier.', title_hi = 'मैं मदद करूँ 🧽', body_hi = 'आप धूल झाड़ती हैं तो आपके हाथ से कपड़ा खींचता है? वह खुद को बड़ा महसूस करना चाहता है। उसे एक छोटा, गीला कपड़ा दीजिए। सफ़ाई से ज़्यादा गंदगी करेगा, लेकिन उसका मन खुश हो जाएगा।', title_id = 'Aku bantu ya 🧽', body_id = 'Saat Anda membersihkan debu, ia menarik lap dari tangan Anda? Ia ingin merasa sudah besar. Beri ia lap kecil yang lembap. Ia akan lebih banyak mengotori daripada membersihkan, tetapi hatinya akan senang.', title_ja = 'お手伝いするね 🧽', body_ja = 'ほこりを払っていると、手から布を引っぱりますか？大きくなった気分を味わいたいのです。小さくぬらした布を渡しましょう。掃除より汚すほうが多くても、自尊心が満たされます。', title_ko = '내가 도와줄게 🧽', body_ko = '엄마가 먼지를 털 때 손에서 걸레를 잡아당기나요? 다 큰 기분을 느끼고 싶은 거예요. 작은 젖은 걸레를 쥐여 주세요. 청소보다 더 어지르겠지만 자존감은 쑥 자랄 거예요.', title_nl = 'Ik help je wel 🧽', body_nl = 'Trekt hij de stofdoek uit je hand als je afstoft? Hij wil zich groot voelen. Geef hem een klein, vochtig doekje. Hij maakt meer rommel dan schoon, maar zijn ego wordt gestreeld.', title_pl = 'Pomogę ci 🧽', body_pl = 'Gdy ścierasz kurze, wyrywa ci ściereczkę z ręki? Chce poczuć się duży. Daj mu małą, wilgotną ściereczkę. Bardziej nabrudzi, niż posprząta, ale jego ego zostanie połechtane.', title_pt = 'Deixa-me ajudar 🧽', body_pt = 'Enquanto tira o pó, puxa-lhe o pano da mão? Quer sentir-se crescido. Dê-lhe um paninho húmido. Vai sujar mais do que limpar, mas o ego dele fica feliz.', title_sv = 'Jag hjälper dig 🧽', body_sv = 'Drar barnet trasan ur din hand när du dammar? Hen vill känna sig stor. Ge hen en liten fuktig trasa. Det blir mer kladd än städning, men självkänslan får en boost.', title_vi = 'Để con giúp mẹ 🧽', body_vi = 'Khi mẹ phủi bụi, bé giật lấy khăn trong tay mẹ? Bé muốn thấy mình là người lớn. Hãy đưa bé một chiếc khăn nhỏ hơi ẩm. Bé sẽ làm bẩn nhiều hơn là lau sạch, nhưng cái tôi của bé sẽ được vỗ về.', title_zh = '我来帮你 🧽', body_zh = '你擦灰时，宝宝从你手里抢抹布？宝宝想感觉自己长大了。给宝宝一块湿的小抹布。弄湿的地方会比擦干净的多，但宝宝的自尊心得到了满足。' WHERE id = '202cf19c-e94a-473d-b9ba-56a3c22509c2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La acústica de casa 🤫', body_es = 'Por fin se ha dormido la siesta. Ahora hasta el menor ruidito de casa puede sacarte de quicio. Activa ya el Medidor de sonido, cierra las ventanas y disfruta de este silencio absoluto.', title_fr = 'L''acoustique de la maison 🤫', body_fr = 'Il a fini par faire la sieste, difficilement. Maintenant, le moindre petit bruit dans la maison peut vous rendre folle. Activez vite le Sonomètre, fermez les fenêtres et savourez ce silence absolu.', title_hi = 'घर की आवाज़ें 🤫', body_hi = 'बड़ी मुश्किल से दोपहर में सोया। अब घर की ज़रा सी खटखट भी आपको परेशान कर सकती है। तुरंत साउंड मीटर चालू कीजिए, खिड़कियाँ बंद कीजिए और इस पूरी खामोशी का आनंद लीजिए।', title_id = 'Akustik rumah 🤫', body_id = 'Ia akhirnya tidur siang dengan susah payah. Kini bunyi derit sekecil apa pun di rumah bisa membuat Anda gila. Segera aktifkan Pengukur Suara, tutup jendela, dan nikmati keheningan total ini.', title_ja = '家の音環境 🤫', body_ja = 'やっとお昼寝してくれました。今は家の小さな物音さえ気になりますよね。すぐに「サウンドメーター」をオンにして、窓を閉め、この完全な静けさを味わいましょう。', title_ko = '집 안의 소리 환경 🤫', body_ko = '겨우 낮잠에 들었어요. 이제 집 안의 작은 똑딱 소리 하나에도 예민해지죠. 바로 소음 측정기를 켜고 창문을 닫은 뒤 이 완벽한 고요를 즐기세요.', title_nl = 'De akoestiek van je huis 🤫', body_nl = 'Met moeite ging hij voor zijn middagslaapje. Nu kan zelfs het kleinste getik in huis je gek maken. Zet meteen de Geluidsmeter aan, doe de ramen dicht en geniet van deze totale stilte.', title_pl = 'Akustyka domu 🤫', body_pl = 'Z trudem zasnął na popołudniową drzemkę. Teraz nawet najmniejsze stuknięcie w domu może cię doprowadzić do szału. Od razu włącz Miernik dźwięku, zamknij okna i delektuj się tą absolutną ciszą.', title_pt = 'A acústica da casa 🤫', body_pt = 'Finalmente adormeceu para a sesta. Agora qualquer pequeno ruído em casa a pode enlouquecer. Ative já o Medidor de Som, feche as janelas e saboreie este silêncio absoluto.', title_sv = 'Hemmets akustik 🤫', body_sv = 'Barnet somnade till slut middag. Nu kan minsta knäpp hemma göra dig galen. Aktivera genast Ljudmätaren, stäng fönstren och njut av den totala tystnaden.', title_vi = 'Âm thanh trong nhà 🤫', body_vi = 'Mãi bé mới chịu ngủ trưa. Giờ chỉ một tiếng lạch cạch nhỏ trong nhà cũng có thể khiến mẹ phát điên. Hãy bật ngay Đo âm thanh, đóng cửa sổ và tận hưởng sự yên tĩnh tuyệt đối này.', title_zh = '家里的声音环境 🤫', body_zh = '好不容易才睡着午觉。现在家里一点小小的咔嗒声都能让你抓狂。马上打开分贝仪，关好窗户，享受这份绝对的安静吧。' WHERE id = '4f32f07a-4c87-40d2-83db-3d4785cda04f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La guerra de los zapatos 👟', body_es = '¿Se ha puesto el zapato derecho en el pie izquierdo y no hay manera de que se lo quite? Déjalo así. Ahora mismo la estética o hacerlo bien no importan más que su sensación de libertad.', title_fr = 'La guerre des chaussures 👟', body_fr = 'Il a mis la chaussure droite au pied gauche et refuse catégoriquement de l''enlever ? Laissez faire. Pour l''instant, l''esthétique ou la bonne façon de faire comptent moins que son sentiment de liberté.', title_hi = 'जूते पहनने की जंग 👟', body_hi = 'दाएँ पैर का जूता बाएँ पैर में पहन लिया और बिल्कुल उतारना नहीं चाहता? रहने दीजिए। अभी दिखावट या सही होना उसकी आज़ादी के एहसास से ज़्यादा ज़रूरी नहीं है।', title_id = 'Perang memakai sepatu 👟', body_id = 'Ia memakai sepatu kanan di kaki kiri dan sama sekali tidak mau melepasnya? Biarkan saja. Saat ini penampilan atau ketepatan tidak lebih penting daripada rasa bebasnya.', title_ja = '靴はきバトル 👟', body_ja = '右の靴を左足にはいて、絶対に脱ぎたがらない？そのままにしておきましょう。今は見た目や正しさより、自由に感じることのほうが大切です。', title_ko = '신발 신기 전쟁 👟', body_ko = '오른쪽 신발을 왼발에 신고 절대 벗지 않겠다고 하나요? 그냥 두세요. 지금은 모양이나 바름보다 자유롭다는 느낌이 더 중요해요.', title_nl = 'De strijd om de schoenen 👟', body_nl = 'Heeft hij de rechterschoen aan zijn linkervoet en wil hij hem absoluut niet uittrekken? Laat maar zo. Hoe het eruitziet of of het klopt is nu niet belangrijker dan zijn gevoel van vrijheid.', title_pl = 'Wojna o zakładanie butów 👟', body_pl = 'Założył prawy but na lewą nogę i za nic nie chce go zdjąć? Niech tak zostanie. Estetyka czy poprawność nie są teraz ważniejsze niż jego poczucie wolności.', title_pt = 'A guerra dos sapatos 👟', body_pt = 'Calçou o sapato direito no pé esquerdo e não o quer tirar de maneira nenhuma? Deixe ficar. Neste momento, a estética ou o certo não são mais importantes do que a sensação de liberdade dele.', title_sv = 'Skokriget 👟', body_sv = 'Har barnet satt högerskon på vänsterfoten och vägrar ta av den? Låt det vara. Estetik och korrekthet är just nu inte viktigare än barnets känsla av frihet.', title_vi = 'Cuộc chiến đi giày 👟', body_vi = 'Bé đi giày phải vào chân trái và nhất quyết không chịu tháo ra? Cứ để vậy. Lúc này thẩm mỹ hay sự đúng sai không quan trọng bằng cảm giác tự do của bé.', title_zh = '穿鞋大战 👟', body_zh = '右脚的鞋穿到了左脚上，还死活不肯脱？就让它这样吧。现在，好看或正确都没有宝宝的自由感重要。' WHERE id = 'f750ae50-4664-4363-8c07-389c3fa0e9cb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con la oscuridad 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y cuéntale en voz muy bajita, susurrando, lo que ha pasado durante el día. Susurrar es el método más natural para preparar el cerebro para dormir.', title_fr = 'Faire la paix avec le noir 🌙', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et racontez-lui sa journée tout bas, en chuchotant. Le chuchotement est la façon la plus naturelle de préparer le cerveau au sommeil.', title_hi = 'अंधेरे से दोस्ती 🌙', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें बहुत धीमी आवाज़ में, फुसफुसाकर उसे सुनाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे स्वाभाविक तरीका है।', title_id = 'Berdamai dengan gelap 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan ceritakan kejadian hari ini dengan suara sangat pelan, berbisik. Berbisik adalah cara paling alami menyiapkan otak untuk tidur.', title_ja = '暗やみと仲直り 🌙', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、今日あったことをとても小さな声でささやくように話してあげて。ささやき声は、脳を眠りへ導くいちばん自然な方法です。', title_ko = '어둠과 친해지기 🌙', body_ko = '방의 불을 모두 꺼 주세요. 옆에 누워 오늘 있었던 일을 아주 작은 목소리로 속삭이듯 들려주세요. 속삭임은 뇌가 잠들 준비를 하게 돕는 가장 자연스러운 방법이에요.', title_nl = 'Vrede sluiten met het donker 🌙', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en vertel heel zachtjes, fluisterend, wat er vandaag is gebeurd. Fluisteren is de meest natuurlijke manier om de hersenen klaar te maken voor de slaap.', title_pl = 'Oswoić ciemność 🌙', body_pl = 'Zgaś wszystkie światła w pokoju. Połóż się obok i bardzo cicho, szeptem opowiedz mu, co wydarzyło się w ciągu dnia. Szept to najbardziej naturalny sposób, by przygotować mózg do snu.', title_pt = 'Fazer as pazes com o escuro 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e conte-lhe, em voz muito baixa e a sussurrar, o que aconteceu durante o dia. Sussurrar é o método mais natural para preparar o cérebro para o sono.', title_sv = 'Försonas med mörkret 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och berätta mycket tyst, viskande, om det som hänt under dagen. Viskningar är det mest naturliga sättet att förbereda hjärnan för sömn.', title_vi = 'Làm hòa với bóng tối 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ kể về những gì đã xảy ra trong ngày. Thì thầm là cách tự nhiên nhất giúp não bộ chuẩn bị cho giấc ngủ.', title_zh = '和黑暗和解 🌙', body_zh = '把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音，悄悄讲讲今天发生的事。悄悄话是帮大脑准备入睡最自然的方法。' WHERE id = 'bcbba6df-cc6d-45d3-b424-d121d2ee2ecb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño artista 🎨', body_es = '¿Dibuja círculos con el lápiz en la pared o en el papel? Es un gran salto en su motricidad.', title_fr = 'Petit artiste 🎨', body_fr = 'Il trace des cercles au crayon sur le mur ou sur une feuille ? C''est un grand bond de motricité.', title_hi = 'नन्हा चित्रकार 🎨', body_hi = 'पेन से दीवार या कागज़ पर गोले बनाता है? यह मोटर स्किल्स में बड़ी छलांग है।', title_id = 'Pelukis kecil 🎨', body_id = 'Ia menggambar lingkaran dengan pensil di dinding atau kertas? Ini lompatan motorik yang besar.', title_ja = '小さな画家さん 🎨', body_ja = 'クレヨンで壁や紙にまるを描いていますか？これは運動能力の大きな飛躍です。', title_ko = '꼬마 화가 🎨', body_ko = '연필로 벽이나 종이에 동그라미를 그리나요? 운동 발달의 큰 도약이에요.', title_nl = 'Kleine kunstenaar 🎨', body_nl = 'Tekent hij met een potlood rondjes op de muur of op papier? Een grote sprong in zijn motoriek.', title_pl = 'Mały artysta 🎨', body_pl = 'Rysuje kredką kółka na ścianie albo na papierze? To wielki skok w motoryce.', title_pt = 'Pequeno artista 🎨', body_pt = 'Desenha círculos com o lápis na parede ou no papel? É um grande salto na motricidade.', title_sv = 'Liten konstnär 🎨', body_sv = 'Ritar barnet cirklar med pennan på väggen eller papperet? Det är ett stort motoriskt språng.', title_vi = 'Họa sĩ nhí 🎨', body_vi = 'Bé dùng bút vẽ vòng tròn trên tường hoặc giấy? Đây là một bước nhảy vọt lớn về vận động.', title_zh = '小画家 🎨', body_zh = '拿着笔在墙上或纸上画圆圈？这是动作发展的一大飞跃。' WHERE id = 'db4f7065-c5e8-4316-a750-ff341f726db5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Empieza la búsqueda de guardería? 🏫', body_es = '¿Se acercan los 3 años y no dejas de pensar en la guardería? Si te cansa darle vueltas tú sola, entra en la Comunidad Anacan y pregunta a otras madres por su experiencia y recomendaciones.', title_fr = 'La recherche de crèche commence ? 🏫', body_fr = 'L''idée de la crèche vous trotte dans la tête à l''approche des 3 ans ? Fatiguée d''y réfléchir seule ? Rejoignez la Communauté Anacan et demandez aux autres mamans leur expérience et leurs conseils.', title_hi = 'प्लेस्कूल की तलाश शुरू? 🏫', body_hi = '3 साल के करीब आते ही प्लेस्कूल का ख्याल मन में घूम रहा है? अकेले सोचते-सोचते थक गई हैं, तो Anacan कम्युनिटी में जाइए और दूसरी माँओं से उनके अनुभव और सुझाव पूछिए।', title_id = 'Mulai mencari TK? 🏫', body_id = 'Menjelang usia 3 tahun, pikiran soal TK terus berputar di kepala? Jika lelah memikirkannya sendiri, masuklah ke Komunitas Anacan dan tanyakan pengalaman serta saran ibu-ibu lain.', title_ja = '保育園探しを始める？🏫', body_ja = '3歳が近づいて、保育園のことが頭から離れない？ひとりで考えるのに疲れたら、Anacanコミュニティに参加して、ほかのママたちの経験やおすすめを聞いてみましょう。', title_ko = '어린이집을 알아보기 시작했나요? 🏫', body_ko = '세 돌을 앞두고 어린이집 생각이 머릿속을 맴도나요? 혼자 고민하느라 지쳤다면 Anacan 커뮤니티에 들어와 다른 엄마들의 경험과 추천을 물어보세요.', title_nl = 'Begint de zoektocht naar opvang? 🏫', body_nl = 'Spookt het idee van een peuterspeelzaal of opvang rond de 3 jaar door je hoofd? Ben je moe van het alleen nadenken? Ga naar de Anacan Community en vraag andere moeders naar hun ervaringen en tips.', title_pl = 'Zaczynasz szukać przedszkola? 🏫', body_pl = 'Myśl o przedszkolu w wieku 3 lat nie daje ci spokoju? Jeśli masz dość rozważania tego w pojedynkę, wejdź do Społeczności Anacan i zapytaj inne mamy o ich doświadczenia i rady.', title_pt = 'Começa a procura de creche? 🏫', body_pt = 'Perto dos 3 anos, a ideia da creche não lhe sai da cabeça? Se está cansada de pensar nisso sozinha, entre na Comunidade Anacan e pergunte às outras mães pelas suas experiências e recomendações.', title_sv = 'Börjar förskolejakten? 🏫', body_sv = 'Snurrar tankar om förskola i huvudet nu när barnet närmar sig 3 år? Om du är trött på att fundera ensam, gå in i Anacan Community och fråga andra mammor om deras erfarenheter och tips.', title_vi = 'Bắt đầu tìm nhà trẻ? 🏫', body_vi = 'Gần 3 tuổi, chuyện cho bé đi nhà trẻ cứ quanh quẩn trong đầu mẹ? Nếu mẹ đã mệt vì phải tự mình suy nghĩ, hãy vào Cộng đồng Anacan và hỏi kinh nghiệm, lời khuyên của các mẹ khác.', title_zh = '开始找幼儿园了？🏫', body_zh = '快3岁了，脑子里总想着幼儿园的事？如果一个人想累了，就进入Anacan社区，问问其他妈妈的经验和建议吧。' WHERE id = 'eacddbb3-0cac-4a07-a3b8-0e2751f215e2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Merienda de té imaginaria ☕', body_es = '¿Te da una taza vacía y te dice «Bebe té»? El juego simbólico es una obra maestra del desarrollo. Bébete con muchas ganas ese té imaginario del tiempo.', title_fr = 'Dînette imaginaire ☕', body_fr = 'Il vous tend une tasse vide en disant « Bois ton thé » ? Le jeu symbolique est un chef-d''œuvre du développement. Buvez avec grand plaisir ce thé imaginaire à température ambiante.', title_hi = 'काल्पनिक चाय पार्टी ☕', body_hi = 'खाली कप आपकी ओर बढ़ाकर कहता है ''चाय पियो''? प्रतीकात्मक खेल विकास का बेहतरीन नमूना है। उस कप की कमरे के तापमान वाली काल्पनिक चाय को खूब मज़े से पीजिए।', title_id = 'Pesta teh khayalan ☕', body_id = 'Ia menyodorkan cangkir kosong dan berkata ''Minum tehnya''? Permainan simbolis adalah karya agung perkembangan. Minumlah teh khayalan bersuhu ruang itu dengan penuh kenikmatan.', title_ja = '空想のお茶会 ☕', body_ja = 'からっぽのカップを差し出して「お茶どうぞ」と言いますか？ごっこ遊びは発達の傑作です。カップの中の空想のお茶を、おいしそうに飲んであげましょう。', title_ko = '상상 속 티타임 ☕', body_ko = '빈 컵을 내밀며 ''차 마셔'' 하나요? 상징 놀이는 발달의 걸작이에요. 컵 속 상상의 차를 아주 맛있게 마셔 주세요.', title_nl = 'Denkbeeldige theepartij ☕', body_nl = 'Geeft hij je een leeg kopje en zegt hij ''Drink thee''? Symbolisch spel is een meesterwerk van de ontwikkeling. Drink die denkbeeldige thee op kamertemperatuur met veel smaak op.', title_pl = 'Wyimaginowane przyjęcie herbaciane ☕', body_pl = 'Podaje ci pustą filiżankę i mówi: „Pij herbatkę”? Zabawa symboliczna to arcydzieło rozwoju. Wypij tę wyimaginowaną herbatkę o temperaturze pokojowej z wielką przyjemnością.', title_pt = 'Lanche imaginário ☕', body_pt = 'Estende-lhe uma chávena vazia e diz "Bebe o chá"? O jogo simbólico é uma obra-prima do desenvolvimento. Beba com muito gosto esse chá imaginário à temperatura ambiente.', title_sv = 'Låtsastebjudning ☕', body_sv = 'Räcker barnet dig en tom kopp och säger ”Drick te”? Symbolisk lek är utvecklingens mästerverk. Drick det rumstempererade låtsasteet i koppen med stor njutning.', title_vi = 'Bữa tiệc trà tưởng tượng ☕', body_vi = 'Bé đưa mẹ chiếc tách rỗng và nói "Mẹ uống trà đi"? Trò chơi biểu tượng là kiệt tác của sự phát triển. Hãy thật thích thú uống chén trà tưởng tượng ấy nhé.', title_zh = '想象中的茶会 ☕', body_zh = '把空杯子递给你说“喝茶”？象征性游戏是发育的杰作。津津有味地喝下杯子里那杯“常温”的想象之茶吧。' WHERE id = '37d0e7fb-1a1f-4126-b2cd-6303007be080' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ropa llena de manchas 🎨', body_es = '¿El pijama lleno de comida y la ropa llena de pintura? Los niños no tienen que crecer limpios: tienen que ensuciarse descubriendo. Usa baberos de silicona y deja el resto a la lavadora.', title_fr = 'Vêtements couverts de taches 🎨', body_fr = 'Son pyjama est couvert de nourriture et ses habits de peinture ? Les enfants ne sont pas faits pour grandir propres, ils doivent se salir en découvrant. Utilisez des bavoirs en silicone et laissez le reste à la machine à laver.', title_hi = 'कपड़ों पर दाग ही दाग 🎨', body_hi = 'पजामे पर खाना और कपड़ों पर रंग के दाग? बच्चों को साफ़-सुथरा नहीं, खोजते हुए गंदा होकर बड़ा होना चाहिए। सिलिकॉन बिब इस्तेमाल कीजिए और बाकी वॉशिंग मशीन पर छोड़ दीजिए।', title_id = 'Baju penuh noda 🎨', body_id = 'Piyamanya penuh noda makanan, bajunya penuh cat? Anak tidak harus tumbuh bersih, mereka harus kotor sambil bereksplorasi. Gunakan celemek silikon, sisanya serahkan pada mesin cuci.', title_ja = '服はシミだらけ 🎨', body_ja = 'パジャマは食べこぼし、服は絵の具のシミだらけ？子どもはきれいなまま育つものではなく、探検して汚れるものです。シリコンのスタイを使って、あとは洗濯機にお任せしましょう。', title_ko = '얼룩투성이 옷 🎨', body_ko = '잠옷은 음식 얼룩, 옷은 물감 얼룩투성이인가요? 아이는 깨끗하게만 자랄 필요가 없어요. 탐험하며 더러워져야 해요. 실리콘 턱받이를 쓰고 나머지는 세탁기에 맡기세요.', title_nl = 'Kleren vol vlekken 🎨', body_nl = 'Zit zijn pyjama onder het eten en zijn hele lijf onder de verf? Kinderen hoeven niet schoon op te groeien, ze horen vies te worden van het ontdekken. Gebruik siliconen slabben en laat de rest aan de wasmachine over.', title_pl = 'Ubrania w plamach 🎨', body_pl = 'Piżama w jedzeniu, ubranie w plamach farby? Dzieci nie mają rosnąć czyste, mają się brudzić, odkrywając świat. Używaj silikonowych śliniaków, a resztę zostaw pralce.', title_pt = 'Roupa cheia de nódoas 🎨', body_pt = 'O pijama tem comida e a roupa tem tinta? As crianças não têm de crescer limpas, têm de se sujar a descobrir. Use babetes de silicone e deixe o resto para a máquina de lavar.', title_sv = 'Kläderna är fulla av fläckar 🎨', body_sv = 'Är pyjamasen full av mat och kläderna av färgfläckar? Barn ska inte växa upp rena, de ska bli smutsiga när de upptäcker. Använd silikonhaklappar och överlåt resten åt tvättmaskinen.', title_vi = 'Quần áo đầy vết bẩn 🎨', body_vi = 'Đồ ngủ dính đầy thức ăn, người lấm lem màu vẽ? Trẻ con không cần lớn lên sạch sẽ, bé cần lấm bẩn khi khám phá. Hãy dùng yếm silicon, phần còn lại cứ giao cho máy giặt.', title_zh = '衣服上满是污渍 🎨', body_zh = '睡衣上全是饭渍，身上满是颜料？孩子不该干干净净地长大，而是要在探索中弄脏自己。用硅胶围兜，剩下的就交给洗衣机吧。' WHERE id = 'aaf79d19-89d8-4b33-8891-ceb716e86559' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapada de 15 minutos 🛀', body_es = '¿Te has metido en el baño, has cerrado la puerta y solo miras el móvil? Sí, es el método de fuga y descanso más famoso de las madres. Quédate en ese silencio sin dar explicaciones a nadie.', title_fr = '15 minutes d''évasion 🛀', body_fr = 'Vous vous êtes enfermée aux toilettes juste pour regarder votre téléphone ? Oui, c''est la méthode d''évasion et de détente la plus célèbre des mamans. Restez dans ce silence sans rendre de comptes à personne.', title_hi = '15 मिनट का फ़रार 🛀', body_hi = 'टॉयलेट में जाकर दरवाज़ा बंद किया और बस फ़ोन देख रही हैं? हाँ, यह माँ का सबसे मशहूर भागने और आराम करने का तरीका है। किसी को हिसाब दिए बिना उस खामोशी में रहिए।', title_id = 'Kabur 15 menit 🛀', body_id = 'Masuk ke kamar mandi, mengunci pintu, dan hanya melihat ponsel? Ya, ini metode kabur dan istirahat paling terkenal para ibu. Nikmati keheningan itu tanpa perlu melapor kepada siapa pun.', title_ja = '15分の逃避行 🛀', body_ja = 'トイレに入ってドアを閉め、ただスマホを見ていますか？そう、これはママのいちばん有名な逃避と休息の方法。だれにも報告せず、その静けさの中にいましょう。', title_ko = '15분의 탈출 🛀', body_ko = '화장실에 들어가 문을 잠그고 휴대폰만 보고 있나요? 맞아요, 엄마들의 가장 유명한 탈출 겸 휴식법이죠. 누구에게도 설명할 필요 없이 그 고요 속에 머무세요.', title_nl = 'Je ontsnapping van 15 minuten 🛀', body_nl = 'Zit je met de deur op slot op de wc, gewoon op je telefoon te kijken? Ja, dat is de bekendste ontsnapping en rustpauze van moeders. Blijf in die stilte, zonder aan iemand verantwoording af te leggen.', title_pl = '15-minutowa ucieczka 🛀', body_pl = 'Weszłaś do łazienki, zamknęłaś drzwi i po prostu przeglądasz telefon? Tak, to najsłynniejsza metoda ucieczki i odpoczynku mam. Zostań w tej ciszy i nikomu się nie tłumacz.', title_pt = 'Fuga de 15 minutos 🛀', body_pt = 'Entrou na casa de banho, fechou a porta e está só a ver o telemóvel? Sim, é o método de fuga e descanso mais famoso das mães. Fique nesse silêncio sem dar satisfações a ninguém.', title_sv = '15 minuters flykt 🛀', body_sv = 'Har du gått in på toaletten, stängt dörren och bara tittar på mobilen? Ja, det är mammans mest kända metod för flykt och vila. Stanna i tystnaden utan att redovisa för någon.', title_vi = '15 phút trốn chạy 🛀', body_vi = 'Mẹ vào nhà vệ sinh, khóa cửa và chỉ lướt điện thoại? Đúng vậy, đây là cách trốn chạy và nghỉ ngơi nổi tiếng nhất của các mẹ. Hãy ở lại trong sự yên tĩnh ấy mà không cần giải thích với ai.', title_zh = '15分钟的逃离 🛀', body_zh = '躲进洗手间关上门，只是看看手机？没错，这是妈妈们最有名的逃离和休息方法。不用向任何人交代，好好待在这份安静里吧。' WHERE id = 'd6cb9a79-b32c-4069-9d3c-ac4297c600b6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La firmeza del «¡No me beses!» 🛑', body_es = '¿Gira la cara y empuja cuando algún familiar quiere besarle? ¡No invadas los límites de su cuerpo! Que proteste ante el contacto sin permiso es clave para un futuro sano.', title_fr = 'La fermeté du « Ne m''embrasse pas ! » 🛑', body_fr = 'Il détourne le visage et repousse un proche qui veut l''embrasser ? Ne touchez pas aux limites de son corps ! Pouvoir refuser les contacts non désirés est essentiel pour son avenir.', title_hi = '''मुझे मत चूमो!'' वाली दृढ़ता 🛑', body_hi = 'कोई रिश्तेदार उसे चूमना चाहे तो मुँह फेर लेता है और धक्का देता है? उसके शरीर की सीमाओं में दखल मत दीजिए! बिना इजाज़त छूने का विरोध करना उसके स्वस्थ भविष्य के लिए ज़रूरी है।', title_id = 'Tegas berkata ''Jangan cium aku!'' 🛑', body_id = 'Saat kerabat ingin menciumnya, ia memalingkan wajah dan mendorong? Jangan langgar batas tubuhnya! Keberaniannya menolak sentuhan tanpa izin penting bagi masa depannya yang sehat.', title_ja = '「チューしないで！」のきっぱりさん 🛑', body_ja = '親せきにキスされそうになると顔をそむけて押しのけますか？体の境界線に踏みこまないで！許可のないふれあいを拒めることは、健やかな未来のために欠かせません。', title_ko = '''뽀뽀하지 마!'' 단호함 🛑', body_ko = '친척이 뽀뽀하려 하면 고개를 돌리고 밀어내나요? 아이의 몸의 경계를 침범하지 마세요! 허락 없는 접촉에 거부할 줄 아는 건 건강한 미래에 꼭 필요해요.', title_nl = 'Vastberaden: ''Niet zoenen!'' 🛑', body_nl = 'Draait hij zijn hoofd weg en duwt hij een familielid weg dat hem wil zoenen? Kom niet aan zijn lichamelijke grenzen! Protesteren tegen aanrakingen zonder toestemming is nodig voor een gezonde toekomst.', title_pl = 'Stanowcze „Nie całuj mnie!” 🛑', body_pl = 'Gdy ktoś z rodziny chce go pocałować, odwraca buzię i odpycha? Nie naruszaj granic jego ciała! Sprzeciw wobec dotyku bez zgody jest niezbędny dla jego zdrowej przyszłości.', title_pt = 'A firmeza do "Não me beijes!" 🛑', body_pt = 'Quando um familiar o quer beijar, vira a cara e empurra? Não invada os limites do corpo dele! Protestar contra toques sem autorização é essencial para um futuro saudável.', title_sv = 'Bestämt ”Pussa mig inte!” 🛑', body_sv = 'Vänder barnet bort ansiktet och knuffar undan när en släkting vill pussa hen? Gå inte över barnets kroppsliga gränser! Att hen säger ifrån mot beröring utan lov är avgörande för en sund framtid.', title_vi = 'Sự kiên quyết "Đừng hôn con!" 🛑', body_vi = 'Khi người thân muốn hôn, bé quay mặt đi và đẩy ra? Đừng xâm phạm ranh giới cơ thể của bé! Việc bé phản đối những đụng chạm không được cho phép là điều kiện cho một tương lai khỏe mạnh.', title_zh = '“别亲我！”的坚决 🛑', body_zh = '亲戚想亲宝宝时，宝宝扭过脸还推开？别侵犯宝宝的身体界限！宝宝会拒绝未经允许的触碰，这对健康的未来至关重要。' WHERE id = '0db2d13e-0a0c-45f3-a6f3-c4bf73384a78' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La realidad de los terrores nocturnos 😭', body_es = 'Se ha despertado llorando en mitad de la noche con los ojos cerrados y no oye a nadie. Es un terror nocturno. No le zarandees ni intentes despertarle. Solo quédate a su lado y dale seguridad.', title_fr = 'La réalité des terreurs nocturnes 😭', body_fr = 'Il s''est réveillé en pleurant en pleine nuit, les yeux fermés, et n''entend personne. C''est une terreur nocturne. Ne le secouez pas, n''essayez pas de le réveiller. Restez simplement près de lui pour le rassurer.', title_hi = 'नाइट टेरर की सच्चाई 😭', body_hi = 'आधी रात को आँखें बंद किए रोते हुए जाग गया और किसी की नहीं सुनता? यह नाइट टेरर है। उसे झकझोरिए मत, जगाने की कोशिश मत कीजिए। बस उसके पास रहिए और भरोसा दीजिए।', title_id = 'Kenyataan teror malam 😭', body_id = 'Ia terbangun tengah malam menangis dengan mata terpejam dan tidak mendengar siapa pun. Ini teror malam. Jangan mengguncangnya atau mencoba membangunkannya. Cukup berada di sisinya dan beri rasa aman.', title_ja = '夜驚症の現実 😭', body_ja = '夜中に目を閉じたまま泣いて起き、だれの声も聞こえていない？これは夜驚症です。ゆさぶったり、起こそうとしたりしないで。ただそばにいて安心させてあげましょう。', title_ko = '야경증의 현실 😭', body_ko = '한밤중에 눈을 감은 채 울며 깨서 아무 말도 듣지 못하나요? 야경증이에요. 흔들거나 깨우려 하지 마세요. 그저 곁에 있어 주며 안심시켜 주세요.', title_nl = 'De realiteit van nachtangst 😭', body_nl = 'Wordt hij midden in de nacht met gesloten ogen huilend wakker en hoort hij niemand? Dat is nachtangst. Schud hem niet en probeer hem niet wakker te maken. Blijf gewoon bij hem en geef hem vertrouwen.', title_pl = 'Rzeczywistość lęku nocnego 😭', body_pl = 'Budzi się w nocy z płaczem, z zamkniętymi oczami, i nikogo nie słyszy? To lęk nocny. Nie potrząsaj nim i nie próbuj go budzić. Po prostu bądź obok i daj mu poczucie bezpieczeństwa.', title_pt = 'A realidade do terror noturno 😭', body_pt = 'Acordou a meio da noite a chorar de olhos fechados e não ouve ninguém? É um terror noturno. Não o abane nem tente acordá-lo. Fique apenas ao lado dele e dê-lhe segurança.', title_sv = 'Nattskräckens verklighet 😭', body_sv = 'Barnet har vaknat gråtande mitt i natten med slutna ögon och hör ingen. Det är nattskräck. Skaka inte barnet och försök inte väcka hen. Var bara där och ge trygghet.', title_vi = 'Sự thật về hoảng sợ ban đêm 😭', body_vi = 'Bé khóc thức giấc giữa đêm, mắt nhắm nghiền và không nghe thấy ai? Đây là hoảng sợ ban đêm. Đừng lay bé, đừng cố đánh thức bé. Chỉ cần ở bên và trấn an bé.', title_zh = '夜惊的真相 😭', body_zh = '半夜闭着眼睛哭醒，谁的话都听不见？这是夜惊。别摇晃宝宝，也别试图叫醒。只要陪在身边，给宝宝安全感就好。' WHERE id = 'aaaf42f2-3e96-489f-b1d3-e331bf487627' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detox de naturaleza obligatorio 🌳', body_es = '¿Hoy el caos de casa es insoportable? Consulta ya Tiempo y ropa, abrigaos bien y corred al parque más cercano. El aire fresco es el mejor calmante para un niño.', title_fr = 'Une détox nature s''impose 🌳', body_fr = 'Le chaos de la maison est insupportable aujourd''hui ? Consultez vite Météo et tenue, habillez-vous comme il faut et filez au parc le plus proche. L''air frais est le meilleur calmant pour un enfant.', title_hi = 'प्रकृति वाला डिटॉक्स ज़रूरी है 🌳', body_hi = 'आज घर की अफ़रा-तफ़री बर्दाश्त से बाहर हो गई? तुरंत मौसम और कपड़े टूल देखिए, सही तैयारी कीजिए और सबसे पास के पार्क की ओर निकल पड़िए। ताज़ी हवा बच्चे को शांत करने का सबसे अच्छा तरीका है।', title_id = 'Detoks alam itu wajib 🌳', body_id = 'Kekacauan di rumah hari ini sudah tak tertahankan? Segera cek alat Cuaca dan Pakaian, berpakaianlah yang sesuai, dan pergilah ke taman terdekat. Udara segar adalah penenang terbaik bagi anak.', title_ja = '自然でデトックスしよう 🌳', body_ja = '今日は家の大混乱にもう耐えられない？すぐに「天気と服装」を確認して、ちょうどいい服装で近くの公園へ出かけましょう。新鮮な空気は、子どもをいちばん落ち着かせてくれます。', title_ko = '자연 디톡스는 필수예요 🌳', body_ko = '오늘 집 안의 소란을 견디기 힘든가요? 바로 날씨와 옷차림 도구를 보고 알맞게 챙겨 입은 뒤 가장 가까운 공원으로 나가세요. 맑은 공기는 아이를 진정시키는 최고의 방법이에요.', title_nl = 'Een natuurdetox is een must 🌳', body_nl = 'Is de chaos thuis vandaag ondraaglijk? Kijk meteen in Weer en kleding, kleed jullie passend aan en ga snel naar het dichtstbijzijnde park. Frisse lucht kalmeert een kind het allerbest.', title_pl = 'Detoks na łonie natury to konieczność 🌳', body_pl = 'Domowy chaos jest dziś nie do zniesienia? Od razu zajrzyj do narzędzia Pogoda i ubiór, ubierzcie się odpowiednio i biegnijcie do najbliższego parku. Świeże powietrze najlepiej uspokaja dziecko.', title_pt = 'Um detox de natureza é obrigatório 🌳', body_pt = 'O caos em casa está hoje insuportável? Veja já o Tempo e Roupa, vistam-se como deve ser e corram para o parque mais próximo. O ar puro é o melhor calmante para uma criança.', title_sv = 'Naturdetox är ett måste 🌳', body_sv = 'Har kaoset hemma blivit outhärdligt i dag? Titta direkt i verktyget Väder och kläder, klä er rätt och skynda till närmaste park. Frisk luft är det bästa lugnande medlet för barnet.', title_vi = 'Cần detox bằng thiên nhiên 🌳', body_vi = 'Sự hỗn loạn trong nhà hôm nay không thể chịu nổi? Hãy xem ngay công cụ Thời tiết và trang phục, mặc đồ phù hợp và ra công viên gần nhất. Không khí trong lành là liều thuốc an thần tốt nhất cho bé.', title_zh = '一定要来次自然排毒 🌳', body_zh = '今天家里乱得让人受不了？马上看看天气穿衣工具，穿戴合适，奔向最近的公园。新鲜空气是孩子最好的镇静剂。' WHERE id = 'be944652-2efc-45de-a928-8d34a23e4645' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nuevas versiones de las palabras 🗣️', body_es = '¿Dice «aba» en vez de agua o «tande» en vez de grande? Suena tan dulce que cuesta no reírse. Pero repítele siempre con cariño la forma correcta para que su cerebro grabe la buena.', title_fr = 'Mots en version revisitée 🗣️', body_fr = 'Il dit « l''iau » au lieu de « l''eau » ou « gand » au lieu de « grand » ? C''est si mignon qu''il est difficile de ne pas rire. Mais à chaque fois, répétez gentiment la bonne version pour que son cerveau la retienne.', title_hi = 'शब्दों का नया रूप 🗣️', body_hi = '''पानी'' को ''मानी'', ''बिल्ली'' को ''बिन्नी'' कहता है? इतना प्यारा लगता है कि हँसी रोकना मुश्किल है। लेकिन हर बार प्यार से शब्द का सही रूप दोहराइए ताकि उसका दिमाग सही रूप याद रखे।', title_id = 'Versi baru kata-kata 🗣️', body_id = 'Ia bilang ''mimum'' untuk minum, ''becal'' untuk besar? Kedengarannya sangat manis hingga sulit menahan tawa. Namun setiap kali, ulangi versi yang benar dengan lembut agar otaknya merekam yang benar.', title_ja = '言葉の新バージョン 🗣️', body_ja = '「おみず」を「おにず」、「おおきい」を「おっきー」と言いますか？かわいくて笑わずにいられませんね。でも毎回やさしく正しい言い方をくり返して、脳が正しい形を覚えられるようにしましょう。', title_ko = '단어의 새 버전 🗣️', body_ko = '말을 귀엽게 바꿔 발음하나요? 너무 사랑스러워서 웃음을 참기 힘들죠. 하지만 그때마다 올바른 단어를 다정하게 다시 들려주세요. 그래야 뇌가 바른 말을 기억해요.', title_nl = 'Nieuwe versies van woorden 🗣️', body_nl = 'Zegt hij ''wawa'' in plaats van water of ''goot'' in plaats van groot? Het klinkt zo schattig dat je bijna moet lachen. Herhaal toch elke keer vriendelijk het juiste woord, zodat zijn hersenen de goede versie opslaan.', title_pl = 'Nowe wersje słów 🗣️', body_pl = 'Zamiast „woda” mówi „boda”, a zamiast „duży” „ziuzi”? Brzmi tak słodko, że trudno się nie śmiać. Ale za każdym razem łagodnie powtarzaj poprawną wersję słowa, by jego mózg ją zakodował.', title_pt = 'A nova versão das palavras 🗣️', body_pt = 'Diz "ága" em vez de água, "gande" em vez de grande? Soa tão doce que é difícil não rir. Mas repita sempre, com carinho, a versão certa da palavra para que o cérebro dele a grave.', title_sv = 'Ordens nya version 🗣️', body_sv = 'Säger barnet ”sjvatten” i stället för vatten eller ”bjug” i stället för stor? Det låter så gulligt att det är svårt att inte skratta. Men upprepa vänligt rätt version varje gång så att hjärnan lär in det rätta.', title_vi = 'Phiên bản mới của từ ngữ 🗣️', body_vi = 'Bé nói "nác" thay vì "nước", "bé" thay vì "bế"? Nghe đáng yêu đến mức khó nhịn cười. Nhưng mỗi lần như vậy, hãy nhẹ nhàng nhắc lại cách nói đúng để não bé ghi nhớ phiên bản đúng.', title_zh = '词语的新版本 🗣️', body_zh = '把“水”说成“匪”，把“大”说成“嗒”？听起来太可爱了，忍住不笑真难。但每次都要温柔地重复一遍正确的说法，让大脑记住正确的版本。' WHERE id = '09900d01-e715-436d-95eb-cb7b3165dfb1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que escriba él el final del cuento 🪄', body_es = 'Los libros clásicos os han cansado a los dos. Esta vez, en Cuentos inteligentes, deja que tu peque elija el final de la historia. Activa su imaginación preguntándole: «¿Quién crees que ayudó al héroe?».', title_fr = 'C''est lui qui écrit la fin du conte 🪄', body_fr = 'Vous en avez assez tous les deux des livres classiques. Cette fois, dans les Contes intelligents, laissez votre enfant choisir la fin de l''histoire. Stimulez son imagination : « À ton avis, qui a aidé le héros ? »', title_hi = 'कहानी का अंत वह लिखे 🪄', body_hi = 'पुरानी किताबों से आप दोनों ऊब गए हैं? इस बार स्मार्ट कहानियों में कहानी का अंत अपने बच्चे से चुनवाइए। ''तुम्हें क्या लगता है, उस हीरो की मदद किसने की?'' पूछकर उसकी कल्पना जगाइए।', title_id = 'Biar ia yang menulis akhir cerita 🪄', body_id = 'Kalian berdua bosan dengan buku klasik. Kali ini di Dongeng Pintar, biarkan anak memilih akhir ceritanya. Pancing daya khayalnya dengan bertanya, ''Menurutmu siapa yang menolong pahlawan itu?''', title_ja = 'お話の結末はお子さんが作る 🪄', body_ja = 'いつもの絵本にふたりともあきてしまった？「スマートおはなし」で、今回はお話の結末をお子さんに選んでもらいましょう。「主人公を助けたのはだれだと思う？」と問いかけて、想像力を働かせて。', title_ko = '동화의 결말은 아이가 써요 🪄', body_ko = '늘 읽던 책이 둘 다 지겨워졌나요? 이번에는 스마트 동화에서 이야기의 결말을 아이가 고르게 해 보세요. ''누가 그 주인공을 도와줬을까?'' 하고 물으며 상상력을 깨워 주세요.', title_nl = 'Laat hem het einde van het sprookje schrijven 🪄', body_nl = 'Zijn jullie allebei klaar met de klassieke boekjes? Laat je kindje deze keer in Slimme sprookjes zelf het einde kiezen. Prikkel zijn fantasie met: ''Wie denk jij dat de held heeft geholpen?''', title_pl = 'Niech on napisze zakończenie 🪄', body_pl = 'Oboje macie dość klasycznych książek. Tym razem w Mądrych bajkach pozwól dziecku wybrać zakończenie historii. Pobudź jego wyobraźnię pytaniem: „Jak myślisz, kto pomógł bohaterowi?”.', title_pt = 'Ele que escreva o fim da história 🪄', body_pt = 'Estão os dois cansados dos livros clássicos. Desta vez, nas Histórias Inteligentes, deixe o seu filho escolher o final. Puxe pela imaginação dele: "Quem achas que ajudou o herói?"', title_sv = 'Låt barnet skriva sagans slut 🪄', body_sv = 'Ni är båda trötta på klassiska böcker. Låt barnet välja hur berättelsen slutar i Smarta sagor den här gången. Sätt fart på fantasin med ”Vem tror du hjälpte hjälten?”.', title_vi = 'Để bé viết đoạn kết 🪄', body_vi = 'Cả hai mẹ con đều chán những cuốn sách kinh điển? Lần này trong Truyện cổ tích thông minh, hãy để bé chọn cái kết. Hỏi bé "Con nghĩ ai đã giúp nhân vật ấy?" để khơi dậy trí tưởng tượng.', title_zh = '让宝宝来写故事的结局 🪄', body_zh = '你们俩都读腻了经典故事书？这次在智能故事里让孩子来选结局吧。问一句“你觉得是谁帮了那位主角？”，激发宝宝的想象力。' WHERE id = '9853e360-5dcb-4105-84a8-77759e13bdcd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuando se acaba la energía 🔋', body_es = '¿Hoy no tienes fuerzas para nada? Prepara en Recetas saludables un batido de 5 minutos cargado de hierro y vitaminas y tómatelo de pie. Cuídate.', title_fr = 'Quand l''énergie s''épuise 🔋', body_fr = 'Aujourd''hui, vous n''avez de force pour rien ? Préparez avec les Recettes saines un smoothie mixé en 5 minutes, riche en fer et en vitamines, et buvez-le debout. Prenez soin de vous.', title_hi = 'जब ऊर्जा खत्म हो जाए 🔋', body_hi = 'आज किसी चीज़ की ताकत नहीं बची? सेहतमंद रेसिपी से 5 मिनट में बनने वाली, आयरन और विटामिन से भरपूर ब्लेंडर स्मूदी बनाइए और खड़े-खड़े पी लीजिए। अपना ख्याल रखिए।', title_id = 'Saat energi habis 🔋', body_id = 'Hari ini tidak punya tenaga untuk apa pun? Buat smoothie kaya zat besi dan vitamin yang siap dalam 5 menit dari Resep Sehat dan minum sambil berdiri. Rawat diri Anda.', title_ja = 'エネルギーが切れたら 🔋', body_ja = '今日は何もする元気がない？「ヘルシーレシピ」から5分でできる、鉄分とビタミンたっぷりのスムージーをミキサーでつくって、立ったままでも飲みましょう。自分をいたわって。', title_ko = '기운이 바닥날 때 🔋', body_ko = '오늘 아무것도 할 힘이 없나요? 건강한 레시피에서 5분이면 만드는, 철분과 비타민 가득한 스무디를 갈아 서서라도 마시세요. 나를 챙겨 주세요.', title_nl = 'Als de energie op is 🔋', body_nl = 'Heb je vandaag nergens de energie voor? Maak een smoothie uit Gezonde recepten, in 5 minuten uit de blender en boordevol ijzer en vitamines, en drink hem staand op. Zorg goed voor jezelf.', title_pl = 'Gdy kończy się energia 🔋', body_pl = 'Nie masz dziś na nic siły? Przygotuj ze Zdrowych przepisów smoothie z blendera, pełne żelaza i witamin, gotowe w 5 minut, i wypij je w biegu. Zadbaj o siebie.', title_pt = 'Quando a energia acaba 🔋', body_pt = 'Hoje não tem forças para nada? Prepare nas Receitas Saudáveis um smoothie de 5 minutos, uma reserva de ferro e vitaminas, e beba-o mesmo de pé. Cuide de si.', title_sv = 'När energin tar slut 🔋', body_sv = 'Orkar du ingenting i dag? Gör en mixad smoothie full av järn och vitaminer som är klar på 5 minuter från Hälsosamma recept och drick den stående. Ta hand om dig själv.', title_vi = 'Khi cạn năng lượng 🔋', body_vi = 'Hôm nay mẹ chẳng còn sức làm gì? Hãy làm một ly sinh tố xay giàu sắt và vitamin trong 5 phút từ Công thức lành mạnh và uống ngay. Hãy chăm sóc bản thân.', title_zh = '精力耗尽时 🔋', body_zh = '今天什么都没力气做？从健康食谱里用5分钟做一杯富含铁和维生素的奶昔，站着喝下去。照顾好自己。' WHERE id = 'd5f06496-2705-48a5-8325-2f0c28ac0a0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista de la compra te salva 🛒', body_es = '¿Fuiste al súper fiándote de tu memoria y volviste sin pañales? Son cosas que pasan. Acostúmbrate a apuntar todo lo que falta en la Lista de la compra y deja que la app se acuerde por ti.', title_fr = 'La liste de courses vous sauve 🛒', body_fr = 'Vous avez fait confiance à votre mémoire au supermarché et vous êtes rentrée sans les couches ? Ça arrive. Prenez l''habitude de tout noter dans la Liste de courses, laissez l''application s''en souvenir à votre place.', title_hi = 'शॉपिंग लिस्ट बचा लेती है 🛒', body_hi = 'याददाश्त के भरोसे बाज़ार गईं और डायपर भूलकर लौट आईं? ऐसा होता है। सारी ज़रूरतें शॉपिंग लिस्ट में लिखने की आदत डालिए, आपकी जगह ऐप याद रखे।', title_id = 'Daftar belanja penyelamat 🛒', body_id = 'Mengandalkan ingatan saat belanja dan pulang tanpa membeli popok? Itu biasa terjadi. Biasakan menulis semua kebutuhan di Daftar Belanja, biar aplikasi yang mengingat untuk Anda.', title_ja = '買い物リストは救世主 🛒', body_ja = '記憶にたよって買い物に行き、おむつを買い忘れて帰ってきた？よくあることです。必要なものはすべて「買い物リスト」に書く習慣をつけて、アプリにかわりに覚えてもらいましょう。', title_ko = '쇼핑 목록은 구세주예요 🛒', body_ko = '기억만 믿고 마트에 갔다가 기저귀를 잊고 돌아왔나요? 그럴 수 있어요. 필요한 건 모두 쇼핑 목록에 적는 습관을 들이고, 기억은 앱에 맡기세요.', title_nl = 'Het boodschappenlijstje redt je 🛒', body_nl = 'Vertrouwde je in de supermarkt op je geheugen en kwam je thuis zonder luiers? Dat gebeurt. Maak er een gewoonte van om alles op je Boodschappenlijstje te zetten en laat de app voor je onthouden.', title_pl = 'Lista zakupów ratuje życie 🛒', body_pl = 'Zaufałaś pamięci, poszłaś do sklepu i wróciłaś bez pieluszek? Zdarza się. Wyrób sobie nawyk wpisywania wszystkich potrzeb na Listę zakupów i niech aplikacja pamięta za ciebie.', title_pt = 'A lista de compras salva vidas 🛒', body_pt = 'Confiou na memória, foi ao supermercado e voltou sem as fraldas? Acontece. Crie o hábito de apontar tudo na Lista de Compras e deixe a app lembrar-se por si.', title_sv = 'Inköpslistan räddar dagen 🛒', body_sv = 'Litade du på ditt minne när du handlade och kom hem utan blöjorna? Sånt händer. Gör det till en vana att skriva in allt i Inköpslistan och låt appen komma ihåg åt dig.', title_vi = 'Danh sách đi chợ là cứu tinh 🛒', body_vi = 'Mẹ tin vào trí nhớ để đi siêu thị rồi về nhà mới nhớ ra quên mua tã? Chuyện thường thôi. Hãy tập ghi mọi thứ cần mua vào Danh sách mua sắm và để ứng dụng nhớ giúp mẹ.', title_zh = '购物清单是救星 🛒', body_zh = '相信自己的记性去超市，结果忘了买尿布就回来了？这种事常有。养成习惯，把所有需要的东西都写进购物清单，让应用替你记着。' WHERE id = '42bb5c65-e45f-45b5-8da0-322b9acd1ab4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rato sorpresa en pareja 🥂', body_es = '¡Se ha dormido antes de lo esperado! No gastes este momento tan raro en limpiar la casa. Sentaos frente a frente con tu pareja, apagad la tele y simplemente preguntaos qué tal ha ido el día.', title_fr = 'Un moment surprise en couple 🥂', body_fr = 'L''enfant s''est endormi plus tôt que prévu ! Ne gaspillez pas ce moment rare en ménage. Asseyez-vous face à votre partenaire, éteignez la télé et demandez-vous simplement comment s''est passée votre journée.', title_hi = 'सरप्राइज़ कपल टाइम 🥂', body_hi = 'बच्चा अचानक जल्दी सो गया! इस दुर्लभ पल को घर की सफ़ाई में मत गँवाइए। अपने पार्टनर के आमने-सामने बैठिए, टीवी बंद कीजिए और बस एक-दूसरे से पूछिए कि दिन कैसा रहा।', title_id = 'Waktu berdua yang tak terduga 🥂', body_id = 'Anak tertidur lebih cepat dari biasanya! Jangan habiskan momen langka ini untuk bersih-bersih. Duduklah berhadapan dengan pasangan, matikan TV, dan tanyakan saja bagaimana hari masing-masing.', title_ja = 'サプライズのふたり時間 🥂', body_ja = 'お子さんが思いがけず早く眠りました！このめったにない時間を家の掃除に使わないで。パートナーと向かい合って座り、テレビを消して、ただお互いの一日がどうだったか聞きましょう。', title_ko = '깜짝 부부 시간 🥂', body_ko = '아이가 예상보다 일찍 잠들었어요! 이 드문 순간을 집 청소에 쓰지 마세요. 배우자와 마주 앉아 TV를 끄고 서로의 하루가 어땠는지 물어보세요.', title_nl = 'Onverwacht uurtje met z''n tweeën 🥂', body_nl = 'Hij viel onverwacht vroeg in slaap! Besteed dit zeldzame moment niet aan schoonmaken. Ga tegenover je partner zitten, zet de tv uit en vraag elkaar gewoon hoe jullie dag was.', title_pl = 'Niespodziewany czas we dwoje 🥂', body_pl = 'Dziecko niespodziewanie wcześnie zasnęło! Nie trać tej rzadkiej chwili na sprzątanie. Usiądź naprzeciwko partnera, wyłączcie telewizor i po prostu zapytajcie się nawzajem, jak minął wam dzień.', title_pt = 'Hora surpresa a dois 🥂', body_pt = 'A criança adormeceu mais cedo do que o esperado! Não gaste este momento raro a limpar a casa. Sente-se frente a frente com o seu companheiro, desligue a televisão e pergunte apenas como foi o dia de cada um.', title_sv = 'Överraskande parstund 🥂', body_sv = 'Barnet somnade oväntat tidigt! Lägg inte den sällsynta stunden på att städa. Sätt dig mitt emot din partner, stäng av tv:n och fråga bara hur den andras dag har varit.', title_vi = 'Giờ hẹn hò bất ngờ 🥂', body_vi = 'Bé ngủ sớm bất ngờ! Đừng dành khoảnh khắc hiếm hoi này để dọn nhà. Hãy ngồi đối diện với chồng, tắt TV và chỉ hỏi nhau hôm nay đã trôi qua thế nào.', title_zh = '意外的二人时光 🥂', body_zh = '孩子出乎意料地早早睡着了！别把这难得的时刻花在打扫上。和另一半面对面坐下，关掉电视，问问彼此今天过得怎么样。' WHERE id = '8f5ba264-bfbc-4e71-b81e-4cbb2fe23c54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ingeniería de puzles 🧩', body_es = 'Insiste en meter las formas en sus agujeros. Aunque se equivoque o se enfade, no le ayudes enseguida. Aprende a resolver problemas justamente con estos intentos y errores.', title_fr = 'Ingénierie du puzzle 🧩', body_fr = 'Il s''obstine à glisser les formes dans les bons trous. Même s''il se trompe ou s''énerve, ne l''aidez pas tout de suite. C''est justement par ces essais et erreurs qu''il apprend à résoudre les problèmes.', title_hi = 'पज़ल इंजीनियरिंग 🧩', body_hi = 'आकारों को सही छेद में डालने की ज़िद करता है? गलती करे या चिढ़ जाए, तब भी तुरंत मदद मत कीजिए। वह आज़माने और गलती करने से ही समस्या सुलझाना सीखता है।', title_id = 'Teknik puzzle 🧩', body_id = 'Ia bersikeras memasukkan bentuk ke lubang yang pas. Meski ia salah dan kesal, jangan langsung membantu. Ia justru belajar memecahkan masalah lewat coba-coba ini.', title_ja = 'パズルエンジニア 🧩', body_ja = '形を合う穴に入れようと、ねばり強くがんばっています。まちがえても、イライラしても、すぐに手を貸さないで。問題解決の力は、まさにこうした試行錯誤で身につきます。', title_ko = '퍼즐 엔지니어링 🧩', body_ko = '모양을 맞는 구멍에 넣으려고 끈질기게 노력하나요? 틀리거나 짜증을 내도 바로 도와주지 마세요. 이런 시행착오를 통해 문제 해결 능력을 배우는 중이에요.', title_nl = 'Puzzelingenieur 🧩', body_nl = 'Wil hij per se vormen in de juiste gaatjes stoppen? Help niet meteen, ook als het fout gaat of hij boos wordt. Juist door proberen en vergissen leert hij problemen oplossen.', title_pl = 'Inżynieria układanek 🧩', body_pl = 'Uparcie wkłada kształty do pasujących otworów. Nawet gdy się myli i denerwuje, nie pomagaj od razu. Właśnie przez takie próby i błędy uczy się rozwiązywać problemy.', title_pt = 'Engenharia de puzzles 🧩', body_pt = 'Insiste em encaixar as formas nos buracos certos. Mesmo que erre ou se irrite, não ajude logo. É precisamente com estas tentativas e erros que aprende a resolver problemas.', title_sv = 'Pusselingenjör 🧩', body_sv = 'Barnet envisas med att få ner formerna i rätt hål. Hjälp inte direkt, även om hen gör fel eller blir arg. Barnet lär sig problemlösning just genom att pröva och misslyckas.', title_vi = 'Kỹ sư ghép hình 🧩', body_vi = 'Bé kiên trì đặt các hình khối vào đúng lỗ. Dù bé có sai hay bực bội, cũng đừng vội giúp. Bé học kỹ năng giải quyết vấn đề chính qua những lần thử và sai này.', title_zh = '拼图工程 🧩', body_zh = '坚持要把形状塞进对应的洞里。就算放错了、着急了，也别马上帮忙。宝宝正是在这些尝试和犯错中学会解决问题的。' WHERE id = '92ad5bcb-5fa6-44a6-8e27-05fc8347c1e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ansiedad por separación 🥺', body_es = 'Llora detrás de ti aunque salgas de la habitación solo un segundo. La ansiedad por separación a veces vuelve. Háblale cada vez y dale seguridad desde lejos: «Estoy aquí, en la cocina, ya voy».', title_fr = 'L''angoisse de séparation 🥺', body_fr = 'Même quand vous quittez la pièce une seconde, il pleure derrière vous. L''angoisse de séparation revient parfois. Rassurez-le de loin à chaque fois : « Je suis là, je suis dans la cuisine, j''arrive. »', title_hi = 'बिछड़ने की बेचैनी 🥺', body_hi = 'आप कमरे से पल भर के लिए भी निकलें तो पीछे से रोता है? अलगाव की चिंता कभी-कभी लौट आती है। हर बार आवाज़ देकर ''मैं रसोई में हूँ, आ रही हूँ'' कहिए और दूर से भरोसा दीजिए।', title_id = 'Cemas berpisah 🥺', body_id = 'Bahkan saat Anda keluar kamar sedetik, ia menangis mengejar Anda. Kecemasan berpisah kadang kembali. Setiap kali, beri rasa aman dari jauh dengan bersuara: ''Ibu di sini, Ibu di dapur, Ibu datang.''', title_ja = '離れるときの不安 🥺', body_ja = 'ほんの一瞬部屋を出ただけで、後ろで泣きますか？分離不安はときどきぶり返します。そのたびに「キッチンにいるよ、すぐ行くよ」と声をかけて、離れたところからも安心させましょう。', title_ko = '분리 불안 🥺', body_ko = '방을 잠깐만 나가도 울며 따라오나요? 분리 불안은 가끔 다시 찾아와요. 그때마다 ''엄마 여기 있어, 주방이야, 금방 갈게'' 하고 멀리서도 목소리로 안심시켜 주세요.', title_nl = 'Verlatingsangst 🥺', body_nl = 'Zelfs als je even de kamer uit gaat, huilt hij je achterna. Verlatingsangst komt soms terug. Laat steeds je stem horen en geef hem van een afstand vertrouwen: ''Ik ben hier, in de keuken, ik kom eraan.''', title_pl = 'Lęk przed rozstaniem 🥺', body_pl = 'Płacze za tobą, nawet gdy wychodzisz z pokoju na sekundę? Lęk separacyjny czasem wraca. Za każdym razem odezwij się i z daleka dodaj mu otuchy: „Jestem tu, w kuchni, już idę”.', title_pt = 'Ansiedade de separação 🥺', body_pt = 'Até quando sai do quarto por um segundo, chora atrás de si. A ansiedade de separação às vezes volta. Fale sempre com ele e dê-lhe segurança à distância: "Estou aqui, estou na cozinha, já vou."', title_sv = 'Separationsoro 🥺', body_sv = 'Barnet gråter efter dig även när du går ut ur rummet en sekund. Separationsångesten kommer ibland tillbaka. Ropa varje gång och ge trygghet på avstånd genom att säga ”jag är i köket, jag kommer”.', title_vi = 'Lo âu chia ly 🥺', body_vi = 'Mẹ chỉ ra khỏi phòng vài giây bé cũng khóc theo. Lo âu chia ly đôi khi quay trở lại. Mỗi lần như vậy, hãy lên tiếng trấn an từ xa: "Mẹ ở đây, mẹ đang trong bếp, mẹ đến ngay".', title_zh = '分离焦虑 🥺', body_zh = '你离开房间一秒钟，宝宝都在后面哭。分离焦虑有时会卷土重来。每次都出声告诉宝宝你在这里，远远地说一句“我在厨房，马上就来”，给宝宝安全感。' WHERE id = '346ca24f-e8f9-47c9-9cc2-dc1b86281214' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La presión de la perfección 🛑', body_es = '¿Otros niños ya cuentan colores y el tuyo no quiere? ¡Deja de comparar ahora mismo! Cada niño tiene su propio reloj de desarrollo. Tu peque avanza a su ritmo y es totalmente normal.', title_fr = 'La pression de la perfection 🛑', body_fr = 'D''autres enfants comptent déjà les couleurs, mais le vôtre n''en a pas envie ? Arrêtez tout de suite de comparer ! Chaque enfant a sa propre horloge de développement. Le vôtre avance à son rythme, et c''est tout à fait normal.', title_hi = 'परफ़ेक्ट होने का दबाव 🛑', body_hi = 'दूसरे बच्चे रंग गिनने लगे हैं, लेकिन आपका बच्चा नहीं चाहता? तुलना करना तुरंत बंद कीजिए! हर बच्चे की विकास की घड़ी अलग होती है। आपका बच्चा अपनी रफ़्तार से आगे बढ़ रहा है और यह बिल्कुल सामान्य है।', title_id = 'Tekanan untuk sempurna 🛑', body_id = 'Anak lain sudah menyebutkan warna, tetapi anak Anda tidak mau? Segera berhenti membandingkan! Jam perkembangan setiap anak berbeda. Anak Anda maju dengan temponya sendiri, dan itu sepenuhnya normal.', title_ja = '完璧でなきゃというプレッシャー 🛑', body_ja = 'ほかの子はもう色を数えているのに、うちの子は興味なし？比べるのはすぐにやめましょう！成長の時計は子どもによって違います。お子さんは自分のペースで進んでいて、それはまったく普通のことです。', title_ko = '완벽해야 한다는 압박 🛑', body_ko = '다른 아이들은 벌써 색깔을 세는데 우리 아이는 관심이 없나요? 비교는 당장 멈추세요! 아이마다 발달 시계가 달라요. 우리 아이는 자기 속도로 나아가고 있고 그건 아주 정상이에요.', title_nl = 'Druk om perfect te zijn 🛑', body_nl = 'Tellen andere kinderen al kleuren, maar wil jouw kind niet? Stop meteen met vergelijken! Elk kind heeft zijn eigen ontwikkelingsklok. Jouw kind gaat in zijn eigen tempo vooruit en dat is heel normaal.', title_pl = 'Presja perfekcji 🛑', body_pl = 'Inne dzieci już nazywają kolory, a twoje nie chce? Natychmiast przestań porównywać! Każde dziecko rozwija się we własnym rytmie. Twoje dziecko idzie naprzód swoim tempem i to zupełnie normalne.', title_pt = 'A pressão da perfeição 🛑', body_pt = 'Outras crianças já contam as cores e o seu filho não quer? Pare já de comparar! Cada criança tem o seu relógio de desenvolvimento. O seu filho avança ao seu ritmo, e isso é perfeitamente normal.', title_sv = 'Pressen att vara perfekt 🛑', body_sv = 'Andra barn räknar redan färger, men ditt barn vill inte? Sluta jämföra direkt! Varje barns utvecklingsklocka är olika. Ditt barn går framåt i sin egen takt och det är helt normalt.', title_vi = 'Áp lực hoàn hảo 🛑', body_vi = 'Những bé khác đã biết đếm màu sắc, còn bé nhà mình thì không muốn? Hãy dừng ngay việc so sánh! Mỗi bé có nhịp phát triển riêng. Bé đang tiến bộ theo tốc độ của mình và điều đó hoàn toàn bình thường.', title_zh = '完美的压力 🛑', body_zh = '别的孩子已经会数颜色了，你的孩子却不想？马上停止比较！每个孩子的发育时钟都不一样。你的孩子在按自己的节奏前进，这完全正常。' WHERE id = 'afa94b0b-8399-4813-8b1a-8a243185fcf4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica secreta de papá 👨‍🍼', body_es = 'Ya tienes bastante con el cansancio del día. Deja que papá, con sus juegos, se encargue de prepararle para dormir y de lavarle los dientes, y tú tómate el té en silencio a un lado.', title_fr = 'La tactique secrète de papa 👨‍🍼', body_fr = 'La fatigue de la journée vous suffit. Confiez la préparation au coucher et le brossage des dents aux jeux de papa, et buvez votre thé au calme, de votre côté.', title_hi = 'पापा की खुफ़िया तरकीब 👨‍🍼', body_hi = 'दिन की थकान आपके लिए काफ़ी है। शाम को बच्चे को सोने के लिए तैयार करना और दाँत ब्रश कराना पापा की मस्ती भरी तरकीबों पर छोड़िए, और आप एक तरफ़ खामोशी से चाय पीजिए।', title_id = 'Taktik rahasia Ayah 👨‍🍼', body_id = 'Kelelahan siang hari sudah cukup bagi Anda. Serahkan persiapan tidur dan menyikat giginya di sore hari pada kejahilan Ayah, sementara Anda minum teh dengan tenang di samping.', title_ja = 'パパの秘密の作戦 👨‍🍼', body_ja = '昼間の疲れでもう十分。夕方の寝る準備や歯みがきは、パパの遊び心にお任せして、あなたは少し離れて静かにお茶を飲みましょう。', title_ko = '아빠의 비밀 전략 👨‍🍼', body_ko = '낮 동안의 피로만으로도 충분해요. 저녁 잠자리 준비와 양치는 장난기 많은 아빠에게 맡기고, 엄마는 한쪽에서 조용히 차를 드세요.', title_nl = 'Papa''s geheime tactiek 👨‍🍼', body_nl = 'Je bent al moe genoeg van de dag. Laat het klaarmaken voor bed en het tandenpoetsen aan het eind van de middag over aan papa''s spelletjes, en drink jij aan de zijkant in stilte je thee.', title_pl = 'Tajna taktyka taty 👨‍🍼', body_pl = 'Masz dość dziennego zmęczenia. Przygotowanie do snu i mycie zębów pod wieczór powierz zabawowym pomysłom taty, a ty w ciszy wypij z boku herbatę.', title_pt = 'A tática secreta do pai 👨‍🍼', body_pt = 'O cansaço do dia já chega. Entregue às brincadeiras do pai a preparação para dormir e a escovagem dos dentes ao fim da tarde, e beba o seu chá à parte, em silêncio.', title_sv = 'Pappas hemliga taktik 👨‍🍼', body_sv = 'Dagens trötthet räcker för dig. Lämna över kvällens förberedelser för läggdags och tandborstningen åt pappas lekfullhet, och drick ditt te i tystnad en bit bort.', title_vi = 'Chiến thuật bí mật của bố 👨‍🍼', body_vi = 'Mệt mỏi ban ngày đã quá đủ với mẹ. Hãy giao việc chuẩn bị cho bé đi ngủ và đánh răng cho những trò vui của bố, còn mẹ ngồi một góc yên lặng uống trà.', title_zh = '爸爸的秘密战术 👨‍🍼', body_zh = '白天的疲惫已经够你受了。傍晚哄睡前的准备、刷牙这些事，就交给爱玩的爸爸吧，你在一旁安安静静地喝杯茶。' WHERE id = 'd5610b5c-f92a-4668-b551-ccf2ba5bd9e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te ha preocupado de repente la curva de talla y peso de tu peque de 32 meses? No busques enfermedades que asustan en foros de internet: aprende con Anacan AI la realidad precisa y con base científica.', body_fr = 'Les courbes de taille et de poids de votre enfant de 32 mois vous inquiètent soudain ? Ne cherchez pas de maladies effrayantes sur les forums, découvrez la réalité précise et fondée sur la science avec Anacan AI.', body_hi = '32 महीने के बच्चे की लंबाई और वज़न का चार्ट अचानक चिंता में डाल रहा है? इंटरनेट फ़ोरम पर डरावनी बीमारियाँ मत ढूँढिए, Anacan AI से सटीक और वैज्ञानिक आधार वाली सच्चाई जानिए।', body_id = 'Grafik tinggi dan berat badan anak usia 32 bulan tiba-tiba membuat Anda cemas? Jangan mencari penyakit menakutkan di forum internet, pelajari fakta yang tepat dan berdasar ilmiah dari Anacan AI.', body_ja = '生後32か月のお子さんの身長や体重のグラフが急に気になりましたか？ネットの掲示板でこわい病気を探さないで、Anacan AIから正確で科学的な根拠のある事実を学びましょう。', body_ko = '32개월 아이의 키와 몸무게 그래프가 갑자기 걱정되나요? 인터넷 게시판에서 무서운 병을 찾지 말고 Anacan AI에게 정확하고 과학적인 정보를 받아 보세요.', body_nl = 'Maakte de lengte- en gewichtscurve van je kind van 32 maanden je ineens ongerust? Zoek niet op internetfora naar enge ziektes, maar krijg nauwkeurige, wetenschappelijk onderbouwde informatie van Anacan AI.', body_pl = 'Siatki wzrostu i wagi 32-miesięcznego dziecka nagle cię zaniepokoiły? Nie szukaj na forach przerażających chorób, poznaj dokładne, oparte na nauce fakty od Anacan AI.', body_pt = 'As curvas de altura e peso do seu filho de 32 meses preocuparam-na de repente? Não procure doenças assustadoras nos fóruns da internet: conheça a realidade precisa e com base científica no Anacan AI.', body_sv = 'Har 32-månadersbarnets längd- och viktkurva plötsligt oroat dig? Sök inte efter skrämmande sjukdomar i forum på nätet, få exakta och vetenskapligt grundade fakta från Anacan AI.', body_vi = 'Biểu đồ chiều cao và cân nặng của bé 32 tháng bỗng khiến mẹ lo lắng? Đừng tìm những căn bệnh đáng sợ trên các diễn đàn mạng, hãy hỏi Anacan AI để biết thực tế chính xác, có cơ sở khoa học.', body_zh = '32个月宝宝的身高体重曲线突然让你担心？别在网上论坛里搜那些吓人的疾病，向Anacan AI了解准确、有科学依据的事实吧。' WHERE id = '47b60c96-b788-4cad-9b79-643917c1b944' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ambiente natural para dormir 🤫', body_es = 'La primera media hora después de dormirse es cuando el cerebro está más sensible. Para neutralizar los ruidos que llegan por la ventana, enciende en la habitación un aparato de ruido blanco suave (por ejemplo, sonido de lluvia).', title_fr = 'Un environnement de sommeil naturel 🤫', body_fr = 'La première demi-heure de sommeil est le moment où le cerveau est le plus sensible. Pour neutraliser les sons venant de la fenêtre, allumez dans la chambre un appareil à bruit blanc doux (le bruit de la pluie, par exemple).', title_hi = 'नींद का प्राकृतिक माहौल 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा वह समय है जब दिमाग सबसे संवेदनशील होता है। खिड़की से आने वाली आवाज़ों को दबाने के लिए कमरे में हल्का व्हाइट नॉइज़ (जैसे बारिश की आवाज़) डिवाइस चलाइए।', title_id = 'Suasana tidur alami 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah saat otak paling sensitif. Untuk meredam suara dari jendela, nyalakan perangkat suara putih yang lembut (misalnya suara hujan) di kamar.', title_ja = '自然な眠りの環境 🤫', body_ja = '寝ついてから最初の30分は、脳がいちばん敏感な時間です。窓の外から聞こえる音をやわらげるために、部屋でやさしいホワイトノイズ（たとえば雨の音）の機械をつけましょう。', title_ko = '자연스러운 수면 환경 🤫', body_ko = '잠든 후 첫 30분은 뇌가 가장 예민한 시간이에요. 창밖에서 들어오는 소리를 줄이려면 방에 은은한 백색소음(예: 빗소리) 기기를 켜 주세요.', title_nl = 'Natuurlijke slaapomgeving 🤫', body_nl = 'Het eerste halfuur na het inslapen zijn de hersenen het gevoeligst. Zet een zacht witteruisapparaat (bijvoorbeeld regengeluid) aan in de kamer om geluiden van buiten te neutraliseren.', title_pl = 'Naturalne warunki do snu 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to czas, gdy mózg jest najbardziej wrażliwy. Aby zneutralizować odgłosy zza okna, włącz w pokoju urządzenie z delikatnym białym szumem (np. odgłosem deszczu).', title_pt = 'Ambiente de sono natural 🤫', body_pt = 'A primeira meia hora depois de adormecer é quando o cérebro está mais sensível. Para neutralizar os sons que vêm da janela, ligue no quarto um aparelho de ruído branco suave (por exemplo, som de chuva).', title_sv = 'Naturlig sömnmiljö 🤫', body_sv = 'Den första halvtimmen efter insomnandet är då hjärnan är som känsligast. För att neutralisera ljud från fönstret, sätt på en lätt vit brus-apparat (till exempel regnljud) i rummet.', title_vi = 'Môi trường ngủ tự nhiên 🤫', body_vi = 'Nửa giờ đầu sau khi bé ngủ là lúc não nhạy cảm nhất. Để trung hòa tiếng ồn từ cửa sổ, hãy bật máy tiếng ồn trắng nhẹ nhàng (ví dụ tiếng mưa) trong phòng.', title_zh = '自然的睡眠环境 🤫', body_zh = '入睡后的头半小时是大脑最敏感的时候。为了屏蔽窗外的声音，在房间里打开轻柔的白噪音机（比如雨声）。' WHERE id = '7f82c861-b627-4e20-b2ed-f2fb9f45756b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te lo explico! ☝️', body_es = 'Lo señala todo con el dedo y hace una pregunta tras otra. Quiere que le pongas nombre al mundo. ¡Es un gran salto en la comunicación! Aunque te canses, repite con paciencia el nombre de las cosas.', title_fr = 'Je vais t''expliquer ! ☝️', body_fr = 'Il montre tout du doigt et enchaîne les questions. Il veut que vous lui nommiez le monde. C''est un grand bond dans la communication ! Même si vous êtes fatiguée, répétez patiemment le nom de ces objets.', title_hi = 'मैं समझाऊँ! ☝️', body_hi = 'हर चीज़ की ओर उँगली दिखाकर एक के बाद एक सवाल पूछता है? वह चाहता है कि आप उसे दुनिया के नाम बताएँ। बातचीत में यह बड़ी छलांग है! थक जाएँ तब भी उन चीज़ों के नाम धैर्य से दोहराइए।', title_id = 'Aku jelaskan ya! ☝️', body_id = 'Ia menunjuk segala hal dengan jarinya dan bertanya bertubi-tubi. Ia ingin Anda menamai dunia untuknya. Lompatan besar dalam komunikasi! Meski lelah, ulangi nama benda-benda itu dengan sabar.', title_ja = '説明してあげる！☝️', body_ja = 'なんでも指さして、次々と質問しますか？世界に名前をつけてほしいのです。コミュニケーションの大きな飛躍です！疲れていても、ものの名前を根気よくくり返してあげましょう。', title_ko = '내가 설명해 줄게! ☝️', body_ko = '손가락으로 모든 걸 가리키며 질문을 쏟아내나요? 엄마가 세상에 이름을 붙여 주길 바라는 거예요. 소통의 큰 도약이에요! 지치더라도 그 물건들의 이름을 인내심 있게 반복해 주세요.', title_nl = 'Ik zal het je uitleggen! ☝️', body_nl = 'Wijst hij alles aan en stelt hij vraag na vraag? Hij wil dat jij de wereld voor hem benoemt. Een grote sprong in communicatie! Ook al ben je moe, herhaal geduldig de namen van die dingen.', title_pl = 'Wytłumaczę ci! ☝️', body_pl = 'Pokazuje wszystko paluszkiem i zadaje pytanie za pytaniem. Chce, żebyś nazywała mu świat. To wielki skok w komunikacji! Nawet jeśli jesteś zmęczona, cierpliwie powtarzaj nazwy tych rzeczy.', title_pt = 'Deixa-me explicar-te! ☝️', body_pt = 'Aponta tudo com o dedo e faz perguntas atrás de perguntas. Quer que dê nome ao mundo por ele. É um grande salto na comunicação! Mesmo cansada, repita com paciência o nome das coisas.', title_sv = 'Jag ska förklara! ☝️', body_sv = 'Barnet pekar på allt och ställer fråga efter fråga. Hen vill att du ska sätta namn på världen. Ett stort kommunikativt språng! Även om du blir trött, upprepa tålmodigt vad sakerna heter.', title_vi = 'Để con giải thích cho! ☝️', body_vi = 'Bé chỉ tay vào mọi thứ và hỏi liên tục. Bé muốn mẹ gọi tên thế giới cho bé. Đây là bước nhảy vọt lớn trong giao tiếp! Dù mệt, hãy kiên nhẫn nhắc lại tên của những đồ vật ấy.', title_zh = '我来给你讲！☝️', body_zh = '什么都用手指着，一个接一个地提问？宝宝想让你给世界命名。这是交流上的一大飞跃！就算累了，也耐心地重复那些东西的名字吧。' WHERE id = '9bea836b-e06e-49f0-af98-259fe4009523' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La exploración de papá en el parque 👨‍👧', body_es = '¡La maternidad no es un turno 24/7! Deja a papá el paseo de hoy. Que se llenen de barro juntos mientras tú te tumbas en el sofá y disfrutas del silencio.', title_fr = 'Papa explore le parc 👨‍👧', body_fr = 'Être maman, ce n''est pas un service 24h/24 et 7j/7 ! Confiez la sortie d''aujourd''hui à papa. Qu''ils pataugent ensemble dans la boue, pendant que vous vous allongez sur le canapé pour savourer le silence.', title_hi = 'पापा की पार्क वाली खोज 👨‍👧', body_hi = 'माँ होना 24/7 की ड्यूटी नहीं है! आज की बाहर की सैर पापा को सौंप दीजिए। उन्हें साथ में कीचड़ में खेलने दीजिए, और आप सोफ़े पर लेटकर खामोशी का आनंद लीजिए।', title_id = 'Petualangan Ayah di taman 👨‍👧', body_id = 'Menjadi ibu bukan tugas 24/7! Serahkan jalan-jalan di luar hari ini kepada Ayah. Biar mereka berlumpur bersama, sementara Anda berbaring di sofa dan menikmati keheningan.', title_ja = 'パパの公園探検 👨‍👧', body_ja = '子育ては24時間365日のシフトではありません！今日の外遊びはパパにお任せしましょう。ふたりでどろんこになってもらい、あなたはソファに横になって静けさを楽しんで。', title_ko = '아빠의 공원 탐험 👨‍👧', body_ko = '엄마 노릇은 24시간 근무가 아니에요! 오늘 바깥 산책은 아빠에게 맡기세요. 둘이 함께 진흙투성이가 되는 동안 엄마는 소파에 누워 고요를 즐기세요.', title_nl = 'Papa ontdekt het park 👨‍👧', body_nl = 'Moederschap is geen dienst van 24/7! Laat de wandeling van vandaag aan papa over. Laat ze samen lekker in de modder spelen, terwijl jij op de bank ligt en van de stilte geniet.', title_pl = 'Parkowa wyprawa taty 👨‍👧', body_pl = 'Macierzyństwo to nie zmiana 24/7! Powierz dzisiejszy spacer tacie. Niech razem tarzają się w błocie, a ty połóż się na kanapie i ciesz się ciszą.', title_pt = 'A exploração do parque com o pai 👨‍👧', body_pt = 'A maternidade não é um turno 24/7! Entregue o passeio de hoje ao pai. Deixe-os enlamear-se juntos e a mãe deita-se no sofá a saborear o silêncio.', title_sv = 'Pappas parkexpedition 👨‍👧', body_sv = 'Moderskap är inte ett skift dygnet runt! Lämna över dagens utomhuspromenad till pappa. Låt dem bli leriga tillsammans medan du ligger på soffan och njuter av tystnaden.', title_vi = 'Bố đưa bé khám phá công viên 👨‍👧', body_vi = 'Làm mẹ không phải ca trực 24/7! Hãy giao buổi đi chơi ngoài trời hôm nay cho bố. Để hai bố con cùng lấm lem bùn đất, còn mẹ nằm dài trên sofa tận hưởng sự yên tĩnh.', title_zh = '爸爸的公园探险 👨‍👧', body_zh = '当妈妈不是24/7的值班！把今天的户外散步交给爸爸吧。让他们一起在泥巴里玩个痛快，你在沙发上躺着享受安静。' WHERE id = '2fb64a2b-9948-4425-9837-80add71d4e54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Estirón de talla y peso 📏', body_es = '¿Los pantalones vuelven a quedarle cortos? ¡Crece cada día delante de tus ojos! Introduce sus medidas actuales en el Seguimiento del desarrollo y mira con orgullo su curva de crecimiento, fruto de tus noches sin dormir.', title_fr = 'Poussée de taille et de poids 📏', body_fr = 'Les pantalons sont encore trop courts ? Il grandit chaque jour sous vos yeux ! Entrez ses mesures actuelles dans le Suivi de développement et regardez fièrement sa courbe, fruit de vos nuits blanches.', title_hi = 'लंबाई और वज़न में उछाल 📏', body_hi = 'पैंट फिर छोटी हो गई? वह हर दिन आपकी आँखों के सामने बड़ा हो रहा है! ग्रोथ ट्रैकर में मौजूदा माप दर्ज कीजिए और आपकी जागी हुई रातों का फल, विकास का ग्राफ़ गर्व से देखिए।', title_id = 'Lonjakan tinggi dan berat badan 📏', body_id = 'Celananya kependekan lagi? Ia tumbuh di depan mata Anda setiap hari! Masukkan ukuran terbarunya ke Pelacak Perkembangan dan lihat dengan bangga kurva pertumbuhan yang merupakan buah dari malam-malam tanpa tidur Anda.', title_ja = '身長と体重の伸び 📏', body_ja = 'ズボンの丈がまた短くなった？毎日目の前で大きくなっています！「発達トラッカー」に今のサイズを入力して、眠れない夜の成果である成長曲線を誇らしく見てみましょう。', title_ko = '키와 몸무게가 쑥 📏', body_ko = '바지가 또 짧아졌나요? 매일 눈앞에서 자라고 있어요! 성장 기록에 현재 수치를 입력하고, 잠 못 든 밤들의 결실인 성장 곡선을 뿌듯하게 바라보세요.', title_nl = 'Sprong in lengte en gewicht 📏', body_nl = 'Is zijn broek weer te kort? Hij groeit elke dag voor je ogen! Vul de huidige maten in de Groeitracker in en kijk trots naar de groeicurve, de vrucht van al je slapeloze nachten.', title_pl = 'Skok wzrostu i wagi 📏', body_pl = 'Spodnie znów za krótkie? Rośnie na twoich oczach każdego dnia! Wpisz aktualne wymiary do Śledzenia rozwoju i z dumą spójrz na krzywą rozwoju, owoc twoich nieprzespanych nocy.', title_pt = 'Salto na altura e no peso 📏', body_pt = 'As calças voltaram a ficar curtas? Ele cresce todos os dias diante dos seus olhos! Introduza as medidas atuais no Registo de Desenvolvimento e veja com orgulho a curva, fruto das suas noites sem dormir.', title_sv = 'Spurt i längd och vikt 📏', body_sv = 'Har byxorna blivit korta igen? Barnet växer framför dina ögon varje dag! För in de aktuella måtten i Tillväxtspåraren och se stolt på tillväxtkurvan, frukten av dina sömnlösa nätter.', title_vi = 'Tăng vọt chiều cao và cân nặng 📏', body_vi = 'Ống quần lại ngắn nữa rồi? Bé lớn lên từng ngày ngay trước mắt mẹ! Hãy nhập số đo hiện tại vào Theo dõi phát triển và tự hào ngắm đường cong phát triển, thành quả của những đêm mất ngủ.', title_zh = '身高体重突增 📏', body_zh = '裤子又短了？宝宝每天都在你眼前长大！在发育追踪里输入当前尺寸，骄傲地看看那条成长曲线，那是你无数个不眠之夜的成果。' WHERE id = '9928c8dc-9b21-49a6-b0c4-fd4704041409' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El milagro de la música clásica 🎶', body_es = '¿Por la tarde empieza una agresividad sin motivo? Apaga la tele, baja las luces y pon en la habitación una música clásica muy suave. La armonía del agua y la música cambiará el ambiente.', title_fr = 'Le miracle de la musique classique 🎶', body_fr = 'Une agressivité sans raison commence en fin d''après-midi ? Éteignez la télé, baissez les lumières et mettez une musique classique très douce dans la pièce. L''harmonie de l''eau et de la musique changera l''atmosphère.', title_hi = 'शास्त्रीय संगीत का जादू 🎶', body_hi = 'शाम को बिना वजह गुस्सा शुरू हो गया? टीवी बंद कीजिए, लाइटें धीमी कीजिए और कमरे में बहुत हल्का शास्त्रीय संगीत चलाइए। पानी और संगीत का तालमेल माहौल बदल देगा।', title_id = 'Keajaiban musik klasik 🎶', body_id = 'Menjelang malam ia tiba-tiba agresif tanpa sebab. Matikan TV, redupkan lampu, dan putar musik klasik yang sangat lembut di kamar. Paduan air dan musik akan mengubah suasana.', title_ja = 'クラシック音楽の奇跡 🎶', body_ja = '夕方に理由のない攻撃的な態度が始まりましたか？テレビを消し、照明を落として、とても静かなクラシック音楽を流しましょう。お水と音楽のハーモニーが空気を変えてくれます。', title_ko = '클래식 음악의 기적 🎶', body_ko = '저녁 무렵 이유 없이 공격적으로 변했나요? TV를 끄고 조명을 낮춘 뒤 아주 잔잔한 클래식 음악을 틀어 주세요. 부드러운 소리와 음악의 조화가 분위기를 바꿔 줄 거예요.', title_nl = 'Het wonder van klassieke muziek 🎶', body_nl = 'Begint hij aan het eind van de middag zonder reden agressief te worden? Zet de tv uit, dim de lichten en laat heel zachte klassieke muziek in de kamer klinken. De harmonie van water en muziek verandert de sfeer.', title_pl = 'Cud muzyki klasycznej 🎶', body_pl = 'Pod wieczór pojawia się agresja bez powodu? Wyłącz telewizor, przygaś światło i puść w pokoju bardzo cichą muzykę klasyczną. Harmonia wody i muzyki zmieni atmosferę.', title_pt = 'O milagre da música clássica 🎶', body_pt = 'Ao fim da tarde começou uma agressividade sem razão? Desligue a televisão, baixe as luzes e ponha no quarto música clássica muito suave. A harmonia da água e da música vai mudar o ambiente.', title_sv = 'Klassisk musik gör underverk 🎶', body_sv = 'Har det börjat en aggressivitet utan orsak på eftermiddagen? Stäng av tv:n, dämpa ljuset och spela mycket lätt klassisk musik i rummet. Harmonin mellan vatten och musik förändrar stämningen.', title_vi = 'Điều kỳ diệu của nhạc cổ điển 🎶', body_vi = 'Chiều tối bé bỗng trở nên hung hăng không lý do? Hãy tắt TV, giảm ánh sáng và bật một bản nhạc cổ điển thật nhẹ trong phòng. Sự hòa quyện của âm thanh êm dịu và âm nhạc sẽ thay đổi bầu không khí.', title_zh = '古典音乐的魔力 🎶', body_zh = '傍晚无缘无故开始发脾气？关掉电视，调暗灯光，在房间里放一点非常轻柔的古典音乐。水和音乐的和谐会改变整个氛围。' WHERE id = 'ed4eff7e-2e68-4d65-af30-186f1086a150' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Agentes secretos en la sopa 🥦', body_es = '¿Le ha declarado el boicot a todo lo verde? No te preocupes. Hacer puré las verduras y esconderlas en albóndigas y salsas con ayuda del Plan de alimentación es el truco de madre más antiguo y útil.', title_fr = 'Agents secrets dans la soupe 🥦', body_fr = 'Il boycotte tout ce qui est vert ? Pas d''inquiétude. Avec le Plan de nutrition, réduire les légumes en purée et les cacher dans les boulettes et les sauces, c''est la plus vieille et la plus utile des astuces de maman.', title_hi = 'सूप में खुफ़िया एजेंट 🥦', body_hi = 'हर हरी चीज़ का बहिष्कार कर दिया? चिंता मत कीजिए। फ़ीडिंग प्लान की मदद से सब्ज़ियों को प्यूरी बनाकर कटलेट और सॉस में छिपाना माँओं की सबसे पुरानी और काम की तरकीब है।', title_id = 'Agen rahasia di dalam sup 🥦', body_id = 'Ia memboikot semua yang berwarna hijau? Jangan khawatir. Menghaluskan sayuran dengan bantuan Rencana Nutrisi lalu menyembunyikannya di perkedel dan saus adalah trik ibu paling kuno dan ampuh.', title_ja = 'スープにひそむ秘密のエージェント 🥦', body_ja = '緑のものを全部ボイコット？心配しないで。「栄養管理ツール」を使って野菜をピューレにし、ハンバーグやソースにかくすのは、昔ながらの役立つママの知恵です。', title_ko = '수프 속 비밀 요원 🥦', body_ko = '초록색은 전부 거부하나요? 걱정 마세요. 식단 계획을 참고해 채소를 퓌레로 만들어 커틀릿이나 소스에 숨기는 건 엄마들의 가장 오래되고 유용한 비법이에요.', title_nl = 'Geheime agenten in de soep 🥦', body_nl = 'Heeft hij een boycot afgekondigd tegen alles wat groen is? Geen zorgen. Groenten pureren en in gehaktballetjes en sausjes verstoppen met hulp van het Voedingsplan is de oudste en handigste moedertruc.', title_pl = 'Tajni agenci w zupie 🥦', body_pl = 'Ogłosił bojkot wszystkiego, co zielone? Nie martw się. Zmiksowanie warzyw z pomocą planu karmienia i ukrycie ich w kotlecikach i sosach to najstarsza i najskuteczniejsza sztuczka mam.', title_pt = 'Agentes secretos na sopa 🥦', body_pt = 'Declarou boicote a tudo o que é verde? Não se preocupe. Com o Plano Alimentar, fazer puré dos legumes e escondê-los nos hambúrgueres e nos molhos é o truque de mãe mais antigo e útil.', title_sv = 'Hemliga agenter i soppan 🥦', body_sv = 'Har barnet bojkottat allt grönt? Oroa dig inte. Att mosa grönsakerna och gömma dem i biffar och såser med hjälp av matplanen är mammornas äldsta och mest användbara knep.', title_vi = 'Điệp viên bí mật trong bát canh 🥦', body_vi = 'Bé tuyên bố tẩy chay mọi thứ màu xanh? Đừng lo. Xay nhuyễn rau để giấu vào chả viên, nước sốt với Kế hoạch dinh dưỡng là mẹo lâu đời và hữu ích nhất của các mẹ.', title_zh = '汤里的秘密特工 🥦', body_zh = '对所有绿色的东西宣布抵制？别担心。借助喂养计划，把蔬菜做成泥藏进肉饼和酱汁里，是妈妈们最古老也最有用的妙招。' WHERE id = '331370dc-1940-499c-abdb-15eb6fc3307a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Canciones inventadas 🎤', body_es = 'Mientras coloca sus juguetes, canta canciones con palabras que no existen en ningún idioma. Su vocabulario y su sentido del ritmo se desarrollan a la vez. Añade sin falta esta nueva etapa musical al Seguimiento del desarrollo.', title_fr = 'Chansons inventées 🎤', body_fr = 'En rangeant ses jouets, il chante tout seul avec des mots qui n''existent dans aucune langue. Son vocabulaire et son sens du rythme se développent en même temps. Ajoutez absolument cette nouvelle étape musicale au Suivi de développement.', title_hi = 'खुद गढ़े गाने 🎤', body_hi = 'खिलौने सजाते समय खुद ही ऐसे शब्दों में गाने गाता है जो किसी भाषा के नहीं? उसकी शब्दावली और लय की समझ एक साथ बढ़ रही है। इस नए संगीत वाले पड़ाव को ग्रोथ ट्रैकर में ज़रूर दर्ज कीजिए।', title_id = 'Lagu karangan sendiri 🎤', body_id = 'Saat menyusun mainannya, ia bernyanyi sendiri dengan kata-kata yang tidak ada di bahasa mana pun. Kosakata dan rasa iramanya berkembang bersamaan. Pastikan mencatat tahap musik baru ini di Pelacak Perkembangan.', title_ja = '即興の歌 🎤', body_ja = 'おもちゃを並べながら、どの言語でもない言葉でひとりで歌っていますか？語彙とリズム感が同時に育っています。この新しい音楽の段階を、ぜひ「発達トラッカー」に記録しましょう。', title_ko = '지어낸 노래 🎤', body_ko = '장난감을 늘어놓으며 세상에 없는 말로 혼자 노래를 부르나요? 어휘와 리듬감이 함께 자라고 있어요. 성장 기록에 이 새로운 음악 단계를 꼭 남겨 두세요.', title_nl = 'Verzonnen liedjes 🎤', body_nl = 'Zingt hij tijdens het opruimen van zijn speelgoed liedjes met woorden die in geen enkele taal bestaan? Zijn woordenschat en ritmegevoel groeien tegelijk. Zet deze nieuwe muzikale fase zeker in de Groeitracker.', title_pl = 'Wymyślone piosenki 🎤', body_pl = 'Układając zabawki, śpiewa sobie piosenki ze słowami, które nie istnieją w żadnym języku. Słownictwo i poczucie rytmu rozwijają się jednocześnie. Koniecznie zapisz ten nowy muzyczny etap w Śledzeniu rozwoju.', title_pt = 'Canções inventadas 🎤', body_pt = 'Enquanto arruma os brinquedos, canta sozinho com palavras que não existem em língua nenhuma. O vocabulário e o sentido de ritmo crescem ao mesmo tempo. Registe sem falta esta nova etapa musical no Registo de Desenvolvimento.', title_sv = 'Påhittade sånger 🎤', body_sv = 'Barnet sjunger sånger med ord som inte finns på något språk medan hen radar upp leksakerna. Ordförrådet och rytmkänslan utvecklas samtidigt. Lägg absolut till det nya musiksteget i Utvecklingsspåraren.', title_vi = 'Những bài hát tự sáng tác 🎤', body_vi = 'Khi xếp đồ chơi, bé tự hát bằng những từ không thuộc ngôn ngữ nào. Vốn từ và cảm nhận nhịp điệu đang cùng phát triển. Nhất định hãy ghi giai đoạn âm nhạc mới này vào Theo dõi phát triển.', title_zh = '自编的小曲 🎤', body_zh = '摆玩具时，自己用哪种语言里都没有的词唱着歌。词汇量和节奏感正在同时发展。一定要把这个新的音乐阶段记进发育追踪里。' WHERE id = 'a9d400f1-6a44-4584-a532-eeed75cc3207' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pijama de la discordia 👕', body_es = '¿Vestirse se ha convertido en una gran guerra? Deja que elija: «¿Quieres el pijama rojo o el azul?». Este pequeño truco le hará sentir que decide él y acabará con la batalla.', title_fr = 'Le pyjama de la discorde 👕', body_fr = 'S''habiller tourne à la guerre ? Laissez-lui le choix : « Tu veux le pyjama rouge ou le bleu ? » Cette petite astuce lui donnera le sentiment de décider et mettra fin à la lutte.', title_hi = 'ज़िद्दी पजामा 👕', body_hi = 'कपड़े पहनाना बड़ी जंग बन गया है? चुनाव उस पर छोड़िए: ''लाल पजामा चाहिए या नीला?'' यह छोटी सी तरकीब उसे महसूस कराएगी कि फ़ैसला उसने लिया, और लड़ाई खत्म हो जाएगी।', title_id = 'Piyama yang bikin ribut 👕', body_id = 'Berpakaian berubah jadi perang besar? Serahkan pilihan padanya: ''Mau piyama merah atau biru?'' Trik kecil ini membuatnya merasa ia yang memutuskan dan menghentikan perdebatan.', title_ja = 'がんこなパジャマ 👕', body_ja = '着がえが大きな戦いになっていますか？選ばせてあげましょう：「赤いパジャマがいい？それとも青？」この小さな工夫で、自分で決めたと感じられて、戦いが終わります。', title_ko = '고집스러운 잠옷 👕', body_ko = '옷 입히기가 큰 전쟁이 되었나요? 선택을 맡겨 보세요: ''빨간 잠옷 입을래, 파란 잠옷 입을래?'' 이 작은 요령으로 스스로 결정했다고 느끼며 씨름이 멈출 거예요.', title_nl = 'Koppige pyjama 👕', body_nl = 'Is aankleden een grote strijd geworden? Laat hem kiezen: ''Wil je de rode pyjama of de blauwe?'' Door dit kleine trucje voelt hij dat hij zelf beslist en stopt de strijd.', title_pl = 'Uparta piżama 👕', body_pl = 'Ubieranie zamieniło się w wielką wojnę? Zostaw mu wybór: „Chcesz czerwoną piżamę czy niebieską?”. Ta mała sztuczka da mu poczucie, że to on decyduje, i zakończy walkę.', title_pt = 'O pijama teimoso 👕', body_pt = 'Vestir-se virou uma guerra? Deixe-o escolher: "Queres o pijama vermelho ou o azul?" Este pequeno truque faz com que sinta que é ele quem decide e acaba com a luta.', title_sv = 'Envis pyjamas 👕', body_sv = 'Har påklädningen blivit ett stort krig? Låt barnet välja: ”Vill du ha den röda pyjamasen eller den blå?” Det lilla knepet får barnet att känna att hen bestämmer och stoppar kampen.', title_vi = 'Bộ đồ ngủ bướng bỉnh 👕', body_vi = 'Mặc đồ trở thành cuộc chiến lớn? Hãy để bé chọn: "Con muốn bộ đồ ngủ màu đỏ hay màu xanh?". Mẹo nhỏ này sẽ giúp bé cảm thấy mình được quyết định và chấm dứt giằng co.', title_zh = '倔强的睡衣 👕', body_zh = '穿衣服变成一场大战？把选择权交给宝宝：“你想穿红色睡衣，还是蓝色的？”这个小妙招会让宝宝觉得是自己做的决定，争执也就结束了。' WHERE id = 'e7308375-84bd-4b4e-9322-163dcd46ff8e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo abrázale 🫂', body_es = 'No hace falta ningún juego, libro ni cuento. Esta noche simplemente abrázale contra tu pecho, respira su olor tan rico y susúrrale en la oscuridad lo valioso que es para ti.', title_fr = 'Serrez-le simplement 🫂', body_fr = 'Pas besoin de jeu, de livre ni de conte. Ce soir, serrez-le simplement contre vous, respirez sa délicieuse odeur et chuchotez-lui dans le noir combien il est précieux.', title_hi = 'बस गले लगाइए 🫂', body_hi = 'किसी खेल, किताब या कहानी की ज़रूरत नहीं। आज शाम बस उसे सीने से लगाइए, उसकी प्यारी खुशबू महसूस कीजिए और अंधेरे में फुसफुसाकर बताइए कि वह आपके लिए कितना कीमती है।', title_id = 'Cukup peluk 🫂', body_id = 'Tidak perlu permainan, buku, atau dongeng. Malam ini cukup dekap ia di dada, hirup aroma indahnya, dan bisikkan dalam gelap betapa berharganya ia bagi Anda.', title_ja = 'ただ抱きしめて 🫂', body_ja = '遊びも絵本もお話もいりません。今夜はただ胸に抱きしめて、そのいいにおいを深く吸いこみ、暗やみの中でどれほど大切な存在かをささやいてあげましょう。', title_ko = '그냥 안아 주세요 🫂', body_ko = '오늘 밤엔 놀이도, 책도, 동화도 필요 없어요. 그냥 꼭 끌어안고 그 사랑스러운 냄새를 깊이 들이마신 뒤, 어둠 속에서 얼마나 소중한 존재인지 속삭여 주세요.', title_nl = 'Gewoon knuffelen 🫂', body_nl = 'Je hebt geen spelletje, boek of sprookje nodig. Druk hem vanavond gewoon tegen je borst, snuif zijn heerlijke geurtje op en fluister in het donker hoe dierbaar hij voor je is.', title_pl = 'Po prostu przytul 🫂', body_pl = 'Nie potrzeba żadnej zabawy, książki ani bajki. Dziś wieczorem po prostu przytul go mocno do piersi, wdychaj jego cudowny zapach i szepnij w ciemności, jak bardzo jest dla ciebie cenny.', title_pt = 'Só um abraço 🫂', body_pt = 'Não precisa de jogos, livros nem histórias. Esta noite, simplesmente aperte-o contra o peito, respire aquele cheiro maravilhoso e sussurre-lhe no escuro o quanto é precioso.', title_sv = 'Bara en kram 🫂', body_sv = 'Inga lekar, böcker eller sagor behövs. I kväll, håll bara barnet tätt intill dig, andas in den underbara doften och viska i mörkret hur värdefull hen är.', title_vi = 'Chỉ cần ôm thôi 🫂', body_vi = 'Không cần trò chơi, sách vở hay truyện cổ tích. Tối nay chỉ cần ôm bé vào lòng, hít hà mùi hương thơm tho của bé và thì thầm trong bóng tối rằng bé quý giá với mẹ biết bao.', title_zh = '抱一抱就好 🫂', body_zh = '不需要任何游戏、书或故事。今晚就把宝宝紧紧抱在怀里，深深闻一闻那好闻的味道，在黑暗中轻声告诉宝宝，宝宝对你有多珍贵。' WHERE id = '68ebc7a3-cb63-4696-9089-9b8d5bd20d47' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Limpieza en equipo 🧹', body_es = '¿Toca recoger la casa? Mientras barres, deja que te ayude pasando un trapo. Lee en el Blog cómo convertir la limpieza en trabajo en equipo y diversión.', title_fr = 'Le ménage ensemble 🧹', body_fr = 'Il faut ranger la maison ? Quand vous balayez, laissez-le vous aider avec un chiffon. Lisez dans les Blogs comment faire du ménage un travail d''équipe et un jeu.', title_hi = 'साथ मिलकर सफ़ाई 🧹', body_hi = 'घर समेटना है? जब आप झाड़ू लगाएँ, तो उसे भी कपड़े से पोंछकर मदद करने दीजिए। सफ़ाई को टीम वर्क और मज़े में बदलने के तरीके ब्लॉग में पढ़िए।', title_id = 'Bersih-bersih bersama 🧹', body_id = 'Rumah perlu dirapikan? Saat Anda menyapu kamar, biarkan ia membantu mengelap dengan kain. Baca di bagian Blog cara mengubah bersih-bersih menjadi kerja tim dan keseruan.', title_ja = '一緒にお掃除 🧹', body_ja = '家の片づけをしなきゃ？部屋をはいているとき、お子さんにもぞうきんでふいて手伝ってもらいましょう。お掃除をチームワークと遊びに変える方法を、ブログで読んでみて。', title_ko = '함께하는 청소 🧹', body_ko = '집을 정리해야 하나요? 엄마가 방을 쓸 때 아이도 걸레로 닦으며 돕게 해 주세요. 청소를 팀워크와 놀이로 바꾸는 방법을 블로그에서 읽어 보세요.', title_nl = 'Samen schoonmaken 🧹', body_nl = 'Moet het huis opgeruimd? Laat hem met een doekje meehelpen als jij de kamer veegt. Lees in Blogs hoe je van schoonmaken teamwerk en plezier maakt.', title_pl = 'Wspólne sprzątanie 🧹', body_pl = 'Trzeba posprzątać dom? Gdy zamiatasz pokój, pozwól mu pomóc, przecierając ściereczką. Przeczytaj na Blogu, jak zamienić sprzątanie w pracę zespołową i zabawę.', title_pt = 'Limpezas a dois 🧹', body_pt = 'É preciso arrumar a casa? Enquanto varre o quarto, deixe-o ajudar a limpar com um pano. Leia no Blogue como transformar a limpeza em trabalho de equipa e diversão.', title_sv = 'Städning tillsammans 🧹', body_sv = 'Behöver hemmet städas? Låt barnet hjälpa till att torka med en trasa när du sopar. Läs i Bloggar hur ni gör städningen till lagarbete och nöje.', title_vi = 'Cùng nhau dọn dẹp 🧹', body_vi = 'Cần dọn nhà? Khi mẹ quét phòng, hãy để bé lấy khăn lau giúp mẹ. Đọc trong mục Blog cách biến việc dọn dẹp thành công việc của cả đội và niềm vui.', title_zh = '一起打扫 🧹', body_zh = '家里该收拾了？你扫地时，让宝宝拿抹布擦擦，帮你的忙。去博客里读读怎样把打扫变成团队合作和乐趣。' WHERE id = 'e7127e7f-2c80-4b8e-aba6-2bcc0bbe7513' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Estoy muy cansada 🔋', body_es = 'Todos esperan energía de ti, pero tu batería se ha agotado. Hoy no cocines, pide comida. Ser una madre perfecta no te obliga a hacerlo todo sola. Date permiso.', title_fr = 'Je suis épuisée 🔋', body_fr = 'Tout le monde attend de l''énergie de vous, mais votre batterie est à plat. Aujourd''hui, ne cuisinez pas, commandez. Être une mère parfaite, ce n''est pas tout faire seule. Autorisez-vous à souffler.', title_hi = 'मैं बहुत थक गई हूँ 🔋', body_hi = 'सब आपसे ऊर्जा की उम्मीद करते हैं, लेकिन आपकी बैटरी खत्म हो गई है। आज कुछ मत पकाइए, ऑर्डर कर दीजिए। परफ़ेक्ट माँ होने का मतलब सब कुछ अकेले करने की मजबूरी नहीं है। खुद को इजाज़त दीजिए।', title_id = 'Aku sangat lelah 🔋', body_id = 'Semua orang mengharapkan energi dari Anda, tetapi baterai Anda habis. Hari ini jangan memasak, pesan saja. Menjadi ibu sempurna bukan berarti harus melakukan semuanya sendiri. Beri izin pada diri Anda.', title_ja = 'もうくたくたです 🔋', body_ja = 'みんながあなたに元気を期待しているけれど、バッテリーはもう空っぽ。今日は何も作らず、出前を頼みましょう。完璧なママとは、なんでもひとりでこなすことではありません。自分を許してあげて。', title_ko = '너무 지쳤어요 🔋', body_ko = '모두가 엄마에게 에너지를 기대하지만 배터리는 이미 바닥났죠. 오늘은 요리하지 말고 배달을 시키세요. 완벽한 엄마라고 모든 걸 혼자 해야 하는 건 아니에요. 스스로에게 허락해 주세요.', title_nl = 'Ik ben zo moe 🔋', body_nl = 'Iedereen verwacht energie van je, maar je batterij is leeg. Kook vandaag niet, bestel eten. Een perfecte moeder hoeft niet alles alleen te doen. Geef jezelf toestemming.', title_pl = 'Jestem bardzo zmęczona 🔋', body_pl = 'Wszyscy oczekują od ciebie energii, a twoja bateria się wyczerpała. Dziś nic nie gotuj, zamów jedzenie. Być idealną mamą nie znaczy robić wszystkiego samej. Daj sobie na to pozwolenie.', title_pt = 'Estou mesmo cansada 🔋', body_pt = 'Todos esperam energia de si, mas a bateria acabou. Hoje não cozinhe, encomende. Ser uma mãe perfeita não é ter de fazer tudo sozinha. Dê-se essa permissão.', title_sv = 'Jag är så trött 🔋', body_sv = 'Alla förväntar sig energi av dig, men batteriet är slut. Laga ingen mat i dag, beställ i stället. Att vara en perfekt mamma betyder inte att du måste göra allt själv. Ge dig själv lov.', title_vi = 'Mẹ mệt lắm rồi 🔋', body_vi = 'Ai cũng chờ mẹ tràn đầy năng lượng, nhưng pin của mẹ đã cạn. Hôm nay đừng nấu nướng, hãy gọi đồ ăn. Làm mẹ hoàn hảo không có nghĩa là phải tự làm tất cả. Hãy cho phép mình nghỉ ngơi.', title_zh = '我太累了 🔋', body_zh = '所有人都期待你充满精力，可你的电池已经没电了。今天什么都别做，点外卖吧。做一个完美妈妈，不等于什么都要自己扛。允许自己休息。' WHERE id = 'f0084bbf-ef12-44c3-80b2-42b0bd99f526' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Del círculo a las formas 🎨', body_es = '¿Dibuja círculos con el lápiz en la pared o en el papel? Esta travesura en realidad es un gran salto en su motricidad.', title_fr = 'Du cercle aux formes 🎨', body_fr = 'Il trace des cercles au crayon sur le mur ou sur une feuille ? Cette bêtise est en réalité un grand bond de motricité.', title_hi = 'गोले से आकार तक 🎨', body_hi = 'पेन से दीवार या कागज़ पर गोले बनाता है? यह शरारत असल में मोटर स्किल्स में बड़ी छलांग है।', title_id = 'Dari lingkaran ke bentuk 🎨', body_id = 'Ia menggambar lingkaran dengan pensil di dinding atau kertas? Kenakalan ini sebenarnya lompatan motorik yang besar.', title_ja = 'まるから形へ 🎨', body_ja = 'クレヨンで壁や紙にまるを描いていますか？このいたずらは、実は運動能力の大きな飛躍です。', title_ko = '동그라미에서 모양으로 🎨', body_ko = '연필로 벽이나 종이에 동그라미를 그리나요? 이 장난은 사실 운동 발달의 큰 도약이에요.', title_nl = 'Van rondje naar vorm 🎨', body_nl = 'Tekent hij met een potlood rondjes op de muur of op papier? Deze ondeugd is eigenlijk een grote sprong in zijn motoriek.', title_pl = 'Od kółka do kształtu 🎨', body_pl = 'Rysuje kredką kółka na ścianie albo na papierze? Ta psota to tak naprawdę wielki skok w motoryce.', title_pt = 'Do círculo às formas 🎨', body_pt = 'Desenha círculos com o lápis na parede ou no papel? Esta travessura é, na verdade, um grande salto na motricidade.', title_sv = 'Från cirkel till form 🎨', body_sv = 'Ritar barnet cirklar med pennan på väggen eller papperet? Det här busiga är egentligen ett stort motoriskt språng.', title_vi = 'Từ vòng tròn đến hình khối 🎨', body_vi = 'Bé dùng bút vẽ vòng tròn trên tường hoặc giấy? Trò nghịch ngợm này thật ra là một bước nhảy vọt lớn về vận động.', title_zh = '从圆圈到形状 🎨', body_zh = '拿着笔在墙上或纸上画圆圈？这种调皮其实是动作发展的一大飞跃。' WHERE id = '001946c3-28e7-4dd7-a8dd-6edeeb1c5013' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La armonía del agua 🛀', body_es = 'Después de correr todo el día, estáis agotados los dos. Durante el baño templado, pon de fondo sonidos relajantes de la naturaleza. La armonía del agua preparará para dormir hasta al niño más tozudo.', title_fr = 'L''harmonie de l''eau 🛀', body_fr = 'Après avoir couru toute la journée, vous êtes épuisés tous les deux. Pendant le bain tiède, mettez des sons de la nature apaisants en fond. L''harmonie de l''eau préparera au sommeil même l''enfant le plus têtu.', title_hi = 'पानी का सुकून 🛀', body_hi = 'दिनभर भागदौड़ से वह भी थक गया और आप भी। गुनगुने पानी से नहलाते समय पीछे प्रकृति की शांत आवाज़ें चलाइए। पानी का यह सुकून सबसे ज़िद्दी बच्चे को भी नींद के लिए तैयार कर देगा।', title_id = 'Harmoni air 🛀', body_id = 'Seharian berlarian, ia dan Anda sama-sama kelelahan. Saat mandi air hangat, putar suara alam yang menenangkan di latar belakang. Harmoni air akan menyiapkan anak yang paling keras kepala sekalipun untuk tidur.', title_ja = 'お水のハーモニー 🛀', body_ja = '一日じゅう走り回って、ふたりともへとへと。ぬるめのお風呂に入るとき、後ろで落ち着く自然の音を流しましょう。お水のハーモニーが、どんなにがんこな子も眠りへ導きます。', title_ko = '물의 조화 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤죠. 따뜻한 목욕을 할 때 잔잔한 자연의 소리를 틀어 주세요. 물의 조화가 가장 고집스러운 아이도 잠들 준비를 하게 해 줄 거예요.', title_nl = 'Harmonie van water 🛀', body_nl = 'Jullie zijn allebei op van een hele dag rennen. Zet tijdens het lauwe bad rustgevende natuurgeluiden op de achtergrond aan. De harmonie van water maakt zelfs het koppigste kind klaar voor de slaap.', title_pl = 'Harmonia wody 🛀', body_pl = 'Po całym dniu biegania oboje jesteście wykończeni. Podczas ciepłej kąpieli włącz w tle kojące odgłosy natury. Harmonia wody przygotuje do snu nawet najbardziej upartego malucha.', title_pt = 'A harmonia da água 🛀', body_pt = 'Depois de correrem o dia todo, estão os dois esgotados. Durante o banho morno, ponha sons calmantes da natureza em fundo. A harmonia da água vai preparar para o sono até a criança mais teimosa.', title_sv = 'Vattnets harmoni 🛀', body_sv = 'Både du och barnet är helt slut efter en hel dag i farten. Sätt på lugnande naturljud i bakgrunden under det ljumma badet. Vattnets harmoni förbereder även det envisaste barnet för sömn.', title_vi = 'Sự hòa quyện của nước 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều kiệt sức. Khi bé tắm nước ấm, hãy bật âm thanh thiên nhiên êm dịu phía sau. Sự hòa quyện của nước sẽ giúp cả đứa trẻ bướng bỉnh nhất sẵn sàng đi ngủ.', title_zh = '水的和谐 🛀', body_zh = '跑了一整天，宝宝和你都累坏了。洗温水澡时，在背景里放些舒缓的大自然声音。水的和谐连最倔的孩子都能带入睡眠准备。' WHERE id = '447f446e-b226-43bb-8269-02d7d4965189' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rabieta en el súper 🛒', body_es = '¿Grita por unas chuches delante de la caja? No hagas ningún caso de las miradas de «niño malo» de los demás. Míralo a los ojos con calma, explícale la regla y mantente firme.', title_fr = 'Crise au supermarché 🛒', body_fr = 'Il hurle pour des bonbons devant la caisse ? Ignorez totalement les regards du genre « quel enfant mal élevé ». Regardez-le calmement dans les yeux, expliquez la règle et ne cédez pas.', title_hi = 'बाज़ार में नखरे 🛒', body_hi = 'कैश काउंटर के सामने मिठाई के लिए चिल्ला रहा है? आसपास के लोगों की ''बिगड़ा बच्चा'' वाली नज़रों की बिल्कुल परवाह मत कीजिए। शांति से आँखों में आँखें डालकर नियम समझाइए और अपनी बात पर टिकी रहिए।', title_id = 'Tantrum di supermarket 🛒', body_id = 'Ia berteriak minta permen di depan kasir? Sama sekali abaikan tatapan ''anak nakal'' dari orang sekitar. Tatap matanya dengan tenang, jelaskan aturannya, dan tetaplah teguh.', title_ja = 'スーパーでのかんしゃく 🛒', body_ja = 'レジの前でお菓子をほしがって叫びますか？「悪い子」と言いたげな周りの視線は気にしないで。落ち着いて目を合わせてルールを説明し、態度を変えないでいましょう。', title_ko = '마트에서 떼쓰기 🛒', body_ko = '계산대 앞에서 사탕을 사 달라고 소리 지르나요? ''버릇없는 아이''라는 주변 시선은 절대 신경 쓰지 마세요. 차분히 눈을 맞추고 규칙을 설명하되 입장은 흔들리지 마세요.', title_nl = 'Driftbui in de supermarkt 🛒', body_nl = 'Schreeuwt hij bij de kassa om snoep? Trek je helemaal niets aan van de ''stout kind''-blikken van anderen. Maak rustig oogcontact, leg de regel uit en houd voet bij stuk.', title_pl = 'Napad złości w sklepie 🛒', body_pl = 'Krzyczy przy kasie, bo chce słodyczy? Nie zwracaj żadnej uwagi na spojrzenia innych mówiące „niegrzeczne dziecko”. Spokojnie nawiąż kontakt wzrokowy, wytłumacz zasadę i nie zmieniaj zdania.', title_pt = 'Birra no supermercado 🛒', body_pt = 'Grita por doces em frente à caixa? Não ligue nada aos olhares de "criança mal-educada" à volta. Estabeleça contacto visual com calma, explique a regra e mantenha a sua posição.', title_sv = 'Utbrott i affären 🛒', body_sv = 'Skriker barnet efter godis vid kassan? Bry dig absolut inte om de andras blickar som säger ”vilket bortskämt barn”. Skapa lugnt ögonkontakt, förklara regeln och stå fast.', title_vi = 'Ăn vạ ở siêu thị 🛒', body_vi = 'Bé la hét đòi kẹo trước quầy thanh toán? Tuyệt đối đừng bận tâm đến ánh nhìn "đứa trẻ hư" của người xung quanh. Hãy bình tĩnh nhìn vào mắt bé, giải thích quy tắc và giữ vững lập trường.', title_zh = '超市里的大哭大闹 🛒', body_zh = '在收银台前为了糖果大喊大叫？完全别在意旁人“坏孩子”的目光。平静地和宝宝对视，解释规则，保持你的立场。' WHERE id = '706c71ad-a073-4d24-bc8e-9dc899c5ba4e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se acumulan las tareas? Que se acumulen. Pide a tu compañero de equipo que hoy se encargue de las tareas de casa. Tú descansa: eres la persona más importante de esta casa y la que más necesita energía.', body_fr = 'Les tâches s''accumulent ? Laissez-les. Demandez à votre coéquipier de prendre en charge les tâches ménagères aujourd''hui. Reposez-vous, vous êtes la personne la plus importante de cette maison, celle qui a le plus besoin d''énergie.', body_hi = 'काम बाकी हैं? रहने दीजिए। अपने टीम पार्टनर से कहिए कि आज घर के काम वे संभाल लें। आप आराम कीजिए, आप इस घर की सबसे ज़रूरी इंसान हैं जिसे ऊर्जा की ज़रूरत है।', body_id = 'Pekerjaan menumpuk? Biarkan saja. Mintalah rekan setim Anda mengambil alih pekerjaan rumah hari ini. Anda beristirahatlah, Anda orang terpenting di rumah ini yang paling butuh energi.', body_ja = '家事が残っている？そのままでいいんです。今日の家事はチームメイトのパートナーにお願いしましょう。あなたは休んで、この家でいちばん大切で、元気が必要な人なのですから。', body_ko = '일이 밀렸나요? 그냥 두세요. 오늘 집안일은 팀 동료인 배우자에게 맡겨 달라고 하세요. 엄마는 쉬세요. 엄마가 이 집에서 가장 중요하고 에너지가 필요한 사람이에요.', body_nl = 'Blijft er werk liggen? Laat maar liggen. Vraag je teamgenoot om vandaag het huishouden op zich te nemen. Rust jij uit, jij bent de belangrijkste persoon in dit huis en hebt energie nodig.', body_pl = 'Obowiązki czekają? Niech czekają. Poproś partnera, żeby dziś przejął domowe obowiązki. Ty odpocznij, jesteś w tym domu najważniejszą osobą i potrzebujesz energii.', body_pt = 'As tarefas acumulam-se? Deixe ficar. Peça ao seu companheiro de equipa que trate hoje das tarefas de casa. Descanse: é a pessoa mais importante desta casa e a que mais precisa de energia.', body_sv = 'Blir sysslorna liggande? Låt dem ligga. Be din lagkamrat ta över hushållet i dag. Vila du, du är den viktigaste personen i det här hemmet och den som behöver mest energi.', body_vi = 'Việc còn tồn đọng? Cứ để đó. Hãy nhờ "đồng đội" của mẹ đảm nhận việc nhà hôm nay. Mẹ hãy nghỉ ngơi, mẹ là người quan trọng nhất và cần được nạp năng lượng nhất trong nhà này.', body_zh = '事情做不完？就放着吧。请你的“队友”今天把家务都包下来。你去休息，你是这个家里最重要、也最需要能量的人。' WHERE id = '295a4c1e-3bba-40c5-820d-04095aefe60e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Habéis superado un día difícil. Cuando tu peque se duerma, tomaos un té con tu pareja y motivaos diciendo: «De verdad lo estamos haciendo genial».', body_fr = 'Vous avez laissé derrière vous une journée difficile. Une fois l''enfant couché, servez-vous un thé avec votre partenaire et motivez-vous : « On s''en sort vraiment très bien. »', body_hi = 'एक मुश्किल दिन पीछे छोड़ दिया। बच्चे के सोने के बाद अपने पार्टनर के साथ चाय पीजिए और ''हम सच में यह काम बहुत अच्छे से संभाल रहे हैं'' कहकर एक-दूसरे का हौसला बढ़ाइए।', body_id = 'Satu hari berat sudah terlewati. Setelah anak tidur, seduh teh bersama pasangan dan saling menyemangati dengan berkata ''Kita benar-benar hebat menjalani ini''.', body_ja = '大変な一日を乗りこえました。お子さんが眠ったら、パートナーとお茶をいれて「わたしたち、本当によくやってるね」とお互いを励まし合いましょう。', body_ko = '힘든 하루를 또 이겨 냈어요. 아이가 잠들면 배우자와 차 한잔 따르며 ''우리 정말 잘하고 있어'' 하고 서로를 북돋아 주세요.', body_nl = 'Jullie hebben weer een zware dag achter de rug. Schenk als hij slaapt samen met je partner thee in en motiveer elkaar met ''We doen dit echt geweldig''.', body_pl = 'Kolejny trudny dzień za wami. Gdy dziecko zaśnie, nalejcie sobie z partnerem herbaty i zmotywujcie się nawzajem słowami: „Naprawdę świetnie sobie z tym radzimy”.', body_pt = 'Deixaram para trás um dia difícil. Depois de a criança adormecer, sirvam-se de um chá e motivem-se um ao outro: "Estamos mesmo a sair-nos lindamente nisto."', body_sv = 'Ni har en tuff dag bakom er. När barnet har somnat, häll upp te med din partner och peppa varandra med ”vi klarar verkligen det här jättebra”.', body_vi = 'Hai người đã vượt qua một ngày khó khăn. Khi bé ngủ, hãy cùng chồng pha một tách trà và động viên nhau: "Chúng mình thật sự làm rất tốt".', body_zh = '你们又熬过了艰难的一天。孩子睡着后，和另一半倒杯茶，说一句“我们真的把这件事做得很好”，互相打打气吧。' WHERE id = '546e217e-8060-4a89-877d-29e71165dae1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Da sentido a los dibujos 📖', body_es = '¿Toca los personajes del libro y pregunta «¿Qué hace este?»? Su percepción visual es asombrosa. Escribid juntos un final nuevo y totalmente inventado para el libro que leéis.', title_fr = 'Il donne du sens aux images 📖', body_fr = 'Il touche les personnages des livres et demande « Qu''est-ce qu''il fait ? » Sa perception visuelle est étonnante. Écrivez ensemble une nouvelle fin, totalement inventée, au livre que vous lisez.', title_hi = 'तस्वीरों को मतलब देता है 📖', body_hi = 'किताब के किरदारों को देखकर उन्हें छूता है और पूछता है ''यह क्या कर रहा है?'' उसकी देखकर समझने की क्षमता कमाल की है। साथ मिलकर पढ़ी जा रही किताब का एक नया, पूरी तरह गढ़ा हुआ अंत लिखिए।', title_id = 'Memberi makna pada gambar 📖', body_id = 'Saat melihat tokoh-tokoh di buku, ia menyentuhnya dan bertanya ''Dia sedang apa?'' Persepsi visualnya luar biasa. Tulislah akhir cerita yang baru dan sepenuhnya karangan untuk buku yang kalian baca bersama.', title_ja = '絵の意味がわかる 📖', body_ja = '絵本のキャラクターを見て、さわりながら「これ、なにしてるの？」と聞きますか？視覚的な理解力がすばらしいですね。一緒に読んでいる絵本に、新しくてまったくオリジナルの結末を考えてみましょう。', title_ko = '그림의 의미를 알아요 📖', body_ko = '책 속 등장인물을 만지며 ''이건 뭐 해?'' 하고 묻나요? 시각 인지가 놀라워요. 함께 읽는 책에 완전히 새로운 상상의 결말을 지어 보세요.', title_nl = 'Hij geeft betekenis aan plaatjes 📖', body_nl = 'Raakt hij de figuren in een boek aan en vraagt hij ''Wat doet die?'' Zijn visuele waarneming is geweldig. Verzin samen een nieuw, helemaal zelfbedacht einde voor het boek dat jullie lezen.', title_pl = 'Nadaje sens obrazkom 📖', body_pl = 'Dotyka postaci w książeczce i pyta: „Co to robi?”. Jego percepcja wzrokowa jest niesamowita. Wymyślcie razem nowe, zupełnie zmyślone zakończenie książki, którą czytacie.', title_pt = 'Dá significado às imagens 📖', body_pt = 'Toca nas personagens do livro e pergunta "O que está a fazer?" A perceção visual é espantosa. Escrevam juntos um final novo e totalmente inventado para o livro que estão a ler.', title_sv = 'Barnet ger bilderna mening 📖', body_sv = 'Rör barnet vid figurerna i boken och frågar ”vad gör den?”. Synuppfattningen är fantastisk. Skriv tillsammans ett nytt, helt påhittat slut på boken ni läser.', title_vi = 'Bé hiểu ý nghĩa tranh ảnh 📖', body_vi = 'Thấy nhân vật trong sách, bé chạm vào và hỏi "Bạn này đang làm gì?". Khả năng nhận thức thị giác của bé thật đáng kinh ngạc. Hãy cùng bé viết một cái kết mới, hoàn toàn tưởng tượng cho cuốn sách hai mẹ con đang đọc.', title_zh = '给图片赋予意义 📖', body_zh = '看到书里的角色就去摸，还问“这是在干什么？”视觉感知真是惊人。和宝宝一起给正在读的书编一个全新的、完全虚构的结局吧。' WHERE id = 'f23e5345-9d7c-4e2d-871d-a259a849da6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Síndrome de la limpieza 🌪️', body_es = '¿Has fregado y barrido la casa, pero 10 minutos después todo vuelve a parecer una zona de explosión? Hoy ríndete al desorden. Siéntate en el sofá y no te levantes hasta terminarte el café.', title_fr = 'Le syndrome du ménage 🌪️', body_fr = 'Vous avez tout nettoyé et 10 minutes plus tard, la maison ressemble de nouveau à un champ de bataille ? Aujourd''hui, rendez-vous face au désordre. Asseyez-vous sur le canapé et ne bougez pas avant d''avoir fini votre café.', title_hi = 'सफ़ाई सिंड्रोम 🌪️', body_hi = 'घर झाड़-पोंछकर साफ़ किया, लेकिन 10 मिनट बाद सब कुछ फिर से धमाके वाली जगह जैसा लगता है? आज बिखराव के आगे हार मान लीजिए। सोफ़े पर बैठिए और कॉफ़ी खत्म होने तक उठिए मत।', title_id = 'Sindrom bersih-bersih 🌪️', body_id = 'Rumah sudah disapu dan dipel, tetapi 10 menit kemudian semuanya kembali seperti zona ledakan? Hari ini menyerahlah pada kekacauan. Duduklah di sofa dan jangan bangkit sampai kopi Anda habis.', title_ja = 'お掃除症候群 🌪️', body_ja = '家をきれいにしたのに、10分後にはまた爆発現場のよう？今日は散らかりに降参しましょう。ソファに座って、コーヒーを飲み終わるまで立ち上がらないで。', title_ko = '청소 강박 🌪️', body_ko = '쓸고 닦았는데 10분 만에 다시 폭탄 맞은 것 같나요? 오늘은 어질러짐에 항복하세요. 소파에 앉아 커피를 다 마실 때까지 일어나지 마세요.', title_nl = 'Opruimsyndroom 🌪️', body_nl = 'Heb je het huis gepoetst en gezogen, maar lijkt alles 10 minuten later weer een rampgebied? Geef je vandaag over aan de rommel. Ga op de bank zitten en sta pas op als je koffie op is.', title_pl = 'Syndrom sprzątania 🌪️', body_pl = 'Wysprzątałaś dom, a 10 minut później wszystko znów wygląda jak po wybuchu? Dziś poddaj się bałaganowi. Usiądź na kanapie i nie wstawaj, dopóki nie dopijesz kawy.', title_pt = 'Síndrome das limpezas 🌪️', body_pt = 'Limpou e varreu a casa, mas 10 minutos depois parece outra vez uma zona de explosão? Hoje renda-se à desarrumação. Sente-se no sofá e não se levante até acabar o café.', title_sv = 'Städsyndromet 🌪️', body_sv = 'Du har torkat och sopat hemma, men 10 minuter senare ser allt ut som en explosionszon igen? Ge upp inför stöket i dag. Sätt dig i soffan och res dig inte förrän kaffet är slut.', title_vi = 'Hội chứng dọn dẹp 🌪️', body_vi = 'Mẹ vừa lau dọn nhà cửa, nhưng 10 phút sau mọi thứ lại như bãi chiến trường? Hôm nay hãy đầu hàng sự bừa bộn. Ngồi xuống sofa và đừng đứng dậy cho đến khi uống hết ly cà phê.', title_zh = '打扫综合征 🌪️', body_zh = '家里刚拖完扫完，10分钟后又像爆炸现场？今天就向凌乱投降吧。坐在沙发上，喝完咖啡之前别起身。' WHERE id = '3edbcdb0-49d0-4dd6-973b-d76b6099a642' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La solución diplomática de papá 👨‍👧', body_es = '¿Tu «Acábate la comida» ya no funciona? Pásale la pelota a papá. Cuando convierte la cuchara en una nave espacial, la tozudez desaparece como por arte de magia. Descansa y disfruta del espectáculo.', title_fr = 'La solution diplomatique de papa 👨‍👧', body_fr = 'Votre « Finis ton assiette » ne marche plus ? Passez la balle à papa. Quand il transforme la cuillère en vaisseau spatial, l''entêtement disparaît comme par miracle. Reposez-vous et profitez du spectacle.', title_hi = 'पापा का कूटनीतिक हल 👨‍👧', body_hi = 'आपका ''खाना खत्म करो'' अब असर नहीं करता? बॉल पापा के पाले में डालिए। जब वे चम्मच को उड़ता अंतरिक्ष यान बनाते हैं, तो ज़िद न जाने कैसे गायब हो जाती है। आराम कीजिए और नज़ारा देखिए।', title_id = 'Solusi diplomatis Ayah 👨‍👧', body_id = 'Kalimat ''Habiskan makananmu'' dari Anda sudah tidak mempan? Oper bolanya kepada Ayah. Saat ia menjadikan sendok pesawat luar angkasa, sifat keras kepala entah bagaimana lenyap secara ajaib. Beristirahatlah dan saksikan pertunjukannya.', title_ja = 'パパの外交的解決 👨‍👧', body_ja = 'あなたの「ごはん食べちゃって」はもう効かない？パパにバトンを渡しましょう。パパがスプーンを空飛ぶ宇宙船にすると、がんこさがなぜか魔法のように消えます。休みながら見守って。', title_ko = '아빠의 외교적 해결책 👨‍👧', body_ko = '''밥 다 먹어야지''가 더는 통하지 않나요? 아빠에게 공을 넘기세요. 아빠가 숟가락을 우주선으로 만들면 고집이 신기하게 사라져요. 쉬면서 구경하세요.', title_nl = 'Papa''s diplomatieke oplossing 👨‍👧', body_nl = 'Werkt jouw ''Eet je bord leeg'' niet meer? Speel de bal naar papa. Zodra hij van de lepel een vliegend ruimteschip maakt, verdwijnt de koppigheid als bij toverslag. Rust uit en geniet van de show.', title_pl = 'Dyplomatyczne rozwiązanie taty 👨‍👧', body_pl = 'Twoje „Dokończ jedzenie” już nie działa? Podaj piłeczkę tacie. Gdy zamienia łyżkę w latający statek kosmiczny, upór w cudowny sposób znika. Odpocznij i oglądaj przedstawienie.', title_pt = 'A solução diplomática do pai 👨‍👧', body_pt = 'O seu "Acaba a comida" já não resulta? Passe a bola ao pai. Quando ele transforma a colher numa nave espacial, a teimosia desaparece como por milagre. Descanse e assista ao espetáculo.', title_sv = 'Pappas diplomatiska lösning 👨‍👧', body_sv = 'Biter ditt ”Ät upp maten” inte längre? Passa bollen till pappa. När han låter skeden bli ett rymdskepp försvinner envisheten på något mirakulöst sätt. Vila och titta på föreställningen.', title_vi = 'Giải pháp ngoại giao của bố 👨‍👧', body_vi = 'Câu "Ăn hết đi con" của mẹ không còn tác dụng? Hãy "chuyền bóng" cho bố. Khi bố biến chiếc thìa thành tàu vũ trụ, sự bướng bỉnh bỗng biến mất thần kỳ. Mẹ cứ nghỉ ngơi và xem màn trình diễn.', title_zh = '爸爸的外交方案 👨‍👧', body_zh = '你那句“把饭吃完”已经不管用了？把球传给爸爸。他把勺子变成飞行的宇宙飞船时，倔强不知怎么就神奇地消失了。休息一下，看这场好戏吧。' WHERE id = '3eea40c1-536e-46c3-bd20-2051d2e3ccae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El abogado de la mañana en acción 💼', body_es = '«¡No me pongo esta camiseta, me pongo la otra!». Ya no hay un niño en la habitación, sino un pequeño abogado que negocia contigo como un profesional. No discutas: ofrécele 2 opciones y dale la ilusión de que decide él.', title_fr = 'Le petit avocat du matin au travail 💼', body_fr = '« Pas ce t-shirt, je mets l''autre ! » Ce n''est plus un enfant dans la chambre, mais un petit avocat qui négocie avec vous comme un pro. Ne discutez pas, proposez-lui simplement 2 choix pour lui donner l''illusion de décider.', title_hi = 'सुबह का वकील काम पर 💼', body_hi = '''यह शर्ट नहीं, वह वाली पहनूँगा!'' कमरे में अब बच्चा नहीं, आपसे पेशेवर बहस करने वाला नन्हा वकील है। बहस मत कीजिए, बस उसे 2 विकल्प देकर यह एहसास दिलाइए कि फ़ैसला उसने लिया।', title_id = 'Pengacara pagi sedang bertugas 💼', body_id = '''Aku tidak mau baju ini, aku mau yang itu!'' Di kamar kini bukan lagi anak kecil, tetapi pengacara cilik yang berdebat dengan Anda secara profesional. Jangan berdebat, cukup beri 2 pilihan agar ia merasa dialah yang memutuskan.', title_ja = '朝の弁護士さん、出勤中 💼', body_ja = '「このシャツじゃなくて、あっちを着る！」部屋にいるのはもう子どもではなく、あなたと本格的に交渉する小さな弁護士です。言い争わず、2つの選択肢を出して、自分で決めたと感じさせてあげましょう。', title_ko = '아침의 꼬마 변호사 출근 💼', body_ko = '''이 옷 말고 저 옷 입을 거야!'' 이제 방에는 아이가 아니라 엄마와 협상하는 꼬마 변호사가 있어요. 다투지 말고 두 가지만 보여 주며 스스로 정했다고 느끼게 해 주세요.', title_nl = 'De ochtendadvocaat aan het werk 💼', body_nl = '''Niet dit shirt, ik wil dat andere!'' Er staat geen kind meer in de kamer, maar een kleine advocaat die als een prof met je onderhandelt. Ga niet in discussie, geef hem 2 keuzes en laat hem denken dat hij beslist.', title_pl = 'Poranny adwokat w akcji 💼', body_pl = '„Nie założę tej koszulki, tylko tamtą!”. W pokoju nie ma już dziecka, tylko mały adwokat, który prowadzi z tobą zawodowe negocjacje. Nie kłóć się, po prostu daj mu 2 opcje i stwórz iluzję, że to on decyduje.', title_pt = 'O advogado matinal ao serviço 💼', body_pt = '"Não visto esta camisola, visto a outra!" Já não tem uma criança no quarto, mas um pequeno advogado que negoceia consigo como um profissional. Não discuta: ofereça-lhe 2 opções e crie a ilusão de que é ele quem decide.', title_sv = 'Morgonens advokat i tjänst 💼', body_sv = '”Jag vill inte ha den här tröjan, jag vill ha den andra!” Nu är det inte ett barn i rummet, utan en liten advokat som förhandlar professionellt med dig. Bråka inte, ge bara 2 val och skapa illusionen av att hen bestämmer.', title_vi = 'Luật sư buổi sáng đang làm việc 💼', body_vi = '"Con không mặc áo này, con mặc áo kia cơ!" Trong phòng giờ không còn là em bé mà là một luật sư nhí đang tranh luận chuyên nghiệp với mẹ. Đừng cãi nhau, chỉ cần đưa ra 2 lựa chọn để bé có cảm giác mình được quyết định.', title_zh = '早晨的小律师上班了 💼', body_zh = '“我不穿这件，我要穿那件！”房间里已经不是小孩，而是一位和你专业谈判的小律师。别争论，给出2个选择，让宝宝觉得是自己做的决定。' WHERE id = 'ac669cdb-bbf4-4741-8460-56b46118bbec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cambia el horario de sueño? 😭', body_es = 'Se ha despertado en mitad de la noche y no quiere dormir. No te enfades. Averigua la causa, acaríciale haciéndole sentir que estás a su lado y espera a que el sueño le venza.', title_fr = 'Le rythme de sommeil change ? 😭', body_fr = 'Il s''est réveillé en pleine nuit et ne veut pas se rendormir. Ne vous énervez pas. Cherchez la cause, caressez-le simplement en lui faisant sentir que vous êtes là et attendez que le sommeil l''emporte.', title_hi = 'नींद का शेड्यूल बदल रहा है? 😭', body_hi = 'आधी रात को जाग गया और सोना नहीं चाहता? उस पर गुस्सा मत कीजिए। वजह पता कीजिए, बस यह महसूस कराते हुए सहलाइए कि आप पास हैं, और नींद आने का इंतज़ार कीजिए।', title_id = 'Jadwal tidur berubah? 😭', body_id = 'Ia terbangun tengah malam dan tidak mau tidur lagi. Jangan kesal padanya. Pastikan penyebabnya, usap ia sambil menunjukkan bahwa Anda ada di sisinya, dan tunggu hingga ia kembali terlelap.', title_ja = '睡眠スケジュールが変わる？😭', body_ja = '真夜中に目を覚まして、眠ろうとしない？イライラしないで。原因を確かめて、そばにいることを感じさせながらやさしくなで、眠りに落ちるのを待ちましょう。', title_ko = '수면 일과가 바뀌나요? 😭', body_ko = '한밤중에 깨서 다시 자려 하지 않나요? 화내지 마세요. 이유를 살펴보고 곁에 있다는 걸 느끼게 하며 쓰다듬어 주고, 다시 잠들 때까지 기다려 주세요.', title_nl = 'Verandert het slaapschema? 😭', body_nl = 'Hij is midden in de nacht wakker en wil niet slapen. Word niet boos op hem. Zoek uit wat de oorzaak is, aai hem zodat hij voelt dat je bij hem bent en wacht tot de slaap hem overneemt.', title_pl = 'Zmienia się plan snu? 😭', body_pl = 'Obudził się w środku nocy i nie chce spać? Nie złość się na niego. Ustal przyczynę, pogłaszcz go, dając poczuć, że jesteś obok, i poczekaj, aż podda się snowi.', title_pt = 'O horário de sono está a mudar? 😭', body_pt = 'Acordou a meio da noite e não quer dormir? Não se irrite com ele. Descubra a causa, faça-lhe festinhas, mostre que está ali ao lado e espere que se renda ao sono.', title_sv = 'Ändras sömnschemat? 😭', body_sv = 'Barnet har vaknat mitt i natten och vill inte sova. Bli inte arg. Ta reda på orsaken, smek barnet så att hen känner att du är där och vänta tills sömnen tar över.', title_vi = 'Lịch ngủ đang thay đổi? 😭', body_vi = 'Bé thức dậy giữa đêm và không chịu ngủ lại. Đừng bực bé. Hãy xác định nguyên nhân, nhẹ nhàng vuốt ve để bé cảm nhận mẹ ở bên và chờ bé chìm vào giấc ngủ.', title_zh = '睡眠作息在变？😭', body_zh = '半夜醒来，就是不肯睡？别对宝宝发火。弄清原因，轻轻抚摸宝宝，让宝宝感觉到你就在身边，等宝宝慢慢睡着。' WHERE id = '076945c8-0a00-4e34-b0d0-2a0bb6a70d19' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sorpresas del tiempo ⛅', body_es = 'Al salir de paseo, no te fíes del tiempo y evita que se enfríe. No decidas solo mirando por la ventana: elige con Tiempo y ropa el conjunto más adecuado para el viento de fuera y sal de casa tranquila.', title_fr = 'Surprise météo ⛅', body_fr = 'Ne vous laissez pas tromper par le temps et ne le laissez pas prendre froid en promenade. Ne décidez pas en regardant par la fenêtre : avec Météo et tenue, choisissez la tenue la mieux adaptée au vent et sortez sereinement.', title_hi = 'मौसम का सरप्राइज़ ⛅', body_hi = 'सैर पर जाते समय मौसम के धोखे में आकर उसे ठंड मत लगने दीजिए। सिर्फ़ खिड़की से देखकर फ़ैसला मत कीजिए, मौसम और कपड़े असिस्टेंट से बाहर की हवा के हिसाब से सबसे सही कपड़े चुनिए और आराम से निकलिए।', title_id = 'Kejutan cuaca ⛅', body_id = 'Saat jalan-jalan, jangan tertipu cuaca hingga ia kedinginan. Jangan memutuskan hanya dengan melihat dari jendela, tentukan setelan yang paling pas untuk angin di luar dengan alat Cuaca dan Pakaian, lalu keluarlah dengan tenang.', title_ja = '天気のサプライズ ⛅', body_ja = 'お散歩のとき、見た目の天気にだまされて体を冷やさないように。窓から見て決めずに、「天気と服装」で外の風にいちばん合うコーディネートを決めて、安心して出かけましょう。', title_ko = '날씨의 변덕 ⛅', body_ko = '산책할 때 날씨에 속아 아이를 춥게 하지 마세요. 창밖만 보고 정하지 말고 날씨와 옷차림 도우미로 바깥바람에 가장 알맞은 옷차림을 정한 뒤 편하게 나가세요.', title_nl = 'Weersverrassing ⛅', body_nl = 'Laat je niet misleiden door het weer als je gaat wandelen, zodat hij het niet koud krijgt. Beslis niet door uit het raam te kijken, maar kies met Weer en kleding de outfit die het best past bij de wind buiten en ga rustig de deur uit.', title_pl = 'Pogodowa niespodzianka ⛅', body_pl = 'Wychodząc na spacer, nie daj się zwieść pogodzie, żeby go nie przeziębić. Nie decyduj, patrząc przez okno, tylko dobierz w narzędziu Pogoda i ubiór zestaw najlepiej pasujący do wiatru i spokojnie wyjdźcie.', title_pt = 'Surpresas do tempo ⛅', body_pt = 'Quando saírem para passear, não se deixe enganar pelo tempo e evite que ele apanhe frio. Não decida só pela janela: escolha no Tempo e Roupa a combinação mais adequada ao vento lá fora e saiam descansados.', title_sv = 'Väderöverraskning ⛅', body_sv = 'Låt dig inte luras av vädret så att barnet fryser på promenaden. Bestäm inte genom att titta ut genom fönstret, välj den klädsel som passar bäst för vinden ute med assistenten Väder och kläder och gå lugnt hemifrån.', title_vi = 'Bất ngờ từ thời tiết ⛅', body_vi = 'Khi ra ngoài đi dạo, đừng để thời tiết đánh lừa khiến bé bị lạnh. Đừng quyết định chỉ bằng cách nhìn qua cửa sổ, hãy dùng trợ lý Thời tiết và trang phục để chọn cách phối đồ hợp với gió bên ngoài và yên tâm ra khỏi nhà.', title_zh = '天气的惊喜 ⛅', body_zh = '出门散步时，别被天气骗了，让宝宝着凉。别只看窗外做决定，用天气穿衣助手找到最适合外面风力的搭配，安心出门。' WHERE id = '3d9ffa52-2fa2-4130-82de-58bdbc77e7b6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las ventajas del juego libre 🧸', body_es = 'No tienes por qué entretenerle cada minuto ni inventarle juegos. Aburrirse es el primer peldaño de la creatividad para los niños. Deja que descubra algo él solo en la habitación.', title_fr = 'Les bienfaits du jeu libre 🧸', body_fr = 'Vous n''êtes pas obligée de l''amuser et de lui inventer des jeux à chaque minute. Chez l''enfant, l''ennui est la première marche de la créativité. Laissez-le découvrir quelque chose tout seul dans la chambre.', title_hi = 'खुले खेल का फ़ायदा 🧸', body_hi = 'आपको हर मिनट उसका मनोरंजन करने, उसके लिए खेल गढ़ने की ज़रूरत नहीं है। बच्चों के लिए ऊब रचनात्मकता की पहली सीढ़ी है। उसे कमरे में अकेले कुछ खोजने दीजिए।', title_id = 'Manfaat bermain bebas 🧸', body_id = 'Anda tidak wajib menghiburnya atau mengarang permainan setiap menit. Bagi anak, rasa bosan adalah langkah pertama menuju kreativitas. Biarkan ia menemukan sesuatu sendiri di kamar.', title_ja = '自由遊びのよさ 🧸', body_ja = 'いつもお子さんを楽しませたり、遊びを考えたりしなくてもいいんです。退屈は、子どもにとって創造性の第一歩。部屋でひとりで何かを発見させてあげましょう。', title_ko = '자유 놀이의 힘 🧸', body_ko = '매 순간 아이를 즐겁게 해 주고 놀이를 만들어 줄 필요는 없어요. 심심함은 아이 창의력의 첫걸음이에요. 방에서 혼자 무언가를 발견하게 두세요.', title_nl = 'Het nut van vrij spel 🧸', body_nl = 'Je hoeft hem niet elke minuut te vermaken of spelletjes te verzinnen. Verveling is voor kinderen de eerste stap naar creativiteit. Laat hem in zijn eentje in de kamer iets ontdekken.', title_pl = 'Zalety swobodnej zabawy 🧸', body_pl = 'Nie musisz zabawiać go co minutę i wymyślać mu zabaw. Nuda to dla dzieci pierwszy stopień kreatywności. Pozwól mu samemu coś odkryć w pokoju.', title_pt = 'O valor do brincar livre 🧸', body_pt = 'Não tem de o entreter nem de inventar jogos a cada minuto. O aborrecimento é, para as crianças, o primeiro degrau da criatividade. Deixe-o descobrir algo sozinho no quarto.', title_sv = 'Fördelen med fri lek 🧸', body_sv = 'Du måste inte underhålla barnet varje minut eller hitta på lekar hela tiden. Tristess är det första steget mot kreativitet för barn. Låt barnet upptäcka något på egen hand i rummet.', title_vi = 'Lợi ích của chơi tự do 🧸', body_vi = 'Mẹ không cần phải lúc nào cũng giải trí cho bé hay nghĩ ra trò chơi. Buồn chán là bậc thang đầu tiên của sự sáng tạo ở trẻ. Hãy để bé tự khám phá điều gì đó trong phòng.', title_zh = '自由玩耍的好处 🧸', body_zh = '你不必每分每秒都逗宝宝玩、给宝宝编游戏。无聊是孩子创造力的第一步。让宝宝在房间里自己去探索点什么吧。' WHERE id = '50a3f6bc-f0a4-4606-972d-9c8a2cc70695' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lo que se olvida en la lista de la compra 🛒', body_es = '¿Siempre se te olvida lo más importante al ir al súper? La Lista de la compra te espera en la app. Apunta ahí lo que falta y que tu pareja lo compre sin fallo al volver del trabajo.', title_fr = 'Les oubliés de la liste de courses 🛒', body_fr = 'Vous oubliez toujours l''article le plus important au supermarché ? La Liste de courses vous attend dans l''application. Notez-y vos besoins, votre partenaire fera les courses avec précision en rentrant du travail.', title_hi = 'शॉपिंग लिस्ट में भूली चीज़ें 🛒', body_hi = 'बाज़ार जाते समय सबसे ज़रूरी चीज़ ज़रूर भूल जाती हैं? ऐप में शॉपिंग लिस्ट आपका इंतज़ार कर रही है। ज़रूरतें वहाँ लिखिए, ताकि आपके पार्टनर काम से लौटते समय सब कुछ ठीक-ठीक ले आएँ।', title_id = 'Yang terlupa dari daftar belanja 🛒', body_id = 'Selalu lupa barang paling penting saat belanja? Daftar Belanja menunggu Anda di aplikasi. Catat kebutuhan di sana, biar pasangan membelinya dengan tepat saat pulang kerja.', title_ja = '買い物リストの買い忘れ 🛒', body_ja = '買い物に行くと、いちばん大事なものを必ず忘れてしまう？アプリの「買い物リスト」が待っています。必要なものをそこに書いて、パートナーに仕事帰りにきちんと買ってきてもらいましょう。', title_ko = '쇼핑 목록에서 빠진 것 🛒', body_ko = '마트에 가면 꼭 가장 중요한 걸 잊어버리나요? 앱의 쇼핑 목록이 기다리고 있어요. 필요한 걸 적어 두면 배우자가 퇴근길에 정확히 사 올 수 있어요.', title_nl = 'Vergeten op het boodschappenlijstje 🛒', body_nl = 'Vergeet je in de supermarkt altijd net het belangrijkste? Het Boodschappenlijstje wacht op je in de app. Zet erop wat je nodig hebt, dan haalt je partner het precies op weg terug van zijn werk.', title_pl = 'Zapomniane z listy zakupów 🛒', body_pl = 'Idąc do sklepu, zawsze zapominasz o najważniejszej rzeczy? Lista zakupów czeka na ciebie w aplikacji. Zapisz tam potrzeby, a partner wracając z pracy, kupi wszystko co do joty.', title_pt = 'O que fica esquecido na lista de compras 🛒', body_pt = 'Esquece-se sempre da coisa mais importante no supermercado? A Lista de Compras espera por si na app. Aponte lá o que falta e o seu companheiro compra tudo certinho ao voltar do trabalho.', title_sv = 'Det som glöms på inköpslistan 🛒', body_sv = 'Glömmer du alltid det viktigaste när du går och handlar? Inköpslistan väntar på dig i appen. Skriv in behoven där så kan din partner handla exakt det som behövs på vägen hem från jobbet.', title_vi = 'Những thứ bị quên trong danh sách đi chợ 🛒', body_vi = 'Đi siêu thị lần nào mẹ cũng quên đúng món quan trọng nhất? Danh sách mua sắm đang chờ mẹ trong ứng dụng. Hãy ghi những thứ cần mua vào đó để chồng mua đủ trên đường đi làm về.', title_zh = '购物清单里被忘掉的东西 🛒', body_zh = '去超市总会忘掉最重要的东西？购物清单就在应用里等着你。把需要的东西记进去，让另一半下班回家时准确采购。' WHERE id = '0e8938b3-51a2-479f-a598-94b98e255136' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comunicarse con el lenguaje corporal 🗣️', body_es = 'Cuando dices «¿Nos vamos?», levanta los brazos, o niega con la cabeza con fuerza si no quiere algo. ¡Su comprensión ha crecido muchísimo! Respóndele con muchas frases de aprobación.', title_fr = 'Communiquer avec le corps 🗣️', body_fr = 'Quand vous dites « On y va ? », il lève les bras, ou secoue vivement la tête pour ce qu''il ne veut pas. Sa compréhension a fait un bond incroyable ! Répondez-lui avec beaucoup de phrases encourageantes.', title_hi = 'शारीरिक भाषा से बातचीत 🗣️', body_hi = '''चलें?'' कहने पर हाथ ऊपर उठाता है या जो नहीं चाहिए उस पर ज़ोर से सिर हिलाता है? उसकी समझ कमाल की बढ़ गई है! उसे खूब हौसला बढ़ाने वाले वाक्यों से जवाब दीजिए।', title_id = 'Berkomunikasi lewat bahasa tubuh 🗣️', body_id = 'Saat Anda bilang ''Ayo pergi?'', ia mengangkat tangannya, atau menggeleng keras pada hal yang tidak ia mau. Daya pemahamannya meningkat luar biasa! Jawablah ia dengan banyak kalimat yang meneguhkan.', title_ja = '体で伝えるコミュニケーション 🗣️', body_ja = '「行こうか？」と言うと両手を上げたり、いやなことには首を強く振ったりしますか？理解する力が驚くほど育っています！たくさん肯定の言葉で答えてあげましょう。', title_ko = '몸짓으로 소통해요 🗣️', body_ko = '''갈까?'' 하면 두 팔을 들고, 싫은 건 고개를 세차게 젓나요? 이해력이 놀랍게 자랐어요! 긍정하고 인정해 주는 말로 듬뿍 대답해 주세요.', title_nl = 'Praten met lichaamstaal 🗣️', body_nl = 'Steekt hij zijn armen omhoog als je ''Gaan we?'' zegt, of schudt hij heftig zijn hoofd bij iets wat hij niet wil? Zijn begrip is enorm gegroeid! Antwoord hem met veel bevestigende zinnen.', title_pl = 'Komunikacja mową ciała 🗣️', body_pl = 'Na „Idziemy?” podnosi rączki, a gdy czegoś nie chce, energicznie kręci głową. Jego rozumienie niesamowicie wzrosło! Odpowiadaj mu jak najczęściej zdaniami, które go potwierdzają.', title_pt = 'Comunicar com o corpo 🗣️', body_pt = 'Quando diz "Vamos?", levanta os braços, ou abana a cabeça com força quando não quer algo. A capacidade de compreensão aumentou imenso! Responda-lhe com muitas frases de confirmação.', title_sv = 'Kommunikation med kroppsspråk 🗣️', body_sv = 'Sträcker barnet upp armarna när du säger ”Ska vi gå?” eller skakar bestämt på huvudet åt något hen inte vill? Förståelsen har ökat otroligt! Svara med många bekräftande meningar.', title_vi = 'Giao tiếp bằng ngôn ngữ cơ thể 🗣️', body_vi = 'Khi mẹ hỏi "Mình đi nhé?", bé giơ tay lên, hoặc lắc đầu thật mạnh khi không muốn điều gì. Khả năng hiểu của bé đã tăng vượt bậc! Hãy đáp lại bé bằng thật nhiều lời khẳng định.', title_zh = '用肢体语言交流 🗣️', body_zh = '你说“走吧？”，宝宝就举起手臂，不想要的东西就用力摇头。理解能力提高得惊人！多用肯定的话回应宝宝吧。' WHERE id = '2b8de8fb-82bc-4b54-a795-1fffd716ddd5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Al sueño con música 🎶', body_es = 'Prueba a cortar con música clásica suave las tormentas sin motivo que estallan a última hora de la tarde. Muchas veces este truco sencillo pero eficaz hace milagros en casa y llena la habitación de paz.', title_fr = 'S''endormir en musique 🎶', body_fr = 'Essayez de stopper les tempêtes sans raison de fin d''après-midi avec une musique classique douce. Souvent, cette astuce simple mais efficace fait des miracles et ramène la paix dans la pièce.', title_hi = 'संगीत के साथ नींद की ओर 🎶', body_hi = 'शाम को अचानक उठने वाले बेवजह के तूफ़ानों को हल्के शास्त्रीय संगीत से रोककर देखिए। अक्सर यह आसान लेकिन असरदार तरकीब घर में जादू कर देती है और कमरे में पूरा सुकून ले आती है।', title_id = 'Menuju tidur dengan musik 🎶', body_id = 'Coba redakan badai tanpa sebab di sore hari dengan musik klasik yang lembut. Trik sederhana namun ampuh ini sering kali membawa keajaiban di rumah dan pasti mendatangkan ketenangan.', title_ja = '音楽で眠りへ 🎶', body_ja = '夕方に起きる理由のない嵐を、静かなクラシック音楽でしずめてみましょう。このシンプルで効果的な工夫が、家に奇跡を起こし、部屋に安らぎを運んでくれることがよくあります。', title_ko = '음악과 함께 잠으로 🎶', body_ko = '저녁 무렵 이유 없이 몰아치는 폭풍을 잔잔한 클래식 음악으로 잠재워 보세요. 이 간단하지만 효과적인 요령이 집에 기적을 일으키고 방에 평온을 가져다줄 때가 많아요.', title_nl = 'Met muziek naar dromenland 🎶', body_nl = 'Probeer de onverklaarbare buien aan het eind van de middag te stoppen met zachte klassieke muziek. Vaak doet dit simpele maar krachtige trucje wonderen en brengt het echt rust in de kamer.', title_pl = 'Zasypianie przy muzyce 🎶', body_pl = 'Spróbuj przerywać wieczorne burze bez powodu cichą muzyką klasyczną. Ta prosta, ale skuteczna sztuczka często czyni w domu cuda i na pewno wnosi do pokoju spokój.', title_pt = 'Adormecer com música 🎶', body_pt = 'Experimente travar com música clássica suave as tempestades sem razão que rebentam ao fim da tarde. Muitas vezes este truque simples, mas eficaz, faz milagres em casa e traz paz ao quarto.', title_sv = 'Musikalisk väg till sömnen 🎶', body_sv = 'Prova att stoppa eftermiddagens stormar utan orsak med lätt klassisk musik. Ofta gör det här enkla men effektiva knepet underverk hemma och ger rummet total ro.', title_vi = 'Vào giấc cùng âm nhạc 🎶', body_vi = 'Hãy thử chặn những cơn bão vô cớ lúc chiều tối bằng nhạc cổ điển nhẹ nhàng. Mẹo đơn giản nhưng hiệu quả này thường tạo nên điều kỳ diệu và mang lại bình yên cho căn phòng.', title_zh = '在音乐中进入梦乡 🎶', body_zh = '试试用轻柔的古典音乐平息傍晚莫名的风暴。这个简单却有效的小妙招，常常能在家里创造奇迹，给房间带来真正的宁静。' WHERE id = 'db645804-58ab-429b-bd1f-cae1d65c9e1e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se descoloca la rutina? ⏱️', body_es = '¿Tarda más de 1 hora en dormirse por la noche? Mira el gráfico del temporizador de sueño. Quizá hace tiempo que toca acortar del todo la siesta y adelantar la hora de dormir.', title_fr = 'Le rythme se décale ? ⏱️', body_fr = 'L''endormissement du soir prend plus d''1 heure ? Regardez le graphique du Minuteur de sommeil. Il est peut-être grand temps de raccourcir nettement la sieste et d''avancer l''heure du coucher.', title_hi = 'रूटीन खिसक रहा है? ⏱️', body_hi = 'शाम को सोने में 1 घंटे से ज़्यादा लगता है? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद को और छोटा करने और शाम का रूटीन जल्दी करने का समय कब का आ चुका है।', title_id = 'Rutinitas bergeser? ⏱️', body_id = 'Tidur malam butuh lebih dari 1 jam? Lihat grafik Timer Tidur. Mungkin sudah lama tiba waktunya memangkas tidur siang dan memajukan jam tidur malam.', title_ja = '生活リズムがずれている？⏱️', body_ja = '夜の寝かしつけに1時間以上かかりますか？睡眠タイマーのグラフを見てみましょう。お昼寝を短くして、夜の寝る時間を早める時期がとっくに来ているのかもしれません。', title_ko = '일과가 밀리나요? ⏱️', body_ko = '저녁에 잠드는 데 1시간 넘게 걸리나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 확 줄이고 잠자리 시간을 앞당길 때가 진작 되었을지도 몰라요.', title_nl = 'Verschuift het ritme? ⏱️', body_nl = 'Duurt inslapen ''s avonds langer dan een uur? Bekijk het schema in de Slaaptimer. Misschien is het allang tijd om het middagslaapje flink in te korten en de avond te vervroegen.', title_pl = 'Rytm dnia się przesuwa? ⏱️', body_pl = 'Wieczorne zasypianie trwa ponad 1 godzinę? Spójrz na wykres w timerze snu. Może już dawno czas skrócić drzemkę w ciągu dnia i przesunąć wieczór na wcześniej.', title_pt = 'A rotina está a fugir? ⏱️', body_pt = 'Adormecer à noite demora mais de 1 hora? Veja o gráfico do temporizador de sono. Talvez já tenha passado a altura de encurtar de vez a sesta e antecipar a hora de deitar.', title_sv = 'Glider rutinen iväg? ⏱️', body_sv = 'Tar det mer än 1 timme för barnet att somna på kvällen? Titta på sömntimerns diagram. Kanske är det sedan länge dags att korta dagsömnen ordentligt och tidigarelägga kvällen.', title_vi = 'Nếp sinh hoạt bị lệch? ⏱️', body_vi = 'Buổi tối bé mất hơn 1 tiếng mới ngủ được? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đã đến lúc rút ngắn hẳn giấc ngủ ngày và cho bé đi ngủ tối sớm hơn.', title_zh = '作息乱了？⏱️', body_zh = '晚上入睡要花1个多小时？看看睡眠计时器的图表。也许早就该把白天的午睡大大缩短，把晚上的入睡时间提前了。' WHERE id = '4144a3ff-720b-4a72-a2d5-5866dd12fa04' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Imitando animales 🐶', body_es = '¿No solo hace los sonidos, sino que gatea como un perro y se frota como un gato? Su lenguaje corporal y su imaginación se unen. Únete con mucha energía a este juego sobre la alfombra.', title_fr = 'Imitations d''animaux 🐶', body_fr = 'Il ne se contente plus d''imiter les cris : il marche à quatre pattes comme un chien et guette comme un chat ? Langage corporel et imagination se rejoignent. Joignez-vous à ce jeu sur le tapis avec plein d''énergie.', title_hi = 'जानवरों की नकल 🐶', body_hi = 'सिर्फ़ आवाज़ ही नहीं निकालता, कुत्ते की तरह घुटनों के बल चलता और बिल्ली की तरह शिकार करता है? शारीरिक भाषा और कल्पना मिल रही हैं। कालीन पर इस खेल में आप भी पूरे जोश से शामिल हो जाइए।', title_id = 'Meniru hewan 🐶', body_id = 'Ia tidak hanya bersuara, tetapi juga merangkak seperti anjing dan mengendap seperti kucing? Bahasa tubuh dan imajinasinya menyatu. Ikutlah bermain bersamanya di atas karpet dengan penuh semangat.', title_ja = '動物のまね 🐶', body_ja = '鳴き声だけでなく、犬のようにはいはいしたり、猫のように体をすりよせたりしますか？体の表現と想像力が結びついています。あなたも元気いっぱいにカーペットの上でこの遊びに加わりましょう。', title_ko = '동물 흉내 🐶', body_ko = '소리만 내는 게 아니라 강아지처럼 기고 고양이처럼 몸을 비비나요? 몸짓 언어와 상상력이 하나가 되고 있어요. 카펫 위에서 엄마도 신나게 이 놀이에 함께해 보세요.', title_nl = 'Dieren nadoen 🐶', body_nl = 'Maakt hij niet alleen geluidjes, maar kruipt hij ook als een hond en sluipt hij als een kat? Lichaamstaal en fantasie komen samen. Doe vol energie mee met dit spel op het tapijt.', title_pl = 'Naśladowanie zwierząt 🐶', body_pl = 'Nie tylko wydaje odgłosy, ale też raczkuje jak pies i łasi się jak kot? Mowa ciała i wyobraźnia się łączą. Dołącz do tej zabawy na dywanie z wielką energią.', title_pt = 'A imitar animais 🐶', body_pt = 'Não só faz os sons, como também gatinha como um cão e se enrosca como um gato? A linguagem corporal e a imaginação juntam-se. Entre também nesta brincadeira no tapete, cheia de energia.', title_sv = 'Djurimitationer 🐶', body_sv = 'Gör barnet inte bara ljud, utan kryper som en hund och smyger som en katt? Kroppsspråk och fantasi förenas. Var med i leken på mattan du också, med full energi.', title_vi = 'Bắt chước các con vật 🐶', body_vi = 'Bé không chỉ phát ra tiếng kêu mà còn bò như chó, rình như mèo? Ngôn ngữ cơ thể và trí tưởng tượng đang kết hợp với nhau. Hãy hào hứng cùng bé chơi trò này trên thảm.', title_zh = '模仿动物 🐶', body_zh = '不只是学叫声，还像小狗一样爬，像小猫一样扑？肢体语言和想象力结合在一起了。你也充满活力地在地毯上加入这个游戏吧。' WHERE id = '556e8775-c182-4e9f-b2c6-f0cf109ff616' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis de la siesta 🥱', body_es = '¿No quiere ir a la cama y llora? Al acercarse a los 3 años, algunos niños empiezan a dejar la siesta. En lugar de luchar, anuncia una hora de calma y proponle jugar en silencio con sus juguetes en la cama.', title_fr = 'La crise de la sieste 🥱', body_fr = 'Il ne veut pas aller au lit et pleure ? Vers 3 ans, certains enfants commencent à abandonner la sieste. Plutôt que de lutter, annoncez un « temps calme » et proposez-lui de jouer en silence avec ses jouets dans son lit.', title_hi = 'दोपहर की नींद का संकट 🥱', body_hi = 'बिस्तर पर नहीं जाना चाहता और रोता है? 3 साल के करीब कुछ बच्चे दिन की नींद छोड़ने लगते हैं। लड़ने के बजाय ''शांत समय'' घोषित कीजिए और बिस्तर पर बस खिलौनों से चुपचाप खेलने को कहिए।', title_id = 'Krisis tidur siang 🥱', body_id = 'Ia tidak mau tidur dan menangis? Menjelang usia 3 tahun sebagian anak mulai berhenti tidur siang. Daripada berdebat, umumkan ''waktu tenang'' dan tawarkan untuk bermain mainan dengan tenang di tempat tidur.', title_ja = 'お昼寝の危機 🥱', body_ja = 'ベッドに行きたがらずに泣きますか？3歳が近づくと、お昼寝をしなくなる子もいます。戦うかわりに「静かな時間」を宣言して、ベッドでおもちゃと静かに遊ぶことを提案しましょう。', title_ko = '낮잠 위기 🥱', body_ko = '자러 가기 싫다며 우나요? 세 돌 무렵 낮잠을 그만두는 아이도 있어요. 씨름하지 말고 ''조용한 시간''을 정해 침대에서 장난감으로 조용히 놀자고 해 보세요.', title_nl = 'Crisis rond het middagslaapje 🥱', body_nl = 'Wil hij niet naar bed en huilt hij? Rond de 3 jaar stoppen sommige kinderen met hun slaapje. Ga de strijd niet aan, maar kondig een rustuurtje aan en stel voor dat hij stil met speelgoed in bed speelt.', title_pl = 'Kryzys popołudniowej drzemki 🥱', body_pl = 'Nie chce iść do łóżka i płacze? Około 3. roku życia niektóre dzieci zaczynają rezygnować z drzemki. Zamiast walczyć, ogłoś godzinę wyciszenia i zaproponuj ciche bawienie się zabawkami w łóżku.', title_pt = 'A crise da sesta 🥱', body_pt = 'Não quer ir para a cama e chora? Perto dos 3 anos, algumas crianças começam a deixar a sesta. Em vez de lutar, anuncie a hora do sossego e proponha que brinque em silêncio com os brinquedos na cama.', title_sv = 'Kris kring dagsömnen 🥱', body_sv = 'Vill barnet inte gå och lägga sig och gråter? När barnet närmar sig 3 år börjar vissa sluta sova på dagen. I stället för att kämpa, utlys en Lugn stund och föreslå att barnet bara leker tyst med leksaker i sängen.', title_vi = 'Khủng hoảng giấc ngủ trưa 🥱', body_vi = 'Bé không muốn lên giường và khóc? Gần 3 tuổi, một số trẻ bắt đầu bỏ giấc ngủ ngày. Thay vì giằng co, hãy tuyên bố "Giờ yên tĩnh" và gợi ý bé lặng lẽ chơi đồ chơi trên giường.', title_zh = '午睡危机 🥱', body_zh = '不想上床，还一直哭？快3岁时，有些孩子开始不再午睡。与其对抗，不如宣布“安静时间”，让宝宝在床上安静地玩玩具。' WHERE id = 'b521243e-fc9e-4c87-849b-f17e742b8529' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No quiere dormir y le da miedo la oscuridad?', body_es = 'Oscurece del todo la habitación y haz con las manos sombras de pájaros y perros en la pared. Convierte el miedo en diversión y ayúdale a hacerse amigo de la oscuridad.', title_fr = 'Il ne veut pas dormir et a peur du noir ?', body_fr = 'Faites le noir complet dans la chambre et créez avec vos mains des ombres d''oiseau ou de chien sur le mur. En transformant la peur en jeu, aidez-le à se faire un ami du noir.', title_hi = 'सोना नहीं चाहता और अंधेरे से डरता है?', body_hi = 'कमरे में पूरा अंधेरा कीजिए और अपने हाथों से दीवार पर चिड़िया और कुत्ते की परछाइयाँ बनाइए। डर को मज़े में बदलकर अंधेरे से उसकी दोस्ती कराइए।', title_id = 'Tidak mau tidur dan takut gelap?', body_id = 'Gelapkan kamar sepenuhnya dan buat bayangan burung atau anjing di dinding dengan tangan Anda. Bantu ia berteman dengan gelap dengan mengubah rasa takut menjadi keseruan.', title_ja = '寝たがらずに、暗やみをこわがりますか？', body_ja = '部屋を真っ暗にして、手で壁に鳥や犬の影絵を作りましょう。こわさを楽しさに変えて、暗やみと仲よくなる手助けをしてあげて。', title_ko = '잠들기 싫어하고 어둠을 무서워하나요?', body_ko = '방을 완전히 어둡게 하고 손으로 벽에 새나 강아지 그림자를 만들어 보세요. 두려움을 놀이로 바꿔 어둠과 친해지도록 도와주세요.', title_nl = 'Wil hij niet slapen en is hij bang voor het donker?', body_nl = 'Maak de kamer helemaal donker en maak met je handen schaduwen van een vogel of hond op de muur. Maak van angst een spel en help hem zo vriendjes te worden met het donker.', title_pl = 'Nie chce zasnąć i boi się ciemności?', body_pl = 'Zaciemnij całkowicie pokój i twórz dłońmi na ścianie cienie ptaka i psa. Zamieniając strach w zabawę, pomożesz mu zaprzyjaźnić się z ciemnością.', title_pt = 'Não quer adormecer e tem medo do escuro?', body_pt = 'Escureça o quarto por completo e faça com as mãos sombras de pássaros e cães na parede. Transforme o medo em diversão e ajude-o a fazer amizade com o escuro.', title_sv = 'Vill barnet inte somna och är rädd för mörkret?', body_sv = 'Gör rummet helt mörkt och gör skuggor av fåglar och hundar på väggen med händerna. Gör rädslan till lek och hjälp barnet att bli vän med mörkret.', title_vi = 'Bé không chịu ngủ và sợ bóng tối?', body_vi = 'Hãy làm tối phòng hoàn toàn và dùng tay tạo bóng chim, bóng chó trên tường. Biến nỗi sợ thành niềm vui để giúp bé kết bạn với bóng tối.', title_zh = '不想睡觉，还害怕黑暗？', body_zh = '把房间完全调暗，用手在墙上做出小鸟、小狗的影子。把害怕变成乐趣，帮宝宝和黑暗交朋友。' WHERE id = '9d29683b-c9aa-4b14-81df-782b8e1da8f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Señales en la alimentación 🥣', body_es = '¿Come dos cucharadas, dice que está lleno y se escapa de la silla? No le obligues. Crear una relación sana con la comida es mucho más importante que dejar el plato vacío. Cuando tenga hambre, lo pedirá.', title_fr = 'Les signaux à table 🥣', body_fr = 'Deux cuillères, il dit qu''il n''a plus faim et s''échappe de sa chaise ? Ne le forcez pas. Construire une relation saine avec la nourriture compte bien plus que finir son assiette. Il en redemandera quand il aura faim.', title_hi = 'खाने में संकेत 🥣', body_hi = 'दो चम्मच खाकर ''पेट भर गया'' कहकर कुर्सी से भाग जाता है? ज़बरदस्ती मत कीजिए। खाने के साथ स्वस्थ रिश्ता बनाना थाली ज़रूर खत्म करने से कहीं ज़्यादा ज़रूरी है। भूख लगेगी तो खुद माँगेगा।', title_id = 'Sinyal saat makan 🥣', body_id = 'Baru dua sendok sudah bilang kenyang lalu kabur dari kursi? Jangan memaksanya. Membangun hubungan sehat dengan makanan jauh lebih penting daripada harus menghabiskan isi piring. Saat lapar, ia akan meminta sendiri.', title_ja = '食事のサイン 🥣', body_ja = 'ふた口食べて「おなかいっぱい」と言っていすから逃げていきますか？無理に食べさせないで。食べ物とよい関係を築くことは、お皿を必ず空にすることよりずっと大切です。おなかがすけば自分から欲しがります。', title_ko = '식사 중 보내는 신호 🥣', body_ko = '두 숟가락 먹고 배부르다며 의자에서 도망가나요? 억지로 먹이지 마세요. 음식과 건강한 관계를 만드는 게 접시를 꼭 비우는 것보다 훨씬 중요해요. 배고프면 스스로 찾을 거예요.', title_nl = 'Signalen bij het eten 🥣', body_nl = 'Zegt hij na twee hapjes al dat hij vol zit en rent hij van zijn stoel? Dwing hem niet. Een gezonde relatie met eten is veel belangrijker dan per se een leeg bord. Als hij honger heeft, vraagt hij zelf.', title_pl = 'Sygnały przy jedzeniu 🥣', body_pl = 'Po dwóch łyżkach mówi, że jest najedzony, i ucieka z krzesełka? Nie zmuszaj go. Zdrowa relacja z jedzeniem jest o wiele ważniejsza niż pusty talerz. Gdy zgłodnieje, sam poprosi.', title_pt = 'Sinais na alimentação 🥣', body_pt = 'Come duas colheres, diz que está cheio e foge da cadeira? Não o force. Criar uma relação saudável com a comida é muito mais importante do que limpar o prato. Quando tiver fome, vai pedir.', title_sv = 'Signaler vid maten 🥣', body_sv = 'Äter barnet två skedar, säger att det är mätt och springer från stolen? Tvinga inte. Att bygga en sund relation till mat är mycket viktigare än att äta upp allt på tallriken. När barnet blir hungrigt ber hen själv om mat.', title_vi = 'Tín hiệu trong bữa ăn 🥣', body_vi = 'Bé ăn hai thìa đã bảo no rồi trèo khỏi ghế? Đừng ép bé. Xây dựng mối quan hệ lành mạnh với thức ăn quan trọng hơn gấp nhiều lần việc ăn hết đĩa. Khi đói bé sẽ tự đòi ăn.', title_zh = '吃饭的信号 🥣', body_zh = '吃了两勺就说“饱了”，从椅子上跑开？别勉强。和食物建立健康的关系，比一定要吃光盘子重要得多。饿了自然会要。' WHERE id = 'a452ae82-775c-477d-b99f-ddd24ddd54fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuentos con dibujos 📖', body_es = '¿Toca los animales o niños que ve en el libro y pregunta «¿Qué hace este?»? Su percepción visual es asombrosa. Inventad juntos historias profundas y graciosas sobre los personajes.', title_fr = 'Histoires en images 📖', body_fr = 'Il touche les animaux ou les enfants des livres et demande « Qu''est-ce qu''il fait ? » Sa perception visuelle est étonnante. Inventez avec lui des histoires riches et drôles sur les personnages.', title_hi = 'तस्वीरों वाली कहानियाँ 📖', body_hi = 'किताब में जानवरों या बच्चों को देखकर उन्हें छूता है और पूछता है ''यह क्या कर रहा है?'' उसकी देखकर समझने की क्षमता कमाल की है। उसके साथ किरदारों के बारे में गहरी और मज़ेदार कहानियाँ गढ़िए।', title_id = 'Cerita bergambar 📖', body_id = 'Saat melihat hewan atau anak-anak di buku, ia menyentuhnya dan bertanya ''Dia sedang apa?'' Persepsi visualnya luar biasa. Karang cerita yang mendalam dan lucu tentang tokoh-tokohnya bersamanya.', title_ja = '絵のついたお話 📖', body_ja = '絵本の動物や子どもを見て、さわりながら「これ、なにしてるの？」と聞きますか？視覚的な理解力がすばらしいですね。キャラクターについて、一緒に深くておもしろいお話を考えましょう。', title_ko = '그림 이야기 📖', body_ko = '책 속 동물이나 아이들을 만지며 ''이건 뭐 해?'' 하고 묻나요? 시각 인지가 놀라워요. 등장인물에 대해 깊이 있고 재미있는 이야기를 함께 지어 보세요.', title_nl = 'Plaatjesverhalen 📖', body_nl = 'Raakt hij dieren of kinderen in een boek aan en vraagt hij ''Wat doet die?'' Zijn visuele waarneming is geweldig. Verzin samen uitgebreide en grappige verhalen over de figuren.', title_pl = 'Historie z obrazków 📖', body_pl = 'Dotyka zwierzątek i dzieci w książeczce i pyta: „Co to robi?”. Jego percepcja wzrokowa jest niesamowita. Wymyślajcie razem rozbudowane i zabawne historie o postaciach.', title_pt = 'Histórias com imagens 📖', body_pt = 'Toca nos animais ou nas crianças que vê nos livros e pergunta "O que está a fazer?" A perceção visual é espantosa. Inventem juntos histórias ricas e cómicas sobre as personagens.', title_sv = 'Bildberättelser 📖', body_sv = 'Rör barnet vid djuren eller barnen i boken och frågar ”vad gör den?”. Synuppfattningen är fantastisk. Hitta på djupa och roliga historier om figurerna tillsammans.', title_vi = 'Những câu chuyện qua tranh 📖', body_vi = 'Thấy con vật hay em bé trong sách, bé chạm vào và hỏi "Bạn này đang làm gì?". Khả năng nhận thức thị giác của bé thật đáng kinh ngạc. Hãy cùng bé nghĩ ra những câu chuyện sâu sắc và hài hước về các nhân vật.', title_zh = '图画故事 📖', body_zh = '看到书里的动物或小朋友，就去摸，还问“这是在干什么？”视觉感知真是惊人。和宝宝一起围绕书里的角色编些有深度又好玩的故事吧。' WHERE id = 'aa995666-2118-43a4-9171-858348f38b54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que invente él el cuento 📖', body_es = 'Esta noche deja el libro a un lado. ¡Que cuente él la historia! Pregunta a Anacan AI formas de dialogar que apoyen este asombroso desarrollo de la imaginación.', title_fr = 'C''est lui qui invente l''histoire 📖', body_fr = 'Ce soir, posez le livre. C''est lui qui raconte l''histoire ! Demandez à Anacan AI des façons de dialoguer pour soutenir ce formidable développement de l''imagination.', title_hi = 'कहानी वह गढ़े 📖', body_hi = 'आज शाम किताब एक तरफ़ रखिए। कहानी उसे सुनाने दीजिए! कल्पना के इस कमाल के विकास को बढ़ावा देने वाले बातचीत के तरीके Anacan AI से पूछिए।', title_id = 'Biar ia yang mengarang dongeng 📖', body_id = 'Malam ini letakkan bukunya. Biar ia yang bercerita! Tanyakan pada Anacan AI cara berdialog yang mendukung perkembangan imajinasi yang luar biasa ini.', title_ja = 'お話はお子さんが作る 📖', body_ja = '今夜は絵本を脇に置いて、お子さんにお話をしてもらいましょう！このすばらしい想像力の発達を支える対話のコツを、Anacan AIに聞いてみて。', title_ko = '동화는 아이가 지어요 📖', body_ko = '오늘 밤엔 책을 내려놓고 아이가 이야기를 들려주게 해 보세요! 이 놀라운 상상력 발달을 돕는 대화 요령을 Anacan AI에게 물어보세요.', title_nl = 'Laat hem het sprookje verzinnen 📖', body_nl = 'Leg het boek vanavond opzij. Laat hem het verhaal vertellen! Vraag Anacan AI naar manieren om met gesprekjes deze geweldige ontwikkeling van zijn fantasie te steunen.', title_pl = 'Niech on wymyśli bajkę 📖', body_pl = 'Dziś wieczorem odłóż książkę. Niech to on opowie historię! Zapytaj Anacan AI o sposoby prowadzenia dialogu, które wspierają ten niesamowity rozwój wyobraźni.', title_pt = 'Ele que invente a história 📖', body_pt = 'Esta noite, ponha o livro de lado. Ele que conte a história! Pergunte ao Anacan AI que diálogos apoiam este desenvolvimento fantástico da imaginação.', title_sv = 'Låt barnet hitta på sagan 📖', body_sv = 'Lägg undan boken i kväll. Låt barnet berätta historien! Fråga Anacan AI om samtalssätt som stöder den här fantastiska utvecklingen av fantasin.', title_vi = 'Để bé tự nghĩ ra câu chuyện 📖', body_vi = 'Tối nay hãy gác sách sang một bên. Để bé kể chuyện! Hãy hỏi Anacan AI những cách đối thoại giúp hỗ trợ sự phát triển trí tưởng tượng đáng kinh ngạc này.', title_zh = '让宝宝来编故事 📖', body_zh = '今晚把书放到一边。让宝宝来讲故事！问问Anacan AI，有哪些对话方式能支持这种惊人的想象力发展。' WHERE id = '9a0661d6-3164-4575-bc05-58b2efdd3f26' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Tira las hojas verdes del plato? No conviertas la mesa en un campo de batalla. Descubre en Recetas saludables magdalenas caseras con verduras escondidas y completa en silencio su ración de vitaminas.', body_fr = 'Il jette les légumes verts de son assiette ? Ne transformez pas la table en champ de bataille. Découvrez dans les Recettes saines des muffins maison aux légumes cachés et comblez ses besoins en vitamines en toute discrétion.', body_hi = 'हरी सब्ज़ियाँ थाली से फेंक देता है? खाने की मेज़ को जंग का मैदान मत बनाइए। सेहतमंद रेसिपी में छिपी सब्ज़ियों वाले घर के बने केक खोजिए और चुपचाप विटामिन का लक्ष्य पूरा कीजिए।', body_id = 'Ia melempar sayuran hijau dari piring? Jangan jadikan meja makan medan perang. Temukan muffin rumahan dengan sayuran tersembunyi di Resep Sehat dan penuhi kebutuhan vitaminnya diam-diam.', body_ja = '青菜をお皿から投げますか？食卓を戦場にしないで。「ヘルシーレシピ」で野菜をかくした手作りマフィンを見つけて、ビタミンの目標をこっそり満たしましょう。', body_ko = '채소를 접시 밖으로 던지나요? 식탁을 전쟁터로 만들지 마세요. 건강한 레시피에서 채소를 숨긴 홈메이드 머핀을 찾아 비타민 기준량을 조용히 채워 주세요.', body_nl = 'Gooit hij groenten van zijn bord? Maak van de tafel geen slagveld. Ontdek in Gezonde recepten zelfgebakken muffins met verstopte groenten en haal stilletjes de vitaminenorm.', body_pl = 'Zrzuca zieleninę z talerza? Nie zamieniaj stołu w pole bitwy. Odkryj w Zdrowych przepisach domowe babeczki z ukrytymi warzywami i po cichu uzupełnij normę witamin.', body_pt = 'Atira as verduras para fora do prato? Não transforme a mesa num campo de batalha. Descubra nas Receitas Saudáveis queques caseiros com legumes escondidos e atinja a dose de vitaminas em silêncio.', body_sv = 'Kastar barnet grönsakerna från tallriken? Gör inte matbordet till ett slagfält. Upptäck hemgjorda muffins med gömda grönsaker i Hälsosamma recept och fyll tyst på vitaminnormen.', body_vi = 'Bé ném rau xanh ra khỏi đĩa? Đừng biến bàn ăn thành chiến trường. Hãy khám phá món bánh nướng giấu rau làm tại nhà trong Công thức lành mạnh và lặng lẽ bổ sung đủ định mức vitamin.', body_zh = '把绿叶菜从盘子里扔出去？别把餐桌变成战场。在健康食谱里找找藏着蔬菜的自制蛋糕，悄悄补足维生素标准吧。' WHERE id = 'f865873b-dd5e-4259-93bf-a8d4ef0dc1b0' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia del susurro 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y susúrrale al oído, en voz muy bajita, lo que ha pasado durante el día. Susurrar es el método más natural y relajante para preparar el cerebro para dormir.', title_fr = 'La magie du chuchotement 🌙', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et chuchotez-lui à l''oreille, tout bas, ce qui s''est passé dans la journée. Le chuchotement est la façon la plus naturelle et la plus apaisante de préparer le cerveau au sommeil.', title_hi = 'फुसफुसाहट का जादू 🌙', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें बहुत धीमी आवाज़ में उसके कान में फुसफुसाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे स्वाभाविक और सुकून भरा तरीका है।', title_id = 'Keajaiban bisikan 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan bisikkan kejadian hari ini dengan suara sangat pelan di telinganya. Berbisik adalah cara paling alami dan menenangkan untuk menyiapkan otak tidur.', title_ja = 'ささやき声の魔法 🌙', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、今日あったことをとても小さな声で耳もとにささやいてあげて。ささやき声は、脳を眠りへ導くいちばん自然で心落ち着く方法です。', title_ko = '속삭임의 마법 🌙', body_ko = '방의 불을 모두 꺼 주세요. 옆에 누워 오늘 있었던 일을 아주 작은 목소리로 귀에 속삭여 주세요. 속삭임은 뇌가 잠들 준비를 하게 돕는 가장 자연스럽고 차분한 방법이에요.', title_nl = 'De magie van fluisteren 🌙', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en fluister heel zachtjes in zijn oor wat er vandaag is gebeurd. Fluisteren is de meest natuurlijke en rustgevende manier om de hersenen klaar te maken voor de slaap.', title_pl = 'Magia szeptu 🌙', body_pl = 'Zgaś wszystkie światła w pokoju. Połóż się obok i bardzo cicho wyszepcz mu do ucha, co wydarzyło się w ciągu dnia. Szept to najbardziej naturalny i kojący sposób, by przygotować mózg do snu.', title_pt = 'A magia do sussurro 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e sussurre-lhe ao ouvido, em voz muito baixa, o que aconteceu durante o dia. Sussurrar é o método mais natural e calmante para preparar o cérebro para o sono.', title_sv = 'Viskningens magi 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och viska mycket tyst i örat om det som hänt under dagen. Viskningar är det mest naturliga och lugnande sättet att förbereda hjärnan för sömn.', title_vi = 'Phép màu của lời thì thầm 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ vào tai bé về những gì đã xảy ra trong ngày. Thì thầm là cách tự nhiên và êm dịu nhất giúp não bộ chuẩn bị cho giấc ngủ.', title_zh = '悄悄话的魔力 🌙', body_zh = '把房间的灯全部关掉。躺在宝宝身边，贴着耳朵，用很轻很轻的声音讲讲今天发生的事。悄悄话是帮大脑准备入睡最自然、最能让人平静的方法。' WHERE id = '00bb1bab-f1b2-408a-929e-869ffd6367c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detective del brócoli 🥦', body_es = '¿Descubre las verduras verdes en el plato y las aparta? Pasa al arte del camuflaje. Descubre en Recetas saludables recetas ingeniosas para hacer puré las verduras y esconderlas en unas albóndigas deliciosas.', title_fr = 'Détective anti-brocoli 🥦', body_fr = 'Il repère les légumes verts dans son assiette et les repousse ? Passez à l''art du camouflage. Découvrez dans les Recettes saines des astuces pour réduire les légumes en purée et les cacher dans de délicieuses boulettes.', title_hi = 'ब्रोकली जासूस 🥦', body_hi = 'थाली में हरी सब्ज़ियाँ ढूँढकर एक तरफ़ कर देता है? छलावरण की कला अपनाइए। सेहतमंद रेसिपी सेक्शन में ऐसी चतुर रेसिपी खोजिए जिनमें सब्ज़ियों को प्यूरी बनाकर स्वादिष्ट कटलेट में छिपाया जा सके।', title_id = 'Detektif brokoli 🥦', body_id = 'Ia menemukan sayuran hijau di piring lalu menyingkirkannya? Beralihlah ke seni kamuflase. Temukan resep cerdik di bagian Resep Sehat untuk menghaluskan sayuran dan menyembunyikannya di perkedel yang lezat.', title_ja = 'ブロッコリー探偵 🥦', body_ja = 'お皿の緑の野菜を見つけて、脇へ押しやりますか？カモフラージュ作戦に切りかえましょう。「ヘルシーレシピ」から、野菜をピューレにしておいしいハンバーグにかくす賢いレシピを見つけて。', title_ko = '브로콜리 탐정 🥦', body_ko = '접시에서 초록 채소를 찾아내 옆으로 밀어내나요? 위장술을 써 보세요. 건강한 레시피에서 채소를 퓌레로 만들어 맛있는 커틀릿에 숨기는 기발한 레시피를 찾아보세요.', title_nl = 'Broccolidetective 🥦', body_nl = 'Ontdekt hij groene groenten op zijn bord en schuift hij ze opzij? Tijd voor de kunst van camouflage. Ontdek in Gezonde recepten slimme recepten om groenten te pureren en in lekkere gehaktballetjes te verstoppen.', title_pl = 'Brokułowy detektyw 🥦', body_pl = 'Wypatruje na talerzu zielone warzywa i odsuwa je na bok? Przejdź do sztuki kamuflażu. Odkryj w sekcji Zdrowe przepisy sprytne przepisy, w których zmiksowane warzywa ukryjesz w smacznych kotlecikach.', title_pt = 'Detetive dos brócolos 🥦', body_pt = 'Descobre os legumes verdes no prato e empurra-os para o lado? Passe à arte da camuflagem. Descubra nas Receitas Saudáveis receitas espertas para fazer puré de legumes e escondê-los em hambúrgueres saborosos.', title_sv = 'Broccolidetektiven 🥦', body_sv = 'Upptäcker barnet de gröna grönsakerna på tallriken och knuffar undan dem? Gå över till kamouflagekonsten. Upptäck listiga recept i avsnittet Hälsosamma recept där du mosar grönsakerna och gömmer dem i goda biffar.', title_vi = 'Thám tử bông cải xanh 🥦', body_vi = 'Bé phát hiện rau xanh trên đĩa và đẩy sang một bên? Hãy chuyển sang nghệ thuật ngụy trang. Khám phá trong mục Công thức lành mạnh những công thức khéo léo xay nhuyễn rau để giấu vào chả viên thơm ngon.', title_zh = '西兰花侦探 🥦', body_zh = '在盘子里发现绿色蔬菜就推到一边？试试伪装的艺术吧。去健康食谱板块找找巧妙的食谱，把蔬菜做成泥藏进美味的肉饼里。' WHERE id = '6948f738-9261-43c8-87d9-90b884505db8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El primer concierto del compositor 🎤', body_es = '¿Mientras coloca sus juguetes canta una canción con palabras que no vienen en ningún diccionario, pero con un ritmo especial? No cortes esta explosión intelectual: anótala en el Seguimiento del desarrollo como su primera composición.', title_fr = 'Le premier concert du compositeur 🎤', body_fr = 'En rangeant ses jouets, il chante avec des mots qui n''existent dans aucun dictionnaire, mais avec un rythme bien à lui ? N''interrompez pas cette explosion intellectuelle, notez-la comme sa première composition dans le Suivi de développement.', title_hi = 'संगीतकार का पहला कॉन्सर्ट 🎤', body_hi = 'खिलौने सजाते समय ऐसे शब्दों में, जो किसी शब्दकोश में नहीं, लेकिन एक खास लय में गाना गाता है? इस बौद्धिक धमाके को मत रोकिए, इसे उसकी पहली रचना के रूप में ग्रोथ ट्रैकर में दर्ज कीजिए।', title_id = 'Konser pertama sang komposer 🎤', body_id = 'Saat menyusun mainannya, ia bernyanyi dengan kata-kata yang tidak ada di kamus mana pun, tetapi dengan irama khusus? Jangan hentikan ledakan intelektual ini, catat di Pelacak Perkembangan sebagai karya pertamanya.', title_ja = '作曲家のはじめてのコンサート 🎤', body_ja = 'おもちゃを並べながら、どの辞書にもない言葉で、でも独特のリズムで歌っていますか？この知的な爆発を止めないで、はじめての作曲として「発達トラッカー」に記録しましょう。', title_ko = '꼬마 작곡가의 첫 공연 🎤', body_ko = '장난감을 늘어놓으며 사전에 없는 말로, 하지만 특별한 리듬으로 노래하나요? 이 지적 폭발을 막지 말고 성장 기록에 첫 작곡으로 남겨 두세요.', title_nl = 'Het eerste concert van de componist 🎤', body_nl = 'Zingt hij tijdens het opruimen van zijn speelgoed een liedje met woorden die in geen enkel woordenboek staan, maar met een eigen ritme? Onderbreek deze creatieve explosie niet en noteer het als zijn eerste compositie in de Groeitracker.', title_pl = 'Pierwszy koncert kompozytora 🎤', body_pl = 'Układając zabawki, śpiewa piosenkę ze słowami, których nie ma w żadnym słowniku, ale w wyjątkowym rytmie? Nie przerywaj tej intelektualnej eksplozji, zapisz ją w Śledzeniu rozwoju jako jego pierwszą kompozycję.', title_pt = 'O primeiro concerto do compositor 🎤', body_pt = 'Enquanto arruma os brinquedos, canta com palavras que não vêm em nenhum dicionário, mas com um ritmo especial? Não interrompa esta explosão intelectual: registe-a no Registo de Desenvolvimento como a primeira composição dele.', title_sv = 'Kompositörens första konsert 🎤', body_sv = 'Sjunger barnet sånger med ord som inte finns i någon ordbok, men med en speciell rytm, medan hen radar upp leksakerna? Avbryt inte den här intellektuella explosionen, anteckna den som barnets första komposition i Utvecklingsspåraren.', title_vi = 'Buổi hòa nhạc đầu tiên của nhà soạn nhạc 🎤', body_vi = 'Khi xếp đồ chơi, bé hát bằng những từ không có trong từ điển nào nhưng theo một nhịp điệu riêng? Đừng ngắt lời sự bùng nổ trí tuệ này, hãy ghi vào Theo dõi phát triển như "sáng tác" đầu tiên của bé.', title_zh = '小作曲家的首场音乐会 🎤', body_zh = '摆玩具时，用词典里都查不到的词、却带着特别的节奏唱着歌？别打断这次智力的爆发，把它作为宝宝的第一首作品记进发育追踪里。' WHERE id = 'c7ff87eb-a94f-4bb4-85c6-085ae172efe9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Plan de fuga a la naturaleza ⛅', body_es = 'Las cuatro paredes os han puesto agresivos a los dos. Consulta Tiempo y ropa, abrigaos enseguida y corred al parque. El oxígeno corta al momento hasta las rabietas más fuertes.', title_fr = 'Plan d''évasion dans la nature ⛅', body_fr = 'Les quatre murs vous rendent agressifs tous les deux. Consultez Météo et tenue, équipez-vous vite et filez au parc. L''oxygène coupe net même les crises de tout-petit les plus vives.', title_hi = 'प्रकृति की ओर भागने का प्लान ⛅', body_hi = 'चार दीवारों ने उसे भी और आपको भी चिड़चिड़ा बना दिया है। मौसम और कपड़े टूल देखिए, तुरंत तैयार होकर पार्क की ओर निकलिए। ऑक्सीजन छोटे बच्चे के सबसे तीखे नखरों को भी तुरंत रोक देती है।', title_id = 'Rencana kabur ke alam ⛅', body_id = 'Empat dinding rumah membuat ia dan Anda sama-sama mudah marah. Cek alat Cuaca dan Pakaian, segera bersiap, dan pergilah ke taman. Oksigen bisa seketika meredakan tantrum balita yang paling hebat.', title_ja = '自然への脱出計画 ⛅', body_ja = '家にこもって、お子さんもあなたもイライラしてきた？「天気と服装」を確認して、すぐに準備して公園へ出かけましょう。新鮮な空気は、イヤイヤ期のどんなに激しいかんしゃくもすぐにしずめてくれます。', title_ko = '자연으로 탈출 작전 ⛅', body_ko = '네 벽 안에서 아이도 엄마도 예민해졌나요? 날씨와 옷차림 도구를 확인하고 바로 챙겨 입은 뒤 공원으로 나가세요. 맑은 공기는 가장 심한 떼쓰기도 바로 멈춰 줘요.', title_nl = 'Ontsnappingsplan naar de natuur ⛅', body_nl = 'Maken de vier muren jullie allebei agressief? Check Weer en kleding, kleed jullie meteen aan en ga snel naar het park. Zuurstof stopt zelfs de heftigste peuterbuien meteen.', title_pl = 'Plan ucieczki na łono natury ⛅', body_pl = 'Cztery ściany sprawiły, że i on, i ty jesteście rozdrażnieni. Sprawdź narzędzie Pogoda i ubiór, szybko się przygotujcie i biegnijcie do parku. Tlen od razu ucina nawet najostrzejsze kryzysy maluchów.', title_pt = 'Plano de fuga para a natureza ⛅', body_pt = 'As quatro paredes deixaram-no a ele e a si agressivos. Veja o Tempo e Roupa, preparem-se logo e corram para o parque. O oxigénio corta logo até as crises mais fortes da primeira infância.', title_sv = 'Flyktplan till naturen ⛅', body_sv = 'De fyra väggarna har gjort både barnet och dig aggressiva. Kolla verktyget Väder och kläder, klä er direkt och skynda till parken. Syre stoppar även de värsta småbarnskriserna direkt.', title_vi = 'Kế hoạch trốn ra thiên nhiên ⛅', body_vi = 'Bốn bức tường khiến cả bé và mẹ trở nên cáu kỉnh. Hãy xem công cụ Thời tiết và trang phục, mặc đồ ngay và ra công viên. Oxy dập tắt ngay cả những cơn khủng hoảng dữ dội nhất của trẻ nhỏ.', title_zh = '逃向大自然计划 ⛅', body_zh = '四面墙让宝宝和你都变得烦躁。看看天气穿衣工具，马上穿戴好，奔向公园。氧气连学步儿最激烈的崩溃都能马上止住。' WHERE id = '331b6c40-0fb5-4851-9134-928632566339' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencio de oro 🤫', body_es = 'El caos de casa por fin ha terminado y se ha dormido profundamente. Abre el Medidor de sonido, mira el nivel de silencio (decibelios) de la habitación y derrítete 15 minutos en este silencio de oro sin mirar ninguna pantalla.', title_fr = 'Un silence d''or 🤫', body_fr = 'Le chaos de la maison est enfin terminé et il dort profondément. Ouvrez le Sonomètre, regardez le niveau de silence (en décibels) de la pièce et fondez 15 minutes dans ce silence d''or, sans regarder aucun écran.', title_hi = 'सुनहरी खामोशी 🤫', body_hi = 'घर की अफ़रा-तफ़री आखिरकार खत्म हुई और वह गहरी नींद में सो गया। साउंड मीटर खोलिए, कमरे की खामोशी का स्तर (डेसिबल) देखिए और 15 मिनट किसी स्क्रीन को देखे बिना इस सुनहरी खामोशी में खो जाइए।', title_id = 'Hening emas 🤫', body_id = 'Kekacauan di rumah akhirnya usai dan ia tertidur lelap. Buka Pengukur Suara, lihat tingkat keheningan (desibel) kamar, dan larutlah dalam hening emas ini selama 15 menit tanpa melihat layar apa pun.', title_ja = '金色の静けさ 🤫', body_ja = '家の大騒ぎがやっと終わり、ぐっすり眠りました。「サウンドメーター」を開いて部屋の静けさ（デシベル）を確かめ、15分間どの画面も見ずにこの金色の静けさに身をゆだねましょう。', title_ko = '황금 같은 고요 🤫', body_ko = '집 안의 소란이 드디어 끝나고 아이가 깊이 잠들었어요. 소음 측정기를 켜서 방의 데시벨을 확인하고, 15분 동안 화면은 보지 말고 이 황금 같은 고요 속에 녹아드세요.', title_nl = 'Gouden stilte 🤫', body_nl = 'De chaos in huis is eindelijk voorbij en hij slaapt diep. Open de Geluidsmeter, bekijk hoe stil de kamer is (in decibel) en smelt 15 minuten weg in deze gouden stilte zonder naar een scherm te kijken.', title_pl = 'Złota cisza 🤫', body_pl = 'Domowy chaos w końcu ucichł, a on zapadł w głęboki sen. Otwórz Miernik dźwięku, sprawdź poziom ciszy w pokoju (decybele) i przez 15 minut, bez patrzenia w żaden ekran, rozpłyń się w tej złotej ciszy.', title_pt = 'Silêncio de ouro 🤫', body_pt = 'O caos em casa acabou finalmente e ele caiu num sono profundo. Abra o Medidor de Som, veja o nível de silêncio do quarto (em decibéis) e derreta-se 15 minutos neste silêncio de ouro sem olhar para nenhum ecrã.', title_sv = 'Gyllene tystnad 🤫', body_sv = 'Kaoset hemma är äntligen över och barnet har somnat djupt. Öppna Ljudmätaren, se hur tyst rummet är (decibel) och smält in i den gyllene tystnaden i 15 minuter utan att titta på någon skärm.', title_vi = 'Sự tĩnh lặng quý như vàng 🤫', body_vi = 'Sự hỗn loạn trong nhà cuối cùng đã kết thúc và bé đã ngủ say. Hãy mở Đo âm thanh, xem độ yên tĩnh (decibel) trong phòng và tan chảy trong sự tĩnh lặng quý như vàng 15 phút mà không nhìn bất kỳ màn hình nào.', title_zh = '金色的安静 🤫', body_zh = '家里的混乱终于结束，宝宝睡熟了。打开分贝仪，看看房间有多安静（分贝），15分钟不看任何屏幕，沉浸在这份金色的安静里。' WHERE id = '56824801-bf77-4597-b1ce-5aa469fe1db9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Moda vanguardista 👗', body_es = '¿Se ha puesto el pantalón en la cabeza y se pasea muy digno por la habitación? No intervengas. Estos experimentos tan cómicos son su búsqueda de libertad e individualidad. Sí, no pega nada, pero estos momentos son deliciosos.', title_fr = 'Mode avant-gardiste 👗', body_fr = 'Il se promène fièrement dans la pièce avec son pantalon sur la tête ? N''intervenez pas. Ces essais comiques sont sa quête de liberté et de personnalité. Oui, c''est assorti n''importe comment, mais ces moments sont délicieux.', title_hi = 'अनोखा फ़ैशन 👗', body_hi = 'पैंट सिर पर पहनकर कमरे में शान से घूमता है? दखल मत दीजिए। ये मज़ेदार प्रयोग उसकी आज़ादी और अपनी पहचान की तलाश हैं। हाँ, बेमेल दिखता है, लेकिन ये पल बहुत प्यारे हैं।', title_id = 'Mode avant-garde 👗', body_id = 'Ia memakai celana di kepala dan berjalan angkuh di kamar? Jangan ikut campur. Percobaan lucu ini adalah pencariannya akan kebebasan dan jati diri. Ya, kelihatannya tidak serasi, tetapi momen ini sangat menggemaskan.', title_ja = '前衛ファッション 👗', body_ja = 'ズボンを頭にかぶって、得意げに部屋を歩き回っていますか？口を出さないで。こうしたおもしろい試みは、自由と自分らしさを探しているのです。ちぐはぐに見えても、こんな瞬間はとても楽しいものです。', title_ko = '아방가르드 패션 👗', body_ko = '바지를 머리에 쓰고 방을 당당하게 걸어 다니나요? 간섭하지 마세요. 이런 웃긴 실험은 자유와 개성을 찾아가는 과정이에요. 어울리지 않아 보여도 이 순간은 정말 사랑스러워요.', title_nl = 'Avant-gardemode 👗', body_nl = 'Loopt hij trots door de kamer met zijn broek op zijn hoofd? Grijp niet in. Deze grappige experimenten zijn zijn zoektocht naar vrijheid en eigenheid. Ja, het past niet, maar deze momenten zijn heerlijk.', title_pl = 'Awangardowa moda 👗', body_pl = 'Założył spodnie na głowę i dumnie przechadza się po pokoju? Nie wtrącaj się. Te zabawne eksperymenty to jego poszukiwanie wolności i indywidualności. Tak, wygląda to dziwnie, ale te chwile są przeurocze.', title_pt = 'Moda de vanguarda 👗', body_pt = 'Enfiou as calças na cabeça e passeia pelo quarto todo vaidoso? Não interfira. Estas experiências cómicas são a procura de liberdade e individualidade. Sim, não combina nada, mas estes momentos são deliciosos.', title_sv = 'Avantgardistiskt mode 👗', body_sv = 'Har barnet satt byxorna på huvudet och spatserar stolt runt i rummet? Lägg dig inte i. De här komiska experimenten är barnets sökande efter frihet och individualitet. Ja, det ser omaka ut, men de här stunderna är så härliga.', title_vi = 'Thời trang tiên phong 👗', body_vi = 'Bé đội quần lên đầu và tự hào đi khắp phòng? Đừng can thiệp. Những thử nghiệm buồn cười này là hành trình tìm kiếm sự tự do và cá tính của bé. Đúng là trông chẳng hợp chút nào, nhưng những khoảnh khắc này thật thú vị.', title_zh = '前卫时尚 👗', body_zh = '把裤子套在头上，在房间里神气地走来走去？别干涉。这些搞笑的尝试是宝宝在寻找自由和个性。没错，看起来不搭，但这些时刻太有意思了。' WHERE id = '7614704a-6622-4005-bcc5-442f422f2e2c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Victoria en el orinal 🚽', body_es = '¿Nota las ganas y corre él solo al orinal? ¡Es una gran victoria!', title_fr = 'Victoire sur le pot 🚽', body_fr = 'Il sent l''envie et court tout seul sur le pot ? C''est une grande victoire !', title_hi = 'पॉटी की जीत 🚽', body_hi = 'पॉटी की ज़रूरत महसूस करके खुद पॉटी की ओर भागता है? यह बड़ी जीत है!', title_id = 'Kemenangan pispot 🚽', body_id = 'Ia merasakan ingin buang air dan berlari sendiri ke pispot? Ini kemenangan besar!', title_ja = 'おまるの勝利 🚽', body_ja = '出したい感覚に気づいて、自分からおまるへ走っていきますか？これは大きな勝利です！', title_ko = '아기 변기의 승리 🚽', body_ko = '신호를 느끼고 스스로 아기 변기로 달려가나요? 정말 큰 승리예요!', title_nl = 'Overwinning op het potje 🚽', body_nl = 'Voelt hij dat hij moet en rent hij zelf naar het potje? Dat is een grote overwinning!', title_pl = 'Zwycięstwo na nocniku 🚽', body_pl = 'Czuje potrzebę i sam biegnie na nocnik? To wielkie zwycięstwo!', title_pt = 'Vitória no bacio 🚽', body_pt = 'Sente vontade de fazer as necessidades e corre sozinho para o bacio? É uma grande vitória!', title_sv = 'Pottsegern 🚽', body_sv = 'Känner barnet att hen behöver gå och springer själv till pottan? Det är en stor seger!', title_vi = 'Chiến thắng với bô 🚽', body_vi = 'Bé tự cảm nhận nhu cầu đi vệ sinh và chạy đến bô? Đây là một chiến thắng lớn!', title_zh = '便盆的胜利 🚽', body_zh = '感觉到要排便，就自己跑去坐便盆？这是一次大胜利！' WHERE id = '8805c85d-beba-4d76-905f-2991bc6002f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amnesia en el súper 🛒', body_es = '¿Fuiste al súper fiándote de tu memoria y volviste sin lo más importante? Acostúmbrate a apuntar todo lo que falta en la Lista de la compra de la app y deja que tu memoria digital te salve.', title_fr = 'Trou de mémoire au supermarché 🛒', body_fr = 'Vous avez fait confiance à votre mémoire au supermarché et êtes rentrée sans l''article le plus important ? Prenez l''habitude de tout noter dans la Liste de courses de l''application, laissez votre mémoire numérique vous sauver.', title_hi = 'बाज़ार में याददाश्त गुम 🛒', body_hi = 'याददाश्त के भरोसे बाज़ार गईं और सबसे ज़रूरी चीज़ भूलकर लौट आईं? सारी ज़रूरतें ऐप की शॉपिंग लिस्ट में लिखने की आदत डालिए, आपकी डिजिटल याददाश्त आपको बचा लेगी।', title_id = 'Hilang ingatan di supermarket 🛒', body_id = 'Mengandalkan ingatan saat belanja dan pulang tanpa barang yang paling penting? Biasakan menulis semua kebutuhan di Daftar Belanja di aplikasi, biar memori digital Anda yang menyelamatkan.', title_ja = 'スーパーで記憶喪失 🛒', body_ja = '記憶にたよって買い物に行き、いちばん大事なものを買い忘れて帰ってきた？必要なものはすべてアプリの「買い物リスト」に書く習慣をつけて、デジタルの記憶に助けてもらいましょう。', title_ko = '마트에서 깜빡깜빡 🛒', body_ko = '기억만 믿고 마트에 갔다가 가장 중요한 걸 잊고 돌아왔나요? 필요한 건 모두 앱의 쇼핑 목록에 적는 습관을 들이고, 디지털 기억에 도움을 받으세요.', title_nl = 'Geheugenverlies in de supermarkt 🛒', body_nl = 'Vertrouwde je op je geheugen en kwam je zonder het belangrijkste uit de supermarkt terug? Maak er een gewoonte van om alles op het Boodschappenlijstje in de app te zetten en laat je digitale geheugen je redden.', title_pl = 'Utrata pamięci w sklepie 🛒', body_pl = 'Zaufałaś pamięci, poszłaś do sklepu i wróciłaś bez najważniejszej rzeczy? Wyrób sobie nawyk wpisywania wszystkich potrzeb na Listę zakupów w aplikacji i niech cyfrowa pamięć cię ratuje.', title_pt = 'Memória perdida no supermercado 🛒', body_pt = 'Confiou na memória, foi ao supermercado e voltou sem o mais importante? Crie o hábito de apontar tudo na Lista de Compras da app e deixe a sua memória digital salvá-la.', title_sv = 'Minnesluckor i affären 🛒', body_sv = 'Litade du på ditt minne när du handlade och kom hem utan det viktigaste? Gör det till en vana att skriva in allt i Inköpslistan i appen och låt ditt digitala minne rädda dig.', title_vi = 'Mất trí nhớ ở siêu thị 🛒', body_vi = 'Mẹ tin vào trí nhớ để đi siêu thị rồi về nhà thiếu đúng món quan trọng nhất? Hãy tập ghi mọi thứ cần mua vào Danh sách mua sắm trong ứng dụng, để "trí nhớ số" cứu nguy cho mẹ.', title_zh = '在超市失忆 🛒', body_zh = '相信自己的记性去超市，结果最重要的东西忘了买就回来了？养成习惯，把所有需要的东西都写进应用里的购物清单，让你的数字记忆来救场。' WHERE id = '45e0f5b4-5219-47b6-9a9e-bcadb9ed774d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Invitados invisibles 👻', body_es = '¿Mira a un hueco vacío del sofá, habla y hasta le sirve té a su amigo invisible? ¡La etapa de los amigos imaginarios está en pleno auge! Ya es el guionista de su propio mundo. Disfruta del espectáculo con una sonrisa.', title_fr = 'Invités invisibles 👻', body_fr = 'Il fixe une place vide sur le canapé en parlant, et sert même du thé à son ami invisible ? La période des amis imaginaires bat son plein ! Il est désormais le scénariste de son propre monde. Regardez ce spectacle en souriant.', title_hi = 'अदृश्य मेहमान 👻', body_hi = 'सोफ़े पर खाली जगह की ओर देखकर बातें करता है, यहाँ तक कि अदृश्य दोस्त को चाय भी परोसता है? काल्पनिक दोस्तों का दौर चरम पर है! वह अब अपनी दुनिया का पटकथा लेखक है। यह नाटक मुस्कुराते हुए देखिए।', title_id = 'Tamu tak kasatmata 👻', body_id = 'Ia menatap tempat kosong di sofa sambil berbicara, bahkan menuangkan teh untuk teman tak kasatmatanya? Masa teman khayalan sedang memuncak! Ia kini penulis skenario dunianya sendiri. Saksikan pertunjukan ini sambil tersenyum.', title_ja = '見えないお客さま 👻', body_ja = 'ソファのだれもいない場所を見ておしゃべりしたり、見えないお友だちにお茶をついだりしていますか？空想のお友だち期が最高潮です！もう自分の世界の脚本家。このお芝居を笑顔で見守りましょう。', title_ko = '보이지 않는 손님 👻', body_ko = '소파의 빈자리를 보며 이야기하고, 보이지 않는 친구에게 차를 따라 주나요? 상상 속 친구 시기가 절정이에요! 아이는 이제 자기 세계의 작가예요. 웃으며 이 공연을 지켜보세요.', title_nl = 'Onzichtbare gasten 👻', body_nl = 'Kijkt hij naar een lege plek op de bank, praat hij honderduit en schenkt hij zelfs thee in voor een onzichtbaar vriendje? De fase van denkbeeldige vriendjes is op zijn hoogtepunt! Hij schrijft nu het scenario van zijn eigen wereld. Kijk lachend naar deze voorstelling.', title_pl = 'Niewidzialni goście 👻', body_pl = 'Patrzy w puste miejsce na kanapie i coś opowiada, a nawet nalewa herbaty niewidzialnemu przyjacielowi? Okres wyimaginowanych przyjaciół w pełni! Jest już scenarzystą własnego świata. Oglądaj to przedstawienie z uśmiechem.', title_pt = 'Convidados invisíveis 👻', body_pt = 'Olha para um lugar vazio no sofá, conversa e até serve chá a um amigo invisível? A fase dos amigos imaginários está no auge! Já é o argumentista do seu próprio mundo. Assista a este espetáculo a sorrir.', title_sv = 'Osynliga gäster 👻', body_sv = 'Tittar barnet på en tom plats i soffan och pratar, och häller till och med upp te åt sin osynliga vän? Låtsaskompisperioden är på topp! Barnet är redan manusförfattare i sin egen värld. Titta på föreställningen med ett leende.', title_vi = 'Những vị khách vô hình 👻', body_vi = 'Bé nhìn vào chỗ trống trên sofa và nói chuyện, thậm chí rót trà cho người bạn vô hình? Giai đoạn bạn tưởng tượng đang lên đến đỉnh điểm! Bé đã là "biên kịch" của thế giới riêng mình. Hãy mỉm cười xem màn kịch này.', title_zh = '看不见的客人 👻', body_zh = '在沙发上对着空地方说话，甚至给看不见的朋友倒茶？想象中的朋友阶段到了高峰！宝宝已经是自己世界的编剧了。笑着欣赏这场演出吧。' WHERE id = '8cab638c-2941-4e59-9d14-fa8e3dd46600' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del agua para borrar el día 🛀', body_es = 'Después de correr todo el día, tenéis los nervios de punta los dos. Un baño templado no es solo higiene: sirve para aprovechar el poder casi mágico del agua, que alivia la tensión y se lleva la energía negativa del día.', title_fr = 'Le pouvoir apaisant de l''eau 🛀', body_fr = 'Après une journée à courir, vos nerfs sont à vif, à lui comme à vous. Le bain tiède n''est pas qu''une question d''hygiène : il sert à profiter du pouvoir presque magique de l''eau, qui dénoue les tensions et emporte l''énergie négative de la journée.', title_hi = 'पानी की तनाव धो देने वाली ताकत 🛀', body_hi = 'दिनभर भागदौड़ से उसकी भी और आपकी भी नसें तन गई हैं। गुनगुना स्नान सिर्फ़ सफ़ाई के लिए नहीं, बल्कि पानी की उस जादुई ताकत के लिए है जो तनाव दूर करती है और दिन की नकारात्मक ऊर्जा धो देती है।', title_id = 'Kekuatan air yang membasuh 🛀', body_id = 'Seharian berlarian, saraf Anda dan dia sama-sama tegang. Mandi air hangat bukan sekadar kebersihan, tetapi cara memanfaatkan kekuatan ajaib air untuk meluruhkan ketegangan dan menghanyutkan energi negatif hari ini.', title_ja = 'お水の洗い流す力 🛀', body_ja = '一日じゅう走り回って、ふたりとも神経がピリピリ。ぬるめのお風呂はただの衛生習慣ではなく、緊張をほどき、一日の嫌な気分を洗い流すお水の不思議な力を借りるためのものです。', title_ko = '물의 치유력 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 신경이 곤두섰죠. 따뜻한 목욕은 단순한 위생이 아니라 긴장을 풀고 하루의 나쁜 기운을 씻어 내는 물의 신비로운 힘을 빌리는 시간이에요.', title_nl = 'De kracht van water spoelt alles weg 🛀', body_nl = 'Na een hele dag rennen zijn jullie allebei gespannen. Een lauw bad is niet alleen voor de hygiëne, maar ook om de bijna magische kracht van water te gebruiken die spanning wegneemt en de negatieve energie van de dag wegspoelt.', title_pl = 'Oczyszczająca moc wody 🛀', body_pl = 'Po całym dniu biegania puszczają nerwy i jemu, i tobie. Ciepła kąpiel to nie tylko higiena, ale sposób, by wykorzystać mistyczną moc wody, która zabiera napięcie i zmywa negatywną energię dnia.', title_pt = 'O poder da água para lavar o dia 🛀', body_pt = 'Depois de correrem o dia todo, os nervos dele e os seus estão em franja. Um banho morno não é só higiene: serve para aproveitar o poder quase místico da água para levar a tensão e a energia negativa do dia.', title_sv = 'Vattnets kraft att skölja bort dagen 🛀', body_sv = 'Efter en hel dag i farten är både barnets och dina nerver spända. Ett ljummet bad är inte bara hygien, det är ett sätt att använda vattnets magiska kraft som släpper spänningar och sköljer bort dagens negativa energi.', title_vi = 'Sức mạnh gột rửa của nước 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều căng thẳng. Bồn nước ấm không chỉ để vệ sinh, mà còn để tận dụng sức mạnh kỳ diệu của nước giúp xua tan căng thẳng và cuốn trôi năng lượng tiêu cực của cả ngày.', title_zh = '水洗去烦恼的力量 🛀', body_zh = '跑了一整天，宝宝和你都神经紧绷。温水澡不只是为了清洁，更是借助水那带走紧张、冲走一天负面情绪的神奇力量。' WHERE id = 'd368c6ed-7184-4b38-b97e-6f9c7890966b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de cocina de papá 👨‍🍳', body_es = 'La maternidad no es una maratón en solitario. Que el fin de semana papá prepare la comida y le dé de comer, y tú túmbate en el sofá y disfruta de una pausa muy merecida.', title_fr = 'Papa de service en cuisine 👨‍🍳', body_fr = 'La maternité n''est pas un marathon en solo. Ce week-end, que papa prépare le déjeuner et le fasse manger, pendant que vous vous allongez sur le canapé pour savourer une pause bien méritée.', title_hi = 'पापा की रसोई वाली बारी 👨‍🍳', body_hi = 'माँ होना अकेले दौड़ने वाली मैराथन नहीं है। वीकेंड का लंच पापा बनाएँ और खिलाएँ, और आप सोफ़े पर लेटकर एक कीमती ब्रेक का मज़ा लीजिए।', title_id = 'Giliran Ayah di dapur 👨‍🍳', body_id = 'Menjadi ibu bukan maraton seorang diri. Akhir pekan ini biar Ayah yang menyiapkan makan siang dan menyuapi, sementara Anda berbaring di sofa dan menikmati jeda yang berharga.', title_ja = 'パパのキッチン当番 👨‍🍳', body_ja = '子育てはひとりで走るマラソンではありません。週末のランチはパパに作って食べさせてもらい、あなたはソファに横になって貴重な休憩を味わいましょう。', title_ko = '아빠의 주방 당번 👨‍🍳', body_ko = '엄마 노릇은 혼자 뛰는 마라톤이 아니에요. 주말 점심은 아빠가 준비하고 먹이게 하고, 엄마는 소파에 누워 소중한 휴식을 즐기세요.', title_nl = 'Papa''s keukendienst 👨‍🍳', body_nl = 'Moederschap is geen marathon die je alleen loopt. Laat papa in het weekend de lunch maken en geven, en geniet jij op de bank van een welverdiende pauze.', title_pl = 'Dyżur taty w kuchni 👨‍🍳', body_pl = 'Macierzyństwo to nie samotny maraton. Niech w weekend tata przygotuje obiad i nakarmi malucha, a ty połóż się na kanapie i ciesz się cenną przerwą.', title_pt = 'O turno do pai na cozinha 👨‍🍳', body_pt = 'A maternidade não é uma maratona a solo. Ao fim de semana, o pai faz o almoço e dá de comer, e a mãe deita-se no sofá e saboreia uma pausa preciosa.', title_sv = 'Pappas tur i köket 👨‍🍳', body_sv = 'Moderskap är inget maraton man springer ensam. Låt pappa laga och servera helglunchen medan du ligger på soffan och njuter av en värdefull paus.', title_vi = 'Ca trực bếp của bố 👨‍🍳', body_vi = 'Làm mẹ không phải là cuộc chạy marathon một mình. Hãy để bố nấu bữa trưa cuối tuần và cho bé ăn, còn mẹ nằm dài trên sofa tận hưởng khoảng nghỉ quý giá.', title_zh = '爸爸的厨房值班 👨‍🍳', body_zh = '当妈妈不是一个人的马拉松。周末让爸爸做午饭、喂饭，你在沙发上躺着，享受一段宝贵的休息吧。' WHERE id = '37a646c6-efce-4c74-8923-488fc7f72713' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Solo me pasa a mí? 💬', body_es = '¿Estás agotada y sientes que nadie te entiende? Escribe ya en la Comunidad Anacan. Allí te darán fuerza los mensajes de «yo también estoy como tú» de miles de madres que sufren la misma falta de sueño.', title_fr = 'Je suis la seule à vivre ça ? 💬', body_fr = 'Très fatiguée, vous avez l''impression que personne ne vous comprend ? Écrivez tout de suite dans la Communauté Anacan. Là-bas, les messages « moi aussi » de milliers de mamans qui vivent les mêmes nuits blanches vous donneront de la force.', title_hi = 'क्या सिर्फ़ मैं ही ऐसी हूँ? 💬', body_hi = 'बहुत थक गई हैं और लगता है कि कोई आपको नहीं समझता? तुरंत Anacan कम्युनिटी में लिखिए। वहाँ आपके जैसी नींद की कमी झेल रही हज़ारों माँओं के ''मैं भी आपके जैसी हूँ'' वाले संदेश आपको ताकत देंगे।', title_id = 'Hanya aku yang begini? 💬', body_id = 'Sangat lelah dan merasa tidak ada yang memahami Anda? Segera tulis di Komunitas Anacan. Di sana pesan ''aku juga sepertimu'' dari ribuan ibu yang sama-sama kurang tidur akan memberi Anda kekuatan.', title_ja = 'こんな気持ち、わたしだけ？💬', body_ja = 'とても疲れて、だれにもわかってもらえないと感じていますか？すぐにAnacanコミュニティに書きこんでみて。同じ寝不足に悩む何千人ものママからの「わたしも同じだよ」というメッセージが、力をくれます。', title_ko = '나만 이런 걸까요? 💬', body_ko = '너무 지쳤는데 아무도 이해해 주지 않는 것 같나요? 바로 Anacan 커뮤니티에 글을 남겨 보세요. 같은 잠 못 드는 밤을 보내는 수많은 엄마들의 ''나도 그래요''라는 메시지가 힘이 될 거예요.', title_nl = 'Ben ik de enige? 💬', body_nl = 'Ben je erg moe en denk je dat niemand je begrijpt? Schrijf meteen in de Anacan Community. Daar geven de berichten ''ik ook, net als jij'' van duizenden moeders met hetzelfde slaapgebrek je kracht.', title_pl = 'Tylko ja tak mam? 💬', body_pl = 'Jesteś bardzo zmęczona i czujesz, że nikt cię nie rozumie? Od razu napisz w Społeczności Anacan. Wiadomości „Ja też tak mam” od tysięcy mam zmagających się z tym samym niewyspaniem dodadzą ci sił.', title_pt = 'Só eu é que sou assim? 💬', body_pt = 'Está muito cansada e sente que ninguém a compreende? Escreva já na Comunidade Anacan. Lá, as mensagens "eu também sou como tu" de milhares de mães com as mesmas noites sem dormir vão dar-lhe força.', title_sv = 'Är det bara jag? 💬', body_sv = 'Är du väldigt trött och känner att ingen förstår dig? Skriv direkt i Anacan Community. Där får du kraft av ”jag är som du”-meddelanden från tusentals mammor som lider av samma sömnbrist.', title_vi = 'Chỉ mình mình như vậy sao? 💬', body_vi = 'Mẹ quá mệt mỏi và nghĩ rằng không ai hiểu mình? Hãy viết ngay vào Cộng đồng Anacan. Ở đó, những lời nhắn "Mình cũng như bạn" của hàng nghìn người mẹ cũng đang mất ngủ sẽ tiếp thêm sức mạnh cho mẹ.', title_zh = '只有我这样吗？💬', body_zh = '太累了，觉得没人理解你？马上在Anacan社区里写下来。那里成千上万位同样睡不好的妈妈发来的“我也和你一样”，会给你力量。' WHERE id = '38899b21-6787-484d-901a-76cdc0b3deb6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que escriba él el guion 🪄', body_es = 'Los libros clásicos os aburren a los dos. Esta vez, en Cuentos inteligentes, deja que tu peque elija el final de la historia. Activa su imaginación antes de dormir preguntándole: «¿Quién crees que ayudó al héroe?».', title_fr = 'C''est lui qui écrit le scénario 🪄', body_fr = 'Vous en avez assez tous les deux des livres classiques. Cette fois, dans les Contes intelligents, laissez votre enfant choisir la fin de l''histoire. Avant de dormir, stimulez son imagination : « À ton avis, qui a aidé le héros ? »', title_hi = 'पटकथा वह लिखे 🪄', body_hi = 'पुरानी किताबों से आप दोनों ऊब गए हैं? इस बार स्मार्ट कहानियों में कहानी का अंत अपने बच्चे से चुनवाइए। ''तुम्हें क्या लगता है, उस हीरो की मदद किसने की?'' पूछकर सोने से पहले उसकी कल्पना जगाइए।', title_id = 'Biar ia yang menulis skenarionya 🪄', body_id = 'Kalian berdua bosan dengan buku klasik. Kali ini di Dongeng Pintar, biarkan anak memilih akhir ceritanya. Pancing imajinasinya sebelum tidur dengan bertanya, ''Menurutmu siapa yang menolong pahlawan itu?''', title_ja = 'シナリオはお子さんが書く 🪄', body_ja = 'いつもの絵本にふたりともあきてしまった？「スマートおはなし」で、今回はお話の結末をお子さんに選んでもらいましょう。「主人公を助けたのはだれだと思う？」と問いかけて、寝る前に想像力を働かせて。', title_ko = '이야기는 아이가 써요 🪄', body_ko = '늘 읽던 책이 둘 다 지겨워졌나요? 이번에는 스마트 동화에서 이야기의 결말을 아이가 고르게 해 보세요. ''누가 그 주인공을 도와줬을까?'' 하고 물으며 잠들기 전 상상력을 깨워 주세요.', title_nl = 'Laat hem het scenario schrijven 🪄', body_nl = 'Zijn jullie allebei de klassieke boekjes beu? Laat je kindje deze keer in Slimme sprookjes zelf het einde kiezen. Prikkel voor het slapengaan zijn fantasie met: ''Wie denk jij dat de held heeft geholpen?''', title_pl = 'Niech on napisze scenariusz 🪄', body_pl = 'Oboje macie dość klasycznych książek. Tym razem w Mądrych bajkach pozwól dziecku wybrać zakończenie historii. Pobudź przed snem jego wyobraźnię pytaniem: „Jak myślisz, kto pomógł bohaterowi?”.', title_pt = 'Ele que escreva o argumento 🪄', body_pt = 'Estão os dois fartos dos livros clássicos. Desta vez, nas Histórias Inteligentes, deixe o seu filho escolher o final. Antes de dormir, puxe pela imaginação dele: "Quem achas que ajudou o herói?"', title_sv = 'Låt barnet skriva manuset 🪄', body_sv = 'Ni är båda trötta på klassiska böcker. Låt barnet välja hur berättelsen slutar i Smarta sagor den här gången. Sätt fart på fantasin före läggdags med ”Vem tror du hjälpte hjälten?”.', title_vi = 'Để bé viết kịch bản 🪄', body_vi = 'Cả hai mẹ con đều chán những cuốn sách kinh điển? Lần này trong Truyện cổ tích thông minh, hãy để bé chọn cái kết. Hỏi bé "Con nghĩ ai đã giúp nhân vật ấy?" để khơi dậy trí tưởng tượng trước giờ ngủ.', title_zh = '让宝宝来写剧本 🪄', body_zh = '你们俩都读腻了经典故事书？这次在智能故事里让孩子来选结局吧。问一句“你觉得是谁帮了那位主角？”，在睡前激发宝宝的想象力。' WHERE id = 'c34613c3-022a-46ef-a284-68eea41b09f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La despensa de mamá 🥗', body_es = 'Has pensado 3 menús distintos para que coma, ¿y tú has picado algo de pie? Elige en Recetas saludables una ensalada cargada de vitaminas que se prepara en 10 minutos y siéntete valiosa.', title_fr = 'Les réserves de maman 🥗', body_fr = 'Vous avez imaginé 3 menus différents pour qu''il mange, et vous, vous avez grignoté debout ? Choisissez dans les Recettes saines une salade pleine de vitamines prête en 10 minutes et sentez que vous comptez, vous aussi.', title_hi = 'माँ का पोषण भंडार 🥗', body_hi = 'उसका पेट भरने के लिए 3 अलग-अलग मेन्यू सोचे, और आपने खुद खड़े-खड़े कुछ खा लिया? सेहतमंद रेसिपी से 10 मिनट में बनने वाला, विटामिन से भरपूर सलाद चुनिए और खुद को कीमती महसूस कीजिए।', title_id = 'Cadangan gizi Ibu 🥗', body_id = 'Anda memikirkan 3 menu berbeda agar ia kenyang, tetapi Anda sendiri makan sambil berdiri? Pilih salad kaya vitamin yang siap dalam 10 menit dari Resep Sehat dan rasakan bahwa Anda berharga.', title_ja = 'ママの栄養補給 🥗', body_ja = 'お子さんのために3つもメニューを考えたのに、自分は立ったままつまんだだけ？「ヘルシーレシピ」から10分でできるビタミンたっぷりのサラダを選んで、自分を大切にしましょう。', title_ko = '엄마의 영양 창고 🥗', body_ko = '아이를 먹이려고 메뉴를 세 가지나 고민했는데 정작 엄마는 서서 대충 때웠나요? 건강한 레시피에서 10분이면 만드는 비타민 가득한 샐러드를 골라 나를 소중히 대해 주세요.', title_nl = 'Voedingsvoorraad voor mama 🥗', body_nl = 'Je bedacht 3 verschillende menu''s om hem te laten eten, maar at zelf staand iets snels? Kies uit Gezonde recepten een vitaminerijke salade die in 10 minuten klaar is en voel je gewaardeerd.', title_pl = 'Zapas energii dla mamy 🥗', body_pl = 'Wymyśliłaś 3 różne menu, żeby go nakarmić, a sama zjadłaś coś na stojąco? Wybierz ze Zdrowych przepisów sałatkę pełną witamin gotową w 10 minut i poczuj, że jesteś ważna.', title_pt = 'A reserva alimentar da mãe 🥗', body_pt = 'Pensou em 3 ementas diferentes para ele e a mãe comeu qualquer coisa de pé? Escolha nas Receitas Saudáveis uma salada cheia de vitaminas, pronta em 10 minutos, e sinta o seu valor.', title_sv = 'Mammas matförråd 🥗', body_sv = 'Du hittade på 3 olika menyer för att barnet skulle bli mätt, men själv småät du stående? Välj en vitaminrik sallad som är klar på 10 minuter från Hälsosamma recept och känn dig värdefull.', title_vi = 'Kho dinh dưỡng của mẹ 🥗', body_vi = 'Mẹ nghĩ ra 3 thực đơn khác nhau để bé ăn no, còn mình thì ăn vội đứng một chỗ? Hãy chọn một món salad giàu vitamin làm trong 10 phút từ Công thức lành mạnh và cảm nhận mình thật đáng được trân trọng.', title_zh = '妈妈的营养储备 🥗', body_zh = '为了让宝宝吃饱，想了3种不同的菜单，自己却站着随便吃两口？从健康食谱里选一份10分钟就能做好、富含维生素的沙拉，好好珍惜自己。' WHERE id = '29d7734b-e03c-4396-8939-93b0dfe516dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El teatro de muecas de papá 🤡', body_es = 'Cuando tus trucos ya no funcionan, los sonidos raros de papá salvan la situación al instante. En las crisis de la noche, pásale la pelota y disfruta desde fuera de las carcajadas.', title_fr = 'Le théâtre de grimaces de papa 🤡', body_fr = 'Quand vos astuces ne marchent plus, les bruits bizarres de papa sauvent la situation en un instant. Pendant les crises du soir, passez-lui la balle et profitez de loin des éclats de rire.', title_hi = 'पापा का चेहरों वाला थिएटर 🤡', body_hi = 'जब आपकी तरकीबें काम नहीं करतीं, तो पापा की अजीब आवाज़ें तुरंत हालात संभाल लेती हैं। शाम के नखरों में बॉल उनके पाले में डालिए और दूर से खिलखिलाहटें देखिए।', title_id = 'Teater mimik Ayah 🤡', body_id = 'Saat cara Anda tidak lagi berhasil, suara aneh Ayah bisa seketika menyelamatkan keadaan. Saat krisis malam hari, oper bolanya kepada Ayah dan saksikan tawa riang dari jauh.', title_ja = 'パパの表情劇場 🤡', body_ja = 'あなたの手がもう効かないとき、パパのおもしろい声がすぐに状況を救ってくれます。夕方のかんしゃくでは、パパにバトンを渡して、楽しい笑い声をそばで眺めましょう。', title_ko = '아빠의 표정 극장 🤡', body_ko = '엄마의 방법이 더는 통하지 않을 때 아빠의 웃긴 소리가 순식간에 상황을 구해 줘요. 저녁 떼쓰기 때는 아빠에게 공을 넘기고 옆에서 즐거운 웃음소리를 즐기세요.', title_nl = 'Papa''s mimiektheater 🤡', body_nl = 'Als jouw trucjes niet meer werken, redden papa''s gekke geluiden de situatie meteen. Speel de bal bij avondbuien naar hem door en kijk vanaf de zijlijn naar het vrolijke gelach.', title_pl = 'Teatr min taty 🤡', body_pl = 'Gdy twoje sposoby już nie działają, dziwne odgłosy taty od razu ratują sytuację. Podczas wieczornych kryzysów podaj mu piłeczkę i z boku słuchaj radosnych chichotów.', title_pt = 'O teatro de caretas do pai 🤡', body_pt = 'Quando os seus truques já não funcionam, os sons estranhos do pai salvam logo a situação. Nas crises da noite, passe-lhe a bola e assista de longe às gargalhadas alegres.', title_sv = 'Pappas minteater 🤡', body_sv = 'När dina knep inte längre fungerar räddar pappas konstiga ljud situationen direkt. Vid kvällskriser, passa bollen till honom och se de glada skratten från sidan.', title_vi = 'Sân khấu biểu cảm của bố 🤡', body_vi = 'Khi những chiêu của mẹ không còn hiệu quả, những âm thanh lạ của bố sẽ cứu nguy ngay lập tức. Khi bé quấy buổi tối, hãy "chuyền bóng" cho bố và ngồi xem những tràng cười vui vẻ.', title_zh = '爸爸的表情剧场 🤡', body_zh = '你的办法都不管用时，爸爸的怪声音能马上挽救局面。晚上宝宝崩溃时，把球传给他，在一旁欣赏欢快的笑声吧。' WHERE id = 'bdf82e6a-e184-465d-ab37-a709d395d1d4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño ayudante de limpieza 🧽', body_es = '¿Mientras quitas el polvo te tira del paño? Quiere sentirse mayor y parte del equipo. Dale un trapo húmedo. Ensuciará más de lo que limpie, pero su ego quedará encantado.', title_fr = 'Petit agent d''entretien 🧽', body_fr = 'Quand vous faites la poussière, il vous arrache le chiffon des mains ? Il veut se sentir grand et membre de l''équipe. Donnez-lui un chiffon humide. Il salira plus qu''il ne nettoiera, mais il sera tellement fier.', title_hi = 'नन्हा सफ़ाईकर्मी 🧽', body_hi = 'आप धूल झाड़ती हैं तो आपके हाथ से कपड़ा खींचता है? वह खुद को बड़ा और टीम का हिस्सा महसूस करना चाहता है। उसे एक गीला कपड़ा दीजिए। सफ़ाई से ज़्यादा गंदगी करेगा, लेकिन उसका मन खुश हो जाएगा।', title_id = 'Asisten rumah cilik 🧽', body_id = 'Saat Anda membersihkan debu, ia menarik lap dari tangan Anda? Ia ingin merasa sudah besar dan menjadi anggota tim. Beri ia lap basah. Ia akan lebih banyak mengotori daripada membersihkan, tetapi hatinya akan senang.', title_ja = '小さなお掃除係 🧽', body_ja = 'ほこりを払っていると、手から布を引っぱりますか？大きくなってチームの一員だと感じたいのです。ぬらした布を渡しましょう。掃除より汚すほうが多くても、自尊心が満たされます。', title_ko = '꼬마 청소 도우미 🧽', body_ko = '엄마가 먼지를 털 때 손에서 걸레를 잡아당기나요? 다 커서 팀의 일원이 된 기분을 느끼고 싶은 거예요. 젖은 걸레를 쥐여 주세요. 청소보다 더 어지르겠지만 자존감은 쑥 자랄 거예요.', title_nl = 'Kleine schoonmaker 🧽', body_nl = 'Trekt hij de stofdoek uit je hand als je afstoft? Hij wil zich groot voelen en bij het team horen. Geef hem een vochtig doekje. Hij maakt meer rommel dan schoon, maar zijn ego wordt gestreeld.', title_pl = 'Mały pomocnik 🧽', body_pl = 'Gdy ścierasz kurze, wyrywa ci ściereczkę z ręki? Chce poczuć się duży i częścią drużyny. Daj mu wilgotną ściereczkę. Bardziej nabrudzi, niż posprząta, ale jego ego zostanie połechtane.', title_pt = 'Pequena ajudante 🧽', body_pt = 'Enquanto tira o pó, puxa-lhe o pano da mão? Quer sentir-se crescido e parte da equipa. Dê-lhe um paninho húmido. Vai sujar mais do que limpar, mas o ego dele fica feliz.', title_sv = 'Liten städare 🧽', body_sv = 'Drar barnet trasan ur din hand när du dammar? Hen vill känna sig stor och som en del av laget. Ge hen en fuktig trasa. Det blir mer kladd än städning, men självkänslan får en boost.', title_vi = 'Người giúp việc tí hon 🧽', body_vi = 'Khi mẹ phủi bụi, bé giật lấy khăn trong tay mẹ? Bé muốn thấy mình là người lớn và là thành viên của đội. Hãy đưa bé một chiếc khăn ẩm. Bé sẽ làm bẩn nhiều hơn là lau sạch, nhưng cái tôi của bé sẽ được vỗ về.', title_zh = '小小清洁员 🧽', body_zh = '你擦灰时，宝宝从你手里抢抹布？宝宝想感觉自己长大了，是团队的一员。给宝宝一块湿抹布。弄湿的地方会比擦干净的多，但宝宝的自尊心得到了满足。' WHERE id = 'f6962d3f-b694-40e4-9faf-0cd32b36de3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El contacto visual es clave 🥂', body_es = '¡Se ha dormido antes de lo esperado! No gastes este momento tan raro en limpiar la casa. Sentaos frente a frente con tu pareja, apagad la tele y, mirándoos a los ojos, preguntaos qué tal ha ido el día.', title_fr = 'Le contact visuel avant tout 🥂', body_fr = 'L''enfant s''est endormi plus tôt que prévu ! Ne gaspillez pas ce moment rare en ménage. Asseyez-vous face à votre partenaire, éteignez la télé et, en vous regardant dans les yeux, demandez-vous comment s''est passée votre journée.', title_hi = 'आँखों में आँखें डालना ज़रूरी है 🥂', body_hi = 'बच्चा अचानक जल्दी सो गया! इस दुर्लभ पल को घर की सफ़ाई में मत गँवाइए। अपने पार्टनर के आमने-सामने बैठिए, टीवी बंद कीजिए और बस एक-दूसरे की आँखों में देखकर पूछिए कि दिन कैसा रहा।', title_id = 'Kontak mata itu wajib 🥂', body_id = 'Anak tertidur lebih cepat dari biasanya! Jangan habiskan momen langka ini untuk bersih-bersih. Duduklah berhadapan dengan pasangan, matikan TV, dan sambil saling menatap, tanyakan bagaimana hari masing-masing.', title_ja = '目を合わせることが大切 🥂', body_ja = 'お子さんが思いがけず早く眠りました！このめったにない時間を家の掃除に使わないで。パートナーと向かい合って座り、テレビを消して、お互いの目を見ながら一日がどうだったか聞きましょう。', title_ko = '눈 맞춤은 꼭 필요해요 🥂', body_ko = '아이가 예상보다 일찍 잠들었어요! 이 드문 순간을 집 청소에 쓰지 마세요. 배우자와 마주 앉아 TV를 끄고 서로의 눈을 보며 하루가 어땠는지 물어보세요.', title_nl = 'Oogcontact is een must 🥂', body_nl = 'Hij viel onverwacht vroeg in slaap! Besteed dit zeldzame moment niet aan schoonmaken. Ga tegenover je partner zitten, zet de tv uit, kijk elkaar in de ogen en vraag gewoon hoe jullie dag was.', title_pl = 'Kontakt wzrokowy to podstawa 🥂', body_pl = 'Dziecko niespodziewanie wcześnie zasnęło! Nie trać tej rzadkiej chwili na sprzątanie. Usiądź naprzeciwko partnera, wyłączcie telewizor i patrząc sobie w oczy, po prostu zapytajcie się, jak minął wam dzień.', title_pt = 'O contacto visual é essencial 🥂', body_pt = 'A criança adormeceu mais cedo do que o esperado! Não gaste este momento raro a limpar a casa. Sente-se frente a frente com o seu companheiro, desligue a televisão e, olhos nos olhos, pergunte como foi o dia de cada um.', title_sv = 'Ögonkontakt är ett måste 🥂', body_sv = 'Barnet somnade oväntat tidigt! Lägg inte den sällsynta stunden på att städa. Sätt dig mitt emot din partner, stäng av tv:n, se varandra i ögonen och fråga bara hur dagen har varit.', title_vi = 'Giao tiếp bằng ánh mắt là cần thiết 🥂', body_vi = 'Bé ngủ sớm bất ngờ! Đừng dành khoảnh khắc hiếm hoi này để dọn nhà. Hãy ngồi đối diện với chồng, tắt TV, nhìn vào mắt nhau và hỏi hôm nay đã trôi qua thế nào.', title_zh = '一定要眼神交流 🥂', body_zh = '孩子出乎意料地早早睡着了！别把这难得的时刻花在打扫上。和另一半面对面坐下，关掉电视，看着彼此的眼睛，问问今天过得怎么样。' WHERE id = '0574f644-1505-478c-8228-ceb707400249' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Grabadora en vivo 🎙️', body_es = '¿Repite como un loro hasta la palabra más casual que dices? Es tu espejo en vivo. Presta el doble de atención a las palabras y emociones que usas delante de tu peque, porque lo copia todo.', title_fr = 'Magnétophone vivant 🎙️', body_fr = 'Il répète comme un perroquet même le mot le plus anodin qui vous échappe ? Il est votre miroir vivant. Faites doublement attention aux mots et aux émotions que vous exprimez près de lui, il copie tout.', title_hi = 'जीता-जागता रिकॉर्डर 🎙️', body_hi = 'आपके मुँह से निकला कोई भी अनजाना शब्द तोते की तरह तुरंत दोहराता है? वह आपका जीता-जागता आईना है। उसके सामने बोले जाने वाले शब्दों और भावनाओं पर दोगुना ध्यान दीजिए, वह सब कुछ नकल करता है।', title_id = 'Perekam hidup 🎙️', body_id = 'Kata paling acak yang Anda ucapkan pun langsung ia ulangi seperti burung beo? Ia adalah cermin hidup Anda. Perhatikan dua kali lipat kata dan emosi yang Anda ucapkan di dekatnya, ia meniru segalanya.', title_ja = '生きたボイスレコーダー 🎙️', body_ja = 'あなたの口から出たなにげない言葉まで、すぐにオウムのようにまねしますか？お子さんはあなたを映す生きた鏡です。そばで話す言葉や感情表現に倍の注意を払って、なんでもまねします。', title_ko = '살아 있는 녹음기 🎙️', body_ko = '엄마가 무심코 한 말까지 앵무새처럼 바로 따라 하나요? 아이는 엄마를 비추는 살아 있는 거울이에요. 아이 앞에서 쓰는 말과 감정에 두 배로 신경 써 주세요. 모든 걸 따라 하니까요.', title_nl = 'Levende recorder 🎙️', body_nl = 'Herhaalt hij zelfs het meest toevallige woord dat jij zegt meteen als een papegaai? Hij is je levende spiegel. Let dubbel op de woorden en emoties die je in zijn bijzijn gebruikt, hij kopieert alles.', title_pl = 'Żywy dyktafon 🎙️', body_pl = 'Każde, nawet najbardziej przypadkowe słowo, które wypowiesz, od razu powtarza jak papużka? Jest twoim żywym lustrem. Zwracaj podwójną uwagę na słowa i emocje, które przy nim wyrażasz, bo on wszystko kopiuje.', title_pt = 'Gravador vivo 🎙️', body_pt = 'Repete logo, como um papagaio, até a palavra mais casual que lhe sai da boca? É o seu espelho vivo. Tenha atenção redobrada às palavras e emoções que usa perto dele: ele copia tudo.', title_sv = 'Levande diktafon 🎙️', body_sv = 'Upprepar barnet genast även det mest slumpmässiga ord du säger, som en papegoja? Barnet är din levande spegel. Tänk dubbelt så mycket på vilka ord och känslor du uttrycker när barnet är nära, hen kopierar allt.', title_vi = 'Chiếc máy ghi âm sống 🎙️', body_vi = 'Bé lặp lại ngay như vẹt cả những từ ngẫu nhiên nhất mẹ vừa nói? Bé là tấm gương sống của mẹ. Hãy chú ý gấp đôi đến lời nói và cảm xúc của mẹ khi ở cạnh bé, vì bé bắt chước mọi thứ.', title_zh = '活的录音机 🎙️', body_zh = '你随口说的每一个词，宝宝都像小鹦鹉一样马上跟着说？宝宝就是你的一面活镜子。在宝宝身边说话和表达情绪时要加倍注意，宝宝什么都会模仿。' WHERE id = '091c7303-14ec-4220-83cd-0ec1c91a3ce2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La realidad del café frío ☕', body_es = 'Servirse un café y bebérselo helado 3 horas después es la ley no escrita de la maternidad. ¡Hoy haz algo diferente! Déjale solo con sus juguetes y tómate ese café caliente en 10 minutos. Te lo mereces.', title_fr = 'La réalité du café froid ☕', body_fr = 'Se servir un café et le boire glacé 3 heures plus tard, c''est la loi non écrite de la maternité. Aujourd''hui, changez la règle ! Laissez-le seul avec ses jouets et buvez ce café encore chaud en 10 minutes. Vous le méritez.', title_hi = 'ठंडी कॉफ़ी की सच्चाई ☕', body_hi = 'कॉफ़ी बनाकर 3 घंटे बाद बर्फ़ जैसी ठंडी पीना माँ होने का अनलिखा नियम है। आज कुछ अलग कीजिए! उसे खिलौनों के साथ अकेला छोड़िए और वह कॉफ़ी 10 मिनट के अंदर गर्म-गर्म पीजिए। आप इसकी हकदार हैं।', title_id = 'Kenyataan kopi dingin ☕', body_id = 'Menuang kopi lalu meminumnya sedingin es 3 jam kemudian adalah hukum tak tertulis menjadi ibu. Hari ini coba berbeda! Biarkan ia bermain sendiri dengan mainannya dan minum kopi itu selagi hangat dalam 10 menit. Anda layak mendapatkannya.', title_ja = '冷めたコーヒーの現実 ☕', body_ja = 'コーヒーをいれて3時間後に冷えきったまま飲むのは、子育ての暗黙のルール。今日はひと工夫を！お子さんをおもちゃとひとりで遊ばせて、そのコーヒーを10分以内に温かいうちに飲みましょう。あなたにはその価値があります。', title_ko = '식은 커피의 현실 ☕', body_ko = '커피를 따르고 3시간 뒤에 얼음처럼 식은 채 마시는 건 엄마들의 불문율이죠. 오늘은 달라져 보세요! 아이가 장난감과 노는 동안 그 커피를 10분 안에 따뜻할 때 드세요. 그럴 자격이 있어요.', title_nl = 'De realiteit van koude koffie ☕', body_nl = 'Koffie inschenken en die 3 uur later ijskoud drinken is de ongeschreven wet van het moederschap. Doe vandaag eens anders! Laat hem even alleen met zijn speelgoed en drink die koffie binnen 10 minuten, nog warm. Dat verdien je.', title_pl = 'Rzeczywistość zimnej kawy ☕', body_pl = 'Nalać kawę i wypić ją 3 godziny później zimną jak lód to niepisane prawo macierzyństwa. Dziś zrób inaczej! Zostaw go z zabawkami i wypij tę kawę w 10 minut, póki jest gorąca. Zasługujesz na to.', title_pt = 'A realidade do café frio ☕', body_pt = 'Servir o café e bebê-lo gelado 3 horas depois é a lei não escrita da maternidade. Hoje faça diferente! Deixe-o com os brinquedos e beba esse café quente, em 10 minutos. Merece-o.', title_sv = 'Det kalla kaffets verklighet ☕', body_sv = 'Att hälla upp kaffet och dricka det iskallt 3 timmar senare är moderskapets oskrivna lag. Gör något annorlunda i dag! Lämna barnet ensamt med leksakerna och drick kaffet medan det är varmt, inom 10 minuter. Du förtjänar det.', title_vi = 'Sự thật về ly cà phê nguội ☕', body_vi = 'Rót cà phê rồi 3 tiếng sau uống khi đã nguội ngắt là luật bất thành văn của các mẹ. Hôm nay hãy khác đi! Để bé chơi một mình với đồ chơi và uống ly cà phê khi còn nóng trong vòng 10 phút. Mẹ xứng đáng được như vậy.', title_zh = '冷咖啡的现实 ☕', body_zh = '倒好咖啡，3小时后才喝上冰凉的，是当妈妈不成文的规定。今天来点不一样的吧！让宝宝和玩具自己玩，你在10分钟内趁热把那杯咖啡喝掉。你值得。' WHERE id = 'e60389be-4932-49bf-9ebd-d4caa963b145' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tormenta secreta de mamá 🩸', body_es = '¿Cansancio repentino, ganas de llorar sin motivo? Abre el Calendario menstrual. Quizá estés en fase de SPM. No te culpes: prepara un tentempié con magnesio de Recetas saludables y escucha a tu cuerpo.', title_fr = 'La tempête secrète de maman 🩸', body_fr = 'Fatigue soudaine, envie de pleurer sans raison ? Ouvrez le Suivi des règles. Vous êtes peut-être en période de SPM. Ne vous blâmez pas, préparez une collation au magnésium avec les Recettes saines et écoutez votre corps.', title_hi = 'माँ का छिपा तूफ़ान 🩸', body_hi = 'अचानक थकान, बिना वजह रोने का मन? पीरियड ट्रैकर खोलिए। शायद PMS चल रहा है। खुद को दोष मत दीजिए, सेहतमंद रेसिपी से मैग्नीशियम वाला स्नैक बनाइए और अपने शरीर की सुनिए।', title_id = 'Badai rahasia Ibu 🩸', body_id = 'Tiba-tiba lelah dan ingin menangis tanpa sebab? Buka Pelacak Menstruasi. Mungkin Anda sedang PMS. Jangan salahkan diri, buat camilan bermagnesium dari Resep Sehat dan dengarkan tubuh Anda.', title_ja = 'ママのひそかな嵐 🩸', body_ja = '急な疲れ、理由もなく泣きたい気持ち？「生理トラッカー」を開いてみましょう。PMSの時期かもしれません。自分を責めずに、「ヘルシーレシピ」からマグネシウムたっぷりのおやつをつくって、体の声を聞いて。', title_ko = '엄마의 숨은 폭풍 🩸', body_ko = '갑자기 피곤하고 이유 없이 울고 싶나요? 생리 주기 기록을 열어 보세요. PMS 기간일 수도 있어요. 자책하지 말고 건강한 레시피에서 마그네슘이 든 간식을 만들어 몸의 소리를 들어 주세요.', title_nl = 'Mama''s verborgen storm 🩸', body_nl = 'Plotseling moe, zomaar zin om te huilen? Open de Cyclustracker. Misschien zit je in je PMS-periode. Veroordeel jezelf niet, maak een tussendoortje met magnesium uit Gezonde recepten en luister naar je lichaam.', title_pl = 'Ukryta burza mamy 🩸', body_pl = 'Nagłe zmęczenie, chęć płaczu bez powodu? Otwórz Kalendarz miesiączkowy. Może to czas PMS. Nie obwiniaj się, przygotuj ze Zdrowych przepisów przekąskę z magnezem i wsłuchaj się w swoje ciało.', title_pt = 'A tempestade secreta da mãe 🩸', body_pt = 'Cansaço repentino, vontade de chorar sem razão? Abra o Registo do Período. Talvez esteja na fase de TPM. Não se culpe: prepare um snack com magnésio das Receitas Saudáveis e ouça o seu corpo.', title_sv = 'Mammas dolda storm 🩸', body_sv = 'Plötslig trötthet, lust att gråta utan anledning? Öppna Mensspåraren. Kanske är du i PMS-perioden. Klandra inte dig själv, gör ett magnesiumrikt mellanmål från Hälsosamma recept och lyssna på din kropp.', title_vi = 'Cơn bão thầm lặng của mẹ 🩸', body_vi = 'Bỗng mệt mỏi, muốn khóc không lý do? Hãy mở Theo dõi kỳ kinh. Có thể mẹ đang trong giai đoạn tiền kinh nguyệt. Đừng tự trách, hãy làm món ăn vặt giàu magie từ Công thức lành mạnh và lắng nghe cơ thể.', title_zh = '妈妈心里的风暴 🩸', body_zh = '突然很累，莫名想哭？打开经期记录。也许你正处在经前期。别责怪自己，从健康食谱里做一份含镁的小零食，倾听身体的声音。' WHERE id = '28610640-860d-43af-8a5a-381f751b562e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pediatra digital 🤖', body_es = '¿Te ha preocupado de repente la curva de talla y peso de tu peque de 33 meses? No busques enfermedades que asustan en foros de internet: aprende con Anacan AI la realidad precisa, al instante y con base científica.', title_fr = 'Le pédiatre numérique 🤖', body_fr = 'Les courbes de taille et de poids de votre enfant de 33 mois vous inquiètent soudain ? Ne cherchez pas de maladies effrayantes sur les forums, découvrez avec Anacan AI une réalité précise, immédiate et fondée sur la science.', title_hi = 'डिजिटल बाल रोग विशेषज्ञ 🤖', body_hi = '33 महीने के बच्चे की लंबाई और वज़न का चार्ट अचानक चिंता में डाल रहा है? इंटरनेट फ़ोरम पर डरावनी बीमारियाँ मत ढूँढिए, Anacan AI से तुरंत सटीक और वैज्ञानिक आधार वाली सच्चाई जानिए।', title_id = 'Dokter anak digital 🤖', body_id = 'Grafik tinggi dan berat badan anak usia 33 bulan tiba-tiba membuat Anda cemas? Jangan mencari penyakit menakutkan di forum internet, pelajari fakta yang tepat, cepat, dan berdasar ilmiah dari Anacan AI.', title_ja = 'デジタル小児科医 🤖', body_ja = '生後33か月のお子さんの身長や体重のグラフが急に気になりましたか？ネットの掲示板でこわい病気を探さないで、Anacan AIから正確で、すぐに、科学的な根拠のある事実を学びましょう。', title_ko = '디지털 소아과 의사 🤖', body_ko = '33개월 아이의 키와 몸무게 그래프가 갑자기 걱정되나요? 인터넷 게시판에서 무서운 병을 찾지 말고 Anacan AI에게 정확하고 과학적인 정보를 바로 받아 보세요.', title_nl = 'Digitale kinderarts 🤖', body_nl = 'Maakte de lengte- en gewichtscurve van je kind van 33 maanden je ineens ongerust? Zoek niet op internetfora naar enge ziektes, maar krijg meteen nauwkeurige, wetenschappelijk onderbouwde informatie van Anacan AI.', title_pl = 'Cyfrowy pediatra 🤖', body_pl = 'Siatki wzrostu i wagi 33-miesięcznego dziecka nagle cię zaniepokoiły? Nie szukaj na forach przerażających chorób, poznaj od Anacan AI dokładne, natychmiastowe i oparte na nauce fakty.', title_pt = 'Pediatra digital 🤖', body_pt = 'As curvas de altura e peso do seu filho de 33 meses preocuparam-na de repente? Não procure doenças assustadoras nos fóruns da internet: conheça a realidade precisa, imediata e com base científica no Anacan AI.', title_sv = 'Digital barnläkare 🤖', body_sv = 'Har 33-månadersbarnets längd- och viktkurva plötsligt oroat dig? Sök inte efter skrämmande sjukdomar i forum på nätet, få exakta, omedelbara och vetenskapligt grundade fakta från Anacan AI.', title_vi = 'Bác sĩ nhi khoa kỹ thuật số 🤖', body_vi = 'Biểu đồ chiều cao và cân nặng của bé 33 tháng bỗng khiến mẹ lo lắng? Đừng tìm những căn bệnh đáng sợ trên các diễn đàn mạng, hãy hỏi Anacan AI để biết ngay thực tế chính xác, có cơ sở khoa học.', title_zh = '数字儿科医生 🤖', body_zh = '33个月宝宝的身高体重曲线突然让你担心？别在网上论坛里搜那些吓人的疾病，向Anacan AI了解准确、即时、有科学依据的事实吧。' WHERE id = '51272fb1-4e13-49cf-9f74-cdaa0749b5ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El efecto Mozart 🎶', body_es = '¿Por la tarde empieza una agresividad sin motivo? Apaga la tele, baja las luces y pon en la habitación una música clásica muy suave. La armonía del agua y la música cambiará el ambiente como por arte de magia.', title_fr = 'L''effet Mozart 🎶', body_fr = 'Une agressivité sans raison commence en fin d''après-midi. Éteignez la télé, baissez les lumières et mettez une musique classique très douce dans la pièce. L''harmonie de l''eau et de la musique changera l''atmosphère comme par magie.', title_hi = 'मोत्ज़ार्ट इफ़ेक्ट 🎶', body_hi = 'शाम को बिना वजह गुस्सा शुरू हो गया? टीवी बंद कीजिए, लाइटें धीमी कीजिए और कमरे में बहुत हल्का शास्त्रीय संगीत चलाइए। पानी और संगीत का तालमेल माहौल को जादुई ढंग से बदल देगा।', title_id = 'Efek Mozart 🎶', body_id = 'Menjelang malam ia tiba-tiba agresif tanpa sebab. Matikan TV, redupkan lampu, dan putar musik klasik yang sangat lembut di kamar. Paduan air dan musik akan mengubah suasana secara ajaib.', title_ja = 'モーツァルト効果 🎶', body_ja = '夕方に理由のない攻撃的な態度が始まりました。テレビを消し、照明を落として、とても静かなクラシック音楽を流しましょう。お水と音楽のハーモニーが、魔法のように空気を変えてくれます。', title_ko = '모차르트 효과 🎶', body_ko = '저녁 무렵 이유 없이 공격적으로 변했나요? TV를 끄고 조명을 낮춘 뒤 아주 잔잔한 클래식 음악을 틀어 주세요. 물과 음악의 조화가 분위기를 마법처럼 바꿔 줄 거예요.', title_nl = 'Het Mozart-effect 🎶', body_nl = 'Begint hij aan het eind van de middag zonder reden agressief te worden? Zet de tv uit, dim de lichten en laat heel zachte klassieke muziek in de kamer klinken. De harmonie van water en muziek verandert de sfeer als bij toverslag.', title_pl = 'Efekt Mozarta 🎶', body_pl = 'Pod wieczór pojawia się agresja bez powodu? Wyłącz telewizor, przygaś światło i puść w pokoju bardzo cichą muzykę klasyczną. Harmonia wody i muzyki magicznie zmieni atmosferę.', title_pt = 'O efeito Mozart 🎶', body_pt = 'Ao fim da tarde começou uma agressividade sem razão. Desligue a televisão, baixe as luzes e ponha no quarto música clássica muito suave. A harmonia da água e da música vai mudar o ambiente como por magia.', title_sv = 'Mozarteffekten 🎶', body_sv = 'Har det börjat en aggressivitet utan orsak på eftermiddagen? Stäng av tv:n, dämpa ljuset och spela mycket lätt klassisk musik i rummet. Harmonin mellan vatten och musik förändrar stämningen magiskt.', title_vi = 'Hiệu ứng Mozart 🎶', body_vi = 'Chiều tối bé bỗng trở nên hung hăng không lý do. Hãy tắt TV, giảm ánh sáng và bật một bản nhạc cổ điển thật nhẹ trong phòng. Sự hòa quyện của nước và âm nhạc sẽ thay đổi bầu không khí một cách kỳ diệu.', title_zh = '莫扎特效应 🎶', body_zh = '傍晚无缘无故开始发脾气？关掉电视，调暗灯光，在房间里放一点非常轻柔的古典音乐。水和音乐的和谐会神奇地改变整个氛围。' WHERE id = 'b5429001-8d63-464c-9e9d-56aab19950f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pruebas de vuelo 🧗‍♂️', body_es = 'Se lanza desde el sofá sobre los cojines. Está probando la gravedad y su valentía. En lugar de prohibírselo, crea en la habitación una zona segura para saltar y deja que suelte energía.', title_fr = 'Essais de vol 🧗‍♂️', body_fr = 'Il se jette du canapé sur les coussins. Il teste la gravité et son courage. Au lieu d''interdire, créez dans la pièce une zone de saut sécurisée et laissez-le se défouler.', title_hi = 'उड़ान के प्रयोग 🧗‍♂️', body_hi = 'सोफ़े से तकियों पर कूद जाता है? वह गुरुत्वाकर्षण और अपनी हिम्मत, दोनों को परख रहा है। मना करने के बजाय कमरे में कूदने के लिए एक सुरक्षित जगह बनाइए और उसे अपनी ऊर्जा निकालने दीजिए।', title_id = 'Uji terbang 🧗‍♂️', body_id = 'Ia melompat dari sofa ke tumpukan bantal. Ia sedang menguji gravitasi dan keberaniannya. Daripada melarang, buat zona lompat yang aman di kamar dan biarkan ia menyalurkan energinya.', title_ja = '飛行テスト 🧗‍♂️', body_ja = 'ソファからクッションの上へ飛びこみますか？重力と自分の勇気を試しています。禁止するかわりに、部屋に安全なジャンプゾーンをつくって、エネルギーを発散させてあげましょう。', title_ko = '비행 시험 🧗‍♂️', body_ko = '소파에서 쿠션 위로 몸을 던지나요? 중력과 자신의 용기를 시험하는 중이에요. 막는 대신 방에 안전한 점프 구역을 만들어 에너지를 마음껏 쓰게 해 주세요.', title_nl = 'Vliegtesten 🧗‍♂️', body_nl = 'Springt hij van de bank op de kussens? Hij test de zwaartekracht en zijn eigen moed. Verbied het niet, maar maak een veilige springzone in de kamer en laat hem zijn energie kwijt.', title_pl = 'Próby lotu 🧗‍♂️', body_pl = 'Skacze z kanapy na poduszki? Sprawdza grawitację i swoją odwagę. Zamiast zabraniać, stwórz w pokoju bezpieczną strefę do skakania i pozwól mu się wyszaleć.', title_pt = 'Testes de voo 🧗‍♂️', body_pt = 'Atira-se do sofá para cima das almofadas. Está a testar a gravidade e a coragem. Em vez de proibir, crie no quarto uma zona segura para saltar e deixe-o gastar energia.', title_sv = 'Flygförsök 🧗‍♂️', body_sv = 'Kastar sig barnet från soffan ner på kuddarna? Hen testar tyngdkraften och sitt mod. I stället för att förbjuda, skapa en säker hoppzon i rummet och låt hen göra av med energin.', title_vi = 'Thử nghiệm bay 🧗‍♂️', body_vi = 'Bé lao mình từ sofa xuống đống gối. Bé đang thử trọng lực và lòng can đảm. Thay vì cấm đoán, hãy tạo một khu nhảy an toàn trong phòng để bé xả năng lượng.', title_zh = '飞行测试 🧗‍♂️', body_zh = '从沙发上扑到靠垫上？宝宝在测试重力和自己的勇气。与其禁止，不如在房间里布置一个安全的跳跃区，让宝宝释放精力。' WHERE id = '8510671a-e1a9-4df3-abde-5ad11cb9aee4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descifrar el llanto nocturno 😭', body_es = 'Las crisis de llanto sin causa aparente agotan a cualquiera. Deja de adivinar: con el Análisis del llanto intenta entender el mensaje oculto tras el sonido (dolor, cansancio) y cálmale.', title_fr = 'Décoder les pleurs de la nuit 😭', body_fr = 'Les crises de pleurs dont on ne trouve pas la cause sont épuisantes. Arrêtez de deviner : avec l''Analyse des pleurs, essayez de comprendre le message caché (douleur, fatigue) et apaisez-le.', title_hi = 'रात की चीख का राज़ 😭', body_hi = 'जिस रोने की वजह न मिले, वह इंसान को थका देता है। अंदाज़े लगाना छोड़िए, क्राइंग एनालिसिस टूल से आवाज़ के पीछे छिपा संदेश (दर्द, थकान) समझने की कोशिश कीजिए और उसे शांत कीजिए।', title_id = 'Kode rahasia tangisan malam 😭', body_id = 'Krisis tangisan yang tidak Anda ketahui penyebabnya sungguh menguras tenaga. Berhentilah menebak, gunakan Analisis Tangisan untuk memahami pesan tersembunyi di balik suaranya (sakit, lelah) dan tenangkan ia.', title_ja = '夜泣きの暗号 😭', body_ja = '理由がわからない泣きは、本当に疲れますよね。推測はやめて、「泣き声分析」で声に隠れたメッセージ（痛み、疲れ）を読み取り、落ち着かせてあげましょう。', title_ko = '밤의 울음 해독하기 😭', body_ko = '이유를 알 수 없는 울음은 사람을 지치게 하죠. 추측은 그만하고 울음 분석 도구로 소리 뒤에 숨은 메시지(통증, 피곤함)를 알아보며 아이를 달래 주세요.', title_nl = 'De code van nachtelijk gehuil 😭', body_nl = 'Huilbuien waarvan je de oorzaak niet vindt, putten je uit. Stop met raden: probeer met Huilanalyse de verborgen boodschap achter het geluid (pijn, vermoeidheid) te begrijpen en kalmeer hem.', title_pl = 'Szyfr nocnego płaczu 😭', body_pl = 'Napady płaczu, których przyczyny nie znasz, wykańczają. Przestań zgadywać, w Analizie płaczu spróbuj zrozumieć ukrytą wiadomość (ból, zmęczenie) za tym dźwiękiem i go uspokój.', title_pt = 'Decifrar o choro da noite 😭', body_pt = 'Crises de choro sem causa aparente esgotam qualquer um. Deixe de adivinhar: use a Análise do Choro para perceber a mensagem escondida no som (dor, cansaço) e acalme-o.', title_sv = 'Koden bakom nattens gråt 😭', body_sv = 'Gråtkriser som du inte hittar orsaken till tar all ork. Sluta gissa, försök förstå det dolda budskapet (smärta, trötthet) bakom ljudet med verktyget Gråtanalys och lugna barnet.', title_vi = 'Giải mã tiếng khóc ban đêm 😭', body_vi = 'Những cơn khóc không rõ nguyên nhân khiến mẹ kiệt sức. Đừng đoán nữa, hãy dùng công cụ Phân tích tiếng khóc để hiểu thông điệp ẩn sau tiếng khóc (đau, mệt) và xoa dịu bé.', title_zh = '解开夜间哭喊的密码 😭', body_zh = '找不到原因的哭闹最让人筋疲力尽。别再猜了，用哭声分析工具试着读懂哭声背后的秘密信息（疼痛、疲惫），让宝宝平静下来。' WHERE id = '8f7f72ec-9698-4ef9-a7b6-a44bc3f231c0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maestra del camuflaje 🥦', body_es = '¿Aparta las verduras de la sopa como si las buscara con microscopio? Encuentra en Recetas saludables salsas que hacen invisibles las verduras. La creatividad es el arma secreta más grande de una madre.', title_fr = 'Maître du camouflage 🥦', body_fr = 'Il trie les légumes de la soupe comme s''il les cherchait au microscope ? Trouvez dans les Recettes saines des sauces qui rendront les légumes invisibles. La créativité est la plus grande arme secrète d''une maman.', title_hi = 'छलावरण का उस्ताद 🥦', body_hi = 'सूप की सब्ज़ियाँ ऐसे ढूँढकर अलग करता है जैसे माइक्रोस्कोप से देख रहा हो? सेहतमंद रेसिपी में ऐसे सॉस ढूँढिए जो सब्ज़ियों को गायब कर दें। रचनात्मकता माँ का सबसे बड़ा खुफ़िया हथियार है।', title_id = 'Ahli kamuflase 🥦', body_id = 'Ia menyisihkan sayuran di sup seolah mencarinya dengan mikroskop? Temukan resep saus yang membuat sayuran tak terlihat di Resep Sehat. Kreativitas adalah senjata rahasia terbesar seorang ibu.', title_ja = 'カモフラージュの達人 🥦', body_ja = 'スープの野菜を顕微鏡で探すように、ひとつ残らずよけていますか？「ヘルシーレシピ」で野菜が見えなくなるソースのレシピを見つけましょう。創意工夫はママのいちばんの秘密兵器です。', title_ko = '위장술의 달인 🥦', body_ko = '수프 속 채소를 현미경으로 찾듯 골라내나요? 건강한 레시피에서 채소를 감쪽같이 숨겨 주는 소스 레시피를 찾아보세요. 창의력은 엄마의 가장 큰 비밀 무기예요.', title_nl = 'Meester in camouflage 🥦', body_nl = 'Vist hij de groenten uit zijn soep alsof hij ze met een microscoop zoekt? Vind in Gezonde recepten sausjes die groenten onzichtbaar maken. Creativiteit is het grootste geheime wapen van een moeder.', title_pl = 'Mistrz kamuflażu 🥦', body_pl = 'Odkłada warzywa z zupy na bok, jakby szukał ich pod mikroskopem? Znajdź w Zdrowych przepisach przepisy na sosy, w których warzywa staną się niewidoczne. Kreatywność to największa tajna broń mamy.', title_pt = 'Mestre da camuflagem 🥦', body_pt = 'Põe de lado os legumes da sopa como se os procurasse ao microscópio? Encontre nas Receitas Saudáveis receitas de molhos que tornam os legumes invisíveis. A criatividade é a maior arma secreta de uma mãe.', title_sv = 'Kamouflagemästare 🥦', body_sv = 'Sorterar barnet bort grönsakerna i soppan som om hen letade med mikroskop? Hitta såsrecept i Hälsosamma recept som gör grönsakerna osynliga. Kreativitet är mammans största hemliga vapen.', title_vi = 'Bậc thầy ngụy trang 🥦', body_vi = 'Bé gạt rau trong bát canh ra như thể soi bằng kính hiển vi? Hãy tìm trong Công thức lành mạnh những công thức nước sốt giúp rau "tàng hình". Sự sáng tạo là vũ khí bí mật lớn nhất của người mẹ.', title_zh = '伪装大师 🥦', body_zh = '像拿着显微镜一样把汤里的蔬菜挑到一边？在健康食谱里找找能让蔬菜“隐身”的酱汁做法。创意是妈妈最大的秘密武器。' WHERE id = 'a4f7c95b-7fff-41b8-a6d4-80ab1d481977' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La guerra del cepillo 🦷', body_es = '¿No te deja acercarle el cepillo a la boca y quiere hacerlo él? No lo conviertas en una obligación, sino en un juego. Que primero te lave él los dientes a ti y luego te toque a ti.', title_fr = 'La guerre de la brosse à dents 🦷', body_fr = 'Il refuse que vous approchiez la brosse de sa bouche et veut le faire tout seul ? Faites-en un jeu, pas une contrainte. Laissez-le d''abord vous brosser les dents, puis ce sera votre tour.', title_hi = 'ब्रश की जंग 🦷', body_hi = 'टूथब्रश मुँह के पास नहीं आने देता और खुद करना चाहता है? इसे मजबूरी नहीं, खेल बनाइए। पहले उसे आपके दाँत ब्रश करने दीजिए, फिर अगली बारी आपकी।', title_id = 'Perang sikat gigi 🦷', body_id = 'Ia tidak mau sikat gigi didekatkan ke mulutnya dan ingin melakukannya sendiri? Jadikan ini permainan, bukan paksaan. Biarkan ia menyikat gigi Anda dulu, lalu giliran Anda.', title_ja = '歯ブラシ戦争 🦷', body_ja = '歯ブラシを口に近づけさせず、自分でやりたがりますか？義務ではなく遊びに変えましょう。まずお子さんにあなたの歯をみがいてもらい、次はあなたの番にして。', title_ko = '칫솔 전쟁 🦷', body_ko = '칫솔을 입에 대지도 못하게 하고 혼자 하겠다고 하나요? 의무가 아닌 놀이로 바꿔 보세요. 먼저 아이가 엄마 이를 닦아 주고, 다음은 엄마 차례로 해 보세요.', title_nl = 'Tandenborsteloorlog 🦷', body_nl = 'Laat hij de tandenborstel niet in de buurt van zijn mond komen en wil hij het zelf doen? Maak er geen verplichting maar een spel van. Laat hem eerst jouw tanden poetsen, daarna ben jij aan de beurt.', title_pl = 'Wojna o szczoteczkę 🦷', body_pl = 'Nie pozwala zbliżyć szczoteczki do buzi i chce sam? Zamień to nie w przymus, tylko w zabawę. Niech najpierw on umyje zęby tobie, a potem twoja kolej.', title_pt = 'A guerra da escova 🦷', body_pt = 'Não a deixa aproximar a escova da boca e quer fazer sozinho? Transforme isto não numa obrigação, mas num jogo. Deixe-o primeiro escovar-lhe os dentes a si e depois é a sua vez.', title_sv = 'Tandborstkriget 🦷', body_sv = 'Låter barnet inte tandborsten komma nära munnen och vill göra det själv? Gör det till en lek i stället för ett tvång. Låt barnet först borsta dina tänder, sedan är det din tur.', title_vi = 'Cuộc chiến bàn chải 🦷', body_vi = 'Bé không cho mẹ đưa bàn chải lại gần miệng và đòi tự đánh? Hãy biến việc này thành trò chơi chứ không phải ép buộc. Để bé đánh răng cho mẹ trước, rồi đến lượt mẹ.', title_zh = '牙刷大战 🦷', body_zh = '不让牙刷靠近嘴巴，非要自己来？别把它变成强迫，变成游戏吧。让宝宝先给你刷牙，接下来再轮到你。' WHERE id = '30d43616-cc93-4cce-b2c3-cdd876b6c9e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Permiso para el desorden 🌪️', body_es = '¿Cansada de guardar cada día los mismos juguetes en la caja? ¡Hoy no recojas! Tu casa no es un museo, es un lugar lleno de vida. No te fijes en el desorden, sino en la alegría de tu peque al descubrir.', title_fr = 'Le désordre autorisé 🌪️', body_fr = 'Fatiguée de ranger chaque jour les mêmes jouets dans le coffre ? Aujourd''hui, ne rangez pas ! Une maison n''est pas un musée, c''est un lieu plein de vie. Concentrez-vous non pas sur le désordre, mais sur la joie de découvrir de votre enfant.', title_hi = 'बिखराव की इजाज़त 🌪️', body_hi = 'रोज़ वही खिलौने डिब्बे में भरते-भरते थक गईं? आज मत समेटिए! घर कोई म्यूज़ियम नहीं, ज़िंदगी से भरी जगह है। बिखराव पर नहीं, अपने बच्चे की खोज की खुशी पर ध्यान दीजिए।', title_id = 'Izin untuk berantakan 🌪️', body_id = 'Lelah memasukkan mainan yang sama ke kotak setiap hari? Hari ini jangan dibereskan! Rumah bukan museum, tetapi tempat yang penuh kehidupan. Fokuslah bukan pada kekacauan, tetapi pada kegembiraan anak Anda saat bereksplorasi.', title_ja = '散らかしてもOK 🌪️', body_ja = '毎日同じおもちゃを箱にしまうのに疲れましたか？今日は片づけなくていい！家は博物館ではなく、命があふれる場所です。散らかりではなく、お子さんの発見のよろこびに目を向けましょう。', title_ko = '어질러도 괜찮아요 🌪️', body_ko = '매일 같은 장난감을 상자에 담느라 지쳤나요? 오늘은 치우지 마세요! 집은 박물관이 아니라 생기 넘치는 공간이에요. 어질러짐 말고 아이가 발견하는 기쁨에 집중하세요.', title_nl = 'Rommel mag 🌪️', body_nl = 'Ben je het zat om elke dag hetzelfde speelgoed in de bak te doen? Ruim vandaag niet op! Je huis is geen museum, maar een plek vol leven. Richt je niet op de rommel, maar op de ontdekkingsvreugde van je kind.', title_pl = 'Pozwolenie na bałagan 🌪️', body_pl = 'Masz dość codziennego wkładania tych samych zabawek do pudła? Dziś ich nie sprzątaj! Dom to nie muzeum, tylko miejsce pełne życia. Skup się nie na bałaganie, ale na radości odkrywania twojego dziecka.', title_pt = 'Licença para desarrumar 🌪️', body_pt = 'Cansada de arrumar todos os dias os mesmos brinquedos na caixa? Hoje não arrume! A casa não é um museu, é um lugar cheio de vida. Concentre-se não na desarrumação, mas na alegria de descobrir do seu filho.', title_sv = 'Lov att stöka 🌪️', body_sv = 'Är du trött på att plocka in samma leksaker i lådan varje dag? Låt bli i dag! Hemmet är inget museum, det är en plats full av liv. Fokusera inte på stöket utan på barnets glädje i att upptäcka.', title_vi = 'Cho phép bừa bộn 🌪️', body_vi = 'Mẹ mệt vì ngày nào cũng xếp lại những món đồ chơi giống nhau vào thùng? Hôm nay đừng dọn! Nhà không phải là bảo tàng, mà là nơi tràn đầy sức sống. Hãy tập trung vào niềm vui khám phá của bé chứ không phải sự bừa bộn.', title_zh = '允许凌乱 🌪️', body_zh = '每天把同样的玩具收进箱子，收累了？今天就别收了！家不是博物馆，而是充满生活气息的地方。别盯着凌乱，关注孩子探索的快乐吧。' WHERE id = '32681963-7779-41a7-9090-772ca76143b7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Le toca a papá 👨‍🍼', body_es = 'Ya tienes bastante con el cansancio del día. Deja a papá prepararle para dormir, lavarle los dientes y ponerle el pijama, y tú tómate el té en silencio a un lado.', title_fr = 'C''est au tour de papa 👨‍🍼', body_fr = 'La fatigue de la journée vous suffit. Confiez à papa la préparation au coucher, le brossage des dents et le pyjama, et buvez votre thé au calme, de votre côté.', title_hi = 'बारी पापा की है 👨‍🍼', body_hi = 'दिन की थकान आपके लिए काफ़ी है। शाम को बच्चे को सोने के लिए तैयार करना, दाँत ब्रश कराना और पजामा पहनाना पापा को सौंपिए, और आप एक तरफ़ खामोशी से चाय पीजिए।', title_id = 'Giliran Ayah 👨‍🍼', body_id = 'Kelelahan siang hari sudah cukup bagi Anda. Serahkan persiapan tidur, menyikat gigi, dan memakaikan piyama di sore hari kepada Ayah, sementara Anda minum teh dengan tenang di samping.', title_ja = 'パパの番 👨‍🍼', body_ja = '昼間の疲れでもう十分。夕方の寝る準備、歯みがき、パジャマの着がえはパパにお任せして、あなたは少し離れて静かにお茶を飲みましょう。', title_ko = '이제 아빠 차례예요 👨‍🍼', body_ko = '낮 동안의 피로만으로도 충분해요. 저녁 잠자리 준비, 양치, 잠옷 입히기는 아빠에게 맡기고, 엄마는 한쪽에서 조용히 차를 드세요.', title_nl = 'Papa is aan de beurt 👨‍🍼', body_nl = 'Je bent al moe genoeg van de dag. Laat het klaarmaken voor bed, het tandenpoetsen en de pyjama aantrekken aan het eind van de middag aan papa over, en drink jij aan de zijkant in stilte je thee.', title_pl = 'Kolej taty 👨‍🍼', body_pl = 'Masz dość dziennego zmęczenia. Przygotowanie do snu, mycie zębów i przebieranie w piżamę pod wieczór powierz tacie, a ty w ciszy wypij z boku herbatę.', title_pt = 'A vez é do pai 👨‍🍼', body_pt = 'O cansaço do dia já chega. Entregue ao pai a preparação para dormir ao fim da tarde, a escovagem dos dentes e o pijama, e beba o seu chá à parte, em silêncio.', title_sv = 'Pappas tur 👨‍🍼', body_sv = 'Dagens trötthet räcker för dig. Lämna över kvällens förberedelser för läggdags, tandborstningen och pyjamasen till pappa, och drick ditt te i tystnad en bit bort.', title_vi = 'Đến lượt bố 👨‍🍼', body_vi = 'Mệt mỏi ban ngày đã quá đủ với mẹ. Hãy giao việc chuẩn bị cho bé đi ngủ, đánh răng và thay đồ ngủ cho bố, còn mẹ ngồi một góc yên lặng uống trà.', title_zh = '轮到爸爸了 👨‍🍼', body_zh = '白天的疲惫已经够你受了。傍晚哄睡前的准备、刷牙、换睡衣，都交给爸爸吧，你在一旁安安静静地喝杯茶。' WHERE id = '500b7216-41e0-45a9-a2b9-20687055dfdc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mamá, mírame! 👀', body_es = '¿Cuando miras el móvil o haces otra cosa viene y te gira la cara hacia él? Quiere toda tu atención. Míralo a los ojos y hazle sentir que le escuchas y que es importante.', title_fr = 'Maman, regarde-moi ! 👀', body_fr = 'Quand vous regardez votre téléphone ou faites autre chose, il vient tourner votre visage vers lui ? Il veut toute votre attention. Regardez-le dans les yeux et faites-lui sentir que vous l''écoutez et qu''il compte.', title_hi = 'माँ, मुझे देखो! 👀', body_hi = 'आप फ़ोन या किसी और काम में लगी हों तो आकर आपका चेहरा अपनी ओर घुमा देता है? उसे आपका पूरा ध्यान चाहिए। आँखों में आँखें डालकर उसे महसूस कराइए कि आप उसे सुन रही हैं और वह ज़रूरी है।', title_id = 'Ibu, lihat aku! 👀', body_id = 'Saat Anda melihat ponsel atau sibuk dengan hal lain, ia datang dan memalingkan wajah Anda ke arahnya? Ia ingin perhatian penuh. Tatap matanya dan tunjukkan bahwa Anda mendengarkannya dan ia penting.', title_ja = 'ママ、こっち見て！👀', body_ja = 'あなたがスマホやほかのことを見ていると、やってきて顔を自分のほうへ向けますか？しっかり注目してほしいのです。目を合わせて、ちゃんと聞いていること、大切な存在だということを感じさせてあげましょう。', title_ko = '엄마, 나 좀 봐! 👀', body_ko = '엄마가 휴대폰이나 다른 일을 볼 때 다가와 얼굴을 자기 쪽으로 돌리나요? 온전한 관심을 원하는 거예요. 눈을 맞추며 귀 기울이고 있다는 것, 소중한 존재라는 걸 느끼게 해 주세요.', title_nl = 'Mama, kijk naar mij! 👀', body_nl = 'Draait hij je gezicht naar zich toe als je op je telefoon kijkt of met iets anders bezig bent? Hij wil je volle aandacht. Maak oogcontact en laat hem voelen dat je luistert en dat hij belangrijk is.', title_pl = 'Mamo, patrz na mnie! 👀', body_pl = 'Gdy patrzysz w telefon albo zajmujesz się czymś innym, podchodzi i odwraca twoją twarz do siebie? Chce pełnej uwagi. Nawiąż kontakt wzrokowy i daj mu poczuć, że go słuchasz i że jest ważny.', title_pt = 'Mamã, olha para mim! 👀', body_pt = 'Quando está a ver o telemóvel ou a fazer outra coisa, vem virar-lhe a cara para ele? Quer atenção total. Olhe-o nos olhos e mostre-lhe que o está a ouvir e que é importante.', title_sv = 'Mamma, titta på mig! 👀', body_sv = 'Kommer barnet och vänder ditt ansikte mot sig när du tittar på mobilen eller gör något annat? Hen vill ha all din uppmärksamhet. Skapa ögonkontakt och låt barnet känna att du lyssnar och att hen är viktig.', title_vi = 'Mẹ ơi, nhìn con này! 👀', body_vi = 'Khi mẹ nhìn điện thoại hay làm việc khác, bé chạy đến xoay mặt mẹ về phía mình? Bé muốn mẹ chú ý trọn vẹn. Hãy nhìn vào mắt bé để bé cảm nhận được mẹ đang lắng nghe và bé thật quan trọng.', title_zh = '妈妈，看我！👀', body_zh = '你看手机或忙别的事时，宝宝跑过来把你的脸转向自己？宝宝想要你全部的注意力。和宝宝对视，让宝宝感受到你在听，宝宝很重要。' WHERE id = 'be6a944e-f3ba-401c-9b99-70457d5df68b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las frases se convierten en cuentos 🗣️', body_es = '¿Ya junta palabras y cuenta historias graciosas e imaginarias? ¡Está viviendo una explosión de vocabulario!', title_fr = 'Les phrases deviennent des contes 🗣️', body_fr = 'Il assemble déjà les mots pour raconter des histoires drôles et imaginaires ? C''est l''explosion du vocabulaire !', title_hi = 'वाक्य कहानियाँ बन रहे हैं 🗣️', body_hi = 'अब शब्द जोड़कर मज़ेदार, काल्पनिक कहानियाँ सुनाता है? शब्दों का धमाका हो रहा है!', title_id = 'Kalimat menjadi dongeng 🗣️', body_id = 'Ia sudah merangkai kata dan bercerita lucu penuh khayalan? Ledakan kosakata sedang terjadi!', title_ja = '文がお話になる 🗣️', body_ja = 'もう言葉をつなげて、おもしろい空想のお話をしますか？語彙の爆発期です！', title_ko = '문장이 동화가 돼요 🗣️', body_ko = '이제 단어를 이어 웃기고 상상력 넘치는 이야기를 하나요? 어휘가 폭발적으로 늘고 있어요!', title_nl = 'Zinnen worden sprookjes 🗣️', body_nl = 'Rijgt hij al woorden aan elkaar en vertelt hij grappige, verzonnen verhaaltjes? Er is een woordexplosie gaande!', title_pl = 'Zdania zamieniają się w bajki 🗣️', body_pl = 'Łączy już słowa i opowiada zabawne, zmyślone historie? To eksplozja słownictwa!', title_pt = 'As frases viram contos 🗣️', body_pt = 'Já junta palavras e conta histórias cómicas e imaginárias? É uma explosão de vocabulário!', title_sv = 'Meningarna blir sagor 🗣️', body_sv = 'Sätter barnet redan ihop ord och berättar roliga, påhittade historier? Ordförrådet exploderar!', title_vi = 'Câu nói thành truyện cổ tích 🗣️', body_vi = 'Bé đã ghép các từ lại để kể những câu chuyện hài hước, tưởng tượng? Vốn từ đang bùng nổ!', title_zh = '句子变成故事 🗣️', body_zh = '已经会把词连起来，讲搞笑又充满想象的故事了？词汇量正在爆发！' WHERE id = 'e95e1a48-e2fe-47ab-898a-2c6c20ef5f3c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al quedarse dormido está más sensible. Para neutralizar los ruidos que llegan por la ventana, revisa el Medidor de sonido y enciende en la habitación un aparato de ruido blanco suave (white noise).', body_fr = 'Au moment de l''endormissement, il est plus sensible. Pour neutraliser les sons venant de la fenêtre, vérifiez le Sonomètre et allumez dans la chambre un appareil à bruit blanc doux.', body_hi = 'सोते समय संवेदनशीलता बढ़ जाती है। खिड़की से आने वाली आवाज़ों को दबाने के लिए साउंड मीटर से जाँचिए और कमरे में हल्का व्हाइट नॉइज़ (white noise) डिवाइस चलाइए।', body_id = 'Saat ia mulai terlelap, kepekaannya meningkat. Untuk meredam suara dari jendela, periksa Pengukur Suara dan nyalakan perangkat suara putih (white noise) yang lembut di kamar.', body_ja = '寝入りばなは音に敏感になります。窓の外から聞こえる音をやわらげるために、「サウンドメーター」で確認して、部屋でやさしいホワイトノイズの機械をつけましょう。', body_ko = '잠드는 순간에는 예민함이 커져요. 창밖에서 들어오는 소리를 줄이려면 소음 측정기로 확인하고 방에 은은한 백색소음 기기를 켜 주세요.', body_nl = 'Bij het inslapen is hij extra gevoelig. Check de Geluidsmeter en zet een zacht witteruisapparaat aan in de kamer om geluiden van buiten te neutraliseren.', body_pl = 'Gdy zasypia, jest bardziej wrażliwy. Aby zneutralizować odgłosy zza okna, sprawdź Miernik dźwięku i włącz w pokoju urządzenie z delikatnym białym szumem (white noise).', body_pt = 'Ao adormecer, a sensibilidade aumenta. Para neutralizar os sons que vêm da janela, verifique o Medidor de Som e ligue no quarto um aparelho de ruído branco (white noise) suave.', body_sv = 'Känsligheten ökar när barnet håller på att somna. För att neutralisera ljud från fönstret, kolla Ljudmätaren och sätt på en lätt vit brus-apparat (white noise) i rummet.', body_vi = 'Lúc bé đang chìm vào giấc ngủ là lúc nhạy cảm nhất. Để trung hòa tiếng ồn từ cửa sổ, hãy kiểm tra Đo âm thanh và bật máy tiếng ồn trắng (white noise) nhẹ nhàng trong phòng.', body_zh = '入睡的时候最敏感。为了屏蔽窗外的声音，看看分贝仪，在房间里打开轻柔的白噪音机。' WHERE id = '13a8c002-9f52-4112-970b-14cac50a9b5c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño ingeniero 🤔', body_es = '«¿Qué pasa si tiro esto?», «¿Para qué sirve este botón?». No para de hacer experimentos físicos. ¡Está aprendiendo! Revisa una vez más la seguridad de la casa a ras de suelo.', title_fr = 'Petit ingénieur 🤔', body_fr = '« Et si je lance ça ? », « Il sert à quoi, ce bouton ? » Il fait sans arrêt des expériences physiques. Il apprend ! Revérifiez encore une fois la sécurité de la maison au ras du sol.', title_hi = 'नन्हा इंजीनियर 🤔', body_hi = '''इसे फेंकूँ तो क्या होगा?'', ''यह बटन किसलिए है?'' वह लगातार शारीरिक प्रयोग करता है। वह सीख रहा है! फ़र्श के स्तर से घर की सुरक्षा एक बार फिर जाँच लीजिए।', title_id = 'Insinyur kecil 🤔', body_id = '''Kalau ini kulempar, apa yang terjadi?'', ''Tombol ini untuk apa?'' Ia terus melakukan percobaan fisik. Ia sedang belajar! Periksa sekali lagi keamanan rumah dari ketinggian lantai.', title_ja = '小さなエンジニア 🤔', body_ja = '「これを投げたらどうなる？」「このボタンはなんのため？」いつも体を使って実験しています。学んでいるのです！床の高さから、家の安全をもう一度見直しましょう。', title_ko = '꼬마 엔지니어 🤔', body_ko = '''이거 던지면 어떻게 돼?'', ''이 버튼은 뭐야?'' 끊임없이 몸으로 실험하고 있어요. 배우는 중이에요! 바닥 높이에서 집 안의 안전을 다시 한번 살펴보세요.', title_nl = 'Kleine ingenieur 🤔', body_nl = '''Wat gebeurt er als ik dit gooi?'', ''Waar is dit knopje voor?'' Hij doet voortdurend fysieke proefjes. Hij leert! Bekijk de veiligheid van je huis nog eens vanaf vloerhoogte.', title_pl = 'Mały inżynier 🤔', body_pl = '„Co się stanie, jak to rzucę?”, „Do czego jest ten guzik?”. Ciągle przeprowadza fizyczne eksperymenty. On się uczy! Jeszcze raz sprawdź bezpieczeństwo domu z poziomu podłogi.', title_pt = 'Pequeno engenheiro 🤔', body_pt = '"O que acontece se atirar isto?", "Para que serve este botão?" Faz experiências físicas sem parar. Está a aprender! Reveja mais uma vez a segurança da casa ao nível do chão.', title_sv = 'Liten ingenjör 🤔', body_sv = '”Vad händer om jag kastar den här?”, ”Vad är den här knappen till?” Barnet gör ständigt fysiska experiment. Hen lär sig! Gå igenom säkerheten hemma från golvnivå en gång till.', title_vi = 'Kỹ sư nhí 🤔', body_vi = '"Ném cái này thì sao nhỉ?", "Nút này để làm gì?" Bé liên tục làm các thí nghiệm vật lý. Bé đang học hỏi! Hãy kiểm tra lại an toàn trong nhà từ tầm thấp sát sàn một lần nữa.', title_zh = '小小工程师 🤔', body_zh = '“扔了这个会怎样？”“这个按钮是干什么的？”宝宝一直在做各种身体实验。宝宝在学习！再从地面的高度检查一遍家里的安全吧。' WHERE id = '4892459c-b0fb-4a8c-89d7-1bb93e680c5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te fíes de la ventana ⛅', body_es = 'Al salir de paseo, no te dejes engañar por lo que ves por la ventana. Elige con Tiempo y ropa el conjunto más adecuado para el viento y la temperatura reales de fuera y sal de casa tranquila.', title_fr = 'Ne vous fiez pas à la fenêtre ⛅', body_fr = 'Avant la promenade, ne vous laissez pas tromper par la vue depuis la fenêtre. Avec Météo et tenue, choisissez la tenue la mieux adaptée au vent et à la température réels, et sortez sereinement.', title_hi = 'खिड़की पर भरोसा मत कीजिए ⛅', body_hi = 'सैर पर जाते समय सिर्फ़ खिड़की से देखकर धोखा मत खाइए। मौसम और कपड़े असिस्टेंट से बाहर की असली हवा और तापमान के हिसाब से सबसे सही कपड़े चुनिए और आराम से निकलिए।', title_id = 'Jangan percaya jendela ⛅', body_id = 'Saat akan jalan-jalan, jangan tertipu dengan melihat dari jendela. Tentukan setelan yang paling pas untuk angin dan suhu sebenarnya di luar dengan alat Cuaca dan Pakaian, lalu keluarlah dengan tenang.', title_ja = '窓を信じないで ⛅', body_ja = 'お散歩に出かけるとき、窓から見た景色にだまされないで。「天気と服装」で外の実際の風と気温にいちばん合うコーディネートを決めて、安心して出かけましょう。', title_ko = '창밖만 믿지 마세요 ⛅', body_ko = '산책 나갈 때 창밖만 보고 속지 마세요. 날씨와 옷차림 도우미로 실제 바람과 기온에 가장 알맞은 옷차림을 정하고 편하게 나가세요.', title_nl = 'Vertrouw het raam niet ⛅', body_nl = 'Laat je niet misleiden door een blik uit het raam als je gaat wandelen. Kies met Weer en kleding de outfit die het best past bij de echte wind en temperatuur buiten en ga rustig de deur uit.', title_pl = 'Nie ufaj oknu ⛅', body_pl = 'Wychodząc na spacer, nie daj się zwieść widokowi za oknem. Dobierz w narzędziu Pogoda i ubiór zestaw najlepiej pasujący do prawdziwego wiatru i temperatury na zewnątrz i spokojnie wyjdźcie.', title_pt = 'Não confie na janela ⛅', body_pt = 'Quando saírem para passear, não se deixe enganar pelo que vê da janela. Escolha no Tempo e Roupa a combinação mais adequada ao vento e à temperatura reais lá fora e saiam descansados.', title_sv = 'Lita inte på fönstret ⛅', body_sv = 'Låt dig inte luras av att titta ut genom fönstret inför promenaden. Välj den klädsel som passar bäst för den verkliga vinden och temperaturen ute med assistenten Väder och kläder och gå lugnt hemifrån.', title_vi = 'Đừng tin cửa sổ ⛅', body_vi = 'Khi ra ngoài đi dạo, đừng để cảnh bên ngoài cửa sổ đánh lừa. Hãy dùng trợ lý Thời tiết và trang phục để chọn cách phối đồ phù hợp nhất với gió và nhiệt độ thực tế rồi yên tâm ra khỏi nhà.', title_zh = '别相信窗外 ⛅', body_zh = '出门散步时，别被窗外的样子骗了。用天气穿衣助手找到最适合外面实际风力和温度的搭配，安心出门。' WHERE id = 'dc8c6058-0791-46ab-b5d1-2637ff0b924e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La salvación del súper 🛒', body_es = '¿Siempre se te olvida lo más importante al ir al súper? La Lista de la compra te espera en la app. Apunta ahí lo que falta y que tu pareja lo compre sin fallo al volver del trabajo.', title_fr = 'Le sauveur des courses 🛒', body_fr = 'Vous oubliez toujours l''article le plus important au supermarché ? La Liste de courses vous attend dans l''application. Notez-y vos besoins, votre partenaire fera les courses avec précision en rentrant du travail.', title_hi = 'बाज़ार की मददगार 🛒', body_hi = 'बाज़ार जाते समय सबसे ज़रूरी चीज़ ज़रूर भूल जाती हैं? ऐप में शॉपिंग लिस्ट आपका इंतज़ार कर रही है। ज़रूरतें वहाँ लिखिए, ताकि आपके पार्टनर काम से लौटते समय सब कुछ ठीक-ठीक ले आएँ।', title_id = 'Penyelamat saat belanja 🛒', body_id = 'Selalu lupa barang paling penting saat belanja? Daftar Belanja menunggu Anda di aplikasi. Catat kebutuhan di sana, biar pasangan membelinya dengan tepat saat pulang kerja.', title_ja = 'スーパーの救世主 🛒', body_ja = '買い物に行くと、いちばん大事なものを必ず忘れてしまう？アプリの「買い物リスト」が待っています。必要なものをそこに書いて、パートナーに仕事帰りにきちんと買ってきてもらいましょう。', title_ko = '장보기의 구세주 🛒', body_ko = '마트에 가면 꼭 가장 중요한 걸 잊어버리나요? 앱의 쇼핑 목록이 기다리고 있어요. 필요한 걸 적어 두면 배우자가 퇴근길에 정확히 사 올 수 있어요.', title_nl = 'Redder in de supermarkt 🛒', body_nl = 'Vergeet je in de supermarkt altijd net het belangrijkste? Het Boodschappenlijstje wacht op je in de app. Zet erop wat je nodig hebt, dan haalt je partner het precies op weg terug van zijn werk.', title_pl = 'Wybawca w sklepie 🛒', body_pl = 'Idąc do sklepu, zawsze zapominasz o najważniejszej rzeczy? Lista zakupów czeka na ciebie w aplikacji. Zapisz tam potrzeby, a partner wracając z pracy, kupi wszystko co do joty.', title_pt = 'A salvação no supermercado 🛒', body_pt = 'Esquece-se sempre da coisa mais importante no supermercado? A Lista de Compras espera por si na app. Aponte lá o que falta e o seu companheiro compra tudo certinho ao voltar do trabalho.', title_sv = 'Inköpsräddaren 🛒', body_sv = 'Glömmer du alltid det viktigaste när du går och handlar? Inköpslistan väntar på dig i appen. Skriv in behoven där så kan din partner handla exakt det som behövs på vägen hem från jobbet.', title_vi = 'Cứu tinh khi đi siêu thị 🛒', body_vi = 'Đi siêu thị lần nào mẹ cũng quên đúng món quan trọng nhất? Danh sách mua sắm đang chờ mẹ trong ứng dụng. Hãy ghi những thứ cần mua vào đó để chồng mua đủ trên đường đi làm về.', title_zh = '超市救星 🛒', body_zh = '去超市总会忘掉最重要的东西？购物清单就在应用里等着你。把需要的东西记进去，让另一半下班回家时准确采购。' WHERE id = '7325d8d6-eeac-417b-abca-d32163dd16b4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de agua 🛀', body_es = 'Después de correr todo el día, estáis agotados los dos. Durante el baño templado, pon de fondo sonidos relajantes de la naturaleza. La armonía del agua preparará para dormir hasta al niño más tozudo.', title_fr = 'Thérapie par l''eau 🛀', body_fr = 'Après avoir couru toute la journée, vous êtes épuisés tous les deux. Pendant le bain tiède, mettez des sons de la nature apaisants en fond. L''harmonie de l''eau préparera au sommeil même l''enfant le plus têtu.', title_hi = 'पानी से थेरेपी 🛀', body_hi = 'दिनभर भागदौड़ से वह भी थक गया और आप भी। गुनगुने पानी से नहलाते समय पीछे प्रकृति की शांत आवाज़ें चलाइए। पानी का यह सुकून सबसे ज़िद्दी बच्चे को भी नींद के लिए तैयार कर देगा।', title_id = 'Terapi air 🛀', body_id = 'Seharian berlarian, ia dan Anda sama-sama kelelahan. Saat mandi air hangat, putar suara alam yang menenangkan di latar belakang. Harmoni air akan menyiapkan anak yang paling keras kepala sekalipun untuk tidur.', title_ja = 'お水のセラピー 🛀', body_ja = '一日じゅう走り回って、ふたりともへとへと。ぬるめのお風呂に入るとき、後ろで落ち着く自然の音を流しましょう。お水のハーモニーが、どんなにがんこな子も眠りへ導きます。', title_ko = '물 테라피 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤죠. 따뜻한 목욕을 할 때 잔잔한 자연의 소리를 틀어 주세요. 물의 조화가 가장 고집스러운 아이도 잠들 준비를 하게 해 줄 거예요.', title_nl = 'Watertherapie 🛀', body_nl = 'Jullie zijn allebei op van een hele dag rennen. Zet tijdens het lauwe bad rustgevende natuurgeluiden op de achtergrond aan. De harmonie van water maakt zelfs het koppigste kind klaar voor de slaap.', title_pl = 'Terapia wodą 🛀', body_pl = 'Po całym dniu biegania oboje jesteście wykończeni. Podczas ciepłej kąpieli włącz w tle kojące odgłosy natury. Harmonia wody przygotuje do snu nawet najbardziej upartego malucha.', title_pt = 'Terapia da água 🛀', body_pt = 'Depois de correrem o dia todo, estão os dois esgotados. Durante o banho morno, ponha sons calmantes da natureza em fundo. A harmonia da água vai preparar para o sono até a criança mais teimosa.', title_sv = 'Vattenterapi 🛀', body_sv = 'Både du och barnet är helt slut efter en hel dag i farten. Sätt på lugnande naturljud i bakgrunden under det ljumma badet. Vattnets harmoni förbereder även det envisaste barnet för sömn.', title_vi = 'Liệu pháp nước 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều kiệt sức. Khi bé tắm nước ấm, hãy bật âm thanh thiên nhiên êm dịu phía sau. Sự hòa quyện của nước sẽ giúp cả đứa trẻ bướng bỉnh nhất sẵn sàng đi ngủ.', title_zh = '水的疗愈 🛀', body_zh = '跑了一整天，宝宝和你都累坏了。洗温水澡时，在背景里放些舒缓的大自然声音。水的和谐连最倔的孩子都能带入睡眠准备。' WHERE id = 'd7e75209-c901-4086-8f01-b71b4374f127' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Un «no» rotundo! 🛑', body_es = '¿Se aparta y dice «no» con firmeza cuando alguien quiere darle un beso? Respeta los límites de su cuerpo. Que proteste ante el contacto sin permiso es clave para su salud psicológica.', title_fr = 'Un « Non ! » catégorique 🛑', body_fr = 'Quand quelqu''un veut l''embrasser, il recule et dit « non » fermement ? Respectez les limites de son corps. Pouvoir refuser les contacts non désirés est essentiel pour son équilibre psychologique.', title_hi = 'पक्की ''ना''! 🛑', body_hi = 'कोई उसे चूमना चाहे तो दूर हट जाता है और सख्ती से ''ना'' कहता है? उसके शरीर की सीमाओं का सम्मान कीजिए। बिना इजाज़त छूने का विरोध करना उसके स्वस्थ मन के लिए ज़रूरी है।', title_id = '''Tidak!'' yang tegas 🛑', body_id = 'Saat seseorang ingin menciumnya, ia menjauh dan tegas berkata tidak? Hormati batas tubuhnya. Keberaniannya menolak sentuhan tanpa izin penting bagi kesehatan jiwanya.', title_ja = 'きっぱり「いや！」🛑', body_ja = 'だれかにキスされそうになると離れて、きっぱり「いや」と言いますか？体の境界線を尊重しましょう。許可のないふれあいを拒めることは、健やかな心のために欠かせません。', title_ko = '단호한 ''아니야!'' 🛑', body_ko = '누가 뽀뽀하려고 하면 피하며 단호하게 ''아니야''라고 하나요? 아이의 몸의 경계를 존중해 주세요. 허락 없는 접촉에 거부할 줄 아는 건 건강한 마음에 꼭 필요해요.', title_nl = 'Een vastberaden ''Nee!'' 🛑', body_nl = 'Trekt hij zich terug en zegt hij stellig ''nee'' als iemand hem wil zoenen? Respecteer zijn lichamelijke grenzen. Protesteren tegen aanrakingen zonder toestemming is nodig voor zijn gezonde psyche.', title_pl = 'Stanowcze „Nie!” 🛑', body_pl = 'Gdy ktoś chce go pocałować, odsuwa się i stanowczo mówi „nie”? Szanuj granice jego ciała. Sprzeciw wobec dotyku bez zgody jest niezbędny dla jego zdrowej psychiki.', title_pt = 'Um "Não!" firme 🛑', body_pt = 'Quando alguém o quer beijar, afasta-se e diz "não" com firmeza? Respeite os limites do corpo dele. Protestar contra toques sem autorização é essencial para a sua saúde psicológica.', title_sv = 'Bestämt nej! 🛑', body_sv = 'Drar sig barnet undan och säger bestämt nej när någon vill pussa hen? Respektera barnets kroppsliga gränser. Att hen säger ifrån mot beröring utan lov är avgörande för en sund psykisk hälsa.', title_vi = '"Không!" dứt khoát 🛑', body_vi = 'Khi có ai muốn hôn, bé né ra và dứt khoát nói "không"? Hãy tôn trọng ranh giới cơ thể của bé. Việc bé phản đối những đụng chạm không được cho phép là điều kiện cho tâm lý khỏe mạnh của bé.', title_zh = '坚决的“不要！” 🛑', body_zh = '有人想亲宝宝时，宝宝躲开还坚决说“不要”？要尊重宝宝的身体界限。宝宝会拒绝未经允许的触碰，这对健康的心理至关重要。' WHERE id = 'f55edde1-4803-4d20-96d6-d40197fda19c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche deja descansar tus cuerdas vocales. Que papá se encargue de leer los libros favoritos de tu peque con voces distintas, inventadas y graciosas.', body_fr = 'Ce soir, reposez vos cordes vocales. Laissez papa lire les livres préférés de l''enfant en changeant de voix, en inventant et en faisant le clown.', body_hi = 'आज शाम अपनी आवाज़ को आराम दीजिए। बच्चे की सबसे पसंदीदा किताबें अलग-अलग आवाज़ों में, अपनी ओर से जोड़कर मज़ेदार ढंग से पढ़ने का काम पापा को करने दीजिए।', body_id = 'Malam ini istirahatkan pita suara Anda. Biar Ayah yang membacakan buku favorit anak dengan berbagai nada suara, sambil mengarang dan melucu.', body_ja = '今夜はあなたの声を休ませましょう。お子さんのいちばん好きな絵本を、いろいろな声色でアドリブを入れておもしろく読む役目は、パパにお任せして。', body_ko = '오늘 저녁엔 목을 쉬게 하세요. 아이가 가장 좋아하는 책을 여러 목소리로 재미있게 지어내며 읽어 주는 일은 아빠에게 맡기세요.', body_nl = 'Laat je stembanden vanavond rusten. Laat papa zijn lievelingsboeken voorlezen, met andere stemmetjes, zelfverzonnen en grappig.', body_pl = 'Daj dziś odpocząć strunom głosowym. Niech to tata przeczyta ulubione książki dziecka różnymi głosami, z wymyślonymi, zabawnymi dodatkami.', body_pt = 'Esta noite, descanse as cordas vocais. Deixe o pai ler os livros preferidos da criança com vozes diferentes, de forma inventada e cómica.', body_sv = 'Vila stämbanden i kväll. Låt pappa läsa barnets favoritböcker med olika röster, på ett påhittat och roligt sätt.', body_vi = 'Tối nay hãy cho dây thanh quản được nghỉ ngơi. Hãy để bố đảm nhận việc đọc những cuốn sách bé yêu thích bằng nhiều giọng khác nhau, theo cách tự chế và hài hước.', body_zh = '今晚让你的嗓子休息一下。把用各种语调、即兴搞笑地读孩子最爱的书这项任务，交给爸爸吧。' WHERE id = 'a279684f-8916-4183-8bdf-0b058193de01' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Propiedad privada 🧸', body_es = '¿No le deja sus juguetes al niño que viene de visita? No es egoísmo, es proteger sus límites personales. Enséñale a compartir con el ejemplo, no obligándole.', title_fr = 'Propriété privée 🧸', body_fr = 'Il ne prête pas son jouet à l''enfant venu en visite ? Ce n''est pas de l''égoïsme, il protège ses limites personnelles. Apprenez-lui le partage par l''exemple, pas par la contrainte.', title_hi = 'निजी संपत्ति 🧸', body_hi = 'घर आए मेहमान बच्चे को अपना खिलौना नहीं देता? यह स्वार्थ नहीं, अपनी निजी सीमाओं की रक्षा है। बाँटना ज़बरदस्ती से नहीं, बस खुद उदाहरण बनकर सिखाइए।', title_id = 'Milik pribadi 🧸', body_id = 'Ia tidak mau meminjamkan mainannya kepada anak tamu? Ini bukan egois, ia sedang menjaga batas pribadinya. Ajarkan berbagi bukan dengan paksaan, tetapi cukup dengan memberi contoh.', title_ja = '自分のもの 🧸', body_ja = '遊びに来たお友だちに、自分のおもちゃを渡さない？これはわがままではなく、自分の境界線を守っているのです。分け合うことは無理強いではなく、お手本を見せて教えましょう。', title_ko = '내 물건 🧸', body_ko = '놀러 온 친구에게 장난감을 안 빌려주나요? 이기심이 아니라 자기 경계를 지키는 거예요. 나눔은 억지로가 아니라 엄마가 본보기를 보여 주며 가르쳐 주세요.', title_nl = 'Persoonlijk bezit 🧸', body_nl = 'Geeft hij zijn speelgoed niet aan een kindje dat op bezoek komt? Dat is geen egoïsme, maar zijn persoonlijke grenzen bewaken. Leer delen niet door te dwingen, maar door zelf het voorbeeld te geven.', title_pl = 'Własność osobista 🧸', body_pl = 'Nie daje swojej zabawki dziecku, które przyszło w gości? To nie egoizm, tylko ochrona osobistych granic. Ucz dzielenia się nie przymusem, ale własnym przykładem.', title_pt = 'Propriedade privada 🧸', body_pt = 'Não empresta o brinquedo à criança que vem de visita? Não é egoísmo, é proteger os seus limites pessoais. Ensine a partilhar não à força, mas pelo seu exemplo.', title_sv = 'Personlig ägodel 🧸', body_sv = 'Vill barnet inte låna ut sin leksak till ett gästande barn? Det är inte egoism, det är att skydda sina personliga gränser. Lär ut att dela genom att vara ett exempel, inte genom tvång.', title_vi = 'Đồ của riêng con 🧸', body_vi = 'Bé không cho bạn nhỏ đến chơi mượn đồ chơi? Đây không phải ích kỷ mà là bé đang bảo vệ ranh giới cá nhân. Hãy dạy chia sẻ bằng cách làm gương, đừng ép buộc.', title_zh = '个人财产 🧸', body_zh = '不肯把自己的玩具给来家里做客的小朋友？这不是自私，而是在守护自己的界限。别强迫分享，用自己的榜样去教就好。' WHERE id = 'acb821ae-037d-451e-905f-fae976b254b3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La barrita energética de mamá 🥑', body_es = 'Con el ajetreo diario, no comas de pie. Elige un tentempié energético en Recetas saludables y, aunque sea 10 minutos, túmbate en el sofá y pon tu alimentación en primer plano.', title_fr = 'La barre énergétique de maman 🥑', body_fr = 'Dans la course du quotidien, ne déjeunez pas debout. Choisissez une collation énergisante dans les Recettes saines et pensez à votre propre alimentation en vous allongeant au moins 10 minutes sur le canapé.', title_hi = 'माँ का एनर्जी बार 🥑', body_hi = 'रोज़ की भागदौड़ में खड़े-खड़े लंच मत कीजिए। सेहतमंद रेसिपी से ऊर्जा देने वाला स्नैक चुनिए और कम से कम 10 मिनट सोफ़े पर आराम करते हुए अपने खाने को प्राथमिकता दीजिए।', title_id = 'Camilan energi Ibu 🥑', body_id = 'Di tengah kesibukan, jangan makan siang sambil berdiri. Pilih camilan berenergi dari Resep Sehat, dan setidaknya berbaringlah 10 menit di sofa dengan mengutamakan asupan Anda sendiri.', title_ja = 'ママのエナジーバー 🥑', body_ja = '毎日のバタバタで、ランチを立ったまま済ませないで。「ヘルシーレシピ」から元気の出るおやつを選び、せめて10分はソファに横になって、自分の栄養を大切にしましょう。', title_ko = '엄마의 에너지 바 🥑', body_ko = '바쁜 하루 속에서 점심을 서서 때우지 마세요. 건강한 레시피에서 힘이 나는 간식을 고르고, 단 10분이라도 소파에 누워 나의 식사를 먼저 챙기세요.', title_nl = 'Energiereep voor mama 🥑', body_nl = 'Eet in de dagelijkse drukte je lunch niet staand. Kies een energierijk tussendoortje uit Gezonde recepten en zet je eigen voeding op de eerste plaats, al is het maar 10 minuten liggend op de bank.', title_pl = 'Batonik energetyczny mamy 🥑', body_pl = 'W codziennej bieganinie nie jedz obiadu na stojąco. Wybierz ze Zdrowych przepisów energetyczną przekąskę i choć przez 10 minut leżąc na kanapie, postaw swoje odżywianie na pierwszym miejscu.', title_pt = 'A barra energética da mãe 🥑', body_pt = 'Na correria do dia, não almoce de pé. Escolha nas Receitas Saudáveis um snack energético e deite-se pelo menos 10 minutos no sofá, pondo a sua alimentação em primeiro lugar.', title_sv = 'Mammas energibar 🥑', body_sv = 'Ät inte lunchen stående i vardagsstressen. Välj ett energirikt mellanmål från Hälsosamma recept och sätt din egen kost i första rummet, ligg åtminstone 10 minuter på soffan.', title_vi = 'Thanh năng lượng của mẹ 🥑', body_vi = 'Đừng ăn trưa vội vàng giữa nhịp sống tất bật. Hãy chọn một món ăn nhẹ giàu năng lượng từ Công thức lành mạnh và ưu tiên dinh dưỡng của mình, ít nhất nằm nghỉ trên sofa 10 phút.', title_zh = '妈妈的能量棒 🥑', body_zh = '每天忙忙碌碌，别站着解决午饭。从健康食谱里选一份充满能量的小零食，至少在沙发上躺10分钟，把自己的饮食放在首位。' WHERE id = 'ee52c904-b97d-4a34-b7fb-b60ab86aadcd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maratón de pilla-pilla 🏃‍♂️', body_es = 'Ya no le basta con caminar: cuando le llamas, sale corriendo y se esconde. Quita los obstáculos peligrosos de la habitación y únete tú también a este divertido pilla-pilla.', title_fr = 'Marathon du chat et de la souris 🏃‍♂️', body_fr = 'Marcher ne lui suffit plus : quand vous l''appelez, il court vite se cacher. Retirez les obstacles dangereux de la pièce et jouez, vous aussi, à ce joyeux jeu du chat et de la souris.', title_hi = 'पकड़म-पकड़ाई की मैराथन 🏃‍♂️', body_hi = 'अब सिर्फ़ चलने से उसका मन नहीं भरता, आप बुलाती हैं तो तेज़ी से दौड़कर छिप जाता है। कमरे से खतरनाक रुकावटें हटाइए और इस मज़ेदार पकड़म-पकड़ाई में आप भी शामिल हो जाइए।', title_id = 'Maraton kejar-kejaran 🏃‍♂️', body_id = 'Ia tidak lagi puas hanya berjalan, saat Anda memanggilnya ia berlari cepat dan bersembunyi. Singkirkan rintangan berbahaya di kamar dan ikutlah bermain kejar-kejaran yang seru ini.', title_ja = '追いかけっこマラソン 🏃‍♂️', body_ja = 'もう歩くだけでは満足せず、呼ぶとさっと走って隠れます。部屋の危ないものを片づけて、あなたもこの楽しい追いかけっこに加わりましょう。', title_ko = '술래잡기 마라톤 🏃‍♂️', body_ko = '이제 걷는 걸로는 부족해서 엄마가 부르면 빠르게 달려가 숨나요? 방의 위험한 장애물을 치우고 엄마도 이 즐거운 술래잡기에 함께해 보세요.', title_nl = 'Tikkertjesmarathon 🏃‍♂️', body_nl = 'Lopen is niet meer genoeg: als je hem roept, rent hij razendsnel weg en verstopt hij zich. Ruim gevaarlijke obstakels in de kamer op en doe mee met dit vrolijke tikkertje.', title_pl = 'Maraton w berka 🏃‍♂️', body_pl = 'Nie wystarcza mu już chodzenie, gdy go wołasz, szybko ucieka i się chowa. Usuń z pokoju niebezpieczne przeszkody i dołącz do tej wesołej zabawy w berka.', title_pt = 'Maratona da apanhada 🏃‍♂️', body_pt = 'Já não se contenta em andar: quando o chama, corre depressa e esconde-se. Retire os obstáculos perigosos do quarto e entre também nesta brincadeira alegre da apanhada.', title_sv = 'Tafattmaraton 🏃‍♂️', body_sv = 'Barnet nöjer sig inte längre med att gå, när du ropar springer hen snabbt iväg och gömmer sig. Plocka bort farliga hinder i rummet och var med i den glada tafattleken du också.', title_vi = 'Cuộc đua đuổi bắt 🏃‍♂️', body_vi = 'Không chỉ đi bộ, khi mẹ gọi bé còn chạy thật nhanh để trốn. Hãy dọn những vật cản nguy hiểm trong phòng và cùng tham gia trò đuổi bắt vui nhộn này nhé.', title_zh = '你追我跑马拉松 🏃‍♂️', body_zh = '已经不满足于走路，你一叫就飞快地跑去躲起来。收起房间里危险的障碍物，你也加入这场欢乐的“你追我跑”吧。' WHERE id = '51decf20-cf70-4c72-beb9-3712b300a999' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubre la psicología 📱', body_es = '¿Te agota que diga «no» a todo? Lee los artículos de psicología del Blog de la app y entiende las causas profundas de esta tormenta de desarrollo que vive su cerebro.', title_fr = 'Découvrez la psychologie 📱', body_fr = 'Ses « non » à tout vous épuisent ? Lisez les blogs de psychologie de l''application pour comprendre les raisons profondes de cette tempête de développement dans son cerveau.', title_hi = 'मनोविज्ञान को जानिए 📱', body_hi = 'बच्चे का हर बात पर ''नहीं'' कहना आपको थका रहा है? ऐप के मनोविज्ञान वाले ब्लॉग पढ़कर उसके दिमाग में चल रहे इस विकास के तूफ़ान की गहरी वजहें समझिए।', title_id = 'Kenali psikologinya 📱', body_id = 'Kata ''tidak'' untuk segala hal membuat Anda lelah? Baca blog psikologi di aplikasi untuk memahami penyebab mendalam badai perkembangan yang terjadi di otaknya.', title_ja = '心理学を知ろう 📱', body_ja = '何にでも「いや」と言われて疲れていませんか？アプリの心理ブログを読んで、頭の中で起きているこの発達の嵐の深い理由を理解しましょう。', title_ko = '아이의 마음을 알아보세요 📱', body_ko = '뭐든 ''싫어''라고 해서 지쳤나요? 앱의 심리 블로그를 읽고 아이 머릿속에서 일어나는 발달의 폭풍이 생기는 깊은 이유를 이해해 보세요.', title_nl = 'Ontdek de psychologie 📱', body_nl = 'Word je moe van zijn eeuwige ''nee''? Lees de psychologische blogs in de app en begrijp de diepere oorzaken van deze ontwikkelingsstorm in zijn hoofdje.', title_pl = 'Odkryj psychologię 📱', body_pl = 'Męczy cię, że na wszystko mówi „nie”? Przeczytaj artykuły psychologiczne na Blogu w aplikacji i zrozum głębokie przyczyny tej rozwojowej burzy w jego głowie.', title_pt = 'Descubra a psicologia 📱', body_pt = 'Está cansada de ouvir "não" a tudo? Leia os artigos de psicologia no blogue da app e perceba as causas profundas desta tempestade de desenvolvimento no cérebro dele.', title_sv = 'Upptäck psykologin 📱', body_sv = 'Är du trött på att barnet säger nej till allt? Läs psykologibloggarna i appen och förstå de djupare orsakerna till utvecklingsstormen i barnets hjärna.', title_vi = 'Khám phá tâm lý 📱', body_vi = 'Bé nói "không" với mọi thứ khiến mẹ mệt mỏi? Hãy đọc các bài blog tâm lý trong ứng dụng để hiểu những nguyên nhân sâu xa của "cơn bão phát triển" đang diễn ra trong não bé.', title_zh = '探索心理学 📱', body_zh = '孩子什么都说“不”，让你心累？读读应用里的心理博客，了解宝宝大脑里这场成长风暴背后的深层原因。' WHERE id = 'aff77c93-ed92-44bc-9afd-e64eb6ce5292' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la oscuridad 🌙', body_es = 'Para que se duerma antes, apaga todas las luces extra de la habitación y las pantallas de las tablets. La melatonina solo se produce rápido en un ambiente oscuro y sin tecnología.', title_fr = 'Le pouvoir du noir 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre. La mélatonine n''est sécrétée rapidement que dans le noir, sans technologie.', title_hi = 'अंधेरे की ताकत 🌙', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ अंधेरे और बिना गैजेट वाले माहौल में तेज़ी से बनता है।', title_id = 'Kekuatan gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar. Melatonin hanya diproduksi dengan cepat dalam suasana gelap dan bebas teknologi.', title_ja = '暗やみの力 🌙', body_ja = '早く寝つけるように、部屋の余分な明かりとタブレットの画面をすべて消しましょう。メラトニンは、暗くて機器のない環境でこそすばやく分泌されます。', title_ko = '어둠의 힘 🌙', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명과 태블릿 화면을 모두 꺼 주세요. 멜라토닌은 어둡고 전자기기 없는 환경에서만 빠르게 분비돼요.', title_nl = 'De kracht van het donker 🌙', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en tabletschermen in de kamer uit. Melatonine wordt alleen in een donkere omgeving zonder techniek snel aangemaakt.', title_pl = 'Moc ciemności 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina wydziela się szybko tylko w ciemnym otoczeniu bez technologii.', title_pt = 'O poder do escuro 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets. A melatonina só é produzida rapidamente num ambiente escuro e sem tecnologia.', title_sv = 'Mörkrets kraft 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplattornas skärmar i rummet. Melatonin utsöndras snabbt bara i en mörk miljö utan teknik.', title_vi = 'Sức mạnh của bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng. Melatonin chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ.', title_zh = '黑暗的力量 🌙', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光和平板屏幕。褪黑素只有在昏暗、没有电子设备的环境里才会快速分泌。' WHERE id = 'e18b761a-6fd6-438d-896c-ec7bd458b9c2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Director en acción 🎭', body_es = '¿Mira los personajes del libro de dibujos y cuenta historias totalmente inventadas por él? ¡Su imaginación está en su punto álgido! Escucha con orgullo sus historias tan originales sin interrumpirle.', title_fr = 'Le metteur en scène au travail 🎭', body_fr = 'Il regarde les personnages d''un livre d''images et raconte des événements totalement inventés ? Son imagination est à son sommet ! Écoutez fièrement ses histoires extraordinaires sans l''interrompre.', title_hi = 'निर्देशक काम पर 🎭', body_hi = 'तस्वीरों वाली किताब के किरदारों को देखकर पूरी तरह अपनी गढ़ी हुई घटनाएँ सुनाता है? कल्पना का विकास शिखर पर है! उसकी इन अनोखी कहानियों को बिना टोके, गर्व से सुनिए।', title_id = 'Sutradara sedang bekerja 🎭', body_id = 'Sambil melihat tokoh di buku bergambar, ia menceritakan kejadian yang sepenuhnya karangannya sendiri? Imajinasinya sedang di puncak! Dengarkan kisah-kisahnya yang luar biasa ini dengan bangga tanpa memotongnya.', title_ja = '監督さん、撮影中 🎭', body_ja = '絵本のキャラクターを見ながら、まったく自分で考えたお話を語っていますか？想像力の発達が最高潮です！この風変わりなお話をさえぎらず、誇らしく聞いてあげましょう。', title_ko = '꼬마 감독 작업 중 🎭', body_ko = '그림책 속 등장인물을 보며 완전히 자기가 지어낸 이야기를 들려주나요? 상상력 발달이 절정이에요! 이 특별한 이야기를 끊지 말고 뿌듯하게 들어 주세요.', title_nl = 'Regisseur aan het werk 🎭', body_nl = 'Vertelt hij bij de figuren in een prentenboek helemaal zelfverzonnen verhalen? Zijn fantasie is op zijn hoogtepunt! Luister trots naar zijn bijzondere verhalen zonder hem te onderbreken.', title_pl = 'Reżyser w akcji 🎭', body_pl = 'Patrząc na postacie w książeczce z obrazkami, opowiada zupełnie zmyślone przez siebie wydarzenia? Wyobraźnia jest u szczytu! Słuchaj z dumą tych niezwykłych historii, nie przerywając mu.', title_pt = 'Realizador ao trabalho 🎭', body_pt = 'Olha para as personagens de um livro de imagens e narra acontecimentos totalmente inventados por ele? A imaginação está no auge! Ouça com orgulho estas histórias fora do comum, sem o interromper.', title_sv = 'Regissören i tjänst 🎭', body_sv = 'Tittar barnet på figurerna i bilderboken och berättar helt egna påhittade händelser? Fantasiutvecklingen är på topp! Lyssna stolt på de ovanliga berättelserna utan att avbryta.', title_vi = 'Đạo diễn đang làm việc 🎭', body_vi = 'Nhìn nhân vật trong sách tranh, bé kể lại những câu chuyện hoàn toàn do mình nghĩ ra? Trí tưởng tượng đang ở đỉnh cao! Hãy tự hào lắng nghe những câu chuyện khác thường này mà không ngắt lời bé.', title_zh = '小导演上班了 🎭', body_zh = '看着图画书里的角色，讲出完全自己编的情节？想象力发展到了顶峰！别打断这些不寻常的故事，骄傲地听下去吧。' WHERE id = '5a4437a7-7519-4a4e-9c66-e797d5e763f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té caliente y calma 🍵', body_es = 'Olvida las tareas de casa, todo puede esperar. Prepárate una infusión de melisa de Recetas saludables y disfruta de estar a solas contigo misma.', title_fr = 'Thé chaud et sérénité 🍵', body_fr = 'Oubliez les tâches ménagères, tout peut attendre. Infusez une tisane de mélisse des Recettes saines et savourez simplement un moment seule avec vous-même.', title_hi = 'गर्म चाय और सुकून 🍵', body_hi = 'घर के काम भूल जाइए, सब कुछ इंतज़ार कर सकता है। सेहतमंद रेसिपी से लेमन बाम (मेलिसा) की चाय बनाइए और बस खुद के साथ रहने का आनंद लीजिए।', title_id = 'Teh hangat dan ketenangan 🍵', body_id = 'Lupakan pekerjaan rumah, semuanya bisa menunggu. Seduh teh melissa dari Resep Sehat dan nikmati waktu sendiri bersama diri Anda.', title_ja = '温かいお茶と静けさ 🍵', body_ja = '家事は忘れましょう、すべて後回しで大丈夫。「ヘルシーレシピ」からレモンバームティーをいれて、自分だけの時間を味わいましょう。', title_ko = '따뜻한 차와 고요 🍵', body_ko = '집안일은 잊으세요. 모든 건 기다릴 수 있어요. 건강한 레시피에서 레몬밤 차를 우려 오롯이 나만의 시간을 즐기세요.', title_nl = 'Warme thee en rust 🍵', body_nl = 'Vergeet het huishouden, alles kan wachten. Zet citroenmelissethee uit Gezonde recepten en geniet ervan om even alleen met jezelf te zijn.', title_pl = 'Ciepła herbata i spokój 🍵', body_pl = 'Zapomnij o obowiązkach, wszystko może poczekać. Zaparz herbatę z melisy ze Zdrowych przepisów i delektuj się chwilą tylko dla siebie.', title_pt = 'Chá quente e sossego 🍵', body_pt = 'Esqueça as tarefas de casa, tudo pode esperar. Prepare um chá de erva-cidreira das Receitas Saudáveis e saboreie o tempo a sós consigo mesma.', title_sv = 'Varmt te och lugn 🍵', body_sv = 'Glöm hushållet, allt kan vänta. Brygg ett citronmelissate från Hälsosamma recept och njut av att bara vara med dig själv.', title_vi = 'Trà ấm và bình yên 🍵', body_vi = 'Quên việc nhà đi, mọi thứ đều có thể chờ. Hãy pha trà tía tô đất từ Công thức lành mạnh và tận hưởng khoảng thời gian chỉ có riêng mình.', title_zh = '热茶与安静 🍵', body_zh = '忘掉家务吧，什么都可以等。从健康食谱里泡一杯蜜蜂花茶，好好享受和自己独处的时光。' WHERE id = '932de885-b10a-4cc0-af8a-8db540c3d060' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de parque 🌳', body_es = 'Las cuatro paredes te agobian. Aunque haga fresco, abrígale bien y salid 20 minutos al parque. Que descubra hojas y piedras; el aire fresco le llevará oxígeno al cerebro.', title_fr = 'Parc-thérapie 🌳', body_fr = 'Les quatre murs vous étouffent. Même s''il fait frais, couvrez-le bien et sortez 20 minutes au parc. Qu''il explore les feuilles et les cailloux, l''air frais apportera de l''oxygène à son cerveau.', title_hi = 'पार्क थेरेपी 🌳', body_hi = 'चार दीवारें घुटन दे रही हैं। मौसम ठंडा हो तब भी उसे अच्छे से कपड़े पहनाकर 20 मिनट के लिए पार्क ले जाइए। उसे पत्ते और पत्थर खोजने दीजिए, ताज़ी हवा उसके दिमाग तक ऑक्सीजन पहुँचाएगी।', title_id = 'Terapi taman 🌳', body_id = 'Empat dinding rumah terasa menyesakkan. Meski udara sejuk, pakaikan ia baju hangat dan ajak ke taman selama 20 menit. Biarkan ia menjelajahi daun dan batu, udara segar akan membawa oksigen ke otaknya.', title_ja = '公園セラピー 🌳', body_ja = '家にこもって息がつまりそう？少し肌寒くても、しっかり着こませて20分ほど公園へ出かけましょう。葉っぱや石を探検させて。新鮮な空気が脳に酸素を届けてくれます。', title_ko = '공원 테라피 🌳', body_ko = '네 벽에 갇힌 듯 답답하죠. 날씨가 쌀쌀해도 따뜻하게 입혀 20분 동안 공원에 나가 보세요. 나뭇잎과 돌멩이를 탐험하게 하면 맑은 공기가 뇌에 산소를 실어다 줄 거예요.', title_nl = 'Parktherapie 🌳', body_nl = 'Kruipen de muren op je af? Ook als het fris is: kleed hem warm aan en ga 20 minuten naar het park. Laat hem bladeren en steentjes ontdekken, de frisse lucht brengt zuurstof naar zijn hersenen.', title_pl = 'Terapia w parku 🌳', body_pl = 'Cztery ściany cię przytłaczają. Nawet jeśli jest chłodno, ubierz go ciepło i wyjdźcie na 20 minut do parku. Niech odkrywa liście i kamyki, świeże powietrze dotleni jego mózg.', title_pt = 'Terapia de parque 🌳', body_pt = 'As quatro paredes sufocam-na. Mesmo que esteja fresco, agasalhe-o bem e vão 20 minutos ao parque. Deixe-o explorar folhas e pedras: o ar puro vai levar oxigénio ao cérebro dele.', title_sv = 'Parkterapi 🌳', body_sv = 'De fyra väggarna kväver dig. Även om det är svalt, klä barnet ordentligt och gå till parken i 20 minuter. Låt hen upptäcka löv och stenar, den friska luften ger hjärnan syre.', title_vi = 'Liệu pháp công viên 🌳', body_vi = 'Bốn bức tường như ngột ngạt. Dù trời se lạnh, hãy mặc ấm cho bé và ra công viên 20 phút. Để bé khám phá lá cây, sỏi đá, không khí trong lành sẽ mang oxy đến não bé.', title_zh = '公园疗法 🌳', body_zh = '四面墙让人透不过气。就算天气凉，也给宝宝穿暖和，去公园走20分钟。让宝宝探索树叶和石头，新鲜空气会把氧气送进宝宝的大脑。' WHERE id = 'ba3e9de9-b98f-4d3a-93a0-ef5b3f06f424' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Arte en el plato 🥦', body_es = '¿No se come la comida? A veces el problema no es el sabor, sino el aspecto. Haz caras graciosas con verduras de colores para abrirle el apetito y convertir la comida en un juego.', title_fr = 'De l''art dans l''assiette 🥦', body_fr = 'Il ne mange pas ? Parfois, le problème n''est pas le goût mais l''aspect. Créez des visages rigolos avec des légumes colorés pour lui ouvrir l''appétit et transformer le repas en jeu.', title_hi = 'थाली में कला 🥦', body_hi = 'वह खाना नहीं खाता? कभी-कभी दिक्कत स्वाद में नहीं, दिखावट में होती है। रंग-बिरंगी सब्ज़ियों से मज़ेदार चेहरे बनाकर उसकी भूख जगाने और खाने को खेल बनाने की कोशिश कीजिए।', title_id = 'Seni di atas piring 🥦', body_id = 'Ia tidak mau makan? Kadang masalahnya bukan rasa, tetapi tampilan. Buat wajah-wajah lucu dari sayuran warna-warni untuk membangkitkan selera makannya dan menjadikan makan sebuah permainan.', title_ja = 'お皿の上のアート 🥦', body_ja = 'ごはんを食べない？問題は味ではなく、見た目のこともあります。カラフルな野菜でおもしろい顔を作って、食欲をそそり、食事を遊びに変えてみましょう。', title_ko = '접시 위의 예술 🥦', body_ko = '밥을 안 먹나요? 가끔은 맛이 아니라 모양이 문제예요. 알록달록한 채소로 웃긴 얼굴을 만들어 입맛을 돋우고 식사를 놀이로 바꿔 보세요.', title_nl = 'Kunst op je bord 🥦', body_nl = 'Wil hij niet eten? Soms zit het probleem niet in de smaak, maar in het uiterlijk. Maak grappige gezichtjes met kleurrijke groenten om zijn eetlust op te wekken en van eten een spel te maken.', title_pl = 'Sztuka na talerzu 🥦', body_pl = 'Nie chce jeść? Czasem problemem nie jest smak, tylko wygląd. Spróbuj pobudzić jego apetyt, układając z kolorowych warzyw zabawne buźki, i zamień jedzenie w zabawę.', title_pt = 'Arte no prato 🥦', body_pt = 'Não come? Às vezes o problema não é o sabor, é o aspeto. Faça caras engraçadas com legumes coloridos para lhe abrir o apetite e transformar a refeição num jogo.', title_sv = 'Konst på tallriken 🥦', body_sv = 'Äter barnet inte maten? Ibland är problemet inte smaken utan utseendet. Gör roliga ansikten av färgglada grönsaker och försök väcka aptiten och göra maten till en lek.', title_vi = 'Nghệ thuật trên đĩa ăn 🥦', body_vi = 'Bé không chịu ăn? Đôi khi vấn đề không nằm ở hương vị mà ở hình thức. Hãy thử tạo những khuôn mặt ngộ nghĩnh từ rau củ nhiều màu để kích thích vị giác và biến bữa ăn thành trò chơi.', title_zh = '餐盘里的艺术 🥦', body_zh = '不肯吃饭？有时问题不在味道，而在外观。用五颜六色的蔬菜摆出搞笑的小脸，试着打开宝宝的胃口，把吃饭变成游戏吧。' WHERE id = '12d65ca5-dc2d-4959-8af5-51ab64abb6bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Carcajadas alegres 🤡', body_es = 'Cuando tus trucos no funcionan, los sonidos raros de papá salvan la situación. En las crisis de la noche, pásale la pelota enseguida y sonríe desde fuera.', title_fr = 'Éclats de rire joyeux 🤡', body_fr = 'Quand vos astuces ne marchent plus, les bruits bizarres de papa sauvent la situation. Pendant les crises du soir, passez-lui vite la balle et souriez en coulisses.', title_hi = 'खुशनुमा खिलखिलाहट 🤡', body_hi = 'जब आपकी तरकीबें काम नहीं करतीं, तो पापा की अजीब आवाज़ें हालात संभाल लेती हैं। शाम के नखरों में तुरंत बॉल उनके पाले में डालिए और दूर से मुस्कुराइए।', title_id = 'Tawa riang 🤡', body_id = 'Saat cara Anda tidak berhasil, suara aneh Ayah bisa menyelamatkan keadaan. Saat krisis malam hari, langsung oper bolanya kepada Ayah dan tersenyumlah dari jauh.', title_ja = '楽しい笑い声 🤡', body_ja = 'あなたの手が効かないとき、パパのおもしろい声が状況を救ってくれます。夕方のかんしゃくでは、すぐにパパにバトンを渡して、そばでほほえみましょう。', title_ko = '즐거운 웃음소리 🤡', body_ko = '엄마의 방법이 통하지 않을 때 아빠의 웃긴 소리가 상황을 구해 줘요. 저녁 떼쓰기 때는 바로 아빠에게 공을 넘기고 옆에서 웃어 주세요.', title_nl = 'Vrolijk gelach 🤡', body_nl = 'Als jouw trucjes niet werken, redden papa''s gekke geluiden de situatie. Speel de bal bij avondbuien direct naar hem door en glimlach vanaf de zijlijn.', title_pl = 'Radosne chichoty 🤡', body_pl = 'Gdy twoje sposoby nie działają, dziwne odgłosy taty ratują sytuację. Podczas wieczornych kryzysów od razu podaj mu piłeczkę i uśmiechaj się z boku.', title_pt = 'Gargalhadas alegres 🤡', body_pt = 'Quando os seus truques não funcionam, os sons estranhos do pai salvam a situação. Nas crises da noite, passe-lhe logo a bola e sorria de longe.', title_sv = 'Glada skratt 🤡', body_sv = 'När dina knep inte fungerar räddar pappas konstiga ljud situationen. Vid kvällskriser, passa bollen till honom direkt och le från sidan.', title_vi = 'Những tràng cười vui vẻ 🤡', body_vi = 'Khi những chiêu của mẹ không hiệu quả, những âm thanh lạ của bố sẽ cứu nguy. Khi bé quấy buổi tối, hãy "chuyền bóng" ngay cho bố và mỉm cười đứng xem.', title_zh = '欢快的笑声 🤡', body_zh = '你的办法都不管用时，爸爸的怪声音能挽救局面。晚上宝宝崩溃时，马上把球传给他，在一旁笑着看就好。' WHERE id = '27428d92-902e-4e8b-a566-975a32a7bf6a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La vida salvaje en casa 🐶', body_es = '¿No solo hace los sonidos, sino que gatea como un perro y se frota como un gato? Su lenguaje corporal y su imaginación se unen de forma asombrosa. Únete tú también a este juego sobre la alfombra.', title_fr = 'La vie sauvage à la maison 🐶', body_fr = 'Il ne se contente plus d''imiter les cris : il marche à quatre pattes comme un chien et guette comme un chat ? Langage corporel et imagination se rejoignent de façon étonnante. Joignez-vous à ce jeu sur le tapis.', title_hi = 'घर में जंगल 🐶', body_hi = 'सिर्फ़ आवाज़ ही नहीं निकालता, कुत्ते की तरह घुटनों के बल चलता और बिल्ली की तरह शिकार करता है? शारीरिक भाषा और कल्पना कमाल के ढंग से मिल रही हैं। कालीन पर इस खेल में आप भी शामिल हो जाइए।', title_id = 'Alam liar di rumah 🐶', body_id = 'Ia tidak hanya bersuara, tetapi juga merangkak seperti anjing dan mengendap seperti kucing? Bahasa tubuh dan imajinasinya menyatu dengan luar biasa. Ikutlah bermain bersamanya di atas karpet.', title_ja = '家の中の野生動物 🐶', body_ja = '鳴き声だけでなく、犬のようにはいはいしたり、猫のように体をすりよせたりしますか？体の表現と想像力がすばらしく結びついています。あなたもカーペットの上でこの遊びに加わりましょう。', title_ko = '집 안의 야생 🐶', body_ko = '소리만 내는 게 아니라 강아지처럼 기고 고양이처럼 몸을 비비나요? 몸짓 언어와 상상력이 놀랍게 하나가 되고 있어요. 카펫 위에서 엄마도 이 놀이에 함께해 보세요.', title_nl = 'De wilde natuur in huis 🐶', body_nl = 'Maakt hij niet alleen geluidjes, maar kruipt hij ook als een hond en sluipt hij als een kat? Lichaamstaal en fantasie komen prachtig samen. Doe mee met dit spel op het tapijt.', title_pl = 'Dzika przyroda w domu 🐶', body_pl = 'Nie tylko wydaje odgłosy, ale też raczkuje jak pies i łasi się jak kot? Mowa ciała i wyobraźnia łączą się w niesamowity sposób. Dołącz do tej zabawy na dywanie.', title_pt = 'A vida selvagem em casa 🐶', body_pt = 'Não só faz os sons, como também gatinha como um cão e se enrosca como um gato? A linguagem corporal e a imaginação juntam-se de forma espantosa. Entre também nesta brincadeira no tapete.', title_sv = 'Vilda djur hemma 🐶', body_sv = 'Gör barnet inte bara ljud, utan kryper som en hund och smyger som en katt? Kroppsspråk och fantasi förenas på ett fantastiskt sätt. Var med i leken på mattan du också.', title_vi = 'Thế giới hoang dã trong nhà 🐶', body_vi = 'Bé không chỉ phát ra tiếng kêu mà còn bò như chó, rình như mèo? Ngôn ngữ cơ thể và trí tưởng tượng đang kết hợp thật tuyệt vời. Hãy cùng bé chơi trò này trên thảm.', title_zh = '家里的野生动物 🐶', body_zh = '不只是学叫声，还像小狗一样爬，像小猫一样扑？肢体语言和想象力惊人地结合在一起。你也在地毯上加入这个游戏吧。' WHERE id = '71ce1c15-b947-45d9-8c0e-c8a77ece4ef7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pies descalzos 👣', body_es = 'Le encanta andar descalzo y tocar superficies distintas. Estimular los nervios de la planta del pie es insustituible para su desarrollo neurológico: deja que ande sin calcetines.', title_fr = 'Pieds nus 👣', body_fr = 'Il adore marcher pieds nus et toucher différentes surfaces. L''éveil des nerfs de la plante des pieds est précieux pour son développement neurologique, laissez-le marcher sans chaussettes.', title_hi = 'नंगे पैर 👣', body_hi = 'नंगे पैर चलने और अलग-अलग सतहों को छूने में उसे खास मज़ा आता है। तलवों की नसों का जागना उसके न्यूरोलॉजिकल विकास के लिए बेहद अहम है, उसे बिना मोज़ों के चलने दीजिए।', title_id = 'Kaki telanjang 👣', body_id = 'Ia sangat senang berjalan tanpa alas kaki dan menyentuh berbagai permukaan. Rangsangan saraf di telapak kakinya sangat berharga bagi perkembangan sarafnya, biarkan ia berjalan tanpa kaus kaki.', title_ja = 'はだしの足 👣', body_ja = 'はだしで歩いたり、いろいろな表面にふれたりするのが大好き。足の裏の神経が目覚めることは、神経の発達にとってかけがえのないこと、くつしたなしで歩かせてあげましょう。', title_ko = '맨발 👣', body_ko = '맨발로 걸으며 여러 표면을 만지는 걸 특히 좋아하나요? 발바닥 신경의 자극은 신경 발달에 정말 소중해요. 양말 없이 걷게 해 주세요.', title_nl = 'Blote voetjes 👣', body_nl = 'Hij geniet extra van blootsvoets lopen en verschillende ondergronden voelen. Het prikkelen van de zenuwen onder zijn voetzolen is onmisbaar voor zijn neurologische ontwikkeling, laat hem zonder sokken rondlopen.', title_pl = 'Bose stópki 👣', body_pl = 'Z wyjątkową przyjemnością chodzi boso i dotyka różnych powierzchni. Pobudzanie nerwów na podeszwach stóp jest bezcenne dla jego rozwoju neurologicznego, pozwól mu chodzić bez skarpetek.', title_pt = 'Pés descalços 👣', body_pt = 'Adora andar descalço e tocar em superfícies diferentes. Estimular os nervos da planta do pé é insubstituível para o desenvolvimento neurológico: deixe-o andar sem meias.', title_sv = 'Bara fötter 👣', body_sv = 'Barnet njuter särskilt av att gå barfota och känna på olika ytor. Att nerverna under fötterna väcks är ovärderligt för den neurologiska utvecklingen, låt barnet gå utan strumpor.', title_vi = 'Đôi chân trần 👣', body_vi = 'Bé đặc biệt thích đi chân trần và chạm vào các bề mặt khác nhau. Việc kích thích các dây thần kinh dưới lòng bàn chân là vô giá cho sự phát triển thần kinh, hãy để bé đi không cần tất.', title_zh = '光着小脚丫 👣', body_zh = '特别喜欢光着脚走路，摸摸不同的地面。唤醒脚底的神经，对宝宝的神经发育无可替代，就让宝宝不穿袜子走走吧。' WHERE id = 'c0f3d36a-8d02-476e-a6a5-3dfb6c2aa133' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Memoria digital 🛒', body_es = '¿Siempre se te olvida algo al ir al súper? La Lista de la compra te espera en la app. Apunta ahí lo que falta y que tu pareja lo compre sin fallo al volver del trabajo.', title_fr = 'Mémoire numérique 🛒', body_fr = 'Vous oubliez toujours quelque chose au supermarché ? La Liste de courses vous attend dans l''application. Notez-y vos besoins, votre partenaire fera les courses avec précision en rentrant du travail.', title_hi = 'डिजिटल याददाश्त 🛒', body_hi = 'बाज़ार जाते समय कुछ न कुछ ज़रूर भूल जाती हैं? ऐप में शॉपिंग लिस्ट आपका इंतज़ार कर रही है। ज़रूरतें वहाँ लिखिए, ताकि आपके पार्टनर काम से लौटते समय सब कुछ ठीक-ठीक ले आएँ।', title_id = 'Memori digital 🛒', body_id = 'Selalu ada yang terlupa saat belanja? Daftar Belanja menunggu Anda di aplikasi. Catat kebutuhan di sana, biar pasangan membelinya dengan tepat saat pulang kerja.', title_ja = 'デジタルの記憶 🛒', body_ja = '買い物に行くと、必ず何かを忘れてしまう？アプリの「買い物リスト」が待っています。必要なものをそこに書いて、パートナーに仕事帰りにきちんと買ってきてもらいましょう。', title_ko = '디지털 기억 🛒', body_ko = '마트에 가면 꼭 하나씩 잊어버리나요? 앱의 쇼핑 목록이 기다리고 있어요. 필요한 걸 적어 두면 배우자가 퇴근길에 정확히 사 올 수 있어요.', title_nl = 'Digitaal geheugen 🛒', body_nl = 'Vergeet je altijd iets als je naar de supermarkt gaat? Het Boodschappenlijstje wacht op je in de app. Zet erop wat je nodig hebt, dan haalt je partner het precies op weg terug van zijn werk.', title_pl = 'Cyfrowa pamięć 🛒', body_pl = 'Idąc do sklepu, zawsze o czymś zapominasz? Lista zakupów czeka na ciebie w aplikacji. Zapisz tam potrzeby, a partner wracając z pracy, kupi wszystko co do joty.', title_pt = 'Memória digital 🛒', body_pt = 'Esquece-se sempre de alguma coisa no supermercado? A Lista de Compras espera por si na app. Aponte lá o que falta e o seu companheiro compra tudo certinho ao voltar do trabalho.', title_sv = 'Digitalt minne 🛒', body_sv = 'Glömmer du alltid något när du går och handlar? Inköpslistan väntar på dig i appen. Skriv in behoven där så kan din partner handla exakt det som behövs på vägen hem från jobbet.', title_vi = 'Trí nhớ kỹ thuật số 🛒', body_vi = 'Đi siêu thị lần nào mẹ cũng quên một thứ gì đó? Danh sách mua sắm đang chờ mẹ trong ứng dụng. Hãy ghi những thứ cần mua vào đó để chồng mua đủ trên đường đi làm về.', title_zh = '数字记忆 🛒', body_zh = '去超市总会忘点什么？购物清单就在应用里等着你。把需要的东西记进去，让另一半下班回家时准确采购。' WHERE id = 'c3c4fb6d-e99b-442f-b18d-4a0a69488a0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Imaginación en voz alta 🪄', body_es = 'Esta noche crea en Cuentos inteligentes una aventura especial: la historia del conejo valiente que no le tiene miedo a la aspiradora. Es muy fácil curar los miedos con cuentos.', title_fr = 'Imagination à voix haute 🪄', body_fr = 'Ce soir, créez-lui une aventure spéciale dans les Contes intelligents : l''histoire du lapin courageux qui n''a pas peur de l''aspirateur. Soigner les peurs avec des contes, c''est très facile.', title_hi = 'आवाज़ वाली कल्पना 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में उसके लिए एक खास रोमांच बनाइए: वैक्यूम क्लीनर से न डरने वाले बहादुर खरगोश की कहानी। कहानियों से डर दूर करना बहुत आसान है।', title_id = 'Imajinasi bersuara 🪄', body_id = 'Malam ini buat petualangan khusus untuknya di Dongeng Pintar: kisah kelinci pemberani yang tidak takut pada penyedot debu. Mengatasi rasa takut dengan dongeng itu sangat mudah.', title_ja = '声の想像力 🪄', body_ja = '今夜は「スマートおはなし」で特別な冒険をつくりましょう：掃除機をこわがらない勇敢なうさぎのお話。こわさはお話でとても簡単にやわらげられます。', title_ko = '목소리로 펼치는 상상 🪄', body_ko = '오늘 저녁 스마트 동화에서 특별한 모험을 만들어 주세요: 청소기를 무서워하지 않는 용감한 토끼 이야기. 두려움은 동화로 다스리기 정말 쉬워요.', title_nl = 'Fantasie met je stem 🪄', body_nl = 'Maak vanavond in Slimme sprookjes een speciaal avontuur voor hem: het verhaal van het dappere konijn dat niet bang is voor de stofzuiger. Angsten zijn heel makkelijk te behandelen met sprookjes.', title_pl = 'Wyobraźnia w głosie 🪄', body_pl = 'Stwórz dziś wieczorem w Mądrych bajkach wyjątkową przygodę: historię dzielnego króliczka, który nie boi się odkurzacza. Leczenie lęków bajkami jest bardzo łatwe.', title_pt = 'Imaginação com voz 🪄', body_pt = 'Esta noite, crie nas Histórias Inteligentes uma aventura especial para ele: a história do coelho corajoso que não tem medo do aspirador. Tratar os medos com histórias é muito fácil.', title_sv = 'Fantasi med ljud 🪄', body_sv = 'Skapa ett speciellt äventyr åt barnet i Smarta sagor i kväll: berättelsen om den modiga kaninen som inte är rädd för dammsugaren. Det är väldigt lätt att bota rädslor med sagor.', title_vi = 'Trí tưởng tượng qua giọng kể 🪄', body_vi = 'Tối nay hãy tạo cho bé một cuộc phiêu lưu đặc biệt trong Truyện cổ tích thông minh: câu chuyện về chú thỏ dũng cảm không sợ máy hút bụi. Chữa nỗi sợ bằng truyện cổ tích thật dễ dàng.', title_zh = '有声的想象 🪄', body_zh = '今晚在智能故事里为宝宝创作一场特别的冒险：一只不怕吸尘器的勇敢小兔子的故事。用故事来化解恐惧，其实很简单。' WHERE id = 'cb069764-7f58-461b-a159-7d553277ecda' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ego herido 🛑', body_es = 'Dice «¡Lo hago yo solo!» y rechaza cualquier ayuda. Aunque se ponga los zapatos cambiados, no se los toques. Un ego sin heridas importa mucho más que unos zapatos mal puestos.', title_fr = 'Un ego blessé 🛑', body_fr = 'Il dit « Je le fais tout seul ! » et refuse toute aide. Même s''il met ses chaussures à l''envers, n''y touchez pas. Un ego intact compte plus qu''une chaussure bien mise.', title_hi = 'आहत अहं 🛑', body_hi = '''मैं खुद करूँगा!'' कहकर हर तरह की मदद ठुकरा देता है? जूते उल्टे पहने तब भी उसे मत छेड़िए। उल्टे पहने जूते से ज़्यादा ज़रूरी है उसका अहं आहत न होना।', title_id = 'Harga diri yang terluka 🛑', body_id = 'Ia bilang ''Aku sendiri!'' dan menolak semua bantuan. Meski sepatunya terbalik, jangan disentuh. Harga diri yang tidak terluka jauh lebih penting daripada sepatu yang terpasang benar.', title_ja = '傷ついたプライド 🛑', body_ja = '「自分でやる！」と言って、どんな手助けも断りますか？靴を左右逆にはいても、手を出さないで。ちぐはぐな靴より、傷つかないプライドのほうがずっと大切です。', title_ko = '상처받은 자존심 🛑', body_ko = '''내가 할 거야!'' 하며 모든 도움을 거절하나요? 신발을 거꾸로 신어도 건드리지 마세요. 제대로 신은 신발보다 상처받지 않은 자존심이 더 중요해요.', title_nl = 'Gekrenkt ego 🛑', body_nl = 'Roept hij ''Ik doe het zelf!'' en weigert hij elke hulp? Ook al trekt hij zijn schoenen verkeerd om aan, kom er niet aan. Een ongeschonden ego is belangrijker dan een goed aangetrokken schoen.', title_pl = 'Zranione ego 🛑', body_pl = 'Mówi „Ja sam!” i odrzuca wszelką pomoc. Nawet jeśli założy buty na odwrót, nie ruszaj ich. Niezranione ego jest ważniejsze niż dobrze założony but.', title_pt = 'Ego ferido 🛑', body_pt = 'Diz "Eu faço sozinho!" e recusa qualquer ajuda. Mesmo que calce os sapatos trocados, não toque. Mais importante do que um sapato bem calçado é um ego que não sai ferido.', title_sv = 'Sårat ego 🛑', body_sv = 'Barnet säger ”Jag gör själv!” och vägrar all hjälp. Rör inte skorna även om de sitter på fel fot. Ett osårat ego är viktigare än en sko som sitter fel.', title_vi = 'Cái tôi bị tổn thương 🛑', body_vi = 'Bé nói "Con tự làm!" và từ chối mọi sự giúp đỡ. Dù bé đi giày ngược chân, cũng đừng can thiệp. Một cái tôi không bị tổn thương quan trọng hơn nhiều so với đôi giày đi sai.', title_zh = '受伤的自尊 🛑', body_zh = '说着“我自己来！”，拒绝一切帮忙。就算鞋子穿反了，也别去碰。比起一只穿反的鞋，一份没有受伤的自尊重要得多。' WHERE id = '62149695-6298-4aba-847f-c8ce0b1eb19a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Adiós a las dudas 🤖', body_es = '¿Te preocupan cambios repentinos en su conducta? No busques enfermedades que asustan en foros de internet: aprende con Anacan AI la realidad precisa, al instante y con base científica.', title_fr = 'Fini les doutes 🤖', body_fr = 'Des changements soudains dans son comportement vous inquiètent ? Ne cherchez pas de maladies effrayantes sur les forums, découvrez avec Anacan AI une réalité précise, immédiate et fondée sur la science.', title_hi = 'शक का अंत 🤖', body_hi = 'बच्चे के व्यवहार में अचानक बदलाव ने आपको चिंता में डाल दिया? इंटरनेट फ़ोरम पर डरावनी बीमारियाँ मत ढूँढिए, Anacan AI से तुरंत सटीक और वैज्ञानिक आधार वाली सच्चाई जानिए।', title_id = 'Akhiri keraguan 🤖', body_id = 'Perubahan mendadak pada perilaku anak membuat Anda cemas? Jangan mencari penyakit menakutkan di forum internet, pelajari fakta yang tepat, cepat, dan berdasar ilmiah dari Anacan AI.', title_ja = '不安にさよなら 🤖', body_ja = 'お子さんの行動の急な変化が気になりましたか？ネットの掲示板でこわい病気を探さないで、Anacan AIから正確で、すぐに、科学的な根拠のある事実を学びましょう。', title_ko = '걱정은 이제 그만 🤖', body_ko = '아이 행동의 갑작스러운 변화가 걱정되나요? 인터넷 게시판에서 무서운 병을 찾지 말고 Anacan AI에게 정확하고 과학적인 정보를 바로 받아 보세요.', title_nl = 'Klaar met twijfelen 🤖', body_nl = 'Maakten plotselinge veranderingen in zijn gedrag je ongerust? Zoek niet op internetfora naar enge ziektes, maar krijg meteen nauwkeurige, wetenschappelijk onderbouwde informatie van Anacan AI.', title_pl = 'Koniec z wątpliwościami 🤖', body_pl = 'Zaniepokoiły cię nagłe zmiany w zachowaniu dziecka? Nie szukaj na forach przerażających chorób, poznaj od Anacan AI dokładne, natychmiastowe i oparte na nauce fakty.', title_pt = 'Chega de dúvidas 🤖', body_pt = 'Mudanças repentinas no comportamento da criança preocuparam-na? Não procure doenças assustadoras nos fóruns da internet: conheça a realidade precisa, imediata e com base científica no Anacan AI.', title_sv = 'Slut på tvivlen 🤖', body_sv = 'Har plötsliga förändringar i barnets beteende oroat dig? Sök inte efter skrämmande sjukdomar i forum på nätet, få exakta, omedelbara och vetenskapligt grundade fakta från Anacan AI.', title_vi = 'Chấm dứt nghi ngờ 🤖', body_vi = 'Những thay đổi đột ngột trong hành vi của bé khiến mẹ lo lắng? Đừng tìm những căn bệnh đáng sợ trên các diễn đàn mạng, hãy hỏi Anacan AI để biết ngay thực tế chính xác, có cơ sở khoa học.', title_zh = '告别疑虑 🤖', body_zh = '孩子的行为突然变化让你担心？别在网上论坛里搜那些吓人的疾病，向Anacan AI了解准确、即时、有科学依据的事实吧。' WHERE id = '86650154-88a4-4c7d-ab75-32f1a232aa9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Guardiana del sueño 🤫', body_es = 'La primera media hora después de dormirse es cuando el cerebro está más activo. Ajusta la habitación con el Medidor de sonido. A veces basta con el sonido de una lluvia suave para llevarle a un sueño profundo.', title_fr = 'Gardienne du sommeil 🤫', body_fr = 'La première demi-heure de sommeil est le moment où le cerveau est le plus actif. Ajustez la chambre avec le Sonomètre. Parfois, le simple bruit d''une pluie légère suffit à l''emmener dans un sommeil profond.', title_hi = 'नींद का पहरेदार 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा वह समय है जब दिमाग सबसे सक्रिय होता है। साउंड मीटर से कमरे का माहौल ठीक कीजिए। कभी-कभी हल्की बारिश की आवाज़ ही उसे गहरी नींद में ले जा सकती है।', title_id = 'Penjaga tidur 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah saat otak paling aktif. Atur kamar dengan Pengukur Suara. Kadang suara gerimis saja bisa membawanya ke tidur yang lelap.', title_ja = '眠りの見張り番 🤫', body_ja = '寝ついてから最初の30分は、脳がいちばん活発な時間です。「サウンドメーター」で部屋を整えましょう。やさしく降る雨の音だけで、深い眠りに入れることもあります。', title_ko = '잠의 수호자 🤫', body_ko = '잠든 후 첫 30분은 뇌가 가장 활발한 시간이에요. 소음 측정기로 방을 조절하세요. 때로는 잔잔한 빗소리만으로도 깊은 잠에 빠질 수 있어요.', title_nl = 'Bewaker van de slaap 🤫', body_nl = 'Het eerste halfuur na het inslapen zijn de hersenen het actiefst. Stem de kamer af met de Geluidsmeter. Soms brengt alleen al het geluid van zachte regen hem in een diepe slaap.', title_pl = 'Strażnik snu 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to czas największej aktywności mózgu. Dostosuj pokój Miernikiem dźwięku. Czasem sam odgłos delikatnego deszczu wystarczy, by zapadł w głęboki sen.', title_pt = 'Guardião do sono 🤫', body_pt = 'A primeira meia hora depois de adormecer é quando o cérebro está mais ativo. Ajuste o quarto com o Medidor de Som. Às vezes basta o som de uma chuva leve para o levar a um sono profundo.', title_sv = 'Sömnens väktare 🤫', body_sv = 'Den första halvtimmen efter insomnandet är då hjärnan är som mest aktiv. Justera rummet med Ljudmätaren. Ibland räcker ljudet av lätt regn för att barnet ska falla i djup sömn.', title_vi = 'Người canh giữ giấc ngủ 🤫', body_vi = 'Nửa giờ đầu sau khi bé ngủ là lúc não hoạt động mạnh nhất. Hãy điều chỉnh phòng bằng Đo âm thanh. Đôi khi chỉ tiếng mưa rơi nhẹ cũng có thể đưa bé vào giấc ngủ sâu.', title_zh = '睡眠守护者 🤫', body_zh = '入睡后的头半小时是大脑最活跃的时候。用分贝仪调节房间环境。有时只是轻轻的雨声，就能把宝宝带入深睡。' WHERE id = 'd8fdf53e-3f50-42fc-a36a-84c2b2cbfbee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo 5 días para los 1000 días! 🎈', body_es = '¡La cuenta atrás está a punto de terminar! Estás a punto de completar un camino grande y legendario de exactamente 1000 días. Sonríe y empieza ya a preparar la celebración y algunas ideas divertidas.', title_fr = 'Plus que 5 jours avant les 1000 jours ! 🎈', body_fr = 'Le compte à rebours touche à sa fin ! Vous êtes sur le point de boucler un grand et légendaire chemin de 1000 jours. Souriez et commencez dès maintenant à préparer la fête et des idées joyeuses !', title_hi = '1000 दिन में बस 5 दिन बाकी! 🎈', body_hi = 'उल्टी गिनती खत्म होने वाली है! आप पूरे 1000 दिनों का एक बड़ा और यादगार सफ़र पूरा करने वाली हैं। मुस्कुराइए, जश्न की तैयारियाँ और मज़ेदार आइडिया अभी से शुरू कीजिए!', title_id = 'Tinggal 5 hari lagi menuju 1000 hari! 🎈', body_id = 'Hitung mundur hampir selesai! Anda akan segera menuntaskan perjalanan besar dan legendaris selama tepat 1000 hari. Tersenyumlah, mulai siapkan perayaan dan konsep seru dari sekarang!', title_ja = '1000日まであと5日！🎈', body_ja = 'カウントダウンもいよいよ終わり！ちょうど1000日という大きくて伝説的な道のりを歩みきろうとしています。ほほえんで、記念日の準備や楽しいアイデアを今から始めましょう！', title_ko = '1000일까지 단 5일! 🎈', body_ko = '카운트다운이 거의 끝나 가요! 꼬박 1000일이라는 크고 전설적인 여정을 곧 마치게 돼요. 미소 지으며 기념일 준비와 즐거운 콘셉트를 지금부터 시작해 보세요!', title_nl = 'Nog maar 5 dagen tot 1000 dagen! 🎈', body_nl = 'Het aftellen is bijna voorbij! Je hebt bijna een grote, legendarische reis van precies 1000 dagen afgelegd. Glimlach en begin nu al met de voorbereidingen en vrolijke ideeën voor het jubileum!', title_pl = 'Do 1000 dni zostało tylko 5! 🎈', body_pl = 'Odliczanie dobiega końca! Za chwilę pokonacie wielką, legendarną drogę równych 1000 dni. Uśmiechnij się i już teraz zacznij przygotowania do jubileuszu i wesołych pomysłów!', title_pt = 'Faltam só 5 dias para os 1000 dias! 🎈', body_pt = 'A contagem decrescente está quase a acabar! Está prestes a completar um grande e lendário caminho de exatamente 1000 dias. Sorria e comece já os preparativos da festa e as ideias divertidas!', title_sv = 'Bara 5 dagar kvar till 1000 dagar! 🎈', body_sv = 'Nedräkningen är nästan slut! Du är på väg att fullborda en stor och legendarisk resa på exakt 1000 dagar. Le och börja redan nu med förberedelserna för jubileet och roliga teman!', title_vi = 'Chỉ còn 5 ngày nữa là tròn 1000 ngày! 🎈', body_vi = 'Đồng hồ đếm ngược sắp kết thúc! Mẹ sắp hoàn thành chặng đường lớn lao và huyền thoại tròn 1000 ngày. Hãy mỉm cười và bắt đầu chuẩn bị cho lễ kỷ niệm cùng những ý tưởng vui nhộn ngay từ bây giờ!', title_zh = '距离1000天只剩5天！🎈', body_zh = '倒计时就要结束了！你即将走完整整1000天这段伟大而传奇的旅程。笑一笑，现在就开始准备纪念日和欢乐的创意吧！' WHERE id = '5820d5b6-2a79-44ac-a012-46235cfe81f4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de lectura en silencio 🥱', body_es = '¿No quiere ir a la cama y se resiste? En esta etapa algunos niños dejan la siesta. En lugar de luchar, anuncia una hora de calma y proponle simplemente hojear un libro en la cama.', title_fr = 'L''heure de lecture calme 🥱', body_fr = 'Il ne veut pas aller au lit et résiste ? À cet âge, certains enfants abandonnent la sieste. Plutôt que de lutter, annoncez un « temps calme » et proposez-lui simplement de feuilleter un livre dans son lit.', title_hi = 'शांत किताब समय 🥱', body_hi = 'बिस्तर पर नहीं जाना चाहता और अड़ जाता है? इस दौर में कुछ बच्चे दिन की नींद छोड़ देते हैं। लड़ने के बजाय ''शांत समय'' घोषित कीजिए और बिस्तर पर बस किताब पलटने को कहिए।', title_id = 'Jam buku yang tenang 🥱', body_id = 'Ia tidak mau tidur dan terus melawan? Sebagian anak berhenti tidur siang di masa ini. Daripada berdebat, umumkan ''waktu tenang'' dan tawarkan untuk membolak-balik buku saja di tempat tidur.', title_ja = '静かな絵本の時間 🥱', body_ja = 'ベッドに行きたがらずに抵抗しますか？この時期にお昼寝をしなくなる子もいます。戦うかわりに「静かな時間」を宣言して、ベッドで絵本をめくるだけでいいと提案しましょう。', title_ko = '조용한 책 시간 🥱', body_ko = '자러 가지 않겠다고 버티나요? 이 시기에 낮잠을 그만두는 아이도 있어요. 씨름하지 말고 ''조용한 시간''을 정해 침대에서 책만 넘겨 보자고 해 보세요.', title_nl = 'Stil leesuurtje 🥱', body_nl = 'Wil hij niet naar bed en verzet hij zich? Sommige kinderen stoppen in deze fase met hun middagslaapje. Ga de strijd niet aan, maar kondig een rustuurtje aan en stel voor dat hij gewoon in bed in een boekje bladert.', title_pl = 'Cicha godzina z książką 🥱', body_pl = 'Nie chce iść do łóżka i się opiera? Niektóre dzieci w tym okresie rezygnują z drzemki w dzień. Zamiast walczyć, ogłoś godzinę wyciszenia i zaproponuj po prostu przeglądanie książeczki w łóżku.', title_pt = 'Hora do livro em silêncio 🥱', body_pt = 'Não quer ir para a cama e resiste? Algumas crianças deixam a sesta nesta fase. Em vez de lutar, anuncie a hora do sossego e proponha que folheie um livro na cama.', title_sv = 'Tyst bokstund 🥱', body_sv = 'Vill barnet inte gå och lägga sig och sätter sig emot? Vissa barn slutar sova på dagen i den här perioden. I stället för att kämpa, utlys en Lugn stund och föreslå att barnet bara bläddrar i böcker i sängen.', title_vi = 'Giờ đọc sách yên tĩnh 🥱', body_vi = 'Bé không muốn lên giường và chống cự? Một số trẻ bỏ giấc ngủ ngày ở giai đoạn này. Thay vì giằng co, hãy tuyên bố "Giờ yên tĩnh" và gợi ý bé chỉ cần lật sách trên giường.', title_zh = '安静看书时间 🥱', body_zh = '不想上床，还一直抗拒？有些孩子在这个阶段会不再午睡。与其对抗，不如宣布“安静时间”，让宝宝在床上翻翻书就好。' WHERE id = '7ac49f38-01ad-4503-8e74-f0a0bf7621d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una página de orgullo 📝', body_es = 'En un camino tan largo y lleno de altibajos, tu mayor fuerza es el amor que le tienes. Abre el Diario de ánimo y escríbele una pequeña carta llena de orgullo para que la lea en el futuro.', title_fr = 'La page de la fierté 📝', body_fr = 'Sur ce chemin si long, plein de hauts et de bas, votre plus grande force est votre amour pour lui. Ouvrez le Journal d''humeur et écrivez-lui une petite lettre pleine de fierté qu''il lira plus tard.', title_hi = 'गर्व का पन्ना 📝', body_hi = 'इतने लंबे और उतार-चढ़ाव भरे सफ़र में आपकी सबसे बड़ी ताकत उसके लिए आपका प्यार है। मूड डायरी खोलिए और उसके लिए एक छोटी, गर्व भरी चिट्ठी लिखिए जिसे वह बड़ा होकर पढ़ेगा।', title_id = 'Lembar kebanggaan 📝', body_id = 'Di perjalanan yang panjang dan penuh naik-turun ini, kekuatan terbesar Anda adalah cinta untuknya. Buka Buku Harian Suasana Hati dan tulis surat kecil yang membanggakan untuk ia baca kelak.', title_ja = '誇りのページ 📝', body_ja = 'こんなに長く、山あり谷ありの道のりで、あなたのいちばんの力はお子さんへの愛です。「気分日記」を開いて、いつかお子さんが読む小さな誇らしい手紙を書きましょう。', title_ko = '자랑스러운 한 페이지 📝', body_ko = '길고 굴곡진 이 여정에서 엄마의 가장 큰 힘은 아이를 향한 사랑이에요. 기분 일기를 열고 아이가 나중에 읽을 작고 자랑스러운 편지를 써 보세요.', title_nl = 'Een bladzijde vol trots 📝', body_nl = 'Op deze lange weg vol ups en downs is je liefde voor hem je grootste kracht. Open je Stemmingsdagboek en schrijf hem een kleine, trotse brief die hij later kan lezen.', title_pl = 'Strona dumy 📝', body_pl = 'Na tej długiej, pełnej wzlotów i upadków drodze twoją największą siłą jest miłość do niego. Otwórz Dziennik nastroju i napisz mu mały list pełen dumy, który przeczyta w przyszłości.', title_pt = 'Página de orgulho 📝', body_pt = 'Neste caminho tão longo e cheio de altos e baixos, a sua maior força é o amor por ele. Abra o Diário de Humor e escreva-lhe uma pequena carta, cheia de orgulho, para ele ler no futuro.', title_sv = 'Ett blad av stolthet 📝', body_sv = 'På en så lång väg med så många upp- och nedgångar är din kärlek till barnet din största styrka. Öppna Humördagboken och skriv ett litet, stolt brev som barnet kan läsa i framtiden.', title_vi = 'Trang giấy tự hào 📝', body_vi = 'Trên chặng đường dài đầy thăng trầm này, sức mạnh lớn nhất của mẹ là tình yêu dành cho bé. Hãy mở Nhật ký tâm trạng và viết cho bé một lá thư nhỏ đầy tự hào để sau này bé đọc.', title_zh = '骄傲的一页 📝', body_zh = '在这条漫长又起起伏伏的路上，你最大的力量是对宝宝的爱。打开心情日记，给宝宝写一封将来可以读的、让人骄傲的小信吧。' WHERE id = 'd50eb553-5709-43ce-81ea-ce5014437b1a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño ayudante 🧸', body_es = '¿Cuando le dices «Trae los zapatos», va y los trae de verdad? ¡Su vocabulario y su comprensión están en su mejor momento! Refuerza su autoestima haciéndole partícipe de pequeñas tareas de casa.', title_fr = 'Petit assistant 🧸', body_fr = 'Quand vous lui dites « Apporte tes chaussures », il va vraiment les chercher ? Son vocabulaire et sa compréhension sont à leur sommet ! Faites-le participer aux petites tâches de la maison pour renforcer sa confiance en lui.', title_hi = 'नन्हा मददगार 🧸', body_hi = '''जूते लाओ'' कहने पर सच में जाकर ले आता है? शब्दावली और समझने की क्षमता चरम पर है! घर के छोटे-छोटे कामों में शामिल करके उसका आत्मविश्वास बढ़ाइए।', title_id = 'Penolong kecil 🧸', body_id = 'Saat Anda bilang ''Ambilkan sepatumu'', ia benar-benar pergi mengambilnya? Kosakata dan daya pahamnya sedang memuncak! Tingkatkan rasa percaya dirinya dengan melibatkannya dalam tugas kecil di rumah.', title_ja = '小さなお手伝いさん 🧸', body_ja = '「靴を持ってきて」と言うと、本当に取ってきてくれますか？語彙と理解力がピークです！家の小さなお手伝いに参加させて、自信を育てましょう。', title_ko = '꼬마 도우미 🧸', body_ko = '''신발 가져와'' 하면 정말로 가서 가져오나요? 어휘와 이해력이 절정이에요! 집안의 작은 일에 참여시키며 자신감을 키워 주세요.', title_nl = 'Kleine helper 🧸', body_nl = 'Gaat hij echt zijn schoenen halen als je ''Pak je schoenen'' zegt? Zijn woordenschat en begrip zijn op hun hoogtepunt! Laat hem helpen met kleine klusjes in huis en geef zijn zelfvertrouwen een boost.', title_pl = 'Mały pomocnik 🧸', body_pl = 'Gdy mówisz „Przynieś buty”, naprawdę idzie i je przynosi? Zasób słów i rozumienie są u szczytu! Angażuj go w drobne domowe zadania i wzmacniaj jego pewność siebie.', title_pt = 'Pequeno ajudante 🧸', body_pt = 'Quando lhe diz "Traz os sapatos", vai mesmo buscá-los? O vocabulário e a compreensão estão no auge! Envolva-o nas pequenas tarefas de casa e aumente a autoconfiança dele.', title_sv = 'Liten hjälpreda 🧸', body_sv = 'Går barnet verkligen och hämtar skorna när du säger ”Hämta skorna”? Ordförrådet och förståelsen är på topp! Låt barnet hjälpa till med små sysslor hemma och stärk självkänslan.', title_vi = 'Người giúp việc nhỏ 🧸', body_vi = 'Khi mẹ bảo "Mang giày lại đây", bé thật sự đi lấy? Vốn từ và khả năng hiểu đang ở đỉnh cao! Hãy cho bé tham gia những việc nhỏ trong nhà để tăng sự tự tin.', title_zh = '小帮手 🧸', body_zh = '你说“把鞋拿来”，宝宝真的就去拿来了？词汇量和理解能力都到了高峰！让宝宝参与家里的小事，增强自信心吧。' WHERE id = '20a1ef6d-4573-433a-a2b7-db48ed6c1114' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Casa desordenada, mamá feliz 🌪', body_es = '¿Montañas de ropa y el lavavajillas lleno? Que esperen. Pide a tu compañero de equipo que hoy se encargue de las tareas de casa. Tú descansa: eres el pilar de esta casa.', title_fr = 'Maison en désordre, maman joyeuse 🌪', body_fr = 'Le linge s''entasse et le lave-vaisselle est plein ? Laissez faire. Demandez à votre coéquipier de prendre en charge les tâches ménagères aujourd''hui. Reposez-vous, vous êtes le pilier de cette maison.', title_hi = 'बिखरा घर, खुश माँ 🌪', body_hi = 'कपड़ों का पहाड़ लगा है, डिशवॉशर भरा है? रहने दीजिए। अपने टीम पार्टनर से कहिए कि आज घर के काम वे संभाल लें। आप आराम कीजिए, आप इस घर का मुख्य सहारा हैं।', title_id = 'Rumah berantakan, ibu bahagia 🌪', body_id = 'Pakaian menumpuk seperti gunung, mesin cuci piring penuh? Biarkan saja. Mintalah rekan setim Anda mengambil alih pekerjaan rumah hari ini. Anda beristirahatlah, Anda tiang utama rumah ini.', title_ja = '散らかった家、ごきげんなママ 🌪', body_ja = '洗濯物は山積み、食洗機はいっぱい？そのままでいいんです。今日の家事はチームメイトのパートナーにお願いしましょう。あなたは休んで、この家の大黒柱なのですから。', title_ko = '어질러진 집, 행복한 엄마 🌪', body_ko = '빨래는 산더미, 식기세척기는 꽉 찼나요? 그냥 두세요. 오늘 집안일은 팀 동료인 배우자에게 맡겨 달라고 하세요. 엄마는 쉬세요. 엄마가 이 집의 기둥이에요.', title_nl = 'Rommelig huis, vrolijke mama 🌪', body_nl = 'Ligt de was in bergen opgestapeld en zit de vaatwasser vol? Laat maar zo. Vraag je teamgenoot om vandaag het huishouden op zich te nemen. Rust jij uit, jij bent de steunpilaar van dit huis.', title_pl = 'Bałagan w domu, wesoła mama 🌪', body_pl = 'Ubrania piętrzą się jak góra, zmywarka pełna? Niech tak zostanie. Poproś partnera, żeby dziś przejął domowe obowiązki. Ty odpocznij, jesteś główną podporą tego domu.', title_pt = 'Casa desarrumada, mãe feliz 🌪', body_pt = 'A roupa está empilhada como uma montanha e a máquina da loiça cheia? Deixe ficar. Peça ao seu companheiro de equipa que trate hoje das tarefas de casa. Descanse: é o pilar desta casa.', title_sv = 'Stökigt hem, glad mamma 🌪', body_sv = 'Ligger tvätten i högar och är diskmaskinen full? Låt det vara. Be din lagkamrat ta över hushållet i dag. Vila du, du är hemmets bärande pelare.', title_vi = 'Nhà bừa, mẹ vui 🌪', body_vi = 'Quần áo chất đống, máy rửa bát đầy ắp? Cứ để đó. Hãy nhờ "đồng đội" của mẹ đảm nhận việc nhà hôm nay. Mẹ hãy nghỉ ngơi, mẹ là trụ cột chính của ngôi nhà này.', title_zh = '乱糟糟的家，快乐的妈妈 🌪', body_zh = '衣服堆成了山，洗碗机也满了？就放着吧。请你的“队友”今天把家务都包下来。你去休息，你是这个家的顶梁柱。' WHERE id = '9d370453-5ab2-46ed-b11b-b4f3648ebe3e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Anuncio: no quiero dormir 🥱', body_es = '¿No quiere ir a la cama y se resiste? En esta etapa algunos niños dejan la siesta. En lugar de luchar, anuncia una hora de calma y proponle jugar en silencio con sus juguetes en la cama.', title_fr = 'Grève du sommeil 🥱', body_fr = 'Il ne veut pas aller au lit et résiste ? À cet âge, certains enfants abandonnent la sieste. Plutôt que de lutter, annoncez un « temps calme » et proposez-lui de jouer en silence avec ses jouets dans son lit.', title_hi = 'नींद से इनकार का ऐलान 🥱', body_hi = 'बिस्तर पर नहीं जाना चाहता और अड़ जाता है? इस दौर में कुछ बच्चे दिन की नींद छोड़ देते हैं। लड़ने के बजाय ''शांत समय'' घोषित कीजिए और बिस्तर पर बस खिलौनों से चुपचाप खेलने को कहिए।', title_id = 'Pengumuman tidak mau tidur 🥱', body_id = 'Ia tidak mau tidur dan terus melawan? Sebagian anak berhenti tidur siang di masa ini. Daripada berdebat, umumkan ''waktu tenang'' dan tawarkan untuk bermain mainan dengan tenang di tempat tidur.', title_ja = '眠らない宣言 🥱', body_ja = 'ベッドに行きたがらずに抵抗しますか？この時期にお昼寝をしなくなる子もいます。戦うかわりに「静かな時間」を宣言して、ベッドでおもちゃと静かに遊ぶことを提案しましょう。', title_ko = '잠 안 잘래 선언 🥱', body_ko = '자러 가지 않겠다고 버티나요? 이 시기에 낮잠을 그만두는 아이도 있어요. 씨름하지 말고 ''조용한 시간''을 정해 침대에서 장난감으로 조용히 놀자고 해 보세요.', title_nl = 'Geen slaap, wordt aangekondigd 🥱', body_nl = 'Wil hij niet naar bed en verzet hij zich? Sommige kinderen stoppen in deze fase met hun middagslaapje. Ga de strijd niet aan, maar kondig een rustuurtje aan en stel voor dat hij stil met speelgoed in bed speelt.', title_pl = 'Ogłoszenie: nie śpię 🥱', body_pl = 'Nie chce iść do łóżka i się opiera? Niektóre dzieci w tym okresie rezygnują z drzemki w dzień. Zamiast walczyć, ogłoś godzinę wyciszenia i zaproponuj ciche bawienie się zabawkami w łóżku.', title_pt = 'Anúncio: hoje não há sono 🥱', body_pt = 'Não quer ir para a cama e resiste? Algumas crianças deixam a sesta nesta fase. Em vez de lutar, anuncie a hora do sossego e proponha que brinque em silêncio com os brinquedos na cama.', title_sv = 'Ingen sömn, meddelar barnet 🥱', body_sv = 'Vill barnet inte gå och lägga sig och sätter sig emot? Vissa barn slutar sova på dagen i den här perioden. I stället för att kämpa, utlys en Lugn stund och föreslå att barnet bara leker tyst med leksaker i sängen.', title_vi = 'Tuyên bố không ngủ 🥱', body_vi = 'Bé không muốn lên giường và chống cự? Một số trẻ bỏ giấc ngủ ngày ở giai đoạn này. Thay vì giằng co, hãy tuyên bố "Giờ yên tĩnh" và gợi ý bé lặng lẽ chơi đồ chơi trên giường.', title_zh = '宣布不睡 🥱', body_zh = '不想上床，还一直抗拒？有些孩子在这个阶段会不再午睡。与其对抗，不如宣布“安静时间”，让宝宝在床上安静地玩玩具。' WHERE id = '7794de7c-0d82-4deb-b825-a11099a42226' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descifrar el terror nocturno 😭', body_es = 'Se ha despertado llorando en mitad de la noche con los ojos cerrados y no oye a nadie. Escucha su llanto con el Análisis del llanto y, si es un terror nocturno, no intentes despertarle. Solo quédate a su lado y dale seguridad.', title_fr = 'Décoder la terreur nocturne 😭', body_fr = 'Il s''est réveillé en pleurant en pleine nuit, les yeux fermés, et n''entend personne. Faites écouter ses pleurs à l''Analyse des pleurs : s''il s''agit d''une terreur nocturne, n''essayez pas de le réveiller. Restez simplement près de lui pour le rassurer.', title_hi = 'नाइट टेरर का राज़ 😭', body_hi = 'आधी रात को आँखें बंद किए रोते हुए जाग गया और किसी की नहीं सुनता? उसकी आवाज़ क्राइंग एनालिसिस को सुनाइए, अगर यह नाइट टेरर है तो उसे जगाने की कोशिश मत कीजिए। बस उसके पास रहिए और भरोसा दीजिए।', title_id = 'Kode rahasia teror malam 😭', body_id = 'Ia terbangun tengah malam menangis dengan mata terpejam dan tidak mendengar siapa pun. Rekam suaranya dengan Analisis Tangisan, dan jika ini teror malam, jangan mencoba membangunkannya. Cukup berada di sisinya dan beri rasa aman.', title_ja = '夜驚症の暗号を解く 😭', body_ja = '夜中に目を閉じたまま泣いて起き、だれの声も聞こえていない？「泣き声分析」で声を聞かせてみましょう。夜驚症なら起こそうとしないで。ただそばにいて安心させてあげましょう。', title_ko = '야경증 해독하기 😭', body_ko = '한밤중에 눈을 감은 채 울며 깨서 아무 말도 듣지 못하나요? 울음 분석에 소리를 들려주고, 야경증이라면 깨우려 하지 마세요. 그저 곁에 있어 주며 안심시켜 주세요.', title_nl = 'De code van nachtangst 😭', body_nl = 'Wordt hij midden in de nacht met gesloten ogen huilend wakker en hoort hij niemand? Laat Huilanalyse luisteren. Is het nachtangst, probeer hem dan niet wakker te maken. Blijf gewoon bij hem en geef hem vertrouwen.', title_pl = 'Szyfr lęku nocnego 😭', body_pl = 'Obudził się w nocy z płaczem, z zamkniętymi oczami, i nikogo nie słyszy? Daj posłuchać jego płaczu Analizie płaczu; jeśli to lęk nocny, nie próbuj go budzić. Po prostu bądź obok i daj mu poczucie bezpieczeństwa.', title_pt = 'Decifrar o terror noturno 😭', body_pt = 'Acordou a meio da noite a chorar de olhos fechados e não ouve ninguém? Use a Análise do Choro; se for terror noturno, não tente acordá-lo. Fique apenas ao lado dele e dê-lhe segurança.', title_sv = 'Nattskräckens kod 😭', body_sv = 'Barnet har vaknat gråtande mitt i natten med slutna ögon och hör ingen. Låt Gråtanalys lyssna på ljudet, och om det är nattskräck, försök inte väcka barnet. Var bara där och ge trygghet.', title_vi = 'Giải mã hoảng sợ ban đêm 😭', body_vi = 'Bé khóc thức giấc giữa đêm, mắt nhắm nghiền và không nghe thấy ai. Hãy cho Phân tích tiếng khóc nghe tiếng khóc, nếu đó là hoảng sợ ban đêm, đừng cố đánh thức bé. Chỉ cần ở bên và trấn an bé.', title_zh = '解开夜惊的密码 😭', body_zh = '半夜闭着眼睛哭醒，谁的话都听不见？让哭声分析听一听，如果是夜惊，别试图叫醒宝宝。只要陪在身边，给宝宝安全感就好。' WHERE id = 'a2143b10-3a17-415c-a09b-d16e4c9ace11' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis de apetito selectivo 🍝', body_es = '¿Hoy rechaza la comida que ayer le encantaba? No conviertas la mesa en un campo de batalla. Revisa el equilibrio semanal con el Seguimiento de tomas y encuentra en Recetas saludables presentaciones diferentes y divertidas.', title_fr = 'Crises d''appétit sélectif 🍝', body_fr = 'Il refuse aujourd''hui le plat qu''il adorait hier ? Ne transformez pas la table en champ de bataille. Vérifiez l''équilibre de la semaine avec le Suivi des repas et trouvez des présentations différentes et amusantes dans les Recettes saines.', title_hi = 'खाने में नखरे 🍝', body_hi = 'कल का पसंदीदा खाना आज मना कर रहा है? खाने की मेज़ को जंग का मैदान मत बनाइए। फ़ीडिंग ट्रैकर से हफ़्ते का संतुलन देखिए और सेहतमंद रेसिपी में अलग, मज़ेदार तरीके से परोसने के आइडिया ढूँढिए।', title_id = 'Krisis pilih-pilih makanan 🍝', body_id = 'Hari ini ia menolak makanan yang kemarin ia sukai? Jangan jadikan meja makan medan perang. Periksa keseimbangan mingguannya di Pemantau Nutrisi dan temukan sajian yang berbeda dan menyenangkan di Resep Sehat.', title_ja = '好き嫌いの時期 🍝', body_ja = '昨日大好きだった料理を、今日はいやがりますか？食卓を戦場にしないで。「栄養管理ツール」で1週間のバランスを確認して、「ヘルシーレシピ」で違った楽しい盛りつけを見つけましょう。', title_ko = '까다로운 입맛의 시기 🍝', body_ko = '어제 좋아하던 음식을 오늘은 거부하나요? 식탁을 전쟁터로 만들지 마세요. 수유 기록 도구로 한 주의 균형을 확인하고, 건강한 레시피에서 색다르고 재미있는 담음새를 찾아보세요.', title_nl = 'Kieskeurige eetbuien 🍝', body_nl = 'Weigert hij vandaag wat hij gisteren nog lekker vond? Maak van de tafel geen slagveld. Check de weekbalans in de Voedingstracker en vind in Gezonde recepten andere, leuke manieren om het op te dienen.', title_pl = 'Kryzysy wybiórczego apetytu 🍝', body_pl = 'Danie, które wczoraj uwielbiał, dziś odrzuca? Nie zamieniaj stołu w pole bitwy. Sprawdź tygodniowy bilans w narzędziu do śledzenia karmienia i znajdź w Zdrowych przepisach inne, zabawne sposoby podania.', title_pt = 'Crises de apetite seletivo 🍝', body_pt = 'Hoje recusa a comida de que ontem gostava? Não transforme a mesa num campo de batalha. Verifique o equilíbrio semanal no Registo de Alimentação e encontre apresentações diferentes e divertidas nas Receitas Saudáveis.', title_sv = 'Kriser med kräsen aptit 🍝', body_sv = 'Vägrar barnet i dag maten hen älskade i går? Gör inte matbordet till ett slagfält. Kolla veckobalansen med Matningskoll och hitta andra, roliga sätt att servera i Hälsosamma recept.', title_vi = 'Những cơn kén ăn 🍝', body_vi = 'Món hôm qua bé thích thì hôm nay lại từ chối? Đừng biến bàn ăn thành chiến trường. Hãy kiểm tra cân bằng hằng tuần bằng Theo dõi cữ bú và tìm những cách bày món khác lạ, vui mắt trong Công thức lành mạnh.', title_zh = '挑食危机 🍝', body_zh = '昨天爱吃的饭，今天却不肯吃？别把餐桌变成战场。用喂养记录工具看看每周的营养平衡，在健康食谱里找些不同的、有趣的摆盘方式。' WHERE id = 'df260082-4554-4a41-9637-0bed22c395ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Clase de anatomía 👀', body_es = '¿Cuando le preguntas «¿Dónde están tus hombros?», se los toca con el dedo? ¡Su comprensión está en su mejor momento! Seguid el juego con partes del cuerpo más difíciles y enriquece su vocabulario.', title_fr = 'Leçon d''anatomie 👀', body_fr = 'Quand vous demandez « Où sont tes épaules ? », il les touche du doigt ? Sa compréhension est à son sommet ! Continuez le jeu avec des parties du corps plus difficiles pour enrichir son vocabulaire.', title_hi = 'शरीर विज्ञान की क्लास 👀', body_hi = '''तुम्हारे कंधे कहाँ हैं?'' पूछने पर उँगली से छूकर दिखाता है? उसकी समझ चरम पर है! शरीर के और मुश्किल अंगों के साथ खेल जारी रखिए और उसकी शब्दावली बढ़ाइए।', title_id = 'Pelajaran anatomi 👀', body_id = 'Saat ditanya ''Bahumu di mana?'', ia menyentuh dan menunjukkannya dengan jari? Daya tangkapnya sedang memuncak! Lanjutkan permainan dengan bagian tubuh yang lebih rumit untuk memperkaya kosakatanya.', title_ja = '体のお勉強 👀', body_ja = '「肩はどこ？」と聞くと、指でさわって教えてくれますか？理解力がピークです！もっとむずかしい体の部位で遊びを続けて、語彙を豊かにしましょう。', title_ko = '해부학 수업 👀', body_ko = '''어깨 어디 있어?'' 하고 물으면 손가락으로 짚어 보여 주나요? 이해력이 절정이에요! 더 어려운 신체 부위로 놀이를 이어 가며 어휘를 늘려 주세요.', title_nl = 'Les in anatomie 👀', body_nl = 'Wijst hij zijn schouders aan als je vraagt ''Waar zijn je schouders?'' Zijn begrip is op zijn hoogtepunt! Speel verder met moeilijkere lichaamsdelen en breid zijn woordenschat uit.', title_pl = 'Lekcja anatomii 👀', body_pl = 'Na pytanie „Gdzie masz ramiona?” dotyka ich paluszkiem i pokazuje? Rozumienie jest u szczytu! Kontynuujcie zabawę z trudniejszymi częściami ciała i wzbogacajcie jego słownictwo.', title_pt = 'Aula de anatomia 👀', body_pt = 'Quando pergunta "Onde estão os teus ombros?", toca-lhes e mostra? A compreensão está no auge! Continue o jogo com partes do corpo mais difíceis e enriqueça o vocabulário dele.', title_sv = 'Anatomilektion 👀', body_sv = 'Pekar barnet med fingret när du frågar ”Var är dina axlar?”? Förståelsen är på topp! Fortsätt leken med svårare kroppsdelar och berika ordförrådet.', title_vi = 'Bài học giải phẫu 👀', body_vi = 'Khi mẹ hỏi "Vai con đâu?", bé chạm tay chỉ vào? Khả năng nhận thức đang ở đỉnh cao! Hãy tiếp tục trò chơi với những bộ phận cơ thể phức tạp hơn để làm phong phú vốn từ của bé.', title_zh = '解剖课 👀', body_zh = '问“你的肩膀在哪儿？”，宝宝就用手指碰一碰指给你看？理解能力到了高峰！用更复杂的身体部位继续这个游戏，丰富宝宝的词汇吧。' WHERE id = '32252794-61c5-419d-b7e8-539bc9987fc9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del agua 🛀', body_es = 'Después de correr todo el día, estáis agotados los dos. Durante el baño templado, pon de fondo sonidos relajantes de la naturaleza. La armonía del agua preparará para dormir hasta al niño más tozudo.', title_fr = 'La puissance de l''eau 🛀', body_fr = 'Après avoir couru toute la journée, vous êtes épuisés tous les deux. Pendant le bain tiède, mettez des sons de la nature apaisants en fond. L''harmonie de l''eau préparera au sommeil même l''enfant le plus têtu.', title_hi = 'पानी की ताकत 🛀', body_hi = 'दिनभर भागदौड़ से वह भी थक गया और आप भी। गुनगुने पानी से नहलाते समय पीछे प्रकृति की शांत आवाज़ें चलाइए। पानी का यह सुकून सबसे ज़िद्दी बच्चे को भी नींद के लिए तैयार कर देगा।', title_id = 'Kekuatan air 🛀', body_id = 'Seharian berlarian, ia dan Anda sama-sama kelelahan. Saat mandi air hangat, putar suara alam yang menenangkan di latar belakang. Harmoni air akan menyiapkan anak yang paling keras kepala sekalipun untuk tidur.', title_ja = 'お水の力 🛀', body_ja = '一日じゅう走り回って、ふたりともへとへと。ぬるめのお風呂に入るとき、後ろで落ち着く自然の音を流しましょう。お水のハーモニーが、どんなにがんこな子も眠りへ導きます。', title_ko = '물의 힘 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤죠. 따뜻한 목욕을 할 때 잔잔한 자연의 소리를 틀어 주세요. 물의 조화가 가장 고집스러운 아이도 잠들 준비를 하게 해 줄 거예요.', title_nl = 'De kracht van water 🛀', body_nl = 'Jullie zijn allebei op van een hele dag rennen. Zet tijdens het lauwe bad rustgevende natuurgeluiden op de achtergrond aan. De harmonie van water maakt zelfs het koppigste kind klaar voor de slaap.', title_pl = 'Moc wody 🛀', body_pl = 'Po całym dniu biegania oboje jesteście wykończeni. Podczas ciepłej kąpieli włącz w tle kojące odgłosy natury. Harmonia wody przygotuje do snu nawet najbardziej upartego malucha.', title_pt = 'O poder da água 🛀', body_pt = 'Depois de correrem o dia todo, estão os dois esgotados. Durante o banho morno, ponha sons calmantes da natureza em fundo. A harmonia da água vai preparar para o sono até a criança mais teimosa.', title_sv = 'Vattnets kraft 🛀', body_sv = 'Både du och barnet är helt slut efter en hel dag i farten. Sätt på lugnande naturljud i bakgrunden under det ljumma badet. Vattnets harmoni förbereder även det envisaste barnet för sömn.', title_vi = 'Sức mạnh của nước 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều kiệt sức. Khi bé tắm nước ấm, hãy bật âm thanh thiên nhiên êm dịu phía sau. Sự hòa quyện của nước sẽ giúp cả đứa trẻ bướng bỉnh nhất sẵn sàng đi ngủ.', title_zh = '水的力量 🛀', body_zh = '跑了一整天，宝宝和你都累坏了。洗温水澡时，在背景里放些舒缓的大自然声音。水的和谐连最倔的孩子都能带入睡眠准备。' WHERE id = '520e2a70-086b-4229-864f-4de7f51683ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lo rico está en el plato de mamá 🥣', body_es = '¿Aparta su plato y quiere lo que comes tú? Los niños siempre se fían más de lo que eligen sus padres. Elige en Recetas saludables platos que podáis comer los dos.', title_fr = 'Le délice dans l''assiette de maman 🥣', body_fr = 'Il repousse son assiette pour se jeter sur la vôtre ? Les enfants font toujours davantage confiance aux choix de leurs parents. Choisissez dans les Recettes saines des plats que vous pouvez manger tous les deux.', title_hi = 'माँ की थाली का स्वाद 🥣', body_hi = 'अपनी थाली एक तरफ़ करके आपकी थाली की ओर लपकता है? बच्चे हमेशा माता-पिता की पसंद पर ज़्यादा भरोसा करते हैं। सेहतमंद रेसिपी में ऐसी रेसिपी चुनिए जो आप दोनों खा सकें।', title_id = 'Lezatnya makanan di piring Ibu 🥣', body_id = 'Ia menyingkirkan piringnya sendiri dan menginginkan makanan Anda? Anak selalu lebih percaya pada pilihan orang tuanya. Pilih resep di Resep Sehat yang bisa kalian makan berdua.', title_ja = 'ママのお皿のごちそう 🥣', body_ja = '自分のお皿を押しのけて、あなたが食べているものに手を伸ばしますか？子どもはいつも親が選んだものをより信頼します。「ヘルシーレシピ」で、ふたりで同じものを食べられるレシピを選びましょう。', title_ko = '엄마 접시 속 맛있는 음식 🥣', body_ko = '자기 접시는 밀어내고 엄마가 먹는 걸 탐내나요? 아이들은 늘 부모의 선택을 더 믿어요. 건강한 레시피에서 둘이 함께 먹을 수 있는 메뉴를 골라 보세요.', title_nl = 'Wat op mama''s bord ligt, is lekkerder 🥣', body_nl = 'Schuift hij zijn eigen bord weg en wil hij wat jij eet? Kinderen vertrouwen altijd meer op wat hun ouders kiezen. Kies in Gezonde recepten gerechten die jullie allebei kunnen eten.', title_pl = 'Smak z maminego talerza 🥣', body_pl = 'Odsuwa swój talerz i sięga po to, co jesz ty? Dzieci zawsze bardziej ufają wyborom rodziców. Wybierz w Zdrowych przepisach dania, które możecie jeść oboje.', title_pt = 'O sabor do prato da mãe 🥣', body_pt = 'Afasta o prato dele e quer o que a mãe está a comer? As crianças confiam sempre mais nas escolhas dos pais. Escolha nas Receitas Saudáveis pratos que possam comer os dois.', title_sv = 'Det goda i mammas skål 🥣', body_sv = 'Knuffar barnet undan sin egen tallrik och vill ha det du äter? Barn litar alltid mer på föräldrarnas val. Välj recept i Hälsosamma recept som ni båda kan äta.', title_vi = 'Món ngon trong đĩa của mẹ 🥣', body_vi = 'Bé đẩy đĩa của mình ra và đòi ăn món mẹ đang ăn? Trẻ luôn tin vào lựa chọn của bố mẹ hơn. Hãy chọn trong Công thức lành mạnh những món cả hai mẹ con đều ăn được.', title_zh = '妈妈碗里的美味 🥣', body_zh = '把自己的盘子推到一边，却想吃你碗里的？孩子总是更相信父母的选择。在健康食谱里选些你们俩都能一起吃的菜吧。' WHERE id = '8083b651-9df8-40f8-a78a-23401da54600' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Táctica de paseo ⛅', body_es = 'Al salir de paseo, no te fíes del tiempo y evita que se enfríe. No decidas solo mirando por la ventana: elige con Tiempo y ropa el conjunto más adecuado para el viento de fuera y sal de casa tranquila.', title_fr = 'Tactique de promenade ⛅', body_fr = 'Ne vous laissez pas tromper par le temps et ne le laissez pas prendre froid en promenade. Ne décidez pas en regardant par la fenêtre : avec Météo et tenue, choisissez la tenue la mieux adaptée au vent et sortez sereinement.', title_hi = 'सैर की रणनीति ⛅', body_hi = 'सैर पर जाते समय मौसम के धोखे में आकर उसे ठंड मत लगने दीजिए। सिर्फ़ खिड़की से देखकर फ़ैसला मत कीजिए, मौसम और कपड़े असिस्टेंट से बाहर की हवा के हिसाब से सबसे सही कपड़े चुनिए और आराम से निकलिए।', title_id = 'Taktik jalan-jalan ⛅', body_id = 'Saat jalan-jalan, jangan tertipu cuaca hingga ia kedinginan. Jangan memutuskan hanya dengan melihat dari jendela, tentukan setelan yang paling pas untuk angin di luar dengan alat Cuaca dan Pakaian, lalu keluarlah dengan tenang.', title_ja = 'お散歩の作戦 ⛅', body_ja = 'お散歩のとき、見た目の天気にだまされて体を冷やさないように。窓から見て決めずに、「天気と服装」で外の風にいちばん合うコーディネートを決めて、安心して出かけましょう。', title_ko = '산책 전략 ⛅', body_ko = '산책할 때 날씨에 속아 아이를 춥게 하지 마세요. 창밖만 보고 정하지 말고 날씨와 옷차림 도우미로 바깥바람에 가장 알맞은 옷차림을 정한 뒤 편하게 나가세요.', title_nl = 'Wandeltactiek ⛅', body_nl = 'Laat je niet misleiden door het weer als je gaat wandelen, zodat hij het niet koud krijgt. Beslis niet door uit het raam te kijken, maar kies met Weer en kleding de outfit die het best past bij de wind buiten en ga rustig de deur uit.', title_pl = 'Taktyka na spacer ⛅', body_pl = 'Wychodząc na spacer, nie daj się zwieść pogodzie, żeby go nie przeziębić. Nie decyduj, patrząc przez okno, tylko dobierz w narzędziu Pogoda i ubiór zestaw najlepiej pasujący do wiatru i spokojnie wyjdźcie.', title_pt = 'Tática para o passeio ⛅', body_pt = 'Quando saírem para passear, não se deixe enganar pelo tempo e evite que ele apanhe frio. Não decida só pela janela: escolha no Tempo e Roupa a combinação mais adequada ao vento lá fora e saiam descansados.', title_sv = 'Promenadtaktik ⛅', body_sv = 'Låt dig inte luras av vädret så att barnet fryser på promenaden. Bestäm inte genom att titta ut genom fönstret, välj den klädsel som passar bäst för vinden ute med assistenten Väder och kläder och gå lugnt hemifrån.', title_vi = 'Chiến thuật đi dạo ⛅', body_vi = 'Khi ra ngoài đi dạo, đừng để thời tiết đánh lừa khiến bé bị lạnh. Đừng quyết định chỉ bằng cách nhìn qua cửa sổ, hãy dùng trợ lý Thời tiết và trang phục để chọn cách phối đồ hợp với gió bên ngoài và yên tâm ra khỏi nhà.', title_zh = '散步战术 ⛅', body_zh = '出门散步时，别被天气骗了，让宝宝着凉。别只看窗外做决定，用天气穿衣助手找到最适合外面风力的搭配，安心出门。' WHERE id = '23868e91-8f1b-41db-955e-cd3d4e20a70a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fábrica de melatonina 🌙', body_es = 'Para que se duerma antes, apaga todas las luces extra de la habitación y las pantallas de las tablets. La melatonina solo se produce rápido en un ambiente oscuro y sin tecnología.', title_fr = 'L''usine à mélatonine 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre. La mélatonine n''est sécrétée rapidement que dans le noir, sans technologie.', title_hi = 'मेलाटोनिन की फ़ैक्टरी 🌙', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ अंधेरे और बिना गैजेट वाले माहौल में तेज़ी से बनता है।', title_id = 'Pabrik melatonin 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar. Melatonin hanya diproduksi dengan cepat dalam suasana gelap dan bebas teknologi.', title_ja = 'メラトニン工場 🌙', body_ja = '早く寝つけるように、部屋の余分な明かりとタブレットの画面をすべて消しましょう。メラトニンは、暗くて機器のない環境でこそすばやく分泌されます。', title_ko = '멜라토닌 공장 🌙', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명과 태블릿 화면을 모두 꺼 주세요. 멜라토닌은 어둡고 전자기기 없는 환경에서만 빠르게 분비돼요.', title_nl = 'Melatoninefabriek 🌙', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en tabletschermen in de kamer uit. Melatonine wordt alleen in een donkere omgeving zonder techniek snel aangemaakt.', title_pl = 'Fabryka melatoniny 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina wydziela się szybko tylko w ciemnym otoczeniu bez technologii.', title_pt = 'A fábrica de melatonina 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets. A melatonina só é produzida rapidamente num ambiente escuro e sem tecnologia.', title_sv = 'Melatoninfabriken 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplattornas skärmar i rummet. Melatonin utsöndras snabbt bara i en mörk miljö utan teknik.', title_vi = 'Nhà máy melatonin 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng. Melatonin chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ.', title_zh = '褪黑素工厂 🌙', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光和平板屏幕。褪黑素只有在昏暗、没有电子设备的环境里才会快速分泌。' WHERE id = '418dbea1-2468-4df0-ad94-f76ab3c14a42' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Normas de cortesía 👋', body_es = '¡Cuando alguien se va, dice adiós con la mano por iniciativa propia! Su inteligencia social y su empatía se están formando. Anima mucho estos gestos de cortesía.', title_fr = 'Les règles de politesse 👋', body_fr = 'Quand quelqu''un part, il fait au revoir de la main de lui-même ! Son intelligence sociale et son empathie se forment. Encouragez beaucoup ces réflexes de politesse.', title_hi = 'शिष्टाचार के नियम 👋', body_hi = 'कोई दरवाज़े से बाहर जाए तो खुद ही हाथ हिलाकर अलविदा कहता है! सामाजिक समझ और हमदर्दी बन रही है। उसकी इन शिष्ट आदतों का खूब हौसला बढ़ाइए।', title_id = 'Aturan sopan santun 👋', body_id = 'Saat seseorang pergi, ia melambaikan tangan dan berpamitan atas inisiatifnya sendiri! Kecerdasan sosial dan empatinya sedang terbentuk. Berikan banyak semangat untuk refleks sopannya ini.', title_ja = '礼儀のルール 👋', body_ja = 'だれかが帰るとき、自分から手を振ってバイバイしますか！社会的な知性と思いやりが育っています。この礼儀正しいふるまいを、たくさんほめて励ましましょう。', title_ko = '예절 배우기 👋', body_ko = '누가 문을 나설 때 스스로 손을 흔들며 인사하나요? 사회성과 공감 능력이 자라고 있어요. 이 예의 바른 행동을 듬뿍 칭찬해 주세요.', title_nl = 'Regels van beleefdheid 👋', body_nl = 'Zwaait hij uit zichzelf gedag als iemand de deur uit gaat? Zijn sociale intelligentie en empathie worden gevormd. Moedig deze beleefde reflexen flink aan.', title_pl = 'Zasady grzeczności 👋', body_pl = 'Gdy ktoś wychodzi, z własnej inicjatywy macha na pożegnanie! Kształtują się inteligencja społeczna i empatia. Jak najczęściej zachęcaj go do tych grzecznych odruchów.', title_pt = 'Regras de boas maneiras 👋', body_pt = 'Quando alguém sai pela porta, acena e diz adeus por iniciativa própria! A inteligência social e a empatia estão a formar-se. Incentive muito estes reflexos educados.', title_sv = 'Artighetsregler 👋', body_sv = 'Vinkar barnet hejdå på eget initiativ när någon går ut genom dörren! Social intelligens och empati formas. Uppmuntra de här artiga reflexerna mycket.', title_vi = 'Phép lịch sự 👋', body_vi = 'Khi có người ra về, bé tự vẫy tay chào tạm biệt! Trí tuệ xã hội và sự đồng cảm đang hình thành. Hãy khuyến khích thật nhiều những phản xạ lịch sự này của bé.', title_zh = '礼貌规则 👋', body_zh = '有人出门时，宝宝主动挥手说再见！社交智慧和共情能力正在形成。多多鼓励宝宝这些有礼貌的反应吧。' WHERE id = 'dcb96656-d377-4147-b075-f440d05b3b54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El médico del osito herido 🩺', body_es = '¿Cuando se cae su juguete lo acaricia y le dice «No llores»? ¡Está naciendo en él una empatía asombrosa! Anota ya esta etapa de oro de su personalidad en el Seguimiento del desarrollo.', title_fr = 'Le docteur de l''ourson blessé 🩺', body_fr = 'Quand son jouet tombe, il le caresse en disant « Pleure pas » ? Un sentiment d''empathie étonnant est en train de naître ! Notez tout de suite cette étape en or de sa personnalité dans le Suivi de développement.', title_hi = 'घायल टेडी का डॉक्टर 🩺', body_hi = 'खिलौना गिर जाए तो उसे सहलाता है और कहता है ''मत रो''? उसमें कमाल की हमदर्दी पैदा हो रही है! व्यक्तित्व के इस सुनहरे पड़ाव को तुरंत ग्रोथ ट्रैकर में दर्ज कीजिए।', title_id = 'Dokter si beruang terluka 🩺', body_id = 'Saat mainannya jatuh, ia mengelusnya dan berkata ''Jangan menangis''? Rasa empati yang luar biasa sedang tumbuh! Segera catat tahap emas kepribadiannya ini di Pelacak Perkembangan.', title_ja = 'けがをしたくまさんのお医者さん 🩺', body_ja = 'おもちゃが落ちると、なでながら「泣かないで」と言いますか？すばらしい思いやりの心が育っています！人格のこの黄金の段階を、すぐに「発達トラッカー」に記録しましょう。', title_ko = '다친 곰 인형의 의사 선생님 🩺', body_ko = '장난감이 넘어지면 쓰다듬으며 ''울지 마'' 하나요? 놀라운 공감 능력이 생기고 있어요! 성격 발달의 이 황금 같은 단계를 바로 성장 기록에 남겨 두세요.', title_nl = 'Dokter van het gewonde beertje 🩺', body_nl = 'Aait hij zijn speelgoed als het valt en zegt hij ''Niet huilen''? Er groeit een prachtig gevoel van empathie! Leg deze gouden fase van zijn persoonlijkheid meteen vast in de Groeitracker.', title_pl = 'Lekarz rannego misia 🩺', body_pl = 'Gdy zabawka upadnie, głaszcze ją i mówi „Nie płacz”? Rodzi się w nim niesamowita empatia! Od razu zapisz ten złoty etap rozwoju osobowości w Śledzeniu rozwoju.', title_pt = 'O médico do ursinho ferido 🩺', body_pt = 'Quando o brinquedo cai, faz-lhe festas e diz "Não chores"? Está a nascer nele uma empatia espantosa! Registe já esta etapa de ouro da personalidade no Registo de Desenvolvimento.', title_sv = 'Den skadade nallens doktor 🩺', body_sv = 'Klappar barnet leksaken när den ramlar och säger ”Gråt inte”? En fantastisk empati håller på att växa fram! Anteckna direkt den här gyllene fasen i personligheten i Utvecklingsspåraren.', title_vi = 'Bác sĩ của chú gấu bị thương 🩺', body_vi = 'Khi đồ chơi bị ngã, bé vuốt ve và nói "Đừng khóc nhé"? Một sự đồng cảm tuyệt vời đang hình thành! Hãy ghi ngay giai đoạn vàng này của sự phát triển nhân cách vào Theo dõi phát triển.', title_zh = '受伤小熊的医生 🩺', body_zh = '玩具摔倒了，就摸摸它说“不哭”？宝宝产生了惊人的共情能力！马上把个性发展的这个黄金阶段记进发育追踪里。' WHERE id = '181acf25-f33b-4b1f-a3df-4084c1837a73' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Invitación a la melatonina 🌙', body_es = 'Para que se duerma antes, apaga todas las luces extra y las pantallas azules de la habitación. La hormona del sueño (melatonina) solo se produce rápido en un ambiente oscuro y sin tecnología.', title_fr = 'Invitation à la mélatonine 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans bleus de la chambre. L''hormone du sommeil (mélatonine) n''est sécrétée rapidement que dans le noir, sans technologie.', title_hi = 'मेलाटोनिन को न्योता 🌙', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और नीली स्क्रीन बंद कर दीजिए। नींद का हार्मोन (मेलाटोनिन) सिर्फ़ अंधेरे और बिना गैजेट वाले माहौल में तेज़ी से बनता है।', title_id = 'Mengundang melatonin 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar biru di kamar. Hormon tidur (melatonin) hanya diproduksi dengan cepat dalam suasana gelap dan bebas teknologi.', title_ja = 'メラトニンを呼びこもう 🌙', body_ja = '早く寝つけるように、部屋の余分な明かりと青い光の画面をすべて消しましょう。眠りのホルモン（メラトニン）は、暗くて機器のない環境でこそすばやく分泌されます。', title_ko = '멜라토닌을 부르는 시간 🌙', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명과 블루라이트 화면을 모두 꺼 주세요. 수면 호르몬(멜라토닌)은 어둡고 전자기기 없는 환경에서만 빠르게 분비돼요.', title_nl = 'Een uitnodiging voor melatonine 🌙', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en blauwe schermen in de kamer uit. Het slaaphormoon (melatonine) wordt alleen in een donkere omgeving zonder techniek snel aangemaakt.', title_pl = 'Zaproszenie dla melatoniny 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i niebieskie ekrany. Hormon snu (melatonina) wydziela się szybko tylko w ciemnym otoczeniu bez technologii.', title_pt = 'Um convite à melatonina 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs azuis. A hormona do sono (melatonina) só é produzida rapidamente num ambiente escuro e sem tecnologia.', title_sv = 'Inbjudan till melatoninet 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och blå skärmar i rummet. Sömnhormonet (melatonin) utsöndras snabbt bara i en mörk miljö utan teknik.', title_vi = 'Mời melatonin đến 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình ánh sáng xanh trong phòng. Hormone giấc ngủ (melatonin) chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ.', title_zh = '邀请褪黑素 🌙', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光和发蓝光的屏幕。睡眠激素（褪黑素）只有在昏暗、没有电子设备的环境里才会快速分泌。' WHERE id = '41b6bff2-f792-4d2c-a887-2fbdd7ee533a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Política en el arenero 🧸', body_es = '¿En el parque no le deja su cubo a nadie? No es egoísmo, solo está descubriendo el sentido de la propiedad. Sin avergonzarle, propón un sistema de turnos y resuelve la crisis diplomática.', title_fr = 'Diplomatie du bac à sable 🧸', body_fr = 'Au parc, il ne prête son seau à personne ? Ce n''est pas de l''égoïsme, il découvre simplement la notion de propriété. Sans lui faire honte, proposez un tour de rôle pour régler cette crise diplomatique.', title_hi = 'सैंडपिट की राजनीति 🧸', body_hi = 'पार्क में अपनी बाल्टी किसी को नहीं देता? यह स्वार्थ नहीं, बस ''मेरा'' की समझ की खोज है। उसे शर्मिंदा किए बिना बारी का तरीका सुझाइए और इस कूटनीतिक संकट को सुलझाइए।', title_id = 'Politik bak pasir 🧸', body_id = 'Di taman ia tidak mau meminjamkan embernya kepada siapa pun? Ini bukan egois, ia hanya sedang mengenal rasa kepemilikan. Tanpa mempermalukannya, tawarkan sistem bergiliran dan selesaikan krisis diplomatik ini.', title_ja = '砂場の政治学 🧸', body_ja = '公園でバケツをだれにも渡さない？これはわがままではなく、「自分のもの」という感覚の発見です。恥ずかしい思いをさせずに順番制を提案して、外交危機を解決しましょう。', title_ko = '모래놀이터의 정치 🧸', body_ko = '공원에서 양동이를 아무에게도 안 주나요? 이기심이 아니라 ''내 것''이라는 개념을 발견한 거예요. 부끄럽게 만들지 말고 순서를 정하자고 제안해 외교 위기를 해결해 주세요.', title_nl = 'Politiek in de zandbak 🧸', body_nl = 'Geeft hij in het park zijn emmertje aan niemand? Dat is geen egoïsme, maar de ontdekking van persoonlijk bezit. Stel zonder hem te beschamen een beurtensysteem voor en los de diplomatieke crisis op.', title_pl = 'Polityka piaskownicy 🧸', body_pl = 'Nikomu nie daje w parku swojego wiaderka? To nie egoizm, tylko odkrywanie poczucia własności. Nie zawstydzając go, zaproponuj zabawę po kolei i rozwiąż ten dyplomatyczny kryzys.', title_pt = 'A política do parque de areia 🧸', body_pt = 'No parque, não empresta o balde a ninguém? Não é egoísmo, é apenas a descoberta da noção de posse. Sem o envergonhar, proponha brincar à vez e resolva a crise diplomática.', title_sv = 'Sandlådepolitik 🧸', body_sv = 'Vill barnet inte låna ut sin hink till någon i parken? Det är inte egoism, barnet upptäcker bara känslan av personlig ägodel. Föreslå turordning utan att skämma ut hen och lös den diplomatiska krisen.', title_vi = 'Chính sách khu chơi cát 🧸', body_vi = 'Ở công viên bé không cho ai mượn xô? Đây không phải ích kỷ mà chỉ là bé đang khám phá cảm giác sở hữu cá nhân. Hãy gợi ý chơi lần lượt mà không làm bé xấu hổ để giải quyết "khủng hoảng ngoại giao" này.', title_zh = '沙坑里的规矩 🧸', body_zh = '在公园里不肯把小桶给任何人？这不是自私，只是发现了“我的东西”的感觉。别让宝宝难堪，提议轮流玩，化解这场“外交危机”。' WHERE id = 'afdd5971-fffc-43af-9956-3bc9d2687359' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Limpieza en equipo 🧹', body_es = '¿Toca recoger la casa? Mientras barres, deja que te ayude pasando un trapo. Lee en el Blog cómo convertir la limpieza en trabajo en equipo y diversión.', title_fr = 'Le ménage ensemble 🧹', body_fr = 'Il faut ranger la maison ? Quand vous balayez, laissez-le vous aider avec un chiffon. Lisez dans les Blogs comment faire du ménage un travail d''équipe et un jeu.', title_hi = 'साथ मिलकर सफ़ाई 🧹', body_hi = 'घर समेटना है? जब आप झाड़ू लगाएँ, तो उसे भी कपड़े से पोंछकर मदद करने दीजिए। सफ़ाई को टीम वर्क और मज़े में बदलने के तरीके ब्लॉग में पढ़िए।', title_id = 'Bersih-bersih bersama 🧹', body_id = 'Rumah perlu dirapikan? Saat Anda menyapu kamar, biarkan ia membantu mengelap dengan kain. Baca di bagian Blog cara mengubah bersih-bersih menjadi kerja tim dan keseruan.', title_ja = '一緒にお掃除 🧹', body_ja = '家の片づけをしなきゃ？部屋をはいているとき、お子さんにもぞうきんでふいて手伝ってもらいましょう。お掃除をチームワークと遊びに変える方法を、ブログで読んでみて。', title_ko = '함께하는 청소 🧹', body_ko = '집을 정리해야 하나요? 엄마가 방을 쓸 때 아이도 걸레로 닦으며 돕게 해 주세요. 청소를 팀워크와 놀이로 바꾸는 방법을 블로그에서 읽어 보세요.', title_nl = 'Samen schoonmaken 🧹', body_nl = 'Moet het huis opgeruimd? Laat hem met een doekje meehelpen als jij de kamer veegt. Lees in Blogs hoe je van schoonmaken teamwerk en plezier maakt.', title_pl = 'Wspólne sprzątanie 🧹', body_pl = 'Trzeba posprzątać dom? Gdy zamiatasz pokój, pozwól mu pomóc, przecierając ściereczką. Przeczytaj na Blogu, jak zamienić sprzątanie w pracę zespołową i zabawę.', title_pt = 'Limpezas a dois 🧹', body_pt = 'É preciso arrumar a casa? Enquanto varre o quarto, deixe-o ajudar a limpar com um pano. Leia no Blogue como transformar a limpeza em trabalho de equipa e diversão.', title_sv = 'Städning tillsammans 🧹', body_sv = 'Behöver hemmet städas? Låt barnet hjälpa till att torka med en trasa när du sopar. Läs i Bloggar hur ni gör städningen till lagarbete och nöje.', title_vi = 'Cùng nhau dọn dẹp 🧹', body_vi = 'Cần dọn nhà? Khi mẹ quét phòng, hãy để bé lấy khăn lau giúp mẹ. Đọc trong mục Blog cách biến việc dọn dẹp thành công việc của cả đội và niềm vui.', title_zh = '一起打扫 🧹', body_zh = '家里该收拾了？你扫地时，让宝宝拿抹布擦擦，帮你的忙。去博客里读读怎样把打扫变成团队合作和乐趣。' WHERE id = '32e0ad68-9613-493b-b8b0-dc5729e770dd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se descoloca la rutina? ⏱️', body_es = '¿Le cuesta mucho dormirse por la noche? Mira el gráfico del temporizador de sueño. Quizá hace tiempo que toca acortar del todo la siesta y adelantar la hora de dormir.', title_fr = 'Le rythme se décale ? ⏱️', body_fr = 'L''endormissement du soir s''éternise ? Regardez le graphique du Minuteur de sommeil. Il est peut-être grand temps de raccourcir nettement la sieste et d''avancer l''heure du coucher.', title_hi = 'रूटीन खिसक रहा है? ⏱️', body_hi = 'शाम को सोने में बहुत देर लगती है? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद को और छोटा करने और शाम का रूटीन जल्दी करने का समय कब का आ चुका है।', title_id = 'Rutinitas bergeser? ⏱️', body_id = 'Tidur malam butuh waktu terlalu lama? Lihat grafik Timer Tidur. Mungkin sudah lama tiba waktunya memangkas tidur siang dan memajukan jam tidur malam.', title_ja = '生活リズムがずれている？⏱️', body_ja = '夜の寝かしつけに時間がかかりすぎますか？睡眠タイマーのグラフを見てみましょう。お昼寝を短くして、夜の寝る時間を早める時期がとっくに来ているのかもしれません。', title_ko = '일과가 밀리나요? ⏱️', body_ko = '저녁에 잠드는 데 너무 오래 걸리나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 확 줄이고 잠자리 시간을 앞당길 때가 진작 되었을지도 몰라요.', title_nl = 'Verschuift het ritme? ⏱️', body_nl = 'Duurt inslapen ''s avonds erg lang? Bekijk het schema in de Slaaptimer. Misschien is het allang tijd om het middagslaapje flink in te korten en de avond te vervroegen.', title_pl = 'Rytm dnia się przesuwa? ⏱️', body_pl = 'Wieczorne zasypianie bardzo się przeciąga? Spójrz na wykres w timerze snu. Może już dawno czas skrócić drzemkę w ciągu dnia i przesunąć wieczór na wcześniej.', title_pt = 'A rotina está a fugir? ⏱️', body_pt = 'Adormecer à noite demora demasiado? Veja o gráfico do temporizador de sono. Talvez já tenha passado a altura de encurtar de vez a sesta e antecipar a hora de deitar.', title_sv = 'Glider rutinen iväg? ⏱️', body_sv = 'Tar det väldigt lång tid för barnet att somna på kvällen? Titta på sömntimerns diagram. Kanske är det sedan länge dags att korta dagsömnen ordentligt och tidigarelägga kvällen.', title_vi = 'Nếp sinh hoạt bị lệch? ⏱️', body_vi = 'Buổi tối bé mất quá lâu mới ngủ được? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đã đến lúc rút ngắn hẳn giấc ngủ ngày và cho bé đi ngủ tối sớm hơn.', title_zh = '作息乱了？⏱️', body_zh = '晚上入睡要花很久？看看睡眠计时器的图表。也许早就该把白天的午睡大大缩短，把晚上的入睡时间提前了。' WHERE id = 'a3a1222f-3b9a-40aa-a53c-50cc656ba7c7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tozudez del «¡Soy mayor!» 🛑', body_es = '¿Quiere meterse en todo y todo va más lento? En esta divertida guerra por la independencia, dale pequeñas opciones para elegir.', title_fr = 'L''entêtement du « Je suis grand ! » 🛑', body_fr = 'Il veut se mêler de tout et ça ralentit tout ? Dans cette comique bataille pour l''indépendance, proposez-lui de petits choix.', title_hi = '''मैं बड़ा हूँ!'' वाली ज़िद 🛑', body_hi = 'हर चीज़ में दखल देना चाहता है और काम धीमे कर देता है? आज़ादी की इस मज़ेदार जंग में उसे छोटे-छोटे विकल्प दीजिए।', title_id = 'Keras kepala ''Aku sudah besar!'' 🛑', body_id = 'Ia ingin ikut campur dalam segala hal dan semuanya jadi lambat? Dalam perang kemandirian yang lucu ini, beri ia pilihan-pilihan kecil.', title_ja = '「ぼく、大きいもん！」のがんばり 🛑', body_ja = 'なんにでも口や手を出して、時間がかかってしまう？このおもしろい自立の戦いでは、小さな選択肢を与えてあげましょう。', title_ko = '''나 다 컸어!'' 고집 🛑', body_ko = '모든 일에 끼어들어 시간이 오래 걸리나요? 이 귀여운 독립 전쟁에서는 작은 선택지를 주세요.', title_nl = 'Koppig: ''Ik ben groot!'' 🛑', body_nl = 'Wil hij zich met alles bemoeien en duurt alles daardoor langer? Geef hem in deze grappige strijd om zelfstandigheid kleine keuzes.', title_pl = 'Upór „Jestem duży!” 🛑', body_pl = 'Chce się wtrącać we wszystko i wszystko się przeciąga? W tej zabawnej walce o samodzielność dawaj mu małe wybory.', title_pt = 'A teimosia do "Eu sou grande!" 🛑', body_pt = 'Quer meter-se em tudo e atrasa as coisas? Nesta guerra cómica pela independência, dê-lhe pequenas escolhas.', title_sv = 'Envisheten i ”Jag är stor!” 🛑', body_sv = 'Vill barnet lägga sig i allt och saktar ner allting? Ge barnet små val i den här komiska kampen för självständighet.', title_vi = 'Sự bướng bỉnh "Con lớn rồi!" 🛑', body_vi = 'Bé muốn can thiệp vào mọi việc khiến mọi thứ chậm lại? Trong cuộc chiến giành độc lập ngộ nghĩnh này, hãy cho bé những lựa chọn nhỏ.', title_zh = '“我长大了！”的倔强 🛑', body_zh = '什么都想插手，事情越做越慢？在这场搞笑的独立之战里，给宝宝一些小小的选择吧。' WHERE id = 'ee3cf122-8fc4-43ea-906b-ef2165dd428d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El milagro de los 1000 días! 👑', body_es = '¡ENHORABUENA! ¡Llevas exactamente 1000 días recorriendo este camino tormentoso y agotador, pero el más valioso del mundo! Celebra ya este día de victoria tan especial y compártelo con orgullo en la Comunidad Anacan.', title_fr = 'Le miracle des 1000 jours ! 👑', body_fr = 'FÉLICITATIONS ! Cela fait exactement 1000 jours que vous parcourez ce chemin tumultueux, épuisant, mais le plus précieux du monde ! Fêtez vite cette journée de victoire et partagez-la fièrement dans la Communauté Anacan !', title_hi = '1000 दिनों का चमत्कार! 👑', body_hi = 'बधाई हो! आप पूरे 1000 दिनों से इस तूफ़ानी, थका देने वाले, लेकिन दुनिया के सबसे कीमती सफ़र पर चल रही हैं! इस खास जीत के दिन का तुरंत जश्न मनाइए और Anacan कम्युनिटी में गर्व से साझा कीजिए!', title_id = 'Keajaiban 1000 hari! 👑', body_id = 'SELAMAT! Sudah tepat 1000 hari Anda menempuh perjalanan yang penuh badai dan melelahkan, namun paling berharga di dunia ini! Segera rayakan hari kemenangan istimewa ini dan bagikan dengan bangga di Komunitas Anacan!', title_ja = '1000日の奇跡！👑', body_ja = 'おめでとうございます！嵐のようで、くたくたになるけれど、世界でいちばん尊い道のりを、ちょうど1000日歩んできました！この特別な勝利の日をすぐにお祝いして、Anacanコミュニティで誇らしくシェアしましょう！', title_ko = '1000일의 기적! 👑', body_ko = '축하해요! 꼬박 1000일 동안 이 폭풍 같고 고단하지만 세상에서 가장 소중한 길을 걸어왔어요! 지금 바로 이 특별한 승리의 날을 축하하고 Anacan 커뮤니티에 자랑스럽게 나눠 보세요!', title_nl = 'Het wonder van 1000 dagen! 👑', body_nl = 'GEFELICITEERD! Al precies 1000 dagen loop je deze stormachtige, vermoeiende, maar waardevolste weg ter wereld! Vier deze bijzondere overwinningsdag meteen en deel hem trots in de Anacan Community!', title_pl = 'Cud 1000 dni! 👑', body_pl = 'GRATULACJE! Od równych 1000 dni idziesz tą burzliwą, męczącą, ale najcenniejszą drogą na świecie! Od razu uczcij ten wyjątkowy dzień zwycięstwa i z dumą podziel się nim w Społeczności Anacan!', title_pt = 'O milagre dos 1000 dias! 👑', body_pt = 'PARABÉNS! Há exatamente 1000 dias que percorre este caminho tempestuoso, cansativo, mas o mais precioso do mundo! Celebre já este dia especial de vitória e partilhe-o com orgulho na Comunidade Anacan!', title_sv = '1000 dagars mirakel! 👑', body_sv = 'GRATTIS! I precis 1000 dagar har du gått den här stormiga, tröttsamma men mest värdefulla vägen i världen! Fira den här speciella segerdagen direkt och dela den stolt i Anacan Community!', title_vi = 'Điều kỳ diệu 1000 ngày! 👑', body_vi = 'CHÚC MỪNG! Mẹ đã đi trọn 1000 ngày trên con đường đầy giông bão, mệt mỏi nhưng quý giá nhất thế gian! Hãy ăn mừng ngay ngày chiến thắng đặc biệt này và tự hào chia sẻ trong Cộng đồng Anacan!', title_zh = '1000天的奇迹！👑', body_zh = '恭喜你！这条风风雨雨、让人疲惫，却是世界上最珍贵的路，你已经整整走了1000天！马上庆祝这个特别的胜利日，骄傲地分享到Anacan社区吧！' WHERE id = '98562e83-4876-4c00-8dbc-2ad2897e54b5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El baile de la victoria del equipo 🥂', body_es = 'Esta noche celebra con tu pareja el cansancio, las lágrimas y la alegría de 1000 días. Poned una vela en la mesa y aplaudid con mucha alegría la victoria de vuestro equipo inquebrantable.', title_fr = 'La danse de la victoire de l''équipe 🥂', body_fr = 'Ce soir, célébrez avec votre partenaire 1000 jours de fatigue, de larmes et de joie. Allumez une bougie sur la table et applaudissez avec bonheur la victoire de votre équipe inébranlable !', title_hi = 'टीम का जीत वाला डांस 🥂', body_hi = 'आज शाम 1000 दिनों की थकान, आँसू और खुशियाँ अपने पार्टनर के साथ मिलकर मनाइए। मेज़ पर एक मोमबत्ती जलाइए और अपनी अटूट टीम की जीत पर खूब खुशी से तालियाँ बजाइए!', title_id = 'Tarian kemenangan tim 🥂', body_id = 'Malam ini rayakan lelah, air mata, dan kebahagiaan 1000 hari bersama pasangan. Nyalakan lilin di meja dan sambut kemenangan tim kalian yang tak tergoyahkan dengan penuh sukacita!', title_ja = 'チームの勝利のダンス 🥂', body_ja = '1000日分の疲れも涙もよろこびも、今夜はパートナーと一緒にお祝いしましょう。食卓にキャンドルを置いて、揺るがないチームの勝利に大きなよろこびで拍手を！', title_ko = '팀의 승리 춤 🥂', body_ko = '오늘 저녁 1000일의 피로와 눈물, 기쁨을 배우자와 함께 기념하세요. 식탁에 초를 켜고 흔들림 없는 팀의 승리에 큰 박수를 보내세요!', title_nl = 'Overwinningsdans van het team 🥂', body_nl = 'Vier vanavond samen met je partner de vermoeidheid, tranen en vreugde van 1000 dagen. Zet een kaars op tafel en juich jullie onbreekbare teamoverwinning met grote blijdschap toe!', title_pl = 'Taniec zwycięstwa drużyny 🥂', body_pl = 'Uczcij dziś wieczorem z partnerem zmęczenie, łzy i radość 1000 dni. Postaw na stole świecę i z wielką radością oklaskujcie zwycięstwo waszej niezniszczalnej drużyny!', title_pt = 'A dança da vitória da equipa 🥂', body_pt = 'Esta noite, celebre com o seu companheiro o cansaço, as lágrimas e a alegria de 1000 dias. Acendam uma vela na mesa e aplaudam com muita alegria a vitória da vossa equipa inabalável!', title_sv = 'Lagets segerdans 🥂', body_sv = 'Fira de 1000 dagarnas trötthet, tårar och glädje tillsammans med din partner i kväll. Tänd ett ljus på bordet och applådera er orubbliga seger som team med stor glädje!', title_vi = 'Điệu nhảy chiến thắng của cả đội 🥂', body_vi = 'Tối nay hãy cùng chồng kỷ niệm 1000 ngày mệt mỏi, nước mắt và niềm vui. Đặt một ngọn nến lên bàn và hân hoan vỗ tay cho chiến thắng của đội không gì lay chuyển được của hai người!', title_zh = '团队的胜利之舞 🥂', body_zh = '今晚和另一半一起庆祝这1000天的疲惫、泪水和欢乐吧。在餐桌上点一支蜡烛，满怀喜悦地为你们坚不可摧的团队胜利鼓掌！' WHERE id = 'c186b66b-55e3-4f3f-9de6-a20601b6d88b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo has conseguido! 📈', body_es = '¡Cuánto camino ha recorrido tu peque! El miedo frágil de los primeros días ha dado paso a una confianza enorme. ¡Has llegado a estos 1000 días con mucho orgullo! ¡Eres realmente increíble!', title_fr = 'Vous l''avez fait ! 📈', body_fr = 'Quel chemin votre enfant a parcouru ! La peur fragile des premiers jours a laissé place à une immense confiance. Vous avez traversé ces 1000 jours avec une grande fierté ! Vous êtes vraiment formidable !', title_hi = 'आपने कर दिखाया! 📈', body_hi = 'आपके बच्चे ने कितना लंबा सफ़र तय किया है! शुरुआती दिनों का वह नाज़ुक डर अब बड़े भरोसे में बदल गया है। आपने ये 1000 दिन बड़े गर्व से पूरे किए! आप सच में कमाल हैं!', title_id = 'Anda berhasil! 📈', body_id = 'Lihat betapa jauh perjalanan anak Anda! Rasa takut yang rapuh di hari-hari pertama kini berganti dengan keyakinan yang besar. Anda melewati 1000 hari ini dengan penuh kebanggaan! Anda sungguh luar biasa!', title_ja = 'あなたはやりとげました！📈', body_ja = 'お子さんはこんなに成長しました！はじめのころの心細いこわさは、今では大きな自信に変わりました。あなたはこの1000日を誇りをもって歩んできたのです！本当にすばらしいママです！', title_ko = '해냈어요! 📈', body_ko = '아이가 얼마나 먼 길을 왔는지 보세요! 첫날들의 여린 두려움은 이제 커다란 자신감으로 바뀌었어요. 엄마는 이 1000일을 자랑스럽게 걸어왔어요! 정말 멋진 엄마예요!', title_nl = 'Het is je gelukt! 📈', body_nl = 'Wat heeft je kind een weg afgelegd! De breekbare angst van de eerste dagen heeft plaatsgemaakt voor een enorm vertrouwen. Je hebt deze 1000 dagen met grote trots doorlopen! Je bent echt geweldig!', title_pl = 'Dałaś radę! 📈', body_pl = 'Jaką drogę przeszło twoje dziecko! Kruchy strach pierwszych dni ustąpił miejsca ogromnej pewności. Przeszłaś te 1000 dni z wielką dumą! Jesteś naprawdę wspaniała!', title_pt = 'Conseguiu! 📈', body_pt = 'Que caminho o seu filho já percorreu! O medo frágil dos primeiros dias deu lugar a uma enorme confiança. Chegou a estes 1000 dias com muito orgulho! É mesmo fantástica!', title_sv = 'Du klarade det! 📈', body_sv = 'Vilken resa barnet har gjort! Den sköra rädslan från de första dagarna har nu ersatts av en enorm tilltro. Du har klarat de här 1000 dagarna med stor stolthet! Du är verkligen fantastisk!', title_vi = 'Mẹ đã làm được! 📈', body_vi = 'Bé đã đi được một chặng đường dài biết bao! Nỗi sợ mong manh của những ngày đầu giờ đã nhường chỗ cho niềm tin lớn lao. Mẹ đã đi qua 1000 ngày này với niềm tự hào lớn! Mẹ thật sự tuyệt vời!', title_zh = '你做到了！📈', body_zh = '你的孩子已经走了这么远！最初那些日子里脆弱的恐惧，如今已变成了巨大的信心。你骄傲地走过了这1000天！你真的很了不起！' WHERE id = 'f26096f7-035d-44ff-ad7c-b1f1eaade001' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No hace falta ningún juego, libro ni cuento. Esta noche simplemente abrázale contra tu pecho, respira su olor tan rico y susúrrale en la oscuridad lo valioso que es para ti.', body_fr = 'Pas besoin de jeu, de livre ni de conte. Ce soir, serrez-le simplement contre vous, respirez sa délicieuse odeur et chuchotez-lui dans le noir combien il est précieux.', body_hi = 'किसी खेल, किताब या कहानी की ज़रूरत नहीं। आज शाम बस उसे सीने से लगाइए, उसकी प्यारी खुशबू महसूस कीजिए और अंधेरे में फुसफुसाकर बताइए कि वह आपके लिए कितना कीमती है।', body_id = 'Tidak perlu permainan, buku, atau dongeng. Malam ini cukup dekap ia di dada, hirup aroma indahnya, dan bisikkan dalam gelap betapa berharganya ia bagi Anda.', body_ja = '遊びも絵本もお話もいりません。今夜はただ胸に抱きしめて、そのいいにおいを深く吸いこみ、暗やみの中でどれほど大切な存在かをささやいてあげましょう。', body_ko = '오늘 밤엔 놀이도, 책도, 동화도 필요 없어요. 그냥 꼭 끌어안고 그 사랑스러운 냄새를 깊이 들이마신 뒤, 어둠 속에서 얼마나 소중한 존재인지 속삭여 주세요.', body_nl = 'Je hebt geen spelletje, boek of sprookje nodig. Druk hem vanavond gewoon tegen je borst, snuif zijn heerlijke geurtje op en fluister in het donker hoe dierbaar hij voor je is.', body_pl = 'Nie potrzeba żadnej zabawy, książki ani bajki. Dziś wieczorem po prostu przytul go mocno do piersi, wdychaj jego cudowny zapach i szepnij w ciemności, jak bardzo jest dla ciebie cenny.', body_pt = 'Não precisa de jogos, livros nem histórias. Esta noite, simplesmente aperte-o contra o peito, respire aquele cheiro maravilhoso e sussurre-lhe no escuro o quanto é precioso.', body_sv = 'Inga lekar, böcker eller sagor behövs. I kväll, håll bara barnet tätt intill dig, andas in den underbara doften och viska i mörkret hur värdefull hen är.', body_vi = 'Không cần trò chơi, sách vở hay truyện cổ tích. Tối nay chỉ cần ôm bé vào lòng, hít hà mùi hương thơm tho của bé và thì thầm trong bóng tối rằng bé quý giá với mẹ biết bao.', body_zh = '不需要任何游戏、书或故事。今晚就把宝宝紧紧抱在怀里，深深闻一闻那好闻的味道，在黑暗中轻声告诉宝宝，宝宝对你有多珍贵。' WHERE id = '0953ad75-dec1-4dc2-9d50-5eb074aad008' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Balance en el diario 📝', body_es = 'Cuando tu peque duerma, abre el Diario de ánimo. ¿Qué es lo que más te ha cansado hoy y qué te ha hecho reír? Suelta tus emociones con total libertad y vacía la mente.', title_fr = 'Le bilan dans le journal 📝', body_fr = 'Quand il dort, ouvrez le Journal d''humeur. Qu''est-ce qui vous a le plus fatiguée aujourd''hui, qu''est-ce qui vous a fait rire ? Laissez complètement libre cours à vos émotions et videz-vous la tête.', title_hi = 'डायरी में हिसाब 📝', body_hi = 'बच्चे के सोने के बाद मूड डायरी खोलिए। आज किस बात ने आपको सबसे ज़्यादा थकाया, किसने हँसाया? अपनी भावनाओं को पूरी तरह खुला छोड़िए और मन हल्का कीजिए।', title_id = 'Laporan di buku harian 📝', body_id = 'Setelah anak tidur, buka Buku Harian Suasana Hati. Apa yang paling melelahkan dan apa yang paling membuat Anda tertawa hari ini? Lepaskan perasaan Anda sebebas-bebasnya dan lapangkan hati.', title_ja = '日記で振り返り 📝', body_ja = 'お子さんが眠ったら「気分日記」を開きましょう。今日いちばん疲れたことは？笑ったことは？自分の気持ちを自由に書き出して、心をすっきりさせましょう。', title_ko = '일기에 남기는 하루 보고 📝', body_ko = '아이가 잠들면 기분 일기를 열어 보세요. 오늘 무엇이 가장 힘들었고, 무엇이 웃게 했나요? 감정을 자유롭게 풀어놓고 마음을 비우세요.', title_nl = 'Verslag in je dagboek 📝', body_nl = 'Open je Stemmingsdagboek als hij slaapt. Wat maakte je vandaag het meest moe, waar moest je om lachen? Laat je gevoelens helemaal de vrije loop en lucht je hart.', title_pl = 'Raport w dzienniku 📝', body_pl = 'Gdy dziecko zaśnie, otwórz Dziennik nastroju. Co dziś najbardziej cię zmęczyło, a co rozśmieszyło? Daj swoim uczuciom pełną swobodę i oczyść głowę.', title_pt = 'Relatório no diário 📝', body_pt = 'Depois de a criança adormecer, abra o Diário de Humor. O que a cansou mais hoje e o que a fez rir? Deixe sair livremente o que sente e alivie o coração.', title_sv = 'Rapport i dagboken 📝', body_sv = 'Öppna Humördagboken när barnet har somnat. Vad tröttade ut dig mest i dag, vad fick dig att skratta? Släpp fram dina känslor helt fritt och rensa själen.', title_vi = 'Báo cáo trong nhật ký 📝', body_vi = 'Khi bé đã ngủ, hãy mở Nhật ký tâm trạng. Hôm nay điều gì khiến mẹ mệt nhất, điều gì khiến mẹ cười? Hãy để cảm xúc tự do tuôn chảy và giải tỏa lòng mình.', title_zh = '写进日记里的总结 📝', body_zh = '孩子睡着后，打开心情日记。今天什么最让你累，什么让你笑了？把感受完全释放出来，让心里清爽一下。' WHERE id = '5cf4179d-ca05-4825-ae51-8ae8bda4be3e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La realidad después de la victoria 🚀', body_es = '¡Después de la celebración de ayer, esta mañana nos hemos vuelto a despertar entre juguetes tirados y «¡No quiero!»! La vida sigue. Respira hondo: eres la mejor gestora de este caos.', title_fr = 'La réalité après la victoire 🚀', body_fr = 'Après la fête d''hier, ce matin, on s''est encore réveillés au milieu des jouets éparpillés et des « Je veux pas ! » ! La vie continue. Respirez profondément, vous êtes la meilleure cheffe de ce joyeux chaos.', title_hi = 'जीत के बाद की सच्चाई 🚀', body_hi = 'कल के जश्न के बाद आज सुबह फिर बिखरे खिलौनों और ''मुझे नहीं चाहिए!'' के साथ आँख खुली! ज़िंदगी चलती रहती है। गहरी साँस लीजिए, आप इस अफ़रा-तफ़री की सबसे बेहतरीन मैनेजर हैं।', title_id = 'Kenyataan setelah kemenangan 🚀', body_id = 'Setelah perayaan kemarin, pagi ini kita kembali bangun disambut mainan berserakan dan ''Aku tidak mau!'' Hidup terus berjalan. Tarik napas dalam, Andalah pengelola terbaik kekacauan ini.', title_ja = 'お祝いのあとの現実 🚀', body_ja = '昨日の記念日のあと、今朝もまた散らかったおもちゃと「いやだ！」で目が覚めました！毎日は続きます。深呼吸しましょう、あなたはこの大混乱のいちばんすてきなリーダーです。', title_ko = '승리 뒤의 현실 🚀', body_ko = '어제 기념일을 보내고 오늘 아침 다시 흩어진 장난감과 ''싫어!''로 눈을 떴죠! 삶은 계속돼요. 깊게 숨 쉬세요. 엄마는 이 혼돈을 가장 멋지게 이끄는 사람이에요.', title_nl = 'De realiteit na de overwinning 🚀', body_nl = 'Na het jubileum van gisteren werden we vanochtend weer wakker tussen het rondslingerende speelgoed en de ''Ik wil niet!''s! Het leven gaat door. Haal diep adem, jij bent de beste manager van deze chaos.', title_pl = 'Rzeczywistość po zwycięstwie 🚀', body_pl = 'Po wczorajszym jubileuszu dziś rano znów obudziliśmy się wśród rozrzuconych zabawek i okrzyków „Nie chcę!”. Życie toczy się dalej. Weź głęboki oddech, jesteś najlepszą menedżerką tego chaosu.', title_pt = 'A realidade depois da vitória 🚀', body_pt = 'Depois da festa de ontem, esta manhã acordámos outra vez com brinquedos espalhados e muitos "Não quero!". A vida continua. Respire fundo: é a melhor gestora deste caos.', title_sv = 'Verkligheten efter segern 🚀', body_sv = 'Efter gårdagens jubileum vaknade vi i morse återigen till utspridda leksaker och ”Jag vill inte!”! Livet går vidare. Andas djupt, du är den bästa ledaren för det här kaoset.', title_vi = 'Thực tế sau chiến thắng 🚀', body_vi = 'Sau lễ kỷ niệm hôm qua, sáng nay mình lại thức dậy giữa đồ chơi vương vãi và những tiếng "Con không muốn!"! Cuộc sống vẫn tiếp diễn. Hãy hít thở sâu, mẹ là người quản lý tuyệt vời nhất của sự hỗn loạn này.', title_zh = '胜利之后的现实 🚀', body_zh = '昨天的纪念日过后，今早醒来又是满地的玩具和一声声“我不要！”生活还在继续。深吸一口气，你就是这场混乱最棒的管理者。' WHERE id = 'f9781f63-e578-4e40-8665-b3d4fa014824' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis de la siesta 🥱', body_es = '¿No quiere ir a la cama y llora? Al acercarse a los 3 años, algunos niños empiezan a dejar la siesta. En lugar de luchar, anuncia una hora de calma y proponle simplemente hojear un libro en la cama.', title_fr = 'La crise de la sieste 🥱', body_fr = 'Il ne veut pas aller au lit et pleure ? Vers 3 ans, certains enfants commencent à abandonner la sieste. Plutôt que de lutter, annoncez un « temps calme » et proposez-lui simplement de feuilleter un livre dans son lit.', title_hi = 'दिन की नींद का संकट 🥱', body_hi = 'बिस्तर पर नहीं जाना चाहता और रोता है? 3 साल के करीब कुछ बच्चे दिन की नींद छोड़ने लगते हैं। लड़ने के बजाय ''शांत समय'' घोषित कीजिए और बिस्तर पर बस किताब पलटने को कहिए।', title_id = 'Krisis tidur siang 🥱', body_id = 'Ia tidak mau tidur dan menangis? Menjelang usia 3 tahun sebagian anak mulai berhenti tidur siang. Daripada berdebat, umumkan ''waktu tenang'' dan tawarkan untuk membolak-balik buku saja di tempat tidur.', title_ja = 'お昼寝の危機 🥱', body_ja = 'ベッドに行きたがらずに泣きますか？3歳が近づくと、お昼寝をしなくなる子もいます。戦うかわりに「静かな時間」を宣言して、ベッドで絵本をめくるだけでいいと提案しましょう。', title_ko = '낮잠 위기 🥱', body_ko = '자러 가기 싫다며 우나요? 세 돌 무렵 낮잠을 그만두는 아이도 있어요. 씨름하지 말고 ''조용한 시간''을 정해 침대에서 책만 넘겨 보자고 해 보세요.', title_nl = 'Crisis rond het middagslaapje 🥱', body_nl = 'Wil hij niet naar bed en huilt hij? Rond de 3 jaar stoppen sommige kinderen met hun slaapje. Ga de strijd niet aan, maar kondig een rustuurtje aan en stel voor dat hij gewoon in bed in een boekje bladert.', title_pl = 'Kryzys drzemki w dzień 🥱', body_pl = 'Nie chce iść do łóżka i płacze? Około 3. roku życia niektóre dzieci zaczynają rezygnować z drzemki. Zamiast walczyć, ogłoś godzinę wyciszenia i zaproponuj po prostu przeglądanie książeczki w łóżku.', title_pt = 'A crise da sesta 🥱', body_pt = 'Não quer ir para a cama e chora? Perto dos 3 anos, algumas crianças começam a deixar a sesta. Em vez de lutar, anuncie a hora do sossego e proponha que folheie um livro na cama.', title_sv = 'Kris kring dagsömnen 🥱', body_sv = 'Vill barnet inte gå och lägga sig och gråter? När barnet närmar sig 3 år börjar vissa sluta sova på dagen. I stället för att kämpa, utlys en Lugn stund och föreslå att barnet bara bläddrar i böcker i sängen.', title_vi = 'Khủng hoảng giấc ngủ ngày 🥱', body_vi = 'Bé không muốn lên giường và khóc? Gần 3 tuổi, một số trẻ bắt đầu bỏ giấc ngủ ngày. Thay vì giằng co, hãy tuyên bố "Giờ yên tĩnh" và gợi ý bé chỉ cần lật sách trên giường.', title_zh = '午睡危机 🥱', body_zh = '不想上床，还一直哭？快3岁时，有些孩子开始不再午睡。与其对抗，不如宣布“安静时间”，让宝宝在床上翻翻书就好。' WHERE id = 'fde949fd-c8a2-4b0b-a364-0d008da67880' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Plan de fuga de la cama 🛌', body_es = '¿Intenta trepar para salir de la cuna? Vuelve a revisar la seguridad de la habitación. Se acerca el momento de pasar a una cama de niño grande.', title_fr = 'Plan d''évasion du lit 🛌', body_fr = 'Il essaie d''escalader son lit à barreaux ? Revérifiez la chambre pour sa sécurité. Le passage au grand lit approche.', title_hi = 'बिस्तर से भागने का प्लान 🛌', body_hi = 'पालने से चढ़कर बाहर निकलने की कोशिश करता है? सुरक्षा के लिए कमरे को फिर से जाँचिए। बड़े बच्चों वाले बिस्तर पर जाने का समय करीब है।', title_id = 'Rencana kabur dari kasur 🛌', body_id = 'Ia mencoba memanjat keluar dari boks bayi? Periksa ulang kamar demi keamanan. Waktunya pindah ke kasur anak besar sudah dekat.', title_ja = 'ベッド脱出計画 🛌', body_ja = 'ベビーベッドからよじ登って出ようとしていますか？安全のために部屋をもう一度見直しましょう。大きい子用ベッドへの移行が近づいています。', title_ko = '침대 탈출 작전 🛌', body_ko = '아기 침대를 기어 넘으려 하나요? 안전을 위해 방을 다시 살펴보세요. 큰 아이 침대로 바꿀 때가 다가오고 있어요.', title_nl = 'Ontsnappingsplan uit bed 🛌', body_nl = 'Probeert hij uit zijn ledikantje te klimmen? Controleer de kamer opnieuw op veiligheid. Het moment voor een groot bed komt eraan.', title_pl = 'Plan ucieczki z łóżeczka 🛌', body_pl = 'Próbuje wydostać się z łóżeczka? Jeszcze raz sprawdź bezpieczeństwo pokoju. Zbliża się czas przejścia do dużego łóżka.', title_pt = 'Plano de fuga da cama 🛌', body_pt = 'Tenta trepar para fora do berço? Por segurança, volte a verificar o quarto. Aproxima-se a altura de passar para uma cama de criança crescida.', title_sv = 'Flyktplan från sängen 🛌', body_sv = 'Försöker barnet klättra ur spjälsängen? Gå igenom rummet igen för säkerhetens skull. Det närmar sig dags att byta till en större barnsäng.', title_vi = 'Kế hoạch trốn khỏi giường 🛌', body_vi = 'Bé cố trèo ra khỏi cũi? Hãy kiểm tra lại căn phòng để đảm bảo an toàn. Sắp đến lúc chuyển sang giường lớn.', title_zh = '逃离小床计划 🛌', body_zh = '想从婴儿床里爬出来？为了安全，重新检查一遍房间。换大床的时候快到了。' WHERE id = '092fe7ca-f54f-4986-9a3f-884d05ff6c27' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empiezan los «¿Cómo?» 🤔', body_es = 'Los «¿Por qué?» dejan paso a los «¿Cómo funciona esto?». Intenta entender los mecanismos. Ármate de paciencia y dale explicaciones cortas y lógicas.', title_fr = 'Les questions « Comment ? » commencent 🤔', body_fr = 'Les « Pourquoi ? » laissent place aux « Comment ça marche ? ». Il essaie de comprendre les mécanismes. Armez-vous de patience et donnez-lui des explications courtes et logiques.', title_hi = '''कैसे?'' वाले सवाल शुरू 🤔', body_hi = '''क्यों?'' वाले सवालों की जगह अब ''यह कैसे काम करता है?'' ने ले ली है। वह चीज़ों का काम करने का तरीका समझने की कोशिश कर रहा है। सब्र जुटाइए और उसे छोटे, तर्कसंगत जवाब दीजिए।', title_id = 'Pertanyaan ''Bagaimana?'' dimulai 🤔', body_id = 'Pertanyaan ''Kenapa?'' berganti menjadi ''Ini bekerja bagaimana?'' Ia mencoba memahami cara kerja benda. Kumpulkan kesabaran dan beri ia penjelasan singkat yang logis.', title_ja = '「どうやって？」の質問が始まる 🤔', body_ja = '「なんで？」が「これ、どうやって動くの？」に変わってきました。しくみを理解しようとしています。忍耐を集めて、短くて筋の通った説明をしてあげましょう。', title_ko = '''어떻게?'' 질문이 시작돼요 🤔', body_ko = '''왜?'' 질문이 ''이건 어떻게 작동해?''로 바뀌고 있나요? 원리를 이해하려는 거예요. 인내심을 모아 짧고 논리적으로 설명해 주세요.', title_nl = 'De ''Hoe?''-vragen beginnen 🤔', body_nl = '''Waarom?'' maakt plaats voor ''Hoe werkt dit?''. Hij probeert te begrijpen hoe dingen werken. Verzamel je geduld en geef hem korte, logische uitleg.', title_pl = 'Zaczynają się pytania „Jak?” 🤔', body_pl = 'Pytania „Dlaczego?” ustępują miejsca pytaniu „Jak to działa?”. Próbuje zrozumieć mechanizmy. Zbierz cierpliwość i dawaj mu krótkie, logiczne wyjaśnienia.', title_pt = 'Começam as perguntas "Como?" 🤔', body_pt = 'Os "Porquê?" dão lugar ao "Como é que isto funciona?". Está a tentar compreender os mecanismos. Arme-se de paciência e dê-lhe explicações curtas e lógicas.', title_sv = 'Hur-frågorna börjar 🤔', body_sv = '”Varför?” ersätts av ”Hur fungerar det här?”. Barnet försöker förstå mekanismer. Samla ditt tålamod och ge korta, logiska förklaringar.', title_vi = 'Những câu hỏi "Thế nào?" bắt đầu 🤔', body_vi = 'Những câu "Tại sao?" nhường chỗ cho "Cái này hoạt động thế nào?". Bé đang cố hiểu các cơ chế. Hãy kiên nhẫn và giải thích cho bé ngắn gọn, hợp lý.', title_zh = '“怎么做？”的问题开始了 🤔', body_zh = '“为什么？”变成了“这个是怎么运作的？”。宝宝在试着理解事物的原理。拿出耐心，给宝宝简短、有逻辑的解释。' WHERE id = '9fdf76d2-ea34-465e-99e8-537978d670c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una pausa para mamá ☕', body_es = 'Mientras juega solo, no corras a hacer tareas de casa. El desorden no se va a escapar, pero tu energía sí puede agotarse. Siéntate y tómate tu café caliente.', title_fr = 'Une pause pour maman ☕', body_fr = 'Quand il joue tout seul, ne foncez pas tout de suite vers les tâches ménagères. Le désordre ne va pas s''envoler, mais votre énergie peut s''épuiser. Asseyez-vous et buvez votre café chaud.', title_hi = 'माँ के लिए ब्रेक ☕', body_hi = 'बच्चा अपने आप खेल रहा है तो तुरंत घर के काम में मत भागिए। कमरे की बिखरी चीज़ें कहीं नहीं जाएँगी, लेकिन आपकी ऊर्जा खत्म हो सकती है। बैठिए और अपनी गर्म कॉफ़ी पीजिए।', title_id = 'Rehat untuk Ibu ☕', body_id = 'Saat anak bermain sendiri, jangan langsung lari ke pekerjaan rumah. Kamar yang berantakan tidak akan ke mana-mana, tetapi energi Anda bisa habis. Duduklah dan minum kopi hangat Anda.', title_ja = 'ママのひと休み ☕', body_ja = 'お子さんがひとりで遊んでいるとき、すぐに家事に走らないで。散らかった部屋は逃げませんが、あなたのエネルギーは尽きてしまいます。座って温かいコーヒーを飲みましょう。', title_ko = '엄마를 위한 쉼표 ☕', body_ko = '아이가 혼자 놀 때 바로 집안일로 달려가지 마세요. 어질러진 방은 어디 가지 않지만 엄마의 기운은 바닥날 수 있어요. 앉아서 따뜻한 커피를 드세요.', title_nl = 'Pauze voor mama ☕', body_nl = 'Ren niet meteen naar het huishouden als hij zelf speelt. De rommel loopt niet weg, maar jouw energie kan wel op raken. Ga zitten en drink je koffie warm.', title_pl = 'Przerwa dla mamy ☕', body_pl = 'Gdy dziecko bawi się samo, nie biegnij od razu do obowiązków. Bałagan nie ucieknie, ale twoja energia może się skończyć. Usiądź i wypij ciepłą kawę.', title_pt = 'Pausa para a mãe ☕', body_pt = 'Quando a criança brinca sozinha, não corra logo para as tarefas de casa. A desarrumação não foge, mas a sua energia pode acabar. Sente-se e beba o seu café quente.', title_sv = 'Paus för mamma ☕', body_sv = 'Rusa inte iväg till hushållet så fort barnet leker själv. Stöket i rummet springer ingenstans, men din energi kan ta slut. Sätt dig och drick ditt varma kaffe.', title_vi = 'Phút nghỉ của mẹ ☕', body_vi = 'Khi bé tự chơi, đừng vội lao vào việc nhà. Căn phòng bừa bộn không chạy đi đâu được, nhưng năng lượng của mẹ thì có thể cạn. Hãy ngồi xuống và uống tách cà phê nóng.', title_zh = '妈妈的休息时间 ☕', body_zh = '孩子自己玩的时候，别急着去做家务。房间乱了跑不掉，可你的精力却会耗尽。坐下来，喝杯热咖啡吧。' WHERE id = 'c9428152-a130-431b-ac89-26275023d613' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La máquina del «¿Qué es esto?» ☝️', body_es = '¿Lo señala todo con el dedo y pregunta cómo se llama? Quiere que le pongas nombre al mundo. ¡Es un gran salto en la comunicación! Aunque te canses, repite con paciencia el nombre de las cosas.', title_fr = 'La machine à « C''est quoi ? » ☝️', body_fr = 'Il montre tout du doigt en demandant le nom ? Il veut que vous lui nommiez le monde. C''est un grand bond dans la communication ! Même si vous êtes fatiguée, répétez patiemment le nom de ces objets.', title_hi = '''यह क्या है?'' वाली मशीन ☝️', body_hi = 'हर चीज़ की ओर उँगली दिखाकर उसका नाम पूछता है? वह चाहता है कि आप उसे दुनिया के नाम बताएँ। बातचीत में यह बड़ी छलांग है! थक जाएँ तब भी उन चीज़ों के नाम धैर्य से दोहराइए।', title_id = 'Mesin ''Ini apa?'' ☝️', body_id = 'Ia menunjuk segala hal dengan jarinya dan menanyakan namanya? Ia ingin Anda menamai dunia untuknya. Lompatan besar dalam komunikasi! Meski lelah, ulangi nama benda-benda itu dengan sabar.', title_ja = '「これなあに？」マシーン ☝️', body_ja = 'なんでも指さして名前を聞きますか？世界に名前をつけてほしいのです。コミュニケーションの大きな飛躍です！疲れていても、ものの名前を根気よくくり返してあげましょう。', title_ko = '''이게 뭐야?'' 질문 기계 ☝️', body_ko = '손가락으로 모든 걸 가리키며 이름을 묻나요? 엄마가 세상에 이름을 붙여 주길 바라는 거예요. 소통의 큰 도약이에요! 지치더라도 그 물건들의 이름을 인내심 있게 반복해 주세요.', title_nl = 'De ''Wat is dat?''-machine ☝️', body_nl = 'Wijst hij alles aan en vraagt hij hoe het heet? Hij wil dat jij de wereld voor hem benoemt. Een grote sprong in communicatie! Ook al ben je moe, herhaal geduldig de namen van die dingen.', title_pl = 'Maszyna do „Co to?” ☝️', body_pl = 'Pokazuje wszystko paluszkiem i pyta o nazwę? Chce, żebyś nazywała mu świat. To wielki skok w komunikacji! Nawet jeśli jesteś zmęczona, cierpliwie powtarzaj nazwy tych rzeczy.', title_pt = 'A máquina do "O que é isto?" ☝️', body_pt = 'Aponta tudo com o dedo e pergunta o nome? Quer que dê nome ao mundo por ele. É um grande salto na comunicação! Mesmo cansada, repita com paciência o nome das coisas.', title_sv = '”Vad är det?”-maskinen ☝️', body_sv = 'Pekar barnet på allt och frågar vad det heter? Hen vill att du ska sätta namn på världen. Ett stort kommunikativt språng! Även om du blir trött, upprepa tålmodigt vad sakerna heter.', title_vi = 'Cỗ máy "Cái gì đây?" ☝️', body_vi = 'Bé chỉ tay vào mọi thứ và hỏi tên? Bé muốn mẹ gọi tên thế giới cho bé. Đây là bước nhảy vọt lớn trong giao tiếp! Dù mệt, hãy kiên nhẫn nhắc lại tên của những đồ vật ấy.', title_zh = '“这是什么？”机器 ☝️', body_zh = '什么东西都用手指着问名字？宝宝想让你给世界命名。这是交流上的一大飞跃！就算累了，也耐心地重复那些东西的名字吧。' WHERE id = '4df5b42c-f87e-4fa7-b1d2-b3aa6d779c67' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Eres humana 🛑', body_es = '¿Hoy nada ha salido según lo previsto? No te culpes. Eres una madre real, no una ilusión con filtro de las redes sociales. Tu peque solo te necesita a ti.', title_fr = 'Vous êtes humaine 🛑', body_fr = 'Rien ne s''est passé comme prévu aujourd''hui ? Ne vous culpabilisez pas. Vous êtes une vraie maman, pas une illusion filtrée des réseaux sociaux. Votre enfant a juste besoin de vous.', title_hi = 'आप इंसान हैं 🛑', body_hi = 'आज कुछ भी प्लान के मुताबिक नहीं हुआ? खुद को दोष मत दीजिए। आप एक असली माँ हैं, सोशल मीडिया का फ़िल्टर किया हुआ भ्रम नहीं। बच्चे को बस आपकी ज़रूरत है।', title_id = 'Anda manusia 🛑', body_id = 'Hari ini tidak ada yang berjalan sesuai rencana? Jangan salahkan diri. Anda ibu yang nyata, bukan ilusi berfilter di media sosial. Anak Anda hanya membutuhkan Anda.', title_ja = 'あなたも人間です 🛑', body_ja = '今日は何も予定どおりにいかなかった？自分を責めないで。あなたは本物のママで、SNSのフィルターがかかった幻ではありません。お子さんに必要なのは、ただあなたです。', title_ko = '엄마도 사람이에요 🛑', body_ko = '오늘 아무것도 계획대로 되지 않았나요? 자책하지 마세요. 엄마는 SNS 속 필터 씌운 환상이 아니라 진짜 엄마예요. 아이에게 필요한 건 그저 엄마예요.', title_nl = 'Je bent een mens 🛑', body_nl = 'Ging vandaag niets volgens plan? Geef jezelf niet de schuld. Je bent een echte moeder, geen gefilterde illusie van sociale media. Je kind heeft gewoon jou nodig.', title_pl = 'Jesteś człowiekiem 🛑', body_pl = 'Dziś nic nie poszło zgodnie z planem? Nie obwiniaj się. Jesteś prawdziwą mamą, a nie przefiltrowaną iluzją z mediów społecznościowych. Dziecko po prostu potrzebuje ciebie.', title_pt = 'É humana 🛑', body_pt = 'Hoje nada correu como planeado? Não se culpe. É uma mãe real, não uma ilusão com filtros das redes sociais. O seu filho só precisa de si.', title_sv = 'Du är människa 🛑', body_sv = 'Gick ingenting enligt planen i dag? Skuldbelägg inte dig själv. Du är en verklig mamma, inte en filtrerad illusion i sociala medier. Barnet behöver bara dig.', title_vi = 'Mẹ cũng là con người 🛑', body_vi = 'Hôm nay chẳng việc gì theo kế hoạch? Đừng tự trách mình. Mẹ là một người mẹ thật, không phải ảo ảnh qua bộ lọc trên mạng xã hội. Bé chỉ cần có mẹ thôi.', title_zh = '你也是人 🛑', body_zh = '今天什么都没按计划进行？别责怪自己。你是一个真实的妈妈，不是社交媒体上加了滤镜的幻象。孩子需要的只是你。' WHERE id = 'fb8b7427-667b-4244-909c-df4ca467d79e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis estética con la comida 🥦', body_es = '¿No se come el borde del pan o una rodaja de pepino porque es «feo»? La selectividad con la comida adopta formas curiosas. Descubre en el Plan de alimentación los trucos más hábiles para hacer puré las verduras y esconderlas.', title_fr = 'Crise d''esthétique à table 🥦', body_fr = 'Il refuse la croûte du pain ou une rondelle de concombre parce qu''elle est « moche » ? La sélectivité alimentaire prend des formes étranges. Découvrez dans le Plan de nutrition les meilleures astuces pour réduire les légumes en purée et les cacher.', title_hi = 'खाने की सुंदरता का संकट 🥦', body_hi = 'ब्रेड का किनारा या खीरे का टुकड़ा ''बदसूरत'' होने की वजह से नहीं खाता? खाने के नखरे अजीब रूप ले रहे हैं। फ़ीडिंग प्लान में सब्ज़ियों को प्यूरी बनाकर छिपाने के सबसे चतुर तरीके खोजिए।', title_id = 'Krisis makanan estetis 🥦', body_id = 'Ia tidak mau makan pinggiran roti atau irisan timun karena ''jelek''? Pilih-pilih makanan bisa berbentuk aneh. Temukan cara paling jitu menghaluskan dan menyembunyikan sayuran di Rencana Nutrisi.', title_ja = '見た目へのこだわり危機 🥦', body_ja = 'パンの耳やきゅうりの薄切りを「かっこわるい」から食べない？好き嫌いは不思議な形をとります。「栄養管理ツール」で、野菜をピューレにしてかくすとっておきの方法を見つけましょう。', title_ko = '보기 좋아야 먹어요 🥦', body_ko = '빵 테두리나 오이 조각이 못생겼다고 안 먹나요? 편식이 별난 모습으로 나타나기도 해요. 식단 계획에서 채소를 퓌레로 만들어 숨기는 가장 기발한 방법을 찾아보세요.', title_nl = 'Eten moet er mooi uitzien 🥦', body_nl = 'Eet hij de korst van zijn brood of een plakje komkommer niet omdat het ''lelijk'' is? Kieskeurig eten krijgt vreemde vormen. Ontdek in het Voedingsplan de slimste manieren om groenten te pureren en te verstoppen.', title_pl = 'Estetyczny kryzys jedzeniowy 🥦', body_pl = 'Nie je skórki od chleba albo plasterka ogórka, bo są „brzydkie”? Wybiórczość jedzeniowa przybiera dziwne formy. Odkryj w planie karmienia najsprytniejsze sposoby, by zmiksować i ukryć warzywa.', title_pt = 'Crise estética no prato 🥦', body_pt = 'Não come a côdea do pão ou a rodela de pepino porque são "feias"? A seletividade alimentar ganha formas estranhas. Descubra no Plano Alimentar as formas mais engenhosas de fazer puré de legumes e escondê-los.', title_sv = 'Estetisk matkris 🥦', body_sv = 'Äter barnet inte brödkanten eller gurkskivan för att den är ful? Kräsenheten tar konstiga former. Upptäck de smartaste sätten att mosa och gömma grönsaker i matplanen.', title_vi = 'Khủng hoảng thẩm mỹ món ăn 🥦', body_vi = 'Bé không ăn vỏ bánh mì hay lát dưa chuột vì "xấu"? Kén ăn có những biểu hiện thật lạ. Hãy khám phá trong Kế hoạch dinh dưỡng những cách khéo léo nhất để xay nhuyễn và giấu rau.', title_zh = '颜值危机 🥦', body_zh = '因为面包边或黄瓜片“很丑”就不吃？挑食变出了各种奇怪的花样。在喂养计划里找找把蔬菜做成泥藏起来的高明办法。' WHERE id = '269b7d14-00d0-4c42-84b9-6759e61b0baa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empieza el concierto matutino 🎤', body_es = '¿En cuanto se despierta canta algo a todo volumen? A las 7 de la mañana su energía está a tope. Frótate los ojos y disfruta con una sonrisa del show de esta pequeña estrella del pop.', title_fr = 'Le concert du matin a commencé 🎤', body_fr = 'Dès le réveil, il chante à pleins décibels ? À 7 h du matin, son énergie est déjà à 100 %. Frottez-vous les yeux et regardez avec le sourire le show de cette petite pop star.', title_hi = 'सुबह का कॉन्सर्ट शुरू 🎤', body_hi = 'जागते ही पूरी आवाज़ में कुछ गाने लगता है? सुबह 7 बजे उसकी ऊर्जा पूरी चार्ज है। आँखें मलिए और इस नन्हे पॉप स्टार का शो मुस्कुराते हुए देखिए।', title_id = 'Konser pagi dimulai 🎤', body_id = 'Begitu bangun ia langsung bernyanyi dengan volume tertinggi? Energinya sudah terisi penuh pukul 7 pagi. Kucek mata Anda dan saksikan pertunjukan bintang pop kecil ini sambil tersenyum.', title_ja = '朝のコンサート開演 🎤', body_ja = '目を覚ましたとたん、最大音量で何かを歌い始めますか？朝7時にはもうエネルギー満タン。目をこすりながら、この小さなポップスターのショーを笑顔で楽しみましょう。', title_ko = '아침 콘서트가 시작됐어요 🎤', body_ko = '눈 뜨자마자 최대 볼륨으로 노래를 부르나요? 아침 7시에 에너지가 완충됐어요. 눈을 비비며 이 꼬마 팝스타의 공연을 웃으며 즐기세요.', title_nl = 'Het ochtendconcert is begonnen 🎤', body_nl = 'Zingt hij meteen bij het wakker worden op het hoogste volume? Om 7 uur ''s ochtends is zijn energie al volledig opgeladen. Wrijf in je ogen en kijk glimlachend naar de show van deze kleine popster.', title_pl = 'Poranny koncert się zaczął 🎤', body_pl = 'Gdy tylko się obudzi, śpiewa coś na cały regulator? O 7 rano jego energia jest w pełni naładowana. Przetrzyj oczy i z uśmiechem oglądaj show tej małej gwiazdy popu.', title_pt = 'Começou o concerto da manhã 🎤', body_pt = 'Mal acorda, canta qualquer coisa no volume máximo? Às 7 da manhã, a energia dele já está a 100%. Esfregue os olhos e assista a sorrir ao espetáculo desta pequena estrela pop.', title_sv = 'Morgonkonserten har börjat 🎤', body_sv = 'Sjunger barnet något på högsta decibel så fort hen vaknar? Energin är fulladdad klockan 7 på morgonen. Gnugga ögonen och titta på den lilla popstjärnans show med ett leende.', title_vi = 'Buổi hòa nhạc buổi sáng bắt đầu 🎤', body_vi = 'Vừa thức dậy bé đã hát gì đó với âm lượng lớn nhất? 7 giờ sáng năng lượng của bé đã sạc đầy. Hãy dụi mắt và mỉm cười thưởng thức màn trình diễn của ngôi sao nhạc pop nhí này.', title_zh = '早晨演唱会开始了 🎤', body_zh = '一醒来就把音量开到最大，唱个不停？早上7点就电量满格了。揉揉眼睛，笑着欣赏这位小小流行歌星的表演吧。' WHERE id = '3619cb9e-e29f-4149-9f97-e65685c72f61' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inundación en el baño 🛀', body_es = 'Jugar con el agua sirve menos para lavarse que para convertir el baño en un parque acuático. Deja que salpique. El agua templada y la diversión se llevarán toda la tozudez acumulada durante el día.', title_fr = 'Inondation dans la salle de bain 🛀', body_fr = 'Jouer avec l''eau, c''est moins pour se laver que pour transformer la salle de bain en parc aquatique. Laissez l''eau éclabousser. L''eau tiède et le jeu emporteront tout l''entêtement accumulé dans la journée.', title_hi = 'बाथरूम में बाढ़ 🛀', body_hi = 'पानी से खेलना सफ़ाई से ज़्यादा बाथरूम को वॉटर पार्क बनाने के लिए है। पानी उछलने दीजिए। गुनगुना पानी और मस्ती दिनभर में जमा हुई उसकी सारी ज़िद धो देंगे।', title_id = 'Banjir di kamar mandi 🛀', body_id = 'Bermain air lebih untuk mengubah kamar mandi menjadi taman air daripada untuk bersih-bersih. Biarkan airnya memercik. Air hangat dan keseruan akan menghanyutkan semua keras kepala yang menumpuk seharian.', title_ja = 'お風呂場の大洪水 🛀', body_ja = 'お水遊びはきれいにするためより、お風呂場をウォーターパークにするためのもの。しぶきを上げさせてあげましょう。ぬるめのお湯と楽しさが、一日にたまったがんこさをすっかり洗い流してくれます。', title_ko = '욕실 대홍수 🛀', body_ko = '물놀이는 씻기보다 욕실을 워터파크로 만드는 시간이에요. 물이 튀어도 괜찮아요. 따뜻한 물과 재미가 하루 동안 쌓인 고집을 모두 씻어 낼 거예요.', title_nl = 'Overstroming in de badkamer 🛀', body_nl = 'Spelen met water draait minder om schoon worden en meer om van de badkamer een waterpark te maken. Laat het maar spetteren. Lauw water en plezier spoelen alle koppigheid van de dag weg.', title_pl = 'Powódź w łazience 🛀', body_pl = 'Zabawa wodą służy bardziej zamienianiu łazienki w aquapark niż myciu. Niech woda chlapie. Ciepła woda i zabawa zmyją cały upór zebrany w ciągu dnia.', title_pt = 'Inundação na casa de banho 🛀', body_pt = 'Brincar com a água é menos para lavar e mais para transformar a casa de banho num parque aquático. Deixe a água salpicar. A água morna e a diversão vão levar toda a teimosia acumulada ao longo do dia.', title_sv = 'Översvämning i badrummet 🛀', body_sv = 'Att leka med vatten handlar mindre om renlighet och mer om att göra badrummet till ett vattenland. Låt det skvätta. Ljummet vatten och lek sköljer bort all envishet som samlats under dagen.', title_vi = 'Lũ lụt trong phòng tắm 🛀', body_vi = 'Nghịch nước không phải để tắm sạch mà để biến phòng tắm thành công viên nước. Cứ để nước bắn tung tóe. Nước ấm và niềm vui sẽ cuốn trôi mọi sự bướng bỉnh tích tụ cả ngày của bé.', title_zh = '浴室发大水 🛀', body_zh = '玩水与其说是为了洗干净，不如说是为了把浴室变成水上乐园。就让水花四溅吧。温水和欢乐会把一整天积攒的倔强全都冲走。' WHERE id = '4e5a485c-972c-4f14-b15e-6d0c1f1b8961' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La trampa del «uno más» 📖', body_es = 'No quiere ir a la cama y alarga el tiempo pidiendo «un cuento más». Evita los libros clásicos. Crea en Cuentos inteligentes una historia corta para dormir con los personajes que él ha inventado y cierra el ritual.', title_fr = 'Encore une, la dernière 📖', body_fr = 'Il ne veut pas aller au lit et gagne du temps avec « encore une histoire ». Évitez les livres classiques. Dans les Contes intelligents, créez une courte histoire du soir avec les personnages qu''il a inventés et concluez le rituel.', title_hi = '''बस एक और'' की चाल 📖', body_hi = 'बिस्तर पर नहीं जाना चाहता और ''बस एक और कहानी'' कहकर समय खींचता है? पुरानी किताबों से बचिए। स्मार्ट कहानियों में उसके गढ़े किरदारों के साथ एक छोटी सी नींद वाली कहानी बनाइए और बात खत्म कीजिए।', title_id = 'Satu lagi ya 📖', body_id = 'Ia tidak mau tidur dan mengulur waktu dengan ''satu dongeng lagi''? Hindari buku klasik. Di Dongeng Pintar, buat cerita tidur singkat dengan tokoh-tokoh karangannya sendiri untuk menutup rutinitas.', title_ja = 'もうひとつだけのわな 📖', body_ja = 'ベッドに行きたがらず、「もうひとつだけお話」と時間をのばしますか？いつもの絵本はやめましょう。「スマートおはなし」で、お子さんが考えたキャラクターが出てくる短いおやすみのお話をつくって、締めくくりましょう。', title_ko = '딱 하나만 더 📖', body_ko = '자러 가기 싫어서 ''하나만 더'' 하며 시간을 끄나요? 늘 읽던 책은 피하세요. 스마트 동화에서 아이가 지어낸 등장인물로 짧은 잠자리 이야기를 만들어 마무리해 보세요.', title_nl = 'Nog eentje dan 📖', body_nl = 'Wil hij niet naar bed en rekt hij het met ''Nog één sprookje''? Laat de klassieke boeken liggen. Maak in Slimme sprookjes een kort slaapverhaal met figuren die hij zelf verzint en rond zo het ritueel af.', title_pl = 'Jeszcze jedna, szybka 📖', body_pl = 'Nie chce iść do łóżka i przeciąga czas prośbą „jeszcze jedna bajka”? Zrezygnuj z klasycznych książek. Stwórz w Mądrych bajkach krótką historię na dobranoc z wymyślonymi przez niego postaciami i zakończ wieczór.', title_pt = 'Só mais uma 📖', body_pt = 'Não quer ir para a cama e adia com "só mais uma história"? Evite os livros clássicos. Crie nas Histórias Inteligentes uma história curta para dormir com as personagens que ele inventou e feche o ritual.', title_sv = 'Fällan ”en till” 📖', body_sv = 'Barnet vill inte gå och lägga sig och drar ut på tiden med ”en saga till”. Undvik klassiska böcker. Skapa en kort godnattberättelse med barnets egna påhittade figurer i Smarta sagor och avsluta.', title_vi = 'Thêm một truyện nữa thôi 📖', body_vi = 'Bé không muốn lên giường, cứ đòi "thêm một truyện nữa" để kéo dài thời gian. Hãy tránh sách kinh điển. Trong Truyện cổ tích thông minh, hãy tạo một câu chuyện ngủ ngắn với những nhân vật bé nghĩ ra để kết thúc.', title_zh = '“再讲一个”的陷阱 📖', body_zh = '不想上床，一直说“再讲一个”拖时间？别用经典故事书了。在智能故事里用宝宝自己编的角色创作一个简短的睡前故事，把这一天收个尾。' WHERE id = '22cad895-d987-4916-ac97-672fe0a05ac0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pausa secreta de chocolate 🍫', body_es = 'Mamá que picas algo dulce de pie a escondidas detrás del armario de la cocina: ¡te vemos! No te culpes. Tienes todo el derecho a ese subidón de glucosa para aguantar el jaleo.', title_fr = 'Pause chocolat secrète 🍫', body_fr = 'Maman qui grignote un petit truc sucré en cachette, debout derrière le placard de la cuisine, on vous voit ! Ne vous blâmez pas. Pour supporter le bruit, vous avez parfaitement droit à ce petit pic de glucose.', title_hi = 'छिपकर चॉकलेट वाला ब्रेक 🍫', body_hi = 'रसोई की अलमारी के पीछे छिपकर खड़े-खड़े कुछ मीठा खाने वाली माँ, हम आपको देख रहे हैं! खुद को दोष मत दीजिए। शोर सहने के लिए आपको उस ग्लूकोज़ बूस्ट का पूरा हक है।', title_id = 'Rehat cokelat rahasia 🍫', body_id = 'Ibu yang diam-diam ngemil manis sambil berdiri di balik lemari dapur, kami melihatmu! Jangan salahkan diri. Untuk bertahan di tengah kebisingan, Anda berhak atas lonjakan glukosa itu.', title_ja = 'こっそりチョコ休憩 🍫', body_ja = 'キッチンの戸棚のかげで、立ったままこっそり甘いものをつまむママ、見ていますよ！自分を責めないで。にぎやかさに耐えるために、糖分をとるのは当然の権利です。', title_ko = '몰래 먹는 초콜릿 타임 🍫', body_ko = '주방 찬장 뒤에서 몰래 서서 단것을 먹는 엄마, 다 보여요! 자책하지 마세요. 이 소란을 견디려면 그 정도 당 충전은 당연히 누려도 돼요.', title_nl = 'Geheime chocoladepauze 🍫', body_nl = 'Mama die stiekem staand achter het keukenkastje iets zoets eet, we zien je! Veroordeel jezelf niet. Je hebt alle recht op die suikerboost om het lawaai te doorstaan.', title_pl = 'Tajna przerwa na czekoladę 🍫', body_pl = 'Mamo, która za szafką kuchenną po kryjomu zjadasz na stojąco coś słodkiego, widzimy cię! Nie obwiniaj się. Żeby znieść ten hałas, masz pełne prawo do tego skoku glukozy.', title_pt = 'Pausa secreta para chocolate 🍫', body_pt = 'Mãe que come um doce às escondidas, de pé, atrás do armário da cozinha: estamos a vê-la! Não se culpe. Para aguentar o barulho, tem todo o direito a esse pico de glicose.', title_sv = 'Hemlig chokladpaus 🍫', body_sv = 'Mamma som i smyg äter något sött stående bakom köksskåpet, vi ser dig! Klandra inte dig själv. Du har all rätt till den där glukosboosten för att stå ut med oväsendet.', title_vi = 'Phút nghỉ sô-cô-la bí mật 🍫', body_vi = 'Mẹ ơi, chúng mình thấy mẹ lén ăn vội chút đồ ngọt sau cánh tủ bếp rồi nhé! Đừng tự trách. Để chịu đựng sự ồn ào, mẹ hoàn toàn có quyền nạp thêm chút đường.', title_zh = '偷偷吃巧克力的小憩 🍫', body_zh = '躲在橱柜后面站着偷吃甜食的妈妈，我们看见你啦！别责怪自己。为了扛住吵闹，你完全有权利来点血糖小高峰。' WHERE id = '4aedb3f8-6caf-4ec5-a8d3-5b5f77908beb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño dictador de la casa 👑', body_es = '«¡Ahí no, siéntate aquí!», «¡Esto no lo haces tú, lo hago yo!». Quiere mandar en casa. Sin romper su voluntad de golpe, busca el equilibrio diciendo: «Tú te sientas aquí y yo allí».', title_fr = 'Le petit dictateur de la maison 👑', body_fr = '« Pas là, assieds-toi ici ! », « C''est moi qui le fais, pas toi ! » Il veut diriger la maison. Sans briser brutalement sa volonté, trouvez l''équilibre : « Toi, tu t''assieds ici, et moi là. »', title_hi = 'घर का नन्हा तानाशाह 👑', body_hi = '''वहाँ नहीं, यहाँ बैठो!'', ''यह तुम नहीं, मैं करूँगा!'' वह घर चलाना चाहता है। उसकी इच्छा को झटके से तोड़े बिना ''तुम यहाँ बैठो, मैं वहाँ'' कहकर संतुलन बनाइए।', title_id = 'Diktator kecil di rumah 👑', body_id = '''Jangan di situ, duduk di sini!'', ''Bukan kamu, aku yang melakukannya!'' Ia ingin mengatur rumah. Tanpa mematahkan kemauannya secara keras, jaga keseimbangan dengan berkata ''Kamu duduk di sini, aku di sana''.', title_ja = 'おうちの小さな独裁者 👑', body_ja = '「そこじゃなくて、ここに座って！」「ママじゃなくて、ぼくがやる！」家を仕切りたいのです。意志を強くくじかずに、「あなたはここ、ママはあそこね」とバランスをとりましょう。', title_ko = '우리 집 꼬마 독재자 👑', body_ko = '''거기 말고 여기 앉아!'', ''엄마 말고 내가 할 거야!'' 집을 자기가 다스리고 싶어 해요. 의지를 꺾지 말고 ''너는 여기, 엄마는 저기 앉을게'' 하며 균형을 맞춰 주세요.', title_nl = 'De kleine dictator van het huis 👑', body_nl = '''Niet daar, hier zitten!'', ''Niet jij, ik doe het!'' Hij wil de baas zijn in huis. Breek zijn wil niet hard, maar zoek een balans met: ''Jij zit hier, en ik daar.''', title_pl = 'Mały dyktator w domu 👑', body_pl = '„Nie tam, siadaj tu!”, „Nie ty, ja to zrobię!”. Chce rządzić domem. Nie łamiąc ostro jego woli, zachowaj równowagę: „Ty siadasz tu, a ja tam”.', title_pt = 'O pequeno ditador da casa 👑', body_pt = '"Aí não, senta-te aqui!", "Não és tu, sou eu que faço!" Quer mandar na casa. Sem quebrar a vontade dele de forma brusca, encontre o equilíbrio: "Tu sentas-te aqui e eu sento-me ali."', title_sv = 'Hemmets lilla diktator 👑', body_sv = '”Inte där, sitt här!”, ”Inte du, jag gör det!” Barnet vill styra hemmet. Utan att knäcka viljan, skapa balans genom att säga ”Du sitter här och jag sitter där”.', title_vi = '"Nhà độc tài" nhỏ của gia đình 👑', body_vi = '"Không phải đó, ngồi đây cơ!", "Không phải mẹ, con làm!" Bé muốn điều khiển cả nhà. Đừng bẻ gãy ý chí của bé một cách gay gắt, hãy giữ cân bằng bằng câu "Con ngồi đây, mẹ ngồi kia nhé".', title_zh = '家里的小独裁者 👑', body_zh = '“别坐那儿，坐这儿！”“这个不是你来，是我来！”宝宝想管理整个家。别硬生生打击宝宝的意志，说一句“你坐这儿，我坐那儿”，找到平衡。' WHERE id = 'c5c0175d-de40-45a7-97f9-43392b324696' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La sesión de masaje de papá 💆‍♂️', body_es = 'Hoy has pasado mucho tiempo de pie y te duele la espalda de correr detrás de tu peque. En cuanto se duerma, pide a tu pareja un masaje de hombros de 10 minutos. Eres el pilar de la casa, y los pilares también necesitan descansar.', title_fr = 'Séance de massage par papa 💆‍♂️', body_fr = 'Vous êtes restée debout toute la journée et votre dos vous fait souffrir à force de courir après lui. Dès qu''il dort, demandez à votre partenaire un massage des épaules de 10 minutes. Vous êtes le pilier de la maison, et les piliers aussi ont besoin de repos.', title_hi = 'पापा का मालिश सेशन 💆‍♂️', body_hi = 'आज बहुत देर खड़ी रहीं, उसके पीछे भागते-भागते कमर टूट रही है। बच्चे के सोते ही अपने पार्टनर से 10 मिनट की कंधों की मालिश माँगिए। आप घर का खंभा हैं, और खंभों को भी आराम चाहिए।', title_id = 'Sesi pijat dari Ayah 💆‍♂️', body_id = 'Hari ini Anda lama berdiri, punggung terasa patah karena mengejarnya. Begitu anak tidur, minta pasangan memijat bahu Anda 10 menit. Anda tiang rumah ini, dan tiang pun perlu istirahat.', title_ja = 'パパのマッサージタイム 💆‍♂️', body_ja = '今日は一日じゅう立ちっぱなしで、追いかけて腰が痛いですね。お子さんが眠ったら、パートナーに10分間肩をもんでもらいましょう。あなたは家の柱、柱だって休みが必要です。', title_ko = '아빠의 마사지 시간 💆‍♂️', body_ko = '오늘 하루 종일 서서 아이를 쫓아다니느라 허리가 끊어질 것 같죠. 아이가 잠들면 배우자에게 10분 어깨 마사지를 부탁하세요. 엄마는 집의 기둥이고, 기둥도 쉬어야 해요.', title_nl = 'Massagesessie van papa 💆‍♂️', body_nl = 'Je stond vandaag lang op je benen en je rug doet pijn van het achter hem aan rennen. Vraag je partner zodra hij slaapt om een schoudermassage van 10 minuten. Jij bent de pilaar van het huis, en pilaren moeten ook rusten.', title_pl = 'Seans masażu od taty 💆‍♂️', body_pl = 'Dziś długo byłaś na nogach, a od biegania za nim pękają ci plecy. Gdy tylko dziecko zaśnie, poproś partnera o 10-minutowy masaż ramion. Jesteś filarem domu, a filary też muszą odpocząć.', title_pt = 'Sessão de massagem do pai 💆‍♂️', body_pt = 'Hoje passou muito tempo de pé e as costas doem de tanto correr atrás dele. Mal a criança adormeça, peça ao seu companheiro uma massagem de 10 minutos nos ombros. É o pilar da casa, e os pilares também precisam de descansar.', title_sv = 'Pappas massagestund 💆‍♂️', body_sv = 'Du har stått mycket i dag och ryggen värker efter allt springande efter barnet. Be din partner om en 10 minuters axelmassage så fort barnet somnar. Du är hemmets pelare, och pelare behöver också vila.', title_vi = 'Buổi mát-xa của bố 💆‍♂️', body_vi = 'Hôm nay mẹ đứng quá nhiều, chạy theo bé đến gãy cả lưng. Bé vừa ngủ, hãy nhờ chồng mát-xa vai 10 phút. Mẹ là trụ cột của gia đình, mà trụ cột cũng cần được nghỉ ngơi.', title_zh = '爸爸的按摩时间 💆‍♂️', body_zh = '今天站了太久，追着宝宝跑得腰都快断了。孩子一睡着，就请另一半给你做10分钟肩部按摩。你是家里的顶梁柱，顶梁柱也需要休息。' WHERE id = '2f5f6f47-30c9-4601-933d-5baa445585db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Respirar en comunidad 💬', body_es = '¿Estás agotada y te sientes la madre más impaciente del mundo? Abre ya la Comunidad Anacan. Leer que otras madres viven las mismas crisis es el mayor apoyo psicológico.', title_fr = 'Respirer grâce à la Communauté 💬', body_fr = 'Très fatiguée, vous vous sentez la maman la plus impatiente du monde ? Ouvrez tout de suite la Communauté Anacan. Lire que d''autres mamans traversent les mêmes crises est le plus grand soutien psychologique.', title_hi = 'कम्युनिटी में सुकून की साँस 💬', body_hi = 'बहुत थक गई हैं और खुद को दुनिया की सबसे बेसब्र माँ महसूस कर रही हैं? तुरंत Anacan कम्युनिटी खोलिए। यह पढ़ना कि दूसरी माँएँ भी ऐसे ही मुश्किल पलों से गुज़रती हैं, सबसे बड़ा मानसिक सहारा है।', title_id = 'Bernapas lega di komunitas 💬', body_id = 'Sangat lelah dan merasa menjadi ibu paling tidak sabar di dunia? Segera buka Komunitas Anacan. Membaca bahwa ibu lain mengalami krisis yang sama adalah dukungan psikologis terbesar.', title_ja = 'コミュニティでひと息 💬', body_ja = 'とても疲れて、世界でいちばんがまんの足りないママだと感じていますか？すぐにAnacanコミュニティを開きましょう。ほかのママも同じ大変さを経験していると読むことが、いちばんの心の支えになります。', title_ko = '커뮤니티에서 숨 돌리기 💬', body_ko = '너무 지쳐서 세상에서 가장 인내심 없는 엄마가 된 것 같나요? 바로 Anacan 커뮤니티를 열어 보세요. 다른 엄마들도 같은 고비를 겪는다는 걸 읽는 것만으로 큰 위로가 돼요.', title_nl = 'Op adem komen in de community 💬', body_nl = 'Ben je erg moe en voel je je de ongeduldigste moeder ter wereld? Open meteen de Anacan Community. Lezen dat andere moeders dezelfde crises meemaken is de grootste psychologische steun.', title_pl = 'Oddech w Społeczności 💬', body_pl = 'Jesteś bardzo zmęczona i czujesz się najmniej cierpliwą mamą na świecie? Od razu otwórz Społeczność Anacan. Czytanie, że inne mamy przeżywają te same kryzysy, to największe wsparcie psychiczne.', title_pt = 'Respirar em comunidade 💬', body_pt = 'Está muito cansada e sente-se a mãe mais impaciente do mundo? Abra já a Comunidade Anacan. Ler que outras mães passam pelas mesmas crises é o maior apoio psicológico.', title_sv = 'Andas i gemenskapen 💬', body_sv = 'Är du väldigt trött och känner dig som världens mest otåliga mamma? Öppna genast Anacan Community. Att läsa att andra mammor går igenom samma kriser är det största psykologiska stödet.', title_vi = 'Thở phào cùng Cộng đồng 💬', body_vi = 'Mẹ quá mệt mỏi và thấy mình là người mẹ thiếu kiên nhẫn nhất thế giới? Hãy mở ngay Cộng đồng Anacan. Đọc những chia sẻ của các mẹ khác cũng trải qua những khủng hoảng như vậy là sự hỗ trợ tâm lý lớn nhất.', title_zh = '在社区里喘口气 💬', body_zh = '太累了，觉得自己是世界上最没耐心的妈妈？马上打开Anacan社区。读到其他妈妈也在经历同样的崩溃，就是最大的心理支持。' WHERE id = 'f3fc49f1-990c-4271-ab6c-21a94434e4c2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El acertijo de las nubes ⛅', body_es = '¿Las cuatro paredes agobian? Preparaos con Tiempo y ropa y salid al parque. Simplemente sentaos y buscad a qué se parecen las nubes del cielo. Este juego pasivo descansa y a la vez estimula el cerebro.', title_fr = 'L''énigme des nuages ⛅', body_fr = 'Les quatre murs vous étouffent ? Préparez-vous avec Météo et tenue et sortez au parc. Asseyez-vous simplement et cherchez à quoi ressemblent les nuages. Ce jeu passif repose le cerveau tout en le stimulant.', title_hi = 'बादलों की पहेली ⛅', body_hi = 'चार दीवारें घुटन दे रही हैं? मौसम और कपड़े टूल से तैयार होकर पार्क जाइए। बस बैठिए और आसमान में ढूँढिए कि बादल किस चीज़ जैसे दिखते हैं। यह शांत खेल दिमाग को आराम भी देता है और विकसित भी करता है।', title_id = 'Teka-teki awan ⛅', body_id = 'Empat dinding terasa menyesakkan? Berpakaianlah sesuai cuaca dan pergilah ke taman. Duduk saja dan tebak bentuk awan di langit. Permainan pasif ini menenangkan sekaligus mengembangkan otak.', title_ja = '雲のなぞなぞ ⛅', body_ja = '家にこもって息がつまりそう？「天気と服装」で準備して公園へ出かけましょう。ただ座って、空の雲が何に見えるか探してみて。この静かな遊びは、脳を休ませながら育ててくれます。', title_ko = '구름 수수께끼 ⛅', body_ko = '네 벽이 답답한가요? 날씨와 옷차림을 확인하고 공원으로 나가세요. 그냥 앉아서 하늘의 구름이 무엇을 닮았는지 찾아보세요. 이 조용한 놀이는 뇌를 쉬게 하면서 발달도 도와줘요.', title_nl = 'Het raadsel van de wolken ⛅', body_nl = 'Kruipen de muren op je af? Bereid je voor met Weer en kleding en ga naar het park. Ga gewoon zitten en zoek samen waar de wolken op lijken. Dit rustige spel ontspant en stimuleert de hersenen tegelijk.', title_pl = 'Zagadka chmur ⛅', body_pl = 'Cztery ściany przytłaczają? Przygotujcie się z Pogodą i ubiorem i wyjdźcie do parku. Po prostu usiądźcie i szukajcie, do czego podobne są chmury. Ta spokojna zabawa i relaksuje mózg, i go rozwija.', title_pt = 'A adivinha das nuvens ⛅', body_pt = 'As quatro paredes sufocam? Prepare-se com o Tempo e Roupa e vão ao parque. Sentem-se e descubram com o que se parecem as nuvens no céu. Este jogo passivo descansa e desenvolve o cérebro.', title_sv = 'Molngåtan ⛅', body_sv = 'Kväver de fyra väggarna dig? Förbered er med Väder och kläder och gå till parken. Sätt er bara ner och lista ut vad molnen på himlen liknar. Den här passiva leken både vilar och utvecklar hjärnan.', title_vi = 'Câu đố từ những đám mây ⛅', body_vi = 'Bốn bức tường như ngột ngạt? Hãy mặc đồ theo Thời tiết và trang phục rồi ra công viên. Chỉ cần ngồi xuống và tìm xem những đám mây trên trời giống cái gì. Trò chơi thụ động này vừa giúp não nghỉ ngơi vừa phát triển.', title_zh = '云朵猜谜 ⛅', body_zh = '四面墙让人透不过气？用天气穿衣工具准备好，去公园吧。就坐着找一找天上的云朵像什么。这种安静的游戏既能让大脑休息，又能促进发展。' WHERE id = '3bcabb18-ba8e-4729-bb3a-959b28fdcaeb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Primeras mentirijillas? 🤥', body_es = '«El agua no la he tirado yo, la ha tirado mi osito». ¡Atención! Su imaginación se ha desarrollado tanto que puede inventarse los hechos a su favor. No le acuses de mentiroso; sonríe y dile: «Dile a tu osito que no la vuelva a tirar».', title_fr = 'Premiers petits mensonges ? 🤥', body_fr = '« C''est pas moi qui ai renversé l''eau, c''est mon nounours. » Attention ! Son imagination est si développée qu''il peut inventer les faits à son avantage. Ne l''accusez pas de mentir, souriez et dites : « Dis à ton nounours de ne plus la renverser. »', title_hi = 'पहले मासूम झूठ? 🤥', body_hi = '''पानी मैंने नहीं गिराया, मेरे टेडी ने गिराया।'' ध्यान दीजिए! कल्पना इतनी बढ़ गई है कि वह घटनाओं को अपने फ़ायदे के लिए गढ़ सकता है। उस पर झूठ बोलने का इल्ज़ाम मत लगाइए, मुस्कुराकर कहिए ''अपने टेडी से कहो, दोबारा न गिराए।''', title_id = 'Kebohongan manis pertama? 🤥', body_id = '''Bukan aku yang menumpahkan air, beruangku yang menumpahkannya.'' Perhatikan! Imajinasinya sudah begitu berkembang hingga ia bisa mengarang kejadian demi keuntungannya. Jangan tuduh ia berbohong, tersenyumlah dan katakan ''Bilang ke beruangmu, jangan tumpahkan lagi ya''.', title_ja = 'はじめてのかわいいうそ？🤥', body_ja = '「お水をこぼしたのはぼくじゃなくて、くまさんだよ」。注目！想像力がここまで育って、出来事を自分に都合よく作れるようになりました。うそつき扱いせず、「くまさんに、もうこぼさないでって言ってね」とほほえみましょう。', title_ko = '첫 귀여운 거짓말? 🤥', body_ko = '''물은 내가 안 쏟았어, 곰돌이가 쏟았어.'' 주목! 상상력이 자라서 일을 자기에게 유리하게 지어낼 수 있게 됐어요. 거짓말쟁이라고 탓하지 말고 ''곰돌이한테 다시는 쏟지 말라고 전해 줘'' 하고 웃어 주세요.', title_nl = 'De eerste schattige leugentjes? 🤥', body_nl = '''Ik heb het water niet gemorst, mijn beertje deed het.'' Let op! Zijn fantasie is zo ver ontwikkeld dat hij dingen in zijn voordeel kan verzinnen. Beschuldig hem niet van liegen, maar zeg met een glimlach: ''Zeg maar tegen je beertje dat hij het niet meer moet doen.''', title_pl = 'Pierwsze słodkie kłamstewka? 🤥', body_pl = '„To nie ja wylałem wodę, to mój miś”. Uwaga! Wyobraźnia rozwinęła się tak bardzo, że potrafi zmyślać zdarzenia na swoją korzyść. Nie oskarżaj go o kłamstwo, uśmiechnij się i powiedz: „Powiedz misiowi, żeby więcej nie wylewał”.', title_pt = 'As primeiras mentirinhas doces? 🤥', body_pt = '"Não fui eu que entornei a água, foi o meu ursinho." Atenção! A imaginação desenvolveu-se tanto que já consegue inventar os acontecimentos a seu favor. Não o acuse de mentir; sorria e diga: "Diz ao teu ursinho que não volte a entornar."', title_sv = 'De första söta lögnerna? 🤥', body_sv = '”Det var inte jag som spillde vattnet, det var nallen.” Observera! Fantasin har utvecklats så mycket att barnet kan hitta på händelser till sin egen fördel. Anklaga inte barnet för att ljuga, le och säg ”Säg åt nallen att inte spilla igen”.', title_vi = 'Những lời nói dối ngọt ngào đầu tiên? 🤥', body_vi = '"Không phải con làm đổ nước, gấu bông làm đổ đấy." Chú ý! Trí tưởng tượng đã phát triển đến mức bé có thể bịa chuyện có lợi cho mình. Đừng buộc tội bé nói dối, hãy mỉm cười: "Con dặn gấu bông lần sau đừng làm đổ nữa nhé".', title_zh = '最初的小谎话？🤥', body_zh = '“水不是我洒的，是我的小熊洒的。”注意啦！想象力已经发展到能把事情编得对自己有利。别指责宝宝撒谎，笑着说一句“告诉你的小熊，下次别再洒了”。' WHERE id = '9de02d84-1ac6-4478-a817-67045fcd6af5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gimnasia matutina 🤸‍♂️', body_es = 'Tú aún no te has despertado, pero tu peque ya salta encima de ti en la cama. ¡El despertador más ruidoso, pero más adorable del mundo! Empieza el día riendo con su energía desbordante.', title_fr = 'Gym du matin 🤸‍♂️', body_fr = 'Vous n''êtes pas encore réveillée, mais il saute déjà sur vous dans le lit. Le réveil le plus bruyant, mais le plus adorable du monde ! Commencez la journée en riant avec son énergie débordante.', title_hi = 'सुबह की कसरत 🤸‍♂️', body_hi = 'आप अभी जागी भी नहीं हैं, लेकिन वह बिस्तर पर आपके ऊपर कूद रहा है। दुनिया की सबसे शोर भरी, लेकिन सबसे प्यारी अलार्म घंटी! उसकी इस बेहिसाब ऊर्जा के साथ हँसते हुए दिन शुरू कीजिए।', title_id = 'Senam pagi 🤸‍♂️', body_id = 'Anda belum bangun, tetapi ia sudah melompat ke atas Anda di tempat tidur. Alarm paling berisik namun paling menggemaskan di dunia! Mulai hari sambil tertawa bersama energinya yang tak terbatas.', title_ja = '朝の体操 🤸‍♂️', body_ja = 'あなたはまだ目が覚めていないのに、ベッドの上で飛び乗ってきますか？世界一にぎやかで、世界一かわいい目覚まし！このありあまるエネルギーと一緒に、笑って一日を始めましょう。', title_ko = '아침 체조 🤸‍♂️', body_ko = '엄마는 아직 잠이 덜 깼는데 아이는 벌써 침대에서 엄마 위로 뛰어오르나요? 세상에서 가장 시끄럽지만 가장 사랑스러운 알람이에요! 이 넘치는 에너지와 함께 웃으며 하루를 시작하세요.', title_nl = 'Ochtendgymnastiek 🤸‍♂️', body_nl = 'Jij bent nog niet eens wakker, maar hij springt al bovenop je in bed. De luidruchtigste, maar liefste wekker ter wereld! Begin de dag lachend met zijn grenzeloze energie.', title_pl = 'Poranna gimnastyka 🤸‍♂️', body_pl = 'Ty jeszcze się nie obudziłaś, a on już skacze po tobie w łóżku. Najgłośniejszy, ale najsłodszy budzik na świecie! Zacznij dzień ze śmiechem i jego ogromną energią.', title_pt = 'Ginástica matinal 🤸‍♂️', body_pt = 'Ainda não acordou e ele já está a saltar para cima de si na cama. O despertador mais barulhento, mas mais adorável do mundo! Comece o dia a rir com esta energia sem limites.', title_sv = 'Morgongympa 🤸‍♂️', body_sv = 'Du har inte ens vaknat, men barnet hoppar redan på dig i sängen. Världens mest högljudda men mest älskade väckarklocka! Börja dagen skrattande med barnets gränslösa energi.', title_vi = 'Thể dục buổi sáng 🤸‍♂️', body_vi = 'Mẹ còn chưa tỉnh mà bé đã nhảy lên người mẹ trên giường. Chiếc chuông báo thức ồn ào nhất nhưng đáng yêu nhất thế giới! Hãy bắt đầu ngày mới bằng nụ cười cùng nguồn năng lượng vô tận của bé.', title_zh = '晨练时间 🤸‍♂️', body_zh = '你还没醒，宝宝已经在床上往你身上跳了。世界上最吵、却也最可爱的叫醒铃！笑着带着宝宝这无限的能量开始新的一天吧。' WHERE id = '3af3aa71-d08b-4f87-af96-9527f5f91ec1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El desastre de ir al súper sin lista 🛒', body_es = '¿Has ido al súper y has vuelto sin lo más importante? Así es la memoria de madre. No te fíes de tu cabeza: acostúmbrate a apuntar al momento cada pequeña cosa en la Lista de la compra.', title_fr = 'Le fléau des courses sans liste 🛒', body_fr = 'Vous êtes allée au supermarché et rentrée sans l''essentiel ? C''est la mémoire de maman. Ne vous fiez pas à votre tête, prenez l''habitude de noter tout de suite le moindre besoin dans la Liste de courses.', title_hi = 'बिना लिस्ट के बाज़ार की मुसीबत 🛒', body_hi = 'बाज़ार गईं और सबसे ज़रूरी चीज़ लिए बिना लौट आईं? माँ की याददाश्त ऐसी ही होती है। दिमाग के भरोसे मत रहिए, हर छोटी ज़रूरत तुरंत शॉपिंग लिस्ट में लिखने की आदत डालिए।', title_id = 'Petaka belanja tanpa daftar 🛒', body_id = 'Pergi belanja dan pulang tanpa barang yang paling penting? Begitulah ingatan seorang ibu. Jangan mengandalkan otak, biasakan langsung mencatat setiap kebutuhan kecil di Daftar Belanja.', title_ja = 'リストなし買い物の災難 🛒', body_ja = '買い物に行ったのに、いちばん大事なものを買わずに帰ってきた？ママの記憶とはそういうもの。頭にたよらず、小さな必要なものもすぐに「買い物リスト」に書く習慣をつけましょう。', title_ko = '목록 없는 장보기의 비극 🛒', body_ko = '마트에 갔다가 가장 중요한 걸 빼고 돌아왔나요? 엄마의 기억력은 원래 그래요. 머리를 믿지 말고 작은 것 하나까지 바로 쇼핑 목록에 적는 습관을 들이세요.', title_nl = 'De ellende van boodschappen zonder lijstje 🛒', body_nl = 'Kwam je zonder het belangrijkste uit de supermarkt terug? Zo werkt een moederbrein nu eenmaal. Vertrouw niet op je hoofd, maar maak er een gewoonte van om alles wat je nodig hebt meteen op het Boodschappenlijstje te zetten.', title_pl = 'Zmora zakupów bez listy 🛒', body_pl = 'Poszłaś do sklepu i wróciłaś bez najważniejszej rzeczy? Taka już jest pamięć mamy. Nie polegaj na głowie, wyrób sobie nawyk, by od razu wpisywać każdą drobną potrzebę na Listę zakupów.', title_pt = 'O drama do supermercado sem lista 🛒', body_pt = 'Foi ao supermercado e voltou sem o mais importante? A memória de mãe é assim. Não confie na cabeça: crie o hábito de apontar logo na Lista de Compras cada pequena coisa que falta.', title_sv = 'Handla utan lista, en katastrof 🛒', body_sv = 'Gick du och handlade och kom hem utan det viktigaste? Så fungerar mammaminnet. Lita inte på hjärnan, gör det till en vana att genast skriva in minsta behov i Inköpslistan.', title_vi = 'Rắc rối khi đi chợ không có danh sách 🛒', body_vi = 'Mẹ đi siêu thị về mà không mua đúng món cần nhất? Trí nhớ của mẹ bỉm là vậy đó. Đừng tin vào trí nhớ, hãy tập ghi ngay mọi nhu cầu nhỏ nhất vào Danh sách mua sắm.', title_zh = '不带清单去超市的烦恼 🛒', body_zh = '去了超市，最主要的东西却没买就回来了？妈妈的记性就是这样。别依赖大脑，养成习惯，有任何小需要都马上写进购物清单。' WHERE id = '8c84402b-2c57-4668-ad1d-96d138e6ba29' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té a la luz de las velas 🕯️', body_es = 'Tu peque se ha dormido. Apaga las luces y enciende una vela en la mesa. No es para hacer algo romántico, sino para calmar tus nervios y tus ojos, irritados todo el día.', title_fr = 'Un thé à la lueur d''une bougie 🕯️', body_fr = 'L''enfant dort. Éteignez les lumières et allumez une bougie sur la table. Pas pour le romantisme, mais simplement pour apaiser vos nerfs et vos yeux mis à rude épreuve toute la journée.', title_hi = 'मोमबत्ती की रोशनी में चाय 🕯️', body_hi = 'बच्चा सो गया। लाइटें बंद कीजिए, मेज़ पर एक मोमबत्ती जलाइए। यह रोमांस के लिए नहीं, बस दिनभर से परेशान नसों और आँखों को सुकून देने के लिए है।', title_id = 'Teh di bawah cahaya lilin 🕯️', body_id = 'Anak sudah tidur. Matikan lampu dan nyalakan lilin di meja. Ini bukan untuk romantis, tetapi sekadar untuk menenangkan saraf dan mata Anda yang lelah seharian.', title_ja = 'キャンドルの明かりでお茶を 🕯️', body_ja = 'お子さんが眠りました。明かりを消して、テーブルにキャンドルをともしましょう。ロマンスのためではなく、一日じゅう張りつめていた神経と目を休ませるためです。', title_ko = '촛불 아래 차 한잔 🕯️', body_ko = '아이가 잠들었어요. 불을 끄고 탁자에 초를 하나 켜 보세요. 로맨스를 위해서가 아니라 하루 종일 예민해진 신경과 지친 눈을 달래기 위해서예요.', title_nl = 'Thee bij kaarslicht 🕯️', body_nl = 'Hij slaapt. Doe de lichten uit en steek een kaars aan op tafel. Niet voor de romantiek, maar gewoon om je overprikkelde zenuwen en vermoeide ogen na de hele dag tot rust te brengen.', title_pl = 'Herbata przy świecy 🕯️', body_pl = 'Dziecko śpi. Zgaś światła i zapal na stole świecę. Nie dla romantyzmu, tylko po to, by ukoić nerwy i oczy podrażnione przez cały dzień.', title_pt = 'Chá à luz da vela 🕯️', body_pt = 'A criança adormeceu. Apague as luzes e acenda uma vela na mesa. Não é para romance, é só para acalmar os nervos e os olhos irritados depois de um dia inteiro.', title_sv = 'Te i levande ljus 🕯️', body_sv = 'Barnet sover. Släck lamporna och tänd ett ljus på bordet. Inte för romantikens skull, utan bara för att lugna dina nerver och ögon som varit irriterade hela dagen.', title_vi = 'Trà dưới ánh nến 🕯️', body_vi = 'Bé ngủ rồi. Hãy tắt đèn và thắp một ngọn nến trên bàn. Không phải để lãng mạn, mà chỉ để xoa dịu thần kinh và đôi mắt đã căng thẳng cả ngày.', title_zh = '烛光下的茶 🕯️', body_zh = '孩子睡着了。关掉灯，在桌上点一支蜡烛。这不是为了浪漫，只是为了让紧绷了一整天的神经和眼睛放松下来。' WHERE id = '90c41ad8-7de7-4c6d-ba3d-cf1aad328939' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inteligencia artificial, ayuda real 🤖', body_es = '¿Qué hay psicológicamente detrás de que se oponga a todo? No busques artículos que asustan en internet. Pide a Anacan AI una explicación corta y científica sobre las crisis de los niños de 33 meses.', title_fr = 'Intelligence artificielle, aide réelle 🤖', body_fr = 'Quelle est la raison psychologique de son entêtement face à tout ? Ne cherchez pas d''articles effrayants sur Internet. Demandez à Anacan AI une explication scientifique et courte sur les crises des enfants de 33 mois.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस, असली मदद 🤖', body_hi = 'बच्चे की हर बात पर ज़िद के पीछे मनोवैज्ञानिक वजह क्या है? इंटरनेट पर डरावने लेख मत ढूँढिए। Anacan AI से 33 महीने के बच्चों के मुश्किल दौर के बारे में वैज्ञानिक, छोटी सी जानकारी माँगिए।', title_id = 'Kecerdasan buatan, bantuan nyata 🤖', body_id = 'Apa latar psikologis di balik sifat keras kepalanya untuk segala hal? Jangan mencari artikel menakutkan di internet. Minta penjelasan ilmiah dan singkat tentang krisis anak usia 33 bulan dari Anacan AI.', title_ja = 'AI、本物のサポート 🤖', body_ja = 'お子さんがなんにでも反抗する心理的な背景は？ネットでこわい記事を探さないで。生後33か月の子の危機について、科学的で短い説明をAnacan AIに聞いてみましょう。', title_ko = '인공지능, 진짜 도움 🤖', body_ko = '아이가 모든 것에 고집을 부리는 심리적 이유가 궁금한가요? 인터넷에서 무서운 글을 찾지 마세요. Anacan AI에게 33개월 아이의 고비에 대한 과학적이고 짧은 설명을 요청하세요.', title_nl = 'Kunstmatige intelligentie, echte hulp 🤖', body_nl = 'Wat zit er psychologisch achter zijn koppigheid? Zoek niet naar enge artikelen op internet. Vraag Anacan AI om een korte, wetenschappelijke uitleg over de crises van kinderen van 33 maanden.', title_pl = 'Sztuczna inteligencja, prawdziwa pomoc 🤖', body_pl = 'Jakie jest psychologiczne podłoże tego, że na wszystko się upiera? Nie szukaj w internecie przerażających artykułów. Poproś Anacan AI o naukowe, krótkie wyjaśnienie kryzysów 33-miesięcznych dzieci.', title_pt = 'Inteligência artificial, ajuda real 🤖', body_pt = 'Qual é o fundo psicológico da teimosia dele em tudo? Não procure artigos assustadores na internet. Peça ao Anacan AI uma explicação científica e curta sobre as crises das crianças de 33 meses.', title_sv = 'Artificiell intelligens, verklig hjälp 🤖', body_sv = 'Vad är den psykologiska bakgrunden till att barnet är envist med allt? Sök inte efter skrämmande artiklar på nätet. Be Anacan AI om en vetenskaplig, kort förklaring om kriserna hos 33-månadersbarn.', title_vi = 'Trí tuệ nhân tạo, sự giúp đỡ thật 🤖', body_vi = 'Nguyên nhân tâm lý của việc bé bướng bỉnh với mọi thứ là gì? Đừng tìm đọc những bài báo đáng sợ trên mạng. Hãy hỏi Anacan AI để có lời giải thích ngắn gọn, khoa học về khủng hoảng ở trẻ 33 tháng.', title_zh = '人工智能，真实的帮助 🤖', body_zh = '孩子什么都要对着干，背后的心理原因是什么？别在网上搜那些吓人的文章。向Anacan AI要一份关于33个月宝宝危机期的科学、简短的解释吧。' WHERE id = '4390f43b-f533-4c56-8aa2-5901fd06c8f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rutina se descoloca ⏱️', body_es = '¿Tarda más de 1 hora en dormirse por la noche? Mira el gráfico del temporizador de sueño. Quizá hace tiempo que toca acortar del todo la siesta y adelantar la hora de dormir.', title_fr = 'Le rythme se décale ⏱️', body_fr = 'L''endormissement du soir prend plus d''1 heure ? Regardez le graphique du Minuteur de sommeil. Il est peut-être grand temps de raccourcir nettement la sieste et d''avancer l''heure du coucher.', title_hi = 'रूटीन खिसक रहा है ⏱️', body_hi = 'शाम को सोने में 1 घंटे से ज़्यादा लगता है? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद को और छोटा करने और शाम का रूटीन जल्दी करने का समय कब का आ चुका है।', title_id = 'Rutinitas bergeser ⏱️', body_id = 'Tidur malam butuh lebih dari 1 jam? Lihat grafik Timer Tidur. Mungkin sudah lama tiba waktunya memangkas tidur siang dan memajukan jam tidur malam.', title_ja = '生活リズムのずれ ⏱️', body_ja = '夜の寝かしつけに1時間以上かかりますか？睡眠タイマーのグラフを見てみましょう。お昼寝を短くして、夜の寝る時間を早める時期がとっくに来ているのかもしれません。', title_ko = '일과가 밀려요 ⏱️', body_ko = '저녁에 잠드는 데 1시간 넘게 걸리나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 확 줄이고 잠자리 시간을 앞당길 때가 진작 되었을지도 몰라요.', title_nl = 'Het ritme verschuift ⏱️', body_nl = 'Duurt inslapen ''s avonds langer dan een uur? Bekijk het schema in de Slaaptimer. Misschien is het allang tijd om het middagslaapje flink in te korten en de avond te vervroegen.', title_pl = 'Przesunięcie rytmu dnia ⏱️', body_pl = 'Wieczorne zasypianie trwa ponad 1 godzinę? Spójrz na wykres w timerze snu. Może już dawno czas skrócić drzemkę w ciągu dnia i przesunąć wieczór na wcześniej.', title_pt = 'A rotina está a fugir ⏱️', body_pt = 'Adormecer à noite demora mais de 1 hora? Veja o gráfico do temporizador de sono. Talvez já tenha passado a altura de encurtar de vez a sesta e antecipar a hora de deitar.', title_sv = 'Rutinen glider iväg ⏱️', body_sv = 'Tar det mer än 1 timme för barnet att somna på kvällen? Titta på sömntimerns diagram. Kanske är det sedan länge dags att korta dagsömnen ordentligt och tidigarelägga kvällen.', title_vi = 'Nếp sinh hoạt bị lệch ⏱️', body_vi = 'Buổi tối bé mất hơn 1 tiếng mới ngủ được? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đã đến lúc rút ngắn hẳn giấc ngủ ngày và cho bé đi ngủ tối sớm hơn.', title_zh = '作息乱了 ⏱️', body_zh = '晚上入睡要花1个多小时？看看睡眠计时器的图表。也许早就该把白天的午睡大大缩短，把晚上的入睡时间提前了。' WHERE id = '70560836-1d71-42c8-8235-1ad990694b3b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El drama de peinarse 🪮', body_es = '¿Grita como si peinarle o tocarle el pelo fuera la peor tortura del mundo? Para la batalla. Primero dale el peine y deja que te peine él a ti; luego te toca a ti.', title_fr = 'Le drame du coiffage 🪮', body_fr = 'Il hurle comme si se faire peigner ou coiffer était la pire des tortures ? Arrêtez la lutte. Donnez-lui d''abord le peigne pour qu''il vous coiffe, puis ce sera votre tour.', title_hi = 'बाल सँवारने पर हंगामा 🪮', body_hi = 'बाल सँवारने या छूने पर ऐसे चिल्लाता है जैसे दुनिया की सबसे बड़ी सज़ा हो? जंग रोकिए। पहले कंघी उसे दीजिए, उसे आपके बाल सँवारने दीजिए, फिर बारी आपकी।', title_id = 'Drama menyisir rambut 🪮', body_id = 'Ia menjerit seolah menyisir atau menyentuh rambutnya adalah siksaan terbesar di dunia? Hentikan perdebatan. Berikan sisirnya dulu, biarkan ia menyisir rambut Anda, lalu giliran Anda.', title_ja = '髪をとかすときの大騒ぎ 🪮', body_ja = '髪をとかしたり、さわったりするだけで、世界一ひどい拷問のように叫びますか？戦いはやめましょう。まずくしを渡して、あなたの髪をとかしてもらい、それからあなたの番にしましょう。', title_ko = '머리 빗기 대소동 🪮', body_ko = '머리를 빗거나 묶는 게 세상 최고의 고문인 듯 소리를 지르나요? 씨름은 멈추세요. 먼저 빗을 건네 엄마 머리를 빗게 하고, 그다음 엄마 차례로 해 보세요.', title_nl = 'Drama bij het haren kammen 🪮', body_nl = 'Schreeuwt hij alsof haren kammen of vlechten de ergste marteling ter wereld is? Stop de strijd. Geef hem eerst de kam en laat hem jouw haar kammen, daarna ben jij aan de beurt.', title_pl = 'Burza przy czesaniu 🪮', body_pl = 'Krzyczy przy czesaniu i dotykaniu włosów, jakby to była największa tortura świata? Przerwij walkę. Najpierw daj mu grzebień, niech uczesze ciebie, a potem twoja kolej.', title_pt = 'O drama do pentear 🪮', body_pt = 'Grita ao pentear ou ao tocar no cabelo como se fosse a maior tortura do mundo? Pare a luta. Primeiro dê-lhe o pente e deixe-o pentear o seu cabelo; depois é a sua vez.', title_sv = 'Kaos vid hårborstningen 🪮', body_sv = 'Skriker barnet som om det vore världens största tortyr att borsta eller fläta håret? Avbryt kampen. Ge först borsten till barnet och låt hen borsta ditt hår, sedan är det din tur.', title_vi = 'Cuộc chiến chải tóc 🪮', body_vi = 'Bé la hét như thể chải tóc, chạm vào tóc là cực hình lớn nhất thế giới? Hãy dừng giằng co. Trước tiên đưa lược cho bé chải tóc cho mẹ, rồi mới đến lượt mẹ.', title_zh = '梳头大战 🪮', body_zh = '梳头、扎头发时，像受了天大的折磨一样尖叫？停下这场对抗。先把梳子给宝宝，让宝宝给你梳头，然后再轮到你。' WHERE id = 'dfed41fd-982b-4955-b70f-6d43247a4468' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Está pálido o sin apetito? Comprueba el hierro en el Seguimiento de tomas. Junto con la carne, dale siempre ensalada con limón para mejorar al instante la absorción de vitaminas.', body_fr = 'Il a le teint pâle ou peu d''appétit ? Vérifiez ses apports en fer dans le Suivi des repas. Servez toujours une salade citronnée avec la viande pour mieux absorber les vitamines.', body_hi = 'चेहरा पीला है या भूख नहीं लगती? फ़ीडिंग ट्रैकर में आयरन देखिए। मांस के साथ नींबू वाला सलाद ज़रूर दीजिए ताकि विटामिन का अवशोषण तुरंत बढ़े।', body_id = 'Ia tampak pucat atau tidak berselera makan? Periksa asupan zat besinya di Pemantau Nutrisi. Selalu sajikan salad dengan lemon bersama daging untuk langsung meningkatkan penyerapan vitamin.', body_ja = '顔色が悪かったり、食欲がなかったりしますか？「栄養管理ツール」で鉄分摂取を確認しましょう。お肉と一緒に必ずレモンをかけたサラダを出して、ビタミンの吸収をすぐに高めて。', body_ko = '얼굴이 창백하거나 입맛이 없나요? 수유 기록 도구로 철분 섭취를 확인하세요. 고기와 함께 레몬 샐러드를 꼭 곁들여 흡수를 바로 높여 주세요.', body_nl = 'Ziet hij bleek of heeft hij weinig trek? Check het ijzer in de Voedingstracker. Geef bij vlees altijd een salade met citroen om de opname van vitamines direct te verbeteren.', body_pl = 'Jest blady albo nie ma apetytu? Sprawdź spożycie żelaza w narzędziu do śledzenia karmienia. Do mięsa koniecznie podawaj sałatkę z cytryną, by od razu poprawić wchłanianie witamin.', body_pt = 'Está pálido ou sem apetite? Verifique a ingestão de ferro no Registo de Alimentação. Sirva sempre a carne com uma salada com limão para melhorar logo a absorção.', body_sv = 'Är barnet blekt eller utan aptit? Kolla järnintaget i Matningskoll. Servera alltid en sallad med citron till köttet för att direkt öka vitaminupptaget.', body_vi = 'Bé xanh xao hoặc biếng ăn? Hãy kiểm tra lượng sắt trong Theo dõi cữ bú. Nhất định cho bé ăn thịt kèm salad có nước cốt chanh để tăng hấp thu vitamin ngay lập tức.', body_zh = '脸色苍白或没胃口？在喂养记录工具里查看铁的摄入。搭配肉类时一定要配上柠檬沙拉，马上提高维生素的吸收。' WHERE id = '5b72c8ce-753e-4283-9bd2-18995d662a91' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lección para compartir juguetes 🧸', body_es = 'Antes de ir al parque, charlad: «Hoy nos vamos a dejar los juguetes por turnos». Sí, puede que otra vez no los deje, pero es clave que escuche esta regla abstracta una y otra vez.', title_fr = 'Leçon de partage des jouets 🧸', body_fr = 'Avant d''aller au parc, discutez : « Aujourd''hui, on va prêter nos jouets chacun son tour. » Oui, il ne prêtera sûrement toujours pas, mais il a besoin d''entendre et réentendre cette règle abstraite.', title_hi = 'खिलौने बाँटने का सबक 🧸', body_hi = 'पार्क जाने से पहले बात कीजिए: ''आज हम अपने खिलौने बारी-बारी से देंगे।'' हाँ, वह फिर भी नहीं देगा, लेकिन इस अमूर्त नियम को बार-बार सुनना ज़रूरी है।', title_id = 'Pelajaran berbagi mainan 🧸', body_id = 'Sebelum ke taman, bicarakan: ''Hari ini kita akan bergiliran meminjamkan mainan.'' Ya, ia mungkin tetap tidak mau, tetapi ia perlu mendengar aturan abstrak ini berulang kali.', title_ja = 'おもちゃを分け合うレッスン 🧸', body_ja = '公園に行く前に「今日はおもちゃを順番に貸してあげようね」とお話ししましょう。そう、きっとまた貸さないでしょう。でも、この抽象的なルールを何度も聞くことが大切なのです。', title_ko = '장난감 나누기 수업 🧸', body_ko = '공원에 가기 전에 ''오늘은 장난감을 차례대로 빌려줄 거야'' 하고 미리 이야기해 보세요. 네, 또 안 빌려주겠지만 이 추상적인 규칙을 거듭 듣는 게 꼭 필요해요.', title_nl = 'Les in speelgoed delen 🧸', body_nl = 'Bespreek voor jullie naar het park gaan: ''Vandaag geven we ons speelgoed om de beurt.'' Ja, hij zal het weer niet doen, maar het is nodig dat hij deze abstracte regel steeds opnieuw hoort.', title_pl = 'Lekcja dzielenia się zabawkami 🧸', body_pl = 'Zanim pójdziecie do parku, porozmawiajcie: „Dziś będziemy dawać zabawki po kolei”. Tak, i tak pewnie nie da, ale musi słyszeć tę abstrakcyjną zasadę wciąż od nowa.', title_pt = 'Aula de partilha de brinquedos 🧸', body_pt = 'Antes de irem ao parque, combinem: "Hoje vamos emprestar os brinquedos à vez." Sim, provavelmente não vai emprestar, mas é essencial que ouça esta regra abstrata vezes sem conta.', title_sv = 'Lektion i att dela leksaker 🧸', body_sv = 'Innan ni går till parken, prata om att ”I dag turas vi om med leksakerna”. Ja, barnet kommer inte att dela nu heller, men det är viktigt att hen hör den här abstrakta regeln om och om igen.', title_vi = 'Bài học chia sẻ đồ chơi 🧸', body_vi = 'Trước khi ra công viên, hãy thỏa thuận: "Hôm nay mình sẽ cho bạn mượn đồ chơi lần lượt nhé". Đúng là bé vẫn sẽ không cho, nhưng việc được nghe đi nghe lại quy tắc trừu tượng này là rất cần thiết.', title_zh = '玩具分享课 🧸', body_zh = '去公园之前，先聊聊“今天我们的玩具要轮流给别人玩”。没错，宝宝可能还是不给，但反复听到这条抽象的规则非常必要。' WHERE id = 'b0a26358-dcc7-4a57-8694-6e91e9d4baaa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica de sueño de papá 👨‍🍼', body_es = '¿Por la noche no quiere ponerse el pijama y sale corriendo? Pásale la pelota a papá. Cuando convierte vestirse en una lucha o un juego gracioso, tu peque acaba con el pijama puesto sin darse cuenta.', title_fr = 'La tactique de sommeil de papa 👨‍🍼', body_fr = 'Il ne veut pas mettre son pyjama le soir et s''enfuit ? Passez la balle à papa. Quand il transforme l''habillage en lutte ou en jeu comique, l''enfant se retrouve en pyjama sans même s''en rendre compte.', title_hi = 'पापा की नींद वाली तरकीब 👨‍🍼', body_hi = 'रात को पजामा नहीं पहनना चाहता और भागता है? बॉल पापा के पाले में डालिए। जब वे कपड़े पहनाने को कुश्ती या मज़ेदार खेल बना देते हैं, तो बच्चा बिना जाने पजामा पहन चुका होता है।', title_id = 'Taktik tidur ala Ayah 👨‍🍼', body_id = 'Malam hari ia tidak mau memakai piyama dan malah kabur? Oper bolanya kepada Ayah. Saat Ayah mengubah berpakaian menjadi gulat atau permainan lucu, tanpa sadar si kecil sudah memakai piyamanya.', title_ja = 'パパの寝かしつけ作戦 👨‍🍼', body_ja = '夜パジャマを着たがらず逃げていきますか？パパにバトンを渡しましょう。パパが着がえをレスリングやおもしろい遊びに変えると、お子さんは気づかないうちにパジャマを着ています。', title_ko = '아빠의 재우기 전략 👨‍🍼', body_ko = '밤에 잠옷을 안 입겠다며 도망가나요? 아빠에게 공을 넘기세요. 아빠가 옷 입히기를 레슬링이나 웃긴 놀이로 바꾸면 아이는 자기도 모르게 잠옷을 입고 있을 거예요.', title_nl = 'Papa''s slaaptactiek 👨‍🍼', body_nl = 'Wil hij ''s avonds geen pyjama aan en rent hij weg? Speel de bal naar papa. Als hij van het aankleden een stoeipartij of een grappig spel maakt, heeft je kindje zijn pyjama aan zonder het te merken.', title_pl = 'Taktyka usypiania taty 👨‍🍼', body_pl = 'Wieczorem nie chce zakładać piżamy i ucieka? Podaj piłeczkę tacie. Gdy zamienia przebieranie w zapasy albo zabawną grę, dziecko nawet nie zauważa, kiedy ma już piżamę na sobie.', title_pt = 'A tática de sono do pai 👨‍🍼', body_pt = 'À noite não quer vestir o pijama e foge? Passe a bola ao pai. Quando ele transforma o vestir numa luta a brincar ou num jogo cómico, a criança fica de pijama sem dar por isso.', title_sv = 'Pappas sömntaktik 👨‍🍼', body_sv = 'Vill barnet inte ta på sig pyjamasen på kvällen och springer iväg? Passa bollen till pappa. När han gör påklädningen till brottning eller en rolig lek har barnet pyjamasen på sig innan hen ens märkt det.', title_vi = 'Chiến thuật ru ngủ của bố 👨‍🍼', body_vi = 'Buổi tối bé không chịu mặc đồ ngủ và chạy trốn? Hãy "chuyền bóng" cho bố. Khi bố biến việc mặc đồ thành trò vật nhau hay trò chơi hài hước, bé đã mặc xong đồ ngủ lúc nào không hay.', title_zh = '爸爸的哄睡战术 👨‍🍼', body_zh = '晚上不肯穿睡衣，到处跑？把球传给爸爸。他把穿衣变成摔跤或搞笑游戏时，孩子不知不觉就已经穿好睡衣了。' WHERE id = 'c1d1533f-3d3f-4fb5-a549-d74668c72b3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Acertijo de la naturaleza 🍁', body_es = 'En el parque, en lugar de solo pasear, pasad a jugar: «¡Vamos a buscar la hoja amarilla más grande!». La naturaleza es para tu peque la escuela más grande e interactiva.', title_fr = 'L''énigme de la nature 🍁', body_fr = 'Au parc, au lieu de simplement marcher, passez au jeu : « Viens, on cherche la plus grande feuille jaune ! » La nature est pour lui la plus grande école, et la plus interactive.', title_hi = 'प्रकृति की पहेली 🍁', body_hi = 'पार्क में सिर्फ़ टहलने के बजाय खेल शुरू कीजिए: ''चलो, सबसे बड़ा पीला पत्ता ढूँढें!'' प्रकृति उसके लिए सबसे बड़ा और इंटरैक्टिव स्कूल है।', title_id = 'Teka-teki alam 🍁', body_id = 'Daripada sekadar berjalan di taman, ubah jadi permainan: ''Ayo cari daun kuning paling besar!'' Alam adalah sekolah terbesar dan paling interaktif baginya.', title_ja = '自然のなぞなぞ 🍁', body_ja = '公園ではただ歩くかわりに遊びにしましょう：「いちばん大きな黄色い葉っぱを探そう！」自然はお子さんにとっていちばん大きくて、体験できる学校です。', title_ko = '자연 수수께끼 🍁', body_ko = '공원에서 그냥 걷지 말고 놀이로 바꿔 보세요: ''가장 큰 노란 나뭇잎을 찾아보자!'' 자연은 아이에게 가장 크고 생생한 학교예요.', title_nl = 'Natuurraadsel 🍁', body_nl = 'Maak van de wandeling in het park een spel: ''Kom, we zoeken het grootste gele blad!'' De natuur is voor hem de grootste en meest interactieve school.', title_pl = 'Przyrodnicza zagadka 🍁', body_pl = 'Zamiast zwykłego spaceru w parku przejdźcie do zabawy: „Znajdźmy największy żółty liść!”. Przyroda to dla niego największa i najbardziej interaktywna szkoła.', title_pt = 'A adivinha da natureza 🍁', body_pt = 'No parque, em vez de só passear, passem a um jogo: "Vamos encontrar a maior folha amarela!" A natureza é para ele a maior e mais interativa escola.', title_sv = 'Naturgåta 🍁', body_sv = 'Byt promenaden i parken mot en lek: ”Ska vi hitta det största gula lövet?” Naturen är barnets största och mest interaktiva skola.', title_vi = 'Câu đố thiên nhiên 🍁', body_vi = 'Ở công viên, thay vì chỉ đi dạo hãy chuyển sang trò chơi: "Mình cùng tìm chiếc lá vàng to nhất nhé!" Thiên nhiên là ngôi trường lớn nhất và sinh động nhất với bé.', title_zh = '大自然猜谜 🍁', body_zh = '在公园里别只是散步，来玩个游戏吧：“我们来找最大的黄叶子！”大自然是宝宝最大、最有互动性的学校。' WHERE id = '3aee856b-a30f-48de-84ad-3c91f83ed092' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Fascinación por la lavadora 🧺', body_es = '¿Se sienta delante de la lavadora y se queda mirando la ropa dar vueltas? Es un entretenimiento totalmente gratis que calma la mente. No le interrumpas y aprovecha tú también para descansar.', title_fr = 'Fasciné par la machine à laver 🧺', body_fr = 'Il est assis devant la machine à laver, captivé par le linge qui tourne ? C''est un divertissement totalement gratuit qui apaise l''esprit. Ne l''interrompez pas, profitez-en pour vous reposer vous aussi.', title_hi = 'वॉशिंग मशीन का आकर्षण 🧺', body_hi = 'वॉशिंग मशीन के सामने बैठकर घूमते कपड़ों को देखता रहता है? यह पूरी तरह मुफ़्त और मन को शांत करने वाला मनोरंजन है। उसे मत रोकिए, आप भी मौके का फ़ायदा उठाकर आराम कीजिए।', title_id = 'Terpikat mesin cuci 🧺', body_id = 'Ia duduk di depan mesin cuci dan terpaku pada pakaian yang berputar? Ini hiburan gratis yang menenangkan pikiran. Jangan ganggu, manfaatkan kesempatan ini untuk beristirahat juga.', title_ja = '洗濯機に夢中 🧺', body_ja = '洗濯機の前に座って、回る洗濯物に見入っていますか？これはまったくお金のかからない、心を落ち着かせる楽しみです。じゃまをせず、あなたもこのチャンスに休みましょう。', title_ko = '세탁기 사랑 🧺', body_ko = '세탁기 앞에 앉아 돌아가는 빨래에 푹 빠졌나요? 완전히 무료이면서 마음을 차분하게 해 주는 놀이예요. 방해하지 말고 엄마도 이 틈에 쉬세요.', title_nl = 'Gefascineerd door de wasmachine 🧺', body_nl = 'Zit hij voor de wasmachine en kijkt hij gefocust naar de draaiende was? Dit is helemaal gratis vermaak dat de geest kalmeert. Stoor hem niet en grijp zelf ook de kans om uit te rusten.', title_pl = 'Fascynacja pralką 🧺', body_pl = 'Siedzi przed pralką i wpatruje się w kręcące się ubrania? To całkowicie darmowa rozrywka, która uspokaja umysł. Nie przeszkadzaj mu, a ty wykorzystaj okazję i odpocznij.', title_pt = 'Fascínio pela máquina de lavar 🧺', body_pt = 'Senta-se em frente à máquina de lavar, concentrado na roupa a girar? É uma diversão totalmente gratuita que acalma a mente. Não o interrompa e aproveite também para descansar.', title_sv = 'Fascinerad av tvättmaskinen 🧺', body_sv = 'Sitter barnet framför tvättmaskinen och följer kläderna som snurrar? Det är en helt gratis underhållning som lugnar sinnet. Avbryt inte, passa på att vila du också.', title_vi = 'Mê mẩn máy giặt 🧺', body_vi = 'Bé ngồi trước máy giặt chăm chú nhìn quần áo quay tròn? Đây là trò giải trí hoàn toàn miễn phí và giúp tâm trí dịu lại. Đừng ngăn bé, mẹ cũng tranh thủ nghỉ ngơi nhé.', title_zh = '着迷于洗衣机 🧺', body_zh = '坐在洗衣机前，盯着转动的衣服看？这是完全免费、还能让大脑平静的娱乐。别打扰宝宝，你也趁机休息一下吧。' WHERE id = '746f5afe-3705-4073-a3c0-ff69e92f5a25' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Confesión en el Diario de ánimo 📝', body_es = 'Coge el móvil. En lugar de deslizar por las redes sociales, abre el Diario de ánimo y escribe todo lo que hoy te ha sacado de quicio hasta desahogarte. La terapia digital funciona.', title_fr = 'Confidences au Journal d''humeur 📝', body_fr = 'Prenez votre téléphone. Au lieu de faire défiler les réseaux sociaux, ouvrez le Journal d''humeur et écrivez tout ce qui vous a rendue folle aujourd''hui, jusqu''à ce que la colère retombe. La thérapie numérique, ça marche.', title_hi = 'मूड डायरी में दिल की बात 📝', body_hi = 'फ़ोन हाथ में लीजिए। सोशल मीडिया स्क्रॉल करने के बजाय मूड डायरी खोलिए और आज जिन बातों ने आपको परेशान किया, वे सब तब तक लिखिए जब तक मन का गुबार न निकल जाए। डिजिटल थेरेपी काम करती है।', title_id = 'Pengakuan di Buku Harian Suasana Hati 📝', body_id = 'Ambil ponsel Anda. Daripada menggulir media sosial, buka Buku Harian Suasana Hati dan tulis semua yang membuat Anda kesal hari ini sampai lega. Terapi digital itu ampuh.', title_ja = '「気分日記」に本音を 📝', body_ja = 'スマホを手に取って。SNSをスクロールするかわりに「気分日記」を開いて、今日あなたをイライラさせたことを、気がすむまで全部書き出しましょう。デジタルセラピーは効きます。', title_ko = '기분 일기에 털어놓기 📝', body_ko = '휴대폰을 들어 보세요. SNS를 넘기는 대신 기분 일기를 열고 오늘 나를 힘들게 한 모든 걸 속이 후련해질 때까지 적어 보세요. 디지털 테라피는 효과가 있어요.', title_nl = 'Een bekentenis in je Stemmingsdagboek 📝', body_nl = 'Pak je telefoon. Scroll niet door sociale media, maar open je Stemmingsdagboek en schrijf alles op wat je vandaag gek maakte, tot je boosheid eruit is. Digitale therapie werkt.', title_pl = 'Wyznanie w Dzienniku nastroju 📝', body_pl = 'Weź telefon do ręki. Zamiast przewijać media społecznościowe, otwórz Dziennik nastroju i wypisz wszystko, co dziś doprowadzało cię do szału, aż złość minie. Cyfrowa terapia działa.', title_pt = 'Desabafo no Diário de Humor 📝', body_pt = 'Pegue no telemóvel. Em vez de andar a deslizar nas redes sociais, abra o Diário de Humor e escreva tudo o que hoje a enlouqueceu, até esvaziar a raiva. A terapia digital funciona.', title_sv = 'Bekännelse i Humördagboken 📝', body_sv = 'Ta mobilen. I stället för att scrolla i sociala medier, öppna Humördagboken och skriv ner allt som gjorde dig galen i dag tills det känns bättre. Digital terapi fungerar.', title_vi = 'Tâm sự trong Nhật ký tâm trạng 📝', body_vi = 'Hãy cầm điện thoại lên. Thay vì lướt mạng xã hội, hãy mở Nhật ký tâm trạng và viết ra mọi thứ khiến mẹ phát điên hôm nay cho đến khi hết bực. Liệu pháp kỹ thuật số thật sự hiệu quả.', title_zh = '在心情日记里倾诉 📝', body_zh = '拿起手机。别刷社交媒体了，打开心情日记，把今天让你抓狂的一切都写下来，直到气消为止。数字疗法真的有用。' WHERE id = '8da8a36e-5d67-4dd0-ac14-245b62a8846a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de la melatonina 🌙', body_es = 'Para que se active la hormona del sueño, apaga al menos 1 hora antes de dormir las fuentes de luz azul como la tele o la tablet. La oscuridad y el silencio son la mejor medicina para dormir.', title_fr = 'L''heure de la mélatonine 🌙', body_fr = 'Pour que l''hormone du sommeil se mette en route, coupez les sources de lumière bleue comme la télé et la tablette au moins 1 heure avant le coucher. Le noir et le silence sont les meilleurs somnifères.', title_hi = 'मेलाटोनिन का समय 🌙', body_hi = 'नींद का हार्मोन काम शुरू करे, इसके लिए सोने से कम से कम 1 घंटा पहले टीवी, टैबलेट जैसी नीली रोशनी वाली चीज़ें बंद कर दीजिए। अंधेरा और खामोशी नींद की सबसे अच्छी दवा हैं।', title_id = 'Waktunya melatonin 🌙', body_id = 'Agar hormon tidur bekerja, matikan sumber cahaya biru seperti TV dan tablet setidaknya 1 jam sebelum tidur. Gelap dan hening adalah obat tidur terbaik.', title_ja = 'メラトニンの時間 🌙', body_ja = '眠りのホルモンが働くように、寝る少なくとも1時間前にはテレビやタブレットなどの青い光をすべて消しましょう。暗やみと静けさがいちばんの眠り薬です。', title_ko = '멜라토닌 시간 🌙', body_ko = '수면 호르몬이 잘 나오도록 잠들기 최소 1시간 전에는 TV, 태블릿 같은 블루라이트를 모두 꺼 주세요. 어둠과 고요가 최고의 수면제예요.', title_nl = 'Tijd voor melatonine 🌙', body_nl = 'Zet minstens 1 uur voor het slapengaan bronnen van blauw licht zoals tv en tablet uit, zodat het slaaphormoon op gang komt. Donker en stilte zijn het beste slaapmiddel.', title_pl = 'Czas melatoniny 🌙', body_pl = 'Aby zadziałał hormon snu, co najmniej 1 godzinę przed snem wyłącz źródła niebieskiego światła, takie jak telewizor czy tablet. Ciemność i cisza to najlepsze lekarstwo na sen.', title_pt = 'Hora da melatonina 🌙', body_pt = 'Para que a hormona do sono comece a atuar, desligue pelo menos 1 hora antes de deitar as fontes de luz azul, como a televisão e o tablet. O escuro e o silêncio são o melhor remédio para dormir.', title_sv = 'Dags för melatonin 🌙', body_sv = 'För att sömnhormonet ska komma igång, stäng av blåljuskällor som tv och surfplatta minst 1 timme före läggdags. Mörker och tystnad är den bästa sömnmedicinen.', title_vi = 'Giờ melatonin 🌙', body_vi = 'Để hormone giấc ngủ bắt đầu hoạt động, hãy tắt các nguồn ánh sáng xanh như TV, máy tính bảng ít nhất 1 tiếng trước khi ngủ. Bóng tối và sự yên tĩnh là liều thuốc ngủ tốt nhất.', title_zh = '褪黑素时间 🌙', body_zh = '为了让睡眠激素发挥作用，睡前至少1小时关掉电视、平板等蓝光来源。黑暗和安静是最好的助眠药。' WHERE id = '71f7d0fb-698f-4308-ad55-a95583a3469b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de «¡Soy mamá!» 🎭', body_es = '¿Amenaza a su muñeca con el dedo y se enfada con tu mismo tono de voz? Hay una pequeña tú paseando por la habitación. Verte desde fuera es cómico y, a la vez, una señal para fijarte en tu propio comportamiento.', title_fr = 'Le jeu du « Je suis la maman ! » 🎭', body_fr = 'Il gronde sa poupée en levant le doigt, avec votre ton de voix ? Une mini-vous se promène dans la pièce. Se voir de l''extérieur, c''est à la fois drôle et un signal pour faire attention à vos comportements.', title_hi = '''मैं मम्मी हूँ!'' वाला खेल 🎭', body_hi = 'गुड़िया को उँगली दिखाकर आपकी आवाज़ के लहजे में डाँटता है? कमरे में एक नन्ही ''आप'' घूम रही है। खुद को बाहर से देखना मज़ेदार भी है और अपने व्यवहार पर ध्यान देने का संकेत भी।', title_id = 'Permainan ''Aku Ibu!'' 🎭', body_id = 'Ia mengancam bonekanya dengan jari dan marah dengan nada suara Anda? Ada Anda versi mini berkeliaran di kamar. Melihat diri sendiri dari luar itu lucu, sekaligus pengingat untuk memperhatikan perilaku Anda.', title_ja = '「わたし、ママだよ！」ごっこ 🎭', body_ja = '人形に指を振ってしかりながら、あなたと同じ口調で怒っていますか？部屋に小さなあなたが歩いています。外から自分を見るのはおかしくもあり、ふだんの言動を見直すきっかけにもなります。', title_ko = '''내가 엄마야!'' 놀이 🎭', body_ko = '인형에게 손가락을 흔들며 엄마 말투로 화를 내나요? 방에 꼬마 엄마가 돌아다니고 있어요. 나를 밖에서 보는 건 웃기기도 하고, 내 행동을 돌아보라는 신호이기도 해요.', title_nl = 'Het spel ''Ik ben mama!'' 🎭', body_nl = 'Dreigt hij zijn pop met een vingertje en wordt hij boos met jouw stemgeluid? Er loopt een kleine jij door de kamer. Jezelf zo van buitenaf zien is grappig, maar ook een signaal om op je eigen gedrag te letten.', title_pl = 'Zabawa „Jestem mamą!” 🎭', body_pl = 'Grozi lalce palcem i złości się twoim tonem głosu? Po pokoju chodzi mała ty. Oglądanie siebie z boku jest i zabawne, i jest sygnałem, by zwrócić uwagę na swoje zachowanie.', title_pt = 'O jogo "Eu sou a mãe!" 🎭', body_pt = 'Ameaça a boneca com o dedo e zanga-se com o seu tom de voz? Anda uma mini-você pela casa. Ver-se de fora é cómico e também um sinal para prestar atenção ao seu comportamento.', title_sv = 'Leken ”Jag är mamma!” 🎭', body_sv = 'Hytter barnet med fingret åt dockan och blir arg med din röst? Det går ett litet du omkring i rummet. Att se dig själv utifrån är både komiskt och en signal att tänka på ditt eget beteende.', title_vi = 'Trò chơi "Mẹ đây!" 🎭', body_vi = 'Bé chỉ tay dọa búp bê và bực bội bằng đúng giọng của mẹ? Một "phiên bản mẹ" nhỏ đang đi lại trong phòng. Nhìn mình từ bên ngoài vừa buồn cười, vừa là tín hiệu để mẹ chú ý đến hành vi của mình.', title_zh = '“我是妈妈！”游戏 🎭', body_zh = '对着娃娃摇手指，用你的语气发脾气？房间里走着一个小小的你。从旁观者的角度看自己，既好笑，也是提醒你注意自己言行的信号。' WHERE id = '9d1de334-e45a-491d-8075-45ce379df7ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No quiere ir a la cama, pero se le cierran los ojos de sueño? Esta resistencia es un clásico al acercarse a los 3 años. No le obligues: baja las luces de la habitación y anuncia una hora de hojear libros en silencio.', body_fr = 'Il ne veut pas aller au lit alors qu''il tombe de sommeil ? Vers 3 ans, cette résistance est classique. Ne le forcez pas, baissez les lumières de la chambre et annoncez une « heure de lecture calme ».', body_hi = 'बिस्तर पर नहीं जाना चाहता, लेकिन आँखों से नींद टपक रही है? 3 साल के करीब यह विरोध आम है। ज़बरदस्ती मत कीजिए, कमरे की लाइटें धीमी करके ''शांत किताब समय'' घोषित कीजिए।', body_id = 'Tidak mau tidur, padahal matanya sudah sangat mengantuk? Menjelang usia 3 tahun penolakan ini klasik. Jangan memaksa, redupkan lampu kamar dan umumkan ''Jam membaca buku dengan tenang''.', body_ja = 'ベッドに行きたがらないのに、目はもう眠そう？3歳が近づくと、こうした抵抗はよくあることです。無理強いせず、部屋の明かりを落として「静かな絵本の時間」を宣言しましょう。', body_ko = '자러 가기 싫다는데 눈꺼풀은 무겁나요? 세 돌 무렵의 전형적인 버티기예요. 억지로 재우지 말고 방의 조명을 낮춘 뒤 ''조용한 책 시간''을 정해 보세요.', body_nl = 'Wil hij niet naar bed, maar vallen zijn ogen bijna dicht? Rond de 3 jaar is dit verzet klassiek. Dwing hem niet, dim de lichten in de kamer en kondig een stil uurtje met boekjes aan.', body_pl = 'Nie chce iść do łóżka, choć oczy same mu się zamykają? Około 3. roku życia ten opór to klasyka. Nie zmuszaj go, przygaś światło w pokoju i ogłoś cichą godzinę przeglądania książeczek.', body_pt = 'Não quer ir para a cama, mas está a cair de sono? Perto dos 3 anos, esta resistência é clássica. Não o obrigue: baixe as luzes do quarto e anuncie uma hora de livros em silêncio.', body_sv = 'Vill barnet inte gå och lägga sig fast ögonen faller ihop? Det här motståndet är klassiskt när barnet närmar sig 3 år. Tvinga inte, dämpa ljuset i rummet och utlys en tyst bokstund.', body_vi = 'Bé không muốn lên giường nhưng mắt đã díp lại? Gần 3 tuổi, sự chống cự này là kinh điển. Đừng ép bé, hãy giảm ánh sáng trong phòng và tuyên bố "Giờ lật sách yên tĩnh".', body_zh = '不想上床，眼睛却困得睁不开？快3岁时这种抗拒很常见。别强迫，把房间灯光调暗，宣布“安静看书时间”。' WHERE id = 'fc7921b2-eab6-4a37-aad0-63611df47ad7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El color de la tozudez matutina 🔴', body_es = 'Había pedido la comida en el plato verde y, cuando se la traes, llora diciendo «¡Yo dije rojo!». Deja de buscar lógica. Simplemente pásala al plato rojo y protege tus neuronas.', title_fr = 'La couleur de l''entêtement du matin 🔴', body_fr = 'Il voulait son repas dans l''assiette verte, mais quand vous l''apportez, il pleure en disant « J''avais dit rouge ! ». Arrêtez de chercher la logique. Versez simplement dans l''assiette rouge et préservez vos nerfs.', title_hi = 'सुबह की ज़िद का रंग 🔴', body_hi = 'खाना हरी प्लेट में माँगा था, और जब आप लाईं तो रोने लगा कि ''मैंने लाल कहा था''? तर्क ढूँढना बंद कीजिए। बस लाल प्लेट में डाल दीजिए और अपनी नसों को बचाइए।', title_id = 'Warna keras kepala pagi 🔴', body_id = 'Tadi ia minta makanannya di piring hijau, tetapi saat Anda bawakan ia menangis, ''Aku bilang merah!'' Berhentilah mencari logika. Pindahkan saja ke piring merah dan selamatkan saraf Anda.', title_ja = '朝のがんこさの色 🔴', body_ja = '緑のお皿がいいと言ったのに、持っていくと「赤って言った！」と泣きますか？理屈を探すのはやめましょう。赤いお皿に移して、あなたの神経を守って。', title_ko = '아침 고집의 색깔 🔴', body_ko = '초록 접시에 달라더니 가져가니까 ''빨간색이라고 했잖아!'' 하며 우나요? 논리 찾기는 그만두세요. 그냥 빨간 접시에 옮겨 담고 엄마의 신경을 지키세요.', title_nl = 'De kleur van ochtendkoppigheid 🔴', body_nl = 'Hij wilde zijn eten op een groen bord, maar als je het brengt huilt hij: ''Ik zei rood!'' Stop met zoeken naar logica. Doe het gewoon op een rood bord en spaar je zenuwen.', title_pl = 'Kolor porannego uporu 🔴', body_pl = 'Chciał jedzenie na zielonym talerzu, a gdy je przynosisz, płacze: „Mówiłem czerwony!”. Przestań szukać logiki. Po prostu przełóż na czerwony talerz i chroń swoje nerwy.', title_pt = 'A cor da teimosia matinal 🔴', body_pt = 'Pediu a comida no prato verde e, quando lho traz, chora: "Eu disse vermelho!" Pare de procurar lógica. Passe simplesmente para o prato vermelho e poupe os seus nervos.', title_sv = 'Morgonenvishetens färg 🔴', body_sv = 'Barnet ville ha maten på den gröna tallriken, men när du kommer med den gråter hen och säger ”jag sa röd”. Sluta leta efter logik. Lägg bara över maten på den röda tallriken och skona dina nerver.', title_vi = 'Màu sắc của sự bướng bỉnh buổi sáng 🔴', body_vi = 'Bé đòi đĩa màu xanh lá, mẹ mang ra thì bé khóc "Con bảo màu đỏ cơ mà". Đừng tìm logic nữa. Cứ đổ sang đĩa màu đỏ và giữ gìn thần kinh của mình.', title_zh = '早晨倔强的颜色 🔴', body_zh = '本来要绿盘子装饭，你端来了，宝宝却哭着说“我说的是红的”？别再找道理了。直接倒进红盘子里，保护好你的神经吧。' WHERE id = '2a74e43d-d2e3-45ad-8762-627a59c365b2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se ha despertado llorando en mitad de la noche sin motivo? ¿Son gases o un terror nocturno? Deja de adivinar: encuentra la causa con el Análisis del llanto y cálmale con un abrazo tranquilo.', body_fr = 'Il s''est réveillé en pleurant en pleine nuit, sans raison apparente ? Des gaz ou une terreur nocturne ? Arrêtez de deviner : trouvez la cause avec l''Analyse des pleurs et apaisez-le en le serrant calmement contre vous.', body_hi = 'बिना वजह आधी रात को रोते हुए जाग गया? गैस है या नाइट टेरर? अंदाज़े लगाना छोड़िए, क्राइंग एनालिसिस से वजह जानिए और शांति से गले लगाकर उसे सुकून दीजिए।', body_id = 'Ia terbangun tengah malam sambil menangis tanpa sebab? Kembung, atau teror malam? Berhentilah menebak, temukan penyebabnya dengan Analisis Tangisan, lalu peluk ia dengan tenang untuk menenangkannya.', body_ja = '理由もなく夜中に泣いて目を覚ましましたか？ガス？それとも夜驚症？推測はやめて、「泣き声分析」で原因を見つけ、静かに抱きしめて安心させてあげましょう。', body_ko = '이유 없이 한밤중에 울며 깼나요? 가스 때문일까요, 야경증일까요? 추측은 그만하고 울음 분석으로 이유를 찾은 뒤 조용히 안아 편안하게 해 주세요.', body_nl = 'Zomaar midden in de nacht huilend wakker? Zijn het krampjes of nachtangst? Stop met raden, vind de oorzaak met Huilanalyse en stel hem gerust met een rustige knuffel.', body_pl = 'Obudził się w nocy z płaczem bez powodu? To gazy czy lęk nocny? Przestań zgadywać, ustal przyczynę w Analizie płaczu i ukój go spokojnym przytuleniem.', body_pt = 'Acordou a meio da noite a chorar sem razão? São gases ou terror noturno? Deixe de adivinhar: descubra a causa com a Análise do Choro e acalme-o com um abraço tranquilo.', body_sv = 'Har barnet vaknat gråtande mitt i natten utan anledning? Är det gaser eller nattskräck? Sluta gissa, hitta orsaken med Gråtanalys och lugna barnet med en stilla kram.', body_vi = 'Bé bỗng khóc thức giấc giữa đêm không rõ lý do? Đầy hơi hay hoảng sợ ban đêm? Đừng đoán nữa, hãy tìm nguyên nhân bằng Phân tích tiếng khóc và nhẹ nhàng ôm bé để bé dịu lại.', body_zh = '半夜无缘无故哭醒？是胀气，还是夜惊？别再猜了，用哭声分析找到原因，平静地抱抱宝宝，让宝宝安心。' WHERE id = '541b84ef-a3ed-43ff-8a33-aa153668c840' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Accidentes con el orinal 🚽', body_es = '¿Otra vez se ha hecho pis en la alfombra mientras aprende a usar el orinal? Respira hondo. Enfadarte puede hacer que retroceda. No te agobies por algo que se limpia: es solo un proceso de aprendizaje.', title_fr = 'Petits accidents de pot 🚽', body_fr = 'Pendant l''apprentissage du pot, il a encore fait pipi sur le tapis ? Respirez profondément. Vous énerver pourrait le faire régresser. Ne vous épuisez pas pour quelque chose qui se nettoie, c''est juste un apprentissage.', title_hi = 'पॉटी वाले हादसे 🚽', body_hi = 'पॉटी ट्रेनिंग के दौरान फिर कालीन पर सू-सू कर दिया? गहरी साँस लीजिए। गुस्सा करने से वह पीछे जा सकता है। जो चीज़ साफ़ हो जाएगी, उसके लिए अपना मन मत थकाइए, यह बस सीखने की प्रक्रिया है।', title_id = 'Kecelakaan pispot 🚽', body_id = 'Saat latihan pispot ia mengompol di karpet lagi? Tarik napas dalam. Kesal hanya akan membuatnya mundur. Jangan membebani pikiran untuk sesuatu yang bisa dibersihkan, ini hanya proses belajar.', title_ja = 'おまるの失敗 🚽', body_ja = 'トイレトレーニング中に、またカーペットでおもらし？深呼吸しましょう。イライラすると後戻りの原因になります。ふけばすむことで心をすり減らさないで、これはただの学びの過程です。', title_ko = '배변 실수 🚽', body_ko = '배변 훈련 중에 또 카펫에 쉬를 했나요? 깊게 숨 쉬세요. 화를 내면 오히려 뒷걸음질할 수 있어요. 닦으면 되는 일로 마음을 소모하지 마세요. 배우는 과정일 뿐이에요.', title_nl = 'Ongelukjes met het potje 🚽', body_nl = 'Plaste hij tijdens de zindelijkheidstraining weer op het tapijt? Haal diep adem. Boos worden kan hem juist terugzetten. Maak je niet druk om iets wat je kunt schoonmaken, het is gewoon een leerproces.', title_pl = 'Wpadki z nocnikiem 🚽', body_pl = 'Podczas nauki korzystania z nocnika znów zsikał się na dywan? Weź głęboki oddech. Złość może sprawić, że się cofnie. Nie męcz psychiki czymś, co da się wyczyścić, to po prostu proces nauki.', title_pt = 'Acidentes no bacio 🚽', body_pt = 'Durante o treino do bacio voltou a fazer chichi no tapete? Respire fundo. Irritar-se pode fazê-lo recuar. Não se desgaste por algo que se limpa: é apenas o processo de aprendizagem.', title_sv = 'Olyckor med pottan 🚽', body_sv = 'Kissade barnet på mattan igen under pottträningen? Andas djupt. Att bli arg kan få barnet att ta ett steg tillbaka. Slit inte på psyket för något som går att städa upp, det är bara en inlärningsprocess.', title_vi = 'Những "tai nạn" khi ngồi bô 🚽', body_vi = 'Đang tập ngồi bô mà bé lại tè ra thảm? Hãy hít thở sâu. Nổi giận có thể khiến bé thụt lùi. Đừng để thứ có thể lau sạch làm mẹ căng thẳng, đây chỉ là quá trình học hỏi.', title_zh = '便盆小意外 🚽', body_zh = '如厕训练时又尿在地毯上了？深呼吸。生气会让宝宝退步。别为一件能清理干净的事累坏自己的心情，这只是学习的过程。' WHERE id = '60323c41-a0d6-4029-8b71-994315dcb0cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El abogado del parque 🗣️', body_es = '«¡Juego un poco más, solo 5 minutos!», y así alarga el tiempo. No tiene noción del tiempo, pero negocia de maravilla. Pon un temporizador y recuérdale las reglas jugando, sin herirle.', title_fr = 'L''avocat du parc 🗣️', body_fr = '« Je joue encore un peu, juste 5 minutes ! » : il gagne du temps. Il n''a aucune notion du temps, mais il négocie à merveille. Réglez un minuteur pour rappeler les règles en jouant, sans le blesser.', title_hi = 'पार्क का वकील 🗣️', body_hi = '''थोड़ा और खेलूँ, बस 5 मिनट!'' कहकर समय बढ़ाता है? उसे समय की समझ नहीं, लेकिन मोलभाव में माहिर है। टाइमर लगाकर नियम बिना दिल दुखाए और खेल-खेल में याद दिलाइए।', title_id = 'Pengacara di taman 🗣️', body_id = 'Ia mengulur waktu dengan ''Main sebentar lagi, 5 menit saja!'' Ia belum paham konsep waktu, tetapi kemampuan tawar-menawarnya hebat. Pasang timer dan ingatkan aturannya lewat permainan tanpa menyakiti hatinya.', title_ja = '公園の弁護士さん 🗣️', body_ja = '「もうちょっとだけ、5分だけ！」と時間をのばしますか？時間の感覚はありませんが、交渉力は抜群です。タイマーをセットして、傷つけずに遊びながらルールを思い出させましょう。', title_ko = '공원의 꼬마 변호사 🗣️', body_ko = '''조금만 더 놀래, 딱 5분만!'' 하며 시간을 끄나요? 시간 개념은 없지만 협상력은 훌륭해요. 타이머를 맞춰 규칙을 다정하게, 놀이처럼 알려 주세요.', title_nl = 'De advocaat in het park 🗣️', body_nl = '''Nog even spelen, maar 5 minuutjes!'' Hij rekt de tijd. Hij heeft nog geen besef van tijd, maar onderhandelen kan hij als de beste. Zet een timer en herinner hem zo speels en zonder te kwetsen aan de regels.', title_pl = 'Adwokat w parku 🗣️', body_pl = '„Jeszcze trochę się pobawię, tylko 5 minut!” i przeciąga czas. Nie ma pojęcia czasu, ale umiejętność targowania się ma świetną. Nastaw timer i przypominaj o zasadach bez urazy, w formie zabawy.', title_pt = 'O advogado do parque 🗣️', body_pt = '"Só mais um bocadinho, só 5 minutos!" e vai adiando. Não tem noção do tempo, mas tem ótimo jeito para negociar. Use um temporizador para lembrar as regras de forma lúdica e sem o magoar.', title_sv = 'Advokaten i parken 🗣️', body_sv = 'Barnet drar ut på tiden med ”Jag vill leka lite till, bara 5 minuter!”. Hen har inget tidsbegrepp, men förhandlingsförmågan är utmärkt. Ställ in en timer och påminn om reglerna på ett lekfullt sätt utan att såra.', title_vi = 'Luật sư ở công viên 🗣️', body_vi = '"Con chơi thêm chút nữa thôi, chỉ 5 phút!" bé cứ kéo dài thời gian. Bé chưa có khái niệm thời gian nhưng khả năng mặc cả thì tuyệt vời. Hãy đặt hẹn giờ để nhắc quy tắc bằng trò chơi mà không làm bé buồn.', title_zh = '公园里的小律师 🗣️', body_zh = '说着“再玩一会儿，就5分钟！”拖延时间？还没有时间概念，讨价还价的本事却很棒。设个计时器，不伤感情、用游戏的方式提醒规则吧。' WHERE id = '1a8259f8-8cae-4f18-b5c2-ee44aa10346d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Estirón 📏', body_es = '¿Los pantalones se le quedan cortos? ¡Está creciendo a toda velocidad! Introduce sus medidas actuales en el Seguimiento del desarrollo y mira con orgullo el fruto de tus noches sin dormir.', title_fr = 'Poussée de croissance 📏', body_fr = 'Les pantalons sont devenus trop courts ? Il grandit vite ! Entrez ses mesures actuelles dans le Suivi de développement et regardez fièrement le fruit de vos nuits blanches.', title_hi = 'लंबाई में उछाल 📏', body_hi = 'पैंट छोटी हो गई? वह तेज़ी से बड़ा हो रहा है! ग्रोथ ट्रैकर में मौजूदा माप दर्ज कीजिए और अपनी जागी हुई रातों का फल गर्व से देखिए।', title_id = 'Lonjakan tinggi badan 📏', body_id = 'Celananya kependekan? Ia tumbuh dengan cepat! Masukkan ukuran terbarunya ke Pelacak Perkembangan dan lihat dengan bangga buah dari malam-malam tanpa tidur Anda.', title_ja = '身長の伸び 📏', body_ja = 'ズボンの丈が短くなった？ぐんぐん成長しています！「発達トラッカー」に今のサイズを入力して、眠れない夜の成果を誇らしく見てみましょう。', title_ko = '키가 쑥 📏', body_ko = '바지가 짧아졌나요? 쑥쑥 크고 있어요! 성장 기록에 현재 수치를 입력하고 잠 못 든 밤들의 결실을 뿌듯하게 바라보세요.', title_nl = 'Groeispurt 📏', body_nl = 'Is zijn broek te kort geworden? Hij groeit snel! Vul de huidige maten in de Groeitracker in en kijk trots naar de vrucht van al je slapeloze nachten.', title_pl = 'Skok wzrostu 📏', body_pl = 'Spodnie zrobiły się za krótkie? Szybko rośnie! Wpisz aktualne wymiary do Śledzenia rozwoju i z dumą spójrz na owoc swoich nieprzespanych nocy.', title_pt = 'Salto de crescimento 📏', body_pt = 'As calças ficaram curtas? Está a crescer depressa! Introduza as medidas atuais no Registo de Desenvolvimento e veja com orgulho o fruto das suas noites sem dormir.', title_sv = 'Längdspurt 📏', body_sv = 'Har byxorna blivit korta? Barnet växer snabbt! För in de aktuella måtten i Tillväxtspåraren och se stolt på frukten av dina sömnlösa nätter.', title_vi = 'Cao vọt 📏', body_vi = 'Ống quần đã ngắn rồi? Bé đang lớn rất nhanh! Hãy nhập số đo hiện tại vào Theo dõi phát triển và tự hào ngắm thành quả của những đêm mất ngủ.', title_zh = '身高突增 📏', body_zh = '裤子又短了？长得真快！在发育追踪里输入当前尺寸，骄傲地看看你无数个不眠之夜的成果吧。' WHERE id = 'bf1a9cee-65ab-4eac-ad90-70c1631bbc46' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pausa en pareja 🥂', body_es = 'Tu peque se ha dormido. Ahora aparca los móviles y las tareas de casa. Habla con tu pareja al menos 20 minutos de cualquier tema distinto que no sea el niño ni los pagos.', title_fr = 'Pause à deux 🥂', body_fr = 'L''enfant dort. Maintenant, mettez de côté téléphones et tâches ménagères. Parlez avec votre partenaire au moins 20 minutes d''un tout autre sujet que l''enfant et les factures.', title_hi = 'कपल ब्रेक 🥂', body_hi = 'बच्चा सो गया। अब फ़ोन और घर के काम एक तरफ़ रखिए। अपने पार्टनर से कम से कम 20 मिनट बच्चे और बिलों के अलावा किसी भी अलग विषय पर बात कीजिए।', title_id = 'Waktu berdua 🥂', body_id = 'Anak sudah tidur. Sekarang singkirkan ponsel dan pekerjaan rumah. Mengobrollah dengan pasangan setidaknya 20 menit tentang topik apa pun yang berbeda, selain anak dan tagihan.', title_ja = 'ふたりの休憩 🥂', body_ja = 'お子さんが眠りました。スマホも家事も脇に置いて、パートナーと少なくとも20分、子どもや支払いのこと以外の話をしましょう。', title_ko = '부부만의 쉼표 🥂', body_ko = '아이가 잠들었어요. 이제 휴대폰과 집안일은 내려놓으세요. 배우자와 최소 20분 동안 아이와 공과금 말고 전혀 다른 이야기를 나눠 보세요.', title_nl = 'Tijd voor jullie tweeën 🥂', body_nl = 'Hij slaapt. Leg nu telefoons en huishouden opzij. Praat minstens 20 minuten met je partner over een heel ander onderwerp, alles behalve de kinderen en de rekeningen.', title_pl = 'Przerwa dla was dwojga 🥂', body_pl = 'Dziecko śpi. Teraz odłóżcie telefony i obowiązki domowe na bok. Porozmawiaj z partnerem przez co najmniej 20 minut na dowolny inny temat poza dzieckiem i rachunkami.', title_pt = 'Pausa a dois 🥂', body_pt = 'A criança adormeceu. Agora ponha de lado os telemóveis e as tarefas de casa. Converse com o seu companheiro pelo menos 20 minutos sobre qualquer assunto diferente, que não seja a criança nem as contas.', title_sv = 'Paus för er två 🥂', body_sv = 'Barnet sover. Lägg nu undan mobilerna och hushållet. Prata med din partner i minst 20 minuter om något annat ämne än barnet och räkningarna.', title_vi = 'Phút nghỉ của hai vợ chồng 🥂', body_vi = 'Bé ngủ rồi. Giờ hãy gác điện thoại và việc nhà sang một bên. Trò chuyện với chồng ít nhất 20 phút về bất kỳ chủ đề nào khác ngoài con cái và các khoản chi tiêu.', title_zh = '夫妻小憩 🥂', body_zh = '孩子睡着了。现在把手机和家务都放到一边。和另一半至少聊20分钟孩子和账单以外的其他话题。' WHERE id = 'cff0599d-3a80-4d02-94df-22f42e5f09f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche prueba en Cuentos inteligentes algo totalmente distinto: la historia de la pequeña nube que explora el cielo. Adapta tu tono de voz al ritmo del cuento y llévale al sueño.', body_fr = 'Ce soir, essayez quelque chose de complètement différent dans les Contes intelligents : l''histoire du petit nuage qui explore le ciel. Adaptez le ton de votre voix au rythme du conte et accompagnez-le vers le sommeil.', body_hi = 'आज शाम स्मार्ट कहानियों में कुछ बिल्कुल अलग आज़माइए: आसमान की खोज करने वाले नन्हे बादल की कहानी। अपनी आवाज़ का लहजा कहानी की लय के साथ मिलाइए और उसे नींद में ले जाइए।', body_id = 'Malam ini coba sesuatu yang sama sekali berbeda di Dongeng Pintar: kisah awan kecil yang menjelajahi langit. Sesuaikan nada suara Anda dengan irama dongeng dan antarkan ia tidur.', body_ja = '今夜は「スマートおはなし」でまったく違うお話を試してみましょう：空を探検する小さな雲のお話。声のトーンをお話のリズムに合わせて、眠りへ導いて。', body_ko = '오늘 밤엔 스마트 동화로 완전히 색다른 이야기를 해 보세요: 하늘을 탐험하는 꼬마 구름 이야기. 목소리 톤을 이야기의 리듬에 맞춰 스르르 잠들게 해 주세요.', body_nl = 'Probeer vanavond in Slimme sprookjes eens iets heel anders: het verhaal van het kleine wolkje dat de lucht ontdekt. Pas de toon van je stem aan op het ritme van het verhaal en wieg hem in slaap.', body_pl = 'Dziś wieczorem spróbuj w Mądrych bajkach czegoś zupełnie innego: historii o małej chmurce, która odkrywa niebo. Dopasuj ton głosu do rytmu bajki i ukołysz go do snu.', body_pt = 'Esta noite, experimente algo totalmente diferente nas Histórias Inteligentes: a história da pequena nuvem que explora o céu. Ajuste o tom de voz ao ritmo do conto e embale-o até adormecer.', body_sv = 'Prova något helt annat i Smarta sagor i kväll: berättelsen om det lilla molnet som upptäcker himlen. Anpassa din röst efter sagans rytm och led barnet in i sömnen.', body_vi = 'Tối nay trong Truyện cổ tích thông minh hãy thử điều gì đó thật khác: câu chuyện về đám mây nhỏ đi khám phá bầu trời. Hãy điều chỉnh giọng kể theo nhịp điệu câu chuyện và ru bé ngủ.', body_zh = '今晚在智能故事里试试完全不一样的故事吧：《探索天空的小云朵》。让你的语调跟上故事的节奏，带宝宝进入梦乡。' WHERE id = '5130988b-06fa-4ca0-8477-7c4e5105998f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El golpe del «¡Mírame!» 👀', body_es = 'Cuando miras el móvil, viene y te da en la mano o te quita el aparato. Tiene toda la razón. Quiere tu atención inmediata y completa. Míralo a los ojos y hazle sentir que le escuchas.', title_fr = 'Le coup du « Regarde-moi ! » 👀', body_fr = 'Quand vous regardez votre téléphone, il vient vous taper la main ou prendre l''appareil. Il a tout à fait raison. Il veut une attention immédiate et entière. Regardez-le dans les yeux et faites-lui sentir que vous l''écoutez.', title_hi = '''मुझे देखो!'' वाला वार 👀', body_hi = 'आप फ़ोन देखती हैं तो आकर आपके हाथ पर मारता है या फ़ोन छीन लेता है? वह बिल्कुल सही है। उसे तुरंत और पूरा ध्यान चाहिए। आँखों में आँखें डालकर उसे महसूस कराइए कि आप उसे सुन रही हैं।', title_id = 'Tuntutan ''Lihat aku!'' 👀', body_id = 'Saat Anda melihat ponsel, ia datang memukul tangan Anda atau merebut ponselnya. Ia sepenuhnya benar. Ia ingin perhatian saat itu juga dan tanpa terbagi. Tatap matanya dan tunjukkan bahwa Anda mendengarkannya.', title_ja = '「こっち見て！」のアピール 👀', body_ja = 'あなたがスマホを見ていると、手をたたいたり、スマホを取ったりしますか？お子さんの言うとおりです。今すぐ、自分だけを見てほしいのです。目を合わせて、ちゃんと聞いていることを感じさせてあげましょう。', title_ko = '''나 좀 봐!'' 한 방 👀', body_ko = '엄마가 휴대폰을 볼 때 다가와 손을 치거나 휴대폰을 빼앗나요? 아이 말이 맞아요. 지금 당장, 온전한 관심을 원하는 거예요. 눈을 맞추며 귀 기울이고 있다는 걸 느끼게 해 주세요.', title_nl = 'De ''Kijk naar mij!''-tik 👀', body_nl = 'Komt hij tegen je hand tikken of pakt hij je telefoon af als je erop kijkt? Hij heeft helemaal gelijk. Hij wil direct en onverdeeld je aandacht. Maak oogcontact en laat voelen dat je naar hem luistert.', title_pl = 'Cios „Patrz na mnie!” 👀', body_pl = 'Gdy patrzysz w telefon, podchodzi i uderza cię w rękę albo zabiera urządzenie. Ma całkowitą rację. Chce natychmiastowej i niepodzielnej uwagi. Nawiąż kontakt wzrokowy i daj mu poczuć, że go słuchasz.', title_pt = 'O golpe do "Olha para mim!" 👀', body_pt = 'Quando está a ver o telemóvel, vem bater-lhe na mão ou tirar-lhe o aparelho. Tem toda a razão. Quer atenção imediata e exclusiva. Olhe-o nos olhos e mostre-lhe que o está a ouvir.', title_sv = 'Slaget ”Titta på mig!” 👀', body_sv = 'Slår barnet till din hand eller tar mobilen när du tittar på den? Hen har helt rätt. Barnet vill ha din omedelbara och odelade uppmärksamhet. Skapa ögonkontakt och låt hen känna att du lyssnar.', title_vi = 'Cú đánh "Nhìn con này!" 👀', body_vi = 'Khi mẹ nhìn điện thoại, bé chạy đến đập vào tay hoặc giật lấy máy. Bé hoàn toàn có lý. Bé muốn mẹ chú ý ngay và trọn vẹn. Hãy nhìn vào mắt bé để bé cảm nhận được mẹ đang lắng nghe.', title_zh = '“看我！”的一击 👀', body_zh = '你看手机时，宝宝跑过来拍你的手，或者把手机拿走。宝宝完全有道理。宝宝要的是即时、完整的注意力。和宝宝对视，让宝宝感受到你在听。' WHERE id = '632fc2f4-f865-49e5-8a30-eef5c63d0d4a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Manchas tozudas, descubrimientos libres 🎨', body_es = '¿El pijama lleno de comida y la ropa llena de pintura? Los niños no tienen que crecer limpios: tienen que ensuciarse descubriendo. El desorden es el himno de su creatividad, no te estreses.', title_fr = 'Taches tenaces, découvertes libres 🎨', body_fr = 'Son pyjama est couvert de nourriture et ses habits de peinture ? Les enfants ne sont pas faits pour grandir propres, ils doivent se salir en découvrant. Le désordre est l''hymne de sa créativité, ne stressez pas.', title_hi = 'ज़िद्दी दाग, आज़ाद खोज 🎨', body_hi = 'पजामे पर खाना और कपड़ों पर रंग के दाग? बच्चों को साफ़-सुथरा नहीं, खोजते हुए गंदा होकर बड़ा होना चाहिए। बिखराव उसकी रचनात्मकता का हस्ताक्षर है, तनाव मत लीजिए।', title_id = 'Noda membandel, penjelajahan bebas 🎨', body_id = 'Piyamanya penuh noda makanan, bajunya penuh cat? Anak tidak harus tumbuh bersih, mereka harus kotor sambil bereksplorasi. Kekacauan adalah lagu kebangsaan kreativitasnya, jangan stres.', title_ja = 'がんこなシミ、自由な探検 🎨', body_ja = 'パジャマは食べこぼし、服は絵の具のシミだらけ？子どもはきれいなまま育つものではなく、探検して汚れるものです。散らかりは創造性のしるし、ストレスに感じないで。', title_ko = '고집스러운 얼룩, 자유로운 탐험 🎨', body_ko = '잠옷은 음식 얼룩, 옷은 물감 얼룩투성이인가요? 아이는 깨끗하게만 자랄 필요가 없어요. 탐험하며 더러워져야 해요. 어질러짐은 창의력의 노래예요. 스트레스받지 마세요.', title_nl = 'Hardnekkige vlekken, vrije ontdekkingen 🎨', body_nl = 'Zit zijn pyjama onder het eten en zijn hele lijf onder de verf? Kinderen hoeven niet schoon op te groeien, ze horen vies te worden van het ontdekken. Rommel is het volkslied van zijn creativiteit, maak je niet druk.', title_pl = 'Uparte plamy, swobodne odkrycia 🎨', body_pl = 'Piżama w jedzeniu, ubranie w plamach farby? Dzieci nie mają rosnąć czyste, mają się brudzić, odkrywając świat. Bałagan to hymn jego kreatywności, nie stresuj się.', title_pt = 'Nódoas teimosas, descobertas livres 🎨', body_pt = 'O pijama tem comida e a roupa tem tinta? As crianças não têm de crescer limpas, têm de se sujar a descobrir. A desarrumação é o hino da criatividade dele, não se stresse.', title_sv = 'Envisa fläckar, fria upptäckter 🎨', body_sv = 'Är pyjamasen full av mat och kläderna av färgfläckar? Barn ska inte växa upp rena, de ska bli smutsiga när de upptäcker. Stöket är kreativitetens signatur, stressa inte.', title_vi = 'Vết bẩn cứng đầu, khám phá tự do 🎨', body_vi = 'Đồ ngủ dính đầy thức ăn, người lấm lem màu vẽ? Trẻ con không cần lớn lên sạch sẽ, bé cần lấm bẩn khi khám phá. Sự bừa bộn là bài ca của óc sáng tạo, đừng căng thẳng.', title_zh = '顽固的污渍，自由的探索 🎨', body_zh = '睡衣上全是饭渍，身上满是颜料？孩子不该干干净净地长大，而是要在探索中弄脏自己。凌乱是宝宝创造力的签名，别有压力。' WHERE id = 'df191a16-4b37-4a90-bbd4-c8972ecc1670' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla en susurros 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y cuéntale en voz muy bajita, susurrando, lo que ha pasado durante el día. Susurrar es el mejor método para preparar el cerebro para dormir.', title_fr = 'Conversation chuchotée 🌙', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et racontez-lui sa journée tout bas, en chuchotant. Le chuchotement est la meilleure façon de préparer le cerveau au sommeil.', title_hi = 'फुसफुसाकर बातें 🌙', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें बहुत धीमी आवाज़ में, फुसफुसाकर उसे सुनाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे अच्छा तरीका है।', title_id = 'Obrolan berbisik 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan ceritakan kejadian hari ini dengan suara sangat pelan, berbisik. Berbisik adalah cara terbaik menyiapkan otak untuk tidur.', title_ja = 'ささやき声のおしゃべり 🌙', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、今日あったことをとても小さな声でささやくように話してあげて。ささやき声は、脳を眠りへ導くいちばんの方法です。', title_ko = '속삭이는 대화 🌙', body_ko = '방의 불을 모두 꺼 주세요. 옆에 누워 오늘 있었던 일을 아주 작은 목소리로 속삭이듯 들려주세요. 속삭임은 뇌가 잠들 준비를 하게 돕는 가장 좋은 방법이에요.', title_nl = 'Fluistergesprekjes 🌙', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en vertel heel zachtjes, fluisterend, wat er vandaag is gebeurd. Fluisteren is de beste manier om de hersenen klaar te maken voor de slaap.', title_pl = 'Rozmowa szeptem 🌙', body_pl = 'Zgaś wszystkie światła w pokoju. Połóż się obok i bardzo cicho, szeptem opowiedz mu, co wydarzyło się w ciągu dnia. Szept to najlepszy sposób, by przygotować mózg do snu.', title_pt = 'Conversa em sussurro 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e conte-lhe, em voz muito baixa e a sussurrar, o que aconteceu durante o dia. Sussurrar é o melhor método para preparar o cérebro para o sono.', title_sv = 'Viskande samtal 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och berätta mycket tyst, viskande, om det som hänt under dagen. Viskningar är det bästa sättet att förbereda hjärnan för sömn.', title_vi = 'Trò chuyện thì thầm 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ kể về những gì đã xảy ra trong ngày. Thì thầm là cách tốt nhất giúp não bộ chuẩn bị cho giấc ngủ.', title_zh = '悄悄话聊天 🌙', body_zh = '把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音，悄悄讲讲今天发生的事。悄悄话是帮大脑准备入睡的最好方法。' WHERE id = '096e15b3-74ca-4180-ab20-07ce9b214b2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te ha asustado que se oponga a todo? No busques artículos que dan miedo en internet. Aprovecha las experiencias reales de las madres veteranas de la Comunidad Anacan y sonríe.', body_fr = 'Son entêtement face à tout vous a fait peur ? Ne cherchez pas d''articles effrayants sur Internet. Profitez du vécu des mamans expérimentées de la Communauté Anacan et souriez.', body_hi = 'बच्चे की हर बात पर ज़िद ने आपको डरा दिया? इंटरनेट पर डरावने लेख मत ढूँढिए। Anacan कम्युनिटी में अनुभवी माँओं के असली अनुभवों का फ़ायदा उठाइए और मुस्कुराइए।', body_id = 'Sifat keras kepalanya untuk segala hal membuat Anda takut? Jangan mencari artikel menyeramkan di internet. Manfaatkan pengalaman nyata ibu-ibu berpengalaman di Komunitas Anacan dan tersenyumlah.', body_ja = '何にでも反抗するお子さんにドキッとしましたか？ネットでこわい記事を探さないで。Anacanコミュニティの経験豊富なママたちのリアルな体験を活用して、ほほえみましょう。', body_ko = '모든 것에 고집을 부리는 아이 때문에 걱정되나요? 인터넷에서 무서운 글을 찾지 마세요. Anacan 커뮤니티의 경험 많은 엄마들의 현실 이야기를 보며 웃어 보세요.', body_nl = 'Schrok je van zijn koppigheid over alles? Zoek niet naar enge artikelen op internet. Leer van de echte ervaringen van ervaren moeders in de Anacan Community en glimlach.', body_pl = 'Przestraszył cię jego upór we wszystkim? Nie szukaj w internecie przerażających artykułów. Skorzystaj z prawdziwych doświadczeń mam w Społeczności Anacan i się uśmiechnij.', body_pt = 'A teimosia dele em tudo assustou-a? Não procure artigos assustadores na internet. Aproveite as experiências reais das mães experientes da Comunidade Anacan e sorria.', body_sv = 'Skrämde barnets envishet med allt dig? Sök inte efter skrämmande artiklar på nätet. Ta del av erfarna mammors verklighet i Anacan Community och le.', body_vi = 'Sự bướng bỉnh với mọi thứ của bé khiến mẹ lo sợ? Đừng tìm đọc những bài báo đáng sợ trên mạng. Hãy tham khảo trải nghiệm thực tế của các mẹ giàu kinh nghiệm trong Cộng đồng Anacan và mỉm cười.', body_zh = '孩子什么都要对着干，吓到你了？别在网上搜那些吓人的文章。听听Anacan社区里有经验的妈妈们的真实经历，笑一笑吧。' WHERE id = '41df7f7d-e272-4737-8498-6c866ab9545a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Bailarín profesional 🎶', body_es = 'Empieza a bailar con el primer ritmo que oye, sea un anuncio o el claxon de un coche. ¡Mira la vida con la misma alegría! Únete en la habitación y bailad unos minutos como locos.', title_fr = 'Danseur professionnel 🎶', body_fr = 'Au premier rythme qu''il entend, qu''il s''agisse d''une pub ou d''un klaxon, il se met à danser. Regardez la vie aussi joyeusement que lui ! Rejoignez-le dans la pièce pour quelques minutes de danse folle.', title_hi = 'पेशेवर डांसर 🎶', body_hi = 'पहली ताल सुनते ही, चाहे विज्ञापन की धुन हो या गाड़ी का हॉर्न, नाचने लगता है? ज़िंदगी को उसकी तरह खुशी से देखिए! कमरे में उसके साथ कुछ मिनट जमकर पागलों वाला डांस कीजिए।', title_id = 'Penari profesional 🎶', body_id = 'Begitu mendengar irama apa pun, entah suara iklan atau klakson mobil, ia langsung berjoget. Pandanglah hidup seceria dia! Ikut bergabung dengannya di kamar dan berjoget heboh beberapa menit.', title_ja = 'プロのダンサー 🎶', body_ja = 'CMの音でも車のクラクションでも、最初に聞こえたリズムで踊り出しますか？お子さんのように明るく人生を楽しみましょう！部屋で一緒に数分間、思いきり踊って。', title_ko = '프로 댄서 🎶', body_ko = '광고 소리든 자동차 경적이든 리듬만 들리면 바로 춤을 추나요? 아이처럼 즐겁게 세상을 바라보세요! 방에서 함께 몇 분 동안 신나게 막춤을 춰 보세요.', title_nl = 'Professionele danser 🎶', body_nl = 'Bij het eerste ritme dat hij hoort, of het nu een reclame is of een autotoeter, begint hij te dansen. Kijk net zo vrolijk naar het leven als hij! Doe met hem mee en dans een paar minuten uitbundig door de kamer.', title_pl = 'Zawodowy tancerz 🎶', body_pl = 'Na pierwszy usłyszany rytm, czy to dźwięk reklamy, czy klakson samochodu, zaczyna tańczyć. Patrz na życie tak radośnie jak on! Dołącz do niego w pokoju i zatańczcie przez kilka minut szalony taniec.', title_pt = 'Bailarino profissional 🎶', body_pt = 'Ao primeiro ritmo que ouve, seja a música de um anúncio ou a buzina de um carro, começa a dançar. Olhe para a vida com a alegria dele! Junte-se a ele no quarto e façam uns minutos de dança maluca.', title_sv = 'Proffsdansare 🎶', body_sv = 'Börjar barnet dansa till första bästa rytm, vare sig det är en reklam eller en biltuta? Se på livet lika glatt som barnet! Var med i rummet och dansa galet i några minuter.', title_vi = 'Vũ công chuyên nghiệp 🎶', body_vi = 'Bé bắt đầu nhảy ngay theo nhịp đầu tiên nghe được, dù là nhạc quảng cáo hay tiếng còi xe. Hãy nhìn cuộc sống vui tươi như bé! Cùng bé nhảy một điệu thật "điên" vài phút trong phòng nhé.', title_zh = '专业舞者 🎶', body_zh = '不管是广告声还是汽车喇叭，一听到节奏就开始跳舞。像宝宝一样快乐地看待生活吧！在房间里加入宝宝，疯狂地跳几分钟舞。' WHERE id = '8ac94a1b-a693-498b-9e54-d59e3331d567' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica secreta de papá 👨‍🍼', body_es = 'Ya tienes bastante con el cansancio del día. Deja que papá, con sus juegos, se encargue de prepararle para dormir y de lavarle los dientes, y tú descansa en silencio a un lado.', title_fr = 'La tactique secrète de papa 👨‍🍼', body_fr = 'La fatigue de la journée vous suffit. Confiez la préparation au coucher et le brossage des dents aux jeux de papa, et reposez-vous au calme, de votre côté.', title_hi = 'पापा की खुफ़िया तरकीब 👨‍🍼', body_hi = 'दिन की थकान आपके लिए काफ़ी है। शाम को बच्चे को सोने के लिए तैयार करना और दाँत ब्रश कराना पापा की मस्ती भरी तरकीबों पर छोड़िए, और आप एक तरफ़ खामोशी से आराम कीजिए।', title_id = 'Taktik rahasia Ayah 👨‍🍼', body_id = 'Kelelahan siang hari sudah cukup bagi Anda. Serahkan persiapan tidur dan menyikat giginya di sore hari pada kejahilan Ayah, sementara Anda beristirahat dengan tenang di samping.', title_ja = 'パパの秘密の作戦 👨‍🍼', body_ja = '昼間の疲れでもう十分。夕方の寝る準備や歯みがきは、パパの遊び心にお任せして、あなたは少し離れて静かに休みましょう。', title_ko = '아빠의 비밀 전략 👨‍🍼', body_ko = '낮 동안의 피로만으로도 충분해요. 저녁 잠자리 준비와 양치는 장난기 많은 아빠에게 맡기고, 엄마는 한쪽에서 조용히 쉬세요.', title_nl = 'Papa''s geheime tactiek 👨‍🍼', body_nl = 'Je bent al moe genoeg van de dag. Laat het klaarmaken voor bed en het tandenpoetsen aan het eind van de middag over aan papa''s spelletjes, en rust jij aan de zijkant in stilte uit.', title_pl = 'Tajna taktyka taty 👨‍🍼', body_pl = 'Masz dość dziennego zmęczenia. Przygotowanie do snu i mycie zębów pod wieczór powierz zabawowym pomysłom taty, a ty w ciszy odpocznij z boku.', title_pt = 'A tática secreta do pai 👨‍🍼', body_pt = 'O cansaço do dia já chega. Entregue às brincadeiras do pai a preparação para dormir e a escovagem dos dentes ao fim da tarde, e descanse à parte, em silêncio.', title_sv = 'Pappas hemliga taktik 👨‍🍼', body_sv = 'Dagens trötthet räcker för dig. Lämna över kvällens förberedelser för läggdags och tandborstningen åt pappas lekfullhet, och vila i tystnad en bit bort.', title_vi = 'Chiến thuật bí mật của bố 👨‍🍼', body_vi = 'Mệt mỏi ban ngày đã quá đủ với mẹ. Hãy giao việc chuẩn bị cho bé đi ngủ và đánh răng cho những trò vui của bố, còn mẹ ngồi một góc yên tĩnh nghỉ ngơi.', title_zh = '爸爸的秘密战术 👨‍🍼', body_zh = '白天的疲惫已经够你受了。傍晚哄睡前的准备、刷牙这些事，就交给爱玩的爸爸吧，你在一旁安安静静地休息。' WHERE id = '540ed6cc-ab45-42f3-bbdf-f7d1a37e6094' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ropa doblada y ropa tirada 👗', body_es = 'Tú doblas la ropa con mucho esfuerzo y tu peque llega y la desordena toda en un segundo. En lugar de enfadarte, conviértelo en un juego: «¿A ver quién lanza esta camiseta más lejos?».', title_fr = 'Linge plié, linge déplié 👗', body_fr = 'Vous pliez le linge avec beaucoup d''efforts, et il vient tout défaire en un instant. Au lieu de vous énerver, transformez ça en jeu : « Voyons qui lancera ce t-shirt le plus loin ? »', title_hi = 'तह किए और बिखरे कपड़े 👗', body_hi = 'आप बड़ी मेहनत से कपड़े तह करती हैं और वह आकर तुरंत सब बिखेर देता है? गुस्सा करने के बजाय काम को खेल बना दीजिए: ''देखें, यह शर्ट कौन ज़्यादा दूर फेंकता है?''', title_id = 'Baju dilipat, baju diacak 👗', body_id = 'Anda melipat pakaian dengan susah payah, lalu ia datang dan langsung mengacak semuanya. Daripada kesal, ubah jadi permainan: ''Ayo lihat siapa yang bisa melempar kaus ini paling jauh?''', title_ja = 'たたんでは崩れる洗濯物 👗', body_ja = '一生懸命洗濯物をたたんだのに、やってきて一瞬で全部崩しますか？イライラするかわりに遊びにしましょう：「このシャツをだれがいちばん遠くまで投げられるかな？」', title_ko = '개면 흩어지는 빨래 👗', body_ko = '애써 빨래를 개 놓으면 아이가 와서 순식간에 다 흩어 놓나요? 화내는 대신 놀이로 바꿔 보세요: ''이 티셔츠 누가 더 멀리 던지나 볼까?''', title_nl = 'Opgevouwen en weer verspreide kleren 👗', body_nl = 'Jij vouwt met veel moeite de was op, en hij komt en gooit alles meteen weer door elkaar. Word niet boos, maar maak er een spel van: ''Wie gooit dit shirt het verst?''', title_pl = 'Ubrania złożone i rozrzucone 👗', body_pl = 'Z wielkim trudem składasz ubrania, a on przychodzi i w mgnieniu oka wszystko rozrzuca. Zamiast się złościć, zamień to w zabawę: „Zobaczmy, kto rzuci tę koszulkę dalej?”.', title_pt = 'Roupa dobrada e desfeita 👗', body_pt = 'Dobra a roupa com todo o cuidado e ele vem e desfaz tudo num instante. Em vez de se irritar, transforme isso num jogo: "Vamos ver quem atira esta camisola mais longe?"', title_sv = 'Vikta och utspridda kläder 👗', body_sv = 'Du viker kläderna med stor möda, och barnet kommer och sprider ut allt direkt. I stället för att bli arg, gör sysslan till en lek: ”Vi ser vem som kan kasta den här tröjan längst!”', title_vi = 'Quần áo vừa gấp đã tung 👗', body_vi = 'Mẹ vất vả gấp quần áo, bé chạy đến làm tung hết trong chớp mắt. Thay vì bực mình, hãy biến việc này thành trò chơi: "Xem ai ném chiếc áo này xa hơn nào?"', title_zh = '叠好又被弄乱的衣服 👗', body_zh = '你辛辛苦苦把衣服叠好，宝宝一过来就全弄乱了。与其生气，不如把它变成游戏：“看看谁能把这件衣服扔得更远？”' WHERE id = '75bb1e03-07ff-448a-b132-6eec4abf1a2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Coge la cuchara y lo pringa todo? Pon el temporizador de tomas. No mires la comida derramada, sino la independencia que está ganando, y alégrate.', body_fr = 'Il prend la cuillère et en met partout ? Lancez le minuteur des repas. Ne regardez pas la nourriture renversée, mais réjouissez-vous de l''autonomie qu''il gagne.', body_hi = 'चम्मच ले लेता है और सब जगह खाना फैला देता है? फ़ीडिंग टाइमर चालू कीजिए। बिखरे खाने को नहीं, उसकी मिली आज़ादी को देखकर खुश होइए।', body_id = 'Ia merebut sendok dan membuat semuanya belepotan? Nyalakan Timer Makan. Jangan lihat makanan yang tumpah, bergembiralah melihat kemandirian yang ia raih.', body_ja = 'スプーンを持って、あちこち汚しますか？食事タイマーをオンにしましょう。こぼれた食べ物ではなく、お子さんが手に入れた自立心に目を向けて、よろこびましょう。', body_ko = '숟가락을 들고 사방을 엉망으로 만드나요? 수유 타이머를 켜세요. 흘린 음식 말고 아이가 얻은 자립심을 보며 기뻐하세요.', body_nl = 'Pakt hij de lepel en maakt hij overal een knoeiboel van? Zet de Voedingstimer aan. Kijk niet naar het gemorste eten, maar wees blij met de zelfstandigheid die hij wint.', body_pl = 'Bierze łyżkę i wszystko brudzi? Włącz timer karmienia. Nie patrz na rozsypane jedzenie, tylko ciesz się samodzielnością, którą zdobywa.', body_pt = 'Pega na colher e suja tudo? Ligue o temporizador de alimentação. Não olhe para a comida espalhada, mas para a autonomia que está a ganhar, e alegre-se.', body_sv = 'Tar barnet skeden och kladdar ner överallt? Starta matningstimern. Titta inte på maten som spills, gläds åt friheten barnet vinner.', body_vi = 'Bé cầm thìa và làm bẩn khắp nơi? Hãy bật Hẹn giờ cho bú. Đừng nhìn vào thức ăn vương vãi, hãy vui vì sự tự lập mà bé đạt được.', body_zh = '抢过勺子弄得到处都是？打开喂养计时器。别盯着撒了一地的饭，为宝宝获得的独立开心一下吧。' WHERE id = 'ca77a3ff-10f8-4690-8926-270fe161b3d5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Aparta las verduras de la sopa como si las buscara con microscopio? Encuentra en Recetas saludables salsas que hacen invisibles las verduras. La creatividad es la mejor arma de una madre.', body_fr = 'Il trie les légumes de la soupe comme s''il les cherchait au microscope ? Trouvez dans les Recettes saines des sauces qui rendront les légumes invisibles. La créativité est la plus grande arme d''une maman.', body_hi = 'सूप की सब्ज़ियाँ ऐसे ढूँढकर अलग करता है जैसे माइक्रोस्कोप से देख रहा हो? सेहतमंद रेसिपी में ऐसे सॉस ढूँढिए जो सब्ज़ियों को गायब कर दें। रचनात्मकता माँ का सबसे बड़ा हथियार है।', body_id = 'Ia menyisihkan sayuran di sup seolah mencarinya dengan mikroskop? Temukan resep saus yang membuat sayuran tak terlihat di Resep Sehat. Kreativitas adalah senjata terbesar seorang ibu.', body_ja = 'スープの野菜を顕微鏡で探すように、ひとつ残らずよけていますか？「ヘルシーレシピ」で野菜が見えなくなるソースのレシピを見つけましょう。創意工夫はママのいちばんの武器です。', body_ko = '수프 속 채소를 현미경으로 찾듯 골라내나요? 건강한 레시피에서 채소를 감쪽같이 숨겨 주는 소스 레시피를 찾아보세요. 창의력은 엄마의 가장 큰 무기예요.', body_nl = 'Vist hij de groenten uit zijn soep alsof hij ze met een microscoop zoekt? Vind in Gezonde recepten sausjes die groenten onzichtbaar maken. Creativiteit is het grootste wapen van een moeder.', body_pl = 'Odkłada warzywa z zupy na bok, jakby szukał ich pod mikroskopem? Znajdź w Zdrowych przepisach przepisy na sosy, w których warzywa staną się niewidoczne. Kreatywność to największa broń mamy.', body_pt = 'Põe de lado os legumes da sopa como se os procurasse ao microscópio? Encontre nas Receitas Saudáveis receitas de molhos que tornam os legumes invisíveis. A criatividade é a maior arma de uma mãe.', body_sv = 'Sorterar barnet bort grönsakerna i soppan som om hen letade med mikroskop? Hitta såsrecept i Hälsosamma recept som gör grönsakerna osynliga. Kreativitet är mammans största vapen.', body_vi = 'Bé gạt rau trong bát canh ra như thể soi bằng kính hiển vi? Hãy tìm trong Công thức lành mạnh những công thức nước sốt giúp rau "tàng hình". Sự sáng tạo là vũ khí lớn nhất của người mẹ.', body_zh = '像拿着显微镜一样把汤里的蔬菜挑到一边？在健康食谱里找找能让蔬菜“隐身”的酱汁做法。创意是妈妈最大的武器。' WHERE id = '43d613a7-90fe-4d48-880a-a0dadfb94dab' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mira abajo, ¿qué descubre? 👣', body_es = 'Le encanta andar descalzo y tocar superficies distintas. Estimular los nervios de la planta del pie es importante para su equilibrio: deja que ande sin calcetines.', title_fr = 'Regarde par terre, que découvre-t-il ? 👣', body_fr = 'Il adore marcher pieds nus et toucher différentes surfaces. L''éveil des nerfs de la plante des pieds est important pour son équilibre, laissez-le marcher sans chaussettes.', title_hi = 'नीचे देखिए, वह क्या खोज रहा है? 👣', body_hi = 'नंगे पैर चलने और अलग-अलग सतहों को छूने में उसे खास मज़ा आता है। तलवों की नसों का जागना उसके संतुलन के लिए ज़रूरी है, उसे बिना मोज़ों के चलने दीजिए।', title_id = 'Lihat ke bawah, apa yang ia temukan? 👣', body_id = 'Ia sangat senang berjalan tanpa alas kaki dan menyentuh berbagai permukaan. Rangsangan saraf di telapak kakinya penting untuk keseimbangannya, biarkan ia berjalan tanpa kaus kaki.', title_ja = '下を見て、何を発見中？👣', body_ja = 'はだしで歩いたり、いろいろな表面にふれたりするのが大好き。足の裏の神経が目覚めることはバランス感覚にとって大切、くつしたなしで歩かせてあげましょう。', title_ko = '발밑을 보세요, 무엇을 발견했을까요? 👣', body_ko = '맨발로 걸으며 여러 표면을 만지는 걸 특히 좋아하나요? 발바닥 신경의 자극은 균형 감각에 중요해요. 양말 없이 걷게 해 주세요.', title_nl = 'Kijk naar beneden, wat ontdekt hij? 👣', body_nl = 'Hij geniet extra van blootsvoets lopen en verschillende ondergronden voelen. Het prikkelen van de zenuwen onder zijn voetzolen is belangrijk voor zijn evenwicht, laat hem zonder sokken rondlopen.', title_pl = 'Spójrz w dół, co odkrywa? 👣', body_pl = 'Z wyjątkową przyjemnością chodzi boso i dotyka różnych powierzchni. Pobudzanie nerwów na podeszwach stóp jest ważne dla jego równowagi, pozwól mu chodzić bez skarpetek.', title_pt = 'Olha para baixo: o que está a descobrir? 👣', body_pt = 'Adora andar descalço e tocar em superfícies diferentes. Estimular os nervos da planta do pé é importante para o equilíbrio: deixe-o andar sem meias.', title_sv = 'Titta ner, vad upptäcker barnet? 👣', body_sv = 'Barnet njuter särskilt av att gå barfota och känna på olika ytor. Att nerverna under fötterna väcks är viktigt för balansen, låt barnet gå utan strumpor.', title_vi = 'Nhìn xuống xem, bé khám phá gì nào? 👣', body_vi = 'Bé đặc biệt thích đi chân trần và chạm vào các bề mặt khác nhau. Việc kích thích các dây thần kinh dưới lòng bàn chân rất quan trọng cho khả năng giữ thăng bằng, hãy để bé đi không cần tất.', title_zh = '往下看，宝宝在发现什么？👣', body_zh = '特别喜欢光着脚走路，摸摸不同的地面。唤醒脚底的神经对宝宝的平衡很重要，就让宝宝不穿袜子走走吧。' WHERE id = '6fd78011-ad7d-48f0-9941-25d07912808e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los guardianes de la noche 🧸', body_es = '¿Le da miedo la oscuridad? Coloca sus ositos y juguetes favoritos alrededor de la cama y dile: «Ellos te van a proteger hasta mañana». Esta seguridad visual funciona de maravilla.', title_fr = 'Les gardiens de la nuit 🧸', body_fr = 'Il a peur du noir ? Installez ses nounours et jouets préférés tout autour de son lit et dites-lui : « Ils vont te protéger jusqu''au matin. » Cette sécurité visuelle marche à merveille.', title_hi = 'रात के रखवाले 🧸', body_hi = 'अंधेरे से डरता है? उसके सबसे पसंदीदा टेडी और खिलौने बिस्तर के चारों ओर सजाइए और कहिए ''ये सुबह तक तुम्हारी रक्षा करेंगे।'' यह दिखने वाला भरोसा कमाल का काम करता है।', title_id = 'Penjaga malam 🧸', body_id = 'Ia takut gelap? Susun boneka beruang dan mainan favoritnya di sekeliling tempat tidur dan katakan ''Mereka akan menjagamu sampai pagi''. Rasa aman visual ini sangat ampuh.', title_ja = '夜を守るなかまたち 🧸', body_ja = '暗やみをこわがりますか？お気に入りのくまさんやおもちゃをベッドのまわりに並べて、「みんなが朝まで守ってくれるよ」と伝えましょう。目に見える安心感がとてもよく効きます。', title_ko = '밤의 수호자들 🧸', body_ko = '어둠을 무서워하나요? 가장 좋아하는 곰 인형과 장난감을 침대 둘레에 놓고 ''아침까지 얘네가 지켜 줄 거야''라고 말해 주세요. 눈에 보이는 이 안정감이 정말 효과 있어요.', title_nl = 'Bewakers van de nacht 🧸', body_nl = 'Is hij bang in het donker? Zet zijn liefste beren en knuffels rondom zijn bed en zeg: ''Zij passen tot de ochtend op je.'' Dit zichtbare gevoel van veiligheid werkt geweldig.', title_pl = 'Nocni strażnicy 🧸', body_pl = 'Boi się ciemności? Ułóż jego ulubione misie i zabawki dookoła łóżka i powiedz: „One będą cię pilnować do rana”. To wizualne poczucie bezpieczeństwa świetnie działa.', title_pt = 'Os guardiões da noite 🧸', body_pt = 'Tem medo do escuro? Ponha os ursinhos e brinquedos preferidos à volta da cama e diga: "Eles vão proteger-te até de manhã." Esta segurança visual funciona muito bem.', title_sv = 'Nattens beskyddare 🧸', body_sv = 'Är barnet rädd för mörkret? Ställ favoritnallarna och leksakerna runt hela sängen och säg ”De vakar över dig till i morgon bitti”. Den här visuella tryggheten fungerar utmärkt.', title_vi = 'Những người bảo vệ ban đêm 🧸', body_vi = 'Bé sợ bóng tối? Hãy xếp những chú gấu và đồ chơi bé yêu thích quanh giường và nói "Các bạn ấy sẽ bảo vệ con đến sáng". Sự an tâm bằng hình ảnh này rất hiệu quả.', title_zh = '夜晚的守护者 🧸', body_zh = '害怕黑？把最爱的小熊和玩具摆在床的四周，告诉宝宝“它们会守护你到天亮”。这种看得见的安全感非常有效。' WHERE id = 'dcc98b1b-6e09-41d3-9be6-78333aecdab4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La confirmación del silencio 🤫', body_es = 'Después de un día ruidoso, cuando se duerma, mide el silencio de la habitación con el Medidor de sonido. Solo ver esos números acercarse a cero ya funciona como terapia para la mente de una madre.', title_fr = 'La preuve du silence 🤫', body_fr = 'Après une journée bruyante, quand il dort, mesurez le silence de la chambre avec le Sonomètre. Rien que voir ces chiffres approcher de zéro agit comme une thérapie sur le cerveau d''une maman.', title_hi = 'खामोशी का सबूत 🤫', body_hi = 'शोर भरे दिन के बाद, बच्चे के सोने पर साउंड मीटर से कमरे की खामोशी मापिए। शून्य के करीब पहुँचते अंक देखना भी माँ के दिमाग पर थेरेपी जैसा असर करता है।', title_id = 'Bukti keheningan 🤫', body_id = 'Setelah hari yang bising, saat anak tidur, ukur keheningan kamar dengan Pengukur Suara. Melihat angkanya mendekati nol saja sudah terasa seperti terapi bagi otak seorang ibu.', title_ja = '静けさを確かめる 🤫', body_ja = 'にぎやかな一日のあと、お子さんが眠ったら「サウンドメーター」で部屋の静けさを測ってみましょう。ゼロに近づく数字を見るだけで、ママの頭にはセラピーのように効きます。', title_ko = '고요를 확인하세요 🤫', body_ko = '시끌벅적한 하루가 지나고 아이가 잠들면 소음 측정기로 방의 고요함을 재 보세요. 0에 가까워지는 숫자를 보는 것만으로도 엄마 머리에는 테라피가 돼요.', title_nl = 'Bevestiging van de stilte 🤫', body_nl = 'Meet na een luidruchtige dag, als hij slaapt, de stilte in de kamer met de Geluidsmeter. Alleen al die getallen naar nul zien gaan werkt als therapie voor het hoofd van een moeder.', title_pl = 'Potwierdzona cisza 🤫', body_pl = 'Po głośnym dniu, gdy dziecko zaśnie, zmierz ciszę w pokoju Miernikiem dźwięku. Już sam widok liczb spadających prawie do zera działa na głowę mamy jak terapia.', title_pt = 'A confirmação do silêncio 🤫', body_pt = 'Depois de um dia barulhento, quando a criança adormecer, meça o silêncio do quarto com o Medidor de Som. Só ver aqueles números a aproximarem-se do zero já é terapia para o cérebro de uma mãe.', title_sv = 'Bekräftad tystnad 🤫', body_sv = 'Efter en högljudd dag, mät tystnaden i rummet med Ljudmätaren när barnet har somnat. Bara att se siffrorna närma sig noll fungerar som terapi för mammans hjärna.', title_vi = 'Xác nhận sự yên tĩnh 🤫', body_vi = 'Sau một ngày ồn ào, khi bé đã ngủ, hãy đo độ yên tĩnh trong phòng bằng Đo âm thanh. Chỉ cần nhìn những con số gần về 0 thôi cũng như liệu pháp cho tâm trí của mẹ.', title_zh = '确认安静 🤫', body_zh = '热闹了一天，孩子睡着后，用分贝仪测一测房间的安静程度。光是看到那接近零的数字，对妈妈的大脑就像一次疗愈。' WHERE id = '3d8d4230-c58c-4f55-bb5e-c5c92f713201' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El «¡No!» de la mañana 🛑', body_es = '¿Aún no ha abierto los ojos y ya te dice «¡No!» a lo que le propones? A las puertas de los 3 años, no preguntes: pasa a la acción. En lugar de «¿Nos lavamos la cara?», di «¡Es hora de lavarse la cara!».', title_fr = 'Le « Non ! » du matin 🛑', body_fr = 'À peine les yeux ouverts, il répond « Non ! » à tout ce que vous lui proposez. À l''approche des 3 ans, ne posez pas de questions, passez directement à l''action. Au lieu de « On va se laver le visage ? », dites « C''est l''heure de se laver le visage ! ».', title_hi = 'सुबह की ''ना!'' 🛑', body_hi = 'आँख खुलने से पहले ही कुछ भी पूछो तो ''नहीं!'' कहता है? 3 साल की दहलीज़ पर सवाल मत पूछिए, बस काम शुरू कीजिए। ''चलो मुँह-हाथ धोएँ?'' नहीं, ''मुँह-हाथ धोने का समय है!'' कहिए।', title_id = '''Tidak!'' di pagi hari 🛑', body_id = 'Bahkan sebelum matanya terbuka, ia langsung bilang ''Tidak!'' pada apa pun yang Anda tawarkan. Menjelang usia 3 tahun, jangan bertanya, langsung bertindak. Ganti ''Ayo cuci muka?'' dengan ''Waktunya cuci muka!''', title_ja = '朝の「いや！」🛑', body_ja = 'まだ目も開けきらないうちに何かを提案すると「いや！」と言いますか？3歳を前にしたら、質問はせずに行動に移しましょう。「顔を洗おうか？」ではなく「顔を洗う時間だよ！」と言って。', title_ko = '아침의 ''싫어!'' 🛑', body_ko = '눈도 다 뜨기 전에 무언가를 권하면 ''싫어!''라고 하나요? 세 돌을 앞두고는 묻지 말고 바로 행동으로 옮기세요. ''세수할까?'' 대신 ''세수할 시간이야!''라고 말해 보세요.', title_nl = 'Het ochtend-''Nee!'' 🛑', body_nl = 'Zegt hij ''Nee!'' als je hem iets voorstelt, nog voor hij zijn ogen open heeft? Stel op de drempel van 3 jaar geen vragen, maar kom gewoon in actie. Zeg niet ''Zullen we ons wassen?'', maar ''Het is tijd om je te wassen!''', title_pl = 'Poranne „Nie!” 🛑', body_pl = 'Zanim jeszcze otworzy oczy, na każdą propozycję mówi „Nie!”? U progu 3. roku życia nie zadawaj pytań, po prostu działaj. Zamiast „Umyjemy buzię?”, powiedz: „Czas umyć buzię!”.', title_pt = 'O "Não!" da manhã 🛑', body_pt = 'Ainda nem abriu os olhos e já diz "Não!" a tudo o que lhe propõe? À porta dos 3 anos, não faça perguntas, passe à ação. Em vez de "Vamos lavar a cara?", diga "É hora de lavar a cara!".', title_sv = 'Morgonens Nej! 🛑', body_sv = 'Barnet säger ”Nej!” när du erbjuder något innan hen ens öppnat ögonen. På tröskeln till 3 år, ställ inga frågor, sätt bara igång. Säg inte ”Ska vi tvätta ansiktet?”, säg ”Nu är det dags att tvätta ansiktet!”.', title_vi = 'Tiếng "Không!" buổi sáng 🛑', body_vi = 'Mắt còn chưa mở, mẹ đề nghị gì bé cũng nói "Không!". Khi bé gần 3 tuổi, đừng hỏi, cứ hành động. Thay vì "Mình đi rửa mặt nhé?", hãy nói "Đến giờ rửa mặt rồi!".', title_zh = '早晨的“不要！” 🛑', body_zh = '还没睁开眼，你提议什么都说“不！”？在快3岁的门槛上，别提问，直接行动。别说“我们去洗脸好吗”，而是说“洗脸时间到啦！”' WHERE id = '53046b7a-695e-4d17-9dda-231255060141' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedícate tiempo también a ti 🥑', body_es = 'Tanto ajetreo te ha dejado sin fuerzas. En lugar de picar algo de pie, prepárate con Recetas saludables un plato especial, saciante y cargado de vitaminas, y cómelo con gusto. Necesitas esa energía.', title_fr = 'Prenez du temps pour vous aussi 🥑', body_fr = 'Cette course permanente vous a vidée. Au lieu de grignoter debout, préparez avec les Recettes saines une assiette spéciale, rassasiante et pleine de vitamines, et savourez-la. Vous avez absolument besoin d''énergie.', title_hi = 'अपने लिए भी समय निकालिए 🥑', body_hi = 'भागदौड़ ने आपको थका दिया है। खड़े-खड़े कुछ भी खा लेने के बजाय सेहतमंद रेसिपी से पेट भरने वाली, विटामिन से भरपूर एक खास थाली बनाइए और मज़े से खाइए। आपको ऊर्जा की सच में ज़रूरत है।', title_id = 'Luangkan waktu untuk diri sendiri 🥑', body_id = 'Kesibukan membuat Anda kehabisan tenaga. Daripada makan sambil berdiri, siapkan sepiring makanan istimewa yang mengenyangkan dan kaya vitamin dari Resep Sehat, lalu nikmati. Anda sangat butuh energi itu.', title_ja = '自分の時間もつくって 🥑', body_ja = 'バタバタ続きでくたくたですね。立ったままつまむかわりに、「ヘルシーレシピ」から満足できるビタミンたっぷりのひと皿を用意して、味わって食べましょう。あなたには元気が必要です。', title_ko = '엄마를 위한 시간도 챙기세요 🥑', body_ko = '정신없이 뛰어다니느라 기운이 다 빠졌죠. 서서 대충 먹는 대신 건강한 레시피에서 든든하고 비타민 가득한 특별한 한 접시를 차려 맛있게 드세요. 엄마에게 에너지는 꼭 필요해요.', title_nl = 'Neem ook tijd voor jezelf 🥑', body_nl = 'Het gerace heeft je uitgeput. Eet niet staand even snel iets, maar maak uit Gezonde recepten een speciaal, voedzaam bord vol vitamines klaar en geniet ervan. Je hebt die energie echt nodig.', title_pl = 'Znajdź czas też dla siebie 🥑', body_pl = 'Bieganina odebrała ci siły. Zamiast jeść coś na stojąco, przygotuj ze Zdrowych przepisów sycący talerz pełen witamin i zjedz go z przyjemnością. Energia jest ci naprawdę potrzebna.', title_pt = 'Reserve tempo também para si 🥑', body_pt = 'A correria deixou-a sem forças. Em vez de petiscar de pé, prepare nas Receitas Saudáveis um prato especial, saciante e cheio de vitaminas, e coma com prazer. Precisa mesmo dessa energia.', title_sv = 'Ta tid för dig själv också 🥑', body_sv = 'Allt springande har gjort dig helt slut. I stället för att småäta stående, gör en mättande, vitaminrik tallrik från Hälsosamma recept och ät med njutning. Du behöver verkligen energin.', title_vi = 'Dành thời gian cho chính mình 🥑', body_vi = 'Chạy tới chạy lui khiến mẹ kiệt sức. Thay vì ăn vội đứng một chỗ, hãy chuẩn bị một đĩa ăn no bụng, giàu vitamin từ Công thức lành mạnh và thưởng thức thật ngon miệng. Mẹ rất cần năng lượng.', title_zh = '也给自己留点时间 🥑', body_zh = '忙得团团转，累坏了吧。别站着随便吃两口，从健康食谱里准备一盘丰盛、富含维生素的特别饭菜，好好享受。你一定需要能量。' WHERE id = 'e5f27372-8ce2-40d6-acbc-12281fab28bb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorador descalzo 👣', body_es = '¿No quiere ponerse calcetines y sale corriendo a esconderse? Deja que sienta un rato descalzo el suelo, la alfombra o las baldosas frías. Estimular las terminaciones nerviosas de la planta del pie es insustituible para su equilibrio.', title_fr = 'L''explorateur pieds nus 👣', body_fr = 'Il refuse de mettre ses chaussettes et part se cacher ? Laissez-le sentir un peu le sol, le tapis, le carrelage froid pieds nus. Le développement des terminaisons nerveuses de la plante des pieds est précieux pour son équilibre.', title_hi = 'नंगे पैर वाला खोजी 👣', body_hi = 'मोज़े नहीं पहनना चाहता, भागकर छिप जाता है? उसे थोड़ी देर नंगे पैर ज़मीन, कालीन और ठंडी टाइल महसूस करने दीजिए। तलवों की नसों का विकास उसके संतुलन के लिए बेहद अहम है।', title_id = 'Penjelajah tanpa alas kaki 👣', body_id = 'Ia tidak mau memakai kaus kaki dan kabur bersembunyi? Biarkan ia sebentar merasakan lantai, karpet, dan ubin dingin dengan kaki telanjang. Perkembangan ujung saraf di telapak kaki sangat berharga untuk keseimbangannya.', title_ja = 'はだしの探検家 👣', body_ja = 'くつしたをはきたがらず、逃げて隠れますか？しばらくはだしで床やカーペット、冷たいタイルを感じさせてあげましょう。足の裏の神経の発達は、バランス感覚にとってかけがえのないものです。', title_ko = '맨발의 탐험가 👣', body_ko = '양말을 안 신겠다고 도망가 숨나요? 잠시 맨발로 바닥, 카펫, 차가운 타일을 느끼게 해 주세요. 발바닥 신경의 발달은 균형 감각에 정말 소중해요.', title_nl = 'Blootsvoetse ontdekkingsreiziger 👣', body_nl = 'Wil hij geen sokken aan en rent hij weg om zich te verstoppen? Laat hem even met blote voeten de vloer, het tapijt en de koude tegels voelen. De ontwikkeling van de zenuwuiteinden onder zijn voetzolen is onmisbaar voor zijn evenwicht.', title_pl = 'Bosy odkrywca 👣', body_pl = 'Nie chce zakładać skarpetek, ucieka i się chowa? Niech przez chwilę poczuje bosymi stopami podłogę, dywan, zimne płytki. Rozwój zakończeń nerwowych na podeszwach stóp jest bezcenny dla jego równowagi.', title_pt = 'Explorador descalço 👣', body_pt = 'Não quer calçar meias e foge para se esconder? Deixe-o sentir um pouco, descalço, o chão, o tapete e o mosaico frio. O desenvolvimento das terminações nervosas da planta do pé é insubstituível para o equilíbrio.', title_sv = 'Barfota upptäcktsresande 👣', body_sv = 'Vill barnet inte ta på sig strumpor och springer och gömmer sig? Låt hen känna golvet, mattan och det kalla kaklet med bara fötter en stund. Utvecklingen av nervändarna under fötterna är ovärderlig för balansen.', title_vi = 'Nhà thám hiểm chân trần 👣', body_vi = 'Bé không chịu đi tất, chạy đi trốn? Hãy để bé đi chân trần một lúc để cảm nhận sàn nhà, thảm, gạch mát lạnh. Sự phát triển của các đầu dây thần kinh dưới lòng bàn chân là vô giá cho khả năng giữ thăng bằng.', title_zh = '光脚小探险家 👣', body_zh = '不肯穿袜子，跑去躲起来？就让宝宝光着脚感受一下地面、地毯和凉凉的瓷砖吧。脚底神经末梢的发育，对宝宝的平衡无可替代。' WHERE id = '25c4de30-89c3-4f45-952f-3b21fb85b41e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apaga la luz, que llegue el sueño 🌙', body_es = 'Para que se duerma antes, apaga todas las luces extra de la habitación y las pantallas de las tablets. La melatonina solo se produce en un ambiente oscuro y sin tecnología.', title_fr = 'Éteins la lumière, que le sommeil vienne 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre. La mélatonine n''est sécrétée que dans le noir, sans technologie.', title_hi = 'लाइटें बंद, नींद आए 🌙', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ अंधेरे और बिना गैजेट वाले माहौल में बनता है।', title_id = 'Matikan lampu, biar kantuk datang 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar. Melatonin hanya diproduksi dalam suasana gelap dan bebas teknologi.', title_ja = '明かりを消して、眠りを呼ぼう 🌙', body_ja = '早く寝つけるように、部屋の余分な明かりとタブレットの画面をすべて消しましょう。メラトニンは、暗くて機器のない環境でしか分泌されません。', title_ko = '불을 끄면 잠이 와요 🌙', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명과 태블릿 화면을 모두 꺼 주세요. 멜라토닌은 어둡고 전자기기 없는 환경에서만 분비돼요.', title_nl = 'Doe het licht uit, dan komt de slaap 🌙', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en tabletschermen in de kamer uit. Melatonine wordt alleen in een donkere omgeving zonder techniek aangemaakt.', title_pl = 'Zgaś światło, niech przyjdzie sen 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina wydziela się tylko w ciemnym otoczeniu bez technologii.', title_pt = 'Apague as luzes, que o sono vem 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets. A melatonina só é produzida num ambiente escuro e sem tecnologia.', title_sv = 'Släck lamporna, låt sömnen komma 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplattornas skärmar i rummet. Melatonin utsöndras bara i en mörk miljö utan teknik.', title_vi = 'Tắt đèn để giấc ngủ đến 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng. Melatonin chỉ được tiết ra trong môi trường tối và không có thiết bị công nghệ.', title_zh = '关灯，睡意来 🌙', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光和平板屏幕。褪黑素只有在昏暗、没有电子设备的环境里才会分泌。' WHERE id = 'a0e0a012-48a8-4169-b4f6-62857311b266' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Búsqueda en la naturaleza 🍁', body_es = 'Preparaos con Tiempo y ropa y salid fuera. Jugad en el parque a encontrar piedras distintas y hojas de colores. A esta edad la naturaleza es su juguete más grande e interactivo.', title_fr = 'Chasse aux trésors de la nature 🍁', body_fr = 'Préparez-vous avec Météo et tenue et sortez. Au parc, jouez à trouver des cailloux différents et des feuilles colorées. À cet âge, la nature est son plus grand jouet, et le plus interactif.', title_hi = 'प्रकृति की खोज 🍁', body_hi = 'मौसम और कपड़े टूल से तैयार होकर बाहर निकलिए। पार्क में अलग-अलग पत्थर और रंग-बिरंगे पत्ते ढूँढने का खेल खेलिए। इस उम्र में प्रकृति उसके लिए सबसे बड़ा और इंटरैक्टिव खिलौना है।', title_id = 'Berburu harta alam 🍁', body_id = 'Berpakaianlah sesuai cuaca dan keluarlah. Di taman, mainkan permainan mencari batu yang berbeda dan daun warna-warni. Di usia ini, alam adalah mainan terbesar dan paling interaktif baginya.', title_ja = '自然の宝さがし 🍁', body_ja = '「天気と服装」で準備して外へ出かけましょう。公園でいろいろな石やカラフルな葉っぱを見つける遊びをして。この年齢の子にとって、自然はいちばん大きくて体験できるおもちゃです。', title_ko = '자연 보물찾기 🍁', body_ko = '날씨와 옷차림을 확인하고 밖으로 나가세요. 공원에서 여러 가지 돌과 알록달록한 나뭇잎을 찾는 놀이를 해 보세요. 이 나이의 아이에게 자연은 가장 크고 생생한 장난감이에요.', title_nl = 'Op zoek in de natuur 🍁', body_nl = 'Bereid je voor met Weer en kleding en ga naar buiten. Speel in het park een zoekspel met bijzondere steentjes en kleurrijke bladeren. De natuur is op deze leeftijd het grootste en meest interactieve speelgoed voor hem.', title_pl = 'Poszukiwania w przyrodzie 🍁', body_pl = 'Przygotujcie się z Pogodą i ubiorem i wyjdźcie na zewnątrz. Pobawcie się w parku w szukanie różnych kamyków i kolorowych liści. Przyroda to w tym wieku jego największa i najbardziej interaktywna zabawka.', title_pt = 'À procura da natureza 🍁', body_pt = 'Prepare-se com o Tempo e Roupa e saiam. No parque, brinquem a encontrar pedras diferentes e folhas coloridas. Nesta idade, a natureza é o maior e mais interativo brinquedo para ele.', title_sv = 'Naturjakt 🍁', body_sv = 'Förbered er med Väder och kläder och gå ut. Lek en lek i parken där ni letar efter olika stenar och färgglada löv. I den här åldern är naturen barnets största och mest interaktiva leksak.', title_vi = 'Đi tìm thiên nhiên 🍁', body_vi = 'Hãy mặc đồ theo Thời tiết và trang phục rồi ra ngoài. Ở công viên, chơi trò tìm những viên sỏi khác nhau, những chiếc lá nhiều màu. Ở tuổi này, thiên nhiên là món đồ chơi lớn nhất và sinh động nhất với bé.', title_zh = '大自然寻宝 🍁', body_zh = '用天气穿衣工具准备好，出门去吧。在公园里玩找不同石头、彩色树叶的游戏。这个年龄，大自然就是宝宝最大、最有互动性的玩具。' WHERE id = 'ac0003df-1b37-4e86-98c2-561682149d03' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despiste en el súper 🛒', body_es = '¿Fuiste al súper fiándote de tu memoria y volviste sin lo más importante? Acostúmbrate a apuntar al momento todo lo que falta en la Lista de la compra y deja que la app se acuerde por ti.', title_fr = 'Trou de mémoire au supermarché 🛒', body_fr = 'Vous avez fait confiance à votre mémoire au supermarché et êtes rentrée sans le plus important ? Prenez l''habitude de noter tout de suite chaque besoin dans la Liste de courses, laissez l''application s''en souvenir à votre place.', title_hi = 'बाज़ार में भूलने की आदत 🛒', body_hi = 'याददाश्त के भरोसे बाज़ार गईं और सबसे ज़रूरी चीज़ भूलकर लौट आईं? सारी ज़रूरतें तुरंत शॉपिंग लिस्ट में लिखने की आदत डालिए, आपकी जगह ऐप याद रखे।', title_id = 'Lupa saat belanja 🛒', body_id = 'Mengandalkan ingatan saat belanja dan pulang tanpa barang yang paling penting? Biasakan langsung mencatat semua kebutuhan di Daftar Belanja, biar aplikasi yang mengingat untuk Anda.', title_ja = 'スーパーでのもの忘れ 🛒', body_ja = '記憶にたよって買い物に行き、いちばん大事なものを買い忘れて帰ってきた？必要なものはすべてすぐに「買い物リスト」に書く習慣をつけて、アプリにかわりに覚えてもらいましょう。', title_ko = '마트에서 깜빡깜빡 🛒', body_ko = '기억만 믿고 마트에 갔다가 가장 중요한 걸 잊고 돌아왔나요? 필요한 건 바로 쇼핑 목록에 적는 습관을 들이고, 기억은 앱에 맡기세요.', title_nl = 'Vergeetachtig in de supermarkt 🛒', body_nl = 'Vertrouwde je op je geheugen en kwam je zonder het belangrijkste uit de supermarkt terug? Maak er een gewoonte van om alles meteen op het Boodschappenlijstje te zetten en laat de app voor je onthouden.', title_pl = 'Zapominalstwo w sklepie 🛒', body_pl = 'Zaufałaś pamięci, poszłaś do sklepu i wróciłaś bez najważniejszej rzeczy? Wyrób sobie nawyk, by od razu wpisywać wszystkie potrzeby na Listę zakupów, i niech aplikacja pamięta za ciebie.', title_pt = 'Esquecimentos no supermercado 🛒', body_pt = 'Confiou na memória, foi ao supermercado e voltou sem o mais importante? Crie o hábito de apontar logo tudo o que falta na Lista de Compras e deixe a app lembrar-se por si.', title_sv = 'Glömska i affären 🛒', body_sv = 'Litade du på ditt minne när du handlade och kom hem utan det viktigaste? Gör det till en vana att genast skriva in allt i Inköpslistan och låt appen komma ihåg åt dig.', title_vi = 'Đãng trí ở siêu thị 🛒', body_vi = 'Mẹ tin vào trí nhớ để đi siêu thị rồi về nhà thiếu đúng món quan trọng nhất? Hãy tập ghi ngay mọi thứ cần mua vào Danh sách mua sắm và để ứng dụng nhớ giúp mẹ.', title_zh = '超市里的健忘 🛒', body_zh = '相信自己的记性去超市，结果最重要的东西忘了买就回来了？养成习惯，马上把所有需要的东西都写进购物清单，让应用替你记着。' WHERE id = '85540a77-8c0c-40d1-bec5-6ddc93f07354' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ayudante de la mañana 🧑‍🍳', body_es = 'Quiere ayudarte a preparar el desayuno. Echará la harina fuera, derramará el agua, la cocina quedará hecha un desastre... Pero crece con estas pequeñas pruebas de motricidad. Ten paciencia.', title_fr = 'Le petit aide du matin 🧑‍🍳', body_fr = 'Il veut vous aider à préparer le petit-déjeuner. Il renversera la farine, l''eau, la cuisine sera sens dessus dessous... Mais il grandit grâce à ces petits essais de motricité. Soyez patiente.', title_hi = 'सुबह का मददगार 🧑‍🍳', body_hi = 'नाश्ता बनाने में मदद करना चाहता है। आटा गिराएगा, पानी फैलाएगा, रसोई गंदी होगी... लेकिन वह इन छोटे मोटर स्किल वाले प्रयोगों से ही बड़ा होता है। धैर्य रखिए।', title_id = 'Asisten pagi 🧑‍🍳', body_id = 'Ia ingin membantu menyiapkan sarapan. Tepung akan tumpah, air berceceran, dapur berantakan... Tetapi ia tumbuh lewat percobaan motorik kecil ini. Bersabarlah.', title_ja = '朝のお手伝いさん 🧑‍🍳', body_ja = '朝ごはんの準備を手伝いたがりますか？小麦粉はこぼれ、お水はあふれ、キッチンは汚れる…でも、この小さな運動の挑戦で成長しているのです。気長にいきましょう。', title_ko = '아침의 꼬마 도우미 🧑‍🍳', body_ko = '아침 준비를 돕고 싶어 하나요? 밀가루는 쏟고 물은 흘리고 주방은 엉망이 되겠죠... 하지만 이런 작은 소근육 실험으로 자라는 거예요. 인내심을 가지세요.', title_nl = 'Ochtendhulpje 🧑‍🍳', body_nl = 'Wil hij helpen met het ontbijt? Hij morst bloem, knoeit met water en de keuken wordt een zooitje... Maar met deze kleine motoriekoefeningen groeit hij. Heb geduld.', title_pl = 'Poranny pomocnik 🧑‍🍳', body_pl = 'Chce pomóc przygotować śniadanie. Rozsypie mąkę, rozleje wodę, kuchnia będzie w opłakanym stanie... Ale on rośnie dzięki tym małym próbom motoryki. Bądź cierpliwa.', title_pt = 'Ajudante da manhã 🧑‍🍳', body_pt = 'Quer ajudar a fazer o pequeno-almoço. Vai entornar a farinha, espalhar a água, sujar a cozinha... Mas é com estes pequenos testes de motricidade que cresce. Tenha paciência.', title_sv = 'Morgonens hjälpreda 🧑‍🍳', body_sv = 'Barnet vill hjälpa till med frukosten. Mjölet hamnar fel, vattnet spills, köket blir kladdigt... Men barnet växer genom de här små motoriska försöken. Ha tålamod.', title_vi = 'Người phụ bếp buổi sáng 🧑‍🍳', body_vi = 'Bé muốn giúp mẹ làm bữa sáng. Bột sẽ đổ, nước sẽ tràn, bếp sẽ bừa... Nhưng bé lớn lên nhờ những thử nghiệm vận động nhỏ này. Hãy kiên nhẫn nhé.', title_zh = '早晨小帮手 🧑‍🍳', body_zh = '想帮忙做早餐。会撒面粉、洒水，厨房会一团糟……但宝宝正是在这些小小的动作练习中长大。耐心一点。' WHERE id = 'bd0902bb-9be1-40b5-8e41-73f85b835f0e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El show de papá mago 🤡', body_es = 'Cuando tus trucos ya no funcionan, los sonidos raros de papá salvan la situación al instante. En las crisis de la noche, pásale la pelota y disfruta desde fuera de las carcajadas.', title_fr = 'Le spectacle de papa magicien 🤡', body_fr = 'Quand vos astuces ne marchent plus, les bruits bizarres de papa sauvent la situation en un instant. Pendant les crises du soir, passez-lui la balle et profitez de loin des éclats de rire.', title_hi = 'जादूगर पापा का शो 🤡', body_hi = 'जब आपकी तरकीबें काम नहीं करतीं, तो पापा की अजीब आवाज़ें तुरंत हालात संभाल लेती हैं। शाम के नखरों में बॉल उनके पाले में डालिए और दूर से खिलखिलाहटें देखिए।', title_id = 'Pertunjukan Ayah sang pesulap 🤡', body_id = 'Saat cara Anda tidak lagi berhasil, suara aneh Ayah bisa seketika menyelamatkan keadaan. Saat krisis malam hari, oper bolanya kepada Ayah dan saksikan tawa riang dari jauh.', title_ja = '魔法使いパパのショー 🤡', body_ja = 'あなたの手がもう効かないとき、パパのおもしろい声がすぐに状況を救ってくれます。夕方のかんしゃくでは、パパにバトンを渡して、楽しい笑い声をそばで眺めましょう。', title_ko = '마술사 아빠의 쇼 🤡', body_ko = '엄마의 방법이 더는 통하지 않을 때 아빠의 웃긴 소리가 순식간에 상황을 구해 줘요. 저녁 떼쓰기 때는 아빠에게 공을 넘기고 옆에서 즐거운 웃음소리를 즐기세요.', title_nl = 'De show van tovenaar papa 🤡', body_nl = 'Als jouw trucjes niet meer werken, redden papa''s gekke geluiden de situatie meteen. Speel de bal bij avondbuien naar hem door en kijk vanaf de zijlijn naar het vrolijke gelach.', title_pl = 'Show taty czarodzieja 🤡', body_pl = 'Gdy twoje sposoby już nie działają, dziwne odgłosy taty od razu ratują sytuację. Podczas wieczornych kryzysów podaj mu piłeczkę i z boku słuchaj radosnych chichotów.', title_pt = 'O espetáculo do pai mágico 🤡', body_pt = 'Quando os seus truques já não funcionam, os sons estranhos do pai salvam logo a situação. Nas crises da noite, passe-lhe a bola e assista de longe às gargalhadas alegres.', title_sv = 'Trollkarlspappans show 🤡', body_sv = 'När dina knep inte längre fungerar räddar pappas konstiga ljud situationen direkt. Vid kvällskriser, passa bollen till honom och se de glada skratten från sidan.', title_vi = 'Màn ảo thuật của bố 🤡', body_vi = 'Khi những chiêu của mẹ không còn hiệu quả, những âm thanh lạ của bố sẽ cứu nguy ngay lập tức. Khi bé quấy buổi tối, hãy "chuyền bóng" cho bố và ngồi xem những tràng cười vui vẻ.', title_zh = '魔术师爸爸的表演 🤡', body_zh = '你的办法都不管用时，爸爸的怪声音能马上挽救局面。晚上宝宝崩溃时，把球传给他，在一旁欣赏欢快的笑声吧。' WHERE id = 'c929f83e-5e59-4728-8c79-df0502607758' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de baño caliente 🛀', body_es = 'Después de correr todo el día, estáis agotados los dos. Durante el baño templado, pon de fondo sonidos relajantes de la naturaleza. La armonía del agua preparará para dormir hasta al niño más tozudo.', title_fr = 'Thérapie du bain chaud 🛀', body_fr = 'Après avoir couru toute la journée, vous êtes épuisés tous les deux. Pendant le bain tiède, mettez des sons de la nature apaisants en fond. L''harmonie de l''eau préparera au sommeil même l''enfant le plus têtu.', title_hi = 'गर्म पानी से नहाने वाली थेरेपी 🛀', body_hi = 'दिनभर भागदौड़ से वह भी थक गया और आप भी। गुनगुने पानी से नहलाते समय पीछे प्रकृति की शांत आवाज़ें चलाइए। पानी का यह सुकून सबसे ज़िद्दी बच्चे को भी नींद के लिए तैयार कर देगा।', title_id = 'Terapi mandi air hangat 🛀', body_id = 'Seharian berlarian, ia dan Anda sama-sama kelelahan. Saat mandi air hangat, putar suara alam yang menenangkan di latar belakang. Harmoni air akan menyiapkan anak yang paling keras kepala sekalipun untuk tidur.', title_ja = '温かいお風呂のセラピー 🛀', body_ja = '一日じゅう走り回って、ふたりともへとへと。ぬるめのお風呂に入るとき、後ろで落ち着く自然の音を流しましょう。お水のハーモニーが、どんなにがんこな子も眠りへ導きます。', title_ko = '따뜻한 목욕 테라피 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤죠. 따뜻한 목욕을 할 때 잔잔한 자연의 소리를 틀어 주세요. 물의 조화가 가장 고집스러운 아이도 잠들 준비를 하게 해 줄 거예요.', title_nl = 'Therapie met een warm bad 🛀', body_nl = 'Jullie zijn allebei op van een hele dag rennen. Zet tijdens het lauwe bad rustgevende natuurgeluiden op de achtergrond aan. De harmonie van water maakt zelfs het koppigste kind klaar voor de slaap.', title_pl = 'Terapia ciepłą kąpielą 🛀', body_pl = 'Po całym dniu biegania oboje jesteście wykończeni. Podczas ciepłej kąpieli włącz w tle kojące odgłosy natury. Harmonia wody przygotuje do snu nawet najbardziej upartego malucha.', title_pt = 'Terapia do banho quente 🛀', body_pt = 'Depois de correrem o dia todo, estão os dois esgotados. Durante o banho morno, ponha sons calmantes da natureza em fundo. A harmonia da água vai preparar para o sono até a criança mais teimosa.', title_sv = 'Terapi med varmt bad 🛀', body_sv = 'Både du och barnet är helt slut efter en hel dag i farten. Sätt på lugnande naturljud i bakgrunden under det ljumma badet. Vattnets harmoni förbereder även det envisaste barnet för sömn.', title_vi = 'Liệu pháp tắm nước ấm 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều kiệt sức. Khi bé tắm nước ấm, hãy bật âm thanh thiên nhiên êm dịu phía sau. Sự hòa quyện của nước sẽ giúp cả đứa trẻ bướng bỉnh nhất sẵn sàng đi ngủ.', title_zh = '热水澡疗法 🛀', body_zh = '跑了一整天，宝宝和你都累坏了。洗温水澡时，在背景里放些舒缓的大自然声音。水的和谐连最倔的孩子都能带入睡眠准备。' WHERE id = '61f1a424-1da9-48ab-b336-92c9137ef39e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quiere servirse solo 💧', body_es = 'Se empeña en servirse él solo el agua en el vaso. Ten los trapos a mano y no rompas su independencia. Lo derramará, pero tras unos cuantos intentos te maravillará con qué cuidado llena el vaso.', title_fr = 'Il veut verser tout seul 💧', body_fr = 'Il veut absolument verser l''eau dans son verre tout seul. Préparez les serviettes et ne brisez pas son autonomie. Il en renversera, mais après quelques essais, vous serez émerveillée de voir avec quel soin il remplit son verre.', title_hi = 'खुद पानी डालना चाहता है 💧', body_hi = 'गिलास में पानी उसे खुद ही डालना है। पोंछने का कपड़ा तैयार रखिए, उसकी आत्मनिर्भरता मत तोड़िए। पानी गिराएगा, लेकिन कुछ कोशिशों के बाद आप देखकर हैरान रह जाएँगी कि वह कितनी सावधानी से गिलास भरता है।', title_id = 'Ingin menuang sendiri 💧', body_id = 'Ia bersikeras menuang air ke gelas sendiri. Siapkan lap, jangan patahkan kemandiriannya. Ia akan menumpahkannya, tetapi setelah beberapa kali mencoba Anda akan kagum betapa hati-hatinya ia mengisi gelas itu.', title_ja = '自分で注ぎたい 💧', body_ja = 'お水を自分でコップに注ぐと言い張りますか？ふきんを用意して、自立心をくじかないで。こぼすでしょうが、何回か挑戦するうちに、上手にコップを満たす姿に感心するはずです。', title_ko = '내가 따를래 💧', body_ko = '물은 꼭 자기가 컵에 따르겠다고 하나요? 행주를 준비하고 자립심을 꺾지 마세요. 흘리겠지만 몇 번 해 보고 나면 조심스럽게 컵을 채우는 모습에 감탄하게 될 거예요.', title_nl = 'Hij wil zelf inschenken 💧', body_nl = 'Hij moet en zal zelf water in zijn beker schenken. Leg de doekjes klaar en breek zijn zelfstandigheid niet. Hij zal morsen, maar na een paar pogingen sta je versteld hoe voorzichtig hij die beker vult.', title_pl = 'Chce nalać sam 💧', body_pl = 'Wodę do kubka koniecznie musi nalać sam. Przygotuj ściereczki i nie łam jego samodzielności. Rozleje, ale po kilku próbach będziesz zachwycona, jak ostrożnie napełnia kubek.', title_pt = 'Quer servir sozinho 💧', body_pt = 'Faz questão de deitar ele próprio a água no copo. Tenha os panos prontos e não quebre a independência dele. Vai entornar, mas depois de algumas tentativas vai ficar encantada com o cuidado com que enche o copo.', title_sv = 'Barnet vill hälla upp själv 💧', body_sv = 'Barnet måste absolut hälla upp vattnet i muggen själv. Ta fram trasorna och knäck inte självständigheten. Det kommer att spillas, men efter några försök blir du förundrad över hur försiktigt hen fyller muggen.', title_vi = 'Bé muốn tự rót 💧', body_vi = 'Bé nhất định phải tự rót nước vào cốc. Hãy chuẩn bị khăn lau, đừng làm tổn thương sự tự lập của bé. Bé sẽ làm đổ, nhưng sau vài lần thử, mẹ sẽ ngạc nhiên khi thấy bé rót đầy cốc cẩn thận thế nào.', title_zh = '想自己倒水 💧', body_zh = '一定要自己往杯子里倒水。准备好抹布，别打击宝宝的独立性。会洒出来，但试过几次后，你会惊叹宝宝能那么小心地把杯子倒满。' WHERE id = '8ae2c146-2d4a-4919-80fe-7f15c41cdc0e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sensación de agotamiento 🔋', body_es = '¿Sientes que no llegas? ¿Crees que no puedes con todo? Mira las publicaciones de la Comunidad: no estás sola ni eres insuficiente. Eres el mundo de tu peque.', title_fr = 'Sensation d''épuisement 🔋', body_fr = 'Vous ne vous sentez pas à la hauteur ? Vous pensez ne pas réussir à tout gérer ? Regardez les publications de la Communauté, vous n''êtes ni seule ni insuffisante. Vous êtes le monde de cet enfant.', title_hi = 'थक कर चूर होने का एहसास 🔋', body_hi = 'खुद को कम महसूस करती हैं? लगता है आप सब कुछ नहीं संभाल पातीं? कम्युनिटी की पोस्ट देखिए, आप न अकेली हैं और न कम। आप इस बच्चे की पूरी दुनिया हैं।', title_id = 'Rasa habis tenaga 🔋', body_id = 'Merasa tidak cukup baik? Merasa tidak sanggup menangani semuanya? Lihat unggahan di Komunitas, Anda tidak sendirian dan bukan ibu yang kurang. Anda adalah dunia bagi anak ini.', title_ja = '燃えつきそうな気持ち 🔋', body_ja = '自分は足りないと感じていますか？すべてをこなせないと思っていますか？コミュニティの投稿を見てみましょう。あなたはひとりでも、力不足でもありません。あなたはこの子の世界そのものです。', title_ko = '번아웃 🔋', body_ko = '내가 부족한 엄마 같나요? 모든 걸 감당할 수 없다고 느끼나요? 커뮤니티의 글을 보세요. 엄마는 혼자도, 부족하지도 않아요. 엄마는 이 아이의 세상이에요.', title_nl = 'Opgebrand gevoel 🔋', body_nl = 'Voel je je tekortschieten? Denk je dat je niet alles aankunt? Kijk naar de berichten in de Community: je bent niet alleen en je schiet niet tekort. Jij bent de wereld van dit kind.', title_pl = 'Poczucie wyczerpania 🔋', body_pl = 'Czujesz, że nie dajesz rady? Myślisz, że ze wszystkim sobie nie radzisz? Zajrzyj do postów w Społeczności, nie jesteś sama ani niewystarczająca. Jesteś światem tego dziecka.', title_pt = 'Sensação de esgotamento 🔋', body_pt = 'Sente que não chega? Acha que não consegue dar conta de tudo? Veja as publicações da Comunidade: não está sozinha e não é insuficiente. É o mundo desta criança.', title_sv = 'Känslan av att vara utbränd 🔋', body_sv = 'Känner du dig otillräcklig? Tror du att du inte klarar allt? Titta på inläggen i Community, du är varken ensam eller otillräcklig. Du är hela världen för det här barnet.', title_vi = 'Cảm giác kiệt sức 🔋', body_vi = 'Mẹ thấy mình chưa đủ tốt? Nghĩ rằng mình không thể lo hết mọi việc? Hãy xem các bài đăng trong Cộng đồng, mẹ không đơn độc và cũng không hề kém cỏi. Mẹ là cả thế giới của bé.', title_zh = '身心耗尽的感觉 🔋', body_zh = '觉得自己做得不够好？觉得什么都应付不过来？看看社区里的帖子，你并不孤单，也没有不够好。你就是这个孩子的全世界。' WHERE id = 'c8458955-5810-4609-a23d-82b155bf6112' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gramática curiosa 🗣️', body_es = 'Hace descubrimientos gramaticales totalmente nuevos y propios, como «Yo sabo» o «Él se iba vino». No le corrijas con dureza: simplemente respóndele repitiendo la frase correcta.', title_fr = 'Une grammaire bien à lui 🗣️', body_fr = '« J''ai faimé », « Il est allé-venu » : il fait des découvertes grammaticales toutes nouvelles et bien à lui. Ne le corrigez pas sèchement, répondez simplement en répétant la phrase correcte.', title_hi = 'अनोखा व्याकरण 🗣️', body_hi = '''मैं भूखा हो गयी था'', ''वह गया आया'' जैसे पूरी तरह नए, अपने ही व्याकरण के प्रयोग करता है? उसे सख्ती से मत टोकिए, बस सही वाक्य दोहराकर जवाब दीजिए।', title_id = 'Tata bahasa yang unik 🗣️', body_id = 'Ia membuat penemuan tata bahasa yang sepenuhnya baru dan khas, seperti ''Aku laparan'' atau ''Dia pergi datang''. Jangan mengoreksinya dengan keras, cukup jawab dengan mengulang kalimat yang benar.', title_ja = 'ふしぎな文法 🗣️', body_ja = '「おなかすいたった」「行ってきたきた」のように、まったく新しい自分なりの文法を発見していますか？きびしく直さず、正しい文をくり返して答えてあげましょう。', title_ko = '독특한 문법 🗣️', body_ko = '''나 배고프었어'', ''걔가 가고 왔어''처럼 완전히 새로운 자기만의 문법을 만들어 내나요? 엄하게 고치지 말고 바른 문장으로 다시 말해 주며 대답해 주세요.', title_nl = 'Vreemde grammatica 🗣️', body_nl = 'Met zinnen als ''Ik heb gehongerd'' of ''Hij ging-kwam'' ontdekt hij een gloednieuwe, eigen grammatica. Verbeter hem niet streng, maar antwoord gewoon door de juiste zin te herhalen.', title_pl = 'Dziwna gramatyka 🗣️', body_pl = '„Ja głodniałem”, „On szedł przyszedł”: odkrywa zupełnie nową, własną gramatykę. Nie poprawiaj go surowo, po prostu odpowiedz, powtarzając poprawne zdanie.', title_pt = 'Gramática curiosa 🗣️', body_pt = 'Faz descobertas gramaticais totalmente novas e muito suas, como "eu fazi" ou "ele foi veio". Não o corrija de forma dura; responda simplesmente repetindo a frase certa.', title_sv = 'Konstig grammatik 🗣️', body_sv = 'Barnet gör helt nya, egna grammatiska upptäckter som ”Jag hungrade” och ”Han gådde kom”. Rätta inte strängt, svara bara genom att upprepa meningen på rätt sätt.', title_vi = 'Ngữ pháp kỳ lạ 🗣️', body_vi = 'Bé tạo ra những "phát minh" ngữ pháp hoàn toàn mới, rất riêng kiểu "Con đói rồi đã", "Bạn ấy đi đến về". Đừng sửa bé một cách gay gắt, chỉ cần đáp lại bằng cách nhắc lại câu nói đúng.', title_zh = '奇怪的语法 🗣️', body_zh = '“我饿饿了”“他去走来了”，宝宝在发现全新的、自成一派的语法。别严厉纠正，只要用正确的句子重复一遍来回应就好。' WHERE id = '87267db7-ab44-41b2-82ed-1d12fea90f71' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Consejo de Anacan AI 🤖', body_es = '¿Tienes dudas sobre cómo socializa tu peque con otros niños en el parque? No te pierdas horas en internet: pregunta a Anacan AI y recibe al momento consejos adaptados a su desarrollo y avalados por pediatras.', title_fr = 'Le conseil d''Anacan AI 🤖', body_fr = 'Vous vous posez des questions sur sa façon de sociabiliser avec les autres enfants au parc ? Ne vous perdez pas des heures sur Internet, posez la question à Anacan AI et recevez tout de suite un conseil adapté à son développement et validé par des pédiatres.', title_hi = 'Anacan AI की सलाह 🤖', body_hi = 'पार्क में बच्चे के दूसरे बच्चों से घुलने-मिलने को लेकर सवाल है? घंटों इंटरनेट पर मत खोइए, Anacan AI से पूछिए और तुरंत विकास के अनुसार, बाल रोग विशेषज्ञों से पुष्ट सलाह पाइए।', title_id = 'Saran Anacan AI 🤖', body_id = 'Punya pertanyaan tentang cara anak bersosialisasi dengan anak lain di taman? Jangan tersesat berjam-jam di internet, tanyakan pada Anacan AI dan langsung dapatkan saran yang sesuai perkembangannya dan disetujui dokter anak.', title_ja = 'Anacan AIのアドバイス 🤖', body_ja = '公園でほかの子とどう関わるかについて質問がありますか？何時間もネットで迷わずにAnacan AIに聞けば、すぐに発達に合った小児科医監修のアドバイスがもらえます。', title_ko = 'Anacan AI의 조언 🤖', body_ko = '아이가 공원에서 다른 아이들과 어울리는 게 궁금한가요? 인터넷에서 몇 시간씩 헤매지 말고 Anacan AI에게 물어 발달에 맞는 소아과 검증 조언을 바로 받아 보세요.', title_nl = 'Tip van Anacan AI 🤖', body_nl = 'Heb je een vraag over hoe hij in het park met andere kinderen omgaat? Verdwaal niet urenlang op internet, vraag het Anacan AI en krijg meteen advies dat past bij zijn ontwikkeling en door kinderartsen is goedgekeurd.', title_pl = 'Rada od Anacan AI 🤖', body_pl = 'Masz pytanie o to, jak dziecko nawiązuje kontakty z innymi dziećmi w parku? Nie gub się godzinami w internecie, zapytaj Anacan AI i od razu otrzymaj zatwierdzoną przez pediatrów radę dopasowaną do etapu rozwoju.', title_pt = 'Conselho do Anacan AI 🤖', body_pt = 'Tem dúvidas sobre a forma como ele convive com outras crianças no parque? Não se perca horas na internet: pergunte ao Anacan AI e receba logo conselhos adequados ao desenvolvimento e aprovados por pediatras.', title_sv = 'Råd från Anacan AI 🤖', body_sv = 'Har du en fråga om hur barnet umgås med andra barn i parken? Gå inte vilse på nätet i timmar, fråga Anacan AI och få direkt råd som passar utvecklingen och är godkända av barnläkare.', title_vi = 'Lời khuyên từ Anacan AI 🤖', body_vi = 'Mẹ có câu hỏi về việc bé hòa nhập với các bạn ở công viên? Đừng lạc hàng giờ trên mạng, hãy hỏi Anacan AI để nhận ngay lời khuyên phù hợp với sự phát triển và được bác sĩ nhi khoa xác nhận.', title_zh = 'Anacan AI的建议 🤖', body_zh = '对孩子在公园里和其他小朋友社交有疑问？别在网上花好几个小时找答案，交给Anacan AI，马上获得符合发育阶段、经儿科医生认可的建议。' WHERE id = '9a6f7d87-06ae-42b3-a4d0-b7eff2923976' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Alerta de terror nocturno 😭', body_es = 'Si llora de repente o grita con los ojos cerrados, compruébalo con el Análisis del llanto. Si es un terror nocturno, no intentes despertarle: solo quédate a su lado y dale seguridad en silencio.', title_fr = 'Alerte terreur nocturne 😭', body_fr = 'S''il pleure soudain ou crie les yeux fermés, vérifiez avec l''Analyse des pleurs. S''il s''agit d''une terreur nocturne, n''essayez pas de le réveiller : restez simplement près de lui et rassurez-le en silence.', title_hi = 'नाइट टेरर की चेतावनी 😭', body_hi = 'अगर अचानक रोए और आँखें बंद किए चीखे, तो क्राइंग एनालिसिस से जाँचिए। अगर नाइट टेरर है, तो उसे जगाने की कोशिश किए बिना बस पास रहिए और चुपचाप भरोसा दीजिए।', title_id = 'Waspada teror malam 😭', body_id = 'Jika ia tiba-tiba menangis atau berteriak dengan mata terpejam, periksa dengan Analisis Tangisan. Jika ini teror malam, jangan mencoba membangunkannya, cukup berada di sisinya dan beri rasa aman tanpa suara.', title_ja = '夜驚症のサイン 😭', body_ja = '急に泣いたり、目を閉じたまま叫んだりしたら、「泣き声分析」で確認しましょう。夜驚症なら起こそうとせず、ただそばにいて静かに安心させてあげて。', title_ko = '야경증 주의 😭', body_ko = '갑자기 울거나 눈을 감은 채 소리를 지르면 울음 분석으로 확인해 보세요. 야경증이라면 깨우려 하지 말고 곁에 있어 주며 조용히 안심시켜 주세요.', title_nl = 'Waarschuwing voor nachtangst 😭', body_nl = 'Huilt hij plotseling of schreeuwt hij met gesloten ogen? Check het met Huilanalyse. Is het nachtangst, probeer hem dan niet wakker te maken, maar blijf gewoon bij hem en geef hem in stilte vertrouwen.', title_pl = 'Uwaga na lęk nocny 😭', body_pl = 'Jeśli nagle płacze i krzyczy z zamkniętymi oczami, sprawdź to w Analizie płaczu. Jeśli to lęk nocny, nie próbuj go budzić, po prostu bądź obok i w ciszy daj mu poczucie bezpieczeństwa.', title_pt = 'Alerta de terror noturno 😭', body_pt = 'Se chorar de repente ou gritar de olhos fechados, verifique com a Análise do Choro. Se for terror noturno, não tente acordá-lo: fique apenas ao lado dele e dê-lhe segurança em silêncio.', title_sv = 'Varning för nattskräck 😭', body_sv = 'Om barnet plötsligt gråter och skriker med slutna ögon, kolla med Gråtanalys. Om det är nattskräck, försök inte väcka barnet, var bara där och ge trygghet i tystnad.', title_vi = 'Cảnh báo hoảng sợ ban đêm 😭', body_vi = 'Nếu bé bỗng khóc, hét lên khi mắt nhắm nghiền, hãy kiểm tra bằng Phân tích tiếng khóc. Nếu là hoảng sợ ban đêm, đừng cố đánh thức bé, chỉ cần ở bên và lặng lẽ trấn an bé.', title_zh = '夜惊提醒 😭', body_zh = '如果突然哭起来、闭着眼睛尖叫，就用哭声分析看看。如果是夜惊，别试图叫醒宝宝，只要陪在身边，安静地给宝宝安全感。' WHERE id = 'a3b7ecf2-9668-46df-b331-9c7487819a32' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Historias imaginarias 🧸', body_es = '¿Le cuenta cuentos a su osito o bebe té de un vaso vacío? El juego simbólico es una obra maestra del desarrollo. No le interrumpas y observa desde fuera a este pequeño director.', title_fr = 'Scénarios imaginaires 🧸', body_fr = 'Il raconte une histoire à son nounours ou boit du thé dans une tasse vide ? Le jeu symbolique est un chef-d''œuvre du développement. Ne l''interrompez pas, observez de loin ce petit metteur en scène.', title_hi = 'काल्पनिक कहानियाँ 🧸', body_hi = 'टेडी बियर को कहानी सुनाता है या खाली कप से चाय पीता है? प्रतीकात्मक खेल विकास का बेहतरीन नमूना है। उसे मत रोकिए, इस नन्हे निर्देशक को दूर से देखिए।', title_id = 'Skenario khayalan 🧸', body_id = 'Ia mendongeng untuk boneka beruangnya atau minum teh dari cangkir kosong? Permainan simbolis adalah karya agung perkembangan. Jangan ganggu, saksikan sutradara kecil ini dari jauh.', title_ja = '空想のシナリオ 🧸', body_ja = 'くまのぬいぐるみにお話をしたり、からっぽのコップでお茶を飲んだりしていますか？ごっこ遊びは発達の傑作です。じゃまをせず、この小さな監督さんを少し離れて見守りましょう。', title_ko = '상상 속 시나리오 🧸', body_ko = '곰 인형에게 이야기를 들려주거나 빈 컵으로 차를 마시나요? 상징 놀이는 발달의 걸작이에요. 방해하지 말고 이 꼬마 감독을 멀리서 지켜보세요.', title_nl = 'Verzonnen scenario''s 🧸', body_nl = 'Vertelt hij zijn knuffelbeer een verhaaltje of drinkt hij thee uit een leeg kopje? Symbolisch spel is een meesterwerk van de ontwikkeling. Stoor hem niet en kijk van een afstandje naar deze kleine regisseur.', title_pl = 'Wyimaginowane scenariusze 🧸', body_pl = 'Opowiada misiowi bajki albo pije herbatę z pustego kubeczka? Zabawa symboliczna to arcydzieło rozwoju. Nie przeszkadzaj, obserwuj z boku tego małego reżysera.', title_pt = 'Cenários imaginários 🧸', body_pt = 'Conta histórias ao ursinho ou bebe chá de uma chávena vazia? O jogo simbólico é uma obra-prima do desenvolvimento. Não o interrompa e observe à distância este pequeno realizador.', title_sv = 'Låtsasscenarier 🧸', body_sv = 'Berättar barnet sagor för nallen eller dricker te ur en tom kopp? Symbolisk lek är utvecklingens mästerverk. Avbryt inte, titta på den lilla regissören på avstånd.', title_vi = 'Những kịch bản tưởng tượng 🧸', body_vi = 'Bé kể chuyện cho gấu bông hay uống trà từ chiếc cốc rỗng? Trò chơi biểu tượng là kiệt tác của sự phát triển. Đừng ngăn bé, hãy quan sát "đạo diễn" nhí này từ xa.', title_zh = '想象中的剧情 🧸', body_zh = '给玩具熊讲故事，或者用空杯子“喝茶”？象征性游戏是发育的杰作。别打扰，在一旁看着这位小导演吧。' WHERE id = 'b69e774e-9d7b-4da5-9fb4-5b192b81f712' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba los decibelios con el Medidor de sonido y ajusta el volumen de la tele de la habitación de al lado.', body_fr = 'La première demi-heure de sommeil est la plus fragile. Vérifiez le niveau de décibels avec le Sonomètre et réglez le volume de la télé dans la pièce d''à côté.', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक होता है। साउंड मीटर से माहौल का डेसिबल जाँचिए और बगल के कमरे में टीवी की आवाज़ उसी हिसाब से रखिए।', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Periksa desibel ruangan dengan Pengukur Suara dan sesuaikan volume TV di kamar sebelah.', body_ja = '寝ついてから最初の30分がいちばん眠りが浅い時間です。「サウンドメーター」で周りのデシベルを確かめ、となりの部屋のテレビの音量を調整しましょう。', body_ko = '잠든 후 첫 30분이 가장 예민한 시간이에요. 소음 측정기로 데시벨을 확인하고 옆방 TV 소리를 맞춰 조절하세요.', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Meet het decibelniveau met de Geluidsmeter en stem het volume van de tv in de kamer ernaast daarop af.', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź Miernikiem dźwięku poziom decybeli i dostosuj głośność telewizora w sąsiednim pokoju.', body_pt = 'A primeira meia hora depois de adormecer é o momento mais sensível. Verifique os decibéis com o Medidor de Som e ajuste o volume da televisão no quarto ao lado.', body_sv = 'Den första halvtimmen efter insomnandet är den känsligaste tiden. Kontrollera ljudnivån i decibel med Ljudmätaren och anpassa ljudet från tv:n i rummet bredvid.', body_vi = 'Nửa giờ đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra decibel bằng Đo âm thanh và điều chỉnh tiếng TV ở phòng bên cạnh.', body_zh = '入睡后的头半小时最敏感。用分贝仪检查环境分贝，把隔壁房间电视的音量调到合适。' WHERE id = 'c131d97d-34fe-4f0d-ab19-20860829451c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Socializar en el parque 🌳', body_es = '¿Más que jugar con otros niños, juega a lo suyo a su lado? El juego paralelo es totalmente normal a esta edad. Consulta Tiempo y ropa y llévale al parque.', title_fr = 'Rencontres au parc 🌳', body_fr = 'Il joue à côté des autres enfants plutôt qu''avec eux ? Le jeu parallèle est tout à fait naturel à cet âge. Consultez Météo et tenue et emmenez-le au parc.', title_hi = 'पार्क में मेलजोल 🌳', body_hi = 'दूसरे बच्चों के साथ खेलने से ज़्यादा उनके पास अपना खेल खेलता है? इस उम्र में पैरेलल प्ले बिल्कुल स्वाभाविक है। मौसम और कपड़े टूल देखकर उसे पार्क ले जाइए।', title_id = 'Bergaul di taman 🌳', body_id = 'Ia lebih sering memainkan permainannya sendiri di dekat anak lain daripada bermain bersama mereka? Bermain paralel sangat wajar di usia ini. Perhatikan cuaca dan pakaiannya, lalu ajak ia ke taman.', title_ja = '公園でのふれあい 🌳', body_ja = 'ほかの子と一緒に遊ぶより、そばで自分の遊びをしていますか？「平行遊び」はこの年齢ではまったく自然なことです。「天気と服装」を確認して、公園に連れていきましょう。', title_ko = '공원에서의 어울림 🌳', body_ko = '다른 아이들과 함께 놀기보다 옆에서 자기 놀이를 하나요? 이 나이엔 평행 놀이가 아주 자연스러워요. 날씨와 옷차림을 확인하고 공원에 데려가 주세요.', title_nl = 'Contact in het park 🌳', body_nl = 'Speelt hij liever zijn eigen spel naast andere kinderen dan met hen? Parallel spel is op deze leeftijd heel normaal. Kijk in Weer en kleding en neem hem mee naar het park.', title_pl = 'Kontakty w parku 🌳', body_pl = 'Zamiast bawić się z innymi dziećmi, bawi się obok nich po swojemu? Zabawa równoległa jest w tym wieku zupełnie naturalna. Sprawdź Pogodę i ubiór i wyjdźcie do parku.', title_pt = 'Convívio no parque 🌳', body_pt = 'Brinca ao lado das outras crianças, mais do que com elas? O jogo paralelo é perfeitamente natural nesta idade. Veja o Tempo e Roupa e leve-o ao parque.', title_sv = 'Umgänge i parken 🌳', body_sv = 'Leker barnet hellre sin egen lek bredvid andra barn än tillsammans med dem? Parallellek är helt naturligt i den här åldern. Kolla Väder och kläder och gå till parken.', title_vi = 'Giao tiếp ở công viên 🌳', body_vi = 'Bé chơi trò của riêng mình bên cạnh các bạn hơn là chơi cùng? Chơi song song hoàn toàn tự nhiên ở tuổi này. Hãy xem thời tiết và trang phục rồi đưa bé ra công viên.', title_zh = '公园社交 🌳', body_zh = '比起和其他孩子一起玩，更喜欢在他们旁边玩自己的？平行游戏在这个年龄完全正常。看看天气穿衣工具，带宝宝去公园吧。' WHERE id = 'e0133a48-f7ee-4d9e-9e82-8b0c0ba8095b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hay retrocesos al dejar el pañal (potty training)? No te agobies: pregunta a Anacan AI cómo resolver este proceso psicológico.', body_fr = 'L''apprentissage du pot fait marche arrière ? Ne vous épuisez pas, demandez à Anacan AI comment surmonter ce processus psychologique.', body_hi = 'पॉटी ट्रेनिंग (potty training) में पीछे जा रहा है? खुद को मत थकाइए, इस मनोवैज्ञानिक प्रक्रिया के हल Anacan AI से पूछिए।', body_id = 'Mengalami kemunduran dalam latihan pispot (potty training)? Jangan memaksakan diri, tanyakan pada Anacan AI cara mengatasi proses psikologis ini.', body_ja = 'トイレトレーニングで後戻りしていますか？自分を追いつめないで、この心の成長のプロセスの乗りこえ方をAnacan AIに聞いてみましょう。', body_ko = '배변 훈련에서 뒷걸음질이 생겼나요? 혼자 애쓰지 말고 이 심리적인 과정을 해결하는 방법을 Anacan AI에게 물어보세요.', body_nl = 'Gaat het met de zindelijkheidstraining weer achteruit? Put jezelf niet uit, maar vraag Anacan AI hoe je dit psychologische proces aanpakt.', body_pl = 'Masz regres w nauce korzystania z nocnika (potty training)? Nie męcz się, zapytaj Anacan AI o sposoby poradzenia sobie z tym psychologicznym procesem.', body_pt = 'Está a ter recuos no treino do bacio (potty training)? Não se desgaste: pergunte ao Anacan AI como resolver este processo psicológico.', body_sv = 'Går pottträningen (potty training) bakåt? Slit inte ut dig, fråga Anacan AI om lösningar på den här psykologiska processen.', body_vi = 'Việc tập ngồi bô (potty training) đang bị thụt lùi? Đừng tự làm mình mệt mỏi, hãy hỏi Anacan AI cách vượt qua quá trình tâm lý này.', body_zh = '如厕训练出现倒退？别把自己累坏，问问Anacan AI这个心理过程该怎么应对。' WHERE id = '88b776b7-0d43-49f1-b31c-da27294feb6f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El tiempo vuela!', body_es = 'Mira atrás y fíjate en todo lo que has aprendido. Este pequeño abogado ya puede negociar contigo sobre cualquier tema. Siéntete orgullosa de tu peque y de ti.', title_fr = 'Le temps file !', body_fr = 'Regardez en arrière et voyez tout ce que vous avez appris. Ce petit avocat sait déjà négocier avec vous sur tous les sujets. Soyez fière de lui et de vous.', title_hi = 'समय उड़ रहा है!', body_hi = 'पीछे मुड़कर देखिए कि आपने कितना कुछ सीखा है। यह नन्हा वकील अब आपसे हर विषय पर मोलभाव कर सकता है। उस पर और खुद पर गर्व कीजिए।', title_id = 'Waktu terbang begitu cepat!', body_id = 'Lihat ke belakang dan sadari betapa banyak yang telah Anda pelajari. Pengacara kecil ini kini sudah bisa tawar-menawar dengan Anda soal apa saja. Banggalah padanya dan pada diri Anda.', title_ja = '時間はあっという間！', body_ja = '振り返って、どれだけたくさんのことを学んできたか見てみましょう。この小さな弁護士さんは、もうどんな話題でもあなたと交渉できます。お子さんと自分を誇りに思いましょう。', title_ko = '시간이 정말 빨라요!', body_ko = '돌아보면 얼마나 많은 걸 배웠는지 보이죠. 이 꼬마 변호사는 이제 어떤 주제로든 엄마와 협상할 수 있어요. 아이도, 엄마 자신도 자랑스러워하세요.', title_nl = 'De tijd vliegt!', body_nl = 'Kijk terug en zie hoeveel je hebt geleerd. Deze kleine advocaat kan nu al over elk onderwerp met je onderhandelen. Wees trots op hem en op jezelf.', title_pl = 'Czas leci!', body_pl = 'Spójrz wstecz i zobacz, jak wiele się nauczyłaś. Ten mały adwokat potrafi już targować się z tobą na każdy temat. Bądź dumna z niego i z siebie.', title_pt = 'O tempo voa!', body_pt = 'Olhe para trás e veja o quanto aprendeu. Este pequeno advogado já negoceia consigo sobre qualquer assunto. Tenha orgulho nele e em si.', title_sv = 'Tiden flyger!', body_sv = 'Blicka tillbaka och se hur mycket ni har lärt er. Den lilla advokaten kan redan förhandla med dig om allt. Var stolt över barnet och dig själv.', title_vi = 'Thời gian trôi nhanh quá!', body_vi = 'Hãy nhìn lại xem mẹ đã học được bao nhiêu điều. "Luật sư" nhỏ này giờ đã có thể mặc cả với mẹ về mọi chủ đề. Hãy tự hào về bé và về chính mình.', title_zh = '时间飞逝！', body_zh = '回头看看，你们一起学会了多少东西。这位小律师已经能在任何话题上和你讨价还价了。为宝宝，也为自己骄傲吧。' WHERE id = '181a440f-5684-4f29-a861-16adef184628' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Los libros clásicos os aburren a los dos. En Cuentos inteligentes conviértele en astronauta y llévale a las estrellas o bajadle a las profundidades del mar. Da rienda suelta a su imaginación antes de dormir.', body_fr = 'Vous en avez assez tous les deux des livres classiques. Dans les Contes intelligents, faites-en un astronaute qui s''envole vers les étoiles ou qui plonge au fond des mers. Avant de dormir, laissez libre cours à son imagination.', body_hi = 'पुरानी किताबों से आप दोनों ऊब गए हैं? स्मार्ट कहानियों में उसे अंतरिक्ष यात्री बनाकर तारों तक उड़ाइए या गहरे समंदर में उतारिए। सोने से पहले उसकी कल्पना को खुला छोड़ दीजिए।', body_id = 'Kalian berdua bosan dengan buku klasik. Di Dongeng Pintar, jadikan ia astronaut yang terbang ke bintang-bintang atau selami lautan dalam. Bebaskan imajinasinya sebelum tidur.', body_ja = 'いつもの絵本にふたりともあきてしまった？「スマートおはなし」で、お子さんを宇宙飛行士にして星へ飛ばしたり、深い海へもぐらせたりしましょう。寝る前に想像力を自由に羽ばたかせて。', body_ko = '늘 읽던 책이 둘 다 지겨워졌나요? 스마트 동화에서 아이를 우주 비행사로 만들어 별로 날려 보내거나 깊은 바다로 데려가 보세요. 잠들기 전 상상력을 마음껏 펼치게 해 주세요.', body_nl = 'Zijn jullie allebei de klassieke boekjes beu? Maak hem in Slimme sprookjes een astronaut die naar de sterren vliegt of laat hem afdalen in de diepe zee. Laat zijn fantasie voor het slapengaan de vrije loop.', body_pl = 'Oboje macie dość klasycznych książek. W Mądrych bajkach zrób z niego kosmonautę i wyślij go do gwiazd albo w głębiny morza. Daj jego wyobraźni swobodę przed snem.', body_pt = 'Estão os dois fartos dos livros clássicos. Nas Histórias Inteligentes, faça dele um astronauta e voem até às estrelas, ou mergulhem no fundo do mar. Antes de dormir, dê asas à imaginação.', body_sv = 'Ni är båda trötta på klassiska böcker. Gör barnet till astronaut och låt hen flyga till stjärnorna eller dyka ner i djupa hav i Smarta sagor. Släpp fantasin fri före läggdags.', body_vi = 'Cả hai mẹ con đều chán những cuốn sách kinh điển? Trong Truyện cổ tích thông minh, hãy biến bé thành phi hành gia bay đến các vì sao hoặc lặn xuống biển sâu. Hãy để trí tưởng tượng tự do bay bổng trước giờ ngủ.', body_zh = '你们俩都读腻了经典故事书？在智能故事里让宝宝当宇航员飞向星星，或者潜入深海。在睡前尽情释放想象力吧。' WHERE id = '31d8e844-a068-4aa5-8b2c-23a9d11616c4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de calma es imprescindible ☕', body_es = 'Si se niega en redondo a dormir la siesta, no le obligues. Pero establece 30 minutos de hora de calma (quiet time). Que se quede solo en la cama con sus libros mientras tú respiras en la habitación.', title_fr = 'Le temps calme est indispensable ☕', body_fr = 'S''il refuse catégoriquement la sieste, ne le forcez pas. Instaurez plutôt 30 minutes de « temps calme ». Il reste seul dans son lit avec des livres, et vous, vous respirez dans la pièce.', title_hi = 'शांत समय ज़रूरी है ☕', body_hi = 'अगर दिन की नींद से साफ़ मना करता है, तो ज़बरदस्ती मत कीजिए। लेकिन 30 मिनट का ''शांत समय'' (quiet time) तय कीजिए। वह बिस्तर पर किताबों के साथ अकेला रहे, और आप कमरे में चैन की साँस लीजिए।', title_id = 'Jam tenang itu wajib ☕', body_id = 'Jika ia sama sekali menolak tidur siang, jangan paksa. Namun tetapkan 30 menit ''waktu tenang'' (quiet time). Biarkan ia sendiri di tempat tidur dengan buku-bukunya, dan Anda bisa bernapas lega.', title_ja = '「静かな時間」は欠かせない ☕', body_ja = 'お昼寝をきっぱり拒否するなら、無理強いしないで。でも30分の「静かな時間」は決めましょう。お子さんはベッドで絵本とひとりで過ごし、あなたは部屋でひと息ついて。', title_ko = '조용한 시간은 꼭 필요해요 ☕', body_ko = '낮잠을 단호히 거부한다면 억지로 재우지 마세요. 대신 30분의 ''조용한 시간''을 정해 보세요. 아이는 침대에서 책과 함께 있고, 엄마는 방에서 숨을 돌리세요.', title_nl = 'Een rustuurtje is een must ☕', body_nl = 'Weigert hij resoluut een middagslaapje? Dwing hem niet. Maar plan wel een rustuurtje van 30 minuten. Laat hem alleen met zijn boekjes in bed blijven, en haal jij in de kamer even adem.', title_pl = 'Godzina wyciszenia to konieczność ☕', body_pl = 'Jeśli stanowczo odmawia drzemki, nie zmuszaj go. Ale wyznacz 30-minutową godzinę wyciszenia (quiet time). Niech zostanie sam w łóżku z książeczkami, a ty złap oddech w pokoju.', title_pt = 'A hora do sossego é obrigatória ☕', body_pt = 'Se recusa de vez a sesta, não o obrigue. Mas defina 30 minutos de sossego (quiet time). Ele fica na cama sozinho com os livros e a mãe respira no quarto.', title_sv = 'Lugn stund är ett måste ☕', body_sv = 'Om barnet helt vägrar dagsömn, tvinga inte. Men inför en 30 minuters Lugn stund (quiet time). Låt barnet vara ensamt med böckerna i sängen medan du andas ut i rummet.', title_vi = 'Giờ yên tĩnh là bắt buộc ☕', body_vi = 'Nếu bé nhất quyết không ngủ ngày, đừng ép bé. Nhưng hãy đặt 30 phút "Giờ yên tĩnh" (quiet time). Bé ở một mình trên giường với sách, còn mẹ được thở trong phòng.', title_zh = '一定要有安静时间 ☕', body_zh = '如果坚决不肯睡午觉，别强迫。但要定一个30分钟的“安静时间”。让宝宝和书一起待在床上，你也在房间里喘口气。' WHERE id = '4280853d-50c1-4092-8d31-3279f5e3d68a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diario de ánimo 📝', body_es = 'Coge el móvil. En lugar de deslizar por las redes sociales, abre el Diario de ánimo y guarda para el futuro el momento más gracioso de hoy, el que más te ha hecho reír.', title_fr = 'Journal d''humeur 📝', body_fr = 'Prenez votre téléphone. Au lieu de faire défiler les réseaux sociaux, ouvrez le Journal d''humeur et notez pour plus tard le moment le plus drôle de sa journée, celui qui vous a le plus fait rire.', title_hi = 'मूड डायरी 📝', body_hi = 'फ़ोन हाथ में लीजिए। सोशल मीडिया स्क्रॉल करने के बजाय मूड डायरी खोलिए और आज के उसके सबसे मज़ेदार, आपको सबसे ज़्यादा हँसाने वाले पल को आगे के लिए दर्ज कीजिए।', title_id = 'Buku Harian Suasana Hati 📝', body_id = 'Ambil ponsel Anda. Daripada menggulir media sosial, buka Buku Harian Suasana Hati dan catat momen paling lucu yang ia lakukan hari ini, yang paling membuat Anda tertawa, untuk masa depan.', title_ja = '気分日記 📝', body_ja = 'スマホを手に取って。SNSをスクロールするかわりに「気分日記」を開いて、今日お子さんがしたいちばんおもしろくて笑った瞬間を、未来のために記録しましょう。', title_ko = '기분 일기 📝', body_ko = '휴대폰을 들어 보세요. SNS를 넘기는 대신 기분 일기를 열고 오늘 아이가 한 가장 웃기고 나를 가장 많이 웃게 한 순간을 나중을 위해 적어 두세요.', title_nl = 'Stemmingsdagboek 📝', body_nl = 'Pak je telefoon. Scroll niet door sociale media, maar open je Stemmingsdagboek en leg het grappigste moment van vandaag, waarom je het hardst moest lachen, vast voor later.', title_pl = 'Dziennik nastroju 📝', body_pl = 'Weź telefon do ręki. Zamiast przewijać media społecznościowe, otwórz Dziennik nastroju i zapisz na przyszłość najzabawniejszą chwilę, którą dziś zafundował, tę, która najbardziej cię rozśmieszyła.', title_pt = 'Diário de Humor 📝', body_pt = 'Pegue no telemóvel. Em vez de andar a deslizar nas redes sociais, abra o Diário de Humor e registe para o futuro o momento mais cómico que ele fez hoje, o que mais a fez rir.', title_sv = 'Humördagboken 📝', body_sv = 'Ta mobilen. I stället för att scrolla i sociala medier, öppna Humördagboken och anteckna för framtiden det roligaste barnet gjorde i dag, det som fick dig att skratta mest.', title_vi = 'Nhật ký tâm trạng 📝', body_vi = 'Hãy cầm điện thoại lên. Thay vì lướt mạng xã hội, hãy mở Nhật ký tâm trạng và ghi lại khoảnh khắc buồn cười nhất bé làm hôm nay để làm kỷ niệm cho tương lai.', title_zh = '心情日记 📝', body_zh = '拿起手机。别刷社交媒体了，打开心情日记，把宝宝今天最搞笑、最让你开怀大笑的时刻记下来，留给未来。' WHERE id = '10fd3d36-ea93-4f52-8bc2-486b88206869' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Operación verduras escondidas 🥦', body_es = '¿Aparta y tira las verduras de la sopa? No luches. Descubre en el Plan de alimentación las formas más originales e ingeniosas de hacer puré las verduras y esconderlas en salsas.', title_fr = 'Opération légumes cachés 🥦', body_fr = 'Il trie et jette les légumes de la soupe ? Ne luttez pas. Découvrez dans le Plan de nutrition les façons les plus originales et astucieuses de réduire les légumes en purée et de les cacher dans les sauces.', title_hi = 'छिपी सब्ज़ियों का ऑपरेशन 🥦', body_hi = 'सूप की सब्ज़ियाँ चुनकर फेंक देता है? लड़ाई मत कीजिए। फ़ीडिंग प्लान में सब्ज़ियों को प्यूरी बनाकर सॉस में छिपाने के सबसे अलग और चतुर तरीके खोजिए।', title_id = 'Operasi sayuran tersembunyi 🥦', body_id = 'Ia memilih dan membuang sayuran dari supnya? Jangan berdebat. Temukan cara paling unik dan cerdik untuk menghaluskan sayuran dan menyembunyikannya di saus lewat Rencana Nutrisi.', title_ja = '野菜かくし作戦 🥦', body_ja = 'スープの野菜を選んで捨てますか？戦わないで。「栄養管理ツール」で、野菜をピューレにしてソースにかくすいちばんユニークで賢い方法を見つけましょう。', title_ko = '채소 숨기기 작전 🥦', body_ko = '수프 속 채소를 골라 버리나요? 씨름하지 마세요. 식단 계획에서 채소를 퓌레로 만들어 소스에 숨기는 가장 색다르고 기발한 방법을 찾아보세요.', title_nl = 'Operatie verstopte groenten 🥦', body_nl = 'Vist hij de groenten uit zijn soep en gooit hij ze weg? Ga de strijd niet aan. Ontdek in het Voedingsplan de meest originele en slimme manieren om groenten te pureren en in sausjes te verstoppen.', title_pl = 'Operacja: ukryte warzywa 🥦', body_pl = 'Wybiera warzywa z zupy i je wyrzuca? Nie walcz z tym. Odkryj w planie karmienia najbardziej nietypowe i sprytne sposoby, by zmiksować warzywa i ukryć je w sosach.', title_pt = 'Operação legumes escondidos 🥦', body_pt = 'Escolhe os legumes da sopa e deita-os fora? Não lute. Descubra no Plano Alimentar as formas mais diferentes e engenhosas de fazer puré de legumes e escondê-los nos molhos.', title_sv = 'Operation gömda grönsaker 🥦', body_sv = 'Plockar barnet bort grönsakerna i soppan och kastar dem? Kämpa inte emot. Upptäck de mest annorlunda och listiga sätten att mosa grönsaker och gömma dem i såser i matplanen.', title_vi = 'Chiến dịch giấu rau 🥦', body_vi = 'Bé nhặt rau trong bát canh ra và vứt đi? Đừng giằng co. Hãy khám phá trong Kế hoạch dinh dưỡng những cách độc đáo và khéo léo nhất để xay nhuyễn rau và giấu vào nước sốt.', title_zh = '秘密蔬菜行动 🥦', body_zh = '把汤里的蔬菜挑出来扔掉？别硬碰硬。在喂养计划里找找把蔬菜做成泥藏进酱汁里的各种巧妙办法。' WHERE id = '502d3376-0322-4c07-aee1-71c209315c6b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La insistencia del «¡Mamá, mírame!» 👀', body_es = '¿Cuando miras el móvil o haces algo viene y te da en la mano? Tiene toda la razón: quiere toda tu atención. 5 minutos de tiempo de calidad mirándole a los ojos le calmarán.', title_fr = 'L''insistance du « Maman, regarde-moi ! » 👀', body_fr = 'Quand vous regardez votre téléphone ou que vous travaillez, il vient vous taper la main ? Il a tout à fait raison, il veut une attention entière. 5 minutes de vrai temps ensemble, les yeux dans les yeux, suffiront à l''apaiser.', title_hi = '''माँ, मुझे देखो!'' वाली ज़िद 👀', body_hi = 'आप फ़ोन देखती हैं या कोई काम करती हैं तो आकर आपके हाथ पर मारता है? वह बिल्कुल सही है, उसे आपका पूरा ध्यान चाहिए। आँखों में आँखें डालकर बिताया 5 मिनट का अच्छा समय उसे शांत कर देगा।', title_id = 'Desakan ''Ibu, lihat aku!'' 👀', body_id = 'Saat Anda melihat ponsel atau sedang bekerja, ia datang memukul tangan Anda? Ia sepenuhnya benar, ia ingin perhatian yang tidak terbagi. 5 menit waktu berkualitas sambil menatap matanya akan menenangkannya.', title_ja = '「ママ、こっち見て！」のがんばり 👀', body_ja = 'あなたがスマホを見たり作業したりしていると、やってきて手をたたきますか？お子さんの言うとおりです、自分だけを見てほしいのです。目を合わせて過ごす5分間の濃い時間が、落ち着かせてくれます。', title_ko = '''엄마, 나 좀 봐!'' 고집 👀', body_ko = '엄마가 휴대폰을 보거나 일할 때 다가와 손을 치나요? 아이 말이 맞아요. 온전한 관심을 원하는 거예요. 눈을 맞추며 보내는 5분의 소중한 시간이 아이를 진정시켜 줄 거예요.', title_nl = 'Koppig: ''Mama, kijk naar mij!'' 👀', body_nl = 'Komt hij tegen je hand tikken als je op je telefoon kijkt of bezig bent? Hij heeft helemaal gelijk, hij wil je onverdeelde aandacht. 5 minuten echte aandacht met oogcontact kalmeert hem.', title_pl = 'Upór „Mamo, patrz na mnie!” 👀', body_pl = 'Gdy patrzysz w telefon albo coś robisz, podchodzi i uderza cię w rękę? Ma całkowitą rację, chce niepodzielnej uwagi. 5 minut wartościowego czasu z kontaktem wzrokowym go uspokoi.', title_pt = 'A insistência do "Mamã, olha para mim!" 👀', body_pt = 'Quando está a ver o telemóvel ou a trabalhar, vem bater-lhe na mão? Tem toda a razão: quer atenção exclusiva. 5 minutos de tempo de qualidade, olhos nos olhos, vão acalmá-lo.', title_sv = 'Envisheten i ”Mamma, titta på mig!” 👀', body_sv = 'Slår barnet till din hand när du tittar på mobilen eller gör något? Hen har helt rätt, barnet vill ha din odelade uppmärksamhet. Skapa ögonkontakt, 5 minuters kvalitetstid lugnar barnet.', title_vi = 'Sự bướng bỉnh "Mẹ ơi, nhìn con này!" 👀', body_vi = 'Khi mẹ nhìn điện thoại hay làm việc, bé chạy đến đập vào tay mẹ? Bé hoàn toàn có lý, bé muốn mẹ chú ý trọn vẹn. 5 phút bên nhau chất lượng, nhìn vào mắt bé sẽ giúp bé dịu lại.', title_zh = '“妈妈，看我！”的执着 👀', body_zh = '你看手机或忙事情时，宝宝跑过来拍你的手？宝宝完全有道理，宝宝要的是完整的注意力。和宝宝对视，5分钟的高质量陪伴就能让宝宝平静下来。' WHERE id = 'ad687f75-6bde-4ad1-8992-78906bd61fd5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de escaparse de la habitación 🏃‍♂️', body_es = 'Cuando quieres ponerle el pijama o la camiseta, sale riendo de la habitación. No lo resuelvas enfadándote, sino convirtiéndolo en un juego. Es más fácil vestirle jugando al pilla-pilla.', title_fr = 'Le jeu de l''évasion 🏃‍♂️', body_fr = 'Quand vous voulez lui mettre son pyjama ou son t-shirt, il s''enfuit de la pièce en riant. Ne vous énervez pas, faites-en un jeu. C''est plus facile de l''habiller en jouant au chat et à la souris.', title_hi = 'कमरे से भागने का खेल 🏃‍♂️', body_hi = 'आप पजामा या शर्ट पहनाना चाहें तो हँसते हुए कमरे से भाग जाता है? इसे गुस्से से नहीं, खेल बनाकर सुलझाइए। पकड़म-पकड़ाई खेलते हुए कपड़े पहनाना ज़्यादा आसान है।', title_id = 'Permainan kabur dari kamar 🏃‍♂️', body_id = 'Saat Anda ingin memakaikan piyama atau kaus, ia berlari keluar kamar sambil tertawa. Atasi bukan dengan marah, tetapi dengan menjadikannya permainan. Memakaikan baju sambil bermain kejar-kejaran jauh lebih mudah.', title_ja = '部屋から脱走ゲーム 🏃‍♂️', body_ja = 'パジャマやシャツを着せようとすると、笑いながら部屋から逃げますか？イライラせずに遊びに変えて解決しましょう。追いかけっこをしながらのほうが、ずっと着せやすくなります。', title_ko = '방 탈출 놀이 🏃‍♂️', body_ko = '잠옷이나 셔츠를 입히려고 하면 깔깔 웃으며 방에서 도망가나요? 화내지 말고 놀이로 풀어 보세요. 술래잡기하며 입히면 훨씬 쉬워요.', title_nl = 'Het ontsnappingsspel 🏃‍♂️', body_nl = 'Rent hij lachend de kamer uit als je hem een pyjama of shirt wilt aantrekken? Los het niet boos op, maar maak er een spel van. Met tikkertje is aankleden veel makkelijker.', title_pl = 'Zabawa w ucieczkę z pokoju 🏃‍♂️', body_pl = 'Gdy chcesz mu założyć piżamę albo koszulkę, ze śmiechem ucieka z pokoju. Rozwiąż to nie złością, tylko zabawą. Ubieranie w trakcie zabawy w berka idzie dużo łatwiej.', title_pt = 'O jogo da fuga do quarto 🏃‍♂️', body_pt = 'Quando lhe quer vestir o pijama ou a camisola, foge do quarto a rir. Resolva isto não com irritação, mas transformando-o num jogo. Vestir a brincar à apanhada é mais fácil.', title_sv = 'Leken att fly från rummet 🏃‍♂️', body_sv = 'Springer barnet skrattande ut ur rummet när du vill sätta på pyjamas eller tröja? Lös det genom att göra det till en lek, inte genom att bli arg. Det är lättare att klä på barnet när ni leker tafatt.', title_vi = 'Trò chạy trốn khỏi phòng 🏃‍♂️', body_vi = 'Khi mẹ muốn mặc đồ ngủ hay áo cho bé, bé cười và chạy khỏi phòng. Hãy giải quyết bằng trò chơi chứ đừng nổi giận. Vừa chơi đuổi bắt vừa mặc đồ sẽ dễ hơn nhiều.', title_zh = '逃出房间的游戏 🏃‍♂️', body_zh = '你想给宝宝穿睡衣或衣服时，宝宝笑着跑出房间。别生气，把它变成游戏来解决。玩着“你追我跑”穿衣服，会容易得多。' WHERE id = '22e7c65d-25fb-4bbe-aa34-29a2d5e5e3ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Alerta del tiempo ⛅', body_es = 'Al salir de paseo, no te dejes engañar por lo que ves por la ventana. Elige con Tiempo y ropa el conjunto más adecuado para el viento y la temperatura reales de fuera y sal de casa.', title_fr = 'Alerte météo ⛅', body_fr = 'Avant la promenade, ne vous laissez pas tromper par la vue depuis la fenêtre. Avec Météo et tenue, choisissez la tenue la mieux adaptée au vent et à la température réels avant de sortir.', title_hi = 'मौसम की चेतावनी ⛅', body_hi = 'सैर पर जाते समय सिर्फ़ खिड़की से देखकर धोखा मत खाइए। मौसम और कपड़े असिस्टेंट से बाहर की असली हवा और तापमान के हिसाब से सबसे सही कपड़े चुनिए और निकलिए।', title_id = 'Peringatan cuaca ⛅', body_id = 'Saat akan jalan-jalan, jangan tertipu dengan melihat dari jendela. Tentukan setelan yang paling pas untuk angin dan suhu sebenarnya di luar dengan alat Cuaca dan Pakaian sebelum keluar rumah.', title_ja = '天気に注意 ⛅', body_ja = 'お散歩に出かけるとき、窓から見た景色にだまされないで。「天気と服装」で外の実際の風と気温にいちばん合うコーディネートを決めてから出かけましょう。', title_ko = '날씨 알림 ⛅', body_ko = '산책 나갈 때 창밖만 보고 속지 마세요. 날씨와 옷차림 도우미로 실제 바람과 기온에 가장 알맞은 옷차림을 정하고 나가세요.', title_nl = 'Weerwaarschuwing ⛅', body_nl = 'Laat je niet misleiden door een blik uit het raam als je gaat wandelen. Kies met Weer en kleding de outfit die het best past bij de echte wind en temperatuur buiten en ga dan pas de deur uit.', title_pl = 'Ostrzeżenie pogodowe ⛅', body_pl = 'Wychodząc na spacer, nie daj się zwieść widokowi za oknem. Dobierz w narzędziu Pogoda i ubiór zestaw najlepiej pasujący do prawdziwego wiatru i temperatury na zewnątrz i dopiero wtedy wyjdźcie.', title_pt = 'Alerta de tempo ⛅', body_pt = 'Quando saírem para passear, não se deixe enganar pelo que vê da janela. Escolha no Tempo e Roupa a combinação mais adequada ao vento e à temperatura reais lá fora antes de sair de casa.', title_sv = 'Vädervarning ⛅', body_sv = 'Låt dig inte luras av att titta ut genom fönstret inför promenaden. Välj den klädsel som passar bäst för den verkliga vinden och temperaturen ute med assistenten Väder och kläder innan ni går.', title_vi = 'Cảnh báo thời tiết ⛅', body_vi = 'Khi ra ngoài đi dạo, đừng để cảnh bên ngoài cửa sổ đánh lừa. Hãy dùng trợ lý Thời tiết và trang phục để chọn cách phối đồ phù hợp nhất với gió và nhiệt độ thực tế rồi mới ra khỏi nhà.', title_zh = '天气提醒 ⛅', body_zh = '出门散步时，别被窗外的样子骗了。用天气穿衣助手找到最适合外面实际风力和温度的搭配再出门。' WHERE id = '322a385d-8940-4d2a-9d21-4777e2660139' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dúo de sueño de papá 📖', body_es = 'Esta noche creemos un ambiente distinto en la habitación. En lugar de leer un libro, cantad bajito con papá una canción rítmica para ayudarle a dormirse.', title_fr = 'Le duo du coucher avec papa 📖', body_fr = 'Ce soir, créons une ambiance différente dans la chambre. Au lieu de lire un livre, chantez avec papa, tout bas, une chanson rythmée pour l''aider à s''endormir.', title_hi = 'पापा के साथ लोरी की जुगलबंदी 📖', body_hi = 'आज शाम कमरे में कुछ अलग माहौल बनाइए। किताब पढ़ने के बजाय पापा के साथ मिलकर धीमी आवाज़ में, लय वाला गाना गाइए और उसे नींद में जाने दीजिए।', title_id = 'Duet tidur bersama Ayah 📖', body_id = 'Malam ini mari ciptakan suasana berbeda di kamar. Daripada membaca buku, nyanyikan lagu berirama dengan suara pelan bersama Ayah untuk mengantarnya tidur.', title_ja = 'パパとの子守歌デュエット 📖', body_ja = '今夜は部屋に違う雰囲気をつくりましょう。絵本を読むかわりに、パパと一緒に小さな声でリズムのある歌を歌って、眠りへ導いてあげて。', title_ko = '아빠와의 자장가 듀엣 📖', body_ko = '오늘 밤엔 방에 색다른 분위기를 만들어 봐요. 책을 읽는 대신 아빠와 함께 작은 목소리로 리듬감 있는 노래를 불러 스르르 잠들게 해 주세요.', title_nl = 'Slaapduet met papa 📖', body_nl = 'Laten we vanavond een andere sfeer in de kamer maken. Lees geen boek voor, maar zing samen met papa zachtjes een ritmisch liedje, zodat hij in slaap kan vallen.', title_pl = 'Kołysankowy duet z tatą 📖', body_pl = 'Stwórzmy dziś wieczorem w pokoju inny klimat. Zamiast czytać książkę, zaśpiewajcie razem z tatą cicho rytmiczną piosenkę, która pomoże mu zasnąć.', title_pt = 'O dueto de sono do pai 📖', body_pt = 'Esta noite, vamos criar um ambiente diferente no quarto. Em vez de ler um livro, cantem com o pai, em voz baixa, uma canção ritmada que o ajude a adormecer.', title_sv = 'Pappas sömnduett 📖', body_sv = 'Låt oss skapa en annan stämning i rummet i kväll. I stället för att läsa en bok, sjung en lugn, rytmisk sång med låg röst tillsammans med pappa och hjälp barnet att somna.', title_vi = 'Bản song ca ru ngủ của bố 📖', body_vi = 'Tối nay hãy tạo một bầu không khí khác trong phòng. Thay vì đọc sách, hãy cùng bố hát khẽ một bài hát nhịp nhàng để bé chìm vào giấc ngủ.', title_zh = '和爸爸的催眠二重唱 📖', body_zh = '今晚给房间换一种氛围吧。别读书了，和爸爸一起低声唱一首有节奏的歌，帮宝宝进入梦乡。' WHERE id = 'af1711a8-2ca3-45c1-ae35-556b3b0e2d67' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá, aliméntate 🥑', body_es = 'Con el ajetreo diario, no comas de pie. Prepárate una ensalada diferente, rica en hierro y calcio, y cómetela sentada y con gusto. Tu energía es el motor de esta casa.', title_fr = 'Maman, nourris-toi 🥑', body_fr = 'Dans la course du quotidien, ne déjeunez pas debout. Préparez une salade originale riche en fer et en calcium et mangez-la assise, en la savourant. Votre énergie est le moteur de cette maison.', title_hi = 'माँ, अपना पेट भरिए 🥑', body_hi = 'रोज़ की भागदौड़ में खड़े-खड़े लंच मत कीजिए। बैठकर, मज़े से, आयरन और कैल्शियम से भरपूर एक अलग सलाद बनाइए और खाइए। आपकी ऊर्जा इस घर का इंजन है।', title_id = 'Ibu, kenyangkan dirimu 🥑', body_id = 'Di tengah kesibukan, jangan makan siang sambil berdiri. Duduklah, siapkan salad istimewa yang kaya zat besi dan kalsium, lalu nikmati. Energi Anda adalah mesin rumah ini.', title_ja = 'ママ、しっかり食べて 🥑', body_ja = '毎日のバタバタで、ランチを立ったまま済ませないで。座って、鉄分とカルシウムたっぷりの特別なサラダをつくり、味わって食べましょう。あなたの元気はこの家のエンジンです。', title_ko = '엄마, 엄마도 챙겨 드세요 🥑', body_ko = '바쁜 하루 속에서 점심을 서서 때우지 마세요. 앉아서 철분과 칼슘이 풍부한 색다른 샐러드를 만들어 맛있게 드세요. 엄마의 에너지가 이 집의 엔진이에요.', title_nl = 'Mama, eet je buik vol 🥑', body_nl = 'Eet in de dagelijkse drukte je lunch niet staand. Ga zitten en geniet van een bijzondere salade vol ijzer en calcium. Jouw energie is de motor van dit huis.', title_pl = 'Mamo, nakarm siebie 🥑', body_pl = 'W codziennej bieganinie nie jedz obiadu na stojąco. Przygotuj wyjątkową sałatkę bogatą w żelazo i wapń i zjedz ją na siedząco, z przyjemnością. Twoja energia to silnik tego domu.', title_pt = 'Mãe, alimente-se 🥑', body_pt = 'Na correria do dia, não almoce de pé. Sente-se e coma com gosto uma salada diferente, rica em ferro e cálcio. A sua energia é o motor desta casa.', title_sv = 'Mamma, ät dig mätt 🥑', body_sv = 'Ät inte lunchen stående i vardagsstressen. Sätt dig ner och ät med njutning, gör en annorlunda sallad rik på järn och kalcium. Din energi är motorn i det här hemmet.', title_vi = 'Mẹ ơi, hãy ăn no nhé 🥑', body_vi = 'Đừng ăn trưa vội vàng giữa nhịp sống tất bật. Hãy ngồi xuống, làm một món salad khác lạ giàu sắt và canxi rồi thưởng thức thật ngon miệng. Năng lượng của mẹ là động cơ của ngôi nhà này.', title_zh = '妈妈，先把自己喂饱 🥑', body_zh = '每天忙忙碌碌，别站着解决午饭。坐下来，好好做一份富含铁和钙的特别沙拉，慢慢享用。你的能量是这个家的发动机。' WHERE id = 'b2328024-7846-4b25-a276-980c22ebcd52' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Primeros pasos en la amistad 👫', body_es = '¿En el parque ha compartido por primera vez su juguete con otro niño por iniciativa propia? ¡Es un gran avance! El egocentrismo se rompe y se forma la empatía. Aplaúdele con mucha alegría.', title_fr = 'Premiers pas en amitié 👫', body_fr = 'Au parc, il a prêté son jouet à un autre enfant pour la première fois, de lui-même ? C''est un grand progrès ! L''égocentrisme recule, l''empathie se forme. Applaudissez-le avec une grande joie.', title_hi = 'दोस्ती के कदम 👫', body_hi = 'पार्क में पहली बार अपनी मर्ज़ी से किसी बच्चे के साथ खिलौना बाँटा? यह बड़ा विकास है! ''मैं ही मैं'' वाली सोच टूट रही है, हमदर्दी बन रही है। खूब खुशी से उसकी तारीफ़ कीजिए।', title_id = 'Langkah persahabatan 👫', body_id = 'Untuk pertama kalinya di taman ia meminjamkan mainannya kepada anak lain atas kemauannya sendiri? Ini perkembangan besar! Egosentrisnya mulai luruh, empatinya terbentuk. Sambut ia dengan kegembiraan besar.', title_ja = '友情への一歩 👫', body_ja = '公園ではじめて、自分からほかの子におもちゃを貸してあげましたか？大きな成長です！自分中心の殻が破れ、思いやりが育っています。大きなよろこびで拍手してあげましょう。', title_ko = '우정의 첫걸음 👫', body_ko = '공원에서 처음으로 스스로 친구에게 장난감을 나눠 줬나요? 큰 성장이에요! 자기중심성이 깨지고 공감 능력이 자라고 있어요. 크게 기뻐하며 박수를 보내 주세요.', title_nl = 'Stapjes in vriendschap 👫', body_nl = 'Deelde hij in het park voor het eerst uit zichzelf zijn speelgoed met een ander kind? Dat is een grote ontwikkeling! Het egocentrisme breekt, empathie ontstaat. Juich het met grote blijdschap toe.', title_pl = 'Pierwsze kroki w przyjaźni 👫', body_pl = 'Pierwszy raz w parku z własnej woli podzielił się zabawką z innym dzieckiem? To wielki krok w rozwoju! Egocentryzm słabnie, kształtuje się empatia. Oklaskuj go z wielką radością.', title_pt = 'Passos de amizade 👫', body_pt = 'No parque, pela primeira vez, emprestou o brinquedo a outra criança por vontade própria? É um grande avanço! O egocentrismo está a ceder e a empatia a formar-se. Aplauda-o com muita alegria.', title_sv = 'Steg mot vänskap 👫', body_sv = 'Delade barnet för första gången frivilligt sin leksak med ett annat barn i parken? Det är en stor utveckling! Egocentrismen bryts och empatin formas. Applådera med stor glädje.', title_vi = 'Những bước đầu của tình bạn 👫', body_vi = 'Lần đầu tiên ở công viên bé tự nguyện chia sẻ đồ chơi với bạn? Đây là bước phát triển lớn! Sự vị kỷ đang mờ dần, sự đồng cảm đang hình thành. Hãy hân hoan khen ngợi bé.', title_zh = '交朋友的脚步 👫', body_zh = '在公园里第一次主动把玩具分给别的小朋友？这是一大进步！自我中心正在打破，共情正在形成。满怀喜悦地为宝宝鼓掌吧。' WHERE id = 'e037ab2c-d2a8-49ed-a1df-aac78a584118' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tozudez del «¡Es mío!» 🛑', body_es = '¿Lo quiere todo para él? Aún no tiene del todo formado el concepto de compartir. No le obligues; en su lugar, introduce poco a poco la regla de «Jugamos por turnos».', title_fr = 'L''entêtement du « C''est à moi ! » 🛑', body_fr = 'Il veut tout garder pour lui ? La notion de partage n''est pas encore tout à fait acquise. Ne le forcez pas, introduisez plutôt peu à peu la règle « On joue chacun son tour ».', title_hi = '''मेरा!'' वाली ज़िद 🛑', body_hi = 'हर चीज़ अपनी बनाना चाहता है? बाँटने की समझ अभी पूरी तरह बनी नहीं है। उस पर ज़बरदस्ती मत कीजिए, बल्कि धीरे-धीरे ''बारी-बारी से खेलें'' का नियम सिखाइए।', title_id = 'Keras kepala ''Punyaku!'' 🛑', body_id = 'Ingin memiliki semuanya? Konsep berbagi belum sepenuhnya terbentuk. Jangan memaksanya, sebaliknya terapkan aturan ''Ayo main bergiliran'' secara bertahap.', title_ja = '「ぼくの！」のがんばり 🛑', body_ja = 'なんでも自分のものにしたい？「分け合うこと」の考え方はまだ十分に育っていません。無理強いせず、かわりに「順番に遊ぼうね」のルールを少しずつ取り入れましょう。', title_ko = '''내 거야!'' 고집 🛑', body_ko = '뭐든 자기 것이라고 하나요? 나눔이라는 개념은 아직 완전히 자리 잡지 않았어요. 억지로 시키지 말고 ''차례대로 놀자'' 규칙을 조금씩 알려 주세요.', title_nl = 'Koppig: ''Van mij!'' 🛑', body_nl = 'Wil hij alles hebben? Het idee van delen is nog niet helemaal gevormd. Dwing hem niet, maar introduceer stap voor stap de regel ''We spelen om de beurt''.', title_pl = 'Upór „To moje!” 🛑', body_pl = 'Chce mieć wszystko na własność? Pojęcie dzielenia się jeszcze w pełni się nie ukształtowało. Nie zmuszaj go, zamiast tego stopniowo wprowadzaj zasadę „bawimy się po kolei”.', title_pt = 'A teimosia do "É meu!" 🛑', body_pt = 'Quer tudo só para si? O conceito de partilhar ainda não está totalmente formado. Não o force; em vez disso, introduza aos poucos a regra "vamos brincar à vez".', title_sv = 'Envisheten i ”Min!” 🛑', body_sv = 'Vill barnet ha allt för sig själv? Begreppet att dela har ännu inte formats helt. Tvinga inte barnet, inför i stället gradvis regeln ”Vi turas om”.', title_vi = 'Sự bướng bỉnh "Của con!" 🛑', body_vi = 'Bé muốn giữ hết mọi thứ? Khái niệm chia sẻ chưa hình thành hoàn toàn. Đừng ép bé, thay vào đó hãy dần áp dụng quy tắc "Mình chơi lần lượt nhé".', title_zh = '“是我的！”的倔强 🛑', body_zh = '什么都想占为己有？“分享”的概念还没有完全形成。别勉强宝宝，而是慢慢引入“我们轮流玩”的规则。' WHERE id = '92aa3f00-711e-43bd-a2d7-1f3bfbc7744d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Le cuesta dormirse? Crea un cuento especial en Cuentos inteligentes y convierte los nuevos hábitos en una historia.', body_fr = 'Il a du mal à s''endormir ? Créez un conte spécial dans les Contes intelligents pour raconter ses nouvelles habitudes sous forme d''histoire.', body_hi = 'सोने में मुश्किल होती है? स्मार्ट कहानियों में एक खास कहानी बनाइए और नई आदतों को कहानी के रूप में सुनाइए।', body_id = 'Sulit tertidur? Buat dongeng khusus di Dongeng Pintar dan jadikan kebiasaan baru sebagai cerita.', body_ja = 'なかなか寝つけない？「スマートおはなし」で特別なお話をつくって、新しい習慣をお話にしてあげましょう。', body_ko = '잠들기 힘들어하나요? 스마트 동화에서 특별한 동화를 만들어 새로운 습관을 이야기로 들려주세요.', body_nl = 'Heeft hij moeite met inslapen? Maak in Slimme sprookjes een speciaal sprookje en verpak nieuwe gewoontes in een verhaal.', body_pl = 'Ma trudności z zasypianiem? Stwórz w Mądrych bajkach wyjątkową bajkę i opowiedz w niej o nowych nawykach.', body_pt = 'Tem dificuldade em adormecer? Crie uma história especial nas Histórias Inteligentes e transforme os novos hábitos num conto.', body_sv = 'Har barnet svårt att somna? Skapa en särskild saga i Smarta sagor och gör de nya vanorna till en berättelse.', body_vi = 'Bé khó đi vào giấc ngủ? Hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh để kể về những thói quen mới.', body_zh = '入睡有困难？在智能故事里创作一个特别的故事，把新习惯编进故事里吧。' WHERE id = 'adf1cd9b-1322-48c3-a05b-72b8aa90f9cc' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '10 minutos a la luz de una vela 🕯️', body_es = 'Tu peque se ha dormido y el caos de casa ha terminado. Apaga las luces, mira la oscuridad o la luz de una vela y, durante 10 minutos, pon a cero tu mente y tus pensamientos.', title_fr = '10 minutes à la lueur d''une bougie 🕯️', body_fr = 'L''enfant dort, le chaos de la maison est terminé. Éteignez les lumières, regardez simplement le noir ou la flamme d''une bougie et remettez complètement à zéro votre cerveau et vos pensées pendant 10 minutes.', title_hi = 'मोमबत्ती की रोशनी में 10 मिनट 🕯️', body_hi = 'बच्चा सो गया, घर की अफ़रा-तफ़री खत्म। लाइटें बंद कीजिए, बस अंधेरे या मोमबत्ती की रोशनी को देखिए और 10 मिनट में अपने दिमाग और ख्यालों को पूरी तरह रीसेट कीजिए।', title_id = '10 menit di bawah cahaya lilin 🕯️', body_id = 'Anak sudah tidur, kekacauan di rumah usai. Matikan lampu, pandangi saja kegelapan atau cahaya lilin, dan kosongkan pikiran Anda sepenuhnya selama 10 menit.', title_ja = 'キャンドルの明かりで10分 🕯️', body_ja = 'お子さんが眠り、家の大騒ぎは終わりました。明かりを消して、暗やみかキャンドルの明かりをただ見つめ、10分間、頭と考えをすっかりリセットしましょう。', title_ko = '촛불 아래 10분 🕯️', body_ko = '아이가 잠들고 집 안의 소란이 끝났어요. 불을 끄고 어둠이나 촛불을 바라보며 10분 동안 머리와 생각을 완전히 비워 보세요.', title_nl = '10 minuten bij kaarslicht 🕯️', body_nl = 'Hij slaapt, de chaos in huis is voorbij. Doe de lichten uit, kijk gewoon in het donker of naar een kaarsvlam en reset 10 minuten lang je hoofd en je gedachten helemaal.', title_pl = '10 minut przy świecy 🕯️', body_pl = 'Dziecko śpi, domowy chaos się skończył. Zgaś światła i po prostu patrz w ciemność albo na płomień świecy, by przez 10 minut całkowicie zresetować głowę i myśli.', title_pt = '10 minutos à luz da vela 🕯️', body_pt = 'A criança adormeceu e o caos em casa acabou. Apague as luzes e, durante 10 minutos, olhe apenas para o escuro ou para a luz de uma vela e reponha a zero o cérebro e os pensamentos.', title_sv = '10 minuter i levande ljus 🕯️', body_sv = 'Barnet sover, kaoset hemma är över. Släck lamporna, titta bara ut i mörkret eller på ett levande ljus och nollställ hjärnan och tankarna helt i 10 minuter.', title_vi = '10 phút dưới ánh nến 🕯️', body_vi = 'Bé ngủ rồi, sự hỗn loạn trong nhà đã kết thúc. Hãy tắt đèn, chỉ nhìn vào bóng tối hoặc ánh nến trong 10 phút để đầu óc và suy nghĩ hoàn toàn được làm mới.', title_zh = '烛光下的10分钟 🕯️', body_zh = '孩子睡着了，家里的混乱结束了。关掉灯，只看着黑暗或一支烛光，用10分钟把大脑和思绪彻底清空。' WHERE id = '1f9d373c-817c-4a86-9cb9-a9b3d9fac797' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Consuelo en la Comunidad 💬', body_es = '¿Te ahoga pensar «Nunca volveré a ser la de antes»? Comparte este sentimiento pasajero pero tan pesado con las madres de la Comunidad Anacan y recibe su apoyo.', title_fr = 'Du réconfort dans la Communauté 💬', body_fr = 'La pensée « Je ne redeviendrai jamais celle que j''étais » vous étouffe ? Partagez cette émotion passagère, mais très lourde, avec les mamans de la Communauté Anacan et trouvez du soutien.', title_hi = 'कम्युनिटी में सुकून 💬', body_hi = '''मैं फिर कभी पहले जैसी नहीं हो पाऊँगी'' वाला ख्याल घुटन दे रहा है? Anacan कम्युनिटी की माँओं के साथ यह गुज़र जाने वाली, लेकिन बहुत भारी भावना बाँटिए और उनसे सहारा पाइए।', title_id = 'Penghiburan di komunitas 💬', body_id = 'Pikiran ''Aku tidak akan pernah bisa menjadi diriku yang dulu'' membuat Anda sesak? Bagikan perasaan yang sementara namun sangat berat ini dengan para ibu di Komunitas Anacan dan dapatkan dukungan mereka.', title_ja = 'コミュニティでほっとひと息 💬', body_ja = '「もう前の自分には戻れない」という思いに押しつぶされそう？この一時的だけれどとても重い気持ちを、Anacanコミュニティのママたちと分かち合って、支えてもらいましょう。', title_ko = '커뮤니티에서 받는 위로 💬', body_ko = '''예전의 나로는 절대 돌아갈 수 없을 거야''라는 생각에 숨이 막히나요? 지나가지만 아주 무거운 이 감정을 Anacan 커뮤니티의 엄마들과 나누고 위로를 받으세요.', title_nl = 'Troost in de community 💬', body_nl = 'Word je overspoeld door de gedachte ''Ik word nooit meer de oude''? Deel dit tijdelijke maar zware gevoel met de moeders in de Anacan Community en vind steun bij hen.', title_pl = 'Pocieszenie w Społeczności 💬', body_pl = 'Przytłacza cię myśl „Już nigdy nie będę dawną sobą”? Podziel się tym przemijającym, ale bardzo ciężkim uczuciem z mamami w Społeczności Anacan i znajdź u nich wsparcie.', title_pt = 'Consolo na Comunidade 💬', body_pt = 'O pensamento "nunca mais vou ser a mesma" sufoca-a? Partilhe este sentimento passageiro, mas muito pesado, com as mães da Comunidade Anacan e receba o apoio delas.', title_sv = 'Tröst i gemenskapen 💬', body_sv = 'Kväver tanken ”jag kommer aldrig att bli mitt gamla jag igen” dig? Dela den här tillfälliga men väldigt tunga känslan med mammorna i Anacan Community och få stöd.', title_vi = 'An ủi trong Cộng đồng 💬', body_vi = 'Ý nghĩ "Mình sẽ không bao giờ là mình của ngày xưa nữa" khiến mẹ ngột ngạt? Hãy chia sẻ cảm xúc tạm thời nhưng nặng nề này với các mẹ trong Cộng đồng Anacan và nhận sự hỗ trợ.', title_zh = '在社区里找到安慰 💬', body_zh = '“我再也回不到从前的自己了”的念头压得你喘不过气？和Anacan社区里的妈妈们聊聊这种短暂却沉重的情绪，获得她们的支持吧。' WHERE id = '7ca4e4fb-3ef6-4d7f-b7a1-18d9264ed8c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Trenzas rebeldes 🪮', body_es = '¿No te deja recogerle ni peinarle el pelo de ninguna manera? Para la batalla. Poneos delante del espejo, péinate primero tú como él quiera y luego dale su turno.', title_fr = 'Les tresses de la discorde 🪮', body_fr = 'Il refuse catégoriquement qu''on lui attache ou peigne les cheveux ? Arrêtez la lutte. Mettez-vous devant le miroir, coiffez d''abord vos cheveux comme il le veut, puis ce sera son tour.', title_hi = 'ज़िद्दी चोटियाँ 🪮', body_hi = 'बाल बाँधने या सँवारने बिल्कुल नहीं देता? जंग रोकिए। आईने के सामने जाकर पहले अपने बाल उसकी पसंद के मुताबिक सँवारिए, फिर बारी उसे दीजिए।', title_id = 'Kepang yang keras kepala 🪮', body_id = 'Ia sama sekali tidak mau rambutnya diikat atau disisir? Hentikan perdebatan. Berdirilah di depan cermin, sisir dulu rambut Anda sesuai keinginannya, lalu berikan giliran padanya.', title_ja = 'がんこな髪 🪮', body_ja = '髪を結んだり、とかしたりをどうしてもさせてくれない？戦いはやめましょう。鏡の前で、まずお子さんの言うとおりにあなたの髪をとかしてから、お子さんの番にして。', title_ko = '고집스러운 머리카락 🪮', body_ko = '머리를 묶거나 빗는 걸 절대 못 하게 하나요? 씨름은 멈추세요. 거울 앞에서 먼저 아이가 원하는 대로 엄마 머리를 빗고, 그다음 아이 차례로 해 보세요.', title_nl = 'Koppige vlechtjes 🪮', body_nl = 'Mag je zijn haar absoluut niet kammen of opsteken? Stop de strijd. Ga voor de spiegel staan, kam eerst je eigen haar zoals hij het wil en geef hem daarna de beurt.', title_pl = 'Uparte warkoczyki 🪮', body_pl = 'Za nic nie pozwala związać ani uczesać włosów? Przerwij walkę. Stańcie przed lustrem, najpierw uczesz swoje włosy tak, jak on chce, a potem oddaj mu kolejkę.', title_pt = 'Tranças teimosas 🪮', body_pt = 'Não a deixa de maneira nenhuma prender-lhe ou pentear-lhe o cabelo? Pare a luta. Ponham-se em frente ao espelho, penteie primeiro o seu cabelo como ele quiser e depois passe-lhe a vez.', title_sv = 'Envisa flätor 🪮', body_sv = 'Låter barnet absolut inte dig sätta upp eller borsta håret? Avbryt kampen. Ställ er framför spegeln, borsta först ditt eget hår som barnet vill och ge sedan turen till barnet.', title_vi = 'Mái tóc bướng bỉnh 🪮', body_vi = 'Bé nhất quyết không cho buộc tóc, chải tóc? Hãy dừng giằng co. Đứng trước gương và chải tóc mẹ theo ý bé trước, rồi mới đến lượt bé.', title_zh = '倔强的小辫子 🪮', body_zh = '死活不让扎头发、梳头发？停下这场对抗。站到镜子前，先按宝宝的想法梳你自己的头发，然后再轮到宝宝。' WHERE id = 'd270bdfa-5a84-42b7-8b44-3231febd32b3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla de la siesta 🥱', body_es = 'Si se niega, no le obligues. En lugar de intentar dormirle una y otra vez y destrozarte los nervios, crea una rutina en la que juegue tranquilo con sus juguetes en la habitación.', title_fr = 'La bataille de la sieste 🥱', body_fr = 'S''il refuse, ne le forcez pas. Plutôt que de vous user les nerfs à essayer encore et encore de l''endormir, instaurez un moment où il joue tranquillement avec ses jouets dans sa chambre.', title_hi = 'दिन की नींद की जंग 🥱', body_hi = 'अगर मना करता है, तो ज़बरदस्ती मत कीजिए। बार-बार सुलाने की कोशिश करके अपनी नसें खराब करने के बजाय ऐसा रूटीन बनाइए जिसमें वह कमरे में चुपचाप खिलौनों से खेले।', title_id = 'Perang tidur siang 🥱', body_id = 'Jika ia menolak, jangan paksa. Daripada merusak saraf Anda dengan berkali-kali mencoba menidurkannya, buat rutinitas bermain mainan dengan tenang di kamar.', title_ja = 'お昼寝の攻防 🥱', body_ja = 'いやがるなら、無理強いしないで。何度も寝かせようとして神経をすり減らすより、部屋で静かにおもちゃで遊ぶ時間をつくりましょう。', title_ko = '낮잠과의 씨름 🥱', body_ko = '거부한다면 억지로 재우지 마세요. 몇 번이고 재우려다 신경을 소모하기보다 방에서 조용히 장난감을 가지고 노는 일과를 만들어 주세요.', title_nl = 'Strijd om het middagslaapje 🥱', body_nl = 'Weigert hij? Dwing hem niet. Zet je zenuwen niet op het spel door hem steeds weer te laten slapen, maar maak een ritme waarin hij rustig in zijn kamer met speelgoed speelt.', title_pl = 'Walka o drzemkę 🥱', body_pl = 'Jeśli odmawia, nie zmuszaj go. Zamiast niszczyć sobie nerwy ciągłymi próbami usypiania, stwórz rytm, w którym spokojnie bawi się w pokoju zabawkami.', title_pt = 'A luta da sesta 🥱', body_pt = 'Se recusa, não o obrigue. Em vez de tentar deitá-lo várias vezes e dar cabo dos nervos, crie uma rotina em que brinca calmamente com os brinquedos no quarto.', title_sv = 'Kampen om dagsömnen 🥱', body_sv = 'Tvinga inte om barnet vägrar. I stället för att slita på nerverna med att försöka söva hen gång på gång, skapa en rutin där barnet leker tyst med leksaker i rummet.', title_vi = 'Cuộc chiến giấc ngủ ngày 🥱', body_vi = 'Nếu bé không chịu ngủ, đừng ép. Thay vì cố cho bé ngủ hết lần này đến lần khác rồi tự làm mình căng thẳng, hãy tạo nếp để bé lặng lẽ chơi đồ chơi trong phòng.', title_zh = '午睡之争 🥱', body_zh = '如果拒绝，就别强迫。与其一次次哄睡把自己气坏，不如定一个让宝宝在房间里安静玩玩具的作息。' WHERE id = 'b155d377-4b41-487e-b8ee-74a365226635' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Victoria en equipo 🥂', body_es = 'Habéis superado otro día difícil. Sentaos frente a frente con tu pareja y brindad con una taza de té: «De verdad somos un equipo legendario y lo hacemos genial».', title_fr = 'Victoire d''équipe 🥂', body_fr = 'Vous avez laissé derrière vous une journée difficile de plus. Asseyez-vous face à votre partenaire et trinquez avec une tasse de thé : « On est vraiment une équipe légendaire, et on s''en sort très bien ! »', title_hi = 'टीम की जीत 🥂', body_hi = 'एक और मुश्किल दिन पीछे छोड़ दिया। अपने पार्टनर के आमने-सामने बैठिए और चाय के गिलास टकराइए: ''हम सच में एक कमाल की टीम हैं और यह काम बढ़िया से कर रहे हैं!''', title_id = 'Kemenangan tim 🥂', body_id = 'Satu hari berat lagi sudah terlewati. Duduklah berhadapan dengan pasangan dan dentingkan gelas teh: ''Kita benar-benar tim legendaris dan kita menjalaninya dengan hebat!''', title_ja = 'チームの勝利 🥂', body_ja = '大変な一日をまたひとつ乗りこえました。パートナーと向かい合って座り、お茶で乾杯しましょう：「わたしたち、本当に伝説のチームだね。最高にうまくやってる！」', title_ko = '팀의 승리 🥂', body_ko = '힘든 하루를 또 이겨 냈어요. 배우자와 마주 앉아 찻잔을 부딪치며 말해 보세요: ''우리 정말 전설적인 팀이야, 정말 잘하고 있어!''', title_nl = 'Overwinning van het team 🥂', body_nl = 'Jullie hebben weer een zware dag achter de rug. Ga tegenover je partner zitten en klink met een kop thee: ''We zijn echt een legendarisch team en we doen het geweldig!''', title_pl = 'Zwycięstwo drużyny 🥂', body_pl = 'Kolejny trudny dzień za wami. Usiądźcie z partnerem naprzeciwko siebie i stuknijcie się kubkami herbaty: „Naprawdę jesteśmy legendarną drużyną i świetnie sobie radzimy!”.', title_pt = 'Vitória da equipa 🥂', body_pt = 'Deixaram para trás mais um dia difícil. Sente-se frente a frente com o seu companheiro e brindem com uma chávena de chá: "Somos mesmo uma equipa lendária e saímo-nos lindamente nisto!"', title_sv = 'Lagets seger 🥂', body_sv = 'Ännu en tuff dag ligger bakom er. Sätt er mitt emot varandra och skåla med en kopp te: ”Vi är verkligen ett legendariskt team och vi klarar det här jättebra!”', title_vi = 'Chiến thắng của cả đội 🥂', body_vi = 'Hai người lại vượt qua thêm một ngày khó khăn. Hãy ngồi đối diện với chồng và cụng ly trà: "Chúng mình thật sự là một đội huyền thoại và làm việc này rất tốt!"', title_zh = '团队的胜利 🥂', body_zh = '你们又熬过了艰难的一天。和另一半面对面坐下，碰一碰茶杯：“我们真是传奇团队，这件事做得太棒了！”' WHERE id = 'b7283d95-1357-4ff9-9423-db4159e19c31' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El drama de compartir 🧸', body_es = '¿No le deja sus juguetes a nadie? No es egoísmo, es desarrollo. Aprende con Anacan AI cómo enseñarle, de cara a los 3 años, no tanto a compartir sino a jugar por turnos.', title_fr = 'Le casse-tête du partage 🧸', body_fr = 'Il ne prête son jouet à personne ? Ce n''est pas de l''égoïsme, c''est une étape du développement. Découvrez avec Anacan AI comment lui transmettre, vers 3 ans, non pas l''idée de partager, mais celle de jouer chacun son tour.', title_hi = 'बाँटने का दुख 🧸', body_hi = 'अपना खिलौना किसी को नहीं देता? यह स्वार्थ नहीं, विकास है। 3 साल के करीब बाँटने की बजाय बारी-बारी से खेलने की समझ के बारे में Anacan AI से जानिए।', title_id = 'Susahnya berbagi 🧸', body_id = 'Ia tidak mau meminjamkan mainannya kepada siapa pun? Ini bukan egois, tetapi perkembangan. Pelajari dari Anacan AI konsep bermain bergiliran, bukan berbagi, menjelang usia 3 tahun.', title_ja = '分け合うのはむずかしい 🧸', body_ja = 'おもちゃをだれにも渡さない？これはわがままではなく、成長の一段階です。3歳が近づくころ、「分け合う」ではなく「順番に遊ぶ」という考え方を、Anacan AIから学びましょう。', title_ko = '나눔의 고민 🧸', body_ko = '장난감을 아무에게도 안 빌려주나요? 이기심이 아니라 발달 과정이에요. 세 돌 무렵에는 나눔보다 차례대로 노는 개념이 중요하다는 걸 Anacan AI에게 배워 보세요.', title_nl = 'Het gedoe met delen 🧸', body_nl = 'Geeft hij zijn speelgoed aan niemand? Dat is geen egoïsme, maar ontwikkeling. Leer van Anacan AI hoe je richting 3 jaar niet zozeer delen, maar om de beurt spelen aanleert.', title_pl = 'Kłopot z dzieleniem się 🧸', body_pl = 'Nikomu nie daje swojej zabawki? To nie egoizm, tylko rozwój. Dowiedz się od Anacan AI, jak w okolicach 3. roku życia uczyć nie tyle dzielenia się, co zabawy po kolei.', title_pt = 'O drama de partilhar 🧸', body_pt = 'Não empresta o brinquedo a ninguém? Não é egoísmo, é desenvolvimento. Aprenda com o Anacan AI como, perto dos 3 anos, ensinar não a partilhar, mas a brincar à vez.', title_sv = 'Svårt att dela 🧸', body_sv = 'Vill barnet inte låna ut sin leksak till någon? Det är inte egoism, det är utveckling. Lär dig av Anacan AI hur du inför 3-årsåldern lär ut att turas om snarare än att dela.', title_vi = 'Nỗi khổ chia sẻ 🧸', body_vi = 'Bé không cho ai mượn đồ chơi? Đây không phải ích kỷ mà là sự phát triển. Gần 3 tuổi, hãy học từ Anacan AI cách dạy bé chơi lần lượt thay vì chia sẻ.', title_zh = '分享的烦恼 🧸', body_zh = '玩具谁也不给？这不是自私，而是成长。快3岁时要培养的不是“分享”，而是“轮流玩”，去问问Anacan AI怎么做吧。' WHERE id = 'c932a08e-a484-4595-8fa6-e57165ffaf96' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El triciclo 🚴‍♂️', body_es = '¿Intenta pisar los pedales y montar en triciclo? ¡Los músculos de sus piernas y su coordinación están en una nueva etapa! Anímale en lugares seguros.', title_fr = 'Le tricycle 🚴‍♂️', body_fr = 'Il appuie sur les pédales pour essayer de rouler ? Les muscles de ses jambes et sa coordination passent un nouveau cap ! Encouragez-le dans des endroits sûrs.', title_hi = 'तीन पहियों वाली साइकिल 🚴‍♂️', body_hi = 'पैडल दबाकर साइकिल चलाने की कोशिश करता है? पैरों की मांसपेशियाँ और तालमेल एक नए पड़ाव पर हैं! सुरक्षित जगहों पर उसका हौसला बढ़ाइए।', title_id = 'Sepeda roda tiga 🚴‍♂️', body_id = 'Ia mencoba menginjak pedal dan mengayuh sepeda? Otot kaki dan koordinasinya memasuki tahap baru! Dukung ia di tempat yang aman.', title_ja = '三輪車 🚴‍♂️', body_ja = 'ペダルをこいで乗ろうとしていますか？足の筋肉と協調性が新しい段階に入っています！安全な場所で応援してあげましょう。', title_ko = '세발자전거 🚴‍♂️', body_ko = '페달을 밟으며 자전거를 타려고 하나요? 다리 근육과 협응력이 새로운 단계에 들어섰어요! 안전한 곳에서 응원해 주세요.', title_nl = 'Driewieler 🚴‍♂️', body_nl = 'Probeert hij de pedalen in te trappen en te fietsen? Zijn beenspieren en coördinatie zitten in een nieuwe fase! Moedig hem aan op veilige plekken.', title_pl = 'Rowerek trójkołowy 🚴‍♂️', body_pl = 'Naciska pedały i próbuje jechać na rowerku? Mięśnie nóg i koordynacja weszły na nowy etap! Zachęcaj go w bezpiecznych miejscach.', title_pt = 'Triciclo 🚴‍♂️', body_pt = 'Carrega nos pedais e tenta andar de triciclo? Os músculos das pernas e a coordenação estão numa nova etapa! Incentive-o em locais seguros.', title_sv = 'Trehjuling 🚴‍♂️', body_sv = 'Försöker barnet trampa och cykla? Benmusklerna och koordinationen är i en ny fas! Uppmuntra barnet på säkra platser.', title_vi = 'Xe đạp ba bánh 🚴‍♂️', body_vi = 'Bé cố đạp bàn đạp để đi xe? Cơ chân và khả năng phối hợp đang bước sang giai đoạn mới! Hãy khuyến khích bé ở những nơi an toàn.', title_zh = '三轮车 🚴‍♂️', body_zh = '努力踩着踏板想骑车？腿部肌肉和协调能力进入了新阶段！在安全的地方多鼓励宝宝吧。' WHERE id = '23137ca6-6246-4dc7-b692-cdcd36eeac0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Bolsillos llenos de tesoros 🍁', body_es = '¿Habéis vuelto del parque y de su bolsillo han salido 3 piedras, 1 hoja seca y un palito? Para tu peque son tesoros valiosos. Tú solo intenta neutralizarlos antes de que acaben esparcidos por casa.', title_fr = 'Des poches pleines de trésors 🍁', body_fr = 'De retour du parc, vous trouvez dans sa poche 3 cailloux, 1 feuille sèche et une brindille ? Pour lui, ce sont des trésors précieux. Essayez simplement de les neutraliser avant qu''ils ne se retrouvent éparpillés dans toute la maison.', title_hi = 'खज़ाने से भरी जेबें 🍁', body_hi = 'पार्क से लौटीं और उसकी जेब से 3 पत्थर, 1 सूखा पत्ता और एक तिनका निकला? उसके लिए ये कीमती खज़ाना हैं। आप बस कोशिश कीजिए कि ये घर में बिखरें नहीं।', title_id = 'Kantong penuh harta karun 🍁', body_id = 'Pulang dari taman dan dari kantongnya keluar 3 batu, 1 daun kering, dan sebatang ranting? Baginya ini harta karun berharga. Tugas Anda hanya mengamankannya sebelum tersebar di seluruh rumah.', title_ja = '宝物でいっぱいのポケット 🍁', body_ja = '公園から帰ったら、ポケットから石が3つ、枯れ葉が1枚、小枝が1本？お子さんにとっては大切な宝物です。家じゅうに散らばらないよう、上手に「処理」しましょう。', title_ko = '주머니 가득 보물 🍁', body_ko = '공원에서 돌아왔더니 주머니에서 돌 3개, 마른 잎 하나, 나뭇가지가 나왔나요? 아이에게는 소중한 보물이에요. 집에 흩어지기 전에 안전하게 처리해 보세요.', title_nl = 'Zakken vol schatten 🍁', body_nl = 'Kwamen er na het park 3 steentjes, 1 verdord blad en een takje uit zijn zak? Voor hem zijn dat kostbare schatten. Probeer ze gewoon onschadelijk te maken voordat ze door het hele huis liggen.', title_pl = 'Kieszenie pełne skarbów 🍁', body_pl = 'Wróciliście z parku, a z jego kieszeni wypadły 3 kamyki, 1 suchy liść i patyk? Dla niego to cenne skarby. Ty po prostu spróbuj je unieszkodliwić, zanim rozsypią się po domu.', title_pt = 'Bolsos cheios de tesouros 🍁', body_pt = 'Voltaram do parque e do bolso dele saíram 3 pedras, 1 folha seca e um pauzinho? Para ele são tesouros preciosos. Tente só neutralizá-los antes que fiquem espalhados pela casa.', title_sv = 'Fickor fulla av skatter 🍁', body_sv = 'Ni kom hem från parken och ur fickan dök 3 stenar, 1 vissnat löv och en pinne upp? För barnet är det dyrbara skatter. Försök bara oskadliggöra dem innan de sprids över hela hemmet.', title_vi = 'Túi đầy kho báu 🍁', body_vi = 'Đi công viên về, trong túi bé có 3 viên sỏi, 1 chiếc lá khô và một que củi? Với bé đó là kho báu quý giá. Mẹ chỉ cần cố gắng "vô hiệu hóa" chúng trước khi bị rải khắp nhà.', title_zh = '装满宝藏的口袋 🍁', body_zh = '从公园回来，口袋里掏出3块石头、1片枯叶和一根小树枝？对宝宝来说，这些都是珍贵的宝藏。你只要想办法别让它们撒得满屋都是就好。' WHERE id = '10872122-03c1-4660-aabc-490c724034c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No busques lógica 👑', body_es = '¿Exige helado o la sopa de lentejas de ayer para desayunar? Hay un nuevo dictador en casa. Desvía su atención al momento dándole a elegir (por ejemplo: «¿Quieres manzana o plátano?»).', title_fr = 'Ne cherchez pas de logique 👑', body_fr = 'Il exige de la glace ou la soupe de lentilles d''hier au petit-déjeuner ? Un nouveau dictateur est dans la place. Détournez vite son attention en lui laissant le choix (par exemple : « Tu veux une pomme ou une banane ? »).', title_hi = 'तर्क मत ढूँढिए 👑', body_hi = 'नाश्ते में आइसक्रीम या कल का दाल का सूप माँगता है? कमरे में एक नया तानाशाह है। चुनने का हक देकर (जैसे: ''सेब चाहिए या केला?'') तुरंत उसका ध्यान भटकाइए।', title_id = 'Jangan mencari logika 👑', body_id = 'Ia menuntut es krim atau sup kacang lentil kemarin untuk sarapan? Ada diktator baru di rumah. Segera alihkan perhatiannya dengan memberi hak memilih (misalnya: ''Mau apel atau pisang?'').', title_ja = '理屈を探さないで 👑', body_ja = '朝ごはんにアイスクリームや昨日のレンズ豆スープを要求しますか？家に新しい独裁者がいます。選ばせてあげて（たとえば「りんごがいい？それともバナナ？」）、すぐに気をそらしましょう。', title_ko = '논리를 찾지 마세요 👑', body_ko = '아침으로 아이스크림이나 어제 먹은 렌틸 수프를 달라고 하나요? 방에 새로운 독재자가 나타났어요. ''사과 먹을래, 바나나 먹을래?''처럼 선택권을 주며 바로 관심을 돌려 보세요.', title_nl = 'Zoek geen logica 👑', body_nl = 'Eist hij ijs of de linzensoep van gisteren als ontbijt? Er is een nieuwe dictator in huis. Leid hem meteen af door hem te laten kiezen (bijvoorbeeld: ''Wil je een appel of een banaan?'').', title_pl = 'Nie szukaj logiki 👑', body_pl = 'Na śniadanie żąda lodów albo wczorajszej zupy z soczewicy? W pokoju jest nowy dyktator. Od razu odwróć jego uwagę, dając mu wybór (np. „Chcesz jabłko czy banana?”).', title_pt = 'Não procure lógica 👑', body_pt = 'Exige gelado ou a sopa de lentilhas de ontem ao pequeno-almoço? Há um novo ditador na sala. Dê-lhe o direito de escolha (por exemplo: "Queres maçã ou banana?") e desvie logo a atenção dele.', title_sv = 'Leta inte efter logik 👑', body_sv = 'Kräver barnet glass eller gårdagens linssoppa till frukost? Det finns en ny diktator i rummet. Avled genast tankarna genom att ge ett val (till exempel: ”Vill du ha äpple eller banan?”).', title_vi = 'Đừng tìm logic 👑', body_vi = 'Bé đòi ăn kem hay canh đậu lăng hôm qua cho bữa sáng? Nhà mình có một "nhà độc tài" mới. Hãy đánh lạc hướng ngay bằng cách cho bé quyền lựa chọn (ví dụ: "Con muốn táo hay chuối?").', title_zh = '别找道理 👑', body_zh = '早餐要吃冰淇淋，或者昨天的扁豆汤？家里来了一位新独裁者。给宝宝选择权（比如：“你想吃苹果还是香蕉？”），马上转移注意力。' WHERE id = '8f84e032-e8dd-4d1f-b3c6-5d57937006dd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Excusas para escapar de la cama 🏃‍♂️', body_es = 'Quiere agua, quiere ir al baño, quiere darle un beso a la cortina... Su cerebro inventa cosas nuevas para no dormirse. Pon límites: «Solo 1 vaso de agua y ya está». Sé firme.', title_fr = 'Les excuses pour fuir le lit 🏃‍♂️', body_fr = 'Il veut de l''eau, aller aux toilettes, embrasser le rideau de la chambre... Son cerveau invente sans cesse pour ne pas dormir. Fixez des limites : « Juste 1 verre d''eau et c''est fini. » Soyez ferme.', title_hi = 'बिस्तर से भागने के बहाने 🏃‍♂️', body_hi = 'पानी चाहिए, टॉयलेट जाना है, कमरे के पर्दे को चूमना है... न सोने के लिए उसका दिमाग नए-नए आविष्कार करता है। सीमा तय कीजिए: ''बस 1 गिलास पानी और बस।'' दृढ़ रहिए।', title_id = 'Alasan kabur dari kasur 🏃‍♂️', body_id = 'Ia minta air, ingin ke toilet, ingin mencium tirai kamar... Otaknya terus menciptakan alasan baru agar tidak tidur. Pasang batas: ''Hanya 1 gelas air, lalu selesai.'' Bersikaplah tegas.', title_ja = 'ベッドから逃げる言い訳 🏃‍♂️', body_ja = 'お水が飲みたい、トイレに行きたい、カーテンにキスしたい…眠らないために、脳が次々と新しい発明をします。区切りをつけましょう：「お水はコップ1杯だけ、それでおしまい」。ぶれずにいて。', title_ko = '침대 탈출 핑계 🏃‍♂️', body_ko = '물 마실래, 화장실 갈래, 커튼에 뽀뽀할래... 잠들지 않으려고 머리가 새로운 핑계를 발명해요. 한계를 정해 주세요: ''물 딱 한 잔, 그걸로 끝.'' 단호하게 해 주세요.', title_nl = 'Smoesjes om uit bed te komen 🏃‍♂️', body_nl = 'Hij wil water, moet naar de wc, wil het gordijn een kusje geven... Zijn hoofdje bedenkt steeds nieuwe uitvindingen om niet te hoeven slapen. Stel grenzen: ''Eén beker water en dan is het klaar.'' Wees vastberaden.', title_pl = 'Wymówki, by uciec z łóżka 🏃‍♂️', body_pl = 'Chce wody, chce do toalety, chce pocałować zasłonę... Jego mózg wymyśla nowe sposoby, by nie zasnąć. Ustal granice: „Tylko 1 kubek wody i koniec”. Bądź stanowcza.', title_pt = 'Desculpas para fugir da cama 🏃‍♂️', body_pt = 'Quer água, quer ir à casa de banho, quer dar um beijo à cortina... Para não adormecer, o cérebro dele faz novas invenções. Ponha limites: "Só 1 copo de água e acabou." Seja firme.', title_sv = 'Ursäkter för att slippa sängen 🏃‍♂️', body_sv = 'Barnet vill ha vatten, gå på toaletten, pussa gardinen... Hjärnan uppfinner nya saker för att slippa somna. Sätt gränser: ”Bara 1 glas vatten, sen är det slut.” Var bestämd.', title_vi = 'Những cái cớ để trốn khỏi giường 🏃‍♂️', body_vi = 'Bé đòi uống nước, đòi đi vệ sinh, đòi hôn cả tấm rèm... Não bé liên tục "phát minh" ra cớ để không phải ngủ. Hãy đặt giới hạn: "Chỉ 1 cốc nước thôi nhé". Hãy kiên quyết.', title_zh = '逃离床铺的借口 🏃‍♂️', body_zh = '要喝水，要上厕所，要亲亲房间的窗帘……为了不睡觉，大脑不断有新发明。定好界限：“只喝1杯水，就结束。”态度要坚决。' WHERE id = '907a5bc5-4a7e-48ec-977c-d9c5440faba0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Llamadas de negocios imaginarias 🍌', body_es = '¿Coge un plátano o el mando y habla muy en serio por teléfono en un idioma inventado? Copia al detalle tu lenguaje corporal. Grábalo en vídeo y guárdalo para el futuro, os vais a reír mucho.', title_fr = 'Appels d''affaires imaginaires 🍌', body_fr = 'Il prend une banane ou la télécommande et parle très sérieusement au téléphone dans une langue inventée ? Il copie parfaitement votre langage corporel. Filmez-le et gardez-le pour plus tard, vous rirez beaucoup.', title_hi = 'काल्पनिक बिज़नेस कॉल 🍌', body_hi = 'हाथ में केला या रिमोट लेकर किसी गढ़ी हुई भाषा में पूरी गंभीरता से फ़ोन पर बात करता है? वह आपकी शारीरिक भाषा की हूबहू नकल कर रहा है। इसका वीडियो बनाकर भविष्य के लिए सहेजिए, बहुत हँसेंगी।', title_id = 'Telepon bisnis khayalan 🍌', body_id = 'Ia memegang pisang atau remote dan menelepon dengan serius dalam bahasa karangannya? Ia meniru bahasa tubuh Anda dengan sempurna. Rekam videonya dan simpan untuk masa depan, Anda akan tertawa terbahak-bahak.', title_ja = '空想のビジネス電話 🍌', body_ja = 'バナナやリモコンを手に、作った言葉でまじめに電話していますか？あなたのしぐさをそっくりまねしています。動画に撮って未来のためにとっておきましょう、きっと大笑いできます。', title_ko = '상상 속 업무 통화 🍌', body_ko = '바나나나 리모컨을 들고 지어낸 언어로 진지하게 통화하나요? 엄마의 몸짓을 그대로 따라 하고 있어요. 영상으로 찍어 보관해 두세요. 나중에 엄청 웃게 될 거예요.', title_nl = 'Verzonnen zakelijke gesprekken 🍌', body_nl = 'Pakt hij een banaan of de afstandsbediening en praat hij in een verzonnen taal heel serieus ''aan de telefoon''? Hij kopieert jouw lichaamstaal precies. Film het en bewaar het voor later, jullie zullen erom lachen.', title_pl = 'Wyimaginowane rozmowy biznesowe 🍌', body_pl = 'Bierze banana albo pilota i z powagą rozmawia przez telefon w wymyślonym języku? Kopiuje dokładnie twoją mowę ciała. Nagraj to i zachowaj na przyszłość, będziecie się świetnie bawić.', title_pt = 'Chamadas de negócios imaginárias 🍌', body_pt = 'Pega numa banana ou no comando e fala muito a sério ao "telefone" numa língua inventada? Copia na perfeição a sua linguagem corporal. Filme e guarde para o futuro: vão rir-se muito.', title_sv = 'Låtsasaffärssamtal 🍌', body_sv = 'Tar barnet en banan eller fjärrkontrollen och pratar på fullt allvar i telefon på ett påhittat språk? Hen kopierar ditt kroppsspråk helt. Filma och spara för framtiden, ni kommer att skratta mycket.', title_vi = 'Những cuộc gọi công việc tưởng tượng 🍌', body_vi = 'Bé cầm quả chuối hay điều khiển TV và nghiêm túc "nói chuyện điện thoại" bằng một ngôn ngữ tự chế? Bé đang bắt chước y hệt ngôn ngữ cơ thể của mẹ. Hãy quay video lưu lại cho sau này, mẹ sẽ cười rất nhiều.', title_zh = '想象中的商务电话 🍌', body_zh = '拿着香蕉或遥控器，用自己编的语言一本正经地“打电话”？宝宝完全复制了你的肢体语言。录下来留给未来，以后会笑翻的。' WHERE id = '4699f7a7-a05a-4fb5-bcc3-1031cc990173' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se descoloca la rutina? ⏱️', body_es = '¿Tarda más de 1 hora en dormirse por la noche? Mira el gráfico del temporizador de sueño. Quizá sea el momento de quitar del todo la siesta y adelantar la hora de dormir.', title_fr = 'Le rythme se décale ? ⏱️', body_fr = 'L''endormissement du soir prend plus d''1 heure ? Regardez le graphique du Minuteur de sommeil. Il est peut-être temps de supprimer complètement la sieste et d''avancer l''heure du coucher.', title_hi = 'रूटीन खिसक रहा है? ⏱️', body_hi = 'शाम को सोने में 1 घंटे से ज़्यादा लगता है? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद को पूरी तरह खत्म करने और शाम का रूटीन जल्दी करने का समय आ गया है।', title_id = 'Rutinitas bergeser? ⏱️', body_id = 'Tidur malam butuh lebih dari 1 jam? Lihat grafik Timer Tidur. Mungkin sudah waktunya menghapus tidur siang sepenuhnya dan memajukan jam tidur malam.', title_ja = '生活リズムがずれている？⏱️', body_ja = '夜の寝かしつけに1時間以上かかりますか？睡眠タイマーのグラフを見てみましょう。お昼寝をすっかりやめて、夜の寝る時間を早める時期かもしれません。', title_ko = '일과가 밀리나요? ⏱️', body_ko = '저녁에 잠드는 데 1시간 넘게 걸리나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 완전히 없애고 잠자리 시간을 앞당길 때가 되었을지도 몰라요.', title_nl = 'Verschuift het ritme? ⏱️', body_nl = 'Duurt inslapen ''s avonds langer dan een uur? Bekijk het schema in de Slaaptimer. Misschien is het tijd om het middagslaapje helemaal te schrappen en de avond te vervroegen.', title_pl = 'Rytm dnia się przesuwa? ⏱️', body_pl = 'Wieczorne zasypianie trwa ponad 1 godzinę? Spójrz na wykres w timerze snu. Może czas całkowicie zrezygnować z drzemki w dzień i przesunąć wieczór na wcześniej.', title_pt = 'A rotina está a fugir? ⏱️', body_pt = 'Adormecer à noite demora mais de 1 hora? Veja o gráfico do temporizador de sono. Talvez esteja na altura de acabar de vez com a sesta e antecipar a hora de deitar.', title_sv = 'Glider rutinen iväg? ⏱️', body_sv = 'Tar det mer än 1 timme för barnet att somna på kvällen? Titta på sömntimerns diagram. Kanske är det dags att slopa dagsömnen helt och tidigarelägga kvällen.', title_vi = 'Nếp sinh hoạt bị lệch? ⏱️', body_vi = 'Buổi tối bé mất hơn 1 tiếng mới ngủ được? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đã đến lúc bỏ hẳn giấc ngủ ngày và cho bé đi ngủ tối sớm hơn.', title_zh = '作息乱了？⏱️', body_zh = '晚上入睡要花1个多小时？看看睡眠计时器的图表。也许是时候完全取消白天的午睡，把晚上的入睡时间提前了。' WHERE id = '77b18a3d-16c2-454b-9fe4-daea00f5a342' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cierra la boca en cuanto ve el cepillo de dientes? No conviertas la higiene en una guerra. Mira en Productos recomendados cepillos musicales y convierte esta rutina tan sufrida en un juego divertido.', body_fr = 'Il verrouille sa bouche dès qu''il voit la brosse à dents ? Ne transformez pas l''hygiène en guerre. Regardez les brosses musicales dans les Produits recommandés et faites de ce rituel pénible un jeu amusant.', body_hi = 'टूथब्रश देखते ही मुँह बंद कर लेता है? सफ़ाई को जंग मत बनाइए। सुझाए गए प्रोडक्ट में म्यूज़िकल ब्रश देखिए और इस मुश्किल रूटीन को मज़ेदार खेल में बदल दीजिए।', body_id = 'Begitu melihat sikat gigi, ia langsung mengatupkan mulut? Jangan jadikan kebersihan medan perang. Lihat sikat gigi bermusik di Produk Rekomendasi dan ubah rutinitas yang menyiksa ini menjadi permainan seru.', body_ja = '歯ブラシを見たとたん、口をぎゅっと閉じますか？歯みがきを戦いにしないで。「おすすめ商品」で音楽つき歯ブラシを見て、このつらいルーティンを楽しい遊びに変えましょう。', body_ko = '칫솔만 보면 입을 꾹 다무나요? 위생을 전쟁으로 만들지 마세요. 추천 제품에서 음악이 나오는 칫솔을 살펴보고 힘든 일과를 재미있는 놀이로 바꿔 보세요.', body_nl = 'Klemt hij zijn mond dicht als hij de tandenborstel ziet? Maak van poetsen geen strijd. Bekijk muzikale tandenborstels in Aanbevolen producten en maak van deze lastige routine een leuk spel.', body_pl = 'Na widok szczoteczki do zębów zaciska buzię? Nie zamieniaj higieny w wojnę. Zajrzyj do Polecanych produktów po grające szczoteczki i zamień tę męczącą rutynę w wesołą zabawę.', body_pt = 'Fecha a boca mal vê a escova de dentes? Não transforme a higiene numa guerra. Veja as escovas com música nos Produtos Recomendados e transforme esta rotina sofrida numa brincadeira divertida.', body_sv = 'Låser barnet munnen när hen ser tandborsten? Gör inte hygienen till ett krig. Titta på tandborstar med musik i Rekommenderade produkter och gör den plågsamma rutinen till en rolig lek.', body_vi = 'Vừa thấy bàn chải là bé ngậm chặt miệng? Đừng biến việc vệ sinh thành cuộc chiến. Hãy xem các loại bàn chải có nhạc trong Sản phẩm gợi ý để biến nếp sinh hoạt "cực hình" này thành trò chơi vui nhộn.', body_zh = '一看到牙刷就紧闭嘴巴？别把清洁变成一场战争。去推荐商品看看音乐牙刷，把这个痛苦的日常变成有趣的游戏。' WHERE id = '9ed1ae4d-be3f-4fb2-a1fd-f7b060b22469' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tozudez del «Mis piernas no funcionan» 🛑', body_es = '¿Volviendo del parque se sienta de repente en el suelo y pide brazos porque «sus piernas no funcionan»? No es cansancio, es manipulación. Conviértelo en un juego: «¿A ver si llegas a casa saltando como un conejo?».', title_fr = 'L''entêtement du « Mes jambes marchent plus » 🛑', body_fr = 'En rentrant du parc, il s''assoit soudain par terre en disant « Mes jambes marchent plus » et réclame les bras ? Ce n''est pas de la fatigue, c''est de la manipulation. Faites-en un jeu : « Voyons si tu peux sauter comme un lapin jusqu''à la maison ? »', title_hi = '''मेरे पैर नहीं चलते'' वाली ज़िद 🛑', body_hi = 'पार्क से लौटते समय अचानक ज़मीन पर बैठकर कहता है ''मेरे पैर नहीं चलते'' और गोद माँगता है? यह थकान नहीं, चालाकी है। ''देखें, क्या तुम खरगोश की तरह कूदते हुए घर तक पहुँच सकते हो?'' कहकर इसे खेल बना दीजिए।', title_id = 'Ngotot ''Kakiku tidak bisa jalan'' 🛑', body_id = 'Pulang dari taman, tiba-tiba ia duduk di tanah, bilang kakinya tidak bisa jalan, dan minta digendong? Ini bukan lelah, tetapi manipulasi. Jadikan permainan: ''Coba lihat, bisa lompat seperti kelinci sampai rumah?''', title_ja = '「足が動かない」のがんばり 🛑', body_ja = '公園からの帰り道、急に座りこんで「足が動かない」と抱っこをせがみますか？これは疲れではなく、駆け引きです。「おうちまでうさぎみたいにぴょんぴょんできるかな？」と遊びに変えましょう。', title_ko = '''다리가 안 움직여'' 고집 🛑', body_ko = '공원에서 돌아오는 길에 갑자기 주저앉아 ''다리가 안 움직여'' 하며 안아 달라고 하나요? 피곤해서가 아니라 작전이에요. ''집까지 토끼처럼 깡충깡충 갈 수 있을까?'' 하며 놀이로 바꿔 보세요.', title_nl = 'Koppig: ''Mijn benen doen het niet'' 🛑', body_nl = 'Gaat hij op weg terug van het park ineens op de grond zitten en wil hij gedragen worden omdat zijn ''benen het niet doen''? Dat is geen vermoeidheid, maar manipulatie. Maak er een spel van: ''Zullen we kijken of je als een konijn naar huis kunt springen?''', title_pl = 'Upór „Nogi mi nie działają” 🛑', body_pl = 'W drodze z parku nagle siada na ziemi, mówi „Nogi mi nie działają” i chce na ręce? To nie zmęczenie, to manipulacja. Zamień to w zabawę: „Zobaczymy, czy doskaczesz do domu jak zajączek?”.', title_pt = 'A teimosia do "As minhas pernas não funcionam" 🛑', body_pt = 'No regresso do parque, senta-se de repente no chão, diz que as pernas não funcionam e pede colo? Não é cansaço, é manipulação. Transforme isto num jogo: "Vamos ver se consegues ir aos saltos como um coelho até casa?"', title_sv = 'Envisheten i ”Mina ben fungerar inte” 🛑', body_sv = 'Sätter sig barnet plötsligt på marken på väg hem från parken, säger ”mina ben fungerar inte” och vill bli buren? Det är inte trötthet, det är manipulation. Gör det till en lek: ”Ska vi se om du kan hoppa som en kanin hela vägen hem?”', title_vi = 'Sự bướng bỉnh "Chân con không đi được" 🛑', body_vi = 'Trên đường từ công viên về, bé bỗng ngồi phịch xuống và nói "Chân con không đi được" để đòi bế? Đây không phải mệt mà là một chiêu thao túng. Hãy biến thành trò chơi: "Xem con có nhảy như thỏ về đến nhà được không nào?"', title_zh = '“我的腿走不动了”的倔强 🛑', body_zh = '从公园回来的路上，突然坐在地上说“我的腿走不动了”，要你抱？这不是累，而是小小的“操控”。说一句“看看你能不能像小兔子一样一路跳回家？”，把它变成游戏吧。' WHERE id = '3d5dc682-22fb-45d2-8bc6-6a1ae9873a3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escondite con el orinal 🚽', body_es = '¿Cuando tiene ganas de ir al baño se esconde detrás de la cortina o junto al sofá? Es el momento perfecto para entrar en el Blog y leer los pasos con base científica para empezar a dejar el pañal.', title_fr = 'Cache-cache avec le pot 🚽', body_fr = 'Quand il a envie d''aller aux toilettes, il se cache derrière le rideau ou au bord du canapé ? C''est le bon moment pour lire dans la rubrique Blogs les étapes scientifiques pour commencer l''apprentissage du pot.', title_hi = 'पॉटी वाली छुपन-छुपाई 🚽', body_hi = 'टॉयलेट जाने की ज़रूरत होने पर पर्दे के पीछे या सोफ़े के कोने में छिप जाता है? ब्लॉग सेक्शन में जाकर पॉटी ट्रेनिंग शुरू करने के वैज्ञानिक कदम पढ़ने का यही सही समय है।', title_id = 'Petak umpet pispot 🚽', body_id = 'Saat ingin buang air, ia bersembunyi di balik tirai atau di samping sofa? Inilah saat yang tepat membuka bagian Blog dan membaca langkah ilmiah memulai latihan pispot.', title_ja = 'おまるのかくれんぼ 🚽', body_ja = 'トイレに行きたいとき、カーテンの後ろやソファのかげに隠れますか？ブログを開いて、トイレトレーニングの科学的な始め方を読むのにちょうどいいタイミングです。', title_ko = '아기 변기 숨바꼭질 🚽', body_ko = '화장실이 급할 때 커튼 뒤나 소파 옆에 숨나요? 블로그 섹션에서 배변 훈련을 시작하는 과학적인 단계를 읽어 볼 딱 좋은 때예요.', title_nl = 'Verstoppertje met het potje 🚽', body_nl = 'Verstopt hij zich achter het gordijn of naast de bank als hij moet? Dit is het perfecte moment om in Blogs de wetenschappelijke stappen te lezen om met zindelijkheidstraining te beginnen.', title_pl = 'Chowany z nocnikiem 🚽', body_pl = 'Gdy chce mu się do toalety, chowa się za zasłoną albo za kanapą? To najlepszy moment, by zajrzeć do sekcji Blog i przeczytać o naukowych krokach rozpoczęcia nauki korzystania z nocnika.', title_pt = 'Escondidas com o bacio 🚽', body_pt = 'Quando precisa de ir à casa de banho, esconde-se atrás da cortina ou ao lado do sofá? É mesmo a altura de abrir o Blogue e ler os passos científicos para começar o treino do bacio.', title_sv = 'Kurragömma med pottan 🚽', body_sv = 'Gömmer sig barnet bakom gardinen eller vid soffan när hen behöver gå på toaletten? Nu är det verkligen dags att gå till avsnittet Bloggar och läsa de vetenskapliga stegen för hur du börjar med pottträning.', title_vi = 'Trốn tìm với bô 🚽', body_vi = 'Khi buồn đi vệ sinh, bé trốn sau rèm cửa hoặc góc sofa? Đây đúng là lúc đọc trong mục Blog các bước khoa học để bắt đầu tập ngồi bô.', title_zh = '便盆躲猫猫 🚽', body_zh = '想上厕所时，就躲到窗帘后面或沙发边上？现在正是去博客板块读读如何科学地开始如厕训练的好时机。' WHERE id = 'b948ea64-f471-4d36-958a-85e04a0250f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desahogarse en el diario 📝', body_es = '¿Alguien te ha dicho «Si estás en casa, ¿de qué te cansas?»? Abre ya el Diario de ánimo y vuelca con los dedos todo tu enfado en la pantalla. Es mejor escribir lo que de verdad sientes que fingir una sonrisa.', title_fr = 'Vider son sac dans le journal 📝', body_fr = 'Quelqu''un vous a dit « Tu es à la maison, de quoi tu es fatiguée ? » ? Ouvrez tout de suite le Journal d''humeur et déversez toute votre colère sur l''écran. Mieux vaut écrire vos vraies émotions que sourire de façon forcée.', title_hi = 'डायरी में गुबार निकालिए 📝', body_hi = 'किसी ने आपसे कहा ''घर पर ही तो हो, किस बात की थकान''? तुरंत मूड डायरी खोलिए और अपना सारा गुस्सा उँगलियों से स्क्रीन पर उतार दीजिए। नकली मुस्कान से बेहतर है अपनी असली भावनाएँ लिखना।', title_id = 'Meluapkan kesal di buku harian 📝', body_id = 'Seseorang berkata ''Kamu kan di rumah saja, capek apanya''? Segera buka Buku Harian Suasana Hati dan tumpahkan semua kekesalan Anda ke layar lewat jari-jari Anda. Menulis perasaan yang sebenarnya lebih baik daripada senyum palsu.', title_ja = '日記でうっぷん晴らし 📝', body_ja = '「家にいるだけなのに、なんで疲れるの？」と言われましたか？すぐに「気分日記」を開いて、イライラを全部指先から画面に吐き出しましょう。作り笑いより、本当の気持ちを書くほうがずっといいです。', title_ko = '일기에 속풀이하기 📝', body_ko = '누가 ''집에 있으면서 뭐가 그렇게 힘들어?''라고 했나요? 바로 기분 일기를 열고 쌓인 화를 손끝으로 모두 쏟아 내세요. 억지 미소보다 진짜 감정을 적는 게 훨씬 나아요.', title_nl = 'Je boosheid kwijt in je dagboek 📝', body_nl = 'Zei iemand ''Je bent toch thuis, waar ben je moe van?'' Open meteen je Stemmingsdagboek en tik al je frustratie van je af. Je echte gevoelens opschrijven is beter dan geforceerd glimlachen.', title_pl = 'Wyrzuć złość w dzienniku 📝', body_pl = 'Ktoś ci powiedział: „Siedzisz w domu, czym się tak męczysz?”. Od razu otwórz Dziennik nastroju i wylej całą złość palcami na ekran. Lepiej zapisać prawdziwe uczucia, niż się sztucznie uśmiechać.', title_pt = 'Desabafar no diário 📝', body_pt = 'Alguém lhe disse "Estás em casa, de que te cansas?"? Abra já o Diário de Humor e deite toda a raiva para o ecrã com os dedos. Mais vale escrever o que sente de verdade do que sorrir à força.', title_sv = 'Avreagera dig i dagboken 📝', body_sv = 'Sa någon ”Du är ju hemma, vad är du trött för?”? Öppna direkt Humördagboken och häll ut all ilska på skärmen med fingrarna. Att skriva ner dina verkliga känslor är bättre än ett påklistrat leende.', title_vi = 'Trút giận vào nhật ký 📝', body_vi = 'Có ai đó nói với mẹ "Ở nhà thì có gì mà mệt"? Hãy mở ngay Nhật ký tâm trạng và trút hết bực bội lên màn hình. Viết ra cảm xúc thật tốt hơn là gượng cười.', title_zh = '在日记里出出气 📝', body_zh = '有人对你说“你不就是在家吗，有什么累的”？马上打开心情日记，用手指把所有的火气都倒在屏幕上。比起假笑，写下真实的感受要好得多。' WHERE id = 'b9e8fff7-f7f2-410b-a103-f4cd6c6231f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El show de cuentos de papá 📖', body_es = 'Esta noche la voz de la habitación no será la tuya, sino la de papá. Que lea él el cuento y le dé gracia poniendo voces graves y agudas a los personajes. Tú quédate a un lado y escucha las risas.', title_fr = 'Le show des contes de papa 📖', body_fr = 'Ce soir, dans la chambre, ce n''est pas votre voix qu''on entendra, mais celle de papa. Qu''il lise l''histoire en prenant des voix graves ou aiguës pour faire rire. Vous, restez à l''écart et écoutez les rires.', title_hi = 'पापा का कहानी शो 📖', body_hi = 'आज शाम कमरे में आवाज़ आपकी नहीं, पापा की होगी। कहानी वे पढ़ें, किरदारों की आवाज़ कभी भारी, कभी पतली करके मज़ा लाएँ। और आप एक तरफ़ खड़ी होकर हँसी सुनिए।', title_id = 'Pertunjukan dongeng Ayah 📖', body_id = 'Malam ini suara di kamar bukan milik Anda, tetapi milik Ayah. Biar ia yang membacakan dongeng dan membuat lelucon dengan membesarkan dan mengecilkan suara para tokoh. Anda menepilah dan dengarkan tawa mereka.', title_ja = 'パパのお話ショー 📖', body_ja = '今夜、部屋に響くのはあなたではなくパパの声。お話はパパに読んでもらい、キャラクターの声を太くしたり細くしたりして笑わせてもらいましょう。あなたは少し離れて、笑い声に耳を傾けて。', title_ko = '아빠의 동화 쇼 📖', body_ko = '오늘 저녁 방 안의 목소리는 엄마가 아니라 아빠 차례예요. 아빠가 동화를 읽으며 등장인물 목소리를 굵게, 가늘게 바꿔 웃음을 주게 하세요. 엄마는 옆에서 웃음소리를 즐기세요.', title_nl = 'Papa''s sprookjesshow 📖', body_nl = 'Vanavond klinkt in de kamer niet jouw stem, maar die van papa. Laat hem voorlezen en de helden grappige zware en hoge stemmetjes geven. Ga jij aan de zijkant staan en luister naar het gelach.', title_pl = 'Bajkowe show taty 📖', body_pl = 'Dziś wieczorem w pokoju nie będzie słychać twojego głosu, tylko taty. Niech on czyta bajkę i bawi, pogrubiając i wyostrzając głosy bohaterów. A ty stań z boku i słuchaj śmiechu.', title_pt = 'O espetáculo de histórias do pai 📖', body_pt = 'Esta noite, a voz no quarto não vai ser a sua, vai ser a do pai. Ele lê a história e faz as vozes das personagens mais graves ou mais finas, para ficar cómico. A mãe fica à parte a ouvir as gargalhadas.', title_sv = 'Pappas sagoshow 📖', body_sv = 'I kväll är det inte din röst som hörs i rummet, utan pappas. Låt honom läsa sagan och göra hjältarnas röster mörka och ljusa för att skapa komik. Stå du en bit bort och lyssna på skratten.', title_vi = 'Màn kể chuyện của bố 📖', body_vi = 'Tối nay giọng nói vang lên trong phòng sẽ không phải của mẹ mà là của bố. Để bố đọc truyện, giả giọng nhân vật lúc trầm lúc bổng thật hài hước. Còn mẹ đứng một bên lắng nghe tiếng cười.', title_zh = '爸爸的故事秀 📖', body_zh = '今晚房间里的声音不是你的，而是爸爸的。让他来读故事，把角色的声音一会儿变粗一会儿变细，制造笑点。你就在一旁听着笑声吧。' WHERE id = '0de1aee1-4ccd-4daa-b9f3-ed4d6ab70bfc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El chocolate secreto de mamá 🍫', body_es = 'Mamá que en cuanto tu peque se da la vuelta te metes un trozo de chocolate en la boca y lo masticas a toda prisa: esa glucosa es tu derecho más natural. Necesitas recargar para aguantar todo el día esa energía.', title_fr = 'Le chocolat secret de maman 🍫', body_fr = 'Maman qui glisse un carré de chocolat dans sa bouche et le mâche à toute vitesse dès que l''enfant a le dos tourné : ce glucose, c''est votre droit le plus naturel. Vous devez vous recharger pour tenir face à cette énergie toute la journée.', title_hi = 'माँ की छिपी चॉकलेट 🍫', body_hi = 'बच्चे के मुड़ते ही मुँह में चॉकलेट का टुकड़ा डालकर जल्दी-जल्दी चबाने वाली माँ, वह ग्लूकोज़ आपका सबसे स्वाभाविक हक है। दिनभर उस ऊर्जा को झेलने के लिए आपको चार्ज होना ही चाहिए।', title_id = 'Cokelat rahasia Ibu 🍫', body_id = 'Ibu yang begitu anak berbalik langsung memasukkan sepotong cokelat ke mulut dan mengunyahnya cepat-cepat, glukosa itu adalah hak paling alami Anda. Untuk bertahan menghadapi energi itu seharian, Anda harus mengisi ulang tenaga.', title_ja = 'ママの秘密のチョコレート 🍫', body_ja = 'お子さんが背を向けたすきに、チョコレートをひとかけら口に放りこんで急いでかむママ、その糖分はあなたのいちばん自然な権利です。一日じゅうあのエネルギーに付き合うには、充電が必要です。', title_ko = '엄마의 비밀 초콜릿 🍫', body_ko = '아이가 등을 돌리자마자 초콜릿 한 조각을 입에 넣고 재빨리 씹는 엄마, 그 당분은 엄마의 당연한 권리예요. 하루 종일 그 에너지를 감당하려면 충전이 필요해요.', title_nl = 'Mama''s geheime chocola 🍫', body_nl = 'Mama die snel een stukje chocola in haar mond stopt zodra hij zich omdraait: die suiker is je natuurlijke recht. Je moet opladen om de hele dag die energie bij te houden.', title_pl = 'Tajna czekolada mamy 🍫', body_pl = 'Mamo, która gdy tylko dziecko się odwróci, wrzucasz do buzi kawałek czekolady i szybko go przeżuwasz: ta glukoza to twoje najbardziej naturalne prawo. Musisz się naładować, by przez cały dzień wytrzymać tę energię.', title_pt = 'O chocolate secreto da mãe 🍫', body_pt = 'Mãe que mete um pedaço de chocolate à boca e mastiga à pressa mal a criança se vira: essa glicose é um direito seu. Precisa de recarregar para aguentar aquela energia o dia todo.', title_sv = 'Mammas hemliga choklad 🍫', body_sv = 'Mamma som stoppar en chokladbit i munnen och tuggar snabbt så fort barnet vänder ryggen till, den glukosen är din mest naturliga rättighet. Du behöver laddas för att stå ut med den energin hela dagen.', title_vi = 'Thanh sô-cô-la bí mật của mẹ 🍫', body_vi = 'Gửi người mẹ vừa thấy bé quay lưng đã vội bỏ một miếng sô-cô-la vào miệng và nhai thật nhanh: lượng đường ấy là quyền tự nhiên nhất của mẹ. Mẹ cần nạp năng lượng để theo kịp bé cả ngày.', title_zh = '妈妈的秘密巧克力 🍫', body_zh = '孩子一转身就往嘴里塞一块巧克力飞快嚼完的妈妈，这点葡萄糖是你最天然的权利。为了扛住一整天的那股能量，你得充充电。' WHERE id = '2fc731d4-47df-4b97-8f67-c7df6aabac96' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un mejor amigo muy peculiar 🥄', body_es = '¿Con tantos juguetes caros, ha encontrado una espátula de silicona en la cocina y se pasa el día paseándola y acostándola? El cerebro de un niño es increíble. No intervengas, deja que quiera a su espátula.', title_fr = 'Un drôle de meilleur ami 🥄', body_fr = 'Avec tous ces jouets coûteux, il a trouvé une spatule en silicone dans la cuisine et la promène toute la journée, il la fait même dormir ? Le cerveau d''un enfant est incroyable. Ne l''en empêchez pas, laissez-le aimer sa spatule.', title_hi = 'अनोखा सबसे अच्छा दोस्त 🥄', body_hi = 'इतने महँगे खिलौनों के बावजूद रसोई से एक सिलिकॉन स्पैचुला ढूँढ लाया और दिनभर उसे लेकर घूमता है, उसे सुलाता है? बच्चे का दिमाग अद्भुत है। मत रोकिए, उसे स्पैचुला से प्यार करने दीजिए।', title_id = 'Sahabat terbaik yang aneh 🥄', body_id = 'Padahal ada begitu banyak mainan mahal, ia malah menemukan spatula silikon di dapur, membawanya ke mana-mana seharian, bahkan menidurkannya? Otak anak sungguh menakjubkan. Jangan halangi, biarkan ia menyayangi spatulanya.', title_ja = 'ふしぎな親友 🥄', body_ja = '高いおもちゃがたくさんあるのに、キッチンからシリコンのへらを見つけて、一日じゅう持ち歩いて寝かしつけていますか？子どもの脳は驚くべきもの。じゃまをせず、へらを好きにさせてあげましょう。', title_ko = '별난 단짝 친구 🥄', body_ko = '비싼 장난감이 그렇게 많은데 주방에서 실리콘 주걱을 찾아 하루 종일 들고 다니며 재우기까지 하나요? 아이의 머릿속은 정말 놀라워요. 방해하지 말고 주걱을 사랑하게 두세요.', title_nl = 'Vreemde beste vriend 🥄', body_nl = 'Al dat dure speelgoed, en hij vindt een siliconen spatel in de keuken en sjouwt er de hele dag mee rond en legt hem zelfs te slapen? Een kinderbrein is ongelooflijk. Stoor hem niet, laat hem lekker van zijn spatel houden.', title_pl = 'Dziwny najlepszy przyjaciel 🥄', body_pl = 'Ma tyle drogich zabawek, a znalazł w kuchni silikonową łopatkę i cały dzień z nią chodzi, a nawet ją usypia? Dziecięcy mózg jest niesamowity. Nie przeszkadzaj, niech kocha swoją łopatkę.', title_pt = 'Um melhor amigo estranho 🥄', body_pt = 'Com tantos brinquedos caros, foi buscar uma espátula de silicone à cozinha e anda com ela o dia todo, até a põe a dormir? O cérebro de uma criança é incrível. Não interfira, deixe-o gostar da espátula.', title_sv = 'En märklig bästis 🥄', body_sv = 'Trots alla dyra leksaker har barnet hittat en silikonslickepott i köket, går omkring med den hela dagen och nattar den? Barnhjärnan är otrolig. Hindra inte, låt barnet älska sin slickepott.', title_vi = 'Người bạn thân kỳ lạ 🥄', body_vi = 'Có biết bao đồ chơi đắt tiền, vậy mà bé tìm được chiếc thìa silicon trong bếp, mang theo cả ngày và còn ru nó ngủ? Trí óc trẻ con thật khó tin. Đừng ngăn bé, cứ để bé yêu chiếc thìa ấy.', title_zh = '奇怪的好朋友 🥄', body_zh = '明明有那么多昂贵的玩具，宝宝却从厨房找来一把硅胶铲，整天带着它到处走，还哄它睡觉？孩子的大脑真是不可思议。别阻止，就让宝宝爱这把铲子吧。' WHERE id = 'edb08c0a-b151-4f7a-9713-c903f3f5c584' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Búsqueda en la naturaleza ⛅', body_es = 'Las cuatro paredes te han dejado la mente adormecida. Consulta Tiempo y ropa y elige el conjunto adecuado. Salid fuera con la misión de buscar hojas amarillas: tu peque suelta energía y tú respiras.', title_fr = 'Exploration nature ⛅', body_fr = 'Les quatre murs vous engourdissent le cerveau. Consultez Météo et tenue et choisissez la bonne tenue. Sortez avec une seule mission, trouver des feuilles jaunes : il se défoulera et vous respirerez.', title_hi = 'प्रकृति की खोज ⛅', body_hi = 'चार दीवारों ने दिमाग सुन्न कर दिया है? मौसम और कपड़े टूल देखकर सबसे सही कपड़े चुनिए। बाहर निकलिए और बस पीले पत्ते ढूँढने के मिशन से उसकी ऊर्जा भी निकालिए और खुद भी चैन की साँस लीजिए।', title_id = 'Menjelajah alam ⛅', body_id = 'Empat dinding membuat otak Anda kaku. Cek cuaca dan pilih setelan yang paling tepat. Keluarlah dengan misi sederhana mencari daun kuning, salurkan energinya sekaligus hirup udara segar untuk diri Anda.', title_ja = '自然の宝さがし ⛅', body_ja = '家にこもって頭がぼんやり？「天気と服装」を確認して、いちばんいいコーディネートを選びましょう。外に出て「黄色い葉っぱ探し」のミッションで、お子さんのエネルギーを発散させ、あなたもひと息ついて。', title_ko = '자연 탐험 ⛅', body_ko = '네 벽 안에서 머리가 멍해졌나요? 날씨와 옷차림을 보고 가장 알맞은 옷을 고르세요. ''노란 나뭇잎 찾기'' 임무를 들고 밖에 나가면 아이는 에너지를 쓰고 엄마는 숨을 돌릴 수 있어요.', title_nl = 'Op zoek in de natuur ⛅', body_nl = 'De vier muren maken je hoofd suf. Kijk in Weer en kleding en kies de beste outfit. Ga naar buiten met de missie om gele blaadjes te zoeken: hij raakt zijn energie kwijt en jij kunt even ademen.', title_pl = 'Poszukiwania w przyrodzie ⛅', body_pl = 'Cztery ściany otępiły ci głowę. Sprawdź Pogodę i ubiór i wybierz najlepszy zestaw. Wyjdźcie na zewnątrz z misją znalezienia żółtych liści: on spali energię, a ty złapiesz oddech.', title_pt = 'À procura da natureza ⛅', body_pt = 'As quatro paredes adormeceram-lhe o cérebro. Veja o Tempo e Roupa e escolha a combinação certa. Saiam com a missão de encontrar folhas amarelas: ele gasta energia e a mãe respira.', title_sv = 'Naturjakt ⛅', body_sv = 'De fyra väggarna har bedövat hjärnan. Kolla Väder och kläder och välj rätt klädsel. Gå ut med uppdraget att hitta gula löv, så får barnet göra av med energin och du får andas.', title_vi = 'Đi tìm thiên nhiên ⛅', body_vi = 'Bốn bức tường khiến đầu óc mẹ tê liệt. Hãy xem Thời tiết và trang phục để chọn cách phối đồ phù hợp nhất. Ra ngoài với nhiệm vụ đi tìm lá vàng, vừa để bé xả năng lượng vừa để mẹ được hít thở.', title_zh = '大自然寻宝 ⛅', body_zh = '四面墙让你的大脑都麻木了。看看天气穿衣工具，选好最合适的搭配。出门去执行“寻找黄叶子”的任务，既释放宝宝的精力，你也能透透气。' WHERE id = '36ebb286-2e4d-4e44-a91d-6c026199737c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Palabras peligrosas 🤐', body_es = '¿Te repite riéndose esa palabrota que ha oído en algún sitio y espera tu reacción? Tu mejor arma es no reaccionar. No te rías ni te enfades, simplemente ignóralo. Se le olvidará.', title_fr = 'Mots dangereux 🤐', body_fr = 'Il vous répète en riant ce gros mot entendu quelque part et attend votre réaction ? Votre meilleure arme, c''est l''absence de réaction. Ne riez pas, ne vous énervez pas, ignorez simplement. Il oubliera.', title_hi = 'खतरनाक शब्द 🤐', body_hi = 'कहीं से सुना कोई बुरा शब्द हँसते हुए आपके सामने दोहराता है और आपकी प्रतिक्रिया का इंतज़ार करता है? आपका सबसे बड़ा हथियार है कोई प्रतिक्रिया न देना। न हँसिए, न गुस्सा कीजिए, बस अनदेखा कीजिए। वह भूल जाएगा।', title_id = 'Kata-kata berbahaya 🤐', body_id = 'Ia mengulangi kata kasar yang entah didengar dari mana sambil tertawa dan menunggu reaksi Anda? Senjata terbesar Anda adalah tidak bereaksi. Jangan tertawa, jangan marah, abaikan saja. Ia akan lupa.', title_ja = '危険な言葉 🤐', body_ja = 'どこかで聞いた悪い言葉を、笑いながらくり返して反応を待っていますか？いちばんの武器は反応しないこと。笑わず、怒らず、ただ聞き流しましょう。そのうち忘れます。', title_ko = '위험한 단어 🤐', body_ko = '어디선가 들은 나쁜 말을 웃으며 따라 하고 엄마의 반응을 기다리나요? 가장 큰 무기는 무반응이에요. 웃지도 화내지도 말고 그냥 못 들은 척하세요. 곧 잊을 거예요.', title_nl = 'Gevaarlijke woorden 🤐', body_nl = 'Herhaalt hij lachend een lelijk woord dat hij ergens heeft gehoord en wacht hij op je reactie? Je grootste wapen is niet reageren. Lach niet, word niet boos, negeer het gewoon. Hij vergeet het wel.', title_pl = 'Niebezpieczne słowa 🤐', body_pl = 'Ze śmiechem powtarza ci brzydkie słowo, które gdzieś usłyszał, i czeka na twoją reakcję? Twoja największa broń to brak reakcji. Nie śmiej się, nie złość się, po prostu to zignoruj. Zapomni.', title_pt = 'Palavras perigosas 🤐', body_pt = 'Repete-lhe a rir aquela palavra feia que ouviu algures e espera pela sua reação? A sua maior arma é não reagir. Não se ria, não se zangue, ignore simplesmente. Ele esquece.', title_sv = 'Farliga ord 🤐', body_sv = 'Upprepar barnet skrattande ett fult ord som hen hört någonstans och väntar på din reaktion? Ditt största vapen är att inte reagera. Skratta inte, bli inte arg, låtsas bara inte om det. Barnet glömmer det.', title_vi = 'Những từ ngữ nguy hiểm 🤐', body_vi = 'Bé cười và nhắc lại với mẹ một từ xấu nghe được ở đâu đó rồi chờ phản ứng? Vũ khí lớn nhất của mẹ là không phản ứng. Đừng cười, đừng nổi giận, cứ phớt lờ. Bé sẽ quên thôi.', title_zh = '危险的词语 🤐', body_zh = '不知从哪儿听来一个脏词，笑着对你重复，还等着看你的反应？你最大的武器就是没反应。别笑，别生气，装作没听见就好。宝宝会忘掉的。' WHERE id = '4b98ee52-d8a1-4d7a-9183-64cdd8482ef0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La medida del silencio de oro 🤫', body_es = '¡Por fin se ha dormido! Activa el Medidor de sonido y mira en la pantalla el nivel de ruido absoluto de la habitación (0-10 decibelios). Ver estas cifras es el mejor masaje para el cerebro de una madre cansada.', title_fr = 'Mesurer le silence d''or 🤫', body_fr = 'Il s''est enfin endormi ! Activez le Sonomètre et regardez sur l''écran le niveau sonore de la pièce (0 à 10 décibels). Voir ces chiffres, c''est le meilleur massage pour le cerveau d''une maman fatiguée.', title_hi = 'सुनहरी खामोशी का माप 🤫', body_hi = 'आखिरकार वह सो गया! साउंड मीटर टूल चालू कीजिए और स्क्रीन पर कमरे का आवाज़ का स्तर (0-10 डेसिबल) देखिए। ये अंक देखना थकी हुई माँ के दिमाग के लिए सबसे अच्छी मालिश है।', title_id = 'Ukuran hening emas 🤫', body_id = 'Ia akhirnya tertidur! Aktifkan Pengukur Suara dan lihat tingkat suara kamar yang benar-benar sunyi (0-10 desibel) di layar. Melihat angka-angka ini adalah pijatan terbaik bagi otak ibu yang lelah.', title_ja = '金色の静けさを測る 🤫', body_ja = 'やっと眠りました！「サウンドメーター」をオンにして、部屋の完全な音のレベル（0〜10デシベル）を画面で見てみましょう。この数字を見るのは、疲れたママの頭へのいちばんのマッサージです。', title_ko = '황금 같은 고요의 크기 🤫', body_ko = '드디어 잠들었어요! 소음 측정기를 켜고 방의 소리 수준(0~10데시벨)을 화면으로 확인해 보세요. 그 숫자를 보는 것만으로도 지친 엄마의 머리에는 최고의 마사지예요.', title_nl = 'De maat van gouden stilte 🤫', body_nl = 'Hij slaapt eindelijk! Zet de Geluidsmeter aan en bekijk het geluidsniveau in de kamer (0-10 decibel) op het scherm. Die getallen zien is de beste massage voor het hoofd van een vermoeide moeder.', title_pl = 'Miara złotej ciszy 🤫', body_pl = 'W końcu zasnął! Włącz Miernik dźwięku i obserwuj na ekranie absolutny poziom hałasu w pokoju (0-10 decybeli). Widok tych liczb to najlepszy masaż dla głowy zmęczonej mamy.', title_pt = 'A medida do silêncio de ouro 🤫', body_pt = 'Finalmente adormeceu! Ative o Medidor de Som e veja no ecrã o nível de som absoluto do quarto (0-10 decibéis). Ver estes números é a melhor massagem para o cérebro de uma mãe cansada.', title_sv = 'Mätt gyllene tystnad 🤫', body_sv = 'Barnet har äntligen somnat! Aktivera Ljudmätaren och följ rummets absoluta ljudnivå (0-10 decibel) på skärmen. Att se de siffrorna är den bästa massagen för en trött mammas hjärna.', title_vi = 'Thước đo sự tĩnh lặng quý như vàng 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Hãy bật công cụ Đo âm thanh và theo dõi mức âm thanh tuyệt đối trong phòng (0-10 decibel) trên màn hình. Nhìn những con số này là liệu pháp mát-xa tốt nhất cho tâm trí của người mẹ mệt mỏi.', title_zh = '金色安静的度量 🤫', body_zh = '宝宝终于睡着了！打开分贝仪，在屏幕上看看房间的绝对音量（0到10分贝）。看到这些数字，就是对疲惫妈妈大脑最好的按摩。' WHERE id = 'c2b89303-d5b8-4b81-97cd-3a091f15bb05' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pijama de la discordia 👗', body_es = '¿No quiere quitarse el pijama manchado y sucio en todo el día? A los 3 años la estética no importa. Si no tiene frío, que siga así unas horas más.', title_fr = 'Le pyjama de l''entêtement 👗', body_fr = 'Il refuse d''enlever son pyjama sali et taché du matin au soir ? À 3 ans, l''esthétique n''a aucune importance. S''il n''a pas froid, laissez-le comme ça quelques heures de plus.', title_hi = 'ज़िद्दी पजामा 👗', body_hi = 'सुबह से शाम तक गंदा और दाग वाला पजामा उतारना नहीं चाहता? 3 साल की उम्र में दिखावट मायने नहीं रखती। अगर ठंड नहीं लग रही, तो कुछ घंटे और ऐसे ही रहने दीजिए।', title_id = 'Piyama yang tak mau lepas 👗', body_id = 'Ia tidak mau melepas piyamanya yang kotor dan bernoda dari pagi sampai malam? Di usia 3 tahun penampilan tidak penting. Kalau ia tidak kedinginan, biarkan saja begitu beberapa jam lagi.', title_ja = 'がんこなパジャマ 👗', body_ja = '朝から晩まで、汚れてシミだらけのパジャマを脱ぎたがらない？3歳では見た目は重要ではありません。寒くなければ、あと数時間そのままにしておきましょう。', title_ko = '고집스러운 잠옷 👗', body_ko = '아침부터 저녁까지 더러워지고 얼룩진 잠옷을 벗지 않으려 하나요? 세 살에게 외모는 중요하지 않아요. 춥지 않다면 몇 시간 더 그대로 두세요.', title_nl = 'Koppige pyjama 👗', body_nl = 'Wil hij zijn vieze pyjama vol vlekken van ''s ochtends tot ''s avonds niet uittrekken? Op 3 jaar doet uiterlijk er niet toe. Heeft hij het niet koud, laat hem dan nog een paar uurtjes zo.', title_pl = 'Uparta piżama 👗', body_pl = 'Od rana do wieczora nie chce zdjąć brudnej, poplamionej piżamy? W wieku 3 lat estetyka nie ma znaczenia. Jeśli nie marznie, niech jeszcze kilka godzin tak zostanie.', title_pt = 'O pijama teimoso 👗', body_pt = 'Não quer tirar o pijama sujo e manchado da manhã à noite? Aos 3 anos, a estética não importa. Se não tem frio, deixe-o ficar assim mais umas horas.', title_sv = 'Envis pyjamas 👗', body_sv = 'Vill barnet inte ta av sig pyjamasen som blivit smutsig och fläckig från morgon till kväll? Estetik spelar ingen roll vid 3 år. Om barnet inte fryser, låt hen ha den på några timmar till.', title_vi = 'Bộ đồ ngủ bướng bỉnh 👗', body_vi = 'Bé không chịu cởi bộ đồ ngủ đã lấm lem từ sáng đến tối? Ở tuổi lên 3, thẩm mỹ không quan trọng. Nếu bé không lạnh, cứ để bé mặc thêm vài tiếng nữa.', title_zh = '倔强的睡衣 👗', body_zh = '从早到晚穿着脏兮兮、满是污渍的睡衣，就是不肯脱？3岁时好不好看并不重要。只要不冷，就让宝宝再穿几个小时吧。' WHERE id = '45a51286-f051-4f99-a23c-39a189481dfa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Yo en el cuento inteligente 🪄', body_es = 'Os sabéis de memoria los libros clásicos. Abre Cuentos inteligentes, haz que el protagonista sea tu peque y el lugar por conquistar, su habitación, y crea una sesión de sueño fuera de lo común.', title_fr = 'Moi, dans un Conte intelligent 🪄', body_fr = 'Vous connaissez les livres classiques par cœur. Ouvrez les Contes intelligents, faites de votre enfant le héros et de sa chambre le lieu à conquérir, et créez une séance du coucher extraordinaire.', title_hi = 'स्मार्ट कहानी में मैं 🪄', body_hi = 'पुरानी किताबें आपको रट गई हैं? स्मार्ट कहानियाँ खोलिए, मुख्य हीरो अपने बच्चे को और जीतने वाली जगह उसके कमरे को बनाइए, और नींद का एक अनोखा सेशन रचिए।', title_id = 'Aku di Dongeng Pintar 🪄', body_id = 'Anda sudah hafal semua buku klasik. Buka Dongeng Pintar, rancang anak Anda sebagai tokoh utama dan kamarnya sebagai tempat yang harus ditaklukkan, lalu ciptakan sesi tidur yang luar biasa.', title_ja = '「スマートおはなし」の主人公はわたし 🪄', body_ja = 'いつもの絵本はもう暗記してしまった？「スマートおはなし」を開いて、主人公はお子さん、冒険の舞台はお子さんの部屋にして、特別な寝かしつけの時間をつくりましょう。', title_ko = '스마트 동화 속의 나 🪄', body_ko = '늘 읽던 책은 이미 다 외웠죠. 스마트 동화를 열어 아이를 주인공으로, 아이의 방을 정복할 장소로 정해 특별한 잠자리 시간을 만들어 보세요.', title_nl = 'Ik in het slimme sprookje 🪄', body_nl = 'Ken je de klassieke boekjes uit je hoofd? Open Slimme sprookjes, maak je kindje de hoofdpersoon en zijn kamer de plek die veroverd moet worden, en creëer zo een bijzonder slaapmoment.', title_pl = 'Ja w Mądrej bajce 🪄', body_pl = 'Znasz już klasyczne książki na pamięć. Otwórz Mądre bajki, zrób dziecko głównym bohaterem, a jego pokój miejscem do zdobycia, i stwórzcie niezwykły seans przed snem.', title_pt = 'Eu na história inteligente 🪄', body_pt = 'Já sabe os livros clássicos de cor. Abra as Histórias Inteligentes, faça do seu filho o herói principal e do quarto dele o lugar a conquistar, e crie uma sessão de sono fora do comum.', title_sv = 'Jag i den smarta sagan 🪄', body_sv = 'Ni kan de klassiska böckerna utantill. Öppna Smarta sagor, gör barnet till huvudperson och barnets rum till platsen som ska erövras, och skapa en ovanlig godnattstund.', title_vi = 'Con trong truyện cổ tích thông minh 🪄', body_vi = 'Mẹ đã thuộc lòng hết sách kinh điển. Hãy mở Truyện cổ tích thông minh, chọn bé làm nhân vật chính và căn phòng của bé là nơi cần chinh phục để tạo một buổi ru ngủ khác thường.', title_zh = '智能故事里的我 🪄', body_zh = '经典故事书你们都背下来了？打开智能故事，让孩子当主角，把要征服的地方设计成宝宝的房间，来一场与众不同的睡前故事吧。' WHERE id = '4c871abf-c886-4fbd-909f-95e344736fa3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crítico de dibujos animados 📺', body_es = 'Te cuenta con su propia gramática los dibujos que ha visto y te explica muy serio quién fue adónde. Escúchale con atención, como si te sorprendiera. Que se sienta el más listo del mundo.', title_fr = 'Critique de dessins animés 📺', body_fr = 'Il vous raconte le dessin animé qu''il a vu avec sa propre grammaire, en expliquant très sérieusement qui est allé où. Écoutez-le attentivement, comme si vous étiez surprise. Qu''il se sente le plus malin du monde.', title_hi = 'कार्टून समीक्षक 📺', body_hi = 'देखा हुआ कार्टून अपने व्याकरण में सुनाता है, गंभीरता से समझाता है कि कौन कहाँ गया? उसे ध्यान से, हैरान होने के अंदाज़ में सुनिए। उसे खुद को दुनिया का सबसे समझदार महसूस करने दीजिए।', title_id = 'Kritikus film kartun 📺', body_id = 'Ia menceritakan film kartun yang ditontonnya dengan tata bahasanya sendiri, menjelaskan dengan serius siapa pergi ke mana. Dengarkan dengan saksama, seolah Anda terkejut. Biarkan ia merasa paling pintar di dunia.', title_ja = 'アニメ評論家 📺', body_ja = '見たアニメを自分なりの文法で話して、だれがどこへ行ったかを真剣に説明しますか？驚いたふりをしながら、しっかり聞いてあげましょう。世界一賢いと感じさせてあげて。', title_ko = '만화 평론가 📺', body_ko = '본 만화를 자기만의 문법으로 들려주며 누가 어디로 갔는지 진지하게 설명하나요? 놀란 듯이 귀 기울여 들어 주세요. 세상에서 가장 똑똑한 사람이 된 기분을 느끼게 해 주세요.', title_nl = 'Tekenfilmcriticus 📺', body_nl = 'Vertelt hij je met zijn eigen grammatica over de tekenfilm die hij zag en legt hij serieus uit wie waar naartoe ging? Luister aandachtig, alsof je verbaasd bent. Laat hem zich de slimste ter wereld voelen.', title_pl = 'Krytyk filmów animowanych 📺', body_pl = 'Opowiada ci obejrzaną bajkę własną gramatyką, z powagą tłumacząc, kto dokąd poszedł. Słuchaj go uważnie, jakbyś była zaskoczona. Niech poczuje się najmądrzejszy na świecie.', title_pt = 'Crítico de desenhos animados 📺', body_pt = 'Conta-lhe o desenho animado que viu com a sua própria gramática e explica muito a sério quem foi para onde. Ouça-o com atenção, como se estivesse surpreendida. Deixe-o sentir-se a pessoa mais inteligente do mundo.', title_sv = 'Tecknade filmens kritiker 📺', body_sv = 'Berättar barnet om den tecknade filmen hen sett med sin egen grammatik och förklarar allvarligt vem som gick vart? Lyssna noga och låtsas bli förvånad. Låt barnet känna sig som världens smartaste.', title_vi = 'Nhà phê bình phim hoạt hình 📺', body_vi = 'Bé kể cho mẹ nghe bộ phim hoạt hình vừa xem bằng ngữ pháp của riêng mình, nghiêm túc giải thích ai đi đâu. Hãy chăm chú lắng nghe như thể thật ngạc nhiên. Để bé cảm thấy mình thông minh nhất thế giới.', title_zh = '动画片评论家 📺', body_zh = '用自己的语法给你讲刚看的动画片，一本正经地解释谁去了哪里。认真地、带着惊讶的表情听宝宝讲。让宝宝觉得自己是世界上最聪明的人。' WHERE id = '9f3be00e-0091-4500-91da-22dc9ba62d93' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Madrugadores antes que el sol 🌅', body_es = '¿Se levanta a las 6 y tú estás agotada? Pregunta a Anacan AI cómo ajustar esta rutina. Recuerda que la falta de sueño no es para siempre, todo pasa.', title_fr = 'Debout avant le soleil 🌅', body_fr = 'Il est debout à 6 h et vous êtes épuisée ? Demandez à Anacan AI comment ajuster ce rythme. N''oubliez pas, le manque de sommeil n''est pas éternel, tout finira par passer.', title_hi = 'सूरज से पहले जागने वाले 🌅', body_hi = 'वह सुबह 6 बजे उठ खड़ा होता है, और आप थक कर चूर हैं? इस रूटीन को कैसे ठीक करें, Anacan AI से पूछिए। याद रखिए, नींद की कमी हमेशा नहीं रहती, यह भी गुज़र जाएगा।', title_id = 'Bangun sebelum matahari 🌅', body_id = 'Ia sudah bangun jam 6, sementara Anda kehabisan tenaga? Tanyakan pada Anacan AI cara mengatur rutinitas ini. Ingat, kurang tidur tidak berlangsung selamanya, semuanya akan berlalu.', title_ja = '日の出前に起きる子 🌅', body_ja = 'お子さんは朝6時に起きているのに、あなたはへとへと？このリズムをどう整えるか、Anacan AIに聞いてみましょう。寝不足は永遠には続きません、必ず過ぎていきます。', title_ko = '해보다 먼저 일어나는 아이 🌅', body_ko = '아이는 6시에 일어났는데 엄마는 지쳤나요? 이 일과를 어떻게 조절할지 Anacan AI에게 물어보세요. 잠 못 드는 날들은 영원하지 않아요. 다 지나갈 거예요.', title_nl = 'Vroeg op, voor de zon 🌅', body_nl = 'Staat hij om 6 uur naast je bed en ben jij uitgeput? Vraag Anacan AI hoe je dit ritme bijstuurt. Vergeet niet: slaapgebrek duurt niet eeuwig, alles gaat voorbij.', title_pl = 'Ci, którzy wstają przed słońcem 🌅', body_pl = 'On jest na nogach o 6 rano, a ty jesteś wykończona? Zapytaj Anacan AI, jak uregulować ten rytm. Pamiętaj, niewyspanie nie trwa wiecznie, wszystko minie.', title_pt = 'Os que acordam antes do sol 🌅', body_pt = 'Às 6 da manhã já está de pé e a mãe está esgotada? Pergunte ao Anacan AI como ajustar esta rotina. Não se esqueça: a falta de sono não é para sempre, tudo vai passar.', title_sv = 'De som vaknar före solen 🌅', body_sv = 'Är barnet uppe klockan 6 medan du är helt slut? Fråga Anacan AI hur du kan justera rutinen. Glöm inte att sömnbristen inte varar för evigt, allt går över.', title_vi = 'Những người dậy trước mặt trời 🌅', body_vi = 'Bé đã dậy từ 6 giờ, còn mẹ thì kiệt sức? Hãy hỏi Anacan AI cách điều chỉnh nếp sinh hoạt này. Đừng quên, thiếu ngủ không kéo dài mãi, mọi chuyện rồi sẽ qua.', title_zh = '比太阳起得还早 🌅', body_zh = '宝宝6点就起来了，而你已经累坏了？问问Anacan AI怎样调整这种作息。别忘了，睡不够的日子不会永远持续，一切都会过去。' WHERE id = '89c52f3b-2e4b-4c88-b0bc-f1bbe0891bb8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Champán de pareja 🥂', body_es = 'Tu peque se ha dormido. Aunque no haya champán, servid té caliente y brindad con tu pareja diciendo «También hemos sobrevivido a este día difícil». Sois un equipo estupendo.', title_fr = 'Champagne en couple 🥂', body_fr = 'L''enfant dort. Même sans champagne, versez du thé chaud dans vos tasses et trinquez avec votre partenaire : « On a encore terminé cette journée difficile sains et saufs. » Vous formez une super équipe.', title_hi = 'कपल वाली शैंपेन 🥂', body_hi = 'बच्चा सो गया। शैंपेन न सही, गिलासों में गर्म चाय डालिए और अपने पार्टनर के साथ ''यह मुश्किल दिन भी सही-सलामत पूरा कर लिया'' कहकर गिलास टकराइए। आप बेहतरीन साथी हैं।', title_id = 'Sampanye untuk berdua 🥂', body_id = 'Anak sudah tidur. Kalaupun tidak ada sampanye, tuang teh hangat ke gelas dan dentingkan bersama pasangan sambil berkata ''Hari yang berat ini pun kita lalui dengan selamat''. Kalian pasangan yang hebat.', title_ja = 'ふたりのシャンパンタイム 🥂', body_ja = 'お子さんが眠りました。シャンパンがなくても、カップに温かいお茶をいれて、パートナーと「今日の大変な一日も無事に終わったね」と乾杯しましょう。あなたたちは最高のパートナーです。', title_ko = '부부의 샴페인 🥂', body_ko = '아이가 잠들었어요. 샴페인이 없어도 잔에 따뜻한 차를 따르고 배우자와 ''오늘 힘든 하루도 무사히 끝냈다'' 하며 잔을 부딪쳐 보세요. 두 사람은 최고의 파트너예요.', title_nl = 'Champagne voor jullie tweeën 🥂', body_nl = 'Hij slaapt. Ook zonder champagne: schenk warme thee in en klink met je partner op ''Ook deze zware dag hebben we heelhuids doorstaan''. Jullie zijn geweldige teamgenoten.', title_pl = 'Szampan dla dwojga 🥂', body_pl = 'Dziecko śpi. Nawet jeśli nie ma szampana, nalejcie do kubków ciepłej herbaty i stuknijcie się z partnerem: „Ten trudny dzień też przetrwaliśmy cali i zdrowi”. Jesteście świetną parą.', title_pt = 'Champanhe a dois 🥂', body_pt = 'A criança adormeceu. Mesmo sem champanhe, sirva chá quente nas chávenas e brinde com o seu companheiro: "Também acabámos este dia difícil sãos e salvos." São uma ótima dupla.', title_sv = 'Parets champagne 🥂', body_sv = 'Barnet sover. Även om det inte finns champagne, häll upp varmt te och skåla med din partner: ”Den här tuffa dagen klarade vi också oskadda.” Ni är fantastiska partner.', title_vi = 'Ly champagne của hai vợ chồng 🥂', body_vi = 'Bé ngủ rồi. Dù không có champagne, hãy rót trà nóng vào cốc và cụng ly với chồng: "Chúng mình lại vượt qua một ngày khó khăn bình an". Hai người là những người đồng hành tuyệt vời.', title_zh = '夫妻的“香槟” 🥂', body_zh = '孩子睡着了。没有香槟也没关系，往杯子里倒上热茶，和另一半碰个杯：“这艰难的一天我们也平平安安地度过了。”你们是很棒的搭档。' WHERE id = 'e229522e-360b-4392-8cfc-620f6326286c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sorpresa en la lista 🛒', body_es = 'Antes de ir al súper abriste la Lista de la compra y viste que tu peque había venido por detrás, había tocado la pantalla y había añadido chocolate. Sí, ¡saben de tecnología más que tú!', title_fr = 'Surprise dans la liste 🛒', body_fr = 'Avant d''aller au supermarché, vous ouvrez la Liste de courses et voyez qu''il est venu dans votre dos appuyer sur l''écran pour y ajouter du chocolat. Eh oui, ils maîtrisent la technologie mieux que vous !', title_hi = 'लिस्ट में सरप्राइज़ 🛒', body_hi = 'बाज़ार जाने से पहले शॉपिंग लिस्ट खोली और देखा कि उसने पीछे से आकर स्क्रीन दबाकर उसमें चॉकलेट जोड़ दी है? हाँ, ये टेक्नोलॉजी आपसे बेहतर जानते हैं!', title_id = 'Kejutan di daftar belanja 🛒', body_id = 'Sebelum belanja Anda membuka Daftar Belanja dan melihat ia datang dari belakang, menekan layar ponsel, dan menambahkan cokelat ke sana. Ya, mereka lebih paham teknologi daripada Anda!', title_ja = 'リストのサプライズ 🛒', body_ja = '買い物の前に「買い物リスト」を開いたら、後ろからやってきて画面をタップし、チョコレートを追加していた？そう、テクノロジーはあなたよりよく知っているのです！', title_ko = '목록 속 깜짝 선물 🛒', body_ko = '마트에 가기 전 쇼핑 목록을 열었더니 아이가 뒤에서 다가와 화면을 눌러 초콜릿을 추가했나요? 네, 아이들은 기술을 엄마보다 더 잘 알아요!', title_nl = 'Verrassing op het lijstje 🛒', body_nl = 'Je opende voor het boodschappen doen je Boodschappenlijstje en zag dat hij achter je was komen staan, op het scherm tikte en chocola had toegevoegd. Ja, ze kennen de techniek beter dan jij!', title_pl = 'Niespodzianka na liście 🛒', body_pl = 'Przed wyjściem do sklepu otworzyłaś Listę zakupów i zobaczyłaś, że podkradł się, nacisnął ekran telefonu i dopisał czekoladę? Tak, znają się na technologii lepiej od ciebie!', title_pt = 'Surpresa na lista 🛒', body_pt = 'Antes de ir ao supermercado, abriu a Lista de Compras e viu que ele veio por trás, carregou no ecrã e acrescentou chocolate? Pois é, sabem mais de tecnologia do que nós!', title_sv = 'Överraskning på listan 🛒', body_sv = 'Du öppnade Inköpslistan innan du skulle handla och såg att barnet kommit bakifrån, tryckt på skärmen och lagt till choklad. Ja, de kan tekniken bättre än du!', title_vi = 'Bất ngờ trong danh sách 🛒', body_vi = 'Trước khi đi siêu thị mẹ mở Danh sách mua sắm và thấy bé đã lén chạm vào màn hình thêm sô-cô-la vào đó. Đúng vậy, bé rành công nghệ hơn cả mẹ!', title_zh = '清单里的惊喜 🛒', body_zh = '去超市前打开购物清单，发现宝宝从身后跑来，按着手机屏幕往里加了巧克力？没错，他们比你还懂科技！' WHERE id = 'f802a634-da9b-44e2-a965-9f94ea543fd1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Arrugados en la bañera 🛀', body_es = 'Jugar con el agua es tan divertido que no quiere salir de la bañera aunque tenga los dedos arrugados. Avísale 5 minutos antes y pon un temporizador. La regla de «Cuando suene la campanita, salimos» suele funcionar.', title_fr = 'Tout fripé dans le bain 🛀', body_fr = 'Jouer dans l''eau est si agréable qu''il refuse de sortir du bain, même les doigts tout fripés. Prévenez-le 5 minutes avant et réglez un minuteur. La règle « Quand ça sonne, on sort » marche souvent.', title_hi = 'नहाते-नहाते झुर्रीदार उँगलियाँ 🛀', body_hi = 'पानी से खेलना इतना मज़ेदार है कि उँगलियाँ सिकुड़ जाएँ तब भी टब से निकलना नहीं चाहता? उसे 5 मिनट पहले बता दीजिए और टाइमर लगाइए। ''घंटी बजेगी तो बाहर निकलेंगे'' वाला नियम अक्सर काम करता है।', title_id = 'Berendam sampai keriput 🛀', body_id = 'Bermain air begitu menyenangkan sampai jarinya keriput pun ia tidak mau keluar dari bak mandi. Beri tahu 5 menit sebelumnya dan pasang timer. Aturan ''Kita keluar saat bel berbunyi'' biasanya berhasil.', title_ja = 'お風呂でふやけるまで 🛀', body_ja = 'お水遊びが楽しすぎて、指がしわしわになってもお風呂から出たがらない？5分前に知らせて、タイマーをセットしましょう。「ベルが鳴ったら出るよ」のルールはたいていうまくいきます。', title_ko = '손가락이 쪼글쪼글해질 때까지 🛀', body_ko = '물놀이가 너무 재미있어서 손가락이 쪼글쪼글해져도 욕조에서 나오기 싫어하나요? 5분 전에 미리 알려 주고 타이머를 맞추세요. ''알람이 울리면 나가기'' 규칙이 잘 통할 때가 많아요.', title_nl = 'Rimpelvingers in bad 🛀', body_nl = 'Spelen met water is zo leuk dat hij niet uit bad wil, ook al zijn zijn vingers gerimpeld. Waarschuw hem 5 minuten vooraf en zet een timer. De regel ''Als de bel gaat, gaan we eruit'' werkt meestal.', title_pl = 'Pomarszczony w wannie 🛀', body_pl = 'Zabawa wodą jest tak przyjemna, że choć ma już pomarszczone paluszki, nie chce wyjść z wanny. Uprzedź go 5 minut wcześniej i nastaw timer. Zasada „Gdy zadzwoni dzwonek, wychodzimy” często działa.', title_pt = 'Enrugar no banho 🛀', body_pt = 'Brincar com a água é tão bom que, mesmo com os dedos enrugados, não quer sair da banheira. Avise-o 5 minutos antes e programe um temporizador. A regra "quando tocar, saímos" resulta muitas vezes.', title_sv = 'Skrynklig i badet 🛀', body_sv = 'Det är så roligt att leka med vattnet att barnet inte vill gå ur badet trots att fingrarna är skrynkliga. Förvarna 5 minuter innan och ställ in en timer. Regeln ”När klockan ringer går vi upp” fungerar ofta.', title_vi = 'Tắm đến nhăn cả tay 🛀', body_vi = 'Nghịch nước vui đến mức dù ngón tay đã nhăn nheo, bé vẫn không chịu ra khỏi bồn. Hãy báo trước cho bé 5 phút và đặt hẹn giờ. Quy tắc "Chuông reo là mình ra" thường rất hiệu quả.', title_zh = '泡到皱巴巴 🛀', body_zh = '玩水太开心了，手指都泡皱了还不肯出浴缸。提前5分钟提醒宝宝，再设个计时器。“铃声响了就出来”的规则往往很管用。' WHERE id = '0d0524d6-a4ad-4051-b779-b554d981748f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla del peinado 🪮', body_es = 'Se ha despertado con el pelo de punta como si le hubiera dado la corriente, y en cuanto ve el peine empieza la persecución. En lugar de peinarle, alísale el pelo con las manos mojadas y acaba con la batalla.', title_fr = 'La bataille de la coiffure 🪮', body_fr = 'Au réveil, ses cheveux sont dressés sur sa tête comme s''il avait pris un coup de jus. Et dès qu''il voit le peigne, la course-poursuite commence. Au lieu de le peigner, aplatissez ses cheveux avec vos mains mouillées et mettez fin à la lutte.', title_hi = 'हेयरस्टाइल की जंग 🪮', body_hi = 'सुबह उठा तो बाल ऐसे खड़े हैं जैसे करंट लगा हो। कंघी देखते ही भागम-भाग शुरू? कंघी करने के बजाय हाथों में पानी लेकर बाल बिठा दीजिए और जंग खत्म कीजिए।', title_id = 'Perang menata rambut 🪮', body_id = 'Ia bangun pagi dengan rambut berdiri seperti tersengat listrik. Begitu melihat sisir, ia langsung kabur. Daripada menyisir, rapikan rambutnya dengan tangan dan sedikit air, lalu akhiri perdebatan.', title_ja = 'ヘアスタイル対決 🪮', body_ja = '朝起きたら、髪が静電気のように逆立っている？そしてくしを見たとたん逃げ出す？とかすかわりに、手と水で髪をなでつけて、戦いを終わらせましょう。', title_ko = '머리 정리 전쟁 🪮', body_ko = '아침에 일어나니 머리가 전기 맞은 것처럼 뻗쳐 있고, 빗만 보면 도망가나요? 빗질 대신 손에 물을 묻혀 머리를 눌러 주며 씨름을 끝내세요.', title_nl = 'Strijd om het kapsel 🪮', body_nl = 'Wordt hij wakker met haar dat rechtop staat alsof hij onder stroom stond? En zodra hij de kam ziet, begint het rennen. Kam niet, maar strijk zijn haar met natte handen glad en maak een eind aan de strijd.', title_pl = 'Walka o fryzurę 🪮', body_pl = 'Obudził się rano z włosami sterczącymi, jakby poraził go prąd? A na widok grzebienia zaczyna się ucieczka. Zamiast czesać, przygładź włosy dłońmi zwilżonymi wodą i zakończ walkę.', title_pt = 'A luta do penteado 🪮', body_pt = 'Acordou com o cabelo no ar, como se tivesse apanhado um choque. E mal vê o pente, começa a fuga. Em vez de pentear, alise-lhe o cabelo com as mãos molhadas e acabe com a luta.', title_sv = 'Kampen om frisyren 🪮', body_sv = 'Barnet har vaknat och håret står rakt upp som efter en elstöt. Så fort hen ser kammen börjar flykten. I stället för att kamma, platta till håret med vatten och händerna och avsluta kampen.', title_vi = 'Cuộc chiến làm tóc 🪮', body_vi = 'Sáng thức dậy tóc bé dựng ngược như bị điện giật. Vừa thấy lược là bé chạy trốn. Thay vì chải, hãy dùng tay vuốt nước cho tóc xẹp xuống và chấm dứt giằng co.', title_zh = '发型大作战 🪮', body_zh = '早上醒来，头发像触了电一样竖起来。一看到梳子就开始到处跑。别梳了，用手沾点水把头发压平，结束这场战斗吧。' WHERE id = '1460be31-c5b7-4f0f-9a6b-7ff5c2085c36' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La opinión de la inteligencia artificial 🤖', body_es = '¿A tu peque le ha salido un hábito raro (por ejemplo, morderse las uñas) y los artículos de internet te han asustado? Para. Pregunta a Anacan AI la verdadera causa, avalada por pediatras, y quédate tranquila.', title_fr = 'L''avis de l''intelligence artificielle 🤖', body_fr = 'Votre enfant a pris une drôle d''habitude (se ronger les ongles, par exemple) et les articles sur Internet vous ont fait peur ? Stop. Demandez à Anacan AI la vraie raison, validée par des pédiatres, et rassurez-vous.', title_hi = 'आर्टिफ़िशियल इंटेलिजेंस की राय 🤖', body_hi = 'बच्चे में कोई अजीब आदत बन गई (जैसे नाखून चबाना) और इंटरनेट के लेखों ने आपको डरा दिया? रुकिए। Anacan AI से इसकी बाल रोग विशेषज्ञों से पुष्ट असली वजह पूछिए और निश्चिंत हो जाइए।', title_id = 'Pendapat kecerdasan buatan 🤖', body_id = 'Anak Anda punya kebiasaan aneh (misalnya menggigit kuku) dan artikel di internet membuat Anda takut? Berhenti. Tanyakan pada Anacan AI penyebab sebenarnya yang disetujui dokter anak dan tenangkan diri.', title_ja = 'AIの見解 🤖', body_ja = 'お子さんに気になる癖（たとえば爪かみ）ができて、ネットの記事にこわくなりましたか？ちょっと待って。Anacan AIに、小児科医が認める本当の原因を聞いて、安心しましょう。', title_ko = '인공지능의 생각 🤖', body_ko = '아이에게 손톱 물어뜯기 같은 별난 습관이 생겼는데 인터넷 글을 보고 겁이 났나요? 잠깐 멈추세요. Anacan AI에게 소아과 검증을 거친 진짜 이유를 물어보고 마음을 놓으세요.', title_nl = 'Wat zegt de AI? 🤖', body_nl = 'Heeft hij een vreemde gewoonte (zoals nagelbijten) en maakten artikelen op internet je bang? Stop. Vraag Anacan AI naar de echte, door kinderartsen goedgekeurde oorzaak en kom tot rust.', title_pl = 'Zdanie sztucznej inteligencji 🤖', body_pl = 'U dziecka pojawił się dziwny nawyk (np. obgryzanie paznokci), a artykuły w internecie cię przestraszyły? Zatrzymaj się. Zapytaj Anacan AI o prawdziwą, zatwierdzoną przez pediatrów przyczynę i się uspokój.', title_pt = 'A opinião da inteligência artificial 🤖', body_pt = 'Surgiu um hábito estranho no seu filho (por exemplo, roer as unhas) e os artigos da internet assustaram-na? Pare. Pergunte ao Anacan AI a verdadeira causa, aprovada por pediatras, e acalme-se.', title_sv = 'Vad säger den artificiella intelligensen? 🤖', body_sv = 'Har barnet fått en konstig vana (till exempel att bita på naglarna) och artiklarna på nätet skrämde dig? Stanna upp. Fråga Anacan AI om den verkliga orsaken, godkänd av barnläkare, och lugna dig.', title_vi = 'Ý kiến của trí tuệ nhân tạo 🤖', body_vi = 'Bé có một thói quen lạ (ví dụ cắn móng tay) và các bài báo trên mạng khiến mẹ lo sợ? Dừng lại. Hãy hỏi Anacan AI nguyên nhân thực sự đã được bác sĩ nhi khoa xác nhận và yên tâm hơn.', title_zh = '人工智能怎么看 🤖', body_zh = '孩子有了一个奇怪的习惯（比如咬指甲），网上的文章把你吓到了？停一下。问问Anacan AI，经儿科医生认可的真正原因是什么，让自己平静下来。' WHERE id = 'fc5667d9-2c85-42d4-a92c-e90c3b994a0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El médico está contigo 🩺', body_es = '¿Coge su estetoscopio de juguete, te lo pone en el pecho y te dice «respira»? Tú eres la paciente y tu peque, el médico jefe. Sigue el juego, túmbate y, aunque sea 5 minutos, cierra los ojos y descansa durante el tratamiento.', title_fr = 'Le docteur est avec vous 🩺', body_fr = 'Il prend son stéthoscope jouet, le pose sur votre poitrine et vous dit « respire » ? Vous êtes la patiente, lui le médecin-chef. Jouez le jeu, allongez-vous et, pendant le soin, fermez les yeux et reposez-vous, ne serait-ce que 5 minutes.', title_hi = 'डॉक्टर आपके साथ है 🩺', body_hi = 'खिलौने वाला स्टेथोस्कोप लेकर आपके सीने पर रखता है और कहता है ''साँस लो''? आप मरीज़ हैं और वह बड़ा डॉक्टर। यह खेल खेलिए, लेट जाइए और इलाज के दौरान 5 मिनट ही सही, आँखें बंद करके आराम कीजिए।', title_id = 'Dokter ada bersama Anda 🩺', body_id = 'Ia mengambil stetoskop mainan, menempelkannya di dada Anda, dan berkata ''Tarik napas''. Anda pasiennya, ia kepala dokternya. Mainkan saja permainan ini, berbaringlah, dan pejamkan mata untuk beristirahat selama perawatan, walau hanya 5 menit.', title_ja = 'お医者さんがついてるよ 🩺', body_ja = 'おもちゃの聴診器をあなたの胸にあてて「息をすって」と言いますか？あなたは患者さん、お子さんは院長先生。この遊びに付き合って横になり、5分間でも治療中は目を閉じて休みましょう。', title_ko = '의사 선생님이 왔어요 🩺', body_ko = '장난감 청진기를 엄마 가슴에 대고 ''숨 쉬어'' 하나요? 엄마는 환자, 아이는 원장님이에요. 이 놀이에 함께하며 누워서 5분이라도 ''치료''받는 동안 눈을 감고 쉬세요.', title_nl = 'De dokter is bij je 🩺', body_nl = 'Zet hij zijn speelgoedstethoscoop op je borst en zegt hij ''Adem in''? Jij bent de patiënt, hij de hoofdarts. Speel mee, ga liggen en sluit tijdens de behandeling je ogen, al is het maar 5 minuten.', title_pl = 'Lekarz jest przy tobie 🩺', body_pl = 'Bierze zabawkowy stetoskop, przykłada ci do piersi i mówi „Oddychaj”? Ty jesteś pacjentką, a on ordynatorem. Pobaw się w to, połóż się i choć przez 5 minut „leczenia” zamknij oczy i odpocznij.', title_pt = 'O médico está consigo 🩺', body_pt = 'Pega no estetoscópio de brincar, põe-lho no peito e diz "respira"? A mãe é a doente e ele o médico-chefe. Entre no jogo, deite-se e, durante o tratamento, feche os olhos e descanse nem que sejam 5 minutos.', title_sv = 'Doktorn är här 🩺', body_sv = 'Barnet tar sitt leksaksstetoskop, sätter det på ditt bröst och säger ”andas”. Du är patienten och barnet är överläkare. Lek leken, ligg ner och blunda och vila under behandlingen, om så bara i 5 minuter.', title_vi = 'Bác sĩ ở ngay bên mẹ 🩺', body_vi = 'Bé lấy ống nghe đồ chơi đặt lên ngực mẹ và nói "Mẹ hít thở đi"? Mẹ là bệnh nhân, còn bé là bác sĩ trưởng. Hãy chơi cùng bé, nằm xuống và nhắm mắt nghỉ ngơi trong lúc "điều trị", dù chỉ 5 phút.', title_zh = '医生就在你身边 🩺', body_zh = '拿着玩具听诊器放在你胸口，说“吸气”。你是病人，宝宝是主任医生。玩这个游戏吧，躺下来，在“治疗”期间闭上眼睛休息，哪怕只有5分钟。' WHERE id = '01349acb-919c-490a-bfce-f75e04518130' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Subidón de energía 🏃‍♂️', body_es = 'Se sube por las paredes dentro de casa. Consulta Tiempo y ropa y salid sí o sí. Correr 30 minutos al aire libre es la mejor garantía de que dormirá bien por la noche.', title_fr = 'Débordement d''énergie 🏃‍♂️', body_fr = 'Il grimpe aux murs à l''intérieur. Consultez Météo et tenue et sortez absolument. 30 minutes de course au grand air sont la meilleure garantie de son sommeil du soir.', title_hi = 'ऊर्जा का उछाल 🏃‍♂️', body_hi = 'घर के अंदर दीवारों पर चढ़ रहा है? मौसम और कपड़े टूल देखकर ज़रूर बाहर निकलिए। ऑक्सीजन से भरे माहौल में 30 मिनट दौड़ना शाम की अच्छी नींद की सबसे बड़ी गारंटी है।', title_id = 'Lonjakan energi 🏃‍♂️', body_id = 'Ia memanjat dinding di dalam rumah. Cek cuaca dan pakaian, lalu pastikan keluar rumah. Berlari 30 menit di tempat yang kaya oksigen adalah jaminan terbesar untuk tidur malamnya.', title_ja = 'エネルギーの爆発 🏃‍♂️', body_ja = '家の中で壁をよじ登っていますか？「天気と服装」を確認して、ぜひ外へ出かけましょう。酸素たっぷりの場所で30分走ることが、夜ぐっすり眠るためのいちばんの保証です。', title_ko = '에너지 폭발 🏃‍♂️', body_ko = '집 안에서 벽을 타고 오를 기세인가요? 날씨와 옷차림을 확인하고 꼭 밖으로 나가세요. 공기 좋은 곳에서 30분 뛰어놀면 저녁 잠은 거의 보장돼요.', title_nl = 'Energiepiek 🏃‍♂️', body_nl = 'Klimt hij in huis tegen de muren op? Check Weer en kleding en ga zeker naar buiten. 30 minuten rennen in de frisse lucht is de beste garantie voor een goede nachtrust.', title_pl = 'Skok energii 🏃‍♂️', body_pl = 'W domu chodzi po ścianach? Sprawdź Pogodę i ubiór i koniecznie wyjdźcie na zewnątrz. 30 minut biegania w otoczeniu pełnym tlenu to najlepsza gwarancja wieczornego snu.', title_pt = 'Pico de energia 🏃‍♂️', body_pt = 'Anda a trepar pelas paredes de casa. Veja o Tempo e Roupa e saiam sem falta. Correr 30 minutos ao ar livre, com muito oxigénio, é a maior garantia do sono dele à noite.', title_sv = 'Energiboost 🏃‍♂️', body_sv = 'Barnet klättrar på väggarna inomhus. Kolla Väder och kläder och gå absolut ut. Att springa i 30 minuter i en syrerik miljö är den bästa garantin för kvällens sömn.', title_vi = 'Năng lượng bùng nổ 🏃‍♂️', body_vi = 'Bé leo trèo khắp các bức tường trong nhà. Hãy xem Thời tiết và trang phục và nhất định ra ngoài. 30 phút chạy nhảy nơi nhiều oxy là bảo đảm lớn nhất cho giấc ngủ tối của bé.', title_zh = '精力爆棚 🏃‍♂️', body_zh = '在家里都快爬上墙了。看看天气穿衣工具，一定要出门。在氧气充足的地方跑上30分钟，是晚上好好睡觉的最大保证。' WHERE id = 'd58d064b-a397-425d-9d57-3f6068e31cf1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia del susurro 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y cuéntale en voz muy bajita, susurrando, lo que ha pasado durante el día. Susurrar es el método más natural y relajante para preparar el cerebro para dormir.', title_fr = 'La magie du chuchotement 🌙', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et racontez-lui sa journée tout bas, en chuchotant. Le chuchotement est la façon la plus naturelle et la plus apaisante de préparer le cerveau au sommeil.', title_hi = 'फुसफुसाहट का जादू 🌙', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें बहुत धीमी आवाज़ में, फुसफुसाकर उसे सुनाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे स्वाभाविक और सुकून भरा तरीका है।', title_id = 'Sihir bisikan 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan ceritakan kejadian hari ini dengan suara sangat pelan, berbisik. Berbisik adalah cara paling alami dan menenangkan untuk menyiapkan otak tidur.', title_ja = 'ささやき声の魔法 🌙', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、今日あったことをとても小さな声でささやくように話してあげて。ささやき声は、脳を眠りへ導くいちばん自然で心落ち着く方法です。', title_ko = '속삭임의 마법 🌙', body_ko = '방의 불을 모두 꺼 주세요. 옆에 누워 오늘 있었던 일을 아주 작은 목소리로 속삭이듯 들려주세요. 속삭임은 뇌가 잠들 준비를 하게 돕는 가장 자연스럽고 차분한 방법이에요.', title_nl = 'De magie van fluisteren 🌙', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en vertel heel zachtjes, fluisterend, wat er vandaag is gebeurd. Fluisteren is de meest natuurlijke en rustgevende manier om de hersenen klaar te maken voor de slaap.', title_pl = 'Magia szeptu 🌙', body_pl = 'Zgaś wszystkie światła w pokoju. Połóż się obok i bardzo cicho, szeptem opowiedz mu, co wydarzyło się w ciągu dnia. Szept to najbardziej naturalny i kojący sposób, by przygotować mózg do snu.', title_pt = 'A magia do sussurro 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e conte-lhe, em voz muito baixa e a sussurrar, o que aconteceu durante o dia. Sussurrar é o método mais natural e calmante para preparar o cérebro para o sono.', title_sv = 'Viskningens trolldom 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och berätta mycket tyst, viskande, om det som hänt under dagen. Viskningar är det mest naturliga och lugnande sättet att förbereda hjärnan för sömn.', title_vi = 'Phép màu của lời thì thầm 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ kể về những gì đã xảy ra trong ngày. Thì thầm là cách tự nhiên và êm dịu nhất giúp não bộ chuẩn bị cho giấc ngủ.', title_zh = '悄悄话的魔法 🌙', body_zh = '把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音，悄悄讲讲今天发生的事。悄悄话是帮大脑准备入睡最自然、最能让人平静的方法。' WHERE id = 'd96fbe0f-26f7-4473-9f0b-34109da6a744' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'A caballito sobre papá 🐴', body_es = '¿No ha soltado toda su energía y no se va a la cama? Galopar por casa a caballito sobre papá y morirse de risa es la forma más rápida y divertida de ponerla a cero. La pelota la tiene papá.', title_fr = 'À dada sur le dos de papa 🐴', body_fr = 'Il n''a pas encore épuisé toute son énergie et refuse d''aller au lit ? Galoper dans la maison sur le dos de papa, avec des fous rires, c''est la façon la plus rapide et la plus drôle de la remettre à zéro. La balle est dans le camp de papa.', title_hi = 'पापा की पीठ पर घुड़सवारी 🐴', body_hi = 'पूरी ऊर्जा नहीं निकली और बिस्तर पर नहीं जाता? पापा की पीठ पर बैठकर घर में घुड़सवारी और हँसी के ठहाके उस ऊर्जा को शून्य करने का सबसे छोटा और मज़ेदार तरीका है। बॉल पापा के पाले में है।', title_id = 'Naik kuda di punggung Ayah 🐴', body_id = 'Energinya belum tersalurkan dan ia tidak mau tidur? Naik kuda-kudaan di punggung Ayah keliling rumah dan tertawa terpingkal-pingkal adalah cara tercepat dan paling seru untuk menolkan energi itu. Bola ada di tangan Ayah.', title_ja = 'パパのお馬さん 🐴', body_ja = 'エネルギーを出しきれず、ベッドに行かない？パパの背中に乗って家じゅうをお馬さんで走り回り、大笑いするのが、エネルギーをリセットするいちばん早くて楽しい方法です。バトンはパパへ。', title_ko = '아빠 등에서 말타기 🐴', body_ko = '에너지를 다 못 써서 자러 가지 않나요? 아빠 등에 타고 집 안을 달리며 깔깔 웃는 게 에너지를 비우는 가장 빠르고 즐거운 방법이에요. 이번엔 아빠 차례예요.', title_nl = 'Paardje rijden op papa''s rug 🐴', body_nl = 'Is hij zijn energie nog niet kwijt en wil hij niet naar bed? Paardje rijden op papa''s rug door het huis en gierend lachen is de snelste en leukste manier om die energie op te maken. De bal ligt bij papa.', title_pl = 'Jazda konna na plecach taty 🐴', body_pl = 'Nie zdążył się wyszaleć i nie idzie do łóżka? Galop po domu na plecach taty i ataki śmiechu to najkrótszy i najzabawniejszy sposób, by wyzerować tę energię. Piłeczka jest po stronie taty.', title_pt = 'Cavalgadas nas costas do pai 🐴', body_pt = 'Ainda não gastou toda a energia e não vai para a cama? Andar às cavalitas do pai pela casa, entre ataques de riso, é a forma mais rápida e divertida de pôr essa energia a zero. A bola está com o pai.', title_sv = 'Rida på pappas rygg 🐴', body_sv = 'Har barnet inte gjort av med all energi och vill inte gå och lägga sig? Att rida runt hemma på pappas rygg och få skrattanfall är det snabbaste och roligaste sättet att nollställa energin. Bollen ligger hos pappa.', title_vi = 'Cưỡi ngựa trên lưng bố 🐴', body_vi = 'Bé chưa xả hết năng lượng và không chịu lên giường? Cưỡi ngựa trên lưng bố khắp nhà, cười nắc nẻ là cách nhanh nhất và vui nhất để đưa năng lượng về 0. Giờ đến lượt bố.', title_zh = '骑在爸爸背上 🐴', body_zh = '精力还没用完，不肯上床？骑在爸爸背上在家里“骑马”，笑个不停，是让精力归零最快、最有趣的方法。球交给爸爸了。' WHERE id = '1fc309f5-659f-4b2e-bf6f-e17296d830ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá necesita calma 🩸', body_es = '¿Te irrita cualquier ruido? Mira el Calendario menstrual. Tu cuerpo necesita descansar. Prepara un tentempié con magnesio de Recetas saludables y date un tiempo para ti.', title_fr = 'Maman a besoin de calme 🩸', body_fr = 'Chaque bruit vous irrite ? Regardez le Suivi des règles. Votre corps a besoin de repos. Préparez une collation au magnésium avec les Recettes saines et accordez-vous du temps.', title_hi = 'माँ को सुकून की ज़रूरत 🩸', body_hi = 'हर आवाज़ चिढ़ा रही है? पीरियड ट्रैकर देखिए। आपके शरीर को आराम चाहिए। सेहतमंद रेसिपी से मैग्नीशियम वाला स्नैक बनाइए और खुद को समय दीजिए।', title_id = 'Ibu butuh ketenangan 🩸', body_id = 'Setiap suara membuat Anda jengkel? Lihat Pelacak Menstruasi. Tubuh Anda butuh istirahat. Buat camilan bermagnesium dari Resep Sehat dan luangkan waktu untuk diri sendiri.', title_ja = 'ママには静けさが必要 🩸', body_ja = 'どんな音にもイライラしますか？「生理トラッカー」を見てみましょう。体が休みを必要としています。「ヘルシーレシピ」からマグネシウムたっぷりのおやつをつくって、自分に時間をあげて。', title_ko = '엄마에게 필요한 고요 🩸', body_ko = '모든 소리가 거슬리나요? 생리 주기 기록을 확인해 보세요. 몸이 쉬고 싶어 하는 거예요. 건강한 레시피에서 마그네슘이 든 간식을 만들어 나에게 시간을 주세요.', title_nl = 'Mama heeft rust nodig 🩸', body_nl = 'Irriteert elk geluid je? Kijk in de Cyclustracker. Je lichaam heeft rust nodig. Maak een tussendoortje met magnesium uit Gezonde recepten en geef jezelf wat tijd.', title_pl = 'Mama potrzebuje spokoju 🩸', body_pl = 'Każdy dźwięk cię drażni? Zajrzyj do Kalendarza miesiączkowego. Twoje ciało potrzebuje odpoczynku. Przygotuj ze Zdrowych przepisów przekąskę z magnezem i daj sobie czas.', title_pt = 'A mãe precisa de sossego 🩸', body_pt = 'Todos os sons a irritam? Veja o Registo do Período. O seu corpo precisa de descansar. Prepare um snack com magnésio das Receitas Saudáveis e dê tempo a si mesma.', title_sv = 'Mammas behov av lugn 🩸', body_sv = 'Irriterar varje ljud dig? Titta i Mensspåraren. Kroppen behöver vila. Gör ett magnesiumrikt mellanmål från Hälsosamma recept och ge dig själv tid.', title_vi = 'Nhu cầu được yên tĩnh của mẹ 🩸', body_vi = 'Tiếng động nào cũng khiến mẹ khó chịu? Hãy xem Theo dõi kỳ kinh. Cơ thể mẹ cần được nghỉ ngơi. Hãy làm món ăn vặt giàu magie từ Công thức lành mạnh và dành thời gian cho bản thân.', title_zh = '妈妈需要安静 🩸', body_zh = '什么声音都让你烦躁？看看经期记录。你的身体需要休息。从健康食谱里做一份含镁的小零食，给自己一点时间。' WHERE id = '69846205-68bb-4476-a7e0-45d4e68fae26' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gritos sin motivo 😭', body_es = '¿Nada más abrir los ojos llora sin motivo? No es un capricho, es sobrecarga emocional. Descubre hablando con nuestro experto Anacan AI cómo actuar en plena crisis.', title_fr = 'Cris sans raison 😭', body_fr = 'Il pleure sans raison dès le réveil ? Ce n''est pas un caprice, c''est une surcharge émotionnelle. Découvrez en discutant avec notre expert Anacan AI comment réagir pendant la crise.', title_hi = 'बिना वजह चीखें 😭', body_hi = 'आँख खुलते ही बिना वजह रोता है? यह नखरा नहीं, भावनाओं का बोझ है। हमारे Anacan AI एक्सपर्ट से बात करके जानिए कि ऐसे मुश्किल पल में कैसे पेश आएँ।', title_id = 'Teriakan tanpa sebab 😭', body_id = 'Begitu membuka mata ia menangis tanpa sebab? Ini bukan manja, tetapi emosi yang berlebihan. Temukan cara bersikap saat krisis dengan mengobrol bersama ahli Anacan AI.', title_ja = '理由のない叫び声 😭', body_ja = '目を開けたとたん理由もなく泣きますか？これはわがままではなく、感情があふれているのです。かんしゃくのときにどう接すればいいか、Anacan AIのエキスパートに相談して見つけましょう。', title_ko = '이유 없는 울음 😭', body_ko = '눈 뜨자마자 이유 없이 우나요? 투정이 아니라 감정 과부하예요. 이런 순간에 어떻게 해야 하는지 Anacan AI 전문가와 이야기하며 알아보세요.', title_nl = 'Geschreeuw zonder reden 😭', body_nl = 'Huilt hij zomaar zodra hij wakker is? Dat is geen verwend gedrag, maar overprikkeling. Ontdek in een gesprek met onze expert Anacan AI hoe je je tijdens zo''n bui het best gedraagt.', title_pl = 'Krzyki bez powodu 😭', body_pl = 'Gdy tylko otworzy oczy, płacze bez powodu? To nie kaprys, tylko przeciążenie emocjami. Porozmawiaj z naszym ekspertem Anacan AI i odkryj, jak się zachować w chwili kryzysu.', title_pt = 'Gritos sem razão 😭', body_pt = 'Mal abre os olhos, chora sem razão? Não é capricho, é sobrecarga emocional. Descubra, a conversar com o especialista Anacan AI, como agir no momento da crise.', title_sv = 'Skrik utan orsak 😭', body_sv = 'Gråter barnet utan anledning så fort hen öppnar ögonen? Det är inte trots, det är känslomässig överbelastning. Prata med vår expert Anacan AI och upptäck hur du ska agera i krisögonblicket.', title_vi = 'Những tiếng hét vô cớ 😭', body_vi = 'Vừa mở mắt bé đã khóc không rõ lý do? Đây không phải nhõng nhẽo mà là quá tải cảm xúc. Hãy trò chuyện với chuyên gia Anacan AI để biết nên làm gì lúc bé khủng hoảng.', title_zh = '莫名的尖叫 😭', body_zh = '一睁眼就无缘无故地哭？这不是任性，而是情绪过载。和我们的Anacan AI专家聊一聊，看看崩溃时该怎么做。' WHERE id = 'c6dcd330-d5df-4d87-b7a0-d8ab33a73063' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de cocina de papá 👨‍🍳', body_es = '¡Hoy preparar la comida y darle de comer es cosa de papá! Tú dedica este tiempo a ti misma, simplemente tumbada o descansando.', title_fr = 'Papa de service en cuisine 👨‍🍳', body_fr = 'Aujourd''hui, préparer le déjeuner et le faire manger, c''est le rôle de papa ! Vous, consacrez ce temps à vous-même, simplement allongée ou en vous reposant.', title_hi = 'पापा की रसोई वाली बारी 👨‍🍳', body_hi = 'आज लंच बनाना और खिलाना पापा की ज़िम्मेदारी है! और आप यह समय बस लेटकर या आराम करके खुद को दीजिए।', title_id = 'Giliran Ayah di dapur 👨‍🍳', body_id = 'Hari ini menyiapkan makan siang dan menyuapi adalah tugas Ayah! Gunakan waktu ini untuk diri Anda dengan berbaring atau beristirahat saja.', title_ja = 'パパのキッチン当番 👨‍🍳', body_ja = '今日のランチ作りと食べさせるのはパパの担当！あなたはこの時間を、横になったり休んだりして自分のために使いましょう。', title_ko = '아빠의 주방 당번 👨‍🍳', body_ko = '오늘 점심 준비와 먹이기는 아빠 몫이에요! 엄마는 이 시간을 그냥 누워서 쉬며 오롯이 나를 위해 쓰세요.', title_nl = 'Papa''s keukendienst 👨‍🍳', body_nl = 'Vandaag zijn lunch maken en eten geven papa''s taak! Besteed die tijd aan jezelf, door gewoon te liggen of uit te rusten.', title_pl = 'Dyżur taty w kuchni 👨‍🍳', body_pl = 'Dziś przygotowanie obiadu i karmienie to zadanie taty! A ty poświęć ten czas sobie, po prostu leżąc albo odpoczywając.', title_pt = 'O turno do pai na cozinha 👨‍🍳', body_pt = 'Hoje, fazer o almoço e dar de comer é tarefa do pai! E a mãe dedica este tempo a si mesma, simplesmente deitada ou a descansar.', title_sv = 'Pappas tur i köket 👨‍🍳', body_sv = 'I dag är det pappas uppgift att laga lunch och mata barnet! Ägna du den tiden åt dig själv genom att bara ligga ner eller vila.', title_vi = 'Ca trực bếp của bố 👨‍🍳', body_vi = 'Hôm nay nấu bữa trưa và cho bé ăn là nhiệm vụ của bố! Còn mẹ dành thời gian này cho bản thân, chỉ cần nằm dài hoặc nghỉ ngơi.', title_zh = '爸爸的厨房值班 👨‍🍳', body_zh = '今天做午饭、喂饭都是爸爸的任务！你就把这段时间留给自己，躺一躺或休息一下吧。' WHERE id = '6ac257ab-47ac-4e61-a9e4-2b538df0a8dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormir con sonidos de la naturaleza 🪄', body_es = '¿La música clásica no funciona? En Cuentos inteligentes cierra el cuento y cambia a un fondo solo con sonidos de lluvia o del bosque. Los sonidos monótonos de la naturaleza le dormirán como por arte de magia.', title_fr = 'S''endormir avec les sons de la nature 🪄', body_fr = 'La musique classique ne marche pas ? Dans les Contes intelligents, arrêtez le conte et passez à un fond sonore avec seulement la pluie ou la forêt. Les sons monotones de la nature endorment l''enfant comme par enchantement.', title_hi = 'प्रकृति की आवाज़ों के साथ नींद 🪄', body_hi = 'शास्त्रीय संगीत काम नहीं कर रहा? स्मार्ट कहानियों में कहानी बंद करके सिर्फ़ बारिश या जंगल की आवाज़ों वाले बैकग्राउंड पर जाइए। प्रकृति की एक जैसी आवाज़ें बच्चे को जादू की तरह सुला देती हैं।', title_id = 'Tidur diiringi suara alam 🪄', body_id = 'Musik klasik tidak mempan? Di Dongeng Pintar, tutup dongengnya dan beralihlah ke latar yang hanya berisi suara hujan atau hutan. Suara alam yang monoton membuat anak tertidur seperti tersihir.', title_ja = '自然の音で眠りへ 🪄', body_ja = 'クラシック音楽が効かない？「スマートおはなし」でお話を閉じて、雨や森の音だけが流れる音に切りかえましょう。単調な自然の音が、魔法のようにお子さんを眠りへ導きます。', title_ko = '자연의 소리와 함께 잠으로 🪄', body_ko = '클래식 음악이 통하지 않나요? 스마트 동화에서 이야기를 끄고 빗소리나 숲 소리만 흐르는 배경으로 바꿔 보세요. 단조로운 자연의 소리가 마법처럼 아이를 재워 줘요.', title_nl = 'Slapen met natuurgeluiden 🪄', body_nl = 'Werkt klassieke muziek niet? Sluit in Slimme sprookjes het verhaal af en schakel over naar een achtergrond met alleen regen- of bosgeluiden. Eentonige natuurgeluiden laten kinderen als betoverd in slaap vallen.', title_pl = 'Sen przy odgłosach natury 🪄', body_pl = 'Muzyka klasyczna nie działa? W Mądrych bajkach zakończ bajkę i przejdź do tła z samymi odgłosami deszczu lub lasu. Monotonne dźwięki natury usypiają dziecko jak zaczarowane.', title_pt = 'Dormir com sons da natureza 🪄', body_pt = 'A música clássica não resulta? Nas Histórias Inteligentes, feche a história e passe para um fundo só com sons de chuva ou de floresta. Os sons monótonos da natureza adormecem a criança como por magia.', title_sv = 'Sömn med naturljud 🪄', body_sv = 'Fungerar inte klassisk musik? Stäng sagan i Smarta sagor och byt till en bakgrund med bara regn- eller skogsljud. Monotona naturljud får barnet att somna som förtrollat.', title_vi = 'Giấc ngủ cùng âm thanh thiên nhiên 🪄', body_vi = 'Nhạc cổ điển không hiệu quả? Trong Truyện cổ tích thông minh, hãy tắt lời kể và chuyển sang nền âm thanh chỉ có tiếng mưa hoặc tiếng rừng. Âm thanh thiên nhiên đều đều ru bé ngủ như có phép màu.', title_zh = '伴着大自然的声音入睡 🪄', body_zh = '古典音乐不管用？在智能故事里讲完故事后，切换到只有雨声或森林声的背景。单调的大自然声音会让孩子像被施了魔法一样睡着。' WHERE id = 'ba525880-dd70-46d8-9c0c-f0fb9b49240c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Suspiros de adulto 😔', body_es = 'Sentado en el sofá, de repente respira hondo y suspira como un adulto. ¡Te copia de maravilla! Observa desde fuera con una sonrisa estas caras tan dramáticas.', title_fr = 'Les soupirs de grande personne 😔', body_fr = 'Assis sur le canapé, il pousse soudain un grand soupir, comme les adultes. Il vous copie si bien ! Regardez simplement ses mimiques dramatiques en souriant.', title_hi = 'बड़ों जैसी आहें 😔', body_hi = 'सोफ़े पर बैठे-बैठे अचानक बड़ों की तरह गहरी साँस लेकर आह भरता है? वह आपकी कितनी अच्छी नकल करता है! उसके इन नाटकीय हाव-भावों को बस मुस्कुराते हुए दूर से देखिए।', title_id = 'Keluh kesah ala orang dewasa 😔', body_id = 'Ia duduk di sofa lalu tiba-tiba menarik napas dalam dan menghela napas seperti orang dewasa. Ia meniru Anda dengan sangat baik! Saksikan saja ekspresi dramatisnya ini sambil tersenyum.', title_ja = '大人のようなため息 😔', body_ja = 'ソファに座って、急に大人のように深く息をついてため息をもらしますか？あなたのことを本当によくまねしています！このドラマチックな表情を、少し離れて笑顔で見守りましょう。', title_ko = '어른 같은 한숨 😔', body_ko = '소파에 앉아 갑자기 어른처럼 깊은 한숨을 쉬나요? 엄마를 정말 똑같이 따라 하네요! 이 드라마틱한 표정을 그냥 웃으며 지켜보세요.', title_nl = 'Zuchten als een grote 😔', body_nl = 'Zit hij op de bank en haalt hij ineens diep adem en zucht hij als een volwassene? Hij kopieert je zo goed! Kijk gewoon glimlachend naar zijn dramatische gezichtjes.', title_pl = 'Westchnienia dorosłego 😔', body_pl = 'Siedzi na kanapie i nagle, jak dorosły, bierze głęboki oddech i wzdycha. Tak dobrze cię kopiuje! Po prostu obserwuj z boku z uśmiechem te dramatyczne miny.', title_pt = 'Suspiros de gente crescida 😔', body_pt = 'Sentado no sofá, respira fundo de repente e suspira como os adultos. Copia-a tão bem! Observe de longe, a sorrir, estas expressões dramáticas.', title_sv = 'Vuxensuckar 😔', body_sv = 'Sitter barnet i soffan och andas plötsligt djupt och suckar som en vuxen? Hen kopierar dig så bra! Titta bara på de dramatiska minerna med ett leende på avstånd.', title_vi = 'Tiếng thở dài như người lớn 😔', body_vi = 'Ngồi trên sofa, bé bỗng hít thật sâu và thở dài như người lớn. Bé bắt chước mẹ giỏi quá! Hãy chỉ mỉm cười quan sát những biểu cảm đầy kịch tính ấy.', title_zh = '大人般的唉声叹气 😔', body_zh = '坐在沙发上，突然像大人一样深深吸口气，长叹一声。模仿得太像你了！在一旁笑着欣赏这些戏剧化的表情就好。' WHERE id = 'ba82984e-ccd6-40f9-b991-bf586ff48b9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las luces extra de la habitación y las pantallas de las tablets. La producción de la hormona melatonina solo se acelera en un ambiente tranquilo y oscuro.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre. La sécrétion de mélatonine ne s''accélère que dans le calme et le noir.', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीन बंद कर दीजिए। मेलाटोनिन हार्मोन सिर्फ़ शांत और अंधेरे माहौल में तेज़ी से बनता है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar. Produksi hormon melatonin hanya meningkat dalam suasana tenang dan gelap.', body_ja = '早く寝つけるように、部屋の余分な明かりとタブレットの画面をすべて消しましょう。メラトニンの分泌は、静かで暗い環境でこそ早まります。', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명과 태블릿 화면을 모두 꺼 주세요. 멜라토닌은 조용하고 어두운 환경에서만 빠르게 분비돼요.', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en tabletschermen in de kamer uit. Melatonine wordt alleen in een rustige, donkere omgeving sneller aangemaakt.', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Wydzielanie melatoniny przyspiesza tylko w spokojnym i ciemnym otoczeniu.', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets. A produção da hormona melatonina só acelera num ambiente calmo e escuro.', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplattornas skärmar i rummet. Melatoninet utsöndras snabbare bara i en lugn och mörk miljö.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng. Hormone melatonin chỉ được tiết ra nhanh hơn trong môi trường yên tĩnh và tối.', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光和平板屏幕。褪黑素只有在安静、黑暗的环境里才会加快分泌。' WHERE id = '2521dffb-415b-4bec-81f4-b18ee93644d8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de recargar a mamá 🔋', body_es = 'Está haciendo un puzle solo y lleva 10 minutos en silencio. Y tú quieres aprovechar ese momento para recoger la casa. ¡No! Ve a tumbarte en el sofá. Tu batería también tiene que cargarse para aguantar hasta la noche.', title_fr = 'Maman se recharge 🔋', body_fr = 'Il fait un puzzle tout seul et il est silencieux depuis 10 minutes. Et vous voulez profiter de ce moment pour ranger la maison. Non ! Allez vous allonger sur le canapé. Votre batterie aussi doit se recharger pour tenir jusqu''au soir.', title_hi = 'माँ का चार्जिंग टाइम 🔋', body_hi = 'वह खुद पज़ल जोड़ रहा है और 10 मिनट से चुप है। और आप उस पल को घर समेटने में लगाना चाहती हैं? नहीं! जाइए, सोफ़े पर लेट जाइए। शाम तक टिके रहने के लिए आपकी बैटरी भी चार्ज होनी चाहिए।', title_id = 'Waktu isi ulang Ibu 🔋', body_id = 'Ia menyusun puzzle sendiri dan sudah 10 menit tenang. Dan Anda ingin menghabiskan momen itu untuk membereskan rumah. Jangan! Berbaringlah di sofa. Baterai Anda juga harus terisi agar bisa bertahan sampai malam.', title_ja = 'ママの充電タイム 🔋', body_ja = 'お子さんがひとりでパズルをして、もう10分も静かです。あなたはこの時間を片づけに使いたいと思っていませんか？ダメ！ソファに横になりましょう。夕方までもつように、あなたのバッテリーも充電しなきゃ。', title_ko = '엄마의 충전 시간 🔋', body_ko = '아이가 혼자 퍼즐을 맞추며 10분째 조용하네요. 그런데 그 시간에 집을 치우려고요? 안 돼요! 소파에 누우세요. 저녁까지 버티려면 엄마의 배터리도 충전해야 해요.', title_nl = 'Oplaadtijd voor mama 🔋', body_nl = 'Hij doet in zijn eentje een puzzel en is al 10 minuten stil. En jij wilt dat moment gebruiken om op te ruimen. Nee! Ga op de bank liggen. Ook jouw batterij moet opladen, zodat je de avond haalt.', title_pl = 'Czas na naładowanie mamy 🔋', body_pl = 'Sam układa układankę i od 10 minut jest cicho. A ty chcesz wykorzystać tę chwilę na sprzątanie domu. Nie! Idź, połóż się na kanapie. Twoja bateria też musi się naładować, żebyś wytrzymała do wieczora.', title_pt = 'Hora de recarregar a mãe 🔋', body_pt = 'Está a fazer um puzzle sozinho e há 10 minutos que não se ouve nada. E a mãe quer usar esse momento para arrumar a casa? Não! Vá deitar-se no sofá. A sua bateria também tem de carregar para aguentar até à noite.', title_sv = 'Mammas laddningstid 🔋', body_sv = 'Barnet lägger pussel själv och har varit tyst i 10 minuter. Och du vill lägga stunden på att städa. Nej! Gå och lägg dig på soffan. Ditt batteri behöver också laddas så att du orkar till kvällen.', title_vi = 'Giờ sạc pin của mẹ 🔋', body_vi = 'Bé đang tự ghép hình và đã im lặng 10 phút. Còn mẹ thì muốn tranh thủ dọn nhà. Không! Hãy đi nằm xuống sofa. Pin của mẹ cũng cần được sạc đầy để trụ được đến tối.', title_zh = '妈妈的充电时间 🔋', body_zh = '宝宝在自己拼拼图，已经安静10分钟了。而你想用这段时间收拾家里。不行！去沙发上躺着。你的电池也得充满，才能撑到晚上。' WHERE id = '8ca17d8b-45e4-4184-b598-9b59778d5b0c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gramática inventada 🗣️', body_es = 'Ha descubierto tiempos verbales raros y graciosos como «Yo fui-iba» o «Él venía-había». ¡Su vocabulario crece! No le corrijas riéndote: simplemente confírmale repitiendo la frase correcta.', title_fr = 'Grammaire inventée 🗣️', body_fr = '« J''ai allé-fait », « Il venait-était » : il a inventé des temps bizarres et comiques. Son vocabulaire se développe ! Ne le corrigez pas en riant, validez simplement en répétant la phrase correcte.', title_hi = 'गढ़ा हुआ व्याकरण 🗣️', body_hi = '''मैं गया-गया था'', ''वह आ रहा होगा था'' जैसे अजीब और मज़ेदार काल के रूप खोज लिए हैं? उसकी शब्दावली बढ़ रही है! हँसते हुए मत टोकिए, बस सही वाक्य दोहराकर हामी भरिए।', title_id = 'Tata bahasa karangan 🗣️', body_id = 'Ia menemukan bentuk waktu yang aneh dan lucu seperti ''Aku sudah pergian'' atau ''Dia tadi datangnya''. Kosakatanya berkembang! Jangan mengoreksinya sambil tertawa, cukup teguhkan dengan mengulang kalimat yang benar.', title_ja = 'オリジナル文法 🗣️', body_ja = '「行ったった」「来てたった」のような、ふしぎでおもしろい時制を発見しましたか？語彙が育っています！笑いながら直さず、正しい文をくり返して受け止めてあげましょう。', title_ko = '지어낸 문법 🗣️', body_ko = '''나 갔었었어'', ''걔가 오고 있었었대''처럼 별나고 웃긴 시제를 발명했나요? 어휘가 자라고 있어요! 웃으며 고치지 말고 바른 문장으로 다시 말해 주며 맞장구쳐 주세요.', title_nl = 'Verzonnen grammatica 🗣️', body_nl = 'Ontdekt hij vreemde, grappige tijdsvormen als ''Ik ging-deed'' of ''Hij was-kwam-had''? Zijn woordenschat groeit! Verbeter hem niet lachend, maar bevestig het door gewoon de juiste zin te herhalen.', title_pl = 'Wymyślona gramatyka 🗣️', body_pl = '„Ja poszłem był”, „On przychodził był”: odkrywa dziwne i zabawne formy czasu. Jego słownictwo się rozwija! Nie poprawiaj go ze śmiechem, po prostu potwierdź, powtarzając poprawne zdanie.', title_pt = 'Gramática inventada 🗣️', body_pt = 'Descobriu tempos verbais estranhos e cómicos, como "eu fuíii" ou "ele vinhava". O vocabulário está a crescer! Não o corrija a rir: confirme apenas, repetindo a frase certa.', title_sv = 'Påhittad grammatik 🗣️', body_sv = 'Barnet har upptäckt konstiga och roliga tidsformer som ”Jag gickade” och ”Han kommade”. Ordförrådet utvecklas! Rätta inte skrattande, bekräfta bara genom att upprepa den rätta meningen.', title_vi = 'Ngữ pháp tự chế 🗣️', body_vi = 'Bé "phát minh" ra những thì động từ kỳ lạ, buồn cười kiểu "Con đã đi rồi đã", "Bạn ấy đang đến đã". Vốn từ đang phát triển! Đừng cười khi sửa, chỉ cần khẳng định bằng cách nhắc lại câu nói đúng.', title_zh = '自创的语法 🗣️', body_zh = '“我去了了”“他来过了来”，宝宝发现了各种奇怪又好笑的时态。词汇量在发展！别笑着纠正，只要重复正确的句子来肯定宝宝就好。' WHERE id = 'c145c120-a19a-477b-922c-6f3ffc430787' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Refugiarse en el Diario de ánimo 📝', body_es = '¿Nadie ve lo cansada que estás? El Diario de ánimo de la app está ahí para escucharte. Escribe todos los pequeños detalles que hoy te han sacado de quicio y vacía la mente.', title_fr = 'Se réfugier dans le Journal d''humeur 📝', body_fr = 'Personne ne voit à quel point vous êtes fatiguée ? Dans l''application, le Journal d''humeur est là pour vous écouter. Écrivez-y tous les petits détails qui vous ont rendue folle aujourd''hui et videz-vous la tête.', title_hi = 'मूड डायरी में सुकून 📝', body_hi = 'कोई नहीं देखता कि आप कितनी थक गई हैं? ऐप में मूड डायरी आपकी बात सुनने के लिए मौजूद है। आज जिन छोटी-छोटी बातों ने परेशान किया, वे सब वहाँ लिखिए और दिमाग साफ़ कीजिए।', title_id = 'Berlindung di Buku Harian Suasana Hati 📝', body_id = 'Tidak ada yang melihat betapa lelahnya Anda? Buku Harian Suasana Hati di aplikasi ada untuk mendengarkan Anda. Tuliskan semua detail kecil yang membuat Anda kesal hari ini dan jernihkan pikiran.', title_ja = '「気分日記」に逃げこもう 📝', body_ja = 'こんなに疲れていることに、だれも気づいてくれない？アプリの「気分日記」は、あなたの話を聞くためにあります。今日イライラした細かいことを全部書いて、頭をすっきりさせましょう。', title_ko = '기분 일기에 기대기 📝', body_ko = '이렇게 지친 걸 아무도 몰라주나요? 앱의 기분 일기가 엄마 이야기를 들어 줄 거예요. 오늘 나를 힘들게 한 작은 일들을 모두 적고 머리를 비우세요.', title_nl = 'Toevlucht in je Stemmingsdagboek 📝', body_nl = 'Ziet niemand hoe moe je bent? Je Stemmingsdagboek in de app is er om naar je te luisteren. Schrijf alle kleine dingen op die je vandaag gek maakten en maak je hoofd leeg.', title_pl = 'Schronienie w Dzienniku nastroju 📝', body_pl = 'Nikt nie widzi, jak bardzo jesteś zmęczona? Dziennik nastroju w aplikacji jest po to, by cię wysłuchać. Zapisz tam wszystkie drobiazgi, które dziś doprowadzały cię do szału, i oczyść głowę.', title_pt = 'Refúgio no Diário de Humor 📝', body_pt = 'Ninguém vê o quanto está cansada? O Diário de Humor da app está lá para a ouvir. Escreva lá todos os pequenos detalhes que hoje a enlouqueceram e limpe a cabeça.', title_sv = 'En fristad i Humördagboken 📝', body_sv = 'Ser ingen hur trött du är? Humördagboken i appen finns där för att lyssna på dig. Skriv ner alla små detaljer som gjorde dig galen i dag och rensa hjärnan.', title_vi = 'Tìm chốn bình yên trong Nhật ký tâm trạng 📝', body_vi = 'Không ai thấy mẹ mệt mỏi đến thế nào? Nhật ký tâm trạng trong ứng dụng luôn ở đó để lắng nghe mẹ. Hãy viết vào đó mọi chi tiết nhỏ khiến mẹ phát điên hôm nay và giải tỏa đầu óc.', title_zh = '躲进心情日记 📝', body_zh = '没人看见你有多累？应用里的心情日记一直在那里倾听你。把今天让你抓狂的所有小细节都写进去，让大脑清爽一下。' WHERE id = '6e5eaf14-24e1-4f23-8d49-63a035b843ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Al quedarse dormido se sobresalta con el menor ruidito? Revisa la acústica de la habitación y pon ruido blanco para neutralizar los sonidos que entran por la ventana.', body_fr = 'Il sursaute au moindre petit bruit dès qu''il s''endort ? Vérifiez l''acoustique de la chambre et mettez un bruit blanc pour neutraliser les sons venant de la fenêtre.', body_hi = 'सोते ही ज़रा सी खटखट पर चौंक जाता है? कमरे की आवाज़ों को जाँचिए और खिड़की से आने वाली आवाज़ें दबाने के लिए व्हाइट नॉइज़ चलाइए।', body_id = 'Begitu tertidur, ia terkejut oleh bunyi sekecil apa pun? Periksa akustik kamar dan nyalakan suara putih untuk meredam suara dari jendela.', body_ja = '寝ついたとたん、小さな物音にびくっとしますか？部屋の音の環境を確認して、窓の外の音をやわらげるためにホワイトノイズを流しましょう。', body_ko = '잠들자마자 아주 작은 소리에도 깜짝 놀라나요? 방의 소리 환경을 확인하고 창밖 소리를 줄이도록 백색소음을 틀어 주세요.', body_nl = 'Schrikt hij bij het kleinste tikje op zodra hij in slaap valt? Check de akoestiek van de kamer en zet witte ruis aan om geluiden van buiten te neutraliseren.', body_pl = 'Gdy tylko zasypia, wzdryga się na najmniejszy szelest? Sprawdź akustykę pokoju i włącz biały szum, by zneutralizować dźwięki zza okna.', body_pt = 'Mal adormece, assusta-se com o mais pequeno ruído? Verifique a acústica do quarto e ponha ruído branco para neutralizar os sons que vêm da janela.', body_sv = 'Rycker barnet till vid minsta knäpp så fort hen somnat? Kontrollera akustiken i rummet och sätt på vitt brus för att neutralisera ljud från fönstret.', body_vi = 'Vừa chìm vào giấc ngủ, bé đã giật mình vì tiếng động nhỏ nhất? Hãy kiểm tra âm thanh trong phòng và bật tiếng ồn trắng để trung hòa tiếng ồn từ cửa sổ.', body_zh = '一睡着，最小的咔嗒声都会被吓一跳？检查一下房间的声音环境，打开白噪音来屏蔽窗外的声音。' WHERE id = '1e376436-3f0d-4a14-a96b-e1c16c40c937' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pruebas con la comida 🥣', body_es = 'Hoy escupe todo lo que comía hasta ayer. Si no son los dientes, es solo una prueba de voluntad. Mira en Recetas saludables recetas de albóndigas de colores y deliciosas que esconden las verduras.', title_fr = 'Tests alimentaires 🥣', body_fr = 'Aujourd''hui, il recrache tout ce qu''il mangeait jusqu''à hier. S''il n''a pas de problème de dents, c''est juste un test de volonté. Essayez dans les Recettes saines des boulettes colorées et savoureuses aux légumes cachés.', title_hi = 'खाने के प्रयोग 🥣', body_hi = 'कल तक जो सब खाता था, आज थूक देता है? अगर दाँतों की दिक्कत नहीं, तो यह बस इच्छा-शक्ति की परीक्षा है। सेहतमंद रेसिपी में सब्ज़ियाँ छिपाने वाले स्वादिष्ट, रंग-बिरंगे कटलेट आज़माइए।', title_id = 'Ujian makanan 🥣', body_id = 'Hari ini ia menyemburkan semua yang ia makan sampai kemarin. Jika tidak ada masalah gigi, ini hanya uji kemauan. Coba resep perkedel warna-warni yang lezat dengan sayuran tersembunyi di Resep Sehat.', title_ja = '食べ物のお試し期間 🥣', body_ja = '昨日まで食べていたものを、今日は全部ぺっと出しますか？歯の問題がなければ、これはただの意志のテストです。「ヘルシーレシピ」で、野菜をかくしたおいしいカラフルなハンバーグのレシピを見てみましょう。', title_ko = '음식 시험 🥣', body_ko = '어제까지 잘 먹던 걸 오늘은 다 뱉나요? 이가 나는 문제가 아니라면 의지 시험일 뿐이에요. 건강한 레시피에서 채소를 숨긴 맛있고 알록달록한 커틀릿 레시피를 확인해 보세요.', title_nl = 'Eetexperimenten 🥣', body_nl = 'Spuugt hij vandaag alles uit wat hij tot gisteren nog at? Zijn er geen tandjesproblemen, dan is het gewoon een wilstest. Bekijk in Gezonde recepten lekkere, kleurrijke gehaktballetjes waarin groenten verstopt zitten.', title_pl = 'Próby jedzeniowe 🥣', body_pl = 'Wszystko, co jadł jeszcze wczoraj, dziś wypluwa? Jeśli to nie ząbki, to po prostu test woli. Sprawdź w Zdrowych przepisach smaczne, kolorowe kotleciki z ukrytymi warzywami.', title_pt = 'Testes à comida 🥣', body_pt = 'Hoje cospe tudo o que comia até ontem? Se não há problemas com os dentes, é só um teste de vontade. Veja nas Receitas Saudáveis receitas de hambúrgueres coloridos e saborosos com legumes escondidos.', title_sv = 'Mattester 🥣', body_sv = 'Barnet spottar ut allt hen åt fram till i går. Om det inte är tänderna, är det bara ett viljetest. Titta på recept på goda, färgglada biffar med gömda grönsaker i Hälsosamma recept.', title_vi = 'Thử nghiệm món ăn 🥣', body_vi = 'Những món đến hôm qua bé vẫn ăn thì hôm nay lại nhè ra hết. Nếu không có vấn đề về răng, đây chỉ là bài kiểm tra ý chí. Hãy xem trong Công thức lành mạnh những món chả viên nhiều màu thơm ngon giấu rau củ.', title_zh = '食物测试 🥣', body_zh = '到昨天为止都吃的东西，今天全吐出来。如果不是牙齿的问题，这只是意志测试。在健康食谱里看看那些藏着蔬菜、好吃又五颜六色的肉饼做法吧。' WHERE id = 'b83f22c8-15c6-43cf-9689-94f8a790e4b9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ilusión de los 5 minutos ⏱️', body_es = 'Dice «Solo 5 minutos más», pero en su cabeza no existe el concepto de 5 minutos. Pon el temporizador del móvil y, cuando suene, hazle entender que se ha acabado. Que la culpa sea de la tecnología, no tuya.', title_fr = 'L''illusion des 5 minutes ⏱️', body_fr = 'Il dit « Encore 5 minutes », mais dans sa tête, la notion de 5 minutes n''existe pas. Réglez le minuteur du téléphone et expliquez-lui que c''est fini quand il sonne. Que la technologie soit la méchante, pas vous.', title_hi = '5 मिनट का भ्रम ⏱️', body_hi = 'कहता है ''बस 5 मिनट और देखूँ'', लेकिन उसके दिमाग में 5 मिनट की कोई समझ नहीं। फ़ोन पर टाइमर लगाइए और समझाइए कि आवाज़ आते ही खत्म। दोष टेक्नोलॉजी पर जाए, आप पर नहीं।', title_id = 'Ilusi 5 menit ⏱️', body_id = 'Ia bilang ''Nonton 5 menit lagi'', tetapi di otaknya belum ada konsep 5 menit. Pasang timer di ponsel dan jelaskan bahwa saat bunyinya terdengar, waktunya selesai. Biar teknologi yang disalahkan, bukan Anda.', title_ja = '「5分」の幻 ⏱️', body_ja = '「あと5分だけ見る」と言いますが、お子さんの頭に「5分」の感覚はありません。スマホのタイマーをセットして、音が鳴ったらおしまいと伝えましょう。悪者はあなたではなく、テクノロジーに。', title_ko = '5분의 환상 ⏱️', body_ko = '''딱 5분만 더 볼래'' 하지만 아이 머릿속엔 5분이라는 개념이 없어요. 휴대폰 타이머를 맞추고 소리가 울리면 끝이라고 알려 주세요. 나쁜 역할은 엄마 말고 기계가 맡게 하세요.', title_nl = 'De illusie van 5 minuten ⏱️', body_nl = 'Hij zegt ''Nog maar 5 minuutjes kijken'', maar in zijn hoofd bestaat het begrip 5 minuten niet. Zet een timer op je telefoon en leg uit dat het klaar is als hij afgaat. Laat de techniek de schuld krijgen, niet jij.', title_pl = 'Iluzja 5 minut ⏱️', body_pl = 'Mówi „Jeszcze tylko 5 minut pooglądam”, ale w jego głowie nie istnieje pojęcie 5 minut. Nastaw timer w telefonie i wytłumacz, że gdy usłyszy dźwięk, to koniec. Niech winna będzie technologia, nie ty.', title_pt = 'A ilusão dos 5 minutos ⏱️', body_pt = 'Diz "Só mais 5 minutos", mas no cérebro dele não existe a noção de 5 minutos. Programe o temporizador do telemóvel e, quando tocar, ele percebe que acabou. Que a culpa seja da tecnologia, não sua.', title_sv = 'Illusionen om 5 minuter ⏱️', body_sv = 'Barnet säger ”Bara 5 minuter till”, men i barnets hjärna finns inget begrepp om 5 minuter. Ställ in mobilens timer och förklara att det är slut när ljudet hörs. Låt tekniken vara den skyldiga, inte du.', title_vi = 'Ảo tưởng 5 phút ⏱️', body_vi = 'Bé nói "Cho con xem thêm 5 phút thôi", nhưng trong đầu bé chưa có khái niệm 5 phút. Hãy đặt hẹn giờ trên điện thoại và cho bé hiểu chuông reo là hết giờ. Hãy để công nghệ làm "người xấu", không phải mẹ.', title_zh = '“5分钟”的幻觉 ⏱️', body_zh = '说“就再看5分钟”，可宝宝脑子里根本没有“5分钟”的概念。设好手机计时器，让宝宝明白听到铃声就结束了。让科技来当坏人，而不是你。' WHERE id = 'fe01f44d-664a-4a34-8ce6-39e87f7fdab2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Un paso atrás con el orinal? 🚽', body_es = '¿Ya había aprendido a ir al orinal y ahora vuelve a escaparse? Es un retroceso muy normal. No le presiones: pregunta a Anacan AI cómo superar sin crisis esta barrera psicológica.', title_fr = 'Un pas en arrière sur le pot ? 🚽', body_fr = 'Il avait appris à aller sur le pot et maintenant il recommence à avoir des accidents ? C''est une régression très normale. Ne mettez pas la pression, demandez à Anacan AI comment franchir cette barrière psychologique sans crise.', title_hi = 'पॉटी में फिर पीछे? 🚽', body_hi = 'पॉटी जाना सीख गया था, अब फिर बचता है? यह बिल्कुल सामान्य पीछे जाना है। दबाव मत डालिए, Anacan AI से पूछिए कि इस मनोवैज्ञानिक रुकावट को बिना हंगामे के कैसे पार करें।', title_id = 'Mundur di urusan toilet? 🚽', body_id = 'Ia sudah belajar ke pispot, tetapi sekarang mengompol lagi? Ini kemunduran yang sangat normal. Jangan menekannya, tanyakan pada Anacan AI cara melewati hambatan psikologis ini tanpa krisis.', title_ja = 'トイレで後戻り？🚽', body_ja = 'おまるでできるようになったのに、またおもらし？これはとてもよくある後戻りです。プレッシャーをかけずに、この心の壁をかんしゃくなしで乗りこえる方法をAnacan AIに聞いてみましょう。', title_ko = '배변 훈련 뒷걸음질? 🚽', body_ko = '아기 변기 사용을 익혔는데 다시 실수하나요? 아주 정상적인 뒷걸음질이에요. 다그치지 말고 이 심리적 장벽을 떼쓰기 없이 넘는 방법을 Anacan AI에게 물어보세요.', title_nl = 'Een stap terug op het potje? 🚽', body_nl = 'Had hij het potje al onder de knie en loopt het nu weer mis? Dat is een heel normale terugval. Zet hem niet onder druk, maar vraag Anacan AI hoe je deze psychologische drempel zonder strijd overwint.', title_pl = 'Krok wstecz z nocnikiem? 🚽', body_pl = 'Nauczył się już korzystać z nocnika, a teraz znów mu się zdarza? To bardzo normalny regres. Nie naciskaj, zapytaj Anacan AI o sposoby pokonania tej psychologicznej bariery bez kryzysów.', title_pt = 'Um passo atrás no bacio? 🚽', body_pt = 'Já tinha aprendido a usar o bacio e agora volta a fugir? É um recuo muito normal. Não pressione: pergunte ao Anacan AI como ultrapassar esta barreira psicológica sem crises.', title_sv = 'Ett steg tillbaka på toaletten? 🚽', body_sv = 'Barnet hade lärt sig gå på pottan, men nu undviker hen den igen? Det är en helt normal tillbakagång. Pressa inte, fråga Anacan AI hur ni tar er över den här psykologiska barriären utan kris.', title_vi = 'Thụt lùi với việc đi vệ sinh? 🚽', body_vi = 'Bé đã biết đi bô, giờ lại tè dầm? Đây là sự thụt lùi rất bình thường. Đừng tạo áp lực, hãy hỏi Anacan AI cách vượt qua rào cản tâm lý này mà không có khủng hoảng.', title_zh = '如厕倒退了？🚽', body_zh = '本来已经学会用便盆，现在又不去了？这是很正常的倒退。别施加压力，问问Anacan AI，怎样不经历崩溃就跨过这道心理障碍。' WHERE id = '0cd42656-20ce-4f47-aca2-4978ae93880d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Inspírate con el Blog 📱', body_es = '¿Qué saltos de desarrollo vive un niño que se acerca a los 35 meses? ¿Qué debería saber hacer? Echa un vistazo a los artículos de desarrollo del Blog de la app y alégrate al ver lo mucho que avanza tu peque.', title_fr = 'S''inspirer des Blogs 📱', body_fr = 'Quels sont les bonds de développement à l''approche des 35 mois ? Que devrait-il savoir faire ? Parcourez les blogs sur le développement dans l''application et réjouissez-vous de voir à quel point votre enfant progresse.', title_hi = 'ब्लॉग से प्रेरणा 📱', body_hi = '35 महीने के करीब बच्चे के विकास की छलाँगें क्या हैं? उसे क्या-क्या आना चाहिए? ऐप के विकास वाले ब्लॉग देखिए और यह जानकर खुश होइए कि आपका बच्चा कितना आगे है।', title_id = 'Inspirasi dari blog 📱', body_id = 'Apa saja lompatan perkembangan anak menjelang usia 35 bulan? Apa yang seharusnya sudah bisa ia lakukan? Lihat blog perkembangan di aplikasi dan bergembiralah melihat betapa majunya anak Anda.', title_ja = 'ブログでひらめきを 📱', body_ja = '生後35か月が近づく子の発達の飛躍って？何ができるようになるの？アプリの発達ブログをのぞいて、お子さんがどれほど成長しているかを見てよろこびましょう。', title_ko = '블로그에서 영감 얻기 📱', body_ko = '35개월을 앞둔 아이에게는 어떤 발달의 도약이 있을까요? 무엇을 할 수 있어야 할까요? 앱의 발달 블로그를 살펴보고 아이가 얼마나 잘 자라고 있는지 보며 기뻐하세요.', title_nl = 'Inspiratie uit de blogs 📱', body_nl = 'Welke ontwikkelingssprongen maakt een kind van bijna 35 maanden? Wat zou hij moeten kunnen? Bekijk de ontwikkelingsblogs in de app en wees blij als je ziet hoe goed je kind het doet.', title_pl = 'Inspiracja z Bloga 📱', body_pl = 'Jakie skoki rozwojowe czekają dziecko zbliżające się do 35. miesiąca? Co powinno umieć? Zajrzyj do artykułów o rozwoju na Blogu w aplikacji i ciesz się, widząc, jak twoje dziecko idzie naprzód.', title_pt = 'Inspire-se no Blogue 📱', body_pt = 'Que saltos de desenvolvimento tem uma criança perto dos 35 meses? O que deve conseguir fazer? Veja os artigos de desenvolvimento no blogue da app e alegre-se ao ver como o seu filho está adiantado.', title_sv = 'Inspiration från bloggarna 📱', body_sv = 'Vilka utvecklingssprång gör ett barn som närmar sig 35 månader? Vad ska barnet kunna? Titta i utvecklingsbloggarna i appen och gläd dig över hur långt ditt barn har kommit.', title_vi = 'Tìm cảm hứng từ Blog 📱', body_vi = 'Bé gần 35 tháng có những bước nhảy vọt phát triển nào? Bé nên làm được gì? Hãy xem các bài blog về phát triển trong ứng dụng và vui mừng khi thấy bé tiến bộ thế nào.', title_zh = '从博客中获得灵感 📱', body_zh = '快到35个月的宝宝会有哪些发育飞跃？应该会做什么？看看应用里的发育博客，你会高兴地发现自己的孩子进步了这么多。' WHERE id = '3164bc6c-fe7e-4273-94e8-6750bee50d0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preparando la victoria 💆‍♂️', body_es = 'Cuando tu peque se duerma, felicitaos tu pareja y tú por la gran cifra de mañana y daos un pequeño masaje de hombros. Para tener energía el día de la celebración, los dos tenéis que descansar.', title_fr = 'Préparatifs de victoire 💆‍♂️', body_fr = 'Une fois l''enfant couché, félicitez-vous avec votre partenaire pour le grand chiffre de demain et offrez-vous un petit massage des épaules. Pour avoir de l''énergie le jour de la fête, vous devez vous reposer tous les deux.', title_hi = 'जीत की तैयारी 💆‍♂️', body_hi = 'बच्चे के सोने के बाद कल की बड़ी संख्या के लिए अपने पार्टनर को बधाई दीजिए और एक-दूसरे के कंधों की छोटी सी मालिश कीजिए। जश्न के दिन की ऊर्जा के लिए आप दोनों का आराम करना ज़रूरी है।', title_id = 'Persiapan kemenangan 💆‍♂️', body_id = 'Setelah anak tidur, saling ucapkan selamat dengan pasangan untuk angka besar esok hari dan saling memijat bahu sebentar. Agar punya energi di hari perayaan, kalian berdua perlu beristirahat.', title_ja = 'お祝いの準備 💆‍♂️', body_ja = 'お子さんが眠ったら、明日の大きな節目をパートナーとお互いにお祝いして、肩を少しもみ合いましょう。記念日を元気に迎えるために、ふたりとも休むことが大切です。', title_ko = '승리를 위한 준비 💆‍♂️', body_ko = '아이가 잠들면 배우자와 내일의 큰 숫자를 미리 축하하며 서로 짧게 어깨 마사지를 해 주세요. 기념일을 즐길 에너지를 위해 두 사람 모두 쉬어야 해요.', title_nl = 'Voorbereiding op de overwinning 💆‍♂️', body_nl = 'Feliciteer elkaar als hij slaapt alvast met het grote getal van morgen en geef elkaar een kleine schoudermassage. Voor de energie op de jubileumdag moeten jullie allebei uitgerust zijn.', title_pl = 'Przygotowania do zwycięstwa 💆‍♂️', body_pl = 'Gdy dziecko zaśnie, pogratulujcie sobie z partnerem jutrzejszej wielkiej liczby i zróbcie sobie nawzajem krótki masaż ramion. Żeby mieć energię na dzień jubileuszu, oboje musicie odpocząć.', title_pt = 'Preparar a vitória 💆‍♂️', body_pt = 'Depois de a criança adormecer, deem os parabéns um ao outro pelo grande número de amanhã e façam uma pequena massagem nos ombros. Para terem energia no dia da festa, os dois precisam de descansar.', title_sv = 'Inför segern 💆‍♂️', body_sv = 'När barnet har somnat, gratulera varandra inför morgondagens stora siffra och ge varandra en kort axelmassage. Ni behöver båda vila för att ha energi till jubileumsdagen.', title_vi = 'Chuẩn bị cho chiến thắng 💆‍♂️', body_vi = 'Khi bé đã ngủ, hãy cùng chồng chúc mừng nhau trước con số lớn ngày mai và mát-xa vai cho nhau một chút. Để có năng lượng cho ngày kỷ niệm, cả hai đều cần nghỉ ngơi.', title_zh = '为胜利做准备 💆‍♂️', body_zh = '孩子睡着后，和另一半为明天那个大数字互相道贺，再互相捏捏肩。为了纪念日的好状态，你们俩都得好好休息。' WHERE id = '4d45db57-1817-4fc6-ad71-f2aeb4cd1050' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Carreras en el dormitorio 🏃‍♂️', body_es = '¿En lugar de dormir salta en el sofá? ¿No se acaban las excusas de «un poquito más de agua»? Pon el temporizador de sueño y mantén tus límites.', title_fr = 'Évasion dans la chambre 🏃‍♂️', body_fr = 'Au lieu de dormir, il saute sur le canapé ? Les excuses du « encore un peu d''eau » n''en finissent pas ? Lancez le Minuteur de sommeil et tenez vos limites.', title_hi = 'बेडरूम में भागम-भाग 🏃‍♂️', body_hi = 'सोने के बजाय सोफ़े पर कूदता है? ''थोड़ा और पानी'' वाले बहाने खत्म ही नहीं होते? स्लीप टाइमर चालू कीजिए, अपनी सीमाओं पर टिके रहिए।', title_id = 'Kabur di kamar tidur 🏃‍♂️', body_id = 'Bukannya tidur, ia malah melompat-lompat di sofa? Alasan ''minta air lagi'' tak ada habisnya? Nyalakan Timer Tidur dan jaga batasan Anda.', title_ja = '寝室での逃走劇 🏃‍♂️', body_ja = '寝るかわりにソファで跳ねていますか？「お水もうちょっと」の言い訳が止まらない？睡眠タイマーをオンにして、ルールを守りましょう。', title_ko = '침실 탈출 🏃‍♂️', body_ko = '자는 대신 소파에서 뛰나요? ''물 조금만 더'' 핑계가 끝이 없나요? 수면 타이머를 켜고 경계를 지켜 주세요.', title_nl = 'Ontsnapping uit de slaapkamer 🏃‍♂️', body_nl = 'Springt hij op de bank in plaats van te slapen? Komen er eindeloos ''nog wat water''-smoesjes? Zet de Slaaptimer aan en bewaak je grenzen.', title_pl = 'Ucieczka w sypialni 🏃‍♂️', body_pl = 'Zamiast spać, skacze po kanapie? Wymówki „jeszcze trochę wody” się nie kończą? Włącz timer snu i pilnuj swoich granic.', title_pt = 'Fuga no quarto 🏃‍♂️', body_pt = 'Em vez de dormir, salta no sofá? As desculpas do "só mais um bocadinho de água" não acabam? Ligue o temporizador de sono e mantenha os seus limites.', title_sv = 'Spring i sovrummet 🏃‍♂️', body_sv = 'Hoppar barnet i soffan i stället för att sova? Tar ursäkterna om ”lite vatten till” aldrig slut? Starta sömntimern och håll dina gränser.', title_vi = 'Chạy trốn trong phòng ngủ 🏃‍♂️', body_vi = 'Bé nhảy trên sofa thay vì ngủ? Những cái cớ "thêm chút nước nữa" mãi không hết? Hãy bật Bộ hẹn giờ ngủ và giữ vững giới hạn.', title_zh = '卧室里的逃跑 🏃‍♂️', body_zh = '不睡觉，反而在沙发上蹦？“再喝点水”的借口没完没了？打开睡眠计时器，守住你的界限。' WHERE id = '41e90866-d00f-459e-8936-e28d83f9d539' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Turno de juego de papá 👨‍👧', body_es = 'La maternidad no es una maratón sin fin. Que hoy papá ayude a tu peque a soltar energía en el parque, y tú disfruta de la soledad en el sofá.', title_fr = 'Papa de service pour le jeu 👨‍👧', body_fr = 'La maternité n''est pas un marathon sans fin. Aujourd''hui, que papa défoule l''enfant au parc, pendant que vous savourez un moment seule sur le canapé.', title_hi = 'पापा की खेल वाली बारी 👨‍👧', body_hi = 'माँ होना कभी न खत्म होने वाली मैराथन नहीं है। आज बच्चे की ऊर्जा पापा पार्क में निकालें, और आप सोफ़े पर अकेले होने का मज़ा लीजिए।', title_id = 'Giliran Ayah bermain 👨‍👧', body_id = 'Menjadi ibu bukan maraton tanpa akhir. Hari ini biar Ayah yang menyalurkan energi anak di taman, sementara Anda menikmati waktu sendiri di sofa.', title_ja = 'パパの遊び当番 👨‍👧', body_ja = '子育ては終わりのないマラソンではありません。今日はパパに公園でお子さんのエネルギーを発散させてもらい、あなたはソファでひとりの時間を味わいましょう。', title_ko = '아빠의 놀이 당번 👨‍👧', body_ko = '엄마 노릇은 끝없는 마라톤이 아니에요. 오늘 아이의 에너지는 아빠가 공원에서 빼 주게 하고, 엄마는 소파에서 혼자만의 시간을 즐기세요.', title_nl = 'Speelbeurt voor papa 👨‍👧', body_nl = 'Moederschap is geen eindeloze marathon. Laat papa vandaag in het park zijn energie eruit laten, en geniet jij op de bank van wat tijd alleen.', title_pl = 'Kolej taty na zabawę 👨‍👧', body_pl = 'Macierzyństwo to nie niekończący się maraton. Niech dziś tata pomoże dziecku spalić energię w parku, a ty delektuj się samotnością na kanapie.', title_pt = 'O turno de brincadeira do pai 👨‍👧', body_pt = 'A maternidade não é uma maratona sem fim. Hoje é o pai que gasta a energia da criança no parque, e a mãe saboreia a solidão no sofá.', title_sv = 'Pappas lekskift 👨‍👧', body_sv = 'Moderskap är inget ändlöst maraton. Låt pappa ta ut barnets energi i parken i dag medan du njuter av ensamheten på soffan.', title_vi = 'Ca chơi của bố 👨‍👧', body_vi = 'Làm mẹ không phải cuộc chạy marathon không hồi kết. Hôm nay để bố đưa bé ra công viên xả năng lượng, còn mẹ tận hưởng sự yên tĩnh một mình trên sofa.', title_zh = '爸爸的游戏时间 👨‍👧', body_zh = '当妈妈不是一场没有终点的马拉松。今天让爸爸带宝宝在公园里释放精力，你在沙发上享受独处的滋味吧。' WHERE id = '4f9eced2-7736-4f35-ad7d-6205edaad1e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gorros de invierno en verano 🧢', body_es = '¿Quiere vestirse justo al contrario de lo que pide el tiempo? En esta guerra por la independencia, dale pequeñas opciones para elegir.', title_fr = 'Bonnets d''hiver en été 🧢', body_fr = 'Il veut s''habiller complètement à l''opposé de la météo ? Dans cette bataille pour l''indépendance, proposez-lui de petits choix.', title_hi = 'गर्मी में सर्दी वाली टोपी 🧢', body_hi = 'मौसम के बिल्कुल उलट कपड़े पहनना चाहता है? आज़ादी की इस जंग में उसे छोटे-छोटे विकल्प दीजिए।', title_id = 'Topi musim dingin di musim panas 🧢', body_id = 'Ia ingin berpakaian yang sama sekali tidak sesuai cuaca? Dalam perang kemandirian ini, beri ia pilihan-pilihan kecil.', title_ja = '夏に冬の帽子 🧢', body_ja = '天気とまったく合わない服を着たがりますか？自立の戦いでは、小さな選択肢を与えてあげましょう。', title_ko = '여름에 겨울 모자 🧢', body_ko = '날씨와 정반대로 입겠다고 하나요? 이 독립 전쟁에서는 작은 선택지를 주세요.', title_nl = 'Wintermutsen in de zomer 🧢', body_nl = 'Wil hij kleding aan die totaal niet bij het weer past? Geef hem in deze strijd om zelfstandigheid kleine keuzes.', title_pl = 'Zimowe czapki latem 🧢', body_pl = 'Chce się ubrać zupełnie wbrew pogodzie? W tej walce o samodzielność dawaj mu małe wybory.', title_pt = 'Gorros de inverno no verão 🧢', body_pt = 'Quer vestir algo totalmente contrário ao tempo? Nesta guerra pela independência, dê-lhe pequenas escolhas.', title_sv = 'Vintermössa på sommaren 🧢', body_sv = 'Vill barnet klä sig helt tvärtemot vädret? Ge barnet små val i kampen för självständighet.', title_vi = 'Mũ mùa đông giữa mùa hè 🧢', body_vi = 'Bé muốn mặc đồ hoàn toàn trái ngược với thời tiết? Trong cuộc chiến giành độc lập này, hãy cho bé những lựa chọn nhỏ.', title_zh = '夏天戴冬帽 🧢', body_zh = '想穿得和天气完全相反？在这场独立之战里，给宝宝一些小小的选择吧。' WHERE id = 'e18107ed-4459-4f40-b466-2d79ae0ff98c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La máquina de preguntas sin fin 🤔', body_es = '¿Los «¿Por qué?» y «¿Cómo?» te agotan la mente? Aprende con Anacan AI a responder con lógica y sin aburrirte a sus ganas de descubrir. Tu paciencia es su desarrollo.', title_fr = 'La machine à questions sans fin 🤔', body_fr = 'Les « Pourquoi ? » et les « Comment ? » vous épuisent ? Découvrez avec Anacan AI comment répondre à sa soif de découverte avec logique et sans vous lasser. Votre patience, c''est son développement.', title_hi = 'कभी न रुकने वाली सवालों की मशीन 🤔', body_hi = '''क्यों?'', ''कैसे?'' वाले सवाल दिमाग थका रहे हैं? Anacan AI से जानिए कि उसकी खोज की जिज्ञासा का बिना ऊबे, तर्कसंगत जवाब कैसे दें। आपका सब्र ही उसका विकास है।', title_id = 'Mesin pertanyaan tanpa henti 🤔', body_id = 'Pertanyaan ''Kenapa?'' dan ''Bagaimana?'' membuat otak Anda lelah? Pelajari dari Anacan AI cara menjawab rasa ingin tahunya dengan logis tanpa bosan. Kesabaran Anda adalah perkembangannya.', title_ja = '終わらない質問マシーン 🤔', body_ja = '「なんで？」「どうやって？」の質問で頭が疲れていませんか？お子さんの探究心に、うんざりせず筋の通った答えを返す方法を、Anacan AIから学びましょう。あなたの忍耐が、お子さんの成長になります。', title_ko = '끝없는 질문 기계 🤔', body_ko = '''왜?'', ''어떻게?'' 질문에 머리가 지쳤나요? 아이의 탐구심에 지루하지 않고 논리적으로 대답하는 방법을 Anacan AI에게 배워 보세요. 엄마의 인내가 곧 아이의 성장이에요.', title_nl = 'De eindeloze vragenmachine 🤔', body_nl = 'Word je moe van alle ''Waarom?''- en ''Hoe?''-vragen? Leer van Anacan AI hoe je zijn ontdekkingsdrang logisch beantwoordt zonder je te vervelen. Jouw geduld is zijn ontwikkeling.', title_pl = 'Niekończąca się maszyna do pytań 🤔', body_pl = 'Pytania „Dlaczego?” i „Jak?” męczą twoją głowę? Dowiedz się od Anacan AI, jak bez znużenia, logicznie odpowiadać na jego ciekawość świata. Twoja cierpliwość to jego rozwój.', title_pt = 'A máquina de perguntas sem fim 🤔', body_pt = 'Os "Porquê?" e os "Como?" cansam-lhe a cabeça? Aprenda com o Anacan AI a responder à curiosidade dele com lógica e sem se aborrecer. A sua paciência é o desenvolvimento dele.', title_sv = 'Den ändlösa frågemaskinen 🤔', body_sv = 'Tröttar frågorna ”Varför?” och ”Hur?” ut hjärnan? Lär dig av Anacan AI hur du svarar logiskt och utan att tröttna på barnets upptäckarlust. Ditt tålamod är barnets utveckling.', title_vi = 'Cỗ máy hỏi không ngừng 🤔', body_vi = 'Những câu "Tại sao?", "Thế nào?" khiến đầu óc mẹ mệt mỏi? Hãy học từ Anacan AI cách trả lời sự tò mò khám phá của bé một cách hợp lý mà không thấy chán. Sự kiên nhẫn của mẹ chính là sự phát triển của bé.', title_zh = '停不下来的提问机器 🤔', body_zh = '“为什么？”“怎么做？”问得你脑子都累了？向Anacan AI学学怎样不厌烦、有逻辑地回应宝宝的探索欲。你的耐心，就是宝宝的成长。' WHERE id = '37ca7eb9-999f-4245-9a90-94f0e28e6df4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diario del silencio 📝', body_es = 'El huracán de casa por fin se ha dormido. Ahora coge el móvil y escríbete en el Diario de ánimo una carta de agradecimiento por haber sobrevivido a hoy. Puedes con esto.', title_fr = 'Le journal du silence 📝', body_fr = 'La petite tornade de la maison s''est enfin endormie. Prenez votre téléphone et écrivez-vous dans le Journal d''humeur une lettre de remerciement pour avoir survécu à cette journée. Vous y arrivez.', title_hi = 'खामोशी की डायरी 📝', body_hi = 'घर का तूफ़ान आखिरकार सो गया। अब फ़ोन उठाइए और मूड डायरी में आज का दिन पार कर लेने के लिए खुद को धन्यवाद की चिट्ठी लिखिए। आप यह कर सकती हैं।', title_id = 'Buku harian keheningan 📝', body_id = 'Badai di rumah akhirnya tertidur. Sekarang ambil ponsel dan tulis surat terima kasih untuk diri sendiri di Buku Harian Suasana Hati karena telah bertahan hari ini. Anda pasti bisa.', title_ja = '静けさの日記 📝', body_ja = '家の小さな台風がやっと眠りました。スマホを手に取って、「気分日記」に今日を乗りきった自分への感謝の手紙を書きましょう。あなたならできます。', title_ko = '고요의 일기 📝', body_ko = '집 안의 작은 태풍이 드디어 잠들었어요. 이제 휴대폰을 들고 기분 일기에 오늘을 버텨 낸 나에게 감사 편지를 써 보세요. 엄마는 해낼 수 있어요.', title_nl = 'Dagboek van de stilte 📝', body_nl = 'De orkaan in huis slaapt eindelijk. Pak nu je telefoon en schrijf in je Stemmingsdagboek een bedankbrief aan jezelf omdat je vandaag hebt overleefd. Jij kunt dit.', title_pl = 'Dziennik ciszy 📝', body_pl = 'Domowy huragan w końcu zasnął. Teraz weź telefon i napisz w Dzienniku nastroju list z podziękowaniem dla siebie za to, że przetrwałaś dzisiejszy dzień. Dajesz radę.', title_pt = 'Diário do silêncio 📝', body_pt = 'O furacão da casa finalmente adormeceu. Agora pegue no telemóvel e escreva no Diário de Humor uma carta de agradecimento a si mesma por ter sobrevivido a hoje. É capaz disto.', title_sv = 'Tystnadens dagbok 📝', body_sv = 'Orkanen hemma har äntligen somnat. Ta nu mobilen och skriv ett tackbrev till dig själv i Humördagboken för att du överlevde i dag också. Du klarar det här.', title_vi = 'Nhật ký tĩnh lặng 📝', body_vi = '"Cơn lốc" trong nhà cuối cùng đã ngủ. Giờ hãy cầm điện thoại lên và viết vào Nhật ký tâm trạng một lá thư cảm ơn chính mình vì đã vượt qua hôm nay. Mẹ làm được mà.', title_zh = '安静日记 📝', body_zh = '家里的小旋风终于睡着了。现在拿起手机，在心情日记里给自己写一封感谢信，谢谢自己又挺过了一天。你做得到。' WHERE id = '70e9f70c-b53f-462f-9274-badc9beebd25' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La resistencia del «Yo solo» 🛑', body_es = '¿Quiere atarse él solo los cordones y se te van 10 minutos? No le metas prisa, dale tiempo. Intentarlo y equivocarse es la base de su futura capacidad para resolver problemas.', title_fr = 'La résistance du « Tout seul » 🛑', body_fr = 'Il veut faire ses lacets tout seul et vous y perdez 10 minutes ? Ne le pressez pas, laissez-lui du temps. Ses essais et ses erreurs sont la base de sa future capacité à résoudre les problèmes.', title_hi = '''मैं खुद'' वाली ज़िद 🛑', body_hi = 'जूते के फीते खुद बाँधना चाहता है और आपके 10 मिनट चले जाते हैं? जल्दी मत कीजिए, उसे समय दीजिए। कोशिश करना और गलती करना ही आगे समस्याएँ सुलझाने की उसकी क्षमता की नींव है।', title_id = 'Ngotot ''Aku sendiri'' 🛑', body_id = 'Ia ingin mengikat tali sepatunya sendiri dan 10 menit Anda pun habis? Jangan terburu-buru, beri ia waktu. Mencoba dan salah adalah dasar kemampuannya memecahkan masalah kelak.', title_ja = '「自分で！」の抵抗 🛑', body_ja = '自分で靴ひもを結びたがって、10分もかかっていますか？急がず、時間をあげましょう。挑戦と失敗が、将来の問題解決力の土台になります。', title_ko = '''내가 할 거야'' 고집 🛑', body_ko = '신발 끈을 혼자 묶겠다고 해서 10분이 걸리나요? 서두르지 말고 시간을 주세요. 시도하고 틀려 보는 경험이 앞으로의 문제 해결 능력의 바탕이 돼요.', title_nl = 'Het verzet van ''Zelf doen'' 🛑', body_nl = 'Wil hij zelf zijn veters strikken en kost dat je 10 minuten? Haast je niet, geef hem de tijd. Proberen en vergissen is de basis voor zijn probleemoplossend vermogen later.', title_pl = 'Opór „Ja sam” 🛑', body_pl = 'Chce sam zawiązać sznurowadła i zajmuje ci to 10 minut? Nie spiesz się, daj mu czas. Próby i błędy to fundament jego przyszłej umiejętności rozwiązywania problemów.', title_pt = 'A resistência do "Eu sozinho" 🛑', body_pt = 'Quer apertar os atacadores sozinho e lá se vão 10 minutos? Não o apresse, dê-lhe tempo. Tentar e errar é a base da capacidade dele de resolver problemas no futuro.', title_sv = 'Motståndet i ”Jag själv” 🛑', body_sv = 'Vill barnet knyta skosnörena själv och det tar 10 minuter? Stressa inte, ge barnet tid. Att försöka och misslyckas är grunden för förmågan att lösa problem i framtiden.', title_vi = 'Sự kháng cự "Con tự làm" 🛑', body_vi = 'Bé muốn tự buộc dây giày và mẹ mất 10 phút chờ? Đừng vội, hãy cho bé thời gian. Những lần thử và sai là nền tảng cho kỹ năng giải quyết vấn đề sau này của bé.', title_zh = '“我自己来”的坚持 🛑', body_zh = '想自己系鞋带，花掉你10分钟？别着急，给宝宝时间。尝试和犯错，是宝宝将来解决问题能力的基础。' WHERE id = 'cac1efaa-10e1-4f19-b586-507cb8610102' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Café y meditación ☕', body_es = '¿Ha puesto la habitación patas arriba? Olvídate de limpiar. Mientras está entretenido, siéntate en el sofá, tómate tu café caliente y, solo mirando la pared, pon tu mente a cero durante 10 minutos.', title_fr = 'Café et méditation ☕', body_fr = 'Il a mis la pièce sens dessus dessous ? Laissez tomber le ménage. Pendant qu''il est occupé, asseyez-vous sur le canapé, buvez votre café chaud et regardez simplement le mur 10 minutes pour remettre votre cerveau à zéro.', title_hi = 'कॉफ़ी और मेडिटेशन ☕', body_hi = 'कमरा उलट-पुलट कर दिया? सफ़ाई छोड़िए। जब तक बच्चा अपने में मगन है, सोफ़े पर बैठिए, गर्म कॉफ़ी पीजिए और बस दीवार को देखते हुए 10 मिनट दिमाग को रीसेट कीजिए।', title_id = 'Kopi dan meditasi ☕', body_id = 'Kamar sudah jungkir balik? Lupakan bersih-bersih. Selagi anak asyik sendiri, duduklah di sofa, minum kopi hangat Anda, dan kosongkan pikiran selama 10 menit sambil menatap dinding saja.', title_ja = 'コーヒーとめい想 ☕', body_ja = '部屋がひっくり返ったような散らかりよう？片づけはひとまず放っておきましょう。お子さんが夢中で遊んでいる間にソファに座り、温かいコーヒーを飲みながら壁を見つめて、10分間頭をリセットして。', title_ko = '커피와 명상 ☕', body_ko = '방이 난장판이 됐나요? 청소는 잠시 잊으세요. 아이가 혼자 노는 동안 소파에 앉아 따뜻한 커피를 마시며 10분 동안 벽만 바라보며 머리를 비우세요.', title_nl = 'Koffie en meditatie ☕', body_nl = 'Heeft hij de kamer op zijn kop gezet? Laat het opruimen maar zitten. Ga op de bank zitten terwijl hij zoet is, drink je warme koffie en staar 10 minuten naar de muur om je hoofd te resetten.', title_pl = 'Kawa i medytacja ☕', body_pl = 'Wywrócił pokój do góry nogami? Odpuść sprzątanie. Gdy dziecko jest czymś zajęte, usiądź na kanapie, wypij gorącą kawę i przez 10 minut po prostu patrz w ścianę, resetując głowę.', title_pt = 'Café e meditação ☕', body_pt = 'Virou o quarto do avesso? Esqueça a limpeza. Enquanto ele está entretido, sente-se no sofá, beba o seu café quente e, a olhar simplesmente para a parede, reponha o cérebro a zero durante 10 minutos.', title_sv = 'Kaffe och meditation ☕', body_sv = 'Har barnet vänt upp och ner på rummet? Strunta i städningen. Medan barnet är upptaget, sätt dig i soffan, drick ditt varma kaffe och nollställ hjärnan i 10 minuter genom att bara stirra på väggen.', title_vi = 'Cà phê và thiền ☕', body_vi = 'Căn phòng bị đảo lộn tung? Gác việc dọn dẹp lại. Khi bé đang mải chơi, hãy ngồi xuống sofa, uống cà phê nóng và chỉ nhìn vào bức tường 10 phút để làm mới đầu óc.', title_zh = '咖啡与冥想 ☕', body_zh = '房间被翻了个底朝天？别管打扫了。趁孩子自己玩得专心，坐到沙发上，喝杯热咖啡，就盯着墙看10分钟，让大脑重启一下。' WHERE id = '078ff563-48f3-4bd6-81ac-93fc21a3bab7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos de sombras 🐰', body_es = '¿No quiere dormirse? Oscurece del todo la habitación y crea con las manos un teatro de sombras en la pared. Es la forma más divertida de vencer el miedo a la oscuridad.', title_fr = 'Jeux d''ombres 🐰', body_fr = 'Il ne veut pas dormir ? Faites le noir complet dans la chambre et créez un théâtre d''ombres avec vos mains sur le mur. C''est la façon la plus amusante de vaincre la peur du noir.', title_hi = 'परछाइयों के खेल 🐰', body_hi = 'सोना नहीं चाहता? कमरे में पूरा अंधेरा कीजिए और अपने हाथों से दीवार पर परछाइयों का थिएटर बनाइए। अंधेरे के डर को जीतने का यह सबसे मज़ेदार तरीका है।', title_id = 'Permainan bayangan 🐰', body_id = 'Tidak mau tidur? Gelapkan kamar sepenuhnya dan buat teater bayangan di dinding dengan tangan Anda. Ini cara paling seru untuk mengalahkan rasa takut gelap.', title_ja = '影絵あそび 🐰', body_ja = '寝たがらない？部屋を真っ暗にして、手で壁に影絵劇場をつくりましょう。暗やみのこわさを乗りこえる、いちばん楽しい方法です。', title_ko = '그림자 놀이 🐰', body_ko = '잠들기 싫어하나요? 방을 완전히 어둡게 하고 손으로 벽에 그림자 극장을 만들어 보세요. 어둠에 대한 두려움을 이기는 가장 재미있는 방법이에요.', title_nl = 'Schaduwspelletjes 🐰', body_nl = 'Wil hij niet slapen? Maak de kamer helemaal donker en speel met je handen schaduwtheater op de muur. Dit is de leukste manier om angst voor het donker te overwinnen.', title_pl = 'Zabawa w cienie 🐰', body_pl = 'Nie chce zasnąć? Zaciemnij całkowicie pokój i stwórz dłońmi teatr cieni na ścianie. To najzabawniejszy sposób na pokonanie lęku przed ciemnością.', title_pt = 'Jogos de sombras 🐰', body_pt = 'Não quer adormecer? Escureça o quarto por completo e faça teatro de sombras na parede com as mãos. É a forma mais divertida de vencer o medo do escuro.', title_sv = 'Skuggspel 🐰', body_sv = 'Vill barnet inte somna? Gör rummet helt mörkt och skapa skuggteater på väggen med händerna. Det är det roligaste sättet att övervinna mörkrädsla.', title_vi = 'Trò chơi bóng hình 🐰', body_vi = 'Bé không chịu ngủ? Hãy làm tối phòng hoàn toàn và dùng tay tạo sân khấu bóng hình trên tường. Đây là cách vui nhất để vượt qua nỗi sợ bóng tối.', title_zh = '影子游戏 🐰', body_zh = '不想睡觉？把房间完全调暗，用手在墙上演一场影子戏。这是战胜怕黑最有趣的方法。' WHERE id = '9f105ce0-5653-4d0b-8d96-2ed9abdc7e4a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tatuajes corporales 🖍️', body_es = 'Unos segundos de silencio a veces son peligrosos. ¿Has entrado en la habitación y le has visto tatuándose los brazos con rotulador? Respira hondo. Su motricidad fina avanza y la piel se lava igualmente.', title_fr = 'Tatouages maison 🖍️', body_fr = 'Quelques secondes de silence peuvent parfois être dangereuses. Vous entrez dans la pièce et il s''est tatoué les bras au feutre ? Respirez profondément. Sa motricité fine se développe, et la peau, ça se lave.', title_hi = 'शरीर पर टैटू 🖍️', body_hi = 'कुछ पल की खामोशी कभी-कभी खतरनाक होती है। कमरे में गईं तो देखा कि बाँहों पर मार्कर से टैटू बना रहा है? गहरी साँस लीजिए। फ़ाइन मोटर स्किल्स बढ़ रही हैं, और त्वचा तो धुल ही जाती है।', title_id = 'Tato di tubuh 🖍️', body_id = 'Hening beberapa detik kadang berbahaya. Masuk kamar dan mendapati ia membuat tato di lengannya dengan spidol? Tarik napas dalam. Motorik halusnya berkembang, dan kulit toh bisa dicuci.', title_ja = 'ボディアート 🖍️', body_ja = '数秒の静けさは、ときに危険のサイン。部屋に入ったら、腕にペンでタトゥーを描いていた？深呼吸しましょう。指先の細かな運動能力が育っていて、肌はどうせ洗えば落ちます。', title_ko = '몸에 그린 타투 🖍️', body_ko = '몇 초의 정적은 가끔 위험하죠. 방에 들어갔더니 팔에 사인펜으로 타투를 그리고 있었나요? 깊게 숨 쉬세요. 소근육이 자라고 있고, 피부는 어차피 씻으면 돼요.', title_nl = 'Tatoeages op zijn lijf 🖍️', body_nl = 'Een paar seconden stilte is soms gevaarlijk. Kwam je de kamer in en zag je dat hij met een stift tatoeages op zijn armen zette? Haal diep adem. Zijn fijne motoriek groeit en huid is toch afwasbaar.', title_pl = 'Tatuaże na ciele 🖍️', body_pl = 'Kilka sekund ciszy bywa niebezpieczne. Weszłaś do pokoju i zobaczyłaś, że robi sobie flamastrem tatuaże na rękach? Weź głęboki oddech. Motoryka mała się rozwija, a skóra i tak się zmyje.', title_pt = 'Tatuagens no corpo 🖍️', body_pt = 'Uns segundos de silêncio às vezes são perigosos. Entrou no quarto e viu que fez tatuagens nos braços com marcador? Respire fundo. A motricidade fina está a desenvolver-se e a pele lava-se.', title_sv = 'Kroppstatueringar 🖍️', body_sv = 'Några sekunders tystnad kan ibland vara farligt. Kom du in i rummet och såg att barnet tatuerat armarna med tusch? Andas djupt. Finmotoriken utvecklas och huden går ändå att tvätta.', title_vi = 'Hình xăm trên cơ thể 🖍️', body_vi = 'Vài giây im lặng đôi khi rất nguy hiểm. Mẹ bước vào phòng và thấy bé dùng bút dạ "xăm" khắp tay? Hãy hít thở sâu. Kỹ năng vận động tinh đang phát triển, còn da thì đằng nào cũng rửa sạch được.', title_zh = '身体上的“纹身” 🖍️', body_zh = '几秒钟的安静有时很危险。走进房间，发现宝宝正用水彩笔在胳膊上“纹身”？深呼吸。精细动作在发展，皮肤反正洗得掉。' WHERE id = '4ab501ea-956f-4adc-a27e-2e2bc99f59c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Papá, tu compañero de equipo 👨‍👧', body_es = '¿A última hora de la tarde tu energía está a cero? Di «Me salgo de este guion» y pásale tu peque a su padre. Recoger la habitación que desordenen juntos es más fácil que pelearte sola con el niño.', title_fr = 'Papa, le coéquipier 👨‍👧', body_fr = 'Votre énergie est à zéro en fin de journée ? Dites « Je sors de ce scénario » et confiez l''enfant à son père. Ranger la pièce qu''ils ont mise sens dessus dessous ensemble, c''est plus facile que de lutter seule avec l''enfant.', title_hi = 'साथी के रूप में पापा 👨‍👧', body_hi = 'शाम तक आपकी ऊर्जा शून्य हो गई? ''मैं इस सीन से बाहर हूँ'' कहिए और बच्चे को उसके पापा को सौंप दीजिए। उनके साथ मिलकर बिखेरा कमरा समेटना अकेले बच्चे से जूझने से कहीं आसान है।', title_id = 'Ayah sang mitra 👨‍👧', body_id = 'Energi Anda habis menjelang malam? Katakan ''Aku keluar dari skenario ini'' dan serahkan anak kepada ayahnya. Membereskan kamar yang mereka acak bersama lebih mudah daripada berjuang sendirian menghadapi anak.', title_ja = 'パートナーのパパ 👨‍👧', body_ja = '夕方にはエネルギーがゼロ？「わたしはこの場面から退場します」と言って、お子さんをパパにバトンタッチ。ふたりが散らかした部屋を片づけるほうが、ひとりでお子さんと格闘するより楽です。', title_ko = '든든한 파트너, 아빠 👨‍👧', body_ko = '저녁이 되니 기운이 바닥났나요? ''나는 이 장면에서 빠질게'' 하고 아이를 아빠에게 넘기세요. 둘이 함께 어지른 방을 치우는 게 혼자 아이와 씨름하는 것보다 쉬워요.', title_nl = 'Papa als teamgenoot 👨‍👧', body_nl = 'Is je energie aan het eind van de middag op? Zeg ''Ik stap uit dit scenario'' en geef hem aan zijn vader. De kamer opruimen die ze samen overhoop hebben gehaald is makkelijker dan alleen met hem strijden.', title_pl = 'Tata do pary 👨‍👧', body_pl = 'Pod wieczór twoja energia spadła do zera? Powiedz: „Wychodzę z tego scenariusza” i przekaż dziecko tacie. Sprzątnięcie pokoju, który razem rozgromią, jest łatwiejsze niż samotna walka z dzieckiem.', title_pt = 'O pai como parceiro 👨‍👧', body_pt = 'Ao fim da tarde, a sua energia chegou a zero? Diga "Eu saio deste filme" e entregue a criança ao pai. Arrumar o quarto que desarrumaram juntos é mais fácil do que lutar sozinha com a criança.', title_sv = 'Pappa som motpart 👨‍👧', body_sv = 'Har energin tagit slut på eftermiddagen? Säg ”Jag kliver ur det här manuset” och lämna över barnet till pappa. Att städa rummet de stökat till tillsammans är lättare än att kämpa ensam med barnet.', title_vi = 'Bố đồng đội 👨‍👧', body_vi = 'Chiều tối năng lượng của mẹ đã về 0? Hãy nói "Mẹ xin rút khỏi kịch bản này" và giao bé cho bố. Dọn căn phòng hai bố con bày bừa còn dễ hơn một mình xoay xở với bé.', title_zh = '搭档爸爸 👨‍👧', body_zh = '傍晚精力归零了？说一句“这场戏我退出了”，把孩子交给爸爸。收拾他们俩一起弄乱的房间，比一个人和孩子周旋轻松多了。' WHERE id = '93712bd1-e114-4739-841f-9d8901785feb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de fibra 💩', body_es = 'Corre mucho, pero se olvida de beber agua. Fíjate en las deposiciones en el orinal. Si hay riesgo de estreñimiento, añade avena y ciruelas a su menú.', title_fr = 'Besoin de fibres 💩', body_fr = 'Il court beaucoup, mais oublie de boire. Surveillez ses selles dans le pot. En cas de risque de constipation, ajoutez de l''avoine et des pruneaux à son menu.', title_hi = 'फ़ाइबर की ज़रूरत 💩', body_hi = 'खूब दौड़ता है, लेकिन पानी पीना भूल जाता है। पॉटी में मल पर नज़र रखिए। अगर कब्ज़ का खतरा हो, तो मेन्यू में ओट्स और आलूबुखारा जोड़िए।', title_id = 'Kebutuhan serat 💩', body_id = 'Banyak berlari, tetapi lupa minum. Perhatikan kotorannya di pispot. Jika ada risiko sembelit, tambahkan oat dan plum ke menunya.', title_ja = '食物繊維が必要 💩', body_ja = 'よく走るのに、お水を飲むのを忘れがち。おまるで便の様子をチェックしましょう。便秘が心配なら、メニューにオートミールやプルーンを加えて。', title_ko = '섬유질이 필요해요 💩', body_ko = '많이 뛰는데 물 마시는 걸 잊어요. 아기 변기에서 배변을 살펴보세요. 변비가 걱정된다면 식단에 귀리와 자두를 추가하세요.', title_nl = 'Behoefte aan vezels 💩', body_nl = 'Hij rent veel, maar vergeet te drinken. Let op zijn ontlasting in het potje. Is er kans op verstopping, voeg dan havermout en pruimen toe aan zijn menu.', title_pl = 'Potrzeba błonnika 💩', body_pl = 'Dużo biega, ale zapomina pić wodę. Obserwuj wypróżnienia w nocniku. Jeśli grozi zaparcie, dodaj do menu płatki owsiane i suszone śliwki.', title_pt = 'Falta de fibra 💩', body_pt = 'Corre muito, mas esquece-se de beber água. Repare nas fezes no bacio. Se houver risco de prisão de ventre, junte aveia e ameixas à ementa.', title_sv = 'Behov av fiber 💩', body_sv = 'Barnet springer mycket men glömmer att dricka vatten. Håll koll på avföringen i pottan. Om det finns risk för förstoppning, lägg till havre och plommon i menyn.', title_vi = 'Nhu cầu chất xơ 💩', body_vi = 'Bé chạy nhiều nhưng quên uống nước. Hãy để ý chất thải trong bô. Nếu có nguy cơ táo bón, hãy thêm yến mạch và mận vào thực đơn.', title_zh = '需要膳食纤维 💩', body_zh = '跑得很多，却忘了喝水。留意便盆里的排便情况。如果有便秘风险，就在菜单里加上燕麦和李子。' WHERE id = '9a4e49fa-28ce-4422-86d1-9b77699fd24c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Enemistad con la sombra 👻', body_es = '¿Se ha echado a llorar de repente en la calle o en la habitación? ¡La causa es que su sombra le persigue! Cerca de los 3 años la imaginación se vuelve curiosa. Abrázale y preséntale a su sombra con una sonrisa.', title_fr = 'Ennemi juré : l''ombre 👻', body_fr = 'Il s''est soudain mis à pleurer dans la rue ou dans la chambre ? La raison : son ombre le suit ! Vers 3 ans, l''imagination devient étrange. Prenez-le dans vos bras et présentez-lui son ombre en souriant.', title_hi = 'परछाईं से दुश्मनी 👻', body_hi = 'सड़क पर या कमरे में अचानक रोने लगा? वजह यह है कि उसकी परछाईं उसका पीछा कर रही है! 3 साल के करीब कल्पना अनोखी हो जाती है। उसे गले लगाइए और मुस्कुराते हुए परछाईं से उसकी पहचान कराइए।', title_id = 'Bermusuhan dengan bayangan 👻', body_id = 'Tiba-tiba ia menangis di jalan atau di kamar? Penyebabnya: bayangannya mengikutinya! Menjelang usia 3 tahun imajinasi jadi unik. Peluk ia dan kenalkan pada bayangannya sambil tersenyum.', title_ja = '影とのけんか 👻', body_ja = '道や部屋で急に泣き出しましたか？自分の影がついてくるのがこわいのです！3歳が近づくと、想像力がふしぎな方向に働きます。抱きしめて、笑顔で影を紹介してあげましょう。', title_ko = '그림자와의 싸움 👻', body_ko = '길이나 방에서 갑자기 울기 시작했나요? 그림자가 따라와서일 수도 있어요! 세 돌 무렵엔 상상력이 엉뚱해져요. 꼭 안아 주고 웃으며 그림자와 인사시켜 주세요.', title_nl = 'Vijandschap met zijn schaduw 👻', body_nl = 'Begon hij op straat of in de kamer ineens te huilen? Omdat zijn schaduw hem volgt! Richting 3 jaar wordt de fantasie vreemd. Knuffel hem en laat hem glimlachend kennismaken met zijn schaduw.', title_pl = 'Wróg w cieniu 👻', body_pl = 'Nagle zaczął płakać na ulicy albo w pokoju? Powód: śledzi go jego cień! W okolicach 3. roku życia wyobraźnia robi się dziwna. Przytul go i z uśmiechem zapoznaj z cieniem.', title_pt = 'Inimizade com a sombra 👻', body_pt = 'Começou de repente a chorar na rua ou no quarto? A causa é a sombra que o segue! Perto dos 3 anos, a imaginação fica estranha. Abrace-o e apresente-lhe a sombra a sorrir.', title_sv = 'Fiendskap med skuggan 👻', body_sv = 'Började barnet plötsligt gråta ute eller i rummet? Orsaken är att skuggan följer efter hen! När barnet närmar sig 3 år blir fantasin märklig. Krama barnet och presentera skuggan med ett leende.', title_vi = 'Kẻ thù cái bóng 👻', body_vi = 'Bé bỗng khóc trên đường hay trong phòng? Lý do là cái bóng cứ đi theo bé! Gần 3 tuổi, trí tưởng tượng trở nên thật kỳ lạ. Hãy ôm bé và mỉm cười giới thiệu bé làm quen với cái bóng.', title_zh = '和影子较劲 👻', body_zh = '在街上或房间里突然哭了起来？原因是影子一直跟着自己！快3岁时，想象力会变得有些奇特。抱抱宝宝，笑着让宝宝和影子认识一下吧。' WHERE id = '2743b373-11c6-4a72-a371-988483c30fb4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cirujano de la comida 🥦', body_es = 'No se come la comida: solo separa con precisión de cirujano los granitos de arroz o las especias verdes. Entra en el Plan de alimentación y descubre cómo hacer puré las verduras.', title_fr = 'Le chirurgien de l''assiette 🥦', body_fr = 'Il ne mange pas, il trie juste les petits grains de riz ou les herbes vertes avec une précision de chirurgien. Ouvrez le Plan de nutrition et découvrez comment réduire les légumes en purée.', title_hi = 'खाने का सर्जन 🥦', body_hi = 'खाना खाता नहीं, बस उसमें से छोटे चावल या हरे मसाले सर्जन जैसी बारीकी से अलग करता है? फ़ीडिंग प्लान खोलिए और सब्ज़ियों को प्यूरी बनाने के तरीके खोजिए।', title_id = 'Ahli bedah makanan 🥦', body_id = 'Ia tidak memakan makanannya, hanya memisahkan butiran kecil atau bumbu hijau dengan ketelitian ahli bedah. Buka Rencana Nutrisi dan temukan cara menghaluskan sayuran.', title_ja = '食べ物の外科医 🥦', body_ja = 'ごはんを食べずに、小さな粒や緑のスパイスを外科医のような正確さでより分けていますか？「栄養管理ツール」を開いて、野菜をピューレにする方法を見つけましょう。', title_ko = '음식 외과 의사 🥦', body_ko = '밥은 안 먹고 그 속의 작은 덩어리나 초록 양념만 외과 의사처럼 골라내나요? 식단 계획에서 채소를 퓌레로 만드는 방법을 찾아보세요.', title_nl = 'Voedselchirurg 🥦', body_nl = 'Hij eet niet, maar haalt met chirurgische precisie de rijstkorrels of groene kruidjes uit zijn eten. Open het Voedingsplan en ontdek hoe je groenten tot puree maakt.', title_pl = 'Chirurg od jedzenia 🥦', body_pl = 'Nie je, tylko z chirurgiczną precyzją oddziela małe grudki albo zielone przyprawy? Zajrzyj do planu karmienia i odkryj sposoby, jak zmiksować warzywa na gładko.', title_pt = 'Cirurgião da comida 🥦', body_pt = 'Não come, só separa com precisão de cirurgião os bocadinhos ou as ervas verdes. Entre no Plano Alimentar e descubra formas de fazer puré com os legumes.', title_sv = 'Matkirurg 🥦', body_sv = 'Barnet äter inte maten utan sorterar bara ut de små riskornen eller de gröna kryddorna med kirurgisk precision. Gå in i matplanen och upptäck sätt att mosa grönsakerna.', title_vi = 'Bác sĩ phẫu thuật món ăn 🥦', body_vi = 'Bé không ăn mà chỉ tách những hạt nhỏ hay gia vị màu xanh ra với độ chính xác của bác sĩ phẫu thuật. Hãy vào Kế hoạch dinh dưỡng và khám phá cách xay nhuyễn rau củ.', title_zh = '食物外科医生 🥦', body_zh = '不吃饭，只是用外科医生般的精准，把里面的小米粒或绿色香料一个个挑出来。去喂养计划里找找把蔬菜做成泥的办法吧。' WHERE id = '344cf14d-0511-4f06-86bb-38e1e79297c3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despedirse de todo 🧸', body_es = 'Antes de dormir quiere dar las buenas noches al coche, a la silla y hasta al pomo de la puerta. Es uno de los nuevos rituales para dormir que ha adoptado, no le metas prisa.', title_fr = 'Dire au revoir à tout 🧸', body_fr = 'Avant de dormir, il veut dire « bonne nuit » à la voiture, à la chaise, et même à la poignée de porte. C''est l''un des nouveaux rituels qu''il s''est approprié pour s''endormir, ne le pressez pas.', title_hi = 'हर चीज़ को अलविदा 🧸', body_hi = 'सोने से पहले कमरे की गाड़ी, कुर्सी, यहाँ तक कि दरवाज़े के हैंडल को भी ''गुड नाइट'' कहना चाहता है? यह सोने से पहले की उसकी नई अपनाई हुई रस्मों में से एक है, जल्दी मत कराइए।', title_id = 'Berpamitan pada segalanya 🧸', body_id = 'Sebelum tidur, ia ingin mengucapkan selamat malam pada mobil-mobilan, kursi, bahkan gagang pintu. Ini salah satu ritual menjelang tidur barunya, jangan buru-buru.', title_ja = 'なんにでもおやすみ 🧸', body_ja = '寝る前に、部屋のくるまにも、いすにも、ドアノブにまで「おやすみ」と言いたがりますか？これは、お子さんが身につけた新しい眠りへの儀式のひとつ。せかさないであげて。', title_ko = '모든 것과 인사하기 🧸', body_ko = '자기 전에 방 안의 자동차, 의자, 문손잡이에게까지 ''잘 자''라고 인사하고 싶어 하나요? 새로 익힌 잠자리 의식 중 하나예요. 재촉하지 마세요.', title_nl = 'Overal gedag tegen zeggen 🧸', body_nl = 'Wil hij voor het slapen ''welterusten'' zeggen tegen het autootje, de stoel en zelfs de deurklink? Dat is een van zijn nieuwe slaaprituelen, jaag hem niet op.', title_pl = 'Pożegnanie ze wszystkim 🧸', body_pl = 'Przed snem chce powiedzieć „dobranoc” samochodzikowi, krzesłu, a nawet klamce. To jeden z nowych rytuałów zasypiania, które przyswoił, nie poganiaj go.', title_pt = 'Dizer adeus a tudo 🧸', body_pt = 'Antes de dormir, quer dizer "boa noite" ao carrinho, à cadeira e até ao puxador da porta. É um dos novos rituais de adormecer que adotou, não o apresse.', title_sv = 'Säga godnatt till allt 🧸', body_sv = 'Före läggdags vill barnet säga godnatt till och med till bilen, stolen och dörrhandtaget i rummet. Det är en av de nya ritualerna för att gå över till sömn som barnet har lärt sig, stressa inte.', title_vi = 'Chúc ngủ ngon mọi thứ 🧸', body_vi = 'Trước khi ngủ, bé muốn chúc ngủ ngon cả chiếc ô tô, cái ghế, thậm chí tay nắm cửa. Đây là một trong những nghi thức trước giờ ngủ bé mới học được, đừng giục bé.', title_zh = '和所有东西说晚安 🧸', body_zh = '睡前想对房间里的小汽车、椅子，甚至门把手说“晚安”？这是宝宝学会的新的入睡仪式之一，别催宝宝。' WHERE id = '85bf1b2b-8bd2-41a8-8e81-bd414469ff03' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El valor del silencio 🤫', body_es = 'Por fin se ha dormido. Ahora hasta el menor ruido de casa te pone nerviosa. Mientras fijas el límite de la habitación con el Medidor de sonido, pon de fondo un ruido blanco continuo.', title_fr = 'Le prix du silence 🤫', body_fr = 'Il s''est enfin endormi. Maintenant, le moindre bruit dans la maison vous agace. Pendant que vous surveillez le niveau de la chambre avec le Sonomètre, mettez un bruit blanc continu en fond.', title_hi = 'खामोशी की कीमत 🤫', body_hi = 'आखिरकार वह सो गया। अब घर की ज़रा सी आवाज़ भी आपको चिढ़ा रही है। साउंड मीटर से कमरे की सीमा तय करते हुए पीछे लगातार चलने वाला व्हाइट नॉइज़ चलाइए।', title_id = 'Harga keheningan 🤫', body_id = 'Ia akhirnya tertidur. Kini suara sekecil apa pun di rumah membuat Anda jengkel. Sambil menjaga batas kebisingan kamar dengan Pengukur Suara, putar suara putih yang terus-menerus di latar belakang.', title_ja = '静けさの価値 🤫', body_ja = 'やっと眠りました。今は家の小さな物音さえ気になりますよね。「サウンドメーター」で部屋の音の上限を保ちながら、後ろで途切れないホワイトノイズを流しましょう。', title_ko = '고요의 가치 🤫', body_ko = '드디어 잠들었어요. 이제 집 안의 아주 작은 소리에도 신경이 곤두서죠. 소음 측정기로 방의 소리를 일정하게 유지하면서 배경에 백색소음을 계속 틀어 주세요.', title_nl = 'De waarde van stilte 🤫', body_nl = 'Hij slaapt eindelijk. Nu irriteert zelfs het kleinste geluid in huis je. Houd met de Geluidsmeter het niveau in de kamer in de gaten en zet op de achtergrond een constante witte ruis aan.', title_pl = 'Cena ciszy 🤫', body_pl = 'W końcu zasnął. Teraz drażni cię nawet najmniejszy dźwięk w domu. Ustalając Miernikiem dźwięku limit w pokoju, włącz w tle stały biały szum.', title_pt = 'O valor do silêncio 🤫', body_pt = 'Finalmente adormeceu. Agora qualquer pequeno ruído em casa a irrita. Enquanto controla o limite do quarto com o Medidor de Som, ponha em fundo um ruído branco contínuo.', title_sv = 'Tystnadens värde 🤫', body_sv = 'Barnet har äntligen somnat. Nu kan minsta ljud hemma irritera dig. Håll rummets gräns stabil med Ljudmätaren och sätt på ett jämnt vitt brus i bakgrunden.', title_vi = 'Giá trị của sự tĩnh lặng 🤫', body_vi = 'Cuối cùng bé cũng ngủ. Giờ chỉ một tiếng động nhỏ trong nhà cũng khiến mẹ bực bội. Trong lúc giữ ổn định độ ồn trong phòng bằng Đo âm thanh, hãy bật tiếng ồn trắng liên tục ở phía sau.', title_zh = '安静的价值 🤫', body_zh = '宝宝终于睡着了。现在家里最小的声音都让你烦躁。用分贝仪把房间音量控制在限度内，同时在背景里打开持续的白噪音。' WHERE id = '0ff4754d-26cd-4a0c-9aad-d8a1cbe8e5a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empezamos a contar 🔢', body_es = '¿Al subir escaleras o colocar sus juguetes intenta decir «uno, dos, tres»? Se están poniendo las bases del pensamiento matemático. Contad juntos en voz alta los objetos de la habitación.', title_fr = 'On commence à compter 🔢', body_fr = 'En montant l''escalier ou en rangeant ses jouets, il essaie de dire « un, deux, trois » ? Les bases de la pensée mathématique se posent. Comptez à voix haute avec lui les objets de la pièce.', title_hi = 'गिनती शुरू 🔢', body_hi = 'सीढ़ियाँ चढ़ते या खिलौने सजाते समय ''एक, दो, तीन'' कहने की कोशिश करता है? गणित वाली सोच की नींव पड़ रही है। उसके साथ मिलकर कमरे की चीज़ें ज़ोर से गिनिए।', title_id = 'Mulai berhitung 🔢', body_id = 'Saat naik tangga atau menyusun mainannya, ia mencoba bilang ''satu, dua, tiga''? Dasar pemikiran matematika sedang diletakkan. Hitunglah benda-benda di kamar bersamanya dengan suara keras.', title_ja = '数を数え始める 🔢', body_ja = '階段を上るときやおもちゃを並べるとき、「いち、に、さん」と言おうとしますか？数を考える力の土台ができています。一緒に部屋のものを声に出して数えましょう。', title_ko = '숫자 세기 시작 🔢', body_ko = '계단을 오르거나 장난감을 늘어놓을 때 ''하나, 둘, 셋''을 말하려고 하나요? 수학적 사고의 기초가 다져지고 있어요. 방 안의 물건을 함께 소리 내어 세어 보세요.', title_nl = 'We beginnen te tellen 🔢', body_nl = 'Probeert hij ''één, twee, drie'' te zeggen als hij de trap op gaat of zijn speelgoed op een rij zet? De basis voor wiskundig denken wordt gelegd. Tel samen hardop de dingen in de kamer.', title_pl = 'Zaczynamy liczyć 🔢', body_pl = 'Wchodząc po schodach albo układając zabawki, próbuje mówić „raz, dwa, trzy”? Kładzie fundamenty myślenia matematycznego. Liczcie razem na głos przedmioty w pokoju.', title_pt = 'Começamos a contar 🔢', body_pt = 'Ao subir as escadas ou arrumar os brinquedos, tenta dizer "um, dois, três"? Estão a ser lançadas as bases do pensamento matemático. Contem juntos, em voz alta, os objetos do quarto.', title_sv = 'Nu börjar vi räkna 🔢', body_sv = 'Försöker barnet säga ett, två, tre när hen går i trappan eller radar upp leksakerna? Grunden för matematiskt tänkande läggs. Räkna sakerna i rummet högt tillsammans.', title_vi = 'Bắt đầu đếm số 🔢', body_vi = 'Khi leo cầu thang hay xếp đồ chơi, bé cố nói "một, hai, ba"? Nền móng của tư duy toán học đang được đặt. Hãy cùng bé đếm to các đồ vật trong phòng.', title_zh = '开始数数啦 🔢', body_zh = '爬楼梯或摆玩具时，努力说“一、二、三”？数学思维的基础正在打下。和宝宝一起大声数数房间里的东西吧。' WHERE id = 'bf9527d0-d7b0-4cb8-8523-c499e2e95693' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Síndrome de agotamiento 🔋', body_es = '¿Te dan ganas de gritar por todo? Estás viviendo un burnout. Entra en la Comunidad Anacan y escribe «Estoy muy cansada». Verás que miles de mujeres te acompañan en ese mismo segundo.', title_fr = 'Syndrome d''épuisement 🔋', body_fr = 'Vous avez envie de crier pour tout ? Vous vivez un burn-out. Allez dans la Communauté Anacan et écrivez « Je suis très fatiguée ». Vous verrez que des milliers de femmes sont solidaires de vous à la même seconde.', title_hi = 'बर्नआउट सिंड्रोम 🔋', body_hi = 'हर बात पर चिल्लाने का मन करता है? आप बर्नआउट से गुज़र रही हैं। Anacan कम्युनिटी में जाइए और लिखिए ''मैं बहुत थक गई हूँ''। आप देखेंगी कि उसी पल हज़ारों महिलाएँ आपके साथ खड़ी हैं।', title_id = 'Sindrom kelelahan 🔋', body_id = 'Ingin berteriak pada segala hal? Anda sedang burnout. Masuklah ke Komunitas Anacan dan tulis ''Aku sangat lelah''. Anda akan melihat ribuan perempuan merasakan hal yang sama dengan Anda di detik yang sama.', title_ja = '燃えつき症候群 🔋', body_ja = '何にでも叫びたくなりますか？燃えつき症候群かもしれません。Anacanコミュニティを開いて「もうくたくた」と書きこんでみて。何千人ものママが、まさに同じ瞬間にあなたと気持ちを分かち合っていることがわかります。', title_ko = '번아웃 증후군 🔋', body_ko = '모든 것에 소리치고 싶나요? 번아웃을 겪고 있는 거예요. Anacan 커뮤니티에 들어가 ''너무 지쳤어요''라고 남겨 보세요. 수많은 엄마들이 바로 그 순간 함께 공감해 줄 거예요.', title_nl = 'Opgebrand 🔋', body_nl = 'Wil je overal tegen schreeuwen? Je hebt een burn-out. Ga naar de Anacan Community en schrijf ''Ik ben zo moe''. Je zult zien dat duizenden vrouwen op hetzelfde moment met je meeleven.', title_pl = 'Syndrom wyczerpania 🔋', body_pl = 'Masz ochotę krzyczeć na wszystko? Przeżywasz wypalenie. Wejdź do Społeczności Anacan i napisz: „Jestem bardzo zmęczona”. Zobaczysz, że w tej samej sekundzie tysiące kobiet są z tobą solidarne.', title_pt = 'Síndrome de esgotamento 🔋', body_pt = 'Apetece-lhe gritar com tudo? Está a viver um burnout. Entre na Comunidade Anacan e escreva "Estou mesmo cansada". Vai ver que, nesse mesmo segundo, milhares de mulheres estão solidárias consigo.', title_sv = 'Utbrändhetssyndrom 🔋', body_sv = 'Vill du skrika åt allt? Du är utbränd. Gå in i Anacan Community och skriv ”Jag är så trött”. Du kommer att se att tusentals kvinnor känner med dig i samma sekund.', title_vi = 'Hội chứng kiệt sức 🔋', body_vi = 'Mẹ muốn hét lên với mọi thứ? Mẹ đang bị kiệt sức (burnout). Hãy vào Cộng đồng Anacan và viết "Mình mệt lắm rồi". Mẹ sẽ thấy hàng nghìn người phụ nữ đồng cảm với mẹ ngay trong giây phút ấy.', title_zh = '倦怠综合征 🔋', body_zh = '对什么都想发火？你正在经历倦怠。进入Anacan社区，写下“我太累了”。你会发现，就在同一秒，成千上万的妈妈和你感同身受。' WHERE id = 'ebcc858d-cfdb-4af6-a7c6-c1e46f778ba5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No quiere dormir la siesta de ninguna manera y lucha contra ella? Cerca de los 3 años algunos niños dejan la siesta. Prueba a sustituirla por una hora de calma sin dormir (sleep-free quiet time).', body_fr = 'Il refuse catégoriquement la sieste et se bat contre elle ? Vers 3 ans, certains enfants abandonnent la sieste. Essayez de la remplacer par un « temps calme » sans sommeil.', body_hi = 'दोपहर में बिल्कुल नहीं सोना चाहता और लड़ता है? 3 साल के करीब कुछ बच्चे दिन की नींद छोड़ देते हैं। रूटीन को ''शांत समय'' (sleep-free quiet time) से बदलकर देखिए।', body_id = 'Ia sama sekali tidak mau tidur siang dan terus melawan? Menjelang usia 3 tahun sebagian anak berhenti tidur siang. Coba ganti rutinitasnya dengan jam tenang (quiet time tanpa tidur).', body_ja = 'お昼寝をどうしてもいやがって抵抗しますか？3歳が近づくと、お昼寝をしなくなる子もいます。寝なくてもいい「静かな時間」に置きかえてみましょう。', body_ko = '낮잠을 절대 안 자겠다고 버티나요? 세 돌 무렵 낮잠을 그만두는 아이도 있어요. 낮잠 대신 잠들지 않아도 되는 ''조용한 시간''으로 바꿔 보세요.', body_nl = 'Wil hij absoluut geen middagslaapje doen en verzet hij zich? Rond de 3 jaar stoppen sommige kinderen met hun slaapje. Probeer het te vervangen door een rustuurtje zonder slapen.', body_pl = 'Za nic nie chce iść na popołudniową drzemkę i walczy? Około 3. roku życia niektóre dzieci rezygnują z drzemki. Spróbuj zastąpić ją godziną wyciszenia bez snu (sleep-free quiet time).', body_pt = 'Não quer de maneira nenhuma dormir a sesta e luta contra ela? Perto dos 3 anos, algumas crianças deixam a sesta. Experimente substituí-la por uma hora de sossego sem dormir (sleep-free quiet time).', body_sv = 'Vill barnet absolut inte sova middag och kämpar emot? När barnet närmar sig 3 år slutar vissa sova på dagen. Prova att ersätta rutinen med en Lugn stund (quiet time utan sömn).', body_vi = 'Bé nhất quyết không ngủ trưa và chống cự? Gần 3 tuổi, một số trẻ bỏ giấc ngủ ngày. Hãy thử thay bằng "Giờ yên tĩnh" không cần ngủ (sleep-free quiet time).', body_zh = '中午怎么都不肯睡，一直抗拒？快3岁时，有些孩子开始不再午睡。试着把作息换成“安静时间”（不睡觉的安静时光）。' WHERE id = '405360f8-7a97-471c-825c-355eafed365d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despiertan los recuerdos 🧠', body_es = '¿Construye frases sobre el pasado como «Ayer fuimos a casa de la abuela»? Se están formando la noción del tiempo y la memoria a largo plazo. Escucha sus recuerdos con interés y hazle preguntas.', title_fr = 'Les souvenirs s''éveillent 🧠', body_fr = 'Il fait des phrases sur le passé, comme « Hier, on est allés chez mamie » ? La notion de temps et la mémoire à long terme se forment. Écoutez ses souvenirs avec intérêt et posez-lui des questions.', title_hi = 'यादें जाग रही हैं 🧠', body_hi = '''कल हम नानी के घर गए थे'' जैसे बीते समय के वाक्य बनाता है? समय की समझ और लंबी याददाश्त बन रही है। उसकी इन यादों को दिलचस्पी से सुनिए और सवाल पूछिए।', title_id = 'Kenangan terbangun 🧠', body_id = 'Ia membuat kalimat tentang masa lalu seperti ''Kemarin kita ke rumah Nenek''? Konsep waktu dan ingatan jangka panjangnya sedang terbentuk. Dengarkan kenangannya dengan antusias dan ajukan pertanyaan.', title_ja = '思い出が目覚める 🧠', body_ja = '「きのう、おばあちゃんちに行ったね」のように、過去のことを話すようになりましたか？時間の感覚と長期記憶が育っています。思い出話を興味深く聞いて、質問してあげましょう。', title_ko = '기억이 깨어나요 🧠', body_ko = '''어제 할머니 댁에 갔어''처럼 지난 일을 문장으로 말하나요? 시간 개념과 장기 기억이 자리 잡고 있어요. 아이의 추억을 관심 있게 들어 주고 질문도 해 주세요.', title_nl = 'Herinneringen worden wakker 🧠', body_nl = 'Maakt hij zinnen over het verleden, zoals ''Gisteren gingen we naar oma''? Zijn besef van tijd en zijn langetermijngeheugen worden gevormd. Luister met interesse naar zijn herinneringen en stel vragen.', title_pl = 'Budzą się wspomnienia 🧠', body_pl = 'Buduje zdania o przeszłości, np. „Wczoraj byliśmy u babci”? Kształtuje się pojęcie czasu i pamięć długotrwała. Słuchaj tych wspomnień z zaciekawieniem i zadawaj pytania.', title_pt = 'As memórias despertam 🧠', body_pt = 'Constrói frases sobre o passado, como "Ontem fomos a casa da avó"? A noção de tempo e a memória de longo prazo estão a formar-se. Ouça estas memórias com interesse e faça-lhe perguntas.', title_sv = 'Minnena vaknar 🧠', body_sv = 'Säger barnet meningar om det som hänt, som ”I går var vi hos mormor”? Tidsbegreppet och långtidsminnet formas. Lyssna nyfiket på minnena och ställ frågor.', title_vi = 'Ký ức thức giấc 🧠', body_vi = 'Bé nói những câu về quá khứ như "Hôm qua mình đến nhà bà"? Khái niệm thời gian và trí nhớ dài hạn đang hình thành. Hãy hào hứng lắng nghe những kỷ niệm của bé và đặt câu hỏi.', title_zh = '回忆苏醒了 🧠', body_zh = '会说“昨天我们去奶奶家了”这样讲过去的句子了？时间概念和长期记忆正在形成。饶有兴趣地听宝宝讲这些回忆，再问问问题吧。' WHERE id = '6740b19e-f070-42e2-9b6e-76434890c90f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Grita y llora en mitad de la noche con los ojos cerrados?', body_es = 'No intentes despertarle. Escucha su llanto con el Análisis del llanto, asegúrate de que es solo un terror nocturno y quédate tranquila a su lado.', title_fr = 'Il crie et pleure les yeux fermés en pleine nuit ?', body_fr = 'N''essayez pas de le réveiller. Faites écouter ses pleurs à l''Analyse des pleurs pour vous assurer qu''il s''agit seulement d''une terreur nocturne, et restez calmement près de lui.', title_hi = 'आधी रात को आँखें बंद किए चीखता और रोता है?', body_hi = 'उसे जगाने की कोशिश मत कीजिए। उसकी आवाज़ क्राइंग एनालिसिस को सुनाकर पक्का कीजिए कि यह बस नाइट टेरर है, और चुपचाप उसके पास रहिए।', title_id = 'Tengah malam berteriak dan menangis dengan mata terpejam?', body_id = 'Jangan mencoba membangunkannya. Rekam suaranya dengan Analisis Tangisan untuk memastikan ini hanya teror malam, lalu tetaplah tenang di sisinya.', title_ja = '夜中に目を閉じたまま叫んで泣きますか？', body_ja = '起こそうとしないで。「泣き声分析」で声を聞かせて、夜驚症であることを確かめ、静かにそばにいてあげましょう。', title_ko = '한밤중에 눈을 감은 채 소리 지르며 우나요?', body_ko = '깨우려 하지 마세요. 울음 분석에 소리를 들려주어 야경증인지 확인하고 조용히 곁에 있어 주세요.', title_nl = 'Schreeuwt en huilt hij midden in de nacht met gesloten ogen?', body_nl = 'Probeer hem niet wakker te maken. Laat Huilanalyse luisteren om zeker te weten dat het gewoon nachtangst is en blijf rustig bij hem.', title_pl = 'W nocy krzyczy i płacze z zamkniętymi oczami?', body_pl = 'Nie próbuj go budzić. Daj posłuchać jego płaczu Analizie płaczu, upewnij się, że to tylko lęk nocny, i spokojnie bądź obok.', title_pt = 'A meio da noite grita e chora de olhos fechados?', body_pt = 'Não tente acordá-lo. Use a Análise do Choro para confirmar que é apenas um terror noturno e fique calmamente ao lado dele.', title_sv = 'Skriker och gråter barnet mitt i natten med slutna ögon?', body_sv = 'Försök inte väcka barnet. Låt Gråtanalys lyssna på ljudet för att försäkra dig om att det bara är nattskräck, och stanna lugnt hos barnet.', title_vi = 'Giữa đêm bé nhắm mắt la hét và khóc?', body_vi = 'Đừng cố đánh thức bé. Hãy cho Phân tích tiếng khóc nghe tiếng khóc để chắc chắn đó chỉ là hoảng sợ ban đêm và lặng lẽ ở bên bé.', title_zh = '半夜闭着眼睛尖叫哭闹？', body_zh = '别试图叫醒宝宝。让哭声分析听一听，确认这只是夜惊，然后安静地陪在旁边。' WHERE id = 'f0257b2e-d5f4-40d8-9701-488c186af81f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tragedias en la cocina 🧑‍🍳', body_es = 'Mientras cocinas, quiere ayudarte sí o sí junto al fuego echando la sal. Si le dejas, se estropea la comida; si no, llora. Dale un cuenco vacío y agua y dile: «Tú cocina tu propia sopa».', title_fr = 'Drames en cuisine 🧑‍🍳', body_fr = 'Quand vous cuisinez, il veut absolument vous aider près de la plaque et verser le sel. Si vous le laissez faire, le plat sera raté, sinon il pleurera. Donnez-lui un bol vide et de l''eau et dites-lui : « Fais ta propre soupe. »', title_hi = 'रसोई की आफ़तें 🧑‍🍳', body_hi = 'खाना बनाते समय चूल्हे के पास आपकी मदद करके नमक डालना ही है? इजाज़त दें तो खाना खराब, न दें तो रोना। उसे एक खाली बर्तन और पानी दीजिए और कहिए ''तुम अपना सूप बनाओ''।', title_id = 'Tragedi di dapur 🧑‍🍳', body_id = 'Saat Anda memasak, ia selalu ingin membantu di dekat kompor dan menaburkan garam. Kalau diizinkan, masakan bisa rusak, kalau tidak, ia akan menangis. Beri ia wadah kosong dan air, lalu katakan ''Kamu masak supmu sendiri''.', title_ja = 'キッチンの大惨事 🧑‍🍳', body_ja = '料理中、コンロのそばで手伝って塩を入れたがりますか？任せれば料理が台なし、断れば泣く。空のお鍋とお水を渡して、「あなたは自分のスープを作ってね」と言いましょう。', title_ko = '주방 대참사 🧑‍🍳', body_ko = '요리할 때 꼭 가스레인지 옆에서 소금을 넣으며 돕겠다고 하나요? 허락하면 요리가 망하고, 안 하면 울겠죠. 빈 그릇과 물을 주고 ''너는 네 수프를 끓여'' 하고 말해 주세요.', title_nl = 'Drama''s in de keuken 🧑‍🍳', body_nl = 'Wil hij tijdens het koken per se naast het fornuis helpen en zout erin doen? Laat je hem, dan is het eten verpest; laat je hem niet, dan huilt hij. Geef hem een lege kom en wat water en zeg: ''Kook jij je eigen soep.''', title_pl = 'Kuchenne tragedie 🧑‍🍳', body_pl = 'Gdy gotujesz, koniecznie chce ci pomagać przy kuchence i sypać sól. Jeśli pozwolisz, danie przepadnie, jeśli nie, będzie płakał. Daj mu pustą miskę i wodę i powiedz: „Ty ugotuj swoją zupę”.', title_pt = 'Tragédias na cozinha 🧑‍🍳', body_pt = 'Enquanto cozinha, quer por força ajudá-la ao pé do fogão e deitar o sal. Se deixar, a comida estraga-se; se não deixar, chora. Dê-lhe uma tigela vazia e água e diga: "Faz tu a tua sopa."', title_sv = 'Kökstragedier 🧑‍🍳', body_sv = 'När du lagar mat vill barnet absolut hjälpa dig vid spisen och hälla i saltet. Låter du hen blir maten förstörd, låter du bli så gråter hen. Ge barnet en tom skål och vatten och säg ”laga du din soppa”.', title_vi = 'Thảm họa trong bếp 🧑‍🍳', body_vi = 'Khi mẹ nấu ăn, bé nhất định đứng cạnh bếp giúp mẹ rắc muối. Cho thì hỏng món, không cho thì bé khóc. Hãy đưa bé một cái bát rỗng và chút nước, nói "Con nấu canh của con đi".', title_zh = '厨房里的“灾难” 🧑‍🍳', body_zh = '你做饭时，宝宝一定要在灶台边帮忙撒盐。让宝宝撒，饭就毁了；不让，宝宝就哭。给宝宝一个空碗和一些水，说“你来煮你自己的汤”。' WHERE id = '268f32e3-3ad0-45c0-aef4-aba7ce610179' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cascada de independencia 🥛', body_es = '¿Quiere servirse él solo el agua o la leche en el vaso y el resultado es todo un charco? Respira hondo. Este caos es el precio del desarrollo de su coordinación ojo-mano y de su seguridad. Dale también un trapo y limpiad juntos sin decir nada.', title_fr = 'Cascade d''autonomie 🥛', body_fr = 'Il veut absolument verser lui-même l''eau ou le lait dans son verre, et résultat ? Des flaques partout. Respirez profondément. Ce chaos est le prix de sa coordination œil-main et de sa confiance en lui. Donnez-lui aussi une éponge et nettoyez ensemble, sans hausser la voix.', title_hi = 'आज़ादी का झरना 🥛', body_hi = 'पानी या दूध गिलास में खुद ही डालना चाहता है, और नतीजा? हर जगह पानी ही पानी। गहरी साँस लीजिए। यह गड़बड़ उसकी आँख-हाथ के तालमेल और आत्मविश्वास के विकास की कीमत है। पोंछने का कपड़ा उसे भी दीजिए और बिना कुछ कहे साथ मिलकर साफ़ कीजिए।', title_id = 'Air terjun kemandirian 🥛', body_id = 'Ia bersikeras menuang air atau susu ke gelas sendiri, dan hasilnya? Genangan di mana-mana. Tarik napas dalam. Kekacauan ini adalah harga dari perkembangan koordinasi mata-tangan dan rasa percaya dirinya. Beri ia lap juga dan bersihkan bersama tanpa mengomel.', title_ja = '自立の滝 🥛', body_ja = 'お水や牛乳を自分でコップに注ぐと言い張って、結果はあちこち水たまり？深呼吸しましょう。この大混乱は、目と手の協調と自信を育てるための代償です。ふきんを渡して、声を荒げずに一緒にふきましょう。', title_ko = '자립의 폭포 🥛', body_ko = '물이나 우유를 꼭 직접 컵에 따르겠다고 하고 결과는 사방이 물바다인가요? 깊게 숨 쉬세요. 이 혼란은 눈과 손의 협응력과 자신감이 자라는 대가예요. 아이에게도 행주를 주고 소리 높이지 말고 함께 닦아요.', title_nl = 'Een waterval van zelfstandigheid 🥛', body_nl = 'Wil hij per se zelf water of melk in zijn beker schenken, met als resultaat overal plassen? Haal diep adem. Deze chaos is de prijs voor zijn oog-handcoördinatie en zelfvertrouwen. Geef hem ook een doekje en ruim het samen zonder mopperen op.', title_pl = 'Wodospad samodzielności 🥛', body_pl = 'Koniecznie chce sam nalać wodę albo mleko do kubka, a efekt? Wszędzie kałuża. Weź głęboki oddech. Ten chaos to cena rozwoju jego koordynacji oko-ręka i pewności siebie. Daj mu też ściereczkę i bez krzyku posprzątajcie razem.', title_pt = 'Cascata de independência 🥛', body_pt = 'Quer por força deitar ele próprio a água ou o leite no copo, e o resultado? Poças por todo o lado. Respire fundo. Este caos é o preço do desenvolvimento da coordenação olho-mão e da autoconfiança dele. Dê-lhe também um pano e limpem juntos, sem ralhar.', title_sv = 'Ett vattenfall av självständighet 🥛', body_sv = 'Vill barnet absolut hälla upp vatten eller mjölk i muggen själv, och resultatet? Pölar överallt. Andas djupt. Kaoset är priset för utvecklingen av öga-hand-koordinationen och självkänslan. Ge barnet en trasa också och torka upp tillsammans utan att höja rösten.', title_vi = 'Thác nước tự lập 🥛', body_vi = 'Bé nhất định tự rót nước hay sữa vào cốc và kết quả là? Khắp nơi thành vũng nước. Hãy hít thở sâu. Sự hỗn loạn này là cái giá cho khả năng phối hợp tay mắt và sự tự tin của bé. Đưa bé một chiếc khăn và cùng lặng lẽ lau dọn.', title_zh = '独立的“瀑布” 🥛', body_zh = '一定要自己往杯子里倒水或倒奶，结果呢？满地都是水洼。深呼吸。这片混乱是宝宝手眼协调和自信心发展的代价。也给宝宝一块抹布，不吭声地一起擦干净吧。' WHERE id = '1da71143-b8dd-434a-bf23-b7f16a2d4a80' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detox de ruido 🎧', body_es = '¿Los «¡Mamá, mamá, mamá!» resuenan en tu cabeza? Declárate una pequeña cuarentena. Déjale 15 minutos con una actividad segura y tómate el café en completo silencio. Tu batería también tiene que cargarse.', title_fr = 'Détox du bruit 🎧', body_fr = 'Les « Maman, maman, maman ! » résonnent dans votre tête ? Déclarez-vous une petite quarantaine. Laissez-le 15 minutes avec une activité sans danger et buvez votre café dans un silence total. Votre batterie aussi doit se recharger.', title_hi = 'शोर से डिटॉक्स 🎧', body_hi = '''माँ, माँ, माँ!'' की आवाज़ें दिमाग में गूँज रही हैं? अपने लिए एक छोटा सा ब्रेक घोषित कीजिए। उसे 15 मिनट किसी सुरक्षित गतिविधि में लगाइए और अपनी कॉफ़ी पूरी खामोशी में पीजिए। आपकी बैटरी भी चार्ज होनी चाहिए।', title_id = 'Detoks kebisingan 🎧', body_id = 'Suara ''Ibu, Ibu, Ibu!'' terus bergema di kepala Anda? Umumkan karantina kecil untuk diri sendiri. Biarkan ia sibuk dengan kegiatan yang aman selama 15 menit, dan minum kopi Anda dalam keheningan total. Baterai Anda juga perlu diisi.', title_ja = '騒音デトックス 🎧', body_ja = '「ママ、ママ、ママ！」が頭の中でこだましていますか？自分に小さな隔離期間を宣言しましょう。お子さんを15分間安全な遊びに任せて、完全な静けさの中でコーヒーを飲んで。あなたのバッテリーも充電が必要です。', title_ko = '소음 디톡스 🎧', body_ko = '''엄마, 엄마, 엄마!''가 머릿속에서 메아리치나요? 나에게 작은 휴식을 선언하세요. 아이를 15분 동안 안전한 놀이에 맡기고 완전한 고요 속에서 커피를 드세요. 엄마의 배터리도 충전해야 해요.', title_nl = 'Detox van lawaai 🎧', body_nl = 'Galmt ''Mama, mama, mama!'' door je hoofd? Kondig een kleine quarantaine voor jezelf af. Laat hem 15 minuten met een veilige bezigheid alleen en drink je koffie in totale stilte. Ook jouw batterij moet opladen.', title_pl = 'Detoks od hałasu 🎧', body_pl = '„Mamo, mamo, mamo!” odbija się echem w twojej głowie? Ogłoś sobie małą kwarantannę. Zostaw go na 15 minut z bezpiecznym zajęciem i wypij kawę w całkowitej ciszy. Twoja bateria też musi się naładować.', title_pt = 'Detox de barulho 🎧', body_pt = 'Os "Mamã, mamã, mamã!" ecoam-lhe na cabeça? Declare uma pequena quarentena para si. Deixe-o 15 minutos com uma atividade segura e beba o seu café em silêncio total. A sua bateria também tem de carregar.', title_sv = 'Detox från oljud 🎧', body_sv = 'Ekar ”Mamma, mamma, mamma!” i huvudet? Utlys en liten karantän för dig själv. Låt barnet vara med en säker sysselsättning i 15 minuter och drick ditt kaffe i total tystnad. Ditt batteri behöver också laddas.', title_vi = 'Detox tiếng ồn 🎧', body_vi = 'Tiếng "Mẹ ơi, mẹ ơi, mẹ ơi!" vang mãi trong đầu mẹ? Hãy tự cho mình một khoảng "cách ly" nhỏ. Để bé với một hoạt động an toàn trong 15 phút và uống cà phê trong yên tĩnh tuyệt đối. Pin của mẹ cũng cần được sạc đầy.', title_zh = '噪音排毒 🎧', body_zh = '“妈妈、妈妈、妈妈！”在脑子里回响？给自己宣布一个小小的“隔离期”。让宝宝做一件安全的事玩15分钟，你在完全的安静中喝杯咖啡。你的电池也得充满。' WHERE id = '7f1b27a1-aff6-4522-ba4e-76bb08fa648e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Romper la tozudez del baño 🛁', body_es = '¿No quiere bañarse y protesta revolcándose por el suelo? En lugar de «Ven, que te lavo», di «Vamos a bañar a tus coches (o muñecas) favoritos». Cualquier obligación convertida en juego es el gran punto débil de un niño.', title_fr = 'Vaincre la résistance au bain 🛁', body_fr = 'Il refuse d''aller dans le bain et se roule par terre pour protester ? Au lieu de « Viens, je te lave », dites « Viens, on va laver tes voitures (ou tes poupées) préférées ». Toute obligation transformée en jeu est le plus grand point faible d''un enfant.', title_hi = 'नहाने की ज़िद तोड़िए 🛁', body_hi = 'नहाने नहीं जाना चाहता, ज़मीन पर लोटकर विरोध करता है? ''चलो तुम्हें नहलाऊँ'' के बजाय कहिए ''चलो, तुम्हारी प्यारी गाड़ियों (या गुड़ियों) को नहलाएँ''। खेल बन जाने वाली हर मजबूरी बच्चे की सबसे बड़ी कमज़ोरी होती है।', title_id = 'Mengatasi drama mandi 🛁', body_id = 'Ia tidak mau mandi dan berguling di lantai sebagai protes? Daripada ''Ayo Ibu mandikan'', katakan ''Ayo kita mandikan mobil-mobilan (atau boneka) kesayanganmu''. Setiap kewajiban yang diubah jadi permainan adalah titik lemah terbesar anak.', title_ja = 'お風呂ぎらいを乗りこえる 🛁', body_ja = 'お風呂に入りたがらず、床を転がって抗議しますか？「洗ってあげるね」ではなく、「お気に入りのくるま（またはお人形）をお風呂に入れてあげよう」と言いましょう。遊びに変わった「しなきゃ」は、子どもの最大の弱点です。', title_ko = '목욕 고집 꺾기 🛁', body_ko = '목욕하기 싫다며 바닥을 구르나요? ''씻자'' 대신 ''좋아하는 자동차(또는 인형) 목욕시키러 가자''라고 말해 보세요. 놀이로 바뀐 의무는 아이가 가장 거절하기 힘든 거예요.', title_nl = 'Badweigering doorbreken 🛁', body_nl = 'Wil hij niet in bad en rolt hij protesterend over de vloer? Zeg niet ''Kom, ik ga je wassen'', maar ''Kom, we gaan je lievelingsautootjes (of poppen) in bad doen.'' Elke verplichting die een spel wordt, is de grootste zwakke plek van een kind.', title_pl = 'Jak przełamać upór przed kąpielą 🛁', body_pl = 'Nie chce wejść do kąpieli i tarza się po podłodze w proteście? Zamiast „Chodź, umyję cię”, powiedz: „Chodźmy wykąpać twoje ulubione samochodziki (albo lalki)”. Każdy przymus zamieniony w zabawę to największy słaby punkt dziecka.', title_pt = 'Vencer a teimosia do banho 🛁', body_pt = 'Não quer entrar no banho e rebola no chão a protestar? Em vez de "Vamos lavar-te", diga "Vamos dar banho aos teus carrinhos (ou bonecas) preferidos". Cada obrigação transformada em jogo é o maior ponto fraco de uma criança.', title_sv = 'Bryt badenvisheten 🛁', body_sv = 'Vill barnet inte gå in i badrummet och protesterar genom att rulla på golvet? I stället för ”Kom så tvättar jag dig”, säg ”Ska vi bada dina favoritbilar (eller dockor)?”. Varje tvång som blir en lek är barnets största svaga punkt.', title_vi = 'Phá tan sự bướng bỉnh khi tắm 🛁', body_vi = 'Bé không chịu vào phòng tắm, lăn ra sàn phản đối? Thay vì "Lại đây mẹ tắm cho", hãy nói "Mình đi tắm cho mấy chiếc ô tô (hoặc búp bê) yêu thích của con nào". Mọi việc bắt buộc được biến thành trò chơi đều là điểm yếu lớn nhất của trẻ.', title_zh = '破解洗澡的倔强 🛁', body_zh = '不肯进浴室，在地上打滚抗议？别说“来，我给你洗澡”，而是说“我们去给你最爱的小汽车（或娃娃）洗澡吧”。任何一件被变成游戏的“必须做”，都是孩子最大的软肋。' WHERE id = '9ebeb631-4aa4-4310-b78e-47bee6920a4e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis de zapatos en casa 👟', body_es = '¿Llora porque quiere llevar los zapatos de calle dentro de casa y no quitárselos por nada? No merece la pena la guerra. Límpiales la suela con un trapo húmedo y deja que se pasee orgulloso unas horas por la habitación. Perder algunas batallas a propósito es en realidad la mayor victoria de una madre.', title_fr = 'Crise des chaussures à la maison 👟', body_fr = 'Il pleure pour garder ses chaussures d''extérieur à la maison et refuse de les enlever ? Ça ne vaut pas la guerre. Essuyez les semelles avec un chiffon humide et laissez-le parader fièrement quelques heures dans la pièce. Perdre volontairement certaines batailles, c''est en réalité la plus grande victoire d''une maman.', title_hi = 'घर में जूतों का संकट 👟', body_hi = 'बाहर वाले जूते घर में पहनने और बिल्कुल न उतारने के लिए रोता है? यह जंग इसके लायक नहीं। तलवे गीले कपड़े से पोंछिए और उसे कुछ घंटे कमरे में शान से चलने दीजिए। कुछ लड़ाइयाँ जानबूझकर हारना असल में माँ की सबसे बड़ी जीत है।', title_id = 'Krisis sepatu di rumah 👟', body_id = 'Ia menangis karena ingin memakai sepatu luar di dalam rumah dan sama sekali tidak mau melepasnya? Tidak sepadan untuk diperdebatkan. Lap solnya dengan kain basah dan biarkan ia berjalan bangga di kamar beberapa jam. Sengaja kalah dalam beberapa pertempuran sebenarnya adalah kemenangan terbesar seorang ibu.', title_ja = '家の中での靴騒動 👟', body_ja = '外の靴を家の中ではいて、絶対に脱ぎたがらずに泣きますか？戦う価値はありません。靴の裏をぬれた布でふいて、しばらく部屋の中を得意げに歩かせてあげましょう。わざと負ける戦いは、実はママのいちばん大きな勝利です。', title_ko = '집 안 신발 대소동 👟', body_ko = '바깥 신발을 집 안에서 신고 절대 벗지 않겠다고 우나요? 전쟁을 벌일 일은 아니에요. 바닥을 젖은 걸레로 닦아 주고 몇 시간 방을 뿌듯하게 걸어 다니게 해 주세요. 작은 싸움에 일부러 져 주는 게 사실 엄마의 가장 큰 승리예요.', title_nl = 'Schoenencrisis in huis 👟', body_nl = 'Huilt hij omdat hij zijn buitenschoenen binnen aan wil houden en ze absoluut niet uit wil trekken? Niet de oorlog waard. Veeg de zolen af met een vochtige doek en laat hem een paar uur trots door de kamer stappen. Sommige gevechten bewust verliezen is eigenlijk de grootste overwinning van een moeder.', title_pl = 'Kryzys butów w domu 👟', body_pl = 'Płacze, bo chce chodzić po domu w butach na dwór i za nic ich nie zdejmie? Nie warto o to walczyć. Przetrzyj podeszwy wilgotną ściereczką i pozwól mu przez kilka godzin dumnie maszerować po pokoju. Świadome przegranie niektórych bitew to tak naprawdę największe zwycięstwo mamy.', title_pt = 'A crise dos sapatos em casa 👟', body_pt = 'Chora porque quer andar em casa com os sapatos da rua e não os tirar de maneira nenhuma? Não vale a pena a guerra. Limpe as solas com um pano húmido e deixe-o desfilar orgulhoso pelo quarto umas horas. Perder algumas batalhas de propósito é, na verdade, a maior vitória de uma mãe.', title_sv = 'Skokris inomhus 👟', body_sv = 'Gråter barnet för att få ha på sig uteskorna inne och aldrig ta av dem? Det är inte värt ett krig. Torka sulorna med en fuktig trasa och låt barnet stolt gå runt i rummet några timmar. Att medvetet förlora vissa strider är egentligen mammans största seger.', title_vi = 'Khủng hoảng giày dép trong nhà 👟', body_vi = 'Bé khóc vì muốn đi giày ra đường trong nhà và nhất quyết không chịu cởi? Không đáng để gây chiến. Hãy lau đế giày bằng khăn ẩm và để bé tự hào đi lại trong phòng vài tiếng. Cố tình thua vài trận nhỏ thật ra là chiến thắng lớn nhất của người mẹ.', title_zh = '家里的鞋子危机 👟', body_zh = '非要在家里穿外面的鞋，哭着就是不肯脱？不值得为此开战。用湿布擦擦鞋底，让宝宝骄傲地在房间里走上几个小时吧。故意输掉一些战斗，其实是妈妈最大的胜利。' WHERE id = '5188ae48-9680-4372-a0c2-b6a14d87d513' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Le toca a papá 👨‍🍼', body_es = 'Estás cansada de decir «no» y de poner normas todo el día. Esta noche pasa a papá la batalla del pijama y el cepillo de dientes. Cierra la puerta de la habitación y dedícate tiempo solo a ti escribiendo cómo te has sentido hoy en el Diario de ánimo.', title_fr = 'C''est au tour de papa 👨‍🍼', body_fr = 'Vous êtes fatiguée d''avoir dit « non » et posé des règles toute la journée. Ce soir, confiez à papa la bataille du pyjama et du brossage de dents. Fermez la porte de la chambre et prenez du temps rien que pour vous en écrivant simplement vos émotions du jour dans le Journal d''humeur.', title_hi = 'बारी पापा की है 👨‍🍼', body_hi = 'दिनभर ''नहीं'' कहते और नियम बनाते-बनाते थक गई हैं। आज शाम पजामा और ब्रश वाली जंग पापा को सौंप दीजिए। कमरे का दरवाज़ा बंद कीजिए, मूड डायरी में बस आज की भावनाएँ लिखिए और पूरा समय खुद को दीजिए।', title_id = 'Giliran Ayah 👨‍🍼', body_id = 'Anda lelah seharian berkata tidak dan membuat aturan. Malam ini serahkan perang piyama dan sikat gigi kepada Ayah. Tutup pintu kamar dan luangkan waktu sepenuhnya untuk diri sendiri dengan menulis perasaan Anda hari ini di Buku Harian Suasana Hati.', title_ja = 'パパの番 👨‍🍼', body_ja = '一日じゅう「ダメ」と言ってルールを決めるのに疲れましたね。今夜のパジャマと歯みがきの戦いはパパにバトンタッチ。部屋のドアを閉めて、「気分日記」に今日の気持ちを書きながら、自分だけの時間を過ごしましょう。', title_ko = '이제 아빠 차례예요 👨‍🍼', body_ko = '하루 종일 ''안 돼''라고 하고 규칙을 세우느라 지쳤나요? 오늘 저녁 잠옷과 양치 전쟁은 아빠에게 넘기세요. 방문을 닫고 기분 일기에 오늘의 마음을 적으며 오롯이 나를 위한 시간을 보내세요.', title_nl = 'Papa is aan de beurt 👨‍🍼', body_nl = 'Ben je moe van de hele dag ''nee'' zeggen en regels stellen? Geef de strijd om pyjama en tandenborstel vanavond aan papa. Trek de deur dicht en neem tijd helemaal voor jezelf door je gevoelens van vandaag in je Stemmingsdagboek te schrijven.', title_pl = 'Kolej taty 👨‍🍼', body_pl = 'Masz dość całodziennego mówienia „nie” i ustalania zasad. Dziś wieczorem przekaż tacie bitwę o piżamę i mycie zębów. Zamknij drzwi pokoju i poświęć czas wyłącznie sobie, po prostu zapisując dzisiejsze uczucia w Dzienniku nastroju.', title_pt = 'A vez é do pai 👨‍🍼', body_pt = 'Está cansada de dizer "não" e de pôr regras o dia todo. Esta noite, passe ao pai a batalha do pijama e da escova de dentes. Feche a porta do quarto e dedique tempo só a si, escrevendo apenas o que sentiu hoje no Diário de Humor.', title_sv = 'Pappas tur 👨‍🍼', body_sv = 'Du är trött på att säga nej och sätta regler hela dagen. Lämna över kampen om pyjamas och tandborstning till pappa i kväll. Stäng dörren och ta tid helt för dig själv genom att bara skriva ner dagens känslor i Humördagboken.', title_vi = 'Đến lượt bố 👨‍🍼', body_vi = 'Cả ngày nói "không" và đặt quy tắc khiến mẹ mệt mỏi. Tối nay hãy giao cuộc chiến đồ ngủ và đánh răng cho bố. Đóng cửa phòng lại và dành trọn thời gian cho mình bằng cách viết cảm xúc hôm nay vào Nhật ký tâm trạng.', title_zh = '轮到爸爸了 👨‍🍼', body_zh = '说了一整天的“不”、立了一整天的规矩，累了吧。今晚把睡衣和刷牙的战斗交给爸爸。关上房门，在心情日记里写写今天的感受，把时间完全留给自己。' WHERE id = 'a80b1c35-a6ce-48dc-a430-2268378d43f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sonrisas en la Comunidad 💬', body_es = '¿Hoy su tozudez te ha dejado agotada de verdad? Abre ya la Comunidad Anacan y lee las historias de crisis parecidas, o incluso más graciosas, de otras casas. Saber que pasáis por lo mismo y que no estás sola es el mejor apoyo psicológico.', title_fr = 'Des sourires dans la Communauté 💬', body_fr = 'Ses caprices vous ont vraiment épuisée aujourd''hui ? Ouvrez tout de suite la Communauté Anacan et lisez les histoires de crises semblables, voire plus drôles, chez d''autres mamans. Savoir que vous passez par les mêmes chemins et que vous n''êtes pas seule, c''est le meilleur soutien psychologique.', title_hi = 'कम्युनिटी में मुस्कान 💬', body_hi = 'आज उसकी ज़िद ने सच में आपको थका दिया? तुरंत Anacan कम्युनिटी खोलिए और दूसरी माँओं के घरों की ऐसी ही, बल्कि और भी मज़ेदार कहानियाँ पढ़िए। यह जानना कि आप उन्हीं रास्तों से गुज़र रही हैं और अकेली नहीं हैं, सबसे अच्छा मानसिक सहारा है।', title_id = 'Senyuman di komunitas 💬', body_id = 'Hari ini sifat keras kepalanya benar-benar menguras tenaga Anda? Segera buka Komunitas Anacan dan baca kisah krisis serupa, bahkan yang lebih lucu, dari rumah ibu-ibu lain. Mengetahui bahwa Anda melewati jalan yang sama dan tidak sendirian adalah dukungan psikologis terbaik.', title_ja = 'コミュニティで笑顔に 💬', body_ja = '今日はお子さんのあまのじゃくに本当に疲れはてましたか？すぐにAnacanコミュニティを開いて、ほかのママの家で起きた似たような、もっとおかしなかんしゃくの話を読んでみましょう。同じ道を歩んでいて、ひとりではないと知ることが、いちばんの心の支えです。', title_ko = '커뮤니티 속 미소 💬', body_ko = '오늘 아이의 고집에 정말 지쳤나요? 바로 Anacan 커뮤니티를 열고 다른 집의 비슷하거나 더 웃긴 떼쓰기 이야기를 읽어 보세요. 같은 길을 걷고 있고 혼자가 아니라는 걸 아는 게 최고의 위로예요.', title_nl = 'Een glimlach in de community 💬', body_nl = 'Heeft zijn dwarsheid je vandaag echt uitgeput? Open meteen de Anacan Community en lees de herkenbare, en soms nog grappigere, crisisverhalen van andere moeders. Weten dat je hetzelfde meemaakt en niet alleen bent is de beste psychologische steun.', title_pl = 'Uśmiech w Społeczności 💬', body_pl = 'Jego przekora naprawdę cię dziś wykończyła? Od razu otwórz Społeczność Anacan i przeczytaj podobne, a nawet zabawniejsze historie kryzysów z domów innych mam. Świadomość, że idziecie tą samą drogą i nie jesteś sama, to najlepsze wsparcie psychiczne.', title_pt = 'Sorrisos na Comunidade 💬', body_pt = 'Hoje as teimosias dele deixaram-na mesmo esgotada? Abra já a Comunidade Anacan e leia as histórias de crises parecidas, ou ainda mais cómicas, nas casas de outras mães. Saber que passa pelo mesmo e que não está sozinha é o melhor apoio psicológico.', title_sv = 'Leenden i gemenskapen 💬', body_sv = 'Har barnets trots verkligen tömt dig i dag? Öppna genast Anacan Community och läs om liknande, eller ännu roligare, kriser hemma hos andra mammor. Att veta att du går samma väg och inte är ensam är det bästa psykologiska stödet.', title_vi = 'Nụ cười trong Cộng đồng 💬', body_vi = 'Hôm nay sự bướng bỉnh của bé khiến mẹ thật sự kiệt sức? Hãy mở ngay Cộng đồng Anacan và đọc những câu chuyện khủng hoảng tương tự, thậm chí buồn cười hơn, ở nhà các mẹ khác. Biết mình đang đi trên cùng một con đường và không đơn độc là sự hỗ trợ tâm lý tốt nhất.', title_zh = '在社区里找回笑容 💬', body_zh = '今天宝宝的倔强真的把你耗尽了？马上打开Anacan社区，读读其他妈妈家里类似、甚至更好笑的崩溃故事。知道大家走着同样的路、你并不孤单，就是最好的心理支持。' WHERE id = 'f6d030df-f5ef-4ef7-84fc-04dd7126bef2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Control de la lista 🛒', body_es = '¿Has añadido a la Lista de la compra todo lo necesario para el día de la celebración? Asegúrate de que estén también los globos y las pequeñas sorpresas. Envía a tu pareja el último recordatorio desde la app.', title_fr = 'Contrôle de la liste 🛒', body_fr = 'Vous avez ajouté à la Liste de courses tout ce qu''il faut pour le jour de la fête ? Vérifiez que les ballons et les petites surprises y sont aussi. Envoyez un dernier rappel à votre partenaire depuis l''application.', title_hi = 'लिस्ट पर नज़र 🛒', body_hi = 'जश्न के दिन के लिए ज़रूरी सब कुछ शॉपिंग लिस्ट में जोड़ लिया? पक्का कर लीजिए कि गुब्बारे और छोटे सरप्राइज़ भी उसमें हैं। ऐप से अपने पार्टनर को आखिरी रिमाइंडर भेज दीजिए।', title_id = 'Periksa daftar 🛒', body_id = 'Sudah menambahkan semua kebutuhan untuk hari perayaan ke Daftar Belanja? Pastikan balon dan kejutan kecil juga ada di sana. Kirim pengingat terakhir kepada pasangan dari aplikasi.', title_ja = 'リストをチェック 🛒', body_ja = '記念日に必要なものは全部「買い物リスト」に入れましたか？風船や小さなサプライズも入っているか確認して、アプリからパートナーに最後のリマインドを送りましょう。', title_ko = '목록 점검 🛒', body_ko = '기념일에 필요한 걸 모두 쇼핑 목록에 넣었나요? 풍선과 작은 깜짝 선물도 들어 있는지 확인하세요. 앱에서 배우자에게 마지막 알림을 보내 주세요.', title_nl = 'Het lijstje checken 🛒', body_nl = 'Heb je alles voor de jubileumdag op het Boodschappenlijstje gezet? Zorg dat de ballonnen en kleine verrassingen er ook op staan. Stuur je partner vanuit de app een laatste herinnering.', title_pl = 'Kontrola listy 🛒', body_pl = 'Dodałaś na Listę zakupów wszystko, czego potrzeba na dzień jubileuszu? Upewnij się, że są tam też balony i małe niespodzianki. Wyślij partnerowi z aplikacji ostatnie przypomnienie.', title_pt = 'Controlo da lista 🛒', body_pt = 'Já juntou à Lista de Compras tudo o que é preciso para o dia da festa? Confirme que os balões e as pequenas surpresas também lá estão. Envie ao seu companheiro o último lembrete pela app.', title_sv = 'Koll på listan 🛒', body_sv = 'Har du lagt till allt som behövs för jubileumsdagen i Inköpslistan? Se till att ballongerna och de små överraskningarna också finns där. Skicka en sista påminnelse till din partner från appen.', title_vi = 'Kiểm tra danh sách 🛒', body_vi = 'Mẹ đã thêm mọi thứ cần cho ngày kỷ niệm vào Danh sách mua sắm chưa? Hãy chắc chắn có cả bóng bay và những món quà bất ngờ nho nhỏ. Gửi lời nhắc cuối cùng cho chồng từ ứng dụng nhé.', title_zh = '检查清单 🛒', body_zh = '纪念日需要的东西都加进购物清单了吗？确认一下气球和小惊喜也在里面。在应用里给另一半发个最后提醒吧。' WHERE id = 'e612b840-bcec-4199-920b-e4d2f37aa7cb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vigilante de la luz 🤫', body_es = 'La primera media hora después de dormirse es cuando el cerebro está más activo. Ajusta la habitación con el Medidor de sonido. Neutraliza los ruidos que llegan por la ventana y crea un ambiente totalmente tranquilo y oscuro.', title_fr = 'Veiller sur l''ambiance du sommeil 🤫', body_fr = 'La première demi-heure de sommeil est le moment où le cerveau est le plus actif. Ajustez la chambre avec le Sonomètre. Neutralisez les sons venant de la fenêtre et créez une ambiance totalement calme et sombre.', title_hi = 'रोशनी पर नज़र 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा वह समय है जब दिमाग सबसे सक्रिय होता है। साउंड मीटर से कमरे का माहौल ठीक कीजिए। खिड़की से आने वाली आवाज़ें दबाकर पूरी तरह शांत और अंधेरा माहौल बनाइए।', title_id = 'Penjaga cahaya 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah saat otak paling aktif. Atur kamar dengan Pengukur Suara. Redam suara dari jendela dan ciptakan suasana yang benar-benar tenang dan gelap.', title_ja = '眠りの環境チェック 🤫', body_ja = '寝ついてから最初の30分は、脳がいちばん活発な時間です。「サウンドメーター」で部屋を整えましょう。窓の外の音をやわらげて、完全に静かで暗い環境をつくって。', title_ko = '수면 환경 지킴이 🤫', body_ko = '잠든 후 첫 30분은 뇌가 가장 활발한 시간이에요. 소음 측정기로 방을 조절하세요. 창밖 소리를 줄이고 완전히 조용하고 어두운 환경을 만들어 주세요.', title_nl = 'Bewaker van de rust 🤫', body_nl = 'Het eerste halfuur na het inslapen zijn de hersenen het actiefst. Stem de kamer af met de Geluidsmeter. Neutraliseer geluiden van buiten en zorg voor een helemaal stille en donkere omgeving.', title_pl = 'Strażnik światła 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to czas największej aktywności mózgu. Dostosuj pokój Miernikiem dźwięku. Zneutralizuj odgłosy zza okna i stwórz całkowicie ciche i ciemne otoczenie.', title_pt = 'Vigilante da luz 🤫', body_pt = 'A primeira meia hora depois de adormecer é quando o cérebro está mais ativo. Ajuste o quarto com o Medidor de Som. Neutralize os sons que vêm da janela e crie um ambiente totalmente calmo e escuro.', title_sv = 'Ljusvakten 🤫', body_sv = 'Den första halvtimmen efter insomnandet är då hjärnan är som mest aktiv. Justera rummet med Ljudmätaren. Neutralisera ljud från fönstret och skapa en helt lugn och mörk miljö.', title_vi = 'Người canh giữ ánh sáng 🤫', body_vi = 'Nửa giờ đầu sau khi bé ngủ là lúc não hoạt động mạnh nhất. Hãy điều chỉnh phòng bằng Đo âm thanh. Trung hòa tiếng ồn từ cửa sổ và tạo một không gian hoàn toàn yên tĩnh, tối.', title_zh = '光线守护者 🤫', body_zh = '入睡后的头半小时是大脑最活跃的时候。用分贝仪调节房间环境。屏蔽窗外的声音，营造完全安静、黑暗的环境。' WHERE id = 'eb50f918-4009-4323-94a0-e8fd1ccc9f1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El director de la historia 🪄', body_es = 'Abre Cuentos inteligentes y esta noche deja que sea tu peque quien dirija la trama. Pregúntale «¿Adónde va ahora el héroe?» y que se duerma con el final absurdo que se invente.', title_fr = 'Le metteur en scène de l''histoire 🪄', body_fr = 'Ouvrez les Contes intelligents et, ce soir, laissez-le diriger l''intrigue. Demandez-lui « Et maintenant, où va le héros ? » et laissez-le s''endormir sur la fin absurde qu''il aura inventée.', title_hi = 'कहानी का निर्देशक 🪄', body_hi = 'स्मार्ट कहानियाँ खोलिए और आज शाम कहानी की दिशा उसे तय करने दीजिए। पूछिए ''अब वह हीरो कहाँ जाए?'', और उसे अपने गढ़े हुए बेतुके अंत के साथ खुद ही सो जाने दीजिए।', title_id = 'Sutradara cerita 🪄', body_id = 'Buka Dongeng Pintar dan malam ini biarkan ia yang mengarahkan alur ceritanya. Tanyakan ''Sekarang pahlawan itu pergi ke mana?'', dan biarkan ia tertidur dengan akhir cerita absurd karangannya sendiri.', title_ja = 'お話の監督さん 🪄', body_ja = '「スマートおはなし」を開いて、今夜はストーリーをお子さんに導いてもらいましょう。「主人公は次にどこへ行こうか？」と聞いて、自分で考えたおかしな結末とともに眠りにつかせてあげて。', title_ko = '이야기의 감독 🪄', body_ko = '스마트 동화를 열고 오늘 밤엔 줄거리를 아이가 이끌게 해 보세요. ''이제 주인공은 어디로 갈까?'' 하고 물으며, 아이가 지어낸 엉뚱한 결말과 함께 스르르 잠들게 해 주세요.', title_nl = 'Regisseur van het verhaal 🪄', body_nl = 'Open Slimme sprookjes en laat hem vanavond het verhaal sturen. Vraag: ''Waar moet de held nu naartoe?'' en laat hem zelf in slaap vallen bij het absurde einde dat hij verzint.', title_pl = 'Reżyser historii 🪄', body_pl = 'Otwórz Mądre bajki i pozwól mu dziś wieczorem kierować fabułą. Zapytaj: „Dokąd teraz ma iść bohater?” i niech zaśnie przy wymyślonym przez siebie absurdalnym zakończeniu.', title_pt = 'O realizador da história 🪄', body_pt = 'Abra as Histórias Inteligentes e, esta noite, deixe-o conduzir o enredo. Pergunte: "E agora, para onde vai o herói?" e deixe-o adormecer com o final absurdo que inventou.', title_sv = 'Berättelsens regissör 🪄', body_sv = 'Öppna Smarta sagor och låt barnet styra handlingen i kväll. Fråga ”Vart ska hjälten gå nu?” och låt barnet somna till sitt eget påhittade, absurda slut.', title_vi = 'Đạo diễn của câu chuyện 🪄', body_vi = 'Hãy mở Truyện cổ tích thông minh và tối nay để bé dẫn dắt cốt truyện. Hỏi bé "Giờ nhân vật ấy nên đi đâu?" và để bé chìm vào giấc ngủ cùng cái kết ngộ nghĩnh do mình nghĩ ra.', title_zh = '故事的导演 🪄', body_zh = '打开智能故事，今晚让宝宝来决定情节。问一句“现在主角该去哪儿？”，让宝宝伴着自己编的离奇结局进入梦乡吧。' WHERE id = '0cde3d33-fabc-43f7-bcba-b8c6c307e26e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lágrimas sin lógica 🐶', body_es = '¿Ha llorado desconsolado 15 minutos porque el perro que visteis en la calle no le miró? No busques lógica. Para tu peque es una pena muy profunda. Valida lo que siente: «Ya lo sé, querías que te mirara».', title_fr = 'Des larmes sans logique 🐶', body_fr = 'Il a sangloté 15 minutes parce que le chien croisé dans la rue ne l''a pas regardé ? Ne cherchez pas de logique. Pour lui, c''est un vrai gros chagrin. Validez son émotion : « Je sais, tu voulais qu''il te regarde. »', title_hi = 'बेतुके आँसू 🐶', body_hi = 'सड़क पर दिखा कुत्ता उसकी ओर नहीं देखा, इसलिए 15 मिनट तक फूट-फूटकर रोया? तर्क मत ढूँढिए। उसके लिए यह सच में गहरा दुख है। ''मैं जानती हूँ, तुम चाहते थे कि वह तुम्हें देखे'' कहकर उसकी भावना को स्वीकार कीजिए।', title_id = 'Air mata tanpa logika 🐶', body_id = 'Ia menangis tersedu-sedu 15 menit karena anjing yang kalian lihat di jalan tidak menoleh padanya? Jangan mencari logika. Baginya ini benar-benar kesedihan yang dalam. Akui perasaannya dengan berkata ''Ibu tahu, kamu ingin dia melihatmu''.', title_ja = '理屈のない涙 🐶', body_ja = '道で見かけた犬がこっちを見なかったから、15分も泣きじゃくった？理屈を探さないで。お子さんにとっては本当に深い悲しみなのです。「わかるよ、見てほしかったんだよね」と気持ちを受け止めましょう。', title_ko = '이유 없는 눈물 🐶', body_ko = '길에서 본 강아지가 쳐다보지 않았다고 15분 동안 엉엉 울었나요? 논리를 찾지 마세요. 아이에게는 정말 깊은 슬픔이에요. ''그 강아지가 너를 봐 주길 바랐구나'' 하고 마음을 인정해 주세요.', title_nl = 'Tranen zonder logica 🐶', body_nl = 'Huilde hij 15 minuten tranen met tuiten omdat een hond op straat niet naar hem keek? Zoek geen logica. Voor hem is dit echt diep verdriet. Erken zijn gevoel: ''Ik weet het, je wilde dat hij naar je keek.''', title_pl = 'Łzy bez logiki 🐶', body_pl = 'Płakał rzewnie przez 15 minut, bo pies na ulicy na niego nie spojrzał? Nie szukaj logiki. Dla niego to naprawdę głęboki smutek. Potwierdź jego uczucia: „Wiem, chciałeś, żeby na ciebie spojrzał”.', title_pt = 'Lágrimas sem lógica 🐶', body_pt = 'Chorou 15 minutos aos soluços porque o cão que viram na rua não olhou para ele? Não procure lógica. Para ele, é um desgosto mesmo profundo. Valide o que sente: "Eu sei, querias que ele olhasse para ti."', title_sv = 'Tårar utan logik 🐶', body_sv = 'Grät barnet hejdlöst i 15 minuter för att hunden ni såg på gatan inte tittade på hen? Leta inte efter logik. För barnet är det en verkligt djup sorg. Bekräfta känslan: ”Jag vet, du ville att den skulle titta på dig.”', title_vi = 'Những giọt nước mắt vô lý 🐶', body_vi = 'Bé khóc nức nở 15 phút chỉ vì chú chó ngoài đường không nhìn bé? Đừng tìm logic. Với bé đó thật sự là nỗi buồn sâu sắc. Hãy công nhận cảm xúc của bé: "Mẹ biết, con muốn bạn chó nhìn con".', title_zh = '没有道理的眼泪 🐶', body_zh = '因为街上的小狗没看自己，就号啕大哭了15分钟？别找道理。对宝宝来说，这真的是很深的伤心。说一句“我知道，你希望它看看你”，认可宝宝的感受。' WHERE id = '60a51ebc-ca29-4910-bc60-cd0880a0539a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con el caos de casa 🌪️', body_es = '¿La habitación está llena de juguetes? Lo importante no es la limpieza, sino estos momentos traviesos con tu peque. Los juguetes seguirán ahí mañana, no te agotes. A veces rendirse al desorden es el mejor descanso.', title_fr = 'Faire la paix avec le chaos de la maison 🌪️', body_fr = 'Il y a des jouets partout dans la pièce ? Ce qui compte, ce n''est pas le ménage, mais ces moments espiègles avec lui. Les jouets seront encore là demain, ne vous épuisez pas. Parfois, se rendre face au désordre est le meilleur repos.', title_hi = 'घर की अफ़रा-तफ़री से सुलह 🌪️', body_hi = 'कमरे में हर जगह खिलौने हैं? सफ़ाई नहीं, उसके साथ बिताए ये शरारती पल ज़रूरी हैं। खिलौने कल भी वहीं होंगे, खुद को मत थकाइए। कभी-कभी बिखराव के आगे हार मान लेना ही सबसे अच्छा आराम है।', title_id = 'Berdamai dengan kekacauan rumah 🌪️', body_id = 'Mainan di mana-mana di seluruh kamar? Yang penting bukan kebersihan, tetapi momen jahil yang Anda lalui bersamanya. Mainan itu besok masih di sana, jangan memaksakan diri. Kadang menyerah pada kekacauan adalah istirahat terbaik.', title_ja = '家の散らかりと仲直り 🌪️', body_ja = '部屋じゅうおもちゃだらけ？大切なのは片づけではなく、お子さんと過ごすこのやんちゃな時間です。おもちゃは明日もそこにあります、無理しないで。ときには散らかりに降参するのがいちばんの休息です。', title_ko = '집 안의 혼돈과 화해하기 🌪️', body_ko = '방 안 곳곳이 장난감인가요? 중요한 건 청소가 아니라 아이와 보내는 이 장난스러운 순간이에요. 장난감은 내일도 거기 있으니 무리하지 마세요. 가끔은 어질러짐에 항복하는 게 최고의 휴식이에요.', title_nl = 'Vrede sluiten met de chaos 🌪️', body_nl = 'Ligt de hele kamer vol speelgoed? Niet de netheid, maar deze ondeugende momenten samen zijn belangrijk. Het speelgoed ligt er morgen ook nog, put jezelf niet uit. Soms is je overgeven aan de rommel de beste rust.', title_pl = 'Pogodzić się z domowym chaosem 🌪️', body_pl = 'Zabawki w każdym kącie pokoju? Ważne jest nie sprzątanie, tylko te psotne chwile z nim. Zabawki będą tam też jutro, nie męcz się. Czasem poddanie się bałaganowi to najlepszy odpoczynek.', title_pt = 'Fazer as pazes com o caos da casa 🌪️', body_pt = 'O quarto está cheio de brinquedos por todo o lado? O importante não é a limpeza, são estes momentos traquinas com ele. Os brinquedos amanhã ainda lá estão, não se canse. Às vezes, render-se à desarrumação é o melhor descanso.', title_sv = 'Försonas med kaoset hemma 🌪️', body_sv = 'Är det leksaker överallt i rummet? Det viktiga är inte städningen, utan de busiga stunderna ni har tillsammans. Leksakerna finns kvar i morgon också, slit inte ut dig. Ibland är det bästa vilan att ge upp inför stöket.', title_vi = 'Làm hòa với sự bừa bộn 🌪️', body_vi = 'Đồ chơi bày khắp phòng? Điều quan trọng không phải là sạch sẽ mà là những khoảnh khắc nghịch ngợm bên bé. Đồ chơi mai vẫn ở đó, đừng tự làm mình mệt. Đôi khi đầu hàng sự bừa bộn là cách nghỉ ngơi tốt nhất.', title_zh = '和家里的混乱和解 🌪️', body_zh = '房间里到处都是玩具？重要的不是干净，而是和宝宝一起度过的这些调皮时光。玩具明天还会在那儿，别累坏自己。有时向凌乱投降，就是最好的休息。' WHERE id = 'e0a781fd-ff93-41bb-aced-df42a4ca9525' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No llores 🫂', body_es = '¿Cuando ve a otro niño llorando en el parque se acerca y le acaricia? ¡Su empatía ya está en marcha! Observa desde fuera con orgullo esta compasión tan bonita.', title_fr = 'Ne pleure pas 🫂', body_fr = 'Au parc, quand il voit un autre enfant pleurer, il s''approche et le caresse ? L''empathie est officiellement en marche ! Observez fièrement de loin sa magnifique bienveillance.', title_hi = 'मत रो 🫂', body_hi = 'पार्क में किसी दूसरे बच्चे को रोता देखकर उसके पास जाकर सहलाता है? हमदर्दी अब सच में काम कर रही है! उसकी इस शानदार दयालुता को दूर से गर्व से देखिए।', title_id = 'Jangan menangis 🫂', body_id = 'Saat melihat anak lain menangis di taman, ia mendekat dan mengelusnya? Rasa empatinya resmi bekerja! Saksikan belas kasihnya yang luar biasa ini dari jauh dengan bangga.', title_ja = '泣かないで 🫂', body_ja = '公園で泣いているほかの子を見て、近づいてなでてあげますか？思いやりの心がいよいよ動き出しました！このすばらしいやさしさを、少し離れて誇らしく見守りましょう。', title_ko = '울지 마 🫂', body_ko = '공원에서 우는 다른 아이를 보면 다가가 쓰다듬어 주나요? 공감 능력이 본격적으로 자라고 있어요! 이 멋진 배려심을 멀리서 뿌듯하게 지켜보세요.', title_nl = 'Niet huilen 🫂', body_nl = 'Gaat hij in het park naar een ander huilend kind toe om het te aaien? Empathie is officieel begonnen! Kijk trots naar zijn prachtige medeleven.', title_pl = 'Nie płacz 🫂', body_pl = 'Gdy w parku widzi płaczące dziecko, podchodzi i je głaszcze? Empatia oficjalnie działa! Z dumą obserwuj z boku to jego wspaniałe współczucie.', title_pt = 'Não chores 🫂', body_pt = 'No parque, quando vê outra criança a chorar, aproxima-se e faz-lhe festas? A empatia está oficialmente em ação! Observe de longe, com orgulho, esta compaixão fantástica.', title_sv = 'Gråt inte 🫂', body_sv = 'Går barnet fram och klappar ett annat barn som gråter i parken? Empatin är officiellt igång! Titta stolt på den fantastiska medkänslan på avstånd.', title_vi = 'Bạn đừng khóc nhé 🫂', body_vi = 'Thấy một bạn khác khóc ở công viên, bé lại gần và vuốt ve bạn? Sự đồng cảm đã chính thức hoạt động! Hãy tự hào quan sát lòng trắc ẩn tuyệt vời này của bé từ xa.', title_zh = '你别哭 🫂', body_zh = '在公园里看到别的小朋友哭，就走过去摸摸他？共情能力正式上线了！在一旁骄傲地看着宝宝这份了不起的善良吧。' WHERE id = '3a84b553-313a-486c-95e8-2a799895283c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Paso a la cama grande? 🛏️', body_es = '¿Intenta trepar para salir de la cuna? Quizá ya tengas dudas. Pregunta a Anacan AI las normas de seguridad y el mejor momento para pasar a una cama de niño grande.', title_fr = 'Passage au grand lit ? 🛏️', body_fr = 'Il essaie d''escalader son lit à barreaux pour en descendre ? Vous hésitez peut-être déjà. Demandez à Anacan AI les règles de sécurité et le meilleur moment pour passer au grand lit.', title_hi = 'बड़े बिस्तर पर जाने का समय? 🛏️', body_hi = 'पालने से चढ़कर नीचे उतरने की कोशिश करता है? शायद आप अभी तय नहीं कर पा रहीं। Anacan AI से बड़े बच्चों वाले बिस्तर पर जाने के सुरक्षा नियम और सबसे सही समय पूछिए।', title_id = 'Pindah ke kasur besar? 🛏️', body_id = 'Ia mencoba memanjat keluar dari boks bayi? Mungkin Anda sudah mulai ragu. Tanyakan pada Anacan AI aturan keamanan dan waktu yang paling tepat untuk pindah ke kasur anak besar.', title_ja = '大きいベッドへ移る？🛏️', body_ja = 'ベビーベッドからよじ登って出ようとしていますか？迷い始めているかもしれませんね。大きい子用ベッドへの移行の安全ルールといちばんいいタイミングを、Anacan AIに聞いてみましょう。', title_ko = '큰 침대로 바꿀 때? 🛏️', body_ko = '아기 침대를 기어 넘으려 하나요? 망설여진다면 Anacan AI에게 큰 아이 침대로 바꿀 때의 안전 수칙과 가장 알맞은 시기를 물어보세요.', title_nl = 'Over naar een groot bed? 🛏️', body_nl = 'Probeert hij uit zijn ledikantje te klimmen? Misschien twijfel je al. Vraag Anacan AI naar de veiligheidsregels en het beste moment om over te stappen naar een groot bed.', title_pl = 'Czas na duże łóżko? 🛏️', body_pl = 'Próbuje wydostać się z łóżeczka? Może już się wahasz. Zapytaj Anacan AI o zasady bezpieczeństwa i najlepszy moment na przejście do dużego łóżka.', title_pt = 'Passar para a cama grande? 🛏️', body_pt = 'Tenta trepar e sair do berço? Talvez já esteja com dúvidas. Pergunte ao Anacan AI as regras de segurança e a melhor altura para passar para a cama de criança crescida.', title_sv = 'Dags för en stor säng? 🛏️', body_sv = 'Försöker barnet klättra ur spjälsängen? Kanske tvekar du redan. Fråga Anacan AI om säkerhetsreglerna och den bästa tidpunkten för att byta till en större barnsäng.', title_vi = 'Chuyển sang giường lớn? 🛏️', body_vi = 'Bé cố trèo ra khỏi cũi? Có lẽ mẹ đang phân vân. Hãy hỏi Anacan AI về quy tắc an toàn và thời điểm phù hợp nhất để chuyển sang giường lớn.', title_zh = '换大床了？🛏️', body_zh = '想从婴儿床里爬出来？也许你已经在犹豫了。问问Anacan AI，换儿童大床的安全规则和最合适的时机。' WHERE id = '77ff1ffc-86a7-418d-bad4-4d026f199772' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche deja descansar tus cuerdas vocales. Que papá se encargue de leer los libros favoritos de tu peque con voces distintas.', body_fr = 'Ce soir, reposez vos cordes vocales. Laissez papa lire les livres préférés de l''enfant en changeant de voix.', body_hi = 'आज शाम अपनी आवाज़ को आराम दीजिए। बच्चे की सबसे पसंदीदा किताबें अलग-अलग आवाज़ों में पढ़ने का काम पापा को करने दीजिए।', body_id = 'Malam ini istirahatkan pita suara Anda. Biar Ayah yang membacakan buku favorit anak dengan berbagai nada suara.', body_ja = '今夜はあなたの声を休ませましょう。お子さんのいちばん好きな絵本をいろいろな声色で読む役目は、パパにお任せして。', body_ko = '오늘 저녁엔 목을 쉬게 하세요. 아이가 가장 좋아하는 책을 여러 목소리로 읽어 주는 일은 아빠에게 맡기세요.', body_nl = 'Laat je stembanden vanavond rusten. Laat papa zijn lievelingsboeken voorlezen, met allerlei verschillende stemmetjes.', body_pl = 'Daj dziś odpocząć strunom głosowym. Niech to tata przeczyta ulubione książki dziecka różnymi głosami.', body_pt = 'Esta noite, descanse as cordas vocais. Deixe o pai ler os livros preferidos da criança com vozes diferentes.', body_sv = 'Vila stämbanden i kväll. Låt pappa läsa barnets favoritböcker med olika röster.', body_vi = 'Tối nay hãy cho dây thanh quản được nghỉ ngơi. Hãy để bố đảm nhận việc đọc những cuốn sách bé yêu thích bằng nhiều giọng khác nhau.', body_zh = '今晚让你的嗓子休息一下。把用各种语调读孩子最爱的书这项任务，交给爸爸吧。' WHERE id = 'e176efcb-aafc-4480-93eb-e1978282a880' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Director frente al espejo 🎭', body_es = '¿Se pone delante del espejo, pone caras distintas y habla solo? Está probando papeles diferentes. Obsérvale a escondidas y disfruta de estos momentos tan cómicos.', title_fr = 'Metteur en scène devant le miroir 🎭', body_fr = 'Devant le miroir, il fait des grimaces et se parle tout seul ? Il essaie différents rôles. Observez-le en cachette et savourez ces moments comiques.', title_hi = 'आईने के सामने निर्देशक 🎭', body_hi = 'आईने के सामने खड़े होकर तरह-तरह के चेहरे बनाता है, खुद से बातें करता है? वह अलग-अलग किरदार आज़मा रहा है। चुपके से उसे देखिए और इन मज़ेदार पलों का आनंद लीजिए।', title_id = 'Sutradara di depan cermin 🎭', body_id = 'Ia berdiri di depan cermin, membuat berbagai ekspresi, dan berbicara sendiri? Ia sedang mencoba berbagai peran. Amati diam-diam dan nikmati momen-momen lucu ini.', title_ja = '鏡の前の監督さん 🎭', body_ja = '鏡の前でいろいろな表情をして、ひとりで話していますか？いろいろな役を試しているのです。こっそり見守って、このおもしろい瞬間を楽しみましょう。', title_ko = '거울 앞의 꼬마 감독 🎭', body_ko = '거울 앞에 서서 여러 표정을 짓고 혼잣말을 하나요? 여러 역할을 시험해 보는 중이에요. 몰래 지켜보며 이 웃긴 순간을 즐기세요.', title_nl = 'Regisseur voor de spiegel 🎭', body_nl = 'Staat hij voor de spiegel allerlei gezichten te trekken en in zichzelf te praten? Hij probeert verschillende rollen uit. Kijk stiekem toe en geniet van deze grappige momenten.', title_pl = 'Reżyser przed lustrem 🎭', body_pl = 'Staje przed lustrem, robi różne miny i mówi do siebie? Wypróbowuje różne role. Obserwuj go ukradkiem i delektuj się tymi zabawnymi chwilami.', title_pt = 'Realizador em frente ao espelho 🎭', body_pt = 'Põe-se em frente ao espelho, faz caretas diferentes e fala sozinho? Está a experimentar papéis diferentes. Observe-o às escondidas e saboreie estes momentos cómicos.', title_sv = 'Regissör framför spegeln 🎭', body_sv = 'Står barnet framför spegeln, gör olika miner och pratar för sig själv? Hen provar olika roller. Titta i smyg och njut av de här komiska stunderna.', title_vi = 'Đạo diễn trước gương 🎭', body_vi = 'Bé đứng trước gương làm đủ kiểu mặt, tự nói chuyện một mình? Bé đang thử nghiệm những vai diễn khác nhau. Hãy lén quan sát và tận hưởng những khoảnh khắc ngộ nghĩnh này.', title_zh = '镜子前的小导演 🎭', body_zh = '站在镜子前做各种表情，自言自语？宝宝在尝试不同的角色。悄悄看着宝宝，好好享受这些搞笑时刻吧。' WHERE id = '2c139fbd-2360-47be-8201-67957bcf1684' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta una reserva de energía 🍲', body_es = 'Tanto ajetreo te ha dejado sin fuerzas. Elige en Recetas saludables una comida diferente, rica en hierro y proteínas, que os guste a ti y a tu peque.', title_fr = 'Besoin d''un plein d''énergie 🍲', body_fr = 'Cette course permanente vous a vidée. Choisissez dans les Recettes saines un déjeuner original riche en fer et en protéines, que vous aimerez tous les deux.', title_hi = 'ऊर्जा का भंडार चाहिए 🍲', body_hi = 'भागदौड़ ने आपको थका दिया है। सेहतमंद रेसिपी सेक्शन से आयरन और प्रोटीन से भरपूर एक अलग सा लंच चुनिए जो आपको भी पसंद आए और बच्चे को भी।', title_id = 'Butuh isi ulang energi 🍲', body_id = 'Kesibukan membuat Anda kehabisan tenaga. Pilih makan siang yang berbeda, kaya zat besi dan protein, dari bagian Resep Sehat yang akan disukai Anda dan si kecil.', title_ja = 'エネルギー補給が必要 🍲', body_ja = 'バタバタ続きでくたくたですね。「ヘルシーレシピ」から、あなたもお子さんも気に入る、鉄分とたんぱく質たっぷりのいつもと違うランチを選びましょう。', title_ko = '에너지 충전이 필요해요 🍲', body_ko = '정신없이 뛰어다니느라 기운이 다 빠졌죠. 건강한 레시피에서 엄마도 아이도 좋아할 철분과 단백질 가득한 색다른 점심을 골라 보세요.', title_nl = 'Tijd om bij te tanken 🍲', body_nl = 'Het gerace heeft je uitgeput. Kies uit Gezonde recepten een bijzondere lunch vol ijzer en eiwitten waar jullie allebei van zullen genieten.', title_pl = 'Potrzebny zastrzyk energii 🍲', body_pl = 'Bieganina odebrała ci siły. Wybierz z sekcji Zdrowe przepisy inny obiad, bogaty w żelazo i białko, który zasmakuje i tobie, i dziecku.', title_pt = 'Precisa de uma reserva de energia 🍲', body_pt = 'A correria deixou-a sem forças. Escolha nas Receitas Saudáveis um almoço diferente, rico em ferro e proteína, de que gostem tanto a mãe como a criança.', title_sv = 'Energipåfyllning behövs 🍲', body_sv = 'Allt springande har gjort dig helt slut. Välj en annorlunda lunch rik på järn och protein i avsnittet Hälsosamma recept som både du och barnet kommer att gilla.', title_vi = 'Cần nạp năng lượng 🍲', body_vi = 'Chạy tới chạy lui khiến mẹ kiệt sức. Hãy chọn trong mục Công thức lành mạnh một bữa trưa khác lạ, giàu sắt và đạm mà cả mẹ và bé đều thích.', title_zh = '需要补充能量 🍲', body_zh = '忙得团团转，累坏了吧。去健康食谱板块选一份你和宝宝都会喜欢、富含铁和蛋白质的特别午餐吧。' WHERE id = '42026a5f-2788-45b9-acb9-1e97ccc1366b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En cuanto se duerma, abrid juntos tu pareja y tú el Diario de ánimo. Escribid lo más gracioso que ha hecho hoy tu peque y soltad el estrés riéndoos juntos.', body_fr = 'Dès qu''il dort, ouvrez le Journal d''humeur avec votre partenaire. Notez la chose la plus drôle qu''il a faite aujourd''hui et évacuez le stress en souriant ensemble.', body_hi = 'बच्चे के सोते ही अपने पार्टनर के साथ मूड डायरी खोलिए। आज बच्चे की सबसे मज़ेदार हरकत लिखिए और साथ मुस्कुराकर तनाव उतारिए।', body_id = 'Begitu anak tidur, buka Buku Harian Suasana Hati bersama pasangan. Tulis hal paling lucu yang ia lakukan hari ini dan lepaskan stres sambil tersenyum bersama.', body_ja = 'お子さんが眠ったら、パートナーと一緒に「気分日記」を開きましょう。今日お子さんがしたいちばんおもしろいことを書いて、一緒に笑ってストレスを手放して。', body_ko = '아이가 잠들면 배우자와 함께 기분 일기를 열어 보세요. 오늘 아이가 한 가장 웃긴 행동을 적고 함께 웃으며 스트레스를 날려 보내세요.', body_nl = 'Open zodra hij slaapt samen met je partner je Stemmingsdagboek. Schrijf het grappigste op wat hij vandaag deed en lach samen de stress weg.', body_pl = 'Gdy tylko dziecko zaśnie, otwórzcie z partnerem Dziennik nastroju. Zapiszcie najzabawniejszą rzecz, którą dziś zrobiło, i razem z uśmiechem zrzućcie stres.', body_pt = 'Mal a criança adormeça, abra o Diário de Humor com o seu companheiro. Escrevam a coisa mais engraçada que ela fez hoje e libertem o stress a sorrir juntos.', body_sv = 'Öppna Humördagboken tillsammans med din partner så fort barnet somnat. Skriv ner det roligaste barnet gjorde i dag och släpp stressen genom att le tillsammans.', body_vi = 'Bé vừa ngủ, hãy cùng chồng mở Nhật ký tâm trạng. Viết lại điều buồn cười nhất bé làm hôm nay và cùng nhau mỉm cười để xua tan căng thẳng.', body_zh = '孩子一睡着，就和另一半一起打开心情日记。写下宝宝今天最搞笑的举动，一起笑一笑，把压力释放掉。' WHERE id = 'f413f7f2-f85e-4bd1-a054-6b9d46b4d341' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Al sueño con música 🛀', title_fr = 'S''endormir en musique 🛀', title_hi = 'संगीत के साथ नींद की ओर 🛀', title_id = 'Menuju tidur dengan musik 🛀', title_ja = '音楽で眠りへ 🛀', title_ko = '음악과 함께 잠으로 🛀', title_nl = 'Met muziek naar dromenland 🛀', title_pl = 'Muzyczne zasypianie 🛀', title_pt = 'Adormecer com música 🛀', title_sv = 'Musikalisk väg till sömnen 🛀', title_vi = 'Vào giấc cùng âm nhạc 🛀', title_zh = '在音乐中进入梦乡 🛀' WHERE id = '59d23d62-6dca-4962-aec7-eb093810797b' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La emoción del «¡Te encontré!» 🙈', body_es = 'El escondite ya es su juego favorito. Se esconde detrás de la cortina y espera a que lo encuentres. A esta edad, la idea de que los objetos siguen existiendo se refuerza aún más con estos juegos.', title_fr = 'Le frisson du « Je t''ai trouvé ! » 🙈', body_fr = 'Cache-cache est désormais son jeu préféré. Il se cache derrière le rideau et attend que vous le trouviez. À cet âge, la notion de permanence de l''objet se renforce grâce à ces jeux.', title_hi = '''मिल गया!'' वाला रोमांच 🙈', body_hi = 'छुपन-छुपाई अब सबसे पसंदीदा खेल है। पर्दे के पीछे छिपकर इंतज़ार करता है कि आप उसे ढूँढें। इस उम्र में ''चीज़ें नज़र से हटकर भी मौजूद रहती हैं'' वाली समझ खेलों से और पक्की होती है।', title_id = 'Serunya ''Ketemu!'' 🙈', body_id = 'Petak umpet kini jadi permainan favoritnya. Ia bersembunyi di balik tirai dan menunggu Anda menemukannya. Di usia ini, pemahaman bahwa benda tetap ada makin kuat lewat permainan.', title_ja = '「みーつけた」のワクワク 🙈', body_ja = 'かくれんぼが今いちばんお気に入りの遊び。カーテンの後ろに隠れて、見つけてもらうのを待っています。この年齢では、「見えなくてもものはある」という理解が遊びを通してさらにしっかりします。', title_ko = '''찾았다!''의 설렘 🙈', body_ko = '숨바꼭질이 가장 좋아하는 놀이가 되었어요. 커튼 뒤에 숨어 엄마가 찾아 주길 기다리죠. 이 나이엔 놀이를 통해 대상 영속성 개념이 더욱 단단해져요.', title_nl = 'De spanning van ''Gevonden!'' 🙈', body_nl = 'Verstoppertje is nu zijn favoriete spel. Hij verstopt zich achter het gordijn en wacht tot je hem vindt. Het besef dat dingen blijven bestaan, ook als je ze niet ziet, wordt op deze leeftijd door zulke spelletjes nog sterker.', title_pl = 'Emocje „Mam cię!” 🙈', body_pl = 'Zabawa w chowanego to teraz jego ulubiona gra. Chowa się za zasłoną i czeka, aż go znajdziesz. W tym wieku dzięki zabawom jeszcze bardziej utrwala się pojęcie stałości przedmiotu.', title_pt = 'A emoção do "Encontrei-te!" 🙈', body_pt = 'As escondidas são agora o jogo preferido. Esconde-se atrás da cortina e espera que o encontre. Nesta idade, a noção de permanência dos objetos consolida-se ainda mais com estas brincadeiras.', title_sv = 'Spänningen i ”Där är du!” 🙈', body_sv = 'Kurragömma är nu favoritleken. Barnet gömmer sig bakom gardinen och väntar på att du ska hitta hen. Förståelsen för objektpermanens stärks ännu mer genom lek i den här åldern.', title_vi = 'Niềm háo hức "Tìm thấy con rồi" 🙈', body_vi = 'Trốn tìm giờ là trò chơi yêu thích nhất của bé. Bé nấp sau rèm cửa và chờ mẹ tìm thấy. Ở tuổi này, khái niệm "vật vẫn tồn tại khi không nhìn thấy" được củng cố thêm qua những trò chơi như vậy.', title_zh = '“找到你啦”的兴奋 🙈', body_zh = '躲猫猫已经是最爱的游戏了。宝宝躲在窗帘后面，等着你来找。这个年龄，“物体恒存”的概念会通过游戏变得更加牢固。' WHERE id = '605d2ada-99ba-4138-bd88-c091a6c53e2b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gestionar las crisis 🛑', body_es = '¿Te dan vergüenza las rabietas en la tienda o en el parque? Recuerda: no importa lo que piensen los demás, sino lo que siente tu peque en ese momento. Abrázale con calma.', title_fr = 'Gérer les crises 🛑', body_fr = 'Les crises au magasin ou au parc vous mettent mal à l''aise ? N''oubliez pas : ce qui compte, ce n''est pas ce que pensent les autres, mais l''émotion de votre enfant à ce moment-là. Serrez-le calmement contre vous.', title_hi = 'नखरों को संभालना 🛑', body_hi = 'दुकान या पार्क में होने वाले नखरे आपको शर्मिंदा करते हैं? याद रखिए, आसपास के लोग क्या सोचते हैं यह नहीं, बल्कि उस पल आपके बच्चे की भावना ज़रूरी है। शांति से गले लगाइए।', title_id = 'Mengelola krisis 🛑', body_id = 'Tantrum di toko atau taman membuat Anda malu? Ingat, yang penting bukan apa yang dipikirkan orang sekitar, tetapi emosi anak Anda saat itu. Peluk ia dengan tenang.', title_ja = 'かんしゃくへの対応 🛑', body_ja = 'お店や公園で起きるかんしゃくが恥ずかしいですか？大切なのは周りがどう思うかではなく、そのときのお子さんの気持ちです。静かに抱きしめてあげましょう。', title_ko = '떼쓰기 다루기 🛑', body_ko = '마트나 공원에서 터지는 떼쓰기가 부끄럽나요? 기억하세요. 중요한 건 주변 사람들의 생각이 아니라 그 순간 아이의 감정이에요. 조용히 안아 주세요.', title_nl = 'Buien in de hand houden 🛑', body_nl = 'Schaam je je voor driftbuien in de winkel of het park? Vergeet niet: het gaat niet om wat anderen denken, maar om wat je kind op dat moment voelt. Knuffel hem rustig.', title_pl = 'Radzenie sobie z kryzysami 🛑', body_pl = 'Wstydzisz się napadów złości w sklepie czy w parku? Pamiętaj, ważne jest nie to, co myślą inni, tylko emocje twojego dziecka w tej chwili. Spokojnie go przytul.', title_pt = 'Gerir as crises 🛑', body_pt = 'As birras na loja ou no parque deixam-na envergonhada? Lembre-se: não importa o que os outros pensam, importa a emoção do seu filho naquele momento. Abrace-o com calma.', title_sv = 'Att hantera kriser 🛑', body_sv = 'Skäms du över utbrotten i affären eller i parken? Kom ihåg att det viktiga inte är vad andra tycker, utan barnets känslor i stunden. Krama barnet lugnt.', title_vi = 'Xử lý khủng hoảng 🛑', body_vi = 'Những cơn ăn vạ ở cửa hàng, công viên khiến mẹ ngại ngùng? Đừng quên, điều quan trọng không phải người xung quanh nghĩ gì mà là cảm xúc của bé lúc đó. Hãy bình tĩnh ôm bé.', title_zh = '应对崩溃 🛑', body_zh = '在商店、公园里突然大闹，让你觉得难堪？别忘了，重要的不是旁人怎么想，而是孩子那一刻的情绪。平静地抱抱宝宝。' WHERE id = 'c0738cb9-5d1f-47d6-821c-55b543c58b28' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pone límites personales ✋', body_es = '¿Se aparta o dice «no» cuando alguien quiere darle un beso? Respeta los límites de su cuerpo y haz que los demás también los respeten. La autoestima empieza justo aquí.', title_fr = 'Il pose ses limites personnelles ✋', body_fr = 'Quand quelqu''un veut l''embrasser, il recule ou dit « non » ? Respectez les limites de son corps et faites-les respecter aux autres. C''est précisément là que commence la confiance en soi.', title_hi = 'अपनी सीमाएँ तय करता है ✋', body_hi = 'कोई उसे चूमना चाहे तो दूर हट जाता है या ''नहीं'' कहता है? उसके शरीर की सीमाओं का सम्मान कीजिए और दूसरों से भी करवाइए। आत्मविश्वास यहीं से शुरू होता है।', title_id = 'Menetapkan batas pribadi ✋', body_id = 'Saat seseorang ingin menciumnya, ia menjauh atau berkata tidak? Hormati batas tubuhnya dan pastikan orang lain juga menghormatinya. Rasa percaya diri justru dimulai dari sini.', title_ja = '自分の境界線をつくる ✋', body_ja = 'だれかにキスされそうになると離れたり、「いや」と言ったりしますか？体の境界線を尊重して、ほかの人にも尊重してもらいましょう。自信はまさにここから始まります。', title_ko = '자기 경계를 세워요 ✋', body_ko = '누가 뽀뽀하려고 하면 피하거나 ''싫어''라고 하나요? 아이의 몸의 경계를 존중하고 다른 사람들도 그렇게 하도록 해 주세요. 자존감은 바로 여기서 시작돼요.', title_nl = 'Hij stelt zijn eigen grenzen ✋', body_nl = 'Trekt hij zich terug of zegt hij ''nee'' als iemand hem wil zoenen? Respecteer zijn lichamelijke grenzen en zorg dat anderen dat ook doen. Hier begint zelfvertrouwen.', title_pl = 'Stawia granice osobiste ✋', body_pl = 'Gdy ktoś chce go pocałować, odsuwa się albo mówi „nie”? Szanuj granice jego ciała i dopilnuj, by inni też je szanowali. Właśnie stąd zaczyna się pewność siebie.', title_pt = 'Põe limites pessoais ✋', body_pt = 'Quando alguém o quer beijar, afasta-se ou diz "não"? Respeite os limites do corpo dele e faça com que os outros também respeitem. A autoconfiança começa precisamente aqui.', title_sv = 'Barnet sätter personliga gränser ✋', body_sv = 'Drar sig barnet undan eller säger nej när någon vill pussa hen? Respektera barnets kroppsliga gränser och se till att andra också gör det. Det är just här självkänslan börjar.', title_vi = 'Bé đặt ra ranh giới cá nhân ✋', body_vi = 'Khi có ai muốn hôn, bé né ra hoặc nói "không"? Hãy tôn trọng ranh giới cơ thể của bé và yêu cầu người khác cũng vậy. Sự tự tin bắt đầu chính từ đây.', title_zh = '设立个人界限 ✋', body_zh = '有人想亲宝宝时，宝宝躲开或说“不”？尊重宝宝的身体界限，也要让别人尊重。自信正是从这里开始的。' WHERE id = '65edab42-e5b4-4da3-8b99-8e271dd3fc16' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cansada de los cuentos clásicos? Dale a Cuentos inteligentes un tema especial: las aventuras del dinosaurio mágico al que le encanta comer verduras.', body_fr = 'Lassée des contes classiques ? Donnez un thème spécial aux Contes intelligents : les aventures d''un dinosaure magique qui adore manger des légumes.', body_hi = 'पुरानी कहानियों से थक गईं? स्मार्ट कहानियों को एक खास विषय दीजिए: सब्ज़ियाँ खाना पसंद करने वाले जादुई डायनासोर के कारनामे।', body_id = 'Bosan dengan dongeng klasik? Beri Dongeng Pintar tema khusus: petualangan dinosaurus ajaib yang suka makan sayur.', body_ja = '昔話にあきてしまった？「スマートおはなし」に特別なテーマをあげましょう：野菜を食べるのが大好きな魔法の恐竜の冒険。', body_ko = '늘 듣던 동화가 지겨워졌나요? 스마트 동화에 특별한 주제를 줘 보세요: 채소를 좋아하는 마법 공룡의 모험.', body_nl = 'Ben je klassieke sprookjes beu? Geef Slimme sprookjes een speciaal thema: de avonturen van de magische dinosaurus die dol is op groenten.', body_pl = 'Masz dość klasycznych bajek? Daj Mądrym bajkom wyjątkowy temat: przygody magicznego dinozaura, który uwielbia jeść warzywa.', body_pt = 'Cansada dos contos clássicos? Dê um tema especial às Histórias Inteligentes: as aventuras do dinossauro mágico que adora comer legumes.', body_sv = 'Trött på klassiska sagor? Ge Smarta sagor ett särskilt tema: äventyren om den magiska dinosaurien som älskar att äta grönsaker.', body_vi = 'Chán truyện cổ tích kinh điển rồi? Hãy cho Truyện cổ tích thông minh một chủ đề đặc biệt: cuộc phiêu lưu của chú khủng long phép thuật thích ăn rau.', body_zh = '经典故事讲累了？给智能故事一个特别的主题：《爱吃蔬菜的魔法恐龙历险记》。' WHERE id = 'c46434f8-d6b6-4038-89e7-8bc38a5332c2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Diplomacia con la ropa 👗', body_es = '¿En pleno invierno quiere ponerse pantalón de verano? Abre ya Tiempo y ropa y explícale con lógica, con las imágenes de la pantalla, que fuera hace frío.', title_fr = 'Diplomatie vestimentaire 👗', body_fr = 'Il veut mettre un pantalon d''été en plein hiver ? Ouvrez vite Météo et tenue et expliquez-lui avec logique, grâce aux images à l''écran, qu''il fait froid dehors.', title_hi = 'कपड़ों की कूटनीति 👗', body_hi = 'सर्दी के बीच गर्मियों वाली पैंट पहनना चाहता है? तुरंत मौसम और कपड़े टूल खोलिए और स्क्रीन की तस्वीरें दिखाकर तर्क से समझाइए कि बाहर ठंड है।', title_id = 'Diplomasi busana 👗', body_id = 'Ia ingin memakai celana musim panas di tengah musim dingin? Segera buka alat Cuaca dan Pakaian dan jelaskan secara logis dengan gambar di layar bahwa udara di luar dingin.', title_ja = '服の外交 👗', body_ja = '真冬に夏のズボンをはきたがりますか？すぐに「天気と服装」を開いて、画面のイラストを見せながら、外が寒いことを筋道立てて説明しましょう。', title_ko = '옷 입기 외교 👗', body_ko = '한겨울에 여름 바지를 입겠다고 하나요? 바로 날씨와 옷차림 도구를 열어 화면 속 그림으로 밖이 춥다는 걸 논리적으로 설명해 주세요.', title_nl = 'Kledingdiplomatie 👗', body_nl = 'Wil hij midden in de winter een zomerbroek aan? Open meteen Weer en kleding en leg hem met de plaatjes op het scherm logisch uit dat het buiten koud is.', title_pl = 'Dyplomacja ubraniowa 👗', body_pl = 'W środku zimy chce założyć letnie spodnie? Od razu otwórz narzędzie Pogoda i ubiór i za pomocą obrazków na ekranie logicznie wytłumacz mu, że na dworze jest zimno.', title_pt = 'Diplomacia da roupa 👗', body_pt = 'Quer vestir calças de verão em pleno inverno? Abra já o Tempo e Roupa e, com as imagens do ecrã, explique-lhe com lógica que lá fora está frio.', title_sv = 'Klädesdiplomati 👗', body_sv = 'Vill barnet ha sommarbyxor mitt i vintern? Öppna direkt verktyget Väder och kläder och förklara logiskt med bilderna på skärmen att det är kallt ute.', title_vi = 'Ngoại giao trang phục 👗', body_vi = 'Giữa mùa đông bé đòi mặc quần mùa hè? Hãy mở ngay công cụ Thời tiết và trang phục và dùng hình ảnh trên màn hình để giải thích hợp lý cho bé rằng bên ngoài trời lạnh.', title_zh = '穿衣外交 👗', body_zh = '大冬天想穿夏天的裤子？马上打开天气穿衣工具，用屏幕上的图片有理有据地告诉宝宝外面很冷。' WHERE id = 'd941dd67-309a-49cb-833c-78b38c4762e7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pide ayuda a tu pareja 🛒', body_es = '¿No tienes tiempo para ir a comprar? Abre la Lista de la compra, apunta todo lo que falta en casa y envíasela a tu pareja con un clic. Repartir las tareas es imprescindible.', title_fr = 'Demandez de l''aide à votre partenaire 🛒', body_fr = 'Pas le temps de faire les courses ? Ouvrez la Liste de courses, notez tout ce qui manque à la maison et envoyez-la à votre partenaire en un clic. Le partage des tâches est essentiel.', title_hi = 'पार्टनर से मदद माँगिए 🛒', body_hi = 'खरीदारी का समय नहीं है? शॉपिंग लिस्ट खोलिए, घर में जिन चीज़ों की कमी है वे सब लिखिए और एक टैप में अपने पार्टनर को भेज दीजिए। काम का बँटवारा ज़रूरी है।', title_id = 'Minta bantuan pasangan 🛒', body_id = 'Tidak punya waktu untuk belanja? Buka Daftar Belanja, catat semua yang kurang di rumah, dan kirim ke pasangan dalam satu klik. Pembagian tugas itu wajib.', title_ja = 'パートナーに助けを頼もう 🛒', body_ja = '買い物に行く時間がない？「買い物リスト」を開いて、家で足りないものを全部書き、ワンタップでパートナーに送りましょう。役割分担は欠かせません。', title_ko = '배우자에게 도움을 청하세요 🛒', body_ko = '장 볼 시간이 없나요? 쇼핑 목록을 열어 집에 떨어진 걸 모두 적고 한 번에 배우자에게 보내세요. 일은 나눠야 해요.', title_nl = 'Vraag je partner om hulp 🛒', body_nl = 'Geen tijd voor boodschappen? Open het Boodschappenlijstje, zet erop wat er thuis op is en stuur het met één klik naar je partner. Taakverdeling is een must.', title_pl = 'Poproś partnera o pomoc 🛒', body_pl = 'Nie masz czasu na zakupy? Otwórz Listę zakupów, zapisz wszystko, czego brakuje w domu, i jednym kliknięciem wyślij partnerowi. Podział obowiązków to podstawa.', title_pt = 'Peça ajuda ao seu companheiro 🛒', body_pt = 'Não tem tempo para as compras? Abra a Lista de Compras, aponte tudo o que falta em casa e envie ao seu companheiro num clique. Dividir as tarefas é essencial.', title_sv = 'Be din partner om hjälp 🛒', body_sv = 'Har du inte tid att handla? Öppna Inköpslistan, anteckna allt som saknas hemma och skicka det till din partner med ett klick. Att dela på sysslorna är ett måste.', title_vi = 'Hãy nhờ chồng giúp 🛒', body_vi = 'Mẹ không có thời gian đi mua sắm? Hãy mở Danh sách mua sắm, ghi mọi thứ trong nhà còn thiếu và gửi cho chồng chỉ bằng một chạm. Phân chia công việc là điều cần thiết.', title_zh = '请伴侣帮忙 🛒', body_zh = '没时间去购物？打开购物清单，记下家里缺的所有东西，一键发给另一半。分工合作很重要。' WHERE id = '244e81e4-ef8a-4010-a428-229aabe2c4b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lectura en silencio 📖', body_es = 'Esta noche que en la habitación solo se oiga el pasar de las páginas. Tumbaos los dos en la cama: que tu peque mire su libro de dibujos y tú descansa en silencio.', title_fr = 'Lecture silencieuse 📖', body_fr = 'Ce soir, qu''on n''entende dans la chambre que le bruit des pages. Allongez-vous tous les deux sur le lit : il regarde son livre d''images, vous vous reposez dans le silence.', title_hi = 'चुपचाप किताब पढ़ना 📖', body_hi = 'आज शाम कमरे में बस किताब के पन्ने पलटने की आवाज़ सुनाई दे। दोनों बिस्तर पर लेटिए, वह अपनी तस्वीरों वाली किताब देखे और आप खामोशी में आराम कीजिए।', title_id = 'Membaca dalam hening 📖', body_id = 'Malam ini biarkan hanya suara halaman buku yang terdengar di kamar. Berbaringlah berdua di tempat tidur, biar ia melihat buku bergambarnya, dan Anda beristirahat dalam keheningan.', title_ja = '静かな読書タイム 📖', body_ja = '今夜は部屋に響くのはページをめくる音だけにしましょう。ふたりでベッドに横になり、お子さんは自分の絵本を眺め、あなたは静けさの中で休んで。', title_ko = '조용한 책 읽기 📖', body_ko = '오늘 저녁엔 방에 책장 넘기는 소리만 들리게 해 보세요. 둘이 함께 침대에 누워 아이는 그림책을 보고, 엄마는 고요 속에서 쉬세요.', title_nl = 'Stil lezen 📖', body_nl = 'Laat vanavond alleen het geritsel van bladzijden in de kamer klinken. Ga allebei in bed liggen: hij bekijkt zijn prentenboek, jij rust uit in de stilte.', title_pl = 'Ciche czytanie książek 📖', body_pl = 'Niech dziś wieczorem w pokoju słychać będzie tylko szelest kartek. Połóżcie się oboje do łóżka, on niech ogląda swoją książeczkę z obrazkami, a ty odpoczywaj w ciszy.', title_pt = 'Leitura em silêncio 📖', body_pt = 'Esta noite, que no quarto só se ouça o virar das páginas. Deitem-se os dois na cama: ele vê o seu livro de imagens e a mãe descansa no silêncio.', title_sv = 'Tyst läsning 📖', body_sv = 'Låt bara ljudet av bläddrande boksidor höras i rummet i kväll. Lägg er båda i sängen, låt barnet titta i sin bilderbok medan du vilar i tystnaden.', title_vi = 'Đọc sách yên lặng 📖', body_vi = 'Tối nay hãy để trong phòng chỉ còn tiếng lật trang sách. Cả hai mẹ con nằm trên giường, bé xem sách tranh của mình, còn mẹ nghỉ ngơi trong sự tĩnh lặng.', title_zh = '安静看书 📖', body_zh = '今晚让房间里只有翻书的声音。你们俩都躺到床上，宝宝看自己的图画书，你在安静中好好休息。' WHERE id = 'e5509d0f-428a-4a25-9b61-f825746504ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Saltos peligrosos 🧗‍♂️', body_es = '¿Intenta saltar al suelo desde lo alto del sofá? Confía mucho en su motricidad. En lugar de prohibírselo, pon cojines blandos en el suelo y crea una zona de salto segura.', title_fr = 'Sauts risqués 🧗‍♂️', body_fr = 'Il essaie de sauter du haut du canapé ? Il a très confiance en sa motricité. Au lieu d''interdire, posez des coussins moelleux par terre pour créer une zone de saut sécurisée.', title_hi = 'खतरनाक छलाँगें 🧗‍♂️', body_hi = 'सोफ़े के ऊपर से ज़मीन पर कूदने की कोशिश करता है? उसे अपनी मोटर स्किल्स पर बहुत भरोसा है। मना करने के बजाय ज़मीन पर नरम तकिए रखकर कूदने के लिए सुरक्षित जगह बनाइए।', title_id = 'Lompatan berbahaya 🧗‍♂️', body_id = 'Ia mencoba melompat dari sandaran sofa ke lantai? Ia sangat percaya pada kemampuan motoriknya. Daripada melarang, letakkan bantal empuk di lantai dan buat zona lompat yang aman.', title_ja = '危ないジャンプ 🧗‍♂️', body_ja = 'ソファのてっぺんから床へ飛び降りようとしますか？自分の運動能力にとても自信があるのです。禁止するかわりに、床にやわらかいクッションを置いて安全なジャンプゾーンをつくりましょう。', title_ko = '아찔한 점프 🧗‍♂️', body_ko = '소파 꼭대기에서 바닥으로 뛰어내리려 하나요? 자기 운동 능력을 무척 믿고 있어요. 막는 대신 바닥에 푹신한 쿠션을 깔아 안전한 점프 구역을 만들어 주세요.', title_nl = 'Gevaarlijke sprongen 🧗‍♂️', body_nl = 'Probeert hij van de rugleuning van de bank op de grond te springen? Hij vertrouwt flink op zijn motoriek. Verbied het niet, maar leg zachte kussens op de grond en maak een veilige springzone.', title_pl = 'Niebezpieczne skoki 🧗‍♂️', body_pl = 'Próbuje skakać z oparcia kanapy na podłogę? Bardzo ufa swojej motoryce. Zamiast zabraniać, połóż na podłodze miękkie poduszki i stwórz bezpieczną strefę do skakania.', title_pt = 'Saltos perigosos 🧗‍♂️', body_pt = 'Tenta saltar do topo do sofá para o chão? Confia muito nas suas capacidades motoras. Em vez de proibir, ponha almofadas macias no chão e crie uma zona segura para saltar.', title_sv = 'Farliga hopp 🧗‍♂️', body_sv = 'Försöker barnet hoppa ner på golvet från soffryggen? Hen litar mycket på sin motorik. I stället för att förbjuda, lägg mjuka kuddar på golvet och skapa en säker hoppzon.', title_vi = 'Những cú nhảy mạo hiểm 🧗‍♂️', body_vi = 'Bé cố nhảy từ trên đỉnh sofa xuống sàn? Bé rất tin vào kỹ năng vận động của mình. Thay vì cấm đoán, hãy đặt gối mềm xuống sàn để tạo khu nhảy an toàn.', title_zh = '危险的跳跃 🧗‍♂️', body_zh = '想从沙发顶上跳到地上？宝宝对自己的动作能力非常自信。与其禁止，不如在地上放些软垫，布置一个安全的跳跃区。' WHERE id = 'f568dd40-0374-40d2-8f34-9a863c9b7158' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba de saltarse las normas ⚠️', body_es = '¿Le dices «no lo hagas» y lo hace mirándote a los ojos? No quiere enfadarte, quiere comprobar lo firmes que son tus límites. Mantente firme con las normas.', title_fr = 'Test des règles ⚠️', body_fr = 'Vous lui dites « ne fais pas ça » et il le fait en vous regardant droit dans les yeux ? Il ne cherche pas à vous mettre en colère, il veut tester la solidité de vos limites. Restez constante dans vos règles.', title_hi = 'नियम तोड़ने की परीक्षा ⚠️', body_hi = '''ऐसा मत करो'' कहने पर भी आपकी आँखों में देखते हुए वही करता है? वह आपको गुस्सा नहीं दिलाना चाहता, बल्कि परखना चाहता है कि आपकी सीमाएँ कितनी पक्की हैं। नियमों पर अडिग रहिए।', title_id = 'Ujian melanggar aturan ⚠️', body_id = 'Anda bilang ''jangan lakukan itu'', tetapi ia melakukannya sambil menatap mata Anda? Ia tidak ingin membuat Anda marah, ia ingin menguji seberapa kokoh batasan Anda. Tetaplah konsisten dengan aturan.', title_ja = 'ルール破りのテスト ⚠️', body_ja = '「やめてね」と言ったのに、目をじっと見ながらその行動をしますか？怒らせたいのではなく、あなたのルールがどれだけ揺るがないかを試したいのです。ルールはぶれずに守りましょう。', title_ko = '규칙 깨기 시험 ⚠️', body_ko = '''하지 마''라고 했는데 눈을 똑바로 보며 그 행동을 하나요? 엄마를 화나게 하려는 게 아니라 경계가 얼마나 단단한지 시험하는 거예요. 규칙을 일관되게 지켜 주세요.', title_nl = 'Regels op de proef stellen ⚠️', body_nl = 'Doet hij precies wat je hem verbood en kijkt hij je daarbij recht aan? Hij wil je niet boos maken, maar testen hoe stevig je grenzen zijn. Blijf consequent in je regels.', title_pl = 'Test łamania zasad ⚠️', body_pl = 'Mówisz „nie rób tego”, a on patrzy ci w oczy i robi to dalej? Nie chce cię rozzłościć, tylko sprawdzić, jak stabilne są twoje granice. Bądź konsekwentna w zasadach.', title_pt = 'O teste de quebrar regras ⚠️', body_pt = 'Diz-lhe "não faças isso" e ele faz, a olhar-lhe nos olhos? Não é para a irritar, quer testar a firmeza dos seus limites. Mantenha-se firme nas regras.', title_sv = 'Test av att bryta regler ⚠️', body_sv = 'Gör barnet det du sa ”gör inte så” om, medan hen tittar dig rakt i ögonen? Det handlar inte om att reta dig, barnet vill testa hur stabila dina gränser är. Var konsekvent med reglerna.', title_vi = 'Thử phá vỡ quy tắc ⚠️', body_vi = 'Mẹ bảo "Đừng làm thế" mà bé vẫn nhìn thẳng vào mắt mẹ và làm? Bé không cố chọc giận mẹ, mà muốn thử xem giới hạn của mẹ vững đến đâu. Hãy giữ vững các quy tắc.', title_zh = '打破规则的测试 ⚠️', body_zh = '你说了“别这样”，宝宝却盯着你的眼睛照做不误？这不是为了惹你生气，而是想测试你的界限有多稳定。在规则上保持坚定。' WHERE id = '1222929d-ba35-40ba-92f4-2c3b29988e2e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que la casa siga desordenada 🌪️', body_es = '¿Cansada de recoger los mismos juguetes cada día? ¡Hoy no recojas! El desorden de la casa no es el fin del mundo, pero el agotamiento psicológico de una madre sí es serio.', title_fr = 'Laissez le désordre 🌪️', body_fr = 'Fatiguée de ranger les mêmes jouets tous les jours ? Aujourd''hui, ne rangez pas ! Une maison en désordre n''est pas la fin du monde, mais l''effondrement psychologique d''une maman, c''est sérieux.', title_hi = 'घर बिखरा रहने दीजिए 🌪️', body_hi = 'रोज़ वही खिलौने समेटते-समेटते थक गईं? आज मत समेटिए! बिखरा घर दुनिया का अंत नहीं है, लेकिन माँ का मानसिक रूप से टूट जाना गंभीर बात है।', title_id = 'Biarkan rumah berantakan 🌪️', body_id = 'Lelah membereskan mainan yang sama setiap hari? Hari ini jangan dibereskan! Rumah berantakan bukan akhir dunia, tetapi ibu yang runtuh secara mental adalah hal yang serius.', title_ja = '家は散らかったままでいい 🌪️', body_ja = '毎日同じおもちゃを片づけるのに疲れましたか？今日は片づけなくていい！散らかった家は世界の終わりではありませんが、ママの心が折れてしまうのは深刻です。', title_ko = '집은 어질러져도 괜찮아요 🌪️', body_ko = '매일 같은 장난감을 치우느라 지쳤나요? 오늘은 치우지 마세요! 어질러진 집이 세상의 끝은 아니지만, 엄마의 마음이 무너지는 건 심각한 일이에요.', title_nl = 'Laat het huis maar rommelig 🌪️', body_nl = 'Ben je het zat om elke dag hetzelfde speelgoed op te ruimen? Laat het vandaag liggen! Een rommelig huis is niet het einde van de wereld, maar een moeder die mentaal instort is wel serieus.', title_pl = 'Niech w domu będzie bałagan 🌪️', body_pl = 'Masz dość codziennego zbierania tych samych zabawek? Dziś ich nie sprzątaj! Bałagan w domu to nie koniec świata, ale psychiczne załamanie mamy to poważna sprawa.', title_pt = 'Deixe a casa desarrumada 🌪️', body_pt = 'Cansada de arrumar os mesmos brinquedos todos os dias? Hoje não arrume! A casa desarrumada não é o fim do mundo, mas o esgotamento psicológico de uma mãe é sério.', title_sv = 'Låt hemmet vara stökigt 🌪️', body_sv = 'Är du trött på att plocka upp samma leksaker varje dag? Låt bli i dag! Ett stökigt hem är inte världens undergång, men en mammas psykiska kollaps är allvarlig.', title_vi = 'Cứ để nhà bừa 🌪️', body_vi = 'Mẹ mệt vì ngày nào cũng dọn những món đồ chơi giống nhau? Hôm nay đừng dọn! Nhà bừa không phải là tận thế, nhưng sự suy sụp tâm lý của người mẹ thì nghiêm trọng.', title_zh = '家里乱就乱吧 🌪️', body_zh = '每天收拾同样的玩具，收拾累了？今天就别收了！家里乱一点不是世界末日，可妈妈的心理崩溃是件大事。' WHERE id = '60d686a6-8001-479b-9d53-bcd85bcdffdb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Dale a Cuentos inteligentes un tema especial: el osito mágico al que le encanta recoger sus juguetes. ¡Quizá esta historia te ayude mañana con la limpieza!', body_fr = 'Donnez un thème spécial aux Contes intelligents : l''ourson magique qui adore ranger ses jouets. Peut-être que cette histoire vous aidera pour le rangement de demain !', body_hi = 'स्मार्ट कहानियों को एक खास विषय दीजिए: अपने खिलौने समेटना पसंद करने वाला जादुई टेडी। शायद यह कहानी कल की सफ़ाई में आपकी मदद कर दे!', body_id = 'Beri Dongeng Pintar tema khusus: beruang ajaib yang suka membereskan mainannya. Siapa tahu cerita ini membantu Anda saat bersih-bersih besok!', body_ja = '「スマートおはなし」に特別なテーマをあげましょう：おもちゃの片づけが大好きな魔法のくまさん。このお話が、明日のお片づけを助けてくれるかもしれません！', body_ko = '스마트 동화에 특별한 주제를 줘 보세요: 장난감 정리를 좋아하는 마법 곰돌이. 어쩌면 이 이야기가 내일 청소에 도움이 될지도 몰라요!', body_nl = 'Geef Slimme sprookjes een speciaal thema: het magische beertje dat dol is op speelgoed opruimen. Misschien helpt dit verhaal je morgen wel bij het opruimen!', body_pl = 'Daj Mądrym bajkom wyjątkowy temat: magiczny miś, który uwielbia sprzątać zabawki. Może ta historia pomoże ci jutro przy sprzątaniu!', body_pt = 'Dê um tema especial às Histórias Inteligentes: o ursinho mágico que adora arrumar os brinquedos. Talvez esta história a ajude nas arrumações de amanhã!', body_sv = 'Ge Smarta sagor ett särskilt tema: den magiska nallen som älskar att plocka undan sina leksaker. Kanske hjälper berättelsen dig med morgondagens städning!', body_vi = 'Hãy cho Truyện cổ tích thông minh một chủ đề đặc biệt: chú gấu phép thuật thích dọn dẹp đồ chơi. Biết đâu câu chuyện này sẽ giúp mẹ trong buổi dọn dẹp ngày mai!', body_zh = '给智能故事一个特别的主题：《爱收拾玩具的魔法小熊》。说不定这个故事明天打扫时能帮上你的忙！' WHERE id = 'e7bfaacc-c0cc-4b36-8687-477371b3bc3d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las rutinas de papá 👨‍🍼', body_es = 'Los niños tienen rutinas especiales con su padre. Esta noche deja la hora de acostarse a las normas divertidas de papá y tómate el té en silencio fuera de la habitación.', title_fr = 'Les rituels de papa 👨‍🍼', body_fr = 'Les enfants ont des rituels bien à eux avec leur papa. Ce soir, confiez le coucher aux règles rigolotes de papa et buvez votre thé au calme, hors de la chambre.', title_hi = 'पापा के अपने तरीके 👨‍🍼', body_hi = 'बच्चों के अपने पापा के साथ खास रूटीन होते हैं। आज शाम सुलाने का काम पापा के मज़ेदार नियमों को सौंप दीजिए और कमरे के बाहर खामोशी से अपनी चाय पीजिए।', title_id = 'Pola andalan Ayah 👨‍🍼', body_id = 'Anak-anak punya rutinitas khusus bersama ayahnya. Serahkan acara menidurkan malam ini pada aturan-aturan lucu Ayah, dan minumlah teh dengan tenang di luar kamar.', title_ja = 'パパのお決まりパターン 👨‍🍼', body_ja = '子どもはパパと特別なルーティンを持っているもの。今夜の寝かしつけはパパのおもしろいルールにお任せして、あなたは部屋の外で静かにお茶を飲みましょう。', title_ko = '아빠만의 방식 👨‍🍼', body_ko = '아이들은 아빠와 특별한 루틴을 갖곤 해요. 오늘 저녁 재우기는 아빠의 웃긴 규칙에 맡기고, 엄마는 방 밖에서 조용히 차를 드세요.', title_nl = 'Papa''s vaste trucjes 👨‍🍼', body_nl = 'Kinderen hebben vaak hun eigen rituelen met papa. Laat het naar bed brengen vanavond over aan papa''s grappige regels en drink buiten de kamer rustig je thee.', title_pl = 'Schematy taty 👨‍🍼', body_pl = 'Dzieci mają z tatą swoje wyjątkowe rytuały. Dziś wieczorem powierz usypianie zabawnym zasadom taty, a ty w ciszy wypij herbatę poza pokojem.', title_pt = 'As rotinas do pai 👨‍🍼', body_pt = 'As crianças têm rotinas especiais com o pai. Esta noite, entregue o ritual de deitar às regras cómicas do pai e beba o seu chá em silêncio, fora do quarto.', title_sv = 'Pappas mallar 👨‍🍼', body_sv = 'Barn har egna rutiner med sina pappor. Lämna över kvällens nattning åt pappas roliga regler och drick ditt te i tystnad utanför rummet.', title_vi = 'Những "mẫu" riêng của bố 👨‍🍼', body_vi = 'Trẻ thường có những nếp sinh hoạt riêng với bố. Tối nay hãy giao việc ru ngủ cho những quy tắc hài hước của bố và yên lặng uống trà bên ngoài phòng.', title_zh = '爸爸的独门套路 👨‍🍼', body_zh = '孩子和爸爸之间总有专属的小习惯。把今晚的哄睡交给爸爸那些搞笑的规矩，你到房间外安安静静地喝杯茶。' WHERE id = '895f4348-4fb2-4124-9532-acf7d07409f6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Agrupa bien los colores diciendo «esto es rojo, esto es azul»? ¡Un gran avance en su desarrollo cognitivo! Marca con orgullo este detalle en el Seguimiento del desarrollo.', body_fr = 'Il classe correctement les couleurs en disant « C''est rouge, c''est bleu » ? Un grand progrès cognitif ! Notez fièrement ce détail dans le Suivi de développement.', body_hi = '''यह लाल है, यह नीला है'' कहकर रंगों को सही से छाँटता है? संज्ञानात्मक विकास में यह बड़ी प्रगति है! ग्रोथ ट्रैकर में यह बात गर्व से दर्ज कीजिए।', body_id = 'Ia mengelompokkan warna dengan benar sambil berkata ''Ini merah, ini biru''? Kemajuan besar dalam perkembangan kognitifnya! Tandai detail ini dengan bangga di Pelacak Perkembangan.', body_ja = '「これは赤、これは青」と言いながら、色を正しく分けていますか？認知発達の大きな前進です！この成長を「発達トラッカー」に誇らしく記録しましょう。', body_ko = '''이건 빨간색, 이건 파란색'' 하며 색깔을 바르게 나누나요? 인지 발달의 큰 진전이에요! 성장 기록에 이 순간을 뿌듯하게 표시해 두세요.', body_nl = 'Sorteert hij kleuren goed met ''Dit is rood, dit is blauw''? Een grote vooruitgang in zijn denkontwikkeling! Markeer dit detail trots in de Groeitracker.', body_pl = 'Mówi „to jest czerwone, to jest niebieskie” i poprawnie grupuje kolory? To wielki postęp w rozwoju poznawczym! Z dumą zaznacz ten szczegół w Śledzeniu rozwoju.', body_pt = 'Agrupa bem as cores, dizendo "isto é vermelho, isto é azul"? É um grande avanço no desenvolvimento cognitivo! Marque este detalhe com orgulho no Registo de Desenvolvimento.', body_sv = 'Sorterar barnet färgerna rätt och säger ”Den här är röd, den här är blå”? Ett stort framsteg i den kognitiva utvecklingen! Markera stolt den här detaljen i Utvecklingsspåraren.', body_vi = 'Bé phân nhóm màu sắc đúng, nói "Cái này màu đỏ, cái này màu xanh"? Một bước tiến lớn trong phát triển nhận thức! Hãy tự hào đánh dấu chi tiết này trong Theo dõi phát triển.', body_zh = '说着“这是红的，这是蓝的”，把颜色分得清清楚楚？认知发展的一大进步！骄傲地在发育追踪里标记下这个细节吧。' WHERE id = 'aca7ae85-535e-4175-ab27-d1ca390e78cb' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juntos en la cocina 🧑‍🍳', body_es = '¿Quiere hacer cosas contigo? Elige en Recetas saludables un bizcocho fácil y deja que te ayude a echar la harina o el agua. Aunque se manche todo, la diversión está garantizada.', title_fr = 'Ensemble en cuisine 🧑‍🍳', body_fr = 'Il veut faire les choses avec vous ? Choisissez un gâteau facile dans les Recettes saines et laissez-le vous aider à verser la farine ou l''eau. Même si ça salit, le plaisir est garanti.', title_hi = 'साथ मिलकर रसोई में 🧑‍🍳', body_hi = 'आपके साथ मिलकर काम करना चाहता है? सेहतमंद रेसिपी से कोई आसान केक चुनिए और आटा या पानी डालने में उसे मदद करने दीजिए। गंदगी होगी, लेकिन मज़े की गारंटी है।', title_id = 'Bersama di dapur 🧑‍🍳', body_id = 'Ia ingin ikut bekerja bersama Anda? Pilih resep kue yang mudah dari Resep Sehat dan biarkan ia membantu menuang tepung atau air. Meski jadi kotor, keseruannya dijamin.', title_ja = '一緒にキッチンで 🧑‍🍳', body_ja = '一緒に作業したがりますか？「ヘルシーレシピ」から簡単なケーキを選んで、小麦粉や水を注ぐのを手伝ってもらいましょう。汚れても、楽しさは保証つきです。', title_ko = '주방에서 함께 🧑‍🍳', body_ko = '엄마와 함께 일하고 싶어 하나요? 건강한 레시피에서 쉬운 머핀을 골라 밀가루나 물을 붓는 걸 돕게 해 주세요. 더러워져도 재미는 보장돼요.', title_nl = 'Samen in de keuken 🧑‍🍳', body_nl = 'Wil hij samen met je aan de slag? Kies een makkelijke cake uit Gezonde recepten en laat hem helpen met bloem of water schenken. Het wordt vies, maar plezier gegarandeerd.', title_pl = 'Razem w kuchni 🧑‍🍳', body_pl = 'Chce z tobą pracować? Wybierz ze Zdrowych przepisów łatwe ciasto i pozwól mu pomóc przy sypaniu mąki czy nalewaniu wody. Nawet jeśli się ubrudzi, zabawa gwarantowana.', title_pt = 'Juntos na cozinha 🧑‍🍳', body_pt = 'Quer trabalhar consigo? Escolha nas Receitas Saudáveis um bolo fácil e deixe-o ajudar a deitar a farinha ou a água. Pode ficar tudo sujo, mas a diversão é garantida.', title_sv = 'Tillsammans i köket 🧑‍🍳', body_sv = 'Vill barnet göra saker tillsammans med dig? Välj en enkel muffins från Hälsosamma recept och låt barnet hjälpa till när du häller mjöl eller vatten. Det blir kladdigt, men roligt är garanterat.', title_vi = 'Cùng nhau vào bếp 🧑‍🍳', body_vi = 'Bé muốn cùng mẹ làm việc? Hãy chọn một món bánh nướng dễ làm từ Công thức lành mạnh và để bé giúp mẹ đổ bột hoặc rót nước. Dù có bừa bộn, niềm vui là điều chắc chắn.', title_zh = '一起下厨房 🧑‍🍳', body_zh = '想和你一起干活？从健康食谱里选一款简单的蛋糕，让宝宝帮你倒面粉或倒水吧。就算弄脏了，快乐也是有保证的。' WHERE id = 'b6ee83b4-0d5f-4791-8483-ed7d1d3aa649' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los decibelios de la noche 🤫', body_es = '¿Los ruidos de la calle no le dejan dormir profundamente? Analiza la habitación con el Medidor de sonido.', title_fr = 'Les décibels de la nuit 🤫', body_fr = 'Les bruits de la rue l''empêchent de plonger dans un sommeil profond ? Analysez la chambre avec le Sonomètre.', title_hi = 'रात का डेसिबल 🤫', body_hi = 'सड़क से आती आवाज़ें उसे गहरी नींद में जाने नहीं देतीं? साउंड मीटर से कमरे की आवाज़ों की जाँच कीजिए।', title_id = 'Desibel malam hari 🤫', body_id = 'Suara dari jalan menghalanginya tidur lelap? Analisis kamar dengan Pengukur Suara.', title_ja = '夜のデシベル 🤫', body_ja = '外からの音で、ぐっすり眠れないでいますか？「サウンドメーター」で部屋を分析しましょう。', title_ko = '밤의 데시벨 🤫', body_ko = '길에서 들어오는 소리가 깊은 잠을 방해하나요? 소음 측정기로 방을 분석해 보세요.', title_nl = 'Decibels in de nacht 🤫', body_nl = 'Houden geluiden van de straat hem uit een diepe slaap? Analyseer de kamer met de Geluidsmeter.', title_pl = 'Decybele nocy 🤫', body_pl = 'Odgłosy z ulicy nie pozwalają mu zapaść w głęboki sen? Przeanalizuj pokój Miernikiem dźwięku.', title_pt = 'Os decibéis da noite 🤫', body_pt = 'Os sons da rua impedem-no de cair num sono profundo? Analise o quarto com o Medidor de Som.', title_sv = 'Nattens decibel 🤫', body_sv = 'Hindrar ljuden från gatan barnet från att somna djupt? Analysera rummet med Ljudmätaren.', title_vi = 'Decibel của đêm 🤫', body_vi = 'Tiếng ồn ngoài đường cản trở bé ngủ sâu? Hãy phân tích căn phòng bằng Đo âm thanh.', title_zh = '夜晚的分贝 🤫', body_zh = '街上的声音让宝宝难以进入深睡？用分贝仪分析一下房间的环境吧。' WHERE id = '2009290a-99c2-4bf0-a2b6-174daa69d49d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Artista en acción 🖍️', body_es = 'Las paredes y las puertas a veces se convierten en su pizarra. En lugar de enfadarte, busca un cartón grande, extiéndelo en el suelo y dile: «Esto es tuyo». Reconduce bien su voluntad.', title_fr = 'L''artiste au travail 🖍️', body_fr = 'Les murs et les portes deviennent parfois sa toile. Au lieu de vous énerver, étalez un grand carton par terre et dites-lui « Ici, c''est à toi ». Orientez sa volonté dans la bonne direction.', title_hi = 'कलाकार काम पर 🖍️', body_hi = 'दीवारें और दरवाज़े कभी-कभी उसका कैनवस बन जाते हैं। गुस्सा करने के बजाय एक बड़ा कार्डबोर्ड ढूँढकर ज़मीन पर बिछाइए और कहिए ''यह तुम्हारा है''। उसकी इच्छा को सही दिशा दीजिए।', title_id = 'Seniman sedang bekerja 🖍️', body_id = 'Dinding dan pintu kadang berubah jadi kanvasnya. Daripada kesal, cari karton besar, bentangkan di lantai, dan katakan ''Ini punyamu''. Arahkan kemauannya ke tempat yang tepat.', title_ja = 'アーティスト、制作中 🖍️', body_ja = '壁やドアがときどきお子さんのキャンバスに？イライラするかわりに、大きな段ボールを床に広げて「ここはあなたの場所だよ」と伝えましょう。意欲を正しい方向へ導いて。', title_ko = '꼬마 화가 작업 중 🖍️', body_ko = '벽과 문이 가끔 아이의 캔버스가 되나요? 화내는 대신 큰 판지를 바닥에 깔고 ''여기는 네 자리야''라고 말해 주세요. 아이의 의지를 올바른 방향으로 이끌어 주세요.', title_nl = 'Kunstenaar aan het werk 🖍️', body_nl = 'Muren en deuren worden soms zijn schoolbord. Word niet boos, maar leg een groot stuk karton op de grond en zeg: ''Dit is van jou.'' Stuur zijn wil de goede kant op.', title_pl = 'Artysta przy pracy 🖍️', body_pl = 'Ściany i drzwi czasem zamieniają się w jego płótno. Zamiast się złościć, znajdź duży karton, rozłóż go na podłodze i powiedz: „To jest twoje”. Skieruj jego wolę we właściwą stronę.', title_pt = 'Artista ao trabalho 🖍️', body_pt = 'As paredes e as portas às vezes viram a tela dele. Em vez de se irritar, arranje um cartão grande, estenda-o no chão e diga: "Isto é teu." Oriente bem a vontade dele.', title_sv = 'Konstnären i tjänst 🖍️', body_sv = 'Väggar och dörrar blir ibland barnets duk. I stället för att bli arg, hitta en stor kartong, bred ut den på golvet och säg ”här är din plats”. Styr viljan åt rätt håll.', title_vi = 'Nghệ sĩ đang làm việc 🖍️', body_vi = 'Tường và cửa đôi khi biến thành tấm bảng của bé. Thay vì bực mình, hãy tìm một tấm bìa các-tông lớn trải xuống sàn và nói "Chỗ này là của con". Hãy định hướng ý chí của bé đúng cách.', title_zh = '小画家上班了 🖍️', body_zh = '墙和门有时会变成宝宝的画板。与其生气，不如找一大张纸板铺在地上，告诉宝宝“这里是你的”。把宝宝的意愿引到正确的方向。' WHERE id = '2a0f6e31-8cdc-436b-8432-73cf4dad5b5c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lluvia de preguntas 🤖', body_es = '¿No se acaban tus dudas sobre su conducta al acercarse a los 3 años? Anacan AI es tu pediatra y psicólogo digital despierto 24/7. Escribe y recibe la respuesta al momento.', title_fr = 'Avalanche de questions 🤖', body_fr = 'Vos questions sur son comportement à l''approche des 3 ans n''en finissent pas ? Anacan AI est votre pédiatre et psychologue numérique, disponible 24h/24 et 7j/7. Écrivez et obtenez une réponse immédiate.', title_hi = 'सवालों की बाढ़ 🤖', body_hi = '3 साल के करीब बच्चे के व्यवहार को लेकर आपके सवाल खत्म ही नहीं होते? Anacan AI आपके लिए 24/7 जागने वाला डिजिटल बाल रोग विशेषज्ञ और मनोवैज्ञानिक है। लिखिए और तुरंत जवाब पाइए।', title_id = 'Banjir pertanyaan 🤖', body_id = 'Pertanyaan Anda tentang perilaku anak menjelang usia 3 tahun tak ada habisnya? Anacan AI adalah dokter anak dan psikolog digital yang siaga 24/7 untuk Anda. Tulis dan langsung dapatkan jawaban.', title_ja = '質問のあらし 🤖', body_ja = '3歳が近づくお子さんの行動について、質問がつきませんか？Anacan AIは、24時間365日起きているデジタルの小児科医であり心理カウンセラーです。書きこめば、すぐに答えがもらえます。', title_ko = '질문 폭탄 🤖', body_ko = '세 돌을 앞둔 아이의 행동에 대한 질문이 끝이 없나요? Anacan AI는 24시간 깨어 있는 디지털 소아과 의사이자 심리 상담사예요. 물어보고 바로 답을 받으세요.', title_nl = 'Een stroom van vragen 🤖', body_nl = 'Houden je vragen over zijn gedrag richting 3 jaar niet op? Anacan AI is jouw digitale kinderarts en psycholoog die 24/7 wakker is. Typ je vraag en krijg meteen antwoord.', title_pl = 'Lawina pytań 🤖', body_pl = 'Pytania o zachowanie dziecka zbliżającego się do 3. roku życia nie mają końca? Anacan AI to twój cyfrowy pediatra i psycholog dostępny 24/7. Napisz i od razu otrzymaj odpowiedź.', title_pt = 'Avalanche de perguntas 🤖', body_pt = 'As suas perguntas sobre o comportamento da criança perto dos 3 anos não acabam? O Anacan AI é o seu pediatra e psicólogo digital, acordado 24/7. Escreva e receba logo uma resposta.', title_sv = 'En flod av frågor 🤖', body_sv = 'Tar dina frågor om barnets beteende inför 3-årsåldern aldrig slut? Anacan AI är din digitala barnläkare och psykolog, vaken dygnet runt. Skriv och få svar direkt.', title_vi = 'Cơn mưa câu hỏi 🤖', body_vi = 'Những câu hỏi về hành vi của bé gần 3 tuổi cứ mãi không dứt? Anacan AI là bác sĩ nhi khoa và chuyên gia tâm lý kỹ thuật số luôn sẵn sàng 24/7 cho mẹ. Hãy hỏi và nhận câu trả lời ngay.', title_zh = '问题如潮 🤖', body_zh = '对快3岁孩子的行为总有问不完的问题？Anacan AI就是为你7×24小时在线的数字儿科医生和心理师。写下来，马上得到回答。' WHERE id = '7750d70c-df5b-48b0-9b2f-522c15391059' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te sientes muy sola e incomprendida? Es un sentimiento de lo más natural. Escribe con sinceridad cómo te sientes en el Diario de ánimo.', body_fr = 'Vous vous sentez très seule et incomprise ? C''est le sentiment le plus naturel qui soit. Écrivez sincèrement ce que vous ressentez dans le Journal d''humeur.', body_hi = 'बहुत अकेला और नासमझा महसूस कर रही हैं? यह सबसे स्वाभाविक एहसास है। मूड डायरी में अपनी भावनाएँ सच्चे मन से लिखिए।', body_id = 'Merasa sangat sendiri dan tidak dipahami? Itu perasaan yang paling wajar. Tuliskan perasaan Anda dengan jujur di Buku Harian Suasana Hati.', body_ja = 'とても孤独で、わかってもらえないと感じていますか？それはごく自然な気持ちです。「気分日記」に素直な気持ちを書きましょう。', body_ko = '너무 외롭고 아무도 이해해 주지 않는 것 같나요? 아주 자연스러운 감정이에요. 기분 일기에 솔직한 마음을 적어 보세요.', body_nl = 'Voel je je heel alleen en onbegrepen? Dat is een heel natuurlijk gevoel. Schrijf je gevoelens eerlijk op in je Stemmingsdagboek.', body_pl = 'Czujesz się bardzo samotna i niezrozumiana? To najbardziej naturalne uczucie. Zapisz szczerze swoje uczucia w Dzienniku nastroju.', body_pt = 'Sente-se muito sozinha e incompreendida? É o sentimento mais natural. Escreva com sinceridade o que sente no Diário de Humor.', body_sv = 'Känner du dig väldigt ensam och missförstådd? Det är den mest naturliga känslan. Skriv ärligt ner dina känslor i Humördagboken.', body_vi = 'Mẹ cảm thấy thật cô đơn và không ai hiểu mình? Đó là cảm giác rất tự nhiên. Hãy chân thành viết cảm xúc của mình vào Nhật ký tâm trạng.', body_zh = '觉得特别孤单、没人理解？这是最自然的感受。把心里话真诚地写进心情日记吧。' WHERE id = '2859fc00-366b-44b7-ba24-815b9b659125' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubriendo su «yo» 👑', body_es = '«¡Soy yo!», «¡Es mío!»: no deja de decirlo. Es el momento más marcado de la etapa egocéntrica. Respeta su individualidad, es una fase del desarrollo.', title_fr = 'Il découvre son « moi » 👑', body_fr = '« C''est moi ! », « C''est à moi ! » ne quittent plus ses lèvres. C''est le pic de la période égocentrique. Accueillez sa personnalité avec respect, c''est une étape du développement.', title_hi = 'अपने ''मैं'' की खोज 👑', body_hi = '''मैं हूँ!'', ''मेरा है!'' ये शब्द उसकी ज़ुबान से हटते ही नहीं। यह ''मैं ही मैं'' वाले दौर का सबसे चरम समय है। उसकी इस अलग पहचान को सम्मान से स्वीकार कीजिए, यह विकास का एक पड़ाव है।', title_id = 'Menemukan ''Aku''-nya 👑', body_id = 'Kata ''Aku!'' dan ''Punyaku!'' tak pernah lepas dari mulutnya. Ini puncak masa egosentris. Sambut jati dirinya dengan hormat, ini adalah tahap perkembangan.', title_ja = '「自分」を発見中 👑', body_ja = '「ぼくの！」「わたしの！」が口ぐせになっていますか？自分中心の時期のまっただ中です。この個性を尊重してあげて、これも発達の一段階です。', title_ko = '''나''를 발견해요 👑', body_ko = '''나야!'', ''내 거야!''를 입에 달고 사나요? 자기중심성이 가장 두드러지는 시기예요. 이 개성을 존중해 주세요. 자연스러운 발달 단계예요.', title_nl = 'Hij ontdekt zijn ''ik'' 👑', body_nl = '''Ik!'' en ''Van mij!'' zijn niet van zijn lippen te krijgen. Dit is het hoogtepunt van de egocentrische fase. Ga respectvol om met zijn eigenheid, het is een ontwikkelingsfase.', title_pl = 'Odkrywa swoje „ja” 👑', body_pl = '„To ja!”, „To moje!” nie schodzą mu z ust. To szczyt okresu egocentryzmu. Przyjmij jego indywidualność z szacunkiem, to etap rozwoju.', title_pt = 'A descobrir o seu "eu" 👑', body_pt = '"Sou eu!", "É meu!" não lhe saem da boca. É o auge da fase egocêntrica. Respeite esta individualidade: é uma etapa do desenvolvimento.', title_sv = 'Barnet upptäcker sitt jag 👑', body_sv = '”Det är jag!”, ”Den är min!” hörs hela tiden. Det är toppen av den egocentriska perioden. Möt barnets individualitet med respekt, det är ett utvecklingssteg.', title_vi = 'Khám phá "cái tôi" 👑', body_vi = '"Của con!", "Con mà!" lúc nào cũng nói. Đây là đỉnh điểm của giai đoạn vị kỷ. Hãy tôn trọng cá tính này của bé, đó là một giai đoạn phát triển.', title_zh = '发现“自我” 👑', body_zh = '“是我！”“是我的！”总挂在嘴边。这是自我中心阶段最明显的时候。尊重宝宝的个性，这是一个成长阶段。' WHERE id = '4f59cf22-ccfa-43b9-8a30-62365a911312' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El tiempo cambia ⛅', body_es = '¿Quieres salir de paseo pero el tiempo de fuera engaña? Entra en Tiempo y ropa y elige el conjunto adecuado para protegerle sin que sude.', title_fr = 'Le temps est changeant ⛅', body_fr = 'Vous voulez sortir vous promener, mais le temps est trompeur ? Ouvrez Météo et tenue et choisissez la tenue idéale qui le protégera sans le faire transpirer.', title_hi = 'मौसम बदलता रहता है ⛅', body_hi = 'सैर पर जाना चाहती हैं, लेकिन बाहर का मौसम धोखा दे सकता है? मौसम और कपड़े टूल खोलकर ऐसे सबसे सही कपड़े चुनिए जिनमें उसे पसीना न आए, लेकिन वह सुरक्षित रहे।', title_id = 'Cuaca tak menentu ⛅', body_id = 'Ingin jalan-jalan, tetapi cuaca di luar menipu? Buka alat Cuaca dan Pakaian dan tentukan setelan paling tepat yang melindunginya tanpa membuatnya berkeringat.', title_ja = '天気は変わりやすい ⛅', body_ja = 'お散歩に行きたいけれど、外の天気があてにならない？「天気と服装」を開いて、汗をかかせず、しっかり守ってくれるいちばんいいコーディネートを決めましょう。', title_ko = '날씨가 변덕스러워요 ⛅', body_ko = '산책하고 싶은데 바깥 날씨가 헷갈리나요? 날씨와 옷차림 도구로 땀나지 않으면서도 아이를 지켜 줄 가장 알맞은 옷차림을 정하세요.', title_nl = 'Het weer is wisselvallig ⛅', body_nl = 'Wil je gaan wandelen, maar is het weer buiten misleidend? Open Weer en kleding en kies de outfit die hem beschermt zonder dat hij gaat zweten.', title_pl = 'Pogoda jest zmienna ⛅', body_pl = 'Chcesz wyjść na spacer, ale pogoda na zewnątrz jest zwodnicza? Wejdź do narzędzia Pogoda i ubiór i dobierz zestaw, w którym się nie spoci, a będzie dobrze chroniony.', title_pt = 'O tempo está instável ⛅', body_pt = 'Quer sair para passear, mas o tempo lá fora engana? Abra o Tempo e Roupa e escolha a combinação certa, que o proteja sem o fazer transpirar.', title_sv = 'Vädret är ombytligt ⛅', body_sv = 'Vill du gå ut på promenad men vädret är bedrägligt? Gå in i verktyget Väder och kläder och välj den klädsel som skyddar barnet utan att hen blir svettig.', title_vi = 'Thời tiết thất thường ⛅', body_vi = 'Mẹ muốn đi dạo nhưng thời tiết bên ngoài dễ đánh lừa? Hãy vào công cụ Thời tiết và trang phục để chọn cách phối đồ phù hợp nhất, vừa bảo vệ bé vừa không làm bé đổ mồ hôi.', title_zh = '天气多变 ⛅', body_zh = '想出门散步，可外面的天气很有迷惑性？打开天气穿衣工具，找到既不让宝宝出汗、又能保护好宝宝的最合适搭配。' WHERE id = 'eddd6a67-3ce9-4446-ba23-dba7c167dca2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Orgullo de equipo 🥂', body_es = 'Habéis superado una semana difícil. Sentaos frente a frente con tu pareja y motivaos diciendo: «De verdad estamos criando muy bien a este niño».', title_fr = 'Fierté d''équipe 🥂', body_fr = 'Vous avez laissé derrière vous une semaine difficile. Asseyez-vous face à votre partenaire et motivez-vous : « On élève vraiment bien cet enfant. »', title_hi = 'टीम का गर्व 🥂', body_hi = 'एक मुश्किल हफ़्ता पीछे छोड़ दिया। अपने पार्टनर के आमने-सामने बैठिए और ''हम सच में इस बच्चे की परवरिश अच्छे से कर रहे हैं'' कहकर एक-दूसरे का हौसला बढ़ाइए।', title_id = 'Bangga sebagai tim 🥂', body_id = 'Satu minggu berat sudah terlewati. Duduklah berhadapan dengan pasangan dan saling menyemangati dengan berkata ''Kita benar-benar membesarkan anak ini dengan baik''.', title_ja = 'チームの誇り 🥂', body_ja = '大変な一週間を乗りこえました。パートナーと向かい合って座り、「わたしたち、この子を本当によく育ててるね」とお互いを励まし合いましょう。', title_ko = '팀의 자부심 🥂', body_ko = '힘든 한 주를 또 이겨 냈어요. 배우자와 마주 앉아 ''우리 정말 아이를 잘 키우고 있어'' 하며 서로를 북돋아 주세요.', title_nl = 'Trots op jullie team 🥂', body_nl = 'Jullie hebben een zware week achter de rug. Ga tegenover je partner zitten en motiveer elkaar met ''We voeden dit kind echt goed op''.', title_pl = 'Duma drużyny 🥂', body_pl = 'Kolejny trudny tydzień za wami. Usiądźcie z partnerem naprzeciwko siebie i zmotywujcie się nawzajem słowami: „Naprawdę dobrze wychowujemy to dziecko”.', title_pt = 'Orgulho de equipa 🥂', body_pt = 'Deixaram para trás uma semana difícil. Sente-se frente a frente com o seu companheiro e motivem-se um ao outro: "Estamos mesmo a criar bem esta criança."', title_sv = 'Stolthet som team 🥂', body_sv = 'Ni har en tuff vecka bakom er. Sätt er mitt emot varandra och peppa varandra med ”vi uppfostrar verkligen det här barnet bra”.', title_vi = 'Niềm tự hào của đội 🥂', body_vi = 'Hai người đã vượt qua một tuần khó khăn. Hãy ngồi đối diện với chồng và động viên nhau: "Chúng mình thật sự đang nuôi dạy con rất tốt".', title_zh = '团队的骄傲 🥂', body_zh = '你们又熬过了艰难的一周。和另一半面对面坐下，说一句“我们真的把这个孩子带得很好”，互相打打气吧。' WHERE id = '009a8d5c-9bba-4789-a6ee-e59d4c647832' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuenta cuentos con frases 🗣️', body_es = '¿Mira un libro de dibujos y se inventa un cuento con frases propias? ¡Su imaginación y su lenguaje están en pleno auge a la vez! Escúchale con atención y aplaúdele.', title_fr = 'Il raconte des histoires en phrases 🗣️', body_fr = 'Il regarde un livre d''images et invente une histoire avec ses propres phrases ? Imagination et langage s''envolent en même temps ! Écoutez-le attentivement et applaudissez-le.', title_hi = 'वाक्यों में कहानी सुनाता है 🗣️', body_hi = 'तस्वीरों वाली किताब देखकर खुद वाक्य गढ़कर कहानी बनाता है? कल्पना और बोली, दोनों एक साथ शिखर पर हैं! उसे ध्यान से सुनिए और तालियाँ बजाइए।', title_id = 'Bercerita dengan kalimat 🗣️', body_id = 'Ia melihat buku bergambar dan mengarang dongeng dengan kalimat buatannya sendiri? Imajinasi dan kemampuan bicaranya melonjak bersamaan! Dengarkan ia dengan saksama dan beri tepuk tangan.', title_ja = '文でお話をする 🗣️', body_ja = '絵本を見ながら、自分で文を考えてお話を作っていますか？想像力と言葉が同時に最高潮です！しっかり聞いて、拍手してあげましょう。', title_ko = '문장으로 동화를 들려줘요 🗣️', body_ko = '그림책을 보며 스스로 문장을 지어 이야기를 만들어 내나요? 상상력과 말하기가 동시에 절정이에요! 귀 기울여 들어 주고 박수를 보내 주세요.', title_nl = 'Hij vertelt sprookjes in zinnen 🗣️', body_nl = 'Verzint hij bij een prentenboek zelf zinnen en een heel verhaal? Fantasie en spraak bloeien tegelijk op! Luister aandachtig en applaudisseer voor hem.', title_pl = 'Opowiada bajki zdaniami 🗣️', body_pl = 'Patrzy na książeczkę z obrazkami i wymyśla bajkę z własnych zdań? Wyobraźnia i mowa jednocześnie rozkwitają! Słuchaj go uważnie i oklaskuj.', title_pt = 'Conta histórias com frases 🗣️', body_pt = 'Olha para um livro de imagens e inventa histórias com frases suas? A imaginação e a fala estão no auge ao mesmo tempo! Ouça-o com atenção e aplauda.', title_sv = 'Barnet berättar sagor i meningar 🗣️', body_sv = 'Tittar barnet i en bilderbok och hittar på en saga med egna meningar? Fantasin och talet är på topp samtidigt! Lyssna noga och applådera.', title_vi = 'Bé kể chuyện bằng những câu nói 🗣️', body_vi = 'Bé nhìn sách tranh và tự nghĩ ra câu để kể chuyện? Trí tưởng tượng và khả năng nói cùng lúc phát triển vượt bậc! Hãy chăm chú lắng nghe và vỗ tay khen bé.', title_zh = '用句子讲故事 🗣️', body_zh = '看着图画书，自己编句子讲故事？想象力和语言同时到了高峰！认真听宝宝讲，再为宝宝鼓掌吧。' WHERE id = 'd0adf273-d83c-415a-88b8-6fa5f74c5f51' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solidaridad entre madres 💬', body_es = '¿Dejar el pañal (potty training) te ha hundido el ánimo? Entra ya en la Comunidad Anacan. Las historias de éxitos y fracasos de otras madres te darán fuerza.', title_fr = 'La solidarité entre mamans 💬', body_fr = 'L''apprentissage du pot vous déprime ? Rejoignez tout de suite la Communauté Anacan. Les histoires de réussites et d''échecs des autres mamans vous donneront de la force.', title_hi = 'माँओं की एकजुटता 💬', body_hi = 'पॉटी ट्रेनिंग (potty training) ने आपको उदास कर दिया है? तुरंत Anacan कम्युनिटी में जाइए। वहाँ दूसरी माँओं की कामयाबी और नाकामी की कहानियाँ आपको ताकत देंगी।', title_id = 'Solidaritas para ibu 💬', body_id = 'Latihan pispot (potty training) membuat Anda terpuruk? Segera masuk ke Komunitas Anacan. Kisah berhasil dan gagal dari ibu-ibu lain di sana akan memberi Anda kekuatan.', title_ja = 'ママどうしの支え合い 💬', body_ja = 'トイレトレーニングで気持ちが沈んでいますか？すぐにAnacanコミュニティに参加しましょう。ほかのママたちの成功や失敗の話が、力をくれます。', title_ko = '엄마들의 연대 💬', body_ko = '배변 훈련 때문에 우울해졌나요? 바로 Anacan 커뮤니티에 들어와 보세요. 다른 엄마들의 성공과 실패 이야기가 힘이 될 거예요.', title_nl = 'Moeders steunen elkaar 💬', body_nl = 'Word je somber van de zindelijkheidstraining? Ga meteen naar de Anacan Community. De verhalen van andere moeders over wat lukte en wat niet, geven je kracht.', title_pl = 'Solidarność mam 💬', body_pl = 'Nauka korzystania z nocnika (potty training) wpędza cię w przygnębienie? Od razu wejdź do Społeczności Anacan. Historie sukcesów i porażek innych mam dodadzą ci sił.', title_pt = 'Solidariedade entre mães 💬', body_pt = 'O treino do bacio (potty training) deixou-a em baixo? Entre já na Comunidade Anacan. As histórias de sucessos e fracassos das outras mães vão dar-lhe força.', title_sv = 'Mammors samhörighet 💬', body_sv = 'Har pottträningen (potty training) gjort dig nedstämd? Gå direkt in i Anacan Community. Berättelserna om framgångar och misslyckanden från andra mammor där ger dig kraft.', title_vi = 'Sự đồng lòng của các mẹ 💬', body_vi = 'Tập ngồi bô (potty training) khiến mẹ suy sụp? Hãy vào ngay Cộng đồng Anacan. Những câu chuyện thành công và thất bại của các mẹ khác ở đó sẽ tiếp thêm sức mạnh cho mẹ.', title_zh = '妈妈们的团结 💬', body_zh = '如厕训练让你快抑郁了？马上进入Anacan社区。那里其他妈妈成功和失败的故事，会给你力量。' WHERE id = 'ff22b088-7f8b-4366-a32b-7bd8cd1aa92f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No tengas miedo a la oscuridad 🌙', body_es = '¿Le da miedo la oscuridad de la habitación? Pon una lucecita de noche junto a su cama, pero asegúrate de que la habitación esté lo bastante oscura para que se produzca melatonina.', title_fr = 'N''aie pas peur du noir 🌙', body_fr = 'Il a peur du noir dans sa chambre ? Mettez une petite veilleuse près de son lit, mais assurez-vous que la pièce reste assez sombre pour la sécrétion de mélatonine.', title_hi = 'अंधेरे से मत डरो 🌙', body_hi = 'कमरे के अंधेरे से डरता है? बिस्तर के पास एक छोटा नाइट लैंप रखिए, लेकिन पक्का कीजिए कि कमरा मेलाटोनिन बनने के लिए काफ़ी अंधेरा है।', title_id = 'Jangan takut gelap 🌙', body_id = 'Ia takut gelapnya kamar? Letakkan lampu tidur kecil di samping tempat tidurnya, tetapi pastikan kamar cukup gelap untuk produksi melatonin.', title_ja = '暗やみをこわがらないで 🌙', body_ja = '部屋の暗さをこわがりますか？ベッドのそばに小さなナイトライトを置きましょう。ただし、メラトニンが分泌されるよう、部屋が十分暗いことを確かめて。', title_ko = '어둠을 무서워하지 마 🌙', body_ko = '방의 어둠을 무서워하나요? 침대 옆에 작은 수면등을 두되, 멜라토닌이 분비될 만큼 방이 충분히 어두운지 확인하세요.', title_nl = 'Wees niet bang voor het donker 🌙', body_nl = 'Is hij bang voor het donker in zijn kamer? Zet een klein nachtlampje naast zijn bed, maar zorg dat de kamer donker genoeg is voor de aanmaak van melatonine.', title_pl = 'Nie bój się ciemności 🌙', body_pl = 'Boi się ciemności w pokoju? Postaw przy łóżku małą lampkę nocną, ale upewnij się, że w pokoju jest wystarczająco ciemno, by wydzielała się melatonina.', title_pt = 'Não ter medo do escuro 🌙', body_pt = 'Tem medo do escuro do quarto? Ponha uma pequena luz de presença ao lado da cama, mas confirme que o quarto fica escuro o suficiente para a produção de melatonina.', title_sv = 'Var inte rädd för mörkret 🌙', body_sv = 'Är barnet rädd för mörkret i rummet? Ställ en liten nattlampa vid sängen, men se till att rummet är tillräckligt mörkt för att melatoninet ska utsöndras.', title_vi = 'Đừng sợ bóng tối 🌙', body_vi = 'Bé sợ bóng tối trong phòng? Hãy đặt một chiếc đèn ngủ nhỏ cạnh giường, nhưng chắc chắn phòng vẫn đủ tối để tiết melatonin.', title_zh = '别怕黑 🌙', body_zh = '害怕房间的黑暗？在床边放一盏小夜灯，但要确保房间足够暗，好让褪黑素分泌。' WHERE id = '1c47434b-8f04-4342-a73a-e77c7a63eb48' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quiere elegir su ropa 👗', body_es = '¿Abre el armario y quiere combinar colores y prendas de estaciones que no pegan? Apoya su independencia, pero para no perder el control ofrécele solo 2 opciones.', title_fr = 'Il veut choisir ses vêtements lui-même 👗', body_fr = 'Il ouvre l''armoire et veut associer des couleurs et des saisons qui ne vont pas ensemble ? Soutenez son autonomie, mais pour garder le contrôle, proposez-lui simplement 2 choix.', title_hi = 'अपने कपड़े खुद चुनना चाहता है 👗', body_hi = 'अलमारी खोलकर बेमेल रंग और मौसम के कपड़े मिलाना चाहता है? उसकी आत्मनिर्भरता का साथ दीजिए, लेकिन नियंत्रण अपने हाथ में रखने के लिए उसे बस 2 विकल्प दीजिए।', title_id = 'Ingin memilih bajunya sendiri 👗', body_id = 'Ia membuka lemari dan ingin memadukan warna dan musim yang tidak serasi? Dukung kemandiriannya, tetapi agar tetap terkendali, beri ia 2 pilihan saja.', title_ja = '自分で服を選びたい 👗', body_ja = 'クローゼットを開けて、合わない色や季節の服を組み合わせたがりますか？自立心を応援しつつ、主導権を保つために、2つだけ選択肢を出しましょう。', title_ko = '옷은 내가 고를래 👗', body_ko = '옷장을 열어 안 어울리는 색과 계절 옷을 섞어 입고 싶어 하나요? 자립심은 응원해 주되, 주도권은 지킬 수 있도록 딱 두 가지만 보여 주세요.', title_nl = 'Hij wil zelf zijn kleren kiezen 👗', body_nl = 'Opent hij de kast en wil hij kleuren en seizoenen combineren die niet bij elkaar passen? Steun zijn zelfstandigheid, maar geef hem gewoon 2 keuzes om de controle te houden.', title_pl = 'Chce sam wybierać ubrania 👗', body_pl = 'Otwiera szafę i chce łączyć niepasujące kolory i pory roku? Wspieraj jego samodzielność, ale żeby zachować kontrolę, daj mu po prostu 2 opcje.', title_pt = 'Quer escolher a própria roupa 👗', body_pt = 'Abre o armário e quer combinar cores e estações que não combinam? Apoie a independência dele, mas, para manter o controlo, ofereça apenas 2 opções.', title_sv = 'Barnet vill välja kläderna själv 👗', body_sv = 'Öppnar barnet garderoben och vill kombinera omatchade färger och årstider? Stöd självständigheten, men ge bara 2 val för att behålla kontrollen.', title_vi = 'Bé muốn tự chọn quần áo 👗', body_vi = 'Bé mở tủ và muốn phối những màu sắc, những món đồ khác mùa chẳng hợp nhau? Hãy ủng hộ sự tự lập của bé, nhưng để vẫn kiểm soát được, chỉ đưa ra 2 lựa chọn.', title_zh = '想自己挑衣服 👗', body_zh = '打开衣柜，想把不搭的颜色和季节混在一起穿？支持宝宝的独立，但为了掌控局面，只给两个选择就好。' WHERE id = '77a1ab3f-8086-4334-93ed-03dab08fb152' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ya no hay siestas y no puedes descansar en todo el día? Déjale 15 minutos con una actividad segura y recárgate sin falta con tu café.', body_fr = 'Plus de siestes et vous n''arrivez plus à souffler de la journée ? Laissez-le 15 minutes avec une activité sans danger et rechargez-vous absolument avec un café.', body_hi = 'दिन की नींद अब नहीं होती और आप दिनभर आराम नहीं कर पातीं? उसे 15 मिनट किसी सुरक्षित गतिविधि में लगाइए और अपनी कॉफ़ी से खुद को ज़रूर चार्ज कीजिए।', body_id = 'Tidur siang sudah tidak ada dan Anda tidak bisa beristirahat seharian? Biarkan ia sibuk dengan kegiatan yang aman selama 15 menit dan pastikan Anda mengisi ulang tenaga dengan kopi.', body_ja = 'もうお昼寝はなく、一日じゅう休めない？お子さんを15分間安全な遊びに任せて、必ず自分のコーヒーで充電しましょう。', body_ko = '낮잠은 이제 없고 하루 종일 쉴 틈이 없나요? 아이를 15분 동안 안전한 놀이에 맡기고 엄마는 꼭 커피로 충전하세요.', body_nl = 'Geen middagslaapjes meer en kun je de hele dag niet uitrusten? Laat hem 15 minuten met een veilige bezigheid alleen en laad jezelf zeker op met een koffie.', body_pl = 'Drzemek w dzień już nie ma i przez cały dzień nie możesz odpocząć? Zostaw go na 15 minut z bezpiecznym zajęciem i koniecznie naładuj się kawą.', body_pt = 'Já não há sestas e não consegue descansar o dia todo? Deixe-o 15 minutos com uma atividade segura e não deixe de recarregar com o seu café.', body_sv = 'Finns det ingen dagsömn längre och du får aldrig vila under dagen? Låt barnet vara med en säker aktivitet i 15 minuter och ladda absolut med ditt eget kaffe.', body_vi = 'Bé không còn ngủ ngày và mẹ không được nghỉ suốt cả ngày? Hãy để bé với một hoạt động an toàn 15 phút và nhất định nạp năng lượng bằng ly cà phê của mình.', body_zh = '已经不睡午觉了，你一整天都没法休息？让宝宝做一件安全的事玩15分钟，你一定要喝杯咖啡给自己充充电。' WHERE id = 'b22d0c31-c528-4596-b176-4f64d3f5be5d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Carga pesada, corazón tozudo 🛒', body_es = '¿Al volver del paseo quiere llevar él sí o sí lo más pesado o la bolsa? Aunque no pueda ni moverla, rechaza tu ayuda en redondo. Deja que se esfuerce un poco y pruebe su fuerza.', title_fr = 'Lourde charge, cœur têtu 🛒', body_fr = 'En rentrant de promenade, il veut absolument porter lui-même l''objet ou le sac le plus lourd ? Même s''il n''arrive pas à le bouger, il refuse catégoriquement votre aide. Laissez-le batailler un peu et tester sa force.', title_hi = 'भारी बोझ, ज़िद्दी दिल 🛒', body_hi = 'सैर से लौटते समय सबसे भारी चीज़ या थैला खुद ही उठाना चाहता है? उसे हिला भी न पाए, फिर भी आपकी मदद साफ़ ठुकरा देता है। उसे थोड़ा जूझने दीजिए, अपनी ताकत परखने दीजिए।', title_id = 'Beban berat, hati yang gigih 🛒', body_id = 'Pulang jalan-jalan, ia bersikeras membawa barang atau tas paling berat sendiri? Meski tidak bisa mengangkatnya, ia menolak bantuan Anda mentah-mentah. Biarkan ia berusaha sebentar dan menguji kekuatannya.', title_ja = '重い荷物、がんこな心 🛒', body_ja = 'お散歩の帰り、いちばん重いものや袋を自分で運ぶと言い張りますか？持ち上げられなくても、手助けはきっぱり断ります。少しがんばらせて、自分の力を試させてあげましょう。', title_ko = '무거운 짐, 고집스러운 마음 🛒', body_ko = '산책에서 돌아올 때 가장 무거운 물건이나 가방을 꼭 자기가 들겠다고 하나요? 들지도 못하면서 엄마의 도움은 단호히 거절하죠. 잠시 애쓰며 자기 힘을 시험해 보게 두세요.', title_nl = 'Zware last, koppig hartje 🛒', body_nl = 'Wil hij op de terugweg van een wandeling per se zelf het zwaarste ding of de zwaarste tas dragen? Ook al krijgt hij het niet van zijn plek, je hulp wijst hij resoluut af. Laat hem even worstelen en zijn kracht testen.', title_pl = 'Ciężki bagaż, uparte serce 🛒', body_pl = 'Wracając ze spaceru, koniecznie chce sam nieść najcięższą rzecz albo torbę? Choć nie może jej ruszyć z miejsca, stanowczo odrzuca twoją pomoc. Niech się trochę pomęczy i sprawdzi swoje siły.', title_pt = 'Carga pesada, coração teimoso 🛒', body_pt = 'No regresso do passeio, quer por força levar ele próprio o objeto ou o saco mais pesado? Mesmo sem o conseguir mexer, recusa a sua ajuda com firmeza. Deixe-o lutar um pouco e testar a sua força.', title_sv = 'Tung börda, envist hjärta 🛒', body_sv = 'Vill barnet absolut bära den tyngsta saken eller kassen själv på väg hem från promenaden? Även om hen inte kan rubba den, vägrar hen bestämt din hjälp. Låt barnet kämpa lite och testa sin styrka.', title_vi = 'Gánh nặng lớn, trái tim bướng bỉnh 🛒', body_vi = 'Trên đường đi dạo về, bé nhất định đòi tự mang món đồ hay chiếc túi nặng nhất? Dù không nhấc nổi, bé vẫn dứt khoát từ chối sự giúp đỡ của mẹ. Hãy để bé loay hoay một chút để thử sức mình.', title_zh = '沉重的东西，倔强的心 🛒', body_zh = '散步回来时，一定要自己拿最重的东西或袋子？就算搬不动，也坚决拒绝你帮忙。让宝宝费点劲，试试自己的力气吧。' WHERE id = '9787e3a9-8592-4bb2-8463-c4e695682c99' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño filósofo 🤔', body_es = '¿Justo cuando se le cerraban los ojos levantó la cabeza y te hizo una pregunta filosófica como «Mamá, ¿adónde se va a dormir el sol?»? Su cerebro procesa el mundo incluso al quedarse dormido. Sin profundizar demasiado, dale una respuesta corta y de cuento.', title_fr = 'Petit philosophe 🤔', body_fr = 'Alors que ses yeux se fermaient, il a soudain relevé la tête pour poser une question philosophique comme « Maman, le soleil va dormir où ? » ? Même au moment de s''endormir, son cerveau traite le monde. Sans aller trop loin, répondez brièvement, comme dans un conte.', title_hi = 'नन्हा दार्शनिक 🤔', body_hi = 'आँखें बंद होते-होते अचानक सिर उठाकर पूछा ''माँ, सूरज सोने कहाँ जाता है?'' जैसा दार्शनिक सवाल? सोने के पल में भी उसका दिमाग दुनिया को समझने में लगा है। बहुत गहराई में गए बिना छोटा, कहानी जैसा जवाब दीजिए।', title_id = 'Filsuf kecil 🤔', body_id = 'Saat matanya hampir terpejam, tiba-tiba ia mengangkat kepala dan bertanya hal filosofis seperti ''Ibu, matahari tidur ke mana?'' Otaknya terus mengolah dunia bahkan saat akan tertidur. Jangan terlalu dalam, beri jawaban singkat ala dongeng.', title_ja = '小さな哲学者 🤔', body_ja = '目がとじかけたその瞬間、急に顔を上げて「ママ、お日さまはどこに寝にいくの？」と哲学的な質問をしましたか？眠りに入る瞬間でさえ、脳は世界を整理しています。深入りせず、短くてお話のような答えを返しましょう。', title_ko = '꼬마 철학자 🤔', body_ko = '눈이 막 감기려는 순간 갑자기 고개를 들고 ''엄마, 해는 어디로 자러 가?'' 같은 철학적인 질문을 했나요? 잠드는 순간에도 뇌는 세상을 정리하고 있어요. 너무 깊이 들어가지 말고 짧고 동화 같은 대답을 해 주세요.', title_nl = 'Kleine filosoof 🤔', body_nl = 'Net als zijn ogen dichtvallen, tilt hij ineens zijn hoofd op met een filosofische vraag als ''Mama, waar gaat de zon slapen?'' Zijn hersenen verwerken de wereld zelfs tijdens het inslapen. Ga niet te diep, geef een kort antwoord als uit een sprookje.', title_pl = 'Mały filozof 🤔', body_pl = 'Gdy oczy już mu się zamykały, nagle podniósł głowę i zadał filozoficzne pytanie: „Mamo, dokąd słońce idzie spać?”. Jego mózg przetwarza świat nawet w chwili zasypiania. Nie wchodząc w szczegóły, odpowiedz krótko i bajkowo.', title_pt = 'Pequeno filósofo 🤔', body_pt = 'Quando os olhos já se fechavam, levantou de repente a cabeça e fez uma pergunta filosófica como "Mamã, onde é que o sol vai dormir?"? O cérebro processa o mundo até no momento de adormecer. Sem ir muito fundo, dê uma resposta curta, como num conto.', title_sv = 'Liten filosof 🤔', body_sv = 'Lyfte barnet plötsligt huvudet precis när ögonen höll på att slutas och ställde en filosofisk fråga som ”Mamma, vart går solen och lägger sig?”? Hjärnan bearbetar världen även i övergången till sömn. Ge ett kort, sagolikt svar utan att gå för djupt.', title_vi = 'Triết gia nhí 🤔', body_vi = 'Đúng lúc sắp nhắm mắt, bé bỗng ngẩng đầu hỏi một câu triết lý như "Mẹ ơi, mặt trời đi ngủ ở đâu?"? Não bé vẫn xử lý thế giới ngay cả khi đang chìm vào giấc ngủ. Hãy trả lời ngắn gọn như truyện cổ tích mà không đi quá sâu.', title_zh = '小小哲学家 🤔', body_zh = '眼睛快闭上时，突然抬起头问“妈妈，太阳去哪儿睡觉？”这样的哲学问题？大脑就连在入睡时都在消化这个世界。别讲得太深，给一个简短、像童话一样的回答吧。' WHERE id = 'bdc2ddcb-448f-4cfa-b4a5-c5e56bf2b001' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exigencias de milagro 🪄', body_es = '¿Esta mañana nada más despertarse te exigió a gritos que volvieras a juntar la manzana cortada? Sí, cerca de los 3 años su lógica desafía las leyes de la física.', title_fr = 'Il exige des miracles 🪄', body_fr = 'Ce matin, dès le réveil, il a exigé en hurlant que vous recolliez la pomme coupée en morceaux ? Eh oui, vers 3 ans, leur logique défie les lois de la physique.', title_hi = 'चमत्कार की माँगें 🪄', body_hi = 'आज सुबह जागते ही चिल्लाकर माँग की कि कटे हुए सेब को फिर से पूरा कर दो? हाँ, 3 साल के करीब उनका तर्क भौतिकी के नियमों को चुनौती देता है।', title_id = 'Permintaan ajaib 🪄', body_id = 'Pagi ini begitu bangun ia berteriak menuntut Anda menyatukan kembali apel yang sudah diiris? Ya, menjelang usia 3 tahun logika mereka menantang hukum fisika.', title_ja = '奇跡のリクエスト 🪄', body_ja = '今朝、目覚めたとたん、切ったりんごを元どおりにしてと叫んで要求しましたか？そう、3歳が近づくと、子どもの理屈は物理の法則に挑戦するのです。', title_ko = '기적을 바라는 꼬마 🪄', body_ko = '오늘 아침 일어나자마자 잘라 놓은 사과를 다시 붙여 달라고 소리쳤나요? 네, 세 돌 무렵 아이들의 논리는 물리 법칙에 도전해요.', title_nl = 'Wonderlijke eisen 🪄', body_nl = 'Eiste hij vanochtend gillend dat je de appel die in stukjes was gesneden weer heel maakte? Ja, richting 3 jaar daagt hun logica de natuurwetten uit.', title_pl = 'Żądania cudów 🪄', body_pl = 'Dziś rano, gdy tylko się obudził, z krzykiem zażądał, żebyś skleiła pokrojone jabłko z powrotem w całość? Tak, w okolicach 3. roku życia ich logika rzuca wyzwanie prawom fizyki.', title_pt = 'Pedidos de milagre 🪄', body_pt = 'Esta manhã, mal acordou, exigiu aos gritos que voltasse a juntar a maçã cortada às fatias? Pois é, perto dos 3 anos a lógica deles desafia as leis da física.', title_sv = 'Krav på mirakel 🪄', body_sv = 'Krävde barnet skrikande så fort hen vaknade i morse att du skulle göra det skivade äpplet helt igen? Ja, när barn närmar sig 3 år utmanar deras logik fysikens lagar.', title_vi = 'Những đòi hỏi phép màu 🪄', body_vi = 'Sáng nay vừa thức dậy bé đã la hét đòi mẹ ghép lại quả táo đã cắt thành nguyên quả? Đúng vậy, gần 3 tuổi, logic của bé thách thức cả định luật vật lý.', title_zh = '要求奇迹 🪄', body_zh = '今早一醒来就尖叫着要你把切好的苹果变回完整的？没错，快3岁时，他们的逻辑在挑战物理定律。' WHERE id = 'c2525bad-5158-49a7-81ce-247259a08d2e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Imitando animales 🐶', body_es = '¿No solo hace los sonidos, sino que gatea como un perro y se frota como un gato? Su lenguaje corporal y su imaginación se unen. Únete a este juego sobre la alfombra.', title_fr = 'Il imite les animaux 🐶', body_fr = 'Il ne se contente plus d''imiter les cris : il marche à quatre pattes comme un chien et guette comme un chat ? Langage corporel et imagination se rejoignent. Joignez-vous à ce jeu sur le tapis.', title_hi = 'जानवरों की नकल 🐶', body_hi = 'सिर्फ़ आवाज़ ही नहीं निकालता, कुत्ते की तरह घुटनों के बल चलता और बिल्ली की तरह शिकार करता है? शारीरिक भाषा और कल्पना मिल रही हैं। कालीन पर इस खेल में आप भी शामिल हो जाइए।', title_id = 'Meniru hewan 🐶', body_id = 'Ia tidak hanya bersuara, tetapi juga merangkak seperti anjing dan mengendap seperti kucing? Bahasa tubuh dan imajinasinya menyatu. Ikutlah bermain bersamanya di atas karpet.', title_ja = '動物のまね 🐶', body_ja = '鳴き声だけでなく、犬のようにはいはいしたり、猫のように体をすりよせたりしますか？体の表現と想像力が結びついています。一緒にカーペットの上でこの遊びに加わりましょう。', title_ko = '동물 흉내 🐶', body_ko = '소리만 내는 게 아니라 강아지처럼 기고 고양이처럼 몸을 비비나요? 몸짓 언어와 상상력이 하나가 되고 있어요. 카펫 위에서 함께 이 놀이를 해 보세요.', title_nl = 'Dieren nadoen 🐶', body_nl = 'Maakt hij niet alleen geluidjes, maar kruipt hij ook als een hond en sluipt hij als een kat? Lichaamstaal en fantasie komen samen. Doe mee met dit spel op het tapijt.', title_pl = 'Naśladowanie zwierząt 🐶', body_pl = 'Nie tylko wydaje odgłosy, ale też raczkuje jak pies i łasi się jak kot? Mowa ciała i wyobraźnia się łączą. Dołącz do tej zabawy na dywanie.', title_pt = 'A imitar animais 🐶', body_pt = 'Não só faz os sons, como também gatinha como um cão e se enrosca como um gato? A linguagem corporal e a imaginação juntam-se. Entre também nesta brincadeira no tapete.', title_sv = 'Härma djur 🐶', body_sv = 'Gör barnet inte bara ljud, utan kryper som en hund och smyger som en katt? Kroppsspråk och fantasi förenas. Var med i leken på mattan tillsammans.', title_vi = 'Bắt chước các con vật 🐶', body_vi = 'Bé không chỉ phát ra tiếng kêu mà còn bò như chó, rình như mèo? Ngôn ngữ cơ thể và trí tưởng tượng đang kết hợp với nhau. Hãy cùng bé chơi trò này trên thảm.', title_zh = '模仿动物 🐶', body_zh = '不只是学叫声，还像小狗一样爬，像小猫一样扑？肢体语言和想象力结合在一起了。在地毯上和宝宝一起玩这个游戏吧。' WHERE id = '1e3f3fa1-dbbc-4651-aa40-6590038f46b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Selectividad con la comida 2.0 🥣', body_es = '¿Hoy rechaza la sopa que hasta ayer le encantaba? No le obligues. Busca en Recetas saludables recetas alternativas en las que puedas esconder las verduras.', title_fr = 'Difficile à table 2.0 🥣', body_fr = 'Il refuse aujourd''hui la soupe qu''il adorait jusqu''à hier ? Ne le forcez pas. Trouvez dans les Recettes saines d''autres recettes où vous pourrez cacher les légumes.', title_hi = 'खाने में नखरे 2.0 🥣', body_hi = 'कल तक जो सूप पसंद था, आज उसे मना कर रहा है? ज़बरदस्ती मत कीजिए। सेहतमंद रेसिपी सेक्शन से ऐसी दूसरी रेसिपी ढूँढिए जिनमें सब्ज़ियाँ छिपाई जा सकें।', title_id = 'Pilih-pilih makanan 2.0 🥣', body_id = 'Hari ini ia menolak sup yang ia sukai sampai kemarin? Jangan memaksa. Temukan resep alternatif yang berbeda di bagian Resep Sehat untuk menyembunyikan sayuran.', title_ja = '好き嫌い2.0 🥣', body_ja = '昨日まで大好きだったスープを、今日はいやがりますか？無理強いしないで。「ヘルシーレシピ」から、野菜をかくせる別のレシピを見つけましょう。', title_ko = '편식 2.0 🥣', body_ko = '어제까지 좋아하던 수프를 오늘은 거부하나요? 억지로 먹이지 마세요. 건강한 레시피에서 채소를 숨길 수 있는 색다른 대안 레시피를 찾아보세요.', title_nl = 'Kieskeurig eten 2.0 🥣', body_nl = 'Weigert hij vandaag de soep waar hij tot gisteren dol op was? Dwing hem niet. Vind in Gezonde recepten andere recepten waarin je groenten kunt verstoppen.', title_pl = 'Wybiórczość jedzeniowa 2.0 🥣', body_pl = 'Zupę, którą jeszcze wczoraj uwielbiał, dziś odrzuca? Nie zmuszaj go. Znajdź w sekcji Zdrowe przepisy inne przepisy, w których ukryjesz warzywa.', title_pt = 'Seletividade alimentar 2.0 🥣', body_pt = 'Hoje recusa a sopa de que gostava até ontem? Não o force. Encontre nas Receitas Saudáveis receitas alternativas onde pode esconder os legumes.', title_sv = 'Kräsen med maten 2.0 🥣', body_sv = 'Vägrar barnet i dag soppan hen älskade fram till i går? Tvinga inte. Hitta andra alternativa recept där du kan gömma grönsakerna i avsnittet Hälsosamma recept.', title_vi = 'Kén ăn 2.0 🥣', body_vi = 'Món canh đến hôm qua bé vẫn thích thì hôm nay lại từ chối? Đừng ép bé. Hãy tìm trong mục Công thức lành mạnh những công thức khác có thể giấu rau củ.', title_zh = '挑食2.0 🥣', body_zh = '到昨天还爱喝的汤，今天却不喝了？别勉强。去健康食谱板块找找能把蔬菜藏起来的其他替代食谱吧。' WHERE id = '4ac97d09-8bce-44ef-922e-5286afc49815' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Historia mágica para dormir 🪄', body_es = 'En Cuentos inteligentes crea la historia de un héroe valiente que se prepara para cumplir 3 años y hazle sentir que está creciendo y haciéndose fuerte.', title_fr = 'Une histoire du soir magique 🪄', body_fr = 'Dans les Contes intelligents, créez l''histoire d''un héros courageux qui se prépare à avoir 3 ans, pour lui faire sentir qu''il grandit et devient plus fort.', title_hi = 'जादुई नींद वाली कहानी 🪄', body_hi = 'स्मार्ट कहानियों में ''तीन साल का होने वाला बहादुर हीरो'' की कहानी बनाइए और उसे महसूस कराइए कि वह बड़ा और मज़बूत हो रहा है।', title_id = 'Cerita tidur ajaib 🪄', body_id = 'Di Dongeng Pintar, buat kisah tentang pahlawan pemberani yang bersiap memasuki usia tiga tahun, dan buat ia merasa bahwa dirinya tumbuh besar dan makin kuat.', title_ja = '魔法のおやすみストーリー 🪄', body_ja = '「スマートおはなし」で、3歳を迎える勇敢な主人公のお話をつくって、自分が大きく強くなっていることを感じさせてあげましょう。', title_ko = '마법 같은 잠자리 이야기 🪄', body_ko = '스마트 동화에서 세 살 생일을 준비하는 용감한 주인공 이야기를 만들어, 아이가 자라고 있고 더 강해지고 있다고 느끼게 해 주세요.', title_nl = 'Magisch slaapverhaal 🪄', body_nl = 'Maak in Slimme sprookjes het verhaal van een dappere held die zich klaarmaakt voor zijn derde verjaardag en laat hem voelen dat hij groter en sterker wordt.', title_pl = 'Magiczna historia na dobranoc 🪄', body_pl = 'Stwórz w Mądrych bajkach historię o dzielnym bohaterze, który szykuje się do trzecich urodzin, i daj mu poczuć, że rośnie i staje się silniejszy.', title_pt = 'História mágica para dormir 🪄', body_pt = 'Nas Histórias Inteligentes, crie a história de um herói corajoso que se prepara para fazer três anos e faça-o sentir que está a crescer e a ficar mais forte.', title_sv = 'Magisk godnattberättelse 🪄', body_sv = 'Skapa berättelsen om en modig hjälte som snart fyller tre år i Smarta sagor och låt barnet känna att hen växer och blir starkare.', title_vi = 'Câu chuyện ngủ ngon kỳ diệu 🪄', body_vi = 'Trong Truyện cổ tích thông minh, hãy tạo câu chuyện về "Người hùng dũng cảm chuẩn bị tròn ba tuổi" để bé cảm nhận mình đang lớn lên và mạnh mẽ hơn.', title_zh = '神奇的睡前故事 🪄', body_zh = '在智能故事里创作一个《准备迎接3岁的勇敢小英雄》的故事，让宝宝感受到自己正在长大、变得更强。' WHERE id = 'd8f03ef9-1ea4-48a4-a43d-dc4f633f2d60' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Vuelve a llorar en cuanto sales de la habitación? La ansiedad por separación a veces vuelve. Dale seguridad con tu voz desde lejos, pero no tienes por qué estar a la vista en todo momento.', body_fr = 'Il se remet à pleurer dès que vous quittez la pièce ? L''angoisse de séparation revient parfois. Rassurez-le de loin avec votre voix, mais vous n''êtes pas obligée d''être sous ses yeux à chaque instant.', body_hi = 'आप कमरे से निकलते ही फिर रोने लगता है? अलगाव की चिंता कभी-कभी लौट आती है। दूर से अपनी आवाज़ से उसे भरोसा दीजिए, लेकिन हर पल उसकी नज़रों के सामने रहना आपकी मजबूरी नहीं है।', body_id = 'Begitu Anda keluar kamar, ia menangis lagi? Kecemasan berpisah kadang kembali. Beri rasa aman lewat suara Anda dari jauh, tetapi Anda tidak wajib selalu terlihat olehnya setiap saat.', body_ja = '部屋を出たとたん、また泣き出しますか？分離不安はときどきぶり返します。離れたところから声で安心させましょう。でも、いつも目の前にいなければならないわけではありません。', body_ko = '방을 나가자마자 또 울기 시작하나요? 분리 불안은 가끔 다시 찾아와요. 멀리서 목소리로 안심시켜 주세요. 하지만 매 순간 눈앞에 있을 필요는 없어요.', body_nl = 'Begint hij weer te huilen zodra je de kamer uit gaat? Verlatingsangst komt soms terug. Geef hem met je stem van een afstand vertrouwen, maar je hoeft niet elk moment in zicht te zijn.', body_pl = 'Gdy tylko wychodzisz z pokoju, znów zaczyna płakać? Lęk separacyjny czasem wraca. Dodawaj mu otuchy głosem z daleka, ale nie musisz cały czas być w zasięgu jego wzroku.', body_pt = 'Volta a chorar mal sai do quarto? A ansiedade de separação às vezes volta. Dê-lhe segurança com a sua voz à distância, mas não é obrigada a estar sempre à vista.', body_sv = 'Börjar barnet gråta igen så fort du lämnar rummet? Separationsångesten kommer ibland tillbaka. Ge trygghet med din röst på avstånd, men du måste inte vara inom synhåll hela tiden.', body_vi = 'Mẹ vừa ra khỏi phòng là bé lại khóc? Lo âu chia ly đôi khi quay trở lại. Hãy trấn an bé bằng giọng nói từ xa, nhưng mẹ không cần lúc nào cũng phải ở trong tầm mắt bé.', body_zh = '你一离开房间，宝宝又开始哭了？分离焦虑有时会卷土重来。用声音远远地给宝宝安全感，但你不必时时刻刻都待在宝宝眼前。' WHERE id = '2a9575e0-ee4f-4f27-86a9-25def022748e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que termine él el cuento 📖', body_es = 'Esta noche, al leer el cuento, deja las frases a medias ¡y que las termine tu peque! Pregunta a Anacan AI formas de dialogar que apoyen este asombroso desarrollo de la imaginación.', title_fr = 'C''est lui qui finit l''histoire 📖', body_fr = 'Ce soir, en lisant l''histoire, laissez vos phrases en suspens et laissez-le les compléter ! Demandez à Anacan AI des façons de dialoguer pour soutenir ce développement étonnant de son imagination.', title_hi = 'कहानी का अंत वह बताए 📖', body_hi = 'आज शाम कहानी पढ़ते समय वाक्य अधूरे छोड़िए और उसे पूरा करने दीजिए! कल्पना के इस कमाल के विकास को बढ़ावा देने वाले बातचीत के तरीके Anacan AI से पूछिए।', title_id = 'Biar ia yang menutup cerita 📖', body_id = 'Malam ini saat membacakan dongeng, hentikan kalimat di tengah jalan dan biarkan ia melanjutkannya! Tanyakan pada Anacan AI cara berdialog yang mendukung perkembangan imajinasi yang luar biasa ini.', title_ja = 'お話の結末はお子さんに 📖', body_ja = '今夜お話を読むとき、文を途中で止めて、お子さんに続きを言ってもらいましょう！このすばらしい想像力の発達を支える対話のコツを、Anacan AIに聞いてみて。', title_ko = '동화의 끝은 아이가 말해요 📖', body_ko = '오늘 저녁 동화를 읽을 때 문장을 중간에 멈추고 아이가 마무리하게 해 보세요! 이 놀라운 상상력 발달을 돕는 대화 요령을 Anacan AI에게 물어보세요.', title_nl = 'Laat hem het einde vertellen 📖', body_nl = 'Stop vanavond tijdens het voorlezen halverwege een zin en laat hem die afmaken! Vraag Anacan AI naar manieren om met gesprekjes deze geweldige ontwikkeling van zijn fantasie te steunen.', title_pl = 'Niech on dokończy bajkę 📖', body_pl = 'Dziś wieczorem, czytając bajkę, przerywaj zdania w połowie i pozwól mu je dokończyć! Zapytaj Anacan AI o sposoby prowadzenia dialogu, które wspierają ten niesamowity rozwój wyobraźni.', title_pt = 'Ele que diga o fim da história 📖', body_pt = 'Esta noite, ao ler a história, deixe as frases a meio e deixe-o completá-las! Pergunte ao Anacan AI que diálogos apoiam este desenvolvimento fantástico da imaginação.', title_sv = 'Låt barnet avsluta sagan 📖', body_sv = 'När du läser saga i kväll, stanna mitt i meningarna och låt barnet fylla i! Fråga Anacan AI om samtalssätt som stöder den här fantastiska utvecklingen av fantasin.', title_vi = 'Để bé kể đoạn kết 📖', body_vi = 'Tối nay khi đọc truyện, hãy dừng giữa câu và để bé nói tiếp! Hãy hỏi Anacan AI những cách đối thoại giúp hỗ trợ sự phát triển trí tưởng tượng đáng kinh ngạc này.', title_zh = '让宝宝来说故事结局 📖', body_zh = '今晚读故事时，把句子留一半，让宝宝来补完！问问Anacan AI，有哪些对话方式能支持这种惊人的想象力发展。' WHERE id = '89de8241-ec59-4180-ba30-e03291e0f208' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lista es imprescindible 🛒', body_es = '¡Que no se olvide nada de lo necesario para el cumpleaños! No cargues la cabeza: apúntalo todo enseguida en la Lista de la compra y sincronízala con tu pareja.', title_fr = 'La liste, indispensable 🛒', body_fr = 'N''oubliez rien de ce qu''il faut pour l''anniversaire ! Ne vous fatiguez pas la tête, notez tout de suite tout dans la Liste de courses et synchronisez-la avec votre partenaire.', title_hi = 'लिस्ट ज़रूरी है 🛒', body_hi = 'जन्मदिन के लिए ज़रूरी चीज़ें भूलनी नहीं चाहिए! दिमाग मत थकाइए, सब कुछ तुरंत शॉपिंग लिस्ट में लिखिए और अपने पार्टनर के साथ सिंक कीजिए।', title_id = 'Daftar itu wajib 🛒', body_id = 'Jangan sampai kebutuhan untuk ulang tahun terlupa! Jangan membebani pikiran, segera catat semuanya di Daftar Belanja dan sinkronkan dengan pasangan.', title_ja = 'リストは欠かせない 🛒', body_ja = 'お誕生日に必要なものを忘れないで！頭を疲れさせず、すべてすぐに「買い物リスト」に書いて、パートナーと共有しましょう。', title_ko = '목록은 필수예요 🛒', body_ko = '생일에 필요한 물건을 잊지 마세요! 머리 아프게 기억하지 말고 바로 쇼핑 목록에 적어 배우자와 공유하세요.', title_nl = 'Een lijstje is een must 🛒', body_nl = 'Vergeet niets voor de verjaardag! Pijnig je hoofd niet, zet alles meteen op het Boodschappenlijstje en synchroniseer het met je partner.', title_pl = 'Lista to konieczność 🛒', body_pl = 'Niech nic potrzebnego na urodziny nie zostanie zapomniane! Nie obciążaj głowy, od razu wpisz wszystko na Listę zakupów i zsynchronizuj ją z partnerem.', title_pt = 'A lista é obrigatória 🛒', body_pt = 'Que não se esqueça nada do que é preciso para o aniversário! Não sobrecarregue a cabeça: aponte tudo logo na Lista de Compras e sincronize com o seu companheiro.', title_sv = 'Listan är ett måste 🛒', body_sv = 'Glöm inte det som behövs till födelsedagen! Belasta inte hjärnan, skriv genast in allt i Inköpslistan och synka med din partner.', title_vi = 'Danh sách là bắt buộc 🛒', body_vi = 'Đừng để quên đồ cần cho sinh nhật! Đừng bắt mình phải nhớ, hãy ghi ngay mọi thứ vào Danh sách mua sắm và đồng bộ với chồng.', title_zh = '清单必不可少 🛒', body_zh = '生日需要的东西可别忘了！别让脑子太累，马上把所有东西写进购物清单，和另一半同步。' WHERE id = 'ca321f21-1031-4b14-96c8-69fa4c4201da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Buscando nuevos amigos 👫', body_es = '¿En el parque intenta correr con otros niños de su edad y unirse a sus juegos? ¡Empieza oficialmente la socialización! Anímale y enséñale a saludar a otros niños.', title_fr = 'À la recherche de nouveaux amis 👫', body_fr = 'Au parc, il essaie de courir avec les enfants de son âge et de se joindre à leurs jeux ? La socialisation commence officiellement ! Encouragez-le et apprenez-lui à dire bonjour aux autres enfants.', title_hi = 'नए दोस्तों की तलाश 👫', body_hi = 'पार्क में अपने हमउम्र बच्चों के साथ दौड़ने और उनके खेल में शामिल होने की कोशिश करता है? सामाजिकता अब शुरू हो रही है! उसका हौसला बढ़ाइए और सिखाइए कि बच्चों से ''हेलो'' कैसे करें।', title_id = 'Mencari teman baru 👫', body_id = 'Ia mencoba berlari bersama teman sebayanya di taman dan ikut dalam permainan mereka? Sosialisasi resmi dimulai! Beri ia semangat dan ajarkan cara menyapa anak-anak lain.', title_ja = '新しいお友だち探し 👫', body_ja = '公園で同じ年ごろの子と一緒に走ったり、遊びに加わろうとしたりしていますか？社会性がいよいよ始まります！励ましてあげて、ほかの子へのあいさつの仕方を教えましょう。', title_ko = '새 친구 찾기 👫', body_ko = '공원에서 또래와 함께 뛰며 놀이에 끼려고 하나요? 사회성이 본격적으로 시작됐어요! 응원해 주고 친구들과 인사하는 법을 알려 주세요.', title_nl = 'Op zoek naar nieuwe vriendjes 👫', body_nl = 'Probeert hij in het park met leeftijdsgenootjes mee te rennen en mee te doen met hun spel? De socialisatie begint officieel! Moedig hem aan en leer hem hoe hij andere kinderen begroet.', title_pl = 'W poszukiwaniu nowych przyjaciół 👫', body_pl = 'W parku próbuje biegać z rówieśnikami i dołączać do ich zabaw? Socjalizacja oficjalnie się zaczyna! Dodawaj mu odwagi i ucz, jak witać się z dziećmi.', title_pt = 'À procura de novos amigos 👫', body_pt = 'No parque, tenta correr com crianças da idade dele e entrar nas brincadeiras delas? A socialização começa oficialmente! Incentive-o e ensine-o a cumprimentar as outras crianças.', title_sv = 'På jakt efter nya vänner 👫', body_sv = 'Försöker barnet springa med jämnåriga i parken och vara med i deras lekar? Socialiseringen börjar officiellt! Uppmuntra barnet och lär hen hur man hälsar på andra barn.', title_vi = 'Đi tìm bạn mới 👫', body_vi = 'Bé cố chạy theo các bạn cùng tuổi ở công viên và tham gia trò chơi của các bạn? Bé chính thức bắt đầu hòa nhập xã hội! Hãy khích lệ và dạy bé cách chào hỏi các bạn.', title_zh = '寻找新朋友 👫', body_zh = '在公园里想跟同龄小朋友一起跑，加入他们的游戏？社交正式开始了！鼓励宝宝，教宝宝怎样和小朋友打招呼吧。' WHERE id = '16b69d4c-feb3-42d5-b458-329c2a13a823' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de naturaleza para mamá 🌳', body_es = '¿Las paredes de casa te agobian? Coge a tu peque y corred al parque más cercano. El aire fresco no solo es el mejor masaje para tu peque, también para tus nervios cansados.', title_fr = 'La nature-thérapie de maman 🌳', body_fr = 'Les murs de la maison vous étouffent ? Prenez l''enfant et filez au parc le plus proche. L''air frais n''est pas seulement bon pour lui : c''est aussi le meilleur massage pour vos nerfs fatigués.', title_hi = 'माँ के लिए प्रकृति थेरेपी 🌳', body_hi = 'घर की दीवारें घुटन दे रही हैं? बच्चे को साथ लीजिए और सबसे पास के पार्क की ओर निकल पड़िए। ताज़ी हवा सिर्फ़ बच्चे की नहीं, आपकी थकी नसों की भी सबसे अच्छी मालिश है।', title_id = 'Terapi alam untuk Ibu 🌳', body_id = 'Dinding rumah terasa menyesakkan? Ajak anak dan pergilah ke taman terdekat. Udara segar bukan hanya untuk anak, tetapi juga pijatan terbaik bagi saraf Anda yang lelah.', title_ja = 'ママのための自然セラピー 🌳', body_ja = '家の壁に息がつまりそう？お子さんを連れて、近くの公園へ出かけましょう。新鮮な空気は、お子さんだけでなく、あなたの疲れた神経にもいちばんのマッサージです。', title_ko = '엄마를 위한 자연 테라피 🌳', body_ko = '집의 벽이 숨 막히게 느껴지나요? 아이와 함께 가장 가까운 공원으로 나가세요. 맑은 공기는 아이뿐 아니라 엄마의 지친 신경에도 최고의 마사지예요.', title_nl = 'Natuurtherapie voor mama 🌳', body_nl = 'Kruipen de muren op je af? Neem je kindje mee en ga naar het dichtstbijzijnde park. Frisse lucht is niet alleen goed voor hem, maar ook de beste massage voor jouw vermoeide zenuwen.', title_pl = 'Terapia naturą dla mamy 🌳', body_pl = 'Ściany domu cię przytłaczają? Weź dziecko i biegnijcie do najbliższego parku. Świeże powietrze to najlepszy masaż nie tylko dla dziecka, ale i dla twoich zmęczonych nerwów.', title_pt = 'Terapia da natureza para a mãe 🌳', body_pt = 'As paredes da casa sufocam-na? Pegue na criança e corram para o parque mais próximo. O ar puro é a melhor massagem não só para ele, mas também para os seus nervos cansados.', title_sv = 'Naturterapi för mamma 🌳', body_sv = 'Kväver hemmets väggar dig? Ta med barnet och skynda till närmaste park. Frisk luft är den bästa massagen inte bara för barnet utan även för dina trötta nerver.', title_vi = 'Liệu pháp thiên nhiên cho mẹ 🌳', body_vi = 'Bốn bức tường khiến mẹ ngột ngạt? Hãy đưa bé ra công viên gần nhất. Không khí trong lành không chỉ tốt cho bé mà còn là liệu pháp mát-xa tốt nhất cho thần kinh mệt mỏi của mẹ.', title_zh = '妈妈的自然疗法 🌳', body_zh = '家里的墙让你透不过气？带上孩子，奔向最近的公园。新鲜空气不只对孩子好，对你疲惫的神经也是最好的按摩。' WHERE id = 'db813abc-1129-479f-a1e4-e6beaeb2ec95' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tragedia de la costura del calcetín 🧦', body_es = 'Esta mañana nos hemos despertado con una gran crisis: ¡la costura del calcetín le roza el dedo! Cerca de los 3 años la sensibilidad sensorial llega a su punto máximo. No busques lógica: ponle el calcetín del revés y mira cómo esta crisis absurda se acaba en 10 segundos.', title_fr = 'Le drame de la couture de chaussette 🧦', body_fr = 'Ce matin, réveil avec une grosse crise : la couture de la chaussette touche son orteil ! Vers 3 ans, la sensibilité sensorielle est à son comble. Ne cherchez pas de logique, mettez la chaussette à l''envers et regardez cette crise absurde se terminer en 10 secondes.', title_hi = 'मोज़े की सिलाई का दुखड़ा 🧦', body_hi = 'आज सुबह एक बड़े संकट के साथ जागे: मोज़े के अंदर की सिलाई उँगली को छू रही है! 3 साल के करीब संवेदनशीलता चरम पर पहुँच जाती है। तर्क मत ढूँढिए, मोज़ा उल्टा पहना दीजिए और देखिए कि यह बेतुका संकट 10 सेकंड में कैसे खत्म हो जाता है।', title_id = 'Tragedi jahitan kaus kaki 🧦', body_id = 'Pagi ini kami bangun dengan krisis besar: jahitan di dalam kaus kaki menyentuh jari kakinya! Menjelang usia 3 tahun kepekaan indranya memuncak. Jangan mencari logika, pakaikan kaus kakinya terbalik dan lihat krisis absurd ini selesai dalam 10 detik.', title_ja = 'くつしたの縫い目の悲劇 🧦', body_ja = '今朝は大きな危機で目が覚めました：くつしたの中の縫い目が指にあたる！3歳が近づくと、感覚の敏感さがピークに達します。理屈を探さず、くつしたを裏返しにはかせて、このふしぎな危機が10秒で終わるのを見届けましょう。', title_ko = '양말 솔기 대참사 🧦', body_ko = '오늘 아침 큰 위기로 시작했나요: 양말 속 솔기가 발가락에 닿는대요! 세 돌 무렵엔 감각이 가장 예민해져요. 논리를 찾지 말고 양말을 뒤집어 신겨 이 황당한 위기가 10초 만에 끝나는 걸 지켜보세요.', title_nl = 'Het drama van de sokkennaad 🧦', body_nl = 'Vanochtend werden we wakker met een grote crisis: de naad in zijn sok raakt zijn teen! Richting 3 jaar is de zintuiglijke gevoeligheid op zijn hoogst. Zoek geen logica, trek de sok binnenstebuiten aan en kijk hoe deze absurde crisis in 10 seconden voorbij is.', title_pl = 'Tragedia szwu w skarpetce 🧦', body_pl = 'Dziś rano obudziliśmy się z wielkim kryzysem: szew w skarpetce dotyka paluszka! W okolicach 3. roku życia wrażliwość zmysłowa osiąga szczyt. Nie szukaj logiki, załóż skarpetkę na lewą stronę i patrz, jak ten absurdalny kryzys kończy się w 10 sekund.', title_pt = 'A tragédia da costura da meia 🧦', body_pt = 'Esta manhã acordámos com uma grande crise: a costura da meia toca-lhe no dedo! Perto dos 3 anos, a sensibilidade sensorial atinge o máximo. Não procure lógica: vista-lhe a meia do avesso e veja como esta crise absurda acaba em 10 segundos.', title_sv = 'Tragedin med strumpsömmen 🧦', body_sv = 'I morse vaknade vi till en stor kris: sömmen inuti strumpan nuddar tån! När barnet närmar sig 3 år når den känslomässiga och sensoriska känsligheten sin topp. Leta inte efter logik, vänd strumpan ut och in och se hur den absurda krisen är över på 10 sekunder.', title_vi = 'Bi kịch đường may chiếc tất 🧦', body_vi = 'Sáng nay mình thức dậy cùng một cuộc khủng hoảng lớn: đường may trong tất chạm vào ngón chân! Gần 3 tuổi, sự nhạy cảm giác quan lên đến đỉnh điểm. Đừng tìm logic, hãy lộn trái chiếc tất và xem cơn khủng hoảng vô lý này kết thúc trong 10 giây.', title_zh = '袜子缝线的悲剧 🧦', body_zh = '今早醒来就是一场大危机：袜子里的缝线碰到脚趾了！快3岁时，感官敏感度达到高峰。别找道理，把袜子翻过来穿，看看这场荒唐的危机怎样在10秒内结束。' WHERE id = '565fda98-0d2c-40b4-8230-13c64e585700' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cazador de charcos 🌧️', body_es = '¿Salisteis después de la lluvia y saltó directo a un charco de barro? Se ha puesto perdido, pero mira esa luz de descubrimiento en sus ojos. Planifica con Tiempo y ropa ponerle botas de agua y deja que viva su infancia.', title_fr = 'Chasseur de flaques 🌧️', body_fr = 'Vous êtes sortis après la pluie et il a sauté droit dans une flaque de boue ? Ses vêtements sont trempés, mais regardez cette lumière de découverte dans ses yeux. Prévoyez des bottes de pluie avec Météo et tenue et laissez-le vivre son enfance.', title_hi = 'पानी के गड्ढों का शिकारी 🌧️', body_hi = 'बारिश के बाद बाहर निकलीं और वह सीधे कीचड़ भरे गड्ढे में कूद गया? कपड़े सन गए, लेकिन उसकी आँखों में खोज की वह चमक देखिए। मौसम और कपड़े टूल देखकर पहले से रबर के जूते पहनाने की योजना बनाइए, उसे अपना बचपन जीने दीजिए।', title_id = 'Pemburu genangan 🌧️', body_id = 'Keluar rumah setelah hujan dan ia langsung melompat ke genangan berlumpur? Bajunya kotor semua, tetapi lihat binar penemuan di matanya. Rencanakan sepatu bot karet sejak awal lewat alat Cuaca dan Pakaian, dan biarkan ia menikmati masa kecilnya.', title_ja = '水たまりハンター 🌧️', body_ja = '雨上がりに外へ出たら、どろどろの水たまりにまっすぐジャンプ？全身どろんこでも、その目にかがやく発見の光を見てください。「天気と服装」で、前もってレインブーツをはかせる計画を立てて、子ども時代を楽しませてあげましょう。', title_ko = '물웅덩이 사냥꾼 🌧️', body_ko = '비 온 뒤 밖에 나갔더니 곧장 진흙 웅덩이로 뛰어들었나요? 옷은 엉망이지만 눈 속의 발견의 빛을 보세요. 날씨와 옷차림을 보고 미리 장화를 신겨 두고, 마음껏 어린 시절을 누리게 해 주세요.', title_nl = 'Plassenjager 🌧️', body_nl = 'Gingen jullie na de regen naar buiten en sprong hij recht in een modderplas? Hij zit onder, maar kijk naar dat licht van ontdekking in zijn ogen. Plan via Weer en kleding vooraf regenlaarzen en laat hem kind zijn.', title_pl = 'Łowca kałuż 🌧️', body_pl = 'Wyszliście po deszczu, a on wskoczył prosto w błotnistą kałużę? Cały się ubrudził, ale spójrz na ten blask odkrywcy w jego oczach. Zaplanuj w Pogodzie i ubiorze wcześniej kalosze i pozwól mu przeżywać dzieciństwo.', title_pt = 'Caçador de poças 🌧️', body_pt = 'Saíram depois da chuva e ele saltou direitinho para uma poça de lama? Ficou todo sujo, mas olhe para aquela luz de descoberta nos olhos dele. No Tempo e Roupa, planeie de antemão as galochas e deixe-o viver a infância.', title_sv = 'Pöljägare 🌧️', body_sv = 'Gick ni ut efter regnet och barnet hoppade rakt ner i en lerig pöl? Kläderna blev smutsiga, men titta på upptäckarglöden i barnets ögon. Planera gummistövlar i förväg med Väder och kläder och låt barnet få vara barn.', title_vi = 'Thợ săn vũng nước 🌧️', body_vi = 'Ra ngoài sau cơn mưa và bé nhảy thẳng vào vũng nước bùn? Người ngợm lấm lem, nhưng hãy nhìn ánh sáng khám phá trong mắt bé. Hãy lên kế hoạch trước với Thời tiết và trang phục, cho bé đi ủng cao su và để bé sống trọn tuổi thơ.', title_zh = '水坑猎人 🌧️', body_zh = '雨后出门，宝宝直接跳进了泥水坑？全身都脏了，可看看宝宝眼里那道发现的光芒。提前用天气穿衣工具计划好穿上雨靴，让宝宝好好享受童年吧。' WHERE id = 'acd26d8c-d24f-4082-9973-a1110aefb638' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las buenas noches de los juguetes 🧸', body_es = 'Es hora de ir a la cama, pero se despide uno a uno de cada coche y cada osito de la habitación. Es una obra maestra del arte de retrasar el sueño. Pon un temporizador y aplica la regla: «En 3 minutos nos despedimos de todos a la vez».', title_fr = 'Bonne nuit les jouets 🧸', body_fr = 'C''est l''heure d''aller au lit, mais il dit au revoir une à une à chaque voiture et chaque peluche de la chambre. C''est un chef-d''œuvre dans l''art de retarder le sommeil. Réglez un minuteur et appliquez la règle : « Dans 3 minutes, on dit au revoir à tout le monde en même temps. »', title_hi = 'खिलौनों को गुड नाइट 🧸', body_hi = 'सोने का समय है, लेकिन वह कमरे की हर गाड़ी और हर टेडी को एक-एक करके अलविदा कहता है? यह नींद टालने की कला का बेहतरीन नमूना है। टाइमर लगाइए और ''हम 3 मिनट में सबको एक साथ बाय कहेंगे'' वाला नियम अपनाइए।', title_id = 'Selamat malam, mainan 🧸', body_id = 'Sudah waktunya tidur, tetapi ia berpamitan satu per satu pada setiap mobil-mobilan dan boneka beruang di kamar. Ini karya agung seni menunda tidur. Pasang timer dan terapkan aturan ''Dalam 3 menit kita bilang selamat malam ke semuanya sekaligus''.', title_ja = 'おもちゃたちにおやすみ 🧸', body_ja = '寝る時間なのに、部屋のくるまやくまさんに一つひとつバイバイしていますか？眠りを遅らせる技の傑作です。タイマーをセットして、「3分後にみんなに一緒におやすみを言おう」のルールにしましょう。', title_ko = '장난감들아, 잘 자 🧸', body_ko = '잘 시간인데 방 안의 자동차와 곰 인형 하나하나에게 인사하나요? 잠을 미루는 기술의 걸작이에요. 타이머를 맞추고 ''3분 뒤에 모두에게 한꺼번에 잘 자 인사하기'' 규칙을 정해 보세요.', title_nl = 'Welterusten tegen het speelgoed 🧸', body_nl = 'Het is bedtijd, maar hij zegt elk autootje en elke beer in de kamer één voor één gedag. Een meesterwerk in het uitstellen van de slaap. Zet een timer en voer de regel in: ''Over 3 minuten zeggen we iedereen tegelijk gedag.''', title_pl = 'Dobranoc, zabawki 🧸', body_pl = 'Czas do łóżka, ale on żegna się po kolei z każdym samochodzikiem i misiem w pokoju. To arcydzieło sztuki opóźniania snu. Nastaw timer i wprowadź zasadę: „Za 3 minuty mówimy dobranoc wszystkim naraz”.', title_pt = 'Boa noite aos brinquedos 🧸', body_pt = 'É hora de ir para a cama, mas ele despede-se um a um de cada carrinho e ursinho do quarto. É a obra-prima da arte de atrasar o sono. Programe um temporizador e aplique a regra: "Daqui a 3 minutos dizemos adeus a todos ao mesmo tempo."', title_sv = 'Leksakernas godnatt 🧸', body_sv = 'Det är dags att lägga sig, men barnet säger hejdå till varje bil och nalle i rummet, en i taget. Det är mästerverket i konsten att skjuta upp sömnen. Ställ in en timer och inför regeln ”Om 3 minuter säger vi godnatt till alla samtidigt”.', title_vi = 'Chúc đồ chơi ngủ ngon 🧸', body_vi = 'Đến giờ đi ngủ, nhưng bé chào tạm biệt từng chiếc ô tô, từng chú gấu trong phòng. Đây là kiệt tác của nghệ thuật trì hoãn giấc ngủ. Hãy đặt hẹn giờ và áp dụng quy tắc "3 phút nữa mình chào tất cả cùng lúc nhé".', title_zh = '和玩具们说晚安 🧸', body_zh = '该上床了，宝宝却要和房间里的每辆小汽车、每只小熊一个个说再见。这是拖延睡觉艺术的杰作。设个计时器，定下“3分钟后我们一起跟大家说再见”的规则。' WHERE id = 'b17158eb-f894-42c6-8d84-cab6d30d297a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El objeto más raro 🥄', body_es = 'Con tantos juguetes caros, ha encontrado un cucharón en la cocina y se pasa la noche paseándolo y acostándolo. Las fijaciones del cerebro infantil no tienen explicación. No intervengas, deja que le dé amor a ese cucharón.', title_fr = 'L''objet le plus bizarre 🥄', body_fr = 'Il a plein de jouets coûteux, mais il a trouvé une louche dans la cuisine et la promène toute la soirée, il la fait même dormir. Les objets fétiches d''un cerveau d''enfant sont inexplicables. Ne l''en empêchez pas, laissez-le donner son amour à cette louche.', title_hi = 'सबसे अजीब चीज़ 🥄', body_hi = 'इतने महँगे खिलौने हैं, लेकिन वह रसोई से एक करछी ढूँढ लाया और पूरी शाम उसे लेकर घूमता है, उसे सुलाता है। बच्चे के दिमाग की पसंद समझ से परे है। मत रोकिए, उसे उस करछी पर प्यार लुटाने दीजिए।', title_id = 'Benda paling aneh 🥄', body_id = 'Padahal ada begitu banyak mainan mahal, ia malah menemukan sendok sayur di dapur, membawanya ke mana-mana sepanjang malam, dan menidurkannya. Kesukaan otak anak memang tak bisa dijelaskan. Jangan halangi, biarkan ia menyayangi sendok sayur itu.', title_ja = 'いちばんふしぎなもの 🥄', body_ja = '高いおもちゃがたくさんあるのに、キッチンからおたまを見つけて、一晩じゅう持ち歩いて寝かしつけていますか？子どもの脳のこだわりは説明できません。じゃまをせず、おたまを好きにさせてあげましょう。', title_ko = '가장 별난 물건 🥄', body_ko = '비싼 장난감이 그렇게 많은데 주방에서 국자를 찾아 저녁 내내 들고 다니며 재우기까지 하나요? 아이 마음이 끌리는 대상은 설명할 수가 없어요. 방해하지 말고 그 국자를 마음껏 사랑하게 두세요.', title_nl = 'Het vreemdste voorwerp 🥄', body_nl = 'Al dat dure speelgoed, en hij vindt een soeplepel in de keuken en sjouwt er de hele avond mee rond en legt hem te slapen. De voorkeuren van een kinderbrein zijn onverklaarbaar. Stoor hem niet, laat hem lekker van die soeplepel houden.', title_pl = 'Najdziwniejszy przedmiot 🥄', body_pl = 'Ma tyle drogich zabawek, a znalazł w kuchni chochlę i cały wieczór z nią chodzi i ją usypia. Fascynacje dziecięcego mózgu są niewytłumaczalne. Nie przeszkadzaj, niech obdarza tę chochlę miłością.', title_pt = 'O objeto mais estranho 🥄', body_pt = 'Há tantos brinquedos caros, mas ele foi buscar uma concha à cozinha e anda com ela a noite toda, até a põe a dormir. As paixões do cérebro de uma criança são inexplicáveis. Não interfira, deixe-o dar amor à concha.', title_sv = 'Det märkligaste föremålet 🥄', body_sv = 'Det finns så många dyra leksaker, men barnet har hittat en slev i köket, går omkring med den hela kvällen och nattar den. Barnhjärnans fixeringar går inte att förklara. Hindra inte, låt barnet ge sleven kärlek.', title_vi = 'Món đồ kỳ lạ nhất 🥄', body_vi = 'Có biết bao đồ chơi đắt tiền, vậy mà bé tìm được chiếc muôi trong bếp, mang theo cả buổi tối và còn ru nó ngủ. Những niềm say mê của trí óc trẻ thơ thật khó giải thích. Đừng ngăn bé, cứ để bé trao tình yêu cho chiếc muôi ấy.', title_zh = '最奇怪的心头好 🥄', body_zh = '明明有那么多昂贵的玩具，宝宝却从厨房找来一把汤勺，一整晚都带着它走，还哄它睡觉。孩子大脑的这些执着真是没法解释。别阻止，就让宝宝去爱那把汤勺吧。' WHERE id = '3b1d044a-5917-48bd-b4f3-847b5ba6d5db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cirujano de la sopa 🥣', body_es = 'No se come la comida: solo aparta con precisión de cirujano los trocitos de cebolla o los granos de arroz. Es hora de hacer puré las verduras y volverlas invisibles. Echa un vistazo en Recetas saludables a las recetas más creativas de las madres con verduras escondidas.', title_fr = 'Le chirurgien de la soupe 🥣', body_fr = 'Il ne mange pas, il met juste de côté les petits morceaux d''oignon ou les grains de riz avec une précision de chirurgien. Il est temps de réduire les légumes en purée pour les rendre invisibles. Jetez un œil dans les Recettes saines aux recettes de mamans les plus créatives, aux légumes cachés.', title_hi = 'सूप का सर्जन 🥣', body_hi = 'खाना खाता नहीं, बस उसमें से प्याज़ के छोटे टुकड़े या चावल के दाने सर्जन जैसी बारीकी से अलग करता है? सब्ज़ियों को प्यूरी बनाकर गायब करने का समय आ गया है। सेहतमंद रेसिपी में माँओं की सबसे रचनात्मक, छिपी सब्ज़ियों वाली रेसिपी देखिए।', title_id = 'Ahli bedah di dalam sup 🥣', body_id = 'Ia tidak memakan makanannya, hanya menyisihkan potongan kecil bawang atau butir nasi dengan ketelitian ahli bedah. Saatnya menghaluskan sayuran agar tak terlihat. Lihat resep sayuran tersembunyi paling kreatif dari para ibu di Resep Sehat.', title_ja = 'スープの中の外科医 🥣', body_ja = 'ごはんを食べずに、小さな玉ねぎやお米の粒を外科医のような正確さでよけていますか？野菜をピューレにして見えなくするときです。「ヘルシーレシピ」で、ママたちのいちばん独創的な野菜かくしレシピをのぞいてみましょう。', title_ko = '수프 속 외과 의사 🥣', body_ko = '밥은 안 먹고 그 속의 작은 양파나 밥알만 외과 의사처럼 골라내나요? 채소를 퓌레로 만들어 감쪽같이 숨길 때예요. 건강한 레시피에서 엄마들의 가장 창의적인 채소 숨기기 레시피를 살펴보세요.', title_nl = 'De chirurg in de soep 🥣', body_nl = 'Hij eet niet, maar haalt met chirurgische precisie de stukjes ui of rijstkorrels uit zijn eten. Tijd om groenten te pureren en onzichtbaar te maken. Bekijk in Gezonde recepten de creatiefste recepten van moeders met verstopte groenten.', title_pl = 'Chirurg w zupie 🥣', body_pl = 'Nie je, tylko z chirurgiczną precyzją odkłada na bok małe kawałki cebuli czy ziarenka ryżu. Czas zmiksować warzywa i uczynić je niewidzialnymi. Zajrzyj do Zdrowych przepisów po najbardziej kreatywne przepisy mam z ukrytymi warzywami.', title_pt = 'O cirurgião da sopa 🥣', body_pt = 'Não come, só separa com precisão de cirurgião os pedacinhos de cebola ou os grãos de arroz. Está na altura de fazer puré dos legumes e torná-los invisíveis. Veja nas Receitas Saudáveis as receitas mais criativas das mães, com legumes escondidos.', title_sv = 'Kirurgen i soppan 🥣', body_sv = 'Barnet äter inte maten utan sorterar bara bort de små lökbitarna eller riskornen med kirurgisk precision. Det är dags att mosa grönsakerna och göra dem osynliga. Titta på mammornas mest kreativa recept med gömda grönsaker i Hälsosamma recept.', title_vi = 'Bác sĩ phẫu thuật trong bát canh 🥣', body_vi = 'Bé không ăn mà chỉ tách những mẩu hành nhỏ hay hạt cơm ra với độ chính xác của bác sĩ phẫu thuật. Đã đến lúc xay nhuyễn rau để chúng "tàng hình". Hãy xem trong Công thức lành mạnh những công thức giấu rau sáng tạo nhất của các mẹ.', title_zh = '汤里的外科医生 🥣', body_zh = '不吃饭，只是用外科医生般的精准，把里面的小洋葱块或米粒挑到一边。是时候把蔬菜做成泥，让它们“隐身”了。去健康食谱里看看妈妈们最有创意、藏着蔬菜的食谱吧。' WHERE id = '498b3498-4fee-4a00-9b62-ebe43844ae53' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El armario lo abro yo! 🚪', body_es = '¿Esta mañana lloró porque abriste tú la puerta del armario, te hizo cerrarla y la abrió él? Sí, el control tiene que ser todo suyo. Sonríe ante estos intentos inocentes de «lo hago yo»: está poniendo a prueba su voluntad.', title_fr = 'C''est moi qui ouvre le placard ! 🚪', body_fr = 'Ce matin, il a pleuré parce que c''est vous qui avez ouvert la porte du placard, vous a fait la refermer pour l''ouvrir lui-même ? Oui, le contrôle doit être entièrement à lui. Souriez à ces tentatives innocentes de « c''est moi qui fais », il teste sa volonté.', title_hi = 'अलमारी मैं खोलूँगा! 🚪', body_hi = 'सुबह अलमारी का दरवाज़ा आपने खोल दिया, इसलिए रोते हुए फिर से बंद करवाया और खुद खोला? हाँ, नियंत्रण पूरी तरह उसके हाथ में होना चाहिए। ''मैं करूँगा'' वाली इन मासूम कोशिशों पर मुस्कुराइए, वह अपनी इच्छा-शक्ति परख रहा है।', title_id = 'Lemarinya aku yang buka! 🚪', body_id = 'Pagi ini ia menangis karena Anda yang membuka pintu lemari, menyuruh Anda menutupnya lagi, lalu membukanya sendiri? Ya, kendali harus sepenuhnya di tangannya. Tersenyumlah pada usaha polos ''aku yang melakukannya'' ini, ia sedang menguji kemauannya.', title_ja = '戸棚はわたしが開ける！🚪', body_ja = '朝、あなたが戸棚を開けたからと泣いて、もう一度閉めさせて自分で開けましたか？そう、主導権は完全にお子さんにないといけないのです。この無邪気な「自分でやる」にほほえみましょう、意志を試しているのです。', title_ko = '옷장은 내가 열래! 🚪', body_ko = '아침에 엄마가 옷장 문을 열었다고 울면서 다시 닫게 하고 자기가 열었나요? 네, 주도권은 완전히 아이에게 있어야 해요. 이 순수한 ''내가 할래'' 시도에 웃어 주세요. 자기 의지를 시험하는 중이에요.', title_nl = 'Ik doe de kast open! 🚪', body_nl = 'Liet hij je vanochtend huilend de kastdeur weer dichtdoen omdat jij hem had geopend, zodat hij hem zelf kon openen? Ja, de controle moet helemaal bij hem liggen. Glimlach om deze onschuldige ''ik doe het''-pogingen, hij test zijn wil.', title_pl = 'Ja otworzę szafkę! 🚪', body_pl = 'Rano płakał, bo to ty otworzyłaś drzwi szafy, kazał je zamknąć i otworzył sam? Tak, kontrola musi być całkowicie po jego stronie. Uśmiechaj się na te niewinne próby „ja to zrobię”, on testuje swoją wolę.', title_pt = 'Eu é que abro o armário! 🚪', body_pt = 'Esta manhã chorou porque foi a mãe que abriu a porta do armário, obrigou-a a fechá-la e abriu-a ele? Sim, o controlo tem de ser todo dele. Sorria a estas tentativas inocentes de "eu faço": está a testar a sua vontade.', title_sv = 'Jag öppnar skåpet! 🚪', body_sv = 'Grät barnet i morse för att du öppnade skåpdörren, fick dig att stänga den och öppnade den sedan själv? Ja, barnet måste ha full kontroll. Le åt de oskyldiga ”jag gör det”-försöken, hen testar sin vilja.', title_vi = 'Con tự mở tủ! 🚪', body_vi = 'Sáng nay vì mẹ mở cửa tủ mà bé khóc, bắt mẹ đóng lại để bé tự mở? Đúng vậy, quyền kiểm soát phải hoàn toàn thuộc về bé. Hãy mỉm cười với những nỗ lực "con tự làm" ngây thơ này, bé đang thử ý chí của mình.', title_zh = '柜子要我来开！🚪', body_zh = '早上因为是你打开了柜门，宝宝就哭着让你关上，再自己打开？没错，掌控权必须完全在宝宝手里。笑着看待这些天真的“我来做”的尝试吧，宝宝在测试自己的意志。' WHERE id = 'a13e9959-a476-4e99-9da8-13f5bff68864' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No tienes por qué hacerlo todo tú. Esta noche deja por completo a papá lavarle los dientes y ponerle el pijama, y míralo desde fuera.', body_fr = 'Vous n''êtes pas obligée de tout faire. Ce soir, confiez entièrement à papa le brossage des dents et le pyjama, et observez de loin.', body_hi = 'आपको सब कुछ खुद करने की ज़रूरत नहीं है। आज शाम ब्रश कराना और पजामा पहनाना पूरी तरह पापा को सौंपिए और दूर से देखिए।', body_id = 'Anda tidak harus melakukan semuanya sendiri. Malam ini serahkan sepenuhnya urusan sikat gigi dan memakai piyama kepada Ayah, dan saksikan dari jauh.', body_ja = 'なんでもあなたがやらなくていいんです。今夜は歯みがきとパジャマの着がえをすべてパパにバトンタッチして、少し離れて見守りましょう。', body_ko = '모든 걸 엄마가 할 필요는 없어요. 오늘 저녁 양치와 잠옷 입히기는 모두 아빠에게 맡기고 옆에서 지켜보세요.', body_nl = 'Je hoeft niet alles zelf te doen. Geef het tandenpoetsen en de pyjama aantrekken vanavond helemaal aan papa en kijk vanaf de zijlijn toe.', body_pl = 'Nie musisz robić wszystkiego sama. Dziś wieczorem przekaż całkowicie tacie mycie zębów i przebieranie w piżamę, a ty patrz z boku.', body_pt = 'Não tem de fazer tudo sozinha. Esta noite, entregue por completo ao pai a escovagem dos dentes e o pijama e observe de longe.', body_sv = 'Du måste inte göra allt själv. Lämna över tandborstning och pyjamas helt till pappa i kväll och titta på från sidan.', body_vi = 'Mẹ không cần phải làm tất cả. Tối nay hãy giao hoàn toàn việc đánh răng và thay đồ ngủ cho bố và đứng ngoài quan sát.', body_zh = '你不必什么都自己来。今晚把刷牙、换睡衣全都交给爸爸，你在一旁看着就好。' WHERE id = 'f7c61cc4-7a2d-48d0-bf89-ec947a89cd75' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La medida digital del silencio 🤫', body_es = '¡Por fin se ha dormido! No te crees el silencio que ha caído sobre la casa. Activa el Medidor de sonido y, mirando esos 0-10 decibelios en la pantalla, siente cómo tu cerebro descansa y se recarga poco a poco.', title_fr = 'La mesure numérique du silence 🤫', body_fr = 'Il s''est enfin endormi ! Vous n''en revenez pas du silence qui règne dans la maison. Activez le Sonomètre, regardez ce chiffre de 0 à 10 décibels à l''écran et sentez votre cerveau se reposer et se recharger peu à peu.', title_hi = 'खामोशी का डिजिटल माप 🤫', body_hi = 'आखिरकार वह सो गया! घर में छाई खामोशी पर यकीन नहीं हो रहा? साउंड मीटर टूल चालू कीजिए और स्क्रीन पर 0-10 डेसिबल का अंक देखते हुए महसूस कीजिए कि आपका दिमाग धीरे-धीरे आराम कर रहा है, चार्ज हो रहा है।', title_id = 'Ukuran digital keheningan 🤫', body_id = 'Ia akhirnya tertidur! Anda tidak percaya pada keheningan yang menyelimuti rumah. Aktifkan Pengukur Suara, lihat angka 0-10 desibel di layar, dan rasakan otak Anda perlahan beristirahat dan terisi ulang.', title_ja = '静けさのデジタル測定 🤫', body_ja = 'やっと眠りました！家を包む静けさが信じられませんね。「サウンドメーター」をオンにして、画面の0〜10デシベルの数字を見ながら、頭が少しずつ休まり、充電されていくのを感じましょう。', title_ko = '고요를 숫자로 확인해요 🤫', body_ko = '드디어 잠들었어요! 집에 내려앉은 고요가 믿기지 않죠. 소음 측정기를 켜고 화면 속 0~10데시벨 숫자를 보며 머리가 천천히 쉬고 충전되는 걸 느껴 보세요.', title_nl = 'De digitale maat van stilte 🤫', body_nl = 'Hij slaapt eindelijk! Je kunt de stilte in huis bijna niet geloven. Zet de Geluidsmeter aan, kijk naar die 0-10 decibel op het scherm en voel hoe je hoofd langzaam tot rust komt en oplaadt.', title_pl = 'Cyfrowa miara ciszy 🤫', body_pl = 'W końcu zasnął! Nie możesz uwierzyć w ciszę, która zapadła w domu. Włącz Miernik dźwięku, patrz na ekranie na te 0-10 decybeli i poczuj, jak twoja głowa powoli odpoczywa i się ładuje.', title_pt = 'A medida digital do silêncio 🤫', body_pt = 'Finalmente adormeceu! Nem acredita no silêncio que caiu sobre a casa. Ative o Medidor de Som e, a olhar para aqueles 0-10 decibéis no ecrã, sinta o cérebro a descansar e a recarregar aos poucos.', title_sv = 'Tystnaden i siffror 🤫', body_sv = 'Barnet har äntligen somnat! Du kan inte tro på tystnaden som lagt sig över hemmet. Aktivera Ljudmätaren, titta på siffran 0-10 decibel på skärmen och känn hur hjärnan sakta vilar och laddas.', title_vi = 'Thước đo kỹ thuật số của sự tĩnh lặng 🤫', body_vi = 'Cuối cùng bé cũng ngủ! Mẹ không tin nổi sự yên tĩnh đang bao trùm căn nhà. Hãy bật công cụ Đo âm thanh, nhìn con số 0-10 decibel trên màn hình và cảm nhận đầu óc mình đang dần được nghỉ ngơi, nạp lại năng lượng.', title_zh = '安静的数字度量 🤫', body_zh = '宝宝终于睡着了！你都不敢相信家里这么安静。打开分贝仪，看着屏幕上0到10分贝的数字，感受大脑正在慢慢放松、充电。' WHERE id = '0a4a5638-968e-4cce-9213-12c0072354c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El golpe del «¡Eres una mamá mala!» 💔', body_es = '¿Te ha dicho «eres mala» porque no le diste el caramelo que quería? Que no se te rompa el corazón. Todavía no sabe expresar lo que siente con las palabras adecuadas; en realidad quiere decir «estoy muy enfadado». Míralo a los ojos y acepta su emoción.', title_fr = 'Le coup du « T''es une méchante maman ! » 💔', body_fr = 'Il vous a dit « T''es méchante » parce que vous ne lui avez pas donné le bonbon qu''il voulait ? Ne vous laissez pas briser le cœur. Il ne sait pas encore exprimer ses émotions avec les bons mots, il veut en fait dire « Je suis très en colère ». Regardez-le dans les yeux et accueillez son émotion.', title_hi = '''तुम बुरी मम्मी हो!'' वाला वार 💔', body_hi = 'मनचाही टॉफ़ी नहीं दी, इसलिए आपसे कहा ''तुम बुरी हो''? दिल मत तोड़िए। वह अभी अपनी भावनाएँ सही शब्दों में नहीं कह पाता, असल में वह कहना चाहता है ''मुझे बहुत गुस्सा आ रहा है''। आँखों में आँखें डालकर उसकी भावना को स्वीकार कीजिए।', title_id = 'Pukulan ''Ibu jahat!'' 💔', body_id = 'Ia bilang ''Ibu jahat'' karena Anda tidak memberinya permen yang ia mau? Jangan sakit hati. Ia belum bisa mengungkapkan perasaannya dengan kata yang tepat, sebenarnya ia ingin bilang ''Aku kesal sekali''. Tatap matanya dan terima perasaannya.', title_ja = '「ママなんてきらい！」の一撃 💔', body_ja = 'ほしいキャンディーをあげなかったから「ママ、いじわる」と言われましたか？傷つかないで。まだ気持ちを正しい言葉で表せず、本当は「すごく怒ってるの」と言いたいのです。目を合わせて、気持ちを受け止めましょう。', title_ko = '''엄마 나빠!'' 한 방 💔', body_ko = '원하는 사탕을 안 줬다고 ''엄마 나빠''라고 했나요? 상처받지 마세요. 아직 감정을 알맞은 말로 표현하지 못하는 거예요. 사실은 ''나 너무 화났어''라는 뜻이에요. 눈을 맞추고 감정을 받아 주세요.', title_nl = 'De klap van ''Jij bent een stomme mama!'' 💔', body_nl = 'Zei hij ''Jij bent stom'' omdat je hem het snoepje niet gaf? Laat je hart niet breken. Hij kan zijn gevoelens nog niet in de juiste woorden uitdrukken; eigenlijk bedoelt hij ''Ik ben heel boos''. Maak oogcontact en erken zijn gevoel.', title_pl = 'Cios „Jesteś złą mamą!” 💔', body_pl = 'Powiedział ci „Jesteś zła”, bo nie dałaś mu cukierka? Nie pozwól, by złamało ci to serce. Jeszcze nie umie wyrazić uczuć właściwymi słowami, tak naprawdę chce powiedzieć „Jestem bardzo zdenerwowany”. Nawiąż kontakt wzrokowy i przyjmij jego emocję.', title_pt = 'O golpe do "És uma mãe má!" 💔', body_pt = 'Disse-lhe "és má" porque não lhe deu o rebuçado que queria? Não fique de coração partido. Ainda não consegue exprimir o que sente com as palavras certas; na verdade, quer dizer "estou muito irritado". Olhe-o nos olhos e aceite a emoção dele.', title_sv = 'Slaget ”Du är en dum mamma!” 💔', body_sv = 'Sa barnet ”du är dum” för att du inte gav hen godiset hen ville ha? Låt inte hjärtat brista. Barnet kan ännu inte uttrycka sina känslor med rätt ord, egentligen vill hen säga ”jag är väldigt arg”. Skapa ögonkontakt och ta emot känslan.', title_vi = 'Cú đánh "Mẹ xấu!" 💔', body_vi = 'Mẹ không cho kẹo nên bé nói "Mẹ xấu lắm"? Đừng buồn lòng. Bé chưa thể diễn đạt cảm xúc bằng từ ngữ đúng, thật ra bé muốn nói "Con đang bực lắm". Hãy nhìn vào mắt bé và chấp nhận cảm xúc của bé.', title_zh = '“你是坏妈妈！”的一击 💔', body_zh = '因为没给想要的糖果，就对你说“你是坏人”？别伤心。宝宝还不会用恰当的词表达感受，其实是想说“我太生气了”。和宝宝对视，接纳宝宝的情绪。' WHERE id = 'b5cfbb8a-14cd-4f76-bc5c-26b6d0b9418a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla con una hormiga invisible 🐜', body_es = '¿En el balcón o en el parque se agacha sobre una hormiga del suelo y le habla muy en serio? Su imaginación y su compasión funcionan a la vez. Captura ya este gran momento con la Sesión de fotos del bebé y guárdalo en el rincón más dulce del archivo.', title_fr = 'Conversation avec une fourmi invisible 🐜', body_fr = 'Sur le balcon ou au parc, il se penche vers une fourmi et lui parle très sérieusement ? L''imagination et la compassion fonctionnent en même temps. Immortalisez vite ce moment magnifique avec la Séance photo bébé et rangez-le dans le coin le plus tendre de vos archives.', title_hi = 'अदृश्य चींटी से बातें 🐜', body_hi = 'बालकनी या पार्क में ज़मीन पर एक चींटी की ओर झुककर बहुत गंभीरता से कुछ कह रहा है? कल्पना और दया का भाव एक साथ काम कर रहे हैं। इस शानदार पल को तुरंत बेबी फ़ोटोशूट से कैद कीजिए और एल्बम के सबसे प्यारे कोने में रखिए।', title_id = 'Mengobrol dengan semut 🐜', body_id = 'Di balkon atau di taman ia membungkuk ke arah seekor semut dan berbicara dengan sangat serius? Imajinasi dan rasa belas kasihnya bekerja bersamaan. Segera abadikan momen hebat ini lewat Pemotretan Bayi dan simpan di sudut arsip yang paling manis.', title_ja = '見えないありさんとおしゃべり 🐜', body_ja = 'ベランダや公園で地面のありにかがみこんで、とても真剣に何か話していますか？想像力と思いやりが同時に働いています。このすばらしい瞬間をすぐに「ベビーフォトセッション」で撮って、アルバムのいちばんかわいいコーナーに残しましょう。', title_ko = '개미와 나누는 대화 🐜', body_ko = '베란다나 공원에서 개미에게 몸을 숙이고 아주 진지하게 이야기하나요? 상상력과 배려심이 함께 자라고 있어요. 이 멋진 순간을 아기 사진 촬영으로 담아 앨범의 가장 사랑스러운 자리에 두세요.', title_nl = 'Gesprek met een onzichtbare mier 🐜', body_nl = 'Buigt hij op het balkon of in het park over een mier en praat hij er heel serieus tegen? Fantasie en medeleven werken tegelijk. Leg dit prachtige moment meteen vast met Babyfotoshoot en geef het een plekje in het liefste hoekje van je archief.', title_pl = 'Rozmowa z niewidzialną mrówką 🐜', body_pl = 'Na balkonie albo w parku pochyla się nad mrówką i bardzo poważnie coś jej opowiada? Wyobraźnia i współczucie działają jednocześnie. Od razu uwiecznij tę wspaniałą chwilę w Sesji zdjęciowej dziecka i umieść ją w najsłodszym zakątku archiwum.', title_pt = 'Conversa com uma formiga invisível 🐜', body_pt = 'Na varanda ou no parque, baixa-se para uma formiga no chão e conversa com ela muito a sério? A imaginação e a compaixão funcionam ao mesmo tempo. Fotografe já este momento fantástico com a Sessão Fotográfica e guarde-o no cantinho mais doce do arquivo.', title_sv = 'Samtal med en osynlig myra 🐜', body_sv = 'Böjer sig barnet ner över en myra på balkongen eller i parken och pratar på fullt allvar med den? Fantasin och medkänslan arbetar samtidigt. Fånga den fantastiska stunden direkt med Babyfotografering och lägg den i arkivets gulligaste hörn.', title_vi = 'Trò chuyện với chú kiến vô hình 🐜', body_vi = 'Ở ban công hay công viên, bé cúi xuống nói chuyện rất nghiêm túc với một chú kiến? Trí tưởng tượng và lòng trắc ẩn đang cùng hoạt động. Hãy chụp ngay khoảnh khắc tuyệt vời này bằng Chụp ảnh cho bé và cất vào góc ngọt ngào nhất của kho ảnh.', title_zh = '和看不见的蚂蚁聊天 🐜', body_zh = '在阳台或公园里蹲下来，一本正经地对着地上的蚂蚁说话？想象力和同情心同时在发挥作用。马上用宝宝写真拍下这个精彩时刻，放进相册里最可爱的角落吧。' WHERE id = 'fabd170d-dc89-4100-b9c1-3acf59e32a5c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Modo avión de papá ✈️', body_es = 'No ha podido soltar su energía en casa y se resiste a ir a la cama. Pide ayuda a papá. Cuando le levanta en el aire y le hace volar como un avión, las carcajadas llenan la habitación y todo el estrés físico acumulado desaparece en segundos.', title_fr = 'Papa en mode avion ✈️', body_fr = 'Il n''a pas pu se défouler à la maison et résiste au coucher. Appelez papa à la rescousse. Quand il le soulève et le fait voler comme un avion, les éclats de rire envahissent la pièce et tout le stress physique accumulé disparaît en quelques secondes.', title_hi = 'पापा का फ़्लाइट मोड ✈️', body_hi = 'घर में ऊर्जा नहीं निकल पाई और बिस्तर पर जाने से अड़ गया? पापा को मदद के लिए बुलाइए। जब वे बच्चे को हवा में उठाकर हवाई जहाज़ बनाते हैं, तो ठहाके कमरे में भर जाते हैं और जमा हुआ सारा शारीरिक तनाव कुछ ही सेकंड में गायब हो जाता है।', title_id = 'Mode terbang Ayah ✈️', body_id = 'Energinya belum tersalurkan di rumah dan ia menolak tidur. Panggil Ayah untuk membantu. Saat Ayah mengangkatnya tinggi dan menjadikannya pesawat, tawa memenuhi kamar dan semua stres fisik yang menumpuk lenyap dalam hitungan detik.', title_ja = 'パパの飛行機モード ✈️', body_ja = '家でエネルギーを出しきれず、ベッドに行くのを拒否していますか？パパに助けを呼びましょう。パパが高く持ち上げて飛行機にすると、部屋は笑い声に包まれ、たまった体のストレスは数秒で消えていきます。', title_ko = '아빠의 비행 모드 ✈️', body_ko = '집에서 에너지를 다 못 쓰고 자러 가지 않겠다고 버티나요? 아빠를 부르세요. 아빠가 아이를 높이 들어 비행기를 태워 주면 방에 웃음이 가득해지고, 쌓인 몸의 긴장이 순식간에 사라져요.', title_nl = 'Papa''s vliegmodus ✈️', body_nl = 'Is hij zijn energie thuis niet kwijtgeraakt en verzet hij zich tegen bedtijd? Roep papa te hulp. Als hij hem optilt en een vliegtuigje maakt, vult het gelach de kamer en verdwijnt alle opgebouwde fysieke stress in een paar seconden.', title_pl = 'Tryb samolotowy taty ✈️', body_pl = 'Nie zdążył w domu spalić energii i opiera się przed pójściem do łóżka. Wezwij tatę na pomoc. Gdy podnosi go w górę i robi z niego samolot, pokój wypełnia się śmiechem, a cały nagromadzony stres fizyczny znika w kilka sekund.', title_pt = 'O modo avião do pai ✈️', body_pt = 'Em casa não conseguiu gastar a energia e resiste a ir para a cama. Chame o pai para ajudar. Quando ele levanta a criança no ar e faz de avião, as gargalhadas enchem o quarto e todo o stress físico acumulado desaparece em segundos.', title_sv = 'Pappas flygläge ✈️', body_sv = 'Barnet har inte fått ut sin energi hemma och vägrar gå och lägga sig. Kalla på pappa. När han lyfter barnet i luften som ett flygplan fylls rummet av skratt och all ackumulerad fysisk stress försvinner på några sekunder.', title_vi = 'Chế độ máy bay của bố ✈️', body_vi = 'Bé chưa xả hết năng lượng và chống cự không chịu lên giường. Hãy gọi bố đến giúp. Khi bố nhấc bé lên cao làm máy bay, tiếng cười sẽ tràn ngập căn phòng và mọi căng thẳng thể chất tích tụ sẽ tan biến trong vài giây.', title_zh = '爸爸的飞行模式 ✈️', body_zh = '在家精力没用完，就是不肯上床。叫爸爸来帮忙。他把孩子举到空中当飞机时，笑声充满整个房间，积攒的身体紧张几秒钟就消失了。' WHERE id = 'a860534c-7167-4781-b298-8321127fd089' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libertad para revolcarse en el suelo 🌪️', body_es = '¿Se ha tirado al suelo en mitad del súper? No intentes levantarle ni dar explicaciones a los demás. Respira hondo. Cuando entres en la Comunidad Anacan verás que miles de madres viven este mismo momento, vergonzoso pero natural.', title_fr = 'La liberté de se rouler par terre 🌪️', body_fr = 'Il s''est jeté par terre en plein supermarché ? N''essayez pas de le relever ni de vous justifier auprès des autres. Respirez profondément. En rejoignant la Communauté Anacan, vous verrez que des milliers de mamans vivent ce même moment gênant, mais naturel.', title_hi = 'ज़मीन पर लोटने की आज़ादी 🌪️', body_hi = 'बाज़ार के बीच ज़मीन पर लोट गया? उसे उठाने या आसपास के लोगों को सफ़ाई देने की कोशिश मत कीजिए। गहरी साँस लीजिए। Anacan कम्युनिटी में जाएँगी तो देखेंगी कि हज़ारों माँएँ ऐसे ही शर्मिंदगी भरे, लेकिन स्वाभाविक पल से गुज़रती हैं।', title_id = 'Bebas berguling di lantai 🌪️', body_id = 'Ia menjatuhkan diri ke lantai di tengah supermarket? Jangan mencoba mengangkatnya atau menjelaskan kepada orang sekitar. Tarik napas dalam. Saat masuk ke Komunitas Anacan, Anda akan melihat ribuan ibu mengalami momen yang memalukan namun wajar ini.', title_ja = '床を転がる自由 🌪️', body_ja = 'スーパーの真ん中で床にひっくり返りましたか？抱き上げようとしたり、周りに説明しようとしたりしないで。深呼吸しましょう。Anacanコミュニティをのぞけば、何千人ものママが同じ恥ずかしくも自然な瞬間を経験していることがわかります。', title_ko = '바닥에 뒹굴 자유 🌪️', body_ko = '마트 한가운데서 바닥에 드러누웠나요? 일으켜 세우거나 주변에 설명하려 애쓰지 마세요. 깊게 숨 쉬세요. Anacan 커뮤니티에 들어가 보면 수많은 엄마들이 똑같이 민망하지만 자연스러운 순간을 겪고 있다는 걸 알게 될 거예요.', title_nl = 'De vrijheid om over de grond te rollen 🌪️', body_nl = 'Gooide hij zich midden in de supermarkt op de grond? Probeer hem niet op te tillen of uitleg te geven aan omstanders. Haal diep adem. In de Anacan Community zie je dat duizenden moeders hetzelfde gênante, maar natuurlijke moment meemaken.', title_pl = 'Wolność tarzania się po podłodze 🌪️', body_pl = 'Rzucił się na podłogę na środku sklepu? Nie próbuj go podnosić ani tłumaczyć się innym. Weź głęboki oddech. Gdy wejdziesz do Społeczności Anacan, zobaczysz, że tysiące mam przeżywają tę samą krępującą, ale naturalną chwilę.', title_pt = 'A liberdade de rebolar no chão 🌪️', body_pt = 'Atirou-se para o chão a meio do supermercado? Não tente levantá-lo nem dar explicações a quem está à volta. Respire fundo. Quando entrar na Comunidade Anacan, vai ver que milhares de mães vivem o mesmo momento embaraçoso, mas natural.', title_sv = 'Friheten att rulla på golvet 🌪️', body_sv = 'Har barnet kastat sig på golvet mitt i affären? Försök inte lyfta upp hen eller förklara dig för andra. Andas djupt. Går du in i Anacan Community ser du att tusentals mammor upplever samma pinsamma men naturliga stund.', title_vi = 'Tự do lăn trên sàn 🌪️', body_vi = 'Bé lăn ra sàn giữa siêu thị? Đừng cố kéo bé dậy hay giải thích với người xung quanh. Hãy hít thở sâu. Khi vào Cộng đồng Anacan, mẹ sẽ thấy hàng nghìn người mẹ cũng trải qua khoảnh khắc đáng xấu hổ nhưng rất tự nhiên này.', title_zh = '在地上打滚的自由 🌪️', body_zh = '在超市中间躺在地上闹？别急着把宝宝拉起来，也别忙着向旁人解释。深吸一口气。进入Anacan社区你就会发现，成千上万的妈妈都经历过这种尴尬却又自然的时刻。' WHERE id = 'e0e56f8d-3c51-4c46-90f2-dbfa90060519' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tozudez del «¡No me mires!» 🙈', body_es = '¿Llora diciendo «¡No me mires!» porque le has mirado sonriendo? ¡La cumbre de la lógica absurda! Gira la cara y espera a que se le pase este capricho tan gracioso; a veces ni ellos saben lo que quieren.', title_fr = 'L''entêtement du « Me regarde pas ! » 🙈', body_fr = 'Il pleure en disant « Me regarde pas ! » parce que vous l''avez regardé en souriant. Le sommet de la logique absurde ! Tournez la tête et attendez que ce drôle de caprice passe, parfois eux-mêmes ne savent pas ce qu''ils veulent.', title_hi = '''मुझे मत देखो!'' वाली ज़िद 🙈', body_hi = 'आपने उसे देखकर मुस्कुरा दिया, इसलिए ''मुझे मत देखो!'' कहकर रोने लगा? बेतुके तर्क की हद! चेहरा दूसरी ओर कीजिए और इस मज़ेदार नखरे के गुज़रने का इंतज़ार कीजिए, कभी-कभी उन्हें भी नहीं पता होता कि उन्हें क्या चाहिए।', title_id = 'Ngotot ''Jangan lihat aku!'' 🙈', body_id = 'Ia menangis dan berkata ''Jangan lihat aku!'' karena Anda menatapnya sambil tersenyum. Puncak logika absurd! Palingkan wajah Anda dan tunggu sampai rengekan lucu ini berlalu, kadang ia sendiri tidak tahu apa yang ia mau.', title_ja = '「見ないで！」のがんこさ 🙈', body_ja = 'あなたがほほえんだだけで、「見ないで！」と泣きますか？ふしぎな理屈の頂点！顔をそむけて、このおかしな気まぐれが過ぎるのを待ちましょう。ときには本人も何がしたいのかわかっていないのです。', title_ko = '''나 보지 마!'' 고집 🙈', body_ko = '엄마가 보고 웃었다고 ''나 보지 마!'' 하며 우나요? 황당한 논리의 절정이에요! 고개를 돌리고 이 웃긴 변덕이 지나가길 기다리세요. 가끔은 아이도 자기가 뭘 원하는지 몰라요.', title_nl = 'Koppig: ''Niet naar mij kijken!'' 🙈', body_nl = 'Huilt hij ''Niet naar mij kijken!'' omdat je glimlachend naar hem keek? Het toppunt van absurde logica! Draai je hoofd weg en wacht tot deze grappige gril voorbij is; soms weten ze zelf ook niet wat ze willen.', title_pl = 'Upór „Nie patrz na mnie!” 🙈', body_pl = 'Płacze i krzyczy „Nie patrz na mnie!”, bo spojrzałaś na niego z uśmiechem? Szczyt absurdalnej logiki! Odwróć twarz i poczekaj, aż ten zabawny kaprys minie, czasem one same nie wiedzą, czego chcą.', title_pt = 'A teimosia do "Não olhes para mim!" 🙈', body_pt = 'Chora e diz "Não olhes para mim!" só porque olhou para ele e sorriu? O auge da lógica absurda! Vire a cara para o lado e espere que este capricho cómico passe: às vezes nem eles sabem o que querem.', title_sv = 'Envisheten i ”Titta inte på mig!” 🙈', body_sv = 'Gråter barnet och säger ”Titta inte på mig!” för att du tittade på hen och log? Toppen av absurd logik! Vänd bort ansiktet och vänta tills det roliga nycket går över, ibland vet barnen inte själva vad de vill.', title_vi = 'Sự bướng bỉnh "Đừng nhìn con!" 🙈', body_vi = 'Bé khóc và nói "Đừng nhìn con!" chỉ vì mẹ nhìn bé và mỉm cười? Đỉnh cao của logic phi lý! Hãy quay mặt đi và chờ cơn nhõng nhẽo buồn cười này qua đi, đôi khi chính bé cũng không biết mình muốn gì.', title_zh = '“别看我！”的倔强 🙈', body_zh = '因为你看着宝宝笑了，宝宝就哭着说“别看我！”？荒唐逻辑的巅峰！把脸转到一边，等这个好笑的小脾气过去，有时他们自己也不知道想要什么。' WHERE id = 'e9ba4911-0212-43aa-9a51-c6bf942facb9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la voz de mamá 🎶', body_es = 'Esta noche no uses ningún aparato. Simplemente abrázale contra tu pecho y susúrrale al oído su nana favorita. Tu voz es su puerto más seguro.', title_fr = 'Le pouvoir de la voix de maman 🎶', body_fr = 'Ce soir, n''utilisez aucun outil. Serrez-le simplement contre vous et chuchotez-lui à l''oreille sa berceuse préférée. Votre voix est son port le plus sûr.', title_hi = 'माँ की आवाज़ की ताकत 🎶', body_hi = 'आज शाम किसी टूल का इस्तेमाल मत कीजिए। बस उसे सीने से लगाइए और उसकी सबसे पसंदीदा लोरी उसके कान में फुसफुसाइए। आपकी आवाज़ उसका सबसे सुरक्षित ठिकाना है।', title_id = 'Kekuatan suara Ibu 🎶', body_id = 'Malam ini jangan gunakan alat apa pun. Cukup dekap ia di dada dan bisikkan lagu nina bobo favoritnya di telinganya. Suara Anda adalah pelabuhan teramannya.', title_ja = 'ママの声の力 🎶', body_ja = '今夜はどんな道具も使わないで。ただ胸に抱きしめて、いちばん好きな子守歌を耳もとでささやいてあげましょう。あなたの声は、お子さんにとっていちばん安心できる港です。', title_ko = '엄마 목소리의 힘 🎶', body_ko = '오늘 저녁엔 어떤 기기도 쓰지 마세요. 그냥 꼭 끌어안고 가장 좋아하는 자장가를 귓가에 속삭여 주세요. 엄마의 목소리는 아이의 가장 안전한 항구예요.', title_nl = 'De kracht van mama''s stem 🎶', body_nl = 'Gebruik vanavond geen enkel hulpmiddel. Druk hem gewoon tegen je borst en fluister zijn lievelingsslaapliedje in zijn oor. Jouw stem is zijn veiligste haven.', title_pl = 'Moc głosu mamy 🎶', body_pl = 'Dziś wieczorem nie korzystaj z żadnych urządzeń. Po prostu przytul go mocno do piersi i wyszepcz mu do ucha jego ulubioną kołysankę. Twój głos to jego najbezpieczniejsza przystań.', title_pt = 'O poder da voz da mãe 🎶', body_pt = 'Esta noite, não use nenhum aparelho. Simplesmente aperte-o contra o peito e sussurre-lhe ao ouvido a canção de embalar preferida. A sua voz é o porto mais seguro dele.', title_sv = 'Kraften i mammas röst 🎶', body_sv = 'Använd inga hjälpmedel i kväll. Håll bara barnet tätt intill dig och viska hens favoritvaggvisa i örat. Din röst är barnets tryggaste hamn.', title_vi = 'Sức mạnh của giọng mẹ 🎶', body_vi = 'Tối nay đừng dùng bất kỳ thiết bị nào. Chỉ cần ôm bé vào lòng và thì thầm bên tai bé bài hát ru bé yêu thích nhất. Giọng của mẹ là bến đỗ an toàn nhất của bé.', title_zh = '妈妈声音的力量 🎶', body_zh = '今晚什么工具都别用。就把宝宝紧紧抱在怀里，在耳边轻轻哼唱宝宝最爱的摇篮曲。你的声音就是宝宝最安全的港湾。' WHERE id = '07c7c2cb-58bb-47db-ac0e-f81bd01e602b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apoyo pediátrico rápido 🤖', body_es = '¿Te preocupa su curva de talla y peso al acercarse a los 3 años? No pases horas buscando en internet: consulta ya en Anacan AI los valores precisos avalados por pediatras.', title_fr = 'Aide pédiatrique express 🤖', body_fr = 'Ses courbes de taille et de poids à l''approche des 3 ans vous inquiètent ? Ne cherchez pas des heures sur Internet, découvrez tout de suite avec Anacan AI les normes précises validées par des pédiatres.', title_hi = 'तुरंत बाल रोग विशेषज्ञ वाली मदद 🤖', body_hi = '3 साल के करीब बच्चे की लंबाई-वज़न का चार्ट चिंता में डाल रहा है? इंटरनेट पर घंटों मत खोजिए, Anacan AI से तुरंत सटीक और बाल रोग विशेषज्ञों से पुष्ट मानक जानिए।', title_id = 'Dukungan dokter anak kilat 🤖', body_id = 'Grafik tinggi dan berat badan anak menjelang usia 3 tahun membuat Anda cemas? Jangan mencari berjam-jam di internet, segera pelajari standar yang tepat dan disetujui dokter anak dari Anacan AI.', title_ja = 'すぐに頼れる小児科サポート 🤖', body_ja = '3歳が近づいて、身長や体重のグラフが気になりますか？ネットで何時間も調べないで、Anacan AIから正確で小児科医監修の目安をすぐに学びましょう。', title_ko = '빠른 소아과 도움 🤖', body_ko = '세 돌을 앞두고 아이의 키와 몸무게 그래프가 걱정되나요? 인터넷에서 몇 시간씩 찾지 말고 Anacan AI에게 정확하고 소아과 검증을 거친 기준을 바로 알아보세요.', title_nl = 'Snelle hulp van een kinderarts 🤖', body_nl = 'Maak je je richting 3 jaar zorgen over zijn lengte- en gewichtscurve? Zoek niet urenlang op internet, maar leer meteen de nauwkeurige, door kinderartsen goedgekeurde normen van Anacan AI.', title_pl = 'Szybkie wsparcie pediatry 🤖', body_pl = 'Niepokoją cię siatki wzrostu i wagi dziecka zbliżającego się do 3. roku życia? Nie szukaj godzinami w internecie, od razu poznaj dokładne, zatwierdzone przez pediatrów normy od Anacan AI.', title_pt = 'Apoio pediátrico rápido 🤖', body_pt = 'Perto dos 3 anos, as curvas de altura e peso do seu filho preocupam-na? Não passe horas a pesquisar na internet: conheça já no Anacan AI os valores de referência precisos e aprovados por pediatras.', title_sv = 'Snabbt stöd från barnläkare 🤖', body_sv = 'Oroar barnets längd- och viktkurva dig nu när hen närmar sig 3 år? Sök inte i timmar på nätet, ta direkt reda på exakta normer godkända av barnläkare från Anacan AI.', title_vi = 'Hỗ trợ nhi khoa nhanh chóng 🤖', body_vi = 'Biểu đồ chiều cao và cân nặng của bé gần 3 tuổi khiến mẹ lo lắng? Đừng mất hàng giờ tìm kiếm trên mạng, hãy hỏi ngay Anacan AI về các chỉ số chuẩn chính xác, được bác sĩ nhi khoa xác nhận.', title_zh = '快速的儿科支持 🤖', body_zh = '快3岁了，孩子的身高体重曲线让你担心？别在网上搜好几个小时，马上向Anacan AI了解准确、经儿科医生认可的标准吧。' WHERE id = '1acb826a-9b73-413f-b0af-4614a74084bd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sabe su nombre y su edad 🎂', body_es = '¿Cuando le preguntas «¿Cuántos años tienes?», intenta enseñarlo con los dedos? Su conciencia de sí mismo va de maravilla. Anota este salto intelectual en el Seguimiento del desarrollo.', title_fr = 'Il connaît son nom et son âge 🎂', body_fr = 'Quand on lui demande « Tu as quel âge ? », il essaie de le montrer avec ses doigts ? Sa conscience de soi est parfaite. Notez ce bond intellectuel dans le Suivi de développement.', title_hi = 'अपना नाम और उम्र जानता है 🎂', body_hi = '''तुम कितने साल के हो?'' पूछने पर उँगलियों से दिखाने की कोशिश करता है? खुद की पहचान की उसकी समझ कमाल की है। ग्रोथ ट्रैकर में इस बौद्धिक छलांग को दर्ज कीजिए।', title_id = 'Tahu nama dan usianya 🎂', body_id = 'Saat ditanya ''Umurmu berapa?'', ia mencoba menunjukkannya dengan jari? Kesadaran dirinya berkembang sempurna. Catat lompatan intelektual ini di Pelacak Perkembangan.', title_ja = '自分の名前と年齢がわかる 🎂', body_ja = '「何歳？」と聞くと、指で見せようとしますか？自己認識がすばらしく育っています。この知的な飛躍を「発達トラッカー」に記録しましょう。', title_ko = '이름과 나이를 알아요 🎂', body_ko = '''몇 살이야?'' 하고 물으면 손가락으로 보여 주려 하나요? 자아 인식이 멋지게 자라고 있어요. 성장 기록에 이 지적 도약을 남겨 두세요.', title_nl = 'Hij weet zijn naam en leeftijd 🎂', body_nl = 'Probeert hij met zijn vingers te laten zien hoe oud hij is als je het vraagt? Zijn zelfbewustzijn is geweldig. Noteer deze intellectuele sprong in de Groeitracker.', title_pl = 'Zna swoje imię i wiek 🎂', body_pl = 'Na pytanie „Ile masz lat?” próbuje pokazać na paluszkach? Jego poczucie tożsamości jest wspaniałe. Zapisz ten intelektualny skok w Śledzeniu rozwoju.', title_pt = 'Sabe o nome e a idade 🎂', body_pt = 'Quando lhe pergunta "Quantos anos tens?", tenta mostrar com os dedos? A consciência de si próprio está ótima. Registe este salto intelectual no Registo de Desenvolvimento.', title_sv = 'Barnet vet sitt namn och sin ålder 🎂', body_sv = 'Försöker barnet visa med fingrarna när du frågar ”Hur gammal är du?”? Självmedvetenheten är fantastisk. Anteckna det här intellektuella språnget i Utvecklingsspåraren.', title_vi = 'Bé biết tên và tuổi của mình 🎂', body_vi = 'Khi được hỏi "Con mấy tuổi?", bé cố giơ ngón tay để chỉ? Nhận thức về bản thân của bé thật tuyệt vời. Hãy ghi lại bước nhảy vọt trí tuệ này trong Theo dõi phát triển.', title_zh = '知道自己的名字和年龄 🎂', body_zh = '问“你几岁啦？”，宝宝就努力用手指比给你看？自我意识发展得很棒。在发育追踪里记下这次智力飞跃吧。' WHERE id = '5bb344ff-e859-413b-93f7-4f25386f0835' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de las luces 🌙', body_es = '¿Empieza a tenerle miedo a la oscuridad? Oscurece del todo la habitación y jugad con una linterna pequeña a hacer luces en el techo. Convierte la oscuridad que teme en diversión, en una pequeña exploración antes de dormir.', title_fr = 'La magie des lumières 🌙', body_fr = 'Il commence à avoir peur du noir ? Faites le noir complet dans la chambre et jouez avec une petite lampe torche à faire des jeux de lumière au plafond. Transformez le noir qui lui fait peur en jeu, en petite exploration avant de dormir.', title_hi = 'रोशनी का जादू 🌙', body_hi = 'अंधेरे से डरने लगा है? कमरे में पूरा अंधेरा कीजिए और छोटी टॉर्च से छत पर रोशनी के खेल खेलिए। जिस अंधेरे से वह डरता है, उसे मज़े और सोने से पहले की छोटी सी खोज में बदल दीजिए।', title_id = 'Keajaiban cahaya 🌙', body_id = 'Ia mulai takut gelap? Gelapkan kamar sepenuhnya dan mainkan permainan cahaya di langit-langit dengan senter kecil. Ubah gelap yang ia takuti menjadi keseruan dan petualangan kecil sebelum tidur.', title_ja = '光の魔法 🌙', body_ja = '暗やみをこわがり始めましたか？部屋を真っ暗にして、小さな懐中電灯で天井に光を映して遊びましょう。こわい暗やみを、寝る前の楽しい小さな探検に変えて。', title_ko = '빛의 마법 🌙', body_ko = '어둠을 무서워하기 시작했나요? 방을 완전히 어둡게 하고 작은 손전등으로 천장에 빛 놀이를 해 보세요. 무서운 어둠을 잠들기 전 작은 탐험 놀이로 바꿔 주세요.', title_nl = 'De magie van licht 🌙', body_nl = 'Begint hij bang te worden voor het donker? Maak de kamer helemaal donker en speel met een klein zaklampje lichtspelletjes op het plafond. Maak van het donker waar hij bang voor is een spel, een kleine ontdekkingstocht voor het slapen.', title_pl = 'Magia świateł 🌙', body_pl = 'Zaczął bać się ciemności? Zaciemnij całkowicie pokój i bawcie się małą latarką w świetlne gry na suficie. Zamień ciemność, której się boi, w zabawę i małą wyprawę przed snem.', title_pt = 'A magia das luzes 🌙', body_pt = 'Começou a ter medo do escuro? Escureça o quarto por completo e faça jogos de luz no teto com uma pequena lanterna. Transforme o escuro de que tem medo numa diversão, uma pequena exploração antes de dormir.', title_sv = 'Ljusets magi 🌙', body_sv = 'Har barnet börjat bli rädd för mörkret? Gör rummet helt mörkt och lek ljuslekar i taket med en liten ficklampa. Gör det skrämmande mörkret till en lek, en liten upptäcktsfärd före sömnen.', title_vi = 'Phép màu của ánh sáng 🌙', body_vi = 'Bé bắt đầu sợ bóng tối? Hãy làm tối phòng hoàn toàn và dùng đèn pin nhỏ chơi trò ánh sáng trên trần nhà. Biến bóng tối bé sợ thành niềm vui, một chuyến thám hiểm nho nhỏ trước giờ ngủ.', title_zh = '光的魔法 🌙', body_zh = '开始怕黑了？把房间完全调暗，用小手电筒在天花板上玩光影游戏。把宝宝害怕的黑暗变成乐趣，变成一次睡前的小探险。' WHERE id = '3b9f5253-06a7-4aef-bfdf-bb0daf30818e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por el pijama 👗', body_es = 'Se ha despertado y se niega en redondo a quitarse el pijama manchado. Si no vais a salir de casa, para la batalla. A veces la tranquilidad psicológica de una madre es mucho más importante que que el niño vaya bien arreglado.', title_fr = 'Passion pyjama 👗', body_fr = 'Au réveil, il refuse catégoriquement d''enlever son pyjama taché. Si vous ne sortez pas de la maison, épargnez-vous la bataille. Parfois, la tranquillité d''esprit de maman compte bien plus que la tenue impeccable de l''enfant.', title_hi = 'पजामे से प्यार 👗', body_hi = 'सुबह उठा और दाग वाला पजामा उतारने से साफ़ मना कर रहा है? अगर घर से बाहर नहीं जाना, तो जंग रोकिए। कभी-कभी माँ का मानसिक सुकून बच्चे के सलीके से दिखने से कहीं ज़्यादा ज़रूरी होता है।', title_id = 'Cinta pada piyama 👗', body_id = 'Pagi ini ia bangun dan menolak keras melepas piyamanya yang bernoda. Jika tidak akan keluar rumah, hentikan perdebatan. Kadang ketenangan batin ibu jauh lebih penting daripada anak yang tampak rapi.', title_ja = 'パジャマが大好き 👗', body_ja = '朝起きても、シミのついたパジャマを脱ぐのをきっぱり拒否しますか？出かけないなら、戦いはやめましょう。ときにはママの心のゆとりのほうが、子どもの見た目よりずっと大切です。', title_ko = '잠옷 사랑 👗', body_ko = '아침에 일어나 얼룩진 잠옷을 절대 벗지 않겠다고 하나요? 외출할 일이 없다면 씨름은 그만두세요. 가끔은 엄마의 마음 편안함이 아이의 단정한 모습보다 훨씬 중요해요.', title_nl = 'Verliefd op zijn pyjama 👗', body_nl = 'Wil hij zijn pyjama vol vlekken bij het opstaan absoluut niet uittrekken? Gaan jullie de deur niet uit, stop dan de strijd. Soms is de rust van een moeder veel belangrijker dan een netjes uitziend kind.', title_pl = 'Miłość do piżamy 👗', body_pl = 'Rano się obudził i stanowczo odmawia zdjęcia poplamionej piżamy. Jeśli nie wychodzicie z domu, odpuść walkę. Czasem psychiczny spokój mamy jest o wiele ważniejszy niż schludny wygląd dziecka.', title_pt = 'Amor pelo pijama 👗', body_pt = 'Acordou e recusa terminantemente tirar o pijama manchado. Se não vão sair de casa, pare a luta. Às vezes, o sossego psicológico da mãe é muito mais importante do que a criança estar arrumadinha.', title_sv = 'Kärlek till pyjamasen 👗', body_sv = 'Barnet har vaknat och vägrar bestämt ta av sig den fläckiga pyjamasen. Om ni inte ska gå ut, avbryt kampen. Ibland är mammans psykiska lugn mycket viktigare än att barnet ser prydligt ut.', title_vi = 'Tình yêu với bộ đồ ngủ 👗', body_vi = 'Sáng thức dậy, bé kiên quyết không chịu cởi bộ đồ ngủ lấm lem. Nếu không ra ngoài, hãy dừng giằng co. Đôi khi sự thoải mái tâm lý của mẹ quan trọng hơn gấp nhiều lần việc bé trông gọn gàng.', title_zh = '爱上睡衣 👗', body_zh = '早上醒来，坚决不肯脱掉身上满是污渍的睡衣。如果今天不出门，就停下这场对抗吧。有时妈妈的心理放松，比孩子穿得整整齐齐重要得多。' WHERE id = '5d1a2a49-e134-453a-a974-f4cff4de0952' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tesoros del bolsillo 🍁', body_es = 'Habéis vuelto del parque y de su bolsillo han salido 3 piedras, 1 hoja seca y un palito. Para ti es basura; para tu peque, un tesoro. En lugar de que acaben esparcidos por casa, crea una caja de colección y deja que los guarde ahí.', title_fr = 'Les trésors des poches 🍁', body_fr = 'De retour du parc, vous trouvez dans sa poche 3 cailloux, 1 feuille sèche et une brindille. Pour vous, ce sont des déchets, pour lui, un trésor. Plutôt que de les laisser traîner partout, créez une boîte à collection où il pourra les ranger.', title_hi = 'जेब से निकले खज़ाने 🍁', body_hi = 'पार्क से लौटीं और उसकी जेब से 3 पत्थर, 1 सूखा पत्ता और एक तिनका निकला। आपके लिए कचरा, उसके लिए खज़ाना। उन्हें घर में बिखेरे बिना एक कलेक्शन बॉक्स बनाइए और उसमें रखने दीजिए।', title_id = 'Harta karun dari kantong 🍁', body_id = 'Pulang dari taman, dari kantongnya keluar 3 batu, 1 daun kering, dan sebatang ranting. Bagi Anda sampah, baginya harta karun. Sebelum tersebar di rumah, buatkan kotak koleksi dan biarkan ia menyimpannya di sana.', title_ja = 'ポケットから出てくる宝物 🍁', body_ja = '公園から帰ったら、ポケットから石が3つ、枯れ葉が1枚、小枝が1本。あなたにはゴミでも、お子さんには宝物です。家じゅうに散らばらないよう、コレクションボックスをつくってしまわせてあげましょう。', title_ko = '주머니 속 보물 🍁', body_ko = '공원에서 돌아왔더니 주머니에서 돌 3개, 마른 잎 하나, 나뭇가지가 나왔나요? 엄마에겐 쓰레기지만 아이에겐 보물이에요. 집에 흩어 놓지 않도록 수집 상자를 만들어 모아 두게 해 주세요.', title_nl = 'Schatten uit zijn zakken 🍁', body_nl = 'Na het park kwamen er 3 steentjes, 1 verdord blad en een takje uit zijn zak. Voor jou afval, voor hem een schat. Laat ze niet door het huis slingeren, maar maak een verzameldoos waarin hij ze kan bewaren.', title_pl = 'Skarby z kieszeni 🍁', body_pl = 'Wróciliście z parku, a z jego kieszeni wypadły 3 kamyki, 1 suchy liść i patyk. Dla ciebie to śmieci, dla niego skarb. Zanim rozsypie je po domu, zróbcie pudełko na kolekcję i pozwól mu je tam zbierać.', title_pt = 'Tesouros que saem do bolso 🍁', body_pt = 'Voltaram do parque e do bolso dele saíram 3 pedras, 1 folha seca e um pauzinho. Para si é lixo, para ele é um tesouro. Em vez de os deixar espalhados pela casa, crie uma caixa de coleção para ele os guardar lá.', title_sv = 'Skatter ur fickan 🍁', body_sv = 'Ni kom hem från parken och ur fickan dök 3 stenar, 1 vissnat löv och en pinne upp. För dig är det skräp, för barnet är det en skatt. Skapa en samlarlåda och låt barnet lägga dem där i stället för att sprida dem över hela hemmet.', title_vi = 'Kho báu trong túi áo 🍁', body_vi = 'Đi công viên về, trong túi bé có 3 viên sỏi, 1 chiếc lá khô và một que củi. Với mẹ đó là rác, với bé là kho báu. Thay vì để bé rải khắp nhà, hãy làm một hộp sưu tập để bé cất vào đó.', title_zh = '口袋里掏出的宝藏 🍁', body_zh = '从公园回来，口袋里掏出3块石头、1片枯叶和一根小树枝。对你是垃圾，对宝宝却是宝藏。别让它们撒得满屋都是，做一个收藏盒，让宝宝收进去吧。' WHERE id = 'c8ffca51-c2fa-4f5a-8090-6c144b596f9c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Soltar la carga emocional 📝', body_es = '¿Nadie ve lo cansada que estás estando en casa? El Diario de ánimo es tu confidente más silencioso. Escribe ahí todos los detalles que hoy te han sacado de quicio y verás cómo se te aligera la mente.', title_fr = 'Déposer sa charge émotionnelle 📝', body_fr = 'Personne à la maison ne voit à quel point vous êtes fatiguée ? Le Journal d''humeur est votre confident le plus silencieux. Écrivez-y tous les détails qui vous ont rendue folle aujourd''hui et sentez votre esprit s''alléger.', title_hi = 'भावनाओं का बोझ उतारिए 📝', body_hi = 'कोई नहीं देखता कि घर पर रहकर आप कितनी थक जाती हैं? मूड डायरी आपकी सबसे खामोश राज़दार है। आज जिन बातों ने परेशान किया, वे सब वहाँ लिखिए और देखिए कि दिमाग कैसे हल्का हो जाता है।', title_id = 'Melepas beban emosi 📝', body_id = 'Tidak ada yang melihat betapa lelahnya Anda di rumah? Buku Harian Suasana Hati adalah teman curhat Anda yang paling diam. Tuliskan semua detail yang membuat Anda kesal hari ini dan rasakan pikiran Anda menjadi ringan.', title_ja = '心の荷物をおろそう 📝', body_ja = '家にいて、あなたがどれほど疲れているかだれも気づかない？「気分日記」はいちばん静かな打ち明け相手です。今日イライラしたことを全部書いて、頭がどれほど軽くなるか感じましょう。', title_ko = '감정의 짐 내려놓기 📝', body_ko = '집에 있다고 얼마나 지쳤는지 아무도 몰라주나요? 기분 일기는 가장 조용한 비밀 친구예요. 오늘 나를 힘들게 한 모든 일을 적고 머리가 가벼워지는 걸 느껴 보세요.', title_nl = 'Emotionele last lossen 📝', body_nl = 'Ziet niemand hoe moe je wordt van thuis zijn? Je Stemmingsdagboek is je stilste vertrouweling. Schrijf alle details op die je vandaag gek maakten en merk hoe je hoofd lichter wordt.', title_pl = 'Zrzucić emocjonalny ciężar 📝', body_pl = 'Nikt w domu nie widzi, jak bardzo jesteś zmęczona? Dziennik nastroju to twój najcichszy powiernik. Zapisz tam wszystkie szczegóły, które dziś doprowadzały cię do szału, i zobacz, jak lżej robi się w głowie.', title_pt = 'Descarregar o peso emocional 📝', body_pt = 'Ninguém em casa vê o quanto está cansada? O Diário de Humor é o seu confidente mais silencioso. Escreva lá todos os detalhes que hoje a enlouqueceram e veja como a cabeça fica mais leve.', title_sv = 'Släpp den känslomässiga bördan 📝', body_sv = 'Ser ingen hur trött du blir av att vara hemma? Humördagboken är din tystaste förtrogna. Skriv ner alla detaljer som gjorde dig galen i dag och känn hur det lättar i huvudet.', title_vi = 'Trút bỏ gánh nặng cảm xúc 📝', body_vi = 'Không ai thấy mẹ ở nhà mệt mỏi đến thế nào? Nhật ký tâm trạng là người bạn tâm giao lặng lẽ nhất. Hãy viết vào đó mọi chi tiết khiến mẹ phát điên hôm nay và cảm nhận đầu óc nhẹ nhõm hơn.', title_zh = '卸下情绪负担 📝', body_zh = '没人看见你在家有多累？心情日记是你最安静的知己。把今天让你抓狂的所有细节都写进去，感受大脑变得轻松吧。' WHERE id = '176265d3-ef2f-4ec4-923c-4308870e611f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Camino yo solo! 🚶‍♂️', body_es = 'En la calle se niega en redondo a darte la mano y declara su libertad. En lugares seguros, dale esa libertad. Sin quitarle el ojo de encima, deja que descubra el mundo con sus propios pasos.', title_fr = 'Je marche tout seul ! 🚶‍♂️', body_fr = 'Dans la rue, il refuse catégoriquement de vous donner la main et proclame sa liberté. Dans les endroits sûrs, accordez-lui cette liberté. Gardez un œil sur lui et laissez-le découvrir le monde à son propre pas.', title_hi = 'मैं खुद चलूँगा! 🚶‍♂️', body_hi = 'सड़क पर आपका हाथ पकड़ने से साफ़ मना करता है, आज़ादी का ऐलान करता है? सुरक्षित जगहों पर उसे यह आज़ादी दीजिए। आपकी नज़र उस पर रहे, उसे अपने कदमों से दुनिया खोजने दीजिए।', title_id = 'Aku jalan sendiri! 🚶‍♂️', body_id = 'Di jalan ia menolak keras berpegangan tangan dan mengumumkan kebebasannya. Di tempat yang aman, berikan kebebasan ini. Tetap awasi, dan biarkan ia menjelajahi dunia dengan langkahnya sendiri.', title_ja = 'ひとりで歩く！🚶‍♂️', body_ja = '道で手をつなぐのをきっぱり断り、自由を宣言していますか？安全な場所ではこの自由をあげましょう。目は離さずに、自分の足で世界を発見させてあげて。', title_ko = '혼자 걸을래! 🚶‍♂️', body_ko = '길에서 엄마 손을 잡지 않겠다며 독립을 선언하나요? 안전한 곳에서는 이 자유를 주세요. 눈은 떼지 말고, 자기 걸음으로 세상을 탐험하게 해 주세요.', title_nl = 'Ik loop zelf! 🚶‍♂️', body_nl = 'Weigert hij op straat resoluut je hand vast te houden en roept hij zijn vrijheid uit? Geef hem die vrijheid op veilige plekken. Houd hem in de gaten en laat hem de wereld met zijn eigen stapjes ontdekken.', title_pl = 'Sam pójdę! 🚶‍♂️', body_pl = 'Na ulicy stanowczo odmawia trzymania cię za rękę i ogłasza niepodległość. W bezpiecznych miejscach daj mu tę swobodę. Miej go na oku i pozwól mu odkrywać świat własnymi krokami.', title_pt = 'Eu ando sozinho! 🚶‍♂️', body_pt = 'Na rua, recusa terminantemente dar-lhe a mão e declara a sua liberdade. Em locais seguros, dê-lhe essa autonomia. Mantenha-o debaixo de olho e deixe-o descobrir o mundo com os próprios passos.', title_sv = 'Jag går själv! 🚶‍♂️', body_sv = 'Vägrar barnet bestämt att hålla dig i handen ute och utropar sin frihet? Ge barnet den här friheten på säkra platser. Håll ett öga på hen och låt hen upptäcka världen med sina egna steg.', title_vi = 'Con tự đi! 🚶‍♂️', body_vi = 'Ra đường bé dứt khoát không chịu nắm tay mẹ, tuyên bố tự do. Ở những nơi an toàn, hãy cho bé sự tự do này. Mẹ vẫn trông chừng, để bé khám phá thế giới bằng chính bước chân mình.', title_zh = '我要自己走！🚶‍♂️', body_zh = '在街上坚决不肯牵你的手，宣布独立。在安全的地方给宝宝这份自由吧。眼睛盯着宝宝，让宝宝用自己的脚步去探索世界。' WHERE id = '94fce04c-73e9-47bd-8d9d-3bd3da19122a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño chef de la cocina 🧑‍🍳', body_es = '¿Mientras estiras la masa, pone una silla a tu lado sí o sí y se mete en el proceso? Dale un trocito de masa. Todo acabará lleno de harina, pero esa carita seria y trabajadora vale toda la limpieza.', title_fr = 'Le petit chef de la cuisine 🧑‍🍳', body_fr = 'Quand vous étalez la pâte, il installe absolument une chaise à côté de vous pour s''en mêler ? Donnez-lui un petit morceau de pâte. Il y aura de la farine partout, mais son air sérieux et affairé vaut bien tout ce nettoyage.', title_hi = 'रसोई का नन्हा शेफ़ 🧑‍🍳', body_hi = 'आप आटा बेलती हैं तो वह बगल में कुर्सी लगाकर काम में दखल देता है? उसके हाथ में आटे का छोटा सा टुकड़ा दीजिए। हर जगह आटा होगा, लेकिन उसका वह गंभीर, काम में डूबा चेहरा इस सारी सफ़ाई के लायक है।', title_id = 'Koki kecil di dapur 🧑‍🍳', body_id = 'Saat Anda menggiling adonan, ia pasti menaruh kursi di samping Anda dan ikut campur? Beri ia sepotong kecil adonan. Tepung akan ada di mana-mana, tetapi ekspresi wajahnya yang serius dan sibuk itu sepadan dengan semua bersih-bersihnya.', title_ja = 'キッチンの小さなシェフ 🧑‍🍳', body_ja = 'あなたが生地をのばしていると、必ずいすを持ってきて手を出しますか？小さな生地をひとかけら渡しましょう。あちこち粉だらけになっても、その真剣な仕事人の表情は、片づけの手間に見合う価値があります。', title_ko = '주방의 꼬마 요리사 🧑‍🍳', body_ko = '엄마가 반죽을 밀 때 꼭 옆에 의자를 놓고 끼어드나요? 작은 반죽 조각을 쥐여 주세요. 사방이 밀가루투성이가 되겠지만, 진지하고 일하는 그 표정은 청소할 가치가 충분해요.', title_nl = 'Kleine kok in de keuken 🧑‍🍳', body_nl = 'Zet hij per se een stoel naast je als jij deeg uitrolt en bemoeit hij zich ermee? Geef hem een klein stukje deeg. Alles zit onder de bloem, maar die serieuze, zakelijke blik is al dat schoonmaken waard.', title_pl = 'Mały kucharz w kuchni 🧑‍🍳', body_pl = 'Gdy wałkujesz ciasto, koniecznie stawia obok krzesło i wtrąca się do pracy? Daj mu mały kawałek ciasta. Wszędzie będzie mąka, ale jego poważna, rzeczowa mina jest warta całego sprzątania.', title_pt = 'O pequeno cozinheiro 🧑‍🍳', body_pt = 'Quando estende a massa, põe por força uma cadeira ao seu lado e mete-se no processo? Dê-lhe um pedacinho de massa. Vai ficar tudo cheio de farinha, mas aquela expressão séria e atarefada vale toda a limpeza.', title_sv = 'Köksliten kock 🧑‍🍳', body_sv = 'Ställer barnet alltid en stol bredvid dig och lägger sig i när du kavlar deg? Ge hen en liten degbit. Det blir mjöl överallt, men barnets allvarliga, affärsmässiga min är värd all städning.', title_vi = 'Đầu bếp nhí trong bếp 🧑‍🍳', body_vi = 'Khi mẹ cán bột, bé nhất định kê ghế đứng cạnh và "can thiệp"? Hãy đưa bé một miếng bột nhỏ. Bột sẽ vương khắp nơi, nhưng gương mặt nghiêm túc, chăm chỉ của bé xứng đáng với mọi công dọn dẹp.', title_zh = '厨房小厨师 🧑‍🍳', body_zh = '你擀面时，宝宝一定要搬把椅子到旁边来插手？给宝宝一小块面团吧。到处都会是面粉，但宝宝那副认真干活的表情，值得你之后的所有打扫。' WHERE id = 'b24a452c-9588-4b0c-923f-9c455be6d1e2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El reto de la pausa sin pantallas 📺', body_es = '¿Hoy, por tus tareas, le has puesto más dibujos animados y te sientes culpable? No te culpes. No puedes ser una madre perfecta todos los días. A veces la niñera digital te salva de un derrumbe psicológico.', title_fr = 'Le défi de la pause sans écran 📺', body_fr = 'Aujourd''hui, à cause de votre travail, il a regardé plus de dessins animés et vous culpabilisez ? Ne vous blâmez pas. Vous ne pouvez pas être une mère parfaite tous les jours. Parfois, la nounou numérique vous sauve de l''effondrement psychologique.', title_hi = 'बिना स्क्रीन वाले ब्रेक की मुश्किल 📺', body_hi = 'आज अपने कामों की वजह से उसे ज़्यादा कार्टून दिखाए और अब अपराध-बोध हो रहा है? खुद को दोष मत दीजिए। आप हर दिन परफ़ेक्ट माँ नहीं हो सकतीं। कभी-कभी डिजिटल आया आपको मानसिक रूप से टूटने से बचा लेती है।', title_id = 'Sulitnya rehat tanpa layar 📺', body_id = 'Hari ini karena banyak pekerjaan Anda memberinya lebih banyak film kartun dan merasa bersalah? Jangan salahkan diri. Anda tidak bisa menjadi ibu sempurna setiap hari. Kadang pengasuh digital menyelamatkan Anda dari keruntuhan mental.', title_ja = '画面なしで過ごすむずかしさ 📺', body_ja = '今日は用事があって、いつもよりアニメを見せてしまい、罪悪感がありますか？自分を責めないで。毎日完璧なママではいられません。ときにはデジタルのベビーシッターが、心が折れるのを救ってくれます。', title_ko = '화면 없는 휴식의 어려움 📺', body_ko = '오늘 할 일 때문에 만화를 더 많이 보여 줘서 죄책감이 드나요? 자책하지 마세요. 매일 완벽한 엄마일 수는 없어요. 가끔은 디지털 보모가 엄마를 마음의 붕괴에서 구해 줘요.', title_nl = 'De uitdaging van een pauze zonder scherm 📺', body_nl = 'Liet je hem vandaag door je werk meer tekenfilms kijken en voel je je schuldig? Veroordeel jezelf niet. Je kunt niet elke dag een perfecte moeder zijn. Soms redt een digitale oppas je van een mentale instorting.', title_pl = 'Trudna przerwa bez ekranu 📺', body_pl = 'Przez swoje obowiązki dałaś mu dziś więcej bajek i masz wyrzuty sumienia? Nie obwiniaj się. Nie możesz być idealną mamą każdego dnia. Czasem cyfrowa niania ratuje cię przed psychicznym załamaniem.', title_pt = 'O desafio da pausa sem ecrã 📺', body_pt = 'Hoje, por causa do trabalho, deu-lhe mais desenhos animados e sente culpa? Não se culpe. Não pode ser uma mãe perfeita todos os dias. Às vezes, a ama digital salva-a de um colapso psicológico.', title_sv = 'Svårt med skärmfria pauser 📺', body_sv = 'Fick barnet titta mer på tecknat i dag för att du hade saker att göra, och nu har du dåligt samvete? Klandra inte dig själv. Du kan inte vara en perfekt mamma varje dag. Ibland räddar den digitala barnvakten dig från ett psykiskt sammanbrott.', title_vi = 'Thử thách không màn hình 📺', body_vi = 'Hôm nay vì bận việc mà mẹ cho bé xem hoạt hình nhiều hơn và thấy áy náy? Đừng tự trách. Mẹ không thể ngày nào cũng hoàn hảo. Đôi khi "bảo mẫu kỹ thuật số" cứu mẹ khỏi suy sụp tâm lý.', title_zh = '无屏幕时间好难 📺', body_zh = '今天因为要忙，给宝宝看了更多动画片，心里很内疚？别责怪自己。你不可能每天都做完美妈妈。有时“数字保姆”能把你从心理崩溃中救出来。' WHERE id = '09711673-d0fa-42b5-be98-012bd4b1ed8b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Grabadora en vivo 🎙️', body_es = '¡Esta mañana le dice a su juguete una palabra cualquiera que usaste ayer hablando con tu pareja! Su vocabulario crece a una velocidad tremenda y te copia por completo. No olvides que eres su ejemplo.', title_fr = 'Magnétophone vivant 🎙️', body_fr = 'Ce matin, il répète à son jouet un mot anodin que vous avez employé hier en parlant avec votre partenaire ! Son vocabulaire s''enrichit à une vitesse folle et il vous copie entièrement. N''oubliez pas que vous êtes son modèle.', title_hi = 'जीता-जागता रिकॉर्डर 🎙️', body_hi = 'कल पार्टनर से बात करते समय इस्तेमाल किया कोई अनजाना शब्द आज सुबह अपने खिलौने से कह रहा है! उसकी शब्दावली गज़ब की तेज़ी से बढ़ रही है और वह आपकी पूरी नकल करता है। याद रखिए, आप उसके लिए उदाहरण हैं।', title_id = 'Perekam hidup 🎙️', body_id = 'Kata acak yang Anda ucapkan kemarin saat berbicara dengan pasangan, pagi ini ia ucapkan pada mainannya! Kosakatanya berkembang sangat cepat dan ia meniru Anda sepenuhnya. Ingat, Anda adalah teladannya.', title_ja = '生きたボイスレコーダー 🎙️', body_ja = '昨日パートナーと話していたときに使ったなにげない言葉を、今朝おもちゃに言っていますか！語彙がものすごい速さで広がり、あなたをそっくりまねしています。お手本であることを忘れないで。', title_ko = '살아 있는 녹음기 🎙️', body_ko = '어제 배우자와 이야기하며 무심코 쓴 단어를 오늘 아침 장난감에게 말하나요? 어휘가 엄청난 속도로 늘고 있고, 엄마를 그대로 따라 하고 있어요. 엄마가 본보기라는 걸 잊지 마세요.', title_nl = 'Levende recorder 🎙️', body_nl = 'Zegt hij vanochtend tegen zijn speelgoed een toevallig woord dat jij gisteren tegen je partner gebruikte? Zijn woordenschat groeit razendsnel en hij kopieert je helemaal. Vergeet niet dat jij zijn voorbeeld bent.', title_pl = 'Żywy dyktafon 🎙️', body_pl = 'Przypadkowe słowo, którego wczoraj użyłaś w rozmowie z partnerem, dziś rano mówi do swojej zabawki! Jego słownictwo rośnie w zawrotnym tempie, a on całkowicie cię kopiuje. Pamiętaj, że jesteś dla niego przykładem.', title_pt = 'Gravador vivo 🎙️', body_pt = 'Esta manhã disse ao brinquedo uma palavra casual que usou ontem a falar com o seu companheiro! O vocabulário cresce a uma velocidade espantosa e ele copia-a por completo. Não se esqueça de que é o exemplo dele.', title_sv = 'Levande diktafon 🎙️', body_sv = 'Säger barnet i morse till sin leksak ett slumpmässigt ord som du använde när du pratade med din partner i går? Ordförrådet växer otroligt snabbt och hen kopierar dig helt. Glöm inte att du är förebilden.', title_vi = 'Chiếc máy ghi âm sống 🎙️', body_vi = 'Sáng nay bé nói với đồ chơi một từ ngẫu nhiên mẹ dùng hôm qua khi nói chuyện với chồng! Vốn từ của bé mở rộng với tốc độ chóng mặt và bé bắt chước mẹ hoàn toàn. Đừng quên mẹ là tấm gương của bé.', title_zh = '活的录音机 🎙️', body_zh = '昨天你和另一半聊天时随口说的一个词，今早宝宝就对着玩具说了出来！词汇量正在以惊人的速度扩展，而且宝宝完全在模仿你。别忘了你就是榜样。' WHERE id = '8649e4ca-170c-4117-8af8-b0d7e819e84f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El lema del susurro 🤫', body_es = 'Está tan activo en la cama que no se duerme. En lugar de levantar la voz, bájala de repente y háblale en susurros. Cuando se concentra para oírte, su cerebro pasa automáticamente al modo sueño.', title_fr = 'La devise du chuchotement 🤫', body_fr = 'Il est si agité dans son lit qu''il ne s''endort pas. Au lieu de hausser la voix, baissez soudain le ton et parlez en chuchotant. Quand l''enfant se concentre pour vous entendre, son cerveau passe automatiquement en mode sommeil.', title_hi = 'फुसफुसाहट का मंत्र 🤫', body_hi = 'बिस्तर पर इतना चुलबुला है कि सोता ही नहीं? आवाज़ ऊँची करने के बजाय अचानक धीमी कर दीजिए और फुसफुसाकर बात कीजिए। जब बच्चा आपको सुनने के लिए ध्यान लगाता है, तो उसका दिमाग अपने आप नींद के मोड में चला जाता है।', title_id = 'Semboyan berbisik 🤫', body_id = 'Ia begitu aktif di tempat tidur sampai tidak bisa tidur. Daripada meninggikan suara, tiba-tiba turunkan nada suara dan berbicaralah sambil berbisik. Saat ia memusatkan perhatian untuk mendengar Anda, otaknya otomatis beralih ke mode tidur.', title_ja = 'ささやき声の合言葉 🤫', body_ja = 'ベッドの上で元気すぎて眠らない？声を大きくするかわりに、急に声のトーンを落として、ささやき声で話しましょう。聞こうとして集中すると、脳が自然に眠りのモードへ切りかわります。', title_ko = '속삭임 작전 🤫', body_ko = '침대에서 너무 활발해서 잠들지 못하나요? 목소리를 높이는 대신 갑자기 톤을 낮추고 속삭여 보세요. 엄마 말을 들으려고 집중하는 사이 뇌가 저절로 수면 모드로 바뀌어요.', title_nl = 'Fluisteren als motto 🤫', body_nl = 'Is hij in bed zo actief dat hij niet in slaap valt? Verhef je stem niet, maar ga ineens zachter praten, fluisterend. Als hij zich concentreert om je te horen, schakelen zijn hersenen vanzelf over naar de slaapstand.', title_pl = 'Hasło: szept 🤫', body_pl = 'W łóżku jest tak aktywny, że nie zasypia. Zamiast podnosić głos, nagle go ścisz i mów szeptem. Gdy dziecko skupia uwagę, by cię usłyszeć, jego mózg automatycznie przechodzi w tryb snu.', title_pt = 'O lema do sussurro 🤫', body_pt = 'Está tão ativo na cama que não adormece. Em vez de levantar a voz, baixe de repente o tom e fale a sussurrar. Quando a criança se concentra para a ouvir, o cérebro passa automaticamente para o modo de sono.', title_sv = 'Viskningsparollen 🤫', body_sv = 'Är barnet så aktivt i sängen att hen inte somnar? I stället för att höja rösten, sänk plötsligt tonläget och viska. När barnet koncentrerar sig för att höra dig går hjärnan automatiskt över i sömnläge.', title_vi = 'Khẩu hiệu thì thầm 🤫', body_vi = 'Bé hiếu động trên giường đến mức không ngủ được. Thay vì cao giọng, hãy bất ngờ hạ giọng và nói thì thầm. Khi bé tập trung để nghe mẹ, não bé tự động chuyển sang chế độ ngủ.', title_zh = '悄悄话口号 🤫', body_zh = '在床上太活跃，怎么都睡不着？别提高嗓门，突然把声音放低，用悄悄话说话。宝宝为了听清你而集中注意力时，大脑会自动切换到睡眠模式。' WHERE id = 'c0faa467-b596-4471-bbba-6d91e0e37db1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta oxígeno ⛅', body_es = 'Las cuatro paredes te han dejado la mente adormecida y en casa estallan crisis. Consulta Tiempo y ropa y elige el conjunto adecuado. Simplemente salir a correr le hará soltar energía a tu peque y a ti te dará un respiro nuevo.', title_fr = 'Besoin d''oxygène ⛅', body_fr = 'Les quatre murs vous engourdissent le cerveau et les crises éclatent à la maison. Consultez Météo et tenue et choisissez la bonne tenue. Sortir et simplement courir le défoulera et vous redonnera du souffle.', title_hi = 'ऑक्सीजन की ज़रूरत ⛅', body_hi = 'चार दीवारों ने दिमाग सुन्न कर दिया है और घर में नखरे फूट रहे हैं? मौसम और कपड़े टूल देखकर सबसे सही कपड़े चुनिए। बाहर निकलकर बस दौड़ना उसकी ऊर्जा भी निकालेगा और आपको भी नई साँस देगा।', title_id = 'Kebutuhan oksigen ⛅', body_id = 'Empat dinding membuat otak Anda kaku dan krisis meledak di rumah. Cek cuaca dan pilih setelan yang paling tepat. Keluar dan berlari saja akan menyalurkan energinya sekaligus memberi Anda napas baru.', title_ja = '酸素が足りない ⛅', body_ja = '家にこもって頭がぼんやりし、家ではかんしゃくが続出？「天気と服装」を確認して、いちばんいいコーディネートを選びましょう。外で思いきり走れば、お子さんのエネルギーも発散でき、あなたも新しい息を吹きこめます。', title_ko = '산소가 필요해요 ⛅', body_ko = '네 벽 안에서 머리는 멍해지고 집에서는 떼쓰기가 터지나요? 날씨와 옷차림을 보고 가장 알맞은 옷을 고르세요. 밖에 나가 뛰기만 해도 아이는 에너지를 쓰고 엄마는 새 숨을 쉴 수 있어요.', title_nl = 'Behoefte aan zuurstof ⛅', body_nl = 'De vier muren maken je hoofd suf en thuis breken de buien uit. Kijk in Weer en kleding en kies de beste outfit. Gewoon buiten rennen laat hem zijn energie kwijt en geeft jou nieuwe adem.', title_pl = 'Potrzeba tlenu ⛅', body_pl = 'Cztery ściany otępiły ci głowę, a w domu wybuchają kryzysy. Sprawdź Pogodę i ubiór i wybierz najlepszy zestaw. Zwykłe bieganie na zewnątrz i jemu pozwoli spalić energię, i tobie da nowy oddech.', title_pt = 'Falta de oxigénio ⛅', body_pt = 'As quatro paredes adormeceram-lhe o cérebro e rebentam crises em casa. Veja o Tempo e Roupa e escolha a combinação certa. Sair e simplesmente correr vai gastar a energia dele e dar-lhe a si um novo fôlego.', title_sv = 'Syrebehov ⛅', body_sv = 'De fyra väggarna har bedövat hjärnan och kriserna avlöser varandra hemma. Kolla Väder och kläder och välj rätt klädsel. Att gå ut och bara springa får ut barnets energi och ger dig nytt andrum.', title_vi = 'Nhu cầu oxy ⛅', body_vi = 'Bốn bức tường khiến đầu óc mẹ tê liệt và trong nhà liên tục có khủng hoảng. Hãy xem Thời tiết và trang phục để chọn cách phối đồ phù hợp nhất. Chỉ cần ra ngoài chạy nhảy là bé vừa xả năng lượng, mẹ vừa có hơi thở mới.', title_zh = '需要氧气 ⛅', body_zh = '四面墙让你的大脑都麻木了，家里还不断上演崩溃。看看天气穿衣工具，选好最合适的搭配。出门跑一跑，既能释放宝宝的精力，也能让你重新喘口气。' WHERE id = '48263ed0-f236-440c-a83e-807da51bd86f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento lo dirige tu peque 🪄', body_es = 'Los libros clásicos os aburren a los dos. Abre Cuentos inteligentes, haz que el protagonista sea tu peque y el lugar por salvar, su habitación, y crea una sesión de sueño original, tranquila y libre.', title_fr = 'C''est lui qui mène le conte 🪄', body_fr = 'Vous en avez assez tous les deux des livres classiques. Ouvrez les Contes intelligents, faites de votre enfant le héros et de sa chambre le lieu à sauver, et créez une séance du coucher extraordinaire, calme et libre.', title_hi = 'कहानी की डोर उसके हाथ 🪄', body_hi = 'पुरानी किताबों से आप दोनों ऊब गए हैं? स्मार्ट कहानियाँ खोलिए, मुख्य हीरो अपने बच्चे को और बचाई जाने वाली जगह उसके कमरे को बनाइए, और एक अनोखा, शांत और खुला नींद का सेशन रचिए।', title_id = 'Kendali dongeng ada padanya 🪄', body_id = 'Kalian berdua bosan dengan buku klasik. Buka Dongeng Pintar, jadikan anak Anda tokoh utama dan kamarnya tempat yang harus diselamatkan, lalu ciptakan sesi tidur yang luar biasa, tenang, dan bebas.', title_ja = 'お話の主導権はお子さんに 🪄', body_ja = 'いつもの絵本にふたりともあきてしまった？「スマートおはなし」を開いて、主人公はお子さん、救う場所はお子さんの部屋にして、特別で静かな、自由なおやすみの時間をつくりましょう。', title_ko = '이야기의 지휘봉은 아이에게 🪄', body_ko = '늘 읽던 책이 둘 다 지겨워졌나요? 스마트 동화를 열어 아이를 주인공으로, 아이의 방을 구해야 할 장소로 정해 특별하고 조용하며 자유로운 잠자리 시간을 만들어 보세요.', title_nl = 'Hij bepaalt het sprookje 🪄', body_nl = 'Zijn jullie allebei de klassieke boekjes beu? Open Slimme sprookjes, maak je kindje de hoofdpersoon en zijn kamer de plek die gered moet worden, en creëer zo een bijzonder, rustig en vrij slaapmoment.', title_pl = 'Bajka w jego rękach 🪄', body_pl = 'Oboje macie dość klasycznych książek. Otwórz Mądre bajki, zrób dziecko głównym bohaterem, a jego pokój miejscem do uratowania, i stwórzcie niezwykły, cichy i swobodny seans przed snem.', title_pt = 'A história é ele que comanda 🪄', body_pt = 'Estão os dois fartos dos livros clássicos. Abra as Histórias Inteligentes, faça do seu filho o herói principal e do quarto dele o lugar a salvar, e crie uma sessão de sono fora do comum, tranquila e livre.', title_sv = 'Barnet styr sagan 🪄', body_sv = 'Ni är båda trötta på klassiska böcker. Öppna Smarta sagor, gör barnet till huvudperson och barnets rum till platsen som ska räddas, och skapa en ovanlig, lugn och fri godnattstund.', title_vi = 'Bé nắm quyền điều khiển câu chuyện 🪄', body_vi = 'Cả hai mẹ con đều chán những cuốn sách kinh điển? Hãy mở Truyện cổ tích thông minh, chọn bé làm nhân vật chính và căn phòng của bé là nơi cần giải cứu để tạo một buổi ru ngủ khác thường, yên tĩnh và tự do.', title_zh = '故事由宝宝掌控 🪄', body_zh = '你们俩都读腻了经典故事书？打开智能故事，让孩子当主角，把要拯救的地方设为宝宝的房间，来一场与众不同、安静又自由的睡前故事吧。' WHERE id = '8fed0a18-52ae-4688-8137-532b6b55726c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Creatividad vanguardista 🖍️', body_es = 'Unos segundos de silencio han acabado en peligro. Has entrado en la habitación y le has visto tatuándose los brazos o la barriga con rotulador. Respira hondo. Su motricidad fina avanza y la piel se lava igualmente.', title_fr = 'Création avant-gardiste 🖍️', body_fr = 'Quelques secondes de silence ont fini en catastrophe. Vous entrez dans la pièce et il s''est tatoué les bras ou le ventre au feutre. Respirez profondément. Sa motricité fine se développe, et la peau, ça se lave.', title_hi = 'अनोखी रचनात्मकता 🖍️', body_hi = 'कुछ पल की खामोशी खतरे में बदल गई। कमरे में गईं तो देखा कि बाँहों या पेट पर मार्कर से टैटू बना रहा है। गहरी साँस लीजिए। उसकी फ़ाइन मोटर स्किल्स बढ़ रही हैं, और त्वचा तो धुल ही जाती है।', title_id = 'Kreativitas avant-garde 🖍️', body_id = 'Hening beberapa detik berakhir dengan bahaya. Anda masuk kamar dan mendapati ia membuat tato di lengan atau perutnya dengan spidol. Tarik napas dalam. Motorik halusnya berkembang, dan kulit toh bisa dicuci.', title_ja = '前衛アート 🖍️', body_ja = '数秒の静けさが危険な結果に。部屋に入ったら、腕やおなかにペンでタトゥーを描いていた？深呼吸しましょう。指先の細かな運動能力が育っていて、肌はどうせ洗えば落ちます。', title_ko = '아방가르드 창작 🖍️', body_ko = '몇 초의 정적이 위험으로 끝났네요. 방에 들어갔더니 팔이나 배에 사인펜으로 타투를 그리고 있었나요? 깊게 숨 쉬세요. 소근육이 자라고 있고, 피부는 어차피 씻으면 돼요.', title_nl = 'Avant-garde creativiteit 🖍️', body_nl = 'Een paar seconden stilte liep uit op gevaar. Je kwam de kamer in en zag dat hij met een stift tatoeages op zijn armen of buik zette. Haal diep adem. Zijn fijne motoriek groeit en huid is toch afwasbaar.', title_pl = 'Awangardowa twórczość 🖍️', body_pl = 'Kilka sekund ciszy skończyło się niebezpiecznie. Weszłaś do pokoju i zobaczyłaś, że robi sobie flamastrem tatuaże na rękach albo brzuchu. Weź głęboki oddech. Motoryka mała się rozwija, a skóra i tak się zmyje.', title_pt = 'Criatividade de vanguarda 🖍️', body_pt = 'Uns segundos de silêncio deram em perigo. Entrou no quarto e viu que fez tatuagens com marcador nos braços ou na barriga. Respire fundo. A motricidade fina está a desenvolver-se e a pele lava-se.', title_sv = 'Avantgardistiskt skapande 🖍️', body_sv = 'Några sekunders tystnad slutade i fara. Du kom in i rummet och såg att barnet tatuerat armarna eller magen med tusch. Andas djupt. Finmotoriken utvecklas och huden går ändå att tvätta.', title_vi = 'Sáng tạo tiên phong 🖍️', body_vi = 'Vài giây im lặng đã thành nguy hiểm. Mẹ bước vào phòng và thấy bé dùng bút dạ "xăm" lên tay hoặc bụng. Hãy hít thở sâu. Kỹ năng vận động tinh đang phát triển, còn da thì đằng nào cũng rửa sạch được.', title_zh = '前卫创作 🖍️', body_zh = '几秒钟的安静引来了“危险”。走进房间，发现宝宝正用水彩笔在胳膊或肚子上“纹身”。深呼吸。精细动作在发展，皮肤反正洗得掉。' WHERE id = 'c7c388a1-a255-4a7c-a615-22236406e4e2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue la guerra contra las verduras 🥦', title_fr = 'La guerre des légumes continue 🥦', title_hi = 'सब्ज़ियों से दुश्मनी जारी है 🥦', title_id = 'Perang melawan sayuran berlanjut 🥦', title_ja = '野菜との戦いは続く 🥦', title_ko = '채소와의 전쟁은 계속돼요 🥦', title_nl = 'De oorlog met groenten gaat door 🥦', title_pl = 'Wojna z warzywami trwa 🥦', title_pt = 'A guerra aos legumes continua 🥦', title_sv = 'Grönsaksfiendskapen fortsätter 🥦', title_vi = 'Cuộc chiến với rau củ vẫn tiếp diễn 🥦', title_zh = '和蔬菜的战争还在继续 🥦' WHERE id = '3deb7e49-2093-4c39-a51d-8dd6fd44d138' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Coge su estetoscopio de juguete, te lo pone en el pecho y te dice «respira»? Tú eres la paciente y tu peque, el médico jefe. Sigue el juego, túmbate y, aunque sea 5 minutos, cierra los ojos y descansa durante el tratamiento.', body_fr = 'Il prend son stéthoscope jouet, le pose sur votre poitrine et vous dit « respire » ? Vous êtes la patiente, lui le médecin-chef. Jouez le jeu, allongez-vous et, pendant le soin, fermez les yeux et reposez-vous, ne serait-ce que 5 minutes.', body_hi = 'खिलौने वाला स्टेथोस्कोप लेकर आपके सीने पर रखता है और कहता है ''साँस लो''? आप मरीज़ हैं और वह बड़ा डॉक्टर। यह खेल खेलिए, लेट जाइए और इलाज के दौरान 5 मिनट ही सही, आँखें बंद करके आराम कीजिए।', body_id = 'Ia mengambil stetoskop mainan, menempelkannya di dada Anda, dan berkata ''Tarik napas''. Anda pasiennya, ia kepala dokternya. Mainkan saja permainan ini, berbaringlah, dan pejamkan mata untuk beristirahat selama perawatan, walau hanya 5 menit.', body_ja = 'おもちゃの聴診器をあなたの胸にあてて「息をすって」と言いますか？あなたは患者さん、お子さんは院長先生。この遊びに付き合って横になり、5分間でも治療中は目を閉じて休みましょう。', body_ko = '장난감 청진기를 엄마 가슴에 대고 ''숨 쉬어'' 하나요? 엄마는 환자, 아이는 원장님이에요. 이 놀이에 함께하며 누워서 5분이라도 ''치료''받는 동안 눈을 감고 쉬세요.', body_nl = 'Zet hij zijn speelgoedstethoscoop op je borst en zegt hij ''Adem in''? Jij bent de patiënt, hij de hoofdarts. Speel mee, ga liggen en sluit tijdens de behandeling je ogen, al is het maar 5 minuten.', body_pl = 'Bierze zabawkowy stetoskop, przykłada ci do piersi i mówi „Oddychaj”? Ty jesteś pacjentką, a on ordynatorem. Pobaw się w to, połóż się i choć przez 5 minut „leczenia” zamknij oczy i odpocznij.', body_pt = 'Pega no estetoscópio de brincar, põe-lho no peito e diz "respira"? A mãe é a doente e ele o médico-chefe. Entre no jogo, deite-se e, durante o tratamento, feche os olhos e descanse nem que sejam 5 minutos.', body_sv = 'Barnet tar sitt leksaksstetoskop, sätter det på ditt bröst och säger ”andas”. Du är patienten och barnet är överläkare. Lek leken, ligg ner och blunda och vila under behandlingen, om så bara i 5 minuter.', body_vi = 'Bé lấy ống nghe đồ chơi đặt lên ngực mẹ và nói "Mẹ hít thở đi"? Mẹ là bệnh nhân, còn bé là bác sĩ trưởng. Hãy chơi cùng bé, nằm xuống và nhắm mắt nghỉ ngơi trong lúc "điều trị", dù chỉ 5 phút.', body_zh = '拿着玩具听诊器放在你胸口，说“吸气”。你是病人，宝宝是主任医生。玩这个游戏吧，躺下来，在“治疗”期间闭上眼睛休息，哪怕只有5分钟。' WHERE id = '9dd6923c-7dc5-4341-8507-b21e0f3c9ee4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apaga la luz, que llegue el sueño 🌙', body_es = 'Para que se duerma antes, apaga todas las luces extra y las pantallas azules de la habitación. La hormona del sueño (melatonina) solo se produce rápido en un ambiente oscuro y sin tecnología.', title_fr = 'Éteins la lumière, que le sommeil vienne 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans bleus de la chambre. L''hormone du sommeil (mélatonine) n''est sécrétée rapidement que dans le noir, sans technologie.', title_hi = 'लाइटें बंद, नींद आए 🌙', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और नीली स्क्रीन बंद कर दीजिए। नींद का हार्मोन (मेलाटोनिन) सिर्फ़ अंधेरे और बिना गैजेट वाले माहौल में तेज़ी से बनता है।', title_id = 'Matikan lampu, biar kantuk datang 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar biru di kamar. Hormon tidur (melatonin) hanya diproduksi dengan cepat dalam suasana gelap dan bebas teknologi.', title_ja = '明かりを消して、眠りを呼ぼう 🌙', body_ja = '早く寝つけるように、部屋の余分な明かりと青い光の画面をすべて消しましょう。眠りのホルモン（メラトニン）は、暗くて機器のない環境でこそすばやく分泌されます。', title_ko = '불을 끄면 잠이 와요 🌙', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명과 블루라이트 화면을 모두 꺼 주세요. 수면 호르몬(멜라토닌)은 어둡고 전자기기 없는 환경에서만 빠르게 분비돼요.', title_nl = 'Doe het licht uit, dan komt de slaap 🌙', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en blauwe schermen in de kamer uit. Het slaaphormoon (melatonine) wordt alleen in een donkere omgeving zonder techniek snel aangemaakt.', title_pl = 'Zgaś światło, niech przyjdzie sen 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i niebieskie ekrany. Hormon snu (melatonina) wydziela się szybko tylko w ciemnym otoczeniu bez technologii.', title_pt = 'Apague as luzes, que o sono vem 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs azuis. A hormona do sono (melatonina) só é produzida rapidamente num ambiente escuro e sem tecnologia.', title_sv = 'Släck lamporna, låt sömnen komma 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och blå skärmar i rummet. Sömnhormonet (melatonin) utsöndras snabbt bara i en mörk miljö utan teknik.', title_vi = 'Tắt đèn để giấc ngủ đến 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình ánh sáng xanh trong phòng. Hormone giấc ngủ (melatonin) chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ.', title_zh = '关灯，睡意来 🌙', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光和发蓝光的屏幕。睡眠激素（褪黑素）只有在昏暗、没有电子设备的环境里才会快速分泌。' WHERE id = '20d0afb1-a487-43f5-b6f3-0f8cd2bca864' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
