UPDATE public.mommy_day_notifications SET title_es = '¿Otra vez ansiedad por separación? 🥺', title_fr = 'Encore l''angoisse de séparation ? 🥺', title_hi = 'फिर से बिछड़ने की चिंता? 🥺', title_id = 'Cemas berpisah lagi? 🥺', title_ja = 'また分離不安？🥺', title_ko = '분리 불안이 다시? 🥺', title_nl = 'Weer verlatingsangst? 🥺', title_pl = 'Znowu lęk separacyjny? 🥺', title_pt = 'Ansiedade de separação outra vez? 🥺', title_sv = 'Separationsångest igen? 🥺', title_vi = 'Lại lo âu chia ly? 🥺', title_zh = '分离焦虑又来了？🥺' WHERE id = '3a35865f-054d-413c-b3ad-81c68c171c47' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La confirmación del silencio 🤫', title_fr = 'La preuve du silence 🤫', title_hi = 'खामोशी का सबूत 🤫', title_id = 'Bukti keheningan 🤫', title_ja = '静けさを確かめる 🤫', title_ko = '고요를 확인하세요 🤫', title_nl = 'Bevestiging van de stilte 🤫', title_pl = 'Potwierdzona cisza 🤫', title_pt = 'A confirmação do silêncio 🤫', title_sv = 'Bekräftad tystnad 🤫', title_vi = 'Xác nhận sự yên tĩnh 🤫', title_zh = '确认安静 🤫' WHERE id = '96b4e611-59a4-4d8b-a157-87f9d477e265' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La presión de la perfección 🛑', body_es = '¿Otros niños ya cuentan colores y el tuyo no quiere? ¡Deja de comparar ahora mismo! Cada niño tiene su propio reloj de desarrollo. Tu peque avanza a su ritmo y es totalmente normal.', title_fr = 'La pression de la perfection 🛑', body_fr = 'D''autres enfants comptent déjà les couleurs, mais le vôtre n''en a pas envie ? Arrêtez tout de suite de comparer ! Chaque enfant a sa propre horloge de développement. Le vôtre avance à son rythme, et c''est tout à fait normal.', title_hi = 'परफ़ेक्ट होने का दबाव 🛑', body_hi = 'दूसरे बच्चे रंग गिनने लगे हैं, लेकिन आपका बच्चा नहीं चाहता? तुलना करना तुरंत बंद कीजिए! हर बच्चे की विकास की घड़ी अलग होती है। आपका बच्चा अपनी रफ़्तार से आगे बढ़ रहा है और यह बिल्कुल सामान्य है।', title_id = 'Tekanan untuk sempurna 🛑', body_id = 'Anak lain sudah menyebutkan warna, tetapi anak Anda tidak mau? Segera berhenti membandingkan! Jam perkembangan setiap anak berbeda. Anak Anda maju dengan temponya sendiri, dan itu sepenuhnya normal.', title_ja = '完璧でなきゃというプレッシャー 🛑', body_ja = 'ほかの子はもう色を数えているのに、うちの子は興味なし？比べるのはすぐにやめましょう！成長の時計は子どもによって違います。お子さんは自分のペースで進んでいて、それはまったく普通のことです。', title_ko = '완벽해야 한다는 압박 🛑', body_ko = '다른 아이들은 벌써 색깔을 세는데 우리 아이는 관심이 없나요? 비교는 당장 멈추세요! 아이마다 발달 시계가 달라요. 우리 아이는 자기 속도로 나아가고 있고 그건 아주 정상이에요.', title_nl = 'Druk om perfect te zijn 🛑', body_nl = 'Tellen andere kinderen al kleuren, maar wil jouw kind niet? Stop meteen met vergelijken! Elk kind heeft zijn eigen ontwikkelingsklok. Jouw kind gaat in zijn eigen tempo vooruit en dat is heel normaal.', title_pl = 'Presja perfekcji 🛑', body_pl = 'Inne dzieci już nazywają kolory, a twoje nie chce? Natychmiast przestań porównywać! Każde dziecko rozwija się we własnym rytmie. Twoje dziecko idzie naprzód swoim tempem i to zupełnie normalne.', title_pt = 'A pressão da perfeição 🛑', body_pt = 'Outras crianças já contam as cores e o seu filho não quer? Pare já de comparar! Cada criança tem o seu relógio de desenvolvimento. O seu filho avança ao seu ritmo, e isso é perfeitamente normal.', title_sv = 'Pressen att vara perfekt 🛑', body_sv = 'Andra barn räknar redan färger, men ditt barn vill inte? Sluta jämföra direkt! Varje barns utvecklingsklocka är olika. Ditt barn går framåt i sin egen takt och det är helt normalt.', title_vi = 'Áp lực hoàn hảo 🛑', body_vi = 'Những bé khác đã biết đếm màu sắc, còn bé nhà mình thì không muốn? Hãy dừng ngay việc so sánh! Mỗi bé có nhịp phát triển riêng. Bé đang tiến bộ theo tốc độ của mình và điều đó hoàn toàn bình thường.', title_zh = '完美的压力 🛑', body_zh = '别的孩子已经会数颜色了，你的孩子却不想？马上停止比较！每个孩子的发育时钟都不一样。你的孩子在按自己的节奏前进，这完全正常。' WHERE id = 'c1d1539d-38e2-40da-9e66-eb22e0cbbd09' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Grupo de apoyo de madres 💬', title_fr = 'Le groupe de soutien des mamans 💬', title_hi = 'माँओं का सपोर्ट ग्रुप 💬', title_id = 'Grup dukungan para ibu 💬', title_ja = 'ママたちのサポートグループ 💬', title_ko = '엄마들의 응원 모임 💬', title_nl = 'Steungroep voor moeders 💬', title_pl = 'Grupa wsparcia mam 💬', title_pt = 'Grupo de apoio das mães 💬', title_sv = 'Mammornas stödgrupp 💬', title_vi = 'Nhóm hỗ trợ của các mẹ 💬', title_zh = '妈妈互助小组 💬' WHERE id = '2d61ffa4-9df3-4b29-acca-6b87ebc82745' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con el caos de casa 🌪️', body_es = '¿La habitación está llena de juguetes? Lo importante no es la limpieza, sino estos momentos traviesos con tu peque. Los juguetes seguirán ahí mañana, no te agotes. A veces rendirse al desorden es el mejor descanso.', title_fr = 'Faire la paix avec le chaos de la maison 🌪️', body_fr = 'Il y a des jouets partout dans la pièce ? Ce qui compte, ce n''est pas le ménage, mais ces moments espiègles avec lui. Les jouets seront encore là demain, ne vous épuisez pas. Parfois, se rendre face au désordre est le meilleur repos.', title_hi = 'घर की अफ़रा-तफ़री से सुलह 🌪️', body_hi = 'कमरे में हर जगह खिलौने हैं? सफ़ाई नहीं, उसके साथ बिताए ये शरारती पल ज़रूरी हैं। खिलौने कल भी वहीं होंगे, खुद को मत थकाइए। कभी-कभी बिखराव के आगे हार मान लेना ही सबसे अच्छा आराम है।', title_id = 'Berdamai dengan kekacauan rumah 🌪️', body_id = 'Mainan di mana-mana di seluruh kamar? Yang penting bukan kebersihan, tetapi momen jahil yang Anda lalui bersamanya. Mainan itu besok masih di sana, jangan memaksakan diri. Kadang menyerah pada kekacauan adalah istirahat terbaik.', title_ja = '家の散らかりと仲直り 🌪️', body_ja = '部屋じゅうおもちゃだらけ？大切なのは片づけではなく、お子さんと過ごすこのやんちゃな時間です。おもちゃは明日もそこにあります、無理しないで。ときには散らかりに降参するのがいちばんの休息です。', title_ko = '집 안의 혼돈과 화해하기 🌪️', body_ko = '방 안 곳곳이 장난감인가요? 중요한 건 청소가 아니라 아이와 보내는 이 장난스러운 순간이에요. 장난감은 내일도 거기 있으니 무리하지 마세요. 가끔은 어질러짐에 항복하는 게 최고의 휴식이에요.', title_nl = 'Vrede sluiten met de chaos 🌪️', body_nl = 'Ligt de hele kamer vol speelgoed? Niet de netheid, maar deze ondeugende momenten samen zijn belangrijk. Het speelgoed ligt er morgen ook nog, put jezelf niet uit. Soms is je overgeven aan de rommel de beste rust.', title_pl = 'Pogodzić się z domowym chaosem 🌪️', body_pl = 'Zabawki w każdym kącie pokoju? Ważne jest nie sprzątanie, tylko te psotne chwile z nim. Zabawki będą tam też jutro, nie męcz się. Czasem poddanie się bałaganowi to najlepszy odpoczynek.', title_pt = 'Fazer as pazes com o caos da casa 🌪️', body_pt = 'O quarto está cheio de brinquedos por todo o lado? O importante não é a limpeza, são estes momentos traquinas com ele. Os brinquedos amanhã ainda lá estão, não se canse. Às vezes, render-se à desarrumação é o melhor descanso.', title_sv = 'Försonas med kaoset hemma 🌪️', body_sv = 'Är det leksaker överallt i rummet? Det viktiga är inte städningen, utan de busiga stunderna ni har tillsammans. Leksakerna finns kvar i morgon också, slit inte ut dig. Ibland är det bästa vilan att ge upp inför stöket.', title_vi = 'Làm hòa với sự bừa bộn 🌪️', body_vi = 'Đồ chơi bày khắp phòng? Điều quan trọng không phải là sạch sẽ mà là những khoảnh khắc nghịch ngợm bên bé. Đồ chơi mai vẫn ở đó, đừng tự làm mình mệt. Đôi khi đầu hàng sự bừa bộn là cách nghỉ ngơi tốt nhất.', title_zh = '和家里的混乱和解 🌪️', body_zh = '房间里到处都是玩具？重要的不是干净，而是和宝宝一起度过的这些调皮时光。玩具明天还会在那儿，别累坏自己。有时向凌乱投降，就是最好的休息。' WHERE id = '58d0ef6e-2eed-490f-85f9-8fd8f899a9bd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La táctica secreta de papá 👨‍🍼', body_es = 'Ya tienes bastante con el cansancio del día. Deja que papá, con sus juegos, se encargue de prepararle para dormir y de lavarle los dientes, y tú descansa en silencio a un lado.', title_fr = 'La tactique secrète de papa 👨‍🍼', body_fr = 'La fatigue de la journée vous suffit. Confiez la préparation au coucher et le brossage des dents aux jeux de papa, et reposez-vous au calme, de votre côté.', title_hi = 'पापा की खुफ़िया तरकीब 👨‍🍼', body_hi = 'दिन की थकान आपके लिए काफ़ी है। शाम को बच्चे को सोने के लिए तैयार करना और दाँत ब्रश कराना पापा की मस्ती भरी तरकीबों पर छोड़िए, और आप एक तरफ़ खामोशी से आराम कीजिए।', title_id = 'Taktik rahasia Ayah 👨‍🍼', body_id = 'Kelelahan siang hari sudah cukup bagi Anda. Serahkan persiapan tidur dan menyikat giginya di sore hari pada kejahilan Ayah, sementara Anda beristirahat dengan tenang di samping.', title_ja = 'パパの秘密の作戦 👨‍🍼', body_ja = '昼間の疲れでもう十分。夕方の寝る準備や歯みがきは、パパの遊び心にお任せして、あなたは少し離れて静かに休みましょう。', title_ko = '아빠의 비밀 전략 👨‍🍼', body_ko = '낮 동안의 피로만으로도 충분해요. 저녁 잠자리 준비와 양치는 장난기 많은 아빠에게 맡기고, 엄마는 한쪽에서 조용히 쉬세요.', title_nl = 'Papa''s geheime tactiek 👨‍🍼', body_nl = 'Je bent al moe genoeg van de dag. Laat het klaarmaken voor bed en het tandenpoetsen aan het eind van de middag over aan papa''s spelletjes, en rust jij aan de zijkant in stilte uit.', title_pl = 'Tajna taktyka taty 👨‍🍼', body_pl = 'Masz dość dziennego zmęczenia. Przygotowanie do snu i mycie zębów pod wieczór powierz zabawowym pomysłom taty, a ty w ciszy odpocznij z boku.', title_pt = 'A tática secreta do pai 👨‍🍼', body_pt = 'O cansaço do dia já chega. Entregue às brincadeiras do pai a preparação para dormir e a escovagem dos dentes ao fim da tarde, e descanse à parte, em silêncio.', title_sv = 'Pappas hemliga taktik 👨‍🍼', body_sv = 'Dagens trötthet räcker för dig. Lämna över kvällens förberedelser för läggdags och tandborstningen åt pappas lekfullhet, och vila i tystnad en bit bort.', title_vi = 'Chiến thuật bí mật của bố 👨‍🍼', body_vi = 'Mệt mỏi ban ngày đã quá đủ với mẹ. Hãy giao việc chuẩn bị cho bé đi ngủ và đánh răng cho những trò vui của bố, còn mẹ ngồi một góc yên tĩnh nghỉ ngơi.', title_zh = '爸爸的秘密战术 👨‍🍼', body_zh = '白天的疲惫已经够你受了。傍晚哄睡前的准备、刷牙这些事，就交给爱玩的爸爸吧，你在一旁安安静静地休息。' WHERE id = 'd52a333c-1a4b-40fd-a11c-b3544628c6df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un mejor amigo muy peculiar 🥄', body_es = '¿Con tantos juguetes caros, ha encontrado una espátula de silicona en la cocina y se pasa el día paseándola y acostándola? El cerebro de un niño es increíble. No intervengas, deja que quiera a su espátula.', title_fr = 'Un drôle de meilleur ami 🥄', body_fr = 'Avec tous ces jouets coûteux, il a trouvé une spatule en silicone dans la cuisine et la promène toute la journée, il la fait même dormir ? Le cerveau d''un enfant est incroyable. Ne l''en empêchez pas, laissez-le aimer sa spatule.', title_hi = 'अनोखा सबसे अच्छा दोस्त 🥄', body_hi = 'इतने महँगे खिलौनों के बावजूद रसोई से एक सिलिकॉन स्पैचुला ढूँढ लाया और दिनभर उसे लेकर घूमता है, उसे सुलाता है? बच्चे का दिमाग अद्भुत है। मत रोकिए, उसे स्पैचुला से प्यार करने दीजिए।', title_id = 'Sahabat terbaik yang aneh 🥄', body_id = 'Padahal ada begitu banyak mainan mahal, ia malah menemukan spatula silikon di dapur, membawanya ke mana-mana seharian, bahkan menidurkannya? Otak anak sungguh menakjubkan. Jangan halangi, biarkan ia menyayangi spatulanya.', title_ja = 'ふしぎな親友 🥄', body_ja = '高いおもちゃがたくさんあるのに、キッチンからシリコンのへらを見つけて、一日じゅう持ち歩いて寝かしつけていますか？子どもの脳は驚くべきもの。じゃまをせず、へらを好きにさせてあげましょう。', title_ko = '별난 단짝 친구 🥄', body_ko = '비싼 장난감이 그렇게 많은데 주방에서 실리콘 주걱을 찾아 하루 종일 들고 다니며 재우기까지 하나요? 아이의 머릿속은 정말 놀라워요. 방해하지 말고 주걱을 사랑하게 두세요.', title_nl = 'Vreemde beste vriend 🥄', body_nl = 'Al dat dure speelgoed, en hij vindt een siliconen spatel in de keuken en sjouwt er de hele dag mee rond en legt hem zelfs te slapen? Een kinderbrein is ongelooflijk. Stoor hem niet, laat hem lekker van zijn spatel houden.', title_pl = 'Dziwny najlepszy przyjaciel 🥄', body_pl = 'Ma tyle drogich zabawek, a znalazł w kuchni silikonową łopatkę i cały dzień z nią chodzi, a nawet ją usypia? Dziecięcy mózg jest niesamowity. Nie przeszkadzaj, niech kocha swoją łopatkę.', title_pt = 'Um melhor amigo estranho 🥄', body_pt = 'Com tantos brinquedos caros, foi buscar uma espátula de silicone à cozinha e anda com ela o dia todo, até a põe a dormir? O cérebro de uma criança é incrível. Não interfira, deixe-o gostar da espátula.', title_sv = 'En märklig bästis 🥄', body_sv = 'Trots alla dyra leksaker har barnet hittat en silikonslickepott i köket, går omkring med den hela dagen och nattar den? Barnhjärnan är otrolig. Hindra inte, låt barnet älska sin slickepott.', title_vi = 'Người bạn thân kỳ lạ 🥄', body_vi = 'Có biết bao đồ chơi đắt tiền, vậy mà bé tìm được chiếc thìa silicon trong bếp, mang theo cả ngày và còn ru nó ngủ? Trí óc trẻ con thật khó tin. Đừng ngăn bé, cứ để bé yêu chiếc thìa ấy.', title_zh = '奇怪的好朋友 🥄', body_zh = '明明有那么多昂贵的玩具，宝宝却从厨房找来一把硅胶铲，整天带着它到处走，还哄它睡觉？孩子的大脑真是不可思议。别阻止，就让宝宝爱这把铲子吧。' WHERE id = 'dbff772c-4b84-4bcd-8132-9e03a5a6d600' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sorpresa en la lista 🛒', body_es = 'Antes de ir al súper abriste la Lista de la compra y viste que tu peque había venido por detrás, había tocado la pantalla y había añadido chocolate. Sí, ¡saben de tecnología más que tú!', title_fr = 'Surprise dans la liste 🛒', body_fr = 'Avant d''aller au supermarché, vous ouvrez la Liste de courses et voyez qu''il est venu dans votre dos appuyer sur l''écran pour y ajouter du chocolat. Eh oui, ils maîtrisent la technologie mieux que vous !', title_hi = 'लिस्ट में सरप्राइज़ 🛒', body_hi = 'बाज़ार जाने से पहले शॉपिंग लिस्ट खोली और देखा कि उसने पीछे से आकर स्क्रीन दबाकर उसमें चॉकलेट जोड़ दी है? हाँ, ये टेक्नोलॉजी आपसे बेहतर जानते हैं!', title_id = 'Kejutan di daftar belanja 🛒', body_id = 'Sebelum belanja Anda membuka Daftar Belanja dan melihat ia datang dari belakang, menekan layar ponsel, dan menambahkan cokelat ke sana. Ya, mereka lebih paham teknologi daripada Anda!', title_ja = 'リストのサプライズ 🛒', body_ja = '買い物の前に「買い物リスト」を開いたら、後ろからやってきて画面をタップし、チョコレートを追加していた？そう、テクノロジーはあなたよりよく知っているのです！', title_ko = '목록 속 깜짝 선물 🛒', body_ko = '마트에 가기 전 쇼핑 목록을 열었더니 아이가 뒤에서 다가와 화면을 눌러 초콜릿을 추가했나요? 네, 아이들은 기술을 엄마보다 더 잘 알아요!', title_nl = 'Verrassing op het lijstje 🛒', body_nl = 'Je opende voor het boodschappen doen je Boodschappenlijstje en zag dat hij achter je was komen staan, op het scherm tikte en chocola had toegevoegd. Ja, ze kennen de techniek beter dan jij!', title_pl = 'Niespodzianka na liście 🛒', body_pl = 'Przed wyjściem do sklepu otworzyłaś Listę zakupów i zobaczyłaś, że podkradł się, nacisnął ekran telefonu i dopisał czekoladę? Tak, znają się na technologii lepiej od ciebie!', title_pt = 'Surpresa na lista 🛒', body_pt = 'Antes de ir ao supermercado, abriu a Lista de Compras e viu que ele veio por trás, carregou no ecrã e acrescentou chocolate? Pois é, sabem mais de tecnologia do que nós!', title_sv = 'Överraskning på listan 🛒', body_sv = 'Du öppnade Inköpslistan innan du skulle handla och såg att barnet kommit bakifrån, tryckt på skärmen och lagt till choklad. Ja, de kan tekniken bättre än du!', title_vi = 'Bất ngờ trong danh sách 🛒', body_vi = 'Trước khi đi siêu thị mẹ mở Danh sách mua sắm và thấy bé đã lén chạm vào màn hình thêm sô-cô-la vào đó. Đúng vậy, bé rành công nghệ hơn cả mẹ!', title_zh = '清单里的惊喜 🛒', body_zh = '去超市前打开购物清单，发现宝宝从身后跑来，按着手机屏幕往里加了巧克力？没错，他们比你还懂科技！' WHERE id = 'e3d2e3a9-22c5-44f1-a54d-89fc427e1f7c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento lo dirige tu peque 🪄', body_es = 'Los libros clásicos os aburren a los dos. Abre Cuentos inteligentes, haz que el protagonista sea tu peque y el lugar por salvar, su habitación, y crea una sesión de sueño original, tranquila y libre.', title_fr = 'C''est lui qui mène le conte 🪄', body_fr = 'Vous en avez assez tous les deux des livres classiques. Ouvrez les Contes intelligents, faites de votre enfant le héros et de sa chambre le lieu à sauver, et créez une séance du coucher extraordinaire, calme et libre.', title_hi = 'कहानी की डोर उसके हाथ 🪄', body_hi = 'पुरानी किताबों से आप दोनों ऊब गए हैं? स्मार्ट कहानियाँ खोलिए, मुख्य हीरो अपने बच्चे को और बचाई जाने वाली जगह उसके कमरे को बनाइए, और एक अनोखा, शांत और खुला नींद का सेशन रचिए।', title_id = 'Kendali dongeng ada padanya 🪄', body_id = 'Kalian berdua bosan dengan buku klasik. Buka Dongeng Pintar, jadikan anak Anda tokoh utama dan kamarnya tempat yang harus diselamatkan, lalu ciptakan sesi tidur yang luar biasa, tenang, dan bebas.', title_ja = 'お話の主導権はお子さんに 🪄', body_ja = 'いつもの絵本にふたりともあきてしまった？「スマートおはなし」を開いて、主人公はお子さん、救う場所はお子さんの部屋にして、特別で静かな、自由なおやすみの時間をつくりましょう。', title_ko = '이야기의 지휘봉은 아이에게 🪄', body_ko = '늘 읽던 책이 둘 다 지겨워졌나요? 스마트 동화를 열어 아이를 주인공으로, 아이의 방을 구해야 할 장소로 정해 특별하고 조용하며 자유로운 잠자리 시간을 만들어 보세요.', title_nl = 'Hij bepaalt het sprookje 🪄', body_nl = 'Zijn jullie allebei de klassieke boekjes beu? Open Slimme sprookjes, maak je kindje de hoofdpersoon en zijn kamer de plek die gered moet worden, en creëer zo een bijzonder, rustig en vrij slaapmoment.', title_pl = 'Bajka w jego rękach 🪄', body_pl = 'Oboje macie dość klasycznych książek. Otwórz Mądre bajki, zrób dziecko głównym bohaterem, a jego pokój miejscem do uratowania, i stwórzcie niezwykły, cichy i swobodny seans przed snem.', title_pt = 'A história é ele que comanda 🪄', body_pt = 'Estão os dois fartos dos livros clássicos. Abra as Histórias Inteligentes, faça do seu filho o herói principal e do quarto dele o lugar a salvar, e crie uma sessão de sono fora do comum, tranquila e livre.', title_sv = 'Barnet styr sagan 🪄', body_sv = 'Ni är båda trötta på klassiska böcker. Öppna Smarta sagor, gör barnet till huvudperson och barnets rum till platsen som ska räddas, och skapa en ovanlig, lugn och fri godnattstund.', title_vi = 'Bé nắm quyền điều khiển câu chuyện 🪄', body_vi = 'Cả hai mẹ con đều chán những cuốn sách kinh điển? Hãy mở Truyện cổ tích thông minh, chọn bé làm nhân vật chính và căn phòng của bé là nơi cần giải cứu để tạo một buổi ru ngủ khác thường, yên tĩnh và tự do.', title_zh = '故事由宝宝掌控 🪄', body_zh = '你们俩都读腻了经典故事书？打开智能故事，让孩子当主角，把要拯救的地方设为宝宝的房间，来一场与众不同、安静又自由的睡前故事吧。' WHERE id = '5242afc1-567f-496d-81cf-522c0271690e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La resistencia del «Yo solo» 🛑', body_es = '¿Quiere atarse él solo los cordones y se te van 10 minutos? No le metas prisa, dale tiempo. Intentarlo y equivocarse es la base de su futura capacidad para resolver problemas.', title_fr = 'La résistance du « Tout seul » 🛑', body_fr = 'Il veut faire ses lacets tout seul et vous y perdez 10 minutes ? Ne le pressez pas, laissez-lui du temps. Ses essais et ses erreurs sont la base de sa future capacité à résoudre les problèmes.', title_hi = '''मैं खुद'' वाली ज़िद 🛑', body_hi = 'जूते के फीते खुद बाँधना चाहता है और आपके 10 मिनट चले जाते हैं? जल्दी मत कीजिए, उसे समय दीजिए। कोशिश करना और गलती करना ही आगे समस्याएँ सुलझाने की उसकी क्षमता की नींव है।', title_id = 'Ngotot ''Aku sendiri'' 🛑', body_id = 'Ia ingin mengikat tali sepatunya sendiri dan 10 menit Anda pun habis? Jangan terburu-buru, beri ia waktu. Mencoba dan salah adalah dasar kemampuannya memecahkan masalah kelak.', title_ja = '「自分で！」の抵抗 🛑', body_ja = '自分で靴ひもを結びたがって、10分もかかっていますか？急がず、時間をあげましょう。挑戦と失敗が、将来の問題解決力の土台になります。', title_ko = '''내가 할 거야'' 고집 🛑', body_ko = '신발 끈을 혼자 묶겠다고 해서 10분이 걸리나요? 서두르지 말고 시간을 주세요. 시도하고 틀려 보는 경험이 앞으로의 문제 해결 능력의 바탕이 돼요.', title_nl = 'Het verzet van ''Zelf doen'' 🛑', body_nl = 'Wil hij zelf zijn veters strikken en kost dat je 10 minuten? Haast je niet, geef hem de tijd. Proberen en vergissen is de basis voor zijn probleemoplossend vermogen later.', title_pl = 'Opór „Ja sam” 🛑', body_pl = 'Chce sam zawiązać sznurowadła i zajmuje ci to 10 minut? Nie spiesz się, daj mu czas. Próby i błędy to fundament jego przyszłej umiejętności rozwiązywania problemów.', title_pt = 'A resistência do "Eu sozinho" 🛑', body_pt = 'Quer apertar os atacadores sozinho e lá se vão 10 minutos? Não o apresse, dê-lhe tempo. Tentar e errar é a base da capacidade dele de resolver problemas no futuro.', title_sv = 'Motståndet i ”Jag själv” 🛑', body_sv = 'Vill barnet knyta skosnörena själv och det tar 10 minuter? Stressa inte, ge barnet tid. Att försöka och misslyckas är grunden för förmågan att lösa problem i framtiden.', title_vi = 'Sự kháng cự "Con tự làm" 🛑', body_vi = 'Bé muốn tự buộc dây giày và mẹ mất 10 phút chờ? Đừng vội, hãy cho bé thời gian. Những lần thử và sai là nền tảng cho kỹ năng giải quyết vấn đề sau này của bé.', title_zh = '“我自己来”的坚持 🛑', body_zh = '想自己系鞋带，花掉你10分钟？别着急，给宝宝时间。尝试和犯错，是宝宝将来解决问题能力的基础。' WHERE id = 'd5e65c0a-6f82-4fee-945e-ee1f72e84c4a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Alerta del tiempo ⛅', title_fr = 'Alerte météo ⛅', title_hi = 'मौसम की चेतावनी ⛅', title_id = 'Peringatan cuaca ⛅', title_ja = '天気に注意 ⛅', title_ko = '날씨 알림 ⛅', title_nl = 'Weerwaarschuwing ⛅', title_pl = 'Ostrzeżenie pogodowe ⛅', title_pt = 'Alerta de tempo ⛅', title_sv = 'Vädervarning ⛅', title_vi = 'Cảnh báo thời tiết ⛅', title_zh = '天气提醒 ⛅' WHERE id = 'aa798243-c44e-4178-957c-647030916048' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crítico de dibujos animados 📺', body_es = 'Te cuenta con su propia gramática los dibujos que ha visto y te explica muy serio quién fue adónde. Escúchale con atención, como si te sorprendiera. Que se sienta el más listo del mundo.', title_fr = 'Critique de dessins animés 📺', body_fr = 'Il vous raconte le dessin animé qu''il a vu avec sa propre grammaire, en expliquant très sérieusement qui est allé où. Écoutez-le attentivement, comme si vous étiez surprise. Qu''il se sente le plus malin du monde.', title_hi = 'कार्टून समीक्षक 📺', body_hi = 'देखा हुआ कार्टून अपने व्याकरण में सुनाता है, गंभीरता से समझाता है कि कौन कहाँ गया? उसे ध्यान से, हैरान होने के अंदाज़ में सुनिए। उसे खुद को दुनिया का सबसे समझदार महसूस करने दीजिए।', title_id = 'Kritikus film kartun 📺', body_id = 'Ia menceritakan film kartun yang ditontonnya dengan tata bahasanya sendiri, menjelaskan dengan serius siapa pergi ke mana. Dengarkan dengan saksama, seolah Anda terkejut. Biarkan ia merasa paling pintar di dunia.', title_ja = 'アニメ評論家 📺', body_ja = '見たアニメを自分なりの文法で話して、だれがどこへ行ったかを真剣に説明しますか？驚いたふりをしながら、しっかり聞いてあげましょう。世界一賢いと感じさせてあげて。', title_ko = '만화 평론가 📺', body_ko = '본 만화를 자기만의 문법으로 들려주며 누가 어디로 갔는지 진지하게 설명하나요? 놀란 듯이 귀 기울여 들어 주세요. 세상에서 가장 똑똑한 사람이 된 기분을 느끼게 해 주세요.', title_nl = 'Tekenfilmcriticus 📺', body_nl = 'Vertelt hij je met zijn eigen grammatica over de tekenfilm die hij zag en legt hij serieus uit wie waar naartoe ging? Luister aandachtig, alsof je verbaasd bent. Laat hem zich de slimste ter wereld voelen.', title_pl = 'Krytyk filmów animowanych 📺', body_pl = 'Opowiada ci obejrzaną bajkę własną gramatyką, z powagą tłumacząc, kto dokąd poszedł. Słuchaj go uważnie, jakbyś była zaskoczona. Niech poczuje się najmądrzejszy na świecie.', title_pt = 'Crítico de desenhos animados 📺', body_pt = 'Conta-lhe o desenho animado que viu com a sua própria gramática e explica muito a sério quem foi para onde. Ouça-o com atenção, como se estivesse surpreendida. Deixe-o sentir-se a pessoa mais inteligente do mundo.', title_sv = 'Tecknade filmens kritiker 📺', body_sv = 'Berättar barnet om den tecknade filmen hen sett med sin egen grammatik och förklarar allvarligt vem som gick vart? Lyssna noga och låtsas bli förvånad. Låt barnet känna sig som världens smartaste.', title_vi = 'Nhà phê bình phim hoạt hình 📺', body_vi = 'Bé kể cho mẹ nghe bộ phim hoạt hình vừa xem bằng ngữ pháp của riêng mình, nghiêm túc giải thích ai đi đâu. Hãy chăm chú lắng nghe như thể thật ngạc nhiên. Để bé cảm thấy mình thông minh nhất thế giới.', title_zh = '动画片评论家 📺', body_zh = '用自己的语法给你讲刚看的动画片，一本正经地解释谁去了哪里。认真地、带着惊讶的表情听宝宝讲。让宝宝觉得自己是世界上最聪明的人。' WHERE id = 'b3ff48b4-aa5c-406e-999b-73655dca1c90' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la oscuridad 🌙', body_es = 'Para que se duerma antes, apaga todas las luces extra de la habitación y las pantallas de las tablets. La melatonina solo se produce rápido en un ambiente oscuro y sin tecnología.', title_fr = 'Le pouvoir du noir 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles et les écrans de tablette de la chambre. La mélatonine n''est sécrétée rapidement que dans le noir, sans technologie.', title_hi = 'अंधेरे की ताकत 🌙', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और टैबलेट की स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ अंधेरे और बिना गैजेट वाले माहौल में तेज़ी से बनता है।', title_id = 'Kekuatan gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan dan layar tablet di kamar. Melatonin hanya diproduksi dengan cepat dalam suasana gelap dan bebas teknologi.', title_ja = '暗やみの力 🌙', body_ja = '早く寝つけるように、部屋の余分な明かりとタブレットの画面をすべて消しましょう。メラトニンは、暗くて機器のない環境でこそすばやく分泌されます。', title_ko = '어둠의 힘 🌙', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명과 태블릿 화면을 모두 꺼 주세요. 멜라토닌은 어둡고 전자기기 없는 환경에서만 빠르게 분비돼요.', title_nl = 'De kracht van het donker 🌙', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en tabletschermen in de kamer uit. Melatonine wordt alleen in een donkere omgeving zonder techniek snel aangemaakt.', title_pl = 'Moc ciemności 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła i ekrany tabletów. Melatonina wydziela się szybko tylko w ciemnym otoczeniu bez technologii.', title_pt = 'O poder do escuro 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e os ecrãs de tablets. A melatonina só é produzida rapidamente num ambiente escuro e sem tecnologia.', title_sv = 'Mörkrets kraft 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor och surfplattornas skärmar i rummet. Melatonin utsöndras snabbt bara i en mörk miljö utan teknik.', title_vi = 'Sức mạnh của bóng tối 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ và màn hình máy tính bảng trong phòng. Melatonin chỉ được tiết ra nhanh trong môi trường tối và không có thiết bị công nghệ.', title_zh = '黑暗的力量 🌙', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光和平板屏幕。褪黑素只有在昏暗、没有电子设备的环境里才会快速分泌。' WHERE id = 'c83099cc-b126-47d8-b334-d8faf9b45dde' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
