UPDATE public.mommy_day_notifications SET title_es = 'La medida del silencio de oro 🤫', title_fr = 'Mesurer le silence d''or 🤫', title_hi = 'सुनहरी खामोशी का माप 🤫', title_id = 'Ukuran hening emas 🤫', title_ja = '金色の静けさを測る 🤫', title_ko = '황금 같은 고요의 크기 🤫', title_nl = 'De maat van gouden stilte 🤫', title_pl = 'Miara złotej ciszy 🤫', title_pt = 'A medida do silêncio de ouro 🤫', title_sv = 'Mätt gyllene tystnad 🤫', title_vi = 'Thước đo sự tĩnh lặng quý như vàng 🤫', title_zh = '金色安静的度量 🤫' WHERE id = '26929739-4514-47f4-b2ff-3f79743e2a52' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Modo avión de papá ✈️', body_es = 'No ha podido soltar su energía en casa y se resiste a ir a la cama. Pide ayuda a papá. Cuando le levanta en el aire y le hace volar como un avión, las carcajadas llenan la habitación y todo el estrés físico acumulado desaparece en segundos.', title_fr = 'Papa en mode avion ✈️', body_fr = 'Il n''a pas pu se défouler à la maison et résiste au coucher. Appelez papa à la rescousse. Quand il le soulève et le fait voler comme un avion, les éclats de rire envahissent la pièce et tout le stress physique accumulé disparaît en quelques secondes.', title_hi = 'पापा का फ़्लाइट मोड ✈️', body_hi = 'घर में ऊर्जा नहीं निकल पाई और बिस्तर पर जाने से अड़ गया? पापा को मदद के लिए बुलाइए। जब वे बच्चे को हवा में उठाकर हवाई जहाज़ बनाते हैं, तो ठहाके कमरे में भर जाते हैं और जमा हुआ सारा शारीरिक तनाव कुछ ही सेकंड में गायब हो जाता है।', title_id = 'Mode terbang Ayah ✈️', body_id = 'Energinya belum tersalurkan di rumah dan ia menolak tidur. Panggil Ayah untuk membantu. Saat Ayah mengangkatnya tinggi dan menjadikannya pesawat, tawa memenuhi kamar dan semua stres fisik yang menumpuk lenyap dalam hitungan detik.', title_ja = 'パパの飛行機モード ✈️', body_ja = '家でエネルギーを出しきれず、ベッドに行くのを拒否していますか？パパに助けを呼びましょう。パパが高く持ち上げて飛行機にすると、部屋は笑い声に包まれ、たまった体のストレスは数秒で消えていきます。', title_ko = '아빠의 비행 모드 ✈️', body_ko = '집에서 에너지를 다 못 쓰고 자러 가지 않겠다고 버티나요? 아빠를 부르세요. 아빠가 아이를 높이 들어 비행기를 태워 주면 방에 웃음이 가득해지고, 쌓인 몸의 긴장이 순식간에 사라져요.', title_nl = 'Papa''s vliegmodus ✈️', body_nl = 'Is hij zijn energie thuis niet kwijtgeraakt en verzet hij zich tegen bedtijd? Roep papa te hulp. Als hij hem optilt en een vliegtuigje maakt, vult het gelach de kamer en verdwijnt alle opgebouwde fysieke stress in een paar seconden.', title_pl = 'Tryb samolotowy taty ✈️', body_pl = 'Nie zdążył w domu spalić energii i opiera się przed pójściem do łóżka. Wezwij tatę na pomoc. Gdy podnosi go w górę i robi z niego samolot, pokój wypełnia się śmiechem, a cały nagromadzony stres fizyczny znika w kilka sekund.', title_pt = 'O modo avião do pai ✈️', body_pt = 'Em casa não conseguiu gastar a energia e resiste a ir para a cama. Chame o pai para ajudar. Quando ele levanta a criança no ar e faz de avião, as gargalhadas enchem o quarto e todo o stress físico acumulado desaparece em segundos.', title_sv = 'Pappas flygläge ✈️', body_sv = 'Barnet har inte fått ut sin energi hemma och vägrar gå och lägga sig. Kalla på pappa. När han lyfter barnet i luften som ett flygplan fylls rummet av skratt och all ackumulerad fysisk stress försvinner på några sekunder.', title_vi = 'Chế độ máy bay của bố ✈️', body_vi = 'Bé chưa xả hết năng lượng và chống cự không chịu lên giường. Hãy gọi bố đến giúp. Khi bố nhấc bé lên cao làm máy bay, tiếng cười sẽ tràn ngập căn phòng và mọi căng thẳng thể chất tích tụ sẽ tan biến trong vài giây.', title_zh = '爸爸的飞行模式 ✈️', body_zh = '在家精力没用完，就是不肯上床。叫爸爸来帮忙。他把孩子举到空中当飞机时，笑声充满整个房间，积攒的身体紧张几秒钟就消失了。' WHERE id = '4cbe2cb0-5188-4114-8447-b099245e7121' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
