UPDATE public.mommy_day_notifications SET title_es = 'Alerta del tiempo ⛅', title_fr = 'Alerte météo ⛅', title_hi = 'मौसम की चेतावनी ⛅', title_id = 'Peringatan cuaca ⛅', title_ja = '天気に注意 ⛅', title_ko = '날씨 알림 ⛅', title_nl = 'Weerwaarschuwing ⛅', title_pl = 'Ostrzeżenie pogodowe ⛅', title_pt = 'Alerta de tempo ⛅', title_sv = 'Vädervarning ⛅', title_vi = 'Cảnh báo thời tiết ⛅', title_zh = '天气提醒 ⛅' WHERE id = 'bfca2126-084c-4371-a225-6bbeaa8fe2d1' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Prueba a cortar con música clásica suave las tormentas sin motivo que estallan a última hora de la tarde. Muchas veces este truco sencillo pero eficaz hace milagros en casa y llena la habitación de paz.', body_fr = 'Essayez de stopper les tempêtes sans raison de fin d''après-midi avec une musique classique douce. Souvent, cette astuce simple mais efficace fait des miracles et ramène la paix dans la pièce.', body_hi = 'शाम को अचानक उठने वाले बेवजह के तूफ़ानों को हल्के शास्त्रीय संगीत से रोककर देखिए। अक्सर यह आसान लेकिन असरदार तरकीब घर में जादू कर देती है और कमरे में पूरा सुकून ले आती है।', body_id = 'Coba redakan badai tanpa sebab di sore hari dengan musik klasik yang lembut. Trik sederhana namun ampuh ini sering kali membawa keajaiban di rumah dan pasti mendatangkan ketenangan.', body_ja = '夕方に起きる理由のない嵐を、静かなクラシック音楽でしずめてみましょう。このシンプルで効果的な工夫が、家に奇跡を起こし、部屋に安らぎを運んでくれることがよくあります。', body_ko = '저녁 무렵 이유 없이 몰아치는 폭풍을 잔잔한 클래식 음악으로 잠재워 보세요. 이 간단하지만 효과적인 요령이 집에 기적을 일으키고 방에 평온을 가져다줄 때가 많아요.', body_nl = 'Probeer de onverklaarbare buien aan het eind van de middag te stoppen met zachte klassieke muziek. Vaak doet dit simpele maar krachtige trucje wonderen en brengt het echt rust in de kamer.', body_pl = 'Spróbuj przerywać wieczorne burze bez powodu cichą muzyką klasyczną. Ta prosta, ale skuteczna sztuczka często czyni w domu cuda i na pewno wnosi do pokoju spokój.', body_pt = 'Experimente travar com música clássica suave as tempestades sem razão que rebentam ao fim da tarde. Muitas vezes este truque simples, mas eficaz, faz milagres em casa e traz paz ao quarto.', body_sv = 'Prova att stoppa eftermiddagens stormar utan orsak med lätt klassisk musik. Ofta gör det här enkla men effektiva knepet underverk hemma och ger rummet total ro.', body_vi = 'Hãy thử chặn những cơn bão vô cớ lúc chiều tối bằng nhạc cổ điển nhẹ nhàng. Mẹo đơn giản nhưng hiệu quả này thường tạo nên điều kỳ diệu và mang lại bình yên cho căn phòng.', body_zh = '试试用轻柔的古典音乐平息傍晚莫名的风暴。这个简单却有效的小妙招，常常能在家里创造奇迹，给房间带来真正的宁静。' WHERE id = '3f3676c6-cf62-4752-a389-70e0f348c529' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
