UPDATE public.mommy_day_notifications SET title_es = 'Yo en el cuento inteligente 🪄', body_es = 'Os sabéis de memoria los libros clásicos. Abre Cuentos inteligentes, haz que el protagonista sea tu peque y el lugar por conquistar, su habitación, y crea una sesión de sueño fuera de lo común.', title_fr = 'Moi, dans un Conte intelligent 🪄', body_fr = 'Vous connaissez les livres classiques par cœur. Ouvrez les Contes intelligents, faites de votre enfant le héros et de sa chambre le lieu à conquérir, et créez une séance du coucher extraordinaire.', title_hi = 'स्मार्ट कहानी में मैं 🪄', body_hi = 'पुरानी किताबें आपको रट गई हैं? स्मार्ट कहानियाँ खोलिए, मुख्य हीरो अपने बच्चे को और जीतने वाली जगह उसके कमरे को बनाइए, और नींद का एक अनोखा सेशन रचिए।', title_id = 'Aku di Dongeng Pintar 🪄', body_id = 'Anda sudah hafal semua buku klasik. Buka Dongeng Pintar, rancang anak Anda sebagai tokoh utama dan kamarnya sebagai tempat yang harus ditaklukkan, lalu ciptakan sesi tidur yang luar biasa.', title_ja = '「スマートおはなし」の主人公はわたし 🪄', body_ja = 'いつもの絵本はもう暗記してしまった？「スマートおはなし」を開いて、主人公はお子さん、冒険の舞台はお子さんの部屋にして、特別な寝かしつけの時間をつくりましょう。', title_ko = '스마트 동화 속의 나 🪄', body_ko = '늘 읽던 책은 이미 다 외웠죠. 스마트 동화를 열어 아이를 주인공으로, 아이의 방을 정복할 장소로 정해 특별한 잠자리 시간을 만들어 보세요.', title_nl = 'Ik in het slimme sprookje 🪄', body_nl = 'Ken je de klassieke boekjes uit je hoofd? Open Slimme sprookjes, maak je kindje de hoofdpersoon en zijn kamer de plek die veroverd moet worden, en creëer zo een bijzonder slaapmoment.', title_pl = 'Ja w Mądrej bajce 🪄', body_pl = 'Znasz już klasyczne książki na pamięć. Otwórz Mądre bajki, zrób dziecko głównym bohaterem, a jego pokój miejscem do zdobycia, i stwórzcie niezwykły seans przed snem.', title_pt = 'Eu na história inteligente 🪄', body_pt = 'Já sabe os livros clássicos de cor. Abra as Histórias Inteligentes, faça do seu filho o herói principal e do quarto dele o lugar a conquistar, e crie uma sessão de sono fora do comum.', title_sv = 'Jag i den smarta sagan 🪄', body_sv = 'Ni kan de klassiska böckerna utantill. Öppna Smarta sagor, gör barnet till huvudperson och barnets rum till platsen som ska erövras, och skapa en ovanlig godnattstund.', title_vi = 'Con trong truyện cổ tích thông minh 🪄', body_vi = 'Mẹ đã thuộc lòng hết sách kinh điển. Hãy mở Truyện cổ tích thông minh, chọn bé làm nhân vật chính và căn phòng của bé là nơi cần chinh phục để tạo một buổi ru ngủ khác thường.', title_zh = '智能故事里的我 🪄', body_zh = '经典故事书你们都背下来了？打开智能故事，让孩子当主角，把要征服的地方设计成宝宝的房间，来一场与众不同的睡前故事吧。' WHERE id = '9c237165-d4a6-41d4-ba0a-333830a89409' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Jugar con el agua es tan divertido que no quiere salir de la bañera aunque tenga los dedos arrugados. Avísale 5 minutos antes y pon un temporizador. La regla de «Cuando suene la campanita, salimos» suele funcionar.', body_fr = 'Jouer dans l''eau est si agréable qu''il refuse de sortir du bain, même les doigts tout fripés. Prévenez-le 5 minutes avant et réglez un minuteur. La règle « Quand ça sonne, on sort » marche souvent.', body_hi = 'पानी से खेलना इतना मज़ेदार है कि उँगलियाँ सिकुड़ जाएँ तब भी टब से निकलना नहीं चाहता? उसे 5 मिनट पहले बता दीजिए और टाइमर लगाइए। ''घंटी बजेगी तो बाहर निकलेंगे'' वाला नियम अक्सर काम करता है।', body_id = 'Bermain air begitu menyenangkan sampai jarinya keriput pun ia tidak mau keluar dari bak mandi. Beri tahu 5 menit sebelumnya dan pasang timer. Aturan ''Kita keluar saat bel berbunyi'' biasanya berhasil.', body_ja = 'お水遊びが楽しすぎて、指がしわしわになってもお風呂から出たがらない？5分前に知らせて、タイマーをセットしましょう。「ベルが鳴ったら出るよ」のルールはたいていうまくいきます。', body_ko = '물놀이가 너무 재미있어서 손가락이 쪼글쪼글해져도 욕조에서 나오기 싫어하나요? 5분 전에 미리 알려 주고 타이머를 맞추세요. ''알람이 울리면 나가기'' 규칙이 잘 통할 때가 많아요.', body_nl = 'Spelen met water is zo leuk dat hij niet uit bad wil, ook al zijn zijn vingers gerimpeld. Waarschuw hem 5 minuten vooraf en zet een timer. De regel ''Als de bel gaat, gaan we eruit'' werkt meestal.', body_pl = 'Zabawa wodą jest tak przyjemna, że choć ma już pomarszczone paluszki, nie chce wyjść z wanny. Uprzedź go 5 minut wcześniej i nastaw timer. Zasada „Gdy zadzwoni dzwonek, wychodzimy” często działa.', body_pt = 'Brincar com a água é tão bom que, mesmo com os dedos enrugados, não quer sair da banheira. Avise-o 5 minutos antes e programe um temporizador. A regra "quando tocar, saímos" resulta muitas vezes.', body_sv = 'Det är så roligt att leka med vattnet att barnet inte vill gå ur badet trots att fingrarna är skrynkliga. Förvarna 5 minuter innan och ställ in en timer. Regeln ”När klockan ringer går vi upp” fungerar ofta.', body_vi = 'Nghịch nước vui đến mức dù ngón tay đã nhăn nheo, bé vẫn không chịu ra khỏi bồn. Hãy báo trước cho bé 5 phút và đặt hẹn giờ. Quy tắc "Chuông reo là mình ra" thường rất hiệu quả.', body_zh = '玩水太开心了，手指都泡皱了还不肯出浴缸。提前5分钟提醒宝宝，再设个计时器。“铃声响了就出来”的规则往往很管用。' WHERE id = '62114884-cb2a-44c8-ab0b-33ab815b8e09' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que escriba él el final del cuento 🪄', title_fr = 'C''est lui qui écrit la fin du conte 🪄', title_hi = 'कहानी का अंत वह लिखे 🪄', title_id = 'Biar ia yang menulis akhir cerita 🪄', title_ja = 'お話の結末はお子さんが作る 🪄', title_ko = '동화의 결말은 아이가 써요 🪄', title_nl = 'Laat hem het einde van het sprookje schrijven 🪄', title_pl = 'Niech on napisze zakończenie 🪄', title_pt = 'Ele que escreva o fim da história 🪄', title_sv = 'Låt barnet skriva sagans slut 🪄', title_vi = 'Để bé viết đoạn kết 🪄', title_zh = '让宝宝来写故事的结局 🪄' WHERE id = 'd2d2c46d-7705-4c59-b1ff-a6a3d0986863' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La confirmación del silencio 🤫', title_fr = 'La preuve du silence 🤫', title_hi = 'खामोशी का सबूत 🤫', title_id = 'Bukti keheningan 🤫', title_ja = '静けさを確かめる 🤫', title_ko = '고요를 확인하세요 🤫', title_nl = 'Bevestiging van de stilte 🤫', title_pl = 'Potwierdzona cisza 🤫', title_pt = 'A confirmação do silêncio 🤫', title_sv = 'Bekräftad tystnad 🤫', title_vi = 'Xác nhận sự yên tĩnh 🤫', title_zh = '确认安静 🤫' WHERE id = '9a78401e-398c-45fd-a3a7-dae1cd59ed31' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una pausa para mamá ☕', body_es = 'Mientras juega solo, no corras a hacer tareas de casa. El desorden no se va a escapar, pero tu energía sí puede agotarse. Siéntate y tómate tu café caliente.', title_fr = 'Une pause pour maman ☕', body_fr = 'Quand il joue tout seul, ne foncez pas tout de suite vers les tâches ménagères. Le désordre ne va pas s''envoler, mais votre énergie peut s''épuiser. Asseyez-vous et buvez votre café chaud.', title_hi = 'माँ के लिए ब्रेक ☕', body_hi = 'बच्चा अपने आप खेल रहा है तो तुरंत घर के काम में मत भागिए। कमरे की बिखरी चीज़ें कहीं नहीं जाएँगी, लेकिन आपकी ऊर्जा खत्म हो सकती है। बैठिए और अपनी गर्म कॉफ़ी पीजिए।', title_id = 'Rehat untuk Ibu ☕', body_id = 'Saat anak bermain sendiri, jangan langsung lari ke pekerjaan rumah. Kamar yang berantakan tidak akan ke mana-mana, tetapi energi Anda bisa habis. Duduklah dan minum kopi hangat Anda.', title_ja = 'ママのひと休み ☕', body_ja = 'お子さんがひとりで遊んでいるとき、すぐに家事に走らないで。散らかった部屋は逃げませんが、あなたのエネルギーは尽きてしまいます。座って温かいコーヒーを飲みましょう。', title_ko = '엄마를 위한 쉼표 ☕', body_ko = '아이가 혼자 놀 때 바로 집안일로 달려가지 마세요. 어질러진 방은 어디 가지 않지만 엄마의 기운은 바닥날 수 있어요. 앉아서 따뜻한 커피를 드세요.', title_nl = 'Pauze voor mama ☕', body_nl = 'Ren niet meteen naar het huishouden als hij zelf speelt. De rommel loopt niet weg, maar jouw energie kan wel op raken. Ga zitten en drink je koffie warm.', title_pl = 'Przerwa dla mamy ☕', body_pl = 'Gdy dziecko bawi się samo, nie biegnij od razu do obowiązków. Bałagan nie ucieknie, ale twoja energia może się skończyć. Usiądź i wypij ciepłą kawę.', title_pt = 'Pausa para a mãe ☕', body_pt = 'Quando a criança brinca sozinha, não corra logo para as tarefas de casa. A desarrumação não foge, mas a sua energia pode acabar. Sente-se e beba o seu café quente.', title_sv = 'Paus för mamma ☕', body_sv = 'Rusa inte iväg till hushållet så fort barnet leker själv. Stöket i rummet springer ingenstans, men din energi kan ta slut. Sätt dig och drick ditt varma kaffe.', title_vi = 'Phút nghỉ của mẹ ☕', body_vi = 'Khi bé tự chơi, đừng vội lao vào việc nhà. Căn phòng bừa bộn không chạy đi đâu được, nhưng năng lượng của mẹ thì có thể cạn. Hãy ngồi xuống và uống tách cà phê nóng.', title_zh = '妈妈的休息时间 ☕', body_zh = '孩子自己玩的时候，别急着去做家务。房间乱了跑不掉，可你的精力却会耗尽。坐下来，喝杯热咖啡吧。' WHERE id = '8b9fda41-95cb-4937-8a79-67166a02c4b7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
