UPDATE public.mommy_day_notifications SET title_es = 'Descifrar el terror nocturno 😭', title_fr = 'Décoder la terreur nocturne 😭', title_hi = 'नाइट टेरर का राज़ 😭', title_id = 'Kode rahasia teror malam 😭', title_ja = '夜驚症の暗号を解く 😭', title_ko = '야경증 해독하기 😭', title_nl = 'De code van nachtangst 😭', title_pl = 'Szyfr lęku nocnego 😭', title_pt = 'Decifrar o terror noturno 😭', title_sv = 'Nattskräckens kod 😭', title_vi = 'Giải mã hoảng sợ ban đêm 😭', title_zh = '解开夜惊的密码 😭' WHERE id = 'e3cb9a40-b6ca-4e32-b4da-ab6d4899625b' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo abrázale 🫂', body_es = 'No hace falta ningún juego, libro ni cuento. Esta noche simplemente abrázale contra tu pecho, respira su olor tan rico y susúrrale en la oscuridad lo valioso que es para ti.', title_fr = 'Serrez-le simplement 🫂', body_fr = 'Pas besoin de jeu, de livre ni de conte. Ce soir, serrez-le simplement contre vous, respirez sa délicieuse odeur et chuchotez-lui dans le noir combien il est précieux.', title_hi = 'बस गले लगाइए 🫂', body_hi = 'किसी खेल, किताब या कहानी की ज़रूरत नहीं। आज शाम बस उसे सीने से लगाइए, उसकी प्यारी खुशबू महसूस कीजिए और अंधेरे में फुसफुसाकर बताइए कि वह आपके लिए कितना कीमती है।', title_id = 'Cukup peluk 🫂', body_id = 'Tidak perlu permainan, buku, atau dongeng. Malam ini cukup dekap ia di dada, hirup aroma indahnya, dan bisikkan dalam gelap betapa berharganya ia bagi Anda.', title_ja = 'ただ抱きしめて 🫂', body_ja = '遊びも絵本もお話もいりません。今夜はただ胸に抱きしめて、そのいいにおいを深く吸いこみ、暗やみの中でどれほど大切な存在かをささやいてあげましょう。', title_ko = '그냥 안아 주세요 🫂', body_ko = '오늘 밤엔 놀이도, 책도, 동화도 필요 없어요. 그냥 꼭 끌어안고 그 사랑스러운 냄새를 깊이 들이마신 뒤, 어둠 속에서 얼마나 소중한 존재인지 속삭여 주세요.', title_nl = 'Gewoon knuffelen 🫂', body_nl = 'Je hebt geen spelletje, boek of sprookje nodig. Druk hem vanavond gewoon tegen je borst, snuif zijn heerlijke geurtje op en fluister in het donker hoe dierbaar hij voor je is.', title_pl = 'Po prostu przytul 🫂', body_pl = 'Nie potrzeba żadnej zabawy, książki ani bajki. Dziś wieczorem po prostu przytul go mocno do piersi, wdychaj jego cudowny zapach i szepnij w ciemności, jak bardzo jest dla ciebie cenny.', title_pt = 'Só um abraço 🫂', body_pt = 'Não precisa de jogos, livros nem histórias. Esta noite, simplesmente aperte-o contra o peito, respire aquele cheiro maravilhoso e sussurre-lhe no escuro o quanto é precioso.', title_sv = 'Bara en kram 🫂', body_sv = 'Inga lekar, böcker eller sagor behövs. I kväll, håll bara barnet tätt intill dig, andas in den underbara doften och viska i mörkret hur värdefull hen är.', title_vi = 'Chỉ cần ôm thôi 🫂', body_vi = 'Không cần trò chơi, sách vở hay truyện cổ tích. Tối nay chỉ cần ôm bé vào lòng, hít hà mùi hương thơm tho của bé và thì thầm trong bóng tối rằng bé quý giá với mẹ biết bao.', title_zh = '抱一抱就好 🫂', body_zh = '不需要任何游戏、书或故事。今晚就把宝宝紧紧抱在怀里，深深闻一闻那好闻的味道，在黑暗中轻声告诉宝宝，宝宝对你有多珍贵。' WHERE id = '10d94f4d-5823-4afc-963c-ff0397bf1a29' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
