UPDATE public.mommy_day_notifications SET title_es = 'Imitando profesiones 🩺', body_es = '¿Cura a su osito o arregla coches? Los juegos simbólicos (roleplay) están en pleno auge.', title_fr = 'Il imite les métiers 🩺', body_fr = 'Il soigne son nounours ou répare ses voitures ? Le jeu symbolique (jeu de rôle) bat son plein.', title_hi = 'पेशों की नकल 🩺', body_hi = 'टेडी बियर का इलाज करता है या गाड़ियाँ ठीक करता है? प्रतीकात्मक खेल (रोलप्ले) शिखर पर है।', title_id = 'Meniru profesi 🩺', body_id = 'Ia mengobati boneka beruangnya atau memperbaiki mobil-mobilan? Permainan simbolis (roleplay) sedang memuncak.', title_ja = 'お仕事ごっこ 🩺', body_ja = 'くまのぬいぐるみを治療したり、くるまを修理したりしていますか？ごっこ遊び（ロールプレイ）が最高潮です。', title_ko = '직업 흉내 내기 🩺', body_ko = '곰 인형을 치료하거나 자동차를 고치나요? 상징 놀이(역할 놀이)가 절정에 이르렀어요.', title_nl = 'Beroepen nadoen 🩺', body_nl = 'Behandelt hij zijn knuffelbeer of repareert hij autootjes? Zijn symbolische spel (rollenspel) bloeit helemaal op.', title_pl = 'Naśladowanie zawodów 🩺', body_pl = 'Leczy misia albo naprawia samochodziki? Zabawa symboliczna (roleplay) rozkwita.', title_pt = 'Imitar profissões 🩺', body_pt = 'Trata o ursinho ou arranja os carrinhos? O jogo simbólico (roleplay) está no auge.', title_sv = 'Leka yrken 🩺', body_sv = 'Doktorerar barnet nallen eller lagar bilarna? Symbolisk lek (rollek) är på topp.', title_vi = 'Đóng vai các nghề nghiệp 🩺', body_vi = 'Bé "chữa bệnh" cho gấu bông hay "sửa" ô tô đồ chơi? Trò chơi biểu tượng (nhập vai) đang ở đỉnh cao.', title_zh = '模仿职业 🩺', body_zh = '给玩具熊“看病”，或者“修理”小汽车？象征性游戏（角色扮演）到了高峰。' WHERE id = '710f54a9-baa0-4889-a361-f7615894b552' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND c