UPDATE public.mommy_day_notifications SET title_es = 'Operación verduras escondidas 🥦', title_fr = 'Opération légumes cachés 🥦', title_hi = 'छिपी सब्ज़ियों का ऑपरेशन 🥦', title_id = 'Operasi sayuran tersembunyi 🥦', title_ja = '野菜かくし作戦 🥦', title_ko = '채소 숨기기 작전 🥦', title_nl = 'Operatie verstopte groenten 🥦', title_pl = 'Operacja: ukryte warzywa 🥦', title_pt = 'Operação legumes escondidos 🥦', title_sv = 'Operation gömda grönsaker 🥦', title_vi = 'Chiến dịch giấu rau 🥦', title_zh = '秘密蔬菜行动 🥦' WHERE id = '8bce8353-bf73-417b-8a15-56b41142ba18' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No intervengas 🧦', body_es = 'Lleva el talón del calcetín por arriba, pero se pasea como la persona más orgullosa del mundo porque se lo ha puesto él solo. No intervengas ni un poquito. La sensación de libertad importa más que vestirse bien.', title_fr = 'N''intervenez pas 🧦', body_fr = 'Le talon de sa chaussette est sur le dessus, mais comme il l''a mise tout seul, il se promène comme la personne la plus fière du monde. N''intervenez surtout pas. Le sentiment de liberté compte plus que de bien s''habiller.', title_hi = 'दखल मत दीजिए 🧦', body_hi = 'मोज़े की एड़ी ऊपर की ओर है, लेकिन खुद पहना है, इसलिए दुनिया के सबसे गर्वीले इंसान की तरह घूम रहा है। ज़रा भी दखल मत दीजिए। आज़ादी का एहसास सही पहनने से ज़्यादा ज़रूरी है।', title_id = 'Jangan ikut campur 🧦', body_id = 'Tumit kaus kakinya ada di atas, tetapi karena memakainya sendiri ia berjalan seperti orang paling bangga di dunia. Jangan ikut campur sedikit pun. Rasa bebas lebih penting daripada berpakaian dengan benar.', title_ja = '手を出さないで 🧦', body_ja = 'くつしたのかかとが上にきているのに、自分ではけたから世界一誇らしげに歩いていますか？少しも口を出さないで。正しく着ることより、自由に感じることのほうが大切です。', title_ko = '끼어들지 마세요 🧦', body_ko = '양말 뒤꿈치가 위로 갔지만 혼자 신었다고 세상에서 가장 뿌듯한 얼굴로 걸어 다니나요? 조금도 끼어들지 마세요. 해냈다는 자유로움이 바르게 신는 것보다 더 중요해요.', title_nl = 'Grijp niet in 🧦', body_nl = 'De hiel van zijn sok zit bovenop, maar hij loopt rond als de trotste mens ter wereld omdat hij hem zelf heeft aangetrokken. Grijp niet in, ook niet een klein beetje. Het gevoel van vrijheid is belangrijker dan het goed aantrekken.', title_pl = 'Nie wtrącaj się 🧦', body_pl = 'Pięta skarpetki jest na górze, ale chodzi dumny jak nikt na świecie, bo założył ją sam. Nie wtrącaj się ani trochę. Poczucie wolności jest ważniejsze niż poprawne ubranie się.', title_pt = 'Não interfira 🧦', body_pt = 'O calcanhar da meia está para cima, mas anda todo orgulhoso porque a calçou sozinho. Não interfira nem um bocadinho. A sensação de liberdade é mais importante do que vestir bem.', title_sv = 'Lägg dig inte i 🧦', body_sv = 'Hälen på strumpan sitter ovanpå, men barnet går omkring som världens stoltaste människa för att hen klädde på sig själv. Lägg dig inte i det minsta. Känslan av frihet är viktigare än att klä sig rätt.', title_vi = 'Đừng can thiệp 🧦', body_vi = 'Gót tất nằm ở phía trên, nhưng vì tự đi được nên bé đi lại như người tự hào nhất thế giới. Đừng can thiệp dù chỉ một chút. Cảm giác tự do quan trọng hơn mặc đúng.', title_zh = '别插手 🧦', body_zh = '袜子后跟穿到了上面，可因为是自己穿的，宝宝像世界上最骄傲的人一样走来走去。一点都别插手。自由感比穿得对更重要。' WHERE id = 'e70841e8-9af5-471e-9ff6-b28774448a7f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
