UPDATE public.mommy_day_notifications SET title_es = 'El verdadero equipo sois vosotros 🌟', body_es = 'Cada paso seguro que da es fruto del esfuerzo compartido tuyo y de tu pareja.', title_fr = 'La vraie équipe, c''est vous 🌟', body_fr = 'Chaque pas assuré est le fruit de vos efforts communs, à vous et à votre partenaire.', title_hi = 'असली टीम आप हैं 🌟', body_hi = 'हर भरोसे भरा कदम आपकी और आपके पार्टनर की साझा मेहनत का नतीजा है।', title_id = 'Kalianlah tim sejati 🌟', body_id = 'Setiap langkah percaya dirinya adalah hasil kerja keras bersama Anda dan pasangan.', title_ja = '本当のチームはあなたたち 🌟', body_ja = '自信に満ちた一歩一歩は、あなたとパートナーが一緒に積み重ねてきた努力の結晶です。', title_ko = '진짜 팀은 바로 두 사람이에요 🌟', body_ko = '자신 있게 내딛는 한 걸음 한 걸음은 엄마와 배우자가 함께 노력한 덕분이에요.', title_nl = 'Jullie zijn het echte team 🌟', body_nl = 'Elke zelfverzekerde stap is het gezamenlijke werk van jou en je partner.', title_pl = 'To wy jesteście prawdziwą drużyną 🌟', body_pl = 'Każdy pewny krok to wasza wspólna zasługa, twoja i twojego partnera.', title_pt = 'A verdadeira equipa são vocês 🌟', body_pt = 'Cada passo confiante é fruto do esforço conjunto seu e do seu companheiro.', title_sv = 'Det är ni som är det riktiga laget 🌟', body_sv = 'Varje säkert steg är ditt och din partners gemensamma verk.', title_vi = 'Hai người mới là đội thực thụ 🌟', body_vi = 'Mỗi bước đi tự tin của bé đều là công sức chung của mẹ và bố.', title_zh = '你们才是真正的团队 🌟', body_zh = '宝宝迈出的每一个自信的小步子，都是你和伴侣共同付出的成果。' WHERE id = '9b33bb20-6873-451a-abe7-084cc34eff93' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Por fin se acabó el caos de casa.', body_es = 'Pon música lofi para tapar los ruidos que llegan por la ventana y deja descansar tu alma.', title_fr = 'Le chaos de la maison est enfin terminé.', body_fr = 'Pour couvrir les bruits venant de la fenêtre, mettez une musique lo-fi et laissez votre esprit se reposer.', title_hi = 'घर की अफ़रा-तफ़री आखिरकार खत्म हुई।', body_hi = 'खिड़की से आती आवाज़ों को रोकने के लिए लोफ़ाई संगीत चलाइए और अपने मन को आराम दीजिए।', title_id = 'Kekacauan di rumah akhirnya usai.', body_id = 'Untuk meredam suara dari jendela, putar musik lofi dan tenangkan jiwa Anda.', title_ja = '家の大騒ぎがやっと終わりました。', body_ja = '窓の外の音をさえぎるためにlofi音楽をかけて、心を休ませましょう。', title_ko = '집 안의 소란이 드디어 끝났어요.', body_ko = '창밖에서 들어오는 소리를 막으려면 로파이 음악을 틀고 마음을 쉬게 하세요.', title_nl = 'De chaos in huis is eindelijk voorbij.', body_nl = 'Zet lofi-muziek op om de geluiden van buiten te blokkeren en laat je hoofd tot rust komen.', title_pl = 'Domowy chaos w końcu się skończył.', body_pl = 'Włącz muzykę lofi, by zagłuszyć odgłosy zza okna, i daj odpocząć duszy.', title_pt = 'O caos em casa acabou finalmente.', body_pt = 'Para abafar os sons que vêm da janela, ponha música lo-fi e descanse a alma.', title_sv = 'Kaoset hemma är äntligen över.', body_sv = 'Sätt på lofi-musik för att blockera ljud från fönstret och låt själen vila.', title_vi = 'Sự hỗn loạn trong nhà cuối cùng đã kết thúc.', body_vi = 'Để chặn tiếng ồn từ cửa sổ, hãy bật nhạc lofi và để tâm hồn được thư giãn.', title_zh = '家里的混乱终于结束了。', body_zh = '打开lofi音乐挡住窗外的声音，让心灵好好休息一下。' WHERE id = '8fab2e02-e35e-45f0-a10f-554adfe7c2c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Modo silencio activado 🤫', body_es = 'Al quedarse dormido está más sensible. Mantén la calma y el silencio.', title_fr = 'Passage en mode silencieux 🤫', body_fr = 'Au moment de l''endormissement, il est plus sensible. Respectez le calme.', title_hi = 'साइलेंट मोड में चलिए 🤫', body_hi = 'सोते समय संवेदनशीलता बढ़ जाती है। खामोशी बनाए रखिए।', title_id = 'Beralih ke mode senyap 🤫', body_id = 'Saat ia mulai terlelap, kepekaannya meningkat. Jagalah ketenangan.', title_ja = 'サイレントモードへ 🤫', body_ja = '寝入りばなは音に敏感になります。静けさを守りましょう。', title_ko = '무음 모드로 전환 🤫', body_ko = '잠드는 순간에는 예민함이 커져요. 조용히 해 주세요.', title_nl = 'Over op stille modus 🤫', body_nl = 'Bij het inslapen is hij extra gevoelig. Zorg voor rust.', title_pl = 'Przejście w tryb cichy 🤫', body_pl = 'Gdy zasypia, jest bardziej wrażliwy. Zadbaj o ciszę.', title_pt = 'Passar ao modo silencioso 🤫', body_pt = 'Ao adormecer, a sensibilidade aumenta. Mantenha o silêncio.', title_sv = 'Över till tyst läge 🤫', body_sv = 'Känsligheten ökar när barnet håller på att somna. Håll det lugnt.', title_vi = 'Chuyển sang chế độ im lặng 🤫', body_vi = 'Lúc bé đang chìm vào giấc ngủ là lúc nhạy cảm nhất. Hãy giữ yên tĩnh.', title_zh = '切换到静音模式 🤫', body_zh = '入睡的时候最敏感。保持安静吧。' WHERE id = '9c87f5af-e2e2-4310-ab2c-98ff6d5521d4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Zapatos de 20 minutos 👟', body_es = '¿Quiere ponerse los zapatos él solo y se retrasa la salida? Que no se te agote la paciencia.', title_fr = 'Des chaussures en 20 minutes 👟', body_fr = 'Il veut mettre ses chaussures tout seul et vous partez en retard ? Ne perdez pas patience.', title_hi = '20 मिनट वाले जूते 👟', body_hi = 'अपने जूते खुद पहनना चाहता है और घर से निकलने में देर हो रही है? अपना सब्र मत खोइए।', title_id = 'Sepatu 20 menit 👟', body_id = 'Ia ingin memakai sepatunya sendiri dan keberangkatan jadi tertunda? Jangan sampai kesabaran Anda habis.', title_ja = '20分かかる靴 👟', body_ja = '自分で靴をはきたがって、出かけるのが遅れますか？イライラしないで、気長に待ちましょう。', title_ko = '20분짜리 신발 신기 👟', body_ko = '신발을 혼자 신겠다고 해서 외출이 늦어지나요? 인내심을 잃지 마세요.', title_nl = '20 minuten voor één schoen 👟', body_nl = 'Wil hij zelf zijn schoenen aantrekken en komen jullie daardoor te laat de deur uit? Verlies je geduld niet.', title_pl = 'Buty na 20 minut 👟', body_pl = 'Chce sam zakładać buty i wyjście z domu się opóźnia? Nie trać cierpliwości.', title_pt = 'Sapatos em 20 minutos 👟', body_pt = 'Quer calçar os sapatos sozinho e a saída de casa atrasa-se? Não perca a paciência.', title_sv = '20 minuter för skorna 👟', body_sv = 'Vill barnet ta på sig skorna själv och ni blir sena hemifrån? Låt inte tålamodet rinna över.', title_vi = 'Đôi giày 20 phút 👟', body_vi = 'Bé muốn tự đi giày khiến việc ra khỏi nhà bị chậm trễ? Đừng để mình mất kiên nhẫn.', title_zh = '穿20分钟的鞋 👟', body_zh = '想自己穿鞋，出门就晚了？别让耐心爆表。' WHERE id = '70cc8a60-04a1-4e4e-b5c3-986f74563498' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se agarra al sofá o a la silla para trepar? Los músculos de sus piernas prueban alturas distintas. Protégele, pero no frenes estos intentos de alpinista.', body_fr = 'Il s''agrippe au canapé ou à une chaise pour grimper ? Les muscles de ses jambes testent différentes hauteurs. Protégez-le, mais n''empêchez pas ces tentatives d''alpiniste.', body_hi = 'सोफ़े और कुर्सी को पकड़कर ऊपर चढ़ने की कोशिश करता है? पैरों की मांसपेशियाँ अलग-अलग ऊँचाइयाँ परख रही हैं। उसकी रक्षा कीजिए, लेकिन इन पर्वतारोही कोशिशों को मत रोकिए।', body_id = 'Ia berpegangan pada sofa dan kursi lalu mencoba memanjat? Otot kakinya sedang menguji berbagai ketinggian. Lindungi ia, tetapi jangan halangi usaha pendaki kecil ini.', body_ja = 'ソファやいすにつかまって、上によじ登ろうとしていますか？足の筋肉がいろいろな高さを試しています。安全を守りつつ、この登山家のような挑戦を止めないであげて。', body_ko = '소파나 의자를 붙잡고 기어오르려 하나요? 다리 근육이 여러 높이를 시험하고 있어요. 안전은 지켜 주되 이 등반 시도를 막지 마세요.', body_nl = 'Probeert hij zich aan de bank of stoel omhoog te trekken en te klimmen? Zijn beenspieren testen verschillende hoogtes. Bescherm hem, maar houd deze kleine klimpogingen niet tegen.', body_pl = 'Łapie się kanapy i krzesła i próbuje się wspinać? Mięśnie nóg testują różne wysokości. Pilnuj go, ale nie przeszkadzaj w tych alpinistycznych próbach.', body_pt = 'Agarra-se ao sofá e às cadeiras e tenta trepar? Os músculos das pernas estão a testar alturas diferentes. Proteja-o, mas não trave estas tentativas de alpinista.', body_sv = 'Håller barnet sig i soffan eller stolen och försöker klättra upp? Benmusklerna testar olika höjder. Skydda barnet, men hindra inte de här klätterförsöken.', body_vi = 'Bé bám vào sofa, ghế để cố trèo lên? Cơ chân của bé đang thử các độ cao khác nhau. Hãy bảo vệ bé, nhưng đừng ngăn cản những lần "leo núi" này.', body_zh = '抓着沙发、椅子想往上爬？腿部肌肉正在测试不同的高度。护好宝宝，但别阻止这些攀登尝试。' WHERE id = 'e0d7037f-df25-46a9-8fd2-5b2b39c1432d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Primera victoria en el baño! 🚽', body_es = '¿Quiere ir solo al orinal? ¡Es la gran victoria de los 2,5 años! Anota este logro en el Seguimiento de pañales y lee en el Blog cómo facilitar aún más la transición.', title_fr = 'Première victoire aux toilettes ! 🚽', body_fr = 'Il veut aller tout seul sur le pot ? C''est la plus grande victoire des 2,5 ans ! Notez ce succès dans le Suivi des couches et du pot et lisez dans les Blogs comment faciliter encore la transition.', title_hi = 'टॉयलेट में पहली जीत! 🚽', body_hi = 'खुद पॉटी पर जाना चाहता है? यह 2.5 साल की सबसे बड़ी जीत है! डायपर/पॉटी ट्रैकर में यह कामयाबी दर्ज कीजिए और ब्लॉग में पढ़िए कि इस बदलाव को और आसान कैसे बनाएँ।', title_id = 'Kemenangan pertama di toilet! 🚽', body_id = 'Ia ingin pergi ke pispot sendiri? Ini kemenangan terbesar usia 2,5 tahun! Catat keberhasilan ini di Pelacak Popok dan baca di bagian Blog cara membuat peralihannya makin mudah.', title_ja = 'トイレではじめての勝利！🚽', body_ja = '自分からおまるに行きたがりますか？これは2歳半のいちばん大きな勝利です！「おむつトラッカー」にこの成功を記録して、ブログで移行をもっと楽にする方法を読みましょう。', title_ko = '화장실 첫 승리! 🚽', body_ko = '혼자 아기 변기에 가고 싶어 하나요? 두 돌 반의 가장 큰 승리예요! 기저귀 기록에 이 성공을 남기고, 블로그에서 이 과정을 더 쉽게 만드는 방법을 읽어 보세요.', title_nl = 'Eerste overwinning op het potje! 🚽', body_nl = 'Wil hij zelf naar het potje? Dat is de grootste overwinning van 2,5 jaar! Noteer dit succes in de Luier-/potjestracker en lees in Blogs hoe je de overstap nog makkelijker maakt.', title_pl = 'Pierwsze zwycięstwo na nocniku! 🚽', body_pl = 'Chce sam chodzić na nocnik? To największe zwycięstwo 2,5-latka! Zapisz ten sukces w narzędziu do śledzenia pieluszek i nocnika i przeczytaj na Blogu, jak jeszcze bardziej ułatwić to przejście.', title_pt = 'Primeira vitória no bacio! 🚽', body_pt = 'Quer ir ao bacio sozinho? É a maior conquista dos 2,5 anos! Registe este sucesso no Registo de Fraldas e leia no Blogue como tornar a transição ainda mais fácil.', title_sv = 'Första segern på toaletten! 🚽', body_sv = 'Vill barnet gå på pottan själv? Det är 2,5-årsålderns största seger! Anteckna framgången i Blöjkollen och läs i Bloggar hur du gör övergången ännu enklare.', title_vi = 'Chiến thắng đầu tiên với bô! 🚽', body_vi = 'Bé muốn tự đi bô? Đây là chiến thắng lớn nhất của tuổi 2,5! Hãy ghi thành công này vào Theo dõi tã/bô và đọc trong mục Blog cách giúp quá trình chuyển đổi dễ dàng hơn.', title_zh = '如厕的第一次胜利！🚽', body_zh = '想自己去坐便盆？这是2.5岁最大的胜利！在尿布/便盆记录里记下这次成功，再去博客里读读怎样让过渡更轻松。' WHERE id = 'ade78fe2-3290-467b-9d4f-4aa0e7d81802' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El final del cuento 🪄', body_es = 'Los cuentos clásicos cansan. Esta vez, en Cuentos inteligentes, deja que tu peque elija el final de la historia. Activa su imaginación preguntándole: «¿Quién crees que ayudó al osito?».', title_fr = 'La fin de l''histoire 🪄', body_fr = 'Les contes classiques, c''est lassant. Cette fois, dans les Contes intelligents, laissez votre enfant choisir la fin de l''histoire. Stimulez son imagination : « À ton avis, qui a aidé le petit ourson ? »', title_hi = 'कहानी का अंत 🪄', body_hi = 'पुरानी कहानियाँ थका देती हैं। इस बार स्मार्ट कहानियों में कहानी का अंत अपने बच्चे से चुनवाइए। ''तुम्हें क्या लगता है, भालू की मदद किसने की?'' पूछकर उसकी कल्पना जगाइए।', title_id = 'Akhir dongeng 🪄', body_id = 'Dongeng klasik bisa membosankan. Kali ini di Dongeng Pintar, biarkan anak memilih akhir ceritanya. Pancing imajinasinya dengan bertanya, ''Menurutmu siapa yang menolong beruang kecil?''', title_ja = 'お話の結末 🪄', body_ja = '昔話はちょっとマンネリ？「スマートおはなし」で、今回はお話の結末をお子さんに選んでもらいましょう。「くまさんを助けたのはだれだと思う？」と問いかけて、想像力を働かせて。', title_ko = '동화의 결말 🪄', body_ko = '늘 듣던 동화는 지루할 수 있어요. 이번에는 스마트 동화에서 이야기의 결말을 아이가 고르게 해 보세요. ''누가 아기 곰을 도와줬을까?'' 하고 물으며 상상력을 깨워 주세요.', title_nl = 'Het einde van het sprookje 🪄', body_nl = 'Klassieke sprookjes kunnen saai worden. Laat je kindje deze keer in Slimme sprookjes zelf het einde kiezen. Prikkel zijn fantasie met: ''Wie denk jij dat het beertje heeft geholpen?''', title_pl = 'Zakończenie bajki 🪄', body_pl = 'Klasyczne bajki bywają nużące. Tym razem w Mądrych bajkach pozwól dziecku wybrać zakończenie historii. Pobudź jego wyobraźnię pytaniem: „Jak myślisz, kto pomógł misiowi?”.', title_pt = 'O fim da história 🪄', body_pt = 'Os contos clássicos cansam. Desta vez, nas Histórias Inteligentes, deixe o seu filho escolher o final. Puxe pela imaginação dele: "Quem achas que ajudou o ursinho?"', title_sv = 'Sagans slut 🪄', body_sv = 'Klassiska sagor kan bli tröttsamma. Låt barnet välja hur berättelsen slutar i Smarta sagor den här gången. Sätt fart på fantasin med ”Vem tror du hjälpte nallen?”.', title_vi = 'Cái kết của câu chuyện 🪄', body_vi = 'Truyện cổ tích kinh điển có thể nhàm chán. Lần này trong Truyện cổ tích thông minh, hãy để bé chọn cái kết. Hỏi bé "Con nghĩ ai đã giúp chú gấu nhỏ?" để khơi dậy trí tưởng tượng.', title_zh = '故事的结局 🪄', body_zh = '经典故事讲多了也累。这次在智能故事里让孩子来选结局吧。问一句“你觉得是谁帮了小熊？”，激发宝宝的想象力。' WHERE id = '2102feb2-22f3-4c41-8de6-6f3e115e2d56' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No se come la comida? A veces el problema no es el sabor, sino el aspecto. Intenta abrirle el apetito haciendo caras graciosas con verduras de colores.', body_fr = 'Il ne mange pas ? Parfois, le problème n''est pas le goût mais l''aspect. Créez des visages rigolos avec des légumes colorés pour lui ouvrir l''appétit.', body_hi = 'वह खाना नहीं खाता? कभी-कभी दिक्कत स्वाद में नहीं, दिखावट में होती है। रंग-बिरंगी सब्ज़ियों से मज़ेदार चेहरे बनाकर उसकी भूख जगाने की कोशिश कीजिए।', body_id = 'Ia tidak mau makan? Kadang masalahnya bukan rasa, tetapi tampilan. Buat wajah-wajah lucu dari sayuran warna-warni untuk membangkitkan selera makannya.', body_ja = 'ごはんを食べない？問題は味ではなく、見た目のこともあります。カラフルな野菜でおもしろい顔を作って、食欲をそそってみましょう。', body_ko = '밥을 안 먹나요? 가끔은 맛이 아니라 모양이 문제예요. 알록달록한 채소로 웃긴 얼굴을 만들어 입맛을 돋워 보세요.', body_nl = 'Wil hij niet eten? Soms zit het probleem niet in de smaak, maar in het uiterlijk. Maak grappige gezichtjes met kleurrijke groenten om zijn eetlust op te wekken.', body_pl = 'Nie chce jeść? Czasem problemem nie jest smak, tylko wygląd. Spróbuj pobudzić jego apetyt, układając z kolorowych warzyw zabawne buźki.', body_pt = 'Não come? Às vezes o problema não é o sabor, é o aspeto. Faça caras engraçadas com legumes coloridos e tente abrir-lhe o apetite.', body_sv = 'Äter barnet inte maten? Ibland är problemet inte smaken utan utseendet. Gör roliga ansikten av färgglada grönsaker och försök väcka aptiten.', body_vi = 'Bé không chịu ăn? Đôi khi vấn đề không nằm ở hương vị mà ở hình thức. Hãy thử tạo những khuôn mặt ngộ nghĩnh từ rau củ nhiều màu để kích thích vị giác của bé.', body_zh = '不肯吃饭？有时问题不在味道，而在外观。用五颜六色的蔬菜摆出搞笑的小脸，试着打开宝宝的胃口吧。' WHERE id = '458c2efd-1859-4a36-bc6c-218987ce42a4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubriendo los números 🔢', body_es = 'Al subir escaleras o colocar los juguetes intenta contar «uno, dos, tres». Apoya esta etapa matemática de su desarrollo cognitivo contando con tu peque.', title_fr = 'Il découvre les chiffres 🔢', body_fr = 'En montant l''escalier ou en rangeant ses jouets, il essaie de compter « un, deux, trois ». Soutenez cette étape mathématique de son développement cognitif en comptant avec lui.', title_hi = 'अंकों की खोज 🔢', body_hi = 'सीढ़ियाँ चढ़ते या खिलौने सजाते समय ''एक, दो, तीन'' कहकर गिनने की कोशिश करता है। उसके साथ मिलकर गिनती करके संज्ञानात्मक विकास के इस गणित वाले पड़ाव को बढ़ावा दीजिए।', title_id = 'Mengenal angka 🔢', body_id = 'Saat naik tangga atau menyusun mainan, ia mencoba menghitung ''satu, dua, tiga''. Dukung tahap matematika dalam perkembangan kognitifnya ini dengan ikut berhitung bersamanya.', title_ja = '数を発見中 🔢', body_ja = '階段を上るときやおもちゃを並べるとき、「いち、に、さん」と数えようとします。認知発達のこの算数の段階を、一緒に数えてサポートしましょう。', title_ko = '숫자를 발견해요 🔢', body_ko = '계단을 오르거나 장난감을 늘어놓을 때 ''하나, 둘, 셋'' 하고 세려고 하나요? 함께 세어 주며 인지 발달의 이 수학 단계를 응원해 주세요.', title_nl = 'Hij ontdekt cijfers 🔢', body_nl = 'Probeert hij ''één, twee, drie'' te tellen als hij de trap op gaat of zijn speelgoed op een rij zet? Steun deze rekenfase van zijn denkontwikkeling door samen met hem te tellen.', title_pl = 'Odkrywa liczby 🔢', body_pl = 'Wchodząc po schodach albo układając zabawki, próbuje liczyć „raz, dwa, trzy”. Wspieraj ten matematyczny etap rozwoju poznawczego, licząc razem z nim.', title_pt = 'A descobrir os números 🔢', body_pt = 'Ao subir as escadas ou arrumar os brinquedos, tenta contar "um, dois, três". Apoie esta etapa matemática do desenvolvimento cognitivo contando com ele.', title_sv = 'Barnet upptäcker siffror 🔢', body_sv = 'Barnet försöker räkna ett, två, tre när hen går i trappan eller radar upp leksakerna. Stöd det här matematiska steget i den kognitiva utvecklingen genom att räkna tillsammans.', title_vi = 'Khám phá con số 🔢', body_vi = 'Bé cố đếm "một, hai, ba" khi leo cầu thang hay khi xếp đồ chơi. Hãy hỗ trợ giai đoạn toán học này của sự phát triển nhận thức bằng cách đếm cùng bé.', title_zh = '发现数字 🔢', body_zh = '爬楼梯或摆玩具时，试着数“一、二、三”。和宝宝一起数数，支持认知发展中的这个数学阶段吧。' WHERE id = '1e03f3e4-2305-4ae5-883c-39581f248697' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arma secreta de papá 🤡', body_es = 'Cuando tus trucos ya no funcionan, los sonidos raros y las caras graciosas de papá salvan la situación al instante. En las crisis de la noche, pásale la pelota enseguida.', title_fr = 'L''arme secrète de papa 🤡', body_fr = 'Quand vos astuces ne marchent plus, les bruits bizarres et les grimaces de papa sauvent la situation en un instant. Pendant les crises du soir, passez-lui vite la balle.', title_hi = 'पापा का खुफ़िया हथियार 🤡', body_hi = 'जब आपकी तरकीबें काम नहीं करतीं, तो पापा की अजीब आवाज़ें और मज़ेदार चेहरे तुरंत हालात संभाल लेते हैं। शाम के नखरों में तुरंत बॉल उनके पाले में डाल दीजिए।', title_id = 'Senjata rahasia Ayah 🤡', body_id = 'Saat cara Anda tidak lagi berhasil, suara aneh dan wajah lucu Ayah bisa seketika menyelamatkan keadaan. Saat krisis malam hari, langsung oper bolanya kepada Ayah.', title_ja = 'パパの秘密兵器 🤡', body_ja = 'あなたの手がもう効かないとき、パパのおもしろい声や変な顔がすぐに状況を救ってくれます。夕方のかんしゃくでは、すぐにパパにバトンを渡しましょう。', title_ko = '아빠의 비밀 무기 🤡', body_ko = '엄마의 방법이 더는 통하지 않을 때 아빠의 웃긴 소리와 표정이 순식간에 상황을 구해 줘요. 저녁 떼쓰기 때는 바로 아빠에게 공을 넘기세요.', title_nl = 'Papa''s geheime wapen 🤡', body_nl = 'Als jouw trucjes niet meer werken, redden papa''s gekke geluiden en grappige gezichten de situatie meteen. Speel de bal bij avondbuien direct naar hem door.', title_pl = 'Tajna broń taty 🤡', body_pl = 'Gdy twoje sposoby już nie działają, dziwne odgłosy i śmieszne miny taty od razu ratują sytuację. Podczas wieczornych kryzysów od razu podaj mu piłeczkę.', title_pt = 'A arma secreta do pai 🤡', body_pt = 'Quando os seus truques já não funcionam, os sons estranhos e as caretas cómicas do pai salvam logo a situação. Nas crises da noite, passe-lhe logo a bola.', title_sv = 'Pappas hemliga vapen 🤡', body_sv = 'När dina knep inte längre fungerar räddar pappas konstiga ljud och roliga ansikten situationen direkt. Vid kvällskriser, passa bollen till honom direkt.', title_vi = 'Vũ khí bí mật của bố 🤡', body_vi = 'Khi những chiêu của mẹ không còn hiệu quả, âm thanh lạ và khuôn mặt ngộ nghĩnh của bố sẽ cứu nguy ngay lập tức. Khi bé quấy buổi tối, hãy "chuyền bóng" ngay cho bố.', title_zh = '爸爸的秘密武器 🤡', body_zh = '你的办法都不管用时，爸爸的怪声音和搞笑表情能马上挽救局面。晚上宝宝崩溃时，马上把球传给他。' WHERE id = '2e1f0716-93b5-4be3-9000-fdb28349534d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El grupo secreto de las madres 💬', body_es = '¿Tienes que tomar una decisión difícil? (por ejemplo, elegir guardería). Los consejos de las madres con experiencia de la Comunidad Anacan son las soluciones más reales y probadas, que no vienen en ningún libro.', title_fr = 'Le groupe secret des mamans 💬', body_fr = 'Vous devez prendre une décision difficile (le choix de la crèche, par exemple) ? Les conseils des mamans expérimentées de la Communauté Anacan sont les solutions les plus concrètes et éprouvées, introuvables dans les livres.', title_hi = 'माँओं का खुफ़िया ग्रुप 💬', body_hi = 'कोई मुश्किल फ़ैसला लेना है? (जैसे, प्लेस्कूल चुनना)। Anacan कम्युनिटी में अनुभवी माँओं की सलाह आज़माए हुए, सबसे असली समाधान हैं जो किसी किताब में नहीं लिखे।', title_id = 'Grup rahasia para ibu 💬', body_id = 'Harus mengambil keputusan sulit? (Misalnya memilih TK). Saran ibu-ibu berpengalaman di Komunitas Anacan adalah solusi paling nyata dan teruji yang tidak tertulis di buku mana pun.', title_ja = 'ママたちの秘密のグループ 💬', body_ja = 'むずかしい決断をしなければなりませんか？（たとえば保育園選び）。Anacanコミュニティの経験豊富なママたちのアドバイスは、どの本にも書かれていない、実際に試されたいちばん現実的な解決策です。', title_ko = '엄마들의 비밀 모임 💬', body_ko = '어린이집 선택처럼 어려운 결정을 해야 하나요? Anacan 커뮤니티의 경험 많은 엄마들의 조언은 어떤 책에도 없는, 직접 검증된 가장 현실적인 해결책이에요.', title_nl = 'De geheime groep van moeders 💬', body_nl = 'Moet je een moeilijke beslissing nemen? (Bijvoorbeeld welke opvang). Het advies van ervaren moeders in de Anacan Community zijn de meest realistische, beproefde oplossingen, die in geen enkel boek staan.', title_pl = 'Tajna grupa mam 💬', body_pl = 'Musisz podjąć trudną decyzję? (Na przykład wybór przedszkola). Rady doświadczonych mam ze Społeczności Anacan to sprawdzone, najbardziej realne rozwiązania, których nie znajdziesz w żadnej książce.', title_pt = 'O grupo secreto das mães 💬', body_pt = 'Tem de tomar uma decisão difícil? (Por exemplo, escolher a creche.) Os conselhos das mães experientes da Comunidade Anacan são as soluções mais reais e testadas, que não vêm em nenhum livro.', title_sv = 'Mammornas hemliga grupp 💬', body_sv = 'Behöver du fatta ett svårt beslut? (Till exempel val av förskola.) Råden från erfarna mammor i Anacan Community är beprövade och de mest verklighetsnära lösningarna som inte står i någon bok.', title_vi = 'Hội kín của các mẹ 💬', body_vi = 'Mẹ cần đưa ra một quyết định khó? (Ví dụ chọn nhà trẻ). Lời khuyên từ các mẹ giàu kinh nghiệm trong Cộng đồng Anacan là những giải pháp thực tế nhất, đã được kiểm chứng mà không cuốn sách nào viết.', title_zh = '妈妈们的秘密小组 💬', body_zh = '要做一个艰难的决定？（比如选幼儿园）Anacan社区里有经验的妈妈们的建议，是任何书里都没写过的、经过检验的最实在的办法。' WHERE id = 'a57ba6d4-a9da-4163-8ddf-e60b3ee296c5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La medida digital del silencio 🤫', title_fr = 'La mesure numérique du silence 🤫', title_hi = 'खामोशी का डिजिटल माप 🤫', title_id = 'Ukuran digital keheningan 🤫', title_ja = '静けさのデジタル測定 🤫', title_ko = '고요를 숫자로 확인해요 🤫', title_nl = 'De digitale maat van stilte 🤫', title_pl = 'Cyfrowa miara ciszy 🤫', title_pt = 'A medida digital do silêncio 🤫', title_sv = 'Tystnaden i siffror 🤫', title_vi = 'Thước đo kỹ thuật số của sự tĩnh lặng 🤫', title_zh = '安静的数字度量 🤫' WHERE id = 'be73d9bc-5d86-4bdb-a6da-ef74ea88ee1e' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Crees que bebe poca agua? 💧', body_es = 'Cómprale vasos de colores y formas diferentes y convierte beber agua en un hábito divertido.', title_fr = 'Il ne boit pas assez d''eau ?💧', body_fr = 'Offrez-lui des gobelets colorés aux formes amusantes et faites de l''eau une habitude ludique.', title_hi = 'लगता है वह कम पानी पीता है? 💧', body_hi = 'उसके लिए रंग-बिरंगे, अलग-अलग आकार के गिलास लाइए और पानी पीने को एक मज़ेदार आदत बना दीजिए।', title_id = 'Merasa ia kurang minum air?💧', body_id = 'Belikan gelas berwarna-warni dengan bentuk berbeda agar minum air jadi kebiasaan yang menyenangkan.', title_ja = 'お水、足りていないと思いますか？💧', body_ja = 'カラフルでいろいろな形のコップを用意して、お水を飲むことを楽しい習慣にしましょう。', title_ko = '물을 너무 적게 마시는 것 같나요?💧', body_ko = '알록달록하고 모양이 다양한 컵을 마련해 물 마시기를 즐거운 습관으로 만들어 주세요.', title_nl = 'Denk je dat hij te weinig water drinkt?💧', body_nl = 'Koop kleurrijke bekers in verschillende vormen voor hem en maak van water drinken een leuke gewoonte.', title_pl = 'Myślisz, że pije za mało wody?💧', body_pl = 'Kup mu kolorowe kubeczki o różnych kształtach i zamień picie wody w zabawny nawyk.', title_pt = 'Acha que bebe pouca água?💧', body_pt = 'Compre-lhe copos coloridos e com formas diferentes e transforme beber água num hábito divertido.', title_sv = 'Tycker du att barnet dricker för lite vatten?💧', body_sv = 'Köp färgglada muggar i olika former och gör vattendrickandet till en rolig vana.', title_vi = 'Mẹ nghĩ bé uống ít nước?💧', body_vi = 'Hãy mua cho bé những chiếc cốc nhiều màu, nhiều hình dáng khác nhau để uống nước trở thành một thói quen vui vẻ.', title_zh = '觉得宝宝水喝得太少？💧', body_zh = '给宝宝买些彩色、形状各异的杯子，让喝水变成一件有趣的习惯。' WHERE id = '7cad0a21-48df-4f84-89c3-bca4ef4e2b8a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charlas en susurros 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y cuéntale en voz muy bajita, susurrando, lo que ha pasado durante el día. Susurrar es el mejor método para preparar el cerebro para dormir.', title_fr = 'Conversations chuchotées 🌙', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et racontez-lui sa journée tout bas, en chuchotant. Le chuchotement est la meilleure façon de préparer le cerveau au sommeil.', title_hi = 'फुसफुसाती बातें 🌙', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें बहुत धीमी आवाज़ में, फुसफुसाकर उसे सुनाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे अच्छा तरीका है।', title_id = 'Obrolan berbisik 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan ceritakan kejadian hari ini dengan suara sangat pelan, berbisik. Berbisik adalah cara terbaik menyiapkan otak untuk tidur.', title_ja = 'ささやき声のおしゃべり 🌙', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、今日あったことをとても小さな声でささやくように話してあげて。ささやき声は、脳を眠りへ導くいちばんの方法です。', title_ko = '속삭이는 대화 🌙', body_ko = '방의 불을 모두 꺼 주세요. 옆에 누워 오늘 있었던 일을 아주 작은 목소리로 속삭이듯 들려주세요. 속삭임은 뇌가 잠들 준비를 하게 돕는 가장 좋은 방법이에요.', title_nl = 'Fluistergesprekjes 🌙', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en vertel heel zachtjes, fluisterend, wat er vandaag is gebeurd. Fluisteren is de beste manier om de hersenen klaar te maken voor de slaap.', title_pl = 'Rozmowy szeptem 🌙', body_pl = 'Zgaś wszystkie światła w pokoju. Połóż się obok i bardzo cicho, szeptem opowiedz mu, co wydarzyło się w ciągu dnia. Szept to najlepszy sposób, by przygotować mózg do snu.', title_pt = 'Conversas em sussurro 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e conte-lhe, em voz muito baixa e a sussurrar, o que aconteceu durante o dia. Sussurrar é o melhor método para preparar o cérebro para o sono.', title_sv = 'Viskande samtal 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och berätta mycket tyst, viskande, om det som hänt under dagen. Viskningar är det bästa sättet att förbereda hjärnan för sömn.', title_vi = 'Những cuộc trò chuyện thì thầm 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ kể về những gì đã xảy ra trong ngày. Thì thầm là cách tốt nhất giúp não bộ chuẩn bị cho giấc ngủ.', title_zh = '悄悄话时间 🌙', body_zh = '把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音，悄悄讲讲今天发生的事。悄悄话是帮大脑准备入睡的最好方法。' WHERE id = 'd2d72f62-94bd-4b00-9bc2-090ee3d937fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libertad para elegir 👗', body_es = '¿Quiere elegir su ropa y los colores no pegan nada? No pasa nada. Para no romper su voluntad, ofrécele solo 2 opciones: ¿esta o la otra?', title_fr = 'La liberté de choisir 👗', body_fr = 'Il veut choisir ses vêtements et les couleurs ne vont pas du tout ensemble ? Ce n''est pas grave. Pour ne pas briser sa volonté, proposez-lui simplement 2 choix : celui-ci ou celui-là ?', title_hi = 'चुनने की आज़ादी 👗', body_hi = 'अपने कपड़े खुद चुनना चाहता है और रंग बिल्कुल मेल नहीं खाते? कोई बात नहीं। उसकी इच्छा को ठेस न पहुँचे, इसलिए उसे बस 2 विकल्प दीजिए: यह वाला या वह वाला?', title_id = 'Kebebasan memilih 👗', body_id = 'Ia ingin memilih bajunya sendiri dan warnanya sama sekali tidak serasi? Tidak apa-apa. Agar tidak mematahkan kemauannya, beri saja 2 pilihan: yang ini atau yang itu?', title_ja = '選ぶ自由 👗', body_ja = '自分で服を選びたがるけれど、色がまったく合っていない？大丈夫です。意志をくじかないように、「これにする？それともあっち？」と2つだけ選択肢を出してあげましょう。', title_ko = '선택의 자유 👗', body_ko = '옷을 직접 고르겠다는데 색이 전혀 안 어울리나요? 괜찮아요. 의지를 꺾지 않도록 ''이거, 아니면 저거?'' 하고 딱 두 가지만 보여 주세요.', title_nl = 'Vrijheid van kiezen 👗', body_nl = 'Wil hij zelf zijn kleren uitkiezen en passen de kleuren helemaal niet bij elkaar? Geen probleem. Geef hem gewoon 2 keuzes, zodat je zijn wil niet breekt: deze of die?', title_pl = 'Wolność wyboru 👗', body_pl = 'Chce sam wybierać ubrania, a kolory zupełnie do siebie nie pasują? Nic nie szkodzi. Żeby nie łamać jego woli, daj mu po prostu 2 opcje: to czy tamto?', title_pt = 'Liberdade de escolha 👗', body_pt = 'Quer escolher a própria roupa e as cores não combinam nada? Não faz mal. Para não quebrar a vontade dele, ofereça apenas 2 opções: esta ou aquela?', title_sv = 'Friheten att välja 👗', body_sv = 'Vill barnet välja kläderna själv och färgerna matchar inte alls? Det gör inget. För att inte knäcka barnets vilja, ge bara 2 val: den här eller den andra?', title_vi = 'Quyền được lựa chọn 👗', body_vi = 'Bé muốn tự chọn quần áo dù màu sắc chẳng hợp nhau chút nào? Không sao cả. Để không làm tổn thương ý chí của bé, chỉ cần đưa ra 2 lựa chọn: "Cái này hay cái kia?"', title_zh = '选择的自由 👗', body_zh = '想自己挑衣服，可颜色完全不搭？没关系。为了不挫伤宝宝的意志，只给两个选择就好：“这件，还是那件？”' WHERE id = 'df67b2d6-67a7-45d0-8784-314cb9888630' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los sonidos raros de papá 🤡', body_es = 'La forma más rápida de hacer reír al bebé es que papá haga sonidos raros y muecas. Escucha las alegres carcajadas de esta noche y sonríe tú también en segundo plano.', title_fr = 'Les drôles de bruits de papa 🤡', body_fr = 'Le moyen le plus rapide de faire rire bébé : papa qui fait des bruits et des grimaces bizarres. Écoutez les éclats de rire de ce soir et souriez, vous aussi, en coulisses.', title_hi = 'पापा की अजीब आवाज़ें 🤡', body_hi = 'बच्चे को हँसाने का सबसे तेज़ तरीका है पापा की अजीब आवाज़ें और मज़ेदार चेहरे। आज शाम की खिलखिलाहट सुनिए और पीछे से आप भी मुस्कुराइए।', title_id = 'Suara lucu Ayah 🤡', body_id = 'Cara tercepat membuat bayi tertawa adalah Ayah membuat suara dan ekspresi wajah yang lucu. Dengarkan tawa riang malam ini dan ikut tersenyum dari belakang.', title_ja = 'パパのおもしろい声 🤡', body_ja = '赤ちゃんをいちばん早く笑わせる方法は、パパがおもしろい声や表情をすること。今夜の楽しい笑い声に耳を傾けて、そばであなたもほほえみましょう。', title_ko = '아빠의 웃긴 소리 🤡', body_ko = '아이를 가장 빨리 웃게 하는 방법은 아빠의 웃긴 소리와 표정이에요. 오늘 저녁 즐거운 웃음소리를 들으며 엄마도 곁에서 미소 지어 보세요.', title_nl = 'Papa''s gekke geluidjes 🤡', body_nl = 'De snelste manier om je baby aan het lachen te krijgen: papa die gekke geluiden en gezichten maakt. Luister vanavond naar het vrolijke gegiechel en glimlach op de achtergrond mee.', title_pl = 'Śmieszne odgłosy taty 🤡', body_pl = 'Najszybszy sposób, by rozśmieszyć malucha, to śmieszne odgłosy i miny taty. Wsłuchaj się dziś wieczorem w te radosne chichoty i uśmiechnij się z boku.', title_pt = 'Os sons engraçados do pai 🤡', body_pt = 'A forma mais rápida de fazer o bebé rir é o pai fazer sons e caretas engraçadas. Ouça as gargalhadas alegres desta noite e sorria também, nos bastidores.', title_sv = 'Pappas konstiga ljud 🤡', body_sv = 'Det snabbaste sättet att få barnet att skratta är när pappa gör konstiga ljud och miner. Lyssna på kvällens glada skratt och le du också i bakgrunden.', title_vi = 'Những âm thanh ngộ nghĩnh của bố 🤡', body_vi = 'Cách nhanh nhất để bé bật cười là bố giả những âm thanh và biểu cảm ngộ nghĩnh. Tối nay hãy lắng nghe những tràng cười giòn tan và mỉm cười cùng từ phía sau nhé.', title_zh = '爸爸的怪声音 🤡', body_zh = '逗宝宝笑最快的办法，就是让爸爸发出怪声音、做鬼脸。今晚听着这欢快的笑声，你也在一旁笑一笑吧。' WHERE id = '308209fb-08e0-4807-8fb4-5bc201b75466' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de desahogarse 💬', body_es = 'Hoy ha llorado por todo y estás agotada. Entra ahora en la Comunidad Anacan y escribe «Hoy ha sido muy difícil». Verás que cientos de mujeres viven el mismo momento.', title_fr = 'Le moment de se confier 💬', body_fr = 'Aujourd''hui, il a pleuré pour tout et vous êtes à bout. Allez tout de suite dans la Communauté Anacan et écrivez « Aujourd''hui a été très dur ». Vous verrez que des centaines de femmes vivent la même chose.', title_hi = 'दिल की बात कहने का समय 💬', body_hi = 'आज वह हर बात पर रोया और आप थक कर चूर हो गईं? तुरंत Anacan कम्युनिटी में जाइए और लिखिए ''आज बहुत मुश्किल दिन था''। आप देखेंगी कि सैकड़ों महिलाएँ इसी पल से गुज़र रही हैं।', title_id = 'Waktunya curhat 💬', body_id = 'Hari ini ia menangis karena segala hal dan Anda kehabisan tenaga. Segera buka Komunitas Anacan dan tulis ''Hari ini berat sekali''. Anda akan melihat ratusan ibu mengalami momen yang sama.', title_ja = '話を聞いてもらう時間 💬', body_ja = '今日は何にでも泣いて、もうへとへと？すぐにAnacanコミュニティを開いて「今日は本当に大変だった」と書きこんでみて。何百人ものママが同じ瞬間を過ごしていることがわかります。', title_ko = '털어놓을 시간 💬', body_ko = '오늘 하루 종일 울어서 지칠 대로 지쳤나요? 바로 Anacan 커뮤니티에 들어가 ''오늘 정말 힘들었어요''라고 남겨 보세요. 수많은 엄마들이 같은 순간을 겪고 있다는 걸 알게 될 거예요.', title_nl = 'Tijd om je hart te luchten 💬', body_nl = 'Vandaag huilde hij om alles en je bent op. Ga meteen naar de Anacan Community en schrijf ''Vandaag was echt zwaar''. Je zult zien dat honderden vrouwen precies hetzelfde meemaken.', title_pl = 'Czas się wygadać 💬', body_pl = 'Dziś płakał o wszystko, a ty jesteś wykończona. Od razu wejdź do Społeczności Anacan i napisz: „Dziś było bardzo ciężko”. Zobaczysz, że setki kobiet przeżywają to samo.', title_pt = 'Hora de desabafar 💬', body_pt = 'Hoje chorou por tudo e está esgotada. Entre já na Comunidade Anacan e escreva "Hoje foi muito difícil". Vai ver que centenas de mulheres vivem o mesmo momento.', title_sv = 'Dags att prata av sig 💬', body_sv = 'I dag grät barnet för allt och du är helt slut. Gå direkt in i Anacan Community och skriv ”I dag var det väldigt tufft”. Du kommer att se att hundratals kvinnor upplever samma sak.', title_vi = 'Đến lúc tâm sự 💬', body_vi = 'Hôm nay bé khóc vì mọi thứ và mẹ đã kiệt sức. Hãy vào ngay Cộng đồng Anacan và viết "Hôm nay thật quá khó khăn". Mẹ sẽ thấy hàng trăm người mẹ khác cũng đang trải qua khoảnh khắc y hệt.', title_zh = '倾诉时间 💬', body_zh = '今天宝宝什么都哭，你也被耗尽了。马上进入Anacan社区，写下“今天真的太难了”。你会发现，成百上千的妈妈正经历着同样的时刻。' WHERE id = '591ee14c-695d-499c-8f9b-1192b3fd9c23' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maestro de las construcciones 🧱', body_es = '¿Intenta encajar piezas grandes de construcción para montar algo? Está descubriendo la geometría. Añade al Seguimiento del desarrollo estos pequeños intentos de ingeniería.', title_fr = 'Maître constructeur 🧱', body_fr = 'Il essaie d''emboîter de gros Lego pour construire quelque chose ? Il découvre la géométrie. Ajoutez ces petits essais d''ingénieur au Suivi de développement.', title_hi = 'कंस्ट्रक्शन का उस्ताद 🧱', body_hi = 'बड़े लेगो एक-दूसरे में फँसाकर कुछ बनाने की कोशिश करता है? वह ज्यामिति की खोज कर रहा है। उसकी इन नन्ही इंजीनियरिंग कोशिशों को ग्रोथ ट्रैकर में जोड़िए।', title_id = 'Jago menyusun balok 🧱', body_id = 'Ia mencoba menyambungkan lego besar dan membuat sesuatu? Ia sedang menemukan geometri. Tambahkan usaha teknik kecilnya ini ke Pelacak Perkembangan.', title_ja = 'ブロック名人 🧱', body_ja = '大きなブロックをつなげて、何かを作ろうとしていますか？図形の世界を発見しています。この小さなエンジニアの挑戦を「発達トラッカー」に記録しましょう。', title_ko = '블록 쌓기 달인 🧱', body_ko = '큰 레고를 끼워 무언가를 만들려고 하나요? 기하학을 발견하는 중이에요. 이 작은 엔지니어링 시도를 성장 기록에 남겨 주세요.', title_nl = 'Kleine bouwmeester 🧱', body_nl = 'Probeert hij grote blokken in elkaar te klikken en iets te bouwen? Hij ontdekt de meetkunde. Zet deze kleine bouwpogingen in de Groeitracker.', title_pl = 'Mistrz klocków 🧱', body_pl = 'Łączy duże klocki i próbuje coś zbudować? Odkrywa geometrię. Dodaj te małe inżynierskie próby do Śledzenia rozwoju.', title_pt = 'Mestre das construções 🧱', body_pt = 'Tenta encaixar legos grandes e construir coisas? Está a descobrir a geometria. Acrescente estas pequenas tentativas de engenharia ao Registo de Desenvolvimento.', title_sv = 'Byggmästare 🧱', body_sv = 'Försöker barnet sätta ihop stora legobitar och bygga något? Barnet upptäcker geometrin. Lägg till de här små ingenjörsförsöken i Utvecklingsspåraren.', title_vi = 'Bậc thầy xếp khối 🧱', body_vi = 'Bé cố ghép những khối lego lớn để tạo ra thứ gì đó? Bé đang khám phá hình học. Hãy thêm những nỗ lực "kỹ sư" nhỏ này vào Theo dõi phát triển nhé.', title_zh = '搭建小能手 🧱', body_zh = '想把大块乐高拼在一起做点什么？宝宝正在探索几何。把这些小小的工程尝试记在发育追踪里吧。' WHERE id = '7b870bcd-23ba-4647-a5da-35a4bde7db6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Repetir palabras 🗣️', body_es = '¿Repite como un loro cada palabra nueva que sale de tu boca? Su vocabulario se enriquece. Presta especial atención a las palabras y emociones que usas delante de tu peque.', title_fr = 'Il répète les mots 🗣️', body_fr = 'Il répète comme un perroquet chaque nouveau mot qui sort de votre bouche ? Son vocabulaire s''enrichit. Faites bien attention aux mots et aux émotions que vous exprimez près de lui.', title_hi = 'शब्दों को दोहराना 🗣️', body_hi = 'आपके मुँह से निकला हर नया शब्द तोते की तरह तुरंत दोहराता है? उसकी शब्दावली बढ़ रही है। उसके सामने बोले जाने वाले शब्दों और भावनाओं पर खास ध्यान दीजिए।', title_id = 'Mengulang kata 🗣️', body_id = 'Setiap kata baru dari mulut Anda langsung ia ulangi seperti burung beo? Kosakatanya makin kaya. Perhatikan baik-baik kata dan emosi yang Anda ucapkan di dekatnya.', title_ja = '言葉のまね 🗣️', body_ja = 'あなたが口にする新しい言葉を、すぐにオウムのようにまねしますか？語彙が豊かになっています。そばで話す言葉や感情表現に特に気をつけましょう。', title_ko = '말 따라 하기 🗣️', body_ko = '엄마가 하는 새로운 말을 앵무새처럼 바로 따라 하나요? 어휘가 풍부해지고 있어요. 아이 앞에서 쓰는 말과 감정에 특히 신경 써 주세요.', title_nl = 'Woordjes herhalen 🗣️', body_nl = 'Herhaalt hij elk nieuw woord dat jij zegt meteen als een papegaai? Zijn woordenschat groeit. Let extra op de woorden en emoties die je in zijn bijzijn gebruikt.', title_pl = 'Powtarzanie słów 🗣️', body_pl = 'Każde nowe słowo, które powiesz, od razu powtarza jak papużka? Jego słownictwo się wzbogaca. Zwracaj szczególną uwagę na słowa i emocje, które przy nim wyrażasz.', title_pt = 'Repetir palavras 🗣️', body_pt = 'Repete logo, como um papagaio, cada palavra nova que sai da sua boca? O vocabulário está a crescer. Tenha especial atenção às palavras e emoções que usa perto dele.', title_sv = 'Ordupprepning 🗣️', body_sv = 'Upprepar barnet genast varje nytt ord du säger, som en papegoja? Ordförrådet växer. Tänk extra på vilka ord och känslor du uttrycker när barnet är nära.', title_vi = 'Lặp lại từ ngữ 🗣️', body_vi = 'Bé lặp lại ngay như vẹt mọi từ mới mẹ vừa nói? Vốn từ của bé đang phong phú dần. Hãy đặc biệt chú ý đến lời nói và cảm xúc của mẹ khi ở cạnh bé.', title_zh = '重复说话 🗣️', body_zh = '你说出的每个新词，宝宝都像小鹦鹉一样马上跟着说？词汇量正在丰富起来。在宝宝身边说话和表达情绪时要格外注意。' WHERE id = '3cc5c04e-9600-46b6-86d4-dfe7f6d1b82d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La melodía de la noche 🛀', body_es = 'Después de correr todo el día, estáis agotados los dos. Un baño templado y una melodía suave y tranquila de fondo calmarán por completo su sistema nervioso.', title_fr = 'La mélodie du soir 🛀', body_fr = 'Après avoir couru toute la journée, vous êtes épuisés tous les deux. Un bain tiède et une mélodie douce en fond sonore apaiseront complètement son système nerveux.', title_hi = 'रात की धुन 🛀', body_hi = 'दिनभर भागदौड़ से वह भी थक गया और आप भी। गुनगुना स्नान और पीछे बजती हल्की, धीमी धुन उसके नर्वस सिस्टम को पूरी तरह शांत कर देगी।', title_id = 'Melodi malam 🛀', body_id = 'Seharian berlarian, ia dan Anda sama-sama kelelahan. Mandi air hangat dengan alunan melodi lembut di latar belakang akan menenangkan sistem sarafnya sepenuhnya.', title_ja = '夜のメロディー 🛀', body_ja = '一日じゅう走り回って、ふたりともへとへと。ぬるめのお風呂と、後ろで流れるやさしく穏やかなメロディーが、神経をすっかり落ち着かせてくれます。', title_ko = '밤의 멜로디 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤죠. 따뜻한 목욕과 잔잔하게 흐르는 부드러운 멜로디가 아이의 신경을 편안하게 진정시켜 줄 거예요.', title_nl = 'Avondmelodie 🛀', body_nl = 'Jullie zijn allebei op van een hele dag rennen. Een lauw bad met een zacht, rustig melodietje op de achtergrond kalmeert zijn zenuwstelsel helemaal.', title_pl = 'Melodia nocy 🛀', body_pl = 'Po całym dniu biegania oboje jesteście wykończeni. Ciepła kąpiel i lekka, łagodna melodia w tle całkowicie uspokoją jego układ nerwowy.', title_pt = 'Melodia da noite 🛀', body_pt = 'Depois de correrem o dia todo, estão os dois esgotados. Um banho morno e uma melodia suave a tocar em fundo vão acalmar completamente o sistema nervoso dele.', title_sv = 'Nattens melodi 🛀', body_sv = 'Både du och barnet är helt slut efter en hel dag i farten. Ett ljummet bad och en lätt, lugn melodi i bakgrunden lugnar barnets nervsystem helt.', title_vi = 'Giai điệu của đêm 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều kiệt sức. Một bồn nước ấm cùng giai điệu nhẹ nhàng, êm dịu vang lên phía sau sẽ giúp hệ thần kinh của bé hoàn toàn dịu lại.', title_zh = '夜晚的旋律 🛀', body_zh = '跑了一整天，宝宝和你都累坏了。一次温水澡，加上背景里轻柔舒缓的旋律，会让宝宝的神经系统彻底放松下来。' WHERE id = 'b4771ddf-ae8c-44a0-b4dd-2f61938d3c93' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Momento de crisis 🛒', body_es = 'Grita porque no le compraste el juguete que quería en el súper. No hagas caso de las miradas de los padres perfectos de alrededor. Míralo a los ojos con calma y explícaselo.', title_fr = 'Moment de crise 🛒', body_fr = 'Il hurle parce que vous ne lui avez pas acheté le jouet qu''il voulait au supermarché. Ignorez les regards des parents « parfaits » autour. Regardez-le calmement dans les yeux et expliquez-lui.', title_hi = 'नखरों का पल 🛒', body_hi = 'बाज़ार में मनचाहा खिलौना नहीं मिला तो चिल्ला रहा है? आसपास के ''परफ़ेक्ट'' माता-पिता की नज़रों की परवाह मत कीजिए। शांति से आँखों में आँखें डालकर उसे समझाइए।', title_id = 'Momen tantrum 🛒', body_id = 'Ia menjerit karena Anda tidak membelikan mainan yang ia mau di supermarket. Abaikan tatapan para orang tua ''sempurna'' di sekitar. Tatap matanya dengan tenang dan jelaskan.', title_ja = 'かんしゃくの瞬間 🛒', body_ja = 'スーパーでほしいおもちゃを買ってもらえず、大声で泣いていますか？周りの「完璧な親」たちの視線は気にしないで。落ち着いて目を合わせ、説明してあげましょう。', title_ko = '위기의 순간 🛒', body_ko = '마트에서 원하는 장난감을 안 사 줬다고 소리를 지르나요? 주변 ''완벽한'' 부모들의 시선은 신경 쓰지 마세요. 차분히 눈을 맞추고 설명해 주세요.', title_nl = 'Driftbui in de winkel 🛒', body_nl = 'Hij schreeuwt omdat je het speelgoed dat hij wilde niet hebt gekocht. Trek je niets aan van de blikken van ''perfecte'' ouders. Maak rustig oogcontact en leg het uit.', title_pl = 'Chwila kryzysu 🛒', body_pl = 'Krzyczy, bo nie kupiłaś mu w sklepie zabawki, którą chciał? Nie przejmuj się spojrzeniami „idealnych” rodziców wokół. Spokojnie nawiąż kontakt wzrokowy i wytłumacz.', title_pt = 'Momento de birra 🛒', body_pt = 'Grita no supermercado porque não lhe comprou o brinquedo que queria? Não ligue aos olhares dos pais "perfeitos" à volta. Estabeleça contacto visual com calma e explique.', title_sv = 'Krisläge 🛒', body_sv = 'Barnet skriker för att det inte fick leksaken det ville ha i affären. Bry dig inte om blickarna från de perfekta föräldrarna runt omkring. Skapa lugnt ögonkontakt och förklara.', title_vi = 'Khoảnh khắc khủng hoảng 🛒', body_vi = 'Bé la hét vì mẹ không mua món đồ chơi bé muốn ở siêu thị. Đừng bận tâm đến ánh nhìn của những phụ huynh "hoàn hảo" xung quanh. Hãy bình tĩnh nhìn vào mắt bé và giải thích.', title_zh = '崩溃时刻 🛒', body_zh = '在超市没给买想要的玩具，就大喊大叫？别在意旁边那些“完美父母”的目光。平静地和宝宝对视，耐心解释。' WHERE id = 'fb38f47e-3f88-41bf-87e7-fb7f9b1c8e65' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que esperen las tareas 🛑', body_es = '¿El suelo sin fregar y la ropa sin doblar? Que se quede así. Una casa sucia se arregla, pero una madre agotada psicológicamente tarda mucho en recuperarse. Túmbate en el sofá.', title_fr = 'Les tâches attendront 🛑', body_fr = 'Le sol n''est pas lavé, le linge n''est pas plié ? Laissez tomber. Une maison en désordre se range, mais une maman épuisée psychologiquement met très longtemps à récupérer. Allongez-vous sur le canapé.', title_hi = 'घर के काम रहने दीजिए 🛑', body_hi = 'फ़र्श पोंछा नहीं गया, कपड़े तह नहीं हुए? रहने दीजिए। गंदा घर ठीक हो जाता है, लेकिन मानसिक रूप से थकी माँ को संभलने में बहुत समय लगता है। सोफ़े पर लेट जाइए।', title_id = 'Biarkan pekerjaan rumah 🛑', body_id = 'Lantai belum dipel, baju belum dilipat? Biarkan saja. Rumah berantakan bisa dirapikan, tetapi ibu yang lelah secara mental butuh waktu sangat lama untuk pulih. Berbaringlah di sofa.', title_ja = '家事はあとで 🛑', body_ja = '床はふけていないし、洗濯物もたたんでいない？そのままでいいんです。散らかった家はすぐ片づきますが、心が疲れきったママの回復にはとても時間がかかります。ソファで横になりましょう。', title_ko = '집안일은 미뤄도 돼요 🛑', body_ko = '바닥도 못 닦고 빨래도 못 갰나요? 그냥 두세요. 어질러진 집은 금방 치울 수 있지만, 마음이 지친 엄마가 회복하는 데는 오래 걸려요. 소파에 누워 쉬세요.', title_nl = 'Het huishouden kan wachten 🛑', body_nl = 'Vloer niet gedweild, was niet opgevouwen? Laat maar liggen. Een rommelig huis is zo opgeruimd, maar een mentaal uitgeputte moeder heeft lang nodig om te herstellen. Ga op de bank liggen.', title_pl = 'Obowiązki poczekają 🛑', body_pl = 'Podłoga nieumyta, ubrania nieposkładane? Niech tak zostanie. Bałagan da się posprzątać, ale psychicznie wyczerpana mama długo dochodzi do siebie. Połóż się na kanapie.', title_pt = 'As tarefas podem esperar 🛑', body_pt = 'O chão não está limpo e a roupa não está dobrada? Deixe ficar. Uma casa desarrumada arruma-se, mas uma mãe psicologicamente esgotada demora muito a recuperar. Deite-se no sofá.', title_sv = 'Låt hushållet vänta 🛑', body_sv = 'Golvet är inte moppat, kläderna är inte vikta? Låt det vara. Ett stökigt hem går att fixa, men en psykiskt utmattad mamma tar mycket lång tid att återhämta sig. Lägg dig på soffan.', title_vi = 'Việc nhà để đó 🛑', body_vi = 'Sàn chưa lau, quần áo chưa gấp? Cứ để đó. Nhà bừa có thể dọn lại, nhưng một người mẹ kiệt sức về tâm lý thì cần rất lâu mới hồi phục. Hãy nằm xuống sofa nhé.', title_zh = '家务先放一放 🛑', body_zh = '地没拖，衣服没叠？就让它们放着吧。乱糟糟的家很快就能收拾好，可心力耗尽的妈妈恢复起来要很久。去沙发上躺一会儿。' WHERE id = '3a862b3f-38a2-4cda-8a77-17c531d3e5f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con el insomnio 😭', body_es = 'Se ha despertado en mitad de la noche y no quiere dormir. No te enfades. Escucha su llanto con el Análisis del llanto para saber la causa (dolor, gases, miedo) y abrázale con paciencia.', title_fr = 'Faire la paix avec les nuits blanches 😭', body_fr = 'Il s''est réveillé en pleine nuit et ne veut pas se rendormir. Ne vous énervez pas. Faites écouter ses pleurs à l''Analyse des pleurs pour en trouver la cause (douleur, gaz, peur) et câlinez-le avec patience.', title_hi = 'नींद न आने से समझौता 😭', body_hi = 'आधी रात को जाग गया और सोना नहीं चाहता? उस पर गुस्सा मत कीजिए। क्राइंग एनालिसिस से उसकी आवाज़ सुनाकर वजह (दर्द, गैस, डर) पक्का कीजिए और धैर्य से उसे गले लगाइए।', title_id = 'Berdamai dengan kurang tidur 😭', body_id = 'Ia terbangun tengah malam dan tidak mau tidur lagi. Jangan kesal padanya. Rekam suaranya dengan Analisis Tangisan untuk memastikan penyebabnya (sakit, kembung, takut) lalu peluk ia dengan sabar.', title_ja = '眠れない夜と仲直り 😭', body_ja = '真夜中に目を覚まして、眠ろうとしない？イライラしないで。「泣き声分析」で声を聞かせて原因（痛み、ガス、こわさ）を確かめ、やさしく抱きしめてあげましょう。', title_ko = '잠 못 드는 밤과 화해하기 😭', body_ko = '한밤중에 깨서 다시 자려 하지 않나요? 화내지 마세요. 울음 분석에 소리를 들려주어 이유(통증, 가스, 무서움)를 확인하고 인내심 있게 안아 주세요.', title_nl = 'Vrede sluiten met slapeloosheid 😭', body_nl = 'Hij is midden in de nacht wakker en wil niet slapen. Word niet boos op hem. Laat Huilanalyse luisteren om de oorzaak (pijn, krampjes, angst) te vinden en knuffel hem geduldig.', title_pl = 'Pogodzić się z nieprzespanymi nocami 😭', body_pl = 'Obudził się w środku nocy i nie chce spać? Nie złość się na niego. Daj posłuchać jego płaczu Analizie płaczu, ustal przyczynę (ból, gazy, strach) i cierpliwie go przytul.', title_pt = 'Fazer as pazes com as noites sem dormir 😭', body_pt = 'Acordou a meio da noite e não quer dormir? Não se irrite com ele. Use a Análise do Choro para perceber a causa (dor, gases, medo) e abrace-o com paciência.', title_sv = 'Försonas med sömnlösheten 😭', body_sv = 'Barnet har vaknat mitt i natten och vill inte sova. Bli inte arg. Låt Gråtanalys lyssna på ljudet för att ta reda på orsaken (smärta, gaser, rädsla) och krama barnet med tålamod.', title_vi = 'Làm hòa với những đêm mất ngủ 😭', body_vi = 'Bé thức dậy giữa đêm và không chịu ngủ lại. Đừng bực bé. Hãy cho Phân tích tiếng khóc nghe tiếng khóc để xác định nguyên nhân (đau, đầy hơi, sợ hãi) rồi kiên nhẫn ôm bé vào lòng.', title_zh = '和失眠和解 😭', body_zh = '半夜醒来，就是不肯睡？别对宝宝发火。让哭声分析听一听，弄清原因（疼痛、胀气、害怕），再耐心地抱抱宝宝。' WHERE id = '52c32776-811a-4d66-a0c4-6b1c34cdfc69' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Buscando nuevos amigos 👫', body_es = '¿En el parque intenta correr con otros niños de su edad y acercarse a ellos? ¡La socialización ya está en marcha! Vigílale de lejos y disfruta de este momento con orgullo.', title_fr = 'À la recherche de nouveaux amis 👫', body_fr = 'Au parc, il essaie de courir avec les enfants de son âge et de s''approcher d''eux ? La socialisation est officiellement lancée ! Surveillez-le de loin et savourez ce moment avec fierté.', title_hi = 'नए दोस्त की तलाश 👫', body_hi = 'पार्क में अपने हमउम्र बच्चों के साथ दौड़ने और उनके पास जाने की कोशिश करता है? सामाजिकता अब शुरू हो चुकी है! दूर से नज़र रखते हुए इस पल को गर्व से देखिए।', title_id = 'Mencari teman baru 👫', body_id = 'Ia mencoba berlari bersama teman sebayanya di taman dan mendekati mereka? Sosialisasi resmi dimulai! Awasi dari jauh dan saksikan momen ini dengan bangga.', title_ja = '新しいお友だち探し 👫', body_ja = '公園で同じ年ごろの子と一緒に走ったり、近づこうとしたりしていますか？社会性がいよいよ動き出しました！少し離れて見守りながら、この瞬間を誇らしく眺めましょう。', title_ko = '새 친구 찾기 👫', body_ko = '공원에서 또래와 함께 뛰고 다가가려고 하나요? 사회성이 본격적으로 자라고 있어요! 멀리서 안전을 지키며 이 순간을 뿌듯하게 지켜보세요.', title_nl = 'Op zoek naar nieuwe vriendjes 👫', body_nl = 'Probeert hij in het park met leeftijdsgenootjes mee te rennen en toenadering te zoeken? De socialisatie is officieel begonnen! Houd hem op afstand in de gaten en kijk trots toe.', title_pl = 'W poszukiwaniu nowych przyjaciół 👫', body_pl = 'W parku próbuje biegać z rówieśnikami i do nich podchodzić? Socjalizacja oficjalnie ruszyła! Asekuruj go z daleka i z dumą obserwuj tę chwilę.', title_pt = 'À procura de novos amigos 👫', body_pt = 'No parque, tenta correr com crianças da idade dele e aproximar-se delas? A socialização está oficialmente em marcha! Vigie de longe e acompanhe este momento com orgulho.', title_sv = 'På jakt efter nya vänner 👫', body_sv = 'Försöker barnet springa med jämnåriga i parken och närma sig dem? Socialiseringen är officiellt igång! Håll ett öga på avstånd och se stolt på det här ögonblicket.', title_vi = 'Đi tìm bạn mới 👫', body_vi = 'Bé cố chạy theo các bạn cùng tuổi ở công viên và lại gần các bạn? Bé chính thức bắt đầu hòa nhập xã hội! Hãy trông chừng từ xa và tự hào ngắm khoảnh khắc này.', title_zh = '寻找新朋友 👫', body_zh = '在公园里想跟同龄小朋友一起跑，主动靠近他们？社交正式开始啦！在远处护着宝宝，骄傲地看着这一刻。' WHERE id = 'bc7db5e2-0eb7-4adc-85cd-1181aac8b268' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aprende con el Blog 📱', body_es = '¿Te agota que diga «no» a todo? Es un síntoma clásico de la crisis de los 2 años. Lee los artículos de psicología del Blog de la app y entiende qué pasa en su cerebro.', title_fr = 'Apprenez avec les Blogs 📱', body_fr = 'Ses « non » à tout vous épuisent ? C''est le signe classique du terrible two. Lisez les blogs de psychologie de l''application pour comprendre ce qui se passe dans sa tête.', title_hi = 'ब्लॉग से सीखिए 📱', body_hi = 'बच्चे का हर बात पर ''नहीं'' कहना आपको थका रहा है? यह 2 साल के सिंड्रोम का क्लासिक लक्षण है। ऐप के मनोविज्ञान वाले ब्लॉग पढ़कर समझिए कि उसके दिमाग में क्या चल रहा है।', title_id = 'Belajar dari blog 📱', body_id = 'Kata ''tidak'' untuk segala hal membuat Anda lelah? Ini tanda klasik sindrom usia 2 tahun. Baca blog psikologi di aplikasi untuk memahami apa yang terjadi di otaknya.', title_ja = 'ブログで学ぼう 📱', body_ja = '何にでも「いや」と言われて疲れていませんか？これは2歳ごろによく見られる典型的なサインです。アプリの心理ブログを読んで、お子さんの頭の中で何が起きているのか理解しましょう。', title_ko = '블로그에서 배워요 📱', body_ko = '뭐든 ''싫어''라고 해서 지쳤나요? 전형적인 미운 두 살의 신호예요. 앱의 심리 블로그를 읽고 아이 머릿속에서 무슨 일이 일어나는지 이해해 보세요.', title_nl = 'Leer van de blogs 📱', body_nl = 'Word je moe van zijn eeuwige ''nee''? Dat is een klassiek teken van de peuterpuberteit. Lees de psychologische blogs in de app en begrijp wat er in zijn hoofdje gebeurt.', title_pl = 'Ucz się z Bloga 📱', body_pl = 'Męczy cię, że na wszystko mówi „nie”? To klasyczny objaw buntu 2-latka. Przeczytaj artykuły psychologiczne na Blogu w aplikacji i zrozum, co dzieje się w jego głowie.', title_pt = 'Aprenda com o blogue 📱', body_pt = 'Já está cansada de ouvir "não" a tudo? É um sinal clássico da crise dos 2 anos. Leia os artigos de psicologia no blogue da app e perceba o que se passa no cérebro dele.', title_sv = 'Lär dig av bloggarna 📱', body_sv = 'Är du trött på att barnet säger nej till allt? Det är ett klassiskt tecken på tvåårstrots. Läs psykologibloggarna i appen och förstå vad som händer i barnets hjärna.', title_vi = 'Học từ Blog 📱', body_vi = 'Bé nói "không" với mọi thứ khiến mẹ mệt mỏi? Đây là dấu hiệu kinh điển của "khủng hoảng tuổi lên 2". Hãy đọc các bài blog tâm lý trong ứng dụng để hiểu điều gì đang diễn ra trong não bé.', title_zh = '从博客中学习 📱', body_zh = '孩子什么都说“不”，让你心累？这是“2岁综合征”的典型表现。读读应用里的心理博客，了解宝宝大脑里正在发生什么。' WHERE id = '100554ba-e336-4148-9dd0-9a0ceeecb04b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te culpes 📝', body_es = '¿Hoy se te ha acabado la paciencia y has levantado la voz? Cuando duerma, escribe cómo te sientes en el Diario de ánimo y perdónate. Solo estás cansada, eres humana.', title_fr = 'Ne vous blâmez pas 📝', body_fr = 'Votre patience a lâché aujourd''hui et vous avez haussé le ton ? Quand il dort, écrivez ce que vous ressentez dans le Journal d''humeur et pardonnez-vous. Vous êtes juste fatiguée, vous êtes humaine.', title_hi = 'खुद को दोष मत दीजिए 📝', body_hi = 'आज सब्र टूट गया और आवाज़ ऊँची हो गई? बच्चे के सोने के बाद मूड डायरी में अपनी भावनाएँ लिखिए और खुद को माफ़ कीजिए। आप बस थक गई हैं, आप भी इंसान हैं।', title_id = 'Jangan salahkan diri Anda 📝', body_id = 'Hari ini kesabaran Anda habis dan Anda meninggikan suara? Saat anak tidur, tulis perasaan Anda di Buku Harian Suasana Hati dan maafkan diri Anda. Anda hanya lelah, Anda manusia.', title_ja = '自分を責めないで 📝', body_ja = '今日はがまんできずに声を荒げてしまいましたか？お子さんが眠ったら「気分日記」に気持ちを書いて、自分を許してあげて。ただ疲れているだけ、あなたも人間です。', title_ko = '자책하지 마세요 📝', body_ko = '오늘 인내심이 바닥나서 목소리를 높였나요? 아이가 잠들면 기분 일기에 마음을 적고 스스로를 용서하세요. 그저 지쳤을 뿐이에요. 엄마도 사람이에요.', title_nl = 'Veroordeel jezelf niet 📝', body_nl = 'Was je geduld vandaag op en verhief je je stem? Schrijf je gevoelens in je Stemmingsdagboek als hij slaapt en vergeef jezelf. Je bent gewoon moe, je bent een mens.', title_pl = 'Nie obwiniaj się 📝', body_pl = 'Zabrakło ci dziś cierpliwości i podniosłaś głos? Gdy dziecko zaśnie, zapisz swoje uczucia w Dzienniku nastroju i wybacz sobie. Jesteś po prostu zmęczona, jesteś człowiekiem.', title_pt = 'Não se culpe 📝', body_pt = 'Hoje perdeu a paciência e levantou a voz? Quando a criança adormecer, escreva o que sente no Diário de Humor e perdoe-se. Está apenas cansada, é humana.', title_sv = 'Döm inte dig själv 📝', body_sv = 'Räckte tålamodet inte till i dag och du höjde rösten? När barnet sover, skriv ner dina känslor i Humördagboken och förlåt dig själv. Du är bara trött, du är människa.', title_vi = 'Đừng tự trách mình 📝', body_vi = 'Hôm nay mẹ hết kiên nhẫn và lỡ to tiếng? Khi bé ngủ, hãy viết cảm xúc vào Nhật ký tâm trạng và tha thứ cho bản thân. Mẹ chỉ mệt thôi, mẹ cũng là con người mà.', title_zh = '别责怪自己 📝', body_zh = '今天没忍住，提高了嗓门？孩子睡着后，把感受写进心情日记，原谅自己吧。你只是累了，你也是人。' WHERE id = '19cce24b-ae51-482e-8dc7-6812a220483b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escaleras por su cuenta 🧗‍♂️', body_es = '¿Está deseando subir escaleras de tu mano, o incluso solo? Está poniendo a prueba los límites de su cuerpo. Vigílale y dale sin falta esa libertad.', title_fr = 'Les escaliers en solo 🧗‍♂️', body_fr = 'Il veut monter les escaliers en vous tenant la main, voire tout seul ? Il teste les limites de son corps. Restez à côté pour l''assurer, mais laissez-lui absolument cette liberté.', title_hi = 'खुद सीढ़ियाँ चढ़ना 🧗‍♂️', body_hi = 'आपका हाथ पकड़कर सीढ़ियाँ चढ़ने, यहाँ तक कि खुद चढ़ने को बेताब है? वह अपने शरीर की सीमाएँ परख रहा है। पास रहकर संभालिए और उसे यह आज़ादी ज़रूर दीजिए।', title_id = 'Naik tangga sendiri 🧗‍♂️', body_id = 'Ia ingin naik tangga sambil memegang tangan Anda, bahkan mencoba naik sendiri? Ia sedang menguji batas tubuhnya. Awasi dan berikan ia kebebasan ini.', title_ja = '階段にチャレンジ 🧗‍♂️', body_ja = '手をつないで階段を上ったり、ひとりで上ろうとしたりしていますか？体の限界をためしています。しっかり見守りながら、この自由をぜひ認めてあげましょう。', title_ko = '혼자 계단 오르기 🧗‍♂️', body_ko = '엄마 손을 잡고 계단을 오르거나 혼자 올라가고 싶어 하나요? 몸의 한계를 시험하는 중이에요. 곁에서 지켜 주면서 이 자유를 꼭 허락해 주세요.', title_nl = 'Zelf de trap op 🧗‍♂️', body_nl = 'Wil hij aan je hand de trap op, of zelfs helemaal alleen? Hij test de grenzen van zijn lichaam. Blijf erbij en gun hem die vrijheid.', title_pl = 'Samodzielnie po schodach 🧗‍♂️', body_pl = 'Trzymając cię za rękę, wspina się po schodach, a nawet chce wchodzić sam? Sprawdza granice swojego ciała. Asekuruj go, ale koniecznie daj mu tę swobodę.', title_pt = 'Escadas sem ajuda 🧗‍♂️', body_pt = 'Quer subir as escadas pela sua mão, ou até sozinho? Está a testar os limites do corpo. Fique por perto e dê-lhe sem falta esta liberdade.', title_sv = 'Trappor på egen hand 🧗‍♂️', body_sv = 'Vill barnet gå i trappan med din hand, eller till och med klättra upp själv? Barnet testar kroppens gränser. Säkra upp och ge barnet den här friheten.', title_vi = 'Tự leo cầu thang 🧗‍♂️', body_vi = 'Bé háo hức nắm tay mẹ leo cầu thang, thậm chí muốn tự leo lên? Bé đang thử giới hạn của cơ thể. Hãy trông chừng và nhất định cho bé sự tự do này.', title_zh = '自己爬楼梯 🧗‍♂️', body_zh = '拉着你的手爬楼梯，甚至想自己爬上去？宝宝正在试探身体的极限。在一旁护着，一定要给宝宝这份自由。' WHERE id = '1bc0b4db-b3a8-4a70-bfa5-eaa18f5fe1f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Miedo a la separación 🥺', body_es = '¿Hasta cuando vas al baño te espera llorando detrás de la puerta? La ansiedad por separación a veces se intensifica. Háblale cada vez para que sepa que estás ahí y que vas a volver.', title_fr = 'Peur de la séparation 🥺', body_fr = 'Même quand vous allez aux toilettes, il pleure derrière la porte en vous attendant. L''angoisse de séparation devient parfois plus forte. Parlez-lui à chaque fois pour lui dire que vous êtes là et que vous revenez.', title_hi = 'बिछड़ने का डर 🥺', body_hi = 'आप टॉयलेट भी जाएँ तो दरवाज़े के पीछे इंतज़ार करते हुए रोता है? अलगाव की चिंता कभी-कभी बढ़ जाती है। हर बार आवाज़ देकर बताइए कि आप यहीं हैं और लौट आएँगी।', title_id = 'Takut berpisah 🥺', body_id = 'Bahkan saat Anda ke toilet, ia menunggu di balik pintu sambil menangis. Kecemasan berpisah kadang memuncak. Setiap kali, bersuaralah dan katakan bahwa Anda ada di sini dan akan kembali.', title_ja = '離れるのがこわい 🥺', body_ja = 'トイレに行くときでさえ、ドアの向こうで待って泣いていますか？分離不安が強くなる時期もあります。そのたびに声をかけて、ここにいること、戻ってくることを伝えましょう。', title_ko = '분리 불안 🥺', body_ko = '화장실에 갈 때도 문 앞에서 기다리며 우나요? 분리 불안이 가끔 심해질 수 있어요. 그때마다 목소리를 들려주며 여기 있고 꼭 돌아온다고 말해 주세요.', title_nl = 'Verlatingsangst 🥺', body_nl = 'Zelfs als je naar de wc gaat, wacht hij huilend achter de deur. Verlatingsangst kan soms heftig worden. Laat steeds je stem horen en zeg dat je er bent en terugkomt.', title_pl = 'Lęk separacyjny 🥺', body_pl = 'Nawet gdy idziesz do toalety, czeka pod drzwiami i płacze? Lęk separacyjny czasem się nasila. Za każdym razem odezwij się i powiedz, że jesteś obok i wrócisz.', title_pt = 'Medo da separação 🥺', body_pt = 'Até quando vai à casa de banho, espera por si atrás da porta a chorar? A ansiedade de separação por vezes intensifica-se. Fale com ele sempre, diga-lhe que está ali e que vai voltar.', title_sv = 'Separationsrädsla 🥺', body_sv = 'Barnet väntar bakom dörren och gråter till och med när du går på toaletten. Separationsångesten kan ibland bli starkare. Ropa varje gång och säg att du är här och att du kommer tillbaka.', title_vi = 'Nỗi sợ xa mẹ 🥺', body_vi = 'Ngay cả khi mẹ vào nhà vệ sinh, bé cũng đứng sau cửa chờ và khóc. Lo âu chia ly đôi khi trở nên dữ dội. Mỗi lần như vậy, hãy lên tiếng để bé biết mẹ ở ngay đây và sẽ quay lại.', title_zh = '分离焦虑 🥺', body_zh = '连你去洗手间，宝宝都在门外等着哭？分离焦虑有时会变得强烈。每次都出声告诉宝宝你就在这里，你会回来的。' WHERE id = '380af2db-ede8-491b-ab1a-6f695da10f42' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La oscuridad de la habitación 🌙', body_es = 'Para que se duerma antes, apaga todas las luces extra de la habitación y, sobre todo, las pantallas de las tablets. La melatonina solo se produce a oscuras.', title_fr = 'L''obscurité de la chambre 🌙', body_fr = 'Pour qu''il s''endorme plus vite, éteignez toutes les lumières inutiles de la chambre, et surtout les écrans de tablette. La mélatonine n''est sécrétée que dans le noir.', title_hi = 'कमरे का अंधेरा 🌙', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी अतिरिक्त लाइटें और खासकर टैबलेट की स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ अंधेरे माहौल में बनता है।', title_id = 'Kamar yang gelap 🌙', body_id = 'Agar ia lebih cepat tertidur, matikan semua lampu tambahan di kamar, terutama layar tablet. Melatonin hanya diproduksi dalam suasana gelap.', title_ja = '部屋を暗く 🌙', body_ja = '早く寝つけるように、部屋の余分な明かり、特にタブレットの画面はすべて消しましょう。メラトニンは暗い環境でしか分泌されません。', title_ko = '방의 어둠 🌙', body_ko = '더 빨리 잠들 수 있도록 방의 불필요한 조명, 특히 태블릿 화면을 모두 꺼 주세요. 멜라토닌은 어두운 환경에서만 분비돼요.', title_nl = 'Een donkere kamer 🌙', body_nl = 'Wil je dat hij sneller in slaap valt? Doe alle extra lampjes en vooral tabletschermen in de kamer uit. Melatonine wordt alleen in het donker aangemaakt.', title_pl = 'Ciemność w pokoju 🌙', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie dodatkowe światła, a zwłaszcza ekrany tabletów. Melatonina wydziela się tylko w ciemności.', title_pt = 'Quarto às escuras 🌙', body_pt = 'Para que adormeça mais depressa, apague todas as luzes extra do quarto e sobretudo os ecrãs de tablets. A melatonina só é produzida no escuro.', title_sv = 'Mörker i rummet 🌙', body_sv = 'För att barnet ska somna snabbare, släck alla extra lampor i rummet och särskilt surfplattans skärm. Melatonin utsöndras bara i mörker.', title_vi = 'Bóng tối trong phòng 🌙', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi đèn phụ trong phòng, đặc biệt là màn hình máy tính bảng. Melatonin chỉ được tiết ra trong môi trường tối.', title_zh = '房间的黑暗 🌙', body_zh = '想让宝宝更快入睡，就关掉房间里所有多余的灯光，尤其是平板屏幕。褪黑素只有在黑暗环境中才会分泌。' WHERE id = '805c93f2-e2d3-43ec-9e6f-4782049680cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pulso con la comida 🥣', body_es = '¿Come dos cucharadas y dice que está lleno? No le obligues. Crear una relación sana con la comida es más importante que hacerle comer a la fuerza. Ofrece más tomas con raciones más pequeñas.', title_fr = 'Bras de fer à table 🥣', body_fr = 'Deux cuillères et il dit qu''il n''a plus faim ? Ne le forcez pas. Construire une relation saine avec la nourriture compte plus que le faire manger de force. Proposez des repas plus fréquents, en plus petites quantités.', title_hi = 'खाने को लेकर ज़िद 🥣', body_hi = 'दो चम्मच खाकर कहता है ''पेट भर गया''? ज़बरदस्ती मत कीजिए। ज़बरदस्ती खिलाने से ज़्यादा ज़रूरी है खाने के साथ स्वस्थ रिश्ता बनाना। खाने के मौके बढ़ाइए, मात्रा घटाइए।', title_id = 'Drama saat makan 🥣', body_id = 'Baru dua sendok sudah bilang kenyang? Jangan memaksanya. Membangun hubungan sehat dengan makanan lebih penting daripada menyuapi secara paksa. Perbanyak waktu makan, kecilkan porsinya.', title_ja = '食事でのせめぎ合い 🥣', body_ja = 'ふた口食べて「おなかいっぱい」と言いますか？無理に食べさせないで。食べ物とよい関係を築くことは、無理やり食べさせるより大切です。回数を増やして、1回の量を減らしましょう。', title_ko = '밥상 위의 고집 🥣', body_ko = '두 숟가락 먹고 배부르다고 하나요? 억지로 먹이지 마세요. 억지로 먹이는 것보다 음식과 건강한 관계를 만드는 게 더 중요해요. 양은 줄이고 횟수를 늘려 주세요.', title_nl = 'Strijd aan tafel 🥣', body_nl = 'Zegt hij na twee hapjes al dat hij vol zit? Dwing hem niet. Een gezonde relatie met eten is belangrijker dan dwangvoeren. Geef vaker kleinere porties.', title_pl = 'Uparty przy jedzeniu 🥣', body_pl = 'Po dwóch łyżkach mówi, że jest najedzony? Nie zmuszaj go. Zdrowa relacja z jedzeniem jest ważniejsza niż karmienie na siłę. Podawaj częściej, ale mniejsze porcje.', title_pt = 'Teimosia à mesa 🥣', body_pt = 'Come duas colheres e diz que está cheio? Não o force. Criar uma relação saudável com a comida é mais importante do que obrigá-lo a comer. Ofereça mais refeições, em porções mais pequenas.', title_sv = 'Envishet vid maten 🥣', body_sv = 'Äter barnet två skedar och säger att det är mätt? Tvinga inte. Att bygga en sund relation till mat är viktigare än att tvångsmata. Fler portioner, mindre mängd.', title_vi = 'Giằng co trong bữa ăn 🥣', body_vi = 'Bé ăn hai thìa đã bảo no? Đừng ép bé. Xây dựng mối quan hệ lành mạnh với thức ăn quan trọng hơn ép ăn. Hãy cho ăn nhiều bữa hơn, mỗi bữa ít hơn.', title_zh = '吃饭较劲 🥣', body_zh = '吃了两勺就说“饱了”？别勉强。和食物建立健康的关系，比强迫进食重要得多。多分几次吃，每次少一点。' WHERE id = 'ba544f24-4325-4cce-9fad-539f5e144287' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La alegría de aplaudir 👏', body_es = '¿Cuando consigue algo (como hacer una torre) se aplaude solo, todo orgulloso? ¡Quiere que se lo reconozcan! Celebra tú también su pequeño logro con mucha alegría.', title_fr = 'La joie d''applaudir 👏', body_fr = 'Quand il réussit quelque chose (une tour, par exemple), il s''applaudit tout seul, tout fier ? Il a besoin d''être encouragé ! Applaudissez, vous aussi, sa petite réussite avec une grande joie.', title_hi = 'ताली बजाने की खुशी 👏', body_hi = 'कुछ कर लेने पर (जैसे टावर बनाकर) खुद ही ताली बजाकर गर्व करता है? वह चाहता है कि उसे सराहा जाए! उसकी इस छोटी सी कामयाबी पर आप भी बड़ी खुशी से ताली बजाइए।', title_id = 'Senangnya bertepuk tangan 👏', body_id = 'Saat berhasil melakukan sesuatu (misalnya menyusun menara), ia bertepuk tangan sendiri dengan bangga? Ia ingin diakui! Sambut keberhasilan kecilnya dengan kegembiraan besar.', title_ja = '拍手のよろこび 👏', body_ja = '何かができたとき（たとえば塔を作ったとき）、自分で拍手して得意げにしていますか？認めてほしいのです！この小さな成功を、あなたも大きなよろこびで拍手してあげましょう。', title_ko = '박수의 기쁨 👏', body_ko = '무언가를 해냈을 때(예: 탑 쌓기) 스스로 박수 치며 뿌듯해하나요? 인정받고 싶은 거예요! 이 작은 성공을 엄마도 크게 기뻐하며 박수로 응원해 주세요.', title_nl = 'Klappen van blijdschap 👏', body_nl = 'Klapt hij voor zichzelf en is hij trots als iets lukt (zoals een toren bouwen)? Hij wil bevestiging! Juich zijn kleine succes ook met grote blijdschap toe.', title_pl = 'Radość klaskania 👏', body_pl = 'Gdy coś mu się uda (np. zbuduje wieżę), sam sobie klaszcze i jest dumny? Chce uznania! Ty też oklaskuj jego mały sukces z wielką radością.', title_pt = 'A alegria de bater palmas 👏', body_pt = 'Quando consegue fazer algo (por exemplo, uma torre), bate palmas a si próprio cheio de orgulho? Quer reconhecimento! Aplauda também esta pequena conquista com muita alegria.', title_sv = 'Glädjen i att klappa händerna 👏', body_sv = 'Klappar barnet händerna för sig själv och är stolt när något lyckas (till exempel att bygga ett torn)? Barnet vill bli bekräftat! Applådera den lilla framgången med stor glädje du också.', title_vi = 'Niềm vui vỗ tay 👏', body_vi = 'Khi làm được điều gì đó (như xếp một tòa tháp), bé tự vỗ tay và đầy tự hào? Bé muốn được công nhận! Hãy cùng reo mừng thành công nhỏ này của bé thật vui vẻ.', title_zh = '拍手的喜悦 👏', body_zh = '做成一件事（比如搭好一座塔）就自己拍手，很骄傲？宝宝想得到认可！你也用大大的喜悦为这个小成就鼓掌吧。' WHERE id = '0b8f75a4-5ddd-4527-a07d-f3a8b79df578' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de calma ☕', body_es = 'Si no hay siesta, establece al menos 1 hora de calma (quiet time). Que hojee un libro en su cama mientras tú te tomas el té y miras el móvil.', title_fr = 'L''heure calme ☕', body_fr = 'Pas de sieste ? Instaurez au moins 1 heure de « temps calme ». Il feuillette un livre dans son lit pendant que vous buvez votre thé en regardant votre téléphone.', title_hi = 'शांत समय ☕', body_hi = 'अगर दिन की नींद नहीं होती, तो कम से कम 1 घंटे का ''शांत समय'' (quiet time) तय कीजिए। वह अपने बिस्तर पर किताब पलटे और आप अपनी चाय पीते हुए फ़ोन देखिए।', title_id = 'Jam tenang ☕', body_id = 'Kalau tidak ada tidur siang, tetapkan setidaknya 1 jam ''waktu tenang'' (quiet time). Biarkan ia membolak-balik buku di tempat tidurnya, sementara Anda minum teh dan melihat ponsel.', title_ja = '静かな時間 ☕', body_ja = 'お昼寝をしないなら、少なくとも1時間の「静かな時間」を決めましょう。お子さんは自分のベッドで絵本をめくり、あなたはお茶を飲みながらスマホを見てひと休み。', title_ko = '조용한 시간 ☕', body_ko = '낮잠을 안 잔다면 최소 1시간의 ''조용한 시간''을 정해 보세요. 아이는 침대에서 책을 넘겨 보고, 엄마는 차를 마시며 휴대폰을 보세요.', title_nl = 'Rustuurtje ☕', body_nl = 'Geen middagslaapje? Plan dan minstens een uur rusttijd. Laat hem in zijn bed in een boekje bladeren, terwijl jij je thee drinkt en op je telefoon kijkt.', title_pl = 'Godzina wyciszenia ☕', body_pl = 'Jeśli nie ma drzemki, wyznacz przynajmniej 1 godzinę wyciszenia (quiet time). Niech przegląda książeczkę w swoim łóżku, a ty wypij herbatę i zajrzyj do telefonu.', title_pt = 'Hora do sossego ☕', body_pt = 'Se não houver sesta, defina pelo menos 1 hora de sossego (quiet time). Ele folheia um livro na cama dele e a mãe bebe o seu chá e vê o telemóvel.', title_sv = 'Lugn stund ☕', body_sv = 'Om barnet inte sover på dagen, inför minst 1 timmes Lugn stund (quiet time). Låt barnet bläddra i böcker i sin säng medan du dricker ditt te och kollar mobilen.', title_vi = 'Giờ yên tĩnh ☕', body_vi = 'Nếu bé không ngủ ngày, hãy đặt ít nhất 1 tiếng "Giờ yên tĩnh" (quiet time). Bé lật sách trên giường của mình, còn mẹ uống trà và xem điện thoại.', title_zh = '安静时间 ☕', body_zh = '如果不睡午觉，至少定一个1小时的“安静时间”。让宝宝在自己床上翻翻书，你喝喝茶、看看手机。' WHERE id = '2ac10424-b1ee-4b11-b087-e5d8e74e2722' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pausa en pareja 🥂', body_es = 'Tu peque se ha dormido. Ahora aparca los móviles y las tareas de casa. Habla con tu pareja al menos 20 minutos de cualquier tema que no sea el niño. También sois una pareja.', title_fr = 'Pause à deux 🥂', body_fr = 'L''enfant dort. Maintenant, mettez de côté téléphones et tâches ménagères. Parlez avec votre partenaire au moins 20 minutes d''autre chose que de l''enfant. Vous êtes aussi un couple.', title_hi = 'कपल ब्रेक 🥂', body_hi = 'बच्चा सो गया। अब फ़ोन और घर के काम एक तरफ़ रखिए। अपने पार्टनर से कम से कम 20 मिनट बच्चे के अलावा किसी भी विषय पर बात कीजिए। आप एक कपल भी हैं।', title_id = 'Waktu berdua 🥂', body_id = 'Anak sudah tidur. Sekarang singkirkan ponsel dan pekerjaan rumah. Mengobrollah dengan pasangan setidaknya 20 menit tentang topik apa pun selain anak. Anda juga sepasang kekasih.', title_ja = 'ふたりの休憩 🥂', body_ja = 'お子さんが眠りました。スマホも家事もいったん脇に置いて、パートナーと少なくとも20分、子どものこと以外の話をしましょう。あなたたちは夫婦でもあるのです。', title_ko = '부부만의 쉼표 🥂', body_ko = '아이가 잠들었어요. 이제 휴대폰과 집안일은 내려놓으세요. 배우자와 최소 20분 동안 아이 말고 다른 이야기를 나눠 보세요. 두 사람은 부부이기도 하니까요.', title_nl = 'Tijd voor jullie tweeën 🥂', body_nl = 'Hij slaapt. Leg nu telefoons en huishouden opzij. Praat minstens 20 minuten met je partner over iets anders dan de kinderen. Jullie zijn ook nog een stel.', title_pl = 'Przerwa dla was dwojga 🥂', body_pl = 'Dziecko śpi. Teraz odłóżcie telefony i obowiązki domowe. Porozmawiaj z partnerem przez co najmniej 20 minut na dowolny temat poza dzieckiem. Jesteście też parą.', title_pt = 'Pausa a dois 🥂', body_pt = 'A criança adormeceu. Agora ponha de lado os telemóveis e as tarefas de casa. Converse com o seu companheiro pelo menos 20 minutos sobre qualquer assunto que não seja a criança. Também são um casal.', title_sv = 'Paus för er två 🥂', body_sv = 'Barnet sover. Lägg nu undan mobilerna och hushållet. Prata med din partner i minst 20 minuter om något annat än barnet. Ni är också ett par.', title_vi = 'Phút nghỉ của hai vợ chồng 🥂', body_vi = 'Bé ngủ rồi. Giờ hãy gác điện thoại và việc nhà sang một bên. Trò chuyện với chồng ít nhất 20 phút về bất kỳ chủ đề nào ngoài con cái. Hai người còn là một cặp đôi nữa.', title_zh = '夫妻小憩 🥂', body_zh = '孩子睡着了。现在把手机和家务放到一边。和另一半至少聊20分钟孩子以外的话题。你们同时也是一对伴侣。' WHERE id = '2eea19a8-6377-4aff-9f02-8b899ec1a730' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Poniendo a prueba los límites ⚠️', body_es = '¿Le dices «no lo hagas» y lo hace mirándote a los ojos? No quiere enfadarte, está comprobando lo firmes que son tus límites. Mantente firme.', title_fr = 'Il teste les limites ⚠️', body_fr = 'Vous lui dites « ne fais pas ça » et il le fait en vous regardant droit dans les yeux ? Il ne cherche pas à vous mettre en colère, il teste la solidité de vos limites. Restez constante.', title_hi = 'सीमाओं की परख ⚠️', body_hi = '''ऐसा मत करो'' कहने पर भी आपकी आँखों में देखते हुए वही करता है? वह आपको गुस्सा नहीं दिलाना चाहता, बल्कि परख रहा है कि आपकी सीमाएँ कितनी पक्की हैं। अडिग रहिए।', title_id = 'Menguji batas ⚠️', body_id = 'Anda bilang ''jangan lakukan itu'', tetapi ia melakukannya sambil menatap mata Anda? Ia tidak ingin membuat Anda marah, ia menguji seberapa kokoh batasan Anda. Tetaplah konsisten.', title_ja = '境界線のテスト ⚠️', body_ja = '「やめてね」と言ったのに、目をじっと見ながらその行動をしますか？怒らせたいのではなく、あなたのルールがどれだけ揺るがないかを試しているのです。ぶれずにいましょう。', title_ko = '경계 시험하기 ⚠️', body_ko = '''하지 마''라고 했는데 눈을 똑바로 보며 그 행동을 하나요? 엄마를 화나게 하려는 게 아니라 경계가 얼마나 단단한지 시험하는 거예요. 일관성을 지키세요.', title_nl = 'Grenzen testen ⚠️', body_nl = 'Doet hij precies wat je hem verbood en kijkt hij je daarbij recht aan? Hij wil je niet boos maken, hij test hoe stevig je grenzen zijn. Blijf consequent.', title_pl = 'Testowanie granic ⚠️', body_pl = 'Mówisz „nie rób tego”, a on patrzy ci w oczy i robi to dalej? Nie chce cię rozzłościć, tylko sprawdza, jak stabilne są twoje granice. Bądź konsekwentna.', title_pt = 'Testar limites ⚠️', body_pt = 'Diz-lhe "não faças isso" e ele faz, a olhar-lhe nos olhos? Não é para a irritar, está a testar a firmeza dos seus limites. Mantenha-se firme.', title_sv = 'Gränstestning ⚠️', body_sv = 'Gör barnet det du sa ”gör inte så” om, medan hen tittar dig rakt i ögonen? Det handlar inte om att reta dig, barnet testar hur stabila dina gränser är. Var konsekvent.', title_vi = 'Thử giới hạn ⚠️', body_vi = 'Mẹ bảo "Đừng làm thế" mà bé vẫn nhìn thẳng vào mắt mẹ và làm? Bé không cố chọc giận mẹ, mà đang thử xem giới hạn của mẹ vững đến đâu. Hãy giữ vững lập trường.', title_zh = '试探界限 ⚠️', body_zh = '你说了“别这样”，宝宝却盯着你的眼睛照做不误？这不是为了惹你生气，而是在测试你的界限有多稳定。保持坚定。' WHERE id = '8df55e5c-cbbb-49b9-bd1a-b655d228f1d5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reacción a los dibujos 📖', body_es = '¿Toca los animales o niños que ve en el libro y hace sonidos? Su percepción visual es asombrosa. Marca este detalle en el Seguimiento del desarrollo.', title_fr = 'Il réagit aux images 📖', body_fr = 'Il touche les animaux ou les enfants dans les livres et fait des bruits ? Sa perception visuelle est étonnante. Notez ce détail dans le Suivi de développement.', title_hi = 'तस्वीरों पर प्रतिक्रिया 📖', body_hi = 'किताब में जानवरों या बच्चों को देखकर उन्हें छूता है, आवाज़ें निकालता है? उसकी देखकर समझने की क्षमता कमाल की है। ग्रोथ ट्रैकर में यह बात दर्ज कीजिए।', title_id = 'Bereaksi pada gambar 📖', body_id = 'Saat melihat hewan atau anak-anak di buku, ia menyentuhnya dan bersuara? Persepsi visualnya luar biasa. Tandai detail ini di Pelacak Perkembangan.', title_ja = '絵への反応 📖', body_ja = '絵本の動物や子どもを見て、さわったり声を出したりしますか？視覚的な理解力がすばらしいですね。「発達トラッカー」にこの成長を記録しましょう。', title_ko = '그림에 반응해요 📖', body_ko = '책 속 동물이나 아이들을 보면 만지고 소리를 내나요? 시각 인지가 놀라워요. 성장 기록에 이 순간을 표시해 두세요.', title_nl = 'Reageren op plaatjes 📖', body_nl = 'Raakt hij dieren of kinderen in een boek aan en maakt hij er geluidjes bij? Zijn visuele waarneming is geweldig. Leg dit detail vast in de Groeitracker.', title_pl = 'Reakcja na obrazki 📖', body_pl = 'Dotyka zwierzątek i dzieci w książeczce i wydaje przy tym dźwięki? Jego percepcja wzrokowa jest niesamowita. Zaznacz ten szczegół w Śledzeniu rozwoju.', title_pt = 'Reagir às imagens 📖', body_pt = 'Toca nos animais ou nas crianças que vê nos livros e faz sons? A perceção visual é espantosa. Marque este detalhe no Registo de Desenvolvimento.', title_sv = 'Reaktion på bilder 📖', body_sv = 'Rör barnet vid djuren eller barnen i boken och gör ljud när hen ser dem? Synuppfattningen är fantastisk. Markera den här detaljen i Utvecklingsspåraren.', title_vi = 'Phản ứng với tranh ảnh 📖', body_vi = 'Bé chạm vào và phát ra âm thanh khi thấy con vật hay em bé trong sách? Khả năng nhận thức thị giác của bé thật đáng kinh ngạc. Hãy đánh dấu chi tiết này trong Theo dõi phát triển.', title_zh = '对图片有反应 📖', body_zh = '看到书里的动物或小朋友，就去摸、还发出声音？视觉感知真是惊人。在发育追踪里标记下这个细节吧。' WHERE id = 'aa89536f-3d4b-4a1e-9088-0384b755894e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detox verde 🌿', body_es = '¿Te sientes hinchada? Revisa tu ciclo en el Calendario menstrual y, con un batido verde de Recetas saludables para mujeres, depura tu cuerpo y recupera la energía.', title_fr = 'Détox aux légumes verts 🌿', body_fr = 'Vous vous sentez gonflée ? Vérifiez votre cycle dans le Suivi des règles et, avec un smoothie vert des Recettes saines pour femmes, purifiez votre corps et retrouvez votre énergie.', title_hi = 'हरी सब्ज़ियों से डिटॉक्स 🌿', body_hi = 'पेट फूला हुआ लगता है? पीरियड ट्रैकर में अपना चक्र देखिए और महिलाओं के लिए सेहतमंद रेसिपी से ग्रीन स्मूदी बनाकर शरीर को हल्का कीजिए और ऊर्जा वापस पाइए।', title_id = 'Detoks sayuran hijau 🌿', body_id = 'Merasa kembung? Periksa siklus Anda di Pelacak Menstruasi dan bersihkan tubuh serta pulihkan energi dengan smoothie hijau dari Resep Sehat untuk wanita.', title_ja = 'グリーンでデトックス 🌿', body_ja = 'おなかの張りを感じますか？「生理トラッカー」で周期を確認して、「女性のためのヘルシーレシピ」のグリーンスムージーで体をすっきりさせ、元気を取り戻しましょう。', title_ko = '초록 디톡스 🌿', body_ko = '몸이 붓는 느낌인가요? 생리 주기 기록에서 주기를 확인하고, 여성을 위한 건강한 레시피의 그린 스무디로 몸을 가볍게 하고 기운을 되찾으세요.', title_nl = 'Groene detox 🌿', body_nl = 'Voel je je opgeblazen? Check je cyclus in de Cyclustracker en reinig je lichaam en herstel je energie met een groene smoothie uit Gezonde recepten voor vrouwen.', title_pl = 'Zielony detoks 🌿', body_pl = 'Czujesz się wzdęta? Sprawdź swój cykl w Kalendarzu miesiączkowym i z zielonym smoothie ze Zdrowych przepisów dla kobiet oczyść organizm i odzyskaj energię.', title_pt = 'Detox verde 🌿', body_pt = 'Sente-se inchada? Veja o seu ciclo no Registo do Período e, com um smoothie verde das Receitas Saudáveis para Mulheres, limpe o corpo e recupere a energia.', title_sv = 'Grön detox 🌿', body_sv = 'Känner du dig uppsvälld? Kolla din cykel i Mensspåraren och rena kroppen och återställ energin med en grön smoothie från Hälsosamma recept för kvinnor.', title_vi = 'Detox rau xanh 🌿', body_vi = 'Mẹ thấy người đầy hơi? Hãy xem chu kỳ trong Theo dõi kỳ kinh và làm một ly sinh tố xanh từ Công thức lành mạnh cho phụ nữ để thanh lọc cơ thể và lấy lại năng lượng.', title_zh = '绿色排毒 🌿', body_zh = '感觉身体浮肿？在经期记录里看看你的周期，再从女性健康食谱里做一杯绿色奶昔，净化身体、恢复活力。' WHERE id = '41c18ba7-5f94-4cf4-bbb5-a65eaf5e3cf9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Corre mucho y bebe poca agua? Fíjate en las deposiciones al cambiar el pañal (o en el orinal). Si hay riesgo de estreñimiento, añade avena a su menú.', body_fr = 'Il court beaucoup et boit peu ? Surveillez ses selles en changeant la couche (ou au pot). En cas de risque de constipation, ajoutez de l''avoine à son menu.', body_hi = 'खूब दौड़ता है, पर पानी कम पीता है? डायपर बदलते समय (या पॉटी में) मल पर नज़र रखिए। अगर कब्ज़ का खतरा हो, तो मेन्यू में ओट्स जोड़िए।', body_id = 'Banyak berlari, sedikit minum? Perhatikan kotorannya saat mengganti popok (atau di pispot). Jika ada risiko sembelit, tambahkan oat ke menunya.', body_ja = 'よく走るのに、お水はあまり飲まない？おむつ替えのとき（またはおまるで）便の様子をチェックしましょう。便秘が心配なら、メニューにオートミールを加えて。', body_ko = '많이 뛰는데 물은 적게 마시나요? 기저귀를 갈 때(또는 아기 변기에서) 배변을 살펴보세요. 변비가 걱정된다면 식단에 귀리를 추가하세요.', body_nl = 'Rent hij veel en drinkt hij weinig? Let bij het verschonen (of op het potje) op zijn ontlasting. Is er kans op verstopping, voeg dan havermout toe aan zijn menu.', body_pl = 'Dużo biega, mało pije? Przy zmianie pieluszki (lub na nocniku) obserwuj wypróżnienia. Jeśli grozi zaparcie, dodaj do menu płatki owsiane.', body_pt = 'Corre muito e bebe pouca água? Repare nas fezes ao mudar a fralda (ou no bacio). Se houver risco de prisão de ventre, junte aveia à ementa.', body_sv = 'Springer barnet mycket men dricker lite vatten? Håll koll på avföringen när du byter blöja (eller på pottan). Om det finns risk för förstoppning, lägg till havre i menyn.', body_vi = 'Bé chạy nhiều mà uống ít nước? Hãy để ý chất thải khi thay tã (hoặc khi ngồi bô). Nếu có nguy cơ táo bón, hãy thêm yến mạch vào thực đơn.', body_zh = '跑得多、喝得少？换尿布时（或在便盆里）留意一下排便情况。如果有便秘风险，就在菜单里加点燕麦。' WHERE id = '99409d74-b463-47c8-b5a8-30d9e195253d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡A cazar monstruos! 👾', body_es = '¿Busca monstruos debajo de la cama? Aumentan los miedos imaginarios. Pon el sonido del ventilador de Ruido blanco para crear un ambiente seguro y monótono en la habitación y calmarle.', title_fr = 'Chasse aux monstres ! 👾', body_fr = 'Il cherche des monstres sous le lit ? Les peurs imaginaires augmentent. Mettez le bruit du ventilateur dans les Bruits blancs pour créer une ambiance rassurante et monotone et l''apaiser.', title_hi = 'राक्षस का शिकार! 👾', body_hi = 'बिस्तर के नीचे राक्षस ढूँढता है? कल्पना से जुड़े डर बढ़ रहे हैं। व्हाइट नॉइज़ में पंखे की आवाज़ चलाकर कमरे में सुरक्षित और एक जैसी लय वाला माहौल बनाइए और उसे शांत कीजिए।', title_id = 'Berburu monster! 👾', body_id = 'Ia mencari monster di bawah tempat tidur? Ketakutan imajinatif sedang meningkat. Putar suara kipas dari Suara Putih untuk menciptakan suasana aman dan monoton, lalu tenangkan ia.', title_ja = 'モンスター退治！👾', body_ja = 'ベッドの下のモンスターを探していますか？想像からくるこわさが増える時期です。「ホワイトノイズ」の扇風機の音を流して、安心できる単調な環境をつくり、落ち着かせてあげましょう。', title_ko = '괴물 사냥! 👾', body_ko = '침대 밑에서 괴물을 찾나요? 상상 속 두려움이 커지는 시기예요. 백색소음에서 선풍기 소리를 틀어 방에 안전하고 단조로운 환경을 만들어 진정시켜 주세요.', title_nl = 'Monsterjacht! 👾', body_nl = 'Zoekt hij monsters onder het bed? Fantasieangsten nemen toe. Zet in Witte ruis het ventilatorgeluid aan en kalmeer hem met een veilige, eentonige sfeer.', title_pl = 'Polowanie na potwory! 👾', body_pl = 'Szuka potworów pod łóżkiem? Wyobrażone lęki narastają. Włącz z Białego szumu dźwięk wentylatora, stwórz w pokoju bezpieczne, monotonne otoczenie i go uspokój.', title_pt = 'Caça aos monstros! 👾', body_pt = 'Procura monstros debaixo da cama? Os medos imaginários estão a aumentar. Ponha o som de ventoinha do Ruído Branco, crie um ambiente seguro e monótono no quarto e acalme-o.', title_sv = 'Monsterjakt! 👾', body_sv = 'Letar barnet efter monster under sängen? Fantasirädslorna ökar. Sätt på fläktljudet i Vitt brus för att skapa en trygg och monoton miljö i rummet och lugna barnet.', title_vi = 'Săn quái vật! 👾', body_vi = 'Bé tìm quái vật dưới gầm giường? Những nỗi sợ tưởng tượng đang tăng lên. Hãy bật tiếng quạt trong Tiếng ồn trắng để tạo không gian an toàn, đều đều và giúp bé bình tĩnh.', title_zh = '抓怪兽！👾', body_zh = '在床底下找怪兽？想象出来的恐惧在增加。打开白噪音里的风扇声，在房间里营造安全、单调的氛围，让宝宝平静下来。' WHERE id = 'ee2ef852-cac1-4c22-a029-d59cd40dbe5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Plan de fuga de la cama 🛌', body_es = '¿Intenta trepar para salir de la cuna? Se acerca el momento de pasar a una cama de niño grande. Vuelve a revisar la seguridad de la habitación a ras de suelo.', title_fr = 'Plan d''évasion du lit 🛌', body_fr = 'Il essaie d''escalader son lit à barreaux ? Le passage au grand lit approche. Revérifiez la sécurité de la chambre au ras du sol.', title_hi = 'बिस्तर से भागने का प्लान 🛌', body_hi = 'पालने से चढ़कर बाहर निकलने की कोशिश करता है? बड़े बच्चों वाले बिस्तर पर जाने का समय करीब है। फ़र्श के स्तर से कमरे की सुरक्षा फिर से जाँचिए।', title_id = 'Rencana kabur dari kasur 🛌', body_id = 'Ia mencoba memanjat keluar dari boks bayi? Waktunya pindah ke kasur anak besar sudah dekat. Periksa ulang keamanan kamar dari ketinggian lantai.', title_ja = 'ベッド脱出計画 🛌', body_ja = 'ベビーベッドからよじ登って出ようとしていますか？大きい子用ベッドへの移行が近づいています。床の高さから部屋の安全をもう一度確認しましょう。', title_ko = '침대 탈출 작전 🛌', body_ko = '아기 침대를 기어 넘으려 하나요? 큰 아이 침대로 바꿀 때가 다가오고 있어요. 바닥 높이에서 방의 안전을 다시 확인해 주세요.', title_nl = 'Ontsnappingsplan uit bed 🛌', body_nl = 'Probeert hij uit zijn ledikantje te klimmen? Het moment voor een groot bed komt eraan. Controleer de veiligheid van de kamer opnieuw vanaf vloerhoogte.', title_pl = 'Plan ucieczki z łóżeczka 🛌', body_pl = 'Próbuje wydostać się z łóżeczka? Zbliża się czas przejścia do dużego łóżka. Jeszcze raz sprawdź bezpieczeństwo pokoju z poziomu podłogi.', title_pt = 'Plano de fuga da cama 🛌', body_pt = 'Tenta trepar para fora do berço? Aproxima-se a altura de passar para uma cama de criança crescida. Volte a verificar a segurança do quarto ao nível do chão.', title_sv = 'Flyktplan från sängen 🛌', body_sv = 'Försöker barnet klättra ur spjälsängen? Det närmar sig dags att byta till en större barnsäng. Kontrollera säkerheten i rummet igen från golvnivå.', title_vi = 'Kế hoạch trốn khỏi giường 🛌', body_vi = 'Bé cố trèo ra khỏi cũi? Sắp đến lúc chuyển sang giường lớn. Hãy kiểm tra lại độ an toàn của căn phòng từ tầm thấp sát sàn.', title_zh = '逃离小床计划 🛌', body_zh = '想从婴儿床里爬出来？换大床的时候快到了。蹲到地面的高度，重新检查一遍房间的安全。' WHERE id = '3389c70e-b510-475b-87c1-4f01743277cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un respiro para mamá ☕', body_es = 'Mientras juega solo, no corras a hacer tareas de casa. El desorden no se va a escapar, pero tu energía sí puede agotarse. Siéntate y tómate tu café caliente.', title_fr = 'Une pause pour maman ☕', body_fr = 'Quand il joue tout seul, ne foncez pas tout de suite vers les tâches ménagères. Le désordre ne va pas s''envoler, mais votre énergie peut s''épuiser. Asseyez-vous et buvez votre café chaud.', title_hi = 'माँ के लिए ब्रेक ☕', body_hi = 'बच्चा अपने आप खेल रहा है तो तुरंत घर के काम में मत भागिए। कमरे की बिखरी चीज़ें कहीं नहीं जाएँगी, लेकिन आपकी ऊर्जा खत्म हो सकती है। बैठिए और अपनी गर्म कॉफ़ी पीजिए।', title_id = 'Rehat untuk Ibu ☕', body_id = 'Saat anak bermain sendiri, jangan langsung lari ke pekerjaan rumah. Kamar yang berantakan tidak akan ke mana-mana, tetapi energi Anda bisa habis. Duduklah dan minum kopi hangat Anda.', title_ja = 'ママのひと休み ☕', body_ja = 'お子さんがひとりで遊んでいるとき、すぐに家事に走らないで。散らかった部屋は逃げませんが、あなたのエネルギーは尽きてしまいます。座って温かいコーヒーを飲みましょう。', title_ko = '엄마의 쉬는 시간 ☕', body_ko = '아이가 혼자 놀 때 바로 집안일로 달려가지 마세요. 어질러진 방은 어디 가지 않지만 엄마의 기운은 바닥날 수 있어요. 앉아서 따뜻한 커피를 드세요.', title_nl = 'Pauze voor mama ☕', body_nl = 'Ren niet meteen naar het huishouden als hij zelf speelt. De rommel loopt niet weg, maar jouw energie kan wel op raken. Ga zitten en drink je koffie warm.', title_pl = 'Przerwa dla mamy ☕', body_pl = 'Gdy dziecko bawi się samo, nie biegnij od razu do obowiązków. Bałagan nie ucieknie, ale twoja energia może się skończyć. Usiądź i wypij ciepłą kawę.', title_pt = 'Pausa para a mãe ☕', body_pt = 'Quando a criança brinca sozinha, não corra logo para as tarefas de casa. A desarrumação não foge, mas a sua energia pode acabar. Sente-se e beba o seu café quente.', title_sv = 'Paus för mamma ☕', body_sv = 'Rusa inte iväg till hushållet så fort barnet leker själv. Stöket i rummet springer ingenstans, men din energi kan ta slut. Sätt dig och drick ditt varma kaffe.', title_vi = 'Mẹ nghỉ một chút ☕', body_vi = 'Khi bé tự chơi, đừng vội lao vào việc nhà. Căn phòng bừa bộn không chạy đi đâu được, nhưng năng lượng của mẹ thì có thể cạn. Hãy ngồi xuống và uống tách cà phê nóng.', title_zh = '妈妈的休息时间 ☕', body_zh = '孩子自己玩的时候，别急着去做家务。房间乱了跑不掉，可你的精力却会耗尽。坐下来，喝杯热咖啡吧。' WHERE id = '92afc025-d2fe-4c60-9ebd-9366e19b0175' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En plena etapa del «¿Por qué?» 🤔', body_es = '«¿Por qué está ahí?», «¿Por qué duermo?»... ¡Su cerebro es como una esponja! Responde a sus preguntas sin fin con respuestas cortas pero lógicas. Está descubriendo el mundo con tus palabras.', title_fr = 'Le pic de la phase des « Pourquoi ? » 🤔', body_fr = '« Pourquoi il est là ? », « Pourquoi je dors ? »... Son cerveau est une éponge ! Répondez à ses questions sans fin de façon courte mais logique. Il découvre le monde à travers vos mots.', title_hi = '''क्यों?'' वाले दौर का चरम 🤔', body_hi = '''वह वहाँ क्यों है?'', ''मैं क्यों सोऊँ?''... उसका दिमाग स्पंज जैसा है! उसके इन कभी न खत्म होने वाले सवालों के छोटे लेकिन तर्कसंगत जवाब दीजिए। वह आपकी भाषा से दुनिया को खोज रहा है।', title_id = 'Puncak masa ''Kenapa?'' 🤔', body_id = '''Kenapa itu di sana?'', ''Kenapa aku tidur?''... Otaknya seperti spons! Berikan jawaban singkat tapi logis untuk pertanyaannya yang tak ada habisnya. Ia menjelajahi dunia lewat bahasa Anda.', title_ja = '「なんで？」期の真っ最中 🤔', body_ja = '「あれはなんでそこにあるの？」「なんで寝るの？」…脳はスポンジのよう！終わらない質問に、短くても筋の通った答えを返しましょう。お子さんはあなたの言葉で世界を発見しています。', title_ko = '''왜?'' 시기의 절정 🤔', body_ko = '''저건 왜 저기 있어?'', ''나는 왜 자?''... 머리가 스펀지 같아요! 끝없는 질문에 짧지만 논리적으로 대답해 주세요. 아이는 엄마의 말로 세상을 알아가고 있어요.', title_nl = 'Hoogtepunt van de ''Waarom?''-fase 🤔', body_nl = '''Waarom staat dat daar?'', ''Waarom moet ik slapen?''... Zijn hoofdje is een spons! Geef korte maar logische antwoorden op zijn eindeloze vragen. Hij ontdekt de wereld via jouw woorden.', title_pl = 'Szczyt etapu „Dlaczego?” 🤔', body_pl = '„Dlaczego on tam jest?”, „Dlaczego mam spać?”... Jego mózg jest jak gąbka! Odpowiadaj na te niekończące się pytania krótko, ale logicznie. Odkrywa świat twoimi słowami.', title_pt = 'O auge da fase dos "Porquê?" 🤔', body_pt = '"Porque é que aquilo está ali?", "Porque é que vou dormir?"... O cérebro dele é uma esponja! Dê respostas curtas mas lógicas a estas perguntas sem fim. Está a descobrir o mundo pelas suas palavras.', title_sv = 'Varför-periodens topp 🤔', body_sv = '”Varför är den där?”, ”Varför ska jag sova?”... Hjärnan är som en svamp! Ge korta men logiska svar på de ändlösa frågorna. Barnet upptäcker världen genom ditt språk.', title_vi = 'Đỉnh điểm của giai đoạn "Tại sao?" 🤔', body_vi = '"Sao nó ở đó?", "Sao con phải ngủ?"... Não bé như một miếng bọt biển! Hãy trả lời những câu hỏi bất tận này ngắn gọn nhưng hợp lý. Bé đang khám phá thế giới qua lời của mẹ.', title_zh = '“为什么？”阶段的高峰 🤔', body_zh = '“它为什么在那儿？”“我为什么要睡觉？”……宝宝的大脑就像海绵！对这些问不完的问题，给出简短但有逻辑的回答。宝宝正在用你的语言探索世界。' WHERE id = 'c522fcae-04de-4086-b6e1-764904ead448' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Socializar en el parque 🌳', body_es = '¿Más que jugar con otros niños, juega a lo suyo a su lado? El juego paralelo es totalmente normal a esta edad. Consulta Tiempo y ropa y llévale a menudo a sitios con niños de su edad.', title_fr = 'Rencontres au parc 🌳', body_fr = 'Il joue à côté des autres enfants plutôt qu''avec eux ? Le jeu parallèle est tout à fait naturel à cet âge. Consultez Météo et tenue et emmenez-le souvent là où il y a des enfants de son âge.', title_hi = 'पार्क में मेलजोल 🌳', body_hi = 'दूसरे बच्चों के साथ खेलने से ज़्यादा उनके पास अपना खेल खेलता है? इस उम्र में पैरेलल प्ले बिल्कुल स्वाभाविक है। मौसम और कपड़े टूल देखकर उसे अक्सर हमउम्र बच्चों के बीच ले जाइए।', title_id = 'Bergaul di taman 🌳', body_id = 'Ia lebih sering memainkan permainannya sendiri di dekat anak lain daripada bermain bersama mereka? Bermain paralel sangat wajar di usia ini. Perhatikan cuaca dan pakaiannya, lalu sering-seringlah ajak ia ke tempat dengan teman sebaya.', title_ja = '公園でのふれあい 🌳', body_ja = 'ほかの子と一緒に遊ぶより、そばで自分の遊びをしていますか？「平行遊び」はこの年齢ではまったく自然なことです。「天気と服装」を確認して、同じ年ごろの子がいる場所へよく連れていきましょう。', title_ko = '공원에서의 어울림 🌳', body_ko = '다른 아이들과 함께 놀기보다 옆에서 자기 놀이를 하나요? 이 나이엔 평행 놀이가 아주 자연스러워요. 날씨와 옷차림을 확인하고 또래가 있는 곳에 자주 데려가 주세요.', title_nl = 'Contact in het park 🌳', body_nl = 'Speelt hij liever zijn eigen spel naast andere kinderen dan met hen? Parallel spel is op deze leeftijd heel normaal. Let op het weer en zijn kleding en neem hem vaak mee naar plekken met leeftijdsgenootjes.', title_pl = 'Kontakty w parku 🌳', body_pl = 'Zamiast bawić się z innymi dziećmi, bawi się obok nich po swojemu? Zabawa równoległa jest w tym wieku zupełnie naturalna. Sprawdź Pogodę i ubiór i często wychodź z nim tam, gdzie są rówieśnicy.', title_pt = 'Convívio no parque 🌳', body_pt = 'Brinca ao lado das outras crianças, mais do que com elas? O jogo paralelo é perfeitamente natural nesta idade. Veja o Tempo e Roupa e leve-o muitas vezes para perto de crianças da idade dele.', title_sv = 'Umgänge i parken 🌳', body_sv = 'Leker barnet hellre sin egen lek bredvid andra barn än tillsammans med dem? Parallellek är helt naturligt i den här åldern. Ta ofta med barnet till jämnåriga, klätt efter vädret.', title_vi = 'Giao tiếp ở công viên 🌳', body_vi = 'Bé chơi trò của riêng mình bên cạnh các bạn hơn là chơi cùng? Chơi song song hoàn toàn tự nhiên ở tuổi này. Hãy xem thời tiết và trang phục rồi thường xuyên đưa bé ra nơi có các bạn cùng tuổi.', title_zh = '公园社交 🌳', body_zh = '比起和其他孩子一起玩，更喜欢在他们旁边玩自己的？平行游戏在这个年龄完全正常。根据天气穿好衣服，常带宝宝去有同龄人的地方。' WHERE id = '3a442f56-c411-4f3c-a16a-32453afe5f33' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amigos imaginarios 🧸', body_es = '¿Le cuenta cuentos a su osito o bebe té de un vaso vacío? El juego simbólico es una obra maestra del desarrollo. Anota con orgullo este salto cognitivo en el Seguimiento del desarrollo.', title_fr = 'Amis imaginaires 🧸', body_fr = 'Il raconte une histoire à son nounours ou boit du thé dans une tasse vide ? Le jeu symbolique est un chef-d''œuvre du développement. Notez fièrement ce bond cognitif dans le Suivi de développement.', title_hi = 'काल्पनिक दोस्त 🧸', body_hi = 'टेडी बियर को कहानी सुनाता है या खाली कप से चाय पीता है? प्रतीकात्मक खेल विकास का बेहतरीन नमूना है। इस संज्ञानात्मक छलांग को गर्व से ग्रोथ ट्रैकर में दर्ज कीजिए।', title_id = 'Teman khayalan 🧸', body_id = 'Ia mendongeng untuk boneka beruangnya atau minum teh dari cangkir kosong? Permainan simbolis adalah karya agung perkembangan. Catat lompatan kognitif ini dengan bangga di Pelacak Perkembangan.', title_ja = '空想のお友だち 🧸', body_ja = 'くまのぬいぐるみにお話をしたり、からっぽのコップでお茶を飲んだりしていますか？ごっこ遊びは発達の傑作です。この認知の飛躍を「発達トラッカー」に誇らしく記録しましょう。', title_ko = '상상 속 친구 🧸', body_ko = '곰 인형에게 이야기를 들려주거나 빈 컵으로 차를 마시나요? 상징 놀이는 발달의 걸작이에요. 성장 기록에 이 인지 발달의 도약을 뿌듯하게 남겨 두세요.', title_nl = 'Denkbeeldige vriendjes 🧸', body_nl = 'Vertelt hij zijn knuffelbeer een verhaaltje of drinkt hij thee uit een leeg kopje? Symbolisch spel is een meesterwerk van de ontwikkeling. Noteer deze cognitieve sprong trots in de Groeitracker.', title_pl = 'Wyimaginowani przyjaciele 🧸', body_pl = 'Opowiada misiowi bajki albo pije herbatę z pustego kubeczka? Zabawa symboliczna to arcydzieło rozwoju. Z dumą zapisz ten skok poznawczy w Śledzeniu rozwoju.', title_pt = 'Amigos imaginários 🧸', body_pt = 'Conta histórias ao ursinho ou bebe chá de uma chávena vazia? O jogo simbólico é uma obra-prima do desenvolvimento. Registe com orgulho este salto cognitivo no Registo de Desenvolvimento.', title_sv = 'Låtsaskompisar 🧸', body_sv = 'Berättar barnet sagor för nallen eller dricker te ur en tom kopp? Symbolisk lek är utvecklingens mästerverk. Anteckna stolt det här kognitiva språnget i Utvecklingsspåraren.', title_vi = 'Những người bạn tưởng tượng 🧸', body_vi = 'Bé kể chuyện cho gấu bông hay uống trà từ chiếc cốc rỗng? Trò chơi biểu tượng là kiệt tác của sự phát triển. Hãy tự hào ghi lại bước nhảy vọt nhận thức này trong Theo dõi phát triển.', title_zh = '想象中的朋友 🧸', body_zh = '给玩具熊讲故事，或者用空杯子“喝茶”？象征性游戏是发育的杰作。骄傲地把这次认知飞跃记在发育追踪里吧。' WHERE id = '5d66b2e6-45ec-4c26-ae59-9d0d0eba4b4d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba los decibelios con el Medidor de sonido y ajusta el volumen de la tele de la habitación de al lado.', body_fr = 'La première demi-heure de sommeil est la plus fragile. Vérifiez le niveau de décibels avec le Sonomètre et réglez le volume de la télé dans la pièce d''à côté.', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक होता है। साउंड मीटर से माहौल का डेसिबल जाँचिए और बगल के कमरे में टीवी की आवाज़ उसी हिसाब से रखिए।', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Periksa desibel ruangan dengan Pengukur Suara dan sesuaikan volume TV di kamar sebelah.', body_ja = '寝ついてから最初の30分がいちばん眠りが浅い時間です。「サウンドメーター」で周りのデシベルを確かめ、となりの部屋のテレビの音量を調整しましょう。', body_ko = '잠든 후 첫 30분이 가장 예민한 시간이에요. 소음 측정기로 데시벨을 확인하고 옆방 TV 소리를 맞춰 조절하세요.', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Meet het decibelniveau met de Geluidsmeter en stem het volume van de tv in de kamer ernaast daarop af.', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź Miernikiem dźwięku poziom decybeli i dostosuj głośność telewizora w sąsiednim pokoju.', body_pt = 'A primeira meia hora depois de adormecer é o momento mais sensível. Verifique os decibéis com o Medidor de Som e ajuste o volume da televisão no quarto ao lado.', body_sv = 'Den första halvtimmen efter insomnandet är den känsligaste tiden. Kontrollera ljudnivån i decibel med Ljudmätaren och anpassa ljudet från tv:n i rummet bredvid.', body_vi = 'Nửa giờ đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra decibel bằng Đo âm thanh và điều chỉnh tiếng TV ở phòng bên cạnh.', body_zh = '入睡后的头半小时最敏感。用分贝仪检查环境分贝，把隔壁房间电视的音量调到合适。' WHERE id = 'd4544a8c-8615-4a88-b7e6-c7dc2d3b805a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Lo quiere todo para él? 🛑', body_es = 'Aún no tiene formado el concepto de compartir. No le obligues; en su lugar, introduce poco a poco la regla de «Jugamos por turnos».', title_fr = 'Il veut tout garder pour lui ? 🛑', body_fr = 'La notion de partage n''est pas encore acquise. Ne le forcez pas, introduisez plutôt peu à peu la règle « On joue chacun son tour ».', title_hi = 'हर चीज़ अपनी बनाना चाहता है? 🛑', body_hi = 'बाँटने की समझ अभी बनी नहीं है। उस पर ज़बरदस्ती मत कीजिए, बल्कि धीरे-धीरे ''बारी-बारी से खेलें'' का नियम सिखाइए।', title_id = 'Ingin memiliki semuanya? 🛑', body_id = 'Konsep berbagi belum terbentuk. Jangan memaksanya, sebaliknya terapkan aturan ''Ayo main bergiliran'' secara bertahap.', title_ja = 'なんでも自分のものにしたい？🛑', body_ja = '「分け合うこと」の考え方はまだ育っていません。無理強いせず、かわりに「順番に遊ぼうね」のルールを少しずつ取り入れましょう。', title_ko = '뭐든 내 거라고요? 🛑', body_ko = '나눔이라는 개념은 아직 자리 잡지 않았어요. 억지로 시키지 말고 ''차례대로 놀자'' 규칙을 조금씩 알려 주세요.', title_nl = 'Wil hij alles hebben? 🛑', body_nl = 'Het idee van delen is nog niet gevormd. Dwing hem niet, maar introduceer stap voor stap de regel ''We spelen om de beurt''.', title_pl = 'Chce mieć wszystko na własność? 🛑', body_pl = 'Pojęcie dzielenia się jeszcze się nie ukształtowało. Nie zmuszaj go, zamiast tego stopniowo wprowadzaj zasadę „bawimy się po kolei”.', title_pt = 'Quer tudo só para si? 🛑', body_pt = 'O conceito de partilhar ainda não está formado. Não o force; em vez disso, introduza aos poucos a regra "vamos brincar à vez".', title_sv = 'Vill barnet ha allt för sig själv? 🛑', body_sv = 'Begreppet att dela har ännu inte formats. Tvinga inte barnet, inför i stället gradvis regeln ”Vi turas om”.', title_vi = 'Bé muốn giữ hết mọi thứ? 🛑', body_vi = 'Khái niệm chia sẻ chưa hình thành ở bé. Đừng ép bé, thay vào đó hãy dần áp dụng quy tắc "Mình chơi lần lượt nhé".', title_zh = '什么都想占为己有？🛑', body_zh = '“分享”的概念还没有形成。别勉强宝宝，而是慢慢引入“我们轮流玩”的规则。' WHERE id = '32813c49-da9b-4dca-8d61-b20de94b9fae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño ingeniero 🏗️', body_es = '¿Le encanta construir torres y derribarlas? Descubre ya en Productos recomendados bloques magnéticos o de madera que reforzarán aún más su inteligencia y su motricidad.', title_fr = 'Petit ingénieur 🏗️', body_fr = 'Il adore construire des tours et les faire tomber ? Découvrez vite dans les Produits recommandés des blocs magnétiques ou en bois qui renforceront encore son intelligence et sa motricité.', title_hi = 'नन्हा इंजीनियर 🏗️', body_hi = 'टावर बनाना और गिराना बहुत पसंद है? उसकी बुद्धि और मोटर स्किल्स को और मज़बूत करने वाले मैग्नेटिक या लकड़ी के ब्लॉक्स अभी सुझाए गए प्रोडक्ट में देखिए।', title_id = 'Insinyur kecil 🏗️', body_id = 'Suka sekali membangun lalu merobohkan menara? Temukan segera balok magnet atau kayu di Produk Rekomendasi yang akan makin memperkuat kecerdasan dan motoriknya.', title_ja = '小さなエンジニア 🏗️', body_ja = '塔を作っては崩すのが大好き？知性と運動能力をさらに伸ばすマグネットブロックや木のブロックを、さっそく「おすすめ商品」で見つけましょう。', title_ko = '꼬마 엔지니어 🏗️', body_ko = '탑을 쌓고 무너뜨리는 걸 좋아하나요? 지능과 운동 능력을 더 키워 줄 자석 블록이나 원목 블록을 추천 제품에서 바로 찾아보세요.', title_nl = 'Kleine ingenieur 🏗️', body_nl = 'Is hij dol op torens bouwen en omgooien? Ontdek in Aanbevolen producten magnetische of houten blokken die zijn verstand en motoriek nog meer versterken.', title_pl = 'Mały inżynier 🏗️', body_pl = 'Uwielbia budować wieże i je burzyć? Od razu odkryj w Polecanych produktach magnetyczne lub drewniane klocki, które jeszcze bardziej wzmocnią jego intelekt i motorykę.', title_pt = 'Pequeno engenheiro 🏗️', body_pt = 'Adora construir torres e deitá-las abaixo? Descubra já nos Produtos Recomendados blocos magnéticos ou de madeira que vão reforçar ainda mais a inteligência e a motricidade dele.', title_sv = 'Liten ingenjör 🏗️', body_sv = 'Älskar barnet att bygga torn och riva dem? Upptäck direkt magnetiska eller träklossar i Rekommenderade produkter som stärker intelligensen och motoriken ännu mer.', title_vi = 'Kỹ sư nhí 🏗️', body_vi = 'Bé mê xây tháp rồi phá đổ? Hãy khám phá ngay các bộ khối nam châm hoặc khối gỗ giúp bé thêm thông minh và khéo tay trong Sản phẩm gợi ý.', title_zh = '小小工程师 🏗️', body_zh = '特别爱搭塔再推倒？马上去推荐商品看看磁力积木或木头积木，让宝宝的智力和动作能力更上一层楼。' WHERE id = '493d7552-4aa4-42f1-ab76-65529b782f6d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Respira hondo 🌬️', body_es = '¿Hoy te has quedado sin fuerzas de tanto correr detrás de tu peque? Abre el Diario de ánimo y escribe tu cansancio. No intentes ser una madre perfecta, ¡lo que sientes también importa!', title_fr = 'Respirez profondément 🌬️', body_fr = 'Vous êtes à bout de forces à force de courir après lui aujourd''hui ? Ouvrez le Journal d''humeur et écrivez votre fatigue. N''essayez pas d''être une mère parfaite, vos émotions comptent aussi !', title_hi = 'गहरी साँस लीजिए 🌬️', body_hi = 'आज उसके पीछे भागते-भागते थक कर चूर हो गईं? मूड डायरी खोलिए और अपनी थकान लिखिए। परफ़ेक्ट माँ बनने की कोशिश मत कीजिए, आपकी भावनाएँ भी मायने रखती हैं!', title_id = 'Tarik napas dalam 🌬️', body_id = 'Hari ini Anda kehabisan tenaga mengejarnya ke sana kemari? Buka Buku Harian Suasana Hati dan tuliskan lelah Anda. Jangan berusaha menjadi ibu sempurna, perasaan Anda juga penting!', title_ja = '深呼吸しましょう 🌬️', body_ja = '今日はお子さんを追いかけて、くたくたになりましたか？「気分日記」を開いて、疲れを書き出しましょう。完璧なママを目指さないで、あなたの気持ちも大切です！', title_ko = '깊게 숨 쉬세요 🌬️', body_ko = '오늘 아이를 쫓아다니느라 기진맥진했나요? 기분 일기를 열고 피곤함을 적어 보세요. 완벽한 엄마가 되려 하지 마세요. 엄마의 감정도 소중해요!', title_nl = 'Haal diep adem 🌬️', body_nl = 'Ben je vandaag uitgeput van het achter hem aan rennen? Open je Stemmingsdagboek en schrijf je vermoeidheid op. Probeer geen perfecte moeder te zijn, jouw gevoelens tellen ook!', title_pl = 'Weź głęboki oddech 🌬️', body_pl = 'Jesteś dziś wykończona bieganiem za nim? Otwórz Dziennik nastroju i zapisz swoje zmęczenie. Nie próbuj być idealną mamą, twoje uczucia też są ważne!', title_pt = 'Respire fundo 🌬️', body_pt = 'Ficou sem forças de tanto correr atrás dele hoje? Abra o Diário de Humor e escreva o seu cansaço. Não tente ser uma mãe perfeita, os seus sentimentos também importam!', title_sv = 'Andas djupt 🌬️', body_sv = 'Är du helt slut efter att ha sprungit efter barnet hela dagen? Öppna Humördagboken och skriv ner din trötthet. Försök inte vara en perfekt mamma, dina känslor är också viktiga!', title_vi = 'Hít thở thật sâu 🌬️', body_vi = 'Hôm nay mẹ đuối sức vì chạy theo bé? Hãy mở Nhật ký tâm trạng và viết ra sự mệt mỏi. Đừng cố làm người mẹ hoàn hảo, cảm xúc của mẹ cũng quan trọng!', title_zh = '深呼吸 🌬️', body_zh = '今天追着宝宝跑，累得筋疲力尽？打开心情日记，写下你的疲惫。别想着做完美妈妈，你的感受也很重要！' WHERE id = '96969038-76a5-48c3-b60c-aafe8839c46c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Ha sido un día difícil?', body_es = 'Desahógate escribiendo el estrés de hoy en el Diario de ánimo. Todas las madres pasan por estas crisis, no estás sola.', title_fr = 'Journée difficile ?', body_fr = 'Videz-vous la tête en écrivant le stress du jour dans le Journal d''humeur. Toutes les mamans traversent ces crises, vous n''êtes pas seule.', title_hi = 'मुश्किल दिन था?', body_hi = 'आज का तनाव मूड डायरी में लिखकर मन हल्का कीजिए। हर माँ ऐसे मुश्किल पलों से गुज़रती है, आप अकेली नहीं हैं।', title_id = 'Hari yang berat?', body_id = 'Lepaskan beban dengan menulis stres hari ini di Buku Harian Suasana Hati. Semua ibu mengalami krisis seperti ini, Anda tidak sendirian.', title_ja = '大変な一日でしたか？', body_ja = '今日のストレスを「気分日記」に書いて、心を軽くしましょう。どのママもこうした大変な時期を経験しています。あなたはひとりではありません。', title_ko = '힘든 하루였나요?', body_ko = '기분 일기에 오늘의 스트레스를 적으며 마음을 비워 보세요. 모든 엄마가 이런 고비를 겪어요. 혼자가 아니에요.', title_nl = 'Was het een zware dag?', body_nl = 'Lucht je hart door de stress van vandaag in je Stemmingsdagboek te schrijven. Alle moeders maken deze crises mee, je bent niet alleen.', title_pl = 'Trudny dzień?', body_pl = 'Zapisz dzisiejszy stres w Dzienniku nastroju i wyrzuć to z siebie. Wszystkie mamy przechodzą przez takie kryzysy, nie jesteś sama.', title_pt = 'Foi um dia difícil?', body_pt = 'Escreva o stress de hoje no Diário de Humor e desabafe. Todas as mães passam por estas crises, não está sozinha.', title_sv = 'Har det varit en tuff dag?', body_sv = 'Skriv av dig dagens stress i Humördagboken. Alla mammor går igenom de här kriserna, du är inte ensam.', title_vi = 'Hôm nay vất vả quá?', body_vi = 'Hãy viết những căng thẳng hôm nay vào Nhật ký tâm trạng cho nhẹ lòng. Người mẹ nào cũng trải qua những cơn khủng hoảng này, mẹ không đơn độc đâu.', title_zh = '今天很难熬？', body_zh = '把今天的压力写进心情日记，把心里清空。每个妈妈都经历过这些崩溃时刻，你并不孤单。' WHERE id = '3cbc904d-0d48-46fa-a264-4d48559d6b46' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Haces de todo para que coma. ¿Y tú? Elige en Recetas saludables una comida rica en hierro que te dé fuerza, siéntate y come con calma.', body_fr = 'Vous faites tout pour qu''il mange bien. Et vous ? Choisissez dans les Recettes saines un déjeuner riche en fer qui vous donnera de la force, et mangez assise, au calme.', body_hi = 'उसका पेट भरने के लिए आप सब कुछ करती हैं। और आप? सेहतमंद रेसिपी से आपको ताकत देने वाला आयरन से भरपूर लंच चुनिए और आराम से बैठकर खाइए।', body_id = 'Anda melakukan segalanya agar ia kenyang. Bagaimana dengan Anda? Pilih makan siang kaya zat besi dari Resep Sehat yang memberi Anda tenaga, lalu duduk dan makanlah dengan tenang.', body_ja = 'お子さんのためにはなんでもするのに、あなた自身は？「ヘルシーレシピ」から元気をくれる鉄分たっぷりのランチを選んで、ゆっくり座って食べましょう。', body_ko = '아이를 배불리 먹이려고 뭐든 하죠. 그럼 엄마는요? 건강한 레시피에서 힘이 되는 철분 가득한 점심을 골라 편히 앉아 드세요.', body_nl = 'Je doet alles om hem te laten eten. Maar jij dan? Kies uit Gezonde recepten een ijzerrijke lunch die je kracht geeft, en ga er rustig voor zitten.', body_pl = 'Robisz wszystko, żeby go nakarmić. A ty? Wybierz ze Zdrowych przepisów obiad bogaty w żelazo, który doda ci sił, usiądź spokojnie i zjedz.', body_pt = 'Faz tudo para que ele coma bem. E a mãe? Escolha nas Receitas Saudáveis um almoço rico em ferro que lhe dê força, sente-se com calma e coma.', body_sv = 'Du gör allt för att barnet ska bli mätt. Men du då? Välj en järnrik lunch som ger dig kraft från Hälsosamma recept, sätt dig ner och ät i lugn och ro.', body_vi = 'Mẹ làm mọi thứ để bé được no. Còn mẹ thì sao? Hãy chọn một bữa trưa giàu sắt trong Công thức lành mạnh để nạp năng lượng, rồi ngồi xuống thong thả ăn nhé.', body_zh = '为了让宝宝吃饱，你什么都做了。那你自己呢？从健康食谱里选一份能给你力量、富含铁的午餐，安安静静坐下来吃吧。' WHERE id = 'aabf621d-766b-4fe7-b19d-2316986fdc64' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Frases de dos palabras 🗣️', body_es = '«Mamá ven», «Tira pelota»: su vocabulario crece día a día. Apoya su lenguaje repitiendo con la pronunciación correcta las palabras que dice a medias.', title_fr = 'Phrases de deux mots 🗣️', body_fr = '« Maman viens », « Lance ballon » : son vocabulaire s''enrichit de jour en jour. Soutenez son langage en répétant ses mots inachevés avec la bonne prononciation.', title_hi = 'दो शब्दों वाले वाक्य 🗣️', body_hi = '''माँ आओ'', ''बॉल फेंको'' - उसकी शब्दावली दिन-ब-दिन बढ़ रही है। उसके अधूरे शब्दों को सही उच्चारण के साथ दोहराकर उसकी बोली को सहारा दीजिए।', title_id = 'Kalimat dua kata 🗣️', body_id = '''Mama sini'', ''Lempar bola'' - kosakatanya makin kaya dari hari ke hari. Dukung kemampuan bicaranya dengan mengulang kata-katanya yang belum lengkap dengan pelafalan yang benar.', title_ja = '2語の文 🗣️', body_ja = '「ママきて」「ボールなげて」語彙は日に日に豊かになっています。言いかけの言葉を正しい発音でくり返して、言葉の発達をサポートしましょう。', title_ko = '두 단어 문장 🗣️', body_ko = '''엄마 와'', ''공 던져'', 어휘가 나날이 늘고 있어요. 아이가 말한 덜 완성된 단어를 정확한 발음으로 다시 들려주며 말하기를 도와주세요.', title_nl = 'Zinnetjes van twee woorden 🗣️', body_nl = '''Mama kom'', ''Bal gooi'': zijn woordenschat groeit met de dag. Steun zijn spraak door zijn halve woordjes met de juiste uitspraak te herhalen.', title_pl = 'Zdania z dwóch słów 🗣️', body_pl = '„Mama chodź”, „Rzuć piłkę”: jego słownictwo bogaci się z dnia na dzień. Wspieraj mowę, powtarzając jego niedokończone słowa z poprawną wymową.', title_pt = 'Frases de duas palavras 🗣️', body_pt = '"Mamã vem", "Atira bola": o vocabulário cresce de dia para dia. Apoie a fala dele repetindo as palavras incompletas com a pronúncia certa.', title_sv = 'Meningar med två ord 🗣️', body_sv = '”Mamma kom”, ”Kasta bollen”: ordförrådet växer dag för dag. Stöd talet genom att upprepa barnets halva ord med rätt uttal.', title_vi = 'Câu hai từ 🗣️', body_vi = '"Mẹ ơi lại đây", "Ném bóng": vốn từ của bé phong phú lên từng ngày. Hãy hỗ trợ khả năng nói bằng cách lặp lại những từ bé nói chưa tròn với cách phát âm đúng.', title_zh = '两个词的句子 🗣️', body_zh = '“妈妈来”“扔球球”，词汇量一天比一天丰富。把宝宝说得不完整的词用正确的发音重复一遍，支持宝宝的语言发展。' WHERE id = 'c60bf17d-5d16-4967-881d-d808bb5c5b6e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se ha tirado al suelo en la tienda porque no le compraste lo que quería? Ignora las miradas de los demás. Agáchate a la altura de sus ojos y dile que entiendes cómo se siente.', body_fr = 'Il s''est jeté par terre parce que vous n''avez pas acheté ce qu''il voulait au magasin ? Ignorez les regards. Baissez-vous à sa hauteur et dites-lui que vous comprenez ce qu''il ressent.', body_hi = 'दुकान में मनचाही चीज़ नहीं मिली तो ज़मीन पर लोट गया? आसपास के लोगों की नज़रों की परवाह मत कीजिए। उसकी आँखों के स्तर तक झुकिए और बताइए कि आप उसकी भावनाएँ समझती हैं।', body_id = 'Ia menjatuhkan diri ke lantai karena Anda tidak membelikan yang ia mau di toko? Abaikan tatapan orang lain. Berjongkoklah setinggi matanya dan katakan bahwa Anda memahami perasaannya.', body_ja = 'お店でほしいものを買ってもらえず、床にひっくり返りましたか？周りの視線は気にしないで。目の高さまでかがんで、気持ちをわかっているよと伝えましょう。', body_ko = '가게에서 원하는 걸 안 사 줬다고 바닥에 드러누웠나요? 주변 시선은 신경 쓰지 마세요. 눈높이로 몸을 낮추고 마음을 이해한다고 말해 주세요.', body_nl = 'Gooide hij zich in de winkel op de grond omdat hij niet kreeg wat hij wilde? Negeer de blikken van anderen. Buk tot zijn ooghoogte en zeg dat je zijn gevoelens begrijpt.', body_pl = 'Rzucił się na podłogę w sklepie, bo nie kupiłaś tego, co chciał? Nie zwracaj uwagi na spojrzenia innych. Zniż się do poziomu jego oczu i powiedz, że rozumiesz jego uczucia.', body_pt = 'Atirou-se para o chão na loja porque não lhe comprou o que queria? Ignore os olhares dos outros. Baixe-se ao nível dos olhos dele e diga-lhe que compreende o que sente.', body_sv = 'Kastade sig barnet på golvet för att hen inte fick det hen ville ha i affären? Strunta i andras blickar. Böj dig ner till barnets ögonhöjd och säg att du förstår hens känslor.', body_vi = 'Bé lăn ra sàn vì mẹ không mua thứ bé muốn ở cửa hàng? Đừng bận tâm ánh nhìn của người xung quanh. Hãy cúi xuống ngang tầm mắt bé và nói rằng mẹ hiểu cảm xúc của bé.', body_zh = '在商店没买到想要的东西，就躺在地上闹？别理会旁人的目光。蹲到和宝宝视线一样的高度，告诉宝宝你理解他的感受。' WHERE id = '274e44c7-f2f2-4e14-a2db-692e3ab50d92' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ropa al revés 👗', body_es = '¿Se pone los zapatos cambiados y la camiseta del revés, y no hay manera de que se los quite? ¡Déjalo así! Es su forma más inocente de afirmar su individualidad.', title_fr = 'Vêtements à l''envers 👗', body_fr = 'Il met ses chaussures à l''envers, son t-shirt aussi, et refuse catégoriquement de les enlever ? Laissez faire ! C''est sa façon la plus innocente d''affirmer sa personnalité.', title_hi = 'उल्टे पहने कपड़े 👗', body_hi = 'जूते उल्टे पैर में, शर्ट उल्टी पहनता है और बिल्कुल उतारना नहीं चाहता? रहने दीजिए! यह उसकी अपनी पहचान जताने का सबसे मासूम तरीका है।', title_id = 'Baju yang terbalik 👗', body_id = 'Ia memakai sepatu terbalik, kausnya terbalik, dan sama sekali tidak mau melepasnya? Biarkan saja! Ini cara paling polos baginya untuk menegaskan jati dirinya.', title_ja = 'あべこべの服 👗', body_ja = '靴を左右逆にはいたり、シャツを裏返しに着たりして、絶対に脱ぎたがらない？そのままにしておきましょう！自分らしさを確かめる、いちばん無邪気な方法なのです。', title_ko = '거꾸로 입은 옷 👗', body_ko = '신발을 거꾸로 신고 옷을 뒤집어 입고는 절대 벗지 않겠다고 하나요? 그냥 두세요! 자기만의 개성을 표현하는 가장 순수한 방법이에요.', title_nl = 'Achterstevoren aangekleed 👗', body_nl = 'Trekt hij zijn schoenen verkeerd om en zijn shirt binnenstebuiten aan en wil hij het absoluut niet uitdoen? Laat maar zo! Dit is zijn meest onschuldige manier om zijn eigenheid te laten zien.', title_pl = 'Ubrania na odwrót 👗', body_pl = 'Zakłada buty na odwrót, koszulkę na lewą stronę i za nic nie chce zdjąć? Niech tak zostanie! To najniewinniejszy sposób, by pokazać swoją indywidualność.', title_pt = 'Roupa vestida ao contrário 👗', body_pt = 'Calça os sapatos trocados, veste a camisola do avesso e não quer tirar de maneira nenhuma? Deixe ficar assim! É a forma mais inocente de afirmar a sua individualidade.', title_sv = 'Kläder åt fel håll 👗', body_sv = 'Har barnet skorna på fel fot och tröjan ut och in och vägrar ta av dem? Låt det vara! Det är barnets mest oskyldiga sätt att bekräfta sin individualitet.', title_vi = 'Quần áo mặc ngược 👗', body_vi = 'Bé đi giày ngược chân, mặc áo trái và nhất quyết không chịu cởi ra? Cứ để vậy đi! Đó là cách ngây thơ nhất để bé khẳng định cá tính của mình.', title_zh = '穿反的衣服 👗', body_zh = '鞋子穿反，衣服也穿反，还死活不肯脱？就让它这样吧！这是宝宝确认自我个性最天真的方式。' WHERE id = '7ffa24e8-d5c5-47fa-bd56-46791566e3ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cada nueva habilidad que aprende y cada paso seguro que da son fruto de tu esfuerzo y el de tu pareja.', body_fr = 'Chaque nouvelle compétence qu''il apprend, chaque pas assuré, c''est le fruit de vos efforts, à vous et à votre partenaire.', body_hi = 'रोज़ सीखा गया हर नया हुनर, हर भरोसे भरा कदम आपकी और आपके पार्टनर की मेहनत का नतीजा है।', body_id = 'Setiap keterampilan baru yang ia pelajari, setiap langkah percaya dirinya, adalah hasil kerja keras Anda dan pasangan.', body_ja = '毎日おぼえる新しいスキル、自信に満ちた一歩一歩は、あなたとパートナーの努力の結晶です。', body_ko = '아이가 매일 배우는 새로운 능력, 자신 있게 내딛는 한 걸음 한 걸음은 모두 엄마와 배우자의 노력 덕분이에요.', body_nl = 'Elke nieuwe vaardigheid die hij leert, elke zelfverzekerde stap is het werk van jou en je partner.', body_pl = 'Każda nowa umiejętność, której się uczy, każdy pewny krok to zasługa twoja i twojego partnera.', body_pt = 'Cada nova capacidade que aprende, cada passo confiante, é fruto do seu esforço e do seu companheiro.', body_sv = 'Varje ny färdighet barnet lär sig varje dag, varje säkert steg, är ditt och din partners verk.', body_vi = 'Mỗi kỹ năng mới bé học được hằng ngày, mỗi bước đi tự tin đều là công sức của mẹ và bố.', body_zh = '宝宝每天学会的新本领、迈出的每一个自信的小步子，都是你和伴侣共同付出的成果。' WHERE id = 'c19b60f5-cbba-4300-8903-9c5cb8625ba7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Declaración de independencia 📜', body_es = '¿Lo quiere hacer todo él solo («¡Yo solo!») y todo va más lento? Pregunta ya a Anacan AI cómo convertir esta tozudez sin límites en desarrollo.', title_fr = 'Déclaration d''indépendance 📜', body_fr = 'Il dit « Je le fais tout seul ! » pour tout et ça ralentit tout ? Demandez vite à Anacan AI comment transformer cet entêtement sans limite en progrès.', title_hi = 'आज़ादी का ऐलान 📜', body_hi = 'हर बात पर कहता है ''मैं खुद करूँगा!'' और काम धीमे हो जाते हैं? इस बेहद ज़िद्दी स्वभाव को विकास में बदलने के तरीके अभी Anacan AI से पूछिए।', title_id = 'Deklarasi kemandirian 📜', body_id = 'Ia bilang ''Aku sendiri!'' untuk segala hal dan semuanya jadi lambat? Segera tanyakan pada Anacan AI cara mengubah sifat keras kepala tanpa batas ini menjadi perkembangan.', title_ja = '独立宣言 📜', body_ja = 'なんでも「自分でやる！」と言って、時間がかかってしまう？この限界知らずのがんばりを成長につなげる方法を、すぐにAnacan AIに聞いてみましょう。', title_ko = '독립 선언 📜', body_ko = '뭐든 ''내가 할래!'' 하며 시간이 오래 걸리나요? 끝없는 이 고집을 성장으로 바꾸는 방법을 Anacan AI에게 바로 물어보세요.', title_nl = 'Onafhankelijkheidsverklaring 📜', body_nl = 'Roept hij bij alles ''Zelf doen!'' en duurt alles daardoor langer? Vraag Anacan AI meteen hoe je deze grenzeloze koppigheid in ontwikkeling omzet.', title_pl = 'Deklaracja niepodległości 📜', body_pl = 'Na wszystko mówi „Ja sam!” i wszystko się przeciąga? Od razu zapytaj Anacan AI, jak zamienić ten nieznający granic upór w rozwój.', title_pt = 'Declaração de independência 📜', body_pt = 'Diz "Eu faço sozinho!" a tudo e atrasa as coisas? Pergunte já ao Anacan AI como transformar esta teimosia sem limites em desenvolvimento.', title_sv = 'Självständighetsförklaring 📜', body_sv = 'Säger barnet ”Jag gör själv!” om allt och saktar ner allting? Fråga Anacan AI direkt hur du kan vända den här gränslösa envisheten till utveckling.', title_vi = 'Tuyên ngôn độc lập 📜', body_vi = 'Việc gì bé cũng nói "Con tự làm!" khiến mọi thứ chậm lại? Hãy hỏi ngay Anacan AI cách biến sự bướng bỉnh không giới hạn này thành động lực phát triển.', title_zh = '独立宣言 📜', body_zh = '什么都要“我自己来！”，事情越做越慢？马上问问Anacan AI，怎样把这股不服输的倔强转化为成长。' WHERE id = 'e47a41a7-8601-4ce3-8c27-0c69ab445dad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Pasa las páginas del libro y señala con el dedo el detalle más pequeño del dibujo? Su memoria visual funciona de maravilla. Charla con tu peque sobre lo que ve en los dibujos.', body_fr = 'Il feuillette un livre et montre du doigt le moindre détail des images ? Sa mémoire visuelle fonctionne à merveille. Discutez avec lui de ce que vous voyez sur les images.', body_hi = 'किताब के पन्ने पलटता है और तस्वीर की सबसे छोटी चीज़ भी उँगली से दिखाता है? उसकी दृश्य याददाश्त बढ़िया काम कर रही है। तस्वीरों के बारे में उससे बातचीत कीजिए।', body_id = 'Ia membolak-balik buku dan menunjuk detail terkecil di gambar dengan jarinya? Memori visualnya bekerja dengan baik. Ajak ia bercakap tentang isi gambar.', body_ja = '絵本をめくって、絵のいちばん小さなところまで指さしますか？視覚的な記憶がよく働いています。絵に描かれたものについて一緒におしゃべりしましょう。', body_ko = '책장을 넘기며 그림 속 아주 작은 부분까지 손가락으로 가리키나요? 시각 기억력이 훌륭하게 자라고 있어요. 그림 속 이야기로 함께 대화해 보세요.', body_nl = 'Bladert hij door een boek en wijst hij het kleinste detail op een plaatje aan? Zijn visuele geheugen werkt uitstekend. Praat met hem over wat er op de plaatjes staat.', body_pl = 'Przegląda książeczkę i pokazuje paluszkiem najmniejsze szczegóły na obrazkach? Jego pamięć wzrokowa działa świetnie. Rozmawiaj z nim o tym, co jest na obrazkach.', body_pt = 'Folheia o livro e aponta com o dedo o mais pequeno detalhe da imagem? A memória visual está a funcionar muito bem. Converse com ele sobre o que aparece nas imagens.', body_sv = 'Bläddrar barnet i boken och pekar med fingret på den minsta detaljen i bilden? Det visuella minnet fungerar utmärkt. Prata med barnet om det som finns på bilderna.', body_vi = 'Bé lật sách và chỉ tay vào chi tiết nhỏ nhất trong tranh? Trí nhớ thị giác của bé hoạt động rất tốt. Hãy trò chuyện với bé về những gì có trong tranh.', body_zh = '翻着书，用手指点出图里最小的细节？视觉记忆非常好。和宝宝聊聊图里都有什么吧。' WHERE id = 'e4b29fb1-70d1-4a56-b112-96966513c6eb' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maestro de los garabatos 🖍️', body_es = 'En cuanto coge un lápiz, garabatea las paredes o el papel. Su motricidad fina se desarrolla con los colores.', title_fr = 'Champion du gribouillage 🖍️', body_fr = 'Dès qu''il attrape un crayon, il gribouille les murs ou le papier. Sa motricité fine se développe avec les couleurs.', title_hi = 'आड़ी-तिरछी लकीरों का उस्ताद 🖍️', body_hi = 'हाथ में पेन आते ही दीवारों या कागज़ पर आड़ी-तिरछी लकीरें खींचने लगता है। रंगों के साथ उसकी फ़ाइन मोटर स्किल्स विकसित हो रही हैं।', title_id = 'Jago mencoret-coret 🖍️', body_id = 'Begitu memegang pensil, ia langsung mencoret-coret dinding atau kertas. Motorik halusnya berkembang lewat warna.', title_ja = 'なぐり描き名人 🖍️', body_ja = 'クレヨンを手にしたとたん、壁や紙になぐり描き？色を使いながら、指先の細かな運動能力が育っています。', title_ko = '낙서 달인 🖍️', body_ko = '크레용을 쥐자마자 벽이나 종이에 낙서를 하나요? 색과 함께 소근육이 자라고 있어요.', title_nl = 'Krabbelkunstenaar 🖍️', body_nl = 'Zodra hij een potlood te pakken heeft, bekrabbelt hij muren of papier. Zijn fijne motoriek ontwikkelt zich met kleuren.', title_pl = 'Mistrz bazgrołów 🖍️', body_pl = 'Gdy tylko dostanie kredkę, bazgrze po ścianach albo po papierze. Jego motoryka mała rozwija się dzięki kolorom.', title_pt = 'Mestre dos rabiscos 🖍️', body_pt = 'Mal apanha um lápis, rabisca as paredes ou o papel. A motricidade fina desenvolve-se com as cores.', title_sv = 'Klottermästare 🖍️', body_sv = 'Så fort barnet får tag i en penna klottrar hen på väggarna eller papperet. Finmotoriken utvecklas med färgerna.', title_vi = 'Bậc thầy vẽ nguệch ngoạc 🖍️', body_vi = 'Vừa cầm được bút là bé vẽ nguệch ngoạc lên tường hoặc giấy. Kỹ năng vận động tinh của bé đang phát triển cùng màu sắc.', title_zh = '涂鸦小能手 🖍️', body_zh = '一拿到笔就在墙上或纸上乱涂乱画。宝宝的精细动作正在色彩中发展。' WHERE id = '14b9dba6-d0f2-4f3d-a4e8-f737b507b018' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El silencio de la noche 🛀', body_es = 'Baño templado, masaje suave y habitación a oscuras. No rompas nunca la rutina de sueño, porque es la mejor señal para su cerebro de que es hora de dormir.', title_fr = 'Le silence de la nuit 🛀', body_fr = 'Bain tiède, massage léger et chambre sombre. Ne sautez jamais la routine du coucher : c''est pour son cerveau le meilleur signal que « c''est l''heure de dormir ».', title_hi = 'रात की खामोशी 🛀', body_hi = 'गुनगुना स्नान, हल्की मालिश और अंधेरा कमरा। सोने के रूटीन को कभी मत तोड़िए, क्योंकि यही उसके दिमाग के लिए ''सोने का समय हो गया'' का सबसे अच्छा संकेत है।', title_id = 'Hening malam 🛀', body_id = 'Mandi air hangat, pijatan ringan, dan kamar yang gelap. Jangan pernah melewatkan rutinitas tidur, karena ini sinyal terbaik bagi otaknya bahwa sudah waktunya tidur.', title_ja = '夜の静けさ 🛀', body_ja = 'ぬるめのお風呂、やさしいマッサージ、暗い部屋。寝る前のルーティンは決して崩さないで。それが脳への「もう寝る時間だよ」といういちばんのサインです。', title_ko = '밤의 고요 🛀', body_ko = '따뜻한 목욕, 부드러운 마사지, 어두운 방. 수면 루틴은 절대 거르지 마세요. 뇌에 ''이제 잘 시간이야''라고 알려 주는 가장 좋은 신호예요.', title_nl = 'Stilte van de nacht 🛀', body_nl = 'Een lauw bad, een zachte massage en een donkere kamer. Sla de slaaproutine nooit over, want dit is voor zijn hersenen het beste signaal dat het slaaptijd is.', title_pl = 'Cisza nocy 🛀', body_pl = 'Ciepła kąpiel, delikatny masaż i ciemny pokój. Nigdy nie zaburzaj rytuału przed snem, bo to dla jego mózgu najlepszy sygnał, że czas spać.', title_pt = 'O silêncio da noite 🛀', body_pt = 'Banho morno, massagem suave e quarto escuro. Nunca quebre a rotina de sono, porque é o melhor sinal para o cérebro dele de que é hora de dormir.', title_sv = 'Nattens tystnad 🛀', body_sv = 'Ljummet bad, lätt massage och ett mörkt rum. Bryt aldrig sovrutinen, för den är signalen ”nu är det dags att sova” till barnets hjärna.', title_vi = 'Sự tĩnh lặng của đêm 🛀', body_vi = 'Bồn nước ấm, mát-xa nhẹ nhàng và căn phòng tối. Đừng bao giờ phá vỡ nếp sinh hoạt trước giờ ngủ, vì đó là tín hiệu tốt nhất báo cho não bé biết "đến giờ ngủ rồi".', title_zh = '夜晚的宁静 🛀', body_zh = '温水澡、轻柔按摩和黑暗的房间。千万别打乱睡前流程，因为这是告诉宝宝大脑“该睡觉了”的最好信号。' WHERE id = '48cc1013-ae1c-4b86-9e80-78bd05d5745a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla entre madres 💬', body_es = '¿Te agota pensar «¿Por qué mi hijo es tan tozudo?»? Entra en la Comunidad Anacan y verás que cada niño pasa por crisis diferentes.', title_fr = 'Entre mamans 💬', body_fr = 'La question « Pourquoi mon enfant est-il si têtu ? » vous épuise ? Rejoignez la Communauté Anacan, vous verrez que chaque enfant traverse ses propres crises.', title_hi = 'माँओं की दिल की बातें 💬', body_hi = '''मेरा बच्चा इतना ज़िद्दी क्यों है?'' यह ख्याल आपको थका रहा है? Anacan कम्युनिटी में जाइए, आप देखेंगी कि हर बच्चा अलग-अलग मुश्किल दौर से गुज़रता है।', title_id = 'Curhat para ibu 💬', body_id = 'Lelah memikirkan ''Kenapa anakku keras kepala sekali?'' Masuklah ke Komunitas Anacan, Anda akan melihat bahwa setiap anak melewati krisis yang berbeda.', title_ja = 'ママたちのおしゃべり 💬', body_ja = '「どうしてうちの子はこんなに頑固なの？」と悩んで疲れていませんか？Anacanコミュニティに参加すれば、どの子もそれぞれの大変な時期を通っていることがわかります。', title_ko = '엄마들의 수다 💬', body_ko = '''우리 아이는 왜 이렇게 고집이 셀까?''라는 생각에 지쳤나요? Anacan 커뮤니티에 들어와 보세요. 모든 아이가 저마다 다른 고비를 지난다는 걸 알게 될 거예요.', title_nl = 'Moeders onder elkaar 💬', body_nl = 'Word je moe van de gedachte ''Waarom is mijn kind zo koppig?'' Ga naar de Anacan Community en je zult zien dat elk kind door andere crises gaat.', title_pl = 'Rozmowy mam 💬', body_pl = 'Męczy cię myśl „Dlaczego moje dziecko jest takie uparte?”? Dołącz do Społeczności Anacan, a zobaczysz, że każde dziecko przechodzi przez różne kryzysy.', title_pt = 'Desabafo entre mães 💬', body_pt = 'Está cansada de pensar "Porque é que o meu filho é tão teimoso?"? Entre na Comunidade Anacan e vai ver que cada criança passa por crises diferentes.', title_sv = 'Mammor pratar av sig 💬', body_sv = 'Tröttar tanken ”Varför är mitt barn så envist?” ut dig? Gå in i Anacan Community, så ser du att varje barn går igenom olika kriser.', title_vi = 'Mẹ tâm sự cùng mẹ 💬', body_vi = 'Câu hỏi "Sao con mình bướng thế?" khiến mẹ mệt mỏi? Hãy vào Cộng đồng Anacan, mẹ sẽ thấy đứa trẻ nào cũng trải qua những giai đoạn khủng hoảng khác nhau.', title_zh = '妈妈们的倾诉 💬', body_zh = '“我的孩子为什么这么倔？”的念头让你心累？进入Anacan社区，你会发现每个孩子都要经历不同的崩溃期。' WHERE id = 'a8d24ffb-d035-4c11-983e-8c2c2a9ad274' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El héroe de la noche: papá 🦸‍♂️', body_es = 'Esta noche deja la rutina de sueño a tu pareja con la función Pareja. Que lea él el cuento mientras tú te preparas un baño caliente y sueltas el estrés del día.', title_fr = 'Le héros du soir : papa 🦸‍♂️', body_fr = 'Ce soir, confiez la routine du coucher à votre partenaire grâce au mode Partenaire. Qu''il lise l''histoire pendant que vous vous préparez un bain chaud pour évacuer le stress de la journée.', title_hi = 'शाम का हीरो: पापा 🦸‍♂️', body_hi = 'आज शाम सोने का रूटीन पार्टनर फ़ीचर से अपने पार्टनर को सौंप दीजिए। कहानी वे पढ़ें और आप अपने लिए गर्म पानी से नहाने की तैयारी करके दिन का तनाव उतारिए।', title_id = 'Pahlawan malam: Ayah 🦸‍♂️', body_id = 'Malam ini serahkan rutinitas tidur kepada pasangan lewat mode Pasangan. Biar ia yang membacakan dongeng, sementara Anda menyiapkan mandi air hangat dan melepas stres hari ini.', title_ja = '今夜のヒーロー：パパ 🦸‍♂️', body_ja = '今夜の寝かしつけは、「パートナーモード」でパートナーにお願いしましょう。お話はパパに読んでもらい、あなたは温かいお風呂で一日のストレスを流して。', title_ko = '저녁의 영웅: 아빠 🦸‍♂️', body_ko = '오늘 저녁 수면 루틴은 파트너 모드로 배우자에게 맡기세요. 동화는 아빠가 읽어 주고, 엄마는 따뜻한 목욕물을 받아 하루의 스트레스를 날려 보내세요.', title_nl = 'Held van de avond: papa 🦸‍♂️', body_nl = 'Laat de slaaproutine vanavond via Partnermodus over aan je partner. Laat hem het sprookje voorlezen, terwijl jij een warm bad voor jezelf laat vollopen en de stress van de dag loslaat.', title_pl = 'Bohater wieczoru: tata 🦸‍♂️', body_pl = 'Dziś wieczorem przekaż rytuał usypiania partnerowi dzięki funkcji Partnera. Niech to on przeczyta bajkę, a ty przygotuj sobie ciepłą kąpiel i zrzuć stres całego dnia.', title_pt = 'O herói da noite: o pai 🦸‍♂️', body_pt = 'Esta noite, entregue a rotina de sono ao seu companheiro com o Modo Parceiro. Ele lê a história e a mãe prepara um banho quente para si e liberta o stress do dia.', title_sv = 'Kvällens hjälte: pappa 🦸‍♂️', body_sv = 'Lämna över kvällens sovrutin till din partner med Partnerläget. Låt hen läsa sagan medan du förbereder ett varmt bad åt dig själv och släpper dagens stress.', title_vi = 'Người hùng buổi tối: Bố 🦸‍♂️', body_vi = 'Tối nay, hãy giao nếp sinh hoạt trước giờ ngủ cho chồng bằng Chế độ đối tác. Để bố đọc truyện, còn mẹ chuẩn bị một bồn nước ấm và trút bỏ căng thẳng cả ngày.', title_zh = '今晚的英雄：爸爸 🦸‍♂️', body_zh = '今晚用伴侣功能把睡前流程交给另一半吧。让他来读故事，你给自己准备一个热水澡，卸下一天的压力。' WHERE id = '5ae62f81-7331-472c-9b48-c967d0615a5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exigente con la comida 🥦', body_es = '¿Hoy rechaza la comida que ayer comía con ganas? Analiza su menú con el Seguimiento de tomas y encuentra en Recetas para bebé presentaciones diferentes y divertidas.', title_fr = 'Difficile à table 🥦', body_fr = 'Il refuse aujourd''hui le plat qu''il a mangé avec appétit hier ? Analysez son menu avec le Suivi des repas et trouvez des présentations différentes et amusantes dans les Recettes pour bébés.', title_hi = 'खाने में नखरे 🥦', body_hi = 'कल जो खाना चाव से खाया, आज उसे मना कर रहा है? फ़ीडिंग ट्रैकर से मेन्यू का विश्लेषण कीजिए और बच्चों की रेसिपी में अलग, मज़ेदार तरीके से परोसने के आइडिया ढूँढिए।', title_id = 'Pilih-pilih makanan 🥦', body_id = 'Hari ini ia menolak makanan yang kemarin ia lahap? Analisis menunya dengan Pemantau Nutrisi dan temukan sajian yang berbeda dan menyenangkan di Resep Bayi.', title_ja = '好き嫌い 🥦', body_ja = '昨日はよく食べたものを、今日はいやがりますか？「栄養管理ツール」でメニューを分析して、「離乳食を始める赤ちゃんのレシピ」で違った楽しい盛りつけを見つけましょう。', title_ko = '편식 🥦', body_ko = '어제 잘 먹던 음식을 오늘은 거부하나요? 수유 기록 도구로 식단을 분석하고, 아기 레시피에서 색다르고 재미있는 담음새를 찾아보세요.', title_nl = 'Kieskeurig eten 🥦', body_nl = 'Weigert hij vandaag wat hij gisteren nog met smaak at? Analyseer zijn menu met de Voedingstracker en vind in Babyrecepten andere, leuke manieren om het op te dienen.', title_pl = 'Wybredne jedzenie 🥦', body_pl = 'Danie, które wczoraj jadł z apetytem, dziś odrzuca? Przeanalizuj menu w narzędziu do śledzenia karmienia i znajdź w Przepisach dla niemowląt inne, zabawne sposoby podania.', title_pt = 'Esquisitices à mesa 🥦', body_pt = 'Hoje recusa a comida que ontem comeu com apetite? Analise a ementa com o Registo de Alimentação e encontre apresentações diferentes e divertidas nas Receitas para bebé.', title_sv = 'Kräsen med maten 🥦', body_sv = 'Vägrar barnet i dag maten hen åt med god aptit i går? Analysera menyn med Matningskoll och hitta andra, roliga sätt att servera i Babyrecept.', title_vi = 'Kén ăn 🥦', body_vi = 'Món hôm qua bé ăn ngon lành thì hôm nay lại từ chối? Hãy phân tích thực đơn bằng Theo dõi cữ bú và tìm những cách bày món khác lạ, vui mắt trong Công thức cho bé.', title_zh = '挑食 🥦', body_zh = '昨天吃得香香的东西，今天却不肯吃？用喂养记录工具分析一下菜单，再到宝宝食谱里找些不同的、有趣的摆盘方式。' WHERE id = '88d95f7d-2e98-41b0-8554-4115adfb31c5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Días sin dolor 🩸', body_es = '¿Se acerca tu regla y han empezado los calambres? Antes de recurrir a los medicamentos, cuídate preparando en Recetas saludables para mujeres un tentempié de dátiles y nueces rico en magnesio.', title_fr = 'Des jours sans douleur 🩸', body_fr = 'Vos règles approchent et les crampes ont commencé ? Avant de vous jeter sur les médicaments, préparez une collation dattes-noix riche en magnésium avec les Recettes saines pour femmes et prenez soin de vous.', title_hi = 'दर्द से राहत वाले दिन 🩸', body_hi = 'पीरियड करीब है और ऐंठन शुरू हो गई? दवाओं की ओर भागने से पहले महिलाओं के लिए सेहतमंद रेसिपी से मैग्नीशियम से भरपूर खजूर-अखरोट वाला स्नैक बनाइए और अपना ख्याल रखिए।', title_id = 'Hari-hari tanpa nyeri 🩸', body_id = 'Haid sudah dekat dan kram mulai terasa? Sebelum buru-buru minum obat, rawat diri Anda dengan camilan kurma dan kenari kaya magnesium dari Resep Sehat untuk wanita.', title_ja = '痛みのない日々 🩸', body_ja = '生理が近づいて、腹痛が始まりましたか？薬にたよる前に、「女性のためのヘルシーレシピ」からマグネシウムたっぷりのデーツとくるみのおやつをつくって、自分をいたわりましょう。', title_ko = '통증 없는 날 🩸', body_ko = '생리가 다가오고 생리통이 시작됐나요? 진통제를 찾기 전에 여성을 위한 건강한 레시피에서 마그네슘이 풍부한 대추야자 호두 간식을 만들어 나를 돌봐 주세요.', title_nl = 'Dagen zonder pijn 🩸', body_nl = 'Komt je menstruatie eraan en zijn de krampen begonnen? Grijp niet meteen naar medicijnen, maar maak uit Gezonde recepten voor vrouwen een magnesiumrijk tussendoortje met dadels en walnoten en zorg goed voor jezelf.', title_pl = 'Dni bez bólu 🩸', body_pl = 'Zbliża się okres i zaczęły się skurcze? Zanim sięgniesz po leki, przygotuj ze Zdrowych przepisów dla kobiet przekąskę z daktylami i orzechami bogatą w magnez i zadbaj o siebie.', title_pt = 'Dias sem dor 🩸', body_pt = 'O período está a chegar e as cólicas já começaram? Antes de recorrer a medicamentos, cuide de si com um snack de tâmaras e nozes rico em magnésio das Receitas Saudáveis para Mulheres.', title_sv = 'Dagar utan smärta 🩸', body_sv = 'Närmar sig mensen och krampen har börjat? Innan du tar till medicin, ta hand om dig med ett magnesiumrikt mellanmål med dadlar och valnötter från Hälsosamma recept för kvinnor.', title_vi = 'Những ngày không đau 🩸', body_vi = 'Kỳ kinh sắp đến và bắt đầu đau bụng? Trước khi tìm đến thuốc, hãy làm món ăn vặt chà là và óc chó giàu magie từ Công thức lành mạnh cho phụ nữ để chăm sóc bản thân.', title_zh = '无痛的日子 🩸', body_zh = '经期快到了，开始痉挛？吃药之前，先从女性健康食谱里做一份富含镁的椰枣核桃小零食，好好照顾自己。' WHERE id = 'b1d18fda-3875-4aca-b436-4ecb52ef49a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La ropa encoge! 📏', body_es = '¿Las mangas de las camisetas se le han vuelto a quedar cortas? Para ver con precisión el estirón hacia el mes 29, introduce sus medidas actuales en el Registro de peso y mira cómo sube la curva.', title_fr = 'Les vêtements rétrécissent ! 📏', body_fr = 'Les manches sont encore trop courtes ? Pour bien voir la poussée de croissance vers le 29e mois, entrez ses mesures actuelles dans le Suivi du poids et regardez la courbe monter.', title_hi = 'कपड़े छोटे हो रहे हैं! 📏', body_hi = 'शर्ट की आस्तीनें फिर छोटी हो गईं? 29वें महीने की ओर हो रहे ग्रोथ स्पर्ट को सही से देखने के लिए वेट ट्रैकर में मौजूदा माप दर्ज कीजिए और ऊपर जाता चार्ट देखिए।', title_id = 'Bajunya makin kecil! 📏', body_id = 'Lengan bajunya sudah kependekan lagi? Untuk melihat lonjakan pertumbuhan menjelang bulan ke-29 dengan tepat, masukkan ukuran terbarunya ke Pelacak Berat Badan dan lihat grafiknya naik.', title_ja = '服が小さくなっちゃう！📏', body_ja = 'シャツのそでがまた短くなりましたか？生後29か月ごろの成長の伸びをしっかり確かめるために、「体重トラッカー」に今のサイズを入力して、右肩上がりのグラフを見てみましょう。', title_ko = '옷이 작아져요! 📏', body_ko = '셔츠 소매가 또 짧아졌나요? 29개월 무렵의 성장 급등을 정확히 보려면 체중 기록에 현재 수치를 입력하고 올라가는 그래프를 확인하세요.', title_nl = 'De kleren krimpen! 📏', body_nl = 'Zijn de mouwen van zijn shirts weer te kort? Vul de huidige maten in de Gewichtstracker in en bekijk de stijgende grafiek om de groeispurt rond de 29e maand precies te zien.', title_pl = 'Ubranka się kurczą! 📏', body_pl = 'Rękawy koszulek znów za krótkie? Aby dokładnie zobaczyć skok wzrostu w okolicach 29. miesiąca, wpisz aktualne wymiary do Licznika wagi i spójrz na rosnący wykres.', title_pt = 'A roupa está a encolher! 📏', body_pt = 'As mangas das camisolas voltaram a ficar curtas? Para ver bem o salto de crescimento perto dos 29 meses, introduza as medidas atuais no Registo de Peso e veja o gráfico a subir.', title_sv = 'Kläderna krymper! 📏', body_sv = 'Har tröjärmarna blivit korta igen? För att tydligt se tillväxtspurten mot 29:e månaden, för in de aktuella måtten i Viktspåraren och titta på den stigande kurvan.', title_vi = 'Quần áo bị chật rồi! 📏', body_vi = 'Tay áo của bé lại ngắn nữa rồi? Để thấy rõ bước nhảy phát triển gần tháng thứ 29, hãy nhập số đo hiện tại vào Theo dõi cân nặng và ngắm biểu đồ đi lên.', title_zh = '衣服变小了！📏', body_zh = '衣袖又变短了？想清楚看到接近29个月时的生长突增，就在体重记录里输入当前尺寸，看看往上走的曲线。' WHERE id = '55fa43db-2800-421e-b0f2-748c40c7ef07' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El héroe del libro 📖', body_es = '¿Quiere que le leas el mismo cuento por centésima vez? Lee en el Blog el papel increíble de esta repetición, que parece aburrida, en el desarrollo de su inteligencia, y renueva tu paciencia.', title_fr = 'Le héros du livre 📖', body_fr = 'Il veut que vous lisiez la même histoire pour la 100e fois ? Lisez dans les Blogs le rôle incroyable de cette répétition, en apparence lassante, dans son développement intellectuel et retrouvez patience.', title_hi = 'किताब का हीरो 📖', body_hi = 'चाहता है कि आप एक ही कहानी 100वीं बार पढ़ें? ब्लॉग में पढ़िए कि यह उबाऊ लगने वाला दोहराव बुद्धि के विकास में कितनी अहम भूमिका निभाता है, और अपना सब्र फिर से जुटाइए।', title_id = 'Pahlawan buku cerita 📖', body_id = 'Ia ingin Anda membacakan dongeng yang sama untuk ke-100 kalinya? Baca di bagian Blog tentang peran luar biasa pengulangan yang tampak membosankan ini bagi kecerdasannya, dan segarkan kembali kesabaran Anda.', title_ja = '絵本のヒーロー 📖', body_ja = '同じお話を100回目も読んでとせがまれますか？うんざりするように見えるこのくり返しが知能の発達にどれほど大切か、ブログで読んで、もう一度がんばる気持ちを取り戻しましょう。', title_ko = '동화책 주인공 📖', body_ko = '같은 동화를 100번째 읽어 달라고 하나요? 지루해 보이는 이 반복이 두뇌 발달에 얼마나 놀라운 역할을 하는지 블로그에서 읽고 인내심을 다시 채워 보세요.', title_nl = 'Boekenheld 📖', body_nl = 'Wil hij dat je hetzelfde sprookje voor de 100e keer voorleest? Lees in Blogs welke ongelooflijke rol deze saai lijkende herhaling speelt in zijn verstandelijke ontwikkeling en vul je geduld weer aan.', title_pl = 'Bohater książki 📖', body_pl = 'Chce, żebyś czytała tę samą bajkę po raz 100.? Przeczytaj na Blogu o niesamowitej roli tego pozornie nużącego powtarzania w rozwoju inteligencji i odnów swoją cierpliwość.', title_pt = 'Herói dos livros 📖', body_pt = 'Quer que leia a mesma história pela 100.ª vez? Leia no Blogue o papel incrível desta repetição, aparentemente aborrecida, no desenvolvimento da inteligência e renove a paciência.', title_sv = 'Bokhjälte 📖', body_sv = 'Vill barnet att du läser samma saga för 100:e gången? Läs i Bloggar om vilken otrolig roll den här till synes tråkiga upprepningen har för intelligensen och fyll på ditt tålamod.', title_vi = 'Nhân vật trong sách 📖', body_vi = 'Bé muốn mẹ đọc cùng một câu chuyện lần thứ 100? Hãy đọc trong mục Blog về vai trò đáng kinh ngạc của sự lặp lại tưởng chừng nhàm chán này với trí tuệ của bé để nạp lại sự kiên nhẫn.', title_zh = '故事书的主角 📖', body_zh = '想让你把同一个故事读第100遍？去博客里读读这种看似无聊的重复对智力发展的惊人作用，重新充满耐心吧。' WHERE id = '8a1a47bc-2d1d-4804-abb1-5b5294f326db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Primeras hipótesis lógicas 🤔', body_es = '¿Construye frases del tipo «Si hago esto, pasa aquello»? No te pierdas este gran salto cognitivo: añádelo en vídeo con sonido al Álbum del bebé y siéntete orgullosa.', title_fr = 'Premières déductions logiques 🤔', body_fr = 'Il fait des phrases du type « Si je fais ça, il va se passer ça » ? Ne manquez pas ce superbe bond cognitif : ajoutez-le en vidéo avec le son à l''Album de bébé, avec fierté.', title_hi = 'पहले तार्किक अनुमान 🤔', body_hi = '''ऐसा करूँ तो ऐसा होगा'' जैसे वाक्य बनाता है? सोचने-समझने की इस शानदार छलांग को बिना चूके आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़िए और गर्व कीजिए।', title_id = 'Dugaan logis pertama 🤔', body_id = 'Ia membuat kalimat seperti ''Kalau aku begini, nanti jadi begitu''? Jangan lewatkan lompatan kognitif luar biasa ini, simpan sebagai video bersuara di Album Bayi dan berbanggalah.', title_ja = 'はじめての論理的な推測 🤔', body_ja = '「これをしたら、こうなる」という文を作っていますか？このすばらしい認知の飛躍を見逃さず、音声つき動画で「ベビーアルバム」に残して誇りに思いましょう。', title_ko = '첫 논리적 추론 🤔', body_ko = '''이렇게 하면 저렇게 돼'' 같은 문장을 만드나요? 이 멋진 인지 발달의 도약을 놓치지 말고 소리가 담긴 영상으로 아기 앨범에 올려 뿌듯해하세요.', title_nl = 'Eerste logische redeneringen 🤔', body_nl = 'Maakt hij zinnen als ''Als ik dit doe, gebeurt dat''? Mis deze prachtige denksprong niet, zet hem als video met geluid in het Babyalbum en wees trots.', title_pl = 'Pierwsze logiczne przypuszczenia 🤔', body_pl = 'Buduje zdania w stylu „Jeśli to zrobię, stanie się tak”? Nie przegap tego wspaniałego skoku poznawczego, dodaj go jako film z dźwiękiem do Albumu dziecka i bądź z niego dumna.', title_pt = 'Primeiras hipóteses lógicas 🤔', body_pt = 'Constrói frases do tipo "Se eu fizer isto, acontece aquilo"? Não perca este salto cognitivo: grave-o em vídeo com som, junte-o ao Álbum do Bebé e sinta orgulho.', title_sv = 'De första logiska antagandena 🤔', body_sv = 'Säger barnet meningar som ”Om jag gör så här, händer det här”? Missa inte det här fantastiska kognitiva språnget, lägg till det som video med ljud i Babyalbumet och var stolt.', title_vi = 'Những suy luận logic đầu tiên 🤔', body_vi = 'Bé nói những câu kiểu "Nếu con làm thế này thì sẽ thế kia"? Đừng bỏ lỡ bước nhảy vọt nhận thức tuyệt vời này, hãy quay video có tiếng, thêm vào Album của bé và tự hào nhé.', title_zh = '最初的逻辑推测 🤔', body_zh = '会说“如果我这样做，就会那样”之类的句子了？别错过这个了不起的认知飞跃，把它录成有声视频加进宝宝相册，好好骄傲一下吧。' WHERE id = 'c88c6893-fe11-4ce0-bf2d-ed7f94e0770d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No quiere dormir la siesta y llora? No luches. En su lugar, anuncia 30 minutos de hora de calma en los que hojee un libro en silencio en su habitación.', body_fr = 'Il refuse la sieste et pleure ? Ne luttez pas. Annoncez plutôt 30 minutes de « temps calme » où il feuillettera un livre en silence dans sa chambre.', body_hi = 'दोपहर में सोना नहीं चाहता और रोता है? लड़ाई मत कीजिए। इसकी बजाय 30 मिनट का ''शांत समय'' घोषित कीजिए, जिसमें वह कमरे में चुपचाप किताब पलटे।', body_id = 'Ia tidak mau tidur siang dan menangis? Jangan berdebat. Sebagai gantinya, umumkan ''waktu tenang'' 30 menit saat ia membolak-balik buku dengan tenang di kamar.', body_ja = 'お昼寝をいやがって泣きますか？戦わないで。かわりに、部屋で静かに絵本をめくる30分の「静かな時間」を宣言しましょう。', body_ko = '낮잠을 안 자겠다고 우나요? 씨름하지 마세요. 대신 방에서 조용히 책을 넘겨 보는 30분의 ''조용한 시간''을 정해 보세요.', body_nl = 'Wil hij geen middagslaapje doen en huilt hij? Ga de strijd niet aan. Kondig in plaats daarvan een rustuurtje van 30 minuten aan, waarin hij stil in zijn kamer in een boekje bladert.', body_pl = 'Nie chce iść na popołudniową drzemkę i płacze? Nie walcz z tym. Zamiast tego ogłoś 30-minutową godzinę wyciszenia, podczas której będzie po cichu przeglądał książeczkę w pokoju.', body_pt = 'Não quer dormir a sesta e chora? Não lute. Em vez disso, anuncie 30 minutos de sossego, em que ele folheia um livro em silêncio no quarto.', body_sv = 'Vill barnet inte sova middag och gråter? Kämpa inte emot. Utlys i stället en 30 minuters Lugn stund då barnet tyst bläddrar i böcker i rummet.', body_vi = 'Bé không chịu ngủ trưa và khóc? Đừng giằng co. Thay vào đó, hãy tuyên bố 30 phút "Giờ yên tĩnh" để bé lặng lẽ lật sách trong phòng.', body_zh = '不想睡午觉，一直哭？别硬碰硬。不如宣布一个30分钟的“安静时间”，让宝宝在房间里安静地翻翻书。' WHERE id = 'c32b736c-41b6-4e37-ad3d-7f15cea8084a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cambio de turno 👨‍👧', body_es = 'Tu cabeza está cansada de responder «¿Por qué?» todo el día. Esta noche pasa a tu pareja la tarea de ponerle el pijama y acostarle, y tú descansa.', title_fr = 'Relève de la garde 👨‍👧', body_fr = 'Votre cerveau est épuisé d''avoir répondu toute la journée aux « Pourquoi ? ». Ce soir, confiez le pyjama et le coucher à votre partenaire, et reposez-vous.', title_hi = 'ड्यूटी बदलिए 👨‍👧', body_hi = 'दिनभर ''क्यों?'' वाले सवालों के जवाब देते-देते दिमाग थक गया? आज शाम पजामा पहनाने और सुलाने की ज़िम्मेदारी अपने पार्टनर को सौंपिए और आप आराम कीजिए।', title_id = 'Ganti giliran 👨‍👧', body_id = 'Otak Anda lelah menjawab pertanyaan ''Kenapa?'' seharian. Malam ini serahkan tugas memakaikan piyama dan menidurkan kepada pasangan, Anda beristirahatlah.', title_ja = 'バトンタッチ 👨‍👧', body_ja = '一日じゅう「なんで？」に答えて、頭がくたくた？今夜はパジャマを着せて寝かしつける役目をパートナーに任せて、あなたは休みましょう。', title_ko = '교대 시간 👨‍👧', body_ko = '하루 종일 ''왜?''라는 질문에 답하느라 머리가 지쳤나요? 오늘 저녁 잠옷 입히기와 재우기는 배우자에게 넘기고 엄마는 쉬세요.', title_nl = 'Wisseling van de wacht 👨‍👧', body_nl = 'Je hoofd is moe van de hele dag ''Waarom?''-vragen beantwoorden. Geef de pyjama en het naar bed brengen vanavond aan je partner, jij rust uit.', title_pl = 'Zmiana warty 👨‍👧', body_pl = 'Twoja głowa jest zmęczona odpowiadaniem przez cały dzień na pytania „Dlaczego?”. Dziś wieczorem przekaż partnerowi przebieranie w piżamę i usypianie, a ty odpocznij.', title_pt = 'Troca de turno 👨‍👧', body_pt = 'O seu cérebro está cansado de responder a "Porquê?" o dia inteiro. Esta noite, passe ao seu companheiro a tarefa de vestir o pijama e deitá-lo, e descanse.', title_sv = 'Skiftbyte 👨‍👧', body_sv = 'Hjärnan är trött efter att ha svarat på ”Varför?” hela dagen. Lämna över pyjamas och nattning till din partner i kväll och vila du.', title_vi = 'Đổi ca 👨‍👧', body_vi = 'Cả ngày trả lời những câu "Tại sao?" khiến đầu óc mẹ mệt nhoài. Tối nay hãy giao việc thay đồ ngủ và cho bé đi ngủ cho chồng, còn mẹ nghỉ ngơi nhé.', title_zh = '换班时间 👨‍👧', body_zh = '回答了一整天的“为什么？”，脑子都累了。今晚把换睡衣、哄睡的任务交给伴侣，你去休息吧。' WHERE id = 'c762e9b7-a5b4-4810-a642-39d1f9c28936' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Moda poco común 👗', body_es = '¿En pleno invierno quiere ponerse pantalón corto de verano y el pantalón en la cabeza? No te metas en sus gustos. Estos experimentos tan cómicos sirven para afirmar su individualidad.', title_fr = 'Une mode originale 👗', body_fr = 'Il veut mettre un short d''été en plein hiver et son pantalon sur la tête ? Ne vous mêlez pas de ses goûts. Ces essais comiques lui servent à affirmer sa personnalité.', title_hi = 'अनोखा फ़ैशन 👗', body_hi = 'सर्दी के बीच गर्मियों वाले शॉर्ट्स और पैंट सिर पर पहनना चाहता है? उसकी पसंद में दखल मत दीजिए। ये मज़ेदार प्रयोग उसकी अपनी पहचान जताने के लिए हैं।', title_id = 'Gaya busana yang unik 👗', body_id = 'Ia ingin memakai celana pendek musim panas di tengah musim dingin, atau memakai celana di kepala? Jangan campuri seleranya. Percobaan lucu ini caranya menegaskan jati dirinya.', title_ja = '個性的なファッション 👗', body_ja = '真冬に夏の半ズボンをはきたがったり、ズボンを頭にかぶったり？好みに口を出さないで。こうしたおもしろい試みは、自分らしさを確かめるためのものです。', title_ko = '독특한 패션 👗', body_ko = '한겨울에 여름 반바지를 입고, 바지를 머리에 쓰고 싶어 하나요? 취향에 간섭하지 마세요. 이런 웃긴 실험은 자기 개성을 확인하는 과정이에요.', title_nl = 'Ongewone mode 👗', body_nl = 'Wil hij midden in de winter een korte broek aan en zijn broek op zijn hoofd? Bemoei je niet met zijn smaak. Deze grappige experimenten laten zijn eigenheid zien.', title_pl = 'Niezwykła moda 👗', body_pl = 'W środku zimy chce założyć letnie szorty, a spodnie na głowę? Nie wtrącaj się w jego gust. Te zabawne eksperymenty pomagają mu potwierdzić swoją indywidualność.', title_pt = 'Moda fora do comum 👗', body_pt = 'Quer usar calções de verão em pleno inverno e as calças na cabeça? Não interfira no gosto dele. Estas experiências cómicas servem para afirmar a sua individualidade.', title_sv = 'Ovanligt mode 👗', body_sv = 'Vill barnet ha sommarshorts mitt i vintern och byxorna på huvudet? Lägg dig inte i smaken. De här komiska experimenten bekräftar barnets individualitet.', title_vi = 'Thời trang khác thường 👗', body_vi = 'Giữa mùa đông bé đòi mặc quần short mùa hè, còn quần dài thì đội lên đầu? Đừng can thiệp vào gu của bé. Những thử nghiệm buồn cười này là để bé khẳng định cá tính.', title_zh = '不寻常的时尚 👗', body_zh = '大冬天想穿夏天的短裤，还想把裤子套在头上？别干涉宝宝的品味。这些搞笑的尝试是为了确认自我个性。' WHERE id = 'dc54ef63-6d88-4c2f-9c5d-c431db5caf8b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exploración en el plato 🥦', body_es = '¿Hoy tira al suelo la comida que ayer le encantaba? Entra en el Plan de alimentación y aprovecha las ideas de menú variadas y coloridas que han preparado expertos para los 2,5 años.', title_fr = 'Exploration dans l''assiette 🥦', body_fr = 'Il jette par terre aujourd''hui le plat qu''il adorait hier ? Ouvrez le Plan de nutrition et profitez d''idées de menus variés et colorés préparés par des spécialistes pour les 2,5 ans.', title_hi = 'थाली में खोजबीन 🥦', body_hi = 'कल का पसंदीदा खाना आज ज़मीन पर फेंक रहा है? फ़ीडिंग प्लान खोलिए और 2.5 साल के बच्चों के लिए विशेषज्ञों के बनाए अलग-अलग और रंग-बिरंगे मेन्यू आइडिया अपनाइए।', title_id = 'Menjelajah piring 🥦', body_id = 'Hari ini ia melempar makanan yang kemarin ia sukai? Buka Rencana Nutrisi dan manfaatkan ide menu yang beragam dan warna-warni dari para ahli untuk usia 2,5 tahun.', title_ja = 'お皿の上の探検 🥦', body_ja = '昨日大好きだった料理を、今日は床に投げますか？「栄養管理ツール」を開いて、専門家が考えた2歳半向けのいろいろなカラフルメニューのアイデアを活用しましょう。', title_ko = '접시 위의 탐험 🥦', body_ko = '어제 좋아하던 음식을 오늘은 바닥에 던지나요? 식단 계획 도구에서 전문가가 두 돌 반 아이를 위해 만든 다채롭고 색다른 메뉴 아이디어를 활용해 보세요.', title_nl = 'Ontdekkingstocht op het bord 🥦', body_nl = 'Gooit hij vandaag het eten dat hij gisteren lekker vond op de grond? Open het Voedingsplan en haal inspiratie uit de gevarieerde, kleurrijke menu-ideeën van experts voor 2,5-jarigen.', title_pl = 'Odkrywanie talerza 🥦', body_pl = 'Danie, które wczoraj uwielbiał, dziś rzuca na podłogę? Wejdź do planu karmienia i skorzystaj z różnorodnych, kolorowych pomysłów na menu dla 2,5-latka przygotowanych przez specjalistów.', title_pt = 'Exploração no prato 🥦', body_pt = 'Hoje atira ao chão a comida de que ontem gostava? Abra o Plano Alimentar e aproveite as ideias de ementa variadas e coloridas preparadas por especialistas para os 2,5 anos.', title_sv = 'Upptäcktsfärd på tallriken 🥦', body_sv = 'Kastar barnet i dag på golvet maten hen älskade i går? Gå in i matplanen och hämta inspiration från olika och färgglada menyidéer för 2,5-åringar som experter har tagit fram.', title_vi = 'Khám phá trên đĩa ăn 🥦', body_vi = 'Món hôm qua bé thích thì hôm nay lại ném xuống sàn? Hãy vào Kế hoạch dinh dưỡng và tham khảo những ý tưởng thực đơn đa dạng, nhiều màu sắc do chuyên gia soạn cho trẻ 2,5 tuổi.', title_zh = '餐盘里的探险 🥦', body_zh = '昨天爱吃的饭，今天却扔到地上？打开喂养计划工具，参考专家为2.5岁宝宝准备的、丰富多彩的不同菜单创意。' WHERE id = '37bfacdd-d6ce-4a16-96d7-85b70834ca41' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Miedos repentinos 👻', body_es = '¿Ha empezado a tener miedo de la oscuridad de la habitación o de sombras imaginarias? Al desarrollarse su imaginación aparecen miedos sin motivo. Dale seguridad y hazle sentir que estás a su lado.', title_fr = 'Peurs soudaines 👻', body_fr = 'Il commence à avoir peur du noir ou d''ombres imaginaires ? En se développant, son imagination fait naître des peurs infondées. Rassurez-le et faites-lui sentir que vous êtes là.', title_hi = 'अचानक आने वाले डर 👻', body_hi = 'कमरे के अंधेरे या काल्पनिक परछाइयों से डरने लगा है? कल्पना बढ़ने के साथ बेवजह के डर पैदा होते हैं। उसे भरोसा दिलाइए और महसूस कराइए कि आप उसके साथ हैं।', title_id = 'Ketakutan tak terduga 👻', body_id = 'Ia mulai takut pada gelapnya kamar atau bayangan khayalan? Seiring imajinasinya berkembang, muncul ketakutan yang tak berdasar. Beri ia rasa aman dan tunjukkan bahwa Anda ada di sisinya.', title_ja = '突然のこわがり 👻', body_ja = '部屋の暗さや想像の影をこわがり始めましたか？想像力が育つにつれて、根拠のないこわさも生まれます。安心させて、そばにいることを感じさせてあげましょう。', title_ko = '갑작스러운 두려움 👻', body_ko = '방의 어둠이나 상상 속 그림자를 무서워하기 시작했나요? 상상력이 자라면서 근거 없는 두려움도 생겨요. 안심시켜 주고 곁에 있다는 걸 느끼게 해 주세요.', title_nl = 'Onverwachte angsten 👻', body_nl = 'Begint hij bang te worden voor het donker of voor denkbeeldige schaduwen? Naarmate zijn fantasie groeit, ontstaan ongegronde angsten. Geef hem vertrouwen en laat voelen dat je bij hem bent.', title_pl = 'Niespodziewane lęki 👻', body_pl = 'Zaczął bać się ciemności w pokoju albo wyimaginowanych cieni? Gdy rozwija się wyobraźnia, pojawiają się nieuzasadnione lęki. Daj mu poczucie bezpieczeństwa i pokaż, że jesteś obok.', title_pt = 'Medos surpresa 👻', body_pt = 'Começou a ter medo do escuro ou de sombras imaginárias? À medida que a imaginação se desenvolve, surgem medos sem razão. Dê-lhe segurança e mostre que está ao lado dele.', title_sv = 'Överraskande rädslor 👻', body_sv = 'Har barnet börjat bli rädd för mörkret i rummet eller för inbillade skuggor? När fantasin utvecklas uppstår obefogade rädslor. Ge barnet trygghet och låt hen känna att du finns där.', title_vi = 'Những nỗi sợ bất ngờ 👻', body_vi = 'Bé bắt đầu sợ bóng tối trong phòng hay những cái bóng tưởng tượng? Khi trí tưởng tượng phát triển, những nỗi sợ vô cớ xuất hiện. Hãy trấn an để bé cảm nhận mẹ luôn ở bên.', title_zh = '突如其来的恐惧 👻', body_zh = '开始害怕房间的黑暗或想象中的影子？随着想象力的发展，会出现一些莫名的恐惧。给宝宝安全感，让宝宝感受到你就在身边。' WHERE id = '6b5d8f34-e3e9-4e8b-8382-9b0f64e3f018' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Batería inagotable 🔋', body_es = 'Tú aún no has podido abrir los ojos, pero tu peque ya está corriendo una maratón sobre la alfombra. Sírvete un café grande, el día va a ser muy movido.', title_fr = 'Une batterie inépuisable 🔋', body_fr = 'Vous n''avez pas encore ouvert les yeux qu''il court déjà un marathon sur le tapis. Servez-vous un grand café, la journée va être très animée.', title_hi = 'कभी न खत्म होने वाली बैटरी 🔋', body_hi = 'आपकी अभी ठीक से आँख भी नहीं खुली, लेकिन वह कालीन पर दौड़ की मैराथन में लगा है। अपने लिए एक बड़ा कप कॉफ़ी बनाइए, आज का दिन बहुत भागदौड़ भरा होगा।', title_id = 'Baterai tak pernah habis 🔋', body_id = 'Mata Anda belum sepenuhnya terbuka, tetapi ia sudah maraton lari di atas karpet. Tuang secangkir besar kopi untuk diri Anda, hari ini akan sangat sibuk.', title_ja = '尽きないバッテリー 🔋', body_ja = 'あなたはまだ目も開けられないのに、お子さんはもうカーペットの上でマラソン中。大きなカップでコーヒーをいれましょう、今日はとても活発な一日になりそうです。', title_ko = '꺼지지 않는 배터리 🔋', body_ko = '엄마는 아직 눈도 못 떴는데 아이는 벌써 카펫 위에서 달리기 마라톤 중이에요. 커피를 큰 잔에 따르세요. 아주 활동적인 하루가 될 거예요.', title_nl = 'Onuitputtelijke batterij 🔋', body_nl = 'Jij hebt je ogen nog niet eens open, maar hij loopt al een marathon op het tapijt. Schenk jezelf een grote koffie in, het wordt een drukke dag.', title_pl = 'Niewyczerpana bateria 🔋', body_pl = 'Ty jeszcze nie otworzyłaś oczu, a on już biega maraton po dywanie. Nalej sobie dużą kawę, dzień będzie bardzo ruchliwy.', title_pt = 'Bateria inesgotável 🔋', body_pt = 'A mãe ainda nem abriu bem os olhos e ele já vai numa maratona de corrida no tapete. Sirva-se de um café grande, o dia vai ser muito agitado.', title_sv = 'Outtömligt batteri 🔋', body_sv = 'Du har knappt hunnit öppna ögonen, men barnet springer redan maraton på mattan. Häll upp en stor kopp kaffe åt dig, dagen kommer att bli väldigt livlig.', title_vi = 'Viên pin không bao giờ cạn 🔋', body_vi = 'Mẹ còn chưa mở nổi mắt mà bé đã chạy marathon trên thảm rồi. Hãy rót cho mình một ly cà phê lớn, hôm nay sẽ là một ngày rất năng động.', title_zh = '用不完的电池 🔋', body_zh = '你还没睁开眼，宝宝已经在地毯上跑起马拉松了。给自己倒一大杯咖啡，今天会非常忙碌。' WHERE id = 'b459387d-d414-446b-ac06-391ffb5af36c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tras los pasos del artista 🖍️', body_es = '¿Se ha acabado el papel y ahora les toca a las paredes y las puertas? Su motricidad fina se desarrolla con los colores. Extiende un cartón grande en la habitación y dile: «Solo puedes dibujar aquí».', title_fr = 'Sur les traces de l''artiste 🖍️', body_fr = 'Plus de papier, c''est au tour des murs et des portes ? Sa motricité fine se développe avec les couleurs. Étalez un grand carton dans la pièce et dites-lui : « Tu peux dessiner seulement ici. »', title_hi = 'कलाकार के निशान 🖍️', body_hi = 'कागज़ खत्म, अब बारी दीवार और दरवाज़ों की है? रंगों के साथ उसकी फ़ाइन मोटर स्किल्स विकसित हो रही हैं। कमरे में एक बड़ा कार्डबोर्ड बिछाइए और कहिए ''तुम ड्रॉइंग सिर्फ़ यहीं बना सकते हो''।', title_id = 'Jejak sang seniman 🖍️', body_id = 'Kertas habis, sekarang giliran dinding dan pintu? Motorik halusnya berkembang lewat warna. Bentangkan karton besar di kamar dan katakan, ''Kamu hanya boleh menggambar di sini''.', title_ja = 'アーティストの足あと 🖍️', body_ja = '紙がなくなって、今度は壁やドアの番？色を使いながら、指先の細かな運動能力が育っています。部屋に大きな段ボールを広げて、「絵はここだけに描いていいよ」と伝えましょう。', title_ko = '꼬마 예술가의 흔적 🖍️', body_ko = '종이가 떨어지니 이제 벽과 문 차례인가요? 색과 함께 소근육이 자라고 있어요. 방에 큰 판지를 깔고 ''그림은 여기에만 그릴 수 있어''라고 말해 주세요.', title_nl = 'In de voetsporen van een kunstenaar 🖍️', body_nl = 'Is het papier op en zijn nu de muren en deuren aan de beurt? Zijn fijne motoriek ontwikkelt zich met kleuren. Leg een groot stuk karton neer en zeg: ''Alleen hier mag je tekenen.''', title_pl = 'Śladami artysty 🖍️', body_pl = 'Papier się skończył, teraz kolej na ściany i drzwi? Jego motoryka mała rozwija się dzięki kolorom. Rozłóż w pokoju duży karton i powiedz: „Rysować możesz tylko tutaj”.', title_pt = 'Nas pegadas de um artista 🖍️', body_pt = 'Acabou o papel e agora é a vez das paredes e das portas? A motricidade fina desenvolve-se com as cores. Estenda um cartão grande no quarto e diga-lhe: "só podes desenhar aqui".', title_sv = 'I konstnärens spår 🖍️', body_sv = 'Är papperet slut och nu är det väggarnas och dörrarnas tur? Finmotoriken utvecklas med färgerna. Bred ut en stor kartong i rummet och säg ”du får bara rita här”.', title_vi = 'Theo dấu người nghệ sĩ 🖍️', body_vi = 'Hết giấy, giờ đến lượt tường và cửa? Kỹ năng vận động tinh của bé đang phát triển cùng màu sắc. Hãy trải một tấm bìa các-tông lớn trong phòng và nói "Con chỉ được vẽ ở đây thôi".', title_zh = '追随小画家的足迹 🖍️', body_zh = '纸用完了，现在轮到墙和门了？宝宝的精细动作正在色彩中发展。在房间里铺一大张纸板，告诉宝宝“只能在这里画画”。' WHERE id = '5b291f89-d920-4ebd-a4e6-3d982c3f7c31' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se ha montado un drama porque le diste el agua en el vaso rojo y no en el azul? No es un capricho: solo comprueba tus límites y si puede controlar el mundo. Ten paciencia.', body_fr = 'Drame parce que vous lui avez donné l''eau dans le gobelet rouge et non le bleu ? Ce n''est pas un caprice, il vérifie simplement vos limites et son pouvoir sur le monde. Soyez patiente.', body_hi = 'पानी नीले की जगह लाल गिलास में दिया तो हंगामा मच गया? यह नखरा नहीं है, वह बस परख रहा है कि आपकी सीमाएँ क्या हैं और वह दुनिया को कितना नियंत्रित कर सकता है। धैर्य रखिए।', body_id = 'Dunia serasa runtuh karena Anda memberinya air di gelas merah, bukan biru? Ini bukan manja, ia hanya menguji batasan Anda dan apakah ia bisa mengendalikan dunianya. Bersabarlah.', body_ja = 'お水を青いコップではなく赤いコップで渡しただけで大騒ぎ？これはわがままではなく、あなたのルールと、自分が世界を動かせるかを試しているだけです。気長にいきましょう。', body_ko = '물을 파란 컵이 아니라 빨간 컵에 줬다고 난리가 났나요? 투정이 아니라 엄마의 경계와 자신이 세상을 움직일 수 있는지 시험하는 거예요. 인내심을 가지세요.', body_nl = 'Brak de hel los omdat je water in een rode in plaats van een blauwe beker gaf? Dat is geen verwend gedrag, hij test gewoon je grenzen en of hij de wereld kan sturen. Heb geduld.', body_pl = 'Rozpętała się burza, bo podałaś wodę w czerwonym, a nie niebieskim kubeczku? To nie kaprys, on po prostu sprawdza twoje granice i to, czy potrafi rządzić swoim światem. Bądź cierpliwa.', body_pt = 'Fez um drama enorme porque lhe deu água no copo vermelho e não no azul? Não é capricho, está só a testar os seus limites e se consegue controlar o mundo. Tenha paciência.', body_sv = 'Blev det kaos för att du gav vattnet i en röd mugg i stället för den blå? Det är inte trots, barnet testar bara dina gränser och om hen kan styra världen. Ha tålamod.', body_vi = 'Cả thế giới như sụp đổ chỉ vì mẹ rót nước vào cốc đỏ thay vì cốc xanh? Đây không phải là nhõng nhẽo, bé chỉ đang thử giới hạn của mẹ và xem mình có điều khiển được thế giới không. Hãy kiên nhẫn.', body_zh = '因为水装在红杯子里而不是蓝杯子里，就闹翻了天？这不是任性，宝宝只是在试探你的界限，看看自己能不能掌控世界。耐心一点。' WHERE id = 'a9576738-56a5-42cd-a95f-6e85e5fb1189' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder terapéutico del agua 🛀', body_es = 'Después de correr todo el día, estáis agotados los dos. Un baño templado no es solo higiene: es el mejor método natural para calmar su sistema nervioso sobrecargado.', title_fr = 'Le pouvoir apaisant de l''eau 🛀', body_fr = 'Après avoir couru toute la journée, vous êtes épuisés tous les deux. Le bain tiède n''est pas qu''une question de propreté : c''est la meilleure méthode naturelle pour apaiser son système nerveux sous tension.', title_hi = 'पानी की चिकित्सीय ताकत 🛀', body_hi = 'दिनभर भागदौड़ से वह भी थक गया और आप भी। गुनगुना स्नान सिर्फ़ सफ़ाई नहीं, बल्कि उसके तनाव भरे नर्वस सिस्टम को शांत करने का सबसे अच्छा प्राकृतिक तरीका है।', title_id = 'Kekuatan terapi air 🛀', body_id = 'Seharian berlarian, ia dan Anda sama-sama kelelahan. Mandi air hangat bukan sekadar membersihkan badan, tetapi cara alami terbaik untuk menenangkan sistem sarafnya yang tegang.', title_ja = 'お水の癒やしの力 🛀', body_ja = '一日じゅう走り回って、ふたりともへとへと。ぬるめのお風呂はただ体をきれいにするだけでなく、高ぶった神経を落ち着かせるいちばんの自然な方法です。', title_ko = '물의 치유력 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤죠. 따뜻한 목욕은 단순히 씻는 게 아니라 예민해진 신경을 진정시키는 가장 좋은 자연의 방법이에요.', title_nl = 'De helende kracht van water 🛀', body_nl = 'Jullie zijn allebei op van een hele dag rennen. Een lauw bad is niet alleen om schoon te worden, het is de beste natuurlijke manier om zijn overprikkelde zenuwstelsel te kalmeren.', title_pl = 'Terapeutyczna moc wody 🛀', body_pl = 'Po całym dniu biegania oboje jesteście wykończeni. Ciepła kąpiel to nie tylko higiena, ale najlepszy naturalny sposób na uspokojenie jego napiętego układu nerwowego.', title_pt = 'O poder terapêutico da água 🛀', body_pt = 'Depois de correrem o dia todo, estão os dois esgotados. Um banho morno não é só higiene, é o melhor método natural para acalmar o sistema nervoso tenso dele.', title_sv = 'Vattnets terapeutiska kraft 🛀', body_sv = 'Både du och barnet är helt slut efter en hel dag i farten. Ett ljummet bad är inte bara renlighet, det är det bästa naturliga sättet att lugna barnets spända nervsystem.', title_vi = 'Sức mạnh trị liệu của nước 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều kiệt sức. Bồn nước ấm không chỉ để tắm sạch, mà còn là cách tự nhiên tốt nhất xoa dịu hệ thần kinh đang căng thẳng của bé.', title_zh = '水的疗愈力量 🛀', body_zh = '跑了一整天，宝宝和你都累坏了。温水澡不只是为了清洁，更是让宝宝紧绷的神经系统放松下来的最好的天然方法。' WHERE id = 'e5ef4a95-198d-48b4-a37a-8ba378115031' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con el desorden 🌪️', body_es = '¿Cansada de recoger los mismos juguetes cada día? ¡Hoy no recojas! El desorden de la casa no es el fin del mundo; tu bienestar psicológico importa más que nada.', title_fr = 'Faire la paix avec le désordre 🌪️', body_fr = 'Fatiguée de ranger les mêmes jouets tous les jours ? Aujourd''hui, ne rangez pas ! Une maison en désordre n''est pas la fin du monde, votre bien-être psychologique passe avant tout.', title_hi = 'बिखरे घर से सुलह 🌪️', body_hi = 'रोज़ वही खिलौने समेटते-समेटते थक गईं? आज मत समेटिए! बिखरा घर दुनिया का अंत नहीं है, आपका मानसिक सुकून सबसे ज़्यादा ज़रूरी है।', title_id = 'Berdamai dengan berantakan 🌪️', body_id = 'Lelah membereskan mainan yang sama setiap hari? Hari ini jangan dibereskan! Rumah berantakan bukan akhir dunia, ketenangan batin Anda lebih penting dari segalanya.', title_ja = '散らかりと仲直り 🌪️', body_ja = '毎日同じおもちゃを片づけるのに疲れましたか？今日は片づけなくていい！散らかった家は世界の終わりではありません。あなたの心のゆとりが何より大切です。', title_ko = '어질러짐과 화해하기 🌪️', body_ko = '매일 같은 장난감을 치우느라 지쳤나요? 오늘은 치우지 마세요! 어질러진 집이 세상의 끝은 아니에요. 엄마의 마음 편안함이 무엇보다 중요해요.', title_nl = 'Vrede sluiten met de rommel 🌪️', body_nl = 'Ben je het zat om elke dag hetzelfde speelgoed op te ruimen? Laat het vandaag liggen! Een rommelig huis is niet het einde van de wereld, je mentale rust is belangrijker dan alles.', title_pl = 'Pogodzić się z bałaganem 🌪️', body_pl = 'Masz dość codziennego zbierania tych samych zabawek? Dziś ich nie sprzątaj! Bałagan w domu to nie koniec świata, twój spokój psychiczny jest najważniejszy.', title_pt = 'Fazer as pazes com a desarrumação 🌪️', body_pt = 'Cansada de arrumar os mesmos brinquedos todos os dias? Hoje não arrume! A casa desarrumada não é o fim do mundo, o seu bem-estar psicológico é o mais importante.', title_sv = 'Försonas med stöket 🌪️', body_sv = 'Är du trött på att plocka upp samma leksaker varje dag? Låt bli i dag! Ett stökigt hem är inte världens undergång, ditt psykiska välmående är viktigast av allt.', title_vi = 'Chấp nhận sự bừa bộn 🌪️', body_vi = 'Mẹ mệt vì ngày nào cũng dọn những món đồ chơi giống nhau? Hôm nay đừng dọn! Nhà bừa không phải là tận thế, sự thoải mái tâm lý của mẹ quan trọng hơn tất cả.', title_zh = '和凌乱和解 🌪️', body_zh = '每天收拾同样的玩具，收拾累了？今天就别收了！家里乱一点不是世界末日，你的心理放松比什么都重要。' WHERE id = '891847ab-5f43-4ba4-a99f-cf7faceb076c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencia la culpa 💬', body_es = '¿Te culpas porque hoy ha pasado mucho tiempo delante de la pantalla? Entra en la Comunidad Anacan, lee que otras madres también se sienten así a veces y quédate tranquila. No estás sola.', title_fr = 'Faites taire la culpabilité 💬', body_fr = 'Vous culpabilisez parce qu''il est resté trop longtemps devant l''écran aujourd''hui ? Rejoignez la Communauté Anacan, lisez que d''autres mamans ressentent parfois la même chose et soufflez. Vous n''êtes pas seule.', title_hi = 'अपराध-बोध को चुप कराइए 💬', body_hi = 'आज वह स्क्रीन के सामने ज़्यादा रहा, इसलिए खुद को दोष दे रही हैं? Anacan कम्युनिटी में जाइए, पढ़िए कि दूसरी माँएँ भी कभी-कभी ऐसा ही महसूस करती हैं, और सुकून पाइए। आप अकेली नहीं हैं।', title_id = 'Bungkam rasa bersalah 💬', body_id = 'Menyalahkan diri karena hari ini ia terlalu lama di depan layar? Masuklah ke Komunitas Anacan, baca bahwa ibu lain juga kadang merasakan hal yang sama, dan tenangkan diri. Anda tidak sendirian.', title_ja = '罪悪感をしずめて 💬', body_ja = '今日は画面を見る時間が長すぎたと自分を責めていますか？Anacanコミュニティに参加して、ほかのママも同じ気持ちになることがあると読んで、ほっとしましょう。あなたはひとりではありません。', title_ko = '죄책감은 잠재우세요 💬', body_ko = '오늘 화면을 너무 오래 봤다고 자책하나요? Anacan 커뮤니티에 들어와 다른 엄마들도 가끔 같은 마음이라는 걸 읽고 마음을 놓으세요. 혼자가 아니에요.', title_nl = 'Leg je schuldgevoel het zwijgen op 💬', body_nl = 'Verwijt je jezelf dat hij vandaag te lang voor een scherm zat? Ga naar de Anacan Community, lees dat andere moeders soms precies hetzelfde voelen en kom tot rust. Je bent niet alleen.', title_pl = 'Ucisz wyrzuty sumienia 💬', body_pl = 'Obwiniasz się, że spędził dziś za dużo czasu przed ekranem? Dołącz do Społeczności Anacan, przeczytaj, że inne mamy też czasem tak się czują, i odetchnij. Nie jesteś sama.', title_pt = 'Cale a culpa 💬', body_pt = 'Culpa-se porque hoje ele passou muito tempo em frente ao ecrã? Entre na Comunidade Anacan, leia que outras mães também sentem o mesmo e fique mais tranquila. Não está sozinha.', title_sv = 'Tysta det dåliga samvetet 💬', body_sv = 'Klandrar du dig själv för att barnet satt länge framför skärmen i dag? Gå in i Anacan Community, läs att andra mammor ibland känner likadant och slappna av. Du är inte ensam.', title_vi = 'Hãy để cảm giác tội lỗi im lặng 💬', body_vi = 'Mẹ tự trách vì hôm nay bé xem màn hình quá lâu? Hãy vào Cộng đồng Anacan, đọc những chia sẻ của các mẹ khác cũng đôi khi có cảm giác như vậy để nhẹ lòng hơn. Mẹ không đơn độc.', title_zh = '让内疚安静下来 💬', body_zh = '因为宝宝今天看屏幕太久而责怪自己？进入Anacan社区，读读其他妈妈有时也有同样的感受，放松一下吧。你并不孤单。' WHERE id = '9de03e77-6cb6-4585-9646-e7347bac18d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La personalidad en el espejo 👀', body_es = '¿Pone caras distintas delante del espejo y habla y se ríe solo? Su conciencia de sí mismo va de maravilla. Obsérvale a escondidas y disfruta con orgullo de estos momentos tan cómicos.', title_fr = 'La personnalité dans le miroir 👀', body_fr = 'Devant le miroir, il fait des grimaces, se parle et rit tout seul ? Sa conscience de soi est parfaite. Observez-le en cachette et savourez fièrement ces moments comiques.', title_hi = 'आईने में अपनी पहचान 👀', body_hi = 'आईने के सामने तरह-तरह के चेहरे बनाता है, खुद से बातें करके हँसता है? अपने आप को पहचानने की उसकी समझ कमाल की है। चुपके से उसे देखिए और इन मज़ेदार पलों का गर्व से आनंद लीजिए।', title_id = 'Jati diri di cermin 👀', body_id = 'Ia membuat berbagai ekspresi di depan cermin, berbicara dan tertawa sendiri? Kesadaran dirinya berkembang sempurna. Amati diam-diam dan nikmati momen lucu ini dengan bangga.', title_ja = '鏡の中の自分 👀', body_ja = '鏡の前でいろいろな表情をして、ひとりでしゃべって笑っていますか？自己認識がすばらしく育っています。こっそり見守って、このおもしろい瞬間を誇らしく楽しみましょう。', title_ko = '거울 속의 나 👀', body_ko = '거울 앞에서 여러 표정을 짓고 혼자 말하며 웃나요? 자아 인식이 멋지게 자라고 있어요. 몰래 지켜보며 이 웃긴 순간을 뿌듯하게 즐기세요.', title_nl = 'De persoonlijkheid in de spiegel 👀', body_nl = 'Trekt hij voor de spiegel allerlei gezichten en praat en lacht hij in zichzelf? Zijn zelfbewustzijn ontwikkelt zich prachtig. Kijk stiekem toe en geniet trots van deze grappige momenten.', title_pl = 'Osobowość w lustrze 👀', body_pl = 'Robi przed lustrem różne miny, mówi do siebie i się śmieje? Jego samoświadomość rozwija się wspaniale. Obserwuj go ukradkiem i z dumą ciesz się tymi zabawnymi chwilami.', title_pt = 'A personalidade no espelho 👀', body_pt = 'Faz caretas diferentes ao espelho, fala sozinho e ri-se? A consciência de si próprio está ótima. Observe-o às escondidas e saboreie com orgulho estes momentos cómicos.', title_sv = 'Personligheten i spegeln 👀', body_sv = 'Gör barnet olika miner framför spegeln och pratar och skrattar för sig själv? Självmedvetenheten är fantastisk. Titta i smyg och njut stolt av de här komiska stunderna.', title_vi = 'Cá tính trong gương 👀', body_vi = 'Bé làm đủ kiểu mặt trước gương, tự nói rồi tự cười? Nhận thức về bản thân của bé đang phát triển tuyệt vời. Hãy lén quan sát và tự hào tận hưởng những khoảnh khắc ngộ nghĩnh này.', title_zh = '镜子里的自我 👀', body_zh = '在镜子前做各种表情，自言自语还自己笑？自我意识发展得很棒。悄悄看着宝宝，骄傲地享受这些搞笑时刻吧。' WHERE id = 'f7d0d8f9-fd4d-4b19-b40e-907cdb2d4aea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baile de la mañana 🎶', body_es = '¿Se despierta lleno de energía? Para calmar el caos de la mañana, pon una canción infantil alegre, bailad unos minutos por la habitación y empezad el día con una sonrisa.', title_fr = 'La danse du matin 🎶', body_fr = 'Plein d''énergie dès qu''il ouvre les yeux ? Pour calmer le chaos du matin, mettez une chanson enfantine joyeuse et dansez quelques minutes dans la pièce pour commencer la journée avec le sourire.', title_hi = 'सुबह का डांस 🎶', body_hi = 'आँख खुलते ही ऊर्जा से भरा है? सुबह की अफ़रा-तफ़री शांत करने के लिए बच्चों का कोई खुशनुमा गाना लगाइए और कमरे में कुछ मिनट नाचकर मुस्कान के साथ दिन शुरू कीजिए।', title_id = 'Joget pagi 🎶', body_id = 'Langsung penuh energi begitu membuka mata? Untuk meredakan kekacauan pagi, putar lagu anak yang ceria dan berjoget beberapa menit di kamar untuk memulai hari dengan senyum.', title_ja = '朝のダンス 🎶', body_ja = '目を開けたとたんにエネルギー全開？朝のバタバタを落ち着かせるために、楽しい子どもの歌をかけて部屋で数分踊り、笑顔で一日を始めましょう。', title_ko = '아침 춤 🎶', body_ko = '눈 뜨자마자 에너지가 넘치나요? 아침의 혼란을 달래려면 신나는 동요를 틀고 방에서 몇 분 춤추며 웃는 얼굴로 하루를 시작해 보세요.', title_nl = 'Ochtenddansje 🎶', body_nl = 'Zit hij vol energie zodra hij zijn ogen opent? Zet een vrolijk kinderliedje op tegen de ochtendchaos en begin de dag met een glimlach door een paar minuten door de kamer te dansen.', title_pl = 'Poranny taniec 🎶', body_pl = 'Pełen energii, gdy tylko otworzy oczy? Aby uspokoić poranny chaos, włącz wesołą piosenkę dla dzieci i zacznijcie dzień z uśmiechem, tańcząc przez kilka minut po pokoju.', title_pt = 'Dança da manhã 🎶', body_pt = 'Mal abre os olhos, já está cheio de energia? Para acalmar o caos da manhã, ponha uma música infantil alegre, dancem uns minutos pelo quarto e comecem o dia a sorrir.', title_sv = 'Morgondans 🎶', body_sv = 'Full av energi så fort ögonen öppnas? För att lugna morgonkaoset, sätt på en glad barnlåt, dansa några minuter i rummet och börja dagen med ett leende.', title_vi = 'Điệu nhảy buổi sáng 🎶', body_vi = 'Vừa mở mắt bé đã tràn đầy năng lượng? Để xoa dịu sự hỗn loạn buổi sáng, hãy bật một bài hát thiếu nhi vui nhộn, nhảy vài phút trong phòng và bắt đầu ngày mới bằng nụ cười.', title_zh = '晨间舞蹈 🎶', body_zh = '一睁眼就精力满满？为了让早晨的混乱平静下来，放一首欢快的儿歌，在房间里跳几分钟舞，用笑容开启新的一天。' WHERE id = '0f4c51cd-27d9-4064-9aec-69b37d8e0a6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lista de lo que falta 🛒', body_es = '¿Se han acabado los pañales, el champú o el puré de fruta? No cargues la cabeza: apúntalo todo enseguida en la Lista de la compra y sincronízala con tu pareja en un clic.', title_fr = 'La liste des besoins 🛒', body_fr = 'Plus de couches, de shampoing ou de compote ? Ne vous encombrez pas l''esprit : notez tout de suite dans la Liste de courses et synchronisez-la avec votre partenaire en un clic.', title_hi = 'ज़रूरतों की लिस्ट 🛒', body_hi = 'डायपर, शैम्पू या फ्रूट प्यूरी खत्म हो गई? दिमाग मत थकाइए, सब कुछ तुरंत शॉपिंग लिस्ट में लिखिए और एक टैप में अपने पार्टनर के साथ सिंक कीजिए।', title_id = 'Daftar kebutuhan 🛒', body_id = 'Popok, sampo, atau puree buah habis? Jangan membebani pikiran, segera catat semuanya di Daftar Belanja dan sinkronkan dengan pasangan dalam satu klik.', title_ja = '必要なものリスト 🛒', body_ja = 'おむつやシャンプー、フルーツピューレが切れた？頭で覚えておかず、すぐに「買い物リスト」に入れて、ワンタップでパートナーと共有しましょう。', title_ko = '필요한 것 목록 🛒', body_ko = '기저귀, 샴푸, 과일 퓌레가 떨어졌나요? 머리 아프게 기억하지 말고 바로 쇼핑 목록에 적어 배우자와 한 번에 공유하세요.', title_nl = 'Boodschappenlijstje 🛒', body_nl = 'Luiers, shampoo of fruitpuree op? Pijnig je hoofd niet, zet alles meteen op je Boodschappenlijstje en synchroniseer het met één klik met je partner.', title_pl = 'Lista potrzeb 🛒', body_pl = 'Skończyły się pieluszki, szampon albo owocowy przecier? Nie obciążaj głowy, od razu wpisz wszystko na Listę zakupów i zsynchronizuj ją z partnerem jednym kliknięciem.', title_pt = 'Lista do que falta 🛒', body_pt = 'Acabaram as fraldas, o champô ou o puré de fruta? Não sobrecarregue a cabeça: aponte tudo logo na Lista de Compras e sincronize com o seu companheiro num clique.', title_sv = 'Lista över behov 🛒', body_sv = 'Har blöjorna, schampot eller fruktpurén tagit slut? Belasta inte hjärnan, skriv genast in allt i Inköpslistan och synka med din partner med ett klick.', title_vi = 'Danh sách cần mua 🛒', body_vi = 'Hết tã, dầu gội hay trái cây nghiền? Đừng bắt mình phải nhớ, hãy ghi ngay mọi thứ vào Danh sách mua sắm và đồng bộ với chồng chỉ bằng một chạm.', title_zh = '需要清单 🛒', body_zh = '尿布、洗发水或果泥用完了？别让脑子太累，马上把它们都写进购物清单，一键和另一半同步。' WHERE id = '3f35178a-8193-420a-abc5-0ec312dd4ef0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencio profundo 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba los decibelios con el Medidor de sonido, baja el volumen de la tele y disfruta del silencio profundo que llena la casa.', title_fr = 'Un silence profond 🤫', body_fr = 'La première demi-heure de sommeil est la plus fragile. Vérifiez le niveau de décibels avec le Sonomètre, baissez la télé et savourez ce silence profond qui envahit la maison.', title_hi = 'गहरी खामोशी 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक होता है। साउंड मीटर से माहौल का डेसिबल जाँचिए, टीवी की आवाज़ कम कीजिए और घर में छाई इस गहरी खामोशी की कद्र कीजिए।', title_id = 'Hening yang dalam 🤫', body_id = 'Setengah jam pertama setelah tertidur adalah waktu paling sensitif. Periksa desibel ruangan dengan Pengukur Suara, kecilkan suara TV, dan nikmati keheningan yang menyelimuti rumah.', title_ja = '深い静けさ 🤫', body_ja = '寝ついてから最初の30分がいちばん眠りが浅い時間です。「サウンドメーター」で周りのデシベルを確かめ、テレビの音を小さくして、家を包む深い静けさを味わいましょう。', title_ko = '깊은 고요 🤫', body_ko = '잠든 후 첫 30분이 가장 예민한 시간이에요. 소음 측정기로 데시벨을 확인하고, TV 소리를 줄이고, 집 안에 내려앉은 깊은 고요를 누려 보세요.', title_nl = 'Diepe stilte 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Meet het decibelniveau met de Geluidsmeter, zet de tv zachter en geniet van de diepe stilte in huis.', title_pl = 'Głęboka cisza 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź Miernikiem dźwięku poziom decybeli, ścisz telewizor i doceń tę głęboką ciszę, która zapada w domu.', title_pt = 'Silêncio profundo 🤫', body_pt = 'A primeira meia hora depois de adormecer é o momento mais sensível. Verifique os decibéis com o Medidor de Som, baixe o volume da televisão e aproveite este silêncio profundo que cai sobre a casa.', title_sv = 'Djup tystnad 🤫', body_sv = 'Den första halvtimmen efter insomnandet är den känsligaste tiden. Kontrollera ljudnivån i decibel med Ljudmätaren, sänk tv:ns ljud och njut av den djupa tystnaden som lägger sig över hemmet.', title_vi = 'Sự tĩnh lặng sâu lắng 🤫', body_vi = 'Nửa giờ đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra decibel bằng Đo âm thanh, vặn nhỏ tiếng TV và tận hưởng sự tĩnh lặng sâu lắng bao trùm căn nhà.', title_zh = '深深的安静 🤫', body_zh = '入睡后的头半小时最敏感。用分贝仪检查环境分贝，调低电视音量，好好珍惜家里这份深深的安静。' WHERE id = '4ec6bcf9-c49a-4e82-9a6f-0ae618212221' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Jugando en la arena no le deja su cubo a nadie? No es egoísmo, es proteger sus límites. No le obligues; en su lugar, enséñale con suavidad la regla de «Jugamos por turnos».', body_fr = 'Il ne prête son seau à personne dans le bac à sable ? Ce n''est pas de l''égoïsme, il protège ses limites. Ne le forcez pas, apprenez-lui plutôt en douceur la règle « On joue chacun son tour ».', body_hi = 'रेत में खेलते समय अपना डिब्बा किसी को नहीं देता? यह स्वार्थ नहीं, अपनी सीमा की रक्षा है। ज़बरदस्ती मत कीजिए, बल्कि प्यार से ''बारी-बारी से खेलें'' का नियम सिखाइए।', body_id = 'Saat bermain pasir ia tidak mau meminjamkan wadahnya kepada siapa pun? Ini bukan egois, ia sedang menjaga batasnya. Jangan memaksanya, sebaliknya ajarkan aturan ''Ayo main bergiliran'' dengan bahasa yang lembut.', body_ja = '砂場で遊ぶとき、自分の容器をだれにも渡しませんか？これはわがままではなく、自分の領域を守っているのです。無理強いせず、「順番に遊ぼうね」のルールをやさしく教えましょう。', body_ko = '모래 놀이를 할 때 그릇을 아무에게도 안 주나요? 이기심이 아니라 자기 경계를 지키는 거예요. 억지로 시키지 말고 ''차례대로 놀자'' 규칙을 부드럽게 알려 주세요.', body_nl = 'Geeft hij in de zandbak zijn emmertje aan niemand? Dat is geen egoïsme, maar zijn grenzen bewaken. Dwing hem niet, maar leer hem vriendelijk de regel ''We spelen om de beurt''.', body_pl = 'W piaskownicy nikomu nie daje swojego wiaderka? To nie egoizm, tylko ochrona granic. Nie zmuszaj go, zamiast tego łagodnie ucz zasady „bawimy się po kolei”.', body_pt = 'Na areia, não empresta o balde a ninguém? Não é egoísmo, é proteger os seus limites. Não o force; em vez disso, ensine com suavidade a regra "vamos brincar à vez".', body_sv = 'Vägrar barnet låna ut sin hink till någon i sandlådan? Det är inte egoism, det är att skydda sina gränser. Tvinga inte barnet, lär i stället ut regeln ”Vi turas om” på ett mjukt sätt.', body_vi = 'Chơi cát mà bé không cho ai mượn xô của mình? Đây không phải ích kỷ mà là bé đang bảo vệ ranh giới. Đừng ép bé, thay vào đó hãy nhẹ nhàng dạy quy tắc "Mình chơi lần lượt nhé".', body_zh = '玩沙子时不肯把小桶给别人？这不是自私，而是在守护自己的界限。别勉强宝宝，用温柔的话教宝宝“我们轮流玩”的规则。' WHERE id = '765fd3c5-2a1b-4659-aa42-b76314ae48dc' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Intenta darle agua a su osito o a su muñeca y habla con ellos? El juego simbólico es una obra maestra del desarrollo. Observa con interés desde fuera a este pequeño director.', body_fr = 'Il essaie de donner à boire à son nounours ou à sa poupée et leur parle ? Le jeu symbolique est un chef-d''œuvre du développement. Observez de loin, avec curiosité, ce mignon petit metteur en scène.', body_hi = 'टेडी बियर या गुड़िया को पानी पिलाने की कोशिश करता है, उनसे बातें करता है? प्रतीकात्मक खेल विकास का बेहतरीन नमूना है। इस प्यारे से निर्देशक को दूर से दिलचस्पी के साथ देखिए।', body_id = 'Ia mencoba memberi minum boneka beruang atau bonekanya, lalu mengajak mereka bicara? Permainan simbolis adalah karya agung perkembangan. Saksikan sutradara kecil yang manis ini dengan penuh minat dari jauh.', body_ja = 'くまのぬいぐるみやお人形にお水を飲ませようとしたり、話しかけたりしていますか？ごっこ遊びは発達の傑作です。このかわいい監督さんを、少し離れて楽しく見守りましょう。', body_ko = '곰 인형이나 인형에게 물을 먹이고 대화를 나누나요? 상징 놀이는 발달의 걸작이에요. 이 귀여운 꼬마 감독을 멀리서 흥미롭게 지켜보세요.', body_nl = 'Probeert hij zijn beer of pop water te geven en praat hij met ze? Symbolisch spel is een meesterwerk van de ontwikkeling. Kijk nieuwsgierig toe naar deze schattige kleine regisseur.', body_pl = 'Próbuje napoić misia lub lalkę wodą i z nimi rozmawia? Zabawa symboliczna to arcydzieło rozwoju. Z zaciekawieniem obserwuj z boku tego słodkiego reżysera.', body_pt = 'Tenta dar água ao ursinho ou à boneca e conversa com eles? O jogo simbólico é uma obra-prima do desenvolvimento. Observe com interesse este pequeno realizador à distância.', body_sv = 'Försöker barnet ge nallen eller dockan vatten och prata med dem? Symbolisk lek är utvecklingens mästerverk. Titta nyfiket på den söta regissören på avstånd.', body_vi = 'Bé cố cho gấu bông hay búp bê uống nước, trò chuyện với chúng? Trò chơi biểu tượng là kiệt tác của sự phát triển. Hãy thích thú quan sát "đạo diễn" đáng yêu này từ xa.', body_zh = '想给玩具熊或娃娃喂水，还和它们对话？象征性游戏是发育的杰作。在一旁饶有兴趣地看看这位可爱的小导演吧。' WHERE id = '8329858a-b5aa-4e88-a094-94baf4b4dff4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Palabras nuevas 🧠', body_es = '¿Hoy ha construido una frase complicada, como un adulto? Abre ya el Seguimiento del desarrollo y guarda este salto cognitivo como recuerdo para leerlo en el futuro.', title_fr = 'Nouveaux mots 🧠', body_fr = 'Aujourd''hui, il a fait une phrase compliquée, comme un grand ? Ouvrez vite le Suivi de développement et notez ce bond cognitif comme un souvenir à relire plus tard.', title_hi = 'नए शब्द 🧠', body_hi = 'आज उसने बड़ों की तरह कोई अलग, जटिल वाक्य बनाया? तुरंत ग्रोथ ट्रैकर खोलिए और इस संज्ञानात्मक छलांग को आगे पढ़ने के लिए याद के तौर पर दर्ज कीजिए।', title_id = 'Kata-kata baru 🧠', body_id = 'Hari ini ia membuat kalimat rumit seperti orang dewasa? Segera buka Pelacak Perkembangan dan catat lompatan kognitif ini sebagai kenangan untuk dibaca di masa depan.', title_ja = '新しい言葉 🧠', body_ja = '今日は大人のような、いつもと違う複雑な文を話しましたか？すぐに「発達トラッカー」を開いて、この認知の飛躍を、いつか読み返す思い出として記録しましょう。', title_ko = '새로운 말 🧠', body_ko = '오늘 어른처럼 색다르고 복잡한 문장을 말했나요? 바로 성장 기록을 열어 이 인지 발달의 도약을 나중에 다시 읽을 추억으로 남겨 두세요.', title_nl = 'Nieuwe woorden 🧠', body_nl = 'Maakte hij vandaag een ingewikkelde zin, net als een grote? Open meteen de Groeitracker en leg deze cognitieve sprong vast als herinnering om later terug te lezen.', title_pl = 'Nowe słowa 🧠', body_pl = 'Zbudował dziś złożone zdanie jak dorosły? Od razu otwórz Śledzenie rozwoju i zapisz ten skok poznawczy jako wspomnienie, do którego kiedyś wrócisz.', title_pt = 'Novas palavras 🧠', body_pt = 'Hoje construiu uma frase complexa, como um adulto? Abra já o Registo de Desenvolvimento e guarde este salto cognitivo como recordação para ler no futuro.', title_sv = 'Nya ord 🧠', body_sv = 'Sa barnet i dag en annorlunda, komplicerad mening som en vuxen? Öppna genast Utvecklingsspåraren och anteckna det här kognitiva språnget som ett minne att läsa i framtiden.', title_vi = 'Từ mới 🧠', body_vi = 'Hôm nay bé nói một câu phức tạp như người lớn? Hãy mở ngay Theo dõi phát triển và ghi lại bước nhảy vọt nhận thức này làm kỷ niệm để đọc lại sau này.', title_zh = '新词语 🧠', body_zh = '今天像个大人一样说了一句复杂的句子？马上打开发育追踪，把这次认知飞跃记下来，留作将来翻看的回忆。' WHERE id = 'fc8def68-9f4f-421f-a543-941a3d40a533' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pausa en pareja 🥂', body_es = 'Tu peque se ha dormido. Ahora aparca las tareas de casa. Habla con tu pareja al menos 20 minutos de cualquier tema que no sea el niño. También sois una pareja.', title_fr = 'Pause à deux 🥂', body_fr = 'L''enfant dort. Maintenant, mettez de côté les tâches ménagères. Parlez avec votre partenaire au moins 20 minutes d''autre chose que de l''enfant. Vous êtes aussi un couple.', title_hi = 'कपल ब्रेक 🥂', body_hi = 'बच्चा सो गया। अब घर के काम एक तरफ़ रखिए। अपने पार्टनर से कम से कम 20 मिनट बच्चे के अलावा किसी भी विषय पर बात कीजिए। आप एक कपल भी हैं।', title_id = 'Waktu berdua 🥂', body_id = 'Anak sudah tidur. Sekarang singkirkan pekerjaan rumah. Mengobrollah dengan pasangan setidaknya 20 menit tentang topik apa pun selain anak. Anda juga sepasang kekasih.', title_ja = 'ふたりの休憩 🥂', body_ja = 'お子さんが眠りました。家事はいったん脇に置いて、パートナーと少なくとも20分、子どものこと以外の話をしましょう。あなたたちは夫婦でもあるのです。', title_ko = '부부만의 쉼표 🥂', body_ko = '아이가 잠들었어요. 이제 집안일은 내려놓으세요. 배우자와 최소 20분 동안 아이 말고 다른 이야기를 나눠 보세요. 두 사람은 부부이기도 하니까요.', title_nl = 'Tijd voor jullie tweeën 🥂', body_nl = 'Hij slaapt. Leg het huishouden nu opzij. Praat minstens 20 minuten met je partner over iets anders dan de kinderen. Jullie zijn ook nog een stel.', title_pl = 'Przerwa dla was dwojga 🥂', body_pl = 'Dziecko śpi. Teraz odłóż obowiązki domowe. Porozmawiaj z partnerem przez co najmniej 20 minut na dowolny temat poza dzieckiem. Jesteście też parą.', title_pt = 'Pausa a dois 🥂', body_pt = 'A criança adormeceu. Agora ponha de lado as tarefas de casa. Converse com o seu companheiro pelo menos 20 minutos sobre qualquer assunto que não seja a criança. Também são um casal.', title_sv = 'Paus för er två 🥂', body_sv = 'Barnet sover. Lägg nu undan hushållet. Prata med din partner i minst 20 minuter om något annat än barnet. Ni är också ett par.', title_vi = 'Phút nghỉ của hai vợ chồng 🥂', body_vi = 'Bé ngủ rồi. Giờ hãy gác việc nhà sang một bên. Trò chuyện với chồng ít nhất 20 phút về bất kỳ chủ đề nào ngoài con cái. Hai người còn là một cặp đôi nữa.', title_zh = '夫妻小憩 🥂', body_zh = '孩子睡着了。现在把家务放到一边。和另一半至少聊20分钟孩子以外的话题。你们同时也是一对伴侣。' WHERE id = '115c548f-9326-4a38-a159-3195407d360e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ya camina, pero a veces gatea rápido para escaparse de ti por diversión? Quita los obstáculos peligrosos de la habitación y únete tú también al juego del pilla-pilla.', body_fr = 'Il marche déjà, mais il lui arrive de repartir à quatre pattes à toute vitesse pour vous échapper en s''amusant ? Retirez les obstacles dangereux de la pièce et jouez, vous aussi, au chat et à la souris.', body_hi = 'चलने के साथ-साथ कभी-कभी मज़े के लिए तेज़ी से घुटनों के बल चलकर आपसे भागता है? कमरे से खतरनाक रुकावटें हटाइए और इस पकड़म-पकड़ाई में आप भी शामिल हो जाइए।', body_id = 'Selain berjalan, kadang ia merangkak cepat untuk kabur dari Anda sambil bermain? Singkirkan rintangan berbahaya di kamar dan ikutlah bermain kejar-kejaran.', body_ja = 'もう歩けるのに、ときどき遊びでさっとはいはいして逃げていきますか？部屋の危ないものを片づけて、あなたもこの追いかけっこに加わりましょう。', body_ko = '이제 걷는데도 가끔 재미로 빠르게 기어서 도망가나요? 방의 위험한 장애물을 치우고 엄마도 이 술래잡기에 함께해 보세요.', body_nl = 'Loopt hij al, maar kruipt hij soms voor de lol razendsnel bij je weg? Ruim gevaarlijke obstakels in de kamer op en doe mee met dit tikkertje.', body_pl = 'Choć już chodzi, czasem dla zabawy szybko raczkuje i przed tobą ucieka? Usuń z pokoju niebezpieczne przeszkody i dołącz do tej zabawy w berka.', body_pt = 'Além de andar, às vezes gatinha depressa para fugir de si, por brincadeira? Retire os obstáculos perigosos do quarto e entre também nesta brincadeira da apanhada.', body_sv = 'Går barnet redan men kryper ibland snabbt iväg från dig för skojs skull? Plocka bort farliga hinder i rummet och var med i tafattleken du också.', body_vi = 'Đã biết đi nhưng đôi khi bé vẫn bò thật nhanh để "trốn" mẹ cho vui? Hãy dọn những vật cản nguy hiểm trong phòng và cùng tham gia trò đuổi bắt này nhé.', body_zh = '已经会走了，有时却为了好玩飞快地爬着躲开你？收起房间里危险的障碍物，你也加入这场“你追我跑”的游戏吧。' WHERE id = '91f7fb7e-2bab-481e-816b-6e91267f93ae' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora offline para mamá ☕', body_es = 'Mientras está absorto jugando en su mundo, no corras al lavavajillas. Sírvete un té caliente, deja el móvil a un lado y desconecta 15 minutos sin pensar en nada.', title_fr = 'Une heure hors ligne pour maman ☕', body_fr = 'Quand il est plongé dans son monde et joue, ne foncez pas vers le lave-vaisselle. Servez-vous un thé chaud, posez le téléphone et déconnectez 15 minutes sans penser à rien.', title_hi = 'माँ का ऑफ़लाइन घंटा ☕', body_hi = 'बच्चा अपनी दुनिया में खोकर खेल रहा है तो तुरंत बर्तन धोने मत भागिए। अपने लिए गर्म चाय बनाइए, फ़ोन एक तरफ़ रखिए और 15 मिनट बिना कुछ सोचे ऑफ़लाइन रहिए।', title_id = 'Jam offline untuk Ibu ☕', body_id = 'Saat anak asyik bermain di dunianya sendiri, jangan langsung lari ke bak cuci piring. Tuang teh hangat untuk diri Anda, letakkan ponsel, dan offline-lah selama 15 menit tanpa memikirkan apa pun.', title_ja = 'ママのオフライン時間 ☕', body_ja = 'お子さんが自分の世界に夢中で遊んでいるとき、すぐに食器洗いに走らないで。温かいお茶をいれて、スマホを置き、15分間なにも考えずにオフラインになりましょう。', title_ko = '엄마를 위한 오프라인 시간 ☕', body_ko = '아이가 자기 세상에 빠져 놀 때 바로 설거지하러 가지 마세요. 따뜻한 차를 따르고 휴대폰을 내려놓은 채 15분 동안 아무 생각 없이 오프라인이 되어 보세요.', title_nl = 'Offline uurtje voor mama ☕', body_nl = 'Ren niet meteen naar de vaatwasser als hij opgaat in zijn spel. Schenk jezelf een warme thee in, leg je telefoon weg en ben 15 minuten offline zonder ergens aan te denken.', title_pl = 'Godzina offline dla mamy ☕', body_pl = 'Gdy dziecko zatopi się w swojej zabawie, nie biegnij od razu do zmywarki. Nalej sobie ciepłej herbaty, odłóż telefon i przez 15 minut bądź offline, o niczym nie myśląc.', title_pt = 'Hora offline para a mãe ☕', body_pt = 'Quando a criança está mergulhada no seu mundo a brincar, não corra logo para a máquina da loiça. Sirva-se de um chá quente, ponha o telemóvel de lado e fique 15 minutos offline sem pensar em nada.', title_sv = 'Offline-timme för mamma ☕', body_sv = 'Rusa inte till diskmaskinen när barnet är försjunket i sin lek. Häll upp en kopp varmt te, lägg undan mobilen och var offline i 15 minuter utan att tänka på något.', title_vi = 'Giờ offline của mẹ ☕', body_vi = 'Khi bé đắm chìm trong thế giới trò chơi của mình, đừng vội lao đến bồn rửa bát. Hãy rót cho mình một tách trà nóng, cất điện thoại và offline 15 phút không nghĩ ngợi gì.', title_zh = '妈妈的离线时间 ☕', body_zh = '孩子沉浸在自己的世界里玩的时候，别急着去洗碗。给自己倒杯热茶，把手机放到一边，什么都不想，离线15分钟。' WHERE id = 'ca59c65d-2643-4f9a-b7e1-efbf69908275' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Está pálido o sin apetito? Comprueba el hierro de hoy en el Seguimiento de tomas y, junto con la carne, dale siempre ensalada con mucho limón para mejorar la absorción.', body_fr = 'Il a le teint pâle ou peu d''appétit ? Vérifiez ses apports en fer du jour dans le Suivi des repas et servez toujours une salade bien citronnée avec la viande pour mieux l''absorber.', body_hi = 'चेहरा पीला है या भूख नहीं लगती? फ़ीडिंग ट्रैकर में आज का आयरन देखिए और मांस के साथ नींबू वाला सलाद ज़रूर दीजिए ताकि आयरन बेहतर तरीके से अवशोषित हो।', body_id = 'Ia tampak pucat atau tidak berselera makan? Periksa asupan zat besi hari ini di Pemantau Nutrisi dan selalu sajikan daging bersama salad dengan banyak perasan lemon untuk meningkatkan penyerapan.', body_ja = '顔色が悪かったり、食欲がなかったりしますか？「栄養管理ツール」で今日の鉄分摂取を確認し、お肉と一緒にレモンをたっぷりかけたサラダを出して吸収を高めましょう。', body_ko = '얼굴이 창백하거나 입맛이 없나요? 수유 기록 도구로 오늘의 철분 섭취를 확인하고, 고기와 함께 레몬을 듬뿍 뿌린 샐러드를 꼭 곁들여 흡수를 높여 주세요.', body_nl = 'Ziet hij bleek of heeft hij weinig trek? Bekijk in de Voedingstracker het ijzer van vandaag en geef bij vlees altijd een salade met veel citroen om de opname te verbeteren.', body_pl = 'Jest blady albo nie ma apetytu? Sprawdź dzisiejsze spożycie żelaza w narzędziu do śledzenia karmienia i do mięsa koniecznie podawaj sałatkę z dużą ilością cytryny, by poprawić wchłanianie.', body_pt = 'Está pálido ou sem apetite? Verifique a ingestão de ferro de hoje no Registo de Alimentação e, junto com a carne, sirva sempre uma salada com bastante limão para melhorar a absorção.', body_sv = 'Är barnet blekt eller utan aptit? Kolla dagens järnintag i Matningskoll och servera alltid en sallad med mycket citron till köttet för att öka upptaget.', body_vi = 'Bé xanh xao hoặc biếng ăn? Hãy kiểm tra lượng sắt hôm nay trong Theo dõi cữ bú và để tăng hấp thu, nhất định cho bé ăn thịt kèm salad có nhiều nước cốt chanh.', body_zh = '脸色苍白或没胃口？在喂养记录工具里查看今天的铁摄入，搭配肉类时一定要配上多挤柠檬汁的沙拉，提高吸收。' WHERE id = '79665648-b787-4a1e-b120-da8384605658' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares nocturnos 🌌', body_es = '¿Se despierta llorando en mitad de la noche y no se calma? Echa un vistazo al Blog para entender la diferencia entre terrores nocturnos y pesadillas y cómo actuar bien a nivel psicológico.', title_fr = 'Réveils nocturnes 🌌', body_fr = 'Il se réveille en pleurant en pleine nuit et ne se calme pas ? Parcourez les Blogs pour comprendre la différence entre terreur nocturne et cauchemar, et réagir de la bonne façon.', title_hi = 'रात में जागना 🌌', body_hi = 'आधी रात को रोते हुए जागता है और शांत नहीं होता? नाइट टेरर और बुरे सपने का फ़र्क समझने और सही तरीके से संभालने के लिए ब्लॉग सेक्शन देखिए।', title_id = 'Terbangun malam hari 🌌', body_id = 'Ia terbangun tengah malam sambil menangis dan sulit ditenangkan? Kunjungi bagian Blog untuk memahami beda teror malam dan mimpi buruk, serta cara menanganinya secara psikologis dengan tepat.', title_ja = '夜中の目覚め 🌌', body_ja = '夜中に泣いて目を覚まし、なかなか落ち着かない？夜驚症と悪夢の違いを知り、正しく心のケアをするために、ブログをのぞいてみましょう。', title_ko = '밤에 깨요 🌌', body_ko = '한밤중에 울며 깨서 달래지지 않나요? 야경증과 악몽의 차이를 알고 올바르게 심리적으로 대처하려면 블로그 섹션을 살펴보세요.', title_nl = 'Nachtelijk wakker worden 🌌', body_nl = 'Wordt hij midden in de nacht huilend wakker en is hij niet te troosten? Lees in Blogs het verschil tussen nachtangst en een nachtmerrie en hoe je hem goed kunt helpen.', title_pl = 'Nocne pobudki 🌌', body_pl = 'Budzi się w nocy z płaczem i nie daje się uspokoić? Zajrzyj do sekcji Blog, by zrozumieć różnicę między lękiem nocnym a koszmarem i właściwie zareagować od strony psychologicznej.', title_pt = 'Despertares noturnos 🌌', body_pt = 'Acorda a meio da noite a chorar e não se acalma? Consulte o Blogue para perceber a diferença entre terror noturno e pesadelo e saber como intervir da forma certa.', title_sv = 'Nattliga uppvaknanden 🌌', body_sv = 'Vaknar barnet gråtande mitt i natten och lugnar sig inte? Titta i avsnittet Bloggar för att förstå skillnaden mellan nattskräck och mardrömmar och hur du bemöter dem rätt.', title_vi = 'Thức giấc ban đêm 🌌', body_vi = 'Bé khóc thét thức giấc giữa đêm và không dịu lại? Hãy xem mục Blog để hiểu sự khác nhau giữa hoảng sợ ban đêm và ác mộng, cũng như cách hỗ trợ tâm lý đúng đắn.', title_zh = '夜间醒来 🌌', body_zh = '半夜哭醒，怎么也安抚不下来？去博客板块看看，了解夜惊和噩梦的区别，学会正确的心理安抚方法。' WHERE id = 'a55553fe-9a49-45fa-b5bb-ccf86cdd6fc8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El arte de dibujar círculos! 🎨', body_es = '¿Intenta dibujar círculos cerrados con el lápiz en el papel (¡o en la pared!)? Es un salto enorme en su motricidad.', title_fr = 'L''art de tracer des cercles ! 🎨', body_fr = 'Il essaie de tracer des cercles fermés au crayon sur une feuille (ou sur le mur !) ? C''est un superbe bond de motricité.', title_hi = 'गोला बनाने की कला! 🎨', body_hi = 'पेन से कागज़ पर (या दीवार पर!) बंद गोले बनाने की कोशिश करता है? यह मोटर स्किल्स में शानदार छलांग है।', title_id = 'Seni menggambar lingkaran! 🎨', body_id = 'Ia mencoba menggambar lingkaran tertutup dengan pensil di kertas (atau di dinding!)? Ini lompatan motorik yang luar biasa.', title_ja = 'まるを描くアート！🎨', body_ja = 'クレヨンで紙に（または壁に！）閉じたまるを描こうとしていますか？これは運動能力のすばらしい飛躍です。', title_ko = '동그라미 그리기 기술! 🎨', body_ko = '종이에(또는 벽에!) 연필로 닫힌 동그라미를 그리려고 하나요? 소근육 발달의 멋진 도약이에요.', title_nl = 'De kunst van rondjes tekenen! 🎨', body_nl = 'Probeert hij met een potlood gesloten rondjes op papier (of de muur!) te tekenen? Een prachtige sprong in de fijne motoriek.', title_pl = 'Sztuka rysowania kółek! 🎨', body_pl = 'Próbuje rysować kredką zamknięte kółka na papierze (albo na ścianie!)? To wspaniały skok w motoryce.', title_pt = 'A arte de desenhar círculos! 🎨', body_pt = 'Tenta desenhar círculos fechados com o lápis no papel (ou na parede!)? É um grande salto na motricidade.', title_sv = 'Konsten att rita cirklar! 🎨', body_sv = 'Försöker barnet rita slutna cirklar med pennan på papper (eller på väggen!)? Det är ett fantastiskt motoriskt språng.', title_vi = 'Nghệ thuật vẽ vòng tròn! 🎨', body_vi = 'Bé cố vẽ những vòng tròn khép kín bằng bút trên giấy (hoặc trên tường!)? Đây là một bước nhảy vọt tuyệt vời về kỹ năng vận động.', title_zh = '画圆的艺术！🎨', body_zh = '拿着笔在纸上（或者墙上！）努力画封闭的圆圈？这是精细动作的一大飞跃。' WHERE id = 'f582b213-b9d3-463a-9b65-bba1181ecabf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charlas en susurros 🌙', body_es = 'Apaga del todo las luces de la habitación. Túmbate a su lado y cuéntale en voz muy bajita, susurrando, lo que ha pasado durante el día. Susurrar es la forma más relajante de preparar el cerebro para dormir.', title_fr = 'Conversations chuchotées 🌙', body_fr = 'Éteignez toutes les lumières de la chambre. Allongez-vous près de lui et racontez sa journée tout bas, en chuchotant. Le chuchotement est la façon la plus apaisante de préparer le cerveau au sommeil.', title_hi = 'फुसफुसाती बातें 🌙', body_hi = 'कमरे की सारी लाइटें बंद कर दीजिए। उसके पास लेटकर दिनभर की बातें बहुत धीमी आवाज़ में, फुसफुसाकर सुनाइए। फुसफुसाहट दिमाग को नींद के लिए तैयार करने का सबसे सुकून भरा तरीका है।', title_id = 'Obrolan berbisik 🌙', body_id = 'Matikan semua lampu kamar. Berbaringlah di sampingnya dan ceritakan kejadian hari ini dengan suara sangat pelan, berbisik. Berbisik adalah cara paling menenangkan untuk menyiapkan otak tidur.', title_ja = 'ささやき声のおしゃべり 🌙', body_ja = '部屋の明かりをすべて消しましょう。そばに横になって、今日あったことをとても小さな声でささやくように話してあげて。ささやき声は、脳を眠りへ導くいちばん心落ち着く方法です。', title_ko = '속삭이는 대화 🌙', body_ko = '방의 불을 모두 꺼 주세요. 옆에 누워 오늘 있었던 일을 아주 작은 목소리로 속삭여 주세요. 속삭임은 뇌가 잠들 준비를 하게 돕는 가장 차분한 방법이에요.', title_nl = 'Fluistergesprekjes 🌙', body_nl = 'Doe alle lichten in de kamer uit. Ga naast hem liggen en vertel heel zachtjes, fluisterend, wat er vandaag is gebeurd. Fluisteren is de meest rustgevende manier om de hersenen klaar te maken voor de slaap.', title_pl = 'Rozmowy szeptem 🌙', body_pl = 'Zgaś wszystkie światła w pokoju. Połóż się obok i bardzo cicho, szeptem opowiedz, co wydarzyło się w ciągu dnia. Szept to najbardziej uspokajający sposób, by przygotować mózg do snu.', title_pt = 'Conversas em sussurro 🌙', body_pt = 'Apague todas as luzes do quarto. Deite-se ao lado dele e conte-lhe, em voz muito baixa e a sussurrar, o que aconteceu durante o dia. Sussurrar é a forma mais calmante de preparar o cérebro para o sono.', title_sv = 'Viskande samtal 🌙', body_sv = 'Släck alla lampor i rummet. Lägg dig bredvid barnet och berätta mycket tyst, viskande, om det som hänt under dagen. Viskningar är det mest lugnande sättet att förbereda hjärnan för sömn.', title_vi = 'Những cuộc trò chuyện thì thầm 🌙', body_vi = 'Hãy tắt hết đèn trong phòng. Nằm cạnh bé và thì thầm thật khẽ kể về những gì đã xảy ra trong ngày. Thì thầm là cách êm dịu nhất giúp não bộ chuẩn bị cho giấc ngủ.', title_zh = '悄悄话时间 🌙', body_zh = '把房间的灯全部关掉。躺在宝宝身边，用很轻很轻的声音悄悄讲讲今天发生的事。悄悄话是帮大脑准备入睡最能让人平静的方式。' WHERE id = '53f1873b-90e8-4dcd-884c-7bbec73835df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Días sin dolor 🩸', body_es = '¿Se acerca tu regla y han empezado los calambres? Antes de recurrir a los medicamentos, cuídate preparando en Recetas saludables un tentempié de dátiles y nueces rico en magnesio.', title_fr = 'Des jours sans douleur 🩸', body_fr = 'Vos règles approchent et les crampes ont commencé ? Avant de vous jeter sur les médicaments, préparez une collation dattes-noix riche en magnésium avec les Recettes saines et prenez soin de vous.', title_hi = 'दर्द से राहत वाले दिन 🩸', body_hi = 'पीरियड करीब है और ऐंठन शुरू हो गई? दवाओं की ओर भागने से पहले सेहतमंद रेसिपी से मैग्नीशियम से भरपूर खजूर-अखरोट वाला स्नैक बनाइए और अपना ख्याल रखिए।', title_id = 'Hari-hari tanpa nyeri 🩸', body_id = 'Haid sudah dekat dan kram mulai terasa? Sebelum buru-buru minum obat, rawat diri Anda dengan camilan kurma dan kenari kaya magnesium dari Resep Sehat.', title_ja = '痛みのない日々 🩸', body_ja = '生理が近づいて、腹痛が始まりましたか？薬にたよる前に、「ヘルシーレシピ」からマグネシウムたっぷりのデーツとくるみのおやつをつくって、自分をいたわりましょう。', title_ko = '통증 없는 날 🩸', body_ko = '생리가 다가오고 생리통이 시작됐나요? 진통제를 찾기 전에 건강한 레시피에서 마그네슘이 풍부한 대추야자 호두 간식을 만들어 나를 돌봐 주세요.', title_nl = 'Dagen zonder pijn 🩸', body_nl = 'Komt je menstruatie eraan en zijn de krampen begonnen? Grijp niet meteen naar medicijnen, maar maak uit Gezonde recepten een magnesiumrijk tussendoortje met dadels en walnoten en zorg goed voor jezelf.', title_pl = 'Dni bez bólu 🩸', body_pl = 'Zbliża się okres i zaczęły się skurcze? Zanim sięgniesz po leki, przygotuj ze Zdrowych przepisów przekąskę z daktylami i orzechami bogatą w magnez i zadbaj o siebie.', title_pt = 'Dias sem dor 🩸', body_pt = 'O período está a chegar e as cólicas já começaram? Antes de recorrer a medicamentos, cuide de si com um snack de tâmaras e nozes rico em magnésio das Receitas Saudáveis.', title_sv = 'Dagar utan smärta 🩸', body_sv = 'Närmar sig mensen och krampen har börjat? Innan du tar till medicin, ta hand om dig med ett magnesiumrikt mellanmål med dadlar och valnötter från Hälsosamma recept.', title_vi = 'Những ngày không đau 🩸', body_vi = 'Kỳ kinh sắp đến và bắt đầu đau bụng? Trước khi tìm đến thuốc, hãy làm món ăn vặt chà là và óc chó giàu magie từ Công thức lành mạnh để chăm sóc bản thân.', title_zh = '无痛的日子 🩸', body_zh = '经期快到了，开始痉挛？吃药之前，先从健康食谱里做一份富含镁的椰枣核桃小零食，好好照顾自己。' WHERE id = '67fb000b-9452-4ae5-aa28-3a36f345f54a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Contar con los dedos 🔢', body_es = '¿Al subir escaleras o colocar sus juguetes intenta decir «uno, dos, tres»? Despierta su lógica matemática. Contad juntos en voz alta los objetos de la habitación.', title_fr = 'Compter sur ses doigts 🔢', body_fr = 'En montant l''escalier ou en rangeant ses jouets, il essaie de dire « un, deux, trois » ? Sa logique mathématique s''éveille. Comptez à voix haute avec lui les objets de la pièce.', title_hi = 'उँगलियों पर गिनती 🔢', body_hi = 'सीढ़ियाँ चढ़ते या खिलौने सजाते समय ''एक, दो, तीन'' कहने की कोशिश करता है? गणित वाली सोच जाग रही है। उसके साथ मिलकर कमरे की चीज़ें ज़ोर से गिनिए।', title_id = 'Berhitung dengan jari 🔢', body_id = 'Saat naik tangga atau menyusun mainannya, ia mencoba bilang ''satu, dua, tiga''? Logika matematikanya mulai bangun. Hitunglah benda-benda di kamar bersamanya dengan suara keras.', title_ja = '指で数える 🔢', body_ja = '階段を上るときやおもちゃを並べるとき、「いち、に、さん」と言おうとしますか？数の論理が目覚めています。一緒に部屋のものを声に出して数えましょう。', title_ko = '손가락으로 세기 🔢', body_ko = '계단을 오르거나 장난감을 늘어놓을 때 ''하나, 둘, 셋''을 말하려고 하나요? 수학적 사고가 깨어나고 있어요. 방 안의 물건을 함께 소리 내어 세어 보세요.', title_nl = 'Tellen op je vingers 🔢', body_nl = 'Probeert hij ''één, twee, drie'' te zeggen als hij de trap op gaat of zijn speelgoed op een rij zet? Zijn wiskundige logica ontwaakt. Tel samen hardop de dingen in de kamer.', title_pl = 'Liczenie na palcach 🔢', body_pl = 'Wchodząc po schodach albo układając zabawki, próbuje mówić „raz, dwa, trzy”? Budzi się logika matematyczna. Liczcie razem na głos przedmioty w pokoju.', title_pt = 'Contar pelos dedos 🔢', body_pt = 'Ao subir as escadas ou arrumar os brinquedos, tenta dizer "um, dois, três"? A lógica matemática está a despertar. Contem juntos, em voz alta, os objetos do quarto.', title_sv = 'Räkna på fingrarna 🔢', body_sv = 'Försöker barnet säga ett, två, tre när hen går i trappan eller radar upp leksakerna? Den matematiska logiken vaknar. Räkna sakerna i rummet högt tillsammans.', title_vi = 'Đếm bằng ngón tay 🔢', body_vi = 'Khi leo cầu thang hay xếp đồ chơi, bé cố nói "một, hai, ba"? Tư duy toán học đang thức tỉnh. Hãy cùng bé đếm to các đồ vật trong phòng.', title_zh = '掰着手指数数 🔢', body_zh = '爬楼梯或摆玩具时，努力说“一、二、三”？数学逻辑正在苏醒。和宝宝一起大声数数房间里的东西吧。' WHERE id = 'f0ddb044-981f-4758-9737-12aa24392d50' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Tanto ajetreo te ha dejado sin fuerzas. En lugar de picar algo de pie, prepárate un plato especial, saciante y rico en calcio, y cómelo con gusto.', body_fr = 'Cette course permanente vous a vidée. Au lieu de grignoter debout, préparez-vous une assiette spéciale, rassasiante et riche en calcium, et savourez-la.', body_hi = 'भागदौड़ ने आपको थका दिया है। खड़े-खड़े कुछ भी खा लेने के बजाय अपने लिए पेट भरने वाली, कैल्शियम से भरपूर एक खास थाली बनाइए और मज़े से खाइए।', body_id = 'Kesibukan membuat Anda kehabisan tenaga. Daripada makan sambil berdiri, siapkan sepiring makanan khusus yang mengenyangkan dan kaya kalsium untuk diri Anda, lalu nikmati.', body_ja = 'バタバタ続きでくたくたですね。立ったままつまむかわりに、自分のためにカルシウムたっぷりの満足できるひと皿を用意して、味わって食べましょう。', body_ko = '정신없이 뛰어다니느라 기운이 다 빠졌죠. 서서 대충 먹는 대신 나만을 위한 든든하고 칼슘 가득한 한 접시를 차려 맛있게 드세요.', body_nl = 'Het gerace heeft je uitgeput. Eet niet staand even snel iets, maar maak voor jezelf een speciaal, voedzaam en calciumrijk bord klaar en geniet ervan.', body_pl = 'Bieganina odebrała ci siły. Zamiast jeść coś na stojąco, przygotuj sobie sycący talerz bogaty w wapń i zjedz go z przyjemnością.', body_pt = 'A correria deixou-a sem forças. Em vez de petiscar de pé, prepare para si um prato especial, saciante e rico em cálcio, e coma com prazer.', body_sv = 'Allt springande har gjort dig helt slut. I stället för att småäta stående, gör en mättande, kalciumrik tallrik åt dig själv och ät med njutning.', body_vi = 'Chạy tới chạy lui khiến mẹ kiệt sức. Thay vì ăn vội đứng một chỗ, hãy chuẩn bị cho mình một đĩa ăn no bụng, giàu canxi và thưởng thức thật ngon miệng.', body_zh = '忙得团团转，累坏了吧。别站着随便吃两口，为自己准备一盘丰盛、富含钙的饭菜，好好享受吧。' WHERE id = '841fa22f-136a-48a1-b594-4a69eafbc030' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las caras graciosas de papá 🤡', body_es = 'La forma más rápida de hacer reír al bebé es que papá haga sonidos raros y muecas. Escucha las alegres carcajadas de esta noche y sonríe tú también en segundo plano.', title_fr = 'Les grimaces de papa 🤡', body_fr = 'Le moyen le plus rapide de faire rire bébé : papa qui fait des bruits et des grimaces bizarres. Écoutez les éclats de rire de ce soir et souriez, vous aussi, en coulisses.', title_hi = 'पापा का मज़ेदार चेहरा 🤡', body_hi = 'बच्चे को हँसाने का सबसे तेज़ तरीका है पापा की अजीब आवाज़ें और मज़ेदार चेहरे। आज शाम की खिलखिलाहट सुनिए और पीछे से आप भी मुस्कुराइए।', title_id = 'Wajah lucu Ayah 🤡', body_id = 'Cara tercepat membuat bayi tertawa adalah Ayah membuat suara dan ekspresi wajah yang lucu. Dengarkan tawa riang malam ini dan ikut tersenyum dari belakang.', title_ja = 'パパのおもしろい顔 🤡', body_ja = '赤ちゃんをいちばん早く笑わせる方法は、パパがおもしろい声や表情をすること。今夜の楽しい笑い声に耳を傾けて、そばであなたもほほえみましょう。', title_ko = '아빠의 웃긴 표정 🤡', body_ko = '아이를 가장 빨리 웃게 하는 방법은 아빠의 웃긴 소리와 표정이에요. 오늘 저녁 즐거운 웃음소리를 들으며 엄마도 곁에서 미소 지어 보세요.', title_nl = 'Papa''s gekke gezichten 🤡', body_nl = 'De snelste manier om je baby aan het lachen te krijgen: papa die gekke geluiden en gezichten maakt. Luister vanavond naar het vrolijke gegiechel en glimlach op de achtergrond mee.', title_pl = 'Śmieszna mina taty 🤡', body_pl = 'Najszybszy sposób, by rozśmieszyć malucha, to śmieszne odgłosy i miny taty. Wsłuchaj się dziś wieczorem w te radosne chichoty i uśmiechnij się z boku.', title_pt = 'As caretas engraçadas do pai 🤡', body_pt = 'A forma mais rápida de fazer o bebé rir é o pai fazer sons e caretas engraçadas. Ouça as gargalhadas alegres desta noite e sorria também, nos bastidores.', title_sv = 'Pappas roliga ansikte 🤡', body_sv = 'Det snabbaste sättet att få barnet att skratta är när pappa gör konstiga ljud och miner. Lyssna på kvällens glada skratt och le du också i bakgrunden.', title_vi = 'Gương mặt ngộ nghĩnh của bố 🤡', body_vi = 'Cách nhanh nhất để bé bật cười là bố giả những âm thanh và biểu cảm ngộ nghĩnh. Tối nay hãy lắng nghe những tràng cười giòn tan và mỉm cười cùng từ phía sau nhé.', title_zh = '爸爸的搞笑表情 🤡', body_zh = '逗宝宝笑最快的办法，就是让爸爸发出怪声音、做鬼脸。今晚听着这欢快的笑声，你也在一旁笑一笑吧。' WHERE id = '98be6947-c839-4cba-807a-2d0a7d2db4bd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La energía matutina de mamá ⚡', body_es = '¿Te has despertado cansada? No recurras al azúcar. Descubre en Recetas saludables una avena con proteínas y fruta que se prepara en 5 minutos y empieza el día con fuerza.', title_fr = 'L''énergie du matin de maman ⚡', body_fr = 'Réveillée fatiguée ? Ne vous jetez pas sur le sucre. Découvrez dans les Recettes saines un porridge protéiné aux fruits prêt en 5 minutes et commencez la journée en forme.', title_hi = 'माँ की सुबह की ऊर्जा ⚡', body_hi = 'सुबह थकी हुई उठीं? मीठे की ओर मत भागिए। सेहतमंद रेसिपी से 5 मिनट में बनने वाले प्रोटीन और फलों से भरे ओट्स आज़माइए और दिन की दमदार शुरुआत कीजिए।', title_id = 'Energi pagi Ibu ⚡', body_id = 'Bangun pagi dengan lelah? Jangan lari ke gula. Temukan oat berprotein dengan buah yang siap dalam 5 menit di Resep Sehat dan mulai hari dengan kuat.', title_ja = 'ママの朝のエネルギー ⚡', body_ja = '朝から疲れて目が覚めましたか？甘いものに手を伸ばさないで。「ヘルシーレシピ」から5分でできる、たんぱく質とフルーツたっぷりのオートミールを見つけて、元気に一日を始めましょう。', title_ko = '엄마의 아침 에너지 ⚡', body_ko = '피곤하게 일어났나요? 단 음식으로 달려가지 마세요. 건강한 레시피에서 5분이면 만드는 단백질 과일 오트밀을 찾아 힘차게 하루를 시작하세요.', title_nl = 'Ochtendenergie voor mama ⚡', body_nl = 'Moe wakker geworden? Grijp niet naar suiker. Ontdek in Gezonde recepten havermout met eiwitten en fruit, klaar in 5 minuten, en begin de dag sterk.', title_pl = 'Poranna energia mamy ⚡', body_pl = 'Obudziłaś się zmęczona? Nie sięgaj po cukier. Odkryj w Zdrowych przepisach owsiankę z białkiem i owocami gotową w 5 minut i zacznij dzień z mocą.', title_pt = 'A energia matinal da mãe ⚡', body_pt = 'Acordou cansada? Não recorra ao açúcar. Descubra nas Receitas Saudáveis uma papa de aveia com proteína e fruta que se prepara em 5 minutos e comece o dia com força.', title_sv = 'Mammas morgonenergi ⚡', body_sv = 'Vaknade du trött? Ta inte till sockret. Upptäck proteinrik havregrynsgröt med frukt som är klar på 5 minuter i Hälsosamma recept och börja dagen starkt.', title_vi = 'Năng lượng buổi sáng của mẹ ⚡', body_vi = 'Sáng nay thức dậy mệt mỏi? Đừng tìm đến đồ ngọt. Hãy khám phá món yến mạch giàu đạm với trái cây làm trong 5 phút từ Công thức lành mạnh và bắt đầu ngày mới thật mạnh mẽ.', title_zh = '妈妈的晨间能量 ⚡', body_zh = '早上醒来就很累？别急着吃甜食。从健康食谱里找一款5分钟就能做好的高蛋白水果燕麦，充满力量地开始新的一天。' WHERE id = '9c1b9283-eb25-42f4-8927-c54192637c35' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta el apoyo de papá 🫂', body_es = '¿Según el Calendario menstrual estás en días de SPM y te sientes sensible? Con la función Pareja, dile que hoy necesitas un poco más de apoyo.', title_fr = 'Besoin du soutien de papa 🫂', body_fr = 'Le Suivi des règles indique vos jours de SPM et vous êtes à fleur de peau ? Avec le mode Partenaire, faites-lui savoir qu''aujourd''hui vous avez besoin d''un peu plus de soutien.', title_hi = 'पापा का साथ चाहिए 🫂', body_hi = 'पीरियड ट्रैकर के हिसाब से PMS के दिन चल रहे हैं और आप संवेदनशील हैं? पार्टनर फ़ीचर से उन्हें बताइए कि आज आपको थोड़े ज़्यादा सहारे की ज़रूरत है।', title_id = 'Butuh dukungan Ayah 🫂', body_id = 'Di Pelacak Menstruasi Anda sedang di hari-hari PMS dan lebih sensitif? Beri tahu pasangan lewat mode Pasangan bahwa hari ini Anda butuh sedikit lebih banyak dukungan.', title_ja = 'パパのサポートが必要 🫂', body_ja = '「生理トラッカー」でPMSの時期に入っていて、気持ちが敏感になっていますか？「パートナーモード」で、今日はいつもより少し多めのサポートが必要だと伝えましょう。', title_ko = '아빠의 응원이 필요해요 🫂', body_ko = '생리 주기 기록을 보니 PMS 기간이라 예민해졌나요? 파트너 모드로 오늘은 조금 더 도움이 필요하다고 배우자에게 알려 주세요.', title_nl = 'Steun van papa is nodig 🫂', body_nl = 'Zit je volgens de Cyclustracker in je PMS-dagen en ben je gevoelig? Laat je partner via Partnermodus weten dat je vandaag wat extra steun nodig hebt.', title_pl = 'Potrzebne wsparcie taty 🫂', body_pl = 'Kalendarz miesiączkowy pokazuje dni PMS i jesteś bardziej wrażliwa? Daj partnerowi znać przez funkcję Partnera, że dziś potrzebujesz trochę więcej wsparcia.', title_pt = 'O apoio do pai faz falta 🫂', body_pt = 'Segundo o Registo do Período, está nos dias de TPM e mais sensível? Use o Modo Parceiro para lhe dizer que hoje precisa de um pouco mais de apoio.', title_sv = 'Pappas stöd behövs 🫂', body_sv = 'Är du i dina PMS-dagar enligt Mensspåraren och känner dig känslig? Låt din partner veta via Partnerläget att du behöver lite mer stöd i dag.', title_vi = 'Mẹ cần bố hỗ trợ 🫂', body_vi = 'Theo Theo dõi kỳ kinh, mẹ đang trong những ngày tiền kinh nguyệt và dễ nhạy cảm? Hãy dùng Chế độ đối tác để cho chồng biết hôm nay mẹ cần được hỗ trợ nhiều hơn một chút.', title_zh = '需要爸爸的支持 🫂', body_zh = '经期记录显示你正处在经前期，情绪敏感？用伴侣功能告诉他，你今天需要多一点支持。' WHERE id = '1868bb46-a550-4249-8524-2b40ecd9cad3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche convierte la habitación en un parque de juegos. Construid un pequeño castillo con los cojines del sofá y meteos dentro. Habrá algo de desorden, pero esas risas lo valen sin duda.', body_fr = 'Ce soir, transformez la chambre en terrain de jeu. Construisez un petit fort avec les coussins du canapé et glissez-vous dedans. Il y aura un peu de désordre, mais ces éclats de rire en valent vraiment la peine.', body_hi = 'आज शाम कमरे को खेल का मैदान बना दीजिए। सोफ़े के कुशन से एक छोटा सा किला बनाइए और अंदर घुस जाइए। थोड़ा बिखराव होगा, लेकिन ये खिलखिलाहटें इसके लायक हैं।', body_id = 'Malam ini ubah kamar menjadi taman bermain. Buat benteng kecil dari bantal sofa dan masuklah ke dalamnya. Akan sedikit berantakan, tetapi tawa riang ini pasti sepadan.', body_ja = '今夜は部屋を遊び場に変えましょう。ソファのクッションで小さなお城を作って、中にもぐりこんで。少し散らかりますが、楽しい笑い声のためなら絶対にその価値があります。', body_ko = '오늘 저녁엔 방을 놀이터로 바꿔 보세요. 소파 쿠션으로 작은 성을 쌓고 그 안에 들어가 보세요. 조금 어질러지겠지만 즐거운 웃음소리는 그럴 가치가 충분해요.', body_nl = 'Maak van de kamer vanavond een speeltuin. Bouw een klein fort van bankkussens en kruip erin. Het wordt een beetje een rommeltje, maar dat vrolijke gelach is het zeker waard.', body_pl = 'Dziś wieczorem zamień pokój w plac zabaw. Zbudujcie małą fortecę z poduszek z kanapy i schowajcie się w środku. Będzie trochę bałaganu, ale te radosne śmiechy są tego warte.', body_pt = 'Esta noite, transforme o quarto num parque infantil. Construam um pequeno forte com as almofadas do sofá e entrem lá para dentro. Vai haver alguma desarrumação, mas estas gargalhadas valem bem a pena.', body_sv = 'Gör rummet till en lekplats i kväll. Bygg en liten borg av soffkuddar och kryp in. Det blir lite stök, men de glada skratten är absolut värda det.', body_vi = 'Tối nay hãy biến căn phòng thành sân chơi. Dùng gối sofa dựng một tòa lâu đài nhỏ rồi cùng chui vào. Sẽ hơi bừa một chút, nhưng những tràng cười vui vẻ chắc chắn rất xứng đáng.', body_zh = '今晚把房间变成游乐场吧。用沙发靠垫搭一座小城堡，一起钻进去。会有点乱，但这些欢笑绝对值得。' WHERE id = '5efae0dc-5ddd-4ac1-9526-ddfa449ec612' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Negocia como un abogado 🗣️', body_es = '¿Te dice «Juego un poco más y luego me visto»? Ya intenta negociar contigo como un profesional. Su lenguaje va genial, pero no olvides mantener tus límites con cariño.', title_fr = 'Il négocie comme un avocat 🗣️', body_fr = 'Il dit « Je joue encore un peu, après je m''habille » ? Il essaie déjà de négocier avec vous comme un pro. Son langage progresse très bien, mais n''oubliez pas de tenir vos limites avec amour.', title_hi = 'वकील की तरह मोलभाव 🗣️', body_hi = 'कहता है ''थोड़ा और खेल लूँ, फिर कपड़े पहनूँगा''? वह अब आपसे पेशेवर तरीके से सौदा करने की कोशिश कर रहा है। बोलने का विकास बढ़िया है, लेकिन प्यार से अपनी सीमाएँ बनाए रखना मत भूलिए।', title_id = 'Tawar-menawar ala pengacara 🗣️', body_id = 'Ia bilang ''Main sebentar lagi, nanti aku pakai baju''? Ia sudah mencoba bernegosiasi dengan Anda secara profesional. Kemampuan bicaranya hebat, tetapi jangan lupa menjaga batasan Anda dengan penuh kasih.', title_ja = '弁護士のような交渉 🗣️', body_ja = '「もうちょっと遊んだら着がえる」と言いますか？もうあなたと本格的な交渉をしようとしています。言葉の発達はすばらしいですが、愛情をもってルールを守ることも忘れずに。', title_ko = '변호사 같은 협상가 🗣️', body_ko = '''조금만 더 놀고 옷 입을게''라고 하나요? 벌써 프로처럼 협상하려는 거예요. 말하기 발달은 훌륭하지만, 경계는 사랑으로 지키는 걸 잊지 마세요.', title_nl = 'Onderhandelen als een advocaat 🗣️', body_nl = 'Zegt hij ''Nog even spelen, dan kleed ik me aan''? Hij probeert al als een prof met je te onderhandelen. Zijn spraakontwikkeling is geweldig, maar vergeet niet je grenzen liefdevol te bewaken.', title_pl = 'Targuje się jak adwokat 🗣️', body_pl = 'Mówi: „Jeszcze chwilę się pobawię, potem się ubiorę”? Już próbuje negocjować z tobą jak zawodowiec. Mowa rozwija się świetnie, ale nie zapominaj z miłością pilnować swoich granic.', title_pt = 'Negociador nato 🗣️', body_pt = 'Diz "Só mais um bocadinho a brincar e depois visto-me"? Já tenta negociar consigo como um profissional. A linguagem está ótima, mas não se esqueça de manter os seus limites com amor.', title_sv = 'Förhandlar som en advokat 🗣️', body_sv = 'Säger barnet ”Jag leker lite till, sen klär jag på mig”? Hen försöker redan göra professionella överenskommelser med dig. Talutvecklingen är toppen, men glöm inte att skydda dina gränser med kärlek.', title_vi = 'Mặc cả như luật sư 🗣️', body_vi = 'Bé nói "Con chơi thêm chút nữa rồi mới mặc đồ"? Bé đã bắt đầu thương lượng với mẹ như dân chuyên nghiệp. Khả năng nói của bé thật tuyệt, nhưng đừng quên giữ vững giới hạn bằng tình yêu thương.', title_zh = '像律师一样讨价还价 🗣️', body_zh = '说“我再玩一会儿，然后再穿衣服”？宝宝已经在试着和你专业地谈条件了。语言发展很棒，但别忘了用爱守住你的界限。' WHERE id = 'e40e4ab0-cd42-4ed7-b968-edc0adab6461' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Las cuatro paredes te agobian. Aunque haga fresco, abrígale bien y salid 20 minutos al parque. Que descubra hojas y piedras; el aire fresco os sentará bien a los dos.', body_fr = 'Les quatre murs vous étouffent. Même s''il fait frais, couvrez-le bien et sortez 20 minutes au parc. Qu''il explore les feuilles et les cailloux, l''air frais vous fera du bien à tous les deux.', body_hi = 'चार दीवारें घुटन दे रही हैं। मौसम ठंडा हो तब भी उसे अच्छे से कपड़े पहनाकर 20 मिनट के लिए पार्क ले जाइए। उसे पत्ते और पत्थर खोजने दीजिए, ताज़ी हवा आप दोनों के लिए अच्छी रहेगी।', body_id = 'Empat dinding rumah terasa menyesakkan. Meski udara sejuk, pakaikan ia baju hangat dan ajak ke taman selama 20 menit. Biarkan ia menjelajahi daun dan batu, udara segar baik untuk kalian berdua.', body_ja = '家にこもって息がつまりそう？少し肌寒くても、しっかり着こませて20分ほど公園へ出かけましょう。葉っぱや石を探検させて。新鮮な空気はふたりにとってよい効果があります。', body_ko = '네 벽에 갇힌 듯 답답하죠. 날씨가 쌀쌀해도 따뜻하게 입혀 20분 동안 공원에 나가 보세요. 나뭇잎과 돌멩이를 탐험하게 하면 맑은 공기가 두 사람 모두에게 좋을 거예요.', body_nl = 'Kruipen de muren op je af? Ook als het fris is: kleed hem warm aan en ga 20 minuten naar het park. Laat hem bladeren en steentjes ontdekken, de frisse lucht doet jullie allebei goed.', body_pl = 'Cztery ściany cię przytłaczają. Nawet jeśli jest chłodno, ubierz go ciepło i wyjdźcie na 20 minut do parku. Niech odkrywa liście i kamyki, świeże powietrze dobrze zrobi wam obojgu.', body_pt = 'As quatro paredes sufocam-na. Mesmo que esteja fresco, agasalhe-o bem e vão 20 minutos ao parque. Deixe-o explorar folhas e pedras: o ar puro vai fazer bem aos dois.', body_sv = 'De fyra väggarna kväver dig. Även om det är svalt, klä barnet ordentligt och gå till parken i 20 minuter. Låt hen upptäcka löv och stenar, den friska luften gör er båda gott.', body_vi = 'Bốn bức tường như ngột ngạt. Dù trời se lạnh, hãy mặc ấm cho bé và ra công viên 20 phút. Để bé khám phá lá cây, sỏi đá, không khí trong lành sẽ tốt cho cả hai mẹ con.', body_zh = '四面墙让人透不过气。就算天气凉，也给宝宝穿暖和，去公园走20分钟。让宝宝探索树叶和石头，新鲜空气对你们俩都有好处。' WHERE id = 'f9854a88-373e-4d4d-91e8-4e24a9ea9cba' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La emoción del «¡Te encontré!» 🙈', body_es = 'El escondite ya es su juego favorito. Se esconde detrás de la cortina y espera a que lo encuentres. Convierte este juego en el momento más divertido de vuestra rutina diaria.', title_fr = 'Le frisson du « Coucou, je t''ai trouvé ! » 🙈', body_fr = 'Cache-cache est désormais son jeu préféré. Il se cache derrière le rideau et attend que vous le trouviez. Faites de ce jeu le moment le plus amusant de votre routine.', title_hi = '''मिल गया!'' वाला रोमांच 🙈', body_hi = 'छुपन-छुपाई अब सबसे पसंदीदा खेल है। पर्दे के पीछे छिपकर इंतज़ार करता है कि आप उसे ढूँढें। इस खेल को अपने रोज़ के रूटीन का सबसे मज़ेदार हिस्सा बना लीजिए।', title_id = 'Serunya ''Ketemu!'' 🙈', body_id = 'Petak umpet kini jadi permainan favoritnya. Ia bersembunyi di balik tirai dan menunggu Anda menemukannya. Jadikan permainan ini bagian paling seru dari rutinitas harian Anda.', title_ja = '「みーつけた！」のワクワク 🙈', body_ja = 'かくれんぼが今いちばんお気に入りの遊び。カーテンの後ろに隠れて、見つけてもらうのを待っています。この遊びを毎日のルーティンのいちばん楽しい時間にしましょう。', title_ko = '''찾았다!''의 설렘 🙈', body_ko = '숨바꼭질이 가장 좋아하는 놀이가 되었어요. 커튼 뒤에 숨어 엄마가 찾아 주길 기다리죠. 이 놀이를 하루 일과 중 가장 즐거운 시간으로 만들어 보세요.', title_nl = 'De spanning van ''Gevonden!'' 🙈', body_nl = 'Verstoppertje is nu zijn favoriete spel. Hij verstopt zich achter het gordijn en wacht tot je hem vindt. Maak van dit spel het leukste stukje van jullie dagelijkse routine.', title_pl = 'Emocje „Mam cię!” 🙈', body_pl = 'Zabawa w chowanego to teraz jego ulubiona gra. Chowa się za zasłoną i czeka, aż go znajdziesz. Zrób z tej zabawy najweselszą część waszej codziennej rutyny.', title_pt = 'A emoção do "Encontrei-te!" 🙈', body_pt = 'As escondidas são agora o jogo preferido. Esconde-se atrás da cortina e espera que o encontre. Faça deste jogo a parte mais divertida da vossa rotina diária.', title_sv = 'Spänningen i ”Där är du!” 🙈', body_sv = 'Kurragömma är nu favoritleken. Barnet gömmer sig bakom gardinen och väntar på att du ska hitta hen. Gör leken till den roligaste delen av er vardag.', title_vi = 'Niềm háo hức "Tìm thấy con rồi!" 🙈', body_vi = 'Trốn tìm giờ là trò chơi yêu thích nhất của bé. Bé nấp sau rèm cửa và chờ mẹ tìm thấy. Hãy biến trò chơi này thành phần vui nhất trong nếp sinh hoạt hằng ngày.', title_zh = '“找到你啦！”的兴奋 🙈', body_zh = '躲猫猫已经是最爱的游戏了。宝宝躲在窗帘后面，等着你来找。把这个游戏变成日常里最有趣的一部分吧。' WHERE id = 'fb90f3c3-fde8-496d-b59b-6ba1236abd46' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Para que se duerma antes, apaga todas las pantallas de la habitación. La luz azul de la tele frena la hormona del sueño.', body_fr = 'Pour qu''il s''endorme plus vite, éteignez tous les écrans de la pièce. La lumière bleue de la télé freine l''hormone du sommeil.', body_hi = 'जल्दी नींद लाने के लिए कमरे की सारी स्क्रीन बंद कर दीजिए। टीवी की नीली रोशनी नींद के हार्मोन को धीमा कर देती है।', body_id = 'Agar ia lebih cepat tertidur, matikan semua layar di kamar. Cahaya biru TV memperlambat hormon tidur.', body_ja = '早く寝つけるように、部屋の画面をすべて消しましょう。テレビの青い光は、眠りのホルモンの分泌を遅らせます。', body_ko = '더 빨리 잠들 수 있도록 방의 모든 화면을 꺼 주세요. TV의 블루라이트는 수면 호르몬 분비를 늦춰요.', body_nl = 'Wil je dat hij sneller in slaap valt? Zet alle schermen in de kamer uit. Het blauwe licht van de tv remt het slaaphormoon af.', body_pl = 'Aby szybciej zasnął, wyłącz w pokoju wszystkie ekrany. Niebieskie światło telewizora spowalnia wydzielanie hormonu snu.', body_pt = 'Para que adormeça mais depressa, desligue todos os ecrãs do quarto. A luz azul da televisão atrasa a hormona do sono.', body_sv = 'För att barnet ska somna snabbare, stäng av alla skärmar i rummet. Det blå ljuset från tv:n bromsar sömnhormonet.', body_vi = 'Để bé ngủ nhanh hơn, hãy tắt mọi màn hình trong phòng. Ánh sáng xanh từ TV làm chậm quá trình tiết hormone giấc ngủ.', body_zh = '想让宝宝更快入睡，就关掉房间里所有的屏幕。电视的蓝光会推迟睡眠激素的分泌。' WHERE id = 'fce8d709-58cb-464d-bc50-7c2b9036555e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se agarra al sofá o al sillón para trepar? Su equilibrio y su fuerza muscular aumentan. Protégele, pero no frenes nunca estos intentos de alpinista.', body_fr = 'Il s''agrippe au canapé ou au fauteuil pour grimper ? Son équilibre et sa force musculaire augmentent. Protégez-le, mais n''empêchez surtout pas ces tentatives d''alpiniste.', body_hi = 'सोफ़े और कुर्सी को पकड़कर ऊपर चढ़ने की कोशिश करता है? संतुलन और मांसपेशियों की ताकत बढ़ रही है। उसकी रक्षा कीजिए, लेकिन इन पर्वतारोही कोशिशों को बिल्कुल मत रोकिए।', body_id = 'Ia berpegangan pada sofa dan kursi lalu mencoba memanjat? Keseimbangan dan kekuatan ototnya meningkat. Lindungi ia, tetapi jangan sekali-kali menghalangi usaha pendaki kecil ini.', body_ja = 'ソファやいすにつかまって、上によじ登ろうとしていますか？バランス感覚と筋力が育っています。安全を守りつつ、この登山家のような挑戦は決して止めないであげて。', body_ko = '소파나 안락의자를 붙잡고 기어오르려 하나요? 균형 감각과 근력이 자라고 있어요. 안전은 지켜 주되 이 등반 시도를 절대 막지 마세요.', body_nl = 'Probeert hij zich aan de bank of fauteuil omhoog te trekken en erop te klimmen? Zijn evenwicht en spierkracht groeien. Bescherm hem, maar houd deze kleine klimpogingen zeker niet tegen.', body_pl = 'Łapie się kanapy i fotela i próbuje się wspinać? Rośnie jego równowaga i siła mięśni. Pilnuj go, ale w żadnym wypadku nie przeszkadzaj w tych alpinistycznych próbach.', body_pt = 'Agarra-se ao sofá e à poltrona e tenta trepar? O equilíbrio e a força muscular estão a aumentar. Proteja-o, mas não trave de forma nenhuma estas tentativas de alpinista.', body_sv = 'Håller barnet sig i soffan eller fåtöljen och försöker klättra upp? Balansen och muskelstyrkan ökar. Skydda barnet, men hindra absolut inte de här klätterförsöken.', body_vi = 'Bé bám vào sofa, ghế bành để cố trèo lên? Khả năng giữ thăng bằng và sức mạnh cơ bắp đang tăng lên. Hãy bảo vệ bé, nhưng tuyệt đối đừng ngăn cản những lần "leo núi" này.', body_zh = '扶着沙发、扶手椅想往上爬？平衡能力和肌肉力量都在增强。护好宝宝，但千万别阻止这些攀登尝试。' WHERE id = '1dc3a9e4-8c1a-46c9-b53c-b30058a99bb3' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tozudez con la comida 🥣', body_es = '¿Come dos cucharadas, dice que está lleno y se va corriendo? No le obligues. Crear una relación sana con la comida es más importante que hacerle comer a la fuerza.', title_fr = 'Bras de fer à table 🥣', body_fr = 'Deux cuillères, il dit qu''il n''a plus faim et s''en va ? Ne le forcez pas. Construire une relation saine avec la nourriture compte plus que le faire manger de force.', title_hi = 'खाने की ज़िद 🥣', body_hi = 'दो चम्मच खाकर ''पेट भर गया'' कहकर भाग जाता है? ज़बरदस्ती मत कीजिए। ज़बरदस्ती खिलाने से ज़्यादा ज़रूरी है खाने के साथ स्वस्थ रिश्ता बनाना।', title_id = 'Keras kepala saat makan 🥣', body_id = 'Baru dua sendok sudah bilang kenyang lalu kabur? Jangan memaksanya. Membangun hubungan sehat dengan makanan lebih penting daripada menyuapi secara paksa.', title_ja = '食事でのがんこさ 🥣', body_ja = 'ふた口食べて「おなかいっぱい」と言って逃げていきますか？無理に食べさせないで。食べ物とよい関係を築くことは、無理やり食べさせるより大切です。', title_ko = '밥상 위의 고집 🥣', body_ko = '두 숟가락 먹고 배부르다며 도망가나요? 억지로 먹이지 마세요. 억지로 먹이는 것보다 음식과 건강한 관계를 만드는 게 더 중요해요.', title_nl = 'Koppig aan tafel 🥣', body_nl = 'Zegt hij na twee hapjes al dat hij vol zit en rent hij weg? Dwing hem niet. Een gezonde relatie met eten is belangrijker dan dwangvoeren.', title_pl = 'Upór przy jedzeniu 🥣', body_pl = 'Po dwóch łyżkach mówi, że jest najedzony, i ucieka? Nie zmuszaj go. Zdrowa relacja z jedzeniem jest ważniejsza niż karmienie na siłę.', title_pt = 'Teimosia à mesa 🥣', body_pt = 'Come duas colheres, diz que está cheio e foge? Não o force. Criar uma relação saudável com a comida é mais importante do que obrigá-lo a comer.', title_sv = 'Envis med maten 🥣', body_sv = 'Äter barnet två skedar, säger att det är mätt och springer iväg? Tvinga inte. Att bygga en sund relation till mat är viktigare än att tvångsmata.', title_vi = 'Bướng bỉnh trong bữa ăn 🥣', body_vi = 'Bé ăn hai thìa đã bảo no rồi chạy đi? Đừng ép bé. Xây dựng mối quan hệ lành mạnh với thức ăn quan trọng hơn ép ăn.', title_zh = '吃饭较劲 🥣', body_zh = '吃了两勺就说“饱了”，然后跑开？别勉强。和食物建立健康的关系，比强迫进食重要得多。' WHERE id = 'a7098097-ad7b-4ef2-ac70-151dc53814b4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hoy has acabado agotadísima o tu peque ha dicho algo muy dulce? En los dos casos, abre el Diario de ánimo, guarda este momento para el futuro y desahógate.', body_fr = 'Aujourd''hui, vous êtes épuisée, ou il a dit un mot adorable ? Dans les deux cas, ouvrez le Journal d''humeur, gravez ce moment pour plus tard et soulagez votre cœur.', body_hi = 'आज आप बेहद थक गईं या उसने कोई बहुत प्यारी बात कही? दोनों ही हालात में मूड डायरी खोलिए, इस पल को आगे के लिए दर्ज कीजिए और मन हल्का कीजिए।', body_id = 'Hari ini Anda lelah luar biasa, atau ia mengucapkan kata yang sangat manis? Apa pun itu, buka Buku Harian Suasana Hati, abadikan momen ini untuk masa depan, dan lapangkan hati Anda.', body_ja = '今日はくたくたに疲れましたか？それとも、とてもかわいいことを言ってくれましたか？どちらにしても「気分日記」を開いて、この瞬間を未来のために記録し、心を軽くしましょう。', body_ko = '오늘 녹초가 됐나요, 아니면 아이가 아주 사랑스러운 말을 했나요? 어느 쪽이든 기분 일기를 열고 이 순간을 기록으로 남기며 마음을 편히 내려놓으세요.', body_nl = 'Was je vandaag doodmoe of zei hij iets heel liefs? Open in beide gevallen je Stemmingsdagboek, leg dit moment vast voor later en lucht je hart.', body_pl = 'Jesteś dziś szalenie zmęczona albo powiedział coś bardzo słodkiego? W obu przypadkach otwórz Dziennik nastroju, zapisz tę chwilę na przyszłość i ulżyj sobie.', body_pt = 'Hoje ficou exausta ou ele disse uma palavra muito doce? Em qualquer dos casos, abra o Diário de Humor, registe este momento para o futuro e alivie o coração.', body_sv = 'Var du galet trött i dag, eller sa barnet något väldigt gulligt? I båda fallen, öppna Humördagboken, anteckna stunden för framtiden och lätta ditt hjärta.', body_vi = 'Hôm nay mẹ mệt rã rời hay bé vừa nói một câu thật ngọt ngào? Dù thế nào, hãy mở Nhật ký tâm trạng, ghi lại khoảnh khắc này cho tương lai và để lòng nhẹ nhõm hơn.', body_zh = '今天累得快疯了，或者宝宝说了一句特别可爱的话？不管哪种，都打开心情日记，把这一刻记下来留给未来，让心里轻松一些。' WHERE id = 'f8b30c93-8e49-4cb9-8db0-9b3082221d0d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ya puede jugar 10-15 minutos con un mismo juguete, como un puzle? Su capacidad de atención se alarga. Quédate en silencio en un rincón de la habitación y obsérvale.', body_fr = 'Il joue désormais 10 à 15 minutes avec un seul jouet, un puzzle par exemple ? Sa capacité de concentration s''allonge. Restez silencieuse dans un coin de la pièce et observez-le.', body_hi = 'एक खिलौने, जैसे पज़ल, से खेलने का समय अब 10-15 मिनट तक पहुँच गया है? यह उसके ध्यान की अवधि बढ़ने का संकेत है। चुपचाप कमरे के एक कोने में खड़े होकर उसे देखिए।', body_id = 'Waktunya bermain dengan satu mainan, misalnya puzzle, sudah mencapai 10-15 menit? Ini tanda rentang perhatiannya makin panjang. Berdirilah diam di sudut kamar dan amati ia.', body_ja = 'パズルなど、ひとつのおもちゃで遊ぶ時間が10〜15分に延びましたか？集中力がのびてきた証拠です。部屋の片すみで静かに見守りましょう。', body_ko = '퍼즐 같은 장난감 하나로 노는 시간이 10~15분까지 늘었나요? 집중력이 길어지고 있다는 뜻이에요. 방 한쪽에서 조용히 지켜봐 주세요.', body_nl = 'Speelt hij al 10-15 minuten met één speeltje, zoals een puzzel? Zijn concentratie wordt langer. Blijf stil in een hoekje van de kamer staan en kijk toe.', body_pl = 'Potrafi już bawić się jedną zabawką, np. układanką, przez 10-15 minut? To znak, że wydłuża się jego koncentracja. Stań cicho w kącie pokoju i go obserwuj.', body_pt = 'Já consegue brincar 10-15 minutos com um só brinquedo, como um puzzle? É a capacidade de atenção a crescer. Fique em silêncio num canto do quarto e observe-o.', body_sv = 'Leker barnet redan 10-15 minuter med en och samma leksak, till exempel ett pussel? Det betyder att koncentrationen blir längre. Stå tyst i ett hörn av rummet och titta på.', body_vi = 'Bé đã có thể chơi một món đồ chơi, như bộ ghép hình, đến 10-15 phút? Đó là khả năng tập trung đang dài ra. Hãy lặng lẽ đứng ở góc phòng và quan sát bé.', body_zh = '玩一个玩具（比如拼图）的时间已经能达到10到15分钟了？这说明专注力在延长。安静地站在房间一角，看着宝宝就好。' WHERE id = '18e35d56-8285-420a-adac-121643743cd2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '«¿Qué pasa si tiro esto?», «¿Para qué sirve este botón?». No para de hacer experimentos físicos. Revisa una vez más la seguridad de la casa a ras de suelo.', body_fr = '« Et si je lance ça ? », « Il sert à quoi, ce bouton ? » Il fait sans arrêt des expériences physiques. Revérifiez encore une fois la sécurité de la maison au ras du sol.', body_hi = '''इसे फेंकूँ तो क्या होगा?'', ''यह बटन किसलिए है?'' वह लगातार शारीरिक प्रयोग करता है। फ़र्श के स्तर से घर की सुरक्षा एक बार फिर जाँच लीजिए।', body_id = '''Kalau ini kulempar, apa yang terjadi?'', ''Tombol ini untuk apa?'' Ia terus melakukan percobaan fisik. Periksa sekali lagi keamanan rumah dari ketinggian lantai.', body_ja = '「これを投げたらどうなる？」「このボタンはなんのため？」いつも体を使って実験しています。床の高さから、家の安全をもう一度見直しましょう。', body_ko = '''이거 던지면 어떻게 돼?'', ''이 버튼은 뭐야?'' 끊임없이 몸으로 실험하고 있어요. 바닥 높이에서 집 안의 안전을 다시 한번 살펴보세요.', body_nl = '''Wat gebeurt er als ik dit gooi?'', ''Waar is dit knopje voor?'' Hij doet voortdurend fysieke proefjes. Bekijk de veiligheid van je huis nog eens vanaf vloerhoogte.', body_pl = '„Co się stanie, jak to rzucę?”, „Do czego jest ten guzik?”. Ciągle przeprowadza fizyczne eksperymenty. Jeszcze raz sprawdź bezpieczeństwo domu z poziomu podłogi.', body_pt = '"O que acontece se atirar isto?", "Para que serve este botão?" Faz experiências físicas sem parar. Reveja mais uma vez a segurança da casa ao nível do chão.', body_sv = '”Vad händer om jag kastar den här?”, ”Vad är den här knappen till?” Barnet gör ständigt fysiska experiment. Gå igenom säkerheten hemma från golvnivå en gång till.', body_vi = '"Ném cái này thì sao nhỉ?", "Nút này để làm gì?" Bé liên tục làm các thí nghiệm vật lý. Hãy kiểm tra lại an toàn trong nhà từ tầm thấp sát sàn một lần nữa.', body_zh = '“扔了这个会怎样？”“这个按钮是干什么的？”宝宝一直在做各种身体实验。再从地面的高度检查一遍家里的安全吧。' WHERE id = '87548d0a-d1fb-4a91-8d0e-f51d5f31d60e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Los cuentos clásicos ya no le llaman la atención? Inventa una historia especial cuyo héroe sea tu peque, con sonidos de la naturaleza de fondo, y entra en su mundo de fantasía.', body_fr = 'Les contes classiques ne l''intéressent plus ? Inventez une histoire spéciale dont il est le héros, accompagnée de sons de la nature, et entrez dans son monde imaginaire.', body_hi = 'पुरानी कहानियाँ अब उसका ध्यान नहीं खींचतीं? एक खास कहानी गढ़िए जिसका हीरो वह खुद हो और पीछे प्रकृति की आवाज़ें हों, और उसकी सपनों की दुनिया में चले जाइए।', body_id = 'Dongeng klasik tidak lagi menarik perhatiannya? Karang cerita khusus dengan dirinya sebagai tokoh utama, diiringi suara alam di latar belakang, dan masuklah ke dunia khayalnya.', body_ja = '昔話にはもう興味を示さない？お子さん自身が主人公で、自然の音が流れる特別なお話を考えて、想像の世界に一緒に入っていきましょう。', body_ko = '늘 듣던 동화에 더 이상 관심이 없나요? 아이가 주인공이고 자연의 소리가 잔잔히 흐르는 특별한 이야기를 지어 아이의 상상 세계로 들어가 보세요.', body_nl = 'Trekken klassieke sprookjes zijn aandacht niet meer? Verzin een speciaal verhaal waarin hij zelf de held is, met natuurgeluiden op de achtergrond, en stap zo zijn fantasiewereld binnen.', body_pl = 'Klasyczne bajki już go nie wciągają? Wymyśl wyjątkową historię, w której to on jest bohaterem, z odgłosami natury w tle, i wejdź do jego świata wyobraźni.', body_pt = 'Os contos clássicos já não lhe prendem a atenção? Invente uma história especial em que ele é o herói, acompanhada de sons da natureza em fundo, e entre no mundo da imaginação dele.', body_sv = 'Fångar klassiska sagor inte längre barnets intresse? Hitta på en egen berättelse där barnet själv är hjälten, med naturljud i bakgrunden, och kliv in i hens fantasivärld.', body_vi = 'Truyện cổ tích kinh điển không còn thu hút bé? Hãy nghĩ ra một câu chuyện đặc biệt với nhân vật chính là bé, kèm âm thanh thiên nhiên phía sau, và bước vào thế giới tưởng tượng của bé.', body_zh = '经典故事已经吸引不了宝宝了？编一个以宝宝为主角、配着大自然声音的特别故事，走进宝宝的梦想世界吧。' WHERE id = 'f1a78ec7-6b62-43e2-8747-e4f8c033a5e7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿En cuanto suena una música alegre se balancea al ritmo? ¡La conexión entre oído y motricidad va perfecta! Pon una canción alegre y bailad juntos por la habitación.', body_fr = 'Dès qu''une musique joyeuse retentit, il se balance en rythme ? Le lien entre audition et motricité se crée à merveille ! Mettez une chanson gaie et dansez avec lui dans la pièce.', body_hi = 'खुशनुमा संगीत बजते ही तुरंत ताल पर झूमने लगता है? सुनने और हरकत का तालमेल बढ़िया बन रहा है! कोई खुशनुमा गाना लगाइए और उसके साथ कमरे में नाचिए।', body_id = 'Begitu terdengar musik ceria, ia langsung bergoyang mengikuti irama? Hubungan pendengaran dan motoriknya terbentuk sempurna! Putar lagu ceria dan berjoget bersamanya di kamar.', body_ja = '楽しい音楽が流れると、すぐにリズムに合わせて体をゆらしますか？聴覚と運動のつながりがすばらしく育っています！楽しい歌をかけて、一緒に部屋で踊りましょう。', body_ko = '신나는 음악이 나오면 바로 리듬에 맞춰 몸을 흔드나요? 청각과 운동 능력이 멋지게 연결되고 있어요! 신나는 노래를 틀고 방에서 함께 춤춰 보세요.', body_nl = 'Wiegt hij meteen mee op het ritme als er vrolijke muziek klinkt? De verbinding tussen gehoor en motoriek ontstaat prachtig! Zet een vrolijk liedje op en dans samen door de kamer.', body_pl = 'Gdy gra wesoła muzyka, od razu kołysze się w rytm? Połączenie słuchu i motoryki rozwija się wspaniale! Włącz wesołą piosenkę i zatańczcie razem w pokoju.', body_pt = 'Quando toca uma música alegre, começa logo a balançar ao ritmo? A ligação entre audição e motricidade está a formar-se na perfeição! Ponha uma canção alegre e dancem juntos pelo quarto.', body_sv = 'Gungar barnet genast i takt när glad musik spelas? Kopplingen mellan hörsel och motorik utvecklas perfekt! Sätt på en glad låt och dansa tillsammans i rummet.', body_vi = 'Vừa nghe nhạc vui là bé đung đưa theo nhịp? Mối liên kết giữa thính giác và vận động đang hình thành tuyệt vời! Hãy bật một bài hát vui nhộn và cùng bé nhảy trong phòng.', body_zh = '一听到欢快的音乐，就马上跟着节奏摇摆？听觉和动作的配合正在完美建立！放一首欢快的歌，和宝宝一起在房间里跳舞吧。' WHERE id = 'becd06f2-3767-4d60-98af-e6ee50a40e21' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Adiós «¿Por qué?», hola «¿Cómo?» 🤔', body_es = '¡Un salto en imaginación y lógica! Ahora pregunta cómo funcionan las cosas. Aprende con nuestro experto Anacan AI técnicas para responder a estas preguntas de forma adecuada a su edad y nada aburrida.', title_fr = 'Fini les « Pourquoi ? », place aux « Comment ? » 🤔', body_fr = 'Un bond d''imagination et de logique ! Maintenant, il demande comment les choses fonctionnent. Découvrez avec notre expert Anacan AI comment répondre à ces questions de façon adaptée à son âge et sans ennui.', title_hi = '''क्यों?'' खत्म, ''कैसे?'' शुरू 🤔', body_hi = 'कल्पना और तर्क में छलांग! अब वह पूछता है कि चीज़ें कैसे काम करती हैं। हमारे Anacan AI एक्सपर्ट से जानिए कि इन सवालों के उम्र के हिसाब से, बिना उबाऊ हुए जवाब कैसे दें।', title_id = '''Kenapa?'' usai, ''Bagaimana?'' dimulai 🤔', body_id = 'Lompatan imajinasi dan logika! Kini ia bertanya bagaimana benda-benda bekerja. Pelajari dari ahli Anacan AI teknik menjawab pertanyaan ini sesuai usianya tanpa membosankan.', title_ja = '「なんで？」が終わって「どうやって？」が始まった 🤔', body_ja = '想像力と論理の飛躍！今度はものがどう動くのかを聞いてきます。こうした質問に年齢に合った、退屈させない答え方を、Anacan AIのエキスパートから学びましょう。', title_ko = '''왜?''는 끝, 이제 ''어떻게?'' 🤔', body_ko = '상상력과 논리력의 도약! 이제는 물건이 어떻게 작동하는지 묻나요? 이런 질문에 나이에 맞게 지루하지 않게 대답하는 요령을 Anacan AI 전문가에게 배워 보세요.', title_nl = 'Klaar met ''Waarom?'', tijd voor ''Hoe?'' 🤔', body_nl = 'Een sprong in fantasie en logica! Nu vraagt hij ook hoe dingen werken. Leer van onze expert Anacan AI hoe je deze vragen passend bij zijn leeftijd en niet saai beantwoordt.', title_pl = '„Dlaczego?” się skończyło, zaczęło się „Jak?” 🤔', body_pl = 'Skok wyobraźni i logiki! Teraz pyta, jak działają rzeczy. Poznaj z naszym ekspertem Anacan AI sposoby odpowiadania na te pytania w nienudny i dopasowany do wieku sposób.', title_pt = 'Acabou o "Porquê?", começou o "Como?" 🤔', body_pt = 'Um salto na imaginação e na lógica! Agora também pergunta como funcionam as coisas. Aprenda com o especialista Anacan AI a responder a estas perguntas de forma adequada à idade e nada aborrecida.', title_sv = '”Varför?” är slut, ”Hur?” har börjat 🤔', body_sv = 'Ett språng i fantasi och logik! Nu frågar barnet hur saker fungerar. Lär dig av vår expert Anacan AI hur du ger åldersanpassade svar som inte är tråkiga.', title_vi = 'Hết "Tại sao?", đến "Thế nào?" 🤔', body_vi = 'Bước nhảy vọt về trí tưởng tượng và tư duy! Giờ bé hỏi cả đồ vật hoạt động thế nào. Hãy học từ chuyên gia Anacan AI cách trả lời những câu hỏi này phù hợp lứa tuổi mà không nhàm chán.', title_zh = '“为什么？”结束，“怎么做？”开始 🤔', body_zh = '想象力和逻辑的飞跃！现在宝宝开始问东西是怎么运作的。向我们的Anacan AI专家学学，怎样用适合年龄又不无聊的方式回答这些问题。' WHERE id = 'd245b047-0d4a-45c3-956c-817469ecd147' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hacer las paces con el insomnio 😭', body_es = 'Se ha despertado en mitad de la noche y no quiere dormir. No te enfades. Averigua la causa (dolor, gases, miedo), abrázale con paciencia y dale seguridad.', title_fr = 'Faire la paix avec les nuits blanches 😭', body_fr = 'Il s''est réveillé en pleine nuit et ne veut pas se rendormir. Ne vous énervez pas. Cherchez la cause (douleur, gaz, peur) et rassurez-le avec un câlin patient.', title_hi = 'नींद न आने से समझौता 😭', body_hi = 'आधी रात को जाग गया और सोना नहीं चाहता? उस पर गुस्सा मत कीजिए। वजह (दर्द, गैस, डर) पक्की कीजिए और धैर्य से गले लगाकर उसे भरोसा दीजिए।', title_id = 'Berdamai dengan kurang tidur 😭', body_id = 'Ia terbangun tengah malam dan tidak mau tidur lagi. Jangan kesal padanya. Pastikan penyebabnya (sakit, kembung, takut), lalu peluk ia dengan sabar dan beri rasa aman.', title_ja = '眠れない夜と仲直り 😭', body_ja = '真夜中に目を覚まして、眠ろうとしない？イライラしないで。原因（痛み、ガス、こわさ）を確かめ、やさしく抱きしめて安心させてあげましょう。', title_ko = '잠 못 드는 밤과 화해하기 😭', body_ko = '한밤중에 깨서 다시 자려 하지 않나요? 화내지 마세요. 이유(통증, 가스, 무서움)를 살펴보고 인내심 있게 안아 주며 안심시켜 주세요.', title_nl = 'Vrede sluiten met slapeloosheid 😭', body_nl = 'Hij is midden in de nacht wakker en wil niet slapen. Word niet boos op hem. Zoek uit wat de oorzaak is (pijn, krampjes, angst) en geef hem geduldig een knuffel en vertrouwen.', title_pl = 'Pogodzić się z nieprzespanymi nocami 😭', body_pl = 'Obudził się w środku nocy i nie chce spać? Nie złość się na niego. Ustal przyczynę (ból, gazy, strach), cierpliwie go przytul i daj mu poczucie bezpieczeństwa.', title_pt = 'Fazer as pazes com as noites sem dormir 😭', body_pt = 'Acordou a meio da noite e não quer dormir? Não se irrite com ele. Descubra a causa (dor, gases, medo) e abrace-o com paciência para lhe dar segurança.', title_sv = 'Försonas med sömnlösheten 😭', body_sv = 'Barnet har vaknat mitt i natten och vill inte sova. Bli inte arg. Ta reda på orsaken (smärta, gaser, rädsla), krama barnet med tålamod och ge trygghet.', title_vi = 'Làm hòa với những đêm mất ngủ 😭', body_vi = 'Bé thức dậy giữa đêm và không chịu ngủ lại. Đừng bực bé. Hãy xác định nguyên nhân (đau, đầy hơi, sợ hãi) và kiên nhẫn ôm bé để trấn an.', title_zh = '和失眠和解 😭', body_zh = '半夜醒来，就是不肯睡？别对宝宝发火。弄清原因（疼痛、胀气、害怕），耐心地抱抱宝宝，给宝宝安全感。' WHERE id = '0d9edca6-9e16-4f20-b482-5f21d8925331' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te agota que la ropa siempre acabe manchada? No te enfades. Está descubriendo los alimentos. Usa baberos de silicona y disfruta de estos momentos llenos de color y pringue.', body_fr = 'Les vêtements toujours tachés vous fatiguent ? Ne vous énervez pas. Il découvre les aliments. Utilisez des bavoirs en silicone et savourez ces moments colorés et salissants.', body_hi = 'कपड़ों पर बार-बार दाग लगना थका रहा है? इस पर गुस्सा मत कीजिए। वह खाने की चीज़ों को खोज रहा है। सिलिकॉन बिब इस्तेमाल कीजिए और इन रंग-बिरंगे, सने हुए पलों का आनंद लीजिए।', body_id = 'Lelah karena bajunya terus kotor? Jangan kesal. Ia sedang mengenal makanan. Gunakan celemek silikon dan nikmati momen penuh warna dan belepotan ini.', body_ja = '服がいつも汚れて疲れますか？イライラしないで。食べ物を探検しているのです。シリコンのスタイを使って、このカラフルでべちゃべちゃな時間を楽しみましょう。', body_ko = '옷에 늘 얼룩이 져서 지쳤나요? 화내지 마세요. 음식을 탐색하는 중이에요. 실리콘 턱받이를 쓰고 이 알록달록하고 엉망진창인 순간을 즐겨 보세요.', body_nl = 'Word je moe van de steeds vieze kleren? Erger je er niet aan. Hij ontdekt eten. Gebruik siliconen slabben en geniet van deze kleurrijke, kliederige momenten.', body_pl = 'Męczą cię ciągle poplamione ubrania? Nie denerwuj się. On odkrywa jedzenie. Używaj silikonowych śliniaków i ciesz się tymi kolorowymi, umorusanymi chwilami.', body_pt = 'Cansada da roupa sempre manchada? Não se irrite. Ele está a descobrir os alimentos. Use babetes de silicone e aproveite estes momentos coloridos e lambuzados.', body_sv = 'Är du trött på att kläderna ständigt blir fläckiga? Bli inte arg. Barnet upptäcker maten. Använd silikonhaklappar och njut av de här färgglada, kladdiga stunderna.', body_vi = 'Quần áo lúc nào cũng dính bẩn khiến mẹ mệt mỏi? Đừng bực mình. Bé đang khám phá thức ăn. Hãy dùng yếm silicon và tận hưởng những khoảnh khắc nhiều màu sắc, lấm lem này.', body_zh = '衣服总是弄脏，让你心累？别为这个生气。宝宝正在探索食物。用硅胶围兜，好好享受这些五颜六色、脏兮兮的时刻吧。' WHERE id = '6fbdbe3b-91f8-4e0a-9823-628cb1856a3a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Te ayudo! 🧹', body_es = '¿Cuando friegas el suelo o quitas el polvo intenta quitarte el trapo? Ya se siente mayor. Dale un trapito y deja que se una a tu equipo.', title_fr = 'Je t''aide ! 🧹', body_fr = 'Quand vous passez la serpillière ou la poussière, il essaie de vous prendre le chiffon ? Il se sent déjà grand. Donnez-lui un petit chiffon et laissez-le rejoindre l''équipe.', title_hi = 'मैं मदद करूँ! 🧹', body_hi = 'आप पोंछा लगाती हैं या धूल झाड़ती हैं तो आपके हाथ से लेने की कोशिश करता है? वह खुद को बड़ा महसूस करता है। उसे एक छोटा कपड़ा दीजिए और अपनी टीम में शामिल होने दीजिए।', title_id = 'Aku bantu ya! 🧹', body_id = 'Saat Anda mengepel atau membersihkan debu, ia mencoba merebut lapnya? Ia merasa sudah besar. Beri ia lap kecil dan biarkan ia bergabung dengan tim Anda.', title_ja = 'お手伝いするね！🧹', body_ja = '床をふいたり、ほこりを払ったりしていると、手から取ろうとしますか？もう自分は大きいと感じています。小さなぞうきんを渡して、チームに加わらせてあげましょう。', title_ko = '내가 도와줄게! 🧹', body_ko = '엄마가 바닥을 닦거나 먼지를 털 때 손에서 걸레를 가져가려 하나요? 벌써 다 컸다고 느끼는 거예요. 작은 걸레를 쥐여 주고 팀에 합류하게 해 주세요.', title_nl = 'Ik help je wel! 🧹', body_nl = 'Probeert hij de doek uit je hand te pakken als je dweilt of afstoft? Hij voelt zich al groot. Geef hem een klein doekje en laat hem bij je team komen.', title_pl = 'Pomogę ci! 🧹', body_pl = 'Gdy myjesz podłogę albo ścierasz kurze, próbuje zabrać ci szmatkę z ręki? Czuje się już duży. Daj mu małą ściereczkę i pozwól dołączyć do twojej drużyny.', title_pt = 'Deixa-me ajudar! 🧹', body_pt = 'Quando limpa o chão ou tira o pó, tenta tirar-lhe o pano da mão? Já se sente crescido. Dê-lhe um paninho e deixe-o juntar-se à equipa.', title_sv = 'Jag hjälper dig! 🧹', body_sv = 'Försöker barnet ta moppen eller dammtrasan ur din hand när du städar? Hen känner sig redan stor. Ge barnet en liten trasa och låt hen gå med i laget.', title_vi = 'Để con giúp mẹ! 🧹', body_vi = 'Khi mẹ lau nhà hay phủi bụi, bé cố giành lấy khăn trong tay mẹ? Bé đã thấy mình lớn rồi. Hãy đưa bé một chiếc khăn nhỏ và cho bé tham gia "đội" của mẹ.', title_zh = '我来帮你！🧹', body_zh = '你拖地或擦灰时，宝宝想从你手里抢过去？宝宝已经觉得自己长大了。给宝宝一块小抹布，让宝宝加入你的团队吧。' WHERE id = '9f08baf7-46d6-4ac6-b651-94901e800f6b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Intenta hacer «miau» cuando ve un gato y «guau» cuando ve un perro? Su vocabulario se desarrolla genial con los sonidos de los animales. Juega con tu peque a este juego.', body_fr = 'Il essaie de faire « miaou » quand il voit un chat et « ouaf ouaf » devant un chien ? Les cris d''animaux enrichissent son vocabulaire. Jouez à ce jeu avec lui.', body_hi = 'बिल्ली देखकर ''म्याऊँ'', कुत्ता देखकर ''भौं-भौं'' करने की कोशिश करता है? जानवरों की आवाज़ों से उसकी शब्दावली बढ़िया बढ़ रही है। उसके साथ यह खेल खेलिए।', body_id = 'Ia mencoba mengeong saat melihat kucing dan menggonggong saat melihat anjing? Kosakatanya berkembang pesat lewat suara hewan. Mainkan permainan ini bersamanya.', body_ja = 'ねこを見て「にゃー」、いぬを見て「わんわん」とまねしようとしますか？動物の鳴き声で語彙がぐんぐん育っています。一緒にこの遊びをしましょう。', body_ko = '고양이를 보면 ''야옹'', 강아지를 보면 ''멍멍'' 하려고 하나요? 동물 소리로 어휘가 훌륭하게 늘고 있어요. 함께 이 놀이를 해 보세요.', body_nl = 'Zegt hij ''miauw'' bij een kat en ''woef'' bij een hond? Zijn woordenschat groeit prima met dierengeluiden. Speel dit spelletje met hem.', body_pl = 'Na widok kota próbuje miauczeć, a na widok psa szczekać „hau-hau”? Jego zasób słów świetnie rozwija się dzięki odgłosom zwierząt. Pobaw się z nim w tę zabawę.', body_pt = 'Tenta fazer "miau" quando vê um gato e "ão-ão" quando vê um cão? O vocabulário cresce muito com os sons dos animais. Brinque a este jogo com ele.', body_sv = 'Säger barnet mjau när hen ser en katt och vov-vov när hen ser en hund? Ordförrådet utvecklas fint med djurläten. Lek den här leken tillsammans.', body_vi = 'Thấy mèo thì bé "meo meo", thấy chó thì "gâu gâu"? Vốn từ của bé đang phát triển rất tốt nhờ tiếng kêu của các con vật. Hãy cùng bé chơi trò này nhé.', body_zh = '看到小猫就“喵喵”，看到小狗就“汪汪”？词汇量正借着动物叫声快速增长。和宝宝一起玩这个游戏吧。' WHERE id = '71af31e1-67cd-4bc6-a54d-505d0d3ed0af' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Qué tamaño deben tener las raciones al acercarse a los 2,5 años? Si tienes dudas, pide ya a Anacan AI una tabla precisa y con base científica.', body_fr = 'Quelle taille de portion à l''approche des 2,5 ans ? Si vous hésitez, demandez vite à Anacan AI un tableau précis et fondé sur la science.', body_hi = '2.5 साल के करीब आते-आते खाने की मात्रा कितनी होनी चाहिए? अगर पक्का नहीं पता, तो अभी Anacan AI से सटीक और वैज्ञानिक आधार वाला चार्ट माँगिए।', body_id = 'Menjelang usia 2,5 tahun, seberapa banyak porsi makannya? Jika ragu, segera minta tabel yang tepat dan berdasar ilmiah dari Anacan AI.', body_ja = '2歳半が近づくと、1回の食事量はどのくらいがいいの？迷ったら、すぐにAnacan AIに正確で科学的な根拠のある表を聞いてみましょう。', body_ko = '두 돌 반이 다가오는데 한 번에 얼마나 먹어야 할지 고민인가요? 망설여진다면 Anacan AI에게 정확하고 과학적인 표를 바로 요청하세요.', body_nl = 'Hoe groot moeten de porties zijn nu hij richting 2,5 jaar gaat? Twijfel je? Vraag Anacan AI meteen om een nauwkeurig, wetenschappelijk onderbouwd schema.', body_pl = 'Jakie powinny być porcje, gdy zbliża się do 2,5 roku? Jeśli masz wątpliwości, od razu poproś Anacan AI o dokładną tabelę opartą na wiedzy naukowej.', body_pt = 'Perto dos 2,5 anos, qual deve ser o tamanho das porções? Se tiver dúvidas, peça já ao Anacan AI uma tabela precisa e com base científica.', body_sv = 'Hur stora ska portionerna vara när barnet närmar sig 2,5 år? Om du är osäker, be direkt Anacan AI om ett exakt och vetenskapligt grundat schema.', body_vi = 'Gần 2,5 tuổi thì khẩu phần ăn nên là bao nhiêu? Nếu mẹ còn phân vân, hãy hỏi ngay Anacan AI một bảng chính xác và có cơ sở khoa học.', body_zh = '快到2.5岁了，每份饭该吃多少？如果拿不准，马上向Anacan AI要一份准确、有科学依据的表格。' WHERE id = '1fe665ee-e68e-4e2a-b81e-f697b1100d0d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escucha a tu cuerpo 🩸', body_es = '¿Antojos repentinos de dulce o cansancio? Mira el calendario en el Calendario menstrual. Si te toca la regla, elige en Recetas saludables un tentempié con magnesio.', title_fr = 'Écoutez votre corps 🩸', body_fr = 'Envies soudaines de sucré ou fatigue ? Regardez le calendrier dans le Suivi des règles. Si ce sont vos règles, choisissez une collation au magnésium dans les Recettes saines.', title_hi = 'अपने शरीर की सुनिए 🩸', body_hi = 'अचानक मीठे की तलब या थकान? पीरियड ट्रैकर का कैलेंडर देखिए। अगर पीरियड चल रहा है, तो सेहतमंद रेसिपी से मैग्नीशियम वाला स्नैक चुनिए।', title_id = 'Dengarkan tubuh Anda 🩸', body_id = 'Tiba-tiba ingin makan manis atau merasa lelah? Lihat kalender di Pelacak Menstruasi. Jika sedang haid, pilih camilan bermagnesium dari Resep Sehat.', title_ja = '体の声を聞いて 🩸', body_ja = '急に甘いものが欲しくなったり、疲れたりしますか？「生理トラッカー」のカレンダーを見てみましょう。生理中なら、「ヘルシーレシピ」からマグネシウムたっぷりのおやつを選んで。', title_ko = '몸의 소리를 들어 보세요 🩸', body_ko = '갑자기 단 게 당기거나 피곤한가요? 생리 주기 기록의 달력을 확인해 보세요. 생리 기간이라면 건강한 레시피에서 마그네슘이 든 간식을 골라 보세요.', title_nl = 'Luister naar je lichaam 🩸', body_nl = 'Plotselinge zoetbuien of vermoeidheid? Kijk in de kalender van de Cyclustracker. Ben je ongesteld, kies dan uit Gezonde recepten een tussendoortje met magnesium.', title_pl = 'Wsłuchaj się w swoje ciało 🩸', body_pl = 'Nagła ochota na słodycze albo zmęczenie? Zajrzyj do kalendarza w Kalendarzu miesiączkowym. Jeśli to twój okres, wybierz ze Zdrowych przepisów przekąskę z magnezem.', title_pt = 'Ouça o seu corpo 🩸', body_pt = 'Desejos repentinos de doces ou cansaço? Veja o calendário no Registo do Período. Se estiver nesses dias, escolha um snack com magnésio nas Receitas Saudáveis.', title_sv = 'Lyssna på din kropp 🩸', body_sv = 'Plötsligt sötsug eller trötthet? Titta i kalendern i Mensspåraren. Om det är din period, välj ett magnesiumrikt mellanmål från Hälsosamma recept.', title_vi = 'Lắng nghe cơ thể 🩸', body_vi = 'Bỗng thèm đồ ngọt hay mệt mỏi? Hãy xem lịch trong Theo dõi kỳ kinh. Nếu đang đến kỳ, hãy chọn món ăn vặt giàu magie từ Công thức lành mạnh.', title_zh = '倾听你的身体 🩸', body_zh = '突然特别想吃甜食，或者感到疲惫？看看经期记录里的日历。如果是经期，就从健康食谱里选一份含镁的小零食。' WHERE id = '40197a85-31e6-4141-9d38-df9b89843274' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sombras en la habitación 🌌', body_es = '¿Le da miedo la oscuridad y los monstruos imaginarios? No dejes la habitación totalmente a oscuras y pon el sonido del vientre materno de Ruido blanco para devolverle aquella sensación de seguridad perfecta.', title_fr = 'Les ombres de la chambre 🌌', body_fr = 'Il a peur du noir et des monstres imaginaires ? Ne plongez pas la chambre dans le noir complet et mettez le son du ventre maternel dans les Bruits blancs pour lui redonner ce sentiment de sécurité d''autrefois.', title_hi = 'कमरे की परछाइयाँ 🌌', body_hi = 'अंधेरे और काल्पनिक राक्षसों से डरता है? कमरे में पूरा अंधेरा मत कीजिए और व्हाइट नॉइज़ में गर्भ की आवाज़ चलाकर उसे वही पुराना, सुकून भरा सुरक्षा का एहसास दीजिए।', title_id = 'Bayangan di kamar 🌌', body_id = 'Ia takut gelap dan monster khayalan? Jangan membuat kamar gelap total, dan putar suara rahim dari Suara Putih untuk memberinya kembali rasa aman yang dulu begitu sempurna.', title_ja = '部屋の影 🌌', body_ja = '暗やみや想像のモンスターをこわがりますか？部屋を真っ暗にせず、「ホワイトノイズ」の胎内音を流して、なつかしい完璧な安心感を届けてあげましょう。', title_ko = '방 안의 그림자 🌌', body_ko = '어둠과 상상 속 괴물을 무서워하나요? 방을 완전히 깜깜하게 하지 말고, 백색소음에서 엄마 배 속 소리를 틀어 예전의 완벽한 안정감을 선물하세요.', title_nl = 'Schaduwen in de kamer 🌌', body_nl = 'Is hij bang voor het donker en voor denkbeeldige monsters? Maak de kamer niet helemaal donker en zet in Witte ruis het baarmoedergeluid aan, voor dat oude, vertrouwde gevoel van veiligheid.', title_pl = 'Cienie w pokoju 🌌', body_pl = 'Boi się ciemności i wyimaginowanych potworów? Nie zaciemniaj pokoju całkowicie i włącz z Białego szumu odgłosy z brzucha mamy, by dać mu dawne, idealne poczucie bezpieczeństwa.', title_pt = 'Sombras no quarto 🌌', body_pt = 'Tem medo do escuro e de monstros imaginários? Não escureça o quarto por completo e ponha o som do útero no Ruído Branco para lhe devolver aquela antiga e perfeita sensação de segurança.', title_sv = 'Skuggor i rummet 🌌', body_sv = 'Är barnet rädd för mörkret och för låtsasmonster? Gör inte rummet helt mörkt, och sätt på livmoderljudet i Vitt brus för att ge barnet den gamla, perfekta känslan av trygghet.', title_vi = 'Những cái bóng trong phòng 🌌', body_vi = 'Bé sợ bóng tối và những con quái vật tưởng tượng? Đừng làm phòng tối hẳn, hãy bật âm thanh trong bụng mẹ trong Tiếng ồn trắng để mang lại cho bé cảm giác an toàn quen thuộc, trọn vẹn.', title_zh = '房间里的影子 🌌', body_zh = '害怕黑暗和想象中的怪兽？别把房间弄得全黑，打开白噪音里的子宫声，给宝宝那种熟悉又完美的安全感。' WHERE id = '4ca62724-362e-47af-b9dc-e138d57c7cbd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Llora detrás de ti cuando sales de la habitación, incluso cuando vas al baño? Cree que no vas a volver. Dale seguridad diciéndole siempre: «Estoy aquí, ¿oyes mi voz?».', body_fr = 'Quand vous quittez la pièce, même pour aller aux toilettes, il pleure derrière vous ? Il croit que vous ne reviendrez pas. Rassurez-le toujours : « Je suis là, tu entends ma voix ? »', body_hi = 'आप कमरे से बाहर जाएँ, टॉयलेट भी जाएँ, तो पीछे से रोता है? उसे लगता है कि आप वापस नहीं आएँगी। हमेशा ''मैं यहीं हूँ, मेरी आवाज़ सुन रहे हो?'' कहकर भरोसा दीजिए।', body_id = 'Saat Anda keluar kamar, bahkan ke toilet, ia menangis mengejar Anda? Ia mengira Anda tidak akan kembali. Selalu beri rasa aman dengan berkata, ''Ibu di sini, kamu dengar suara Ibu?''', body_ja = 'あなたが部屋を出たり、トイレに行ったりするだけで、後ろで泣きますか？もう戻ってこないと思っているのです。「ここにいるよ、声が聞こえる？」といつも伝えて安心させましょう。', body_ko = '방을 나가거나 화장실에 갈 때도 울며 따라오나요? 엄마가 다시 돌아오지 않을 거라고 생각하는 거예요. ''엄마 여기 있어, 목소리 들리지?'' 하고 늘 안심시켜 주세요.', body_nl = 'Huilt hij je achterna als je de kamer uit gaat, zelfs als je naar de wc gaat? Hij denkt dat je niet terugkomt. Geef hem vertrouwen door steeds te zeggen: ''Ik ben hier, hoor je mijn stem?''', body_pl = 'Płacze za tobą, gdy wychodzisz z pokoju, nawet do toalety? Myśli, że już nie wrócisz. Zawsze dodawaj mu otuchy słowami: „Jestem tutaj, słyszysz mój głos?”.', body_pt = 'Quando sai do quarto, até quando vai à casa de banho, chora atrás de si? Acha que não vai voltar. Dê-lhe segurança dizendo sempre: "Estou aqui, ouves a minha voz?"', body_sv = 'Gråter barnet efter dig när du lämnar rummet, till och med när du går på toaletten? Hen tror att du inte kommer tillbaka. Ge alltid trygghet genom att säga ”Jag är här, hör du min röst?”.', body_vi = 'Khi mẹ ra khỏi phòng, kể cả đi vệ sinh, bé cũng khóc theo? Bé nghĩ rằng mẹ sẽ không quay lại. Hãy luôn trấn an bằng câu "Mẹ ở đây mà, con nghe tiếng mẹ không?".', body_zh = '你走出房间，甚至去洗手间，宝宝都在后面哭？宝宝以为你不会回来了。总是说一句“我在这儿，听到我的声音了吗？”，给宝宝安全感。' WHERE id = 'f8e208a6-e2c2-4a88-b04c-adaeb10974b8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Peque parlanchín 🗣️', body_es = '¿Ya junta 4-5 palabras y cuenta historias graciosas? ¡Está viviendo una explosión de vocabulario! No te pierdas este momento de oro.', title_fr = 'Petit bavard 🗣️', body_fr = 'Il assemble déjà 4 ou 5 mots pour raconter des histoires drôles ? C''est l''explosion du vocabulaire ! Ne manquez pas ce moment en or.', title_hi = 'बातूनी नन्हा 🗣️', body_hi = 'अब 4-5 शब्द जोड़कर मज़ेदार कहानियाँ सुनाता है? शब्दों का धमाका हो रहा है! यह सुनहरा पल मत चूकिए।', title_id = 'Si kecil yang cerewet 🗣️', body_id = 'Ia sudah merangkai 4-5 kata dan bercerita lucu? Ledakan kosakata sedang terjadi! Jangan lewatkan momen emas ini.', title_ja = 'おしゃべりさん 🗣️', body_ja = 'もう4〜5語をつなげて、おもしろいお話をしますか？語彙の爆発期です！この黄金の瞬間を見逃さないで。', title_ko = '수다쟁이 꼬마 🗣️', body_ko = '벌써 4~5개 단어를 이어 웃긴 이야기를 하나요? 어휘가 폭발적으로 늘고 있어요! 이 황금 같은 순간을 놓치지 마세요.', title_nl = 'Klein kletskousje 🗣️', body_nl = 'Plakt hij al 4-5 woorden aan elkaar en vertelt hij grappige verhaaltjes? Er is een woordexplosie gaande! Mis dit gouden moment niet.', title_pl = 'Mały gaduła 🗣️', body_pl = 'Łączy już 4-5 słów i opowiada zabawne historie? To eksplozja słownictwa! Nie przegap tej złotej chwili.', title_pt = 'Pequeno conversador 🗣️', body_pt = 'Já junta 4-5 palavras e conta histórias cómicas? É uma explosão de vocabulário! Não perca este momento de ouro.', title_sv = 'Liten pratkvarn 🗣️', body_sv = 'Sätter barnet redan ihop 4-5 ord och berättar roliga historier? Ordförrådet exploderar! Missa inte den här gyllene stunden.', title_vi = 'Bé hay chuyện 🗣️', body_vi = 'Bé đã ghép được 4-5 từ để kể những câu chuyện hài hước? Vốn từ đang bùng nổ! Đừng bỏ lỡ khoảnh khắc vàng này.', title_zh = '爱聊天的小家伙 🗣️', body_zh = '已经能把4到5个词连起来讲搞笑的故事了？词汇量正在爆发！别错过这个黄金时刻。' WHERE id = '216f95a1-f03e-48c4-8e9d-615f08aa0853' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al quedarse dormido está más sensible. Para neutralizar los ruidos que llegan por la ventana, enciende en la habitación un aparato de ruido blanco suave (white noise) o música.', body_fr = 'Au moment de l''endormissement, il est plus sensible aux bruits. Pour neutraliser les sons venant de la fenêtre, allumez un appareil à bruit blanc doux ou une musique dans la chambre.', body_hi = 'सोते समय संवेदनशीलता बढ़ जाती है। खिड़की से आने वाली आवाज़ों को दबाने के लिए कमरे में हल्का व्हाइट नॉइज़ (white noise) डिवाइस या संगीत चलाइए।', body_id = 'Saat ia mulai terlelap, kepekaannya meningkat. Untuk meredam suara dari jendela, nyalakan perangkat suara putih (white noise) yang lembut atau musik di kamar.', body_ja = '寝入りばなは音に敏感になります。窓の外から聞こえる音をやわらげるために、部屋でやさしいホワイトノイズの機械や音楽をつけましょう。', body_ko = '잠드는 순간에는 예민함이 커져요. 창밖에서 들어오는 소리를 줄이려면 방에 은은한 백색소음 기기나 음악을 틀어 주세요.', body_nl = 'Bij het inslapen is hij extra gevoelig. Zet een zacht witteruisapparaat of rustige muziek aan in de kamer om geluiden van buiten te neutraliseren.', body_pl = 'Gdy zasypia, jest bardziej wrażliwy. Aby zneutralizować odgłosy zza okna, włącz w pokoju urządzenie z delikatnym białym szumem (white noise) albo muzykę.', body_pt = 'Ao adormecer, a sensibilidade aumenta. Para neutralizar os sons que vêm da janela, ligue no quarto um aparelho de ruído branco (white noise) suave ou música.', body_sv = 'Känsligheten ökar när barnet håller på att somna. För att neutralisera ljud från fönstret, sätt på en lätt vit brus-apparat (white noise) eller musik i rummet.', body_vi = 'Lúc bé đang chìm vào giấc ngủ là lúc nhạy cảm nhất. Để trung hòa tiếng ồn từ cửa sổ, hãy bật máy tiếng ồn trắng (white noise) nhẹ nhàng hoặc nhạc trong phòng.', body_zh = '入睡的时候最敏感。为了屏蔽窗外的声音，在房间里打开轻柔的白噪音机或音乐。' WHERE id = '41e28dbe-e3fb-4744-b4f1-9927a3802b24' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juntos en la cocina 🧑‍🍳', body_es = '¿Quiere ayudarte en la cocina? Deja que te eche una mano al echar la harina o el agua. Aunque se manche todo, su felicidad y sus ganas de aprender lo valen.', title_fr = 'Ensemble en cuisine 🧑‍🍳', body_fr = 'Il veut vous aider en cuisine ? Laissez-le verser la farine ou l''eau avec vous. Même si tout se salit, son bonheur et son envie d''apprendre en valent la peine.', title_hi = 'साथ मिलकर रसोई में 🧑‍🍳', body_hi = 'रसोई में आपके साथ काम करना चाहता है? आटा या पानी डालने में उसे मदद करने दीजिए। सब जगह गंदगी हो जाए तब भी उसकी खुशी और सीखने का उत्साह इसके लायक है।', title_id = 'Bersama di dapur 🧑‍🍳', body_id = 'Ia ingin membantu Anda di dapur? Biarkan ia membantu menuang tepung atau air. Meski semuanya jadi kotor, kebahagiaan dan semangat belajarnya sepadan.', title_ja = '一緒にキッチンで 🧑‍🍳', body_ja = 'キッチンであなたと一緒に作業したがりますか？小麦粉や水を注ぐのを手伝ってもらいましょう。あちこち汚れても、お子さんのしあわせと学ぶ意欲にはその価値があります。', title_ko = '주방에서 함께 🧑‍🍳', body_ko = '주방에서 엄마와 같이 일하고 싶어 하나요? 밀가루나 물을 붓는 걸 돕게 해 주세요. 여기저기 더러워져도 아이의 행복과 배우려는 열정은 그럴 가치가 있어요.', title_nl = 'Samen in de keuken 🧑‍🍳', body_nl = 'Wil hij met je meehelpen in de keuken? Laat hem helpen met bloem of water schenken. Ook al wordt alles vies, zijn geluk en leergierigheid zijn het waard.', title_pl = 'Razem w kuchni 🧑‍🍳', body_pl = 'Chce pracować z tobą w kuchni? Pozwól mu pomóc przy sypaniu mąki czy nalewaniu wody. Nawet jeśli wszystko się ubrudzi, jego radość i chęć nauki są tego warte.', title_pt = 'Juntos na cozinha 🧑‍🍳', body_pt = 'Quer ajudá-la na cozinha? Deixe-o ajudar a deitar a farinha ou a água. Mesmo que fique tudo sujo, a felicidade e a vontade de aprender dele valem a pena.', title_sv = 'Tillsammans i köket 🧑‍🍳', body_sv = 'Vill barnet hjälpa dig i köket? Låt hen hjälpa till när du häller mjöl eller vatten. Även om allt blir smutsigt är barnets glädje och lust att lära värd det.', title_vi = 'Cùng nhau vào bếp 🧑‍🍳', body_vi = 'Bé muốn cùng mẹ làm việc trong bếp? Hãy để bé giúp đổ bột hoặc rót nước. Dù mọi thứ có bừa bộn, niềm vui và sự ham học hỏi của bé cũng rất xứng đáng.', title_zh = '一起下厨房 🧑‍🍳', body_zh = '想在厨房里跟你一起干活？让宝宝帮你倒面粉或倒水吧。就算到处都弄脏了，宝宝的快乐和学习热情也值得。' WHERE id = '745737c8-7329-40d3-90c9-336ff2e4a2ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿La falta de sueño te ha debilitado la memoria y se te olvida qué comprar en el súper? No cargues la cabeza. Apúntalo todo en la Lista de la compra de la app.', body_fr = 'Le manque de sommeil affaiblit votre mémoire et vous oubliez les courses ? Ne vous fatiguez pas la tête. Notez tout dans la Liste de courses de l''application.', body_hi = 'नींद की कमी से याददाश्त कमज़ोर हो गई और बाज़ार से लाने वाली चीज़ें भूल जाती हैं? दिमाग मत थकाइए। सब कुछ ऐप की शॉपिंग लिस्ट में लिख लीजिए।', body_id = 'Kurang tidur membuat Anda pelupa dan belanjaan sering terlupa? Jangan membebani pikiran. Catat semuanya di Daftar Belanja di aplikasi.', body_ja = '寝不足で記憶力が落ちて、スーパーで買うものを忘れてしまう？頭を疲れさせないで。すべてアプリの「買い物リスト」に書いておきましょう。', body_ko = '잠이 부족해 기억력이 흐려지고 장 볼 것을 자꾸 잊나요? 머리 아프게 기억하지 마세요. 앱의 쇼핑 목록에 모두 적어 두세요.', body_nl = 'Is je geheugen door slaapgebrek wazig en vergeet je wat je moet kopen? Pijnig je hoofd niet. Zet alles op het Boodschappenlijstje in de app.', body_pl = 'Przez niewyspanie słabnie ci pamięć i zapominasz, co kupić w sklepie? Nie obciążaj głowy. Wpisz wszystko na Listę zakupów w aplikacji.', body_pt = 'A falta de sono enfraqueceu-lhe a memória e esquece-se do que tem de comprar? Não sobrecarregue a cabeça. Aponte tudo na Lista de Compras da app.', body_sv = 'Har sömnbristen försvagat minnet så att du glömmer vad du skulle köpa i affären? Belasta inte hjärnan. Skriv in allt i Inköpslistan i appen.', body_vi = 'Thiếu ngủ khiến mẹ hay quên và quên luôn cả đồ cần mua ở siêu thị? Đừng bắt mình phải nhớ. Hãy ghi mọi thứ vào Danh sách mua sắm trong ứng dụng.', body_zh = '睡眠不足让记性变差，在超市总忘了要买什么？别让脑子太累。把所有东西都写进应用里的购物清单吧。' WHERE id = '1938c0bd-ea98-478e-8da7-ef024a27ce71' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No hace falta ningún juego ni libro. Esta noche simplemente abrázale contra tu pecho, respira su olor y susúrrale en la oscuridad lo valioso que es para ti.', body_fr = 'Pas besoin de jeu ni de livre. Ce soir, serrez-le simplement contre vous, respirez son odeur et chuchotez-lui dans le noir combien il est précieux.', body_hi = 'किसी खेल या किताब की ज़रूरत नहीं। आज शाम बस उसे सीने से लगाइए, उसकी खुशबू महसूस कीजिए और अंधेरे में फुसफुसाकर बताइए कि वह आपके लिए कितना कीमती है।', body_id = 'Tidak perlu permainan atau buku. Malam ini cukup dekap ia di dada, hirup aromanya, dan bisikkan dalam gelap betapa berharganya ia bagi Anda.', body_ja = '遊びも絵本もいりません。今夜はただ胸に抱きしめて、においを深く吸いこみ、暗やみの中でどれほど大切な存在かをささやいてあげましょう。', body_ko = '오늘 밤엔 놀이도 책도 필요 없어요. 그냥 꼭 끌어안고 아이 냄새를 깊이 들이마신 뒤, 어둠 속에서 얼마나 소중한 존재인지 속삭여 주세요.', body_nl = 'Je hebt geen spelletje of boek nodig. Druk hem vanavond gewoon tegen je borst, snuif zijn geurtje op en fluister in het donker hoe dierbaar hij voor je is.', body_pl = 'Nie potrzeba żadnej zabawy ani książki. Dziś wieczorem po prostu przytul go mocno do piersi, wdychaj jego zapach i szepnij w ciemności, jak bardzo jest dla ciebie cenny.', body_pt = 'Não precisa de jogos nem de livros. Esta noite, simplesmente aperte-o contra o peito, respire o cheiro dele e sussurre-lhe no escuro o quanto é precioso.', body_sv = 'Inga lekar eller böcker behövs. I kväll, håll bara barnet tätt intill dig, andas in doften och viska i mörkret hur värdefull hen är.', body_vi = 'Không cần trò chơi hay sách vở. Tối nay chỉ cần ôm bé vào lòng, hít hà mùi hương của bé và thì thầm trong bóng tối rằng bé quý giá với mẹ biết bao.', body_zh = '不需要任何游戏或书。今晚就把宝宝紧紧抱在怀里，深深闻一闻宝宝的味道，在黑暗中轻声告诉宝宝，宝宝对你有多珍贵。' WHERE id = '30a1934e-958b-40a0-9b32-c4894a70a798' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maestro de las construcciones 🧱', body_es = '¿Intenta encajar piezas grandes de construcción para montar algo? Está descubriendo el espacio y la geometría. Marca este intento especial de ingeniería en el Seguimiento del desarrollo.', title_fr = 'Maître constructeur 🧱', body_fr = 'Il essaie d''emboîter de gros Lego pour construire quelque chose ? Il découvre l''espace et la géométrie. Notez cette tentative d''ingénieur spéciale dans le Suivi de développement.', title_hi = 'कंस्ट्रक्शन का उस्ताद 🧱', body_hi = 'बड़े लेगो एक-दूसरे में फँसाकर कुछ बनाने की कोशिश करता है? वह जगह और ज्यामिति की खोज कर रहा है। उसकी इस खास इंजीनियरिंग कोशिश को ग्रोथ ट्रैकर में दर्ज कीजिए।', title_id = 'Jago menyusun balok 🧱', body_id = 'Ia mencoba menyambungkan lego besar dan membuat sesuatu? Ia sedang menemukan ruang dan geometri. Tandai usaha teknik istimewanya ini di Pelacak Perkembangan.', title_ja = 'ブロック名人 🧱', body_ja = '大きなブロックをつなげて、何かを作ろうとしていますか？空間や図形を発見しています。この特別なエンジニアの挑戦を「発達トラッカー」に記録しましょう。', title_ko = '블록 쌓기 달인 🧱', body_ko = '큰 레고를 끼워 무언가를 만들려고 하나요? 공간과 기하학을 발견하는 중이에요. 성장 기록에 이 특별한 엔지니어링 시도를 표시해 두세요.', title_nl = 'Kleine bouwmeester 🧱', body_nl = 'Probeert hij grote blokken in elkaar te klikken en iets te bouwen? Hij ontdekt ruimte en meetkunde. Markeer deze bijzondere bouwpoging in de Groeitracker.', title_pl = 'Mistrz klocków 🧱', body_pl = 'Łączy duże klocki i próbuje coś zbudować? Odkrywa przestrzeń i geometrię. Zaznacz tę wyjątkową inżynierską próbę w Śledzeniu rozwoju.', title_pt = 'Mestre das construções 🧱', body_pt = 'Tenta encaixar legos grandes e construir coisas? Está a descobrir o espaço e a geometria. Marque esta tentativa especial de engenharia no Registo de Desenvolvimento.', title_sv = 'Byggmästare 🧱', body_sv = 'Försöker barnet sätta ihop stora legobitar och bygga något? Barnet upptäcker rummet och geometrin. Markera det här speciella ingenjörsförsöket i Utvecklingsspåraren.', title_vi = 'Bậc thầy xếp khối 🧱', body_vi = 'Bé cố ghép những khối lego lớn để tạo ra thứ gì đó? Bé đang khám phá không gian và hình học. Hãy đánh dấu nỗ lực "kỹ sư" đặc biệt này trong Theo dõi phát triển.', title_zh = '搭建小能手 🧱', body_zh = '想把大块乐高拼在一起做点什么？宝宝正在探索空间和几何。在发育追踪里标记下这次特别的工程尝试吧。' WHERE id = 'e00d8cce-8b3a-4ac6-ad35-5a22b01bd325' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'La habitación se ha quedado en silencio. Pide a tu pareja que se encargue de todo en casa. Tú date una ducha caliente y disfruta de un rato a solas contigo misma.', body_fr = 'Le silence est tombé sur la chambre. Demandez à votre partenaire de gérer toute la maison. Vous, prenez une douche chaude et accordez-vous un moment rien qu''à vous.', body_hi = 'कमरे में खामोशी छा गई। अपने पार्टनर से कहिए कि घर का सब कुछ वे संभालें। और आप गर्म पानी से नहाकर बस खुद के साथ कुछ पल बिताइए।', body_id = 'Kamar sudah hening. Mintalah pasangan mengurus semua hal di rumah. Anda mandilah air hangat dan nikmati waktu berdua dengan diri sendiri.', body_ja = '部屋が静かになりました。家のことはすべてパートナーにお願いしましょう。あなたは温かいシャワーを浴びて、自分だけの時間を過ごして。', body_ko = '방에 고요가 내려앉았어요. 배우자에게 집안일을 모두 맡기고, 엄마는 따뜻한 샤워를 하며 오롯이 혼자만의 시간을 보내세요.', body_nl = 'Het is stil geworden in huis. Vraag je partner om alles in huis over te nemen. Neem jij een warme douche en wees even helemaal alleen met jezelf.', body_pl = 'W pokoju zapadła cisza. Poproś partnera, żeby przejął wszystko w domu. A ty weź ciepły prysznic i pobądź sama ze sobą.', body_pt = 'O quarto ficou em silêncio. Peça ao seu companheiro que trate de tudo em casa. Tome um duche quente e fique a sós consigo mesma.', body_sv = 'Det har blivit tyst i rummet. Be din partner ta hand om allt hemma. Ta själv en varm dusch och var bara för dig själv en stund.', body_vi = 'Căn phòng đã yên tĩnh. Hãy nhờ chồng lo mọi việc trong nhà. Còn mẹ tắm nước ấm và dành chút thời gian cho riêng mình.', body_zh = '房间里安静下来了。请另一半来负责家里的一切，你去洗个热水澡，好好和自己独处一会儿。' WHERE id = '1a4b3925-7885-40fb-a56f-488e3358cee1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis de los 2 años 📱', body_es = '¿Te agota que diga «no» a todo? Lee los artículos del Blog y entiende las causas de esta tormenta de desarrollo que vive su cerebro.', title_fr = 'Le terrible two 📱', body_fr = 'Ses « non » à tout vous épuisent ? Lisez les articles de la rubrique Blogs pour comprendre les raisons de cette tempête de développement dans son cerveau.', title_hi = '2 साल का सिंड्रोम 📱', body_hi = 'बच्चे का हर बात पर ''नहीं'' कहना आपको थका रहा है? ब्लॉग सेक्शन के लेख पढ़कर समझिए कि उसके दिमाग में चल रहे इस विकास के तूफ़ान की वजहें क्या हैं।', title_id = 'Sindrom usia 2 tahun 📱', body_id = 'Kata ''tidak'' untuk segala hal membuat Anda lelah? Baca artikel di bagian Blog untuk memahami penyebab badai perkembangan yang terjadi di otaknya.', title_ja = '2歳ごろのイヤイヤ期 📱', body_ja = '何にでも「いや」と言われて疲れていませんか？ブログの記事を読んで、頭の中で起きているこの発達の嵐の理由を理解しましょう。', title_ko = '미운 두 살 📱', body_ko = '뭐든 ''싫어''라고 해서 지쳤나요? 블로그 섹션의 글을 읽고 아이 머릿속에서 일어나는 발달의 폭풍이 왜 생기는지 이해해 보세요.', title_nl = 'De peuterpuberteit 📱', body_nl = 'Word je moe van zijn eeuwige ''nee''? Lees de artikelen in Blogs en begrijp de oorzaken van deze ontwikkelingsstorm in zijn hoofdje.', title_pl = 'Bunt 2-latka 📱', body_pl = 'Męczy cię, że na wszystko mówi „nie”? Przeczytaj artykuły w sekcji Blog i zrozum przyczyny tej rozwojowej burzy, która dzieje się w jego głowie.', title_pt = 'A crise dos 2 anos 📱', body_pt = 'Está cansada de ouvir "não" a tudo? Leia os artigos do Blogue e perceba as causas desta tempestade de desenvolvimento que se passa no cérebro dele.', title_sv = 'Tvåårstrotsen 📱', body_sv = 'Är du trött på att barnet säger nej till allt? Läs artiklarna i avsnittet Bloggar och förstå orsakerna till utvecklingsstormen i barnets hjärna.', title_vi = 'Khủng hoảng tuổi lên 2 📱', body_vi = 'Bé nói "không" với mọi thứ khiến mẹ mệt mỏi? Hãy đọc các bài viết trong mục Blog để hiểu nguyên nhân của "cơn bão phát triển" đang diễn ra trong não bé.', title_zh = '2岁综合征 📱', body_zh = '孩子什么都说“不”，让你心累？读读博客板块里的文章，了解宝宝大脑里这场成长风暴的原因。' WHERE id = '505c8d78-0b81-4cb5-96f5-e5571e1fc049' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Tira del plato las hojas verdes o el brócoli? Descubre en Recetas para bebé unas magdalenas caseras de colores con verduras y alcanza sin esfuerzo su ración de vitaminas en el Seguimiento de tomas.', body_fr = 'Il jette les légumes verts ou le brocoli de son assiette ? Découvrez dans les Recettes pour bébés des muffins maison colorés aux légumes et atteignez facilement ses besoins en vitamines dans le Suivi des repas.', body_hi = 'हरी सब्ज़ियाँ या ब्रोकली थाली से फेंक देता है? बच्चों की रेसिपी में रंग-बिरंगा, सब्ज़ियों वाला घर का बना केक खोजिए और फ़ीडिंग ट्रैकर में विटामिन का लक्ष्य आसानी से पूरा कीजिए।', body_id = 'Ia melempar sayuran hijau atau brokoli dari piring? Temukan muffin rumahan penuh sayur yang warna-warni di Resep Bayi dan penuhi kebutuhan vitaminnya dengan mudah di Pemantau Nutrisi.', body_ja = '青菜やブロッコリーをお皿から投げますか？「離乳食を始める赤ちゃんのレシピ」でカラフルな野菜入りの手作りマフィンを見つけて、「栄養管理ツール」のビタミン目標を楽にクリアしましょう。', body_ko = '채소나 브로콜리를 접시 밖으로 던지나요? 아기 레시피에서 알록달록한 채소 홈메이드 머핀을 찾아보고, 수유 기록 도구로 비타민 기준량을 쉽게 채워 주세요.', body_nl = 'Gooit hij groenten of broccoli van zijn bord? Ontdek in Babyrecepten kleurrijke zelfgebakken groentemuffins en haal makkelijk de vitaminenorm in de Voedingstracker.', body_pl = 'Zrzuca z talerza zieleninę albo brokuły? Odkryj w Przepisach dla niemowląt kolorowe domowe babeczki z warzywami i łatwo osiągnij normę witamin w narzędziu do śledzenia karmienia.', body_pt = 'Atira as verduras ou os brócolos para fora do prato? Descubra nas Receitas para bebé um queque caseiro colorido com legumes e atinja facilmente a dose de vitaminas no Registo de Alimentação.', body_sv = 'Kastar barnet bort grönsakerna eller broccolin från tallriken? Upptäck färgglada hemgjorda muffins med grönsaker i Babyrecept och nå lätt vitaminnormen i Matningskoll.', body_vi = 'Bé ném rau xanh hay bông cải xanh ra khỏi đĩa? Hãy khám phá món bánh nướng nhiều màu với rau củ làm tại nhà trong Công thức cho bé và dễ dàng đạt định mức vitamin trong Theo dõi cữ bú.', body_zh = '把绿叶菜或西兰花从盘子里扔出去？在宝宝食谱里找找五颜六色的自制蔬菜蛋糕，轻松达到喂养记录工具里的维生素标准。' WHERE id = '5e96bc6a-ca0b-4e3c-9cde-441c31566ab3' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Abrazos de «Te quiero» 🫂', body_es = '¿De repente viene y te abraza el cuello o te acaricia la cara? Ya muestra su cariño físicamente. Disfruta de la paz inigualable que trae este momento.', title_fr = 'Les câlins « Je t''aime » 🫂', body_fr = 'Il vient soudain se jeter à votre cou ou vous caresser le visage ? Il montre désormais son amour physiquement. Savourez la paix incomparable de ce moment.', title_hi = '''आई लव यू'' वाली झप्पी 🫂', body_hi = 'अचानक आकर गले से लिपट जाता है या आपका चेहरा सहलाता है? वह अब अपना प्यार शारीरिक रूप से जताने लगा है। इस पल के अनोखे सुकून का पूरा आनंद लीजिए।', title_id = 'Pelukan ''Aku Sayang Kamu'' 🫂', body_id = 'Tiba-tiba ia datang memeluk leher Anda atau membelai wajah Anda? Ia kini menunjukkan cintanya secara fisik. Nikmati ketenangan tiada tara dari momen ini.', title_ja = '「大好き」のハグ 🫂', body_ja = '急に来て首に抱きついたり、顔をなでたりしますか？もう体で愛情を表しています。この瞬間がくれる、かけがえのない安らぎを味わいましょう。', title_ko = '''사랑해'' 포옹 🫂', body_ko = '갑자기 다가와 목을 끌어안거나 얼굴을 쓰다듬나요? 이제 몸으로 사랑을 표현하고 있어요. 이 순간이 주는 더없는 평온을 마음껏 누리세요.', title_nl = '''Ik hou van je''-knuffels 🫂', body_nl = 'Komt hij ineens je nek omhelzen of je gezicht aaien? Hij toont zijn liefde nu ook lichamelijk. Geniet van de onvergelijkbare rust van dit moment.', title_pl = 'Przytulasy „Kocham cię” 🫂', body_pl = 'Nagle podchodzi i obejmuje cię za szyję albo głaszcze po twarzy? Okazuje już swoją miłość fizycznie. Delektuj się niezrównanym spokojem, jaki daje ta chwila.', title_pt = 'Abraços de "Gosto de ti" 🫂', body_pt = 'De repente vem abraçar-lhe o pescoço ou acariciar-lhe a cara? Já mostra o seu amor fisicamente. Saboreie a paz incomparável deste momento.', title_sv = 'Jag älskar dig-kramen 🫂', body_sv = 'Kommer barnet plötsligt och slår armarna om din hals eller smeker ditt ansikte? Barnet visar redan sin kärlek fysiskt. Njut av det ojämförliga lugnet i det här ögonblicket.', title_vi = 'Cái ôm "Con yêu mẹ" 🫂', body_vi = 'Bé bất ngờ chạy đến ôm cổ hay vuốt má mẹ? Giờ đây bé đã thể hiện tình yêu bằng hành động. Hãy tận hưởng sự bình yên vô giá mà khoảnh khắc này mang lại.', title_zh = '“我爱你”的拥抱 🫂', body_zh = '突然跑过来搂住你的脖子，或者摸摸你的脸？宝宝已经会用身体表达爱了。好好享受这一刻带来的无比安宁吧。' WHERE id = '9d6f4449-54d1-4585-9f63-6d19afec1bda' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Pronuncia algunas palabras a medias o de forma muy graciosa? No te rías: repítele la forma correcta con la entonación adecuada para que su cerebro grabe la versión correcta.', body_fr = 'Il prononce certains mots à moitié ou de façon très drôle ? Ne riez pas, répétez-lui plutôt le mot correctement avec la bonne intonation pour que son cerveau retienne la bonne version.', body_hi = 'कुछ शब्द अधूरे या बहुत मज़ेदार ढंग से बोलता है? हँसिए मत, बल्कि सही लहजे के साथ सही शब्द दोहराइए ताकि उसका दिमाग सही रूप याद रखे।', body_id = 'Ia mengucapkan beberapa kata setengah-setengah atau dengan lucu sekali? Jangan tertawa, ulangi kata yang benar dengan tekanan yang tepat agar otaknya merekam versi yang benar.', body_ja = '言葉を途中までしか言えなかったり、とてもおもしろい発音をしたりしますか？笑わないで、正しいアクセントでくり返してあげて。脳が正しい形を覚えられます。', body_ko = '어떤 단어를 덜 완성하거나 아주 웃기게 발음하나요? 웃지 말고 올바른 발음과 억양으로 다시 들려주세요. 그래야 뇌가 바른 말을 기억해요.', body_nl = 'Spreekt hij sommige woorden half of heel grappig uit? Lach niet, maar herhaal het juiste woord met de goede klemtoon, zodat zijn hersenen de juiste versie opslaan.', body_pl = 'Niektóre słowa wymawia niedokończone albo bardzo zabawnie? Nie śmiej się, tylko powtórz mu poprawną wersję z właściwym akcentem, by jego mózg zakodował dobry wariant.', body_pt = 'Pronuncia algumas palavras pela metade ou de forma muito cómica? Não se ria, mas repita a forma certa com a entoação correta para que o cérebro dele grave a versão correta.', body_sv = 'Uttalar barnet vissa ord till hälften eller väldigt komiskt? Skratta inte, men upprepa det rätta ordet med rätt betoning så att hjärnan lär in rätt variant.', body_vi = 'Bé phát âm một số từ chưa tròn hoặc rất buồn cười? Đừng cười, mà hãy nhắc lại cách nói đúng với ngữ điệu chuẩn để não bé ghi nhớ phiên bản đúng.', body_zh = '有些词说得不完整，或者发音特别搞笑？别笑，用正确的重音把正确的说法重复给宝宝听，让大脑记住正确的版本。' WHERE id = 'de182c61-510f-445a-9f50-8ed2459f90cf' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un momento que detiene el tiempo 📸', body_es = 'Cuando duerma, mira su carita inocente. Aunque te haya vuelto loca todo el día, en cuanto se duerme ya le echas de menos, ¿verdad? La maternidad es justo esta paradoja.', title_fr = 'L''instant qui arrête le temps 📸', body_fr = 'Quand il dort, regardez son visage innocent. Même s''il vous a rendue folle toute la journée, il vous manque dès qu''il s''endort, n''est-ce pas ? La maternité, c''est exactement ce paradoxe.', title_hi = 'समय को थाम लेने वाला पल 📸', body_hi = 'बच्चा सो जाए तो उसके मासूम चेहरे को देखिए। दिनभर भले उसने आपको परेशान किया हो, सोते ही आपको उसकी याद आने लगती है, है ना? माँ होना यही विरोधाभास है।', title_id = 'Momen yang menghentikan waktu 📸', body_id = 'Saat anak tidur, pandangi wajah polosnya. Meski seharian ia membuat Anda pusing, begitu ia tidur Anda langsung rindu, bukan? Itulah paradoks menjadi ibu.', title_ja = '時間が止まる瞬間 📸', body_ja = 'お子さんが眠ったら、その無邪気な寝顔を見てみて。一日じゅう振り回されても、眠ったとたんに恋しくなりませんか？それこそが子育ての不思議なところです。', title_ko = '시간이 멈추는 순간 📸', body_ko = '아이가 잠들면 그 순수한 얼굴을 바라보세요. 하루 종일 정신없게 했어도 잠들자마자 보고 싶어지죠? 엄마가 된다는 건 바로 이런 모순이에요.', title_nl = 'Een moment dat de tijd stilzet 📸', body_nl = 'Kijk als hij slaapt naar zijn onschuldige gezichtje. Ook al maakte hij je de hele dag gek, zodra hij slaapt mis je hem, toch? Dat is precies de paradox van het moederschap.', title_pl = 'Chwila, która zatrzymuje czas 📸', body_pl = 'Gdy dziecko śpi, popatrz na jego niewinną buzię. Choć przez cały dzień doprowadzało cię do szału, tęsknisz za nim, gdy tylko zaśnie, prawda? Macierzyństwo to właśnie ten paradoks.', title_pt = 'O momento que para o tempo 📸', body_pt = 'Quando a criança dorme, olhe para aquele rosto inocente. Mesmo que a tenha deixado à beira de um ataque de nervos o dia todo, mal adormece sente saudades dele, não é? A maternidade é exatamente este paradoxo.', title_sv = 'Stunden som stoppar tiden 📸', body_sv = 'Titta på barnets oskyldiga ansikte när hen sover. Även om hen gjort dig galen hela dagen saknar du hen så fort hen somnat, eller hur? Det är precis den paradoxen som är moderskap.', title_vi = 'Khoảnh khắc ngưng đọng thời gian 📸', body_vi = 'Khi bé ngủ, hãy ngắm gương mặt ngây thơ ấy. Dù cả ngày bé khiến mẹ phát điên, vừa ngủ là mẹ đã nhớ bé rồi, phải không? Làm mẹ chính là nghịch lý ngọt ngào ấy.', title_zh = '让时间停下的瞬间 📸', body_zh = '孩子睡着时，看看那张天真的小脸。就算白天被折腾得快疯了，一睡着你就开始想宝宝了，对吧？当妈妈就是这样的矛盾。' WHERE id = '3ead07a7-4417-4744-9277-6bedf5fa245b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El hábito de beber agua 💧', body_es = '¿Pide zumos dulces todo el rato en lugar de agua? Revisa los líquidos en el Plan de alimentación. Anímale ofreciéndole el agua en vasos de colores con pajita especial.', title_fr = 'L''habitude de boire de l''eau 💧', body_fr = 'Il réclame sans cesse des jus sucrés au lieu de l''eau ? Vérifiez ses apports en liquides dans le Plan de nutrition. Encouragez-le en lui proposant l''eau dans des gobelets colorés avec une paille spéciale.', title_hi = 'पानी पीने की आदत 💧', body_hi = 'पानी की जगह बार-बार मीठा जूस माँगता है? फ़ीडिंग प्लान में तरल की मात्रा देखिए। रंग-बिरंगे, खास स्ट्रॉ वाले गिलास में पानी देकर उसका उत्साह बढ़ाइए।', title_id = 'Kebiasaan minum air 💧', body_id = 'Ia terus minta jus manis alih-alih air? Periksa asupan cairannya di Rencana Nutrisi. Dorong ia minum dengan menyajikan air di gelas berwarna dengan sedotan khusus.', title_ja = 'お水を飲む習慣 💧', body_ja = 'お水のかわりに甘いジュースばかり欲しがりますか？「栄養管理ツール」で水分量を確認しましょう。カラフルなストローつきのコップでお水を出して、飲む気持ちを引き出して。', title_ko = '물 마시는 습관 💧', body_ko = '물 대신 단 주스만 찾나요? 식단 계획에서 수분 섭취를 확인하세요. 알록달록한 컵이나 특별한 빨대컵에 물을 담아 주며 마시고 싶게 해 주세요.', title_nl = 'De gewoonte van water drinken 💧', body_nl = 'Wil hij steeds zoete sapjes in plaats van water? Check zijn vochtinname in het Voedingsplan. Moedig hem aan door water in kleurrijke bekers met een speciaal rietje te geven.', title_pl = 'Nawyk picia wody 💧', body_pl = 'Zamiast wody ciągle chce słodkich soków? Sprawdź ilość płynów w planie karmienia. Zachęcaj go, podając wodę w kolorowych kubeczkach ze specjalną słomką.', title_pt = 'O hábito de beber água 💧', body_pt = 'Pede sumos doces em vez de água? Verifique a ingestão de líquidos no Plano Alimentar. Ofereça água em copos coloridos com palhinha especial para o motivar.', title_sv = 'Vanan att dricka vatten 💧', body_sv = 'Vill barnet hela tiden ha söt saft i stället för vatten? Kolla vätskeintaget i matplanen. Uppmuntra barnet genom att servera vattnet i färgglada muggar med speciella sugrör.', title_vi = 'Thói quen uống nước 💧', body_vi = 'Bé cứ đòi nước trái cây ngọt thay vì nước lọc? Hãy kiểm tra lượng chất lỏng trong Kế hoạch dinh dưỡng. Khuyến khích bé bằng cách cho uống nước trong những chiếc cốc nhiều màu có ống hút đặc biệt.', title_zh = '喝水的习惯 💧', body_zh = '总想喝甜果汁，不想喝水？在喂养计划里看看饮水情况。用彩色的、带特别吸管的杯子装水，激发宝宝的兴趣。' WHERE id = '5f09ad8f-0fde-4f65-8032-dfe56e435a81' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El equipo de los aplausos 👏', body_es = '¿Cuando consigue algo se aplaude solo de alegría? En cuanto veas este gran momento, haced en casa un pequeño baile de la victoria y únete a su alegría.', title_fr = 'L''équipe des applaudissements 👏', body_fr = 'Quand il réussit quelque chose, il s''applaudit tout seul de joie ? Dès que vous voyez ce moment génial, faites une petite danse de la victoire et partagez sa joie !', title_hi = 'ताली बजाओ टीम 👏', body_hi = 'कुछ कर लेने पर खुद ही ताली बजाकर अपनी खुशी जताता है? यह शानदार पल देखते ही घर में एक छोटा सा जीत का डांस कीजिए और उसकी खुशी में शामिल हो जाइए!', title_id = 'Tim tepuk tangan 👏', body_id = 'Saat berhasil melakukan sesuatu, ia bertepuk tangan sendiri dengan gembira? Begitu melihat momen hebat ini, lakukan tarian kemenangan kecil di rumah dan ikutlah bergembira!', title_ja = '拍手チーム 👏', body_ja = '何かができると、自分で拍手してよろこびを表しますか？このすばらしい瞬間を見たら、家で小さな勝利のダンスをして、一緒によろこびましょう！', title_ko = '박수 팀 👏', body_ko = '무언가를 해내면 스스로 박수 치며 기뻐하나요? 이 멋진 순간을 보면 집에서 작은 승리의 춤을 추며 함께 기뻐해 주세요!', title_nl = 'Het klapteam 👏', body_nl = 'Klapt hij voor zichzelf als iets lukt en laat hij zijn blijdschap zien? Zodra je dit prachtige moment ziet: doe een klein overwinningsdansje en deel in zijn vreugde!', title_pl = 'Drużyna oklasków 👏', body_pl = 'Gdy coś mu się uda, sam sobie klaszcze z radości? Gdy tylko zobaczysz tę wspaniałą chwilę, zatańcz w domu mały taniec zwycięstwa i dołącz do jego radości!', title_pt = 'Equipa das palmas 👏', body_pt = 'Quando consegue fazer algo, bate palmas a si próprio e mostra a sua alegria? Quando vir este momento fantástico, faça uma pequena dança da vitória em casa e junte-se à alegria dele!', title_sv = 'Klappteamet 👏', body_sv = 'Klappar barnet händerna för sig själv och visar sin glädje när något lyckas? Så fort du ser det här fantastiska ögonblicket, gör en liten segerdans hemma och dela barnets glädje!', title_vi = 'Đội vỗ tay 👏', body_vi = 'Khi làm được điều gì đó, bé tự vỗ tay và thể hiện niềm vui? Ngay khi thấy khoảnh khắc tuyệt vời này, hãy nhảy một điệu mừng chiến thắng nho nhỏ và cùng chung vui với bé!', title_zh = '拍手小队 👏', body_zh = '做成一件事就自己拍手表达开心？看到这个精彩时刻，就在家里跳一段小小的胜利舞，加入宝宝的喜悦吧！' WHERE id = 'e8fd5bc0-a904-4768-8c61-d9259b243761' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Corre mucho y bebe poca agua? Fíjate en las deposiciones en el orinal o el pañal. Si hay riesgo de estreñimiento, anótalo en la app y añade enseguida avena o pera a su menú con el Seguimiento de tomas.', body_fr = 'Il court beaucoup et boit peu ? Surveillez ses selles dans le pot ou la couche. En cas de risque de constipation, notez-le dans l''application et ajoutez tout de suite de l''avoine ou des poires à son menu avec le Suivi des repas.', body_hi = 'खूब दौड़ता है, पर पानी कम पीता है? पॉटी या डायपर में मल पर नज़र रखिए। अगर कब्ज़ का खतरा हो, तो ऐप में दर्ज कीजिए और फ़ीडिंग ट्रैकर से तुरंत मेन्यू में ओट्स या नाशपाती जोड़िए।', body_id = 'Banyak berlari, sedikit minum? Perhatikan kotorannya di pispot atau popok. Jika ada risiko sembelit, catat di aplikasi dan segera tambahkan oat atau pir ke menunya lewat Pemantau Nutrisi.', body_ja = 'よく走るのに、お水はあまり飲まない？おまるやおむつで便の様子をチェックしましょう。便秘が心配なら、アプリに記録して、すぐに「栄養管理ツール」でメニューにオートミールや洋なしを加えて。', body_ko = '많이 뛰는데 물은 적게 마시나요? 아기 변기나 기저귀에서 배변을 살펴보세요. 변비가 걱정된다면 앱에 기록하고 수유 기록 도구로 식단에 귀리나 배를 바로 추가하세요.', body_nl = 'Rent hij veel en drinkt hij weinig? Let op zijn ontlasting in het potje of de luier. Is er kans op verstopping, noteer het dan in de app en voeg met de Voedingstracker meteen havermout of peer toe aan zijn menu.', body_pl = 'Dużo biega, mało pije? Obserwuj wypróżnienia w nocniku lub pieluszce. Jeśli grozi zaparcie, zapisz to w aplikacji i od razu dodaj do menu w narzędziu do śledzenia karmienia płatki owsiane lub gruszkę.', body_pt = 'Corre muito e bebe pouca água? Repare nas fezes no bacio ou na fralda. Se houver risco de prisão de ventre, registe na app e junte logo aveia ou pera à ementa com o Registo de Alimentação.', body_sv = 'Springer barnet mycket men dricker lite vatten? Håll koll på avföringen i pottan eller blöjan. Om det finns risk för förstoppning, anteckna det i appen och lägg direkt till havre eller päron i menyn med Matningskoll.', body_vi = 'Bé chạy nhiều mà uống ít nước? Hãy để ý chất thải trong bô hoặc tã. Nếu có nguy cơ táo bón, hãy ghi vào ứng dụng và thêm ngay yến mạch hoặc lê vào thực đơn bằng Theo dõi cữ bú.', body_zh = '跑得多、喝得少？留意便盆或尿布里的排便情况。如果有便秘风险，在应用里记下来，马上用喂养记录工具在菜单里加上燕麦或梨。' WHERE id = '0727c4e7-7433-410a-9da5-27fff69d9877' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Buscando nuevos amigos 👫', body_es = '¿En el parque intenta correr con otros niños de su edad y acercarse a ellos? ¡La socialización ya está en marcha! Vigílale de lejos y observa con orgullo estos intentos.', title_fr = 'À la recherche de nouveaux amis 👫', body_fr = 'Au parc, il essaie de courir avec les enfants de son âge et de s''approcher d''eux ? La socialisation est officiellement lancée ! Surveillez de loin ces tentatives avec fierté.', title_hi = 'नए दोस्त की तलाश 👫', body_hi = 'पार्क में अपने हमउम्र बच्चों के साथ दौड़ने और उनके पास जाने की कोशिश करता है? सामाजिकता अब शुरू हो चुकी है! दूर से नज़र रखते हुए इन कोशिशों को गर्व से देखिए।', title_id = 'Mencari teman baru 👫', body_id = 'Ia mencoba berlari bersama teman sebayanya di taman dan mendekati mereka? Sosialisasi resmi dimulai! Awasi dari jauh dan saksikan usahanya dengan bangga.', title_ja = '新しいお友だち探し 👫', body_ja = '公園で同じ年ごろの子と一緒に走ったり、近づこうとしたりしていますか？社会性がいよいよ動き出しました！少し離れて見守りながら、この挑戦を誇らしく眺めましょう。', title_ko = '새 친구 찾기 👫', body_ko = '공원에서 또래와 함께 뛰고 다가가려고 하나요? 사회성이 본격적으로 자라고 있어요! 멀리서 안전을 지키며 이 시도를 뿌듯하게 지켜보세요.', title_nl = 'Op zoek naar nieuwe vriendjes 👫', body_nl = 'Probeert hij in het park met leeftijdsgenootjes mee te rennen en toenadering te zoeken? De socialisatie is officieel begonnen! Houd hem op afstand in de gaten en kijk trots naar deze pogingen.', title_pl = 'W poszukiwaniu nowych przyjaciół 👫', body_pl = 'W parku próbuje biegać z rówieśnikami i do nich podchodzić? Socjalizacja oficjalnie ruszyła! Asekuruj go z daleka i z dumą obserwuj te próby.', title_pt = 'À procura de novos amigos 👫', body_pt = 'No parque, tenta correr com crianças da idade dele e aproximar-se delas? A socialização está oficialmente em marcha! Vigie de longe e acompanhe estas tentativas com orgulho.', title_sv = 'På jakt efter nya vänner 👫', body_sv = 'Försöker barnet springa med jämnåriga i parken och närma sig dem? Socialiseringen är officiellt igång! Håll ett öga på avstånd och se stolt på de här försöken.', title_vi = 'Đi tìm bạn mới 👫', body_vi = 'Bé cố chạy theo các bạn cùng tuổi ở công viên và lại gần các bạn? Bé chính thức bắt đầu hòa nhập xã hội! Hãy trông chừng từ xa và tự hào ngắm những nỗ lực này.', title_zh = '寻找新朋友 👫', body_zh = '在公园里想跟同龄小朋友一起跑，主动靠近他们？社交正式开始啦！在远处护着宝宝，骄傲地看着这些尝试。' WHERE id = '5730e69b-8e67-40bb-94c5-56cb9dd41a75' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La melodía de la noche 🛀', body_es = 'Después de correr todo el día, estáis agotados los dos. Un baño templado y una melodía suave y tranquila de fondo calmarán por completo su sistema nervioso.', title_fr = 'La mélodie du soir 🛀', body_fr = 'Après avoir couru toute la journée, vous êtes épuisés tous les deux. Un bain tiède et une mélodie douce en fond sonore apaiseront complètement son système nerveux.', title_hi = 'रात की धुन 🛀', body_hi = 'दिनभर भागदौड़ से वह भी थक गया और आप भी। गुनगुना स्नान और पीछे बजती हल्की, धीमी धुन उसके नर्वस सिस्टम को पूरी तरह शांत कर देगी।', title_id = 'Melodi malam 🛀', body_id = 'Seharian berlarian, ia dan Anda sama-sama kelelahan. Mandi air hangat dengan alunan melodi lembut di latar belakang akan menenangkan sistem sarafnya sepenuhnya.', title_ja = '夜のメロディー 🛀', body_ja = '一日じゅう走り回って、ふたりともへとへと。ぬるめのお風呂と、後ろで流れるやさしく穏やかなメロディーが、神経をすっかり落ち着かせてくれます。', title_ko = '밤의 멜로디 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤죠. 따뜻한 목욕과 잔잔하게 흐르는 부드러운 멜로디가 아이의 신경을 편안하게 진정시켜 줄 거예요.', title_nl = 'Avondmelodie 🛀', body_nl = 'Jullie zijn allebei op van een hele dag rennen. Een lauw bad met een zacht, rustig melodietje op de achtergrond kalmeert zijn zenuwstelsel helemaal.', title_pl = 'Melodia nocy 🛀', body_pl = 'Po całym dniu biegania oboje jesteście wykończeni. Ciepła kąpiel i lekka, łagodna melodia w tle całkowicie uspokoją jego układ nerwowy.', title_pt = 'Melodia da noite 🛀', body_pt = 'Depois de correrem o dia todo, estão os dois esgotados. Um banho morno e uma melodia suave a tocar em fundo vão acalmar completamente o sistema nervoso dele.', title_sv = 'Nattens melodi 🛀', body_sv = 'Både du och barnet är helt slut efter en hel dag i farten. Ett ljummet bad och en lätt, lugn melodi i bakgrunden lugnar barnets nervsystem helt.', title_vi = 'Giai điệu của đêm 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều kiệt sức. Một bồn nước ấm cùng giai điệu nhẹ nhàng, êm dịu vang lên phía sau sẽ giúp hệ thần kinh của bé hoàn toàn dịu lại.', title_zh = '夜晚的旋律 🛀', body_zh = '跑了一整天，宝宝和你都累坏了。一次温水澡，加上背景里轻柔舒缓的旋律，会让宝宝的神经系统彻底放松下来。' WHERE id = 'a11a0d3a-a9c4-402b-9b3c-bc6d874fc9a7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Otra vez no se ha dormido? No luches y os agotéis los dos. Jugar en silencio con sus juguetes en la habitación también es una forma de descanso para el cerebro.', body_fr = 'Il ne s''est encore pas endormi ? Ne luttez pas, vous vous épuiseriez tous les deux. Jouer tranquillement avec ses jouets dans la chambre, c''est aussi une forme de repos pour le cerveau.', body_hi = 'फिर से नहीं सोया? लड़कर उसे और खुद को मत थकाइए। कमरे में चुपचाप खिलौनों से खेलना भी दिमाग के लिए एक तरह का आराम है।', body_id = 'Lagi-lagi tidak tidur? Jangan berdebat hingga ia dan Anda sama-sama lelah. Bermain mainan dengan tenang di kamar juga salah satu cara otak beristirahat.', body_ja = 'また寝なかった？戦ってお互いに疲れないで。部屋で静かにおもちゃで遊ぶことも、脳にとってはひとつの休息です。', body_ko = '또 잠들지 않았나요? 씨름하며 아이도 엄마도 지치게 하지 마세요. 방에서 조용히 장난감을 가지고 노는 것도 뇌에는 하나의 휴식이에요.', body_nl = 'Weer niet in slaap gevallen? Ga de strijd niet aan en put jullie allebei niet uit. Rustig in de kamer met speelgoed spelen is ook een vorm van rust voor de hersenen.', body_pl = 'Znowu nie zasnął? Nie walcz, męcząc jego i siebie. Ciche bawienie się zabawkami w pokoju to też rodzaj odpoczynku dla mózgu.', body_pt = 'Outra vez não adormeceu? Não lute nem se canse, nem a ele. Brincar em silêncio com os brinquedos no quarto também é uma forma de descanso para o cérebro.', body_sv = 'Somnade barnet inte nu heller? Kämpa inte så att både barnet och du blir utmattade. Att leka tyst med leksaker i rummet är också en form av vila för hjärnan.', body_vi = 'Bé lại không ngủ? Đừng giằng co khiến cả hai mẹ con kiệt sức. Lặng lẽ chơi đồ chơi trong phòng cũng là một cách nghỉ ngơi cho não bộ.', body_zh = '又没睡着？别硬碰硬，把宝宝和自己都累坏。在房间里安静地玩玩具，对大脑来说也是一种休息。' WHERE id = '100fc6ed-66a7-4e9e-939c-15af0683652e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Se ha dormido! En lugar de vaciar el lavavajillas, siéntate en la habitación a oscuras. Valora 15 minutos de silencio y descansa.', body_fr = 'Il dort ! Au lieu de vider le lave-vaisselle, asseyez-vous dans la pénombre de la chambre. Savourez 15 minutes de silence et reposez-vous.', body_hi = 'वह सो गया! अब डिशवॉशर खाली करने के बजाय कमरे के अंधेरे में बैठ जाइए। 15 मिनट की खामोशी की कद्र कीजिए और आराम कीजिए।', body_id = 'Ia sudah tidur! Daripada mengosongkan mesin cuci piring, duduklah dalam gelapnya kamar. Hargai 15 menit keheningan ini dan beristirahatlah.', body_ja = '眠りました！食洗機を片づけるかわりに、暗い部屋で座りましょう。15分間の静けさをかみしめて、休んで。', body_ko = '잠들었어요! 식기세척기를 비우는 대신 어두운 방에 가만히 앉아 보세요. 15분의 고요를 소중히 누리며 쉬세요.', body_nl = 'Hij slaapt! Ruim nu niet de vaatwasser uit, maar ga in de donkere kamer zitten. Waardeer 15 minuten stilte en rust uit.', body_pl = 'Zasnął! Zamiast teraz rozładowywać zmywarkę, usiądź w ciemnym pokoju. Doceń 15 minut ciszy i odpocznij.', body_pt = 'Adormeceu! Em vez de esvaziar a máquina da loiça, sente-se na penumbra do quarto. Aproveite 15 minutos de silêncio e descanse.', body_sv = 'Barnet sover! I stället för att tömma diskmaskinen, sätt dig i det mörka rummet. Uppskatta 15 minuters tystnad och vila.', body_vi = 'Bé ngủ rồi! Thay vì dỡ bát đĩa trong máy rửa bát, hãy ngồi yên trong căn phòng tối. Trân trọng 15 phút tĩnh lặng và nghỉ ngơi nhé.', body_zh = '宝宝睡着了！现在别去收拾洗碗机，在昏暗的房间里坐一会儿。珍惜这15分钟的安静，好好休息。' WHERE id = 'ca5c9545-5eb9-432c-acea-7e6fe2c5ab98' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ya se coge los dedos de los pies para explorarlos y hasta disfruta andando descalzo? Descubrir los nervios de la planta del pie es muy importante para su equilibrio.', body_fr = 'Il attrape ses orteils pour les examiner et adore même marcher pieds nus ? Découvrir les nerfs de la plante des pieds est très important pour son équilibre.', body_hi = 'वह अब पैर की उँगलियाँ पकड़कर उन्हें परखता है और नंगे पैर चलने का मज़ा लेता है? तलवों की नसों की यह खोज उसके संतुलन के लिए बहुत ज़रूरी है।', body_id = 'Ia sudah memegang dan memeriksa jari kakinya, bahkan senang berjalan tanpa alas kaki? Mengenal saraf di telapak kaki sangat penting untuk keseimbangannya.', body_ja = '足の指をつかんで調べたり、はだしで歩くのを楽しんだりしていますか？足の裏の神経を発見することは、バランス感覚にとってとても大切です。', body_ko = '이제 발가락을 잡고 살펴보거나 맨발로 걷는 걸 즐기나요? 발바닥 신경을 발견하는 건 균형 감각에 아주 중요해요.', body_nl = 'Pakt hij al zijn tenen vast om ze te bekijken en loopt hij graag op blote voeten? Het ontdekken van de zenuwen onder zijn voetzolen is heel belangrijk voor zijn evenwicht.', body_pl = 'Łapie się już za palce u stóp i je bada, a nawet z przyjemnością chodzi boso? Odkrywanie nerwów na podeszwach stóp jest bardzo ważne dla jego równowagi.', body_pt = 'Já agarra os dedos dos pés para os explorar e até gosta de andar descalço? Descobrir os nervos da planta do pé é muito importante para o equilíbrio dele.', body_sv = 'Tar barnet redan tag i tårna och undersöker dem, och tycker till och med om att gå barfota? Att upptäcka nerverna under fötterna är väldigt viktigt för balansen.', body_vi = 'Bé đã biết nắm ngón chân để khám phá, thậm chí thích đi chân trần? Việc khám phá các dây thần kinh dưới lòng bàn chân rất quan trọng cho khả năng giữ thăng bằng.', body_zh = '已经会抓着脚趾研究，甚至喜欢光着脚走路了？探索脚底的神经对宝宝的平衡非常重要。' WHERE id = 'cc9ba302-22d8-43e5-a70d-2bed916f8d33' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se aparta y dice «no» con firmeza cuando alguien quiere darle un beso? Respeta los límites de su cuerpo. Es muy importante que proteste ante el contacto sin permiso.', body_fr = 'Quand quelqu''un veut l''embrasser, il recule et dit « non » fermement ? Respectez les limites de son corps. C''est très important qu''il puisse refuser les contacts non désirés.', body_hi = 'कोई उसे चूमना चाहे तो दूर हट जाता है और सख्ती से ''नहीं'' कहता है? उसके शरीर की सीमाओं का सम्मान कीजिए। बिना इजाज़त छूने का विरोध करना बहुत ज़रूरी है।', body_id = 'Saat seseorang ingin menciumnya, ia menjauh dan tegas berkata tidak? Hormati batas tubuhnya. Sangat penting ia berani menolak sentuhan tanpa izin.', body_ja = 'だれかにキスされそうになると離れて、きっぱり「いや」と言いますか？体の境界線を尊重しましょう。許可のないふれあいを拒めることは、とても大切です。', body_ko = '누가 뽀뽀하려고 하면 피하며 단호하게 ''싫어''라고 하나요? 아이의 몸의 경계를 존중해 주세요. 허락 없는 접촉에 거부할 줄 아는 건 아주 중요해요.', body_nl = 'Trekt hij zich terug en zegt hij stellig ''nee'' als iemand hem wil zoenen? Respecteer zijn lichamelijke grenzen. Het is heel belangrijk dat hij protesteert tegen aanrakingen zonder toestemming.', body_pl = 'Gdy ktoś chce go pocałować, odsuwa się i stanowczo mówi „nie”? Szanuj granice jego ciała. To bardzo ważne, że sprzeciwia się dotykowi bez zgody.', body_pt = 'Quando alguém o quer beijar, afasta-se e diz "não" com firmeza? Respeite os limites do corpo dele. É muito importante que proteste contra toques sem autorização.', body_sv = 'Drar sig barnet undan och säger bestämt nej när någon vill pussa hen? Respektera barnets kroppsliga gränser. Det är väldigt viktigt att hen säger ifrån mot beröring utan lov.', body_vi = 'Khi có ai muốn hôn, bé né ra và dứt khoát nói "không"? Hãy tôn trọng ranh giới cơ thể của bé. Việc bé phản đối những đụng chạm không được cho phép là rất quan trọng.', body_zh = '有人想亲宝宝时，宝宝躲开还坚决说“不”？要尊重宝宝的身体界限。宝宝会拒绝未经允许的触碰，这一点非常重要。' WHERE id = '5c059ccd-12dd-4a31-9da6-6e33ef79b1be' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Estás muy cansada? Entra en la Comunidad Anacan. Lee las historias reales de miles de madres y coge fuerzas sabiendo que no estás sola.', body_fr = 'Très fatiguée ? Rejoignez la Communauté Anacan. Lisez les vraies histoires de milliers de mamans et puisez de la force dans ce sentiment : « je ne suis pas seule ».', body_hi = 'बहुत थक गई हैं? Anacan कम्युनिटी में जाइए। हज़ारों माँओं की असली कहानियाँ पढ़िए और ''मैं अकेली नहीं हूँ'' के एहसास से ताकत जुटाइए।', body_id = 'Sangat lelah? Masuklah ke Komunitas Anacan. Baca kisah nyata ribuan ibu dan kumpulkan kekuatan dengan rasa ''aku tidak sendirian''.', body_ja = 'とても疲れていますか？Anacanコミュニティに参加しましょう。何千人ものママの本当の話を読んで、「ひとりじゃない」という気持ちで力をもらいましょう。', body_ko = '너무 지쳤나요? Anacan 커뮤니티에 들어와 보세요. 수많은 엄마들의 진짜 이야기를 읽으며 ''나만 그런 게 아니구나'' 하고 힘을 얻으세요.', body_nl = 'Ben je erg moe? Ga naar de Anacan Community. Lees de echte verhalen van duizenden moeders en haal kracht uit het gevoel ''ik ben niet alleen''.', body_pl = 'Jesteś bardzo zmęczona? Dołącz do Społeczności Anacan. Przeczytaj prawdziwe historie tysięcy mam i nabierz sił z poczuciem, że nie jesteś sama.', body_pt = 'Está muito cansada? Entre na Comunidade Anacan. Leia as histórias reais de milhares de mães e ganhe forças ao sentir que não está sozinha.', body_sv = 'Är du väldigt trött? Gå in i Anacan Community. Läs tusentals mammors verkliga berättelser och hämta kraft i känslan av att inte vara ensam.', body_vi = 'Mẹ quá mệt mỏi? Hãy vào Cộng đồng Anacan. Đọc những câu chuyện thật của hàng nghìn người mẹ và lấy thêm sức mạnh từ cảm giác "mình không đơn độc".', body_zh = '太累了？进入Anacan社区。读读成千上万位妈妈的真实故事，带着“我不是一个人”的感觉重新攒足力量。' WHERE id = '79a825c4-e46e-4e7d-81f2-4387a7318ef2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Esconde las verduras 🥦', body_es = '¿Aparta todas las verduras de la sopa? No luches. Hacer puré las verduras y esconderlas en salsas o albóndigas es el truco de madre más antiguo.', title_fr = 'Cachez les légumes 🥦', body_fr = 'Il met tous les légumes de la soupe de côté ? Ne luttez pas. Les réduire en purée et les cacher dans les sauces ou les boulettes, c''est la plus vieille astuce de maman.', title_hi = 'सब्ज़ियाँ छिपाइए 🥦', body_hi = 'सूप की सारी सब्ज़ियाँ एक तरफ़ कर देता है? लड़ाई मत कीजिए। सब्ज़ियों को प्यूरी बनाकर सॉस या कटलेट में छिपाना माँओं की सबसे पुरानी तरकीब है।', title_id = 'Sembunyikan sayurannya 🥦', body_id = 'Ia menyisihkan semua sayuran di supnya? Jangan berdebat. Menghaluskan sayuran lalu menyembunyikannya di saus atau perkedel adalah trik ibu paling kuno.', title_ja = '野菜をかくそう 🥦', body_ja = 'スープの野菜を全部よけてしまいますか？戦わないで。野菜をピューレにしてソースやハンバーグの中にかくすのは、昔ながらのママの知恵です。', title_ko = '채소 숨기기 🥦', body_ko = '수프 속 채소를 모두 골라내나요? 씨름하지 마세요. 채소를 퓌레로 만들어 소스나 커틀릿 속에 숨기는 건 가장 오래된 엄마의 비법이에요.', title_nl = 'Verstop de groenten 🥦', body_nl = 'Vist hij alle groenten uit zijn soep? Ga de strijd niet aan. Groenten pureren en in sausjes of gehaktballetjes verstoppen is de oudste moedertruc.', title_pl = 'Ukryj warzywa 🥦', body_pl = 'Odkłada na bok wszystkie warzywa z zupy? Nie walcz z tym. Zmiksowanie warzyw i ukrycie ich w sosach lub kotlecikach to najstarsza sztuczka mam.', title_pt = 'Esconder os legumes 🥦', body_pt = 'Põe de lado todos os legumes da sopa? Não lute. Fazer puré dos legumes e escondê-los nos molhos ou nos hambúrgueres caseiros é o truque mais antigo das mães.', title_sv = 'Göm grönsakerna 🥦', body_sv = 'Lägger barnet alla grönsaker i soppan åt sidan? Kämpa inte emot. Att mosa grönsakerna och gömma dem i såser eller biffar är det äldsta mammaknepet.', title_vi = 'Giấu rau đi 🥦', body_vi = 'Bé gạt hết rau trong bát canh ra một bên? Đừng giằng co. Xay nhuyễn rau rồi giấu vào nước sốt hoặc chả viên là mẹo lâu đời nhất của các mẹ.', title_zh = '把蔬菜藏起来 🥦', body_zh = '把汤里的蔬菜全挑到一边？别硬碰硬。把蔬菜做成泥，藏进酱汁或肉饼里，是妈妈们最古老的妙招。' WHERE id = '0048f15c-3ab2-4568-b3e6-cf763bd916d3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reacción a los dibujos 📖', body_es = '¿Toca los animales u objetos que ve en el libro y hace sonidos? Su percepción visual es asombrosa. Habla con tu peque sobre los personajes del libro.', title_fr = 'Il réagit aux images 📖', body_fr = 'Il touche les animaux ou les objets qu''il voit dans les livres et fait des bruits ? Sa perception visuelle est étonnante. Parlez avec lui des personnages du livre.', title_hi = 'तस्वीरों पर प्रतिक्रिया 📖', body_hi = 'किताब में जानवरों या अलग-अलग चीज़ों को देखकर उन्हें छूता है, आवाज़ें निकालता है? उसकी देखकर समझने की क्षमता कमाल की है। किताब के किरदारों के बारे में उससे बात कीजिए।', title_id = 'Bereaksi pada gambar 📖', body_id = 'Saat melihat hewan atau benda berbeda di buku, ia menyentuhnya dan bersuara? Persepsi visualnya luar biasa. Ajak ia membicarakan tokoh-tokoh di buku.', title_ja = '絵への反応 📖', body_ja = '絵本の動物やいろいろなものを見て、さわったり声を出したりしますか？視覚的な理解力がすばらしいですね。絵本のキャラクターについて一緒に話しましょう。', title_ko = '그림에 반응해요 📖', body_ko = '책 속 동물이나 여러 사물을 보면 만지고 소리를 내나요? 시각 인지가 놀라워요. 책 속 등장인물에 대해 함께 이야기해 보세요.', title_nl = 'Reageren op plaatjes 📖', body_nl = 'Raakt hij dieren of andere dingen in een boek aan en maakt hij er geluidjes bij? Zijn visuele waarneming is geweldig. Praat met hem over de figuren in het boek.', title_pl = 'Reakcja na obrazki 📖', body_pl = 'Dotyka zwierzątek i różnych przedmiotów w książeczce i wydaje przy tym dźwięki? Jego percepcja wzrokowa jest niesamowita. Rozmawiaj z nim o postaciach z książki.', title_pt = 'Reagir às imagens 📖', body_pt = 'Toca nos animais ou nos objetos que vê nos livros e faz sons? A perceção visual é espantosa. Converse com ele sobre as personagens do livro.', title_sv = 'Reaktion på bilder 📖', body_sv = 'Rör barnet vid djuren eller andra föremål i boken och gör ljud när hen ser dem? Synuppfattningen är fantastisk. Prata med barnet om figurerna i boken.', title_vi = 'Phản ứng với tranh ảnh 📖', body_vi = 'Bé chạm vào và phát ra âm thanh khi thấy con vật hay đồ vật trong sách? Khả năng nhận thức thị giác của bé thật đáng kinh ngạc. Hãy trò chuyện với bé về các nhân vật trong sách.', title_zh = '对图片有反应 📖', body_zh = '看到书里的动物或各种东西，就去摸、还发出声音？视觉感知真是惊人。和宝宝聊聊书里的角色吧。' WHERE id = '4d0d3015-35d0-4444-b757-3789d14e8ec4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pilla-pilla del sueño 🏃‍♂️', body_es = '¿No para de inventar excusas para no ir a la cama? Pon el temporizador de sueño, mantén los límites y calma la habitación con el sonido de la lluvia de Ruido blanco.', title_fr = 'Course-poursuite avant le dodo 🏃‍♂️', body_fr = 'Il invente sans arrêt des excuses pour ne pas aller au lit ? Lancez le Minuteur de sommeil, tenez vos limites et apaisez la chambre avec le bruit de la pluie des Bruits blancs.', title_hi = 'नींद से भागम-भाग 🏃‍♂️', body_hi = 'बिस्तर पर न जाने के लिए लगातार बहाने बनाता है? स्लीप टाइमर चालू कीजिए, अपनी सीमाओं पर टिके रहिए और व्हाइट नॉइज़ में बारिश की आवाज़ चलाकर कमरे को शांत कीजिए।', title_id = 'Kejar-kejaran sebelum tidur 🏃‍♂️', body_id = 'Ia terus mencari alasan agar tidak tidur? Nyalakan Timer Tidur, jaga batasan, dan putar suara hujan dari Suara Putih untuk menenangkan kamar.', title_ja = '眠りの追いかけっこ 🏃‍♂️', body_ja = '寝たくなくて、次々と言い訳を考えますか？睡眠タイマーをオンにして、ルールを守りつつ、「ホワイトノイズ」の雨の音で部屋を落ち着かせましょう。', title_ko = '잠과의 술래잡기 🏃‍♂️', body_ko = '자러 가지 않으려고 계속 핑계를 대나요? 수면 타이머를 켜고 경계를 지키며, 백색소음에서 빗소리를 틀어 방을 차분하게 만들어 주세요.', title_nl = 'Tikkertje rond bedtijd 🏃‍♂️', body_nl = 'Verzint hij eindeloos smoesjes om niet naar bed te gaan? Zet de Slaaptimer aan, bewaak je grenzen en kalmeer de kamer met regengeluid uit Witte ruis.', title_pl = 'Wielka gonitwa przed snem 🏃‍♂️', body_pl = 'Bez przerwy wymyśla wymówki, żeby nie iść do łóżka? Włącz timer snu, pilnuj granic i uspokój pokój odgłosem deszczu z Białego szumu.', title_pt = 'A fuga ao sono 🏃‍♂️', body_pt = 'Inventa desculpas sem parar para não ir para a cama? Ligue o temporizador de sono, mantenha os limites e ponha o som de chuva do Ruído Branco para acalmar o quarto.', title_sv = 'Sömnjakten 🏃‍♂️', body_sv = 'Hittar barnet ständigt på ursäkter för att slippa gå och lägga sig? Starta sömntimern, håll gränserna och lugna rummet med regnljudet i Vitt brus.', title_vi = 'Cuộc rượt đuổi giấc ngủ 🏃‍♂️', body_vi = 'Bé liên tục viện cớ để không phải lên giường? Hãy bật Bộ hẹn giờ ngủ, giữ vững giới hạn và bật tiếng mưa trong Tiếng ồn trắng để căn phòng dịu lại.', title_zh = '睡前追逐战 🏃‍♂️', body_zh = '为了不上床，不停地找借口？打开睡眠计时器，守住界限，再打开白噪音里的雨声，让房间安静下来。' WHERE id = 'cfe51929-b2af-45a2-b23e-e670a8d3ebd8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Memoria en quiebra 🛒', body_es = '¿La falta de sueño te ha debilitado la memoria y se te olvida qué comprar en el súper? No cargues la cabeza. Apúntalo todo en una lista y que tu pareja se encargue al volver.', title_fr = 'Panne de mémoire 🛒', body_fr = 'Le manque de sommeil affaiblit votre mémoire et vous oubliez les courses ? Ne vous fatiguez pas la tête. Notez tout sur une liste, votre partenaire s''en chargera en rentrant.', title_hi = 'याददाश्त ने जवाब दे दिया 🛒', body_hi = 'नींद की कमी से याददाश्त कमज़ोर हो गई और बाज़ार से लाने वाली चीज़ें भूल जाती हैं? दिमाग मत थकाइए। सब कुछ लिस्ट में लिखिए, ताकि आपके पार्टनर आते समय ले आएँ।', title_id = 'Otak lupa segalanya 🛒', body_id = 'Kurang tidur membuat Anda pelupa dan belanjaan sering terlupa? Jangan membebani pikiran. Catat semuanya di daftar, biar pasangan yang mengurusnya saat pulang.', title_ja = '記憶のピンチ 🛒', body_ja = '寝不足で記憶力が落ちて、スーパーで買うものを忘れてしまう？頭を疲れさせないで。すべてリストに書いて、パートナーに帰りに買ってきてもらいましょう。', title_ko = '깜빡깜빡 기억력 🛒', body_ko = '잠이 부족해 기억력이 흐려지고 장 볼 것을 자꾸 잊나요? 머리 아프게 기억하지 마세요. 모두 목록에 적어 두고 배우자가 퇴근길에 해결하게 하세요.', title_nl = 'Mamabrein 🛒', body_nl = 'Is je geheugen door slaapgebrek wazig en vergeet je wat je moet kopen? Pijnig je hoofd niet. Zet alles op een lijstje en laat je partner het onderweg naar huis regelen.', title_pl = 'Pamięć zawodzi 🛒', body_pl = 'Przez niewyspanie słabnie ci pamięć i zapominasz, co kupić w sklepie? Nie obciążaj głowy. Zapisz wszystko na liście, a partner załatwi to w drodze do domu.', title_pt = 'Memória em falência 🛒', body_pt = 'A falta de sono enfraqueceu-lhe a memória e esquece-se do que tem de comprar? Não sobrecarregue a cabeça. Aponte tudo numa lista e deixe o seu companheiro tratar disso a caminho de casa.', title_sv = 'Minnet sviker 🛒', body_sv = 'Har sömnbristen försvagat minnet så att du glömmer vad du skulle köpa i affären? Belasta inte hjärnan. Skriv allt på listan och låt din partner fixa det på vägen hem.', title_vi = 'Trí nhớ "đình công" 🛒', body_vi = 'Thiếu ngủ khiến mẹ hay quên và quên luôn cả đồ cần mua ở siêu thị? Đừng bắt mình phải nhớ. Hãy ghi hết vào danh sách để chồng mua trên đường về.', title_zh = '记性罢工了 🛒', body_zh = '睡眠不足让记性变差，在超市总忘了要买什么？别让脑子太累。把所有东西都写进清单，让另一半回家路上顺便搞定。' WHERE id = '6c9cc94d-8363-4a16-b062-eb3e2640d824' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Negociaciones diplomáticas 🤝', body_es = '¿En el parque no deja su juguete? Lee sin falta en el Blog cómo enseñarle, a partir de los 2,5 años, no tanto a compartir sino a jugar por turnos.', title_fr = 'Négociations diplomatiques 🤝', body_fr = 'Il ne veut pas prêter son jouet au parc ? Lisez absolument dans la rubrique Blogs comment lui transmettre, après 2,5 ans, non pas l''idée de partager, mais celle de jouer chacun son tour.', title_hi = 'कूटनीतिक बातचीत 🤝', body_hi = 'पार्क में अपना खिलौना नहीं देता? 2.5 साल के बाद बाँटने की बजाय बारी-बारी से खेलने की समझ कैसे दें, यह ब्लॉग सेक्शन में ज़रूर पढ़िए।', title_id = 'Negosiasi diplomatik 🤝', body_id = 'Ia tidak mau meminjamkan mainannya di taman? Baca di bagian Blog cara menanamkan konsep bermain bergiliran, bukan berbagi, setelah usia 2,5 tahun.', title_ja = '外交交渉 🤝', body_ja = '公園でおもちゃを渡さない？2歳半を過ぎたら、「分け合う」ではなく「順番に遊ぶ」という考え方をどう教えるか、ブログでぜひ読んでみましょう。', title_ko = '외교 협상 🤝', body_ko = '공원에서 장난감을 안 빌려주나요? 두 돌 반 이후에는 나눔보다 차례대로 노는 개념을 어떻게 알려 줄지 블로그 섹션에서 꼭 읽어 보세요.', title_nl = 'Diplomatieke onderhandelingen 🤝', body_nl = 'Geeft hij in het park zijn speelgoed niet af? Lees in Blogs hoe je na 2,5 jaar niet zozeer delen, maar om de beurt spelen aanleert.', title_pl = 'Negocjacje dyplomatyczne 🤝', body_pl = 'Nie oddaje zabawki w parku? Koniecznie przeczytaj w sekcji Blog, jak po 2,5 roku uczyć nie tyle dzielenia się, co zabawy po kolei.', title_pt = 'Negociações diplomáticas 🤝', body_pt = 'No parque, não empresta o brinquedo? Leia sem falta no Blogue como, depois dos 2,5 anos, ensinar não a partilhar, mas a brincar à vez.', title_sv = 'Diplomatiska förhandlingar 🤝', body_sv = 'Vill barnet inte ge bort sin leksak i parken? Läs i avsnittet Bloggar hur du efter 2,5 år lär ut att turas om snarare än att dela.', title_vi = 'Đàm phán ngoại giao 🤝', body_vi = 'Bé không chịu đưa đồ chơi ở công viên? Nhất định hãy đọc trong mục Blog cách dạy bé khái niệm chơi lần lượt, thay vì chia sẻ, sau tuổi 2,5.', title_zh = '外交谈判 🤝', body_zh = '在公园里不肯交出玩具？一定要去博客板块读读，2.5岁以后怎样培养的不是“分享”，而是“轮流玩”的概念。' WHERE id = '8f8c331b-379e-4898-a071-076982bfc0c2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares nocturnos 🌌', body_es = '¿Se despierta llorando en mitad de la noche y no se calma? Mira el gráfico del temporizador de sueño. Para entender la diferencia entre terrores nocturnos y pesadillas, echa ya un vistazo al Blog.', title_fr = 'Réveils nocturnes 🌌', body_fr = 'Il se réveille en pleurant en pleine nuit et ne se calme pas ? Regardez le graphique du Minuteur de sommeil. Pour comprendre la différence entre terreur nocturne et cauchemar, parcourez vite la rubrique Blogs.', title_hi = 'रात में जागना 🌌', body_hi = 'आधी रात को रोते हुए जागता है और शांत नहीं होता? स्लीप टाइमर का चार्ट देखिए। नाइट टेरर और बुरे सपने का फ़र्क समझने के लिए तुरंत ब्लॉग सेक्शन देखिए।', title_id = 'Terbangun malam hari 🌌', body_id = 'Ia terbangun tengah malam sambil menangis dan sulit ditenangkan? Lihat grafik Timer Tidur. Untuk memahami beda teror malam dan mimpi buruk, segera kunjungi bagian Blog.', title_ja = '夜中の目覚め 🌌', body_ja = '夜中に泣いて目を覚まし、なかなか落ち着かない？睡眠タイマーの記録を見てみましょう。夜驚症と悪夢の違いを知るために、すぐにブログをのぞいてみて。', title_ko = '밤에 깨요 🌌', body_ko = '한밤중에 울며 깨서 달래지지 않나요? 수면 타이머 그래프를 살펴보세요. 야경증과 악몽의 차이를 알려면 바로 블로그 섹션을 확인하세요.', title_nl = 'Nachtelijk wakker worden 🌌', body_nl = 'Wordt hij midden in de nacht huilend wakker en is hij niet te troosten? Bekijk het schema in de Slaaptimer. Lees meteen in Blogs wat het verschil is tussen nachtangst en een nachtmerrie.', title_pl = 'Nocne pobudki 🌌', body_pl = 'Budzi się w nocy z płaczem i nie daje się uspokoić? Spójrz na wykres w timerze snu. Od razu zajrzyj do sekcji Blog, by zrozumieć różnicę między lękiem nocnym a koszmarem.', title_pt = 'Despertares noturnos 🌌', body_pt = 'Acorda a meio da noite a chorar e não se acalma? Veja o gráfico do temporizador de sono. Para perceber a diferença entre terror noturno e pesadelo, consulte já o Blogue.', title_sv = 'Nattliga uppvaknanden 🌌', body_sv = 'Vaknar barnet gråtande mitt i natten och lugnar sig inte? Titta på sömntimerns diagram. Gå direkt till avsnittet Bloggar för att förstå skillnaden mellan nattskräck och mardrömmar.', title_vi = 'Thức giấc ban đêm 🌌', body_vi = 'Bé khóc thét thức giấc giữa đêm và không dịu lại? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Để hiểu sự khác nhau giữa hoảng sợ ban đêm và ác mộng, hãy xem ngay mục Blog.', title_zh = '夜间醒来 🌌', body_zh = '半夜哭醒，怎么也安抚不下来？看看睡眠计时器的图表。马上去博客板块看看，了解夜惊和噩梦的区别。' WHERE id = 'e1ad3771-efd0-4fef-8fce-2cfe9cc2174f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'La rutina de casa empieza a agobiarte. Hoy haz algo diferente. Id a una cafetería tranquila cerca de casa: tu peque cambia de ambiente y tú disfrutas de tu café.', body_fr = 'La routine à la maison commence à vous étouffer. Changez aujourd''hui. Allez dans un café calme près de chez vous pour lui faire changer d''air et savourer votre café.', body_hi = 'घर का रूटीन घुटन देने लगा है। आज कुछ अलग कीजिए। पास के किसी शांत कैफ़े में जाइए, उसका माहौल भी बदलिए और अपनी कॉफ़ी का भी मज़ा लीजिए।', body_id = 'Rutinitas di rumah mulai terasa menyesakkan. Hari ini cobalah sesuatu yang berbeda. Pergilah ke kafe yang tenang di dekat rumah, ganti suasananya dan nikmati kopi Anda.', body_ja = '家でのルーティンに息がつまりそう？今日は気分を変えましょう。近くの静かなカフェに行って、お子さんには新しい環境を、あなたは自分のコーヒーを楽しんで。', body_ko = '집에서의 반복되는 일상이 답답해지기 시작했나요? 오늘은 변화를 줘 보세요. 근처 조용한 카페에 가서 아이에게는 새로운 환경을, 엄마에게는 커피 한 잔의 여유를 선물하세요.', body_nl = 'De routine thuis begint je te verstikken. Doe vandaag eens iets anders. Ga naar een rustig cafeetje in de buurt: hij krijgt een andere omgeving en jij geniet van je koffie.', body_pl = 'Domowa rutyna zaczyna cię przytłaczać. Zrób dziś coś innego. Wybierzcie się do spokojnej kawiarni w pobliżu: on zmieni otoczenie, a ty delektuj się kawą.', body_pt = 'A rotina de casa começa a sufocá-la. Hoje faça algo diferente. Vá a um café tranquilo aqui perto: ele muda de ambiente e a mãe saboreia o seu café.', body_sv = 'Rutinen hemma har börjat kväva dig. Gör något annorlunda i dag. Gå till ett lugnt kafé i närheten, ge barnet en ny miljö och njut av ditt eget kaffe.', body_vi = 'Nếp sinh hoạt ở nhà bắt đầu khiến mẹ ngột ngạt. Hôm nay hãy đổi gió. Đến một quán cà phê yên tĩnh gần nhà để bé được thay đổi không gian và mẹ thưởng thức ly cà phê của mình.', body_zh = '家里的日常开始让你透不过气了。今天来点不一样的吧。去附近一家安静的咖啡馆，给宝宝换个环境，你也好好享受一杯咖啡。' WHERE id = '127ac6bb-4f6e-424f-91fb-e2d406c68c2a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Al salir de paseo, no te fíes del tiempo y evita que se enfríe. No decidas solo mirando por la ventana: comprueba antes la velocidad del viento y la sensación térmica real.', body_fr = 'Ne vous laissez pas tromper par le temps et ne le laissez pas prendre froid en promenade. Ne décidez pas en regardant par la fenêtre : vérifiez d''abord la vitesse du vent et la température ressentie dehors.', body_hi = 'सैर पर जाते समय मौसम के धोखे में आकर उसे ठंड मत लगने दीजिए। सिर्फ़ खिड़की से देखकर फ़ैसला मत कीजिए, बाहर की हवा की रफ़्तार और असली तापमान पहले से जाँच लीजिए।', body_id = 'Saat jalan-jalan, jangan tertipu cuaca hingga ia kedinginan. Jangan memutuskan hanya dengan melihat dari jendela, periksa dulu kecepatan angin dan suhu sebenarnya di luar.', body_ja = 'お散歩のとき、見た目の天気にだまされて体を冷やさないように。窓から見て決めずに、外の風の強さと実際の気温を前もって確認しましょう。', body_ko = '산책할 때 날씨에 속아 아이를 춥게 하지 마세요. 창밖만 보고 정하지 말고 바깥 풍속과 실제 체감 온도를 미리 확인하세요.', body_nl = 'Laat je niet misleiden door het weer als je gaat wandelen, zodat hij het niet koud krijgt. Beslis niet door uit het raam te kijken, maar check vooraf de windsnelheid en de gevoelstemperatuur buiten.', body_pl = 'Wychodząc na spacer, nie daj się zwieść pogodzie, żeby go nie przeziębić. Nie decyduj, patrząc przez okno, tylko wcześniej sprawdź prędkość wiatru i temperaturę odczuwalną.', body_pt = 'Quando saírem para passear, não se deixe enganar pelo tempo e evite que ele apanhe frio. Não decida só pela janela: verifique antes a velocidade do vento e a temperatura real lá fora.', body_sv = 'Låt dig inte luras av vädret så att barnet fryser på promenaden. Bestäm inte genom att titta ut genom fönstret, kolla vindhastigheten och den verkliga temperaturen ute i förväg.', body_vi = 'Khi ra ngoài đi dạo, đừng để thời tiết đánh lừa khiến bé bị lạnh. Đừng quyết định chỉ bằng cách nhìn qua cửa sổ, hãy kiểm tra trước tốc độ gió và nhiệt độ cảm nhận thực tế bên ngoài.', body_zh = '出门散步时，别被天气骗了，让宝宝着凉。别只看窗外做决定，提前查一下外面的风速和实际温度。' WHERE id = '0bcb845e-25a8-4c8a-b05c-67b7a3788c4a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubriendo su «yo» 👑', body_es = '«¡Soy yo!», «¡Es mío!»: no deja de decirlo. Es el momento más marcado de la etapa egocéntrica. Respeta su individualidad, es una fase del desarrollo.', title_fr = 'Il découvre son « moi » 👑', body_fr = '« C''est moi ! », « C''est à moi ! » ne quittent plus ses lèvres. C''est le pic de la période égocentrique. Accueillez sa personnalité avec respect, c''est une étape du développement.', title_hi = 'अपने ''मैं'' की खोज 👑', body_hi = '''मैं हूँ!'', ''मेरा है!'' ये शब्द उसकी ज़ुबान से हटते ही नहीं। यह ''मैं ही मैं'' वाले दौर का सबसे चरम समय है। उसकी इस अलग पहचान को सम्मान से स्वीकार कीजिए, यह विकास का एक पड़ाव है।', title_id = 'Menemukan ''Aku''-nya 👑', body_id = 'Kata ''Aku!'' dan ''Punyaku!'' tak pernah lepas dari mulutnya. Ini puncak masa egosentris. Sambut jati dirinya dengan hormat, ini adalah tahap perkembangan.', title_ja = '「自分」を発見中 👑', body_ja = '「ぼくの！」「わたしの！」が口ぐせになっていますか？自分中心の時期のまっただ中です。この個性を尊重してあげて、これも発達の一段階です。', title_ko = '''나''를 발견해요 👑', body_ko = '''나야!'', ''내 거야!''를 입에 달고 사나요? 자기중심성이 가장 두드러지는 시기예요. 이 개성을 존중해 주세요. 자연스러운 발달 단계예요.', title_nl = 'Hij ontdekt zijn ''ik'' 👑', body_nl = '''Ik!'' en ''Van mij!'' zijn niet van zijn lippen te krijgen. Dit is het hoogtepunt van de egocentrische fase. Ga respectvol om met zijn eigenheid, het is een ontwikkelingsfase.', title_pl = 'Odkrywa swoje „ja” 👑', body_pl = '„To ja!”, „To moje!” nie schodzą mu z ust. To szczyt okresu egocentryzmu. Przyjmij jego indywidualność z szacunkiem, to etap rozwoju.', title_pt = 'A descobrir o seu "eu" 👑', body_pt = '"Sou eu!", "É meu!" não lhe saem da boca. É o auge da fase egocêntrica. Respeite esta individualidade: é uma etapa do desenvolvimento.', title_sv = 'Barnet upptäcker sitt jag 👑', body_sv = '”Det är jag!”, ”Den är min!” hörs hela tiden. Det är toppen av den egocentriska perioden. Möt barnets individualitet med respekt, det är ett utvecklingssteg.', title_vi = 'Khám phá "cái tôi" 👑', body_vi = '"Của con!", "Con mà!" lúc nào cũng nói. Đây là đỉnh điểm của giai đoạn vị kỷ. Hãy tôn trọng cá tính này của bé, đó là một giai đoạn phát triển.', title_zh = '发现“自我” 👑', body_zh = '“是我！”“是我的！”总挂在嘴边。这是自我中心阶段最明显的时候。尊重宝宝的个性，这是一个成长阶段。' WHERE id = '1566736d-5f6a-420b-9aaa-9e37909efa16' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta una reserva de energía 🍲', body_es = '¿El cansancio te ha calado hasta los huesos? Prémiate con una ensalada especial que se prepara en 10 minutos, te sacia y te da energía.', title_fr = 'Besoin d''un plein d''énergie 🍲', body_fr = 'La fatigue vous pèse jusqu''aux os ? Récompensez-vous avec une salade spéciale prête en 10 minutes, qui vous rassasiera et vous redonnera du peps.', title_hi = 'ऊर्जा का भंडार चाहिए 🍲', body_hi = 'थकान हड्डियों तक उतर गई है? 10 मिनट में बनने वाला एक खास सलाद बनाइए जो पेट भी भरे और ताज़गी भी दे, और खुद को इनाम दीजिए।', title_id = 'Butuh isi ulang energi 🍲', body_id = 'Lelah sampai ke tulang? Hadiahi diri Anda dengan salad istimewa yang siap dalam 10 menit, mengenyangkan sekaligus menyegarkan.', title_ja = 'エネルギー補給が必要 🍲', body_ja = '疲れが体の芯までしみていますか？10分でできて、おなかも満たされ、元気も出る特別なサラダをつくって、自分にごほうびをあげましょう。', title_ko = '에너지 충전이 필요해요 🍲', body_ko = '피로가 뼛속까지 스몄나요? 10분이면 만드는, 든든하면서 활력을 주는 특별한 샐러드로 나에게 상을 주세요.', title_nl = 'Tijd om bij te tanken 🍲', body_nl = 'Zit de vermoeidheid in je botten? Beloon jezelf met een speciale salade die in 10 minuten klaar is, je verzadigt en je weer fris maakt.', title_pl = 'Potrzebny zastrzyk energii 🍲', body_pl = 'Zmęczenie daje ci się we znaki? Nagródź się wyjątkową sałatką gotową w 10 minut, która zarówno cię nasyci, jak i doda energii.', title_pt = 'Precisa de uma reserva de energia 🍲', body_pt = 'O cansaço já lhe chegou aos ossos? Recompense-se com uma salada especial, pronta em 10 minutos, que a deixa saciada e cheia de energia.', title_sv = 'Energipåfyllning behövs 🍲', body_sv = 'Har tröttheten gått in i märgen? Belöna dig själv med en speciell sallad som är klar på 10 minuter och som både mättar och piggar upp.', title_vi = 'Cần nạp năng lượng 🍲', body_vi = 'Mệt mỏi thấm vào tận xương? Hãy tự thưởng cho mình một món salad đặc biệt làm trong 10 phút, vừa no lâu vừa giúp mẹ tỉnh táo.', title_zh = '需要补充能量 🍲', body_zh = '累到骨子里了？做一份10分钟就能完成、既顶饱又提神的特别沙拉，犒劳一下自己吧。' WHERE id = '2876fc5f-fac3-4af5-b718-9c2f0d9b5314' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cierra la boca en cuanto ve el cepillo de dientes? Busca en Productos recomendados cepillos infantiles musicales o giratorios que faciliten el proceso y convierte la higiene en diversión.', body_fr = 'Il verrouille sa bouche dès qu''il voit la brosse à dents ? Cherchez dans les Produits recommandés des brosses musicales ou rotatives pour enfants et transformez l''hygiène en jeu.', body_hi = 'टूथब्रश देखते ही मुँह बंद कर लेता है? इस काम को आसान बनाने वाले म्यूज़िकल या घूमने वाले बच्चों के ब्रश सुझाए गए प्रोडक्ट में ढूँढिए और सफ़ाई को मज़े में बदलिए।', body_id = 'Begitu melihat sikat gigi, ia langsung mengatupkan mulut? Cari sikat gigi anak bermusik atau berputar di Produk Rekomendasi untuk memudahkan prosesnya dan ubah kebersihan jadi permainan.', body_ja = '歯ブラシを見たとたん、口をぎゅっと閉じますか？歯みがきを楽にする音楽つきや回転する子ども用歯ブラシを「おすすめ商品」で探して、歯みがきを楽しい遊びにしましょう。', body_ko = '칫솔만 보면 입을 꾹 다무나요? 추천 제품에서 음악이 나오거나 회전하는 어린이 칫솔을 찾아 양치를 재미있는 놀이로 바꿔 보세요.', body_nl = 'Klemt hij zijn mond dicht zodra hij een tandenborstel ziet? Zoek in Aanbevolen producten muzikale of draaiende kindertandenborstels die het makkelijker maken en maak van poetsen een spelletje.', body_pl = 'Na widok szczoteczki do zębów zaciska buzię? Poszukaj w Polecanych produktach grających lub obrotowych szczoteczek dla dzieci, które ułatwią ten proces, i zamień higienę w zabawę.', body_pt = 'Fecha a boca mal vê a escova de dentes? Procure nos Produtos Recomendados escovas infantis com música ou rotativas que facilitam o processo e transforme a higiene numa brincadeira.', body_sv = 'Låser barnet munnen så fort hen ser tandborsten? Leta efter barntandborstar med musik eller roterande huvud i Rekommenderade produkter och gör hygienen till en lek.', body_vi = 'Vừa thấy bàn chải là bé ngậm chặt miệng? Hãy tìm bàn chải có nhạc hoặc bàn chải xoay cho trẻ trong Sản phẩm gợi ý để biến việc vệ sinh thành trò vui.', body_zh = '一看到牙刷就紧闭嘴巴？去推荐商品找找能让刷牙更轻松的音乐牙刷或旋转儿童牙刷，把清洁变成乐趣。' WHERE id = '2b82cde7-2302-4ad2-96b7-ca1beedb8f4f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se ha despertado llorando en mitad de la noche sin motivo? ¿Son gases o un terror nocturno? Abrázale con calma y dale paz sin levantar la voz.', body_fr = 'Il s''est réveillé en pleurant en pleine nuit, sans raison apparente ? Des gaz, ou juste une terreur nocturne ? Prenez-le calmement dans vos bras et apaisez-le sans hausser la voix.', body_hi = 'बिना वजह आधी रात को रोते हुए जाग गया? गैस है या बस नाइट टेरर? शांति से गले लगाइए और आवाज़ ऊँची किए बिना उसे सुकून दीजिए।', body_id = 'Ia terbangun tengah malam sambil menangis tanpa sebab? Kembung, atau hanya teror malam? Peluk ia dengan tenang dan beri ketenangan tanpa meninggikan suara.', body_ja = '理由もなく夜中に泣いて目を覚ましましたか？ガス？それとも夜驚症？静かに抱きしめて、声を荒げずに安心させてあげましょう。', body_ko = '이유 없이 한밤중에 울며 깼나요? 가스 때문일까요, 아니면 야경증일까요? 조용히 안아 주고 목소리를 높이지 말고 편안하게 해 주세요.', body_nl = 'Zomaar midden in de nacht huilend wakker? Zijn het krampjes of gewoon nachtangst? Knuffel hem rustig en geef hem rust zonder je stem te verheffen.', body_pl = 'Obudził się w nocy z płaczem bez powodu? To gazy czy lęk nocny? Spokojnie go przytul i nie podnosząc głosu, daj mu spokój.', body_pt = 'Acordou a meio da noite a chorar sem razão? São gases ou apenas terror noturno? Abrace-o com calma e tranquilize-o sem levantar a voz.', body_sv = 'Har barnet vaknat gråtande mitt i natten utan anledning? Är det gaser, eller bara nattskräck? Krama barnet lugnt och ge hen ro utan att höja rösten.', body_vi = 'Bé bỗng khóc thức giấc giữa đêm không rõ lý do? Đầy hơi hay hoảng sợ ban đêm? Hãy nhẹ nhàng ôm bé và vỗ về mà không cao giọng.', body_zh = '半夜无缘无故哭醒？是胀气，还是只是夜惊？平静地抱住宝宝，不提高嗓门，给宝宝安宁。' WHERE id = 'c3b0f127-530e-4b11-9687-7c0bcb24de5f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Responde con gritos a cada «no» que le dices? Desahógate con Anacan AI y aprende tácticas para gestionar con calma estos estallidos emocionales y desviar su atención.', body_fr = 'Chaque « non » de votre part déclenche des cris ? Discutez avec Anacan AI pour apprendre à gérer avec calme ces explosions émotionnelles incontrôlables et des astuces pour détourner son attention.', body_hi = 'आपकी हर ''नहीं'' का जवाब चीख से देता है? इन बेकाबू भावनात्मक विस्फोटों को शांत रहकर संभालने और ध्यान भटकाने की तरकीबें सीखने के लिए Anacan AI से बात कीजिए।', body_id = 'Setiap ''tidak'' dari Anda dibalas dengan teriakan? Mengobrollah dengan Anacan AI untuk belajar menghadapi ledakan emosi yang tak terkendali ini dengan kepala dingin dan taktik mengalihkan perhatian.', body_ja = 'あなたが「ダメ」と言うたびに叫んで返してきますか？この手に負えない感情の爆発に冷静に対応し、気をそらすコツを学ぶために、Anacan AIに相談しましょう。', body_ko = '엄마의 ''안 돼'' 한마디마다 소리를 지르나요? 걷잡을 수 없는 감정 폭발을 침착하게 다루고 관심을 돌리는 요령을 Anacan AI와 이야기하며 배워 보세요.', body_nl = 'Reageert hij op elk ''nee'' met geschreeuw? Praat met Anacan AI en leer hoe je deze onbeheersbare emotionele uitbarstingen kalm opvangt en hoe je zijn aandacht afleidt.', body_pl = 'Na każde twoje „nie” odpowiada krzykiem? Porozmawiaj z Anacan AI, by nauczyć się spokojnie radzić sobie z tymi niekontrolowanymi wybuchami emocji i odwracać jego uwagę.', body_pt = 'Responde a cada "não" seu com gritos? Fale com o Anacan AI para aprender a gerir com calma estas explosões emocionais incontroláveis e a usar táticas de distração.', body_sv = 'Svarar barnet med skrik på varje nej? Prata med Anacan AI för att lära dig hantera de här okontrollerade känsloutbrotten med lugn och avledningstaktiker.', body_vi = 'Mỗi lần mẹ nói "không" là bé đáp lại bằng tiếng hét? Hãy trò chuyện với Anacan AI để học cách bình tĩnh xử lý những cơn bùng nổ cảm xúc khó kiểm soát này và các mẹo đánh lạc hướng.', body_zh = '你每说一个“不”，宝宝都用尖叫回应？和Anacan AI聊一聊，学学怎样冷静应对这些失控的情绪爆发，以及转移注意力的技巧。' WHERE id = 'd3fd3ce0-fc06-4bdf-8472-041feda78c86' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del cuento con papá 📚', body_es = '¡Esta noche deja el ritual de dormir a tu pareja! Con el modo Pareja de la app, que lea él el cuento mientras tú te tomas tranquilamente tu té.', title_fr = 'L''heure du conte avec papa 📚', body_fr = 'Ce soir, confiez le rituel du coucher à votre partenaire ! Avec le mode Partenaire de l''application, il lit l''histoire pendant que vous buvez tranquillement votre thé.', title_hi = 'पापा की कहानी का समय 📚', body_hi = 'आज शाम सोने की रस्म अपने पार्टनर को सौंप दीजिए! ऐप में पार्टनर मोड से कहानी वे पढ़ें और आप आराम से अपनी चाय पीजिए।', title_id = 'Waktu dongeng Ayah 📚', body_id = 'Malam ini serahkan ritual menjelang tidur kepada pasangan! Lewat mode Pasangan di aplikasi, biar ia yang membacakan dongeng, sementara Anda menikmati teh dengan tenang.', title_ja = 'パパのお話タイム 📚', body_ja = '今夜の寝かしつけはパートナーにお願いしましょう！アプリの「パートナーモード」を使ってお話はパパに読んでもらい、あなたはゆっくりお茶を飲んで。', title_ko = '아빠의 동화 시간 📚', body_ko = '오늘 저녁 잠자리 의식은 배우자에게 맡기세요! 앱의 파트너 모드로 동화는 아빠가 읽어 주고, 엄마는 조용히 차를 마시세요.', title_nl = 'Voorleesuurtje met papa 📚', body_nl = 'Laat het slaapritueel vanavond aan je partner over! Met Partnermodus in de app leest hij het sprookje voor, terwijl jij rustig je thee drinkt.', title_pl = 'Bajka na dobranoc z tatą 📚', body_pl = 'Dziś wieczorem powierz rytuał usypiania partnerowi! Dzięki trybowi Partnera w aplikacji niech to on przeczyta bajkę, a ty spokojnie wypij herbatę.', title_pt = 'A hora do conto com o pai 📚', body_pt = 'Esta noite, entregue o ritual de deitar ao seu companheiro! Com o Modo Parceiro da app, ele lê a história e a mãe bebe o seu chá com calma.', title_sv = 'Pappas sagostund 📚', body_sv = 'Lämna över kvällens nattningsritual till din partner! Låt hen läsa sagan med Partnerläget i appen medan du dricker ditt te i lugn och ro.', title_vi = 'Giờ kể chuyện của bố 📚', body_vi = 'Tối nay hãy giao nghi thức đi ngủ cho chồng! Dùng Chế độ đối tác trong ứng dụng để bố đọc truyện, còn mẹ thong thả uống trà.', title_zh = '爸爸的故事时间 📚', body_zh = '今晚把哄睡仪式交给伴侣吧！用应用里的伴侣模式，让他来读故事，你安安静静地喝杯茶。' WHERE id = 'de972116-bddf-48f9-bc08-9f55438a9ed7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te ha asustado algo nuevo que hace tu peque? No busques artículos que dan miedo en internet. Aprovecha los consejos de las madres con experiencia de la Comunidad Anacan.', body_fr = 'Un nouveau geste de votre enfant vous a fait peur ? Ne cherchez pas d''articles effrayants sur Internet. Profitez des conseils des mamans expérimentées de la Communauté Anacan.', body_hi = 'बच्चे की किसी नई हरकत ने आपको डरा दिया? इंटरनेट पर डरावने लेख मत ढूँढिए। Anacan कम्युनिटी में अनुभवी माँओं की सलाह का फ़ायदा उठाइए।', body_id = 'Gerakan baru anak membuat Anda takut? Jangan mencari artikel menyeramkan di internet. Manfaatkan saran ibu-ibu berpengalaman di Komunitas Anacan.', body_ja = 'お子さんの新しい動きにドキッとしましたか？ネットでこわい記事を探さないで。Anacanコミュニティの経験豊富なママたちのアドバイスを活用しましょう。', body_ko = '아이의 새로운 행동에 놀랐나요? 인터넷에서 무서운 글을 찾지 마세요. Anacan 커뮤니티의 경험 많은 엄마들의 조언을 활용하세요.', body_nl = 'Schrok je van een nieuwe beweging van je kindje? Zoek niet naar enge artikelen op internet. Haal advies bij ervaren moeders in de Anacan Community.', body_pl = 'Nowe zachowanie dziecka cię przestraszyło? Nie szukaj w internecie przerażających artykułów. Skorzystaj z rad doświadczonych mam w Społeczności Anacan.', body_pt = 'Um novo comportamento do seu filho assustou-a? Não procure artigos assustadores na internet. Aproveite os conselhos das mães experientes da Comunidade Anacan.', body_sv = 'Skrämde barnets nya beteende dig? Sök inte efter skrämmande artiklar på nätet. Ta del av råden från erfarna mammor i Anacan Community.', body_vi = 'Một cử động mới của bé khiến mẹ lo sợ? Đừng tìm đọc những bài báo đáng sợ trên mạng. Hãy tham khảo lời khuyên của các mẹ giàu kinh nghiệm trong Cộng đồng Anacan.', body_zh = '宝宝的新举动吓到你了？别在网上搜那些吓人的文章。听听Anacan社区里有经验的妈妈们的建议吧。' WHERE id = 'fd7112b4-d166-4f5f-ab2b-5f43c5c75632' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Está pálido o sin apetito? Comprueba el hierro de hoy en el Seguimiento de tomas y, junto con la carne, dale siempre ensalada con mucho limón para mejorar la absorción.', body_fr = 'Il a le teint pâle ou peu d''appétit ? Vérifiez ses apports en fer du jour dans le Suivi des repas et servez toujours une salade bien citronnée avec la viande pour mieux l''absorber.', body_hi = 'चेहरा पीला है या भूख नहीं लगती? फ़ीडिंग ट्रैकर में आज का आयरन देखिए और मांस के साथ नींबू वाला सलाद ज़रूर दीजिए ताकि आयरन बेहतर तरीके से अवशोषित हो।', body_id = 'Ia tampak pucat atau tidak berselera makan? Periksa asupan zat besi hari ini di Pemantau Nutrisi dan selalu sajikan daging bersama salad dengan banyak perasan lemon untuk meningkatkan penyerapan.', body_ja = '顔色が悪かったり、食欲がなかったりしますか？「栄養管理ツール」で今日の鉄分摂取を確認し、お肉と一緒にレモンをたっぷりかけたサラダを出して吸収を高めましょう。', body_ko = '얼굴이 창백하거나 입맛이 없나요? 수유 기록 도구로 오늘의 철분 섭취를 확인하고, 고기와 함께 레몬을 듬뿍 뿌린 샐러드를 꼭 곁들여 흡수를 높여 주세요.', body_nl = 'Ziet hij bleek of heeft hij weinig trek? Bekijk in de Voedingstracker het ijzer van vandaag en geef bij vlees altijd een salade met veel citroen om de opname te verbeteren.', body_pl = 'Jest blady albo nie ma apetytu? Sprawdź dzisiejsze spożycie żelaza w narzędziu do śledzenia karmienia i do mięsa koniecznie podawaj sałatkę z dużą ilością cytryny, by poprawić wchłanianie.', body_pt = 'Está pálido ou sem apetite? Verifique a ingestão de ferro de hoje no Registo de Alimentação e, junto com a carne, sirva sempre uma salada com bastante limão para melhorar a absorção.', body_sv = 'Är barnet blekt eller utan aptit? Kolla dagens järnintag i Matningskoll och servera alltid en sallad med mycket citron till köttet för att öka upptaget.', body_vi = 'Bé xanh xao hoặc biếng ăn? Hãy kiểm tra lượng sắt hôm nay trong Theo dõi cữ bú và để tăng hấp thu, nhất định cho bé ăn thịt kèm salad có nhiều nước cốt chanh.', body_zh = '脸色苍白或没胃口？在喂养记录工具里查看今天的铁摄入，搭配肉类时一定要配上多挤柠檬汁的沙拉，提高吸收。' WHERE id = '0b033378-5688-4baf-b5a5-b23c33fde967' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Solo comida seca? 🍞', body_es = '¿Rechaza los purés y las comidas jugosas y solo quiere pan y galletas? Es selectividad por texturas. Analiza su menú con el Seguimiento de tomas y encuentra alternativas sanas en Recetas para bebé.', title_fr = 'Seulement des aliments secs ? 🍞', body_fr = 'Il refuse purées et plats en sauce et ne veut que du pain et des biscuits ? C''est une sélectivité de texture. Analysez son menu avec le Suivi des repas et trouvez des alternatives saines dans les Recettes pour bébés.', title_hi = 'सिर्फ़ सूखी चीज़ें? 🍞', body_hi = 'प्यूरी और रसीले खाने से मना करके सिर्फ़ ब्रेड और बिस्किट माँगता है? यह बनावट को लेकर चुनाव है। फ़ीडिंग ट्रैकर से मेन्यू का विश्लेषण कीजिए और बच्चों की रेसिपी में सेहतमंद विकल्प ढूँढिए।', title_id = 'Hanya makanan kering? 🍞', body_id = 'Ia menolak puree dan makanan berkuah, hanya mau roti dan biskuit? Ini pilih-pilih tekstur. Analisis menunya dengan Pemantau Nutrisi dan temukan alternatif sehat di Resep Bayi.', title_ja = 'かわいたものばかり？🍞', body_ja = 'ピューレや汁気のある料理をいやがって、パンやビスケットばかり欲しがりますか？これは食感の好き嫌いです。「栄養管理ツール」でメニューを分析して、「離乳食を始める赤ちゃんのレシピ」でヘルシーな代わりのメニューを見つけましょう。', title_ko = '마른 음식만? 🍞', body_ko = '퓌레나 촉촉한 음식은 거부하고 빵과 과자만 찾나요? 식감 편식이에요. 수유 기록 도구로 식단을 분석하고 아기 레시피에서 건강한 대안을 찾아보세요.', title_nl = 'Alleen droog eten? 🍞', body_nl = 'Weigert hij puree en zacht eten en wil hij alleen brood en koekjes? Dat is kieskeurigheid in structuur. Analyseer zijn menu met de Voedingstracker en vind gezonde alternatieven in Babyrecepten.', title_pl = 'Tylko suche jedzenie? 🍞', body_pl = 'Odmawia przecierów i płynnych dań, chce tylko chleba i ciastek? To wybiórczość co do konsystencji. Przeanalizuj menu w narzędziu do śledzenia karmienia i znajdź zdrowe alternatywy w Przepisach dla niemowląt.', title_pt = 'Só comida seca? 🍞', body_pt = 'Recusa purés e comida com molho e só quer pão e bolachas? É seletividade de textura. Analise a ementa com o Registo de Alimentação e encontre alternativas saudáveis nas Receitas para bebé.', title_sv = 'Bara torr mat? 🍞', body_sv = 'Vägrar barnet puré och blöt mat och vill bara ha bröd och kex? Det är kräsenhet med konsistensen. Analysera menyn med Matningskoll och hitta hälsosamma alternativ i Babyrecept.', title_vi = 'Chỉ ăn đồ khô? 🍞', body_vi = 'Bé từ chối đồ nghiền và món có nước, chỉ đòi bánh mì, bánh quy? Đây là kén chọn kết cấu thức ăn. Hãy phân tích thực đơn bằng Theo dõi cữ bú và tìm lựa chọn lành mạnh trong Công thức cho bé.', title_zh = '只吃干的东西？🍞', body_zh = '不吃泥糊和汤水类的饭，只要面包和饼干？这是对口感的挑剔。用喂养记录工具分析一下菜单，在宝宝食谱里找健康的替代选择。' WHERE id = '69b9bded-4194-4499-ad7b-42407cdd5970' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escucha a tu cuerpo 🩸', body_es = '¿Antojos repentinos de dulce e irritabilidad? Mira el calendario en el Calendario menstrual. Si te toca la regla, prepara en Recetas saludables para mujeres un tentempié de dátiles y nueces rico en magnesio.', title_fr = 'Écoutez votre corps 🩸', body_fr = 'Envies soudaines de sucré et irritabilité ? Regardez le calendrier dans le Suivi des règles. Si ce sont vos règles, préparez une collation dattes-noix riche en magnésium avec les Recettes saines pour femmes.', title_hi = 'अपने शरीर की सुनिए 🩸', body_hi = 'अचानक मीठे की तलब और चिड़चिड़ापन? पीरियड ट्रैकर में कैलेंडर देखिए। अगर पीरियड चल रहा है, तो महिलाओं के लिए सेहतमंद रेसिपी से मैग्नीशियम से भरपूर खजूर-अखरोट वाला स्नैक बनाइए।', title_id = 'Dengarkan tubuh Anda 🩸', body_id = 'Tiba-tiba ingin makan manis dan mudah kesal? Lihat kalender di Pelacak Menstruasi. Jika sedang haid, buat camilan kurma dan kenari kaya magnesium dari Resep Sehat untuk wanita.', title_ja = '体の声を聞いて 🩸', body_ja = '急に甘いものが欲しくなったり、イライラしたりしますか？「生理トラッカー」のカレンダーを見てみましょう。生理中なら、「女性のためのヘルシーレシピ」からマグネシウムたっぷりのデーツとくるみのおやつをつくって。', title_ko = '몸의 소리를 들어 보세요 🩸', body_ko = '갑자기 단 게 당기고 예민해졌나요? 생리 주기 기록의 달력을 확인하세요. 생리 기간이라면 여성을 위한 건강한 레시피에서 마그네슘이 풍부한 대추야자 호두 간식을 만들어 보세요.', title_nl = 'Luister naar je lichaam 🩸', body_nl = 'Plotselinge zoetbuien en prikkelbaarheid? Kijk in de kalender van de Cyclustracker. Ben je ongesteld, maak dan uit Gezonde recepten voor vrouwen een magnesiumrijk tussendoortje met dadels en walnoten.', title_pl = 'Wsłuchaj się w swoje ciało 🩸', body_pl = 'Nagła ochota na słodycze i rozdrażnienie? Zajrzyj do kalendarza w Kalendarzu miesiączkowym. Jeśli to twój okres, przygotuj ze Zdrowych przepisów dla kobiet przekąskę z daktylami i orzechami bogatą w magnez.', title_pt = 'Ouça o seu corpo 🩸', body_pt = 'Desejos repentinos de doces e irritabilidade? Veja o calendário no Registo do Período. Se estiver nesses dias, prepare um snack de tâmaras e nozes rico em magnésio das Receitas Saudáveis para Mulheres.', title_sv = 'Lyssna på din kropp 🩸', body_sv = 'Plötsligt sötsug och irritation? Titta i kalendern i Mensspåraren. Om det är din period, gör ett magnesiumrikt mellanmål med dadlar och valnötter från Hälsosamma recept för kvinnor.', title_vi = 'Lắng nghe cơ thể 🩸', body_vi = 'Bỗng thèm đồ ngọt và dễ cáu? Hãy xem lịch trong Theo dõi kỳ kinh. Nếu đang đến kỳ, hãy làm món ăn vặt chà là và óc chó giàu magie từ Công thức lành mạnh cho phụ nữ.', title_zh = '倾听你的身体 🩸', body_zh = '突然特别想吃甜食，还心烦气躁？看看经期记录里的日历。如果是经期，就从女性健康食谱里做一份富含镁的椰枣核桃小零食。' WHERE id = 'a97ba33c-1ca8-42a6-b9a0-1eac5f5ba6a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Detective de la naturaleza 🔍', body_es = '¿En casa lo desordena todo? ¡Coge una lupa y salid fuera! Busca en Lugares para mamás un parque verde, descubrid juntos bichos y hojas y canaliza su energía hacia la naturaleza.', title_fr = 'Détective de la nature 🔍', body_fr = 'Il met la maison sens dessus dessous ? Prenez une loupe et sortez ! Trouvez un parc verdoyant dans les Lieux adaptés aux mamans et canalisez son énergie en explorant ensemble insectes et feuilles.', title_hi = 'प्रकृति का जासूस 🔍', body_hi = 'घर में सब कुछ बिखेर देता है? मैग्निफ़ाइंग ग्लास लीजिए और बाहर चलिए! माँ के लिए अनुकूल जगहें में हरा-भरा पार्क ढूँढिए, साथ मिलकर कीड़े और पत्ते खोजिए और उसकी ऊर्जा प्रकृति की ओर मोड़िए।', title_id = 'Detektif alam 🔍', body_id = 'Ia mengacak-acak segalanya di rumah? Ambil kaca pembesar dan keluarlah! Temukan taman hijau di Tempat Ramah Ibu dan salurkan energinya ke alam dengan menjelajahi serangga dan daun bersama.', title_ja = '自然の探偵 🔍', body_ja = '家の中をめちゃくちゃにしていますか？虫めがねを持って外へ出かけましょう！「ママにやさしいスポット」で緑の多い公園を見つけて、虫や葉っぱを一緒に探検し、エネルギーを自然に向けて。', title_ko = '자연 탐정 🔍', body_ko = '집 안을 온통 어지르나요? 돋보기를 챙겨 밖으로 나가세요! 엄마 친화 장소에서 푸른 공원을 찾아 벌레와 나뭇잎을 함께 탐험하며 에너지를 자연으로 돌려 보세요.', title_nl = 'Natuurdetective 🔍', body_nl = 'Breekt hij thuis alles af? Pak een vergrootglas en ga naar buiten! Zoek in Mamavriendelijke plekken een groen park, ontdek samen beestjes en bladeren en richt zijn energie op de natuur.', title_pl = 'Detektyw przyrody 🔍', body_pl = 'W domu wszystko rozrzuca? Weź lupę i wyjdźcie na zewnątrz! Znajdź w Miejscach przyjaznych mamom zielony park i skieruj jego energię na przyrodę, odkrywając razem robaczki i liście.', title_pt = 'Detetive da natureza 🔍', body_pt = 'Em casa desarruma tudo? Pegue numa lupa e saiam! Encontre nos Locais Amigos das Mães um parque verde e canalize a energia dele para a natureza, a descobrir insetos e folhas juntos.', title_sv = 'Naturdetektiv 🔍', body_sv = 'River barnet ner allt hemma? Ta ett förstoringsglas och gå ut! Hitta en grön park i Mammavänliga platser, upptäck insekter och löv tillsammans och rikta energin mot naturen.', title_vi = 'Thám tử thiên nhiên 🔍', body_vi = 'Bé phá tung mọi thứ trong nhà? Cầm theo kính lúp và ra ngoài thôi! Tìm một công viên xanh trong Địa điểm thân thiện với mẹ và cùng bé khám phá côn trùng, lá cây để giải tỏa năng lượng giữa thiên nhiên.', title_zh = '大自然小侦探 🔍', body_zh = '在家把什么都弄乱？拿上放大镜出门去！在妈妈友好场所里找一个绿树成荫的公园，一起探索虫子和树叶，把精力引向大自然。' WHERE id = '16180139-d7b3-4c7d-9723-1b1d28274883' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se complica la rutina de la noche? 🛀', body_es = 'Durante el baño templado, pon música relajante de fondo. La armonía del agua y la melodía ablanda hasta al niño más tozudo.', title_fr = 'La routine du soir devient difficile ?🛀', body_fr = 'Pendant le bain tiède, mettez une musique apaisante en fond. L''harmonie de l''eau et de la mélodie adoucit même l''enfant le plus têtu.', title_hi = 'शाम का रूटीन मुश्किल हो गया? 🛀', body_hi = 'गुनगुने पानी से नहलाते समय पीछे शांत संगीत चलाइए। पानी और धुन का तालमेल सबसे ज़िद्दी बच्चे को भी नरम कर देता है।', title_id = 'Rutinitas malam makin sulit?🛀', body_id = 'Saat mandi air hangat, putar musik yang menenangkan di latar belakang. Paduan air dan melodi bisa melunakkan anak yang paling keras kepala sekalipun.', title_ja = '夜のルーティンが大変？🛀', body_ja = 'ぬるめのお風呂に入るとき、後ろで落ち着く音楽を流しましょう。お湯とメロディーのハーモニーは、どんなにがんこな子の心もやわらげます。', title_ko = '저녁 루틴이 힘들어졌나요?🛀', body_ko = '따뜻한 목욕을 할 때 잔잔한 음악을 틀어 주세요. 물과 멜로디의 조화는 가장 고집스러운 아이도 부드럽게 만들어요.', title_nl = 'Wordt de avondroutine lastig?🛀', body_nl = 'Zet rustgevende muziek op de achtergrond aan tijdens het lauwe bad. De harmonie van water en melodie maakt zelfs het koppigste kind zachter.', title_pl = 'Wieczorna rutyna stała się trudna?🛀', body_pl = 'Podczas ciepłej kąpieli włącz w tle uspokajającą muzykę. Harmonia wody i melodii zmiękcza nawet najbardziej upartego malucha.', title_pt = 'A rotina da noite está difícil?🛀', body_pt = 'Durante o banho morno, ponha música calmante em fundo. A harmonia entre a água e a melodia acalma até a criança mais teimosa.', title_sv = 'Har kvällsrutinen blivit svårare?🛀', body_sv = 'Sätt på lugnande musik i bakgrunden under det ljumma badet. Harmonin mellan vatten och melodi mjukar upp även det envisaste barnet.', title_vi = 'Nếp sinh hoạt buổi tối khó khăn hơn?🛀', body_vi = 'Khi bé tắm nước ấm, hãy bật một bản nhạc êm dịu phía sau. Sự hòa quyện giữa nước và giai điệu có thể làm dịu cả đứa trẻ bướng bỉnh nhất.', title_zh = '晚间流程变难了？🛀', body_zh = '洗温水澡时，在背景里放一些舒缓的音乐。水和旋律的和谐，连最倔的孩子都会软下来。' WHERE id = '1e0561d7-2e98-4811-8aaf-2ee6c5e76ef8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca del silencio absoluto 🛋️', body_es = '¡En cuanto se duerma, no corras a vaciar el lavavajillas! Túmbate en el sofá, cierra los ojos y derrítete 15 minutos en ese silencio absoluto y tan poco habitual de la casa.', title_fr = 'En quête de silence absolu 🛋️', body_fr = 'Dès qu''il s''endort, ne courez pas vider le lave-vaisselle ! Allongez-vous sur le canapé, fermez les yeux et fondez pendant 15 minutes dans ce silence absolu si rare à la maison.', title_hi = 'पूरी खामोशी की तलाश 🛋️', body_hi = 'बच्चे के सोते ही डिशवॉशर खाली करने मत भागिए! सोफ़े पर लेटिए, आँखें बंद कीजिए और 15 मिनट तक घर की उस दुर्लभ, पूरी खामोशी में खो जाइए।', title_id = 'Mencari hening total 🛋️', body_id = 'Begitu anak tidur, jangan buru-buru mengosongkan mesin cuci piring! Berbaringlah di sofa, pejamkan mata, dan larutlah selama 15 menit dalam keheningan langka di rumah.', title_ja = '完全な静けさを求めて 🛋️', body_ja = 'お子さんが眠ったとたん、食洗機を片づけに走らないで！ソファに横になり、目を閉じて、15分間、家に訪れためったにない完全な静けさに身をゆだねましょう。', title_ko = '완벽한 고요를 찾아서 🛋️', body_ko = '아이가 잠들자마자 식기세척기를 비우러 가지 마세요! 소파에 누워 눈을 감고, 집 안의 드물고 완벽한 고요 속에서 15분 동안 녹아내리듯 쉬세요.', title_nl = 'Op zoek naar totale stilte 🛋️', body_nl = 'Ren niet naar de vaatwasser zodra hij slaapt! Ga op de bank liggen, sluit je ogen en smelt 15 minuten weg in die zeldzame, totale stilte in huis.', title_pl = 'W poszukiwaniu absolutnej ciszy 🛋️', body_pl = 'Gdy dziecko zaśnie, nie biegnij rozładowywać zmywarki! Połóż się na kanapie, zamknij oczy i przez 15 minut rozpłyń się w tej rzadkiej, absolutnej ciszy w domu.', title_pt = 'À procura do silêncio absoluto 🛋️', body_pt = 'Mal a criança adormece, não corra para esvaziar a máquina da loiça! Deite-se no sofá, feche os olhos e deixe-se derreter durante 15 minutos naquele raro e absoluto silêncio da casa.', title_sv = 'På jakt efter total tystnad 🛋️', body_sv = 'Rusa inte till diskmaskinen så fort barnet somnat! Lägg dig på soffan, blunda och smält in i den sällsynta, totala tystnaden i hemmet i 15 minuter.', title_vi = 'Đi tìm sự tĩnh lặng tuyệt đối 🛋️', body_vi = 'Bé vừa ngủ, đừng vội chạy đi dỡ máy rửa bát! Hãy nằm xuống sofa, nhắm mắt và tan chảy trong 15 phút tĩnh lặng tuyệt đối hiếm hoi của căn nhà.', title_zh = '寻找绝对的安静 🛋️', body_zh = '孩子一睡着，别急着去收拾洗碗机！在沙发上躺下，闭上眼睛，花15分钟沉浸在家里那难得的、绝对的安静中。' WHERE id = '15d607dd-13ee-4b91-b920-e762edd4acd3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te escucha con atención e intenta construir frases parecidas? ¡Está hablando contigo! Respóndele con muchas sonrisas y anima esta comunicación.', body_fr = 'Il vous écoute attentivement et essaie de faire des phrases semblables ? Il vous parle ! Répondez-lui avec plein de sourires et encouragez cette communication.', body_hi = 'आपको ध्यान से सुनकर मिलते-जुलते वाक्य बनाने की कोशिश करता है? वह आपसे बात कर रहा है! खूब मुस्कुराकर जवाब दीजिए और इस बातचीत को बढ़ावा दीजिए।', body_id = 'Ia mendengarkan Anda dengan saksama dan mencoba membuat kalimat serupa? Ia sedang berbicara dengan Anda! Jawablah dengan banyak senyuman dan dorong komunikasi ini.', body_ja = 'あなたの話をじっと聞いて、似たような文を作ろうとしていますか？あなたとおしゃべりしているのです！たくさん笑顔で答えて、このコミュニケーションを応援しましょう。', body_ko = '엄마 말을 귀 기울여 듣고 비슷한 문장을 만들려고 하나요? 엄마와 대화하고 있는 거예요! 활짝 웃으며 대답해 주고 이 소통을 응원해 주세요.', body_nl = 'Luistert hij aandachtig naar je en probeert hij vergelijkbare zinnen te maken? Hij praat met je! Antwoord met veel glimlachjes en moedig dit contact aan.', body_pl = 'Uważnie cię słucha i próbuje budować podobne zdania? On z tobą rozmawia! Odpowiadaj mu z szerokim uśmiechem i zachęcaj do tej komunikacji.', body_pt = 'Ouve-a com atenção e tenta construir frases parecidas? Está a conversar consigo! Responda com muitos sorrisos e incentive esta comunicação.', body_sv = 'Lyssnar barnet noga på dig och försöker säga liknande meningar? Hen pratar med dig! Svara med många leenden och uppmuntra den här kommunikationen.', body_vi = 'Bé chăm chú lắng nghe và cố nói những câu tương tự? Bé đang trò chuyện với mẹ đấy! Hãy đáp lại bằng thật nhiều nụ cười và khuyến khích sự giao tiếp này.', body_zh = '认真听你说话，还试着说出相似的句子？宝宝在和你对话！多多微笑着回应，鼓励这种交流吧。' WHERE id = '986722e4-1562-4f18-a164-dd6f65efe855' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ya disfruta andando descalzo y descubriendo texturas con los pies? Descubrir los nervios de la planta del pie es muy importante para su equilibrio.', body_fr = 'Il adore marcher pieds nus et découvrir différentes textures avec ses pieds ? Découvrir les nerfs de la plante des pieds est très important pour son équilibre.', body_hi = 'उसे अब नंगे पैर चलने और पैरों से अलग-अलग बनावट महसूस करने में मज़ा आता है? तलवों की नसों की यह खोज उसके संतुलन के लिए बहुत ज़रूरी है।', body_id = 'Ia senang berjalan tanpa alas kaki dan menjelajahi berbagai tekstur dengan kakinya? Mengenal saraf di telapak kaki sangat penting untuk keseimbangannya.', body_ja = 'はだしで歩いたり、足でいろいろな感触を探検したりするのを楽しんでいますか？足の裏の神経を発見することは、バランス感覚にとってとても大切です。', body_ko = '이제 맨발로 걸으며 발로 여러 촉감을 탐색하는 걸 즐기나요? 발바닥 신경을 발견하는 건 균형 감각에 아주 중요해요.', body_nl = 'Loopt hij graag op blote voeten en ontdekt hij met zijn voeten verschillende structuren? Het ontdekken van de zenuwen onder zijn voetzolen is heel belangrijk voor zijn evenwicht.', body_pl = 'Z przyjemnością chodzi boso i odkrywa stopami różne faktury? Odkrywanie nerwów na podeszwach stóp jest bardzo ważne dla jego równowagi.', body_pt = 'Já gosta de andar descalço e de explorar texturas diferentes com os pés? Descobrir os nervos da planta do pé é muito importante para o equilíbrio dele.', body_sv = 'Tycker barnet redan om att gå barfota och upptäcka olika ytor med fötterna? Att upptäcka nerverna under fötterna är väldigt viktigt för balansen.', body_vi = 'Bé thích đi chân trần và dùng chân khám phá các bề mặt khác nhau? Việc khám phá các dây thần kinh dưới lòng bàn chân rất quan trọng cho khả năng giữ thăng bằng.', body_zh = '已经喜欢光着脚走路，用脚探索不同的触感？探索脚底的神经对宝宝的平衡非常重要。' WHERE id = '48fd17bd-f8c5-4be3-9778-ec599f5cc5b0' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta noche prueba algo totalmente distinto: la historia de la pequeña nube que explora el cielo. Adapta tu tono de voz al ritmo del cuento.', body_fr = 'Ce soir, essayez quelque chose de complètement différent : l''histoire du petit nuage qui explore le ciel. Adaptez le ton de votre voix au rythme du conte.', body_hi = 'आज शाम कुछ बिल्कुल अलग आज़माइए: आसमान की खोज करने वाले नन्हे बादल की कहानी। अपनी आवाज़ का लहजा कहानी की लय के साथ मिलाइए।', body_id = 'Malam ini coba sesuatu yang sama sekali berbeda: kisah awan kecil yang menjelajahi langit. Sesuaikan nada suara Anda dengan irama dongeng.', body_ja = '今夜はまったく違うお話を試してみましょう：空を探検する小さな雲のお話。声のトーンをお話のリズムに合わせて。', body_ko = '오늘 밤엔 완전히 색다른 이야기를 해 보세요: 하늘을 탐험하는 꼬마 구름 이야기. 목소리 톤을 이야기의 리듬에 맞춰 주세요.', body_nl = 'Probeer vanavond eens iets heel anders: het verhaal van het kleine wolkje dat de lucht ontdekt. Pas de toon van je stem aan op het ritme van het verhaal.', body_pl = 'Dziś wieczorem spróbuj czegoś zupełnie innego: historii o małej chmurce, która odkrywa niebo. Dopasuj ton głosu do rytmu bajki.', body_pt = 'Esta noite, experimente algo totalmente diferente: a história da pequena nuvem que explora o céu. Ajuste o tom de voz ao ritmo do conto.', body_sv = 'Prova något helt annat i kväll: berättelsen om det lilla molnet som upptäcker himlen. Anpassa din röst efter sagans rytm.', body_vi = 'Tối nay hãy thử điều gì đó thật khác: câu chuyện về đám mây nhỏ đi khám phá bầu trời. Hãy điều chỉnh giọng kể theo nhịp điệu của câu chuyện.', body_zh = '今晚试试完全不一样的故事吧：《探索天空的小云朵》。让你的语调跟上故事的节奏。' WHERE id = 'e607fc1e-dfa8-4735-b945-f39209fa5d8a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Silencio en la rutina de la noche 🌬️', body_es = '¿Ha corrido todo el día y ahora no sabe frenar? Pon el temporizador de sueño y las olas del océano de Ruido blanco, convierte la habitación en una tranquila cueva de sueño y pon su energía a cero.', title_fr = 'Le calme de la routine du soir 🌬️', body_fr = 'Il a couru toute la journée et n''arrive plus à freiner ? Lancez le Minuteur de sommeil, mettez les vagues de l''océan des Bruits blancs et faites de la chambre une grotte de sommeil apaisante pour remettre son énergie à zéro.', title_hi = 'शाम के रूटीन में खामोशी 🌬️', body_hi = 'दिनभर दौड़ता रहा और अब रुक ही नहीं पा रहा? स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में समुद्र की लहरें चलाकर कमरे को नींद की शांत गुफ़ा बनाइए और उसकी ऊर्जा को शांत कीजिए।', title_id = 'Hening di rutinitas malam 🌬️', body_id = 'Seharian berlari dan sekarang tidak bisa mengerem? Nyalakan Timer Tidur, putar suara ombak laut dari Suara Putih, ubah kamar menjadi gua tidur yang tenang, dan nolkan energinya.', title_ja = '夜のルーティンに静けさを 🌬️', body_ja = '一日じゅう走り回って、ブレーキがきかない？睡眠タイマーをオンにして、「ホワイトノイズ」の波の音で部屋を静かな眠りのほら穴に変え、エネルギーをリセットしましょう。', title_ko = '저녁 루틴 속 고요 🌬️', body_ko = '하루 종일 뛰어다니더니 이제 멈추질 못하나요? 수면 타이머를 켜고 백색소음에서 파도 소리를 틀어 방을 고요한 수면 동굴로 만들고 에너지를 차분히 가라앉혀 주세요.', title_nl = 'Stilte in de avondroutine 🌬️', body_nl = 'Heeft hij de hele dag gerend en kan hij nu niet meer remmen? Zet de Slaaptimer aan, kies oceaangolven in Witte ruis en maak van de kamer een rustige slaapgrot om zijn energie te resetten.', title_pl = 'Cisza w wieczornej rutynie 🌬️', body_pl = 'Biegał cały dzień i teraz nie może wyhamować? Włącz timer snu, puść z Białego szumu fale oceanu, zamień pokój w spokojną jaskinię snu i wyzeruj jego energię.', title_pt = 'Silêncio na rotina da noite 🌬️', body_pt = 'Correu o dia todo e agora não consegue travar? Ligue o temporizador de sono, ponha as ondas do mar do Ruído Branco, transforme o quarto numa gruta de sono tranquila e reponha a energia a zero.', title_sv = 'Tystnad i kvällsrutinen 🌬️', body_sv = 'Har barnet sprungit hela dagen och kan inte bromsa nu? Starta sömntimern, sätt på havsvågor i Vitt brus, gör rummet till en lugn sömngrotta och nollställ energin.', title_vi = 'Sự yên tĩnh trong nếp sinh hoạt buổi tối 🌬️', body_vi = 'Bé chạy cả ngày và giờ không "phanh" lại được? Hãy bật Bộ hẹn giờ ngủ, mở tiếng sóng biển trong Tiếng ồn trắng để biến căn phòng thành "hang ngủ" yên tĩnh và đưa năng lượng về 0.', title_zh = '晚间流程里的安静 🌬️', body_zh = '跑了一整天，现在停不下来了？打开睡眠计时器，再打开白噪音里的海浪声，把房间变成安静的睡眠小洞穴，让精力归零。' WHERE id = '4434b892-1b9a-48ea-bd05-6295b7705bc1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El día de cocina de papá 👨‍🍳', body_es = 'Activa el modo Pareja. ¡Hoy preparar la comida y darle de comer es cosa de papá! Tú dedica este tiempo a ti misma leyendo o descansando.', title_fr = 'Papa aux fourneaux 👨‍🍳', body_fr = 'Activez le mode Partenaire. Aujourd''hui, préparer le déjeuner et le faire manger, c''est le rôle de papa ! Vous, consacrez ce temps à vous-même en lisant ou en vous reposant.', title_hi = 'पापा का रसोई वाला दिन 👨‍🍳', body_hi = 'पार्टनर मोड चालू कीजिए। आज लंच बनाना और खिलाना पापा की ज़िम्मेदारी है! और आप यह समय किताब पढ़कर या आराम करके खुद को दीजिए।', title_id = 'Hari dapur Ayah 👨‍🍳', body_id = 'Aktifkan mode Pasangan. Hari ini menyiapkan makan siang dan menyuapi adalah tugas Ayah! Gunakan waktu ini untuk diri Anda dengan membaca buku atau beristirahat.', title_ja = 'パパのキッチンデー 👨‍🍳', body_ja = '「パートナーモード」をオンにしましょう。今日のランチ作りと食べさせるのはパパの担当！あなたはこの時間を、読書やひと休みなど自分のために使って。', title_ko = '아빠의 주방 데이 👨‍🍳', body_ko = '파트너 모드를 켜세요. 오늘 점심 준비와 먹이기는 아빠 몫이에요! 엄마는 이 시간을 책을 읽거나 쉬며 오롯이 나를 위해 쓰세요.', title_nl = 'Papa''s keukendag 👨‍🍳', body_nl = 'Zet Partnermodus aan. Vandaag zijn lunch maken en eten geven papa''s taak! Besteed die tijd aan jezelf, met een boek of gewoon rust.', title_pl = 'Dzień taty w kuchni 👨‍🍳', body_pl = 'Włącz tryb Partnera. Dziś przygotowanie obiadu i karmienie to zadanie taty! A ty poświęć ten czas sobie, czytając książkę albo odpoczywając.', title_pt = 'O dia do pai na cozinha 👨‍🍳', body_pt = 'Ative o Modo Parceiro. Hoje, fazer o almoço e dar de comer é tarefa do pai! E a mãe dedica este tempo a si mesma, a ler um livro ou a descansar.', title_sv = 'Pappas köksdag 👨‍🍳', body_sv = 'Aktivera Partnerläget. I dag är det pappas uppgift att laga lunch och mata barnet! Ägna du den tiden åt dig själv genom att läsa en bok eller vila.', title_vi = 'Ngày vào bếp của bố 👨‍🍳', body_vi = 'Hãy bật Chế độ đối tác. Hôm nay nấu bữa trưa và cho bé ăn là nhiệm vụ của bố! Còn mẹ dành thời gian này cho bản thân, đọc sách hoặc nghỉ ngơi.', title_zh = '爸爸的厨房日 👨‍🍳', body_zh = '打开伴侣模式。今天做午饭、喂饭都是爸爸的任务！你就把这段时间留给自己，看看书或休息一下吧。' WHERE id = 'a8561422-a7d3-4164-876d-1471ce35f23d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ya camina, pero a veces gatea rápido para escaparse de ti por diversión? Quita los obstáculos peligrosos de la habitación y únete tú también al juego del pilla-pilla.', body_fr = 'Il marche déjà, mais il lui arrive de repartir à quatre pattes à toute vitesse pour vous échapper en s''amusant ? Retirez les obstacles dangereux de la pièce et jouez, vous aussi, au chat et à la souris.', body_hi = 'चलने के साथ-साथ कभी-कभी मज़े के लिए तेज़ी से घुटनों के बल चलकर आपसे भागता है? कमरे से खतरनाक रुकावटें हटाइए और इस पकड़म-पकड़ाई में आप भी शामिल हो जाइए।', body_id = 'Selain berjalan, kadang ia merangkak cepat untuk kabur dari Anda sambil bermain? Singkirkan rintangan berbahaya di kamar dan ikutlah bermain kejar-kejaran.', body_ja = 'もう歩けるのに、ときどき遊びでさっとはいはいして逃げていきますか？部屋の危ないものを片づけて、あなたもこの追いかけっこに加わりましょう。', body_ko = '이제 걷는데도 가끔 재미로 빠르게 기어서 도망가나요? 방의 위험한 장애물을 치우고 엄마도 이 술래잡기에 함께해 보세요.', body_nl = 'Loopt hij al, maar kruipt hij soms voor de lol razendsnel bij je weg? Ruim gevaarlijke obstakels in de kamer op en doe mee met dit tikkertje.', body_pl = 'Choć już chodzi, czasem dla zabawy szybko raczkuje i przed tobą ucieka? Usuń z pokoju niebezpieczne przeszkody i dołącz do tej zabawy w berka.', body_pt = 'Além de andar, às vezes gatinha depressa para fugir de si, por brincadeira? Retire os obstáculos perigosos do quarto e entre também nesta brincadeira da apanhada.', body_sv = 'Går barnet redan men kryper ibland snabbt iväg från dig för skojs skull? Plocka bort farliga hinder i rummet och var med i tafattleken du också.', body_vi = 'Đã biết đi nhưng đôi khi bé vẫn bò thật nhanh để "trốn" mẹ cho vui? Hãy dọn những vật cản nguy hiểm trong phòng và cùng tham gia trò đuổi bắt này nhé.', body_zh = '已经会走了，有时却为了好玩飞快地爬着躲开你？收起房间里危险的障碍物，你也加入这场“你追我跑”的游戏吧。' WHERE id = 'f2202a7a-5edc-4209-b790-4083df0975d2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No sabe por qué llora 😭', body_es = '¿Se monta una gran crisis porque el vaso es rojo y no azul? En realidad la causa es el cansancio o la sobrecarga sensorial. Desahógate con Anacan AI y aprende a gestionar con calma estos estallidos emocionales.', title_fr = 'Il ne sait pas pourquoi il pleure 😭', body_fr = 'Grosse crise parce que le gobelet est rouge et non bleu ? En réalité, la cause est la fatigue ou une surcharge émotionnelle. Discutez avec Anacan AI pour gérer avec calme ces explosions émotionnelles incontrôlables.', title_hi = 'उसे नहीं पता वह क्यों रो रहा है 😭', body_hi = 'गिलास नीला नहीं, लाल है, इसलिए बड़ा हंगामा? असल वजह थकान या भावनाओं का बोझ होती है। इन बेकाबू भावनात्मक विस्फोटों को शांत रहकर संभालने के लिए Anacan AI से बात कीजिए।', title_id = 'Tak tahu kenapa menangis 😭', body_id = 'Tantrum besar karena gelasnya merah, bukan biru? Sebenarnya penyebabnya kelelahan atau emosi yang berlebihan. Mengobrollah dengan Anacan AI untuk belajar menghadapi ledakan emosi tak terkendali ini dengan kepala dingin.', title_ja = 'なんで泣いているのかわからない 😭', body_ja = 'コップが青じゃなくて赤だからと大騒ぎ？本当の原因は疲れや感覚の刺激が多すぎることです。この手に負えない感情の爆発に冷静に対応するために、Anacan AIに相談しましょう。', title_ko = '왜 우는지 몰라요 😭', body_ko = '컵이 파란색이 아니라 빨간색이라고 큰 난리가 났나요? 사실 이유는 피곤함이나 감정 과부하예요. 걷잡을 수 없는 감정 폭발을 침착하게 다루는 방법을 Anacan AI와 이야기해 보세요.', title_nl = 'Hij weet niet waarom hij huilt 😭', body_nl = 'Een enorme driftbui omdat zijn beker rood is en niet blauw? Eigenlijk zit vermoeidheid of overprikkeling erachter. Praat met Anacan AI om deze onbeheersbare emotionele uitbarstingen kalm op te vangen.', title_pl = 'Nie wie, dlaczego płacze 😭', body_pl = 'Wielki kryzys, bo kubek nie jest niebieski, tylko czerwony? Tak naprawdę przyczyną jest zmęczenie albo przeciążenie emocjami. Porozmawiaj z Anacan AI, by nauczyć się spokojnie radzić sobie z tymi niekontrolowanymi wybuchami.', title_pt = 'Nem sabe porque chora 😭', body_pt = 'Faz uma grande crise porque o copo é vermelho e não azul? Na verdade, a causa é o cansaço ou a sobrecarga emocional. Fale com o Anacan AI para gerir com calma estas explosões emocionais incontroláveis.', title_sv = 'Barnet vet inte varför hen gråter 😭', body_sv = 'Blir det en stor kris för att muggen är röd och inte blå? Egentligen är orsaken trötthet eller känslomässig överbelastning. Prata med Anacan AI för att hantera de här okontrollerade känsloutbrotten med lugn.', title_vi = 'Bé không biết vì sao mình khóc 😭', body_vi = 'Một cơn khủng hoảng lớn chỉ vì cốc màu đỏ chứ không phải màu xanh? Thật ra nguyên nhân là mệt mỏi hoặc quá tải cảm xúc. Hãy trò chuyện với Anacan AI để bình tĩnh xử lý những cơn bùng nổ cảm xúc khó kiểm soát này.', title_zh = '不知道自己为什么哭 😭', body_zh = '因为杯子是红的不是蓝的，就大闹一场？其实原因是疲惫或情绪过载。和Anacan AI聊一聊，学学怎样冷静应对这些失控的情绪爆发。' WHERE id = '04970a72-c396-466c-9613-3a82e661e79f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ruidos extraños en la habitación 🌌', body_es = '¿Le despierta el silencio total de la habitación o los golpecitos de los vecinos? Pon el sonido del ventilador de Ruido blanco y verás qué aislamiento tan perfecto crea para dormir.', title_fr = 'Bruits étranges dans la chambre 🌌', body_fr = 'Le silence total de la chambre ou les petits coups chez les voisins le réveillent ? Mettez le bruit du ventilateur dans les Bruits blancs et voyez comme il isole parfaitement son sommeil.', title_hi = 'कमरे की अनजानी आवाज़ें 🌌', body_hi = 'कमरे की पूरी खामोशी या पड़ोस से आती छोटी-छोटी खटखट उसे जगा देती है? व्हाइट नॉइज़ में पंखे की आवाज़ चलाइए और देखिए कि यह नींद के माहौल को कितनी अच्छी तरह बाहरी आवाज़ों से बचाती है।', title_id = 'Suara asing di kamar 🌌', body_id = 'Hening total di kamar atau ketukan kecil dari tetangga membangunkannya? Putar suara kipas dari Suara Putih dan lihat betapa sempurnanya ia meredam suara di sekitar tidurnya.', title_ja = '部屋の聞きなれない音 🌌', body_ja = '部屋の完全な静けさや、となりからの小さな物音で目を覚ましますか？「ホワイトノイズ」の扇風機の音を流して、眠りの環境がどれほどしっかり守られるか確かめてみましょう。', title_ko = '방 안의 낯선 소리 🌌', body_ko = '방 안의 완전한 정적이나 이웃집의 작은 똑딱 소리에 깨나요? 백색소음에서 선풍기 소리를 틀어 수면 환경을 얼마나 완벽하게 차단해 주는지 확인해 보세요.', title_nl = 'Vreemde geluiden in de kamer 🌌', body_nl = 'Wordt hij wakker van totale stilte of van kleine tikjes bij de buren? Zet in Witte ruis het ventilatorgeluid aan en merk hoe goed dat zijn slaapomgeving afschermt.', title_pl = 'Obce dźwięki w pokoju 🌌', body_pl = 'Budzi go całkowita cisza w pokoju albo drobne stukanie od sąsiadów? Włącz z Białego szumu odgłos wentylatora i zobacz, jak idealnie izoluje on przestrzeń do snu.', title_pt = 'Sons estranhos no quarto 🌌', body_pt = 'O silêncio total do quarto ou os pequenos barulhos do vizinho acordam-no? Ponha o som de ventoinha do Ruído Branco e veja como cria um isolamento perfeito no ambiente de sono.', title_sv = 'Främmande ljud i rummet 🌌', body_sv = 'Vaknar barnet av total tystnad i rummet eller av små knackningar från grannarna? Sätt på fläktljudet i Vitt brus och se hur perfekt det isolerar sömnmiljön.', title_vi = 'Những âm thanh lạ trong phòng 🌌', body_vi = 'Sự im lặng tuyệt đối hay tiếng lạch cạch nhỏ từ nhà hàng xóm khiến bé thức giấc? Hãy bật tiếng quạt trong Tiếng ồn trắng và xem nó tạo lớp cách âm hoàn hảo cho giấc ngủ thế nào.', title_zh = '房间里陌生的声音 🌌', body_zh = '房间里太安静，或者邻居家细小的敲击声会把宝宝吵醒？打开白噪音里的风扇声，看看它怎样为睡眠环境营造完美的隔音效果。' WHERE id = 'c150e539-1698-44fc-be7c-18e8beb9b566' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Limpieza en familia 🧹', body_es = '¿Toca limpiar la casa? ¡Activa el modo Pareja! Descubrid tú, su padre y tu peque (con un trapito en la mano) cómo convertir la limpieza en un divertido juego familiar.', title_fr = 'Le ménage en famille 🧹', body_fr = 'Il faut faire le ménage ? Activez le mode Partenaire ! Vous, papa et votre petit (avec un petit chiffon en main), découvrez comment faire du ménage un jeu familial amusant.', title_hi = 'साथ मिलकर घर की सफ़ाई 🧹', body_hi = 'घर साफ़ करना है? पार्टनर मोड चालू कीजिए! आप, पापा और आपका नन्हा (उसके हाथ में छोटा सा कपड़ा देकर) मिलकर जानिए कि सफ़ाई को मज़ेदार फ़ैमिली गेम कैसे बनाएँ।', title_id = 'Bersih-bersih bersama 🧹', body_id = 'Rumah perlu dibersihkan? Nyalakan mode Pasangan! Anda, ayahnya, dan si kecil (dengan lap kecil di tangannya) bisa menemukan cara mengubah bersih-bersih menjadi permainan keluarga yang seru.', title_ja = 'みんなでお掃除 🧹', body_ja = '家の掃除をしなきゃ？「パートナーモード」をオンにしましょう！あなたとパパとお子さん（小さなぞうきんを渡して）で、お掃除を楽しい家族の遊びにする方法を見つけて。', title_ko = '함께하는 집 청소 🧹', body_ko = '집 청소를 해야 하나요? 파트너 모드를 켜세요! 엄마, 아빠, 그리고 작은 걸레를 쥔 아이가 함께 청소를 즐거운 가족 놀이로 바꿔 보세요.', title_nl = 'Samen het huis schoonmaken 🧹', body_nl = 'Moet het huis schoon? Zet Partnermodus aan! Ontdek hoe jij, papa en je kleintje (met een klein doekje in zijn hand) van schoonmaken een leuk gezinsspel maken.', title_pl = 'Wspólne sprzątanie domu 🧹', body_pl = 'Trzeba posprzątać dom? Włącz tryb Partnera! Ty, tata i maluch (z małą ściereczką w ręce) odkryjcie, jak zamienić sprzątanie w wesołą rodzinną zabawę.', title_pt = 'Limpezas em família 🧹', body_pt = 'É preciso limpar a casa? Ative o Modo Parceiro! A mãe, o pai e o pequeno (com um paninho na mão) descubram como transformar a limpeza num jogo de família divertido.', title_sv = 'Storstädning tillsammans 🧹', body_sv = 'Behöver hemmet städas? Starta Partnerläget! Upptäck hur du, pappa och den lilla (med en liten trasa i handen) kan göra städningen till en rolig familjelek.', title_vi = 'Cùng nhau dọn nhà 🧹', body_vi = 'Cần dọn nhà? Hãy bật Chế độ đối tác! Mẹ, bố và bé (cầm một chiếc khăn nhỏ) sẽ khám phá cách biến việc dọn dẹp thành trò chơi gia đình vui nhộn.', title_zh = '一起打扫家里 🧹', body_zh = '家里该打扫了？打开伴侣模式！你、爸爸和小家伙（给宝宝一块小抹布），一起来发现怎样把打扫变成有趣的家庭游戏。' WHERE id = 'f0684802-cf6d-4a4b-96a5-44c5cabd2832' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juego en lugar de pantalla 📱', body_es = '¿Por la tarde pide dibujos animados y llora? Aprende con Anacan AI a limitar el tiempo de pantalla sin estrés y a llevar enseguida su atención a otro juego.', title_fr = 'Du jeu plutôt que l''écran 📱', body_fr = 'Il réclame un dessin animé en fin d''après-midi et pleure ? Découvrez avec Anacan AI comment limiter le temps d''écran sans stress et détourner tout de suite son attention vers un autre jeu.', title_hi = 'स्क्रीन की जगह खेल 📱', body_hi = 'शाम को कार्टून माँगता है और रोता है? Anacan AI से जानिए कि बिना तनाव के स्क्रीन टाइम कैसे सीमित करें और उसका ध्यान तुरंत किसी दूसरे खेल पर कैसे लगाएँ।', title_id = 'Bermain, bukan layar 📱', body_id = 'Menjelang malam ia minta film kartun sambil menangis? Pelajari dari Anacan AI cara membatasi waktu layar tanpa stres dan segera mengalihkan perhatiannya ke permainan lain.', title_ja = '画面のかわりに遊びを 📱', body_ja = '夕方にアニメを見たがって泣きますか？ストレスなく画面の時間を制限し、すぐにほかの遊びに気をそらす方法を、Anacan AIから学びましょう。', title_ko = '화면 대신 놀이 📱', body_ko = '저녁 무렵 만화를 보겠다며 우나요? 스트레스 없이 화면 시간을 줄이고 관심을 다른 놀이로 바로 돌리는 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Spelen in plaats van een scherm 📱', body_nl = 'Wil hij aan het eind van de middag tekenfilms en huilt hij? Leer van Anacan AI hoe je schermtijd zonder stress beperkt en zijn aandacht meteen naar een ander spel trekt.', title_pl = 'Zabawa zamiast ekranu 📱', body_pl = 'Pod wieczór chce bajek w telewizji i płacze? Dowiedz się od Anacan AI, jak bez stresu ograniczyć czas przed ekranem i od razu przekierować jego uwagę na inną zabawę.', title_pt = 'Brincar em vez de ecrã 📱', body_pt = 'Ao fim da tarde pede desenhos animados e chora? Aprenda com o Anacan AI a limitar o tempo de ecrã sem stress e a desviar logo a atenção dele para outra brincadeira.', title_sv = 'Lek i stället för skärm 📱', body_sv = 'Vill barnet se tecknat på eftermiddagen och gråter? Lär dig av Anacan AI hur du begränsar skärmtiden utan stress och genast leder uppmärksamheten till en annan lek.', title_vi = 'Chơi thay vì màn hình 📱', body_vi = 'Chiều tối bé đòi xem hoạt hình và khóc? Hãy học từ Anacan AI cách giới hạn thời gian xem màn hình mà không căng thẳng và chuyển ngay sự chú ý của bé sang trò chơi khác.', title_zh = '用游戏代替屏幕 📱', body_zh = '傍晚想看动画片，还哭闹？向Anacan AI学学怎样没有压力地限制屏幕时间，并马上把宝宝的注意力引到别的游戏上。' WHERE id = '20745776-36d1-4511-abf0-1fafb63ced1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu momento del café ☕', body_es = '¿Cansada de estar siempre en casa? Busca en Lugares para mamás cafeterías infantiles donde se reúnen muchas madres y crea un nuevo ambiente para socializar tú también.', title_fr = 'Votre pause café ☕', body_fr = 'Fatiguée de rester à la maison ? Trouvez dans les Lieux adaptés aux mamans des cafés pour enfants où les mamans se retrouvent et offrez-vous un nouvel endroit pour sociabiliser.', title_hi = 'आपकी कॉफ़ी का समय ☕', body_hi = 'घर में अकेले बैठे-बैठे थक गईं? माँ के लिए अनुकूल जगहें में ऐसे किड्स कैफ़े ढूँढिए जहाँ माँएँ अक्सर मिलती हैं, और अपने लिए भी मेलजोल का नया माहौल बनाइए।', title_id = 'Waktu ngopi Anda ☕', body_id = 'Bosan hanya duduk di rumah? Temukan kafe anak tempat banyak ibu berkumpul di Tempat Ramah Ibu dan ciptakan suasana baru untuk Anda bersosialisasi.', title_ja = 'あなたのコーヒータイム ☕', body_ja = '家にいるだけの毎日に疲れましたか？「ママにやさしいスポット」でママたちがよく集まるキッズカフェを見つけて、自分も人とつながれる新しい場所をつくりましょう。', title_ko = '엄마의 커피 타임 ☕', body_ko = '집에만 있는 게 지겨워졌나요? 엄마 친화 장소에서 엄마들이 많이 모이는 키즈 카페를 찾아 나에게도 사람들과 어울릴 새로운 환경을 만들어 주세요.', title_nl = 'Jouw koffiemoment ☕', body_nl = 'Ben je het zat om alleen thuis te zitten? Zoek in Mamavriendelijke plekken kindercafés waar veel moeders komen en zorg ook voor jezelf voor een nieuwe plek om mensen te ontmoeten.', title_pl = 'Twój czas na kawę ☕', body_pl = 'Masz dość siedzenia w domu? Znajdź w Miejscach przyjaznych mamom kawiarnie dla dzieci, gdzie spotyka się wiele mam, i stwórz sobie nowe otoczenie do kontaktów z innymi.', title_pt = 'A sua hora do café ☕', body_pt = 'Cansada de estar só em casa? Encontre nos Locais Amigos das Mães cafés para crianças onde se juntam muitas mães e crie um novo ambiente para também conviver.', title_sv = 'Din kaffestund ☕', body_sv = 'Är du trött på att bara sitta hemma? Hitta barnkaféer där många mammor träffas i Mammavänliga platser och skapa en ny miljö där du också kan umgås.', title_vi = 'Giờ cà phê của mẹ ☕', body_vi = 'Mẹ mệt vì chỉ ở nhà? Hãy tìm những quán cà phê trẻ em nơi các mẹ hay gặp nhau trong Địa điểm thân thiện với mẹ và tạo cho mình một không gian mới để giao lưu.', title_zh = '你的咖啡时间 ☕', body_zh = '总待在家里待累了？在妈妈友好场所里找找妈妈们常去的亲子咖啡馆，也给自己创造一个社交的新环境。' WHERE id = '956585f5-6347-4c88-b6a3-3638bd223889' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de esperar turno 🧸', body_es = '¿En el parque no quiere esperar a que otro niño baje del tobogán? Lee sin falta en el Blog cómo enseñarle paciencia y a jugar por turnos a partir de los 2,5 años.', title_fr = 'L''art d''attendre son tour 🧸', body_fr = 'Au parc, il ne veut pas attendre qu''un autre enfant descende du toboggan ? Lisez absolument dans la rubrique Blogs comment lui transmettre, après 2,5 ans, la patience et le jeu chacun son tour.', title_hi = 'बारी का इंतज़ार करने की कला 🧸', body_hi = 'पार्क में दूसरे बच्चे के स्लाइड से उतरने का इंतज़ार नहीं करना चाहता? 2.5 साल के बाद सब्र और बारी-बारी से खेलने की समझ कैसे दें, यह ब्लॉग सेक्शन में ज़रूर पढ़िए।', title_id = 'Seni menunggu giliran 🧸', body_id = 'Di taman ia tidak mau menunggu anak lain turun dari perosotan? Baca di bagian Blog cara menanamkan konsep sabar dan bermain bergiliran setelah usia 2,5 tahun.', title_ja = '順番を待つ練習 🧸', body_ja = '公園でほかの子がすべり台をすべり終わるのを待てない？2歳半を過ぎたら、がまんすることや順番に遊ぶことをどう教えるか、ブログでぜひ読んでみましょう。', title_ko = '차례를 기다리는 기술 🧸', body_ko = '공원에서 다른 아이가 미끄럼틀을 다 탈 때까지 기다리기 싫어하나요? 두 돌 반 이후 인내심과 차례대로 노는 개념을 어떻게 알려 줄지 블로그 섹션에서 꼭 읽어 보세요.', title_nl = 'De kunst van op je beurt wachten 🧸', body_nl = 'Wil hij in het park niet wachten tot een ander kind van de glijbaan is? Lees in Blogs hoe je na 2,5 jaar geduld en om de beurt spelen aanleert.', title_pl = 'Sztuka czekania na swoją kolej 🧸', body_pl = 'W parku nie chce czekać, aż inne dziecko zjedzie ze zjeżdżalni? Koniecznie przeczytaj w sekcji Blog, jak po 2,5 roku uczyć cierpliwości i zabawy po kolei.', title_pt = 'A arte de esperar a vez 🧸', body_pt = 'No parque, não quer esperar que outra criança desça do escorrega? Leia sem falta no Blogue como ensinar paciência e a brincar à vez depois dos 2,5 anos.', title_sv = 'Konsten att vänta på sin tur 🧸', body_sv = 'Vill barnet inte vänta på att ett annat barn ska åka ner för rutschkanan i parken? Läs i avsnittet Bloggar hur du efter 2,5 år lär ut tålamod och att turas om.', title_vi = 'Nghệ thuật chờ đến lượt 🧸', body_vi = 'Bé không muốn chờ bạn khác trượt xong ở công viên? Nhất định hãy đọc trong mục Blog cách dạy bé sự kiên nhẫn và chơi lần lượt sau tuổi 2,5.', title_zh = '等待轮到自己的艺术 🧸', body_zh = '在公园里不想等别的小朋友从滑梯上下来？一定要去博客板块读读，2.5岁以后怎样培养耐心和“轮流玩”的概念。' WHERE id = '96e63d94-22cd-4a99-8350-f721e6ade562' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vitamina D para los huesos ☀️', body_es = '¡La vitamina D es imprescindible para absorber el calcio! Revisa la dieta de hoy con el Seguimiento de tomas y echa un vistazo en Productos recomendados a las gotas que recomiendan los médicos.', title_fr = 'De la vitamine D pour les os ☀️', body_fr = 'La vitamine D est indispensable à l''absorption du calcium ! Vérifiez son alimentation du jour avec le Suivi des repas et jetez un œil aux gouttes conseillées par les médecins dans les Produits recommandés.', title_hi = 'हड्डियों के लिए विटामिन D ☀️', body_hi = 'कैल्शियम के अवशोषण के लिए विटामिन D ज़रूरी है! फ़ीडिंग ट्रैकर से आज का खाना जाँचिए और सुझाए गए प्रोडक्ट में डॉक्टरों की सुझाई ड्रॉप्स देखिए।', title_id = 'Vitamin D untuk tulang ☀️', body_id = 'Vitamin D wajib untuk penyerapan kalsium! Periksa menu hari ini di Pemantau Nutrisi dan lihat tetes vitamin yang disarankan dokter di Produk Rekomendasi.', title_ja = '骨のためのビタミンD ☀️', body_ja = 'カルシウムの吸収にはビタミンDが欠かせません！「栄養管理ツール」で今日の食事を確認して、「おすすめ商品」で医師がすすめるドロップをチェックしましょう。', title_ko = '뼈를 위한 비타민 D ☀️', body_ko = '칼슘이 흡수되려면 비타민 D가 꼭 필요해요! 수유 기록 도구로 오늘의 식단을 확인하고, 추천 제품에서 의사들이 권하는 드롭 제품을 살펴보세요.', title_nl = 'Vitamine D voor de botten ☀️', body_nl = 'Vitamine D is nodig om calcium op te nemen! Check het menu van vandaag in de Voedingstracker en bekijk in Aanbevolen producten de druppels die artsen aanraden.', title_pl = 'Witamina D dla kości ☀️', body_pl = 'Witamina D jest niezbędna do wchłaniania wapnia! Sprawdź dzisiejszą dietę w narzędziu do śledzenia karmienia i zajrzyj do Polecanych produktów po krople zalecane przez lekarzy.', title_pt = 'Vitamina D para os ossos ☀️', body_pt = 'A vitamina D é essencial para absorver o cálcio! Verifique a alimentação de hoje no Registo de Alimentação e veja nos Produtos Recomendados as gotas aconselhadas pelos médicos.', title_sv = 'D-vitamin för skelettet ☀️', body_sv = 'D-vitamin behövs för att kalcium ska tas upp! Kolla dagens kost med Matningskoll och titta på dropparna som läkare rekommenderar i Rekommenderade produkter.', title_vi = 'Vitamin D cho xương ☀️', body_vi = 'Vitamin D là điều kiện để hấp thu canxi! Hãy kiểm tra khẩu phần hôm nay bằng Theo dõi cữ bú và xem các loại thuốc nhỏ giọt được bác sĩ khuyên dùng trong Sản phẩm gợi ý.', title_zh = '强健骨骼的维生素D ☀️', body_zh = '钙的吸收离不开维生素D！用喂养记录工具检查今天的饮食，再去推荐商品看看医生推荐的滴剂。' WHERE id = '9f77c4af-512a-49b9-8cbf-0c7c57609122' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La crisis de las prisas 🛑', body_es = '¿Tenéis que salir de casa, pero lo hace todo despacio y sin prisa? ¡A esta edad no existe el concepto del tiempo! En lugar de meterle prisa, aprende con nuestro experto Anacan AI a facilitar las transiciones.', title_fr = 'La crise du retard 🛑', body_fr = 'Vous devez sortir, mais il fait tout lentement et ne se presse pas ? À cet âge, la notion de temps n''existe pas ! Plutôt que de le presser, apprenez avec notre expert Anacan AI à faciliter les transitions.', title_hi = 'देरी का संकट 🛑', body_hi = 'घर से निकलना है, लेकिन वह सब कुछ धीरे-धीरे करता है और जल्दी नहीं करता? इस उम्र में समय की समझ नहीं होती! जल्दबाज़ी कराने के बजाय हमारे Anacan AI एक्सपर्ट से जानिए कि एक काम से दूसरे पर जाना आसान कैसे बनाएँ।', title_id = 'Krisis terlambat 🛑', body_id = 'Anda harus keluar rumah, tetapi ia melakukan semuanya pelan-pelan dan tidak terburu-buru? Di usia ini belum ada konsep waktu! Daripada mendesaknya, pelajari dari ahli Anacan AI cara memperlancar peralihan.', title_ja = 'おでかけ前のバトル 🛑', body_ja = '出かけなきゃいけないのに、なんでもゆっくりで急がない？この年齢には時間の感覚がありません！せかすかわりに切りかえを楽にする方法を、Anacan AIのエキスパートから学びましょう。', title_ko = '늑장 위기 🛑', body_ko = '집을 나서야 하는데 아이는 모든 걸 천천히 하며 서두르지 않나요? 이 나이엔 시간 개념이 없어요! 재촉하는 대신 전환을 쉽게 만드는 방법을 Anacan AI 전문가에게 배워 보세요.', title_nl = 'Strijd om op tijd te zijn 🛑', body_nl = 'Moeten jullie de deur uit, maar doet hij alles langzaam en heeft hij geen haast? Op deze leeftijd bestaat het begrip tijd nog niet! Leer van onze expert Anacan AI hoe je overgangen makkelijker maakt in plaats van hem op te jagen.', title_pl = 'Kryzys spóźnienia 🛑', body_pl = 'Musicie wyjść z domu, a on robi wszystko powoli i wcale się nie spieszy? W tym wieku nie ma jeszcze pojęcia czasu! Zamiast go poganiać, dowiedz się od naszego eksperta Anacan AI, jak ułatwić przejścia między czynnościami.', title_pt = 'A crise dos atrasos 🛑', body_pt = 'Têm de sair de casa, mas ele faz tudo devagar e sem pressa? Nesta idade não existe noção de tempo! Em vez de o apressar, aprenda com o especialista Anacan AI a facilitar as transições.', title_sv = 'Förseningskris 🛑', body_sv = 'Ni måste gå hemifrån, men barnet gör allt långsamt och har ingen brådska? I den här åldern finns inget tidsbegrepp! Lär dig av vår expert Anacan AI hur du gör övergångarna enklare i stället för att stressa.', title_vi = 'Khủng hoảng chậm trễ 🛑', body_vi = 'Cần ra khỏi nhà mà bé làm gì cũng chậm và chẳng vội? Ở tuổi này bé chưa có khái niệm thời gian! Thay vì giục giã, hãy học từ chuyên gia Anacan AI cách giúp những lần chuyển đổi dễ dàng hơn.', title_zh = '拖延危机 🛑', body_zh = '该出门了，可宝宝什么都慢吞吞，一点也不急？这个年龄还没有时间概念！与其催促，不如向我们的Anacan AI专家学学怎样让过渡更顺利。' WHERE id = 'a85116cf-7f79-486c-8e28-8b90c93cfb63' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hoy se te ha agotado la paciencia y has levantado la voz? No te sientas culpable. Cuando se duerma, aligera la carga escribiendo tus agobios en el Diario de ánimo.', body_fr = 'Votre patience a débordé et vous avez haussé la voix aujourd''hui ? Ne culpabilisez pas. Quand il dort, allégez votre charge en écrivant vos tensions dans le Journal d''humeur.', body_hi = 'आज सब्र टूट गया और आवाज़ ऊँची हो गई? खुद को दोष मत दीजिए। बच्चे के सोने के बाद मूड डायरी में अपने मन की घुटन लिखकर बोझ हल्का कीजिए।', body_id = 'Hari ini kesabaran Anda habis dan suara Anda meninggi? Jangan merasa bersalah. Setelah anak tidur, ringankan beban dengan menuliskan isi hati Anda di Buku Harian Suasana Hati.', body_ja = '今日はがまんの限界で声を荒げてしまいましたか？罪悪感を持たないで。お子さんが眠ったら「気分日記」に心のもやもやを書いて、気持ちを軽くしましょう。', body_ko = '오늘 인내심이 바닥나서 목소리가 커졌나요? 죄책감은 갖지 마세요. 아이가 잠든 뒤 기분 일기에 속마음을 적으며 짐을 덜어 내세요.', body_nl = 'Was je geduld vandaag op en verhief je je stem? Voel je niet schuldig. Schrijf je zorgen in je Stemmingsdagboek als hij slaapt en verlicht je last.', body_pl = 'Dziś puściły ci nerwy i podniosłaś głos? Nie miej wyrzutów sumienia. Gdy dziecko zaśnie, zapisz swoje wewnętrzne troski w Dzienniku nastroju i ulżyj sobie.', body_pt = 'Hoje a paciência esgotou-se e levantou a voz? Não sinta culpa. Depois de a criança adormecer, escreva as suas angústias no Diário de Humor e alivie o peso.', body_sv = 'Rann tålamodet över i dag och du höjde rösten? Ha inte dåligt samvete. När barnet somnat, skriv ner det som tynger dig i Humördagboken och lätta bördan.', body_vi = 'Hôm nay mẹ hết kiên nhẫn và lỡ to tiếng? Đừng dằn vặt. Khi bé ngủ, hãy viết những nỗi niềm vào Nhật ký tâm trạng để nhẹ gánh hơn.', body_zh = '今天耐心用完了，嗓门也提高了？别内疚。孩子睡着后，把心里的烦闷写进心情日记，给自己减减负。' WHERE id = 'b222d604-2c4a-4c8d-9eda-efff14884581' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se acaba la siesta? ⏱️', body_es = '¿Se niega en redondo a dormir la siesta y por la noche está agotadísimo? Analiza las estadísticas del temporizador de sueño y prueba a pasar a una hora de calma (quiet time).', title_fr = 'La sieste appartient au passé ? ⏱️', body_fr = 'Il refuse catégoriquement la sieste, mais le soir il est épuisé ? Analysez les statistiques du Minuteur de sommeil et essayez de passer entièrement à un « temps calme ».', title_hi = 'दिन की नींद अब इतिहास? ⏱️', body_hi = 'दोपहर में सोने से साफ़ मना करता है और शाम तक बहुत ज़्यादा थक जाता है? स्लीप टाइमर के आँकड़े देखिए और पूरी तरह ''शांत समय'' (quiet time) पर जाने के बारे में सोचिए।', title_id = 'Tidur siang tinggal kenangan? ⏱️', body_id = 'Ia menolak tidur siang sama sekali, lalu sangat kelelahan di malam hari? Analisis statistik Timer Tidur dan coba beralih sepenuhnya ke jam tenang (quiet time).', title_ja = 'お昼寝は卒業？⏱️', body_ja = 'お昼寝をきっぱり拒否して、夕方には疲れすぎていますか？睡眠タイマーの記録を分析して、「静かな時間」に切りかえることを試してみましょう。', title_ko = '낮잠은 이제 옛날 일인가요? ⏱️', body_ko = '낮잠은 단호히 거부하고 저녁엔 너무 지쳐 버리나요? 수면 타이머 통계를 분석하고 완전히 ''조용한 시간'' 루틴으로 바꿔 보는 것을 고려해 보세요.', title_nl = 'Is het middagslaapje verleden tijd? ⏱️', body_nl = 'Weigert hij resoluut een middagslaapje en is hij ''s avonds oververmoeid? Analyseer de statistieken van de Slaaptimer en probeer over te stappen op een rustuurtje.', title_pl = 'Koniec z drzemkami w dzień? ⏱️', body_pl = 'Stanowczo odmawia drzemki po południu, a wieczorem jest przemęczony? Przeanalizuj statystyki timera snu i spróbuj przejść całkowicie na godzinę wyciszenia (quiet time).', title_pt = 'A sesta está a passar à história? ⏱️', body_pt = 'Recusa terminantemente dormir a sesta e à noite fica cansado demais? Analise as estatísticas do temporizador de sono e experimente passar só para uma hora de sossego (quiet time).', title_sv = 'Är dagsömnen ett minne blott? ⏱️', body_sv = 'Vägrar barnet helt att sova middag men är alldeles för trött på kvällen? Analysera sömntimerns statistik och prova att gå över helt till en lugn stund (quiet time).', title_vi = 'Giấc ngủ ngày đã thành quá khứ? ⏱️', body_vi = 'Bé dứt khoát không ngủ trưa, còn buổi tối thì quá mệt? Hãy phân tích thống kê của Bộ hẹn giờ ngủ và thử chuyển hẳn sang chế độ giờ yên tĩnh (quiet time).', title_zh = '午睡要成为过去了？⏱️', body_zh = '中午坚决不肯睡，晚上却累过了头？分析一下睡眠计时器的统计数据，试着换成完全的“安静时间”模式。' WHERE id = '259a4698-04af-4cc3-93e9-91599ab8a275' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las crisis de SPM de mamá 🍫', body_es = '¿Te baja la energía antes de la regla? Antes de recurrir a los medicamentos, recupera tu cuerpo con un batido de frutos rojos con azúcares naturales de Recetas saludables para mujeres que da fuerza al instante.', title_fr = 'Les crises de SPM de maman 🍫', body_fr = 'Votre énergie chute à l''approche de vos règles ? Avant de vous jeter sur les médicaments, préparez avec les Recettes saines pour femmes un smoothie aux baies, naturellement sucré et énergisant, pour retrouver vos forces.', title_hi = 'माँ का PMS वाला मुश्किल समय 🍫', body_hi = 'पीरियड से पहले ऊर्जा कम हो गई? दवाओं की ओर भागने से पहले महिलाओं के लिए सेहतमंद रेसिपी से तुरंत ताकत देने वाली, प्राकृतिक मिठास वाली बेरी स्मूदी बनाइए और शरीर को फिर से तरोताज़ा कीजिए।', title_id = 'Krisis PMS Ibu 🍫', body_id = 'Energi Anda turun menjelang haid? Sebelum buru-buru minum obat, pulihkan tubuh dengan smoothie beri bergula alami yang langsung memberi tenaga dari Resep Sehat untuk wanita.', title_ja = 'ママのPMSのつらさ 🍫', body_ja = '生理の前にエネルギーが落ちていますか？薬にたよる前に、「女性のためのヘルシーレシピ」から、すぐに元気をくれる自然な甘さのベリースムージーをつくって、体を回復させましょう。', title_ko = '엄마의 PMS 위기 🍫', body_ko = '생리 전이라 기운이 떨어졌나요? 진통제를 찾기 전에 여성을 위한 건강한 레시피에서 바로 힘이 나는 자연스러운 단맛의 베리 스무디를 만들어 몸을 회복하세요.', title_nl = 'Mama''s PMS-buien 🍫', body_nl = 'Is je energie laag vlak voor je menstruatie? Grijp niet meteen naar medicijnen, maar herstel je lichaam met een natuurlijk zoete bessensmoothie uit Gezonde recepten voor vrouwen die je direct kracht geeft.', title_pl = 'Kryzysy PMS mamy 🍫', body_pl = 'Przed okresem spada ci energia? Zanim sięgniesz po leki, przygotuj ze Zdrowych przepisów dla kobiet smoothie z owoców jagodowych z naturalnym cukrem, które od razu doda ci sił, i zregeneruj organizm.', title_pt = 'As crises de TPM da mãe 🍫', body_pt = 'A energia caiu nas vésperas do período? Antes de recorrer a medicamentos, recupere o corpo com um smoothie de frutos vermelhos, doce por natureza e cheio de energia, das Receitas Saudáveis para Mulheres.', title_sv = 'Mammas PMS-kriser 🍫', body_sv = 'Har energin sjunkit inför mensen? Innan du tar till medicin, gör en bärsmoothie med naturligt socker som ger kraft direkt från Hälsosamma recept för kvinnor och återställ kroppen.', title_vi = 'Những cơn tiền kinh nguyệt của mẹ 🍫', body_vi = 'Gần đến kỳ kinh mẹ thấy uể oải? Trước khi tìm đến thuốc, hãy làm một ly sinh tố quả mọng ngọt tự nhiên, tiếp sức tức thì từ Công thức lành mạnh cho phụ nữ để cơ thể hồi phục.', title_zh = '妈妈的经前期低潮 🍫', body_zh = '经期前精力下降？吃药之前，先从女性健康食谱里做一杯能马上补充能量、带天然糖分的莓果奶昔，帮身体恢复。' WHERE id = '278f2f23-c655-4241-807c-401148d291e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo corto yo! ✂️', body_es = '¿Quiere cortar él solo el plátano o la plastilina en la cocina? ¡Es un deseo estupendo que exige motricidad fina! Mira ya en Productos recomendados cuchillos y tijeras infantiles seguros que no cortan.', title_fr = 'Je coupe tout seul ! ✂️', body_fr = 'En cuisine, il veut couper lui-même sa banane ou sa pâte à modeler ? C''est une superbe envie qui demande de la motricité fine ! Regardez vite dans les Produits recommandés les couteaux et ciseaux sans danger pour enfants.', title_hi = 'मैं खुद काटूँगा! ✂️', body_hi = 'रसोई में केला या प्ले-डो खुद काटना चाहता है? यह फ़ाइन मोटर स्किल्स माँगने वाली शानदार इच्छा है! सुझाए गए प्रोडक्ट में बच्चों के लिए सुरक्षित, न काटने वाले चाकू और कैंची अभी देखिए।', title_id = 'Aku potong sendiri! ✂️', body_id = 'Ia ingin memotong pisang atau plastisin sendiri di dapur? Ini keinginan hebat yang butuh motorik halus! Segera lihat pisau dan gunting anak yang aman dan tidak tajam di Produk Rekomendasi.', title_ja = '自分で切る！✂️', body_ja = 'キッチンでバナナや粘土を自分で切りたがりますか？指先の細かな運動能力が必要な、すばらしい意欲です！「おすすめ商品」で子ども用の安全な切れないナイフやはさみをさっそく見てみましょう。', title_ko = '내가 자를래! ✂️', body_ko = '주방에서 바나나나 클레이를 직접 자르고 싶어 하나요? 소근육이 필요한 멋진 욕구예요! 추천 제품에서 아이에게 안전한, 베이지 않는 칼과 가위를 바로 살펴보세요.', title_nl = 'Ik snijd het zelf! ✂️', body_nl = 'Wil hij in de keuken zelf een banaan of klei snijden? Een prachtige wens die fijne motoriek vraagt! Bekijk meteen in Aanbevolen producten veilige kindermessen en -scharen die niet snijden.', title_pl = 'Sam pokroję! ✂️', body_pl = 'W kuchni chce sam kroić banana albo ciastolinę? To wspaniała chęć, która wymaga motoryki małej! Od razu zajrzyj do Polecanych produktów po bezpieczne dla dzieci, nietnące noże i nożyczki.', title_pt = 'Eu corto sozinho! ✂️', body_pt = 'Na cozinha, quer cortar sozinho a banana ou a plasticina? É um desejo fantástico que exige motricidade fina! Veja já nos Produtos Recomendados facas e tesouras infantis seguras, que não cortam.', title_sv = 'Jag skär själv! ✂️', body_sv = 'Vill barnet själv skära bananen eller trolldegen i köket? Det är en fantastisk önskan som kräver finmotorik! Titta direkt på säkra barnknivar och saxar som inte skär i Rekommenderade produkter.', title_vi = 'Con tự cắt! ✂️', body_vi = 'Bé muốn tự cắt chuối hay đất nặn trong bếp? Đây là mong muốn tuyệt vời đòi hỏi kỹ năng vận động tinh! Hãy xem ngay dao và kéo an toàn, không sắc cho trẻ trong Sản phẩm gợi ý.', title_zh = '我自己来切！✂️', body_zh = '在厨房里想自己切香蕉或橡皮泥？这是需要精细动作的了不起的愿望！马上去推荐商品看看儿童专用、不会割手的安全刀具和剪刀。' WHERE id = 'af74ff56-7d79-46b1-8bf0-e27bd2c06fed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Está pálido o sin apetito? Comprueba el hierro de hoy en el Seguimiento de tomas y, junto con la carne, dale siempre ensalada con mucho limón para mejorar la absorción.', body_fr = 'Il a le teint pâle ou peu d''appétit ? Vérifiez ses apports en fer du jour dans le Suivi des repas et servez toujours une salade bien citronnée avec la viande pour mieux l''absorber.', body_hi = 'चेहरा पीला है या भूख नहीं लगती? फ़ीडिंग ट्रैकर में आज का आयरन देखिए और मांस के साथ नींबू वाला सलाद ज़रूर दीजिए ताकि आयरन बेहतर तरीके से अवशोषित हो।', body_id = 'Ia tampak pucat atau tidak berselera makan? Periksa asupan zat besi hari ini di Pemantau Nutrisi dan selalu sajikan daging bersama salad dengan banyak perasan lemon untuk meningkatkan penyerapan.', body_ja = '顔色が悪かったり、食欲がなかったりしますか？「栄養管理ツール」で今日の鉄分摂取を確認し、お肉と一緒にレモンをたっぷりかけたサラダを出して吸収を高めましょう。', body_ko = '얼굴이 창백하거나 입맛이 없나요? 수유 기록 도구로 오늘의 철분 섭취를 확인하고, 고기와 함께 레몬을 듬뿍 뿌린 샐러드를 꼭 곁들여 흡수를 높여 주세요.', body_nl = 'Ziet hij bleek of heeft hij weinig trek? Bekijk in de Voedingstracker het ijzer van vandaag en geef bij vlees altijd een salade met veel citroen om de opname te verbeteren.', body_pl = 'Jest blady albo nie ma apetytu? Sprawdź dzisiejsze spożycie żelaza w narzędziu do śledzenia karmienia i do mięsa koniecznie podawaj sałatkę z dużą ilością cytryny, by poprawić wchłanianie.', body_pt = 'Está pálido ou sem apetite? Verifique a ingestão de ferro de hoje no Registo de Alimentação e, junto com a carne, sirva sempre uma salada com bastante limão para melhorar a absorção.', body_sv = 'Är barnet blekt eller utan aptit? Kolla dagens järnintag i Matningskoll och servera alltid en sallad med mycket citron till köttet för att öka upptaget.', body_vi = 'Bé xanh xao hoặc biếng ăn? Hãy kiểm tra lượng sắt hôm nay trong Theo dõi cữ bú và để tăng hấp thu, nhất định cho bé ăn thịt kèm salad có nhiều nước cốt chanh.', body_zh = '脸色苍白或没胃口？在喂养记录工具里查看今天的铁摄入，搭配肉类时一定要配上多挤柠檬汁的沙拉，提高吸收。' WHERE id = '1cf87075-900c-4f1c-a89d-b12b8314ac9b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El masaje de papá 💆‍♀️', body_es = '¿Te duele la espalda de correr todo el día detrás de tu peque? Con la función Pareja, dile que esta noche, después de acostar al niño, toca un pequeño masaje de hombros para ti.', title_fr = 'Le massage de papa 💆‍♀️', body_fr = 'Votre dos est noué à force de courir après l''enfant toute la journée ? Avec le mode Partenaire, faites-lui savoir que ce soir, une fois l''enfant couché, c''est l''heure d''un petit massage des épaules pour vous.', title_hi = 'पापा की मालिश 💆‍♀️', body_hi = 'दिनभर बच्चे के पीछे भागते-भागते कमर अकड़ गई? पार्टनर फ़ीचर से उन्हें बताइए कि आज शाम बच्चे को सुलाने के बाद आपके कंधों की छोटी सी मालिश का समय हो गया है।', title_id = 'Pijatan dari Ayah 💆‍♀️', body_id = 'Punggung Anda pegal seharian mengejar anak? Beri tahu pasangan lewat mode Pasangan bahwa malam ini, setelah menidurkan anak, sudah waktunya ia memijat bahu Anda sebentar.', title_ja = 'パパのマッサージ 💆‍♀️', body_ja = '一日じゅうお子さんを追いかけて腰が痛い？「パートナーモード」で、今夜お子さんを寝かしつけたあとに、肩を少しマッサージしてほしいと伝えましょう。', title_ko = '아빠의 마사지 💆‍♀️', body_ko = '하루 종일 아이를 쫓아다니느라 허리가 뻐근한가요? 파트너 모드로 오늘 저녁 아이를 재운 뒤 짧은 어깨 마사지를 해 줄 시간이라고 배우자에게 알려 주세요.', title_nl = 'Massage van papa 💆‍♀️', body_nl = 'Heb je last van je rug van een hele dag achter hem aan rennen? Laat je partner via Partnermodus weten dat het tijd is voor een korte schoudermassage zodra hij de kleine vanavond in bed heeft gelegd.', title_pl = 'Masaż od taty 💆‍♀️', body_pl = 'Po całym dniu biegania za dzieckiem bolą cię plecy? Daj partnerowi znać przez funkcję Partnera, że dziś wieczorem, gdy uśpi dziecko, czas na krótki masaż twoich ramion.', title_pt = 'A massagem do pai 💆‍♀️', body_pt = 'As costas doem-lhe de correr atrás da criança o dia todo? Use o Modo Parceiro para lhe dizer que, depois de deitar a criança esta noite, chegou a hora de uma pequena massagem nos seus ombros.', title_sv = 'Pappas massage 💆‍♀️', body_sv = 'Har ryggen låst sig efter att ha sprungit efter barnet hela dagen? Låt din partner veta via Partnerläget att det är dags för en kort axelmassage åt dig i kväll när barnet har somnat.', title_vi = 'Bố mát-xa cho mẹ 💆‍♀️', body_vi = 'Cả ngày chạy theo bé khiến mẹ đau lưng? Hãy dùng Chế độ đối tác để nhắn chồng rằng tối nay, sau khi cho bé ngủ, đã đến lúc bố mát-xa vai cho mẹ một chút.', title_zh = '爸爸的按摩 💆‍♀️', body_zh = '追着孩子跑了一整天，腰都酸了？用伴侣功能告诉他，今晚哄孩子睡着后，是时候给你做个简短的肩部按摩了。' WHERE id = '9c0be1cd-f5f7-43c2-bf11-199a917727ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Convierte beber agua en un juego 💧', body_es = '¿Corre mucho y bebe poca agua? Aumenta el riesgo de estreñimiento. Anota las deposiciones en la app, añade enseguida avena a su menú con el Seguimiento de tomas y pide en Productos recomendados botellas infantiles de colores.', title_fr = 'Faites de l''eau un jeu 💧', body_fr = 'Il court beaucoup et boit peu ? Le risque de constipation augmente. Notez ses selles dans l''application, ajoutez tout de suite de l''avoine à son menu avec le Suivi des repas et commandez des gourdes colorées dans les Produits recommandés.', title_hi = 'पानी पीने को खेल बनाइए 💧', body_hi = 'खूब दौड़ता है, पर पानी कम पीता है? कब्ज़ का खतरा बढ़ जाता है। ऐप में मल दर्ज कीजिए, फ़ीडिंग ट्रैकर से तुरंत मेन्यू में ओट्स जोड़िए और सुझाए गए प्रोडक्ट से रंग-बिरंगी बच्चों की पानी की बोतलें मँगाइए।', title_id = 'Jadikan minum air sebuah permainan 💧', body_id = 'Banyak berlari, sedikit minum? Risiko sembelit meningkat. Catat kotorannya di aplikasi, segera tambahkan oat ke menunya lewat Pemantau Nutrisi, dan pesan botol minum anak warna-warni dari Produk Rekomendasi.', title_ja = 'お水をゲームにしよう 💧', body_ja = 'よく走るのに、お水はあまり飲まない？便秘のリスクが高まります。アプリに便の様子を記録して、すぐに「栄養管理ツール」でメニューにオートミールを加え、「おすすめ商品」からカラフルな子ども用水筒を注文しましょう。', title_ko = '물 마시기를 놀이로 💧', body_ko = '많이 뛰는데 물은 적게 마시나요? 변비 위험이 커져요. 앱에 배변을 기록하고 수유 기록 도구로 식단에 귀리를 바로 추가한 뒤, 추천 제품에서 알록달록한 어린이 물병을 주문해 보세요.', title_nl = 'Maak van water drinken een spel 💧', body_nl = 'Rent hij veel en drinkt hij weinig? De kans op verstopping stijgt. Noteer zijn ontlasting in de app, voeg met de Voedingstracker meteen havermout toe aan zijn menu en bestel in Aanbevolen producten kleurrijke drinkflesjes.', title_pl = 'Zamień picie wody w zabawę 💧', body_pl = 'Dużo biega, mało pije? Rośnie ryzyko zaparć. Zapisz wypróżnienia w aplikacji, od razu dodaj płatki owsiane do menu w narzędziu do śledzenia karmienia i zamów w Polecanych produktach kolorowe bidony dla dzieci.', title_pt = 'Transforme a água num jogo 💧', body_pt = 'Corre muito e bebe pouca água? O risco de prisão de ventre aumenta. Registe as fezes na app, junte logo aveia à ementa com o Registo de Alimentação e encomende garrafinhas coloridas nos Produtos Recomendados.', title_sv = 'Gör vattendrickandet till en lek 💧', body_sv = 'Springer barnet mycket men dricker lite vatten? Risken för förstoppning ökar. Anteckna avföringen i appen, lägg direkt till havre i menyn med Matningskoll och beställ färgglada vattenflaskor för barn i Rekommenderade produkter.', title_vi = 'Biến việc uống nước thành trò chơi 💧', body_vi = 'Bé chạy nhiều mà uống ít nước? Nguy cơ táo bón tăng lên. Hãy ghi chất thải vào ứng dụng, thêm ngay yến mạch vào thực đơn bằng Theo dõi cữ bú và đặt bình nước nhiều màu cho bé từ Sản phẩm gợi ý.', title_zh = '把喝水变成游戏 💧', body_zh = '跑得多、喝得少？便秘风险会增加。在应用里记下排便情况，马上用喂养记录工具在菜单里加上燕麦，再从推荐商品里订几个彩色的儿童水杯。' WHERE id = 'fcd8e598-c584-4111-a575-0192c20a2ba3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apetito selectivo 🍝', body_es = '¿Solo quiere pasta? Revisa el equilibrio semanal con el Seguimiento de tomas. No te cargues con el estrés de un solo día.', title_fr = 'Appétit sélectif 🍝', body_fr = 'Il ne veut que des pâtes ? Vérifiez l''équilibre de la semaine avec le Suivi des repas. Ne vous chargez pas du stress d''une seule journée.', title_hi = 'चुनिंदा भूख 🍝', body_hi = 'सिर्फ़ पास्ता चाहिए? फ़ीडिंग ट्रैकर से हफ़्ते का संतुलन देखिए। सिर्फ़ एक दिन के तनाव का बोझ खुद पर मत डालिए।', title_id = 'Selera pilih-pilih 🍝', body_id = 'Hanya mau makaroni? Periksa keseimbangan mingguannya di Pemantau Nutrisi. Jangan membebani diri dengan stres satu hari saja.', title_ja = '好き嫌いの多い食欲 🍝', body_ja = 'パスタしか食べたがらない？「栄養管理ツール」で1週間のバランスを確認しましょう。1日だけのことで自分を追いつめないで。', title_ko = '까다로운 입맛 🍝', body_ko = '파스타만 먹으려 하나요? 수유 기록 도구로 한 주의 균형을 확인하세요. 하루 식사 때문에 스트레스받지 마세요.', title_nl = 'Kieskeurige eter 🍝', body_nl = 'Wil hij alleen pasta? Check de weekbalans in de Voedingstracker. Belast jezelf niet met de stress van één dag.', title_pl = 'Wybiórczy apetyt 🍝', body_pl = 'Chce tylko makaronu? Sprawdź tygodniowy bilans w narzędziu do śledzenia karmienia. Nie obciążaj się stresem jednego dnia.', title_pt = 'Apetite seletivo 🍝', body_pt = 'Só quer massa? Verifique o equilíbrio semanal no Registo de Alimentação. Não se sobrecarregue com o stress de um único dia.', title_sv = 'Kräsen aptit 🍝', body_sv = 'Vill barnet bara ha pasta? Kolla veckobalansen med Matningskoll. Belasta inte dig själv med stressen från en enda dag.', title_vi = 'Kén ăn 🍝', body_vi = 'Bé chỉ đòi ăn mì ống? Hãy kiểm tra cân bằng hằng tuần bằng Theo dõi cữ bú. Đừng tự tạo áp lực vì chuyện của một ngày.', title_zh = '挑剔的胃口 🍝', body_zh = '只想吃意面？用喂养记录工具看看每周的营养平衡。别因为一天的情况就给自己太大压力。' WHERE id = '819da396-26ce-4c11-baf2-c21f3a1ad406' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lágrimas de cansancio 💧', body_es = '¿Tú también tienes ganas de llorar? Es totalmente normal. Escribe cómo te sientes en el Diario de ánimo y deja a un lado la culpa.', title_fr = 'Larmes de fatigue 💧', body_fr = 'Vous aussi, vous avez envie de pleurer ? C''est tout à fait normal. Écrivez ce que vous ressentez dans le Journal d''humeur et laissez la culpabilité de côté.', title_hi = 'थकान के आँसू 💧', body_hi = 'आपको भी रोने का मन कर रहा है? यह बिल्कुल सामान्य है। मूड डायरी में अपनी भावनाएँ लिखिए और अपराध-बोध को एक तरफ़ रख दीजिए।', title_id = 'Air mata kelelahan 💧', body_id = 'Anda juga ingin menangis? Itu sangat wajar. Tuliskan perasaan Anda di Buku Harian Suasana Hati dan singkirkan rasa bersalah.', title_ja = '疲れの涙 💧', body_ja = 'あなたも泣きたい気分ですか？それはまったく普通のことです。「気分日記」に気持ちを書いて、罪悪感は手放しましょう。', title_ko = '지쳐서 흐르는 눈물 💧', body_ko = '엄마도 울고 싶나요? 아주 자연스러운 일이에요. 기분 일기에 마음을 적고 죄책감은 내려놓으세요.', title_nl = 'Tranen van vermoeidheid 💧', body_nl = 'Wil jij ook huilen? Dat is heel normaal. Schrijf je gevoelens in je Stemmingsdagboek en zet je schuldgevoel opzij.', title_pl = 'Łzy zmęczenia 💧', body_pl = 'Ty też chcesz płakać? To zupełnie normalne. Zapisz swoje uczucia w Dzienniku nastroju i odłóż wyrzuty sumienia na bok.', title_pt = 'Lágrimas de cansaço 💧', body_pt = 'Também lhe apetece chorar? É perfeitamente normal. Escreva o que sente no Diário de Humor e ponha a culpa de lado.', title_sv = 'Trötthetstårar 💧', body_sv = 'Vill du också gråta? Det är helt normalt. Skriv ner dina känslor i Humördagboken och lägg det dåliga samvetet åt sidan.', title_vi = 'Những giọt nước mắt mệt mỏi 💧', body_vi = 'Mẹ cũng muốn khóc? Điều đó hoàn toàn bình thường. Hãy viết cảm xúc vào Nhật ký tâm trạng và gác lại cảm giác tội lỗi.', title_zh = '疲惫的眼泪 💧', body_zh = '你也想哭？这完全正常。把感受写进心情日记，把内疚放到一边。' WHERE id = 'f0c36b67-8799-4202-8ab4-a072283a2c59' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Reconoce los números? 🔢', body_es = '¿Intenta contar cosas al subir escaleras o recoger los juguetes? Añade ya estas primeras chispas de su desarrollo matemático en vídeo con sonido al Álbum del bebé y conviértelas en un recuerdo para siempre.', title_fr = 'Il reconnaît les chiffres ? 🔢', body_fr = 'En montant l''escalier ou en rangeant ses jouets, il essaie de compter ? Ajoutez vite ces premières étincelles mathématiques en vidéo avec le son à l''Album de bébé pour en faire un souvenir pour la vie.', title_hi = 'अंक पहचानता है? 🔢', body_hi = 'सीढ़ियाँ चढ़ते या खिलौने समेटते समय कुछ गिनने की कोशिश करता है? गणित के विकास की इन पहली चिंगारियों को तुरंत आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़िए और उम्रभर की याद बनाइए।', title_id = 'Mengenal angka? 🔢', body_id = 'Ia mencoba menghitung sesuatu saat naik tangga atau membereskan mainan? Segera abadikan percikan pertama kemampuan matematikanya ini sebagai video bersuara di Album Bayi untuk kenangan seumur hidup.', title_ja = '数字がわかる？🔢', body_ja = '階段を上るときやおもちゃを片づけるとき、何かを数えようとしますか？算数の発達のはじめの火花を、すぐに音声つき動画で「ベビーアルバム」に残して、一生の思い出にしましょう。', title_ko = '숫자를 알아보나요? 🔢', body_ko = '계단을 오르거나 장난감을 정리할 때 무언가를 세려고 하나요? 이 수학 발달의 첫 불꽃을 소리가 담긴 영상으로 바로 아기 앨범에 올려 평생의 추억으로 만드세요.', title_nl = 'Herkent hij cijfers? 🔢', body_nl = 'Probeert hij dingen te tellen als hij de trap op gaat of zijn speelgoed opruimt? Maak van deze eerste vonkjes van rekeninzicht een herinnering voor het leven: zet ze meteen als video met geluid in het Babyalbum.', title_pl = 'Rozpoznaje liczby? 🔢', body_pl = 'Wchodząc po schodach albo zbierając zabawki, próbuje coś liczyć? Od razu dodaj te pierwsze iskierki rozwoju matematycznego jako film z dźwiękiem do Albumu dziecka i zamień je we wspomnienie na całe życie.', title_pt = 'Reconhece os números? 🔢', body_pt = 'Ao subir as escadas ou arrumar os brinquedos, tenta contar coisas? Grave já estas primeiras faíscas de desenvolvimento matemático em vídeo com som no Álbum do Bebé e guarde-as para sempre.', title_sv = 'Känner barnet igen siffror? 🔢', body_sv = 'Försöker barnet räkna saker när hen går i trappan eller plockar upp leksaker? Lägg genast till de första gnistorna av matematisk utveckling som video med ljud i Babyalbumet och gör dem till ett minne för livet.', title_vi = 'Bé nhận biết con số? 🔢', body_vi = 'Bé cố đếm khi leo cầu thang hay khi dọn đồ chơi? Hãy quay ngay video có tiếng những tia sáng đầu tiên của tư duy toán học này, thêm vào Album của bé để thành kỷ niệm trọn đời.', title_zh = '认识数字了？🔢', body_zh = '爬楼梯或收玩具时，试着数点什么？马上把这数学发展的第一束火花录成有声视频加进宝宝相册，变成一辈子的回忆吧。' WHERE id = 'f35164ca-a4af-42c5-8f5c-d2b4e2de79f4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hierro y fuerza 🥩', body_es = '¿Está pálido? Comprueba el hierro en el Seguimiento de tomas. Mejora la absorción dándole ensalada con limón junto con la carne.', title_fr = 'Fer et énergie 🥩', body_fr = 'Il a le teint pâle ? Vérifiez ses apports en fer dans le Suivi des repas. Servez une salade citronnée avec la viande pour mieux l''absorber.', title_hi = 'आयरन और ताकत 🥩', body_hi = 'चेहरा पीला है? फ़ीडिंग ट्रैकर में आयरन देखिए। मांस के साथ नींबू वाला सलाद देकर आयरन का अवशोषण बढ़ाइए।', title_id = 'Zat besi dan tenaga 🥩', body_id = 'Ia tampak pucat? Periksa asupan zat besinya di Pemantau Nutrisi. Sajikan salad dengan lemon bersama daging untuk meningkatkan penyerapan.', title_ja = '鉄分と元気 🥩', body_ja = '顔色が悪い？「栄養管理ツール」で鉄分摂取を確認しましょう。お肉と一緒にレモンをかけたサラダを出して吸収を高めて。', title_ko = '철분과 힘 🥩', body_ko = '얼굴이 창백한가요? 수유 기록 도구로 철분 섭취를 확인하세요. 고기와 함께 레몬 샐러드를 곁들여 흡수를 높여 주세요.', title_nl = 'IJzer en kracht 🥩', body_nl = 'Ziet hij bleek? Check het ijzer in de Voedingstracker. Geef bij vlees een salade met citroen om de opname te verbeteren.', title_pl = 'Żelazo i siła 🥩', body_pl = 'Jest blady? Sprawdź spożycie żelaza w narzędziu do śledzenia karmienia. Do mięsa podawaj sałatkę z cytryną, by poprawić wchłanianie.', title_pt = 'Ferro e força 🥩', body_pt = 'Está pálido? Verifique a ingestão de ferro no Registo de Alimentação. Sirva a carne com uma salada com limão para melhorar a absorção.', title_sv = 'Järn och styrka 🥩', body_sv = 'Är barnet blekt? Kolla järnintaget i Matningskoll. Servera en sallad med citron till köttet för att öka upptaget.', title_vi = 'Sắt và sức mạnh 🥩', body_vi = 'Bé xanh xao? Hãy kiểm tra lượng sắt trong Theo dõi cữ bú. Cho bé ăn thịt kèm salad có nước cốt chanh để tăng hấp thu.', title_zh = '铁与力量 🥩', body_zh = '脸色苍白？在喂养记录工具里查看铁的摄入。搭配肉类时配上柠檬沙拉，提高吸收。' WHERE id = '034073b2-a550-46ff-9473-8411c49fc4ec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La guerra del cepillo de dientes 🪥', body_es = '¿Sale corriendo al ver el cepillo? Mira en Productos recomendados cepillos musicales. Convierte la higiene en un juego, no en una obligación.', title_fr = 'La bataille de la brosse à dents 🪥', body_fr = 'Il s''enfuit dès qu''il voit la brosse ? Regardez les brosses musicales dans les Produits recommandés. Faites de l''hygiène un jeu, pas une obligation.', title_hi = 'टूथब्रश की जंग 🪥', body_hi = 'ब्रश देखते ही भागता है? सुझाए गए प्रोडक्ट में म्यूज़िकल ब्रश देखिए। सफ़ाई को मजबूरी नहीं, खेल बनाइए।', title_id = 'Perang sikat gigi 🪥', body_id = 'Kabur begitu melihat sikat gigi? Lihat sikat gigi bermusik di Produk Rekomendasi. Jadikan kebersihan sebagai permainan, bukan paksaan.', title_ja = '歯ブラシバトル 🪥', body_ja = '歯ブラシを見ると逃げていきますか？「おすすめ商品」で音楽つき歯ブラシを見てみましょう。歯みがきを義務ではなく遊びに変えて。', title_ko = '칫솔 전쟁 🪥', body_ko = '칫솔만 보면 도망가나요? 추천 제품에서 음악이 나오는 칫솔을 살펴보세요. 위생을 의무가 아닌 놀이로 바꿔 주세요.', title_nl = 'Strijd om de tandenborstel 🪥', body_nl = 'Rent hij weg als hij de tandenborstel ziet? Bekijk muzikale tandenborstels in Aanbevolen producten. Maak van poetsen een spel in plaats van een verplichting.', title_pl = 'Wojna o szczoteczkę 🪥', body_pl = 'Ucieka na widok szczoteczki? Zajrzyj do Polecanych produktów po grające szczoteczki. Zamień higienę z obowiązku w zabawę.', title_pt = 'A guerra da escova de dentes 🪥', body_pt = 'Foge quando vê a escova? Veja escovas com música nos Produtos Recomendados. Faça da higiene uma brincadeira e não uma obrigação.', title_sv = 'Tandborstkriget 🪥', body_sv = 'Springer barnet iväg när hen ser tandborsten? Titta på tandborstar med musik i Rekommenderade produkter. Gör hygienen till en lek i stället för ett tvång.', title_vi = 'Cuộc chiến bàn chải đánh răng 🪥', body_vi = 'Thấy bàn chải là bé chạy? Hãy xem các loại bàn chải có nhạc trong Sản phẩm gợi ý. Biến việc vệ sinh thành trò chơi chứ không phải nghĩa vụ.', title_zh = '牙刷大战 🪥', body_zh = '一看到牙刷就跑？去推荐商品看看音乐牙刷。别把清洁变成强迫，把它变成游戏吧。' WHERE id = '3e853511-fee0-4626-9f71-c751f4b255ca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis de pantallas 📱', body_es = '¿Se monta un drama cuando le quitas el móvil? Pregunta a Anacan AI los secretos psicológicos que funcionan de verdad para poner límites a las pantallas sin estrés.', title_fr = 'Crises d''écran 📱', body_fr = 'C''est le drame quand vous reprenez le téléphone ? Demandez à Anacan AI les secrets psychologiques qui marchent vraiment pour limiter le temps d''écran sans stress.', title_hi = 'स्क्रीन वाले नखरे 📱', body_hi = 'फ़ोन लेते ही हंगामा मच जाता है? बिना तनाव के स्क्रीन टाइम की सीमा तय करने के सच में काम करने वाले मनोवैज्ञानिक राज़ Anacan AI से पूछिए।', title_id = 'Krisis layar 📱', body_id = 'Dunia serasa runtuh saat ponsel diambil? Tanyakan pada Anacan AI rahasia psikologis yang benar-benar ampuh untuk membatasi waktu layar tanpa stres.', title_ja = '画面をめぐるかんしゃく 📱', body_ja = 'スマホを取り上げると大騒ぎ？ストレスなく画面の時間に区切りをつける、本当に効く心理学のコツをAnacan AIに聞いてみましょう。', title_ko = '화면 전쟁 📱', body_ko = '휴대폰을 가져가면 난리가 나나요? 스트레스 없이 화면 시간에 한계를 정하는, 실제로 효과 있는 심리 비법을 Anacan AI에게 물어보세요.', title_nl = 'Schermbuien 📱', body_nl = 'Breekt de hel los als je de telefoon afpakt? Vraag Anacan AI naar psychologische tips die echt werken om zonder stress grenzen aan schermtijd te stellen.', title_pl = 'Kryzysy przy ekranie 📱', body_pl = 'Gdy zabierasz telefon, rozpętuje się burza? Zapytaj Anacan AI o naprawdę działające psychologiczne sposoby, jak bez stresu ustalić granice czasu przed ekranem.', title_pt = 'Crises de ecrã 📱', body_pt = 'É o fim do mundo quando lhe tira o telemóvel? Pergunte ao Anacan AI os segredos psicológicos que funcionam mesmo para pôr limites ao tempo de ecrã sem stress.', title_sv = 'Skärmkriser 📱', body_sv = 'Blir det kaos när du tar mobilen? Fråga Anacan AI om de psykologiska knep som verkligen fungerar för att sätta gränser för skärmtiden utan stress.', title_vi = 'Khủng hoảng màn hình 📱', body_vi = 'Lấy điện thoại đi là bé làm ầm lên? Hãy hỏi Anacan AI những bí quyết tâm lý thực sự hiệu quả để giới hạn thời gian xem màn hình mà không căng thẳng.', title_zh = '屏幕引发的崩溃 📱', body_zh = '一拿走手机就闹翻天？问问Anacan AI，没有压力地给屏幕时间设界限，有哪些真正有效的心理窍门。' WHERE id = 'd32651ed-78b7-4090-bd14-46fc6e60d9a7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terrores nocturnos 🤖', body_es = '¿Se despierta gritando en mitad de la noche y no te reconoce? Aprende ya en los artículos del Blog qué hacer en estos casos y cuál es la diferencia.', title_fr = 'Terreurs nocturnes 🤖', body_fr = 'Il se réveille en hurlant en pleine nuit et ne vous reconnaît pas ? Découvrez vite dans les articles de la rubrique Blogs quoi faire dans ce cas et en quoi c''est différent.', title_hi = 'नाइट टेरर 🤖', body_hi = 'आधी रात को चीखते हुए जागता है और आपको पहचानता नहीं? ऐसे में क्या करें और फ़र्क क्या है, यह तुरंत ब्लॉग सेक्शन के लेखों से जानिए।', title_id = 'Teror malam 🤖', body_id = 'Ia terbangun tengah malam sambil berteriak dan tidak mengenali Anda? Segera pelajari apa yang harus dilakukan dan bedanya dari artikel di bagian Blog.', title_ja = '夜驚症 🤖', body_ja = '夜中に叫んで目を覚まし、あなたのことがわからない？そんなときにどうすればいいか、違いは何か、すぐにブログの記事で学びましょう。', title_ko = '야경증 🤖', body_ko = '한밤중에 비명을 지르며 깨서 엄마를 못 알아보나요? 이럴 때 어떻게 해야 하는지, 무엇이 다른지 블로그 섹션의 글에서 바로 알아보세요.', title_nl = 'Nachtangsten 🤖', body_nl = 'Wordt hij midden in de nacht schreeuwend wakker en herkent hij je niet? Lees meteen in de artikelen in Blogs wat je dan moet doen en wat het verschil is.', title_pl = 'Lęki nocne 🤖', body_pl = 'Budzi się w nocy z krzykiem i cię nie poznaje? Od razu dowiedz się z artykułów w sekcji Blog, co wtedy robić i czym to się różni od koszmaru.', title_pt = 'Terrores noturnos 🤖', body_pt = 'Acordou a meio da noite aos gritos e não a reconhece? Leia já nos artigos do Blogue o que fazer neste caso e qual é a diferença.', title_sv = 'Nattskräck 🤖', body_sv = 'Vaknar barnet skrikande mitt i natten och känner inte igen dig? Lär dig direkt i artiklarna i avsnittet Bloggar vad du ska göra och vad skillnaden är.', title_vi = 'Hoảng sợ ban đêm 🤖', body_vi = 'Bé hét lên thức giấc giữa đêm và không nhận ra mẹ? Hãy tìm hiểu ngay cách xử lý và sự khác biệt qua các bài viết trong mục Blog.', title_zh = '夜惊 🤖', body_zh = '半夜尖叫着醒来，还认不出你？马上去博客板块的文章里了解这时该怎么做，以及两者的区别。' WHERE id = '49972eb0-ce9d-4cba-ad0b-3cc84b80e743' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también tienes amigas ☕', body_es = 'Hablar solo con tu peque cansa. Busca en Lugares para mamás cafeterías infantiles, tómate un café y socializa con otras madres.', title_fr = 'Vous aussi, vous avez une amie ☕', body_fr = 'Ne parler qu''avec l''enfant, c''est épuisant. Trouvez des cafés pour enfants dans les Lieux adaptés aux mamans, buvez un café et échangez avec d''autres mamans.', title_hi = 'आपके भी दोस्त हैं ☕', body_hi = 'सिर्फ़ बच्चे से बात करते-करते थकान हो जाती है। माँ के लिए अनुकूल जगहें में किड्स कैफ़े ढूँढिए, एक कॉफ़ी पीजिए और दूसरी माँओं से मिलिए-जुलिए।', title_id = 'Anda juga punya teman ☕', body_id = 'Hanya mengobrol dengan anak bisa melelahkan. Temukan kafe anak di Tempat Ramah Ibu, minum kopi, dan bersosialisasilah dengan ibu-ibu lain.', title_ja = 'あなたにも友だちがいます ☕', body_ja = '子どもとだけ話す毎日は疲れますよね。「ママにやさしいスポット」でキッズカフェを見つけて、コーヒーを飲みながらほかのママたちと交流しましょう。', title_ko = '엄마에게도 친구가 있어요 ☕', body_ko = '아이하고만 이야기하는 건 지치죠. 엄마 친화 장소에서 키즈 카페를 찾아 커피 한 잔 마시며 다른 엄마들과 어울려 보세요.', title_nl = 'Jij hebt ook vriendinnen ☕', body_nl = 'Alleen met je kindje praten is vermoeiend. Zoek in Mamavriendelijke plekken een kindercafé, drink een koffie en maak contact met andere moeders.', title_pl = 'Ty też masz przyjaciółkę ☕', body_pl = 'Rozmowy wyłącznie z dzieckiem męczą. Znajdź w Miejscach przyjaznych mamom kawiarnie dla dzieci, wypij kawę i porozmawiaj z innymi mamami.', title_pt = 'A mãe também tem amigas ☕', body_pt = 'Falar só com a criança cansa. Encontre cafés para crianças nos Locais Amigos das Mães, beba um café e conviva com outras mães.', title_sv = 'Du har också vänner ☕', body_sv = 'Det är tröttsamt att bara prata med barnet. Hitta barnkaféer i Mammavänliga platser, ta en kaffe och umgås med andra mammor.', title_vi = 'Mẹ cũng có bạn bè ☕', body_vi = 'Cả ngày chỉ nói chuyện với bé thật mệt. Hãy tìm quán cà phê trẻ em trong Địa điểm thân thiện với mẹ, uống một ly cà phê và giao lưu với các mẹ khác.', title_zh = '你也有朋友 ☕', body_zh = '整天只和孩子说话也会累。在妈妈友好场所里找找亲子咖啡馆，喝杯咖啡，和其他妈妈聊聊天吧。' WHERE id = '4efefe1c-c867-4006-9142-0718a80c34db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis matutinas 🛑', body_es = '¿Llora con cada «no» que le dices? Desahógate con Anacan AI y aprende a gestionar con calma los estallidos emocionales y a desviar su atención.', title_fr = 'Crises du matin 🛑', body_fr = 'Il pleure à chacun de vos « non » ? Discutez avec Anacan AI pour gérer avec calme les explosions émotionnelles et détourner son attention.', title_hi = 'सुबह के नखरे 🛑', body_hi = 'आपकी हर ''नहीं'' पर रोता है? भावनात्मक विस्फोटों को शांत रहकर संभालने और ध्यान भटकाने के लिए Anacan AI से बात कीजिए।', title_id = 'Tantrum pagi 🛑', body_id = 'Ia menangis setiap Anda bilang ''tidak''? Mengobrollah dengan Anacan AI untuk belajar menghadapi ledakan emosi dengan kepala dingin dan mengalihkan perhatiannya.', title_ja = '朝のかんしゃく 🛑', body_ja = '「ダメ」と言うたびに泣きますか？感情の爆発に冷静に対応し、気をそらすコツを知るために、Anacan AIに相談しましょう。', title_ko = '아침의 떼쓰기 🛑', body_ko = '엄마의 ''안 돼'' 한마디마다 우나요? 감정 폭발을 침착하게 다루고 관심을 돌리는 방법을 Anacan AI와 이야기해 보세요.', title_nl = 'Ochtendbuien 🛑', body_nl = 'Huilt hij bij elk ''nee''? Praat met Anacan AI over hoe je emotionele uitbarstingen kalm opvangt en zijn aandacht afleidt.', title_pl = 'Poranne kryzysy 🛑', body_pl = 'Płacze na każde twoje „nie”? Porozmawiaj z Anacan AI, by nauczyć się spokojnie radzić sobie z wybuchami emocji i odwracać jego uwagę.', title_pt = 'Crises da manhã 🛑', body_pt = 'Chora a cada "não" seu? Fale com o Anacan AI para gerir com calma as explosões emocionais e desviar a atenção dele.', title_sv = 'Morgonkriser 🛑', body_sv = 'Gråter barnet vid varje nej? Prata med Anacan AI för att lära dig hantera känsloutbrotten med lugn och avleda uppmärksamheten.', title_vi = 'Khủng hoảng buổi sáng 🛑', body_vi = 'Mỗi lần mẹ nói "không" là bé khóc? Hãy trò chuyện với Anacan AI để học cách bình tĩnh xử lý những cơn bùng nổ cảm xúc và đánh lạc hướng bé.', title_zh = '早晨的崩溃 🛑', body_zh = '你每说一个“不”，宝宝都哭？和Anacan AI聊一聊，学学怎样冷静应对情绪爆发、转移注意力。' WHERE id = 'a185d77d-1385-43cb-bec6-87f42c458382' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Permiso para ensuciarse 🏖️', body_es = '¿Quiere jugar con barro? ¡Deja que se ensucie! Encuentra en Productos recomendados los mejores materiales para apoyar su desarrollo sensorial.', title_fr = 'Permission de se salir 🏖️', body_fr = 'Il veut jouer dans la boue ? Laissez-le se salir ! Trouvez dans les Produits recommandés le meilleur matériel pour soutenir son développement sensoriel.', title_hi = 'गंदा होने की इजाज़त 🏖️', body_hi = 'कीचड़ से खेलना चाहता है? गंदा होने दीजिए! सेंसरी विकास में मदद करने वाली सबसे अच्छी चीज़ें सुझाए गए प्रोडक्ट में ढूँढिए।', title_id = 'Boleh kotor-kotoran 🏖️', body_id = 'Ia ingin bermain lumpur? Biarkan ia kotor! Temukan perlengkapan terbaik untuk mendukung perkembangan sensoriknya di Produk Rekomendasi.', title_ja = '汚れてもいいよ 🏖️', body_ja = 'どろんこ遊びがしたい？汚れても大丈夫！感覚の発達をサポートするいちばんの道具を「おすすめ商品」で見つけましょう。', title_ko = '더러워져도 괜찮아요 🏖️', body_ko = '진흙 놀이를 하고 싶어 하나요? 더러워지게 두세요! 감각 발달을 돕는 가장 좋은 놀이 도구를 추천 제품에서 찾아보세요.', title_nl = 'Vies worden mag 🏖️', body_nl = 'Wil hij met modder spelen? Laat hem lekker vies worden! Vind in Aanbevolen producten de beste spullen die zijn zintuiglijke ontwikkeling ondersteunen.', title_pl = 'Pozwól się ubrudzić 🏖️', body_pl = 'Chce bawić się w błocie? Niech się ubrudzi! Znajdź w Polecanych produktach najlepsze akcesoria wspierające rozwój sensoryczny.', title_pt = 'Licença para se sujar 🏖️', body_pt = 'Quer brincar com lama? Deixe-o sujar-se! Encontre nos Produtos Recomendados os melhores materiais para apoiar o desenvolvimento sensorial.', title_sv = 'Lov att bli smutsig 🏖️', body_sv = 'Vill barnet leka med lera? Låt hen bli smutsig! Hitta de bästa sakerna som stöder sensorisk utveckling i Rekommenderade produkter.', title_vi = 'Cho phép lấm bẩn 🏖️', body_vi = 'Bé muốn nghịch bùn? Cứ để bé bẩn! Hãy tìm những món đồ tốt nhất hỗ trợ phát triển giác quan trong Sản phẩm gợi ý.', title_zh = '允许弄脏 🏖️', body_zh = '想玩泥巴？就让宝宝弄脏吧！去推荐商品找找支持感官发展的最佳用品。' WHERE id = '1d63f653-1008-4746-a730-0e985e6ca79c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Estirón 📏', body_es = '¿Las camisetas se le quedan cortas? ¡Está creciendo! Introduce sus medidas actuales en el Registro de peso y mira con orgullo cómo sube su curva de crecimiento.', title_fr = 'Poussée de croissance 📏', body_fr = 'Les t-shirts sont devenus courts ? Il grandit ! Entrez ses mesures actuelles dans le Suivi du poids et regardez fièrement sa courbe de croissance monter.', title_hi = 'लंबाई में उछाल 📏', body_hi = 'शर्ट छोटी हो गईं? वह बड़ा हो रहा है! वेट ट्रैकर में मौजूदा माप दर्ज कीजिए और गर्व से देखिए कि विकास का ग्राफ़ कैसे ऊपर जा रहा है।', title_id = 'Lonjakan tinggi badan 📏', body_id = 'Bajunya sudah kependekan? Ia sedang tumbuh! Masukkan ukuran terbarunya ke Pelacak Berat Badan dan lihat dengan bangga kurva pertumbuhannya naik.', title_ja = '身長の伸び 📏', body_ja = 'シャツが短くなった？成長しています！「体重トラッカー」に今のサイズを入力して、成長曲線が上がっていく様子を誇らしく眺めましょう。', title_ko = '키가 쑥 📏', body_ko = '셔츠가 짧아졌나요? 자라고 있어요! 체중 기록에 현재 수치를 입력하고 성장 곡선이 올라가는 모습을 뿌듯하게 지켜보세요.', title_nl = 'Groeispurt 📏', body_nl = 'Zijn zijn shirts te kort? Hij groeit! Vul de huidige maten in de Gewichtstracker in en kijk trots hoe zijn groeicurve stijgt.', title_pl = 'Skok wzrostu 📏', body_pl = 'Koszulki zrobiły się za krótkie? Rośnie! Wpisz aktualne wymiary do Licznika wagi i z dumą zobacz, jak wznosi się krzywa rozwoju.', title_pt = 'Salto de crescimento 📏', body_pt = 'As camisolas ficaram curtas? Está a crescer! Introduza as medidas atuais no Registo de Peso e veja com orgulho como sobe a curva de crescimento.', title_sv = 'Längdspurt 📏', body_sv = 'Har tröjorna blivit korta? Barnet växer! För in de aktuella måtten i Viktspåraren och se stolt hur tillväxtkurvan stiger.', title_vi = 'Cao vọt 📏', body_vi = 'Áo đã ngắn rồi? Bé đang lớn! Hãy nhập số đo hiện tại vào Theo dõi cân nặng và tự hào ngắm đường cong phát triển đi lên.', title_zh = '身高突增 📏', body_zh = '衣服变短了？宝宝在长大！在体重记录里输入当前尺寸，骄傲地看看成长曲线是怎么往上走的。' WHERE id = 'ab5b74cd-5dbb-4df0-aad8-f7ce58bb43e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El temporizador se ha parado y tu peque duerme. ¡Olvida las tareas de casa! Prepárate una infusión de melisa de Recetas saludables y disfruta solo del silencio.', body_fr = 'Le minuteur s''est arrêté, l''enfant dort. Oubliez les tâches ménagères ! Infusez une tisane de mélisse des Recettes saines et savourez simplement le silence.', body_hi = 'टाइमर रुक गया, बच्चा सो गया। घर के काम भूल जाइए! सेहतमंद रेसिपी से लेमन बाम (मेलिसा) की चाय बनाइए और बस खामोशी का आनंद लीजिए।', body_id = 'Timer berhenti, anak tertidur. Lupakan pekerjaan rumah! Seduh teh melissa dari Resep Sehat dan nikmati keheningan saja.', body_ja = 'タイマーが止まり、お子さんは眠りました。家事は忘れて！「ヘルシーレシピ」からレモンバームティーをいれて、静けさだけを味わいましょう。', body_ko = '타이머가 멈추고 아이가 잠들었어요. 집안일은 잊으세요! 건강한 레시피에서 레몬밤 차를 우려 오직 고요함만 즐기세요.', body_nl = 'De timer is gestopt, hij slaapt. Vergeet het huishouden! Zet citroenmelissethee uit Gezonde recepten en geniet alleen van de stilte.', body_pl = 'Timer się zatrzymał, dziecko śpi. Zapomnij o obowiązkach! Zaparz herbatę z melisy ze Zdrowych przepisów i po prostu delektuj się ciszą.', body_pt = 'O temporizador parou, a criança adormeceu. Esqueça as tarefas de casa! Prepare um chá de erva-cidreira das Receitas Saudáveis e saboreie apenas o silêncio.', body_sv = 'Timern har stannat, barnet sover. Glöm hushållet! Brygg ett citronmelissate från Hälsosamma recept och njut bara av tystnaden.', body_vi = 'Hẹn giờ đã dừng, bé đã ngủ. Quên việc nhà đi! Hãy pha trà tía tô đất từ Công thức lành mạnh và chỉ tận hưởng sự yên tĩnh.', body_zh = '计时器停了，孩子睡着了。忘掉家务吧！从健康食谱里泡一杯蜜蜂花茶，只管享受这份安静。' WHERE id = 'cd4b46fb-6caf-421b-9a9e-22b85cfd2d73' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Análisis de la rutina ⏱️', body_es = '¿Le cuesta mucho dormirse por la noche? Mira el gráfico del temporizador de sueño. Quizá haya llegado el momento de acortar del todo la siesta.', title_fr = 'Analyse du rythme ⏱️', body_fr = 'L''endormissement du soir s''éternise ? Regardez le graphique du Minuteur de sommeil. Il est peut-être temps de raccourcir nettement la sieste.', title_hi = 'रूटीन का विश्लेषण ⏱️', body_hi = 'शाम को सोने में बहुत देर लगती है? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद को और छोटा करने का समय आ गया है।', title_id = 'Analisis rutinitas ⏱️', body_id = 'Tidur malam butuh waktu terlalu lama? Lihat grafik Timer Tidur. Mungkin sudah waktunya memangkas tidur siangnya sepenuhnya.', title_ja = '生活リズムの分析 ⏱️', body_ja = '夜の寝かしつけに時間がかかりすぎますか？睡眠タイマーのグラフを見てみましょう。お昼寝を短くする時期が来ているのかもしれません。', title_ko = '일과 분석 ⏱️', body_ko = '저녁에 잠드는 데 너무 오래 걸리나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 확 줄일 때가 되었을지도 몰라요.', title_nl = 'Het ritme analyseren ⏱️', body_nl = 'Duurt inslapen ''s avonds erg lang? Bekijk het schema in de Slaaptimer. Misschien is het tijd om het middagslaapje flink in te korten.', title_pl = 'Analiza rytmu dnia ⏱️', body_pl = 'Wieczorne zasypianie bardzo się przeciąga? Spójrz na wykres w timerze snu. Może czas całkowicie skrócić drzemkę w ciągu dnia.', title_pt = 'Análise da rotina ⏱️', body_pt = 'Adormecer à noite demora demasiado? Veja o gráfico do temporizador de sono. Talvez esteja na altura de encurtar de vez a sesta.', title_sv = 'Analys av rutinen ⏱️', body_sv = 'Tar det väldigt lång tid för barnet att somna på kvällen? Titta på sömntimerns diagram. Kanske är det dags att korta dagsömnen ordentligt.', title_vi = 'Phân tích nếp sinh hoạt ⏱️', body_vi = 'Buổi tối bé mất quá lâu mới ngủ được? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đã đến lúc rút ngắn hẳn giấc ngủ ngày.', title_zh = '作息分析 ⏱️', body_zh = '晚上入睡要花很久？看看睡眠计时器的图表。也许是时候把白天的午睡大大缩短了。' WHERE id = '3e08f834-ae99-412b-94f4-fcb284f337ca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No bebe leche? El calcio es imprescindible para los huesos. Calcula con el Seguimiento de tomas cuánto yogur o brócoli ha tomado y completa lo que falte.', body_fr = 'Il ne boit pas de lait ? Le calcium est indispensable pour les os. Calculez ses apports en yaourt ou en brocoli avec le Suivi des repas et comblez les manques.', body_hi = 'दूध नहीं पीता? हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से दही या ब्रोकली की मात्रा गिनिए और कमी पूरी कीजिए।', body_id = 'Tidak mau minum susu? Kalsium wajib untuk tulang. Hitung asupan yoghurt atau brokolinya di Pemantau Nutrisi dan lengkapi kekurangannya.', body_ja = '牛乳を飲まない？骨のためにカルシウムは欠かせません。「栄養管理ツール」でヨーグルトやブロッコリーの摂取量を計算して、足りない分を補いましょう。', body_ko = '우유를 안 마시나요? 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 요거트나 브로콜리 섭취량을 계산해 부족한 만큼 채워 주세요.', body_nl = 'Drinkt hij geen melk? Calcium is nodig voor de botten. Bereken met de Voedingstracker hoeveel yoghurt of broccoli hij binnenkrijgt en vul aan wat ontbreekt.', body_pl = 'Nie pije mleka? Wapń jest niezbędny dla kości. Policz w narzędziu do śledzenia karmienia spożycie jogurtu lub brokułów i uzupełnij braki.', body_pt = 'Não bebe leite? O cálcio é essencial para os ossos. Calcule no Registo de Alimentação o consumo de iogurte ou brócolos e compense o que falta.', body_sv = 'Dricker barnet inte mjölk? Kalcium är ett måste för skelettet. Räkna ut intaget av yoghurt eller broccoli med Matningskoll och fyll på det som saknas.', body_vi = 'Bé không uống sữa? Canxi rất cần cho xương. Hãy tính lượng sữa chua hoặc bông cải xanh bé ăn bằng Theo dõi cữ bú và bổ sung phần còn thiếu.', body_zh = '不肯喝奶？骨骼离不开钙。用喂养记录工具算一算酸奶或西兰花的摄入量，把不足的补上。' WHERE id = '6c779bea-dc2a-41ad-8ebb-96d5620eee3b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Frases largas 🗣️', body_es = '¿Ya cuenta historias graciosas? ¡Está viviendo una explosión de vocabulario! No te pierdas este momento de oro y guárdalo con sonido en el Álbum del bebé.', title_fr = 'Des phrases plus longues 🗣️', body_fr = 'Il raconte déjà des histoires drôles ? C''est l''explosion du vocabulaire ! Ne manquez pas ce moment en or : enregistrez un souvenir sonore dans l''Album de bébé.', title_hi = 'लंबे वाक्य 🗣️', body_hi = 'अब मज़ेदार कहानियाँ सुनाता है? शब्दों का धमाका हो रहा है! यह सुनहरा पल चूके बिना बेबी एल्बम में आवाज़ वाली याद के रूप में सहेजिए।', title_id = 'Kalimat yang panjang 🗣️', body_id = 'Ia sudah bercerita lucu? Ledakan kosakata sedang terjadi! Jangan lewatkan momen emas ini, simpan sebagai kenangan bersuara di Album Bayi.', title_ja = '長い文 🗣️', body_ja = 'もうおもしろいお話をしますか？語彙の爆発期です！この黄金の瞬間を見逃さず、「ベビーアルバム」に音声で残しましょう。', title_ko = '길어지는 문장 🗣️', body_ko = '벌써 웃긴 이야기를 하나요? 어휘가 폭발적으로 늘고 있어요! 이 황금 같은 순간을 놓치지 말고 아기 앨범에 음성으로 남겨 두세요.', title_nl = 'Lange zinnen 🗣️', body_nl = 'Vertelt hij al grappige verhaaltjes? Er is een woordexplosie gaande! Mis dit gouden moment niet en bewaar het als geluidsopname in het Babyalbum.', title_pl = 'Długie zdania 🗣️', body_pl = 'Opowiada już zabawne historie? To eksplozja słownictwa! Nie przegap tej złotej chwili i zapisz nagranie głosowe w Albumie dziecka.', title_pt = 'Frases compridas 🗣️', body_pt = 'Já conta histórias cómicas? É uma explosão de vocabulário! Não perca este momento de ouro e guarde-o como gravação de voz no Álbum do Bebé.', title_sv = 'Långa meningar 🗣️', body_sv = 'Berättar barnet redan roliga historier? Ordförrådet exploderar! Missa inte den här gyllene stunden, spara den som ett ljudminne i Babyalbumet.', title_vi = 'Câu nói dài hơn 🗣️', body_vi = 'Bé đã kể được những câu chuyện hài hước? Vốn từ đang bùng nổ! Đừng bỏ lỡ khoảnh khắc vàng này, hãy lưu lại bằng âm thanh trong Album của bé.', title_zh = '长句子 🗣️', body_zh = '已经会讲搞笑的故事了？词汇量正在爆发！别错过这个黄金时刻，把它作为有声回忆存进宝宝相册吧。' WHERE id = '9550715f-5ff1-4a49-8dae-33944b52477f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Esconde las verduras 🥦', body_es = '¿Tira del plato las hojas verdes o el brócoli? Descubre en Recetas para bebé unas magdalenas caseras de colores con verduras y alcanza sin esfuerzo su ración de vitaminas en el Seguimiento de tomas.', title_fr = 'Cachez les légumes 🥦', body_fr = 'Il jette les légumes verts ou le brocoli de son assiette ? Découvrez dans les Recettes pour bébés des muffins maison colorés aux légumes et atteignez facilement ses besoins en vitamines dans le Suivi des repas.', title_hi = 'सब्ज़ियाँ छिपाइए 🥦', body_hi = 'हरी सब्ज़ियाँ या ब्रोकली थाली से फेंक देता है? बच्चों की रेसिपी में रंग-बिरंगा, सब्ज़ियों वाला घर का बना केक खोजिए और फ़ीडिंग ट्रैकर में विटामिन का लक्ष्य आसानी से पूरा कीजिए।', title_id = 'Sembunyikan sayurannya 🥦', body_id = 'Ia melempar sayuran hijau atau brokoli dari piring? Temukan muffin rumahan penuh sayur yang warna-warni di Resep Bayi dan penuhi kebutuhan vitaminnya dengan mudah di Pemantau Nutrisi.', title_ja = '野菜をかくしましょう 🥦', body_ja = '青菜やブロッコリーをお皿から投げますか？「離乳食を始める赤ちゃんのレシピ」でカラフルな野菜入りの手作りマフィンを見つけて、「栄養管理ツール」のビタミン目標を楽にクリアしましょう。', title_ko = '채소를 숨겨 보세요 🥦', body_ko = '채소나 브로콜리를 접시 밖으로 던지나요? 아기 레시피에서 알록달록한 채소 홈메이드 머핀을 찾아보고, 수유 기록 도구로 비타민 기준량을 쉽게 채워 주세요.', title_nl = 'Verstop de groenten 🥦', body_nl = 'Gooit hij groenten of broccoli van zijn bord? Ontdek in Babyrecepten kleurrijke zelfgebakken groentemuffins en haal makkelijk de vitaminenorm in de Voedingstracker.', title_pl = 'Ukryj warzywa 🥦', body_pl = 'Zrzuca z talerza zieleninę albo brokuły? Odkryj w Przepisach dla niemowląt kolorowe domowe babeczki z warzywami i łatwo osiągnij normę witamin w narzędziu do śledzenia karmienia.', title_pt = 'Esconda os legumes 🥦', body_pt = 'Atira as verduras ou os brócolos para fora do prato? Descubra nas Receitas para bebé um queque caseiro colorido com legumes e atinja facilmente a dose de vitaminas no Registo de Alimentação.', title_sv = 'Göm grönsakerna 🥦', body_sv = 'Kastar barnet bort grönsakerna eller broccolin från tallriken? Upptäck färgglada hemgjorda muffins med grönsaker i Babyrecept och nå lätt vitaminnormen i Matningskoll.', title_vi = 'Giấu rau đi 🥦', body_vi = 'Bé ném rau xanh hay bông cải xanh ra khỏi đĩa? Hãy khám phá món bánh nướng nhiều màu với rau củ làm tại nhà trong Công thức cho bé và dễ dàng đạt định mức vitamin trong Theo dõi cữ bú.', title_zh = '把蔬菜藏起来 🥦', body_zh = '把绿叶菜或西兰花从盘子里扔出去？在宝宝食谱里找找五颜六色的自制蔬菜蛋糕，轻松达到喂养记录工具里的维生素标准。' WHERE id = '02944013-1945-43f5-a622-bb7657b42970' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sois un equipo perfecto 🌟', body_es = 'Cada nueva habilidad que aprende y cada paso seguro que da son fruto de tu esfuerzo y el de tu pareja. ¡Abre el Diario de ánimo y hoy aplaudíos de pie como equipo!', title_fr = 'Vous formez une équipe parfaite 🌟', body_fr = 'Chaque nouvelle compétence qu''il apprend, chaque pas assuré, c''est le fruit de vos efforts, à vous et à votre partenaire. Ouvrez le Journal d''humeur et, aujourd''hui, offrez-vous une ovation d''équipe !', title_hi = 'आप एक परफ़ेक्ट टीम हैं 🌟', body_hi = 'रोज़ सीखा गया हर नया हुनर, हर भरोसे भरा कदम आपकी और आपके पार्टनर की मेहनत का नतीजा है। मूड डायरी खोलिए और आज एक टीम के रूप में खुद के लिए खड़े होकर तालियाँ बजाइए!', title_id = 'Kalian tim yang sempurna 🌟', body_id = 'Setiap keterampilan baru yang ia pelajari, setiap langkah percaya dirinya, adalah hasil kerja keras Anda dan pasangan. Buka Buku Harian Suasana Hati dan beri tepuk tangan meriah untuk tim Anda hari ini!', title_ja = '最高のチームです 🌟', body_ja = '毎日おぼえる新しいスキル、自信に満ちた一歩一歩は、あなたとパートナーの努力の結晶です。「気分日記」を開いて、今日はチームとして自分たちに拍手を送りましょう！', title_ko = '두 사람은 완벽한 팀이에요 🌟', body_ko = '아이가 매일 배우는 새로운 능력, 자신 있게 내딛는 한 걸음 한 걸음은 엄마와 배우자의 노력 덕분이에요. 기분 일기를 열고 오늘은 팀으로서 서로에게 기립 박수를 보내세요!', title_nl = 'Jullie zijn een perfect team 🌟', body_nl = 'Elke nieuwe vaardigheid die hij leert, elke zelfverzekerde stap is het werk van jou en je partner. Open je Stemmingsdagboek en geef jullie team vandaag een staande ovatie!', title_pl = 'Jesteście idealną drużyną 🌟', body_pl = 'Każda nowa umiejętność, której się uczy, każdy pewny krok to zasługa twoja i twojego partnera. Otwórz Dziennik nastroju i nagródź dziś siebie jako drużynę owacją na stojąco!', title_pt = 'São uma equipa perfeita 🌟', body_pt = 'Cada nova capacidade que aprende, cada passo confiante, é fruto do seu esforço e do seu companheiro. Abra o Diário de Humor e aplaudam-se hoje de pé, como equipa!', title_sv = 'Ni är ett perfekt team 🌟', body_sv = 'Varje ny färdighet barnet lär sig varje dag, varje säkert steg, är ditt och din partners verk. Öppna Humördagboken och ge er själva stående ovationer som team i dag!', title_vi = 'Hai người là một đội hoàn hảo 🌟', body_vi = 'Mỗi kỹ năng mới bé học được hằng ngày, mỗi bước đi tự tin đều là công sức của mẹ và bố. Hãy mở Nhật ký tâm trạng và hôm nay hãy đứng dậy vỗ tay cho cả đội nhé!', title_zh = '你们是完美的团队 🌟', body_zh = '宝宝每天学会的新本领、迈出的每一个自信的小步子，都是你和伴侣共同付出的成果。打开心情日记，今天为你们这个团队起立鼓掌吧！' WHERE id = '45019ac4-08ed-4d8b-8186-060ceb70601a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del cuento con papá 📚', body_es = 'Esta noche el momento de dormir es cosa de tu pareja. Que lea él el cuento y tú disfruta de esta pequeña pausa que te han regalado.', title_fr = 'L''heure du conte avec papa 📚', body_fr = 'Ce soir, le coucher revient à votre partenaire. Qu''il lise l''histoire, et vous, savourez cette petite pause qui vous est offerte.', title_hi = 'पापा की कहानी का समय 📚', body_hi = 'आज शाम सुलाने की ज़िम्मेदारी आपके पार्टनर की है। कहानी वे पढ़ें और आप मिले हुए इस छोटे से ब्रेक का मज़ा लीजिए।', title_id = 'Waktu dongeng Ayah 📚', body_id = 'Malam ini giliran pasangan menidurkan anak. Biar ia yang membacakan dongeng, sementara Anda menikmati jeda singkat yang diberikan untuk Anda.', title_ja = 'パパのお話タイム 📚', body_ja = '今夜の寝かしつけはパートナーの番。お話は任せて、あなたはもらえたこの短い休憩を楽しみましょう。', title_ko = '아빠의 동화 시간 📚', body_ko = '오늘 저녁 재우기는 배우자 차례예요. 동화는 배우자가 읽어 주고, 엄마는 주어진 짧은 휴식을 마음껏 즐기세요.', title_nl = 'Voorleesuurtje met papa 📚', body_nl = 'Vanavond brengt je partner hem naar bed. Laat hem het sprookje voorlezen en geniet jij van deze korte pauze die je krijgt.', title_pl = 'Bajka na dobranoc z tatą 📚', body_pl = 'Dziś wieczorem usypianie należy do partnera. Niech to on przeczyta bajkę, a ty ciesz się tą krótką przerwą.', title_pt = 'A hora do conto com o pai 📚', body_pt = 'Esta noite, o ritual de deitar fica com o seu companheiro. Ele lê a história e a mãe aproveita esta pequena pausa que lhe foi oferecida.', title_sv = 'Pappas sagostund 📚', body_sv = 'I kväll är det din partner som sköter nattningen. Låt hen läsa sagan medan du njuter av den här korta pausen du fått.', title_vi = 'Giờ kể chuyện của bố 📚', body_vi = 'Tối nay đến lượt chồng cho bé đi ngủ. Để bố đọc truyện, còn mẹ tận hưởng khoảng nghỉ ngắn ngủi được dành tặng này.', title_zh = '爸爸的故事时间 📚', body_zh = '今晚哄睡交给伴侣。让他来读故事，你好好享受这段难得的小憩吧。' WHERE id = '3a871deb-8d4f-4409-84bd-a7fdcb6e8f4e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las preguntas «¿Por qué?» 🤔', body_es = 'Quiere entender el mundo. Aprende en el Blog a responder con paciencia a sus preguntas sin fin. Tu paciencia es su desarrollo.', title_fr = 'Les questions « Pourquoi ? » 🤔', body_fr = 'Il veut comprendre le monde. Découvrez dans les Blogs comment répondre avec patience à ses questions sans fin. Votre patience, c''est son développement.', title_hi = '''क्यों?'' वाले सवाल 🤔', body_hi = 'वह दुनिया को समझना चाहता है। ब्लॉग से जानिए कि उसके कभी न खत्म होने वाले सवालों का सब्र से जवाब कैसे दें। आपका सब्र ही उसका विकास है।', title_id = 'Pertanyaan ''Kenapa?'' 🤔', body_id = 'Ia ingin memahami dunia. Pelajari di bagian Blog cara menjawab pertanyaannya yang tak ada habisnya dengan sabar. Kesabaran Anda adalah perkembangannya.', title_ja = '「なんで？」の質問 🤔', body_ja = '世界を理解したいのです。終わらない質問にどうやって気長に答えるか、ブログで学びましょう。あなたの忍耐が、お子さんの成長になります。', title_ko = '''왜?'' 질문 🤔', body_ko = '세상을 이해하고 싶어 해요. 끝없는 질문에 인내심 있게 대답하는 방법을 블로그에서 배워 보세요. 엄마의 인내가 곧 아이의 성장이에요.', title_nl = '''Waarom?''-vragen 🤔', body_nl = 'Hij wil de wereld begrijpen. Lees in Blogs hoe je geduldig antwoord geeft op zijn eindeloze vragen. Jouw geduld is zijn ontwikkeling.', title_pl = 'Pytania „Dlaczego?” 🤔', body_pl = 'Chce zrozumieć świat. Dowiedz się z Bloga, jak cierpliwie odpowiadać na jego niekończące się pytania. Twoja cierpliwość to jego rozwój.', title_pt = 'As perguntas "Porquê?" 🤔', body_pt = 'Quer compreender o mundo. Aprenda no Blogue a responder com paciência às perguntas sem fim dele. A sua paciência é o desenvolvimento dele.', title_sv = 'Varför-frågor 🤔', body_sv = 'Barnet vill förstå världen. Lär dig i Bloggar hur du svarar på de ändlösa frågorna med tålamod. Ditt tålamod är barnets utveckling.', title_vi = 'Những câu hỏi "Tại sao?" 🤔', body_vi = 'Bé muốn hiểu thế giới. Hãy học trong mục Blog cách kiên nhẫn trả lời những câu hỏi bất tận của bé. Sự kiên nhẫn của mẹ chính là sự phát triển của bé.', title_zh = '“为什么？”问题 🤔', body_zh = '宝宝想了解世界。去博客里学学怎样耐心回答那些问不完的问题。你的耐心，就是宝宝的成长。' WHERE id = '751db3a1-bc4d-4599-b35d-5aadaed3cfca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las cuatro paredes agobian 🌳', body_es = '¿En casa todo vuela por los aires? Busca en Lugares para mamás un parque cercano. El aire fresco es la mejor medicina para los dos.', title_fr = 'Les quatre murs vous oppressent 🌳', body_fr = 'À la maison, tout vole ? Trouvez un parc tout proche dans les Lieux adaptés aux mamans. L''air frais est le meilleur remède, pour lui comme pour vous.', title_hi = 'चार दीवारें घुटन देती हैं 🌳', body_hi = 'घर में सब कुछ उथल-पुथल है? माँ के लिए अनुकूल जगहें में पास का पार्क ढूँढिए। ताज़ी हवा उसके लिए भी और आपके लिए भी सबसे अच्छी दवा है।', title_id = 'Empat dinding terasa sempit 🌳', body_id = 'Di rumah semuanya beterbangan? Temukan taman terdekat di Tempat Ramah Ibu. Udara segar adalah obat terbaik untuknya dan untuk Anda.', title_ja = '家にこもって息がつまる 🌳', body_ja = '家の中がしっちゃかめっちゃか？「ママにやさしいスポット」で近くの公園を見つけましょう。新鮮な空気は、お子さんにもあなたにもいちばんの薬です。', title_ko = '네 벽이 답답해요 🌳', body_ko = '집 안이 난장판인가요? 엄마 친화 장소에서 가까운 공원을 찾아보세요. 맑은 공기는 아이에게도 엄마에게도 최고의 약이에요.', title_nl = 'De muren komen op je af 🌳', body_nl = 'Vliegt alles thuis door de lucht? Zoek in Mamavriendelijke plekken een park in de buurt. Frisse lucht is het beste medicijn, voor hem en voor jou.', title_pl = 'Cztery ściany przytłaczają 🌳', body_pl = 'W domu wszystko lata w powietrzu? Znajdź w Miejscach przyjaznych mamom pobliski park. Świeże powietrze to najlepsze lekarstwo i dla niego, i dla ciebie.', title_pt = 'As quatro paredes apertam 🌳', body_pt = 'Em casa está tudo pelo ar? Encontre um parque perto nos Locais Amigos das Mães. O ar puro é o melhor remédio para ele e para si.', title_sv = 'De fyra väggarna tränger sig på 🌳', body_sv = 'Flyger allt i luften hemma? Hitta en park i närheten i Mammavänliga platser. Frisk luft är den bästa medicinen för er båda.', title_vi = 'Bốn bức tường ngột ngạt 🌳', body_vi = 'Mọi thứ trong nhà như bay tứ tung? Hãy tìm công viên gần nhà trong Địa điểm thân thiện với mẹ. Không khí trong lành là liều thuốc tốt nhất cho cả bé và mẹ.', title_zh = '四面墙好压抑 🌳', body_zh = '家里乱成一团？在妈妈友好场所里找一个附近的公园。新鲜空气对宝宝和你都是最好的良药。' WHERE id = 'ce6fd7ba-57bf-4c85-bfa6-c9b4b3713d0c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares tempranos 🌅', body_es = '¿Se despierta antes que el sol y lleno de energía, y tú estás agotada? Pregunta a Anacan AI cómo ajustar esta rutina. La falta de sueño no es para siempre.', title_fr = 'Réveils matinaux 🌅', body_fr = 'Il se réveille avant le soleil, plein d''énergie, et vous êtes épuisée ? Demandez à Anacan AI comment ajuster ce rythme. Le manque de sommeil n''est pas éternel.', title_hi = 'जल्दी जागना 🌅', body_hi = 'सूरज से पहले जाग जाता है और ऊर्जा से भरा रहता है? और आप थक कर चूर हैं। इस रूटीन को कैसे ठीक करें, Anacan AI से पूछिए। नींद की कमी हमेशा नहीं रहती।', title_id = 'Bangun terlalu pagi 🌅', body_id = 'Ia bangun sebelum matahari terbit dan penuh energi, sementara Anda kehabisan tenaga? Tanyakan pada Anacan AI cara mengatur rutinitas ini. Kurang tidur tidak berlangsung selamanya.', title_ja = '早起き 🌅', body_ja = '日の出前に起きて元気いっぱい？あなたはもうくたくた。このリズムをどう整えるか、Anacan AIに聞いてみましょう。寝不足は永遠には続きません。', title_ko = '너무 이른 기상 🌅', body_ko = '해 뜨기 전에 깨서 에너지가 넘치는데 엄마는 지쳤나요? 이 일과를 어떻게 조절할지 Anacan AI에게 물어보세요. 잠 못 드는 날들이 영원하지는 않아요.', title_nl = 'Vroeg wakker 🌅', body_nl = 'Wordt hij vóór zonsopgang wakker, vol energie, terwijl jij uitgeput bent? Vraag Anacan AI hoe je dit ritme bijstuurt. Slaapgebrek duurt niet eeuwig.', title_pl = 'Wczesne pobudki 🌅', body_pl = 'Budzi się przed świtem pełen energii, a ty jesteś wykończona? Zapytaj Anacan AI, jak uregulować ten rytm. Niewyspanie nie trwa wiecznie.', title_pt = 'Despertares cedo 🌅', body_pt = 'Acorda antes do sol e cheio de energia, e a mãe está esgotada? Pergunte ao Anacan AI como ajustar esta rotina. As noites sem dormir não são para sempre.', title_sv = 'Tidiga uppvaknanden 🌅', body_sv = 'Vaknar barnet före solen och är full av energi? Och du är helt slut. Fråga Anacan AI hur du kan justera rutinen. Sömnbristen varar inte för evigt.', title_vi = 'Dậy sớm 🌅', body_vi = 'Bé thức dậy trước cả mặt trời và tràn đầy năng lượng? Còn mẹ thì kiệt sức. Hãy hỏi Anacan AI cách điều chỉnh nếp sinh hoạt này. Thiếu ngủ không kéo dài mãi đâu.', title_zh = '早醒 🌅', body_zh = '太阳还没出来就醒了，还精力满满？而你已经累坏了。问问Anacan AI怎样调整这种作息。睡不够的日子不会永远持续。' WHERE id = '2d4c6405-93aa-4a22-9aae-af7a8dcd04fc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de papá 📚', body_es = 'Activa el modo Pareja. ¡Esta noche el héroe del cuento es papá! Que lea él mientras tú te sirves un café y disfrutas del silencio fuera de la habitación.', title_fr = 'L''histoire de papa 📚', body_fr = 'Activez le mode Partenaire. Ce soir, le héros du conte, c''est papa ! Qu''il lise pendant que vous vous servez un café et savourez le silence hors de la chambre.', title_hi = 'पापा की कहानी 📚', body_hi = 'पार्टनर मोड खोलिए। आज शाम कहानी के हीरो पापा हैं! वे पढ़ें और आप अपनी कॉफ़ी बनाकर कमरे के बाहर खामोशी का आनंद लीजिए।', title_id = 'Cerita dari Ayah 📚', body_id = 'Aktifkan mode Pasangan. Malam ini pahlawan dongengnya adalah Ayah! Biar ia yang membaca, sementara Anda menuang kopi dan menikmati keheningan di luar kamar.', title_ja = 'パパのお話 📚', body_ja = '「パートナーモード」をオンにしましょう。今夜のお話のヒーローはパパ！パパに読んでもらい、あなたはコーヒーをいれて、部屋の外で静けさを味わって。', title_ko = '아빠의 이야기 📚', body_ko = '파트너 모드를 켜세요. 오늘 저녁 동화의 주인공은 아빠예요! 아빠가 읽어 주는 동안 엄마는 커피를 따라 방 밖에서 고요함을 즐기세요.', title_nl = 'Papa''s verhaaltje 📚', body_nl = 'Zet Partnermodus aan. Vanavond is papa de held van het sprookje! Laat hem voorlezen, terwijl jij koffie inschenkt en buiten de kamer van de stilte geniet.', title_pl = 'Opowieść taty 📚', body_pl = 'Włącz tryb Partnera. Dziś wieczorem bohaterem bajki jest tata! Niech on czyta, a ty nalej sobie kawy i delektuj się ciszą poza pokojem.', title_pt = 'A história do pai 📚', body_pt = 'Ative o Modo Parceiro. Esta noite, o herói da história é o pai! Ele lê e a mãe serve-se de um café e saboreia o silêncio fora do quarto.', title_sv = 'Pappas berättelse 📚', body_sv = 'Öppna Partnerläget. I kväll är pappa sagans hjälte! Låt honom läsa medan du häller upp ditt kaffe och njuter av tystnaden utanför rummet.', title_vi = 'Câu chuyện của bố 📚', body_vi = 'Hãy bật Chế độ đối tác. Tối nay bố là người hùng của giờ kể chuyện! Để bố đọc, còn mẹ rót một ly cà phê và tận hưởng sự yên tĩnh bên ngoài phòng.', title_zh = '爸爸讲故事 📚', body_zh = '打开伴侣模式。今晚的故事主角是爸爸！让他来读，你倒杯咖啡，到房间外享受安静吧。' WHERE id = '49091c89-e2f8-4ecf-a7b6-b705116efa46' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El drama de compartir 🧸', body_es = '¿No le deja sus juguetes a nadie? No es egoísmo, es una etapa propia de su edad. Aprende en el Blog cómo enseñarle la regla de jugar por turnos.', title_fr = 'Le casse-tête du partage 🧸', body_fr = 'Il ne prête son jouet à personne ? Ce n''est pas de l''égoïsme, c''est une étape normale à son âge. Découvrez dans les Blogs comment lui apprendre à jouer chacun son tour.', title_hi = 'बाँटने का दुख 🧸', body_hi = 'अपना खिलौना किसी को नहीं देता? यह स्वार्थ नहीं, उम्र के साथ आने वाला विकास है। ब्लॉग में जानिए कि बारी-बारी से खेलने का नियम कैसे सिखाएँ।', title_id = 'Susahnya berbagi 🧸', body_id = 'Ia tidak mau meminjamkan mainannya kepada siapa pun? Ini bukan egois, tetapi perkembangan sesuai usianya. Pelajari di bagian Blog cara menanamkan aturan bermain bergiliran.', title_ja = '分け合うのはむずかしい 🧸', body_ja = 'おもちゃをだれにも渡さない？これはわがままではなく、年齢に応じた発達です。「順番に遊ぶ」ルールをどう教えるか、ブログで学びましょう。', title_ko = '나눔의 고민 🧸', body_ko = '장난감을 아무에게도 안 빌려주나요? 이기심이 아니라 나이에 맞는 발달이에요. 차례대로 노는 규칙을 어떻게 알려 줄지 블로그에서 배워 보세요.', title_nl = 'Het gedoe met delen 🧸', body_nl = 'Geeft hij zijn speelgoed aan niemand? Dat is geen egoïsme, maar een normale ontwikkeling voor zijn leeftijd. Lees in Blogs hoe je de regel van om de beurt spelen aanleert.', title_pl = 'Kłopot z dzieleniem się 🧸', body_pl = 'Nikomu nie daje swojej zabawki? To nie egoizm, tylko rozwój typowy dla wieku. Dowiedz się na Blogu, jak uczyć zasady zabawy po kolei.', title_pt = 'O drama de partilhar 🧸', body_pt = 'Não empresta o brinquedo a ninguém? Não é egoísmo, é desenvolvimento próprio da idade. Aprenda no Blogue a ensinar a regra de brincar à vez.', title_sv = 'Svårt att dela 🧸', body_sv = 'Vill barnet inte låna ut sin leksak till någon? Det är inte egoism, det är utveckling som hör till åldern. Lär dig i Bloggar hur du lär ut regeln att turas om.', title_vi = 'Nỗi khổ chia sẻ 🧸', body_vi = 'Bé không cho ai mượn đồ chơi? Đây không phải ích kỷ mà là sự phát triển theo lứa tuổi. Hãy học trong mục Blog cách dạy bé quy tắc chơi lần lượt.', title_zh = '分享的烦恼 🧸', body_zh = '玩具谁也不给？这不是自私，而是这个年龄的正常发展。去博客里学学怎样培养“轮流玩”的规则。' WHERE id = '865b1ef2-1722-47cc-bf4d-3108a098404b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las lágrimas son normales 💧', body_es = '¿Estás cansada y solo quieres llorar? Ser una madre fuerte a veces es saber reconocer tu debilidad.', title_fr = 'Les larmes sont normales 💧', body_fr = 'Vous êtes fatiguée et vous avez juste envie de pleurer ? Être une maman forte, c''est parfois savoir reconnaître sa fragilité.', title_hi = 'आँसू आना सामान्य है 💧', body_hi = 'थक गई हैं और बस रोने का मन है? मज़बूत माँ होने का मतलब कभी-कभी अपनी कमज़ोरी मान लेना भी है।', title_id = 'Menangis itu wajar 💧', body_id = 'Lelah dan hanya ingin menangis? Menjadi ibu yang kuat terkadang berarti berani mengakui kelemahan.', title_ja = '涙はあたりまえ 💧', body_ja = '疲れて、ただ泣きたい気分ですか？強いママでいるとは、ときに自分の弱さを認められることでもあります。', title_ko = '눈물은 자연스러워요 💧', body_ko = '지쳐서 그냥 울고 싶나요? 강한 엄마란 때로 자신의 약함을 인정할 줄 아는 거예요.', title_nl = 'Tranen zijn normaal 💧', body_nl = 'Ben je moe en wil je gewoon huilen? Een sterke moeder zijn betekent soms ook je zwakte kunnen toegeven.', title_pl = 'Łzy są w porządku 💧', body_pl = 'Jesteś zmęczona i chce ci się po prostu płakać? Być silną mamą to czasem umieć przyznać się do słabości.', title_pt = 'As lágrimas são normais 💧', body_pt = 'Está cansada e só lhe apetece chorar? Ser uma mãe forte é, às vezes, conseguir admitir a própria fragilidade.', title_sv = 'Tårar är normala 💧', body_sv = 'Är du trött och vill bara gråta? Att vara en stark mamma handlar ibland om att kunna erkänna sin svaghet.', title_vi = 'Nước mắt là bình thường 💧', body_vi = 'Mẹ mệt mỏi và chỉ muốn khóc? Là một người mẹ mạnh mẽ, đôi khi là dám thừa nhận sự yếu đuối của mình.', title_zh = '流泪很正常 💧', body_zh = '累了，只想哭一场？做一个坚强的妈妈，有时就是能承认自己的脆弱。' WHERE id = '983d85d9-b1dc-40ec-a012-9c7aba93c4d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Bajón de energía ⚡', body_es = '¿A mediodía das cabezadas de pie? ¡Apuesta por las proteínas, no por la cafeína! Renuévate con un batido de crema de cacahuete de Recetas saludables que da fuerza al instante.', title_fr = 'Coup de pompe ⚡', body_fr = 'Vous somnolez debout en début d''après-midi ? Misez sur les protéines plutôt que sur la caféine ! Rechargez-vous avec un smoothie au beurre de cacahuète énergisant des Recettes saines.', title_hi = 'ऊर्जा में गिरावट ⚡', body_hi = 'दोपहर में खड़े-खड़े झपकी आ रही है? कैफ़ीन नहीं, प्रोटीन की ओर जाइए! सेहतमंद रेसिपी से तुरंत ताकत देने वाली पीनट बटर स्मूदी से तरोताज़ा हो जाइए।', title_id = 'Energi menurun ⚡', body_id = 'Terkantuk-kantuk sambil berdiri di siang hari? Pilih protein, bukan kafein! Isi ulang tenaga dengan smoothie selai kacang dari Resep Sehat.', title_ja = 'エネルギー切れ ⚡', body_ja = 'お昼過ぎに立ったままうとうと？カフェインではなく、たんぱく質を！「ヘルシーレシピ」から、すぐに元気をくれるピーナッツバターのスムージーでリフレッシュしましょう。', title_ko = '기운이 뚝 ⚡', body_ko = '오후에 서서 꾸벅꾸벅 조나요? 카페인 말고 단백질을 챙기세요! 건강한 레시피의 바로 힘이 나는 땅콩버터 스무디로 기운을 되찾으세요.', title_nl = 'Energiedip ⚡', body_nl = 'Val je ''s middags staand in slaap? Kies niet voor cafeïne maar voor eiwitten! Laad op met een pindakaassmoothie uit Gezonde recepten die je direct kracht geeft.', title_pl = 'Spadek energii ⚡', body_pl = 'Po południu przysypiasz na stojąco? Sięgnij po białko, nie po kofeinę! Zregeneruj się smoothie z masłem orzechowym ze Zdrowych przepisów, które od razu doda ci sił.', title_pt = 'Quebra de energia ⚡', body_pt = 'À tarde passa pelas brasas de pé? Aposte na proteína, não na cafeína! Recarregue-se com um smoothie de manteiga de amendoim das Receitas Saudáveis que dá energia na hora.', title_sv = 'Energidipp ⚡', body_sv = 'Slumrar du till stående mitt på dagen? Ta till protein, inte koffein! Pigga upp dig med en smoothie med jordnötssmör som ger kraft direkt från Hälsosamma recept.', title_vi = 'Tụt năng lượng ⚡', body_vi = 'Buổi trưa mẹ đứng cũng ngủ gật? Đừng tìm đến caffeine, hãy chọn đạm! Nạp lại năng lượng với ly sinh tố bơ đậu phộng tiếp sức tức thì từ Công thức lành mạnh.', title_zh = '精力下滑 ⚡', body_zh = '中午站着都要打瞌睡了？别靠咖啡因，靠蛋白质！从健康食谱里做一杯能马上补充能量的花生酱奶昔，重新充满电。' WHERE id = 'ee623f8b-a47a-4ef6-96d3-5754f3e3cd43' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gritos repentinos 🛑', body_es = '¿Se tira al suelo sin ningún motivo? Desahógate con Anacan AI y aprende a gestionar estas crisis con calma sin hacer caso de las miradas de alrededor.', title_fr = 'Cris soudains 🛑', body_fr = 'Il se jette par terre sans aucune raison ? Discutez avec Anacan AI pour gérer ces crises avec calme et ignorer les regards autour de vous.', title_hi = 'अचानक चीखें 🛑', body_hi = 'बिना किसी वजह के ज़मीन पर लोट जाता है? इन नखरों को शांत रहकर संभालने और आसपास की नज़रों की परवाह न करने के लिए Anacan AI से बात कीजिए।', title_id = 'Teriakan mendadak 🛑', body_id = 'Ia menjatuhkan diri ke lantai tanpa sebab? Mengobrollah dengan Anacan AI untuk belajar menghadapi krisis ini dengan kepala dingin dan tidak memedulikan tatapan orang.', title_ja = '突然の叫び声 🛑', body_ja = '理由もなく床にひっくり返りますか？こうしたかんしゃくに冷静に対応し、周りの視線を気にしないために、Anacan AIに相談しましょう。', title_ko = '갑작스러운 비명 🛑', body_ko = '아무 이유 없이 바닥에 드러눕나요? 이런 떼쓰기를 침착하게 다루고 주변 시선에 흔들리지 않는 방법을 Anacan AI와 이야기해 보세요.', title_nl = 'Plotseling geschreeuw 🛑', body_nl = 'Gooit hij zich zonder reden op de grond? Praat met Anacan AI om deze buien kalm op te vangen en je niets aan te trekken van blikken van anderen.', title_pl = 'Nagłe krzyki 🛑', body_pl = 'Bez powodu rzuca się na podłogę? Porozmawiaj z Anacan AI, by nauczyć się spokojnie radzić sobie z tymi kryzysami i nie przejmować się spojrzeniami innych.', title_pt = 'Gritos repentinos 🛑', body_pt = 'Atira-se para o chão sem razão nenhuma? Fale com o Anacan AI para gerir estas crises com calma e não ligar aos olhares dos outros.', title_sv = 'Plötsliga skrik 🛑', body_sv = 'Kastar sig barnet på golvet utan någon anledning? Prata med Anacan AI för att hantera de här kriserna med lugn och strunta i omgivningens blickar.', title_vi = 'Những tiếng hét bất chợt 🛑', body_vi = 'Bé lăn ra sàn ăn vạ mà không có lý do? Hãy trò chuyện với Anacan AI để bình tĩnh xử lý những cơn khủng hoảng này và không bận tâm đến ánh nhìn xung quanh.', title_zh = '突然的尖叫 🛑', body_zh = '毫无原因就躺在地上闹？和Anacan AI聊一聊，学学怎样冷静应对这些崩溃，不去在意周围人的目光。' WHERE id = 'fe3bdaaa-fafd-445d-b4e7-84a8026c6168' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tragedia de la galleta rota 🍪', body_es = '¿Se acaba el mundo porque su galleta se ha partido en dos? Bienvenida a las crisis clásicas de los 2,5 años. No busques lógica, solo dile que entiendes su gran disgusto.', title_fr = 'Le drame du biscuit cassé 🍪', body_fr = 'C''est la fin du monde parce que son biscuit s''est cassé en deux ? Bienvenue dans les crises classiques des 2,5 ans. Ne cherchez pas de logique, dites-lui simplement que vous comprenez son gros chagrin.', title_hi = 'टूटे बिस्किट का दुखड़ा 🍪', body_hi = 'बिस्किट दो टुकड़े हो गया तो जैसे दुनिया खत्म हो गई? 2.5 साल के क्लासिक नखरों में आपका स्वागत है। तर्क मत ढूँढिए, बस उसे बताइए कि आप उसका यह बड़ा दुख समझती हैं।', title_id = 'Tragedi biskuit patah 🍪', body_id = 'Dunia serasa kiamat karena biskuitnya patah dua? Selamat datang di krisis klasik usia 2,5 tahun. Jangan mencari logika, cukup katakan bahwa Anda memahami kesedihan besarnya.', title_ja = '割れたビスケットの悲劇 🍪', body_ja = 'ビスケットが2つに割れて、この世の終わり？2歳半の典型的なかんしゃくへようこそ。理屈を探さず、この大きな悲しみをわかっているよと伝えてあげましょう。', title_ko = '부러진 과자 대참사 🍪', body_ko = '과자가 반으로 쪼개졌다고 세상이 끝난 것 같나요? 두 돌 반의 전형적인 떼쓰기에 오신 걸 환영해요. 논리를 찾지 말고 그 큰 슬픔을 이해한다고만 말해 주세요.', title_nl = 'Het drama van het gebroken koekje 🍪', body_nl = 'Is het het einde van de wereld omdat zijn koekje in tweeën brak? Welkom bij de klassieke buien van 2,5 jaar. Zoek geen logica, zeg gewoon dat je zijn grote verdriet begrijpt.', title_pl = 'Tragedia złamanego ciastka 🍪', body_pl = 'Koniec świata, bo ciastko pękło na pół? Witaj w klasycznych kryzysach 2,5-latka. Nie szukaj logiki, po prostu powiedz mu, że rozumiesz ten wielki smutek.', title_pt = 'A tragédia da bolacha partida 🍪', body_pt = 'É o fim do mundo porque a bolacha se partiu ao meio? Bem-vinda às crises clássicas dos 2,5 anos. Não procure lógica, diga-lhe apenas que compreende este grande desgosto.', title_sv = 'Tragedin med det trasiga kexet 🍪', body_sv = 'Har världen gått under för att kexet gick av på mitten? Välkommen till 2,5-årsålderns klassiska kriser. Leta inte efter logik, säg bara att du förstår den stora sorgen.', title_vi = 'Bi kịch chiếc bánh quy gãy 🍪', body_vi = 'Cả thế giới như sụp đổ chỉ vì chiếc bánh quy gãy làm đôi? Chào mừng mẹ đến với những cơn khủng hoảng kinh điển của tuổi 2,5. Đừng tìm logic, chỉ cần nói với bé rằng mẹ hiểu nỗi buồn lớn lao này.', title_zh = '饼干碎了的大悲剧 🍪', body_zh = '饼干断成两半，就像世界末日到了？欢迎来到2.5岁的经典崩溃时刻。别讲道理，只要告诉宝宝你理解这份“大伤心”就好。' WHERE id = '59dde031-61d1-4132-874a-bbebe2bc223a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Realidad sin filtros 🛑', body_es = '¿Te culpas al ver en redes sociales vídeos de niños tranquilos y limpios? Son solo ilusiones de 15 segundos. Tu realidad desordenada y ruidosa es la más bonita.', title_fr = 'La réalité sans filtre 🛑', body_fr = 'Vous vous blâmez en regardant les vidéos d''enfants calmes et propres sur les réseaux sociaux ? Ce ne sont que des illusions de 15 secondes. Votre réalité en désordre et bruyante est la plus belle.', title_hi = 'बिना फ़िल्टर की सच्चाई 🛑', body_hi = 'सोशल मीडिया पर शांत और साफ़-सुथरे बच्चों के वीडियो देखकर खुद को दोष देती हैं? वे बस 15 सेकंड का भ्रम हैं। आपकी बिखरी, शोर भरी असलियत ही सबसे खूबसूरत है।', title_id = 'Kenyataan tanpa filter 🛑', body_id = 'Menyalahkan diri setelah melihat video anak yang tenang dan rapi di media sosial? Itu hanya ilusi 15 detik. Kenyataan Anda yang berantakan dan ramai adalah yang paling indah.', title_ja = 'フィルターなしの現実 🛑', body_ja = 'SNSで静かできれいな子どもの動画を見て、自分を責めていませんか？あれはたった15秒の幻です。あなたの散らかってにぎやかな現実こそ、いちばんすてきです。', title_ko = '필터 없는 현실 🛑', body_ko = 'SNS 속 얌전하고 깔끔한 아이 영상을 보며 자책하나요? 그건 15초짜리 환상일 뿐이에요. 어질러지고 시끌벅적한 우리 집의 현실이 가장 아름다워요.', title_nl = 'Realiteit zonder filter 🛑', body_nl = 'Veroordeel je jezelf na het zien van rustige, keurige kinderen in filmpjes op sociale media? Dat zijn gewoon illusies van 15 seconden. Jouw rommelige, luidruchtige realiteit is de mooiste.', title_pl = 'Rzeczywistość bez filtra 🛑', body_pl = 'Oglądasz w mediach społecznościowych filmiki ze spokojnymi, czystymi dziećmi i się obwiniasz? To tylko 15-sekundowe iluzje. Twoja chaotyczna, głośna rzeczywistość jest najpiękniejsza.', title_pt = 'Realidade sem filtros 🛑', body_pt = 'Culpa-se ao ver nas redes sociais vídeos de crianças calmas e arrumadas? São apenas ilusões de 15 segundos. A sua realidade desarrumada e barulhenta é a mais bonita.', title_sv = 'Ofiltrerad verklighet 🛑', body_sv = 'Klandrar du dig själv när du ser lugna och rena barnvideor i sociala medier? De är bara 15 sekunders illusioner. Din stökiga, högljudda verklighet är den vackraste.', title_vi = 'Thực tế không qua bộ lọc 🛑', body_vi = 'Mẹ tự trách mình khi xem những video trẻ con ngoan ngoãn, sạch sẽ trên mạng xã hội? Đó chỉ là những ảo ảnh 15 giây. Thực tế bừa bộn, ồn ào của mẹ mới là đẹp nhất.', title_zh = '没有滤镜的现实 🛑', body_zh = '看着社交媒体上安静又干净的孩子视频，就开始责怪自己？那些只是15秒的幻象。你那乱糟糟、吵吵闹闹的现实才是最美的。' WHERE id = '5e26eff6-747b-42a4-909a-13e90be41e9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Protesta contra el pijama 👕', body_es = '¿No quiere vestirse y corretea por casa? Convierte la batalla en un juego. El reto «¿A ver quién se viste antes?» suele ser la mejor arma contra la tozudez.', title_fr = 'La révolte du pyjama 👕', body_fr = 'Il refuse de s''habiller et court partout ? Transformez la lutte en jeu. Le défi « Voyons qui s''habille le plus vite ? » est souvent la meilleure arme contre l''entêtement.', title_hi = 'पजामे का विरोध 👕', body_hi = 'कपड़े नहीं पहनना चाहता और घर में भागता है? इस जंग को खेल बना दीजिए। ''देखें, कौन जल्दी कपड़े पहनता है?'' वाला मुकाबला अक्सर ज़िद तोड़ने का सबसे अच्छा हथियार होता है।', title_id = 'Protes piyama 👕', body_id = 'Ia tidak mau berpakaian dan berlarian di rumah? Ubah perdebatan menjadi permainan. Lomba ''Siapa yang paling cepat pakai baju?'' sering menjadi senjata terbaik melawan keras kepala.', title_ja = 'パジャマ反対運動 👕', body_ja = '服を着たがらずに家じゅうを走り回る？戦いを遊びに変えましょう。「どっちが早く着られるかな？」の競争は、がんこさを崩すいちばんの武器になることが多いです。', title_ko = '잠옷 거부 시위 👕', body_ko = '옷을 안 입겠다고 집 안을 뛰어다니나요? 씨름을 놀이로 바꿔 보세요. ''누가 더 빨리 입나 볼까?'' 같은 시합은 고집을 꺾는 최고의 무기예요.', title_nl = 'Pyjamaprotest 👕', body_nl = 'Wil hij zich niet aankleden en rent hij door het huis? Maak van de strijd een spel. ''Wie is het eerst aangekleed?'' Zo''n wedstrijdje is vaak het beste wapen tegen koppigheid.', title_pl = 'Protest przeciw piżamie 👕', body_pl = 'Nie chce się ubrać i biega po domu? Zamień walkę w zabawę. Rywalizacja „Zobaczymy, kto szybciej się ubierze?” to często najlepsza broń na upór.', title_pt = 'Protesto do pijama 👕', body_pt = 'Não se quer vestir e corre pela casa? Transforme a luta num jogo. "Vamos ver quem se veste mais depressa?" A competição é muitas vezes a melhor arma contra a teimosia.', title_sv = 'Pyjamasprotest 👕', body_sv = 'Vill barnet inte klä på sig och springer runt hemma? Gör kampen till en lek. Tävlingen ”Vi ser vem som klär på sig snabbast!” är ofta det bästa vapnet mot envisheten.', title_vi = 'Phản đối đồ ngủ 👕', body_vi = 'Bé không chịu mặc đồ và chạy khắp nhà? Hãy biến cuộc chiến thành trò chơi. Thử thách "Xem ai mặc đồ nhanh hơn nào?" thường là vũ khí tốt nhất phá tan sự bướng bỉnh.', title_zh = '睡衣抗议 👕', body_zh = '不肯穿衣服，在家里到处跑？把对抗变成游戏。“看看谁穿得更快？”这样的比赛，往往是打破倔强的最好武器。' WHERE id = 'db6eccad-9548-4b17-8f6b-0466160ee8dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pequeña grabadora se ha encendido 🎙️', body_es = '¿Repite al instante hasta la palabra más casual que dices? Es tu espejo en vivo. A esta edad su vocabulario explota; anota estas palabras nuevas en el Seguimiento del desarrollo.', title_fr = 'Le petit magnétophone est en marche 🎙️', body_fr = 'Il répète tout de suite même le mot le plus anodin qui vous échappe ? Il est votre miroir vivant. À cet âge, le vocabulaire explose : notez ces nouveaux mots dans le Suivi de développement.', title_hi = 'नन्हा रिकॉर्डर चालू हो गया 🎙️', body_hi = 'आपके मुँह से निकला कोई भी अनजाना शब्द तुरंत दोहराता है? वह आपका जीता-जागता आईना है। इस उम्र में शब्दावली में धमाका होता है, ये नए शब्द ग्रोथ ट्रैकर में दर्ज कीजिए।', title_id = 'Perekam kecil mulai menyala 🎙️', body_id = 'Kata paling acak yang Anda ucapkan pun langsung ia ulangi? Ia adalah cermin hidup Anda. Di usia ini kosakatanya meledak, catat kata-kata barunya di Pelacak Perkembangan.', title_ja = '小さなボイスレコーダーが作動中 🎙️', body_ja = 'あなたの口から出たなにげない言葉まで、すぐにまねしますか？お子さんはあなたを映す生きた鏡です。この年齢は語彙の爆発期、新しい言葉を「発達トラッカー」に記録しましょう。', title_ko = '꼬마 녹음기가 켜졌어요 🎙️', body_ko = '엄마가 무심코 한 말까지 바로 따라 하나요? 아이는 엄마를 비추는 살아 있는 거울이에요. 이 나이엔 어휘가 폭발적으로 늘어요. 성장 기록에 새로운 말을 남겨 두세요.', title_nl = 'De kleine recorder staat aan 🎙️', body_nl = 'Herhaalt hij meteen zelfs het meest toevallige woord dat jij zegt? Hij is je levende spiegel. Op deze leeftijd explodeert de woordenschat, noteer deze nieuwe woorden in de Groeitracker.', title_pl = 'Mały dyktafon włączony 🎙️', body_pl = 'Od razu powtarza nawet najbardziej przypadkowe słowo, które wypowiesz? Jest twoim żywym lustrem. W tym wieku zasób słów eksploduje, zapisuj nowe słowa w Śledzeniu rozwoju.', title_pt = 'O pequeno gravador ligou-se 🎙️', body_pt = 'Repete logo até a palavra mais casual que lhe sai da boca? É o seu espelho vivo. Nesta idade o vocabulário explode: registe estas novas palavras no Registo de Desenvolvimento.', title_sv = 'Den lilla diktafonen är igång 🎙️', body_sv = 'Upprepar barnet genast även det mest slumpmässiga ord du säger? Barnet är din levande spegel. I den här åldern exploderar ordförrådet, anteckna de nya orden i Utvecklingsspåraren.', title_vi = 'Chiếc máy ghi âm nhỏ đã bật 🎙️', body_vi = 'Bé lặp lại ngay cả những từ ngẫu nhiên nhất mẹ vừa nói? Bé là tấm gương sống của mẹ. Ở tuổi này vốn từ đang bùng nổ, hãy ghi lại những từ mới này trong Theo dõi phát triển.', title_zh = '小录音机开机了 🎙️', body_zh = '你随口说的每一个词，宝宝都马上跟着说？宝宝就是你的一面活镜子。这个年龄词汇量正在爆发，把这些新词记在发育追踪里吧。' WHERE id = '118d8e02-86c1-4716-8dfd-287849e960b7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Compra exprés 🛒', body_es = '¿La falta de sueño te dispersa y siempre se te olvida qué comprar? Apunta todo al momento en la Lista de la compra y deja que tu pareja se encargue por completo del súper.', title_fr = 'Ravitaillement express 🛒', body_fr = 'Le manque de sommeil vous rend distraite ? Vous oubliez sans cesse quoi acheter. Ajoutez tout instantanément à la Liste de courses et laissez votre partenaire prendre en charge les courses.', title_hi = 'फ़टाफ़ट खरीदारी 🛒', body_hi = 'नींद की कमी से ध्यान भटकता है? आप बार-बार भूल जाती हैं कि क्या खरीदना है। सब कुछ तुरंत शॉपिंग लिस्ट में डालिए और बाज़ार की ज़िम्मेदारी पूरी तरह अपने पार्टनर को सौंप दीजिए।', title_id = 'Belanja kilat 🛒', body_id = 'Kurang tidur membuat Anda sulit fokus? Selalu lupa apa yang harus dibeli? Langsung masukkan semuanya ke Daftar Belanja, dan biarkan pasangan mengambil alih tanggung jawab belanja sepenuhnya.', title_ja = 'スピード買い出し 🛒', body_ja = '寝不足で集中力が続かない？何を買うかいつも忘れてしまいますか？すべてすぐに「買い物リスト」に入れて、買い物はパートナーにまるごと任せましょう。', title_ko = '빠른 장보기 🛒', body_ko = '잠이 부족해 집중이 흐트러지고 살 것을 자꾸 잊나요? 바로바로 쇼핑 목록에 넣고 장보기는 배우자가 온전히 맡게 하세요.', title_nl = 'Snel boodschappen 🛒', body_nl = 'Is je concentratie weg door slaapgebrek? Vergeet je steeds wat je moet kopen? Zet alles meteen op het Boodschappenlijstje en laat je partner de boodschappen helemaal overnemen.', title_pl = 'Szybkie zaopatrzenie 🛒', body_pl = 'Przez niewyspanie trudno ci się skupić? Ciągle zapominasz, co kupić? Od razu wrzucaj wszystko na Listę zakupów i niech partner w pełni przejmie zakupy.', title_pt = 'Abastecimento rápido 🛒', body_pt = 'A falta de sono deixou-a distraída e esquece sempre o que tem de comprar? Ponha tudo logo na Lista de Compras e deixe o seu companheiro assumir por completo as idas ao supermercado.', title_sv = 'Snabba inköp 🛒', body_sv = 'Har sömnbristen gjort dig okoncentrerad? Glömmer du hela tiden vad du ska köpa? Lägg genast in allt i Inköpslistan och låt din partner ta hela ansvaret för handlingen.', title_vi = 'Mua sắm thần tốc 🛒', body_vi = 'Thiếu ngủ khiến mẹ mất tập trung? Lúc nào cũng quên cần mua gì? Hãy thêm ngay mọi thứ vào Danh sách mua sắm và để chồng nhận trọn trách nhiệm đi chợ.', title_zh = '快速补货 🛒', body_zh = '睡眠不足让你注意力分散？总是忘了要买什么。马上把所有东西丢进购物清单，让另一半全权负责去超市采购吧。' WHERE id = '4ffb5f4c-fcb6-4d97-8d29-5662777e74bb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El teatro de cuentos de papá 📖', body_es = 'Tus cuerdas vocales están cansadas de decir «no» todo el día. Esta noche pasa la hora del cuento a papá. Que cambie las voces y cuente historias graciosas mientras tú descansas.', title_fr = 'Le théâtre des contes de papa 📖', body_fr = 'Vos cordes vocales sont fatiguées d''avoir dit « non » toute la journée. Ce soir, confiez l''heure du conte à papa. Qu''il change de voix et raconte des histoires drôles pendant que vous vous reposez.', title_hi = 'पापा का कहानी थिएटर 📖', body_hi = 'दिनभर ''नहीं'' कहते-कहते आपकी आवाज़ थक गई है। आज शाम कहानी का समय पापा को सौंप दीजिए। उन्हें आवाज़ें बदलकर मज़ेदार कहानियाँ सुनाने दीजिए, और आप आराम कीजिए।', title_id = 'Teater dongeng Ayah 📖', body_id = 'Pita suara Anda lelah bilang ''tidak'' seharian. Malam ini serahkan waktu dongeng kepada Ayah. Biar ia bercerita lucu dengan berbagai suara, Anda beristirahatlah.', title_ja = 'パパのお話劇場 📖', body_ja = '一日じゅう「ダメ」と言い続けて声がかれそう。今夜のお話タイムはパパにバトンタッチ。声色を変えておもしろいお話をしてもらい、あなたは休みましょう。', title_ko = '아빠의 동화 극장 📖', body_ko = '하루 종일 ''안 돼''라고 하느라 목이 지쳤나요? 오늘 저녁 동화 시간은 아빠에게 넘기세요. 목소리를 바꿔 가며 웃긴 이야기를 들려주게 하고 엄마는 쉬세요.', title_nl = 'Papa''s sprookjestheater 📖', body_nl = 'Je stembanden zijn moe van de hele dag ''nee'' zeggen. Geef het voorleesmoment vanavond aan papa. Laat hem stemmetjes doen en grappige verhalen vertellen, en rust jij uit.', title_pl = 'Bajkowy teatr taty 📖', body_pl = 'Twoje struny głosowe są zmęczone całodziennym mówieniem „nie”. Dziś wieczorem przekaż czas na bajkę tacie. Niech zmienia głosy i opowiada zabawne historie, a ty odpocznij.', title_pt = 'O teatro de histórias do pai 📖', body_pt = 'As cordas vocais estão cansadas de dizer "não" o dia todo. Esta noite, passe a hora do conto ao pai. Ele muda as vozes e conta histórias cómicas, e a mãe descansa.', title_sv = 'Pappas sagoteater 📖', body_sv = 'Stämbanden är trötta efter att ha sagt nej hela dagen. Lämna över sagostunden till pappa i kväll. Låt honom ändra rösterna och berätta roliga historier medan du vilar.', title_vi = 'Sân khấu kể chuyện của bố 📖', body_vi = 'Dây thanh quản của mẹ đã mệt vì nói "không" cả ngày. Tối nay hãy giao giờ kể chuyện cho bố. Để bố đổi giọng kể những câu chuyện hài hước, còn mẹ nghỉ ngơi.', title_zh = '爸爸的故事剧场 📖', body_zh = '说了一整天的“不”，嗓子都累了。今晚把故事时间交给爸爸。让他换着各种声音讲搞笑故事，你好好休息。' WHERE id = '8658617d-87c3-40a0-a148-d3af3d34503e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El nuevo lienzo del artista 🖍️', body_es = '¿Se ha acabado el papel y ahora quiere pintar en la pared o la puerta? No está garabateando: está descubriendo el mundo con su motricidad fina. Dale un cartón grande y marca los límites.', title_fr = 'La nouvelle toile de l''artiste 🖍️', body_fr = 'Plus de papier, et maintenant il veut dessiner sur le mur ou la porte ? Il ne gribouille pas, il découvre le monde grâce à sa motricité fine. Donnez-lui un grand carton et fixez une limite.', title_hi = 'कलाकार का नया कैनवस 🖍️', body_hi = 'कागज़ खत्म, अब दीवार या दरवाज़े पर ड्रॉइंग बनाना चाहता है? वह बस लकीरें नहीं खींच रहा, अपनी फ़ाइन मोटर स्किल्स से दुनिया को खोज रहा है। उसे एक बड़ा कार्डबोर्ड दीजिए और सीमा तय कीजिए।', title_id = 'Kanvas baru sang seniman 🖍️', body_id = 'Kertas habis, sekarang ia ingin menggambar di dinding atau pintu? Ia bukan sekadar mencoret, ia menjelajahi dunia dengan motorik halusnya. Beri ia karton besar dan tetapkan batasnya.', title_ja = 'アーティストの新しいキャンバス 🖍️', body_ja = '紙がなくなって、今度は壁やドアに描きたがりますか？なぐり描きではなく、指先の細かな運動能力で世界を発見しているのです。大きな段ボールを渡して、描いていい場所を決めましょう。', title_ko = '꼬마 화가의 새 캔버스 🖍️', body_ko = '종이가 떨어지니 이제 벽이나 문에 그리고 싶어 하나요? 낙서가 아니라 소근육으로 세상을 탐색하는 중이에요. 큰 판지를 주고 그릴 공간을 정해 주세요.', title_nl = 'Een nieuw doek voor de kunstenaar 🖍️', body_nl = 'Is het papier op en wil hij nu op de muur of de deur tekenen? Hij krabbelt niet zomaar, hij ontdekt de wereld met zijn fijne motoriek. Geef hem een groot stuk karton en trek een grens.', title_pl = 'Nowe płótno artysty 🖍️', body_pl = 'Papier się skończył, a teraz chce rysować po ścianie albo drzwiach? On nie bazgrze, tylko odkrywa świat dzięki motoryce małej. Daj mu duży karton i wyznacz granicę.', title_pt = 'A nova tela do artista 🖍️', body_pt = 'Acabou o papel e agora quer desenhar na parede ou na porta? Não está só a rabiscar, está a descobrir o mundo com a motricidade fina. Dê-lhe um cartão grande e defina limites.', title_sv = 'Konstnärens nya duk 🖍️', body_sv = 'Är papperet slut och nu vill barnet rita på väggen eller dörren? Barnet klottrar inte, hen upptäcker världen med sin finmotorik. Ge hen en stor kartong och sätt en gräns.', title_vi = 'Tấm bảng mới của người nghệ sĩ 🖍️', body_vi = 'Hết giấy, giờ bé muốn vẽ lên tường hoặc cửa? Bé không vẽ bậy đâu, bé đang khám phá thế giới bằng kỹ năng vận động tinh. Hãy đưa bé một tấm bìa các-tông lớn và đặt ra giới hạn.', title_zh = '小画家的新画板 🖍️', body_zh = '纸用完了，现在想在墙上或门上画画？宝宝不是在乱涂，而是在用精细动作探索世界。给宝宝一大张纸板，划好界限。' WHERE id = '5d60ba67-a127-4fbd-bd24-40125cd3bcc8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sentir el silencio 🤫', body_es = 'El caos de casa por fin ha terminado y se ha dormido. Abre el Medidor de sonido, mira el nivel de silencio de la habitación y derrítete 15 minutos en esa calma sin mirar ninguna pantalla.', title_fr = 'Toucher le silence 🤫', body_fr = 'Le chaos de la maison est enfin terminé et il dort. Ouvrez le Sonomètre, regardez le niveau de silence de la pièce et fondez dans ce calme 15 minutes, sans aucun écran.', title_hi = 'खामोशी को महसूस कीजिए 🤫', body_hi = 'घर की अफ़रा-तफ़री आखिरकार खत्म हुई और वह सो गया। साउंड मीटर खोलिए, कमरे की खामोशी का स्तर देखिए और 15 मिनट किसी स्क्रीन को देखे बिना इस खामोशी में खो जाइए।', title_id = 'Menyentuh keheningan 🤫', body_id = 'Kekacauan di rumah akhirnya usai dan ia sudah tidur. Buka Pengukur Suara, lihat tingkat keheningan kamar, dan larutlah dalam ketenangan ini selama 15 menit tanpa melihat layar apa pun.', title_ja = '静けさにふれる 🤫', body_ja = '家の大騒ぎがやっと終わり、お子さんは眠りました。「サウンドメーター」を開いて部屋の静けさを確かめ、15分間どの画面も見ずにこの静けさに身をゆだねましょう。', title_ko = '고요를 느껴 보세요 🤫', body_ko = '집 안의 소란이 드디어 끝나고 아이가 잠들었어요. 소음 측정기를 켜서 방의 조용함을 확인하고, 15분 동안 화면은 보지 말고 이 고요 속에 녹아드세요.', title_nl = 'De stilte voelen 🤫', body_nl = 'De chaos in huis is eindelijk voorbij en hij slaapt. Open de Geluidsmeter, bekijk hoe stil de kamer is en smelt 15 minuten weg in die stilte zonder naar een scherm te kijken.', title_pl = 'Dotknąć ciszy 🤫', body_pl = 'Domowy chaos w końcu ucichł i zasnął. Otwórz Miernik dźwięku, sprawdź poziom ciszy w pokoju i przez 15 minut, bez patrzenia w żaden ekran, rozpłyń się w tej ciszy.', title_pt = 'Tocar o silêncio 🤫', body_pt = 'O caos em casa acabou finalmente e ele adormeceu. Abra o Medidor de Som, veja o nível de silêncio do quarto e derreta-se 15 minutos neste silêncio sem olhar para nenhum ecrã.', title_sv = 'Känn tystnaden 🤫', body_sv = 'Kaoset hemma är äntligen över och barnet sover. Öppna Ljudmätaren, se hur tyst det är i rummet och smält in i tystnaden i 15 minuter utan att titta på någon skärm.', title_vi = 'Chạm vào sự tĩnh lặng 🤫', body_vi = 'Sự hỗn loạn trong nhà cuối cùng đã kết thúc và bé đã ngủ. Hãy mở Đo âm thanh, xem độ yên tĩnh trong phòng và tan chảy trong sự tĩnh lặng 15 phút mà không nhìn bất kỳ màn hình nào.', title_zh = '触摸安静 🤫', body_zh = '家里的混乱终于结束，宝宝睡着了。打开分贝仪，看看房间有多安静，15分钟不看任何屏幕，沉浸在这份安静里。' WHERE id = 'b27a302e-b37e-4606-900b-22135e770f9b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Camuflaje de verduras 🥦', body_es = '¿Aparta todo lo verde del plato? La selectividad con la comida está en su punto álgido. Encuentra en el Plan de alimentación recetas ingeniosas para hacer puré las verduras y esconderlas en albóndigas.', title_fr = 'Légumes camouflés 🥦', body_fr = 'Il repousse tout ce qui est vert dans son assiette ? La sélectivité alimentaire est à son comble. Trouvez dans le Plan de nutrition des recettes astucieuses pour réduire les légumes en purée et les cacher dans les boulettes.', title_hi = 'सब्ज़ियों का छलावरण 🥦', body_hi = 'थाली की हर हरी चीज़ एक तरफ़ कर देता है? खाने में नखरे चरम पर हैं। फ़ीडिंग प्लान सेक्शन में ऐसी चतुर रेसिपी ढूँढिए जिनमें सब्ज़ियों को प्यूरी बनाकर कटलेट में छिपाया जा सके।', title_id = 'Kamuflase sayuran 🥦', body_id = 'Ia menyingkirkan semua yang berwarna hijau di piring? Pilih-pilih makanan sedang di puncaknya. Temukan resep cerdik di Rencana Nutrisi untuk menghaluskan sayuran dan menyembunyikannya di perkedel.', title_ja = '野菜のカモフラージュ 🥦', body_ja = 'お皿の緑色のものを全部押しのけますか？好き嫌いのピークです。「栄養管理ツール」から、野菜をピューレにしてハンバーグにかくす賢いレシピを見つけましょう。', title_ko = '채소 위장술 🥦', body_ko = '접시 위 초록색은 전부 밀어내나요? 편식이 절정이에요. 식단 계획에서 채소를 퓌레로 만들어 커틀릿에 숨기는 기발한 레시피를 찾아보세요.', title_nl = 'Groentecamouflage 🥦', body_nl = 'Schuift hij alles wat groen is aan de kant? Kieskeurig eten is op zijn hoogtepunt. Zoek in het Voedingsplan slimme recepten om groenten te pureren en in gehaktballetjes te verstoppen.', title_pl = 'Warzywny kamuflaż 🥦', body_pl = 'Odsuwa na bok wszystko, co zielone na talerzu? Wybiórczość jedzeniowa jest u szczytu. Znajdź w sekcji Plan karmienia sprytne przepisy, w których zmiksowane warzywa ukryjesz w kotlecikach.', title_pt = 'Legumes camuflados 🥦', body_pt = 'Afasta para o lado tudo o que é verde no prato? A seletividade alimentar está no auge. Encontre no Plano Alimentar receitas espertas para fazer puré de legumes e escondê-los nos hambúrgueres.', title_sv = 'Grönsakskamouflage 🥦', body_sv = 'Knuffar barnet undan allt grönt på tallriken? Kräsenheten med maten är på topp. Hitta listiga recept i matplanen där du mosar grönsakerna och gömmer dem i biffar.', title_vi = 'Ngụy trang rau củ 🥦', body_vi = 'Bé đẩy mọi thứ màu xanh ra khỏi đĩa? Kén ăn đang ở đỉnh điểm. Hãy tìm trong Kế hoạch dinh dưỡng những công thức khéo léo xay nhuyễn rau để giấu vào chả viên.', title_zh = '蔬菜伪装术 🥦', body_zh = '把盘子里所有绿色的东西都推到一边？挑食到了高峰。去喂养计划板块找找巧妙的食谱，把蔬菜做成泥藏进肉饼里。' WHERE id = 'd7ebaa5c-a836-4c14-8fc7-8ddab08162c6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Límites en el parque 🧸', body_es = '¿En el arenero no le deja su cubo a nadie? No es egoísmo, es el concepto de propiedad. Enséñale a compartir sin obligarle, con turnos: «Ahora le toca a él».', title_fr = 'Les limites au parc 🧸', body_fr = 'Dans le bac à sable, il ne prête son seau à personne ? Ce n''est pas de l''égoïsme, c''est la notion de propriété. Apprenez-lui le partage non par la force, mais par le tour de rôle : « Maintenant, c''est son tour. »', title_hi = 'पार्क में सीमाएँ 🧸', body_hi = 'सैंडपिट में अपनी बाल्टी किसी को नहीं देता? यह स्वार्थ नहीं, ''मेरा'' की समझ है। बाँटना ज़बरदस्ती नहीं, बारी के ज़रिए सिखाइए: ''अब उसकी बारी है।''', title_id = 'Batasan di taman 🧸', body_id = 'Di bak pasir ia tidak mau meminjamkan embernya kepada siapa pun? Ini bukan egois, tetapi pemahaman tentang kepemilikan. Ajarkan berbagi bukan dengan paksaan, tetapi dengan giliran: ''Sekarang gilirannya''.', title_ja = '公園での境界線 🧸', body_ja = '砂場でバケツをだれにも渡さない？これはわがままではなく、「自分のもの」という考え方です。分け合うことは無理強いではなく、順番で教えましょう：「今はあの子の番だよ」。', title_ko = '공원에서의 경계 🧸', body_ko = '모래놀이터에서 양동이를 아무에게도 안 주나요? 이기심이 아니라 소유 개념이 생긴 거예요. 억지로가 아니라 순서를 정해 나눔을 가르쳐 주세요: ''이제 저 친구 차례야.''', title_nl = 'Grenzen in het park 🧸', body_nl = 'Geeft hij in de zandbak zijn emmertje aan niemand? Dat is geen egoïsme, maar het begrip bezit. Leer delen niet met dwang, maar met beurten: ''Nu is hij aan de beurt.''', title_pl = 'Granice w parku 🧸', body_pl = 'W piaskownicy nikomu nie daje swojego wiaderka? To nie egoizm, tylko poczucie własności. Ucz dzielenia się nie siłą, ale kolejką: „Teraz jego kolej”.', title_pt = 'Limites no parque 🧸', body_pt = 'No parque de areia, não empresta o balde a ninguém? Não é egoísmo, é a noção de posse. Ensine a partilhar não à força, mas por turnos: "Agora é a vez dele."', title_sv = 'Gränser i parken 🧸', body_sv = 'Vill barnet inte låna ut sin hink till någon i sandlådan? Det är inte egoism, det är begreppet äganderätt. Lär ut att dela genom turordning, inte tvång: ”Nu är det hens tur.”', title_vi = 'Ranh giới ở công viên 🧸', body_vi = 'Ở khu chơi cát bé không cho ai mượn xô? Đây không phải ích kỷ mà là khái niệm sở hữu. Hãy dạy chia sẻ không phải bằng ép buộc mà bằng lần lượt: "Giờ đến lượt bạn nhé".', title_zh = '公园里的界限 🧸', body_zh = '在沙坑里不肯把小桶给任何人？这不是自私，而是“所有权”的概念。别强迫分享，用排队轮流来教：“现在轮到他了。”' WHERE id = '2461cdb3-c847-4528-8c72-5b1258b6ff1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Han llegado invitados imaginarios ☕', body_es = '¿Habla solo en la habitación con amigos invisibles y les sirve té? ¡Es el punto álgido del desarrollo de su imaginación! Observa con orgullo desde fuera a este gran guionista.', title_fr = 'Les invités imaginaires sont arrivés ☕', body_fr = 'Seul dans la chambre, il parle à ses amis invisibles et leur sert du thé ? C''est le sommet du développement de l''imagination ! Observez fièrement de loin ce formidable scénariste.', title_hi = 'काल्पनिक मेहमान आए हैं ☕', body_hi = 'कमरे में अकेले अपने अदृश्य दोस्तों से बातें करता है, उन्हें चाय परोसता है? यह कल्पना के विकास का शिखर है! इस शानदार पटकथा लेखक को दूर से गर्व से देखिए।', title_id = 'Tamu khayalan datang ☕', body_id = 'Ia berbicara sendiri dengan teman tak kasatmata di kamar dan menuangkan teh untuk mereka? Ini puncak perkembangan imajinasinya! Saksikan penulis skenario hebat ini dari jauh dengan bangga.', title_ja = '空想のお客さまが来た ☕', body_ja = '部屋でひとり、見えないお友だちと話したり、お茶をついだりしていますか？想像力の発達の最高潮です！このすばらしい脚本家を、少し離れて誇らしく見守りましょう。', title_ko = '상상 속 손님이 왔어요 ☕', body_ko = '방에서 혼자 보이지 않는 친구와 이야기하며 차를 따라 주나요? 상상력 발달의 정점이에요! 이 멋진 꼬마 작가를 멀리서 뿌듯하게 지켜보세요.', title_nl = 'Denkbeeldige gasten op bezoek ☕', body_nl = 'Praat hij alleen in zijn kamer met onzichtbare vriendjes en schenkt hij ze thee in? Dit is het hoogtepunt van zijn fantasie! Kijk trots toe naar deze geweldige scenarioschrijver.', title_pl = 'Przyszli wyimaginowani goście ☕', body_pl = 'Sam w pokoju rozmawia z niewidzialnymi przyjaciółmi i nalewa im herbaty? To szczyt rozwoju wyobraźni! Z dumą obserwuj z boku tego wspaniałego scenarzystę.', title_pt = 'Chegaram convidados imaginários ☕', body_pt = 'Sozinho no quarto, fala com amigos invisíveis e serve-lhes chá? É o ponto alto do desenvolvimento da imaginação! Observe com orgulho este fantástico argumentista à distância.', title_sv = 'Låtsasgästerna har kommit ☕', body_sv = 'Pratar barnet ensamt i rummet med osynliga vänner och häller upp te åt dem? Det är fantasiutvecklingens absoluta topp! Titta stolt på den fantastiska manusförfattaren på avstånd.', title_vi = 'Những vị khách tưởng tượng đã đến ☕', body_vi = 'Bé một mình nói chuyện với những người bạn vô hình trong phòng, rót trà cho họ? Đây là đỉnh cao của sự phát triển trí tưởng tượng! Hãy tự hào quan sát "biên kịch" tuyệt vời này từ xa.', title_zh = '想象中的客人来了 ☕', body_zh = '一个人在房间里和看不见的朋友聊天，还给他们倒茶？这是想象力发展的巅峰时刻！在一旁骄傲地看着这位了不起的小编剧吧。' WHERE id = 'b0edd680-c98e-4626-b7fa-18383befe832' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia la controla tu peque 🪄', body_es = '¿Los cuentos clásicos le aburren? Esta vez, en Cuentos inteligentes, deja que elija él al héroe. Un perro volador o un árbol que habla: da rienda suelta a su imaginación.', title_fr = 'C''est l''enfant qui tient la baguette magique 🪄', body_fr = 'Les contes classiques le lassent ? Cette fois, dans les Contes intelligents, laissez-le choisir le héros. « Le chien volant » ou « L''arbre qui parle » : laissez libre cours à son imagination.', title_hi = 'जादू की डोर बच्चे के हाथ 🪄', body_hi = 'पुरानी कहानियों से ऊब गया? इस बार स्मार्ट कहानियों में हीरो उसे चुनने दीजिए। ''उड़ने वाला कुत्ता'' या ''बोलने वाला पेड़'', उसकी कल्पना को खुला छोड़ दीजिए।', title_id = 'Keajaiban di tangan anak 🪄', body_id = 'Dongeng klasik membuatnya bosan? Kali ini di Dongeng Pintar, biarkan ia memilih tokoh utamanya. ''Anjing terbang'' atau ''Pohon yang bisa bicara'', bebaskan daya khayalnya.', title_ja = '魔法を使うのはお子さん 🪄', body_ja = '昔話にあきてしまった？「スマートおはなし」で、今回は主人公をお子さんに選んでもらいましょう。「空飛ぶ犬」や「おしゃべりする木」、想像力を自由に羽ばたかせて。', title_ko = '마법은 아이 손에 🪄', body_ko = '늘 듣던 동화가 지루해졌나요? 이번에는 스마트 동화에서 주인공을 아이가 고르게 해 주세요. ''날아다니는 강아지''나 ''말하는 나무'', 상상력을 마음껏 펼치게 해 주세요.', title_nl = 'Hij bepaalt de magie 🪄', body_nl = 'Is hij klassieke sprookjes beu? Laat hem in Slimme sprookjes deze keer zelf de held kiezen. Een vliegende hond of een pratende boom: laat zijn fantasie de vrije loop.', title_pl = 'Magia w rękach dziecka 🪄', body_pl = 'Klasyczne bajki go znudziły? Tym razem w Mądrych bajkach pozwól mu wybrać bohatera. „Latający pies” albo „Gadające drzewo”: daj wolność jego wyobraźni.', title_pt = 'A magia está nas mãos dele 🪄', body_pt = 'Os contos clássicos cansam-no? Nas Histórias Inteligentes, deixe-o desta vez escolher o herói. "Um cão que voa" ou "uma árvore que fala": dê asas à imaginação.', title_sv = 'Barnet styr magin 🪄', body_sv = 'Är barnet trött på klassiska sagor? Låt hen välja hjälten i Smarta sagor den här gången. En flygande hund eller ett pratande träd: släpp fantasin fri.', title_vi = 'Phép màu trong tay bé 🪄', body_vi = 'Truyện cổ tích kinh điển khiến bé chán? Lần này trong Truyện cổ tích thông minh, hãy để bé tự chọn nhân vật chính. "Chú chó biết bay" hay "Cái cây biết nói": hãy để trí tưởng tượng bay xa.', title_zh = '魔法由孩子掌控 🪄', body_zh = '经典故事讲腻了？这次在智能故事里让宝宝自己选主角吧。“会飞的小狗”还是“会说话的树”，尽情释放想象力。' WHERE id = 'dea0086a-894a-4d43-a110-0948ee956740' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escribe sus propias reglas 🛑', body_es = 'Todo lo quiere hacer «¡yo solo!». Se pone los zapatos cambiados y la camiseta mal, pero insiste. No pasa nada: las ganas de independencia importan más que la estética, déjale.', title_fr = 'Il écrit ses propres règles 🛑', body_fr = 'Il dit « Je le fais tout seul ! » pour tout. Chaussures à l''envers, t-shirt mal mis, mais il insiste. Ce n''est pas grave, son envie d''autonomie compte plus que l''esthétique : laissez faire.', title_hi = 'अपने नियम खुद लिखता है 🛑', body_hi = 'हर बात पर कहता है ''मैं खुद!''। जूते उल्टे, शर्ट गलत पहनता है, फिर भी ज़िद करता है। कोई बात नहीं, खुद करने की चाह दिखावट से ज़्यादा ज़रूरी है, उसे करने दीजिए।', title_id = 'Membuat aturannya sendiri 🛑', body_id = 'Ia bilang ''Aku sendiri!'' untuk segala hal. Sepatunya terbalik, kausnya salah pakai, tetapi ia tetap bersikeras. Tidak apa-apa, keinginan untuk mandiri lebih penting daripada penampilan, biarkan saja.', title_ja = '自分のルールを作る 🛑', body_ja = 'なんでも「自分でやる！」と言います。靴を左右逆に、シャツをまちがえて着ても、ゆずりません。大丈夫、見た目より自立したい気持ちのほうが大切、やらせてあげましょう。', title_ko = '자기만의 규칙을 만들어요 🛑', body_ko = '뭐든 ''내가 할래!''라고 하나요? 신발을 거꾸로, 옷을 잘못 입어도 고집을 부리죠. 괜찮아요. 지금은 멋보다 독립하고 싶은 마음이 더 중요하니 허락해 주세요.', title_nl = 'Hij schrijft zijn eigen regels 🛑', body_nl = 'Zegt hij bij alles ''Zelf doen!''? Hij trekt zijn schoenen verkeerd om en zijn shirt verkeerd aan, maar houdt vol. Geen probleem: zijn wens naar zelfstandigheid is belangrijker dan hoe het eruitziet, laat hem maar.', title_pl = 'Pisze własne zasady 🛑', body_pl = 'Na wszystko mówi „Ja sam!”. Zakłada buty na odwrót, koszulkę źle, ale i tak się upiera. Nic nie szkodzi, chęć samodzielności jest ważniejsza niż estetyka, pozwól mu.', title_pt = 'Escreve as próprias regras 🛑', body_pt = 'Diz "Eu faço sozinho!" a tudo. Calça os sapatos trocados, veste a camisola mal, mas insiste. Não faz mal: a vontade de independência é mais importante do que a estética, deixe-o.', title_sv = 'Barnet skriver sina egna regler 🛑', body_sv = 'Barnet säger ”jag själv!” om allt. Hen tar skorna på fel fot och tröjan fel, men står ändå på sig. Det gör inget, viljan att vara självständig är viktigare än estetiken, låt hen göra det.', title_vi = 'Bé tự đặt luật lệ 🛑', body_vi = 'Việc gì bé cũng nói "Con tự làm!". Đi giày ngược chân, mặc áo sai nhưng vẫn nhất quyết. Không sao cả, mong muốn tự lập quan trọng hơn thẩm mỹ, hãy để bé làm.', title_zh = '自己定规矩 🛑', body_zh = '什么都要“我自己来！”。鞋子穿反、衣服穿错，还是坚持己见。没关系，追求独立比好不好看更重要，就让宝宝去做吧。' WHERE id = '0a08658d-8354-4bb5-9ba8-b4c528e517fc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de agua 🛀', body_es = 'Después de correr todo el día, tenéis los nervios de punta los dos. Un baño templado no es solo higiene: sirve para aprovechar el poder casi mágico del agua para soltar la tensión.', title_fr = 'Thérapie par l''eau 🛀', body_fr = 'Après une journée à courir, vos nerfs sont à vif, à lui comme à vous. Le bain tiède n''est pas qu''une question d''hygiène : il sert à profiter du pouvoir presque magique de l''eau qui dénoue les tensions.', title_hi = 'पानी से थेरेपी 🛀', body_hi = 'दिनभर भागदौड़ से उसकी भी और आपकी भी नसें तन गई हैं। गुनगुना स्नान सिर्फ़ सफ़ाई के लिए नहीं, बल्कि पानी की उस जादुई ताकत के लिए है जो तनाव दूर कर देती है।', title_id = 'Terapi air 🛀', body_id = 'Seharian berlarian, saraf Anda dan dia sama-sama tegang. Mandi air hangat bukan sekadar kebersihan, tetapi cara memanfaatkan kekuatan ajaib air untuk meluruhkan ketegangan.', title_ja = 'お水セラピー 🛀', body_ja = '一日じゅう走り回って、ふたりとも神経がピリピリ。ぬるめのお風呂はただの衛生習慣ではなく、緊張をほどくお水の不思議な力を借りるためのものです。', title_ko = '물 테라피 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 신경이 곤두섰죠. 따뜻한 목욕은 단순한 위생이 아니라 긴장을 풀어 주는 물의 신비로운 힘을 빌리는 시간이에요.', title_nl = 'Watertherapie 🛀', body_nl = 'Na een hele dag rennen zijn jullie allebei gespannen. Een lauw bad is niet alleen voor de hygiëne, maar ook om de bijna magische kracht van water te gebruiken die spanning wegneemt.', title_pl = 'Terapia wodą 🛀', body_pl = 'Po całym dniu biegania puszczają nerwy i jemu, i tobie. Ciepła kąpiel to nie tylko higiena, ale sposób, by wykorzystać mistyczną moc wody, która zabiera napięcie.', title_pt = 'Terapia da água 🛀', body_pt = 'Depois de correrem o dia todo, os nervos dele e os seus estão em franja. Um banho morno não é só higiene: serve para aproveitar o poder quase místico da água para levar a tensão.', title_sv = 'Vattenterapi 🛀', body_sv = 'Efter en hel dag i farten är både barnets och dina nerver spända. Ett ljummet bad är inte bara hygien, det är ett sätt att använda vattnets magiska kraft att släppa spänningar.', title_vi = 'Liệu pháp nước 🛀', body_vi = 'Cả ngày chạy nhảy khiến cả bé và mẹ đều căng thẳng. Bồn nước ấm không chỉ để vệ sinh, mà còn để tận dụng sức mạnh kỳ diệu của nước giúp xua tan căng thẳng.', title_zh = '水疗时间 🛀', body_zh = '跑了一整天，宝宝和你都神经紧绷。温水澡不只是为了清洁，更是借助水那带走紧张的神奇力量。' WHERE id = '411275c3-b6bc-4218-a886-bbf3ee4ba697' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sensación de agotamiento 🔋', body_es = '¿Te dan ganas de gritar por todo? Es burnout. Entra ya en la Comunidad Anacan, lee las confesiones de madres que viven la misma etapa que tú y encuentra apoyo.', title_fr = 'Sensation d''épuisement 🔋', body_fr = 'Vous avez envie de crier pour tout ? C''est le burn-out. Rejoignez tout de suite la Communauté Anacan, lisez les confidences de mamans qui vivent la même période et trouvez du soutien.', title_hi = 'थक कर चूर होने का एहसास 🔋', body_hi = 'हर बात पर चिल्लाने का मन करता है? यह बर्नआउट है। तुरंत Anacan कम्युनिटी में जाइए, आपके जैसे दौर से गुज़र रही माँओं की बातें पढ़िए और सहारा पाइए।', title_id = 'Rasa habis tenaga 🔋', body_id = 'Ingin berteriak pada segala hal? Itu burnout. Segera masuk ke Komunitas Anacan, baca pengakuan ibu-ibu yang mengalami masa yang sama, dan dapatkan dukungan.', title_ja = '燃えつきそうな気持ち 🔋', body_ja = '何にでも叫びたくなりますか？それは燃えつき症候群です。すぐにAnacanコミュニティに参加して、同じ時期を過ごしているママたちの本音を読んで支えてもらいましょう。', title_ko = '번아웃 🔋', body_ko = '모든 것에 소리치고 싶나요? 번아웃이에요. 바로 Anacan 커뮤니티에 들어가 같은 시기를 보내는 엄마들의 고백을 읽고 위로를 받으세요.', title_nl = 'Opgebrand gevoel 🔋', body_nl = 'Wil je overal tegen schreeuwen? Dat is een burn-out. Ga meteen naar de Anacan Community, lees de bekentenissen van moeders die hetzelfde doormaken en vind steun.', title_pl = 'Poczucie wyczerpania 🔋', body_pl = 'Masz ochotę krzyczeć na wszystko? To wypalenie. Od razu wejdź do Społeczności Anacan, przeczytaj wyznania mam, które przechodzą przez to samo, i znajdź wsparcie.', title_pt = 'Sensação de esgotamento 🔋', body_pt = 'Apetece-lhe gritar com tudo? Isto é burnout. Entre já na Comunidade Anacan, leia os desabafos de mães que vivem a mesma fase e encontre apoio.', title_sv = 'Känslan av att vara utbränd 🔋', body_sv = 'Vill du skrika åt allt? Det är utbrändhet. Gå direkt in i Anacan Community, läs bekännelser från mammor som går igenom samma period och få stöd.', title_vi = 'Cảm giác kiệt sức 🔋', body_vi = 'Mẹ muốn hét lên với mọi thứ? Đó là kiệt sức (burnout). Hãy vào ngay Cộng đồng Anacan, đọc tâm sự của các mẹ đang trải qua giai đoạn giống mẹ và nhận được sự sẻ chia.', title_zh = '身心耗尽的感觉 🔋', body_zh = '对什么都想发火？这就是倦怠。马上进入Anacan社区，读读和你经历同样阶段的妈妈们的心声，获得支持。' WHERE id = 'd5a4b327-9717-431f-8c67-ec44df34af85' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sabotaje en la cocina 🧑‍🍳', body_es = '¿Mientras cocinas, da un concierto con las cazuelas? Él también quiere formar parte del equipo. Dale un trocito de masa y deja que cocine también.', title_fr = 'Sabotage en cuisine 🧑‍🍳', body_fr = 'Pendant que vous cuisinez, il donne un concert avec les casseroles ? Il veut lui aussi faire partie de l''équipe. Donnez-lui un petit morceau de pâte et laissez-le cuisiner, lui aussi.', title_hi = 'रसोई में तोड़फोड़ 🧑‍🍳', body_hi = 'आप खाना बनाती हैं और वह बर्तनों से कॉन्सर्ट करता है? वह भी टीम का हिस्सा बनना चाहता है। उसके हाथ में आटे का छोटा सा टुकड़ा दीजिए और उसे भी खाना बनाने दीजिए।', title_id = 'Kekacauan di dapur 🧑‍🍳', body_id = 'Saat Anda memasak, ia mengadakan konser dengan panci? Ia juga ingin menjadi anggota tim. Beri ia sepotong kecil adonan dan biarkan ia ikut memasak.', title_ja = 'キッチンの大混乱 🧑‍🍳', body_ja = '料理をしていると、お鍋でコンサートを始めますか？チームの一員になりたいのです。小さな生地をひとかけら渡して、一緒に料理をさせてあげましょう。', title_ko = '주방 대소동 🧑‍🍳', body_ko = '엄마가 요리할 때 냄비로 연주회를 여나요? 아이도 팀의 일원이 되고 싶은 거예요. 작은 반죽 조각을 쥐여 주고 함께 요리하게 해 주세요.', title_nl = 'Sabotage in de keuken 🧑‍🍳', body_nl = 'Geeft hij een concert met de pannen terwijl jij kookt? Hij wil ook bij het team horen. Geef hem een klein stukje deeg en laat hem ook koken.', title_pl = 'Kuchenna dywersja 🧑‍🍳', body_pl = 'Gdy gotujesz, on daje koncert na garnkach? Też chce być członkiem drużyny. Daj mu mały kawałek ciasta, niech i on gotuje.', title_pt = 'Sabotagem na cozinha 🧑‍🍳', body_pt = 'Enquanto cozinha, ele dá um concerto com os tachos? Também quer fazer parte da equipa. Dê-lhe um pedacinho de massa e deixe-o cozinhar também.', title_sv = 'Sabotage i köket 🧑‍🍳', body_sv = 'Ger barnet konsert med kastrullerna medan du lagar mat? Hen vill också vara en del av laget. Ge barnet en liten degbit och låt hen också laga mat.', title_vi = '"Phá hoại" trong bếp 🧑‍🍳', body_vi = 'Khi mẹ nấu ăn, bé "biểu diễn hòa nhạc" với xoong nồi? Bé cũng muốn là một thành viên trong đội. Hãy đưa bé một miếng bột nhỏ và để bé cùng "nấu ăn".', title_zh = '厨房“破坏”行动 🧑‍🍳', body_zh = '你做饭时，宝宝拿着锅碗瓢盆开起了音乐会？宝宝也想成为团队的一员。给宝宝一小块面团，让宝宝也来“做饭”吧。' WHERE id = '38c563a6-395b-403a-8ffd-c4d46a16b207' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lo resolvemos juntos 🥂', body_es = 'Cuando tu peque se duerma, sentaos frente a frente con tu pareja. En lugar de hablar del niño, sonreíos diciendo «Hoy también hemos sobrevivido» y sentid el espíritu de equipo.', title_fr = 'On s''en sort ensemble 🥂', body_fr = 'Une fois l''enfant couché, asseyez-vous face à votre partenaire. Au lieu de parler de l''enfant, souriez-vous en disant « On a encore survécu aujourd''hui » et ressentez l''esprit d''équipe.', title_hi = 'मिलकर संभालते हैं 🥂', body_hi = 'बच्चे के सोने के बाद अपने पार्टनर के आमने-सामने बैठिए। बच्चे की बातें करने के बजाय ''आज भी हम बच गए'' कहकर एक-दूसरे को मुस्कुराकर देखिए और टीम वाली भावना महसूस कीजिए।', title_id = 'Kita selesaikan bersama 🥂', body_id = 'Setelah anak tidur, duduklah berhadapan dengan pasangan. Daripada membicarakan anak, tersenyumlah satu sama lain sambil berkata ''Hari ini pun kita berhasil melewatinya'' dan rasakan semangat tim.', title_ja = '一緒に乗りこえる 🥂', body_ja = 'お子さんが眠ったら、パートナーと向かい合って座りましょう。子どもの話をするかわりに、「今日もなんとか乗りきったね」と笑い合って、チームの絆を感じて。', title_ko = '함께 해결해요 🥂', body_ko = '아이가 잠들면 배우자와 마주 앉아 보세요. 아이 이야기 대신 ''우리 오늘도 살아남았어'' 하며 서로에게 웃어 주고 한 팀이라는 걸 느껴 보세요.', title_nl = 'Samen lossen we het op 🥂', body_nl = 'Ga als hij slaapt tegenover je partner zitten. Praat niet over de kinderen, maar glimlach naar elkaar met ''We hebben het vandaag weer overleefd'' en voel de teamgeest.', title_pl = 'Rozwiązujemy to razem 🥂', body_pl = 'Gdy dziecko zaśnie, usiądź naprzeciwko partnera. Zamiast rozmawiać o dziecku, uśmiechnijcie się do siebie: „Przetrwaliśmy kolejny dzień” i poczujcie ducha drużyny.', title_pt = 'Resolvemos juntos 🥂', body_pt = 'Depois de a criança adormecer, sente-se frente a frente com o seu companheiro. Em vez de falarem da criança, sorriam um para o outro, digam "Sobrevivemos a mais um dia" e sintam o espírito de equipa.', title_sv = 'Vi löser det tillsammans 🥂', body_sv = 'När barnet har somnat, sätt dig mitt emot din partner. I stället för att prata om barnet, le mot varandra och säg ”Vi överlevde i dag också” och känn laganda.', title_vi = 'Cùng nhau vượt qua 🥂', body_vi = 'Khi bé đã ngủ, hãy ngồi đối diện với chồng. Thay vì nói chuyện về con, hãy mỉm cười với nhau, nói "Hôm nay chúng mình lại vượt qua rồi" và cảm nhận tinh thần đồng đội.', title_zh = '我们一起搞定 🥂', body_zh = '孩子睡着后，和另一半面对面坐下。别再聊孩子，笑着对彼此说一句“今天我们又挺过来了”，感受一下团队精神。' WHERE id = '65dda26f-c428-4285-904a-5e44f932685c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hay que salir sí o sí ⛅', body_es = 'Las cuatro paredes te agobian. Consulta la sensación térmica real en Tiempo y ropa y corred al parque sin pensarlo. El aire fresco corta al momento hasta las crisis más fuertes.', title_fr = 'Il faut sortir ⛅', body_fr = 'Les quatre murs vous étouffent. Vérifiez la température ressentie dans Météo et tenue et filez au parc sans réfléchir. L''air frais coupe net même les crises les plus vives.', title_hi = 'बाहर निकलना ज़रूरी है ⛅', body_hi = 'चार दीवारें घुटन दे रही हैं। मौसम और कपड़े टूल से असली तापमान देखिए और बिना सोचे पार्क की ओर निकल पड़िए। ताज़ी हवा सबसे तीखे नखरों को भी तुरंत रोक देती है।', title_id = 'Harus keluar rumah ⛅', body_id = 'Empat dinding rumah terasa menyesakkan. Cek suhu sebenarnya di alat Cuaca dan Pakaian, lalu langsung pergi ke taman. Udara segar bisa seketika meredakan krisis paling hebat sekalipun.', title_ja = '外に出なきゃ ⛅', body_ja = '家にこもって息がつまりそう？「天気と服装」で実際の気温を確認して、迷わず公園へ出かけましょう。新鮮な空気は、どんなに激しいかんしゃくもすぐにしずめてくれます。', title_ko = '밖으로 나가야 할 때 ⛅', body_ko = '네 벽에 갇혀 숨이 막히나요? 날씨와 옷차림 도구로 체감 온도를 확인하고 고민 없이 공원으로 나가세요. 맑은 공기는 가장 심한 떼쓰기도 바로 멈춰 줘요.', title_nl = 'Tijd om naar buiten te gaan ⛅', body_nl = 'Kruipen de muren op je af? Check de gevoelstemperatuur in Weer en kleding en ga zonder nadenken naar het park. Frisse lucht stopt zelfs de heftigste buien meteen.', title_pl = 'Trzeba wyjść na zewnątrz ⛅', body_pl = 'Cztery ściany cię przytłaczają. Sprawdź temperaturę odczuwalną w narzędziu Pogoda i ubiór i bez namysłu biegnijcie do parku. Świeże powietrze od razu ucina nawet najostrzejsze kryzysy.', title_pt = 'É preciso sair de casa ⛅', body_pt = 'As quatro paredes sufocam-na. Veja a temperatura real no Tempo e Roupa e vá para o parque sem pensar duas vezes. O ar puro corta logo até as crises mais fortes.', title_sv = 'Måste ut ⛅', body_sv = 'De fyra väggarna kväver dig. Kolla den verkliga temperaturen i Väder och kläder och skynda till parken utan att tveka. Frisk luft stoppar även de värsta kriserna direkt.', title_vi = 'Phải ra ngoài thôi ⛅', body_vi = 'Bốn bức tường như ngột ngạt. Hãy xem nhiệt độ cảm nhận thực tế trong công cụ Thời tiết và trang phục và ra công viên ngay không cần nghĩ ngợi. Không khí trong lành dập tắt ngay cả những cơn khủng hoảng dữ dội nhất.', title_zh = '必须出门走走 ⛅', body_zh = '四面墙让人透不过气。看看天气穿衣工具，查好实际温度，别犹豫，直接去公园。新鲜空气连最激烈的崩溃都能马上止住。' WHERE id = '68aff420-6957-4fb3-8fd3-172910f79641' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
COMMIT;
